INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440533,'asir-region','سد الغرابه بال عمر بللحمر','','al-gharabah-dam-belhamar','["أماكن سياحية"]','["sights"]','سد الغرابة من السدود الواقعة في منطقة بللحمر بعسير، ويسهم في تجميع مياه الأمطار والاستفادة منها في المنطقة المحيطة.','<div class="texte" > <p>يقع سد الغرابة في منطقة بللحمر بالقرب من مدينة أبها في عسير، وهو من السدود التي أُقيمت لتجميع مياه الأمطار والاستفادة منها في ري المزارع المحيطة وتغذية المياه الجوفية. يتحول محيط السد بعد هطول الأمطار إلى مسطح مائي جميل يجذب الأهالي والزوار لالتقاط الصور والاستمتاع بالمناظر الطبيعية المحيطة به.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440533-44205983.jpg?v=1637323264"]','https://cmsphoto.ww-cdn.com/resizeapi/b9ea7de322fcc88162125f9112cc43c34d6e24d1/480/',18.7891953,42.305144,'Q8Q4+M3C Billasmar Abha','','','','https://www.saudi-guide.com/asir-region/i/59440533/al-gharabah-dam-belhamar',1,0,'سد غرابه بال عمر بللحمر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440472,'asir-region','بحيرة سد الملك فهد بوادي بيشه','','king-fahd-dam-lake-wadi-bisha','["أماكن سياحية"]','["sights"]','يعد سد الملك فهد بن عبد العزيز بوادي بيشة من أضخم المشاريع التي نفذتها الحكومة السعودية لتأمين المياه وتنمية مصادرها، كما تعد البحيرة التي يصنعها السد مكانًا جميلًا للتنزه فيه.','<div class="texte" > <p>يعد سد الملك فهد بن عبد العزيز بوادي بيشة من أضخم المشاريع التي نفذتها الحكومة السعودية لتأمين المياه وتنمية مصادرها في منطقة عسير. تشكل البحيرة التي يكوّنها السد مكانًا جميلًا للتنزه، حيث يقصدها الزوار للاستمتاع بمناظرها المائية الواسعة والتقاط الصور، خصوصًا في مواسم امتلاء السد بمياه الأمطار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440472-44206120.jpg?v=1637323753"]','https://cmsphoto.ww-cdn.com/resizeapi/71ee1dc0336f138c8fe44e90551ebe85daba32ae/480/',19.6775211,42.4810498,'بحيرة سد الملك فهد بيشة منطقة عسير','','','','https://www.saudi-guide.com/asir-region/i/59440472/king-fahd-dam-lake-wadi-bisha',1,0,'بحيره سد ملك فهد بوادي بيشه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440414,'asir-region','قصر بن هتيل في بيشه','Ben Hôtel Historical Palace','ben-h-tel-historical-palace','["أماكن سياحية"]','["sights"]','من أجمل وأهم المتاحف في محافظة بيشه، يختص القصر في كل ما يتعلق بالتراث وغيره من القصص التارخية المتعلقة بالمنطقة الجنوبية بشكل عام وبيشه على وجه الخصوص، كما يوجد أيضًا فندق خاص بالمتحف للسكن فيه.','<div class="texte" > <p>من أجمل وأهم المتاحف في محافظة&nbsp;بيشه، يختص القصر في كل ما يتعلق&nbsp;بالتراث وغيره من القصص التارخية المتعلقة بالمنطقة الجنوبية&nbsp;بشكل عام وبيشه على وجه الخصوص، كما يوجد أيضاً&nbsp;فندق خاص بالمتحف للسكن فيه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440414-44206125.jpg?v=1637323780"]','https://cmsphoto.ww-cdn.com/resizeapi/a07d938175daa99ef0e833f2cdabddbb9ee2b5fe/480/',20.0451519,42.6075537,'8151 Al Nakhil Bisha','','','','https://www.saudi-guide.com/asir-region/i/59440414/ben-h-tel-historical-palace',1,0,'قصر بن هتيل في بيشه ben hôtel historical palace اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440392,'asir-region','عقبة السقيفة عليان - سبت العلايه','','al-saqifah-alyan-pass-sabt-alaya','["أماكن سياحية"]','["sights"]','عقبة السقيفة عليان من المعالم الطبيعية الواقعة في سبت العلاية بمنطقة عسير، وتتميز بطرقها الجبلية وإطلالاتها الخلابة على المرتفعات المحيطة.','<div class="texte" > <p>تُعد عقبة السقيفة عليان من المعالم الطبيعية اللافتة في محافظة سبت العلاية بمنطقة عسير، حيث تتعرج الطريق بين المرتفعات الجبلية مكوّنة مناظر طبيعية خلابة تجذب عشاق الطبيعة والتصوير. تمنح العقبة زائريها إطلالات بانورامية على السلاسل الجبلية المحيطة، وتُعد من الممرات التي تعكس التضاريس الجبلية المميزة لمنطقة عسير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440392-44206126.jpg?v=1637323808"]','https://cmsphoto.ww-cdn.com/resizeapi/4a1f660a7896fe303ec5d239cd8904c22c99711c/480/',19.5781411,41.8677606,'Sabt Al Alayah Balqarn Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59440392/al-saqifah-alyan-pass-sabt-alaya',1,0,'عقبه سقيفه عليان سبت علايه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440390,'asir-region','بحيرة شيبانة سبت العلاية','','shaybanah-lake-sabt-alaya','["أماكن سياحية"]','["sights"]','تعد بحيرة شيبانة مقصدًا سياحيًا مهمًا لأهالي المنطقة وزوارها لما تحتويه من جمال البحيرة والطبيعة المحيطة بها.','<div class="texte" > <p>تعد بحيرة شيبانة مقصدًا سياحيًا مهمًا لأهالي محافظة سبت العلاية وزوارها، لما تحتويه من جمال طبيعي يجمع بين صفاء مياهها والتضاريس الجبلية المحيطة بها. تشكل البحيرة وجهة مناسبة للتنزه العائلي والتصوير، وتزداد جاذبيتها في مواسم الأمطار حين ترتفع مناسيب المياه وتزهر الطبيعة المحيطة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440390-44206138.jpg?v=1637323840"]','https://cmsphoto.ww-cdn.com/resizeapi/7c79bc6a8746b60e9163f147eee2d394034664c8/480/',19.5868863,41.9278662,'HWPH+Q45 Sabt Al Alayah Balqarn','','','','https://www.saudi-guide.com/asir-region/i/59440390/shaybanah-lake-sabt-alaya',1,0,'بحيره شيبانه سبت علايه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411638,'asir-region','مطل رجال المع','','rijal-almaa-viewpoint','["أماكن سياحية"]','["sights"]','يعد مطل رجال ألمع من أجمل المزارات السياحية في المنطقة حيث يتميز بإطلالة شاهقة الارتفاع وشديدة الانحدار.','<div class="texte" > <p>يعد مطل رجال ألمع من أجمل المزارات السياحية في منطقة عسير، حيث يتميز بإطلالة شاهقة الارتفاع وشديدة الانحدار تكشف عن مناظر جبلية خلابة تمتد حتى سفوح الجبال المحيطة. يقصد المطل عشاق التصوير والطبيعة، خصوصًا عند الغروب حين تتلون السماء فوق القمم الجبلية، ما يمنح الزائر تجربة بصرية مميزة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411638-44206143.jpg?v=1637323873"]','https://cmsphoto.ww-cdn.com/resizeapi/e89e8905d1e086d7d69a7ea042044599440247b0/480/',18.2494166,42.2608209,'Al Jarf Ragal Almaa Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59411638/rijal-almaa-viewpoint',1,0,'مطل رجال مع اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411543,'asir-region','قرية ربوع بلادي السياحية والتراثية والفندقية بالمجاردة','','rubou-bladi-village-al-majaridah','["أماكن سياحية"]','["sights"]','قرية ربوع بلادي من الوجهات السياحية والتراثية والفندقية في منطقة المجاردة بعسير، وتجمع بين الطابع التراثي والخدمات السياحية والفندقية في موقع واحد.','<div class="texte" > <p>تقع قرية ربوع بلادي السياحية والتراثية والفندقية في منطقة المجاردة بعسير، وهي وجهة متكاملة تجمع بين الطابع المعماري التراثي والخدمات السياحية والفندقية الحديثة في موقع واحد. توفر القرية للزوار تجربة تجمع بين الإقامة المريحة واستكشاف عناصر التراث المحلي، كما تحتوي على مساحات مخصصة للجلسات العائلية والفعاليات، ما يجعلها محطة مناسبة لمحبي السياحة التراثية في منطقة عسير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411543-44206168.jpg?v=1637324084"]','https://cmsphoto.ww-cdn.com/resizeapi/23d5a20e9d902af840a966108c0d842580b0808a/480/',19.1265121,41.9215851,'Almajaridah Alkhaldiyah Al Majaridah','','','','https://www.saudi-guide.com/asir-region/i/59411543/rubou-bladi-village-al-majaridah',1,0,'قريه ربوع بلادي سياحيه والتراثيه والفندقيه بالمجارده اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411538,'asir-region','جبل تهوي بالمجاردة','Tahoy','tahoy','["أماكن سياحية"]','["sights"]','يقع جبل تهوي في الجنوب الشرقي وتحديدًا في مركز خاط التابع لمحافظة المجاردة في منطقة عسير، ويبلغ ارتفاع الجبل حوالي 1,600 متر فوق سطح البحر، وتقع في الجهة الشرقية منه قرية رهوة آل صميد التي تُعد من أجمل المناطق السياحية.','<div class="texte" > <p>يقع جبل تهوي في الجنوب الشرقي وتحديداً في مركز خاط التابع لمحافظة المجاردة في منطقة عسير في السعودية، ويبلغ ارتفاع الجبل&nbsp;حوالي 1,600 متر (5,249 قدم) فوق سطح البحر. وتقع في الجهة الشرقية منه قرية (رهوة آل صميد) والتي تُعد من أجمل المناطق السياحية، كما يوجد أسفل الجبل وادي (السليل) الذي يشتهر بكثافة أشجاره ووفرة مياهه ومن الجهة المقابلة له قرية&nbsp;ال شغيب القف التي تشتهر بكثافة اشجارها وطبيعتها الخلابة .</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411538-44206199.jpg?v=1637324289"]','https://cmsphoto.ww-cdn.com/resizeapi/ca4f819c53fee8450d1b6bfe23a78eebf613374b/480/',19.111891,41.9841073,'Tahoy Aseer Province SA','','','','https://www.saudi-guide.com/asir-region/i/59411538/tahoy',1,0,'جبل تهوي بالمجارده tahoy اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411511,'asir-region','مدينة جُرش الأثرية بأحد رفيدة','','jurash-archaeological-city-ahad-rafidah','["التراث والثقافة"]','["heritage"]','موقع جرش الأثري يقع في محافظة أحد رفيدة، على مسافة 15 كم جنوب خميس مشيط التابعة لمنطقة عسير. يحتوي الموقع على بقايا مبانٍ بعضها من الحجارة وأخرى من الطين، كما يضم معثورات يعود تاريخها إلى فترة ما قبل الإسلام والفترات الإسلامية المتعاقبة وصولاً إلى القرن الحادي عشر الميلادي. تقع جرش على طريق الحج القادم من اليمن، واشتهرت بصناعاتها الجلدية والحربية، كما كانت مركزًا تجاريًا مهمًا في فترة البعثة النبوية.','<div class="texte" > <p>موقع جرش الأثري، يقع في محافظة أحد رفيدة، كما يقع على مسافة 15 كم جنوب خميس مشيط التابعة لمنطقة عسير جنوب غرب السعودية. يحتوي الموقع على بقايا مبان ضخمة بعضها من الحجارة وأخرى من الطين، كما تضم معثورات يعود تاريخها إلى فترة ما قبل الإسلام والفترات الإسلامية المتعاقبة وصولاً إلى القرن الحادي عشر الميلادي، حيث ظهرت دلائل على الاستيطان خلال الفترة العباسية في شمال ووسط الموقع، أما في جنوب الموقع فهناك دلائل على الاستيطان خلال الفترة الإسلامية الوسيطة والمتأخرة. تقع جرش على طريق الحج القادم من اليمن، وقد اشتهرت بصناعاتها الجلدية والحربية ومن ضمنها المنجنيق والعرادات وما كان يعرف باسم الدبابات، كما كانت جرش معروفة في فترة البعثة النبوية كونها مركزاً تجارياً مهماً، وقد أسلم أهل جرش في عهد النبي محمد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411511-44206179.jpg?v=1637324210"]','https://cmsphoto.ww-cdn.com/resizeapi/35629a3d26d3079b4ed58a2be509c0376befbee3/480/',18.2027875,42.8243873,'6R3F+4Q6 السلامة، أحد رفيدة','','','','https://www.saudi-guide.com/asir-region/i/59411511/jurash-archaeological-city-ahad-rafidah',1,0,'مدينه جرش اثريه باحد رفيده تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411507,'asir-region','قرية بن حمسان التراثية بالخميس','','bin-hamsan-heritage-village-khamis','["التراث والثقافة"]','["heritage"]','قرية ابن حمسان هي واحدة من القرى السياحية ذات الطابع المعماري التراثي في خميس مشيط جنوب المملكة، وقد أصبحت من أشهر القرى على مستوى منطقة عسير، وقد زارها عدد من أصحاب السمو الأمراء والمعالي الوزراء ورواد الفكر والأدب، كما زارها عدد من الوفود الأوروبية والأمريكية والآسيوية.','<div class="texte" > <p>قرية ابن حمسان هي واحدة من القرى السياحية ذات الطابع المعماري التراثي في خميس مشيط جنوب المملكة العربية السعودية،&nbsp;وقد أصبحت من أشهر القرى على مستوى منطقة عسير، وقد زار القرية على مستوى المملكة عدد من أصحاب السمو الأمراء، والمعالي الوزراء، ورواد الفكر والأدب، كما زارها على المستوى الدولي عدد من الوفود الأوروبية والأمريكية والآسيوية، إلى جانب السياح من داخل المملكة وخارجها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411507-44206230.jpg?v=1637324489"]','https://cmsphoto.ww-cdn.com/resizeapi/31887be887864bcc373f679978ecf1cace33a482/480/',18.2965483,42.7578386,'Prince Sultan Rd An Nasim Khamis Mushait','','','','https://www.saudi-guide.com/asir-region/i/59411507/bin-hamsan-heritage-village-khamis',1,0,'قريه بن حمسان تراثيه بالخميس تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411504,'asir-region','متحف بن عفيصان التراثي بالخميس','','bin-afeesan-heritage-museum-khamis','["التراث والثقافة"]','["heritage"]','يعتبر متحف عفيصان التراثي وجهة مميزة لمحبي التراث لما يحتويه من قطع أثرية تشرح تاريخ المنطقة وبعض الحضارات القديمة.','<div class="texte" > <p>يعتبر متحف بن عفيصان التراثي بمدينة خميس مشيط وجهة مميزة لمحبي التراث، لما يحتويه من قطع أثرية متنوعة تشرح تاريخ المنطقة وبعض الحضارات القديمة، من مخطوطات وأدوات وأثاث تراثي. يمنح المتحف زواره فرصة للتعرف على أسلوب الحياة القديم في منطقة عسير، ويُعد وجهة تعليمية وثقافية مناسبة للعائلات والمهتمين بالتاريخ المحلي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411504-44206232.jpg?v=1637324509"]','https://cmsphoto.ww-cdn.com/resizeapi/947ccb6ffcfdac7e0733920ed986cc606931a803/480/',18.3306486,42.7539309,'7592 Khamis Mushait Khamis Mushayt','','','','https://www.saudi-guide.com/asir-region/i/59411504/bin-afeesan-heritage-museum-khamis',1,0,'متحف بن عفيصان تراثي بالخميس تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411499,'asir-region','بحيرة سد وادي تندحة','','wadi-tandaha-dam-lake','["أماكن سياحية"]','["sights"]','تم تشييد سد وادي تندحة لتغذية المزارع من حول الوادي، حيث يُشتهر الوادي بمزارعه ذات المحاصيل الوافرة والعالية الجودة.','<div class="texte" > <p>تم تشييد سد وادي تندحة أساسًا لتغذية المزارع المحيطة به، حيث يُشتهر الوادي بمزارعه ذات المحاصيل الوافرة والعالية الجودة. وبعد هطول الأمطار يتكون خلف السد مسطح مائي جميل يجذب الزوار لالتقاط الصور والاستمتاع بالطبيعة الخضراء المحيطة، ما يجعله محطة مناسبة لمحبي الرحلات البرية في منطقة خميس مشيط.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411499-44206234.jpg?v=1637324531"]','https://cmsphoto.ww-cdn.com/resizeapi/b0972463bb245890a70fb5a070c524ff41d07cb0/480/',18.311607,42.880296,'Tendaha Khamis Mushayt Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59411499/wadi-tandaha-dam-lake',1,0,'بحيره سد وادي تندحه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411486,'asir-region','بوليفارد الخميس','Boulevard','boulevard','["أماكن سياحية"]','["sights"]','سلسلة متكاملة ومتنوعة من المقاهي والمطاعم.','<div class="texte" > <p>بوليفارد الخميس هو سلسلة متكاملة ومتنوعة من المقاهي والمطاعم، يقع على طريق الأمير سلطان في حي الشفا بمدينة خميس مشيط. يجمع الموقع بين أجواء عصرية وخيارات متنوعة من المأكولات والمشروبات، ما يجعله وجهة مفضلة للعائلات والشباب لقضاء أمسياتهم، خصوصًا في فترات المساء حين تنتعش الحركة في الموقع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411486-44218830.jpg?v=1637419397"]','https://cmsphoto.ww-cdn.com/resizeapi/37c74da4c79a707cf90d19911f2b5c4ee7da783e/480/',18.2743099,42.719653,'طريق الأمير سلطان، Al Shifa Khamis Mushait','','','','https://www.saudi-guide.com/asir-region/i/59411486/boulevard',1,0,'بوليفارد خميس boulevard اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411478,'asir-region','جادة محايل','','mahayil-avenue','["أماكن سياحية"]','["sights"]','جادة محايل من الوجهات الترفيهية والاجتماعية في محافظة محايل بمنطقة عسير، وتُعد مكانًا مناسبًا للتنزه والمشي.','<div class="texte" > <p>تعد جادة محايل واحدة من أبرز الوجهات الترفيهية والاجتماعية في محافظة محايل بمنطقة عسير، حيث تتوسط حي الحيلة الغربي وتجذب الأهالي والزوار على حد سواء. تتميز الجادة بممراتها المخصصة للمشي والتنزه، إضافة إلى وجود عدد من المقاهي والمحال التي تضفي أجواء حيوية خصوصًا في ساعات المساء. تُعد وجهة مناسبة للعائلات الراغبة في قضاء وقت هادئ بعيدًا عن صخب المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411478-44218860.jpg?v=1637419525"]','https://cmsphoto.ww-cdn.com/resizeapi/1b758965af9a7d5ac1896b3d66ab47d4f724583c/480/',18.5159805,42.0632101,'G387+97W حي الحيلة الغربي محايل','','','','https://www.saudi-guide.com/asir-region/i/59411478/mahayil-avenue',1,0,'جاده محايل اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411454,'asir-region','متحف ومعرض محايل عسير','','mahayil-asir-museum','["التراث والثقافة"]','["heritage"]','تأسس متحف محايل عسير على يد عاشق للتراث إدريس الشاعري وبدعم من بلدية محايل عسير، ويضم أكثر من 1000 قطعة أثرية من مخطوطات تاريخية وأسلحة قديمة وأواني مطبخ وأدوات زراعة وغيرها.','<div class="texte" > <p>تأسس متحف ومعرض محايل عسير على يد عاشق التراث إدريس الشاعري، وبدعم من بلدية محايل عسير، ويضم المتحف أكثر من 1000 قطعة أثرية تشمل مخطوطات تاريخية وأسلحة قديمة وأواني مطبخ وأدوات زراعة وغيرها. يُعد المتحف وجهة تعليمية وثقافية مهمة توثق تاريخ محافظة محايل وتراثها الشعبي لزوارها من مختلف الأعمار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411454-44242897.jpg?v=1637590848"]','https://cmsphoto.ww-cdn.com/resizeapi/fa64f8bf53c82e23950836faaf51db6a28061504/480/',18.4905399,42.0615425,'F3R6+6J7 حي الحيلة الشرقي محايل','','','','https://www.saudi-guide.com/asir-region/i/59411454/mahayil-asir-museum',1,0,'متحف ومعرض محايل عسير تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411436,'asir-region','قصر الحضارات الإسلامية','Palace Islamic civilizations Balnmas','palace-islamic-civilizations-balnmas','["التراث والثقافة"]','["heritage"]','يقع قصر الحضارات الإسلامية في قرية المقر الواقعة في محافظة النماص على بعد 170 كم شمال أبها في جنوب غرب السعودية، ويعتبر أعجوبة من أعاجيب القرن الواحد والعشرين صاغتها عقلية هندسية تراثية في قالب سعودي صرف.','<div class="texte" > <p>يقع قصر الحضارات الإسلامية في قرية المقر الواقعة في محافظة النماص على بعد 170 كم شمال أبها في جنوب غرب السعودية، ويعتبر أعجوبة من أعاجيب القرن الواحد والعشرين صاغتها عقلية هندسية تراثية في قالب سعودي صرف، ويتداعى إلى الأذهان عند مدخل النماص قصر الحمراء في غرناطة، الذي يتربع في ثنايا القرن السابع عشر، ويستلهم المقر قصة حضارة حفرها (محمد المقر الشهري) صاحب القرية التراثية، استغرقت أكثر من 35 عاما واستخدم في البناء أكثر من مليوني حجر طبيعي من جبال عسير بتكلفة تفوق الـ 80 مليون ريال سعودي لتكون من شواهد براعة هذا الإرث التاريخي.</p> <p>ولم يدر بخلد (محمد المقر الشهري)، الذي تعثر في دراسته في مرحلة الطفولة، وأعاد الأول ابتدائي سبع مرات، أنه سيقضي بقية عمره في البناء والتشييد مروراً قبلها برحلاتٍ سافر فيها إلى كل الدنيا مكتسباً الخبرة والدراية الكافية لتكون شرارة الانطلاق لمشروعه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411436-44242902.jpg?v=1637590871"]','https://cmsphoto.ww-cdn.com/resizeapi/ee97e077ea593205bba28c083bf434f1f6397f44/480/',19.1177429,42.1189712,'SA Al Namas Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59411436/palace-islamic-civilizations-balnmas',1,0,'قصر حضارات اسلاميه palace islamic civilizations balnmas تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411428,'asir-region','قرية العرش التراثية','Alorosh Heritage Village','alorosh-heritage-village','["التراث والثقافة"]','["heritage"]','قرية العرش هي إحدى قرى قبائل بني ثابت الواقعه شمال محافظة النماص، أبرز ما يميز القرية هو المتحف المتكون من مبنى كبير من طابقين مبني بالحجر على طراز البيوت التراثية لمنطقة عسير القديمة ويضم 9 غرف مختلفة المساحات تضم حوالي 1000 قطعة تراثية.','<div class="texte" > <p>قرية العرش هي إحدى قرى قبائل بني ثابت الواقعه شمال محافظة النماص، أبرز ما يميز القرية هو المتحف&nbsp;المتكون من مبنى كبير من طابقين مبني بالحجر على طراز البيوت التراثية لمنطقة عسير القديمة ويضم 9 غرف مختلفة المساحات تضم حوالي 1000 قطعة تراثية، وتتكون القطع التراثية الموجودة بداخل ذلك المتحف من أدوات وأواني الطهي والطعام وكذلك أواني الري ويشتمل على غرفة لتخزين الحبوب كذلك تشمل أدوات القهوة والمباخر والرحي لطحن وجرش الحبوب كما تشمل أيضا أدوات الزراعة والحراثة وأدوات النحت والنجارة وكذلك بعض الملابس الرجالية والنسائية وبعض الحلي وأدوات التجميل الخاصة بالنساء والخاصة بتجهيز العروس قديم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411428-44242907.jpg?v=1637590894"]','https://cmsphoto.ww-cdn.com/resizeapi/cd4188e1627a18c1c298fa2e32e95afa8576a949/480/',19.322553,42.073695,'SA Bani Amr Al Namas','','','','https://www.saudi-guide.com/asir-region/i/59411428/alorosh-heritage-village',1,0,'قريه عرش تراثيه alorosh heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411421,'asir-region','القرية التراثية بالنماص','','al-namas-heritage-village','["التراث والثقافة"]','["heritage"]','تقع قرية المقر السياحية في محافظة النماص بمنطقة عسير، وتتميز بموقعها المميز حيث تقع على مطل مرتفع في المنطقة، بالإضافة إلى أهم القصور التاريخية الموجودة في القرية وهو قصر المقر التاريخي الذي يتميز أيضًا بأنه تحفة معمارية وهندسية وفنية.','<div class="texte" > <p>تقع قرية المقر السياحية&nbsp;في محافظة النماص في منطقة عسير جنوب المملكة العربية السعودية وتتميز قرية المقر بموقعها المميز حيث تقع علي مطل مرتفع في المنطقة، بالإضافة إلى أهم القصور التاريخية الموجودة في القرية وهو قصر المقر التاريخي الذي يتميز أيَضًا بأنه تحفة معمارية وهندسية وفنية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411421-44266548.jpg?v=1637674809"]','https://cmsphoto.ww-cdn.com/resizeapi/6c75d5d52f39ff8458fd07cbf42e725efa876451/480/',19.0434999,42.1185487,'King Faisal Rd الظهارة Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59411421/al-namas-heritage-village',1,0,'قريه تراثيه بالنماص تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411372,'asir-region','متحف بن سلام التراثي بقرية الميفا','Bin Salam village heritage','bin-salam-village-heritage','["التراث والثقافة"]','["heritage"]','يعد متحف ابن سلام التراثي من أبرز المعالم الأثرية في منطقة عسير حيث أنه يعبر عن تراث المنطقة وحضارتها، يضم المتحف عددا من أدوات الطبخ والزراعة التي كانت تستخدم قديمًا بالإضافة إلى بعض أنواع الحلي القديمة.','<div class="texte" > <p>يعد متحف ابن سلام التراثي من أبرز المعالم الأثرية في منطقة عسير حيث أنه يعبر عن تراث المنطقة وحضارتها، يضم المتحف عددا من أدوات الطبخ والزراعة التي كانت تستخدم قديماً بالإضافة إلى بعض أنواع الحلي القديمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411372-44283021.jpg?v=1637766795"]','https://cmsphoto.ww-cdn.com/resizeapi/34275cfdc65c6d7ba30fd0cd4d9aecc37029d611/480/',19.0382187,42.1134919,'الظهارة Al Namas Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59411372/bin-salam-village-heritage',1,0,'متحف بن سلام تراثي بقريه ميفا bin salam village heritage تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411368,'asir-region','متحف بن صوفان - النماص','Museum son Sofan','museum-son-sofan','["التراث والثقافة"]','["heritage"]','يتكون متحف بن صوفان الواقع في محافظة النماص من أربع قاعات كبيرة للعرض بالإضافة إلى قاعه خارجية مكشوفة ويحتوي المتحف على حوالي 1200 قطعة تراثية تشمل أدوات الزراعة والري.','<div class="texte" > <p>يتكون متحف بن صوفان الواقع في محافظة النماص من أربع قاعات كبيرة للعرض بالإضافة إلى قاعه خارجية مكشوفة ويحتوي المتحف على حوالي 1200 قطعة تراثية تشمل أدوات الزراعة والري بالإضافة لوجود جناح خاص بالعملات وجزء خاص بالأسلحة والأواني والصور القديمة كما أن هناك جناح مخصص للضيافة مكون من أدوات حمس القهوة ودلال مختلفة الأنواع وأباريق للشاي وأدوات إشعال النار قديما وقد وضعت القطع على أرفف وعلى فترينات وكذلك العرض بالتعليق على الجداران.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411368-44283037.jpg?v=1637766848"]','https://cmsphoto.ww-cdn.com/resizeapi/9cf8882065d6ba6d3aa229c0283531ae77639c4d/480/',19.1800987,42.1291961,'SA Al Namas Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59411368/museum-son-sofan',1,0,'متحف بن صوفان نماص museum son sofan تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411366,'asir-region','قصر ثربان','','tharban-palace','["التراث والثقافة"]','["heritage"]','قصر ثربان هو أحد القصور التاريخية الموجودة في محافظة النماص، ويتكون من ساحة خارجية وبئر ماء ومساحة مزروعة وعدد من المباني، تم حصرها في أربع مبانٍ ومسجد وثلاثة غرف مجاورة للمسجد. جميع المباني منشأة من الحجر ومكونة من طابقين ومبنى واحد مكون من خمس طوابق، ويوجد للقصر مدخلان، الأول في السور على الطريق العام مباشرة في الجهة الغربية والثاني في الجهة الشمالية الغربية.','<div class="texte" > <p>قصر ثربان هو أحد القصور التاريخية الموجودة في محافظة النماص، ويتكون من ساحة خارجية وبئر ماء ومساحة مزروعة وعدد من المباني تم حصرها في أربع مباني ومسجد وثلاثة غرف مجاورة للمسجد، جميع المباني منشأة من الحجر ومكونة من طابقين ومبنى وحيد مكون من خمس طوابق ودور واحد للمسجد وملاحقه، ويوجد للقصر مدخلان الأول في السور على الطريق العام مباشرة في الجهة الغربية والثاني في الجهة الشمالية الغربية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411366-44283049.jpg?v=1637766892"]','https://cmsphoto.ww-cdn.com/resizeapi/fc7221915c20bd1b48f3ccfdfa87dd658bbf8d3e/480/',19.1212453,42.1300239,'Al Namas Al Sediq Al Namas','','','','https://www.saudi-guide.com/asir-region/i/59411366/tharban-palace',1,0,'قصر ثربان تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411364,'asir-region','قرية آل جبر','The village of Al Jabr','the-village-of-al-jabr','["أماكن سياحية"]','["sights"]','تعد قرية آل جبر التراثية واحدة من أجمل القرى القديمة جنوب محافظة النماص حيث لا زالت تحتفظ بالكثير من تراث الماضي.','<div class="texte" > <p>تعد قرية آل جبر التراثية واحدة من أجمل القرى القديمة جنوب محافظة النماص، حيث لا تزال تحتفظ بالكثير من ملامح العمارة التراثية والبناء الحجري التقليدي. تعكس القرية أسلوب الحياة القديم في منطقة عسير، وتجذب محبي التراث والتصوير الراغبين في استكشاف تفاصيل العمارة الجبلية الأصيلة المحافظ عليها حتى اليوم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411364-44218931.jpg?v=1637419710"]','https://cmsphoto.ww-cdn.com/resizeapi/13c2bc28b294be8c977dc68e39a0ff51ac998eda/480/',19.074754,42.1359888,'King Faisal Rd Al Namas Al Namas','','','','https://www.saudi-guide.com/asir-region/i/59411364/the-village-of-al-jabr',1,0,'قريه جبر the village of al jabr اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411361,'asir-region','متحف النماص الأثري','Namas Museum','namas-museum','["التراث والثقافة"]','["heritage"]','يقع متحف النماص الأثري في الحي القديم ويجاوره عدد من القصور والحصون الأثرية القديمة ذات التصاميم الإبداعية، ويحتوي المتحف على كل مايتصل بتراث المنطقة، كما يحتوي على أكثر من 2000 قطعة أثرية.','<div class="texte" > <p>يقع متحف النماص الأثري في الحي القديم ويجاوره عدد من القصور والحصون الأثرية القديمة ذات التصاميم الإبداعية، ويحتوي المتحف على كل مايتصل بتراث المنطقة، كما يحتوي على أكثر من 2000 قطعة أثرية،</p> <p>&nbsp;يتكون المتحف من خمس طوابق، في الطابق&nbsp;الأول نجد كل الأدوات الزراعية التي كان يستخدمها الأهالي قديما كما يضم نموذجا للبئر القديمة وطرق استخراج الماء منها بالطرق التقليدية، وأما الطابق&nbsp;الثاني فهو&nbsp;يحتوي على الأدوات المنزلية المستخدمة قديماً، ويضم بعض الأجهزة مثل الهاتف، والمكواة والتلفاز وبالنسبة للطابق الثالث فيحتوي على الأسلحة القديمة كالبنادق والرماح والجنابي بجميع أنواعها ورؤوس وقرون الصيد الوعول والغزلان، وهناك قسم لأنواع العملات السعودية والأجنبية الورقية والمعدنية، أما الطابقين&nbsp;الرابع والخامس فيحتويان على حلي النساء وأدوات الزينة للمرأة في اليد وفي الأذن وجميع أنواع الملابس النسائية القديمة كما أن بالمتحف ركنا للأحجار ذات النقوش الحجرية والتي يرجع تاريخ أقدمها إلى القرن الأول الهجري والعديد من المخطوطات والوثائق القديمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411361-44283065.jpg?v=1637766929"]','https://cmsphoto.ww-cdn.com/resizeapi/95f5c944d8c4fc6ae96345c80369d9bee8cd1d70/480/',19.1202864,42.13107,'Abu Bakar Alsadeeq Al Sediq Al Namas','','','','https://www.saudi-guide.com/asir-region/i/59411361/namas-museum',1,0,'متحف نماص اثري namas museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411357,'asir-region','قرية المقر السياحية','Al Meger Tourist Village','al-meger-tourist-village-2','["التراث والثقافة"]','["heritage"]','قرية المقر في محافظة النماص بعسير تقع على مطلّ مرتفع، وأبرز معالمها قصر المقر التراثي بطرازه الإسلامي والأندلسي، ويحتضن مجموعة هائلة من المخطوطات والقطع الأثرية منها أكثر من ألف مخطوطة يدوية للقرآن الكريم.','<div class="texte" > <p>تقع قرية المقر في محافظة النماص بمنطقة عسير، وتتميز بموقعها على مطلّ مرتفع في المنطقة. أبرز معالمها هو قصر المقر، وهو قصر تراثي يجمع بين الطراز الإسلامي والأندلسي، ويحتضن مجموعة هائلة من المخطوطات والقطع الأثرية القديمة، من بينها أكثر من ألف مخطوطة يدوية للقرآن الكريم، ما يجعله من أبرز حاضنات هذه الكنوز في المنطقة. كما يقدم القصر خدمات فاخرة وأماكن إقامة مريحة للزوار، ما يجعل زيارته تجربة ثقافية وتاريخية لا تُنسى لمحبي التراث والعمارة التقليدية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411357-44218942.jpg?v=1637419773"]','https://cmsphoto.ww-cdn.com/resizeapi/769d22ebd3cbfb599f905014f6d26c1fcb85d8fb/480/',19.1178664,42.1190323,'4499+4JV Al Namas Al Namas','','https://www.visitsaudi.com/ar/aseer/attractions/heritage-civilization-palace-museum-almaqar','','https://www.saudi-guide.com/asir-region/i/59411357/al-meger-tourist-village-2',1,0,'قريه مقر سياحيه al meger tourist village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411347,'asir-region','قرية آل عليان التاريخية','Al Olayyan','al-olayyan','["التراث والثقافة"]','["heritage"]','آل عليان هي إحدى القرى التراثية التابعة لمركز السرح في محافظة النماص بمنطقة عسير، ويعود تاريخها إلى 1500 سنة، تحتوي القرية متحفا ومسجد وقلعة أثريين، ويضم المتحف 3000 قطعة أثرية.','<div class="texte" > <p>آل عليان هي إحدى القرى التراثية التابعة لمركز السرح في محافظة النماص بمنطقة عسير، ويعود تاريخها إلى نحو 1500 عام. تحتوي القرية على متحف ومسجد وقلعة أثرية، ويضم المتحف نحو 3000 قطعة أثرية تعكس تاريخ المنطقة وأسلوب الحياة فيها قديمًا، ما يجعلها وجهة مهمة لمحبي التاريخ والتراث في عسير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411347-44283077.jpg?v=1637766964"]','https://cmsphoto.ww-cdn.com/resizeapi/321f66501ea2e493cc0146e37368133ef652cf5a/480/',19.2913879,42.063657,'73R7+HF3 Halaba Al Namas','','','','https://www.saudi-guide.com/asir-region/i/59411347/al-olayyan',1,0,'قريه عليان تاريخيه al olayyan تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411311,'asir-region','منتزه الامير سلطان بن سلمان بالنماص','','prince-sultan-bin-salman-park-al-namas','["أماكن سياحية"]','["sights"]','منتزه يحتوي على مساحة كبيرة من المسطحات الخضراء تبلغ مساحتها حوالي 4500 متر مربع، كما يحتوي المنتزه على جلسات مظللة ومناطق ألعاب وعدة مرافق خدمية.','<div class="texte" > <p>يحتوي منتزه الأمير سلطان بن سلمان في محافظة النماص على مساحة كبيرة من المسطحات الخضراء تبلغ نحو 4500 متر مربع، إلى جانب جلسات مظللة ومناطق ألعاب وعدة مرافق خدمية. يُعد المنتزه وجهة عائلية مفضلة للتنزه والاسترخاء وسط أجواء النماص الجبلية المعتدلة، ويستقطب الزوار على مدار العام خصوصًا في فصل الصيف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411311-44218956.jpg?v=1637419833"]','https://cmsphoto.ww-cdn.com/resizeapi/0acee79d86cb996603f2db39f2f0baeaf072fd00/480/',19.097393,42.1189749,'2492 Al Namas Al Namas','','','','https://www.saudi-guide.com/asir-region/i/59411311/prince-sultan-bin-salman-park-al-namas',1,0,'منتزه امير سلطان بن سلمان بالنماص اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411303,'asir-region','بحيرة سد وادي بدوه - النماص','','wadi-badwah-dam-lake-al-namas','["أماكن سياحية"]','["sights"]','أنشئ سد بدوة سنة 2002 من أجل استعاضة مياه الآبار الجوفية وتوفير مياه الشرب لسكان المنطقة، حاجزه خرساني النوع، يبلغ طول السد 92 مترًا وارتفاعه 30 مترًا وبسعة تخزينية تفوق مليوني متر مكعب. اعتمد المجلس البلدي بمحافظة النماص عددًا من المشاريع المقترحة منها تطوير متنزه سد بدوة والعمل على تجهيزه وتهيئته للاستثمار.','<div class="texte" > <p>أنشئ سد بدوة سنة 2002 من أجل استعاضة مياه الآبار الجوفية وتوفير مياه الشرب لسكان المنطقة والاستفادة من موارد المياه في وادي بدوة، حاجزه خراساني النوع، يبلغ طول السد 92 مترًا وارتفاعه يبلغ 30 مترًا وبسعة تخزينية تفوق مليوني متر مكعب.</p> <p>اعتمد المجلس البلدي بمحافظة النماص عددا من المشاريع المقترحة لتنفيذها منها تطوير متنزه سد بدوة والعمل على تجهيزه من قبل البلدية وتهيئته للاستثمار وكذلك ربطه بطريق مزدوج من وسط المحافظة وجعله واجهة سياحية مميزة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411303-44218966.jpg?v=1637419907"]','https://cmsphoto.ww-cdn.com/resizeapi/b415d890230b2e18b97517b9ca52be775d9c97e5/480/',19.1659262,42.1643703,'بحيرة سد وادي بدوه النماص النماص','','','','https://www.saudi-guide.com/asir-region/i/59411303/wadi-badwah-dam-lake-al-namas',1,0,'بحيره سد وادي بدوه نماص اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411280,'asir-region','بحيرة سد وادي ترج -النماص','','wadi-turaj-dam-lake-al-namas','["أماكن سياحية"]','["sights"]','يعد سد وادي ترج أحد أكبر السدود في محافظة النماص، حيث يبلغ ارتفاعه حوالي 30 مترًا، ويعد السد متنفسًا لأهالي المنطقة.','<div class="texte" > <p>يعد سد وادي ترج أحد أكبر السدود في محافظة النماص بمنطقة عسير، حيث يبلغ ارتفاعه حوالي 30 مترًا، ويشكل بحيرة خلفه تُعد متنفسًا لأهالي المنطقة وزوارها. تحيط بالبحيرة تضاريس جبلية خضراء تضفي عليها منظرًا طبيعيًا آسرًا، ما يجعلها وجهة محببة لهواة التنزه والتصوير على مدار العام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411280-44219097.jpg?v=1637420963"]','https://cmsphoto.ww-cdn.com/resizeapi/d63a0f6e8c610f968193cfe6f585aeca165fb977/480/',19.03709,42.2125022,'بحيرة سد وادي ترج منطقة عسير SA','','','','https://www.saudi-guide.com/asir-region/i/59411280/wadi-turaj-dam-lake-al-namas',1,0,'بحيره سد وادي ترج النماص اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411276,'asir-region','متحف رجال ألمع','Rijal Alma Museum','rijal-alma-museum','["التراث والثقافة"]','["heritage"]','يتكون متحف رجال ألمع من مبنى مستقل يضم قاعة كبيرة وقاعة أصغر ومستودعًا، ويضم وثائق وعملات تاريخية إلى جانب صور قديمة ومخطوطات وكتب توارثت المنطقة.','<div class="texte" > <p>يتكون متحف رجال ألمع من مبنى مستقل متكون من قاعة كبيرة وقاعة أصغر ومستودع، الصالة الأولى عرض بها وثائق وعملات للحكم السعودي والدول الخليجية والعربية والأجنبية إضافة للطوابع والمخطوطات القديمة المتوارثة وغيرها وبعض الكتب القديمة،&nbsp;الصالة الثانية عبارة عن صور قديمة وهي أكثر من 700 صورة معروضة ومبروزه بالإضافة إلى قطع تراثيه محليه وتشمل بعض الأواني والفوانيس والأسلحة القديمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411276-44283092.jpg?v=1637767005"]','https://cmsphoto.ww-cdn.com/resizeapi/f70f3b6461a5960c8aaa5a62faa87a70f45f04bc/480/',18.2125386,42.273848,'Brightest region of Asir province of Rojal of Saudi Arabia رجال ألمع منطقة عسير','','','','https://www.saudi-guide.com/asir-region/i/59411276/rijal-alma-museum',1,0,'متحف رجال مع rijal alma museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411266,'asir-region','قرية رجال ألمع التراثية','Rejal Almaa Heritage Village','rejal-almaa-heritage-village','["التراث والثقافة"]','["heritage"]','قرية رجال ألمع التراثية تقع في محافظة رجال ألمع بمنطقة عسير جنوب غرب السعودية، وتبعد عن مدينة أبها حوالي 52 كم باتجاه الغرب، يزيد تاريخ بناءها عن 900 سنة.','<div class="texte" > <p>قرية رجال ألمع التراثية هي قرية تراثية تقع في محافظة رجال ألمع الواقعة بمنطقة عسير جنوب غرب السعودية، وتبعد عن مدينة أبها حوالي 52 كم باتجاه الغرب،&nbsp;يزيد تاريخ بناءها عن 900 سنة، كانت القرية نقطة مهمة، حيث كانت تربط بين القادمين من اليمن وبلاد الشام مروراً بمكة المكرمة والمدينة المنورة، الأمر الذي جعلها مركزاً تجارياً هاماً،&nbsp;تتكون القرية من نحو 60 مبنىً بنيت من الحجارة الطبيعية والطين والأخشاب، ويضم الموقع متحفاً قام بإنشائه أهالي القرية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411266-44283098.jpg?v=1637767044"]','https://cmsphoto.ww-cdn.com/resizeapi/a57dd315a5215f9ea71377941184dcedf5dee947/480/',18.2124413,42.2732161,'211 Rojal Ragal Almaa','','','','https://www.saudi-guide.com/asir-region/i/59411266/rejal-almaa-heritage-village',1,0,'قريه رجال مع تراثيه rejal almaa heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411110,'jizan','القرية التراثية','Jazan Heritage Village','jazan-heritage-village-alkry-altrathy','["التراث والثقافة"]','["heritage"]','القرية التراثية بجازان واجهة للموروث الشعبي، تعرض أدوات البيئات الجبلية والبحرية والساحلية والملابس والأسلحة القديمة ومنتجات الأسر المنتجة.','<div class="texte" > <p>القرية التراثية تمثل واجهة للموروث الشعبي بمنطقة جازان، تحتوي على الأدوات التراثية المستخدمة في البيئة الجبلية البحرية الساحلية من ملابس أدوات الحرث والأسلحة القديمة والآنية المستخدمة في كل بيئة بالإضافة إلى&nbsp;مواهب وإبداعات أبناء المنطقة في الرسم التشكيلي والتنظيم وما تزخر به المنطقة من نباتات عطرية ومنتجات متميزة للأسر المنتجة إضافة إلى الشاي الأزرق الذي يتم إنتاجه في منطقة جازان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411110-44664397.jpg?v=1640393343"]','https://cmsphoto.ww-cdn.com/resizeapi/f256d7e0fa567dc9e6cbcb23776348c297bd4459/480/',16.8251686,42.6205426,'King Abdullah Rd Industrial Area Jizan','','','','https://www.saudi-guide.com/jizan/i/59411110/jazan-heritage-village-alkry-altrathy',1,0,'قريه تراثيه jazan heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411108,'jizan','قلعة جازان التراثية','Turks Castle','turks-castle-klaa-gazan-altrathy','["التراث والثقافة"]','["heritage"]','قلعة جازان التراثية أو قلعة الدوسرية قلعة أثرية تتربع على جبل يطل على البحر الأحمر وسط مدينة جازان، وتعود إلى العهد العثماني.','<div class="texte" > <p>قلعة جازان التراثية أو كما تسمى قلعة الدوسرية هي قلعة أثرية تتربع على جبل&nbsp;<span>يطل على البحر الأحمر</span> في وسط مدينة جازان جنوب المملكة العربية السعودية،&nbsp;يعود تاريخ بناءها إلى الدولة العثمانية حيث كانت مقر للحاكم التركي،&nbsp;يقدر ارتفاعها بنحو 150 متر فوق سطح البحر، تأخذ القلعة شكل المربع ومساحتها الإجمالية تقدر بنحو 900 م2، وهي مدعمة بأربعة أبراج ضخمة، بدأت وزارة السياحة أعمال ترميم القلعة وإعادة هيكلتها في يناير 2012م على ثلاث مراحل، المرحلة الأولى عبارة عن إزالة الأنقاض، والثانية إمداد الكهرباء، وتطوير المنطقة المحيطة بالقلعة، والمرحلة الثالثلة والأخيرة إنشاء المتحف داخل القلعة.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411108-44664394.jpg?v=1640393322"]','https://cmsphoto.ww-cdn.com/resizeapi/6f910ffb21988aec09a33ceb79489fd81cd781b8/480/',16.8880336,42.545583,'VGQW+668 Alqal''a Jazan','','','','https://www.saudi-guide.com/jizan/i/59411108/turks-castle-klaa-gazan-altrathy',1,0,'قلعه جازان تراثيه turks castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411099,'jizan','جزيرة احبار','','gzyr-ahbar','["أماكن سياحية"]','["sights"]','جزيرة أحبار أو حبار في البحر الأحمر قبالة شاطئ جازان، ملاذ للسياح بشواطئها الرملية ومياهها الفيروزية، وتجذب الغواصين ومحبي الصيد والطيور.','<div class="texte" > <p>جزيرة حُبار أو جزيرة أحبار هي إحدى الجزر الواقعة في البحر الأحمر، تعرف جزيرة حُبار أو أحبار أيضاً باسم جزيرة ذو الراكة، وتقع على بعد 15 كيلومتر من شاطئ محافظة جازان جنوب غرب السعودية، وتشكّل ملاذاً مثالياً للسياح الذين يتطلعون إلى الاستمتاع بالشواطئ الرملية والبحر الفيروزي والمساحات الخضراء والأرصفة والمقاهي ومطاعم المأكولات البحرية ومجموعة واسعة من الأنشطة المائية، كما تجذب الجزيرة العديد من الغواصين والصيادين، ويمكن لمحبي الطبيعة اكتشاف العديد من أنواع الطيور النادرة والمهاجرة،&nbsp;تبلغ مساحة الجزيرة نحو 1,1 كم مربع.</p> <p>كما أن الجزيرة تحتوي على العديد من أنواع العيون الحارة التي يأتي إليها السياح من جميع أنحاء العالم بهدف السياحة العلاجية، كما تتعدد أنواع الشعب المرجانية في جيرة أحبار نظرًا لأنها تطل مباشرة على البحر الأحمر المعروف بتميز الشعاب المرجانية الموجودة به، ومناخه المعتدل على مدار العام،&nbsp;تم تطوير الجزيرة لكي تلبي كافة احتياجات الزوار، وقد تم تزويدها بالعديد من الجلسات والأرصفة الخاصة بالقوارب، حتى يستطيع السياح استئجار أحد تلك القوارب للوصول إلى كافة الأماكن والشواطئ في الجزيرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411099-44664402.jpg?v=1640393374"]','https://cmsphoto.ww-cdn.com/resizeapi/ffc42116365ce98fab07f6932906ffb48e575779/480/',16.8835158,42.4101934,'VCM6+C34 Jazan Jazan','','','','https://www.saudi-guide.com/jizan/i/59411099/gzyr-ahbar',1,0,'جزيره احبار اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411092,'jizan','مرسى الأحلام','','mrs-alahlam','["أماكن سياحية"]','["sights"]','مرسى الأحلام من أهم الأماكن السياحية في جازان، يوفر قوارب للإيجار وجميع المرافق الخدمية من مطاعم ومقاهٍ ومصلى.','<div class="texte" > <p>يعد مرسى الأحلام واحد من أهم الأماكن السياحية في منطقة جازان، يوفر المرسى عدة قوارب للإيجار بالساعة كما يوفر المرسى جميع المرافق الخدمية مثل المطاعم والمقاهي والمصلى ودورات المياه وغيرها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411092-44676969.jpg?v=1640554465"]','https://cmsphoto.ww-cdn.com/resizeapi/58b2a21e3e0eaa9e00a5f84cbce3d3ba2e7df114/480/',16.839497,42.5833572,'Jizan Industrial Area Gazan','','','','https://www.saudi-guide.com/jizan/i/59411092/mrs-alahlam',1,0,'مرسي احلام اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411087,'jizan','مرسى الحافة السياحي','Tourist Edge Marina','tourist-edge-marina-mrs-alhaf-alsyahy','["أماكن سياحية"]','["sights"]','مرسى الحافة السياحي في جازان يوفر قوارب نزهة إلى جزيرة أحبار ورحلات إلى جزر فرسان.','<div class="texte" > <p>مرسى لتأجير قوارب النزهة لجزيرة احبار وتاكسي فرسان واسعاره تعد الاقل مقارنةً بالمراسئ الاخرى.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411087-44676950.jpg?v=1640554376"]','https://cmsphoto.ww-cdn.com/resizeapi/99e7a4e56f6cc153a92efcc1985348f8b466c4a6/480/',16.9019745,42.5411654,'Jazan Ash Shati Gazan','','','','https://www.saudi-guide.com/jizan/i/59411087/tourist-edge-marina-mrs-alhaf-alsyahy',1,0,'مرسي حافه سياحي tourist edge marina اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411061,'jizan','بوليفارد جازان','','bolyfard-gazan','["أماكن سياحية"]','["sights"]','بوليفارد جازان مبنى تجاري وإداري على طريق الكورنيش في حي الشاطئ بجازان، يطل مباشرة على كورنيش جازان والواجهة البحرية.','<div class="texte" > <p>بوليفارد جازان مبنى تجاري وإداري على طريق الكورنيش في حي الشاطئ بمدينة جازان، ويطل مباشرة على كورنيش جازان والواجهة البحرية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411061-44676956.jpg?v=1640554418"]','https://cmsphoto.ww-cdn.com/resizeapi/d95e932307d2bbfdd74e4df161a350603e65fff1/480/',16.9090967,42.5486374,'Prince Abdullah Al Faisal St Ash Shati Jizan','','','','https://www.saudi-guide.com/jizan/i/59411061/bolyfard-gazan',1,0,'بوليفارد جازان اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59411036,'jizan','الكورنيش الشمالي','North Corniche Park','north-corniche-park-alkornysh-alshmaly','["أماكن سياحية"]','["sights"]','الكورنيش الشمالي في جازان واجهة بحرية على ساحل البحر الأحمر، يوفر مسارات للمشي ومساحات للجلوس والاستمتاع بالنسيم البحري.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59411036-44676964.jpg?v=1640554439"]','https://cmsphoto.ww-cdn.com/resizeapi/709a0e426a7b5a0c2207ca812dd4580310b65231/480/',16.9169738,42.5467196,'Corniche Rd Ash Shati Jizan','','','','https://www.saudi-guide.com/jizan/i/59411036/north-corniche-park-alkornysh-alshmaly',1,0,'كورنيش شمالي north corniche park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408447,'medina','مزرعة وبئر عثمان بن عفان','Uthman Ibn Affan Farm Well','uthman-ibn-affan-farm-well','["أماكن سياحية"]','["sights"]','مزرعة وبئر عثمان بن عفان بالمدينة المنورة، أول وقف في تاريخ الإسلام، بئر رومة التي اشتراها عثمان بن عفان تبرعًا للمحتاجين.','<div class="texte" > <p>تعتبر مزرعة وبئر عثمان بن عفان واحدة من المعالم التاريخية القديمة والأثرية في المدينة المنورة والتي تقع في الشمال الغربي من المدينة المنورة، وتبعد عن المسجد النبوي حوالي خمسة كيلومترات، بأسفل الوادي المبارك المعروف بوادي العقيق قُرب مجمع السيل. وهي عبارة عن مزرعة قديمة جداً تضم البئر الذي اشتراه عثمان بن عفان تبرعاً للمحتاجين، وقد تم الاعتناء بالمزرعة كاملة على مر العصور، وتمت زراعتها بمختلف المحاصيل الزراعية كالنخيل، الى جانب العديد من المشاتل الزراعية للخضار والفاكهة التي تنتشر في أرجاء المزرعة،وقد أصبحت المزرعة أول وقف في تاريخ الاسلام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408447-44307175.jpg?v=1637905216"]','https://cmsphoto.ww-cdn.com/resizeapi/a8e7c252f2f62d6dbd47ab9aa10732269c8f85bb/480/',24.494549,39.5785656,'Bir Uthman Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408447/uthman-ibn-affan-farm-well',1,0,'مزرعه وبئر عثمان بن عفان uthman ibn affan farm well اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408433,'medina','المساجد السبعة','The Seven Mosques','the-seven-mosques','["معالم إسلامية"]','["islamic"]','المساجد السبعة بالمدينة المنورة، مجموعة مساجد صغيرة مرتبطة بغزوة الخندق من أهم المعالم التي يزورها القادمون إلى المدينة.','<div class="texte" > <p>من أهم المعالم التي يزورها القادمون إلى المدينة المنورة، وهي مجموعة مساجد صغيرة عددها الحقيقي ستة وليس سبعة ولكنها اشتهرت بهذا الاسم، نظراً لإضافة البعض لمسجد القبلتين&nbsp;ضمن هذه المساجد، وذلك لأن من يزورها يزور ذلك المسجد أيضاً في نفس الرحلة فيصبح عددها سبعة</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408433-44307244.jpg?v=1637905672"]','https://cmsphoto.ww-cdn.com/resizeapi/2cf5962ee61ffd5a1493273f72539cfdf22733e9/480/',24.4768665,39.5960078,'As Sih Al Fath Medina','','','','https://www.saudi-guide.com/medina/i/59408433/the-seven-mosques',1,0,'مساجد سبعه the seven mosques معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408432,'medina','بئر عذق','Bir Athq','bir-athq','["أماكن سياحية"]','["sights"]','بئر عذق بالمدينة المنورة، بئر مباركة غرب مسجد قباء في موقع منازل بني عمرو بن عوف الأوسيين.','<div class="texte" > <p>يقع بئر عذق غرب مسجد قباء، ويميل نحو الجنوب نوعًا ما، وكانت مكانها تقع منازل بني عمرو بن عوف الأوسيين، ومن حينها أصبحت هذه البئر مباركة، وهي من الآبار النبوية الشريفة في المدينة المنورة التي وثقها أهل المدينة والمؤرخون ومعروفة حتى يومنا هذا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408432-44307438.jpg?v=1637907562"]','https://cmsphoto.ww-cdn.com/resizeapi/9305961f19abce53bb8172ee9c05e1ea5fc71d0f/480/',24.4384949,39.6158376,'Al Usbah Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408432/bir-athq',1,0,'بئر عذق bir athq اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408388,'medina','جماء الجمة الغربية','Jammaa Al Jumma Al Gharbiyah','jammaa-al-jumma-al-gharbiyah','["أماكن سياحية"]','["sights"]','الجماء الغربية (جماء العاقر) أحد جبال الجماوات الثلاثة المطلة على وادي العقيق غربي المدينة المنورة، وأكبرها وأبعدها عن المسجد النبوي.','<div class="texte" > <p>الجماء الغربية هي جماء العاقر (وتُعرف أيضاً بجماء العاقل)، إحدى الجماوات الثلاث التي تطل على وادي العقيق غربي المدينة المنورة. تقع في الجهة الشمالية الغربية من جماء تضارع وجماء أم خالد، وهي أبعدها عن المدينة إذ تبعد عن المسجد النبوي الشريف نحو تسعة كيلومترات، كما تُعد أكبر الجماوات وأضخمها. وقد قامت عند سفحها قديماً عدة قصور على وادي العقيق، أشهرها قصر جعفر بن سليمان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408388-44307514.jpg?v=1637907942"]','https://cmsphoto.ww-cdn.com/resizeapi/024a1d13e80296275c3f1c6e25a94e12677b7e47/480/',24.477378,39.5298644,'Medina As Salam Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408388/jammaa-al-jumma-al-gharbiyah',1,0,'جماء جمه غربيه jammaa al jumma al gharbiyah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408370,'medina','حصن بني واقف','Hisn Bani Waqif','hisn-bani-waqif','["أماكن سياحية"]','["sights"]','حصن بني واقف بالمدينة المنورة، معلم أثري جنوب شرق مسجد قباء، نسبة لبني واقف من الأوس الذين صلى النبي ﷺ في حصنهم.','<div class="texte" > <p>&nbsp;حصن بني واقف او أطم بنى واقف الذي يقع جنوب شرق مسجد قباء بنحو 500 متر ورغم أنه من المعالم والآثار التاريخية في المدينة المنورة ولا يبعد عن المسجد النبوي سوى أربعة كيلومترات وأفاد الباحث محمد غالي الترجمي بأن بني واقف الذين سمي الحصن على اسمهم هم من الأوس من قبائل الأنصار الذين ناصروا الرسول صلى الله عليه وسلم مشيرا إلى أن الرسول عليه الصلاة والسلام صلى في حصنهم الذي يقع جنوب مسجد قباء ...</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408370-44345398.jpg?v=1638040588"]','https://cmsphoto.ww-cdn.com/resizeapi/983bb42cbec18b3f99bdeac6b66b5bcfd78c21f0/480/',24.4359922,39.6199487,'SA Al Khatim Medina','','','','https://www.saudi-guide.com/medina/i/59408370/hisn-bani-waqif',1,0,'حصن بني واقف hisn bani waqif اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408367,'medina','المسجد النبوي','Al Masjid an Nabawi','al-masjid-an-nabawi','["معالم إسلامية"]','["islamic"]','المسجد النبوي الشريف، ثاني أقدس مسجد عند المسلمين، يضم الروضة الشريفة والحجرة النبوية، مساحته تتجاوز 400 ألف متر مربع.','<div class="texte" > <p>المسجد النبوي الشريف ثاني أقدس مسجد عند المسلمين بعد المسجد الحرام بمكة المكرمة، ويقع في قلب المدينة المنورة. بناه النبي محمد ﷺ بنفسه عام الهجرة النبوية (622م) فور وصوله إلى المدينة، وكان في بداياته مسجدًا بسيطًا من الطين وجذوع النخل، ثم توالت عليه التوسعات عبر العصور من الخلفاء الراشدين مرورًا بالعصور الأموية والعباسية والعثمانية حتى العصر السعودي الذي شهد أكبر توسعاته لتصل مساحته الحالية إلى أكثر من 400 ألف متر مربع تستوعب أكثر من مليون مصلٍ. يضم المسجد الروضة الشريفة، وهي البقعة الواقعة بين منبر النبي ﷺ وحجرته الشريفة التي وصفها بأنها "روضة من رياض الجنة"، وتحتضن الحجرة النبوية قبر النبي محمد ﷺ وصاحبيه أبي بكر وعمر رضي الله عنهما. يتميز المسجد بقبته الخضراء الشهيرة ومآذنه العشر وبواباته الواسعة وقبابه ومظلاته المتحركة، ويُعد وجهة أساسية لكل حاج ومعتمر وزائر للمدينة المنورة على مدار العام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408367-44307313.jpg?v=1637906237"]','https://cmsphoto.ww-cdn.com/resizeapi/37840a0262fe9f0ede832e70fa8448b7f454a371/480/',24.467197,39.6111545,'Al Haram Medina Al Madinah Al Munawwarah','','https://visitmadinahsa.com/sa-ar/destinations/%D8%A7%D9%84%D9%85%D8%B3%D8%AC%D8%AF-%D8%A7%D9%84%D9%86%D8%A8%D9%88%D9%8A','','https://www.saudi-guide.com/medina/i/59408367/al-masjid-an-nabawi',1,0,'مسجد نبوي al masjid an nabawi معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408363,'medina','متحف السلام','Assalam Museum','assalam-museum','["التراث والثقافة"]','["heritage"]','متحف السلام بالمدينة المنورة، أحد أبرز المعالم الإسلامية، قريب من الحرم، يروي سيرة النبي ﷺ منذ ولادته بأسلوب بصري مميز.','<div class="texte" > <p>يعد متحف السلام أحد أبرز الأماكن إسلامية التي يمكن ان تزورها وتتعلم منها الكثير عن الدين وتاريخ الاسلام بشكل عام، وتاريخ النبي محمد عليه السلام بشكل خاص، يقع المتحف بالقرب من الحرم في المسجد النبوي، حيث انه مكان عليك الا تفوت فرصة زيارته اثناء تواجدك في المدينة المنورة. يحتوي المتحف على معرض تم تصويره بشكل جيد جدا، ويمكنك من التعرف على سيرة رسول الله منذ ولادته الى رحلته في نشر الاسلام، وانتهاء بوفاته. قم بزيارته انت وعائلتك واطفالك او اصدقاؤك، واعمل على اثراء معلوماتك الدينية</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408363-44346476.jpg?v=1638041021"]','https://cmsphoto.ww-cdn.com/resizeapi/4e9446b8d3a3d05ac2a1130b9b5c1942424be0ec/480/',24.4678403,39.6075971,'SA Al Haram Medina','','','','https://www.saudi-guide.com/medina/i/59408363/assalam-museum',1,0,'متحف سلام assalam museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408301,'medina','متحف المدينة المنورة','Al Madinah Museum','al-madinah-museum','["التراث والثقافة"]','["heritage"]','متحف المدينة المنورة الحكومي، يعرض تاريخ المدينة وتراثها من خلال حوالي 2000 قطعة أثرية، ويوثق تطور المسجد النبوي منذ منزل وفناء.','<div class="texte" > <p>متحف المدينة المنورة هو متحف حكومي يعرض تراث المدينة المنورة وتاريخها، ويضم مجموعات أثرية مختلفة وصالات عرض بصرية وصور نادرة تتعلق بالمدينة المنورة، كما يعرض حوالي 2000 قطعة أثرية نادرة تجسد تراث وثقافة المدينة المنورة وتوثق مناظرها الطبيعية وسكانها وكيف تم تشكيلها على مر السنين، وأحد أكثر الأجزاء إثارةً للاهتمام في الجولة حول المتحف هو تطور المسجد النبوي من منزل وفناء ومنزل إلى المجمع الضخم الذي هو عليه الآن.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408301-44348412.jpg?v=1638041782"]','https://cmsphoto.ww-cdn.com/resizeapi/846592f02ff729c4c21aeeddfc66ac2ad39da0d3/480/',24.4619371,39.6009011,'Omar Ibn Alkhtab Rd Al Suqya Medina','','','','https://www.saudi-guide.com/medina/i/59408301/al-madinah-museum',1,0,'متحف مدينه منوره al madinah museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408267,'medina','متحف حضارة طيبة','Taiba Civilization Museum','taiba-civilization-museum','["التراث والثقافة"]','["heritage"]','متحف حضارة طيبة بالمدينة المنورة، يضم مجموعة كبيرة من القطع التراثية ومكتبة تضم أهم الكتب في التاريخ والثقافة.','<div class="texte" > <p>يضم المتحف مجموعة كبيرة من القطع التراثية المهمة ، و يوجد بجوار المتحف في نفس الطابق مكتبة كبيرة تضم العديد من أهم الكتب في التاريخ و الثقافة ، و يعرض القطع بأسلوب رائع و علمي يجذب السياح إليه من خلال أضلاع خشبية من النوع القيم صممت علي شكل أجنحة صغيرة و خزانات زجاجية مما حظي علي اهتمام كبير من قبل الشيخ عبد العزيز عمر مكوار .</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408267-44350001.jpg?v=1638042602"]','https://cmsphoto.ww-cdn.com/resizeapi/b3acf7d76d004db8c6b721407115cbff9e7a5d60/480/',24.47549,39.6059328,'Al Masani Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408267/taiba-civilization-museum',1,0,'متحف حضاره طيبه taiba civilization museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408205,'medina','مجمع دار القلم','Dar Al Qalam Complex','dar-al-qalam-complex','["التراث والثقافة"]','["heritage"]','مجمع دار القلم بالمدينة المنورة، مركز ثقافي تعليمي بعمر يزيد على 80 عامًا، يضم معهدًا لتحفيظ القرآن ومكتبة تراثية ومسرحًا تاريخيًا.','<div class="texte" > <p>يحتوي المجمع على عدة مكونات تخدم أبناء المنطقة وزائريها، وهي مركز الخط العربي والمعرض الفني ومركز الصور والوثائق التعليمية، إضافةً إلى المسرح التاريخي ومركز إيثار للخدمات الكشفية والتطوعية.</p> <p>ويضم المجمع كذلك معهداً لتحفيظ القرآن الكريم، إضافةً إلى احتوائه على وثائق تاريخية خاصة بالتعليم في منطقة المدينة المنورة منذ أكثر من 80 عاماً، وصور قديمة للتعليم ومناسباته في المدينة، ومكتبة عامة تراثية وبعض التحف والمقتنيات الأثرية، وسجلات الملفات القديمة التي كانت تستخدم في أقسام إدارة التعليم والمدارس في المدينة المنورة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408205-44352544.jpg?v=1638043481"]','https://cmsphoto.ww-cdn.com/resizeapi/8c47c72562498774725b5bbe68d8d00005961c9f/480/',24.4630711,39.6018099,'FJ72+6PF Al Suqya Medina','','','','https://www.saudi-guide.com/medina/i/59408205/dar-al-qalam-complex',1,0,'مجمع دار قلم dar al qalam complex تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408199,'medina','متحف دار المدينة','Dar Al Madinah Museum','dar-al-madinah-museum','["التراث والثقافة"]','["heritage"]','متحف دار المدينة بالمدينة المنورة، أول وأكبر متحف متخصص في تاريخها وتراثها العمراني، يضم مقتنيات وصورًا نادرة.','<div class="texte" > <p>أول وأكبر متحف متخصص في تاريخ المدينة المنورة وتراثها العمراني والحضاري . يضيء المتحف صفحات ناصعة من تاريخ المدينة المنورة على صاحبها أفضل الصلاة والسلام ، ويكشف معالم إرثها وحضارتها الإسلامية وعبق تاريخها المجيد . يهدف المتحف إلى إثراء المعرفة في العلوم والأبحاث المتخصصة في تاريخ المدينة المنورة ويتميز باستعراضه لمجموعة كبيرة من المقتنيات والمجسمات التي تنقل صورة حية عن معالم تاريخ المدينة المنورة بالإضافة إلى مجموعة ضخمة من الصور النادرة لتاريخ المدينة المنورة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408199-44354553.jpg?v=1638044223"]','https://cmsphoto.ww-cdn.com/resizeapi/50f21e70d3c3b2f42c7e31bfb7642a2a2568fe39/480/',24.477161,39.6878556,'Safwan Ibn Malik Al Tamimi Al Mabuth Medina','','','','https://www.saudi-guide.com/medina/i/59408199/dar-al-madinah-museum',1,0,'متحف دار مدينه dar al madinah museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408138,'medina','قصر سعيد بن العاص','Saeed Ibn Al-Aas Palace','saeed-ibn-al-aas-palace','["معالم إسلامية"]','["islamic"]','قصر سعيد بن العاص بالمدينة المنورة، قصر أثري في وادي العقيق، بناه الصحابي سعيد بن العاص والي المدينة في خلافة معاوية.','<div class="texte" > <p>قصر سعيد بن العاص قصر أثري قديم يقع في وادي العقيق بالمدينة المنورة، بناه الصحابي سعيد بن العاص رضي الله عنه عندما كان واليًا للمدينة في خلافة معاوية بن أبي سفيان رضي الله عنه. عُرف سعيد بن العاص بعدله وحكمته في إدارة المدينة المنورة، وقد اهتم بتعمير المدينة وشق الطرق وبناء المساكن للناس فيها، وكان من الصحابة الذين اشتهروا بالكرم وحسن السياسة. لا تزال بقايا هذا القصر شاهدة على التاريخ العمراني لمنطقة وادي العقيق في العصر الأموي، ويُعد من المعالم الأثرية التي تجذب محبي التاريخ الإسلامي في المدينة المنورة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408138-44355062.jpg?v=1638044531"]','https://cmsphoto.ww-cdn.com/resizeapi/be9795da415c37ac00e30a4b9dcd269cef6706c3/480/',24.4865951,39.5676507,'FHP9+J3J Al Jamiah Medina','','','','https://www.saudi-guide.com/medina/i/59408138/saeed-ibn-al-aas-palace',1,0,'قصر سعيد بن عاص saeed ibn al aas palace معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408132,'medina','مسجد فاطمة الزهراء','Masjid Fatimah Alzahraa','masjid-fatimah-alzahraa','["معالم إسلامية"]','["islamic"]','مسجد فاطمة الزهراء بالمدينة المنورة، أصغر المساجد السبعة، يُعرف تاريخيًا بمسجد سعد بن معاذ رضي الله عنه.','<div class="texte" > <p>مسجد فاطمة الزهراء، ويُسمى في المصادر التاريخية مسجد سعد بن معاذ، هو أصغر المساجد السبعة بمساحة تبلغ نحو 12 مترًا مربعًا وله درجة صغيرة، وقد بُني وفق نمط عمارة المجموعة نفسها. يقع ضمن مجموعة المساجد السبعة الواقعة في منطقة الخندق شمال غرب المسجد النبوي، والتي تُحاكي مواقع مرابطة المسلمين وقيادتهم أثناء غزوة الخندق (الأحزاب) في السنة الخامسة للهجرة. ينسب المسجد إلى الصحابي الجليل سعد بن معاذ رضي الله عنه، سيد الأوس الذي كان له دور بارز في هذه الغزوة، ويُعد المسجد من المعالم الصغيرة التي يقصدها زوار المدينة المنورة لاستكمال زيارة المساجد السبعة التاريخية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408132-44357217.jpg?v=1638045351"]','https://cmsphoto.ww-cdn.com/resizeapi/65eb95728bcbb425a44f2f193a0d8e9275777f8a/480/',24.4758302,39.594996,'As Sih Al Fath Medina','','','','https://www.saudi-guide.com/medina/i/59408132/masjid-fatimah-alzahraa',1,0,'مسجد فاطمه زهراء masjid fatimah alzahraa معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408115,'medina','مسجد القبلتين','Masjid Al Qiblatayn','masjid-al-qiblatayn','["معالم إسلامية"]','["islamic"]','مسجد القبلتين بالمدينة المنورة، شهد تحول القبلة من المسجد الأقصى إلى المسجد الحرام، من أبرز المعالم التاريخية بعد المسجد النبوي وقباء.','<div class="texte" > <p>مسجد القبلتين، مسجد ذو مكانة في ذاكرة المسلمين على مستوى العالم، وله مكانته عند المهتمين بالتاريخ الإسلامي وكل من يزور المدينة المنورة، حيث صلى فيه الرسول صلى الله عليه وسلم، وشهد تحوّل القبلة من المسجد الأقصى إلى المسجد الحرام، إضافة إلى أنه مثبت في السنة من خلال الأحاديث النبوية، ومسجل في ذاكرة التاريخ الإسلامي باعتباره أحد أهم وأبرز المعالم التاريخية ومن أعظم الآثار النبوية في المدينة المنورة بعد المسجد النبوي ومسجد قباء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408115-44357921.jpg?v=1638045578"]','https://cmsphoto.ww-cdn.com/resizeapi/6e6ee894d25cdad013a7c885561338e87f18b36b/480/',24.4841397,39.5793008,'مسجد Khalid Ibn Al Walid Rd Al Qiblatayn','','','','https://www.saudi-guide.com/medina/i/59408115/masjid-al-qiblatayn',1,0,'مسجد قبلتين masjid al qiblatayn معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408095,'medina','قصر عروة بن الزبير','Arwa Bin Al Zubair Castle','arwa-bin-al-zubair-castle','["معالم إسلامية"]','["islamic"]','قصر عروة بن الزبير بالمدينة المنورة، معلم أثري على ضفاف وادي العقيق، أمر عمر بن عبدالعزيز ببنائه تكليفًا للتابعي عروة بن الزبير.','<div class="texte" > <p>يقع قصر عروة بن الزبير على ضفاف وادي العقيق في غرب المدينة المنورة، على امتداد الطريق المؤدي إلى مسجد الميقات (ميقات أهل المدينة)، ويبعد عن المسجد النبوي حوالي 3.5 كم. أمر عمر بن عبدالعزيز رضي الله عنه ببناء هذا القصر تكليفًا من عروة بن الزبير، أحد كبار فقهاء التابعين وأبناء الصحابي الزبير بن العوام رضي الله عنه، والمعروف بعلمه الواسع في الفقه والحديث والسيرة النبوية. لا تزال بعض مباني القصر قائمة حتى اليوم، وتُعد من المعالم الأثرية المهمة التي تعكس طراز العمارة في العصر الأموي، وتجذب محبي التاريخ والآثار الإسلامية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408095-44358127.jpg?v=1638045911"]','https://cmsphoto.ww-cdn.com/resizeapi/dcaf2650b696e8b26aab21b81830b4c5f127f0f0/480/',24.45039,39.5816615,'3521 Umar Ibn Al Khattab Rd Urwah','','','','https://www.saudi-guide.com/medina/i/59408095/arwa-bin-al-zubair-castle',1,0,'قصر عروه بن زبير arwa bin al zubair castle معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408092,'medina','مسجد عمر بن الخطاب','Masjid Umar Ibn Al Khattab','masjid-umar-ibn-al-khattab','["معالم إسلامية"]','["islamic"]','مسجد عمر بن الخطاب بالمدينة المنورة، يقع على طريق قباء بين المسجد النبوي ومسجد قباء، بالقرب من مسجد الغمامة.','<div class="texte" > <p>يقع المسجد في الجهة الجنوبية الغربية من المسجد النبوي، ويبعد عن مبنى التوسعة 455 متراً، كما يبعد عن مسجد الغمامة قرابة 133 متراً. يوجد هذا المسجد عند تقاطع شارع قباء مع شارع العنبرية، وعلى يسار المتجه من المدينة المنورة إلى قباء، ويطل مسجد عمر من الناحية الغربية على طريق قباء، بينما يطل من الناحية الشمالية على ميدان مسجد الغمامة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408092-44358161.jpg?v=1638046400"]','https://cmsphoto.ww-cdn.com/resizeapi/b4c69306c970a403853362b7dfa3af7cda8ab4e4/480/',24.4765165,39.5951611,'Al Fath Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408092/masjid-umar-ibn-al-khattab',1,0,'مسجد عمر بن خطاب masjid umar ibn al khattab معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408091,'medina','مسجد سلمان الفارسي','Masjid Salman Al Farsi','masjid-salman-al-farsi','["معالم إسلامية"]','["islamic"]','مسجد سلمان الفارسي بالمدينة المنورة، ثاني المساجد السبعة في منطقة الخندق، نُسب للصحابي سلمان الفارسي صاحب فكرة حفر الخندق.','<div class="texte" > <p>مسجد سلمان الفارسي رضي الله عنه أحد مساجد رسول الله ﷺ ومصلياته في المدينة المنورة على التحقيق، وهو ثاني المساجد السبعة الواقعة في منطقة الخندق شمال غرب المسجد النبوي. نُسب المسجد إلى الصحابي الجليل سلمان الفارسي رضي الله عنه، صاحب فكرة حفر الخندق التي أشار بها على النبي ﷺ لحماية المدينة من غزو الأحزاب في السنة الخامسة للهجرة. يقع المسجد ضمن مجموعة المساجد السبعة التي تحاكي مواقع القيادة والمرابطة للمسلمين أثناء غزوة الخندق، ويُعد من المعالم التي يقصدها زوار المدينة المنورة لمعرفة قصة هذه الغزوة الخالدة ودور الصحابة فيها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408091-44358200.jpg?v=1638046823"]','https://cmsphoto.ww-cdn.com/resizeapi/7c5c6e63960afd82fc9ae118ec0590fba85a1258/480/',24.4774493,39.5955791,'Al Fath Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408091/masjid-salman-al-farsi',1,0,'مسجد سلمان فارسي masjid salman al farsi معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408059,'medina','مسجد الفتح','Masjid Al Fath','masjid-al-fath','["معالم إسلامية"]','["islamic"]','مسجد الفتح بالمدينة المنورة، على سفح جبل سلع، موقع خيمة النبي ﷺ يوم غزوة الخندق، ويُعرف أيضًا بمسجد الأحزاب.','<div class="texte" > <p>يقع مسجد الفتح على سفح جبل سلع غربي المسجد النبوي، حيث ضُربت خيمة النبي ﷺ يوم غزوة الخندق (الأحزاب)، وبالقرب منه مقبرة شهداء الخندق. سُمي بالفتح لما تحقق من فتح للمسلمين بعد الغزوة، ويُسمى أيضًا مسجد الأحزاب لدعاء النبي ﷺ على الأحزاب فيه، كما يُعرف بالمسجد الأعلى لارتفاعه عن المساجد المحيطة به.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408059-44361506.jpg?v=1638083239"]','https://cmsphoto.ww-cdn.com/resizeapi/c84181e4faa6d33898a17a9b20ccda39391298ce/480/',24.4778525,39.5955776,'Al Fath Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408059/masjid-al-fath',1,0,'مسجد فتح masjid al fath معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408058,'medina','مسجد السقيا','Masjid Al Suqya','masjid-suqya','["معالم إسلامية"]','["islamic"]','مسجد السقيا بالمدينة المنورة، مسجد سُمي نسبة لبئر السقيا التي توضأ منها النبي ﷺ متوجهًا لغزوة بدر الكبرى.','<div class="texte" > <p>مسجد السقيا مسجد صغير تعلوه 3 قباب، يقع على مساحة 56 مترًا بلا مئذنة، وتصميم بنائه عثماني. سُمي بهذا الاسم نسبة لقربه من بئر السقيا، البئر التي رُوي أن النبي ﷺ توضأ منها وهو متوجه إلى غزوة بدر الكبرى، وصلّى بالقرب منها ودعا لأهل المدينة، ثم بنى عمر بن عبدالعزيز رضي الله عنه في ولايته على المدينة مسجدًا في موضع صلاته ﷺ. أُعيد ترميم المسجد في عهد خادم الحرمين الشريفين الملك فهد بن عبدالعزيز في الفترة 1423-1424هـ، ضمن مشروعات العناية بالمساجد التاريخية والأثرية في المدينة المنورة، ليبقى شاهدًا على هذه المحطة من السيرة النبوية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408058-44361510.jpg?v=1638083297"]','https://cmsphoto.ww-cdn.com/resizeapi/7aad630314814aa74efc708a3ab1254da35c4274/480/',24.4608561,39.6001903,'Al Suqya Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59408058/masjid-suqya',1,0,'مسجد سقيا masjid al suqya معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408057,'medina','مسجد بني غفار','Masjid Bani Ghifar','masjid-bani-ghifar','["معالم إسلامية"]','["islamic"]','مسجد بني غفار بالمدينة المنورة، مسجد أثري مأثور صلى فيه النبي ﷺ، يُعرف أيضًا بكهف بني حرام الكبير.','<div class="texte" > <p>مسجد بني غفار من المساجد الأثرية المأثورة التي وردت الروايات بأن النبي ﷺ صلّى فيها، ويُعرف أيضًا بكهف بني حرام الكبير. تنتسب تسميته إلى قبيلة غفار، وهي إحدى قبائل كنانة التي أسلم كثير من أفرادها مبكرًا واستوطنوا هذه المنطقة من المدينة المنورة. يُعد المسجد شاهدًا على ارتباط النبي ﷺ بمختلف الأحياء والقبائل التي سكنت المدينة، حيث كان يزورها ويصلي فيها تعزيزًا للأخوة الإسلامية بين المهاجرين والأنصار والقبائل المسلمة. لا يزال المسجد قائمًا حتى اليوم كأحد المعالم الأثرية الصغيرة التي يقصدها محبو التاريخ الإسلامي والسيرة النبوية في المدينة المنورة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408057-44361527.jpg?v=1638083671"]','https://cmsphoto.ww-cdn.com/resizeapi/056b9290a69e85df3da179f1049548524a9852b8/480/',24.471863,39.6025299,'4116 1st Ring Branch Rd الفتح','','','','https://www.saudi-guide.com/medina/i/59408057/masjid-bani-ghifar',1,0,'مسجد بني غفار masjid bani ghifar معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408054,'medina','مسجد العنبرية','Anbariya Mosque','anbariya-mosque','["معالم إسلامية"]','["islamic"]','مسجد العنبرية بالمدينة المنورة، يقع غرب الحرم النبوي بالقرب من محطة سكة الحجاز، محاط بحديقة دائرية بطراز عثماني أصيل.','<div class="texte" > <p>يقع مسجد العنبرية غرب الحرم النبوي الشريف بالقرب من محطة سكة الحديد الحجاز التي كانت في العهد العثماني، ويبعد عنه بنحو 500 متر بواجهة شمالية. والمسجد محاط بحديقة دائرية تضفي عليه روعة وجمالاً لتظهر مبانيه الأثرية التي شيدت في عهد الدولة العثمانية بالحجر المنحوت بروعة ودقة الفن المعماري.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408054-44361559.jpg?v=1638083884"]','https://cmsphoto.ww-cdn.com/resizeapi/03d7090001b8b8626ee42a53d058658380f352ca/480/',24.461521,39.601645,'SA Al Suqya Medina','','','','https://www.saudi-guide.com/medina/i/59408054/anbariya-mosque',1,0,'مسجد عنبريه anbariya mosque معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59408028,'medina','مسجد أبو بكر الصديق','Masjid Abu Bakr Al Siddiq','masjid-abu-bakr-al-siddiq','["معالم إسلامية"]','["islamic"]','مسجد أبو بكر الصديق بالمدينة المنورة، مسجد تاريخي بُني عام 1245هـ، يتميز بجداره الشرقي الأسود ذي القبة البيضاء.','<div class="texte" > <p>واحد من المساجد التاريخية والأثرية في المدينة إذ تم بناؤه في عام 1245 هجري، وهو من المساجد التي لا تزال تحافظ على نمطها العتيق وتصميمها التقليدي حيث يمكنك ملاحظة الجدار الشرقي الاسود الذي يبدو مبهراً مع لون القبة البيضاء ليشكل مزيج استثنائي ملفت للنظر، وهو من المساجد الصغيرة إذ تبغ مساحته حوالي 81 متر مربع، ويستقبل المصليين يومياً، كما أن الزوار يصطفون في الخارج لأخذ الصور التذكارية الجميلة نظراً لكونه تحفة معمارية وفنية مبهرة.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59408028-44361593.jpg?v=1638084035"]','https://cmsphoto.ww-cdn.com/resizeapi/d350cd322a98ec99c89d9ceced25c8cd048b6d90/480/',24.4811786,39.5784365,'4980 عبدالرحمن بن خارف، Al Qiblatayn','','','','https://www.saudi-guide.com/medina/i/59408028/masjid-abu-bakr-al-siddiq',1,0,'مسجد ابو بكر صديق masjid abu bakr al siddiq معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407997,'medina','مسجد الغمامة','Masjid Al Ghamamah','masjid-al-ghamamah','["معالم إسلامية"]','["islamic"]','مسجد الغمامة بالمدينة المنورة، آخر المواضع التي صلى بها النبي ﷺ صلاة العيد، يبعد نحو 500 متر عن المسجد النبوي.','<div class="texte" > <p>يحرص زائرو المدينة المنورة، على زيارة مسجد الغمامة والصلاة فيه، إذ كان آخر المواضع التي صلى بها الرسول (صلى الله عليه وسلم) صلاة العيد، وسمي «الغمامة» لما يقال من أن غمامة حجبت الشمس عن رسول الله (صلى الله عليه وسلم) عند صلاته. كما صلى فيه صلاة الغائب على النجاشي.<br /> <br /> ويبعد عن المسجد النبوي الشريف نحو 500 متر فقط، من الناحية الجنوبية الغربية من المسجد النبوي. ويكثر زواره هذه الأيام لمشاهدة ما يحويه من موروث حضاري قديم، ومعالم وذكرى ارتبطت بالسيرة النبوية.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407997-44361604.jpg?v=1638084184"]','https://cmsphoto.ww-cdn.com/resizeapi/30da493ed61d925433debd0f97a009074be2b5ac/480/',24.4658851,39.6069604,'Al Haram Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59407997/masjid-al-ghamamah',1,0,'مسجد غمامه masjid al ghamamah معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407899,'medina','بقيع الغرقد','Al-Baqi Cemetery','al-baqi-cemetery','["معالم إسلامية"]','["islamic"]','بقيع الغرقد بالمدينة المنورة، أشهر المقابر في الإسلام، دفن فيه العديد من الصحابة وأمهات المؤمنين، منهم عثمان بن عفان رضي الله عنه.','<div class="texte" > <p>بقيع الغرقد أشهر المقابر في العالم الإسلامي، وتُعد المقبرة الرئيسية لأهل المدينة المنورة منذ عهد النبي محمد ﷺ حتى يومنا هذا. سُمي بهذا الاسم نسبة لشجر الغرقد الذي كان ينبت فيه قديمًا. دُفن فيه عدد كبير من الصحابة رضي الله عنهم، ومن أبرزهم عثمان بن عفان رضي الله عنه، وأمهات المؤمنين، وعمّات النبي ﷺ وبناته، وعمه العباس بن عبدالمطلب، بالإضافة إلى آلاف من التابعين والعلماء والصالحين عبر العصور المتعاقبة. رُوي أن النبي ﷺ كان يزور البقيع ويدعو لأهله بالمغفرة، وكان يقول: "السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون". يتميز البقيع بطابعه البسيط الخالي من الزخرفة اتباعًا للسنة النبوية في التسوية بالقبور، ويقع بجوار المسجد النبوي الشريف من الجهة الجنوبية الشرقية، ويُسمح للزوار بزيارته في أوقات محددة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407899-44361624.jpg?v=1638084348"]','https://cmsphoto.ww-cdn.com/resizeapi/91db59330e3ee43e4922368883e7566ab051ade9/480/',24.4672192,39.6138277,'ممر مشاة Al Haram Medina','','','','https://www.saudi-guide.com/medina/i/59407899/al-baqi-cemetery',1,0,'بقيع غرقد al baqi cemetery معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407895,'medina','مسجد الإجابة','Masjid Al Ijaba','masjid-al-ijaba','["معالم إسلامية"]','["islamic"]','مسجد الإجابة بالمدينة المنورة، سُمي بذلك لاستجابة دعاء النبي ﷺ فيه، يقع شمال البقيع في طريق الملك فيصل.','<div class="texte" > <p>مسجد الإجابة، ويُعرف أيضًا بمسجد بني معاوية، يقع في الجهة الشمالية الشرقية من المسجد النبوي الشريف، على بُعد نحو 385 مترًا شمال البقيع في طريق الملك فيصل. سُمي بهذا الاسم لأن دعاء النبي ﷺ فيه استُجيب، إذ رُوي أنه ﷺ صلّى فيه ودعا بثلاث دعوات؛ سأل ربه ألا يُهلك أمته بالسنة (القحط والجدب)، وألا يُسلّط عليهم عدوًا من غير أنفسهم فيستبيح بيضتهم، وألا يجعل بأسهم بينهم، فاستُجيبت له الدعوتان الأوليان ولم تُستجب الثالثة. لهذا حرص المسلمون عبر العصور على التبرك بزيارته والصلاة فيه، وحظي على مر التاريخ باهتمام الولاة والحكام الذين رمموه وحافظوا على بنائه، ولا يزال حتى اليوم من المعالم التي يقصدها زوار المدينة المنورة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407895-44361645.jpg?v=1638084562"]','https://cmsphoto.ww-cdn.com/resizeapi/18b50c63f1c4e7df7b2887085558827177340905/480/',24.4719274,39.6184227,'FJC9+Q9F Bani Muawiyah Medina','','','','https://www.saudi-guide.com/medina/i/59407895/masjid-al-ijaba',1,0,'مسجد اجابه masjid al ijaba معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407890,'medina','مسجد قباء','Masjid Quba','masjid-quba','["معالم إسلامية"]','["islamic"]','مسجد قباء بالمدينة المنورة، أول مسجد أسسه الرسول صلى الله عليه وسلم عندما وصل إلى المدينة مهاجرًا من مكة، من أبرز المساجد الأثرية في الإسلام.','<div class="texte" > <p>يعتبر مسجد قباء في المدينة المنورة أول مسجد أسسه الرسول صلى الله عليه وسلم عندما وصل إلى المدينة المنورة مُهاجراً إليها من مكة المكرمة، وشارك في وضع أحجاره الأولى ثم أكمله الصحابة.</p> <p>وكان الرسول الكريم يقصده بين الحين والآخر ليصلي فيه ويختار أيام السبت غالباً ويحض على زيارته، وجاء في الحديث الشريف: "من تطهر في بيته ثم أتى مسجد قباء فصلى فيه صلاة كان له كأجر عمرة".</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407890-63567953.jpg?v=1753138115"]','https://cmsphoto.ww-cdn.com/resizeapi/f9d6f48e15c6b1af23e4227b237de88479d183b8/480/',24.4392471,39.6172886,'3493 Al Hijrah Rd Al Khatim','','https://qubaa.mda.gov.sa/quba%20features.html','','https://www.saudi-guide.com/medina/i/59407890/masjid-quba',1,0,'مسجد قباء masjid quba معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407888,'medina','جبل الرماة','Jabal Al Rumat','jabal-al-rumat','["معالم إسلامية"]','["islamic"]','جبل الرماة بالمدينة المنورة، موقع الرماة الخمسين في غزوة أحد بقيادة عبدالله بن جبير، يُعرف أيضًا بجبل عينين.','<div class="texte" > <p>جبل الرماة أحد أهم المعالم التاريخية التي يحرص المتتبعون لسيرة النبي ﷺ على زيارتها، ويُعرف أيضًا بجبل "عينين". يقع في الجهة الجنوبية من جبل أحد، ويحده من الجهة الجنوبية وادي قناة. اكتسب الجبل أهميته التاريخية العظيمة لأن النبي ﷺ أمر فيه خمسين من الرماة بقيادة عبدالله بن جبير رضي الله عنه بالبقاء في مواقعهم لحماية ظهور المسلمين أثناء غزوة أحد، وعدم مبارحة الجبل مهما حدث. لكن حين ظنوا أن النصر تحقق، ترك أغلب الرماة مواقعهم لجمع الغنائم، فاستغل خالد بن الوليد -قبل إسلامه- هذه الثغرة والتف بجيش المشركين من خلفهم، فانقلبت موازين المعركة وأصيب المسلمون بخسائر فادحة. يُعد الجبل اليوم من أبرز المعالم التي تُروى فيها هذه العبرة الخالدة عن أهمية الالتزام بأوامر القيادة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407888-44361688.jpg?v=1638085117"]','https://cmsphoto.ww-cdn.com/resizeapi/816ff9f071a2938e14585056c940f60039e5aea0/480/',24.5020717,39.6122843,'جبل الرماة سيد الشهداء المدينة المنورة','','','','https://www.saudi-guide.com/medina/i/59407888/jabal-al-rumat',1,0,'جبل رماه jabal al rumat معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407886,'medina','جبل أحد','Uhud Mountain','uhud-mountain','["معالم إسلامية"]','["islamic"]','جبل أحد بالمدينة المنورة، شهد غزوة أحد الشهيرة، ووصفه النبي ﷺ بقوله أحد جبل يحبنا ونحبه.','<div class="texte" > <p>جبل أحد من أشهر الجبال التاريخية عند المسلمين، يطل شامخًا على المدينة المنورة من الجهة الشمالية بطول نحو سبعة كيلومترات وعرض يتراوح بين 2 إلى 3 كيلومترات، ويصل ارتفاعه إلى 350 مترًا. اكتسب الجبل مكانته العظيمة لأنه شهد غزوة أحد الشهيرة في السنة الثالثة للهجرة، وهي إحدى أهم الغزوات في السيرة النبوية بعد غزوة بدر، حيث قاتل المسلمون بقيادة النبي ﷺ جيش قريش عند سفحه، واستشهد فيها سبعون من الصحابة في مقدمتهم حمزة بن عبدالمطلب عم النبي ﷺ سيد الشهداء. ورد في الحديث الشريف أن النبي ﷺ قال عن هذا الجبل: "أُحُد جبل يحبنا ونحبه"، وهي من العبارات النبوية التي تُبرز مكانته الخاصة. يُعد الجبل اليوم من أبرز الوجهات التي يقصدها زوار المدينة المنورة لمعرفة قصة الغزوة والوقوف على مقبرة الشهداء القريبة منه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407886-44361693.jpg?v=1638085172"]','https://cmsphoto.ww-cdn.com/resizeapi/47115daa1646e65c92d75c8365d37c2bb7e1f60b/480/',24.5217701,39.6260059,'Uhud Mountain Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59407886/uhud-mountain',1,0,'جبل احد uhud mountain معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407666,'medina','الحكير تايم','Alhokair Time','alhokair-time','["أماكن سياحية"]','["sights"]','مدينة ملاهي عائلية في حي القصواء بالمدينة المنورة، تضم ألعابًا كهربائية وصالة ألعاب فيديو تناسب جميع الأعمار، مفتوحة يوميًا من الثانية ظهرًا حتى الحادية عشرة ليلاً.','<div class="texte" > <p>تقع مدينة الحكير تايم الترفيهية في حي القصواء بالمدينة المنورة، وتُعد من أبرز الوجهات الترفيهية العائلية بالمدينة، إذ افتُتحت ضمن سلسلة مدن الملاهي التابعة لمجموعة الحكير عام 2001م.</p> <p>تضم المدينة مجموعة متنوعة من الألعاب الكهربائية والحركية التي تناسب مختلف الأعمار وخاصة الأطفال، إضافة إلى صالة واسعة لألعاب الفيديو والتسلية. تفتح أبوابها يوميًا من الساعة الثانية ظهرًا حتى الحادية عشرة مساءً، وتقدّم تجربة ترفيهية متكاملة لقضاء أمسية ممتعة مع الأسرة بعيدًا عن صخب المعالم الدينية، ويُنصح بزيارتها في المساء لتجنّب ازدحام النهار والاستمتاع بالأجواء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407666-44361722.jpg?v=1638085399"]','https://cmsphoto.ww-cdn.com/resizeapi/74cf90ab6a9e3b904e6f1e38b52e125bb2c511be/480/',24.427628,39.58509,'CHGP+X2 7017 الامير سلطان بن عبدالعزيز الفرعي','','','','https://www.saudi-guide.com/medina/i/59407666/alhokair-time',1,0,'حكير تايم alhokair time اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407635,'medina','وادي العقيق','Wadi Al-Aqiq','wadi-al-aqiq','["أماكن سياحية"]','["sights"]','وادي العقيق بالمدينة المنورة، أشهر أودية المدينة، تدل الكتب التاريخية على أنه كان أشبه بنهر دائم الجريان من البساتين والمساكن.','<div class="texte" > <p>يعد وادي العقيق أشهر أودية المدينة المنورة وشاهدا على تاريخها وعلى السيرة النبوية، وتدل الكتابات التاريخية على أن الوادي كان أشبه بنهر دائم الجريان، إذ قام على ضفافه قديما عديد من البساتين والمساكن، ولا سيما في العصرين الأموي والعباسي، ومنها أطلال قصري سعد بن أبي وقاص، وعروة بن الزبير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407635-44361735.jpg?v=1638085573"]','https://cmsphoto.ww-cdn.com/resizeapi/555bf873024c5bbc06fab5576ba8f330869d1e4f/480/',24.4103711,39.5427769,'SA Abu Kabir Medina','','https://visitmadinahsa.com/sa-ar/destinations/%D9%88%D8%A7%D8%AF%D9%8A-%D8%A7%D9%84%D8%B9%D9%82%D9%8A%D9%82','','https://www.saudi-guide.com/medina/i/59407635/wadi-al-aqiq',1,0,'وادي عقيق wadi al aqiq اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407631,'medina','مجمع الملك فهد لطباعة المصحف الشريف','King Fahd Quran Printing Complex','king-fahd-quran-printing-complex','["أماكن سياحية"]','["sights"]','مجمع الملك فهد لطباعة المصحف الشريف، أكبر مطبعة للمصاحف في العالم بمساحة 250 ألف متر مربع، يزوره سنويًا نحو مليوني زائر.','<div class="texte" > <p>يصنف مجمع الملك فهد لطباعة المصحف الشريف في المدينة المنورة كأكبر مطبعة للمصاحف في العالم، حيث تبلغ مساحته 250.000 متر مربع ، ويعتبر واحد من أبرز وأهم الاماكن السياحيه في المدينة المنورة إذ يزوره سنويا ما يقارب الـ 2 مليون زائر من مختلف البلاد والجنسيات معظمهم من المعتمرين والحجاج.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407631-44361756.jpg?v=1638085636"]','https://cmsphoto.ww-cdn.com/resizeapi/a2752cbdb787126eb0be915304bfcc295953bb23/480/',24.5149461,39.5404561,'طريق تبوك الفرعي، An Nakhil Medina','','','','https://www.saudi-guide.com/medina/i/59407631/king-fahd-quran-printing-complex',1,0,'مجمع ملك فهد لطباعه مصحف شريف king fahd quran printing complex اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407625,'medina','ارياف طيبة','Aryaf Taibah','aryaf-taibah','["أماكن سياحية"]','["sights"]','منتزه ومزرعة ارياف طيبة بالمدينة المنورة، موقع عائلي وموقع جذب سياحي يضم جلسات ومطاعم ومقاهي وألعاب أطفال ومتاجر للتمور والأدوات اليدوية.','<div class="texte" > <p>يعتبر منتزه مزرعة ارياف طيبة متنزهاً عائلياً وموقع جذب سياحي، وهو أحد أفضل منتزهات المدينة المنورة وأماكن السياحة في السعودية، يقدم العديد من الخدمات لزواره، كما يحتوي على أماكن مخصصة للجلسات العائلية ومطاعم وكافيهات وألعاب أطفال ومتاجر لبيع التمور والأدوات المصنوعة يدوياً بالمدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407625-44361776.jpg?v=1638086210"]','https://cmsphoto.ww-cdn.com/resizeapi/d63cf6623f821497d9953e7fed3a2cf7dea303bd/480/',24.500434,39.596023,'SA Al''uyun Medina','','','','https://www.saudi-guide.com/medina/i/59407625/aryaf-taibah',1,0,'ارياف طيبه aryaf taibah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407618,'medina','حديقة الأمير محمد بن عبدالعزيز','Prince Mohammed bin Abdul Aziz Park','prince-mohammed-bin-abdulaziz-park','["أماكن سياحية"]','["sights"]','حديقة الأمير محمد بن عبدالعزيز، تقع على جبل أحد التاريخي بموقع مرتفع يطل على المدينة المنورة، تضم مسطحات خضراء وأماكن جلوس مميزة لمشاهدة الغروب خاصة.','<div class="texte" > <p>حديقة الأمير محمد بن عبدالعزيز تعتبر من أجمل الحدائق الموجودة في المدينة المنورة لأنها تتمتع بموقع متميز، و هي تقع علي جبل أحد التاريخي بالإضافة إلى أنها تقع على الطريق الدائري المعروف، و تتميز حديقة الأمير محمد بن عبدالعزيز أنها توفر إطلالة جميلة و ذلك بسبب ارتفاعها المتميز لوقوعها على الجبل. و من خلال زيارتك لهذه الحديقة المميزة سوف ترى جمال و روعة المدينة المنورة و خصوصاً في المساء؛ و يوجد في الحديقة أيضاً مسطحات خضراء كثيرة و أماكن رائعة للجلوس على الجبل لذلك تعد مقصداً لأهالي المدينة المنورة.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407618-44361784.jpg?v=1638086340"]','https://cmsphoto.ww-cdn.com/resizeapi/3b3363df9c984e20059cccf10a0c620e8b40ffcb/480/',24.5347607,39.5953415,'طريق عثمان بن عفان، Jabal Auhud Medina','','','','https://www.saudi-guide.com/medina/i/59407618/prince-mohammed-bin-abdulaziz-park',1,0,'حديقه امير محمد بن عبدالعزيز prince mohammed bin abdul aziz park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407590,'medina','حديقة الملك فهد','King Fahd Central Park','king-fahd-central-park','["أماكن سياحية"]','["sights"]','حديقة الملك فهد المركزية، من أكبر متنزهات المدينة المنورة بمساحة 4.5 كيلومتر مربع، على بعد خمس كيلومترات من المسجد النبوي، تضم مساحات خضراء ومناطق للعائلات وملاعب الشباب.','<div class="texte" > <p>حديقة الملك فهد المركزية هي واحدة من بين أجمل ست منتزهات في المدينة المنورة كما أنها قريبة جداً من المسجد النبوي حيث تبعد خمسة كيلومترات عن جنوب الحرم النبوي؛ تمتاز حديقة الملك فهد بأشجارها الكثيفة العالية و المزروعة على أفضل تنسيق و تتوافر أماكن الجلوس وسط المناظر الخلابة و الخضرة البديعة حيث تحتل الحديقة مساحة 4.5 كيلومتراً مربعاً. و تنقسم الحديقة إلى عدة أقسام؛ فهناك قسم مخصص للعائلات و قسم مخصص للبحيرة الصناعية و الجبال المحيطة بها و قسم آخر لملاعب الشباب توجد به منطقة لركوب الخيل و الجمال و منطقة للمزارع و البساتين البديعة حيث أشجار النخيل ممتدة على مدى البصر؛ و أخيراً و ليس آخراً قسم مخصص لألعاب الأطفال من مختلف الأعمار؛ فلا تفوت زيارة هذه الحديقة الجميلة الحافلة بالمميزات.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407590-44361800.jpg?v=1638086612"]','https://cmsphoto.ww-cdn.com/resizeapi/c1523106137b7460c87ea8432a53294926a655e1/480/',24.4200407,39.6061752,'Al Hadiqah Medina Al Madinah Al Munawwarah','','','','https://www.saudi-guide.com/medina/i/59407590/king-fahd-central-park',1,0,'حديقه ملك فهد king fahd central park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407562,'medina','مزرعة الأوسية التاريخية','Al Awsiyah Historical Farm','al-awsiyah-historical-farm','["أماكن سياحية"]','["sights"]','مزرعة الأوسية التاريخية شرق مسجد قباء، تحكي تاريخًا عظيمًا لمدينة الرسول صلى الله عليه وسلم، وتمتد جذورها للصحابي هلال بن أمية الأسلمي رضي الله عنه.','<div class="texte" > <p>تقع مزرعة الأوسية التاريخية مباشرة شرق مسجد قباء بالمدينة المنورة، وتحمل قيمة تاريخية عريقة إذ تمتد جذورها إلى الصحابي الجليل هلال بن أمية الأوسي رضي الله عنه، أحد الثلاثة الذين خُلّفوا وتاب الله عليهم.</p> <p>تجمع المزرعة بين الطابع الزراعي التقليدي والقيمة التاريخية، حيث تحيط بها أشجار النخيل الباسقة على الطراز الذي عُرفت به ضواحي المدينة المنورة قديمًا. تبعد المزرعة خطوات قليلة عن مسجد قباء، ما يجعلها محطة مناسبة يضيفها الزوار إلى برنامج زيارتهم لمسجد قباء والمسجد النبوي الشريف، خاصة عند التجول في أحياء العوالي شرق المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407562-44361808.jpg?v=1638086720"]','https://cmsphoto.ww-cdn.com/resizeapi/1e9008b4f88f654f02a5fa3be5e525f0fc03f604/480/',24.4402338,39.620575,'طارق بن عبدالرحمن البجلي، Al Khatim Medina','','','','https://www.saudi-guide.com/medina/i/59407562/al-awsiyah-historical-farm',1,0,'مزرعه اوسيه تاريخيه al awsiyah historical farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407503,'medina','بلاد السهلة للسياحة','Blad Al-Sahlah for Tourism','blad-al-sahlah','["أماكن سياحية"]','["sights"]','مزرعة سياحية بالمدينة المنورة تقدم الفطور والغداء والعشاء، وتبيع التمر والنعناع والورد والمنتجات المدينية الطازجة.','<div class="texte" > <p>مزرعه سياحية لأهل المدينة وزوارها تقدم الفطور والغدا والعشا والقهوة وايضاً بالإمكان شراء التمر والنعناع والورد والمنتوجات المدينية</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407503-44361826.jpg?v=1638087072"]','https://cmsphoto.ww-cdn.com/resizeapi/7a51dc9cd2e42c143763901716590bfaddb96c8b/480/',24.4311772,39.6313773,'CJJJ+FHC Al Khatim Medina','','','','https://www.saudi-guide.com/medina/i/59407503/blad-al-sahlah',1,0,'بلاد سهله للسياحه blad al sahlah for tourism اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407485,'medina','جادة قباء','Jadat Quba','jadat-quba','["أماكن سياحية"]','["sights"]','جادة قباء، سوق شعبي بالمدينة المنورة يرتاده زوارها من مختلف دول العالم، يتميز بطرازه المعماري التراثي ومنتجاته المتنوعة من مختلف الأركان.','<div class="texte" > <p>يرتاد أهالي وزوار المدينة المنورة من مختلف دول العالم سوق "جادة قباء" الذي يتميز بموقعه الحيوي وسط الأحياء القديمة ومنتجاته المتنوعة التي تعج في العديد من الأركان المختلفة، ويتوسطه طريق مشاة ومجموعة من الفنادق والأبراج السكنية وعدد من المجسمات المنحوتة. كما يتميز بالطراز المعماري الذي يُحاكي البيئة والتراث المدني.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407485-44361833.jpg?v=1638087206"]','https://cmsphoto.ww-cdn.com/resizeapi/e8fa35a59c25028e469ed38dd07085dd3c97753a/480/',24.4618773,39.607452,'جادة قباء Al Jumuah Medina','','','','https://www.saudi-guide.com/medina/i/59407485/jadat-quba',1,0,'جاده قباء jadat quba اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59407484,'medina','منتزه الفُلك البحري','Muntazih Alfulk Albahrii','muntazih-alfulk-albahrii','["أماكن سياحية"]','["sights"]','منتزه ومطعم وألعاب الفُلك البحري بالمدينة المنورة، وجهة ترفيهية عائلية تجمع بين المطعم وألعاب الأطفال والمساحات الخضراء، خيار محبب لقضاء أجمل الأوقات.','<div class="texte" > <p>يقع منتزه ومطعم وألعاب الفُلك البحري في المدينة المنورة وهو أحد فروع مجموعة القصواء للأعمال التجارية . قامت فكرة إنشاء الفُلك البحري على توفير مكان مميز يُقدم مجموعة خدمات قيّمة و مميزة ذات جودة عالية تليق بسكان المدينة المنورة و زوارها الكرام . تسعى المجموعة بأن يكون منتزه ومطعم الفُلك البحري هو الخيار الأول للعوائل والشباب لقضاء أجمل الأوقات .&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59407484-44361835.jpg?v=1638087249"]','https://cmsphoto.ww-cdn.com/resizeapi/7410a4eb38e88ded7ff736bb4ba7e555cd66b79f/480/',24.5093489,39.7080187,'طريق الملك خالد، Al Aqool Medina','','','','https://www.saudi-guide.com/medina/i/59407484/muntazih-alfulk-albahrii',1,0,'منتزه فلك بحري muntazih alfulk albahrii اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59377804,'abha','حي البسطة القديم','Al Basta Historic District','al-basta-historic-district-hy-albst-alkdym','["التراث والثقافة"]','["heritage"]','حي البسطة من أقدم أحياء أبها، حي تراثي على ضفاف وادي أبها يضم مباني وقلاعاً يعود بعضها للعهد العثماني، ويربطه بالضفة الأخرى جسر عثماني قديم.','<div class="texte" > <p>يعد حي البسطة أحد أحياء ابها القديمة التي لازالت تحتفظ بعبق وبساطة&nbsp;الماضي، هو حي&nbsp;تراثي يتكون من مجموعة مباني وقلاع أثرية قديمة يعود بعضها إلى العهد العثماني، عند زيارتك للمكان ستجد ساحة عامة وبعض المحلات التجارية التقليدية القديمة، يقع حي البسطة على ضفاف وادي أبها وسط المدينة ويربطها بالضفة الأخرى من المدينة جسر عثماني قديم أنشئ منذ عهد الدولة العثمانية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59377804-44065966.jpg?v=1636569945"]','https://cmsphoto.ww-cdn.com/resizeapi/c035a39ea4a2419819f6447922481d605689e810/480/',18.2202734,42.4978628,'Town Center Abha Abha','','','','https://www.saudi-guide.com/abha/i/59377804/al-basta-historic-district-hy-albst-alkdym',1,0,'حي بسطه قديم al basta historic district تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329191,'taif','سد عكرمة التاريخي','Ekrimah Dam','ekrimah-dam-sd-aakrm-altarykhy','["التراث والثقافة"]','["heritage"]','يعتبر سد عكرمة التاريخي أول السدود المنفذة بالمملكة حيث كان له دور إيجابي كبير في حماية مدينة الطائف من أخطار السيول التي كانت تلحق الأضرار بها بصفة','<div class="texte" > <p>يعتبر سد عكرمة التاريخي أول السدود المنفذة بالمملكة حيث كان له دور إيجابي كبير في حماية مدينة الطائف من أخطار السيول التي كانت تلحق الأضرار بها بصفة مستمرة، بالإضافة إلى دعم مصادر المياه للمدينة.</p> <p>تم إنشاء هذا السد عام 1375هـ الموافق 1955م وقد أنشئ في عهد الملك سعود بن عبدالعزيز، وقد كُتبت لوحة&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; تأسيسية من المرمر عليها تاريخ بناء السد بصيغة :&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; "بسم الله الرحمن الرحيم سد عكرمة بالطائف، انشئ هذا السد في عهد الملك سعود الأول ملك المملكة العربية&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;السعودية أيدهُ الله بنصرٍ من عنده وأبقاهُ ذخراً للعرب والمسلمين عام 1375هـ وزارة الزراعة"&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; وقد أستخدمت في الكتابة أنواع الخطوط كالكوفي، والفارسي، والثلث.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329191-44162937.jpg?v=1637075682"]','https://cmsphoto.ww-cdn.com/resizeapi/246e6c9658901fcdd58ab0469ae0c430c7a5ead9/480/',21.2436049,40.3585365,'Ekrimah Dam Wadi Waj Rd C1','','','','https://www.saudi-guide.com/taif/i/59329191/ekrimah-dam-sd-aakrm-altarykhy',1,0,'سد عكرمه تاريخي ekrimah dam تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329189,'taif','مسجد الكوع التراثي','Alkou Mosque','alkou-mosque-msgd-alkoaa-altrathy','["التراث والثقافة"]','["heritage"]','يعتبر مسجد الكوع ويسمى أيضاً مسجد الموقف من أهم المساجد الأثرية في مدينة الطائف وقد سمي مسجد الموقف بهذا الاسم لأن النبي صلى الله عليه وسلم وقف بهذا','<div class="texte" > <p>يعتبر مسجد الكوع ويسمى&nbsp;أيضاً&nbsp;مسجد الموقف&nbsp;من أهم المساجد الأثرية في مدينة الطائف وقد سمي مسجد الموقف بهذا الاسم لأن النبي صلى الله عليه وسلم وقف بهذا المكان عند قدومه إلى الطائف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329189-44162968.jpg?v=1637075827"]','https://cmsphoto.ww-cdn.com/resizeapi/c658a5bd928c71dc59a630f771afd83cc7abd486/480/',21.2569991,40.3868695,'Al Mathnah Taif At-Taif','','','','https://www.saudi-guide.com/taif/i/59329189/alkou-mosque-msgd-alkoaa-altrathy',1,0,'مسجد كوع تراثي alkou mosque تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329165,'taif','مسجد المدهون','Masjid e Madhoon','masjid-e-madhoon-msgd-almdhon','["التراث والثقافة"]','["heritage"]','مسجد المدهون واحد من المساجد الأثرية في مدينة الطائف، يسمى هذا المسجد بهذا الاسم نسبةً إلى الجبل الذي يقع فيه، كما يسمى مسجد القنطرة لأنه بعد بناء','<div class="texte" > <p>مسجد المدهون واحد من المساجد الأثرية في مدينة الطائف، يسمى هذا المسجد بهذا الاسم نسبةً إلى الجبل الذي يقع فيه، كما يسمى مسجد القنطرة لأنه بعد بناء قنطرة العين التي كانت تمر من أمامه، كما يسمى كذلك بمسجد قابل لأنه يقع بجوار مزرعة لآل قابل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329165-44163191.jpg?v=1637077056"]','https://cmsphoto.ww-cdn.com/resizeapi/da640b333ae4da428fdb2276e707e43922ab4d8a/480/',21.2560566,40.3913219,'4033 Awdah At Taif','','','','https://www.saudi-guide.com/taif/i/59329165/masjid-e-madhoon-msgd-almdhon',1,0,'مسجد مدهون masjid e madhoon تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329163,'taif','بيت الكاتب التاريخي','Al-Kateb House','al-kateb-house-byt-alkatb-altarykhy','["التراث والثقافة"]','["heritage"]','بيت الكاتب، بيت تاريخي في مدينة الطائف إحدى مدن المملكة العربية السعودية، أسس في عام 1898، سمي بـ «قصر النيابة» لأن الملك فيصل بن عبدالعزيز أل سعود كان','<div class="texte" > <p>بيت الكاتب، بيت تاريخي في مدينة الطائف إحدى مدن المملكة العربية السعودية، أسس في عام 1898، سمي بـ «قصر النيابة» لأن الملك فيصل بن عبدالعزيز أل سعود كان يقيم فيه أثناء فترة الصيف، واختارته دارة الملك عبدالعزيز ليكون مقرًا لمركز تاريخ الطائف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329163-44174184.jpg?v=1637154523"]','https://cmsphoto.ww-cdn.com/resizeapi/68ad92c01ca321e936d847270a5db19788b9aeab/480/',21.2689872,40.399459,'Al Farabi Qurwa At Taif','','','','https://www.saudi-guide.com/taif/i/59329163/al-kateb-house-byt-alkatb-altarykhy',1,0,'بيت كاتب تاريخي al kateb house تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329160,'taif','قصور الدهلوي','Palaces Dehlawi','palaces-dehlawi-ksor-aldhloy','["التراث والثقافة"]','["heritage"]','يعد قصر الدهلوي من واحد من أهم القصور التراثية في الطائف كما يعد القصر تحفة معمارية حيث يتميز بطريقة بنائه التي تعكس الثقافة الحجازية الطائفية في','<div class="texte" > <p>يعد&nbsp;قصر الدهلوي من واحد من أهم القصور التراثية في الطائف كما يعد القصر تحفة معمارية حيث يتميز بطريقة بنائه التي تعكس الثقافة الحجازية الطائفية في العمران، وقد سكن القصر عدة شخصيات مهمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329160-44163078.jpg?v=1637076374"]','https://cmsphoto.ww-cdn.com/resizeapi/034af558c03b174643d45c18342fc0d93ca615a4/480/',21.2726652,40.4002677,'Osama bin Zaid Qurwa At Taif','','','','https://www.saudi-guide.com/taif/i/59329160/palaces-dehlawi-ksor-aldhloy',1,0,'قصور دهلوي palaces dehlawi تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329158,'taif','سوق البلد التاريخي','Bab Alrea','bab-alrea-sok-albld-altarykhy','["التراث والثقافة"]','["heritage"]','يعتبر سوق سوق البلد التاريخي من أقدم وأكبر الأسواق في محافظة الطائف ويعد من أهم معالم الطائف التاريخية.','<div class="texte" > <p>يعتبر سوق&nbsp;سوق البلد التاريخي من أقدم وأكبر الأسواق في محافظة الطائف ويعد من أهم معالم الطائف التاريخية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329158-44174289.jpg?v=1637155181"]','https://cmsphoto.ww-cdn.com/resizeapi/f323a13244b3bdf601bd358e88761e551d4076bc/480/',21.2722593,40.4063291,'Adam Almantiqah Almarkaziyyah At Taif','','','','https://www.saudi-guide.com/taif/i/59329158/bab-alrea-sok-albld-altarykhy',1,0,'سوق بلد تاريخي bab alrea تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329112,'taif','قصر شبرا التاريخي - متحف','','ksr-shbra-altarykhy-mthf','["التراث والثقافة"]','["heritage"]','قصر شبرا التاريخي أو متحف قصر شبرا هو أحد القصور التاريخية الموجودة بمدينة الطائف.','<div class="texte" > <p>قصر شبرا التاريخي أو متحف قصر شبرا هو أحد القصور التاريخية الموجودة بمدينة الطائف. أنشأ القصر الشريف علي عبد الله بن محمد بن عبد المعين بن عون باشا عام 1323هـ (1904 ميلادي) وتم الانتهاء منه خلال عامين وتم ذلك في عام 1324هـ (1906ميلادي)، تم تحويله إلى متحف إقليمي لمحافظة الطائف وافتتح لاستقبال الزوار عام 1415هـ الموافق 1995م. كان الملك عبد العزيز آل سعود وفيصل بن عبد العزيز آل سعود يتخذانه قصراً لهم عند زيارتهم لمدينة الطائف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329112-44174679.jpg?v=1637156990"]','https://cmsphoto.ww-cdn.com/resizeapi/2d0e190050b8bee1df2f24377a3a88e4a82beb0d/480/',21.2900651,40.4198209,'6171 Al Faisaliyyah At Taif','','','','https://www.saudi-guide.com/taif/i/59329112/ksr-shbra-altarykhy-mthf',1,0,'قصر شبرا تاريخي متحف تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329085,'taif','مسجد عبدالله بن عباس','Abdullah Ibn Alabbas Ancient Mosque','abdullah-ibn-alabbas-ancient-mosque-msgd-aabdallh-bn-aabas','["أماكن سياحية"]','["sights"]','مسجد عبد الله ابن عباس من أشهر مساجد مدينة الطائف الجبلية، وأنشئ عام 592هـ أيام الناصر لدين الله أبي العباس أحمد بن المستضيء العباسي، وسمي بذلك لأنه','<div class="texte" > <p>مسجد عبد الله ابن عباس من أشهر مساجد مدينة الطائف الجبلية، وأنشئ عام 592هـ أيام الناصر لدين الله أبي العباس أحمد بن المستضيء العباسي، وسمي بذلك لأنه يقع بجوار مقبرة حبر هذه الأمة وفقيهها الصحابي الجليل عبد الله بن عباس الذي أخبر رسول الله بموته ودفنه في الطائف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329085-44119649.jpg?v=1636971867"]','https://cmsphoto.ww-cdn.com/resizeapi/08b08afbeca6800da7eef022a18269b2ab5a8d1b/480/',21.2561082,40.3925376,'Wadi Waj Rd Awdah At Taif','','','','https://www.saudi-guide.com/taif/i/59329085/abdullah-ibn-alabbas-ancient-mosque-msgd-aabdallh-bn-aabas',1,0,'مسجد عبدالله بن عباس abdullah ibn alabbas ancient mosque اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329083,'taif','سد السملقي','Alsamlagui Ancient Dam','alsamlagui-ancient-dam-sd-alsmlky','["أماكن سياحية"]','["sights"]','يقع سد السملقي بأعلى وادي ليه في ضواحي محافظة الطائف ويعد أحد السدود التاريخية فيها، يقع السد على بعد 25 كم تقريبا جنوب شرق مدينة الطائف وهو سد أثري','<div class="texte" > <p><span>يقع سد السملقي بأعلى وادي ليه في&nbsp;ضواحي محافظة&nbsp;الطائف ويعد</span>&nbsp;أحد السدود التاريخية فيها،&nbsp;يقع السد على بعد 25 كم تقريبا&nbsp;جنوب شرق مدينة الطائف&nbsp;وهو سد أثري قديم من المرجح أن يكون قد تم بناؤه في الفترة السابقة لظهور الإسلام حيث يوجد&nbsp;كتابات كوفية مبكرة <span>على بعض صخوره&nbsp;</span>ولا تزال معظم جوانبه قائمة، يتميز السد بضخامته حيث يبلغ طوله&nbsp;210 أمتار وعرضه 10&nbsp;أمتار وعرض القاع السفلي 14 م و11 متراً ارتفاعا من على سطح الأرض.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329083-44119929.jpg?v=1636973279"]','https://cmsphoto.ww-cdn.com/resizeapi/a8876c6d33ca9c5e49ceb5c8f5054f6d7863ff63/480/',21.1292446,40.5123565,'SA At-Taif Makkah Province','','','','https://www.saudi-guide.com/taif/i/59329083/alsamlagui-ancient-dam-sd-alsmlky',1,0,'سد سملقي alsamlagui ancient dam اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329080,'taif','متحف الطائف الإقليمي','','mthf-altayf-alaklymy','["أماكن سياحية"]','["sights"]','قصر شبرا التاريخي هو أحد القصور التاريخية الموجودة بمدينة الطائف، أنشئ القصر على يد الشريف علي عبد الله بن محمد بن عبد المعين باشا عام 1323هـ ثم تم','<div class="texte" > <p>قصر شبرا التاريخي&nbsp;هو أحد القصور التاريخية الموجودة بمدينة الطائف، أنشئ&nbsp;القصر على يد&nbsp;الشريف علي عبد الله بن محمد بن عبد المعين باشا عام 1323هـ&nbsp;ثم تم تحويله&nbsp;إلى متحف إقليمي لمحافظة الطائف وافتُتح لاستقبال الزوار عام 1415هـ الموافق،&nbsp;كان الملك عبد العزيز آل سعود وفيصل بن عبد العزيز آل سعود يتخذانه قصراً لهم عند زيارتهم لمدينة الطائف.</p> <p>المتحف يعطى نبذة عن إنشاء القصر، والمراحل التاريخية والسياسية التي شهدها وتحتوى أيضا على مجموعة من الأدوات الحجرية والقطع الفخارية ولوحات من النقوش والكتابات الصخرية كما يوجد قسم عن الحرف والصناعات بالطائف مثل استخراج الورد الطائفي وقسم آخر عن السوق القديم.</p> <p>يحتفظ في داخل متحف القصر بآثار ومنقوشات ورسوم أثرية على صخور حجرية مرتبة بشكل منتظم ومعلقة على رفوف وحوامل خشبية حيث اكتشفت تلك الآثار في محافظة الطائف وتعود إلى عصور إسلامية سابقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329080-44119788.jpg?v=1636972663"]','https://cmsphoto.ww-cdn.com/resizeapi/2d0b2b43ca1c4eaf3e49d1ac3f085eb82495ede7/480/',21.2862858,40.4151556,'At Taif Shubra At-Taif','','','','https://www.saudi-guide.com/taif/i/59329080/mthf-altayf-alaklymy',1,0,'متحف طائف اقليمي اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329053,'taif','سد معاوية بن ابي سفيان','Saysad Dam','saysad-dam-sd-maaaoy-bn-aby-sfyan','["التراث والثقافة"]','["heritage"]','سد سيسد هو سد أثري قديم يقع جنوب شرقي الطائف في منطقة محفوظة طبيعياً وقد بُني السد في عهد الخليفة الأموي معاوية بن أبي سفيان ويعد السد واحد من أبرز','<div class="texte" > <p>سد سيسد هو سد أثري قديم يقع جنوب شرقي الطائف في منطقة محفوظة طبيعياً وقد بُني السد في عهد الخليفة الأموي معاوية بن أبي سفيان ويعد السد واحد من أبرز معالم الطائف التاريخية حيث نقش على واجهة إحدى صخوره بالخط الكوفي : "هذا السد لعبد الله معاوية، أمير المؤمنين بناه عبد الله بن صخر، بإذن الله لسنة ثمان وخمسين، اللهم اغفر لعبد الله معاوية، أمير المؤمنين وثبته وانصره ومتع المؤمنين به كتب عمرو بن حباب".</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329053-44163502.jpg?v=1637077934"]','https://cmsphoto.ww-cdn.com/resizeapi/558f8d0b18ec88534c43a819956a3e01809ad8c7/480/',21.2932786,40.4943455,'SA ج35 الطائف','','','','https://www.saudi-guide.com/taif/i/59329053/saysad-dam-sd-maaaoy-bn-aby-sfyan',1,0,'سد معاويه بن ابي سفيان saysad dam تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329004,'taif','Al Shareef Museum- متحف الشريف','','al-shareef-museum-mthf-alshryf','["التراث والثقافة"]','["heritage"]','متحف الشريف أحد متاحف منطقة مكة المكرمة في محافظة الطائف، أسسه على خلف ملبس الشريف، هو متحف وطني داخل مبنى شعبي كبير تبلغ مساحته 5000 متر مربع ويحوي','<div class="texte" > <p>متحف الشريف أحد متاحف منطقة مكة المكرمة في محافظة الطائف، أسسه على خلف ملبس الشريف، هو متحف وطني داخل مبنى شعبي كبير تبلغ مساحته 5000 متر مربع ويحوي مجموعة كبيرة من القطع التراثية بجميع أنواعها ووظائفها ومادتها والتي تمثل تراث منطقة الطائف، ويحوي المتخف على سوق صغير عبارة عن مجموعة من الأكشاك أو الدكاكين وجعل كل دكان لحرفة معينة وأضاف إليه الأدوات والآلات التي تخص تلك الحرفة، كما يحوي المتحف على قاعات لكل مجموعة كالأسلحة المتمثلة في السيوف والبنادق والخناجر والرماح في قاعة وحدها، وكذلك أدوات القهوة في مكان مخصص لها وأواني الطبخ في مكان وأدوات الزراعة والملابس والحلي النسائية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329004-44177421.jpg?v=1637165377"]','https://cmsphoto.ww-cdn.com/resizeapi/8c2dad133fc05f721b9fc23db7389aefdacd13f5/480/',21.2432424,40.4472184,'السداد الطائف الطائف','','','','https://www.saudi-guide.com/taif/i/59329004/al-shareef-museum-mthf-alshryf',1,0,'al shareef museum متحف شريف تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59329003,'taif','سوق عكاظ التاريخي','Souq Okaz','souq-okaz-sok-aakath-altarykhy','["التراث والثقافة"]','["heritage"]','سوق عكاظ، أحد الأسواق الثلاثة الكبرى في الجاهلية بالإضافة إلى سوق مجنة وسوق ذي المجاز، تعود بدايته إلى 501 للميلاد، وكانت العرب تأتيه لمدة 20 يوما من','<div class="texte" > <p>سوق عكاظ، أحد الأسواق الثلاثة الكبرى في الجاهلية بالإضافة إلى سوق مجنة وسوق ذي المجاز، تعود بدايته إلى 501 للميلاد، وكانت العرب تأتيه لمدة 20 يوما من أول ذي القعدة يبيعون فيه البضائع ويلقون القصائد إلى يوم 20 من الشهر، ثم تسير إلى سوق مجنة فتقضي فيه الأيام العشر الاواخر من شهر ذي القعدة ثم تسير إلى سوق ذي المجاز فتقضي فيه الأيام الثمانية الأولى من شهر ذي الحجة ثم تسير إلى حجها، وسكان سوق عكاظ الأوائل هم قبيلة عدوان وقبيلة هوازن.</p> <p>وبعد توقف دام 1300 سنة أعادت المملكة العربية السعودية إحياء سوق عكاظ وتحديدًا في عهد الملك عبدالله بن عبدالعزيز آل سعود عام 1428هـ، ليكون معلمًا سياحيًا من معالم المملكة، في ذات المكان الذي يقع فيه سوق عكاظ التاريخي، ويقصده العديد من السائحين من شتى أنحاء العالم، إضافة إلى كونه ملتقى تاريخي يجمع الفنانيين والأدباء والشعراء وكافة المهتمين بتاريخ العرب القديم، ويقدم السوق قيمة معرفية من خلال الندوات الثقافية والأمسيات الشعرية والأدبية، إضافة لتنظيم عدد من المسابقات والفعاليات الأدبية على مستوى العالم العربي وتشمل الشعر الفصيح والعامي، والقصة القصيرة، والرسم، والأعمال الحرفية، والرسم، والتصوير الفوتوغرافي، كما أعاد السوق إحياء ديوان العرب من عيون الشعر ومعلقاته وذلك بمحاكاة لشعراء المعلقات المخضرمين.وتشرف وزارة السياحة على سوق عكاظ بعد أن أشرفت عليه إمارة مكة المكرمة على مدار عشر سنوات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59329003-44174104.jpg?v=1637154239"]','https://cmsphoto.ww-cdn.com/resizeapi/f70b9729046f311859124eb0bebac55ce27def2e/480/',21.4736526,40.6461575,'SA Suqukadh At Taif','','','','https://www.saudi-guide.com/taif/i/59329003/souq-okaz-sok-aakath-altarykhy',1,0,'سوق عكاظ تاريخي souq okaz تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328954,'taif','المصنع بيت الورد طائفي','House sectarian roses factory','house-sectarian-roses-factory-msnaa-byt-alord-altayfy','["أماكن سياحية"]','["sights"]','تشتهر الطائف بزراعة الورد الطائفي المستخدم في إنتاج ماء الورد وعطورات ودهن الورد وغيرها من المنتجات، في مصنع بيت الورد طائفي يمكنك شراء والتعرف على','<div class="texte" > <p>تشتهر الطائف بزراعة الورد الطائفي المستخدم في إنتاج ماء الورد وعطورات ودهن الورد وغيرها من المنتجات، في&nbsp;مصنع بيت الورد طائفي يمكنك شراء والتعرف على طريقة إنتاج هذه المنتجات.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328954-44120445.jpg?v=1636975532"]','https://cmsphoto.ww-cdn.com/resizeapi/889d2f7f3a888278d68f7800f723e7451acd16c0/480/',21.3469708,40.2926332,'At Taif At-Taif Makkah Province','','','','https://www.saudi-guide.com/taif/i/59328954/house-sectarian-roses-factory-msnaa-byt-alord-altayfy',1,0,'مصنع بيت ورد طائفي house sectarian roses factory اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328930,'taif','تلفريك الهدا','Telefric Al Hada (Cable Car)','telefric-al-hada-cable-car-tlfryk-alhda','["أماكن سياحية"]','["sights"]','عبرات التلفريك الجبلية تصل بين الهدا ومنطقة الكر بطول 4 كيلو متر وارتفاع 2000 متر عن سطح البحر.','<div class="texte" > <p>عبرات التلفريك الجبلية تصل بين الهدا ومنطقة الكر بطول 4 كيلو متر&nbsp;وارتفاع 2000 متر عن سطح البحر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328930-44122326.jpg?v=1636983417"]','https://cmsphoto.ww-cdn.com/resizeapi/8fd6694ac28db550418c52417a790f61ef9a1109/480/',21.3642004,40.2670805,'Alhuda At-Taif Makkah Province','','','','https://www.saudi-guide.com/taif/i/59328930/telefric-al-hada-cable-car-tlfryk-alhda',1,0,'تلفريك هدا telefric al hada (cable car) اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328928,'taif','قرية الكر السياحية','Al Kar Tourist Village','al-kar-tourist-village-kry-alkr-alsyahy','["أماكن سياحية"]','["sights"]','تتميز قرية الكر السياحية بمناخها خلال فصل الصيف حيث أنها تقع على ارتفاع 900 متر عن سطح البحر، تضم القرية المحطة السفلية لمشروع تلفريك الهدا بالإضافة إلى','<div class="texte" > <p>تتميز<span>&nbsp;قرية الكر السياحية</span> بمناخها خلال فصل الصيف حيث أنها تقع ع<span>لى ارتفاع 900 متر عن سطح البحر،&nbsp;</span>تضم القرية المحطة السفلية لمشروع تلفريك الهدا بالإضافة إلى ملاهي مائية ونهران صناعيان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328928-44120698.jpg?v=1636976445"]','https://cmsphoto.ww-cdn.com/resizeapi/4efb64a9ed77b81e702343ae3d6e8fa90f4edb95/480/',21.3568821,40.2282492,'SA Makkah Al-Mukarramah Makkah Province','','','','https://www.saudi-guide.com/taif/i/59328928/al-kar-tourist-village-kry-alkr-alsyahy',1,0,'قريه كر سياحيه al kar tourist village اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328882,'taif','الشفا','Ash Shafa','ash-shafa-alshfa','["أماكن سياحية"]','["sights"]','مركز الشفا هو مركز تابع لمحافظة الطائف بمنطقة مكة المكرمة غرب المملكة العربية السعودية، يشتهر الشفا بطبيعته الجميلة ويعتبر من أهم المصائف الموجودة بالمم','<div class="texte" > <p>مركز الشفا هو مركز تابع لمحافظة الطائف بمنطقة مكة المكرمة غرب المملكة العربية السعودية، يشتهر الشفا بطبيعته الجميلة ويعتبر من أهم المصائف الموجودة بالمملكة العربية السعودية حيث يقصده السياح باستمرار من جميع الدول وخصوصا من دول الخليج العربي الذين يرتادونه باستمرار لقضاء الإجازة الصيفية، وهو من أجمل وأروع مصايف المملكة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328882-44119587.jpg?v=1636971638"]','https://cmsphoto.ww-cdn.com/resizeapi/8d194eec39ee20688db2080c9972c73fe2401002/480/',21.0701785,40.3088658,'Ash Shafa At-Taif Makkah Province','','','','https://www.saudi-guide.com/taif/i/59328882/ash-shafa-alshfa',1,0,'شفا ash shafa اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328880,'taif','الهدا','Alhuda','alhuda-alhda','["أماكن سياحية"]','["sights"]','الهدا في الطائف منطقة جبلية تعلو أكثر من 2000 متر فوق سطح البحر، تطل على سهول تهامة، وتشتهر بمناخها المعتدل ومنتجعاتها وزراعة الورد والفواكه.','<div class="texte" > <p>تمتاز منطقة الهدا بخصائصها السياحية المميزة لكونها تقع على الحافة الغربية لمرتفعات جبال الحجاز، وتطل بصورة مباشرة على سهول إقليم تهامة بارتفاع يزيد عن 2000 متر فوق سطح البحر، وهي بذلك تتمتع بمناخ معتدل وطبيعة جبلية مميزة، مما أدى إلى جذب الاهتمام نحو التنمية السياحية بالمنطقة بإقامة المنتجعات السياحية والفنادق والشقق المفروشة و<span>الملاهي الكهربائية والجلسات العائلية والشبابية</span>&nbsp;وهو ما&nbsp;أدى إلى تطورها ونموها كمنتجع سياحي،&nbsp;تتمتع المنطقة بجمال طبيعي كبير مميز وهواء معتدل خلال فصل الصيف،&nbsp;ومن منتجات الهدا الزراعية: الفواكه و<span>الخضار&nbsp;والبقول&nbsp;</span>بأنواعها&nbsp;كما تشتهر بزراعة الورد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328880-44119935.jpg?v=1636973446"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/59328880-44119935.jpg?v=1636973476',21.3648223,40.2803491,'Alhuda At-Taif Makkah Province','','','','https://www.saudi-guide.com/taif/i/59328880/alhuda-alhda',1,0,'هدا alhuda اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328857,'taif','القاضي بيت الورد الطائفي','','alkady-byt-alord-altayfy','["أماكن سياحية"]','["sights"]','متجر عطورات يبيع كل أنواع منتجات الورد الطائفي.','<div class="texte" > <p>متجر عطورات يبيع كل أنواع منتجات الورد الطائفي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328857-44122283.jpg?v=1636983207"]','https://cmsphoto.ww-cdn.com/resizeapi/fabebb923f480f9622923d6219ef5ceae07fc55c/480/',21.2728186,40.4085922,'At Taif Almantiqah Almarkaziyyah At-Taif','','','','https://www.saudi-guide.com/taif/i/59328857/alkady-byt-alord-altayfy',1,0,'قاضي بيت ورد طائفي اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328781,'taif','وادي وج','Wej Vally','wej-vally-oady-og','["أماكن سياحية"]','["sights"]','وادي وج، هو وادي يقع في محافظة الطائف التابعة لمنطقة مكة المكرمة غرب المملكة العربية السعودية، ويسمى اليوم منطقة وادي المحرم بالهدا.','<div class="texte" > <p>وادي وج، هو وادي يقع في محافظة الطائف التابعة لمنطقة مكة المكرمة غرب المملكة العربية السعودية، ويسمى اليوم منطقة وادي المحرم بالهدا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328781-44121025.jpg?v=1636978101"]','https://cmsphoto.ww-cdn.com/resizeapi/33b19a4bb429cbc1df13a7310809ac7973443163/480/',21.3960552,40.5454436,'Wej Vally Taif At-Taif','','','','https://www.saudi-guide.com/taif/i/59328781/wej-vally-oady-og',1,0,'وادي وج wej vally اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328780,'taif','فوهة بركان الوعبة - مقلع طمية','Al-Waba Crater','al-waba-crater-foh-brkan-aloaab-mklaa-tmy','["أماكن سياحية"]','["sights"]','فوهة الوعبة (محلياً: مقلع طمية) حفرة عميقة في الأرض بقطر دائري يبلغ 3 كيلومترات وبعمق 380 مترا، وهي الأكبر من نوعها في الشرق الأوسط.','<div class="texte" > <p>فوهة الوعبة (محلياً: مقلع طمية) حفرة عميقة في الأرض بقطر دائري يبلغ 3 كيلومترات وبعمق 380 مترا، وهي الأكبر من نوعها في الشرق الأوسط. تقع على بعد 254 كم من مدينة الطائف، يكسو وسط الفوهة طبقة ملحية بيضاء اللون ويعتقد أن سبب تكونها يرجع إلى أن مياه الأمطار تتجمع في قاع الفوهة مكونة بحيرة صغيرة ضحلة لاتتسرب إلى باطن الأرض.</p> <p>سُميت مقلع طميه نسبة لجبل طميه على نفس شكلها ولذلك سميت الفهوة البركانية باسم مقلع طمية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328780-44122533.jpg?v=1636984474"]','https://cmsphoto.ww-cdn.com/resizeapi/2b986311b4e818309eb84e4dc352e1a454bc3d87/480/',22.9010939,41.1391637,'SA Ta''if Makkah Province','','','','https://www.saudi-guide.com/taif/i/59328780/al-waba-crater-foh-brkan-aloaab-mklaa-tmy',1,0,'فوهه بركان وعبه مقلع طميه al waba crater اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328632,'taif','منتزه الجبل الاخضر','Green Mountain Resort','green-mountain-resort-mntzh-algbl-alakhdr','["أماكن سياحية"]','["sights"]','متنزه ترفيهي فسيح يحتوي على العديد من الألعاب الكهربائية المناسبة لكل الأعمار.','<div class="texte" > <p>متنزه ترفيهي فسيح يحتوي على العديد من الألعاب الكهربائية المناسبة لكل الأعمار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328632-44124146.jpg?v=1636990331"]','https://cmsphoto.ww-cdn.com/resizeapi/438b79e6b82f6877b6d36a3eda5a67216b136f81/480/',21.3393455,40.3428657,'Alhada Rd C44 At Taif','','','','https://www.saudi-guide.com/taif/i/59328632/green-mountain-resort-mntzh-algbl-alakhdr',1,0,'منتزه جبل اخضر green mountain resort اماكن سياحيه',strftime('%s','now'));
