INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039678,'jeddah','ذا دوكس للألعاب','The Dockx Gaming Center','the-dockx-gaming-center-tha-doks-llalaaab','["سياحة وترفيه"]','["sights"]','ذا دوكس مركز ترفيهي متكامل في جدة يضم غرف كاريوكي وبلياردو وألعاب واقع معزز ومضمار كارتينج صغير، إضافة إلى مطعم ومقهى.','<div class="texte" > <p>The Dockx مركز ترفيهي متكامل في جدة يضم غرف كاريوكي وبلياردو وألعاب واقع معزز وألعاب ورق ومضمار كارتينج صغير، إضافة إلى مطعم ومقهى، ما يجعله وجهة مناسبة للعائلات والشباب على حد سواء.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039678-68539699.jpg?v=1791530818", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039678-68539706.jpg?v=1791530831"]','https://cmsphoto.ww-cdn.com/resizeapi/a15bd471bd377fa98a5be537fe8b61282080d8c5/480/',21.6268027,39.1131386,'King Abdul Aziz Rd, Ash Shati, Jeddah 21146','','','','https://www.saudi-guide.com/jeddah/i/98039678/the-dockx-gaming-center-tha-doks-llalaaab',1,0,'ذا دوكس للالعاب the dockx gaming center سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039677,'jeddah','ميدان X بينتبول','X Paintball Arena','x-paintball-arena-mydan-x-byntbol','["سياحة وترفيه"]','["sights"]','ميدان X بينتبول في جدة يقدم تجربة بينتبول تنافسية في الهواء الطلق، لمجموعات تتراوح بين 6 و18 لاعبًا، وسط أجواء مليئة بالإثارة والأكشن والحماس.','<div class="texte" > <p>ميدان X بينتبول في جدة يقدم تجربة بينتبول تنافسية في الهواء الطلق، لمجموعات تتراوح بين 6 و18 لاعبًا، وسط أجواء مليئة بالإثارة والأكشن والحماس، ويُنصح بالحجز المسبق نظرًا لإقباله الكبير.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039677-68540709.jpg?v=1791533741"]','https://cmsphoto.ww-cdn.com/resizeapi/d541d249f7a03ee00aaba3fc0c0005516e452eac/480/',21.8110363,39.1112757,'King Saud Rd, Al Sawari, Jeddah 23828','','','','https://www.saudi-guide.com/jeddah/i/98039677/x-paintball-arena-mydan-x-byntbol',1,0,'ميدان x بينتبول x paintball arena سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039676,'jeddah','مسرح ذا كلوب','The Club Theatre','the-club-theatre-msrh-tha-klob','["سياحة وترفيه"]','["sights"]','عرض ترفيهي حي يجمع بين الأجواء المميزة والموسيقى والمطربين والممثلين في تجربة بصرية وأدائية متكاملة.','<div class="texte" > <p>مسرح ذا كلوب في جدة يستضيف عروضًا ترفيهية حية تجمع بين الموسيقى والغناء والأداء المسرحي، بأجواء بصرية مميزة ونظام صوتي وإضاءة متطور يمنح الجمهور تجربة أدائية متكاملة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039676-68539738.jpg?v=1791530978"]','https://cmsphoto.ww-cdn.com/resizeapi/ee4a9734f08563ae0eebb8adae095aa231b3d1d7/480/',21.6317382,39.128733,'7520 Ash Shati, Jeddah 23413','','','','https://www.saudi-guide.com/jeddah/i/98039676/the-club-theatre-msrh-tha-klob',1,0,'مسرح ذا كلوب the club theatre سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039675,'jeddah','غيم أوفر لغرف الهروب','Game Over Escape Room','game-over-escape-room-ghym-aofr-lghrf-alhrob','["سياحة وترفيه"]','["sights"]','غيم أوفر في جدة تقدم غرف هروب سينمائية بتصاميم متنوعة وألغازاً تفاعلية، يتسابق فيها الزوار مع الوقت لحل الألغاز والخروج قبل نفاده.','<div class="texte" > <p>Game Over Escape Room في جدة تقدم غرف هروب سينمائية بتصاميم متنوعة وألغازًا تفاعلية، حيث يتسابق الزوار ضد عد تنازلي مدته ستين دقيقة لحل الألغاز والخروج قبل نفاد الوقت.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039675-68539758.jpg?v=1791531058", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039675-68539761.jpg?v=1791531064"]','https://cmsphoto.ww-cdn.com/resizeapi/be35f692abb54d020b83e58939264b7477c8538c/480/',21.5802946,39.1499382,'6604 Al Yamamah, As Salamah, Jeddah 32436','','','','https://www.saudi-guide.com/jeddah/i/98039675/game-over-escape-room-ghym-aofr-lghrf-alhrob',1,0,'غيم اوفر لغرف هروب game over escape room سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039674,'jeddah','نادي البولينج ذا بي كلوب','The B Club','the-b-club-nady-albolyng-tha-by-klob','["سياحة وترفيه"]','["sights"]','نادي ذا بي كلوب للبولينج في جدة يقع داخل مجمع سرافي ويوفر 16 مساراً، إضافة إلى ألعاب البلياردو وتنس الطاولة وأجهزة الفيديو.','<div class="texte" > <p>نادٍ متميز للبولينج في جدة يقع داخل مجمع سرافي، ويوفر 16 مسارًا بأحجام كرات متعددة تناسب مختلف الأعمار، إضافة إلى ألعاب البلياردو وتنس الطاولة وأجهزة الفيديو، ومرافق صلاة للرجال والنساء.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039674-68539766.jpg?v=1791531118", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039674-68539768.jpg?v=1791531119"]','https://cmsphoto.ww-cdn.com/resizeapi/c1f5eb364953b58a421d5ac5f2cf7a981dcde9de/480/',21.5608872,39.1845219,'Serafi Mega Mall, Al Faisaliyyah, Jeddah 23441','','','','https://www.saudi-guide.com/jeddah/i/98039674/the-b-club-nady-albolyng-tha-by-klob',1,0,'نادي بولينج ذا بي كلوب the b club سياحه وترفيه',strftime('%s','now'));
