INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039671,'jeddah','لكي رول','Lucky Roll','lucky-roll-lky-rol','["سياحة وترفيه"]','["sights"]','لكي رول وجهة ترفيهية نابضة بالحياة في جدة، تجمع بين مسارات البولينج وألعاب الأركيد وكشك التصوير الفوري.','<div class="texte" > <p>لكي رول وجهة ترفيهية نابضة بالحياة في جدة، تجمع بين مسارات البولينج وألعاب الأركيد وكشك التصوير الفوري، مع مقهى داخلي يمنح الزوار تجربة اجتماعية متكاملة تناسب العائلة والأصدقاء.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039671-68540822.jpg?v=1791533827"]','https://cmsphoto.ww-cdn.com/resizeapi/988673334795281e72a6c8a352aada9e5cb7f955/480/',21.6479563,39.1205692,'Ibrahim Al-Anqari, Al Mohammadiyyah, Jeddah 23617','','','','https://www.saudi-guide.com/jeddah/i/98039671/lucky-roll-lky-rol',1,0,'لكي رول lucky roll سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039670,'jeddah','فينك','Fennec','fennec-fynk','["سياحة وترفيه"]','["sights"]','فينك مساحة إبداعية في جدة تجمع بين الفن والترفيه، تستضيف عروضًا مسرحية وفعاليات ثقافية وورش فنية ضمن مجتمع محلي نابض بالحيوية.','<div class="texte" > <p>فينك مساحة إبداعية في جدة تجمع بين الفن والترفيه، تستضيف عروضًا مسرحية وفعاليات ثقافية وورش فنية ضمن مجتمع محلي نابض بالحيوية، وتُعد وجهة مناسبة للأصدقاء والعائلات الباحثين عن أجواء ثقافية غير تقليدية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039670-68539812.jpg?v=1791531445", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039670-68539813.jpg?v=1791531454"]','https://cmsphoto.ww-cdn.com/resizeapi/c5bef2d6503fccd723aa0ec973f6ee1928156f01/480/',21.6316243,39.1288285,'Arwa Bint Abdulmutaleb, Al Mohammadiyyah, Jeddah 23615','','','','https://www.saudi-guide.com/jeddah/i/98039670/fennec-fynk',1,0,'فينك fennec سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039669,'jeddah','إسطبل صن ست','Sunset Stables','sunset-stables-astbl-sn-st','["سياحة وترفيه"]','["sights"]','إسطبل صن ست يقدم تجربة ركوب خيل مميزة على شاطئ البحر في جدة، حيث يمكن للزوار التنقل بين الرمال والمياه الضحلة مع مناظر غروب خلابة.','<div class="texte" > <p>إسطبل صن ست يقدم تجربة ركوب خيل مميزة على شاطئ البحر في جدة، حيث يمكن للزوار التنقل بين الرمال والمياه الضحلة مع مناظر غروب خلابة. التجربة مناسبة للمبتدئين والمحترفين، ويحرص المرشدون على راحة وسلامة كل راكب.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039669-68539819.jpg?v=1791531515", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039669-68539820.jpg?v=1791531526"]','https://cmsphoto.ww-cdn.com/resizeapi/64ed45938eaf0a1e48b530f503204d323cb5c288/480/',21.9192876,39.040226,'Sunset Stable, Jeddah 23868','','','','https://www.saudi-guide.com/jeddah/i/98039669/sunset-stables-astbl-sn-st',1,0,'اسطبل صن ست sunset stables سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039666,'jeddah','جزيرة بياضة','Bayadah Island','bayadah-island-gzyr-byad','["سياحة وترفيه"]','["sights"]','جزيرة بياضة إحدى الجزر الطبيعية على ساحل البحر الأحمر قبالة جدة، تتميز بمياهها الفيروزية ورمالها البيضاء وشعابها المرجانية الملونة.','<div class="texte" > <p>جزيرة بياضة إحدى الجزر الطبيعية على ساحل البحر الأحمر قبالة جدة، تتميز بمياهها الفيروزية ورمالها البيضاء وشعابها المرجانية الملونة. تصل إليها رحلات بحرية يومية، وتُعد وجهة مفضلة لهواة السنوركلنغ والاسترخاء بعيدًا عن صخب المدينة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039666-68539840.jpg?v=1791531665", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039666-68539842.jpg?v=1791531675"]','https://cmsphoto.ww-cdn.com/resizeapi/b06175ecad1ea4905e877fa3ea762ce9643ff690/480/',21.7177867,39.1041724,'Al Kurnaysh Br Rd, Abhur Al Junoobiyah, Jeddah 23731','','','','https://www.saudi-guide.com/jeddah/i/98039666/bayadah-island-gzyr-byad',1,0,'جزيره بياضه bayadah island سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039664,'jeddah','منتجع وفلل ريكسوس أبحر جدة','Rixos Obhur Jeddah','rixos-obhur-jeddah-mntgaa-ofll-ryksos-abhr-gd','["سياحة وترفيه"]','["sights"]','اكتشف الفخامة الشاملة في منتجع وفلل ريكسوس أبحر جدة، بإطلالات على البحر الأحمر وفلل أنيقة ومطاعم عالمية متنوعة.','<div class="texte" > <p>منتجع فاخر في منطقة أبحر شمال جدة، يوفر إطلالات مباشرة على البحر الأحمر وفللًا أنيقة ومسبحًا خاصًا، مع مجموعة متنوعة من المطاعم العالمية وأندية أطفال مخصصة، ما يجعله وجهة مثالية للعائلات الباحثة عن استجمام فاخر.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039664-68539851.jpg?v=1791531738", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039664-68539852.jpg?v=1791531746"]','https://cmsphoto.ww-cdn.com/resizeapi/36391815cac69627c300a4e606a05497ade8f0c6/480/',21.7594216,39.1266917,'Abdullah Al Faisal Street, Abhur Ash Shamaliyah, Jeddah 23817','','','','https://www.saudi-guide.com/jeddah/i/98039664/rixos-obhur-jeddah-mntgaa-ofll-ryksos-abhr-gd',1,0,'منتجع وفلل ريكسوس ابحر جده rixos obhur jeddah سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039663,'jeddah','منتجع ريكسوس مرجانة','Rixos Marjan Island','rixos-marjan-island-mntgaa-ryksos-mrgan','["سياحة وترفيه"]','["sights"]','استمتع بتجربة الفخامة الشاملة في منتجع ريكسوس مرجانة بمدينة الملك عبدالله الاقتصادية، مع شاطئ خاص وحديقة مائية وتجارب ضيافة راقية.','<div class="texte" > <p>يقع منتجع ريكسوس مرجانة في مدينة الملك عبدالله الاقتصادية شمال جدة، ويقدم تجربة فخامة شاملة تضم شاطئًا خاصًا وحديقة مرجانة المائية ومجموعة متنوعة من المطاعم العالمية، إلى جانب أنشطة ترفيهية للعائلة طوال العام.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039663-68539859.jpg?v=1791531807", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039663-68539860.jpg?v=1791531834"]','https://cmsphoto.ww-cdn.com/resizeapi/ef2ca4a55a9981ee6dac304f945598d2b4beab3e/480/',22.4566929,39.091813,'Al Sahel Rd Al Murooj, King Abdullah Economic City 23981','','','','https://www.saudi-guide.com/jeddah/i/98039663/rixos-marjan-island-mntgaa-ryksos-mrgan',1,0,'منتجع ريكسوس مرجانه rixos marjan island سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039661,'jeddah','معرض تيم لاب','teamLab Borderless Jeddah','teamlab-borderless-jeddah-maard-tym-lab','["التراث والثقافة"]','["heritage"]','معرض تيم لاب في جدة متحف فني تفاعلي يقدم أعمالاً رقمية تتحرك وتتفاعل مع حركة الزائر، وهو الأول من نوعه في الشرق الأوسط.','<div class="texte" > <p>متحف فني تفاعلي بلا حدود في جدة، يقدم أعمالًا رقمية تتحرك وتتفاعل مع حركة الزائر، وهو الأول من نوعه في الشرق الأوسط. تخلق المساحات المتصلة داخل المتحف تجربة غامرة تمزج بين الفن والتقنية، وتناسب الزوار من مختلف الأعمار.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039661-68539868.jpg?v=1791531883", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039661-68539871.jpg?v=1791531896"]','https://cmsphoto.ww-cdn.com/resizeapi/7aa64686d24aa164911121a478febeed903f7c92/480/',21.4948976,39.1836397,'Hamzah Shehatah, Historic Jeddah, Jeddah 22235','','','','https://www.saudi-guide.com/jeddah/i/98039661/teamlab-borderless-jeddah-maard-tym-lab',1,0,'معرض تيم لاب teamlab borderless jeddah تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039660,'jeddah','حي السينما','Hayy Cinema','hayy-cinema-hy-alsynma','["التراث والثقافة"]','["heritage"]','حي السينما في جدة أول دار عرض فنية مستقلة في السعودية ضمن مجمع حي جميل، تعرض أفلاماً محلية وعالمية في مساحة ثقافية نابضة.','<div class="texte" > <p>أول دار عرض فنية مستقلة في السعودية، تقع ضمن مجمع حي جميل، وتعرض أفلامًا محلية وعالمية طوال العام في مساحة ثقافية نابضة بالإبداع، إلى جانب فعاليات وورش سينمائية تدعم صناع الأفلام الناشئين.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039660-68539877.jpg?v=1791531948", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039660-68539879.jpg?v=1791531958"]','https://cmsphoto.ww-cdn.com/resizeapi/7d75f160c7b03ac9cff66f85b540e89dd2b0f5bf/480/',21.6317555,39.1289256,'Hayy Jameel, Al Muhammadiyah, Jeddah 23623','','','','https://www.saudi-guide.com/jeddah/i/98039660/hayy-cinema-hy-alsynma',1,0,'حي سينما hayy cinema تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039659,'jeddah','حي جميل','Hayy Jameel','hayy-jameel-hy-gmyl','["التراث والثقافة"]','["heritage"]','حي جميل حي ثقافي إبداعي في جدة، يقدم معارض فنية موسمية وورش عمل وفعاليات ثقافية وتجارب عائلية ضمن مجتمع نابض بالحياة.','<div class="texte" > <p>حي جميل حي ثقافي إبداعي في جدة، يقدم معارض فنية موسمية وورش عمل وفعاليات ثقافية وتجارب عائلية ضمن مجتمع نابض بالحياة، ويضم مساحات فنية متعددة ومقاهٍ ومحال إبداعية تجعله وجهة يومية لمحبي الفن والثقافة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039659-68539889.jpg?v=1791532017", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039659-68539890.jpg?v=1791532027"]','https://cmsphoto.ww-cdn.com/resizeapi/e3fdbe8e4a9d83478fb8d94649ff1f6662dd2556/480/',21.6313125,39.1290136,'Al Muhammadiyah District, Jeddah 23615','','','','https://www.saudi-guide.com/jeddah/i/98039659/hayy-jameel-hy-gmyl',1,0,'حي جميل hayy jameel تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039658,'jeddah','دارة صفية بن زقر','Darat Safeya Binzagr','darat-safeya-binzagr-dar-sfy-bn-zkr','["التراث والثقافة"]','["heritage"]','دارة صفية بن زقر في جدة مخصصة لأعمال الفنانة السعودية الرائدة، تضم لوحات وأزياء تقليدية ومقتنيات تعكس التراث السعودي.','<div class="texte" > <p>دارة مخصصة لأعمال الفنانة السعودية الرائدة صفية بن زقر، تضم مجموعة واسعة من اللوحات والأزياء التقليدية والمقتنيات التي تعكس التراث السعودي. تستعرض الدارة معارض موضوعية تشمل مشاهد الحياة اليومية والاحتفالات التقليدية والأزياء الإقليمية، إلى جانب استوديو الفنانة ومكتبتها الشخصية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039658-68539911.jpg?v=1791532166"]','https://cmsphoto.ww-cdn.com/resizeapi/e98914c1d949d6359a7b9735a8efdf0a600fc314/480/',21.5097737,39.1810003,'King Abdullah Rd, Al-Baghdadiyah Al-Gharbiyah, Jeddah 22234','','','','https://www.saudi-guide.com/jeddah/i/98039658/darat-safeya-binzagr-dar-sfy-bn-zkr',1,0,'داره صفيه بن زقر darat safeya binzagr تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039657,'jeddah','معرض أثر','ATHR Gallery','athr-gallery-maard-athr','["التراث والثقافة"]','["heritage"]','يستضيف معرض أثر في جدة معارض فردية وجماعية لفنانين سعوديين وإقليميين في مجالات الرسم والنحت والفنون المتعددة الوسائط منذ تأسيسه عام 2009.','<div class="texte" > <p>يستضيف معرض أثر في جدة معارض فردية وجماعية لفنانين سعوديين وإقليميين في مجالات الرسم والنحت والفنون المتعددة الوسائط منذ تأسيسه عام 2009، ويُعد من أبرز منصات الفن المعاصر في المنطقة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039657-68539924.jpg?v=1791532252", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039657-68539926.jpg?v=1791532265"]','https://cmsphoto.ww-cdn.com/resizeapi/33e5816fb84452acabe79c8f9946a6ab857f4fd3/480/',21.4841943,39.1879635,'Bait Shouaib Jeddah Historical District, Historic Jeddah, Jeddah 22236','','','','https://www.saudi-guide.com/jeddah/i/98039657/athr-gallery-maard-athr',1,0,'معرض اثر athr gallery تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039656,'jeddah','دار الفنون الإسلامية','Jeddah House of Islamic Arts','jeddah-house-of-islamic-arts-dar-alfnon-alaslamy','["التراث والثقافة"]','["heritage"]','يعد دار الفنون الإسلامية في جدة معلمًا ثقافيًا فريدًا يخوض بالزوار في رحلة تأملية عبر جماليات الحضارة الإسلامية وإرثها البصري والروحي.','<div class="texte" > <p>يعد دار الفنون الإسلامية في جدة معلمًا ثقافيًا فريدًا يخوض بالزوار في رحلة تأملية عبر جماليات الحضارة الإسلامية وإرثها البصري والروحي، من خلال مقتنيات نادرة ومساحات عرض مصممة بعناية تجمع بين الأصالة والحداثة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039656-68539932.jpg?v=1791532322", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039656-68539934.jpg?v=1791532331"]','https://cmsphoto.ww-cdn.com/resizeapi/441902170ac4955227b77e3e06cf8a7d1e5d63a2/480/',21.5562968,39.1839916,'Aziziyah, Jeddah 23334','','','','https://www.saudi-guide.com/jeddah/i/98039656/jeddah-house-of-islamic-arts-dar-alfnon-alaslamy',1,0,'دار فنون اسلاميه jeddah house of islamic arts تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039654,'jeddah','سوق قابل','Souq Qabel','souq-qabel-sok-kabl','["التراث والثقافة"]','["heritage"]','يقع سوق قابل في قلب جدة التاريخية، محافظًا على روحه وتفاصيله الأصيلة منذ قرون. لا يُعد هذا السوق مجرد مكان للتسوّق.','<div class="texte" > <p>يقع سوق قابل في قلب جدة التاريخية، محافظًا على روحه وتفاصيله الأصيلة منذ قرون. لا يُعد هذا السوق مجرد مكان للتسوّق، بل معلم ثقافي حي يوثّق ملامح الحياة اليومية والتقاليد التي توارثها الأهالي عبر الأجيال، ويضم بائعي التوابل والمنسوجات وأصحاب الحرف التقليدية.</p> </div>  <div class="texte" > <p>مصدر الصور: Wikimedia Commons — تصوير: Richard Mortel (CC BY 2.0)، Imam Khairul Annas (CC BY-SA 4.0)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039654-68554058.jpg?v=1791668590", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039654-68554059.jpg?v=1791668601"]','https://cmsphoto.ww-cdn.com/resizeapi/f1a76294a685687e77dc040f0f3a4ce4fc8ba928/480/',21.4840759,39.1850077,'Qabel Trail, Historic Jeddah, Jeddah 22233','','','','https://www.saudi-guide.com/jeddah/i/98039654/souq-qabel-sok-kabl',1,0,'سوق قابل souq qabel تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98038546,'albaha','متحف بيت العايد','Bait Al Aed Museum','bait-al-aed-museum-mthf-byt-alaaayd','["التراث والثقافة"]','["heritage"]','متحف بيت العايد في بلجرشي وجهة تراثية تقدم تجربة الضيافة السعودية الأصيلة، بمقتنيات تقليدية وأطباق شعبية وعروض فلكلورية حية.','<div class="texte" > <p>متحف بيت العايد وجهة تراثية بمنطقة بلجرشي تقدم تجربة متكاملة للضيافة السعودية الأصيلة، حيث يتعرف الزوار على مقتنيات وقطع أثرية تقليدية، ويستمتعون بالأطباق الشعبية والعروض الفلكلورية الحية التي تعكس ثقافة المنطقة وعاداتها.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98038546-68539959.jpg?v=1791532484", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98038546-68539965.jpg?v=1791532498"]','https://cmsphoto.ww-cdn.com/resizeapi/1e9f32e24a23636637a1bca50767cb8cca8ddf7a/480/',19.9441875,41.5650625,'الدهامشة، بني كبير 65642','','','','https://www.saudi-guide.com/albaha/i/98038546/bait-al-aed-museum-mthf-byt-alaaayd',1,0,'متحف بيت عايد bait al aed museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98038545,'albaha','قرية العبادل التراثية','Al Abadil Heritage Village','al-abadil-heritage-village-kry-alaabadl-altrathy','["التراث والثقافة"]','["heritage"]','قرية العبادل التراثية في الباحة تكشف نمط الحياة الجبلية القديمة، ببيوت حجرية متراصة وممرات ضيقة متعرجة وطابع أصيل بعيد عن صخب المدن.','<div class="texte" > <p>تكشف قرية العبادل التراثية عن نمط الحياة الجبلية التقليدية في الباحة، ببيوتها الحجرية العريقة المتراصة وممراتها الضيقة المتعرجة بين المنازل. تحافظ القرية على طابعها الأصيل بعيدًا عن صخب المدن، وتمنح الزائر تجربة هادئة للتجول بين آثار العمارة المحلية القديمة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98038545-68539974.jpg?v=1791532558"]','https://cmsphoto.ww-cdn.com/resizeapi/f0819835f9c5ed77ef4b1a5940e3af396f5674c2/480/',19.9447462,41.5610376,'العبادل، بني كبير 65642','','','','https://www.saudi-guide.com/albaha/i/98038545/al-abadil-heritage-village-kry-alaabadl-altrathy',1,0,'قريه عبادل تراثيه al abadil heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98038543,'albaha','مركز زوار قرية ذي عين التراثية','Thee Ain Village Visitor Center','thee-ain-village-visitor-center-mrkz-zoar-kry-thy-aayn-altrathy','["التراث والثقافة"]','["heritage"]','مركز زوار قرية ذي عين المحطة الأولى لاستكشاف القرية الحجرية العريقة، يقدم عرضاً تعريفياً تفاعلياً بتاريخها وحياة أهلها عبر القرون.','<div class="texte" > <p>يُعد مركز الزوار المحطة الأولى لاستكشاف قرية ذي عين التراثية، حيث يقدم عرضًا تعريفيًا وأجواء تفاعلية تشرح تاريخ القرية الحجرية العريقة وطبيعة الحياة فيها عبر القرون، قبل أن ينطلق الزائر في جولته داخل القرية نفسها بجبال السروات.</p> </div>    <div class="texte" > <p>مصدر الصور: ويكيميديا كومنز — تصوير Richard Mortel (CC BY 2.0) ووكالة الأنباء السعودية واس (CC BY-SA 4.0)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98038543-68537712.jpg?v=1791497861", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98038543-68537716.jpg?v=1791497873"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98038543-68537712.jpg?v=1791497862',19.9295024,41.4399081,'العام، المخواة 95413','','','','https://www.saudi-guide.com/albaha/i/98038543/thee-ain-village-visitor-center-mrkz-zoar-kry-thy-aayn-altrathy',1,0,'مركز زوار قريه ذي عين تراثيه thee ain village visitor center تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98038539,'albaha','قرية الموسى التراثية','Al Musa Heritage Village','al-musa-heritage-village-kry-almosa-altrathy','["التراث والثقافة"]','["heritage"]','قرية الموسى التراثية في الباحة وجهة ثقافية تنقل الزائر لأجواء الحياة الشعبية، بعروض تراثية وحرف يدوية وطعام شعبي وجولات مع مرشدين محليين.','<div class="texte" > <p>قرية الموسى التراثية بالباحة وجهة ثقافية تنقل الزائر إلى أجواء الحياة الشعبية القديمة في المنطقة، عبر عروض تراثية وحرف يدوية أصيلة يمارسها حرفيون محليون. تقدم القرية أيضًا تجارب طعام شعبي، وجولات تعريفية يقودها مرشدون محليون يشرحون فيها ملامح الهوية الثقافية لسكان الباحة عبر الأجيال.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98038539-68539980.jpg?v=1791532614", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98038539-68539984.jpg?v=1791532627"]','https://cmsphoto.ww-cdn.com/resizeapi/c2dc6826d556c39834e356403a761a5b9121395d/480/',20.1104561,41.4191521,'الباحة 65734','','','','https://www.saudi-guide.com/albaha/i/98038539/al-musa-heritage-village-kry-almosa-altrathy',1,0,'قريه موسي تراثيه al musa heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98022460,'jeddah','متحف البحر الأحمر','Red Sea Museum','red-sea-museum-mthf-albhr-alahmr','["التراث والثقافة"]','["heritage"]','متحف البحر الأحمر في جدة هو من أبرز المعالم الثقافية والسياحية في المملكة العربية السعودية.','<div class="texte" > <p>متحف البحر الأحمر في جدة هو من أبرز المعالم الثقافية والسياحية في المملكة العربية السعودية. افتتح المتحف في 2021 كمبادرة تهدف إلى تعزيز الوعي البيئي والثقافي في المنطقة، خاصة فيما يخص الحياة البحرية والتنوع البيولوجي في البحر الأحمر.</p> <p>يمتد المتحف على مساحة شاسعة ويضم مجموعة متنوعة من المعارض الفنية والتفاعلية التي تستعرض تاريخ البحر الأحمر، بالإضافة إلى التطبيقات الحديثة للعلوم البحرية. يركز المتحف على أنشطة التوعية البيئية من خلال برامج تعليمية تستهدف الزوار من جميع الأعمار.</p> <p>كما يُعتبر المتحف منصة للفنانين المحليين والدوليين من خلال استضافة معارض فنية تضم أعمالاً تُعبر عن جمال الطبيعة البحرية وتعكس التحديات التي تواجه البيئة. يساهم المتحف كذلك في تنمية السياحة الثقافية في جدة ويعزز من مكانتها كوجهة سياحية عالمية.</p> <p>يتميز متحف البحر الأحمر بتصميمه المعماري الفريد الذي يحاكي أشكال الموجات البحرية، مما يجعله رمزًا للفن المعاصر وروح البحر الأحمر. يتوفر للزوار مجموعة من الفعاليات والأنشطة التي تفعل ارتباطهم بعالم البحر والمحيطات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98022460-68242265.jpg?v=1789348781", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98022460-68242266.jpg?v=1789348790"]','https://cmsphoto.ww-cdn.com/resizeapi/c2ca16484ed8e44039743a611aeafd02919b1395/480/',21.4833191,39.1827557,' F5MM+84 جدة التاريخية','','https://www.moc.gov.sa/ar/Modules/Pages/CulturalCenterAndAssets/Red-Sea-Museum','','https://www.saudi-guide.com/jeddah/i/98022460/red-sea-museum-mthf-albhr-alahmr',1,0,'متحف بحر احمر red sea museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97954793,'umluj','منتجع ناموس','Nammos Resort AMAALA','nammos-resort-amaala-mntgaa-namos','["أماكن سياحية"]','["sights"]','في ناموس أمالا، يمتزج سحر الحياة الساحلية اليونانية بأصالة الحفاوة السعودية، وسط أجواء ساحلية راقية ومشاهد بحرية آسرة تعكس روح أمالا.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div data-testid="header-section-description"> <p>في ناموس أمالا، يمتزج سحر الحياة الساحلية اليونانية بأصالة الحفاوة السعودية، لتولد تجربة استثنائية تُحفر في الذاكرة. هنا لكل لحظة إيقاعها الخاص، أجواء ساحلية راقية، وتجارب تنبض بالحيوية، ومشاهد بحرية آسرة تجتمع لتصنع لحظات خالدة تعكس روح أمالا.</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97954793-68196307.jpg?v=1788820460", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97954793-68196315.jpg?v=1788820475", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97954793-68196306.jpg?v=1788820363"]','https://cmsphoto.ww-cdn.com/resizeapi/51bf7eed16f341b83bff33e6d070405d0fc996ec/480/',26.6450556,36.2145128,'8491 Triple Bay Marina Resort 1 3110','+966 11222 2222','https://www.visitredsea.com/ar/resorts/nammos-resort-amaala','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97954793/nammos-resort-amaala-mntgaa-namos',1,0,'منتجع ناموس nammos resort amaala اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97954745,'umluj','منتجع إكوينوكس، أمالا','','mntgaa-akoynoks-amala','["أماكن سياحية"]','["sights"]','يُجسّد منتجع إكوينوكس أمالا مفهوم الفخامة عالية الأداء في قلب تريبل باي، وسط مشاهد البحر الأحمر وجبال الحجاز، مع برامج استشفاء وتجارب طهي مُلهمة.','<div class="texte" > <p>يُجسّد منتجع إكوينوكس أمالامفهوم الفخامة عالية الأداء، ويشكّل القلب النابض لتريبل باي. تحيط به مشاهد البحر الأحمر الآسرة، وجبال الحجاز العريقة، وتظلّله سماء لا نهائية مرصّعة بالنجوم. صُمِّمت كل التفاصيل فيه لترتقي بالتجربة بدءًا من تقنيات النوم المدعومة علميًا وبرامج نادي اللياقة المصممة بدقة، وصولًا إلى برامج الاستشفاء المتنوعة وتجارب الطهي المُلهمة.</p> <p>هذا ليس مجرد منتجع، بل منظومة متكاملة صُمِّمت لتدفعك نحو التجديد دائمًا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97954745-68196290.jpg?v=1788820120"]','https://cmsphoto.ww-cdn.com/resizeapi/162f273630292a38a86bb3b0005de99d65dd18b7/480/',26.6491365,36.2153564,'J6X8+M45 Al Wajh Tabuk Province','+966 11222 2222','https://www.visitredsea.com/ar/resorts/equinox','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97954745/mntgaa-akoynoks-amala',1,0,'منتجع اكوينوكس امالا اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97863223,'umluj','أدرينا','Adrena Beach Club','adrena-beach-club-adryna','["أماكن سياحية"]','["sights"]','أدرينا منطقة مغامرات ورياضات مائية وبرية تابعة للبحر الأحمر الدولية، تبعد 20 دقيقة عن جزر شورى، وتقدم أكثر من 24 نشاطًا ترفيهيًا وحيويًا لعشاق الإثارة.','<div class="texte" > <div> <div> <div data-cmp-data-layer="{&quot;text-d234b3a470&quot;:{&quot;@type&quot;:&quot;redsea-rsc/components/text&quot;,&quot;repo:modifyDate&quot;:&quot;2026-03-15T11:15:40Z&quot;,&quot;xdm:text&quot;:&quot;&lt;p&gt;تفتح شركة &amp;quot;البحر الأحمر الدولية&amp;quot; آفاقاً غير مسبوقة للإثارة والترفيه تحت مسمى &amp;quot;أدرينا&amp;quot;. وهي منطقة متخصصة للمغامرة صُممت لتقدم تجارب رياضية وحيوية تفيض بالتشويق، ممتدة عبر كافة وجهات الشركة الرائدة.&lt;/p&gt;\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\r\n&quot;}}" id="text-d234b3a470"> <p>تفتح شركة "البحر الأحمر الدولية" آفاقاً غير مسبوقة للإثارة والترفيه تحت مسمى "أدرينا". وهي منطقة متخصصة للمغامرة صُممت لتقدم تجارب رياضية وحيوية تفيض بالتشويق، ممتدة عبر كافة وجهات الشركة الرائدة.</p> <p>&nbsp;</p> </div> </div> </div> <div> <div> <div data-cmp-data-layer="{&quot;text-093314d5af&quot;:{&quot;@type&quot;:&quot;redsea-rsc/components/text&quot;,&quot;repo:modifyDate&quot;:&quot;2026-03-15T11:15:47Z&quot;,&quot;xdm:text&quot;:&quot;&lt;p&gt;&lt;br&gt;\r\nوتعد &amp;quot;أدرينا&amp;quot; كوجهة مستقلة بذاتها، حيث تقع على بُعد 20 دقيقة فقط من منتجعات جزيرة &amp;quot;شورى&amp;quot; الأحد عشر. وتتخذ مكانها وسط الطبيعة البكر لساحل البحر الأحمر، ممتدة على مساحة فسيحة تعادل 16 ملعباً لكرة القدم. كما تقدم &amp;quot;أدرينا&amp;quot; 24 نشاطاً استثنائياً صُممت لتناغم إيقاع الليل والنهار، وتلبي تطلعات الزوار باختلاف اهتماماتهم في أجواء تناسب الجميع.&lt;/p&gt;\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\r\n&lt;p&gt;استُلهم اسم &amp;quot;أدرينا&amp;quot; من تمازج الأدرينالين (Adrenaline) برحابة الساحة (Arena) وتحقيق الحلم (Dream)، لتجسد روح الحركة والخيال. وتدار &amp;quot;أدرينا&amp;quot; وتشغل من قبل &amp;quot;البحر الأحمر للرياضة والترفيه&amp;quot;، وهي شركة تابعة لشركة &amp;quot;البحر الأحمر الدولية&amp;quot; وتقف خلف علاماتنا الرائدة &amp;quot;واما&amp;quot; و&amp;quot;جالاكسيا&amp;quot; و&amp;quot;أكون&amp;quot;.&lt;/p&gt;\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\r\n&lt;p&gt;ينغمس الضيوف هنا في تجارب برية ومائية فريدة؛ من ركوب الأمواج والتزلج على الماء، إلى القفز من المنحدرات والرياضات الحيوية، في أنشطة صُممت بعناية لتكون احتفاءً بروح البحر الأحمر المتجددة وعلاقتنا الأبدية بمياهه الصافية.&lt;/p&gt;\r\n&quot;}}" id="text-093314d5af"> <p><br /> وتعد "أدرينا" كوجهة مستقلة بذاتها، حيث تقع على بُعد 20 دقيقة فقط من منتجعات جزيرة "شورى" الأحد عشر. وتتخذ مكانها وسط الطبيعة البكر لساحل البحر الأحمر، ممتدة على مساحة فسيحة تعادل 16 ملعباً لكرة القدم. كما تقدم "أدرينا" 24 نشاطاً استثنائياً صُممت لتناغم إيقاع الليل والنهار، وتلبي تطلعات الزوار باختلاف اهتماماتهم في أجواء تناسب الجميع.</p> <p>&nbsp;</p> <p>استُلهم اسم "أدرينا" من تمازج الأدرينالين (Adrenaline) برحابة الساحة (Arena) وتحقيق الحلم (Dream)، لتجسد روح الحركة والخيال. وتدار "أدرينا" وتشغل من قبل "البحر الأحمر للرياضة والترفيه"، وهي شركة تابعة لشركة "البحر الأحمر الدولية" وتقف خلف علاماتنا الرائدة "واما" و"جالاكسيا" و"أكون".</p> <p>&nbsp;</p> <p>ينغمس الضيوف هنا في تجارب برية ومائية فريدة؛ من ركوب الأمواج والتزلج على الماء، إلى القفز من المنحدرات والرياضات الحيوية، في أنشطة صُممت بعناية لتكون احتفاءً بروح البحر الأحمر المتجددة وعلاقتنا الأبدية بمياهه الصافية.</p> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97863223-68118079.jpg?v=1788123719"]','https://cmsphoto.ww-cdn.com/resizeapi/f00e9d471731c1249e3cde3e040931a67adf9bc9/480/',25.5269091,36.9996095,'GXGX+QR Hanak Umluj','','https://www.redseaglobal.com/ar/portfolio/projects/adrena/','','https://www.saudi-guide.com/umluj/i/97863223/adrena-beach-club-adryna',1,0,'ادرينا adrena beach club اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97835166,'umluj','منتجع روزوود، أمالا','Rosewood AMAALA','rosewood-amaala-mntgaa-rozood-amala','["أماكن سياحية"]','["sights"]','في قلب وجهة الاستشفاء الأولى في السعودية، يقدّم روزوود أمالا تجربة مستوحاة من إيقاع البحر الأحمر وهدوء شواطئه، تمزج جذور الثقافة العربية بالفن.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div data-testid="header-section-description"> <p>في قلب وجهة الاستشفاء الأولى في المملكة العربية السعودية، يقدّم روزوود أمالا تجربة مستوحاة من إيقاع البحر الأحمر وهدوء شواطئه. تمتزج فيه جذور الثقافة العربية مع الفن وروح المكان في أجواء صُممت للتجدد.</p> </div> </div> <div aria-label="Carousel" data-testid="cards-resort-details-carousel" dir="rtl" role="button" tabindex="0"> <div dir="rtl"> <div data-testid="carousel-slide-0"> <div data-testid="carousel-slide-0-wrapper-content"> <div aria-label="عنصر السلايدر 1" data-testid="carousel-slide-0-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97835166-68101506.jpg?v=1787862595", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97835166-68101491.jpg?v=1787862550", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97835166-68101502.jpg?v=1787862575"]','https://cmsphoto.ww-cdn.com/resizeapi/35af33403b20d931e57abf5672f6208c544af65e/480/',26.6319949,36.2278278,'Rosewood AMAALA - منتجع روزوود، أمالا','+966 11222 2222','https://www.visitredsea.com/ar/resorts/rosewood','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97835166/rosewood-amaala-mntgaa-rozood-amala',1,0,'منتجع روزوود امالا rosewood amaala اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97835128,'umluj','منتجع دارة','Daraah Resort - AMAALA','daraah-resort-amaala-mntgaa-dar','["أماكن سياحية"]','["sights"]','يقع منتجع دارة بين بحيرة هادئة ومياه البحر المفتوحة في تريبل باي بأمالا، ويوفر تجارب طهي متميزة وجلسات سبا ونادٍ رياضيًا متكاملًا، بلمسات من تراث تبوك الساحلي.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div data-testid="header-section-description"> <p>يقع منتجع دارة بين بحيرة هادئة ومياه البحر المفتوحة، ليقدم ملاذاً ساحلياً متوازناً في تريبل باي. يمكن للضيوف الاستمتاع بعالم من تجارب الطهي المتميزة وجلسات السبا الاستشفائية، أو الحفاظ على نشاطهم في النادي الشاطئي والمركز الرياضي المتكامل الذي يضم ملاعب البادل والتنس وجهاز محاكاة الجولف. وبينما يوفر المنتجع أجواءً من السكينة، فإنه يبعد 18 دقيقة فقط بالسيارة عن مركز الحياة البحرية كوراليوم ونادي أمالا لليخوت. وتكتمل هذه التجربة بالحفاوة السعودية الأصيلة، مع لمسات مستوحاة من التراث الساحلي العريق في منطقة تبوك.</p> </div> </div> <div aria-label="Carousel" data-testid="cards-resort-details-carousel" dir="rtl" role="button" tabindex="0"> <div dir="rtl"> <div data-testid="carousel-slide-0"> <div data-testid="carousel-slide-0-wrapper-content"> <div aria-label="عنصر السلايدر 1" data-testid="carousel-slide-0-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97835128-68101456.jpg?v=1787862273", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97835128-68101473.jpg?v=1787862321"]','https://cmsphoto.ww-cdn.com/resizeapi/40c6a9c5a799b96729d79802a8b13c6e7daca595/480/',26.726285,36.1271632,' Triple Bay Amaala Amaala','+966 11222 2222','https://www.visitredsea.com/ar/resorts/daraah-resort','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97835128/daraah-resort-amaala-mntgaa-dar',1,0,'منتجع داره daraah resort amaala اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97835049,'umluj','منتجع Six Senses، أمالا','Six Senses AMAALA','six-senses-amaala-mntgaa-six-senses-amala','["أماكن سياحية"]','["sights"]','يفتح Six Senses أمالا أبوابه لضيوفه على وقع نسيم البحر ودفء الشمس، بنهج مميز في الضيافة الحدسية والاستشفاء، وأجنحة وفلل راقية وسط الطبيعة.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div data-testid="header-section-description"> <p>بإيقاع هادئ ينعش الروح وتجارب تثري الحواس، يفتح&nbsp; Six Senses أمالا أبوابه لضيوفه من جميع الأجيال، داعياً إياهم إلى التمهّل، وإعادة التواصل مع الطبيعة، واستعادة التوازن في قلب المشهد الساحلي الآسر لوجهة أمالا، على وقع نسيم البحر ودفء الشمس. ومن خلال نهجه المميّز في الضيافة الحدسية والاستشفاء، يقدّم&nbsp; Six Senses أمالا تجربة شاملة تنسج بين رحابة الأجنحة والفلل، والتجارب المتنوعة، والارتباط العميق بالطبيعة المحيطة، في تناغم فريد.</p> </div> </div> <div aria-label="Carousel" data-testid="cards-resort-details-carousel" dir="rtl" role="button" tabindex="0"> <div dir="rtl"> <div data-testid="carousel-slide-0"> <div data-testid="carousel-slide-0-wrapper-content"> <div aria-label="عنصر السلايدر 1" data-testid="carousel-slide-0-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97835049-68101427.jpg?v=1787861914", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97835049-68101431.jpg?v=1787861998"]','https://cmsphoto.ww-cdn.com/resizeapi/7097c4c71dfcedc6f154b0f75cf72a5c4e84751e/480/',26.640382,36.2314835,' SA الوجه','+966 11222 2222','https://www.visitredsea.com/ar/resorts/six-senses-amaala','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97835049/six-senses-amaala-mntgaa-six-senses-amala',1,0,'منتجع six senses امالا six senses amaala اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97834999,'umluj','منتجع ومساكن فور سيزونز، أمالا','Four Seasons Resort and Residences AMAALA at Triple Bay','four-seasons-resort-and-residences-amaala-triple-bay-mntgaa-omsakn-syzonz-amala','["أماكن سياحية"]','["sights"]','منتجع ومساكن فور سيزونز أمالا ملاذ ساحلي يجمع بين الرفاهية الراقية والطبيعة الساحرة، بإطلالات خلابة وتجارب استشفاء ومطاعم راقية.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div data-testid="header-section-description"> <p>اكتشف منتجع ومساكن فور سيزونز أمالا، الملاذً الساحلي الإستثنائي الذي يجمع بين الرفاهية الراقية والطبيعة الساحرة. من الإطلالات الخلابة وتجارب الاستشفاء المتجددة إلى المطاعم الراقية والخدمة الاستثنائية، صُممت كل لحظة لتمنحك تجربة إقامة فاخرة لا تُنسى.&nbsp;</p> </div> </div> <div aria-label="Carousel" data-testid="cards-resort-details-carousel" dir="rtl" role="button" tabindex="0"> <div dir="rtl"> <div data-testid="carousel-slide-0"> <div data-testid="carousel-slide-0-wrapper-content"> <div aria-label="عنصر السلايدر 1" data-testid="carousel-slide-0-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97834999-68101402.jpg?v=1787861603", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97834999-68101355.jpg?v=1787861298", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97834999-68101357.jpg?v=1787861331"]','https://cmsphoto.ww-cdn.com/resizeapi/d908e1812d6cae1f6e67d327420c7752776b66cf/480/',26.6474433,36.218858,' Amaala Building 8491 Secondary 3110 An Nu’Aylah','+966 11222 2222','https://www.visitredsea.com/ar/resorts/four-seasons-resort-and-residences-amaala','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97834999/four-seasons-resort-and-residences-amaala-triple-bay-mntgaa-omsakn-syzonz-amala',1,0,'منتجع ومساكن فور سيزونز امالا four seasons resort and residences amaala at triple bay اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97828149,'umluj','منتجع فورسيزونز البحر الأحمر','Four Seasons Resort and Residences Red Sea at Shura Island','four-seasons-resort-and-residences-red-sea-shura-island-mntgaa-forsyzonz-albhr-alahmr','["أماكن سياحية"]','["sights"]','منتجع فورسيزونز البحر الأحمر يجمع بين الطبيعة النقية والأناقة العصرية على جزيرة شورى، بغرف مطلة على البحر ومطاعم راقية وتجارب عائلية فريدة.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div data-testid="header-section-description"> <p>في منتجع فورسيزونز البحر الأحمر تأخذك التفاصيل الفخمة في رحلة بين الطبيعة النقية والأناقة العصرية: ابتداءًا من الغرف المُطلة على البحر، والمطاعم الراقية إلى التجارب العائلية الفريدة، كل ذلك وأكثر وسط أجواء جزيرة شورى النابضة بالحياة.</p> </div> </div> <div aria-label="Carousel" data-testid="cards-resort-details-carousel" dir="rtl" role="button" tabindex="0"> <div dir="rtl"> <div data-testid="carousel-slide-0"> <div data-testid="carousel-slide-0-wrapper-content"> <div aria-label="عنصر السلايدر 1" data-testid="carousel-slide-0-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97828149-68096236.jpg?v=1787816065", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97828149-68096240.jpg?v=1787816108"]','https://cmsphoto.ww-cdn.com/resizeapi/e3d31d63825ddbfa451403eb39912bc197b0bf84/480/',25.4951423,36.9825391,' Red Sea Project Hanak','+966 11222 2222','https://www.visitredsea.com/ar/resorts/four-seasons-shura','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97828149/four-seasons-resort-and-residences-red-sea-shura-island-mntgaa-forsyzonz-albhr-alahmr',1,0,'منتجع فورسيزونز بحر احمر four seasons resort and residences red sea at shura island اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97828140,'umluj','منتجع ميرافال البحر الأحمر','Miraval The Red Sea','miraval-red-sea-mntgaa-myrafal-albhr-alahmr','["أماكن سياحية"]','["sights"]','يقع ميرافال البحر الأحمر على شواطئ جزيرة شورى، وهو منتجع فاخر بنظام الإقامة الشاملة مخصص للبالغين، قائم على مفاهيم العافية والتوازن، تحيط به البحيرات والكثبان الساحلية.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div> <div data-testid="header-section-description"> <p>يقع ميرافال البحر الأحمر على شواطئ جزيرة شورى الهادئة، وهو منتجع فاخر بنظام الإقامة الشاملة مخصّص للبالغين فقط (+18)، قائم على مفاهيم العافية والحضور الواعي والتوازن. ينسجم تصميم المنتجع بانسيابية مع محيطه الطبيعي، حيث تحيط به البحيرات الساحلية والشواطئ الممتدة والكثبان الرملية، ليهيّئ لضيوفه مساحة للتأمل والتجدّد.</p> <p>&nbsp;</p> <p>ومن خلال تجارب العافية الغامرة والمساحات المصمّمة بعناية التي يوفّرها ميرافال، تصبح كل إقامة فرصة لاكتشاف الذات، وتعميق التواصل معها ومع الطبيعة، وعيش اللحظة بوعي، في تناغم مع الإيقاع الهادئ للبحر الأحمر.</p> </div> </div> </div> <div aria-label="Carousel" data-testid="cards-resort-details-carousel" dir="rtl" role="button" tabindex="0"> <div> <div dir="rtl"> <div data-testid="carousel-slide-0"> <div data-testid="carousel-slide-0-wrapper-content"> <div aria-label="عنصر السلايدر 1" data-testid="carousel-slide-0-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> <div data-testid="carousel-slide-1"> <div data-testid="carousel-slide-1-wrapper-content"> <div aria-label="عنصر السلايدر 2" data-testid="carousel-slide-1-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> <div data-testid="carousel-slide-2"> <div data-testid="carousel-slide-2-wrapper-content"> <div aria-label="عنصر السلايدر 3" data-testid="carousel-slide-2-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> <div data-testid="carousel-slide-3"> <div data-testid="carousel-slide-3-wrapper-content"> <div aria-label="عنصر السلايدر 4" data-testid="carousel-slide-3-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> <div data-testid="carousel-slide-4"> <div data-testid="carousel-slide-4-wrapper-content"> <div aria-label="عنصر السلايدر 5" data-testid="carousel-slide-4-card" role="button" tabindex="0"> <div>&nbsp;</div> </div> </div> </div> </div> </div> <div aria-label="Carousel" data-testid="carousel-paginator" role="navigation"><button aria-disabled="false" aria-label="زر العنصر السابق في السلايدر" data-testid="carousel-paginator-prev-btn"></button></div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97828140-68096206.jpg?v=1787815809"]','https://cmsphoto.ww-cdn.com/resizeapi/01dde3fe19b3fcf6ef00145b79dd8e72801985bf/480/',25.5010959,36.9702218,'Shura Island Umluj Umluj','+966 11222 2222','https://www.visitredsea.com/ar/resorts/miraval-the-red-sea','info@visitredsea.com','https://www.saudi-guide.com/umluj/i/97828140/miraval-red-sea-mntgaa-myrafal-albhr-alahmr',1,0,'منتجع ميرافال بحر احمر miraval the red sea اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97056806,'albaha','سوق السبت التاريخي','Saturday Market Street','saturday-market-street-sok-alsbt-altarykhy','["أماكن سياحية", "أسواق"]','["shopping", "sights"]','سوق السبت التاريخي في بلجرشي من أقدم وأكبر الأسواق الشعبية في الباحة، يُقام منذ نحو أربعة قرون ويعرض الحرف اليدوية والعسل والمنتجات المحلية.','<div class="texte" > <p data-original-size="16px">في قلب محافظة بلجرشي، يقف سوق السبت التاريخي كواحد من أقدم وأكبر الأسواق الشعبية في منطقة الباحة، محافظًا على روحه وتفاصيله الأصيلة منذ قرون. لا يُعد هذا السوق مجرد مكان للتسوّق، بل هو معلم ثقافي حي يوثّق ملامح الحياة اليومية والتقاليد التي توارثها الأهالي عبر الأجيال.</p> <p data-original-size="16px">تتسلل إليك رائحة الأعشاب العطرية وأصوات الباعة وأنت تتجوّل بين أروقة السوق الضيقة، حيث تُعرض المشغولات اليدوية، والأقمشة التقليدية، والمنتجات المحلية، والأدوات التراثية — كل ركن هنا يحكي قصة من الزمن الجميل.</p> <p data-original-size="16px">بمعماره الشعبي وأجوائه الدافئة وهويته الصادقة، يدعوك السوق إلى رحلة حسية متكاملة تعبّر عن عمق التراث وروح الجنوب</p> </div>  <div class="texte" > <p>يُقام السوق في موقعه ذاته منذ نحو أربعة قرون، ويضم متحفاً صغيراً ومحلات للمشغولات اليدوية والعسل المحلي الذي تشتهر به منطقة الباحة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97056806-67630660.jpg?v=1781953554"]','https://cmsphoto.ww-cdn.com/resizeapi/9b66f90266118a957a8175dee2718718ce052a37/480/',19.8601451,41.5600898,'Saturday Market St Baljurshi Baljurashi','','https://www.visitsaudi.com/ar/al-baha/attractions/saturday-heritage-market','','https://www.saudi-guide.com/albaha/i/97056806/saturday-market-street-sok-alsbt-altarykhy',1,0,'سوق سبت تاريخي saturday market street اماكن سياحيه اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (97042223,'medina','قلعة قباء التاريخية','Historical Quba Castle','historical-quba-castle-klaa-kba-altarykhy','["التراث والثقافة"]','["heritage"]','قلعة قباء التاريخية بحي الدويمة بالمدينة المنورة، حصن دفاعي يزيد عمره على 100 عام، كان يحرس طريق الحجاج ويشرف على منطقة قباء.','<div class="texte" > <p>تقع قلعة قباء التاريخية على تلة صغيرة في حي الدويمة بالمدينة المنورة، بالقرب من مسجد قباء، ويعود تاريخ بنائها إلى أكثر من 100 عام حيث شُيّدت لتكون نقطة حراسة تُشرف على طريق الحجاج القادمين إلى المدينة المنورة وتحمي المنطقة من هجمات القبائل واللصوص.</p> <p>تعكس القلعة رحلة التحوّل من الدفاع إلى السلام عبر تاريخ المدينة، وتُعد اليوم من أبرز المعالم التراثية التي تحرص الهيئة العامة للسياحة والتراث الوطني على ترميمها والحفاظ عليها ضمن مسارات المدينة التاريخية، وتقصدها فئة من الزوار المهتمين بالآثار وتاريخ المدينة المنورة.</p> <p>تُعد منطقة قباء بشكل عام من أبرز المواقع التاريخية في المدينة المنورة، وترتبط بالعديد من الأحداث الإسلامية المهمة منذ عهد النبي صلى الله عليه وسلم، وتمثل جزءًا مهمًا من الهوية التاريخية والثقافية للمدينة. كما تتميز المنطقة بقربها من عدد من المواقع الإسلامية المعروفة، مما يجعلها محطة مهمة ضمن مسارات الزيارة والسياحة الثقافية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97042223-68551557.jpg?v=1791633836"]','https://cmsphoto.ww-cdn.com/resizeapi/de8dd953d45709612219c23cabc14b5954aee5cb/480/',24.4475237,39.6127381,'منطقة قباء، المدينة المنورة، المملكة العربية السعودية','','https://www.visitsaudi.com/ar/madinah/attractions/historical-quba-castle','','https://www.saudi-guide.com/medina/i/97042223/historical-quba-castle-klaa-kba-altarykhy',1,0,'قلعه قباء تاريخيه historical quba castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (96824542,'alula','مكتبة العلا العامة','AlUla Public Library','alula-public-library','["التراث والثقافة"]','["heritage"]','مركز ثقافي واجتماعي يستقبل الضيوف من جميع الأعمار في عمارة تقليدية بحي الجديدة للفنون، يضم قاعات للمطالعة ومناطق للأطفال ومقهى مطل على المبنى.','<div class="texte" > <div> <div id="5555"> <div> <div data-cmp-data-layer="{&quot;W4&quot;:{&quot;@type&quot;:&quot;rcudxp/components/ea/content/title&quot;,&quot;repo:modifyDate&quot;:&quot;2025-09-22T19:04:26Z&quot;,&quot;dc:title&quot;:&quot;مركز ثقافي واجتماعي يستقبل الضيوف من جميع الأعمار مع مكتبة عامة ومقهى &quot;}}" data-track-click-rte="" id="W4"> <h3>مركز ثقافي واجتماعي يستقبل الضيوف من جميع الأعمار مع مكتبة عامة ومقهى</h3> <div>&nbsp;</div> </div> </div> <div> <section data-cmp-is="overview-component" id="overview-component"> <div data-cmp-copytext="copytext">تتألّق مكتبة العلا العامة ضمن عمارة تقليدية مُرممة حديثاً في حي الجديدة للفنون، ويجمع أرشيفها بين الكتب والأعمال الفكرية المناسبة لجميع الاهتمامات، والمطبوعة بمختلف اللغات. تتضمن المكتبة عدداً كبيراً من قاعات المطالعة بالإضافة إلى المناطق المُخصصة للأطفال، والجلسات المريحة على سطح المبنى، فضلاً عن المقهى المثالي للاستمتاع بالمشروبات المتنوّعة مع الأصدقاء. وجهة مثالية لقراءة الروايات الأدبية، والمشاركة في ندوات الكُتّاب والقُرّاء، وحضور النشاطات والفعاليات المُقامة بشكل منتظم.</div> </section> </div> </div> </div> <div> <div id="container-6377bbd29f"> <div> <div> <div data-index="0"> <div> <div data-alt="أرشيف المكتبة" data-cmp-is="contentblock" data-cmp-open-modal="false" data-modal-desktop-image="/content/dam/rcudxp/global/places-to-go/alula-library/hero/hero/library-hero-03.jpg" data-modal-mobile-image="/content/dam/rcudxp/global/places-to-go/alula-library/hero/hero/library-hero-03.jpg" data-modal-tablet-image="/content/dam/rcudxp/global/places-to-go/alula-library/hero/hero/library-hero-03.jpg" data-track-click-section=""> <div data-cmp-is="media-container" data-cmp-open-modal="false">&nbsp;</div> </div> </div> </div> </div> </div> </div> </div> <source media="(min-width: 1024px)" srcset="https://s7g10.scene7.com/is/image/rcu/library-hero-03?$Responsive$&amp;fit=stretch&amp;fmt=webp&amp;wid=1920" /><source media="(min-width: 765px)" srcset="https://s7g10.scene7.com/is/image/rcu/library-hero-03?$Responsive$&amp;fit=stretch&amp;fmt=webp&amp;wid=820" /><source media="(min-width: 1px)" srcset="https://s7g10.scene7.com/is/image/rcu/library-hero-03?$Responsive$&amp;fit=stretch&amp;fmt=webp&amp;wid=410" /> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/96824542-67491794.jpg?v=1780443632"]','https://cmsphoto.ww-cdn.com/resizeapi/0e7b2c9578b4007ef5dd9cca0483586e02405db3/480/',26.6298203,37.9117797,'8042 شارع الربوة Al Ula','','https://www.experiencealula.com/ar/places-to-go/alula-library','','https://www.saudi-guide.com/alula/i/96824542/alula-public-library',1,0,'مكتبه علا عامه alula public library تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (96700967,'asir-region','منتزه دلغان','Dalaghan Park','dalaghan-park','["أماكن سياحية"]','["sights"]','منتزه دلغان وجهة طبيعية مميزة للعائلات والباحثين عن الاسترخاء، يضم مسارات للمشي والجري ومناطق للنزهات وألعاباً للأطفال ومرافق خدمية مريحة.','<div class="texte" > <h2>نبذة عن منتزه دلغان</h2> <p>منتزه دلغان هو وجهة سياحية مميزة تقع في قلب الطبيعة، ويعتبر مكانًا مثاليًا للعائلات والأفراد الباحثين عن الاسترخاء والاستمتاع بجمال الطبيعة. يتميز المنتزه بتنوعه البيئي، حيث يضم العديد من الأشجار الخضراء والنباتات المحلية التي تضفي على المكان جمالاً وهدوءًا.</p> <h3>المرافق والخدمات</h3> <ul> <li>مسارات للمشي والجري في وسط الطبيعة.</li> <li>أماكن مخصصة للنزهات مع طاولات وكراسي.</li> <li>مناطق مخصصة للألعاب للأطفال.</li> <li>خدمات مريحة مثل دورات المياه والمواقف للزوار.</li> </ul> <h3>الأنشطة المتاحة</h3> <p>يمكن للزوار الاستمتاع بمجموعة متنوعة من الأنشطة في منتزه دلغان، بما في ذلك:</p> <ul> <li>التنزه والاستكشاف.</li> <li>ركوب الدراجات في المسارات المخصصة.</li> <li>تنظيم حفلات الشواء في المناطق المحددة.</li> <li>التقاط صور للمناظر الخلابة والنباتات.</li> </ul> <p>يعتبر منتزه دلغان مكانًا مثاليًا للهروب من صخب الحياة اليومية والتمتع بأوقات ممتعة في أحضان الطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/96700967-67405462.jpg?v=1779638542"]','https://cmsphoto.ww-cdn.com/resizeapi/03ab39b949bbf6f40c591740125b291c425b9165/480/',18.1013689,42.7051666,'4P24+G3V Al Fara Aseer Province','','https://www.visitsaudi.com/ar/aseer/attractions/dalaghan-park','','https://www.saudi-guide.com/asir-region/i/96700967/dalaghan-park',1,0,'منتزه دلغان dalaghan park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (96700901,'abha','مزرعة ركايب','Rakayb Farm','rakayb-farm-mzraa-rkayb','["أماكن سياحية"]','["sights"]','مزرعة ركايب في أبها ملاذ ريفي هادئ بإطلالات بانورامية وجلسات عائلية مفتوحة وسط المساحات الخضراء والحقول، لتجربة تجمع بساطة الريف ودفئه.','<blockquote class="instagram-media" data-instgrm-captioned data-instgrm-permalink="https://www.instagram.com/reel/DYc-SFJtfKK/?utm_source=ig_embed&utm_campaign=loading" data-instgrm-version="14"><div> <a href="https://www.instagram.com/reel/DYc-SFJtfKK/?utm_source=ig_embed&utm_campaign=loading" target="_blank"> <div> <div></div> <div> <div></div> <div></div></div></div><div></div> <div><svg width="50px" height="50px" viewBox="0 0 60 60" version="1.1" xmlns="https://www.w3.org/2000/svg" xmlns:xlink="https://www.w3.org/1999/xlink"><g stroke="none" stroke-width="1" fill="none" fill-rule="evenodd"><g transform="translate(-511.000000, -20.000000)" fill="#000000"><g><path d="M556.869,30.41 C554.814,30.41 553.148,32.076 553.148,34.131 C553.148,36.186 554.814,37.852 556.869,37.852 C558.924,37.852 560.59,36.186 560.59,34.131 C560.59,32.076 558.924,30.41 556.869,30.41 M541,60.657 C535.114,60.657 530.342,55.887 530.342,50 C530.342,44.114 535.114,39.342 541,39.342 C546.887,39.342 551.658,44.114 551.658,50 C551.658,55.887 546.887,60.657 541,60.657 M541,33.886 C532.1,33.886 524.886,41.1 524.886,50 C524.886,58.899 532.1,66.113 541,66.113 C549.9,66.113 557.115,58.899 557.115,50 C557.115,41.1 549.9,33.886 541,33.886 M565.378,62.101 C565.244,65.022 564.756,66.606 564.346,67.663 C563.803,69.06 563.154,70.057 562.106,71.106 C561.058,72.155 560.06,72.803 558.662,73.347 C557.607,73.757 556.021,74.244 553.102,74.378 C549.944,74.521 548.997,74.552 541,74.552 C533.003,74.552 532.056,74.521 528.898,74.378 C525.979,74.244 524.393,73.757 523.338,73.347 C521.94,72.803 520.942,72.155 5