INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59088165,'riyadh','فزز هوا Fizz Hawa','','fizz-hawa-riyadh','["ترفيه واستجمام"]','["fun"]','فزز هوا بالرياض، مركز ترفيهي يقدم ألعاباً وأنشطة ممتعة للأطفال والعائلات.','<div class="texte" > <p>تجربة مبتكرة ومصممة لتناسب جميع أفراد العائلة، بالإضافة إلى العديد من الألعاب الهوائية كـ عقبات النينجا، الويب آوت، كرة المناورة، جدار التسلق، والقفز الحر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59088165-43913473.jpg?v=1635441808"]','https://cmsphoto.ww-cdn.com/resizeapi/540e1d223a2c38e40c99d7fcbe90b27d635d698c/480/',24.8183348,46.7814652,'3390 Dammam Rd Mounsiah','','','','https://www.saudi-guide.com/riyadh/i/59088165/fizz-hawa-riyadh',1,0,'فزز هوا fizz hawa ترفيه واستجمام',strftime('%s','now'));
