INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59087936,'riyadh','بوليفارد الرياض','Riyadh Boulevard','riyadh-boulevard','["أماكن سياحية"]','["sights"]','بوليفارد الرياض، مشروع ترفيهي ضخم بمساحة 20 ألف متر مربع، يضم فندقًا بخمس نجوم ومساحات تجارية ورصيف طولي 500 متر.','<div class="texte" > <p>يعتبر مشروع&nbsp; بوليفارد الرياض بمثابة مجمع تجاري مفتوح في الهواء الطلق بمساحة 20 ألف متر مربع، يضم المشروع فندقاً بخدمات خمس نجوم&nbsp;بالإضافة إلى مساحات تجارية خارجية مخصصة للمطاعم والمقاهي العالمية بإطلالة على حدائق ومسطحات مائية مصممة بشكل فني أنيق ومزودة بخدمة صف السيارات و خدمة كبار الشخصيات،&nbsp;كما يضم المشروع رصيف طولي للمشي بطول 500 متربالإضافة إلى نادي صحي ومكاتب تجارية فاخرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59087936-43576529.jpg?v=1633038350"]','https://cmsphoto.ww-cdn.com/resizeapi/bcb96a83c66ff2dd64e77fe5d8f5ff72b17d7d19/480/',24.7636336,46.6032994,'طريق الأمير تركي بن عبدالعزيز الأول، Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59087936/riyadh-boulevard',1,0,'بوليفارد رياض riyadh boulevard اماكن سياحيه',strftime('%s','now'));
