INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049912,'riyadh','دون روبن','Don Ruben''s','don-rubens-don-robn','["مطاعم"]','["food"]','دون روبن تجربة مكسيكية أصيلة داخل الحي الدبلوماسي، ويُعد من أفضل المطاعم المكسيكية في الرياض بشهادة الزوار.','<div class="texte" > <p>دون روبن تجربة مكسيكية أصيلة داخل الحي الدبلوماسي، ويُعد من أفضل المطاعم المكسيكية في الرياض بشهادة الزوار. يشتهر ببوريتو اللحم وتاكو البيريا، ويتميز بموقعه الهادئ وأجوائه الموسيقية التي تنقلك إلى المكسيك. للتواصل أو الحجز: 0502929307، ومواعيد الدوام من 12:00 ظهرًا حتى 10:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049912-68541876.jpg?v=1791537919", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049912-68541877.jpg?v=1791537940"]','https://cmsphoto.ww-cdn.com/resizeapi/90d31b2f895df896a718092822c109a1dbf98546/480/',24.6859526,46.6259041,'9163 شارع العين، السفارات، الرياض 12523','0502929307','','','https://www.saudi-guide.com/riyadh/i/98049912/don-rubens-don-robn',1,0,'دون روبن don ruben''s مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049911,'riyadh','طوكيو','Tokyo','tokyo-tokyo','["مطاعم"]','["food"]','طوكيو أول مطعم ياباني افتُتح في الرياض، ويقدم تشكيلة مبتكرة من الأطباق الشهية التي جمعت بين الأصالة اليابانية والتقديم العصري.','<div class="texte" > <p>طوكيو أول مطعم ياباني افتُتح في الرياض، ويقدم تشكيلة مبتكرة من الأطباق الشهية التي جمعت بين الأصالة اليابانية والتقديم العصري. يشتهر بسلطة السلطعون المقرمشة وتاكو اللوبستر وأطباق الروبيان المميزة، ويحظى بسمعة راسخة كأحد رواد المطبخ الياباني في المدينة. للتواصل أو الحجز: 920009662، ومواعيد الدوام من 12:30 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049911-68551641.jpg?v=1791634487", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049911-68551644.jpg?v=1791634496"]','https://cmsphoto.ww-cdn.com/resizeapi/a76f4927017c7012b5f68a4164a8df5b23da7285/480/',24.7181459,46.6867051,'طريق العروبة، الورود، الرياض 12245','920009662','','','https://www.saudi-guide.com/riyadh/i/98049911/tokyo-tokyo',1,0,'طوكيو tokyo مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049910,'riyadh','ناك','NAC','nac-nak','["مطاعم"]','["food"]','ناك (NAC) مطعم فريد في أم الحمام الغربي يقدم نكهات عالمية بجودة متميزة، ويشتهر بالباستا الوردية والبيض التركي بديكور أنيق.','<div class="texte" > <p>NAC ينغمس في النكهات العالمية المقدمة بجودة متميزة في هذا المطعم الفريد الواقع في أم الحمام الغربي. يشتهر بأطباق الباستا الوردية والمكرونة والجبن بالترافل والبيض التركي، بديكور أنيق يناسب الغداء أو السهرة المسائية. مواعيد الدوام من 9:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049910-68541897.jpg?v=1791538090", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049910-68541902.jpg?v=1791538104"]','https://cmsphoto.ww-cdn.com/resizeapi/7b86677a2f3e0324b65db8ba740d060a1d6638fc/480/',24.6931346,46.6321083,'طريق الملك خالد، أم الحمام الغربي، الرياض 12329','','','','https://www.saudi-guide.com/riyadh/i/98049910/nac-nak',1,0,'ناك nac مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049907,'riyadh','ام شريف كافيه','Em Sherif Cafe','em-sherif-cafe-am-shryf-kafyh','["مطاعم"]','["food"]','ام شريف كافيه يقدم لك المأكولات اللبنانية الراقية في أجواء مذهلة داخل حي التخصصي، بامتداد من فرع "ام شريف" الشهير في بيروت.','<div class="texte" > <p>ام شريف كافيه يقدم لك المأكولات اللبنانية الراقية في أجواء مذهلة داخل حي التخصصي، بامتداد من فرع "ام شريف" الشهير في بيروت. يشتهر بالمقبلات اللبنانية المتنوعة والمعجنات الطازجة، ويحظى بشعبية كبيرة لتناول الإفطار والغداء بأجواء أنيقة تجمع بين الطابع الشرقي والحديث. للتواصل أو الحجز: 920017617، ومواعيد الدوام من 8:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049907-68541961.jpg?v=1791538370"]','https://cmsphoto.ww-cdn.com/resizeapi/333b49407c12628462774facfa3ab0b54839a0b3/480/',24.7314602,46.6494851,'التخصصي، المحمدية، الرياض 12362','920017617','','','https://www.saudi-guide.com/riyadh/i/98049907/em-sherif-cafe-am-shryf-kafyh',1,0,'ام شريف كافيه em sherif cafe مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90066405,'diriyah','تكية','TAKYA','takya','["المطاعم والمقاهي"]','["food"]','مطعم تكية في البجيري بالدرعية، يأخذك في جولة بين الأكلات السعودية التقليدية المتنوعة، تُقدَّم بأسلوب فاخر ومعاصر وبأجود المكونات.','<div class="texte" > <h2 data-content_id="e7uYpjtgqEehDWNqzZxz8A" data-testid="tagline">مزيج من تراث الأكل السعودي يُقدم على طبقٍ فاخر ومعاصر</h2> <div data-content_id="e7uYpjtgqEehDWNqzZxz8A"> <div data-testid="description"> <p>ياخذك تكية في جولة من الأكلات السعودية المتنوّعة وأطباقها التقليدية المحضّرة بأرقى المكونات والنكهات العالميّة&nbsp;</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90066405-64526439.jpg?v=1760978935", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90066405-63580900.jpg?v=1753206930"]','https://cmsphoto.ww-cdn.com/resizeapi/0950cf3f5d446f71cabde578ff0e7d61df84b40d/480/',24.736991,46.5750159,'7297 King Faisal Rd Al Bujairi','+966 55 040 2000','https://www.diriyah.sa/ar/dine/takya','','https://www.saudi-guide.com/riyadh/i/90066405/takya',1,1,'تكيه takya مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90066363,'diriyah','تاتيل','TATEL Riyadh','tatel-riyadh','["المطاعم والمقاهي"]','["food"]','مطعم تاتيل في الدرعية، ينقل روائع المطبخ الإسباني من مدريد إلى طبقك في تجربة طعام راقية تجسّد ثقافة إسبانيا العريقة ونكهاتها.','<div class="texte" > <h2 data-content_id="HXviIkXAv0G0pPAezGhDbA" data-testid="tagline">نكهة الثقافة الإسبانية تُقدم من مدريد إلى طبقك</h2> <div data-content_id="HXviIkXAv0G0pPAezGhDbA"> <div data-testid="description"> <p>تذوق روائع المطبخ الإسباني في تاتيل، أحد أفضل مطاعم العالم، حيث يُقدم تجربة طعام لا مثيل لها تُجسّد ثقافة إسبانيا العريقة.</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90066363-63580857.jpg?v=1753206642"]','https://cmsphoto.ww-cdn.com/resizeapi/399fcb2500e8b18bcb7ebda9a782e05a2c6b54aa/480/',24.7364146,46.5754563,'7227 3377 King Faisal Rd','+966 56 886 8966','https://www.diriyah.sa/ar/dine/tatel','','https://www.saudi-guide.com/diriyah/i/90066363/tatel-riyadh',1,1,'تاتيل tatel riyadh مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90066252,'diriyah','برنش آند كيك','Brunch & Cake Al Bujairi','brunch-and-cake-al-bujairi','["المطاعم والمقاهي"]','["food"]','مطعم برنش آند كيك في البجيري بالدرعية، يقدم مأكولات عضوية ونكهات مبتكرة لوجبات البرنش والحلويات في أجواء دافئة وديكورات فنية مميزة.','<div class="texte" > <h2 data-content_id="mwq-sGZLJ0-HsIvkssuC6Q" data-testid="tagline">أجواء دافئة ومرحبة ونكهات مبتكرة وتجربة لتناول الطعام الاستثنائي</h2> <div data-content_id="mwq-sGZLJ0-HsIvkssuC6Q"> <div data-testid="description"> <p>برنش آند كيك: تذوق الفن في مأكولات عضوية<br /> يقدم برنش آند كيك رحلة فنية للذوق الرفيع، حيث تتناغم الأطباق الشهية مع الديكورات الداخلية لتشكل تجربة لا تُنسى.</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90066252-63580806.jpg?v=1753206371"]','https://cmsphoto.ww-cdn.com/resizeapi/421bb9ebb2c0f8ffb89a7f5af49ef04421bc61db/480/',24.7369345,46.5742679,'البجيري الدرعية الدرعية','+966 59 265 7843','https://www.diriyah.sa/ar/dine/brunch-and-cake','','https://www.saudi-guide.com/diriyah/i/90066252/brunch-and-cake-al-bujairi',1,1,'برنش اند كيك brunch & cake al bujairi مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90066077,'diriyah','أولو','Oulu Diriyah','oulu-diriyah','["المطاعم والمقاهي"]','["food"]','مطعم أولو في البجيري بالدرعية، يقدم المأكولات الإيطالية بنكهاتها الأصيلة باستخدام مكونات طازجة في أجواء راقية وتجربة طعام فاخرة.','<div class="texte" > <h2 data-content_id="ksBWRayCvEyOAZh_qrfT6g" data-testid="tagline">أولو، النكهة الأيطالية في كل يوم</h2> <div data-content_id="ksBWRayCvEyOAZh_qrfT6g"> <div data-testid="description"> <p>"أولو إيطالي" مطعم يقدّم المأكولات الإيطالية بنكهاتها الحقيقية، باستخدام مكونات طازجة وأجواء راقية، ليمنح الزوّار تجربة طعام فاخرة.</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90066077-63580721.jpg?v=1753206083"]','https://cmsphoto.ww-cdn.com/resizeapi/711544c00aed11d256a741fd628e42d70bec16f3/480/',24.738457,46.5767084,'Imam Abdulaziz Bin Muhammad Bin Saud Al Bujairi Riyadh','+966 53 417 2244','https://www.diriyah.sa/ar/dine/oulu','','https://www.saudi-guide.com/diriyah/i/90066077/oulu-diriyah',1,1,'اولو oulu diriyah مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90066007,'diriyah','أنجلينا','Angelina Bujairi Terrace','angelina-bujairi-terrace','["المطاعم والمقاهي"]','["food"]','عش تجربة أصيلة واستمتع بألذ المخبوزات والشاي على الأصول الباريسية في مقهى أنجلينا بمطل البجيري في الدرعية.','<div class="texte" > <h2 data-content_id="JD-BCNdr90eSWXck34iqdw" data-testid="tagline">عش تجربة أصيلة، واستمتع بألذ المخبوزات والشاي على الأصول الباريسية.</h2> <div data-content_id="JD-BCNdr90eSWXck34iqdw"> <div data-testid="description"> <p>رحلة عريقة من التميز في عالم المقاهي، بدأت منذ عام 1903م في جادة دي ريفولي في باريس، لتصلك اليوم بكامل أصالتها وعراقتها من فرنسا إلى مطل البجيري.</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90066007-63580687.jpg?v=1753205851"]','https://cmsphoto.ww-cdn.com/resizeapi/cfaa82293aa005b3d9ec3bade306cc6c2b81a26d/480/',24.7371464,46.5746207,'PHPF+VXJ Al Bujairi Diriyah','+966 50 955 3788','https://www.diriyah.sa/ar/dine/angelina','','https://www.saudi-guide.com/diriyah/i/90066007/angelina-bujairi-terrace',1,1,'انجلينا angelina bujairi terrace مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90065754,'diriyah','آرتشي','ARCHI','archi','["المطاعم والمقاهي"]','["food"]','آرتشي علامة تجارية سعودية تقدّم مشروبات القهوة الساخنة والباردة عالية الجودة، إلى جانب تشكيلة من الحلويات والسندوتشات الطازجة في الدرعية.','<div class="texte" > <p>آرتشي علامة تجارية سعودية متخصصة في تقديم مشروبات القهوة الساخنة والباردة بجودة عالية، بالإضافة إلى مجموعة مختارة من الحلويات والسندوتشات الطازجة.&nbsp;<br /> <br /> تلتزم العلامة بتقديم تجربة متكاملة ترتكز على جودة المذاق ودقة التحضير.&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90065754-63580610.jpg?v=1753205436"]','https://cmsphoto.ww-cdn.com/resizeapi/94f29dd25543be31c30d958dac8dc9f06e360af9/480/',24.7366274,46.5750041,'Al Bujairi Diriyah Diriyah','+966 13 575 6664','https://www.diriyah.sa/ar/dine/archi','info@archsaudi.com','https://www.saudi-guide.com/diriyah/i/90065754/archi',1,1,'ارتشي archi مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90065533,'diriyah','إيه أوك كيتشن','AOK Kitchen Zallal','aok-kitchen-zallal','["المطاعم والمقاهي"]','["food"]','مطعم إيه أوك كيتشن الحائز على جوائز في الدرعية، خالٍ من السكر المكرر ومراعٍ للحد من الألبان والجلوتين، يقدّم تجربة طعام استثنائية.','<div class="texte" > <p>مطعم A.O.K Kitchen هو مطعم حائز على جوائز حيث يُرحب بالجميع؛ خالي من السكر المكرر ومراعي للحد من استخدام الألبان والجلوتين، مطعم لا يقتصر فقط على تلبية المتطلبات الغذائية، بل يقدم للزوار تجربة استثنائية.&nbsp;<br /> <br /> سواء كنت تزور لتناول الإفطار أو الغداء أو العشاء، هناك شيء واحد مؤكد: كل شيء سيكون على ما يرام في A.O.K.&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90065533-63580476.jpg?v=1753205002", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90065533-64526204.jpg?v=1760977503"]','https://cmsphoto.ww-cdn.com/resizeapi/c7cb562c8d1dcbdfe2ed2c0ffe41199fa2db297c/480/',24.7379753,46.5765907,'PHQG+5JP شارع عبد العزيز محمد بن سعود Al Bujairi',' +966 92 0025 304','https://www.diriyah.sa/ar/dine/aok-kitchen','','https://www.saudi-guide.com/diriyah/i/90065533/aok-kitchen-zallal',1,1,'ايه اوك كيتشن aok kitchen zallal مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90048033,'medina','مقصد قباء','Maqsad Quba','maqsad-quba','["أماكن سياحية"]','["sights"]','مقصد قباء مشروع تراثي وتنموي متكامل بجوار مسجد قباء بالمدينة المنورة، يضم قسمين رئيسيين: الأول يشمل معارض تجارية ومنطقة أطفال ومطعمًا محليًا ومركز معلومات وأزقة مفعّلة، والثاني يضم معارض تجارية وركن تجربة اللباس المديني ومنطقة ملامسة الحيوانات ونقاط تجمع سياحية وأكشاك موسمية متجددة.','<div class="texte" > <div data-original-size="14px"> <div data-original-size="14px"> <div data-habitat="C1"> <section data-original-size="14px" id="AboutSectionWrapperId"> <section data-original-size="14px"> <div data-original-size="16px"> <div data-original-size="16px"> <p>ماهو مشروع مقصد قباء؟</p> <p>مشروع ذو قيمة حضارية صمم ليكون أحد المعالم المعمارية البارزة التي تشكل إضافة جمالية للمدينة المنورة و تجربة سياحية فريدة، وصولاً إلى تحقيق الهدف الأساسي الذي يعود بالمنفعة على الفئات المستهدفة من خلال توفير الخدمات المتكاملة لزوار المدينة المنورة لاحتوائه على ساحات ومناطق مفتوحة وممرات رئيسية بطريقة الأزقة التي تطل على مسجد قباء. تسمح المساحات المتوفرة بإقامة فعاليات مستدامة بالساحات الخارجية ليشكل المشروع نسيجاً عمرانياً متكاملاً ليكون المقصد لكل قاصدي المدينة و سكانها في منظومة من التصاميم الفريدة المواكبة لأحدث الابداعات الهندسية التي تجمع بين ماضي وحاضر المدينة المنورة ومسجد قباء على وجه الخصوص</p> <p>محتويات المشروع:</p> <p>ينقسم المشرع الى قسمين:</p> <p>القسم الأول:</p> <ul> <li>يحتوي على معارض تجارية ترمز للمدينة المنورة</li> <li>تجربة هذه المدينة</li> <li>منطقة مخصصة لحضان الأطفال تخدم قاصدي مسجد قباء</li> <li>المطعم المديني</li> <li>أكشاك متحركة من خيرات المدينة</li> <li>مركز استعلامات</li> </ul> <p>القسم الثاني:</p> <ul> <li>معارض تجارية</li> <li>ملعب بادل بتصميم مديني</li> <li>محمية طيور</li> <li>مواقف للزوار وباصات للمعتمرين</li> <li>جلسات تخدم جودة الحياة</li> <li>أكشاك موسمية متغيرة</li> </ul> </div> </div> </section> </section> </div> </div> </div> <div data-original-size="14px"> <div data-original-size="14px"> <div data-habitat="C1">&nbsp;</div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90048033-63568055.jpg?v=1753138833", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90048033-63568056.jpg?v=1753138859"]','https://cmsphoto.ww-cdn.com/resizeapi/10443b62ec150606e735bce6c1446fa4bc968980/480/',24.4372471,39.6167476,'7852 DMAD7852 3426','','https://www.visitsaudi.com/ar/madinah/attractions/maqsad-quba','','https://www.saudi-guide.com/medina/i/90048033/maqsad-quba',1,0,'مقصد قباء maqsad quba اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90047263,'medina','مطل العزيزية','The Aziziyah Overlook','aziziyah-overlook','["أماكن سياحية"]','["sights"]','مطل حديث في حي العزيزية بالمدينة المنورة ضمن مشروع تطويري لأمانة المنطقة، يضم 98 منشأة ومحلًا تجاريًا و6 أكشاك سيارة و341 موقف سيارات، إضافة إلى مسارات مشي وجلسات خارجية ومطاعم ومقاهي متنوعة، ويطل على أحياء غرب المدينة المنورة.','<blockquote class="tiktok-embed" cite="https://www.tiktok.com/@soonmadinah/video/7498819868486012178" data-video-id="7498819868486012178" > <section> <a target="_blank" title="@soonmadinah" href="https://www.tiktok.com/@soonmadinah?refer=embed">@soonmadinah</a> زائر او من اهل المدينة مطل العزيزية من افضل الاماكن الجديدة الان في المدينة <a title="المدينة_المنورة" target="_blank" href="https://www.tiktok.com/tag/%D8%A7%D9%84%D9%85%D8%AF%D9%8A%D9%86%D8%A9_%D8%A7%D9%84%D9%85%D9%86%D9%88%D8%B1%D8%A9?refer=embed">#المدينة_المنورة</a> <a title="اماكن_المدينه" target="_blank" href="https://www.tiktok.com/tag/%D8%A7%D9%85%D8%A7%D9%83%D9%86_%D8%A7%D9%84%D9%85%D8%AF%D9%8A%D9%86%D9%87?refer=embed">#اماكن_المدينه</a> <a title="مطل_العزيزيه" target="_blank" href="https://www.tiktok.com/tag/%D9%85%D8%B7%D9%84_%D8%A7%D9%84%D8%B9%D8%B2%D9%8A%D8%B2%D9%8A%D9%87?refer=embed">#مطل_العزيزيه</a> <a title="جديد_المدينة" target="_blank" href="https://www.tiktok.com/tag/%D8%AC%D8%AF%D9%8A%D8%AF_%D8%A7%D9%84%D9%85%D8%AF%D9%8A%D9%86%D8%A9?refer=embed">#جديد_المدينة</a> <a title="explore" target="_blank" href="https://www.tiktok.com/tag/explore?refer=embed">#explore</a> <a title="المدينة" target="_blank" href="https://www.tiktok.com/tag/%D8%A7%D9%84%D9%85%D8%AF%D9%8A%D9%86%D8%A9?refer=embed">#المدينة</a> <a target="_blank" title="♬ الصوت الأصلي - قريباً في المدينة" href="https://www.tiktok.com/music/الصوت-الأصلي-7498819895409937168?refer=embed">♬ الصوت الأصلي - قريباً في المدينة</a> </section> </blockquote> <script async src="https://www.tiktok.com/embed.js"></script> <div class="texte" > <div>أعلنت أمانة منطقة المدينة المنورة مؤخراّ عن اعتماد وبدء مشروع تطويري جديد لمطل العزيزة بحي الجماوات يهدف إلى رفع جودة الحياة في المدينة المنورة.</div> <div>وبحسب ما أورد حساب أمانة منطقة المدينة المنورة يتضمن المشروع 98 منشأة تجارية ومصليين، وعدد &nbsp;6 أكشاك سيارة و341 موقف للسيارات.</div> <div>وينتظر أن يسهم المشروع كما أشارت أمانة منطقة المدينة المنورة في تهيئة بيئة جاذبة ووجهات ترفيهية فريدة، وتوفير خيارات متعددة للأهالي والزوار ، حيث يمثل المشروع الجديد نقطة جذب كونه مرتفع يطل على أحياء غرب المدينة المنورة ، ويسهم في تعزيز ورفع جودة الحياة في المدينة المنورة.</div> <div>&nbsp;</div> <div>يذكر أن مشروع مطل العزيزية يضم مجموعة متنوعة من خيارات الترفيه تشمل، ساحات وجلسات خارجية مطلة، ومسارات للمشي وأخرى للدراجات الهوائية ومقاهي ومطاعم ومنافذ تجارية متعددة.</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90047263-63567679.jpg?v=1753136305"]','https://cmsphoto.ww-cdn.com/resizeapi/b4985ee7d7b9a6e46d34c2286bf506b2fd0b1017/480/',24.4509895,39.5540787,'FH23+9JW Umm Khalid Madinah','','https://visitmadinahsa.com/sa-ar','','https://www.saudi-guide.com/medina/i/90047263/aziziyah-overlook',1,0,'مطل عزيزيه the aziziyah overlook اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90028944,'diriyah','شركة حرف السعودية','Saudi Artisanal Company Workshop','saudi-artisanal-company','["التسوق"]','["shopping"]','تعرف على شركة حرف السعودية في الدرعية، التي تعمل على تطوير وتمكين قطاع الحرف اليدوية عبر منظومة تجارية متكاملة من التصميم إلى التسويق.','<div class="texte" > <p>تعمل شركة حِرف السعودية على تطوير وتمكين قطاع الحرف اليدوية عبر بناء منظومة تجارية متكاملة، تجمع بين الإبداع في التصميم، كفاءة الإنتاج، التزام بمعايير الجودة، وتكامل الخدمات من التسويق إلى التوريد.&nbsp;</p> <p>تركز الشركة على الحفاظ على التراث الحرفي وتعزيز استدامته، وتوسيع حضوره في الأسواق المحلية والدولية، بما يحقق أثرًا اقتصاديًا واجتماعيًا مستدامًا.<br /> <br /> وفي زلال، نهدف إلى إثراء تجربة الزوار من خلال تقديم رحلة تسوّق فريدة تُبرز الحرف اليدوية السعودية بأسلوب مبتكر، حيث يمكن للزوار استكشاف وشراء منتجات تمثّل قطعًا أصيلة من التراث الوطني، كل منها يحمل قصة وإرثًا يُجسّد أصالة الحرفة وروح المكان.&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90028944-63557059.jpg?v=1753061115"]','https://cmsphoto.ww-cdn.com/resizeapi/5325f64b2f272cecd3cb7549409cbb904b81b3bc/480/',24.7382842,46.5772071,'Al Imam Abdulaziz Ibn Mohammad Ibn Saud St Al Bujairi Diriyah','','https://www.diriyah.sa/ar/shopping/saudi-artisanal-company','info@saudiartisanal.com','https://www.saudi-guide.com/diriyah/i/90028944/saudi-artisanal-company',1,0,'شركه حرف سعوديه saudi artisanal company workshop تسوق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90028838,'diriyah','أسولين بوتيك','Maison Assouline','assouline-boutique','["التسوق", "المطاعم والمقاهي"]','["food", "shopping"]','تسوق في أسولين بوتيك بالدرعية، حيث تلتقي الثقافة بالفخامة في تشكيلة مختارة من الكتب والهدايا الفاخرة.','<div class="texte" > <h2 data-content_id="OPcYsRBBWk6T9JE3EuBPGA" data-testid="tagline">حيث تلتقي الثقافة بالفخامة</h2> <div data-content_id="OPcYsRBBWk6T9JE3EuBPGA"> <div data-testid="description"> <p>ميزون أسولين هي الوجهة الأمثل لعشّاق الثقافة والذوق الرفيع؛ حيث تلتقي المكتبة الراقية التي تحتضن أحدث الإصدارات والطبعات النادرة، مع مطعم فاخر ومقهى بيانو أنيق، في مساحة تمتد على طابقين وتنبض بروح الإبداع والفخامة</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90028838-63556961.jpg?v=1753060180"]','https://cmsphoto.ww-cdn.com/resizeapi/8a04c6d9c0bc187b890d3ecbf494c4b08d6cd7c9/480/',24.736024,46.5758792,'Unit #11 7227 King Faisal Rd','+966 92 001 4627','https://www.diriyah.sa/ar/shopping/assouline-boutique','riyadh@assouline.com','https://www.saudi-guide.com/diriyah/i/90028838/assouline-boutique',1,0,'اسولين بوتيك maison assouline تسوق مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90028816,'diriyah','التبيانو','Altopiano','altopiano','["المطاعم والمقاهي"]','["food"]','مطعم التبيانو في مطل البجيري بالدرعية، يقدم أطباق جنوب إيطاليا بمكونات طازجة ولمسات مبتكرة من الشيف دافيد دينياتزو في تجربة أصيلة.','<div class="texte" > <h2 data-content_id="T2k7vXzJq0ufPDp8jAzQRw" data-testid="tagline">نكهات مميزة ومكونات طازجة، من الجنوب الإيطالي إلى مطل البجيري</h2> <div data-content_id="T2k7vXzJq0ufPDp8jAzQRw"> <div data-testid="description"> <p>أطباق مميزة بشكل جديد، يعدّها الشيف دافيد دينياتزو من أجود المكونات، اللي تجمع بين النكهات التقليدية ولمساته المبتكرة، وتصنع لك تجربة أصيلة لا تنساها.</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90028816-63556951.jpg?v=1753059890"]','https://cmsphoto.ww-cdn.com/resizeapi/fb696f5f3dd9343763627cb043c0688f7fbf1a86/480/',24.7366108,46.5732675,'UNIT 19 BUJAIRI TERRACE Al Bujairi Diriyah',' 966506348683','https://www.diriyah.sa/ar/dine/altopiano','','https://www.saudi-guide.com/diriyah/i/90028816/altopiano',1,1,'تبيانو altopiano مطاعم والمقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90027533,'diriyah','سبالة موضي','Sbalat Modhi','sbalat-modhi','["التاريخ والثقافة"]','["heritage"]','تعرف على سبالة موضي في الدرعية، أول وقف خيري مجتمعي في الدولة السعودية الأولى، ورمز من رموز العطاء الاجتماعي التاريخي.','<div class="texte" > <h2 data-content_id="iLWTUydq5EGqxxQmNvTgaA" data-testid="heading">سبالة موضي، أول وقف خيري مجتمعي في الدولة السعودية الأولى.</h2> <div>&nbsp;</div> <div> <div data-testid="duration"> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="heading">ما الذي يمكن أن تتوقعه؟</h2> <div data-content_id="iLWTUydq5EGqxxQmNvTgaA" data-testid="description"> <p>كان الهدف من بناء سبالة موضي انعكاسًا لعطاء الأميرة موضي وإيثارها، لإيواء الزائر والمسافر والمحتاج وطالب العلم، وتضمّ السبالة غرفًا للتدريس والنوم والإطعام والتخزين، وإسطبلاتٍ لإيواء دواب قوافل التجار ومسجدًا.</p> </div> </div> <div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="inclusions-heading">يشمل</h2> <div data-content_id="iLWTUydq5EGqxxQmNvTgaA" data-testid="inclusions-list"> <ul> <li> <p>جولات إرشادية حول أهم المواقع والمعالم التاريخية في الدرعية.&nbsp;</p> </li> <li> <p>تعليق صوتي من المرشدين المتخصصين في تاريخ المنطقة وأهميتها (جولة الطريف – مع مرشد)</p> </li> </ul> </div> </div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="exclusions-heading">لا يشمل</h2> <div data-content_id="iLWTUydq5EGqxxQmNvTgaA" data-testid="exclusions-list"> <ul> <li> <p>الأطعمة والمشروبات.</p> </li> <li> <p>رسوم الدخول إلى بعض المناطق والفعاليات (إن وجدت).</p> </li> <li> <p>التكاليف الشخصية مثل شراء الهدايا التذكارية أو حضور الأنشطة الإضافية.</p> </li> </ul> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90027533-63556633.jpg?v=1753052811"]','https://cmsphoto.ww-cdn.com/resizeapi/2ceeda22d72c8207cd5db6e5e101a0de65118287/480/',24.7335988,46.5761817,'PHMG+CFM Al Traif Diriyah','','https://www.diriyah.sa/ar/experiences/modhi-endowment','','https://www.saudi-guide.com/diriyah/i/90027533/sbalat-modhi',1,0,'سباله موضي sbalat modhi تاريخ والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90027528,'diriyah','معرض التاريخ العسكري','Military Gallery','military-gallery','["التاريخ والثقافة"]','["heritage"]','معرض التاريخ العسكري في الدرعية، يستعرض معارك الدولة السعودية الأولى وما تعرّض له حي الطريف التاريخي من أضرار عام 1818م.','<div class="texte" > <h2 data-content_id="7jLYE3sF1E6w6BAKesyP3A" data-testid="heading">المعرض يستعرض معارك الدولة السعودية الأولى وأضرار حي الطريف التاريخي.</h2> <div>&nbsp;</div> <div> <div data-testid="duration">&nbsp;</div> <div data-testid="duration"> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="heading">ما الذي يمكن أن تتوقعه؟</h2> <div data-content_id="7jLYE3sF1E6w6BAKesyP3A" data-testid="description"> <p>اعرف أكثر عن المعارك التي خاضتها الدولة السعودية الأولى في أوائل خطواتها لتأسيس دولتنا العظيمة اليوم، مما أدى في بعض هذه المعارك إلى تضرر حي الطريف التاريخي كما حصل في عام 1818م.&nbsp;</p> </div> </div> <div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="inclusions-heading">يشمل</h2> <div data-content_id="7jLYE3sF1E6w6BAKesyP3A" data-testid="inclusions-list"> <ul> <li> <p>جولات إرشادية حول أهم المواقع والمعالم التاريخية في الدرعية.&nbsp;</p> </li> <li> <p>تعليق صوتي من المرشدين المتخصصين في تاريخ المنطقة وأهميتها (جولة الطريف – مع مرشد)</p> </li> </ul> </div> </div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="exclusions-heading">لا يشمل</h2> <div data-content_id="7jLYE3sF1E6w6BAKesyP3A" data-testid="exclusions-list"> <ul> <li> <p>الأطعمة والمشروبات.</p> </li> <li> <p>رسوم الدخول إلى بعض المناطق والفعاليات (إن وجدت).</p> </li> <li> <p>التكاليف الشخصية مثل شراء الهدايا التذكارية أو حضور الأنشطة الإضافية.</p> </li> </ul> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90027528-63556626.jpg?v=1753052531"]','https://cmsphoto.ww-cdn.com/resizeapi/6aad036f902512d0c5af454cf543a1ebc8605c4b/480/',24.7366274,46.5750041,'Al Bujairi Diriyah Diriyah','920021727','https://www.diriyah.sa/ar/experiences/military-gallery','','https://www.saudi-guide.com/diriyah/i/90027528/military-gallery',1,0,'معرض تاريخ عسكري military gallery تاريخ والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90027434,'diriyah','معرض الخيل العربي','Arabian Horse Gallery','the-arabian-horse-gallery','["التاريخ والثقافة"]','["heritage"]','اكتشف قصة الخيل العربي الأصيل وتاريخه وجماله وعلاقته العميقة بثقافة المنطقة في معرض الخيل العربي بالدرعية.','<div class="texte" > <h2 data-content_id="dl2fEZitPUKUdTfhaZ-YcA" data-testid="heading">هذا المعرض يسرد قصة الخيل العربي الأصيل، مستعرضاً تاريخه وجماله وقوته، وعلاقته العميقة بثقافة المنطقة.</h2> <div>&nbsp;</div> <div> <div data-testid="duration">&nbsp;</div> <div data-testid="duration"> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="heading">ما الذي يمكن أن تتوقعه؟</h2> <div data-content_id="dl2fEZitPUKUdTfhaZ-YcA" data-testid="description"> <p>نحكي لك في هذا المعرض قصة الخيل العربي الأصيل، عن تاريخها وفصائلها وأصالتها، إذ تحتفي ثقافة هذا المكان بالخيل وجمالها وقوتها.&nbsp;</p> </div> </div> <div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="inclusions-heading">يشمل</h2> <div data-content_id="dl2fEZitPUKUdTfhaZ-YcA" data-testid="inclusions-list"> <ul> <li> <p>جولات إرشادية حول أهم المواقع والمعالم التاريخية في الدرعية.&nbsp;</p> </li> <li> <p>تعليق صوتي من المرشدين المتخصصين في</p> </li> <li> <p>تاريخ المنطقة وأهميتها (جولة الطريف – مع مرشد)</p> </li> </ul> </div> </div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="exclusions-heading">لا يشمل</h2> <div data-content_id="dl2fEZitPUKUdTfhaZ-YcA" data-testid="exclusions-list"> <ul> <li> <p>الأطعمة والمشروبات.</p> </li> <li> <p>رسوم الدخول إلى بعض المناطق والفعاليات (إن وجدت).</p> </li> <li> <p>التكاليف الشخصية مثل شراء الهدايا التذكارية أو حضور الأنشطة الإضافية.</p> </li> </ul> </div> </div> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90027434-63556615.jpg?v=1753052237"]','https://cmsphoto.ww-cdn.com/resizeapi/e09953bca8cf64c7159e537776b5f610a51ffe25/480/',24.7329947,46.5745791,'PHMF+5RW وادي حنيفة Al Traif','','https://www.diriyah.sa/ar/experiences/the-arabian-horse-gallery','','https://www.saudi-guide.com/diriyah/i/90027434/the-arabian-horse-gallery',1,0,'معرض خيل عربي arabian horse gallery تاريخ والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90027423,'diriyah','معرض العمارة النجدية','Traditional Architecture Gallery','traditional-architecture-gallery','["التاريخ والثقافة"]','["heritage"]','معرض العمارة النجدية في الدرعية، يعرّفك على قواعد الطراز المعماري النجدي وأساليبه الذكية في توفير الظل والبرودة في المناخ الحار والجاف.','<div class="texte" > <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="heading">ما الذي يمكن أن تتوقعه؟</h2> <div data-content_id="Y9COGjMX0UqKVPl4Tn8H_A" data-testid="description"> <p>في هذا المعرض ستتعرف أكثر على قواعد الطراز المعماري النجدي، الذي صمدت مبانيه عبر سنين طويلة ولم تتأثر بظروف الطقس الحار والجاف، ووفرت لسكانها الظل والبرودة بطرق ذكية وعملية.&nbsp;</p> </div> </div> <div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="inclusions-heading">يشمل</h2> <div data-content_id="Y9COGjMX0UqKVPl4Tn8H_A" data-testid="inclusions-list"> <ul> <li> <p>جولات إرشادية حول أهم المواقع والمعالم التاريخية في الدرعية.&nbsp;</p> </li> <li> <p>تعليق صوتي من المرشدين المتخصصين في تاريخ المنطقة وأهميتها (جولة الطريف – مع مرشد)</p> </li> </ul> </div> </div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="exclusions-heading">لا يشمل</h2> <div data-content_id="Y9COGjMX0UqKVPl4Tn8H_A" data-testid="exclusions-list"> <ul> <li> <p>الأطعمة والمشروبات.</p> </li> <li> <p>رسوم الدخول إلى بعض المناطق والفعاليات (إن وجدت).</p> </li> <li> <p>التكاليف الشخصية مثل شراء الهدايا التذكارية أو حضور الأنشطة الإضافية.</p> </li> </ul> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90027423-63556600.jpg?v=1753051800"]','https://cmsphoto.ww-cdn.com/resizeapi/8822172888ecc0d4ad7ebdf8eaaa2f53c946169d/480/',24.7366274,46.5750041,'Al Bujairi Diriyah Diriyah','','https://www.diriyah.sa/ar/experiences/traditional-architecture-gallery','','https://www.saudi-guide.com/diriyah/i/90027423/traditional-architecture-gallery',1,0,'معرض عماره نجديه traditional architecture gallery تاريخ والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90027379,'diriyah','مركز الزوار بحي الطريف','Atturaif Visitor Centre','at-turaif-visitor-centre','["التاريخ والثقافة"]','["heritage"]','مركز الزوار بحي الطريف في الدرعية، يروي عبر خط زمني هجرة بني حنيفة إلى المنطقة وتأسيس الدرعية وصولًا إلى برنامج تطويرها الحديث.','<div class="texte" > <h2 data-content_id="BbLOcA2v80-03RFnjqfnFw" data-testid="heading">استكشف هجرة بني حنيفة، وتأسيس الدرعية، وبرنامج تطويرها في مركز الزوار.</h2> <div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="heading">ما الذي يمكن أن تتوقعه؟</h2> <div data-content_id="BbLOcA2v80-03RFnjqfnFw" data-testid="description"> <p>في مركز الزوار، تعرف على بداية هجرة بنو حنيفة للمنطقة واستيطانهم بها مرورًا بتاريخ الدرعية والتأسيس وصولًا إلى برنامج تطوير الدرعية من خلال خط زمني يوضح تلك الحقب. بالإضافة إلى العديد من الخدمات التي تقدم للزوار.&nbsp;</p> </div> </div> <div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="inclusions-heading">يشمل</h2> <div data-content_id="BbLOcA2v80-03RFnjqfnFw" data-testid="inclusions-list"> <ul> <li> <p>جولات إرشادية حول أهم المواقع والمعالم التاريخية في الدرعية.&nbsp;</p> </li> <li> <p>تعليق صوتي من المرشدين المتخصصين في</p> <p>تاريخ المنطقة وأهميتها) جولة الطريف – مع مرشد).</p> <p>&nbsp;</p> </li> </ul> </div> </div> <div> <h2 data-content_id="lax7EntlqUud3MbWAFsVrA" data-testid="exclusions-heading">لا يشمل</h2> <div data-content_id="BbLOcA2v80-03RFnjqfnFw" data-testid="exclusions-list"> <ul> <li> <p>الأطعمة والمشروبات.&nbsp;</p> </li> <li> <p>رسوم الدخول إلى بعض المناطق والفعاليات (إن وجدت).</p> </li> <li> <p>التكاليف الشخصية مثل شراء الهدايا التذكارية أو حضور الأنشطة الإضافية.</p> </li> </ul> </div> </div> </div> </div> <div> <div data-testid="duration">&nbsp;</div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90027379-63556585.jpg?v=1753051513"]','https://cmsphoto.ww-cdn.com/resizeapi/1dac8d89848660520637c42f928d6367cb8f26ff/480/',24.7344258,46.5761011,'PHMG+QCH Al Traif Diriyah','','https://www.diriyah.sa/ar/experiences/at-turaif-visitor-centre','','https://www.saudi-guide.com/diriyah/i/90027379/at-turaif-visitor-centre',1,0,'مركز زوار بحي طريف atturaif visitor centre تاريخ والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90027338,'diriyah','معرض الدرعية','Diriyah Gallery','diriyah-gallery','["التاريخ والثقافة"]','["heritage"]','معرض الدرعية في حي الطريف، رحلة تفاعلية عبر أكثر من 1400 عام تسرد قصة أهل الدرعية منذ استيطان وادي حنيفة حتى قيام الدولة السعودية الأولى.','<div class="texte" > <h2>تاريخ أهل الدرعية الممتد على 1400 عام حتى أسرة آل سعود.</h2> <div>&nbsp;</div> <h2>ما الذي يمكن أن تتوقعه؟</h2> <p>يأخذك معرض الدرعية في رحلة عبر الزمن تمتد لأكثر من 1400 عام، تسرد قصة أهل الدرعية منذ استيطانهم الأول في وادي حنيفة وحتى نشأة الدولة السعودية الأولى على يد أسرة آل سعود. يعتمد المعرض على وسائل عرض تفاعلية وحديثة تجمع بين المقتنيات الأثرية والوسائط المرئية، لتقديم سردية متكاملة عن الحياة الاجتماعية والاقتصادية والسياسية التي شكّلت هوية الدرعية عبر العصور.</p> <p>يقع المعرض في قلب حي الطريف التاريخي، أحد مواقع التراث العالمي لليونسكو، ما يمنح الزائر فرصة ربط ما يشاهده بالمباني والأزقة الطينية المحيطة به، ليخرج بفهم أعمق لعمق الجذور التاريخية للدرعية ودورها المحوري في تأسيس المملكة العربية السعودية.</p> <div> <h2>يشمل</h2> <ul> <li><p>جولات إرشادية حول أهم المواقع والمعالم التاريخية في الدرعية.&nbsp;</p></li> <li><p>تعليق صوتي من المرشدين المتخصصين في تاريخ المنطقة وأهميتها (جولة الطريف – مع مرشد)</p></li> </ul> </div> <div> <h2>لا يشمل</h2> <ul> <li><p>الأطعمة والمشروبات.</p></li> <li><p>رسوم الدخول إلى بعض المناطق والفعاليات (إن وجدت).</p></li> <li><p>التكاليف الشخصية مثل شراء الهدايا التذكارية أو حضور الأنشطة الإضافية.</p></li> </ul> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90027338-63556576.jpg?v=1753051240"]','https://cmsphoto.ww-cdn.com/resizeapi/7e0261f45a4288006d0df9f9de54ffd2b6105397/480/',24.733917,46.575278,'PHMG+H46 Al Traif Diriyah','','https://www.diriyah.sa/ar/experiences/diriyah-gallery','','https://www.saudi-guide.com/diriyah/i/90027338/diriyah-gallery',1,0,'معرض درعيه diriyah gallery تاريخ والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90026935,'diriyah','وادي حنيفة','Wadi Hanifah','wadi-hanifah','["أماكن للزيارة"]','["sights"]','وادي حنيفة في الدرعية، شريان الحياة التاريخي لوسط الجزيرة العربية وأكبر متنزه في المملكة، يتميز بالطبيعة الخلابة والمساحات الواسعة والتجارب الترفيهية.','<div class="texte" > <div> <div data-content_id="WJPogOLeK022nqQkBr8WvA"> <div data-testid="heading"> <h2>ماضي عريق يشكل المستقبل</h2> </div> </div> </div> <div> <div data-content_id="WJPogOLeK022nqQkBr8WvA"> <div data-testid="description"> <p>تقع الدرعية على وادي حنيفة، الذي يعد الشريان الأساسي للمدينة وأكبر متنزه في المملكة العربية السعودية</p> <p>تحاط الدرعية بوادي حنيفة الذي كان يعد شريان الحياة لسكان وسط شبه الجزيرة العربية قديمًا.</p> <p>يتميز وادي حنيفة بالهواء النقي والمساحات الواسعة والطبيعة الخلابة بالإضافة إلى العديد من التجارب الترفيهية والرياضية والمرافق الفاخرة.</p> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90026935-63556447.jpg?v=1753049942", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90026935-64793643.jpg?v=1762502050"]','https://cmsphoto.ww-cdn.com/resizeapi/8ea2d282e00d1416b27b2fbe778c9ab70d111ae1/480/',24.7356869,46.5741073,'PHPF+7JH وادي حنيفة، البجيري، Al Traif','','https://www.diriyah.sa/ar/wadi-hanifah','','https://www.saudi-guide.com/diriyah/i/90026935/wadi-hanifah',1,0,'وادي حنيفه wadi hanifah اماكن للزياره',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90023241,'diriyah','مطل البجيري','Bujairi Terrace','bujairi-terrace','["أماكن للزيارة"]','["sights"]','استمتع بأجواء مطل البجيري في الدرعية، الوجهة الأشهر للمطاعم والمقاهي العالمية بإطلالة على حي الطريف التاريخي.','<div class="texte" > <p>مطل البجيري وجهة للمطاعم والمقاهي في حي البجيري بالدرعية، ويطل على حي الطريف التاريخي المسجل في قائمة اليونسكو للتراث العالمي. افتُتح في ديسمبر 2022م، ويضم مجموعة من المطاعم المحلية والعالمية في بيئة مستوحاة من العمارة النجدية التقليدية، مع ممرات وساحات مفتوحة تناسب التنزه والجلسات المسائية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90023241-63555197.jpg?v=1753035511", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90023241-63557069.jpg?v=1753061337"]','https://cmsphoto.ww-cdn.com/resizeapi/728419a8f98222e0c68ede9dc98c9389da4a335f/480/',24.7373233,46.5747979,'7295 King Faisal Rd Al Bujairi','','https://www.diriyah.sa/ar/bujairi-terrace','','https://www.saudi-guide.com/riyadh/i/90023241/bujairi-terrace',1,0,'مطل بجيري bujairi terrace اماكن للزياره',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (90023210,'diriyah','الطريف','Al Turaif','at-turaif','["أماكن للزيارة"]','["sights"]','استكشف حي الطريف التاريخي، الحي الملكي للدولة السعودية الأولى وأحد مواقع التراث العالمي لليونسكو في الدرعية.','<div class="texte" > <div> <div data-content_id="CDR3ObArmEWwpglwGc3wtw"> <div data-testid="heading"> <h2>حي الطريف التاريخي: الحي الملكي للدولة السعودية الأولى</h2> </div> </div> </div> <div> <div data-content_id="CDR3ObArmEWwpglwGc3wtw"> <div data-testid="description"> <p>يشكل حي الطريف التاريخي، أحد مواقع التراث العالمي لليونسكو منذ عام 2010، تحفة معمارية تجسد التطور العلمي والثقافي الذي ميزت به الدولة السعودية الأولى.</p> <p>تتميز أبنية هذا الحي العريق بتصاميمها الفريدة، حيث تتكون من عدة طوابق شيدت باستخدام الطين والمواد الطبيعية المستمدة من البيئة المحيطة. وقد برهنت هذه المباني على متانتها وقدرتها على الصمود لقرون طويلة، لتكون شاهداً حياً على عبقرية الإبداع المعماري في تلك الحقبة.</p> <p>ولقد شكّل حي الطريف دورًا محوريًا كمركز حضاري نابض بالحياة في الدرعية، عاصمة الدولة السعودية الأولى (1727-1818م).</p> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90023210-63555171.jpg?v=1753035295", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/90023210-64793762.jpg?v=1762502916"]','https://cmsphoto.ww-cdn.com/resizeapi/7afeb578176c66b935c29949b0c60ede76641ca2/480/',24.7338946,46.5748073,'Al Traif Diriyah Diriyah','','https://www.diriyah.sa/ar/at-turaif','','https://www.saudi-guide.com/diriyah/i/90023210/at-turaif',1,0,'طريف al turaif اماكن للزياره',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (89960697,'taif','القصر الوطني التاريخي للحضارات الإسلامية بالسيل الكبير قرن المنازل','','alksr-alotny-altarykhy-llhdarat-alaslamy-balsyl-alkbyr-krn-almnazl','["التراث والثقافة"]','["heritage"]','يعد القصر الوطني التاريخي للحضارات الإسلامية بقرن المنازل أحد أبرز المعالم التاريخية والمعمارية التي تروي فصولًا من عبق الماضي الإسلامي الأصيل.','<video controls controlsList="nodownload" poster="https://cmsphoto.ww-cdn.com/superstatic/images/2892882/video/3431288/player/player_preview.jpg?v=1752753704" width="100%" oncontextmenu="return false;"><source src="https://www.saudi-guide.com/apiv3/video/getIphoneSVideo/3431288/49768641.mp4/" type="video/mp4" /></video> <video controls controlsList="nodownload" poster="https://cmsphoto.ww-cdn.com/superstatic/images/2892882/video/3431289/player/player_preview.jpg?v=1752753727" width="100%" oncontextmenu="return false;"><source src="https://www.saudi-guide.com/apiv3/video/getIphoneSVideo/3431289/49768645.mp4/" type="video/mp4" /></video> <div class="texte" > <div>يعد القصر التاريخي الرطني للحضارات رالإسلامية بقرن المنازل كأحد أبرز المعالم التاريخية والمعمارية التي تروي فصولًا من عبق الماضي الإسلامي الأصيل.</div> <div>&nbsp;</div> <div>شُيّد هذا القصر على طراز العمارات المناطقية، ويضم سبعة متاحف داخل مكان واحد بمساحة 70 الف متر مربع ويحوي مجموعة نادرة من المقتنيات التراثية والمجسمات التوضيحية للحضارات الإسلامية عبر العصور، بدءًا من العصر النبوي والخلافة الراشدة، مرورًا بالأموية والعباسية، وانتهاءً بالحضارات العثمانية&nbsp; والأندلسية.</div> <div>&nbsp;</div> <div>يأخذك القصر في جولة بصرية وثقافية ساحرة، تبدأ من تصميمه الخارجي الذي يعكس روح العمارة الإسلامية، وصولًا إلى تفاصيل القاعات والمجسمات والعروض التفاعلية التي تناسب الزوّار من مختلف الأعمار.</div> <div>&nbsp;</div> <div>• مكان غني بالتاريخ والثقافة الإسلامية</div> <div>• تجربة تعليمية وترفيهية فريدة وسط بيئة تراثية</div> <div>• فرصة لالتقاط صور رائعة بين التحف والنقوش</div> <div>• مناسب للزيارات العائلية والرحلات المدرسية</div> <div>&nbsp;</div> <div>🕰️ ساعات الزيارة:</div> <div>من الساعة ٩ صباحاً حتى ١١ مساءً</div> <div>يستقبل الزوّار للسياحية والمناسبات، ويمكن التنسيق لحجز زيارات خاصة.</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89960697-63528935.jpg?v=1752753658"]','https://cmsphoto.ww-cdn.com/resizeapi/35da96072669af0065e9a563a444b090f1897b9e/480/',21.6108583,40.4059972,'JC64+89X As Sail Al Kabeer Al Taif','0555715235','','','https://www.saudi-guide.com/taif/i/89960697/alksr-alotny-altarykhy-llhdarat-alaslamy-balsyl-alkbyr-krn-almnazl',1,0,'قصر وطني تاريخي للحضارات اسلاميه بالسيل كبير قرن منازل تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (89707768,'riyadh','المتحف الوطني السعودي','The National Museum','national-museum-saudi-arabia','["التراث والثقافة"]','["heritage"]','المتحف الوطني السعودي بالرياض، ثمانية أقسام تروي رحلة تاريخ الجزيرة من الأرض إلى توحيد المملكة، 3700 قطعة تراثية.','<div class="texte" > <div data-original-size="14px"> <h2 data-original-size="48px">نبذة عن المتحف الوطني السعودي</h2> <div data-original-size="14px"> <div data-original-size="14px"><button aria-label="Share" data-original-size="14px"></button></div> </div> </div> <div data-original-size="16px"> <div data-original-size="16px"> <p data-original-size="16px">من الأرض إلى القمر، ومن عصور ما قبل التاريخ إلى العصر الحديث، تأخذك أروقة&nbsp;المتحف الوطني السعودي&nbsp;في رحلة شيقة، تتجاوز فيها الزمان والمكان، وتقف على شواهد فنية وتاريخية في قلب مدينة الرياض بحي المربع، بجوار قصر الملك عبدالعزيز، حيث افتتح المتحف في عام 1419هـ، على مساحة قدرها 17 ألف متر مربع، تنتشر فيها حكايات 3,700 قطعة تراثية من تماثيل، ومخطوطات، ومنحوتات لا مثيل لها.&nbsp;</p> </div> </div> </div>  <div class="texte" > <p>يضم المتحف الوطني السعودي ثمانية أقسام مفعمة بروح التاريخ، تبدأ في قاعة الإنسان والكون، حيث تتعرّف على نشأة الكون والمجموعة الشمسية، والعوامل الطبيعية المؤثرة في تطوره منذ ملايين السنين. وتتيح لك قاعة الممالك العربية القديمة الانغماس في حضارات امتدت من الألف الرابعة قبل الميلاد إلى القرن الثاني بعد الميلاد، كما تظهر أنماط الحياة الدينية والاجتماعية قبل الإسلام في قاعة العصر الجاهلي، وتتجلى سيرة النبي محمد -صلى الله عليه وسلم- في قاعة البعثة النبوية، منذ نزول الوحي وحتى هجرته إلى المدينة المنورة، ثم يظهر تاريخ توحيد المملكة في فيلم وثائقي داخل قاعة توحيد المملكة، وتضم قاعة الحج والحرمين الشريفين، جوانب التطور العمراني للحرم المكي والنبوي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89707768-63387755.jpg?v=1751551815"]','https://cmsphoto.ww-cdn.com/resizeapi/878edaba4ce50fddd19333eb3b89eae814b9ca2e/480/',24.6480983,46.7109536,'حي 8745 طريق الملك سعود','','https://www.visitsaudi.com/ar/riyadh/attractions/the-national-museum-of-saudi-arabia','','https://www.saudi-guide.com/riyadh/i/89707768/national-museum-saudi-arabia',1,0,'متحف وطني سعودي the national museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (89707529,'riyadh','حي الدحو','Addoho Neighborhood','addoho-neighborhood','["التراث والثقافة"]','["heritage"]','حي الدحو التاريخي بالرياض، أحد الأحياء القديمة التي تعكس الطابع المعماري الأصيل لمدينة الرياض.','<div class="texte" > <div data-original-size="14px"> <h2 data-original-size="48px">نبذة عن حي الدحو</h2> <div data-original-size="14px"> <div data-original-size="14px"><button aria-label="Share" data-original-size="14px"></button></div> </div> </div> <div data-original-size="16px"> <div data-original-size="16px"> <p data-original-size="16px">على بعد كيلومتر جنوب غرب قصر الحكم، يقع&nbsp;حي الدحو&nbsp;في قلب العاصمة الرياض، وهو آخر الأحياء القديمة التي حافظت على عِمرانها النجدي التقليدي. يعود تاريخ بناء الدحو إلى أكثر من 200 عام، فبموقعه الاستراتيجي داخل منطقة قصر الحكم وشواهدها التاريخية، إلى أزقته الضيقة وتفاصيل بيوته التي تعبر عن أسلوب عيش السكان المحليين آنذاك، يحكي حي الدحو قصة حضارة صحراوية أُحيطت مبانيها بالأسوار والنخيل.</p> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89707529-63387668.jpg?v=1751551144", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89707529-63387670.jpg?v=1751551167"]','https://cmsphoto.ww-cdn.com/resizeapi/f3921e27661d8e84540bec6abdbbdfa49828dc7a/480/',24.6287153,46.7140804,'حي الدحو Riyadh Riyadh Principality','','https://www.visitsaudi.com/ar/riyadh/attractions/addoho-neighborhood','','https://www.saudi-guide.com/riyadh/i/89707529/addoho-neighborhood',1,0,'حي دحو addoho neighborhood تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (89701761,'riyadh','مركز زوار مرقب منيخ','','marqab-munikh-visitor-center','["التراث والثقافة"]','["heritage"]','مركز زوار مرقب منيخ بالرياض، موقع طبيعي وتراثي يطل على منطقة الدرعية التاريخية.','<div class="texte" > <p data-original-size="16px">اكتشف مرقب منيخ في المجمعة، الواقع في الناحية الجنوبية للبلدة القديمة. يتميز هذا المرقب بموقع استراتيجي على ارتفاع يتيح لأهالي البلدة القديمة مراقبة المناطق المحيطة من جميع الاتجاهات بدون عوائق، مما جعله رمزاً للأمان واليقظة في تلك الفترة.</p> <p data-original-size="16px">من سطح الجبل، يمكن للزوار الاستمتاع بإطلالات بانورامية على مدينة المجمعة والمزارع المحيطة بها، ما يوفر تجربة مميزة تمزج بين عبق التاريخ وجمال الطبيعة. سواء كنت من عشاق التراث أو محبي المناظر الطبيعية، فإن مرقب منيخ وجهة تستحق الزيارة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89701761-63383487.jpg?v=1751533304"]','https://cmsphoto.ww-cdn.com/resizeapi/e1abd1f0585b9bc1837144816055f3206edca793/480/',25.9017616,45.3343769,'Almarqab St Al Marqab Al Majmaah','','https://www.visitsaudi.com/ar/riyadh/attractions/al-munikh-visitor-centre','','https://www.saudi-guide.com/riyadh/i/89701761/marqab-munikh-visitor-center',1,0,'مركز زوار مرقب منيخ تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (89569478,'riyadh','الزلال الدرعية','','al-zulal-diriyah','["التراث والثقافة"]','["heritage"]','الزلال الدرعية، وجهة تراثية وطبيعية بالقرب من الدرعية التاريخية.','<div class="texte" > <div> <div data-content_id="a9RfctI5lUGzisHuocHDag"> <div data-testid="heading"> <h2>استشعر جمال الحياة اليومية</h2> </div> </div> </div> <div> <div data-content_id="a9RfctI5lUGzisHuocHDag"> <div data-testid="description"> <p>في قلب الدرعية، يقدّم زلّال أسلوب حياة يتسم بالهدوء والتناغم مع المكان. بتصميم مستوحى من العمارة النجدية، تتيح شوارعه المخصصة للمشي، وأفنيته المظللة، ومطلّاته الواسعة تجربة متوازنة تُركّز على جودة التفاصيل والارتقاء بجودة الحياة. زلّال ليس مجرد وجهة، بل بيئة متكاملة تجمع بين الطابع التراثي والحياة العصرية.&nbsp;<br /> <br /> يشارك “زلّال” في&nbsp;إحياء موقعًا ذا قيمة تاريخية، ليكون مركزًا للراحة والاستجمام، وموردًا مستدامًا للسكّان والزائرين، اليوم وفي المستقبل.</p> </div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89569478-63313518.jpg?v=1750943396"]','https://cmsphoto.ww-cdn.com/resizeapi/72ddb86784b616864ff297d8e323b98865cf53d3/480/',24.7382792,46.5774088,'PHQG+8V8 Al Imam Abdulaziz Ibn Mohammad Ibn Saud St Al Bujairi','','https://www.diriyah.sa/ar/zallal','','https://www.saudi-guide.com/riyadh/i/89569478/al-zulal-diriyah',1,0,'زلال درعيه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (89289511,'abha','متحف القط العسيري','Al Qatt Al Asiri Museum','al-qatt-al-asiri-museum-mthf-alkt-alaasyry','["التراث والثقافة"]','["heritage"]','متحف القط العسيري في أبها مخصص لتراث المرأة العسيرية وفن القط المدرج في قائمة اليونسكو، يعرض رموز نقوشه وألوانه المستخلصة من طبيعة عسير.','<div class="texte" > <div data-original-size="14px"> <h2 data-original-size="48px">نبذة عن متحف القط العسيري (متحف فاطمة)</h2> <div data-original-size="14px"> <div data-original-size="14px"><button aria-label="Share" data-original-size="14px"></button></div> </div> </div> <div data-original-size="16px"> <div data-original-size="16px"> <p data-original-size="16px">قم بزيارة متحف القط العسيري، حيث ينبض فن القط العسيري بالحياة. يخصص هذا المتحف الفريد لتراث وفن المرأة العسيرية، ويقدم تجربة غامرة تكشف عن أسلوبها المميز في تزيين المنازل والحياة اليومية.</p> <p data-original-size="16px">من لحظة دخولك، تستقبلك النباتات العطرية عند المدخل لتأخذك إلى عالم من الأنماط الهندسية والزخارف الزاهية. تزين الجدران خطوط القط الملونة التي تروي قصصاً عن التراث الثقافي والتعبير الفني، وهو ما اعترف به اليونسكو كتراث غير مادي. يمكن للزوار المشاركة في ورش تعليمية للتعرف على هذا الفن واقتناء منتجات مزينة بنقوش القط الفريدة. أثناء جولتك، ستتعرف على الرموز الجميلة في نقوش القط التي تعكس قيم وتقاليد المجتمع المحلي. شاهد المهارة الرائعة للنساء العسيريات في استخراج الألوان الطبيعية من البيئة المحيطة واستخدامها في تزيين المنازل.</p> </div> </div> </div>  <div class="texte" > <div data-original-size="14px"> <div data-habitat="C1"> <section data-original-size="14px"> <div data-original-size="14px"> <h3 data-original-size="32px">توثيق المعنى في نقوش القَطّ العسري</h3> <div data-original-size="14px"> <div data-original-size="16px"> <p data-original-size="16px"><br data-original-size="16px" /> تُظهر الزخارف الفنية في متحف فاطمة لتراث المرأة العسيرية المكنونات الجمالية والدلالات الرمزية الآتية من ذاكرة الهوية الجنوبية، حيث يمثل المثلث المرأة، ويرمز المربع إلى ختمة القرآن الكريم، وهي إشارة إلى أهمية البعد الديني للمجتمع المحلي، فيما تكشف نقوش الأمشاط المصطفة جنبًا إلى جنب بأطوال واحدة، عن جوهر العلاقات الإنسانية القائمة على مبدأ التساوي.&nbsp;</p> </div> </div> <div data-original-size="14px">&nbsp;</div> </div> </section> </div> </div> <div data-original-size="14px"> <div data-habitat="C1"> <section data-original-size="14px"> <div data-original-size="14px"> <h3 data-original-size="32px">إبداع يتجدد من الطبيعة</h3> <div data-original-size="14px"> <div data-original-size="16px"> <p data-original-size="16px"><br data-original-size="16px" /> يظهر إبداع المرأة العسيرية في استخلاص الألوان الزاهية من مخزون الطبيعة في منطقة عسير، حيث تبدأ رحلة رائدات القَطّ العسيري في استخلاص اللون الأخضر من البرسيم، مرورًا باللون الأسود المستخلص من الفحم، والأصفر من الكركم، وتكتمل الرحلة عبر مزج كل لون بالصمغ العربي، حتى يتخذ شكلًا ثابًتا ولونًا ساطعًا يدوم على جدران بيوت جنوبية تشعّ بالحياة.&nbsp;</p> </div> </div> </div> </section> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89289511-63154021.jpg?v=1749887027"]','https://cmsphoto.ww-cdn.com/resizeapi/5d50f7b1097cb418e2a3cc3dabb18fdc8e992603/480/',18.1907539,42.5448192,'Abha Asir Principality Aseer Province','0541033129','https://www.visitsaudi.com/ar/aseer/attractions/fatima-museum','','https://www.saudi-guide.com/abha/i/89289511/al-qatt-al-asiri-museum-mthf-alkt-alaasyry',1,0,'متحف قط عسيري al qatt al asiri museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (88253451,'jeddah','واجهة روشن البحرية','ROSHN Waterfront','roshn-waterfront-oagh-roshn-albhry','["سياحة وترفيه"]','["sights"]','تعتبر واجهة روشن البحرية بجدة إحدى أجمل الواجهات البحرية وأكبرها في المملكة.','<div class="texte" > <section id="two-column-content"> <div> <div> <div> <p>تعتبر واجهة روشن البحرية بجدة إحدى أجمل الواجهات البحرية وأكبرها، حيث تستقبل أكثر من 55 مليون زائر سنوياً، وتتضمن العديد من المرافق الترفيهة ومجموعة واسعة من المطاعم والمحلات التجارية التي تناسب كل &nbsp;الأذواق.</p> </div> </div> </div> </section> <section id="large-text-with-parallax-image"> <p>&nbsp;</p> </section> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88253451-62531491.jpg?v=1746024096", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88253451-62531458.jpg?v=1746023975", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88253451-62531493.jpg?v=1746024107", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88253451-62531492.jpg?v=1746024118"]','https://cmsphoto.ww-cdn.com/resizeapi/9dd08266d103cb205183ffaf455438dd458ed07a/480/',21.6027992,39.1071945,'J434+4X Ash Shati Jeddah','','https://www.roshn.sa/ar/sponsorships/roshn-water-front','','https://www.saudi-guide.com/jeddah/i/88253451/roshn-waterfront-oagh-roshn-albhry',1,0,'واجهه روشن بحريه roshn waterfront سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (87789158,'umluj','منتجع ديزرت روك','Desert Rock Resort','desert-rock-resort-mntgaa-dyzrt-rok','["أماكن سياحية"]','["sights"]','يقع منتجع ديزرت روك الجبلي في وادٍ خفي بين الجبال على بعد 30 دقيقة من مطار البحر الأحمر الدولي، ويضم 64 وحدة فندقية فاخرة بينها وحدات محفورة داخل الصخور.','<iframe width="560" height="315" src="https://www.youtube.com/embed/JTB5_TQSYkI?si=9A9_QQbmrMeHqIod&gbyoutube=JTB5_TQSYkI" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>         <div class="texte" > <p>يقع منتجع "ديزرت روك" الجبلي في وادي خفي بين الجبال، مما يتيح للزوار الاستمتاع بالمناظر الخلابة المحيطة، وتجارب فاخرة وفريدة من نوعها. ويقع على بعد 30 دقيقة بالسيارة من "مطار البحر الأحمر الدولي". ​</p> <p>&nbsp;</p> <p>ويتميز المنتجع بتصميم فريد يتماهى بشكل ساحر مع الطبيعة، مع الحفاظ على هيئة وتكوين المنطقة الجبلية. ويقدم المنتجع مجموعة متنوعة من خيارات الإقامة، كالوحدات الفندقية الموجودة في الطابق الأرضي والأجنحة الموجودة داخل الشقوق الجبلية صعوداً للأعلى، بالإضافة إلى عدد معين من الوحدات الفندقية التي تم حفرها في الكتل الصخرية للجبل.​</p> <p>&nbsp;</p> <p>ويحتضن المنتجع 64 وحدة فندقية فاخرة، بما في ذلك 54 فيلا و10 وحدات فندقية مميزة، وسط منطقة جبلية وبإطلالة فريدة على مدى بصري واسع، ما يمنح الزوار فرصة الاستمتاع بتجربة إقامة فاخرة مع إطلالات خلابة للطبيعة بالأسفل.​</p> <p>&nbsp;</p> <p>كما يضم المنتجع مجموعة من المرافق العصرية، بما في ذلك منتجع صحي بمستوى عالمي، ومركز لياقة بدنية وأماكن لتناول أشهى الأطباق في أماكن موزعة في أنحاء المنتجع وواحة ببحيرة مميزة.​</p> <p>​</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87789158-62224024.jpg?v=1744190415", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87789158-62224054.jpg?v=1744190426", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87789158-62224062.jpg?v=1744190442", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87789158-62224064.jpg?v=1744190452", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87789158-62224066.jpg?v=1744190458", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87789158-62224071.jpg?v=1744190483"]','https://cmsphoto.ww-cdn.com/resizeapi/36d36ff013f1b8bc592ddb692c8f6e4df41ca271/480/',25.7129375,37.2393125,'7GQVP67Q+5P Umluj Tabuk Province','','https://www.visitredsea.com/ar/resorts/desert-rock','','https://www.saudi-guide.com/umluj/i/87789158/desert-rock-resort-mntgaa-dyzrt-rok',1,0,'منتجع ديزرت روك desert rock resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (87788683,'umluj','منتجع سانت ريجيس البحر الأحمر','The St. Regis Red Sea Resort','st-regis-red-sea-resort-mntgaa-sant-rygys-albhr-alahmr','["أماكن سياحية"]','["sights"]','يقع منتجع سانت ريجيس البحر الأحمر على جزيرة بكر خاصة ضمن أرخبيل أمهات، ويوفر حتى 90 فيلا فوق سطح الماء ومطلة على الشاطئ، مع مسابح ونادٍ صحي ومطاعم فاخرة.','<div class="texte" > <p data-ellipsis-type="seemore" data-seeless-text="رؤية تفاصيل أقل" data-seemore-text="الاطلاع على المزيد" data-threshold="400">يقع منتجع سانت ريجيس البحر الأحمر على جزيرة بكر خاصة، ويقدم رؤية جذابة لطراز معيشة رائع في أرخبيل أمهات. تم تصميم هذه الوجهة من أحد الكنوز الطبيعية غير المكتشفة في العالم، فهي تمزج ببراعة جوهر الرؤية للعلامة التجارية والطراز الطليعي والخدمة المخصصة، مع معيار جديد متطور للتنمية المستدامة. تحتل الجزيرة موقعًا منعزلًا داخل مشروع البحر الأحمر الرائد، ويمكن الوصول إليها من ساحل المملكة العربية السعودية&nbsp;بواسطة قارب سريع أو طائرة مائية. يوفر المنتجع بيئة غنية تتألق بأجواء مبهرة خالدة، إذ يوفر مجموعة من الفيلات تصل إلي 90 فيلا فوق سطح الماء ومواجهة للشاطئ، وتتميز كل منها بمساحة فسيحة ومسبح خاص. يخلق المنتجع أجواء تفيض بالتجارب الغامرة، إذ يضم مسابح خارجية، ومركزًا للياقة البدنية عالي التقنية، ونادي السانت ريجيس الصحي، وناديًا للأطفال، إلى جانب المطاعم الفاخرة الاستثنائية. تُعزز كل إقامة بمجموعة منتقاة من الطقوس المميزة وخدمة الخادم الشخصي المميزة من سانت ريجيس.</p> <div>&nbsp;</div> </div>              <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788683-62223670.jpg?v=1744188515", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788683-62223707.jpg?v=1744188534", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788683-62223706.jpg?v=1744188710", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788683-62223705.jpg?v=1744188716", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788683-62223702.jpg?v=1744188725", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788683-62223701.jpg?v=1744188739", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788683-62223753.jpg?v=1744188750"]','https://cmsphoto.ww-cdn.com/resizeapi/d0daae653cb660715665ff8a6d734581b75e04c0/480/',25.5472801,36.7452928,'Red Sea املج منطقة تبوك','','https://www.marriott.com/ar/hotels/ejhxr-the-st-regis-red-sea-resort/overview/','','https://www.saudi-guide.com/umluj/i/87788683/st-regis-red-sea-resort-mntgaa-sant-rygys-albhr-alahmr',1,0,'منتجع سانت ريجيس بحر احمر the st regis red sea resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (87788537,'umluj','منتجع نجومه ريتز كارلتون','Nujuma, a Ritz-Carlton Reserve','nujuma-ritz-carlton-reserve-mntgaa-ngomh-rytz-karlton','["أماكن سياحية"]','["sights"]','منتجع نجومة، محمية ريتز كارلتون، وُلد من نجوم السماء والشعاب المرجانية الملونة، ويحيط به مياه صافية ورمال بيضاء ناعمة على البحر الأحمر.','<div class="texte" > <div> <h1>مكان يلتقي فيه المجهول مع الاستثنائي</h1> </div> <div> <div> <p>وُلدت نجوما، محمية ريتز كارلتون من نجوم السماء اللامتناهية في الأعلى والشعاب المرجانية الملونة في الأسفل، وهي تحمل تقاليد أولئك الذين سافروا عبر أراضٍ مجهولة لاكتشاف الجمال الطبيعي البكر والتراث الثقافي الغني والنكهات النابضة بالحياة مثل البحر نفسه. كما تحيط بنجوما مياه صافية ورمال بيضاء ناعمة، وتُعد ملاذًا بكرًا يأتي فيه الاستكشاف بمجموعة من التجارب التي لا تُنسى.</p> </div> </div> </div>          <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788537-62223559.jpg?v=1744187667", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788537-62223515.jpg?v=1744187639", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788537-62223560.jpg?v=1744187658", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788537-62223558.jpg?v=1744187678", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788537-62223557.jpg?v=1744187684"]','https://cmsphoto.ww-cdn.com/resizeapi/7a62b117c9c752a0646663b2e44ee4072b393716/480/',25.5280447,36.7735525,'Red Sea Umluj Tabuk Province','','https://www.ritzcarlton.com/ar/hotels/ejhrz-nujuma-a-ritz-carlton-reserve/overview/','','https://www.saudi-guide.com/umluj/i/87788537/nujuma-ritz-carlton-reserve-mntgaa-ngomh-rytz-karlton',1,0,'منتجع نجومه ريتز كارلتون nujuma a ritz carlton reserve اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (87788192,'umluj','منتجع شيبارة','Shebara Resort','shebara-resort-mntgaa-shybar','["أماكن سياحية"]','["sights"]','منتجع شيبارة يضم 38 فيلا عائمة و35 فيلا مطلة على الشاطئ على سواحل البحر الأحمر، ويقدم مطاعم عالمية ومرافق استثنائية مع اهتمام راسخ بالاستدامة.','<div class="texte" > <div data-testid="cards-resort-details-header"> <div> <div data-testid="header-section-description"> <p>اكتشف "شيبارة"، ملاذٌ يعانق روعة العمارة الفاخرة وجمال الطبيعة الخلاب على شواطئ البحر الأحمر في المملكة. مع 38 فيلا عائمة و35 فيلا مطلة على الشاطئ، تُعيد "شيبارة" تعريف الفخامة بأسلوب مبتكر. استمتع بمطاعم عالمية، ومرافق استثنائية، واهتمام راسخ بالاستدامة، لتخلق هنا تجربة لا مثيل لها حيث تتناغم الخصوصية والابتكار والصحة في أروع انسجام.</p> </div> </div> </div> <div aria-label="Carousel" data-testid="cards-resort-details-carousel" dir="rtl"> <div aria-label="Carousel" data-testid="carousel-paginator" role="navigation"><button data-testid="carousel-paginator-prev-btn"></button></div> </div> </div>            <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788192-62223224.jpg?v=1744186887", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788192-62223450.jpg?v=1744186953", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788192-62223453.jpg?v=1744186972", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788192-62223454.jpg?v=1744186979", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788192-62223456.jpg?v=1744186991", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87788192-62223459.jpg?v=1744186998"]','https://cmsphoto.ww-cdn.com/resizeapi/4b659a164e758ed2181fe42014ee8d66129e960d/480/',25.4115625,36.8679375,'The Red Sea Destination 7GQRCV69+J5 املج','','https://www.visitredsea.com/ar/resorts/shebara','','https://www.saudi-guide.com/umluj/i/87788192/shebara-resort-mntgaa-shybar',1,0,'منتجع شيباره shebara resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (84673733,'medina','مزرعة المربد','Al Marbad Farm','al-marbad-farm','["أماكن سياحية"]','["sights"]','مزرعة المربد بحي العهن بالمدينة المنورة، وجهة طبيعية هادئة تضم محمية للطيور ومساحات خضراء ومطاعم ومقاهي، مثالية للاسترخاء مع العائلة.','<iframe width="560" height="315" src="https://www.youtube.com/embed/hruKG_GoBRU?si=SQmnwpOLMLmY3Iyf&gbyoutube=hruKG_GoBRU" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>       <div class="texte" > <p>تقع مزرعة المربد في حي العهن جنوب شرق المدينة المنورة، وتُعد من أبرز الوجهات الطبيعية الهادئة بالمدينة، إذ تجمع بين أجواء الريف الأصيلة والخدمات الترفيهية الحديثة.</p> <p>تضم المزرعة محمية صغيرة للطيور يمكن للزوار مراقبتها والتفاعل معها عن قرب، إضافة إلى مساحات خضراء مفتوحة تناسب الجلسات العائلية، ومجموعة من المطاعم والمقاهي لقضاء وقت مريح بعيدًا عن صخب المدينة. تشتهر المزرعة بإقبال الزوار عليها خاصة في المساء وخلال شهر رمضان، وتُعد خيارًا مميزًا لمحبي الطبيعة والهدوء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84673733-60442109.jpg?v=1733177780", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84673733-60442104.jpg?v=1733177748", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84673733-60442100.jpg?v=1733177741"]','https://cmsphoto.ww-cdn.com/resizeapi/af910cd183ebc8788c48719678e6bf9d80f0b0f1/480/',24.441789,39.628481,'6168 طريق علي بن ابي طالب Al Ihn','','https://www.visitsaudi.com/ar/madinah/attractions/al-marbad-farm','','https://www.saudi-guide.com/medina/i/84673733/al-marbad-farm',1,0,'مزرعه مربد al marbad farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (84636185,'riyadh','روضة الخفس','Rawdat Al Khafs','rawdat-al-khafs','["أماكن سياحية"]','["sights"]','روضة الخفس بالرياض، متنزه تخييم الشتاء الأخضر بين صحراء الدهناء وجبال العرمة.','<div class="texte" > <p>تغطي روضة الخفس بساط أخضر على مد البصر، وتحاط بأعمدة تحميها من دخول السيارات تتوزع بها أنواع من الزهور المبهجة كالخزامى والأقحوان والنفل، ومع أواخر الخريف حتى نهاية فصل الربيع، ستحظى بتجربة تخييم متميزة وسط طبيعة ثرية، إذ تحدها من الشرق صحراء الدهناء ومن الغرب جبال العرمة بتكويناتها الصخرية العجيبة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84636185-60416891.jpg?v=1733053903"]','https://cmsphoto.ww-cdn.com/resizeapi/d006de87bc788ff60e17b99d8b89b7cf8a91a7aa/480/',25.4526234,46.4527923,'FF33+24V Khafs Riyadh Principality','','','','https://www.saudi-guide.com/riyadh/i/84636185/rawdat-al-khafs',1,0,'روضه خفس rawdat al khafs اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (84636160,'riyadh','روضة خريم','','rawdat-khuraim','["أماكن سياحية"]','["sights"]','روضة خريم شرق الرياض، محمية خضراء تضم أشجار السدر والطلح، وجهة مثالية للتخييم مع ممرات مائية طبيعية.','<div class="texte" > <p>تحولت روضة خريم&nbsp;إلى محمية بسبب جمالها الفطري بطبيعتها الخضراء و لتمتعها بهدوء مُغري، حيث تضم أشجار السدر والطلح والسمر، وتبعد الروضة عن مدينة الرياض 100 كلم، باتجاهها الشرقي، فيما يعتبر أحد الأسباب التي تبقيها الخيار الأمثل للتخييم هو وجود ممرات مائية اعتادت السيول أن تتخذها طريقًا، لتبقى غالب فصول السنة تحفة بيئية بكامل بهائها. اقضِ ليلة أو ليلتين وعش وقتًا استثنايًا في طبيعة غنّاء.</p> <div>&nbsp;</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84636160-60416883.jpg?v=1733053734"]','https://cmsphoto.ww-cdn.com/resizeapi/e6456d06e3e4106b48ed105dc7847dae13ec61e1/480/',25.3665525,47.3060379,'9884+JCF رماح المروج','','','','https://www.saudi-guide.com/riyadh/i/84636160/rawdat-khuraim',1,0,'روضه خريم اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (84636128,'riyadh','روضة نورة','','rawdat-nourah','["أماكن سياحية"]','["sights"]','روضة نورة شمال الرياض، بيئة صحراوية تزدان بالنباتات الربيعية وتحت حماية أمنية، من أفضل وجهات التخييم الموسمية.','<div class="texte" > <p>تقع روضة نورة على بُعد 150 كلم شمال الرياض قريبًا من محافظة ثادق، وتعد أكثر الأماكن صفاءً، وتقع ضمن محمية الملك عبدالعزيز الملكية، وهي بيئة برية تمتاز بطول عشبها الأخضر في موسمي الربيع والشتاء، ويعد هذان الموسمان أفضل مواسم زيارتها للتخييم وتجديد طاقتك.<br /> &nbsp;</p> <p>&nbsp;تقع الروضة تحت حماية الأمن البيئي، مما يجعل لها سكينة خاصة بها، وتتغطى في الربيع بأنواع النباتات الربيعية البديعة كالروض والحواء والنفل والأقحوان والخزامى.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84636128-60416879.jpg?v=1733053656"]','https://cmsphoto.ww-cdn.com/resizeapi/05eb00b43a63951d9c1c1f40e966363c76d04cf1/480/',25.6943285,46.2207377,'Thadiq Riyadh Province SA','','','','https://www.saudi-guide.com/riyadh/i/84636128/rawdat-nourah',1,0,'روضه نوره اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (83416900,'umluj','منتجع سكس سينز في البحر الاحمر','Six Senses Southern Dunes','six-senses-southern-dunes-mntgaa-sks-synz-fy-albhr-alahmr','["أماكن سياحية"]','["sights"]','منتجع Six Senses Southern Dunes أول وجهة افتتحت في البحر الأحمر عام 2023، ويتميز بأسلوب معماري يحتفي بالإرث النبطي وجمال الصحراء المحيطة.','<div class="texte" > <p>استمتع بالإسترخاء في مواقع ساحرة، ومغامرات استثنائية في إجازتك مع منتجع Six Senses Southern Dunes.</p> <p>كأول وجهة تفتتح في البحر الأحمر لعام 2023، يعرض المنتجع أسلوباً معمارياً فريداً يحتفي بالإرث النبطي والجمال الصحراوي المهيب. تمتع بالراحة والاستجمام الذي يقدمه Six Senses، واكتشف السحر الذي تزخر به العصور القديمة في لك هذا المنتجع المتميز.</p> </div>      <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/83416900-59727227.jpg?v=1728600589", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/83416900-59727230.jpg?v=1728600627", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/83416900-59727231.jpg?v=1728600639"]','https://cmsphoto.ww-cdn.com/resizeapi/3fe8b800de3eb3bf8c9709de369680df6933ad44/480/',25.3797653,37.3334544,'The Red Sea Development Umluj Umluj','','https://www.sixsenses.com/ar/hotels-resorts/middle-east-africa/saudi-arabia/southern-dunes-the-red-sea/','','https://www.saudi-guide.com/umluj/i/83416900/six-senses-southern-dunes-mntgaa-sks-synz-fy-albhr-alahmr',1,0,'منتجع سكس سينز في بحر احمر six senses southern dunes اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (83416523,'eastern-region','سوق الحرفيين الهفوف','','sok-alhrfyyn-alhfof','["التراث والثقافة"]','["heritage"]','يعد سوق الحرفيين بمدينة الأحساء أحد أبرز المعالم التراثية، ويتميز بتصميمه المستوحى من العمارة الأحسائية التقليدية، ويضم محلات مخصصة للحرف اليدوية والفنون الشعبية.','<div class="texte" > <div> <h2>نبذة عن قلعة الحرفيين</h2> <div> <div> <h2>&nbsp;</h2> </div> </div> </div> <div> <div> <p>تعد قلعة الحرفيين ذات الطابع التراثي الأحسائي الشعبي القديم أحد أهم معالم مدينة الأحساء، وتأتي امتداداً لانضمامها لشبكة المدن الإبداعية بمنظمة اليونسكو العالمية في المجال الإبداعي الخاص بالحرف اليدوية والفنون الشعبية.</p> <div> <div data-habitat="C1"> <section> <div> <div> <div> <p>ومن الناحية الفنية تتميز قلعة الحرفيين بتصميمها الأخاذ المستمد من العمارة الأحسائية، تقع على مساحة تزيد عن 12 ألف متر مربع، وتتكون من محلات مخصصة للحرف ذات النشاط الذاتي، بينما خصصت محلات أخرى للحرف التي يستخدم فيها الماء، وترتبط هذه المحلات جميعها بممرات مسقوفة مع وجود نوافذ تسمح بدخول الضوء الطبيعي وتهوية السوق، ويتوسط القلعة فناء مفتوح يضم قهوة شعبية ومخبز تنور تقليديا، إضافة إلى وجود ساحة للفعاليات تنطلق منها الفعاليات والمهرجانات الشعبية.</p> <div>&nbsp;</div> </div> </div> </div> </section> </div> </div> <div> <div data-habitat="C1"> <section> <div>&nbsp;</div> </section> </div> </div> </div> </div> </div>    <div class="texte" > <div> <div data-habitat="C1"> <section> <p>تمنح قلعة الحرفيين لزوارها متعة تسوق فريدة من خلال المحلات التراثية المذهلة التي تجمع تحت سقفها متعة التسوق من خلال شراء أروع المنتجات التراثية التي صُنعت بأيدي أمهر الحرفيين في المدينة.</p> <p>&nbsp;</p> <p>&nbsp;</p> </section> </div> </div> <div> <div data-habitat="C1"> <section id="PromotionalBannerWrapperId"> <div id="promotionalBanner"> <div> <div> <div> <div> <div> <div id="picture">&nbsp;</div> </div> </div> </div> </div> </div> </div> </section> </div> </div> <source media="(max-width: 420px)" srcset="https://scth.scene7.com/is/image/scthacc/al_ahasa_break_free_landing_page_winter_campaign_1920x1080_2:crop-460x620?defaultImage=al_ahasa_break_free_landing_page_winter_campaign_1920x1080_2&amp;wid=460&amp;hei=620 460w" /><source srcset="https://scth.scene7.com/is/image/scthacc/al_ahasa_break_free_landing_page_winter_campaign_1920x1080_2:crop-660x337?defaultImage=al_ahasa_break_free_landing_page_winter_campaign_1920x1080_2&amp;wid=660&amp;hei=337 660w" /> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/83416523-59727073.jpg?v=1728598342", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/83416523-59727079.jpg?v=1728598314"]','https://cmsphoto.ww-cdn.com/resizeapi/139702280e2407dbf819036a763a391a45b109ee/480/',25.3763032,49.5939642,'9HGV+GHG Al Rafaa North Al Hofuf','','https://www.visitsaudi.com/ar/al-ahsa/attractions/handcraft-castle-in-al-ahsa','','https://www.saudi-guide.com/eastern-region/i/83416523/sok-alhrfyyn-alhfof',1,0,'سوق حرفيين هفوف تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (83183204,'jizan','مزرعة قهوتكم لجابر المالكي في بني مالك الدائر','','mzraa-gabr-almalky-fy-bny-malk-aldayr','["أماكن سياحية"]','["sights"]','مزرعة قهوتكم لجابر المالكي في محافظة الداير بني مالك بمنطقة جازان، من مزارع البن في المرتفعات الجبلية التي تشتهر بزراعة القهوة الخولانية.','<div class="texte" > <p class="ql-align-justify"><span>قهوتكم النموذجية&nbsp;</span><span>هو متجر إلكتروني لشركة أسواق قهوتكم متخصص لتلبية رغبات عشاق القهوة. هدفنا هو إيصال تجربه فريدة من نوعها لعملائنا المميزين وتسهيل الوصول لأنواع القهوة المختلفة مع احترافية التوصيل السريع و بأفضل الأسعار.</span></p> <p>&nbsp;</p> <h4><span>نقدر عشقك لقهوتكم</span></h4> <p>في متجر قهوتكم نقدر عشق القهوة في السعودية وهدفنا ان نوفر لعملائنا تجربة فريدة وسهلة في اختيار ما يناسب قهوتكم النموذجية السعودية ولذلك جمعنا كل ما تحتاجونه في مكان واحد.</p> <p>&nbsp;</p> <h4><span>أفاق الخيارات غير محدودة</span></h4> <p>قهوتكم النموذجية السعودية بتوفر كل ما يحتاج اليه محبي وعشاق القهوة من مختلف أنواع القهوة المختصة النموذجية السعودية.</p> <p>&nbsp;</p> <h4><span>الشحن المجاني</span></h4> <p>يوفر متجر قهوتكم النموذجية السعودية الشحن المجاني لعملائها المميزين على مدار العام.</p> <p>&nbsp;</p> <h4><span>الدعم على مدار الساعة</span></h4> <p>تستطيع إرسال رسائل مباشرة لفريق موود قهوة عن طريق الموقع و بسهولة لمساعدتك.</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/veUVmOfw52w?si=jXyNWlzQU5fG4veP&gbyoutube=veUVmOfw52w" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe> <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/83183204-59593001.jpg?v=1727793688", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/83183204-59592990.jpg?v=1727793667"]','https://cmsphoto.ww-cdn.com/resizeapi/cee189b1e1d39dcd9d38a5435c6869586703baa7/480/',17.3674303,43.1859066,'958P+X9F Addayer Al Dayer','0554345539','https://salla.sa/yourcof.com','','https://www.saudi-guide.com/jizan/i/83183204/mzraa-gabr-almalky-fy-bny-malk-aldayr',1,0,'مزرعه قهوتكم لجابر مالكي في بني مالك دائر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (77049378,'jeddah','سيان واتربارك Cyan Waterpark','','syan-oatrbark-cyan-waterpark','["سياحة وترفيه"]','["sights"]','تحظى حديقة الألعاب المائية سيان واتر بارك الواقعة بأبحر الشمالية، بإقبال كبير من محبي الألعاب المائية للاستمتاع بهذه التجربة المشوقة.','<div class="texte" > <p>تحظى حديقة الألعاب المائية "سيان واتر بارك" الواقعة بأبحر الشمالية، بإقبال كبير من محبي الألعاب المائية للاستمتاع بهذه التجربة المشوقة،التي تعد واحدة من أهم وسائل الترفيه التي توفر ألعابًا جماعية ممتعة للكبار والصغار.<br /> وتضم الحديقة المائية التي تقع على مساحة 110 آلاف متر مربع, عددًا كبيرًا من المطاعم والمحال، وتشهد العديد من الأنشطة المائية، عبر الشواطئ والأمواج الصناعية والألعاب المائية، التي خصص جزء منها للسباحة، إلى جانب ألعاب مائية أخرى متنوعة مثل الزلاجات المائية، والنفق المائي، والأمواج الاصطناعية، والممرات المائية.<br /> وتتميز "سيان واتربارك" بتنوع الألعاب المائية من خلال البحيرات الاصطناعية بأحجامها ومساحاتها المختلفة، والتي صممت لتمثل نقلة نوعية في مجال الترفيه والمغامرة لتوفر للزوار من مختلف الفئات العمرية تجربة أنواع مختلفة من المغامرات التنافسية والترفيه طوال فترة وجودهم في الحديقة، إلى جانب بعض المرافق الأخرى التي تحتوي على عدد كبير من الألعاب الشيقة والممتعة مخصصة للأطفال للاستمتاع بأوقاتهم وسط متابعة من الأهالي من خلال الجلسات المحيطة بهذه المرافق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/77049378-55892824.jpg?v=1701239319", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/77049378-55892789.jpg?v=1701239263"]','https://cmsphoto.ww-cdn.com/resizeapi/889d9de66583cb9f0a73886396fd91a4162be04b/480/',21.8128438,39.1122767,'4740 King Saud Rd Jeddah','','https://tickets.cyanwp.com/booking/ar','','https://www.saudi-guide.com/jeddah/i/77049378/syan-oatrbark-cyan-waterpark',1,0,'سيان واتربارك cyan waterpark سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (76774480,'jeddah','واجهة أبحر البحرية Obhur Corniche','','oagh-abhr-albhry-obhur-corniche','["سياحة وترفيه"]','["sights"]','ممشى بحري، ومسطحات خضراء تضم أشجارًا ونخيلًا، وشواطئ عامة للسباحة، ومسار مخصص للدراجات الهوائية.','<div class="texte" > <p>ممشى بحري، ومسطحات خضراء على مساحة 27 ألف م2 تتضمن 1.080 شجرة ونخلة، وشواطئ عامة للسباحة بمساحة 5.800 م2 ومسار للدراجات بطول 2.600م، وشواطئ رملية جافة بمساحة 10.350م2 ، ومنطقة ألعاب للأطفال بمساحة 560م ومواقف للسيارات تتجاوز 1.272 موقف، إضافة إلى سقالة بحرية بطول 130 مترًا، ومبان خدمية واستثمارية، وأعمال بحرية وتجهيز للبنية التحتية بشكل كامل، من شبكة للكهرباء وشبكة للصرف الصحي وشبكة تصريف لمياه الأمطار والسيول، كما تضمنت تجهيزات المشروع توفير 125 كاميرا للمراقبة تغطي كامل الموقع مرتبطة بغرفة للتحكم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76774480-55345807.jpg?v=1700265275", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76774480-55345823.jpg?v=1700265474"]','https://cmsphoto.ww-cdn.com/resizeapi/a5338dfe53f75278f0823a3d62f7d589f662589b/480/',21.7219876,39.1143151,'P4C7+QPW Abhur Al Junoobiyah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/76774480/oagh-abhr-albhry-obhur-corniche',1,0,'واجهه ابحر بحريه obhur corniche سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (76340477,'alula','حي الجديدة للفنون','AlJadeedah Arts District','aljadidah-arts-district','["أماكن سياحية"]','["sights"]','استكشف الأجواء الإبداعية في حي الجديدة للفنون بالعلا، حيث تلتقي المعارض والمقاهي والمتاجر الفنية والأعمال اليدوية في أجواء ثقافية فريدة تعكس تراث المنطقة.','<div class="texte" > <h2>استكشف الأجواء الإبداعية وتأمل أروع التصاميم الفنية&nbsp;</h2> <p>تجمع هذه الوجهة الحيوية روّاد الثقافة والفنون، وهي جزء من بلدة العلا القديمة التي حصلت على لقب أفضل قرية سياحية بتصنيف منظمة السياحة العالمية.</p> <p>يحتضن حي الجديدة للفنون المشهد &nbsp;الثقافي والإبداعي المزدهر في العلا مع العديد من المطاعم، والمقاهي، ومتاجر الأعمال الفنية.&nbsp;</p> <p>تتزين ساحات وشوارع الحي باللوحات الجدارية والأعمال الفنية، ويتميزّ بأكبر سجادة مرسومة باليد في العالم على طرقاته المخصصة للمشي. ويستضيف حي الجديدة للفنون مجموعة متنوعة من المعارض الفنية، المحلية والعالمية، على مدار العام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76340477-54495505.jpg?v=1698915133", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76340477-54495521.jpg?v=1698915286"]','https://cmsphoto.ww-cdn.com/resizeapi/f2130b6b9fa1c41d9dae4864879591275fccb0aa/480/',25.8390234,38.1728168,'Al Jadedah Al Ula Al Madinah Province','','https://www.experiencealula.com/ar/discover-alula/arts-culture/aljadidah','','https://www.saudi-guide.com/alula/i/76340477/aljadidah-arts-district',1,0,'حي جديده للفنون aljadeedah arts district اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (76340282,'alula','الواحة','The Oasis','the-oasis','["أماكن سياحية"]','["sights"]','الواحة في العلا وجهة مثالية للمشي والاسترخاء بين مزارعها الغنّاء التي تعود لآلاف السنين، مع مطاعم ومقاهي متنوعة وجلسات مريحة وأجواء تراثية أصيلة.','<div class="texte" > <h2>وجهة مثالية للمشي والاسترخاء بين أجمل المناظر الطبيعية</h2> <p>الواحة هي جزء من بلدة العلا القديمة التي حصلت على لقب أفضل قرية سياحية بتصنيف منظمة السياحة العالمية.<br /> <br /> ازدهرت مزارع الواحة الغنّاء منذ آلاف السنين، واستفادت الحضارات القديمة من مياهها الوفيرة وتربتها الخصبة لزراعة العديد من المحاصيل. تعتمد أساليب الزراعة في الواحة إلى يومنا هذا على مفاهيم الاستدامة البيئية، وتوفّر لضيوفها مسارات المشي بين أروع المناظر الطبيعية، بالإضافة إلى مجموعة متنوعة من المطاعم والمقاهي مع جلسات مريحة وأجواء مثالية للاسترخاء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76340282-54495233.jpg?v=1698913890"]','https://cmsphoto.ww-cdn.com/resizeapi/74b3d8fd2e836aeb72ff595638b3b3187cad8c0d/480/',26.6270084,37.9167131,'JWG8+RM4 AlUla Al Ula','','https://www.experiencealula.com/ar/discover-alula/alula-old-town-village/the-oasis','','https://www.saudi-guide.com/alula/i/76340282/the-oasis',1,0,'واحه the oasis اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (76340242,'alula','وادي عِشار','Wadi Ashar','ashar-valley','["أماكن سياحية"]','["sights"]','يتميز وادي عِشار بتضاريسه الجغرافية المذهلة مع وديان صحراوية تُغطيها الرمال والنباتات البرية وتكوينات صخرية عجيبة، ويضم أفخم فنادق العلا وقاعة مرايا الحائزة على جوائز عالمية.','<div class="texte" > <div> <div> <p>يتميز وادي عِشار بتضاريسه الجغرافية المذهلة مع وديان صحراوية تُغطيها الرمال والنباتات البرية، وتكوينات صخرية عجيبة نحتتها الرياح عبر ملايين السنين. ويحتضن الوادي بين معالمه الطبيعية المدهشة البعض من أفخم فنادق العلا بالإضافة إلى قاعة مرايا الحائزة على جوائز عالمية، أكبر مبنى مغطى بالمرايا العاكسة في العالم.</p> <div>&nbsp;</div> </div> </div> <div> <div> <div>&nbsp;</div> </div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76340242-54495091.jpg?v=1698913531"]','https://cmsphoto.ww-cdn.com/resizeapi/dcef0a515b8d0d4c1a3692a60a2c1c019aa63c78/480/',26.7398414,37.8498875,'Al Ula Al Ula Al Madinah Province','','https://www.experiencealula.com/ar/discover-alula/nature-outdoors/ashar-valley','','https://www.saudi-guide.com/alula/i/76340242/ashar-valley',1,0,'وادي عشار wadi ashar اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (76339838,'alula','قاعة مرايا','Maraya Concert Hall','maraya-concert-hall','["أماكن سياحية"]','["sights"]','أكبر مبنى عاكس بالمرايا في العالم وفق موسوعة غينيس، يستضيف حفلات لكبار الفنانين العرب والعالميين ومعارض فنية عالمية وسط الأودية الصحراوية بالعلا.','<div class="texte" > <p>تنهض قاعة مرايا من الرمال مثل السراب، وتُغطي هيكل المبنى ألواح عاكسة تُظهر جمال العلا وتتناغم مع المناظر الطبيعية وسط الأودية الصحراوية. تتباهى هذه التحفة الفنية بمساحة 9,740 متر مربع من المرايا العاكسة، مما يجعلها أكبر مبنى عاكس في العالم وفقاً لموسوعة غينيس للأرقام القياسية.<br /> <br /> تحتفل قاعة مرايا بالدور التاريخي المهم للعلا، باعتبارها نقطة التقاء الحضارات القديمة على مَر القرون، وتشكّل المرايا العاكسة على المبنى لوحة فنية معاصرة تُظهر التراث العريق للمنطقة. تحتضن قاعة مرايا مشهد الثقافة والفنون المزدهر في العلا، وتستضيف العديد من المناسبات الفنية والترفيهية المتميّزة لتحفر اسم العلا كمركز ثقافي على مستوى عالمي.<br /> <br /> استضافت قاعة مرايا الكثير من الحفلات الموسيقية لأهم نجوم الوطن العربي مثل: محمد عبده، أنغام، ماجد المهندس، كاظم الساهر، وأصالة نصري وكذلك مشاهير العالم مثل: اليشا كيز، جون ليجند، ون ريببلك، آشِر، وسيل. فضلاً عن المعارض الفنية والإبداعية، مثل معرض «<a href="https://www.experiencealula.com/ar/discover-alula/arts-culture/fame-andy-warhol-in-alula" target="_blank">شهرة: آندي وارهول في العلا</a>» ومعرض «<a href="https://www.experiencealula.com/ar/discover-alula/arts-culture/fame-andy-warhol-in-alula" target="_blank">ما يبقى في الأعماق</a>».<br /> <br /> يُعتبر حفل توزيع جوائز منظمة السياحة العالمية من أهم الفعاليات التي قامت في قاعة مرايا، حيث فازت بلدة العلا القديمة بلقب&nbsp;<a href="https://www.experiencealula.com/ar/discover-alula/heritage/alula-old-town/unwto-best-tourism-village" target="_blank">أفضل قرية سياحية</a>&nbsp;إلى جانب 32 قرية أخرى من جميع أنحاء العالم.<br /> <br /> تُرحّب قاعة مرايا بالمناسبات المختلفة، من اجتماعات العمل والمؤتمرات إلى حفلات الزفاف والعروض الفنية، كما يستقبل الشيف جايسون أثرتون البريطاني، الحائز على نجمة ميشلان، ضيوف مطعمه الراقي «<a href="https://www.experiencealula.com/ar/plan-your-trip/where-to-eat/maraya-social" target="_blank">مرايا سوشل</a>» على سطح المبنى.<br /> &nbsp;</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/HFD3nBu-jmA?si=ajijY-6_317mnZBj&gbyoutube=HFD3nBu-jmA" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe> <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76339838-54494742.jpg?v=1698912093", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76339838-54494642.jpg?v=1698912040"]','https://cmsphoto.ww-cdn.com/resizeapi/944898e909846bb6f0ff5aafd31195aef493ac12/480/',26.7431645,37.8648114,'Al Atheeb Al Ula Al Madinah Province','','https://www.experiencealula.com/ar/business-special-events/maraya','','https://www.saudi-guide.com/alula/i/76339838/maraya-concert-hall',1,0,'قاعه مرايا maraya concert hall اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (76099072,'riyadh','ڤيا رياض','VIA Riyadh','via-riyadh','["ترفيه واستجمام", "أماكن سياحية"]','["fun", "sights"]','فيا رياض على الطراز السلماني، وجهة فاخرة تضم فندق سانت ريجس ومحال عالمية للأزياء والمطاعم الفاخرة.','<div class="texte" > <p>منطقة مصممة على الطراز السلماني بالتناغم مع الهوية المحلية لمدينة الرياض، يتواجد فيها أحد أشهر فنادق الخمس نجوم "سانت ريجس الرياض"، وسبع صالات سينما راقية مع عدد من البوتيكات العالمية الحصرية في عالم الأزياء والمجوهرات والعديد من المطاعم والمقاهي العالمية لأول مرة في المملكة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76099072-53857471.jpg?v=1698217669", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/76099072-53857567.jpg?v=1698218618"]','https://cmsphoto.ww-cdn.com/resizeapi/b10619ad3f9173929019cc88992fcbb649daf1bb/480/',24.6670649,46.6263991,'الهدا، Riyadh Riyadh Principality','','https://www.viariyadh.com/ar','','https://www.saudi-guide.com/riyadh/i/76099072/via-riyadh',1,0,'ڤيا رياض via riyadh ترفيه واستجمام اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75766235,'riyadh','مهرجان الرياض لعربات الطعام','Food Truck Park','mhrgan-alryad-laarbat-altaaam-food-truck-park','["موسم الرياض"]','["fun"]','مهرجان الرياض لعربات الطعام تجربة ترفيهية تجمع عربات طعام محلية وعالمية في مكان واحد، مع مأكولات متنوعة وأنشطة ترفيهية للعائلة.','<div class="texte" > <div> <div> <div data-testid="collapsable-text">مهرجان الرياض لعربات الطعام يسعى لدمج الثقافة المحلية والعالمية من خلال استضافة أفضل عربات الطعام حول العالم لخلق تجربة ترفيهية بنكهات مختلفة لتستمتعوا بأفضل المأكولات والأنشطة الترفيهية في مكان واحد.</div> <div>&nbsp;</div> </div> </div> <div>&nbsp;</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75766235-53281972.jpg?v=1696966044", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75766235-53281981.jpg?v=1696966058"]','https://cmsphoto.ww-cdn.com/resizeapi/6d55f2d5020e529511e9d15394ff82ef15a1bb6b/480/',24.7755014,46.6094175,'الحوي Riyadh Riyadh Principality','','https://riyadhseason.com/ar-SA/zone/food-truck-park','','https://www.saudi-guide.com/riyadh/i/75766235/mhrgan-alryad-laarbat-altaaam-food-truck-park',1,0,'مهرجان رياض لعربات طعام food truck park موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75766073,'riyadh','وندر جاردن','Wonder garden','ondr-gardn-wonder-garden','["موسم الرياض"]','["fun"]','وندر جاردن مدينة ترفيهية في الرياض من ثلاث مناطق، يستمتع فيها الزوار بمشاهدة طيور الفلامنجو والفراشات الملونة والأشجار الخلابة في أجواء أشبه بالخيال.','<div class="texte" > <div> <div> <div data-testid="collapsable-text">مدينة ترفيهية ساحرة مكونة من ٣ مناطق مليئة بالمتعة، حيث يمكن لزوارها الاستمتاع بمشاهدة طيور الفلامنجو الساحرة، والفراشات الملونة والأشجار الخلابة في عالم أشبه ما يكون بالخيال!</div> <div>&nbsp;</div> </div> </div> <div>&nbsp;</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75766073-53281897.jpg?v=1696965459"]','https://cmsphoto.ww-cdn.com/resizeapi/1437e3cfcbee1332979ce7087baf0272ac6a7b1b/480/',24.8066988,46.5851571,'4065 رقم 225 Al Qirawan','','https://riyadhseason.com/ar-SA/zone/wonder-garden','','https://www.saudi-guide.com/riyadh/i/75766073/ondr-gardn-wonder-garden',1,0,'وندر جاردن wonder garden موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75765051,'riyadh','ذا قروفز','The Groves','groves-tha-krofz','["موسم الرياض"]','["fun"]','ذا قروفز وجهة ترفيهية في حي السفارات بالرياض ضمن فعاليات موسم الرياض، تقدم للزوار تجربة مبتكرة مليئة بالإثارة في أجواء مميزة.','<div class="texte" > <p>ذا قروفز من أبرز مناطق موسم الرياض، وهي وجهة راقية تجمع بين المطاعم الفاخرة والتسوق والأجواء الهادئة بين الأشجار والبحيرات. تضم المنطقة مطاعم متنوعة مثل قلناز خانم للمأكولات الفارسية وحارة أبو عصام للمأكولات الشامية، ومتجر سمودا للمنتجات الحرفية، وحديقة لوكا بارك لخدمات الحيوانات الأليفة، وجلسات كشتة ذا قروفز بجانب البحيرة، إلى جانب قرية ذا قروفز بأكواخها المفتوحة ومقاهيها وممراتها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75765051-53281490.jpg?v=1696962126", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75765051-53281516.jpg?v=1696962139"]','https://cmsphoto.ww-cdn.com/resizeapi/a5f1ae943cceea9d1e18c25775e58aad0d913ac5/480/',24.6862945,46.621746,'Alkhawabi St Al Safarat Riyadh','','https://riyadhseason.com/ar-SA/zone/the-groves','','https://www.saudi-guide.com/riyadh/i/75765051/groves-tha-krofz',1,0,'ذا قروفز the groves موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75765037,'riyadh','سوق الأولين','','sok-alaolyn','["موسم الرياض"]','["fun"]','سوق الأولين في الرياض تجربة سوق شعبي تستحضر تراث نجد القديم، مع عروض وفعاليات تعكس الثقافة المحلية ومحال تبيع المنتجات التقليدية.','<div class="texte" > <div> <div> <div data-testid="collapsable-text">استمتـع بتجربـة السوق الشعبي وتراث ماضـي نجـد فـي سـوق األولـين، حيـث العـديـد مــن العــروض الحماسية والفعاليات التي تعكـس الثقافة المحلية والمحال التي تبيع المنتجات التقليدية القديمة، في كل ركن وزاوية تتعرف فيها أكثر على هوية السوق النجدي القديم.</div> <div>&nbsp;</div> </div> </div> <div>&nbsp;</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75765037-53281406.jpg?v=1696961759", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75765037-53281408.jpg?v=1696961748"]','https://cmsphoto.ww-cdn.com/resizeapi/4632862d1a3e649e10aa136cc4fad6528cc42f50/480/',24.7519365,46.740639,'QP2R+RCM King Abdullah Dt. Riyadh','','https://riyadhseason.com/ar-SA/zone/souq-alawaleen','','https://www.saudi-guide.com/riyadh/i/75765037/sok-alaolyn',1,0,'سوق اولين موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75764958,'riyadh','واجهة روشن','Roshn Front','oagh-roshn','["موسم الرياض", "أماكن سياحية"]','["fun", "sights"]','واجهة روشن وجهة عصرية في الرياض تجمع بين العمل والترفيه، وتضم مطاعم وأسواقًا ومساحات مفتوحة بتصميم يمنح الزوار تجربة مختلفة.','<div class="texte" > <p>واجهة روشن حيث تُعيد اكتشاف شغفك، وطريقة عملك، وكيفية الترفيه عن نفسك، من خلال التصميم الذي يمنحك تجربة مختلفة تتوافق مع متطلباتك. وحيث الحياة العملية والحياة الاجتماعية تندمجان معًا بطريقة مبتكرة. صُمّمت واجهة الرياض لتُثري حياتك اليومية عبر تجارب استثنائية متمثلة في المطاعم والأسواق والمساحات المفتوحة، مما يمنحك نمط الحياة الأجمل في قلب مدينة الرياض.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75764958-53281339.jpg?v=1696961564", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75764958-53281377.jpg?v=1696961608"]','https://cmsphoto.ww-cdn.com/resizeapi/05209b49272f865565544ab5f5736a63da6af601/480/',24.8349029,46.7295433,'Riyadh Province King Khalid International Airport Riyadh','','https://riyadhseason.com/ar-SA/zone/roshn-front','','https://www.saudi-guide.com/riyadh/i/75764958/oagh-roshn',1,0,'واجهه روشن roshn front موسم رياض اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75764909,'riyadh','بوليفارد وورلد','Boulevard World','boulevard-world-bolyfard-oorld','["موسم الرياض"]','["fun"]','بوليفارد وورلد في حي حطين بالرياض وجهة ترفيهية يتعرف فيها الزوار على حضارات وثقافات مختلفة، مع تجارب ومغامرات متنوعة بين الفنون والرياضة.','<div class="texte" > <div> <div> <div data-testid="collapsable-text">بوليفارد وورلد هو المكان الذي يمكنك فيه التعرف على عدة حضارات والتجوّل بين ثقافاتها المختلفة، ويتيح لك تجربة العديد من المغامرات المنوعة بين الفنون والرياضة وغيرها من التجارب الجديدة والفريدة</div> <div>&nbsp;</div> </div> </div> <div>&nbsp;</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75764909-53281299.jpg?v=1696961313"]','https://cmsphoto.ww-cdn.com/resizeapi/a09f66e16f949448a9c2f05126fb8c7d5b266886/480/',24.7725623,46.5995014,'Riyadh Hittin Riyadh Principality','','https://riyadhseason.com/ar-SA/zone/boulevard-world','','https://www.saudi-guide.com/riyadh/i/75764909/boulevard-world-bolyfard-oorld',1,0,'بوليفارد وورلد boulevard world موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75764610,'riyadh','بوليفارد سيتي','Boulevard City','boulevard-city-bolyfard-syty','["موسم الرياض"]','["fun"]','بوليفارد سيتي في شمال الرياض من أبرز وجهات موسم الرياض، يضم حدائق ومقاهي ومطاعم ومحلات لماركات محلية وعالمية، إضافة إلى النافورة الراقصة.','<div class="texte" > <h2>استمتع بمستوى جديد من المرح والتسلية</h2> <div> <div data-testid="collapsable-text">إنّ منطقة بوليفارد رياض سيتي، تعدّ واحدةً من أهم وجهات الموسم، والتي تقع في شمال الرياض، وهي مركز الترفيه الأكبر والمستدام في الموسم، إذ تضمّ الكثير من الفعاليات؛ وذلك لما تتمتّع به من حدائق ومقاهٍ، ومطاعم ومحلات لأشهر الماركات المحلية والعالمية الكائنة بمنطقة بوليفارد سكوير، بجانب احتوائها للمشهد الخلّاب للنافورة الراقصة. كذلك وتحوي منطقة جاردن هب على العديد من مطاعم الوجبات السريعة والمسارح ذات العروض الفنية والغنائية،</div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75764610-53281215.jpg?v=1696960927", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75764610-53281190.jpg?v=1696960883"]','https://cmsphoto.ww-cdn.com/resizeapi/49da922a25c7b55dbddc763ba9924ceca3f3ed90/480/',24.7679246,46.6013928,'Hittin Riyadh Riyadh Principality','','https://riyadhseason.com/ar-SA/zone/boulevard-city','','https://www.saudi-guide.com/riyadh/i/75764610/boulevard-city-bolyfard-syty',1,0,'بوليفارد سيتي boulevard city موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75764409,'riyadh','المملكة ارينا','KINGDOM ARENA','bolyfard-hol-boulevard-hall','["موسم الرياض"]','["fun"]','المملكة أرينا في حي حطين بالرياض مبنى متعدد الاستخدامات بمساحة شاسعة، جُهّز بأحدث التقنيات لاستضافة الفعاليات الكبرى وفق المعايير العالمية.','<div class="texte" > <p>مبنى بمساحة شاسعة تزيد عن ٢٠٠ ألف متر مربع، تم بناؤه وتجهيزه بأحدث التقنيات التي تخدم جميع الفعاليات المقامة والمعتمدة عالمياً، خلال ٦٠ يوماً، ليتسع لأكثر من ٤٠ ألف زائر.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75764409-53281069.jpg?v=1696960690", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75764409-53281170.jpg?v=1696960724"]','https://cmsphoto.ww-cdn.com/resizeapi/3ecd46e310353af9bca71a39163cf4588543a4de/480/',24.7817509,46.6099001,'8161 المجارده حي حطين','','https://riyadhseason.com/ar-SA/zone/boulevard-hall','','https://www.saudi-guide.com/riyadh/i/75764409/bolyfard-hol-boulevard-hall',1,0,'مملكه ارينا kingdom arena موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75572411,'alula','اوكتو','OKTO','okto-restaurant','["مطاعم وكافيهات"]','["food"]','مطعم الشيف أنتينوس فوتيناكيس يقدم قائمة طعام حصرية بالطابع الأسود المستوحى من جيولوجيا العلا، مع إطلالات على الواحة الغنّاء والتضاريس الصحراوية.','<div class="texte" > <p>يُبدع الشيف أنتينوس فوتيناكيس، أحد أهم الطهاة العالميين، بتقديم قائمة طعام حصرية تتميز بالطابع الأسوَد المستوحى من جيولوجيا العلا الاستثنائية. ويتميز اوكتو بموقعه المثالي مع إطلالات مفتوحة على الواحة الغنّاء، والتضاريس الصحراوية المذهلة في الأفق البعيد. ندعو ضيوفنا للاستمتاع بمشروبهم المفضّل مع مشاهد تخطف الأنظار عند غروب الشمس، وتأمّل النجوم الساطعة في سماء الصحراء باستخدام التلسكوبات الحديثة المتوفرة في المطل. تتوفر الخيارات النباتية بأنواعها مع مأكولات خالية من الجلوتين أو الألبان.</p> </div>    <iframe width="560" height="315" src="https://www.youtube.com/embed/tgfKMnOkcCc?si=bQamLpTRLtdKc6Jh&gbyoutube=tgfKMnOkcCc" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe> <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75572411-53030199.jpg?v=1696243315", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75572411-53030218.jpg?v=1696243347"]','https://cmsphoto.ww-cdn.com/resizeapi/a394424b044ec56cd5e9a94fdeb0bc2f9899e0ad/480/',26.6324386,37.8967285,'King Abdulaziz Park Al Ula Al Ula','','https://www.experiencealula.com/ar/plan-your-trip/where-to-eat/okto','','https://www.saudi-guide.com/alula/i/75572411/okto-restaurant',1,0,'اوكتو okto مطاعم وكافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75570719,'alula','حرة في بانيان تري','Harrat at Banyan Tree','harrat-banyan-tree','["مطاعم وكافيهات"]','["food"]','قائمة طعام تجمع نخبة من أهم الطهاة العالميين، تقدم مأكولات بحرية ومشاوي ومقبلات ومشاوي عربية ضمن أجواء داخلية تقليدية أنيقة في منتجع بانيان تري بالعلا.','<div class="texte" > <p>تتضمن قائمة الطعام التي يُبدع بتحضيرها نخبة من أهم الطُهاة خيارات متنوعة من المأكولات البحرية، المعكرونة بأنواعها، المقبلات والمشاوي العربية. يستقبل حرة ضيوفه بتصاميم داخلية تقليدية مع أعمال فنية ومنتجات الحِرف اليدوية، مثل الأواني الفخارية والسجّاد الشرقي، ليستمتعوا بالأجواء التراثية الجميلة مع النكهات المحلية الأصيلة.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75570719-53027467.jpg?v=1696240688", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75570719-53027450.jpg?v=1696240655"]','https://cmsphoto.ww-cdn.com/resizeapi/73a93861bac5a83807d3ada06588ac179ee6de5b/480/',26.7555446,37.8629753,'Wadi Ashar Al Ula Al Ula','+966 145120000','https://www.experiencealula.com/ar/plan-your-trip/where-to-eat/harrat','','https://www.saudi-guide.com/alula/i/75570719/harrat-banyan-tree',1,0,'حره في بانيان تري harrat at banyan tree مطاعم وكافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75570200,'alula','تاما في هابيتاتس','Habitas AlUla','habitas-alula-tama','["مطاعم وكافيهات"]','["food"]','مطعم تاما في هابيتاس العلا يقدم قائمة طعام خبر طازج مع المربيات أو العسل بالزنجبيل، والمأكولات النباتية المتنوعة، ضمن أجواء صحراوية دافئة.','<div class="texte" > <p>يُجسّد مطعم تاما في العلا باسمه المأخوذ من اللغة الآرامية بمعنى «هنا والآن» روح علامة هابيتاس التجارية التي تدعو ضيوفها لعيش اللحظة، في المكان والزمان الحالي، وتجديد التواصل. رحلة عبر الزمن تُعيد إحياء النكهات الأصيلة من شبه الجزيرة العربية، مع أجود المحاصيل الطازجة من المزارع المحلية حول العلا. تتضمن قائمة الطعام الخبر الطازج مع المربيات الشهية أو العسل بالزنجبيل، المأكولات النباتية المتنوعة، ريب اي ستيك. بينما تتميز أصناف الحلويات بنكهات الواحة الغنّاء مع كيكة التمر بالتوفي، حلوى أم علي التقليدية، وغيرها الكثير.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75570200-53026379.jpg?v=1696240138", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75570200-53027321.jpg?v=1696240392"]','https://cmsphoto.ww-cdn.com/resizeapi/e195437f9d6ee51cf60e17b2aa93f57e3b8194c2/480/',26.7677909,37.8482524,'QR9X+48 Shlal Al Ula','+966 148213900','https://www.experiencealula.com/ar/plan-your-trip/where-to-eat/tama','','https://www.saudi-guide.com/alula/i/75570200/habitas-alula-tama',1,0,'تاما في هابيتاتس habitas alula مطاعم وكافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (75569286,'alula','مرايا سوشل للشيف جايسون أثرتون','Maraya Social by Jason Atherton','maraya-social-jason-atherton','["مطاعم وكافيهات"]','["food"]','مطعم الشيف جايسون أثرتون فوق سطح قاعة مرايا بالعلا، يقدم أطباقاً عربية وبريطانية معاصرة وسط أجواء عصرية مطلة على وادي عِشار.','<div class="texte" > <div> <div> <div> <p>يفتتح الشيف جايسون أثيرتون، أحد أبرز الطهاة في المملكة المتحدة وصاحب المطاعم الحائزة على نجمة ميشلان في جميع أنحاء العالم، مطعمه الراقي «مرايا سوشل» على سطح قاعة مرايا الحائزة على جوائز عالمية. تتميز قائمة الطعام بأطباق المشاركة، والموكتيلات الفاخرة، ومأكولات البحر الأبيض المتوسط بالإضافة إلى روائع فنون الطهي العربية والبريطانية المحضّرة بأسلوب الشيف أثيرتون الاستثنائي من أجود المكوّنات الموسمية. وجهة متكاملة توفّر لضيوف العلا فرصة مثالية للاسترخاء وتناول الطعام مع أجمل الإطلالات على التكوينات الصخرية المذهلة في وادي عِشار.</p> <div>&nbsp;</div> </div> </div> </div> </div>      <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75569286-53024909.jpg?v=1696238138", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75569286-53025069.jpg?v=1696238676", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/75569286-53025006.jpg?v=1696238380"]','https://cmsphoto.ww-cdn.com/resizeapi/1e12954e9c0f532b32a91df43b55a63b9d71d5cd/480/',26.7429878,37.8658089,'Al Ula Al Ula Al Madinah Province','966508767166','https://www.experiencealula.com/ar/plan-your-trip/where-to-eat/maraya-social','','https://www.saudi-guide.com/alula/i/75569286/maraya-social-jason-atherton',1,0,'مرايا سوشل للشيف جايسون اثرتون maraya social by jason atherton مطاعم وكافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (74246511,'asir-region','قلاع آل أبونقطة المتحمي / طبب التاريخية_ ABO NOGHTA CASTLES & HISTORIC TABAB','','abo-noghta-castles-historic-tabab','["التراث والثقافة"]','["heritage"]','تبرز قصور آل أبو نقطة المتحمي، المطلة على ضفاف وادي تهلل، كأحد أهم قصور قرية طبب التاريخية، وتتكون من 6 مواقع مبنية من حجارة الجبال الصخرية بارتفاعات متباينة تصل إلى 16 مترًا. تضم القصور مدافن ثمانية مبنية في جوف الجبل الصخري استخدمها الأهالي قديمًا لتخزين وحفظ الحبوب، إضافة إلى مطاعم ذات جلسات خارجية مطلة على القرية ومزارعها، وأكشاك ومتاجر للهدايا التذكارية، ومخبز لتذوق الخبزة الجنوبية الطازجة.','<iframe width="560" height="315" src="https://www.youtube.com/embed/Ndc5OReWS44?gbyoutube=Ndc5OReWS44" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe> <div class="texte" > <h2>القصور التاريخية في طبب</h2> <p>تبرز قصور آل أبو نقطة المتحمي، والمطلة على ضفاف وادي تهلل، كأحد أهم قصور قرية طبب التاريخية، وتتكون من 6 مواقع مبنية من حجارة الجبال الصخرية، وهي متباينة الارتفاع بمساحة 4 آلاف متر، فيما تبرز جمالية نوافذها وحواف قصورها العليا باللون الأبيض المنسجم مع السحاب الذي يفاجئ الزوار من حين لآخر.</p> <p>يمكنك مشاهدة المدافن الثمانية المبنية في جوف الجبل الصخري، والتي استخدمها الأهالي قديمًا لتخزين وحفظ الحبوب، تتميز الصخور بعدم امتصاصها للمياه أثناء سقوط الأمطار، ويمتد عمقها إلى 3 أمتار، بينما يصل عرضها إلى 16م.</p> <p>تتميز القصور بمرافق متنوعة، منها مطاعم ذات جلسات خارجية مطلة على القرية ومزارعها، وأكشاك خدمة ومتاجر للحصول على الهدايا التذكارية، ومخبز لتذوق الخبزة الجنوبية الطازجة من التنور الحار.</p> <p>لعيش تجربة السكن في قصور آل أبو نقطة المتحمي، يمكنك الحجز في أحد أجنحتها المهيئة لقضاء لحظات تعرف طريقها لذاكرتك.</p> <p><a href="https://abha.platinumlist.net/ar/event-tickets/87857/historic-tabab">لحجز التذاكر من هنا&nbsp;</a></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/74246511-51650560.jpg?v=1690280907"]','https://cmsphoto.ww-cdn.com/resizeapi/5e38d4be8f7bcd9de88eb486ea1cb8e97e113500/480/',18.3739437,42.3773046,'Tabab Asir Principality Aseer Province','','https://www.visitsaudi.com/ar/see-do/destinations/abha/historical-tabab-aseer','','https://www.saudi-guide.com/asir-region/i/74246511/abo-noghta-castles-historic-tabab',1,0,'قلاع ابونقطه متحمي / طبب تاريخيه abo noghta castles & historic tabab تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (73903582,'albaha','منتزه الأمير مشاري','Prince Mishari bin Saud Park','prince-mishari-bin-saud-park-mntzh-alamyr-mshary','["أماكن سياحية"]','["sights"]','منتزه الأمير مشاري بن سعود في غابة خيرة ببني حسن منتزه واسع يضم مسطحات خضراء وجلسات وألعاباً للأطفال وملعب كرة قدم.','<div class="texte" > <p>يقع منتزه الأمير مشاري بن سعود داخل غابة خيرة على مساحة إجمالية تُقدّر بنحو 330 ألف متر مربع، ويضم منطقة ألعاب للأطفال وملعب كرة قدم إلى جانب المسطحات الخضراء والجلسات، كما يضم مواقف تتسع لنحو 300 سيارة ودورات مياه ومصلى ومواقع استثمارية متعددة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/73903582-51405893.jpg?v=1688628788"]','https://cmsphoto.ww-cdn.com/resizeapi/5ffe830c9e897019a94739569d3f1404bd910fe3/480/',20.0521954,41.3977336,'SA Bani Hassan Al Bahah Province','','https://amanatalbaha.gov.sa/ar/Departments/ImageAlbum/129?deptId=117','','https://www.saudi-guide.com/albaha/i/73903582/prince-mishari-bin-saud-park-mntzh-alamyr-mshary',1,0,'منتزه امير مشاري prince mishari bin saud park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (72400320,'alula','ميدان المنشية','AlManshiyah Plaza','almanshiyah-plaza','["أماكن سياحية"]','["sights"]','وجهة جديدة بروحٍ تاريخية تفتح أبوابها بعد ترميم سكة حديد الحجاز القديمة، يُرحب بجميع أفراد العائلة مع مطاعم ومقاهي وساحات لعب للأطفال.','<video controls controlsList="nodownload" poster="https://cmsphoto.ww-cdn.com/superstatic/images/2892882/video/2737813/player/player_preview.jpg?v=1682414428" width="100%" oncontextmenu="return false;"><source src="https://www.saudi-guide.com/apiv3/video/getIphoneSVideo/2737813/42580132.mp4/" type="video/mp4" /></video> <div class="texte" > <p>وجهة جديدة بروحٍ تاريخية تفتح أبوابها بعد ترميم سكة حديد الحجاز القديمة لاستقبال ضيوف العلا. يُرحب ميدان المنشية بجميع أفراد العائلة مع العديد من المطاعم والمقاهي، ساحات اللعب المخصصة للأطفال، الجلسات الخارجية، الحفلات الموسيقية أيام الجمعة وغيرها الكثير من المفاجآت.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/72400320-50375055.jpg?v=1682413927"]','https://cmsphoto.ww-cdn.com/resizeapi/9e5b64acb18a61bf62528c10a1c6efb767a8eefa/480/',26.603042,37.9400868,'الوادي 2، 3066، Al Ula AlUla','','https://www.experiencealula.com/ar/plan-your-trip/what-to-do/almanshiyah-plaza','','https://www.saudi-guide.com/alula/i/72400320/almanshiyah-plaza',1,0,'ميدان منشيه almanshiyah plaza اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (71694948,'alula','صخرة الحوار','Dialogue Rock','dialogue-rock','["التراث والثقافة"]','["heritage"]','جبل كبير يُروى أنه ناقة نبي الله صالح التي خرجت منه، يقع بالقرب من منطقة الحِجر ضمن محافظة العلا التابعة لمنطقة المدينة المنورة.','<div class="texte" > <p>جبل الحوار أو صخرة الحوارة هو عبارة عن جبل كبير أملس يُروى أن ناقة نبي الله صالح خرجت منه ولجا إليه ابن الناقة بعد عقر الناقة، ويقع الجبل جانب منطقة مزحم الناقة والتي ترتبط أيضاً بقصة ناقة نبي الله صالح وقتها في ذلك المكان ويقع الجبل في منطقة الحجر شمال محافظة العلا التابعة لمنطقة المدينة المنورة.</p> <p>&nbsp;</p> <p>حقوق الصورة ل&nbsp;<span>i - Nageeb</span></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/71694948-49936916.jpg?v=1679771539"]','https://cmsphoto.ww-cdn.com/resizeapi/d5ed89b79939556639f7bd2dfd23d8d97eb650fd/480/',26.8107724,37.8828794,'RV6M+852 Hegra AlUla','','','','https://www.saudi-guide.com/alula/i/71694948/dialogue-rock',1,0,'صخره حوار dialogue rock تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (69960794,'riyadh','ليسن فالي','Laysen Valley','laysen-valley','["أماكن سياحية"]','["sights"]','ليسن فالي بالرياض، مشروع حيوي متطور متعدد الأنشطة يدعم تطلعات رؤية 2030 في تحسين جودة الحياة.','<div class="texte" > <p>في قلب المملكة العربية السعودية التي تُشكل قوة استثمارية رائدة، يقع ليسن فالي في مدينة الرياض، ويُمثل مشروعًا حيويًا متطورًا ذو بيئة متكاملة متعددة الأنشطة التي من شأنها تلبية احتياجات المملكة والتماشي مع رؤية 2030 لتحسين جودة الحياة ودفع عجلة التنمية الاقتصادية إلى مزيد من التقدم والازدهار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/69960794-48852008.jpg?v=1673011967"]','https://cmsphoto.ww-cdn.com/resizeapi/c5857efabe84b266ed03a9e30b111d1d7b8b0260/480/',24.6922282,46.6332502,'Al Urubah Rd مقابل Riyadh','','https://laysenvalley.sa/','','https://www.saudi-guide.com/riyadh/i/69960794/laysen-valley',1,0,'ليسن فالي laysen valley اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (68625975,'aljawf-region','مسجد عمر بن الخطاب','Omar ibn Al-Khattab Mosque','omar-ibn-al-khattab-mosque-msgd-aamr-bn-alkhtab','["التراث والثقافة"]','["heritage"]','مسجد عمر بن الخطاب في دومة الجندل من أقدم المساجد الأثرية، يشتهر بمئذنته الحجرية ويجاور قلعة مارد وحي الدرع في قلب البلدة القديمة.','<div class="texte" > <p>&nbsp;يعتبر مسجد عمر بن الخطاب رضي الله عنه من أهم المساجد الأثرية في العصر الإسلامي. وتنبع أهمية المسجد من تخطيطه حيث يمثل استمرارية لنمط تخطيط المساجد الأولى في الإسلام وذلك على غرار مسجد الرسول صلى الله عليه وسلم في المدينة المنورة في مراحلة الاولى. ويشتهر المسجد بمئذنته التي تعتبر أول مئذنه بنيت في الإسلام والتي يبلغ ارتفاعها الحجري حوالي ١٢ متراً والتي كان يؤذن من خلالها للصلاة. *الخلفية التاريخية ترجع الأهمية التاريخية لمسجد عمر بن الخطاب إلى وجود عدد من الروايات التي تنسب بنائه للخليفة الثاني عمر بن الخطاب رضي الله عنه، حيث أمر ببنائه أثناء عودته من بيت المقدس عام 17هـ</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/FRlkoJMi6Y0?gbyoutube=FRlkoJMi6Y0" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe> <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/68625975-48237711.jpg?v=1667945010"]','https://cmsphoto.ww-cdn.com/resizeapi/8a617595b2c26b56f9b0ce1c500a86bcccec2272/480/',29.8119169,39.8674552,'RV68+QX Alkhaldiyah Dumah Al Jandal','','','','https://www.saudi-guide.com/aljawf-region/i/68625975/omar-ibn-al-khattab-mosque-msgd-aamr-bn-alkhtab',1,0,'مسجد عمر بن خطاب omar ibn al khattab mosque تراث والثقافه',strftime('%s','now'));
