INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (67869002,'riyadh','الرياض جاليري','Riyadh Gallery Mall','riyadh-gallery-mall','["المولات"]','["shopping"]','الرياض جاليري مول بحي الملك فهد، مركز تسوق عائلي يضم متاجر محلية وعالمية ومطاعم ومقاهي.','<div class="texte" > <p>الرياض جاليري مول من مراكز التسوق العائلية في حي الملك فهد بالرياض. يضم المول مجموعة من المتاجر المحلية والعالمية للأزياء والإلكترونيات ومستلزمات المنزل، بالإضافة إلى منطقة مطاعم ومقاهي متنوعة. يتميز بموقعه المركزي وتصميمه العصري، ما يجعله وجهة تسوق مريحة للعائلات وسكان المنطقة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67869002-68544443.jpg?v=1791549494", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67869002-68544444.jpg?v=1791549500"]','https://cmsphoto.ww-cdn.com/resizeapi/58e0fba68d83efbe57e8941762cba2bbe8e8c724/480/',24.7436082,46.6580521,'حي الملك فهد، الفرعي، Riyadh','','','','https://www.saudi-guide.com/riyadh/i/67869002/riyadh-gallery-mall',1,1,'رياض جاليري riyadh gallery mall مولات',strftime('%s','now'));
