INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (67868731,'riyadh','رويال مول','Royal Mall','royal-mall-riyadh','["المولات"]','["shopping"]','رويال مول بالرياض، مركز تسوق متوسط على طريق الملك فهد يضم متاجر محلية ومطاعم متنوعة.','<div class="texte" > <p>رويال مول من مراكز التسوق المتوسطة في الرياض، ويقع على طريق الملك فهد بموقع سهل الوصول. يضم المول تشكيلة من المتاجر المحلية للأزياء والاحتياجات المنزلية، بالإضافة إلى مطاعم ومقاهي متنوعة. يتميز بحجمه المناسب وسهولة التنقل بين متاجره، ما يجعله خيارًا عمليًا لقضاء رحلة تسوق سريعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67868731-47888126.jpg?v=1665187810"]','https://cmsphoto.ww-cdn.com/resizeapi/0369deb7a7da309f4b880638a25048159d7ba87a/480/',24.7240689,46.6650449,'King Fahd Rd الفرعي، Riyadh','','','','https://www.saudi-guide.com/riyadh/i/67868731/royal-mall-riyadh',1,0,'رويال مول royal mall مولات',strftime('%s','now'));
