INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (67868545,'riyadh','العثيم مول','Al Othaim Mall','al-othaim-mall','["المولات"]','["shopping"]','مول العثيم بحي الربوة بالرياض، مركز تسوق عائلي يضم هايبر ماركت ومتاجر محلية ومطاعم متنوعة.','<div class="texte" > <p>مول العثيم من مراكز التسوق العائلية المعروفة في الرياض، ويقع في حي الربوة. يضم المول مجموعة متنوعة من المتاجر المحلية للأزياء والاحتياجات المنزلية، بالإضافة إلى هايبر ماركت العثيم الشهير الذي يوفر جميع احتياجات التسوق اليومي، ومنطقة مطاعم ومقاهي متنوعة. يتميز بأسعاره المناسبة وقربه من الأحياء السكنية، ما يجعله وجهة عملية للتسوق اليومي للعائلات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67868545-47888076.jpg?v=1665186319"]','https://cmsphoto.ww-cdn.com/resizeapi/2f739fb5674d3e27ecda912ba0588ce433f5af17/480/',24.6856632,46.7754282,'Riyadh Ar Rabwah Ar-Riyad','','','','https://www.saudi-guide.com/riyadh/i/67868545/al-othaim-mall',1,0,'عثيم مول al othaim mall مولات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (67868498,'riyadh','النخيل مول','Al Nakheel Mall','al-nakheel-mall','["المولات"]','["shopping"]','مول النخيل بالرياض، مركز تسوق عريق بحي النخيل يضم متاجر محلية وعالمية وسينما ومنطقة ترفيهية للأطفال.','<div class="texte" > <p>مول النخيل من أعرق وأشهر مراكز التسوق في شمال الرياض، ويقع في حي النخيل بموقع متميز على طريق الملك فهد. يضم المول تشكيلة واسعة من المتاجر المحلية والعالمية للأزياء والإلكترونيات ومستلزمات المنزل، بالإضافة إلى صالة سينما ومنطقة ترفيهية للأطفال، وساحة طعام تضم مجموعة متنوعة من المطاعم والمقاهي. يتميز بتصميمه العصري ومساحاته الواسعة ومواقف السيارات الكبيرة، ما يجعله وجهة تسوق مفضلة لسكان شمال الرياض.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67868498-47888061.jpg?v=1665186069"]','https://cmsphoto.ww-cdn.com/resizeapi/ae655498fb54f7bb38fc8f6d940d9df51adda453/480/',24.7680248,46.7148039,'حي المغرزات، Riyadh Ar-Riyad','','','','https://www.saudi-guide.com/riyadh/i/67868498/al-nakheel-mall',1,0,'نخيل مول al nakheel mall مولات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (67868431,'riyadh','الرياض بارك مول','Riyadh Park','riyadh-park-mall','["المولات"]','["shopping"]','الرياض بارك مول، من أضخم مولات الرياض في حي العقيق، يضم 300+ متجر وسينما فوكس ومنطقة ترفيهية عائلية.','<div class="texte" > <p>الرياض بارك مول من أضخم وأشمل مولات الرياض، يقع في حي العقيق شمال المدينة، ويضم أكثر من 300 متجر تجمع بين أرقى العلامات التجارية العالمية والمحلية لتلبية كافة الاحتياجات، من الأزياء والإلكترونيات إلى الأثاث المنزلي. يحتوي على صالة سينما "فوكس" المجهزة بأحدث التقنيات، ومنطقة ترفيهية عائلية واسعة بألعاب مخصصة للأطفال، بالإضافة إلى ساحة طعام ضخمة تضم مجموعة متنوعة من المطاعم والمقاهي العالمية والمحلية. يتميز المول بتصميمه المعماري الحديث ومساحاته الواسعة المكيّفة، ومواقف سيارات مجانية كبيرة، ما يجعله وجهة تسوق وترفيه مفضلة للعائلات على مدار الأسبوع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67868431-47888054.jpg?v=1665185862"]','https://cmsphoto.ww-cdn.com/resizeapi/b3470f952214041210b18e1ec3d9681c6e111550/480/',24.7558509,46.6301956,'حي العقيق، Riyadh','','','','https://www.saudi-guide.com/riyadh/i/67868431/riyadh-park-mall',1,0,'رياض بارك مول riyadh park مولات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (67721101,'riyadh','منتزه السلام','Salam Park','salam-park-riyadh','["ترفيه واستجمام"]','["fun"]','منتزه السلام بالرياض، حديقة عامة توفر أجواء خضراء ومساحات مناسبة للمشي والاسترخاء.','<div class="texte" > <p>منتزه سلام&nbsp;يُعد من أكبر المنتزهات الترفيهية في مدينة الرياض، تأسس عام&nbsp;1424هـ&nbsp;/&nbsp;2003&nbsp;من قبل الهيئة العليا لتطوير&nbsp;مدينة الرياض، وقد قامت الهيئة بتطويره بهدف خدمة سكان&nbsp;الرياض&nbsp;والزائرين إليها للاستمتاع بمناظره&nbsp;الطبيعية&nbsp;الساحرة وقضاء أوقاتا عائلية ممتعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67721101-47820786.jpg?v=1664629045"]','https://cmsphoto.ww-cdn.com/resizeapi/7d48064d7e3dc8f008b1b200e92aaa5fad5deaa1/480/',24.6200404,46.7094679,'الرياض سلام الرياض','','','','https://www.saudi-guide.com/riyadh/i/67721101/salam-park-riyadh',1,0,'منتزه سلام salam park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (67463579,'taif','باب الحزم','Bab Alhazm','bab-alhazm-bab-alhzm','["أماكن سياحية"]','["sights"]','باب الحزم أحد الأبواب التاريخية بوسط مدينة الطائف القديمة، ويعد من معالمها التراثية العريقة.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/67463579-47700854.jpg?v=1663647638"]','https://cmsphoto.ww-cdn.com/resizeapi/dfa2d7b335e85f9be8661b38945d6dbc1a1f447b/480/',21.2750106,40.4097784,'At Taif Almantiqah Almarkaziyyah At-Taif','','','','https://www.saudi-guide.com/taif/i/67463579/bab-alhazm-bab-alhzm',1,0,'باب حزم bab alhazm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (62895142,'riyadh-region','حي الطريف التاريخي','At-Turaif District','turaif-district-hy-altryf-altarykhy','["التراث والثقافة"]','["heritage"]','حي الطريف أحد أهم المواقع السياسية والجغرافية في المملكة العربية السعودية منذ نشأة الدولة السعودية الأولى. يقع الحي في قلب شبه الجزيرة العربية، وبالتحديد...','<div class="texte" > <p>حي الطريف&nbsp;أحد أهم المواقع السياسية والجغرافية في&nbsp;المملكة العربية السعودية&nbsp;منذ نشأة&nbsp;الدولة السعودية الأولى. يقع الحي في قلب&nbsp;شبه الجزيرة العربية، وبالتحديد في&nbsp;الدرعية&nbsp;شمال غرب&nbsp;الرياض، إذ كان الحي أول عاصمة لأسرة&nbsp;آل سعود.&nbsp;يحمل حي الطُّريف الذي أُسس في&nbsp;القرن الخامس عشر الميلادي&nbsp;آثار الأسلوب المعماري النجدي الذي يتفرد به وسط شبه الجزيرة العربية، وتنامى في القرن الثامن عشر وبداية القرن التاسع عشر الدور السياسي والديني لحي الطريف وأضحى مركزًا لسلطة آل سعود وانتشار الإصلاح السلفي في&nbsp;الإسلام. يضم الحي آثار للكثير من القصور، فضلاً عن مدينة بُنيت على ضفاف واحة الدرعية. تم تسجيل موقع حي الطريف بالدرعية التاريخية ضمن قائمة التراث العمراني العالمي باليونسكو في عام&nbsp;1431 هـ&nbsp;الموافق&nbsp;2010م.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/62895142-45468036.jpg?v=1646756009", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/62895142-45468028.jpg?v=1646755992"]','https://cmsphoto.ww-cdn.com/resizeapi/c5e3fafc9e645051f3bac6acd532dcf4d7140743/480/',24.7335154,46.5748112,'وادي حنيفة Al Traif Ad Diriyah','','','','https://www.saudi-guide.com/riyadh-region/i/62895142/turaif-district-hy-altryf-altarykhy',1,0,'حي طريف تاريخي at turaif district تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (62625727,'hail','عين بلطة','Ain Balta','ain-balta-aayn-blt','["التراث والثقافة"]','["heritage"]','عين بلطة عين ماء قديمة تحيط بها النخيل وسط جبال أجا في حائل، ورد ذكرها في شعر امرئ القيس، وذكرها ياقوت الحموي في معجم البلدان موضعاً بجبلي طيء.','<div class="texte" > <p>عين بلطة وهي عين قديمة كانت جارية وحولها نخيل تتوسط جبال اجا على امتداد شعيب الحمرة والجدم واللذان يفيضان في وادي السلف ومازلت موجودة الى يومنا هذا&nbsp; وقد ورد ذكرها في قصائد الشعراء ومنهم امرؤ القيس وسلام بن عمرو بن درماء الطائي وغيرهم.</p> <p>جاء في معجم البلدان لياقوت الحموي:</p> <p>بلطة، قيل هو موضع معروف بجبلي طئ، وهو كان منزل عمرو بن درماء الذي نزل به امرؤ القيس بن حجر الكندي مستذما، وقال:</p> <p>نزلت على عمرو بن درماء بلطة</p> <p>&nbsp;فيا حسن ما جار ويا كرم ما محل</p> <p>&nbsp;وقال امرؤ القيس أيضا:</p> <p>وكنت إذا ما خفت يوما ظلامة</p> <p>&nbsp;فإن لها شعبا ببلطة زيمرا</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/62625727-45345292.jpg?v=1645777153"]','https://cmsphoto.ww-cdn.com/resizeapi/534ddd12f835d584f34c51691db763846257b722/480/',27.4748951,41.488685,'FFFQ+XF3 الصليعاء حائل','','','','https://www.saudi-guide.com/hail/i/62625727/ain-balta-aayn-blt',1,0,'عين بلطه ain balta تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60885948,'jeddah','نادي جدة لليخوت jeddah yacht club','','nady-alykhot','["سياحة وترفيه"]','["sights"]','نادي جدة لليخوت يقع على واجهة جدة البحرية بحي الشاطئ، ويُعد وجهة مخصصة لهواة اليخوت والرياضات البحرية والاستمتاع بإطلالة البحر الأحمر.','<div class="texte" > <p>يقع نادي جدة لليخوت على واجهة جدة البحرية بحي الشاطئ، ويُعد وجهة مخصصة لهواة اليخوت والرياضات البحرية والاستمتاع بإطلالة البحر الأحمر.</p> <p>يوفر النادي أجواءً هادئة تجمع بين رسو اليخوت والجلسات البحرية، ما يجعله مقصدًا مناسبًا لمحبي الإبحار والراغبين في قضاء وقت هادئ على ضفاف البحر الأحمر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60885948-44497467.jpg?v=1639009678"]','https://cmsphoto.ww-cdn.com/resizeapi/651d403f1bbe93f390c9415350c9d7a2ce60e3de/480/',21.6533392,39.1008262,'Al Kurnaysh Br Rd الفرعي، الشاطئ، Jeddah','','','','https://www.saudi-guide.com/jeddah/i/60885948/nady-alykhot',1,0,'نادي جده لليخوت jeddah yacht club سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60492616,'yanbu','عين المبارك ينبع النخل','Ayn AlMabark','ayn-almabark-aayn-almbark-ynbaa-alnkhl','["أماكن سياحية"]','["sights"]','عين المبارك في ينبع النخل، عيون طبيعية عادت للجريان بعد انقطاع سنين طويلة لتشكّل بحيرة المبارك وسط النخيل في مشهد طبيعي جميل يستحق الزيارة.','<div class="texte" > <p>تقع عين المبارك في ينبع النخل بمحافظة ينبع، وقد عادت عيون ينبع النخل إلى الجريان بعد انقطاع دام سنين طويلة، لتشكّل بحيرة المبارك وسط النخيل والمزارع في مشهد طبيعي جميل يجذب الزوار ومحبي الطبيعة والتصوير.</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/wV3wYfpiLYs?gbyoutube=wV3wYfpiLYs" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe> <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60492616-44268095.jpg?v=1637681738"]','https://cmsphoto.ww-cdn.com/resizeapi/8fbe4e5088735c9760ba93ff85841f1ee6728584/480/',24.265495,38.3738447,'SA Yanbu Al Bahr Al Madinah Province','','','','https://www.saudi-guide.com/yanbu/i/60492616/ayn-almabark-aayn-almbark-ynbaa-alnkhl',1,0,'عين مبارك ينبع نخل ayn almabark اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60486717,'asir-region','شجرة الرقاعه في تنومة','','al-ruqaah-tree-tanomah','["أماكن سياحية"]','["sights"]','شجرة معمرة في تنومة يزيد عمرها عن 150 عامًا، وتمتد جذورها لمسافة تصل إلى 40 مترًا، ما يجعلها من المعالم الطبيعية اللافتة في المنطقة.','<div class="texte" > <p>شجرة الرقاعة في تنومة هي شجرة معمرة يزيد عمرها عن 150 عامًا، وتمتد جذورها لمسافة تصل إلى 40 مترًا، ما يجعلها من أبرز المعالم الطبيعية في المحافظة. تجذب الشجرة الزوار والباحثين عن الظل الطبيعي، وتعكس عراقة الغطاء النباتي في منطقة عسير الجبلية، كما تُعد من المزارات التي يقصدها محبو التصوير لتوثيق حجمها وشكلها الفريد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60486717-44265427.jpg?v=1637669384", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60486717-44265425.jpg?v=1637669394"]','https://cmsphoto.ww-cdn.com/resizeapi/2a12b3ec9b709b733cfc43685e05ca8a55ef098b/480/',18.9903357,42.1308306,'X4RJ+48P Tanomah Tanomah','','','','https://www.saudi-guide.com/asir-region/i/60486717/al-ruqaah-tree-tanomah',1,0,'شجره رقاعه في تنومه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169957,'najran','قصر تركي الماضي','Turki Al Madi Palace','turki-al-madi-palace-ksr-trky-almady','["التراث والثقافة"]','["heritage"]','قصر تركي الماضي أو قصر الإمارة التاريخي في حي أبا السعود بنجران، مبنى تراثي بُني بأمر أمير نجران تركي الماضي على مساحة تقارب 6252 متراً مربعاً.','<div class="texte" > <p>قصر إمارة نجران والذي بني بأمر من الأميرتركي الماضي أمير نجران آن ذاك، وهو مبنى تاريخي يقع في وسط المدينة القديمة بنجران في حي أبا السعود التاريخي، على مساحة تقدر بحوالي 6,252 متر مربع،&nbsp;يُعد القصر من أشهر المباني التراثية بمنطقة نجران ومن أهم المباني في المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169957-45042134.jpg?v=1643479891"]','https://cmsphoto.ww-cdn.com/resizeapi/833f8e7f9375b366412663105ff6f3f50f6e95f5/480/',17.4900776,44.1319245,'ابا لسعود نجران نجران','','','','https://www.saudi-guide.com/najran/i/60169957/turki-al-madi-palace-ksr-trky-almady',1,0,'قصر تركي ماضي turki al madi palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169885,'najran','قرية نجران التراثية ومتحف شعيب دحضة','Najran Heritage Village and Dahda Museum','najran-heritage-village-and-dahda-museum-kry-ngran-altrathy-omthf-shaayb-dhd','["التراث والثقافة"]','["heritage"]','قرية نجران التراثية ومتحف شعيب دحضة قرب موقع دحضة الأثري الذي عُثر فيه على أدوات حجرية بالغة القدم، وجهة للتعرف على تراث نجران وعمارتها.','<div class="texte" > <p>قرية نجران التراثية ومتحف شعيب دحضة وجهة تراثية في مدينة نجران تعرّف زوارها بطراز العمارة الطينية النجرانية ومقتنيات الحياة القديمة في المنطقة.</p> <p>ويحمل المتحف اسم شعيب دحضة القريب منه، وهو موقع أثري مهم عُثر فيه على أدوات حجرية تُنسب إلى الحضارة الأولدوانية، يُقدَّر عمرها بأكثر من مليون عام، وتشمل قواطع ومكاشط وشفرات ومطارق حجرية، ما يجعل المنطقة من أقدم مواقع الاستيطان البشري في الجزيرة العربية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169885-45042135.jpg?v=1643479911"]','https://cmsphoto.ww-cdn.com/resizeapi/98e7bfc28a3b82ba129dbc7d0db1f88996ca2922/480/',17.510464,44.1567681,'Najran Dahdah Najran','','','','https://www.saudi-guide.com/najran/i/60169885/najran-heritage-village-and-dahda-museum-kry-ngran-altrathy-omthf-shaayb-dhd',1,0,'قريه نجران تراثيه ومتحف شعيب دحضه najran heritage village and dahda museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169883,'najran','قصر أبو ساق كحيلان التاريخي','Abu Saq Kahilan Historic Palace','abu-saq-kahilan-historic-palace-ksr-abo-sak-khylan-altarykhy','["التراث والثقافة"]','["heritage"]','قصر أبو ساق كحيلان التاريخي في نجران من المباني التراثية الطينية التي تعكس طراز العمارة النجرانية التقليدية، ومقصد لمحبي التراث والتصوير.','<div class="texte" > <p>قصر أبو ساق كحيلان التاريخي من المباني التراثية في مدينة نجران، ويعكس طراز العمارة النجرانية التقليدية القائمة على البناء بالطين في طبقات متتالية، بجدرانه المرتفعة ونوافذه الصغيرة التي تلائم مناخ المنطقة.</p> <p>ويُعد القصر من الشواهد على الموروث العمراني لنجران، ومقصداً لمحبي التراث والتصوير الراغبين في التعرف على ملامح العمارة القديمة في المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169883-45042139.jpg?v=1643479935"]','https://cmsphoto.ww-cdn.com/resizeapi/13d975d154f3b38f8898392e1b2ee0c72207ad24/480/',17.5203918,44.2111189,'6785 Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169883/abu-saq-kahilan-historic-palace-ksr-abo-sak-khylan-altarykhy',1,0,'قصر ابو ساق كحيلان تاريخي abu saq kahilan historic palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169880,'najran','آبار حمى التاريخية','Hima Wells','hima-wells-abar-hma-altarykhy','["التراث والثقافة"]','["heritage"]','آبار حمى في نجران موقع تراث عالمي على طريق قوافل قديم، يضم 550 لوحة فن صخري بمئات الآلاف من النقوش والرسوم التي توثق 7 آلاف عام من الحياة.','<div class="texte" > <p>منطقة حما الثقافية أو بئر حما أو آبار حمى التاريخية، هي موقع تراث عالمي تقع في منطقة نجران جنوب المملكة العربية السعودية،&nbsp;تتضمن المنطقة أكثر من 34 موقعًا يزخر بالنقوش الصخرية والآبار على امتداد أحد أقدم طرق القوافل التي كانت تعبر من جنوب الجزيرة العربية إلى شمالها،&nbsp;تمتدّ منطقة الفن الصخري الثقافي في حِمى على مساحة 557 كم2، وتضمّ 550 لوحة فن صخري تحوي مئات الآلاف من النقوش والرسوم الصخرية التي تصوِّر الصيد والحيوانات والنباتات وأساليب الحياة لثقافة امتدت على 7 آلاف عام دون انقطاع، وتعدّ واحدةً من أكبر مجمعات الفن الصخري في العالم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169880-45042114.jpg?v=1643479685"]','https://cmsphoto.ww-cdn.com/resizeapi/ebe7e7d82711f7ddcc240b01523c11fd2604d9ff/480/',18.2506683,44.4514131,'1230 Thar Najran','','','','https://www.saudi-guide.com/najran/i/60169880/hima-wells-abar-hma-altarykhy',1,0,'ابار حمي تاريخيه hima wells تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169798,'najran','مدينة الأخدود الأثرية','Al Ukhdud Archaeological Site','al-ukhdud-archaeological-site-mdyn-alakhdod-alathry','["التراث والثقافة"]','["heritage"]','مدينة الأخدود الأثرية على ضفاف وادي نجران، عُرفت قديماً باسم رقمات، وارتبط اسمها بقصة أصحاب الأخدود التي ذكرها القرآن الكريم.','<div class="texte" > <p>الأُخدود وعرفت سابقاً باسم "رقمات" هي مدينة تاريخية تعود لعصر مملكة حمير (110 قبل الميلاد ~ 525 بعد الميلاد) وتقع على ضفاف وادي نجران في منطقة نجران في المملكة العربية السعودية،&nbsp;اشتهرت المدينة بالمذبحة التاريخية التي أوقعها ذو نواس الملك الحميري في سنة 520 بحق أصحاب الأخدود&nbsp;وهو الأمر الذي سجل في القرآن الكريم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169798-45042106.jpg?v=1643479645"]','https://cmsphoto.ww-cdn.com/resizeapi/28682bd827778aae12c7152a62d200a65d87bfc7/480/',17.4774955,44.1793098,'1002 Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169798/al-ukhdud-archaeological-site-mdyn-alakhdod-alathry',1,0,'مدينه اخدود اثريه al ukhdud archaeological site تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169796,'najran','قلعة وجبل رعوم','Raum Castle and Mountain','raum-castle-and-mountain-klaa-ogbl-raaom','["التراث والثقافة"]','["heritage"]','قلعة رعوم التاريخية على قمة جبل رعوم وسط قرية الحضن في نجران، قلعة صخرية واضحة المعالم يُصعد إليها بدرج، ويقصدها محبو الآثار وهواة التسلق.','<div class="texte" > <p>قلعة رعوم هي قلعة تاريخية تقع على قمة جبل رعوم الذي يتوسط قرية الحضن في نجران جنوب المملكة العربية السعودية، بالقرب من طريق الأمير سلطان، وهذه القلعة صخرية لا تزال واضحة المعالم، ويمكن الصعود إليها بواسطة درج، ويرتادها عشاق الآثار وهواة رياضة تسلق الجبال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169796-45042112.jpg?v=1643479666"]','https://cmsphoto.ww-cdn.com/resizeapi/227f49a8f34d7af1c563e15a0bf7d83cc4289285/480/',17.4692005,44.0874,'F39P+MXJ الحضن، نجران','','','','https://www.saudi-guide.com/najran/i/60169796/raum-castle-and-mountain-klaa-ogbl-raaom',1,0,'قلعه وجبل رعوم raum castle and mountain تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169794,'najran','متحف نجران','Najran Museum','najran-museum-mthf-ngran','["التراث والثقافة"]','["heritage"]','متحف نجران قرب موقع الأخدود الأثري، بُني عام 1403هـ وافتُتح عام 1407هـ، ويضم قاعات للعرض المتحفي ومعامل للترميم ومكتبة متخصصة وقاعة للعروض الزائرة.','<div class="texte" > <p>متحف نجران، أحد متاحف منطقة نجران، وتم بناء المتحف عام 1403 هـ 1983 بالقرب من موقع الأخدود الأثري بنجران على أرض مساحتها 482232 متر مربع وافتتح لاستقبال الزوار عام 1407 هـ 1987 ، ويحتوي المتحف على مكاتب مجهزة بأحدث المعدات وهي: مكاتب الإدارة، والموظفين، وقاعة العرض المتحفي ومعامل المساحة والرسم ومعامل التصوير ومعامل الترميم والمختبر وقاعة العرض التلفزيوني والمكتبة تضم مجموعة من الكتب المتخصصة بالإضافة إلى بعض الدوريات والنشرات وقاعة العروض الزائرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169794-45042100.jpg?v=1643479624"]','https://cmsphoto.ww-cdn.com/resizeapi/0bc042b7ff6c9dbeed56acd7d5c8e421e66ff047/480/',17.4777482,44.175515,'3785 Prince Sultan Ibn Abdulaziz نجران','','','','https://www.saudi-guide.com/najran/i/60169794/najran-museum-mthf-ngran',1,0,'متحف نجران najran museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169793,'najran','قصر العان','Al Aan Palace','al-aan-palace-ksr-alaaan','["التراث والثقافة"]','["heritage"]','قصر العان الأثري على جبل العان في نجران، عُرف قديماً بقصر سعدان، بُني نحو عام 1100هـ من الطين على أساسات حجرية بطراز العمارة النجرانية المميز.','<div class="texte" > <p><span>قصر العان، أو قصر سعدان قديماً، هو قصر أثري يقع على جبل العان. بني عام 1100 هـ من الطين على أساسات من الحجر بطراز معماري تتميز به منطقة نجران الواقعة جنوب المملكة العربية السعودية، سمي بهذا الاسم نسبة إلى القرية التي يقع بها.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169793-45042099.jpg?v=1643479601"]','https://cmsphoto.ww-cdn.com/resizeapi/cf32f85df9e39c20c620b32be185424b3aebb056/480/',17.4804079,44.0959695,'7158 شارع الامير نايف بن عبدالعزيز Aba Lasaud','','','','https://www.saudi-guide.com/najran/i/60169793/al-aan-palace-ksr-alaaan',1,0,'قصر عان al aan palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169788,'najran','منتزه الشلال','Waterfall Park','waterfall-park-mntzh-alshlal','["أماكن سياحية"]','["sights"]','منتزه الشلال على طريق الملك عبدالعزيز في نجران، منتزه عائلي يتميز بشلاله ومساحاته الخضراء، ويقصده الأهالي والزوار للتنزه والجلسات العائلية.','<div class="texte" > <p>منتزه الشلال من المنتزهات العائلية في مدينة نجران، ويقع على طريق الملك عبدالعزيز، ويتميز بشلاله الذي يمنحه اسمه ومساحاته الخضراء المفتوحة، ويقصده الأهالي والزوار للتنزه والجلسات العائلية والاستمتاع بالأجواء في الهواء الطلق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169788-45042140.jpg?v=1643479954"]','https://cmsphoto.ww-cdn.com/resizeapi/978842f55743133cf48cad64788b2d16c8515736/480/',17.5155766,44.1870037,'King Abdulaziz Rd Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169788/waterfall-park-mntzh-alshlal',1,0,'منتزه شلال waterfall park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169785,'najran','وادي نجران','Wadi Najran','wadi-najran-oady-ngran','["أماكن سياحية"]','["sights"]','وادي نجران من أكبر أودية المملكة، يقسم مدينة نجران إلى شمال وجنوب، وتأتي روافده من جبال السروات ويمتد نحو 180 كيلومتراً شرقاً حتى رمال الربع الخالي.','<div class="texte" > <p>وادي نجران هو واحد من أكبر أودية المملكة العربية السعودية وأكبر أودية منطقة نجران،&nbsp;ويقسم مدينة نجران لقسمين شمالي وجنوبي، تأتي روافده من جبال الحجاز (جبال السروات) والهضاب المحيطة بالمنطقة (هضبة عسير)، ويمتد مسافة 180 كيلومتر إلى الشرق ابتداءًا من مصبه في السهول حيث ينتهي في رمال صحراء الربع الخالي، كما يبلغ متوسط عرضه في السهول 1000 متر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169785-45042097.jpg?v=1643479579"]','https://cmsphoto.ww-cdn.com/resizeapi/c52778d1a6cb7be2c29563831a10f0bc794bcbaf/480/',17.5078981,44.2052316,'Wadi Najran Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169785/wadi-najran-oady-ngran',1,0,'وادي نجران wadi najran اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169741,'najran','غابة سقام','Saqam Forest','saqam-forest-ghab-skam','["أماكن سياحية"]','["sights"]','غابة سقام أو منتزه الملك فهد من أجمل المنتزهات في جنوب نجران، يتميز بمناظره الطبيعية الخضراء، ويعد وجهة مفضلة للأهالي والزوار للتنزه والاسترخاء.','<div class="texte" > <p>منتزة الملك فهد (غابة سقام)، يعد من أجمل الأماكن التي توجد في الجهة الجنوبية في منطقة نجران ويُعد من المنتزهات السياحية المهمة والمفضلة لسكان المنطقة ومقصد للزوار ويتميز بالمناظر الطبيعية&nbsp;الخضراء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169741-45042096.jpg?v=1643479559"]','https://cmsphoto.ww-cdn.com/resizeapi/f80449d0776ab12478170751a084bb682db8ae0f/480/',17.4924426,44.2103278,'بن عبد العزيز Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169741/saqam-forest-ghab-skam',1,0,'غابه سقام saqam forest اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783376,'tabuk-region','ضبا القديمة','Old Duba','dba-alkdym','["التراث والثقافة"]','["heritage"]','ضباء القديمة، البلدة التاريخية لمدينة ضباء على ساحل البحر الأحمر، تضم مباني حجرية تقليدية وأزقة قديمة قرب قلعة الملك عبدالعزيز، وتعكس تاريخ المدينة الساحلي.','<div class="texte" > <p>ضباء القديمة هي البلدة التاريخية لمدينة ضباء المطلة على البحر الأحمر، وتضم مباني حجرية تقليدية تعكس فن العمارة الساحلية في المنطقة، وتقع بالقرب منها قلعة الملك عبدالعزيز والسوق القديم، ما يجعلها محطة مميزة للتعرف على تاريخ المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783376-44704138.jpg?v=1640799701"]','https://cmsphoto.ww-cdn.com/resizeapi/17b29ffa628a03bfb4febde339c66e14a305dbc0/480/',27.350037,35.6965988,'9M2W+2J9 البلد،، Duba','','','','https://www.saudi-guide.com/tabuk-region/i/59783376/dba-alkdym',1,0,'ضبا قديمه old duba تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783373,'tabuk-region','السوق القديم في الوجه','Old Souq in Al Wajh','alsok-alkdym-fy-alogh','["التراث والثقافة"]','["heritage"]','السوق القديم في الوجه المعروف بالمناخة، سوق تاريخي في حي البلد كانت له بوابة، وقصده البادية والتجار للتبادل، وتعلوه قلعة السوق المبنية عام 1276هـ.','<div class="texte" > <p>السوق القديم في محافظة الوجه، المعروف قديمًا باسم «المناخة»، من أبرز معالم حي البلد التاريخي، وكانت له بوابة تنظم الدخول إليه والخروج منه. شكّل السوق مركزًا للتبادل التجاري، إذ كان أهل البادية يجلبون إليه المواشي والسمن والعسل والحطب، ويوفر التجار الأرز والقمح والأقمشة والقهوة والهيل والسكر، وارتبط بميناء الوجه الذي كانت تنطلق منه السفن الشراعية نحو موانئ البحر الأحمر.</p> <p>وتطل على السوق قلعة السوق (قلعة البلدة) القائمة على تل مرتفع، والتي يعود بناؤها إلى عام 1276هـ / 1859م بغرض حماية البلدة والإشراف على الميناء والسوق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783373-44704127.jpg?v=1640799677"]','https://cmsphoto.ww-cdn.com/resizeapi/5f76883fabb424a6f2391173f12b770e53433381/480/',26.2268979,36.4567194,'حي البلد، محافظة الوجه، منطقة تبوك','','','','https://www.saudi-guide.com/tabuk-region/i/59783373/alsok-alkdym-fy-alogh',1,0,'سوق قديم في وجه old souq in al wajh تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783368,'tabuk-region','قلعة الزريب بالوجه','Al Zurayb Castle','klaa-alzryb-balogh','["التراث والثقافة"]','["heritage"]','قلعة الزريب شرق محافظة الوجه، قلعة عثمانية بُنيت عام 1026هـ لتأمين الحجاج، مربعة الشكل بأربعة أبراج دائرية، وتضم حجرات ومسجدًا وبئرًا وبركًا ملاصقة لها.','<div class="texte" > <p>قلعة الزريب الأثرية من القلاع التاريخية في شرق محافظة الوجه التابعة لمنطقة تبوك، وهي قلعة كبيرة أُنشئت في عصر السلطان أحمد الأول سنة 1026 هـ / 1617م لتأمين الحجاج وخزن ودائعهم وأقواتهم، ويوجد على مدخل القلعة نقش تأسيس البناء.</p> <p>مسقط القلعة مستطيل الشكل ولها أربعة أبراج في كل ركن من أركانها، والمدخل يقع في الضلع الغربي، وتتكون القلعة من الداخل من حجرات تُحيط بفناء القلعة، ومسجد ومصلى، وبئر، ويلتصق بالضلع الشمالي للقلعة من الخارج ثلاث برك، وتأخذ القلعة الشكل المربع ويقوم على زواياها أربعة أبراج دائرية للمراقبة والحماية، ويتضح من شكل مسقطها الأفقي حرفية عالية في البناء ودقته، إذ أن الزوايا قائمة وخطوط واجهاتها مستقيمة، ولها بوابة ظاهرة وبارزة على واجهتها الغربية من خلال بروز قليل نسبياً، وشكل بوابة المدخل مستطيلة ومتسعة ويعلوها قوس موتور وعلى جانبيها مقاعد حجرية وقد استعمل لحماية باب الدخول للقلعة، كما تميزت الواجهة الداخلية لبوابة الدخول باستخدام حجارة ملونة تميزه عن الحجارة المستخدمة في الخارج، إذ تخلو الوجهات من الفتحات المعمارية إلا من الطلقات المنتشرة على امتدادها في القسم العلوي للبناء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783368-44704116.jpg?v=1640799656"]','https://cmsphoto.ww-cdn.com/resizeapi/cff6c2683aabf9ec270299249ebe1b23553b112d/480/',26.2525158,36.5457387,'7G3W+275 Zurayb Al Wajh','','','','https://www.saudi-guide.com/tabuk-region/i/59783368/klaa-alzryb-balogh',1,0,'قلعه زريب بالوجه al zurayb castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783322,'tabuk-region','جبل السفينة في بجدة','Ship Mountain in Bajdah','gbl-alsfyn-fy-bgd','["التراث والثقافة"]','["heritage"]','جبل السفينة غرب مدينة تبوك، سُمي بذلك لشكله القريب من السفينة، ويضم نقوشًا ثمودية يزيد عمرها على 2600 عام وكتابات عربية قديمة ونقوشًا بالخط الكوفي.','<div class="texte" > <p>جبل السفينة جبل يضم آثارا جيولوجية وتاريخية يقع في الجهة الغربية من مدينة تبوك شمال غرب السعودية. سمّي بجبل السفينة لتكوينه الذي يبدو في هيئته أقرب إلى السفينة.</p> <p>تعددت النقوش والآثار على جبل السفينة التي توثق حياة أقوام سابقة مرت على المنطقة، حيث يقع الجبل في صحراء سحمى التي كانت تمثل محطة على طريق التجارة القديم من وإلى الجزيرة العربية، وهذا ما يفسر وجود آثارا لنقوش وكتابات ثمودية يعود تاريخها لأكثر من 2600 عام على الجبل، وكتابات عربية تعود إلى فترة ما قبل الإسلام، وتدوينات مكتوبة بالخط الكوفي تعود إلى القرن الأول من الهجرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783322-44704109.jpg?v=1640799631"]','https://cmsphoto.ww-cdn.com/resizeapi/4d42e97f87983d2a363a3f489e6313ec50757b26/480/',28.3271534,35.8032337,'8RG3+V79 بجده تبوك','','','','https://www.saudi-guide.com/tabuk-region/i/59783322/gbl-alsfyn-fy-bgd',1,0,'جبل سفينه في بجده ship mountain in bajdah تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783298,'tabuk-region','متحف البيت الطيني','Mud House Museum','mud-house-museum-mthf-albyt-altyny','["التراث والثقافة"]','["heritage"]','متحف البيت الطيني في مدينة تبوك، وجهة ثقافية تحاكي حياة الأجداد وتعرض مقتنيات تراثية تعرّف الزوار بتاريخ تبوك وموروثها، ويستقبل زواره بالقهوة السعودية والتمر.','<div class="texte" > <p>متحف البيت الطيني وجهة ثقافية في مدينة تبوك، يحاكي حياة الأجداد بتفاصيلها ومقتنياتها التراثية، ويتيح للزوار التعرف على تاريخ تبوك وموروثها عن قرب، ويستقبلهم بالقهوة السعودية والتمر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783298-44735018.jpg?v=1641164834"]','https://cmsphoto.ww-cdn.com/resizeapi/1493764f2c7b340fb687965fbfe1196af6193ced/480/',28.3832631,36.5553428,'3060 Al Amir Fahd Ibn Sultan Rd Al''awayshah','','','','https://www.saudi-guide.com/tabuk-region/i/59783298/mud-house-museum-mthf-albyt-altyny',1,0,'متحف بيت طيني mud house museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783132,'tabuk-region','عين السكر بجوار قلعة تبوك','Ain Al Sukkar','aayn-alskr-klaa-tbok-alaslamy','["التراث والثقافة"]','["heritage"]','عين السكر أو عين تبوك بجوار قلعة تبوك الأثرية، عين ماء تاريخية يعود ذكرها إلى زمن غزوة تبوك، ومن أبرز المعالم في قلب مدينة تبوك القديمة.','<div class="texte" > <p>عين تبوك أو عين سكر عين ماء يقع في مدينة تبوك الواقعة إلى الشمال الغربي من المملكة العربية السعودية. يعود تاريخ العين إلى فترة بعثة النبي محمد، واستمرت منذ ذلك التاريخ حتى الآن.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783132-44704047.jpg?v=1640799465"]','https://cmsphoto.ww-cdn.com/resizeapi/0a3459b6b14c2c0e1f37498443ce302318255eca/480/',28.3827377,36.5562052,'9HM4+3FW Al''awayshah Tabuk','','','','https://www.saudi-guide.com/tabuk-region/i/59783132/aayn-alskr-klaa-tbok-alaslamy',1,0,'عين سكر بجوار قلعه تبوك ain al sukkar تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783108,'tabuk-region','مركز بن عاصي للفروسية والتراث','Bin Assi Equestrian and Heritage Center','mrkz-bn-aaasy-llfrosy-oaltrath','["التراث والثقافة"]','["heritage"]','مركز بن عاصي للفروسية والتراث في تبوك، وجهة تجمع بين الخيل العربية الأصيلة والموروث الشعبي، ويستقبل الوفود السياحية والزوار للتعرف على تراث المنطقة.','<div class="texte" > <p>مركز بن عاصي للفروسية والتراث في منطقة تبوك، مركز يجمع بين الفروسية والخيل العربية الأصيلة والموروث الشعبي، ويضم متحفًا تراثيًا، ويستقبل الوفود السياحية والزوار للتعرف على تراث المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783108-44735019.jpg?v=1641164854"]','https://cmsphoto.ww-cdn.com/resizeapi/0fd49211a95597adacdc84504039f53feb36cb2d/480/',28.3961217,36.4080763,'SA Tabouk Tabuk Province','','','','https://www.saudi-guide.com/tabuk-region/i/59783108/mrkz-bn-aaasy-llfrosy-oaltrath',1,0,'مركز بن عاصي للفروسيه والتراث bin assi equestrian and heritage center تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783084,'tabuk-region','متحف وقفة على عتبات الماضي','Waqfa Ala Atabat Al Madi Museum','mthf-okf-aal-aatbat-almady','["التراث والثقافة"]','["heritage"]','متحف وقفة على عتبات الماضي في تبوك، من أبرز المتاحف الخاصة في المدينة، يضم أجنحة لمقتنيات أثرية وتراثية ويستقبل الوفود السياحية وطلاب المدارس.','<div class="texte" > <p>متحف وقفة على عتبات الماضي من أبرز المتاحف الخاصة في مدينة تبوك، يضم أجنحة متعددة لمقتنيات أثرية وتراثية، ويحظى بزيارات الوفود السياحية والمؤسسات التعليمية وطلاب المدارس.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783084-44735020.jpg?v=1641164870"]','https://cmsphoto.ww-cdn.com/resizeapi/3ccacdbfa876f097c910bb94219379aebb704ded/480/',28.3959043,36.5252363,'8947 3171 King Fahad Road','','','','https://www.saudi-guide.com/tabuk-region/i/59783084/mthf-okf-aal-aatbat-almady',1,0,'متحف وقفه علي عتبات ماضي waqfa ala atabat al madi museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783048,'tabuk-region','مسجد التوبة التاريخي','Al Tawba Mosque','al-tawba-mosque-msgd-altob-altarykhy','["التراث والثقافة"]','["heritage"]','مسجد التوبة في تبوك، ويُعرف بمسجد الرسول، تعود نشأته إلى غزوة تبوك سنة 9هـ، وجُدد بناؤه عبر العصور ثم أعيد على طراز المسجد النبوي في العهد السعودي.','<div class="texte" > <p>مسجد التوبة أو المسجد الأثري أو ما يعرف عند أهالي مدينة تبوك بمسجد الرسول. تعود نشأة المسجد إلى غزوة تبوك سنة 9 هـ حيث أدى الرسول محمد صلى الله عليه وسلم الصلاة فيه عشر ليال. أول بناء للمسجد كان في عهد الخليفة الأموي عمر بن عبد العزيز، حيث كان بناؤه من الطين وسعف النخل للسقف والحجارة المنقوشة، ثم تجدد بناء المسجد في العهد العثماني عام 1062 هـ الموافق 1651م، وأعيد بناؤه مرة أخرى في العهد السعودي على طراز المسجد النبوي الشريف في عام 1393 هـ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783048-44735006.jpg?v=1641164601"]','https://cmsphoto.ww-cdn.com/resizeapi/2fe62e5613de89ab0cadfd5a1d7c97ca003f0ee4/480/',28.3840072,36.55768,'Tabuk Al''awayshah Tabouk','','','','https://www.saudi-guide.com/tabuk-region/i/59783048/al-tawba-mosque-msgd-altob-altarykhy',1,0,'مسجد توبه تاريخي al tawba mosque تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783042,'tabuk-region','قلعة تبوك التاريخية','Tabuk Castle','tabuk-castle-klaa-tbok-altarykhy','["التراث والثقافة"]','["heritage"]','قلعة تبوك الأثرية، إحدى محطات طريق الحج الشامي، يعود بناؤها إلى عام 967هـ ورُممت في العهدين العثماني والسعودي، وتقع في قلب مدينة تبوك القديمة.','<div class="texte" > <p>قَلْعَة تَبُوك الأثَرِيَّة هي إحدى محطات طريق الحج الشامي الذي يربط بين الشام والحجاز،&nbsp;يعود تاريخ بناء القلعة إلى عام 967 هـ / 1559م، ولقد أعيد ترميمها في عهد السلطان محمد الرابع حيث أدخلت تجديدات على بلاطات خزفية مازالت موجودة في مدخل القلعة، ثم أعيد ترميمها وتجديدها بالكامل مرة أخرى في عهد السلطان عبد المجيد بن محمد في عام 1259 هـ / 1844م، وقد وضع بمحراب المسجد نقش خاص بهذه الذكرى، ثم جُددت القلعة في العهد السعودي عام 1370 هـ / 1950م، وأجريت عليها ترميمات شاملة عام 1413 هـ / 1992م، من قِبل وكالة الآثار والمتاحف بوزارة المعارف سابقاً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783042-44704042.jpg?v=1640799443"]','https://cmsphoto.ww-cdn.com/resizeapi/32dab6595ec76839399ce439299ea048ad58f647/480/',28.3828076,36.5565499,'SA العوايشة تبوك','','','','https://www.saudi-guide.com/tabuk-region/i/59783042/tabuk-castle-klaa-tbok-altarykhy',1,0,'قلعه تبوك تاريخيه tabuk castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783011,'tabuk-region','متحف تبوك الإقليمي','Tabuk Regional Museum','mthf-tbok-alaklymy','["التراث والثقافة"]','["heritage"]','متحف تبوك الإقليمي داخل موقع سكة حديد الحجاز، يضم قاعات لما قبل التاريخ وما قبل الإسلام والفترة الإسلامية والتراث والتاريخ الحديث وبيئة المنطقة.','<div class="texte" > <p>متحف تبوك هو يقع في تبوك شمال المملكة العربية السعودية، حيث يقام المتحف داخل موقع سكة حديد الحجاز القديمة على مساحة إجمالية تبلغ 21800 متر مربع تشكل مساحة المباني نحو 8370 مترا مربعا، يضم المتحف&nbsp;عناصر من أهمها البهو الرئيسي الذي يضم المدخل الرئيسي وقاعة الاستقبال إضافة لقاعة كبار الزوار ومصلى للرجال والنساء وركن للهدايا والتذكارات وقاعة تثقيف الأطفال إضافة إلى قاعة العروض وأخرى لبيئة المنطقة وقاعة الصور ما قبل التاريخ وقاعة ما قبل الإسلام وقاعة الفترة الإسلامية وقاعة التراث وقاعة التاريخ الحديث وأخرى للمحاضرات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783011-44704041.jpg?v=1640799423"]','https://cmsphoto.ww-cdn.com/resizeapi/16c80d23180c855362eb14950c1ed426bb9d66f5/480/',28.3878143,36.5619096,'Tabuk Alaziziyah Alqadimah Tabouk','','','','https://www.saudi-guide.com/tabuk-region/i/59783011/mthf-tbok-alaklymy',1,0,'متحف تبوك اقليمي tabuk regional museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783006,'tabuk-region','متحف قطار الحجاز - محطة تبوك','Hijaz Railway Station (Tabuk station)','hijaz-railway-station-tabuk-station-ktar-alhgaz-mht-tbok','["التراث والثقافة"]','["heritage"]','محطة تبوك من المحطات الرئيسية لخط حديد الحجاز، وصلها أول قطار عام 1906م، وتضم ثلاثة عشر مبنى على امتداد السكة إضافة إلى مستودعات للقاطرات وورش صيانة.','<div class="texte" > <p>محطة تبوك هي إحدى محطات خط حديد الحجاز وتعتبر من المحطات الرئيسية للخط وصل لها أول قطار عام 1906 م. تتميز المحطة بطريقة بنائها، كما تتكون من مجموعة من المباني المشيدة في خط مستقيم مواز لمسار السكة بالإضافة إلى احتوائها على مستودعات للقاطرات ومعامل للصيانة، حيث تضم ثلاثة عشر مبنى مشيدة في خط مستقيم موازٍ لمسار السكة وتقع على مساحة تقدر بنحو ثمانين ألف متر مربع. حالياً تقع وسط مدينة تبوك، وقد تم ترميمها عدة مرات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783006-44735005.jpg?v=1641164584"]','https://cmsphoto.ww-cdn.com/resizeapi/66512eb991e7fefd17d0cd1eb54fd27ce02812a9/480/',28.3877526,36.5612155,'2792 King Abdul Aziz Rd Alaziziyah Alqadimah','','','','https://www.saudi-guide.com/tabuk-region/i/59783006/hijaz-railway-station-tabuk-station-ktar-alhgaz-mht-tbok',1,0,'متحف قطار حجاز محطه تبوك hijaz railway station (tabuk station) تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782976,'tabuk-region','رأس الشيخ حميد','Ras Al Sheikh Hamid','ras-alsheikh-hamid-ras-alshykh-hmyd','["أماكن سياحية"]','["sights"]','رأس الشيخ حميد على ساحل منطقة تبوك، وجهة مميزة للسباحة والغوص بمياهها الصافية، ويطل على مضائق تيران وجبال سيناء المقابلة عبر البحر الأحمر.','<div class="texte" > <p>تعتبر منطقة رأس الشيخ حميد من المناطق المميزة لهواة السباحة والغوص، حيث تتميز مياه المنطقة بالصفاء، كما يمكن للزائر رؤية جبال شرم الشيخ والطور ومضائق تيران حيث لا تزيد المسافة بينهما عن 17 كيلو متر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782976-44735004.jpg?v=1641164567"]','https://cmsphoto.ww-cdn.com/resizeapi/826f0d32fce8b5ee1a38b3e361537f4e2790cbfd/480/',28.1181582,34.6303372,'Ras ِAlsheikh Hamid Tabuk Province SA','','','','https://www.saudi-guide.com/tabuk-region/i/59782976/ras-alsheikh-hamid-ras-alshykh-hmyd',1,0,'راس شيخ حميد ras al sheikh hamid اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782973,'tabuk-region','وادي طيب اسم','Wadi Tayeb Al Ism','wadi-tayyib-al-ism-oady-tyb-asm','["أماكن سياحية"]','["sights"]','وادي طيب اسم شمال مقنا، شق ضيق بين جبال شاهقة تجري فيه المياه طوال العام، وتقع على مدخله البحري واحة نخيل، ويضم ثلاث عيون عذبة قرب البحر.','<div class="texte" > <p>"طيب اسم" عبارة عن شق وسط جبال شاهقة تتوسطها مياه جارية طوال العام، وعلى مدخلة البحري تقع واحة من النخيل، والشق ضيق لدرجة لا تسمح إلا بمرور سيارة واحدة فقط. ويوجد بالوادي ثلاثة عيون أكثرها حلاوة تلك التي على مقربة من البحر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782973-44735003.jpg?v=1641164551"]','https://cmsphoto.ww-cdn.com/resizeapi/6418c66ec3db297e22f9aac6fa0ed25e970de665/480/',28.5598732,34.8021448,'SA Haql Tabuk Province','','','','https://www.saudi-guide.com/tabuk-region/i/59782973/wadi-tayyib-al-ism-oady-tyb-asm',1,0,'وادي طيب اسم wadi tayeb al ism اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782970,'tabuk-region','شاطئ مقنا','Magna Beach','shaty-mkna','["أماكن سياحية"]','["sights"]','شاطئ مقنا على خليج العقبة غرب البدع، يشتهر بمناظره البحرية الخلابة وشعابه المرجانية وعيون المياه القريبة كعين موسى، وتحيط به مزارع النخيل والفواكه.','<div class="texte" > <p>مقنا، مدينة ساحلية تقع على خليج العقبة في منطقة تبوك السعودية بين محافظة حقل ومركز رأس الشيخ، وتبعد قرية مقنا ما يقارب 35 كيلاً غربي محافظة البدع،&nbsp;وتبعد عن مدينة تبوك 235 كم،&nbsp;وتشتهر بمناظرها الخلابة ووجود عيني مياه بها وهي عين موسى وشمالها بـ 20 كيلو عين طيب اسم،&nbsp;كما تمتاز بكثرة وجود أشجار النخيل والفواكه والمانجو والليمون وكذلك مناظرها البحرية الخلابة الغنية بالأحياء البحرية والشعب المرجانية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782970-44735000.jpg?v=1641164534"]','https://cmsphoto.ww-cdn.com/resizeapi/3d054cc606ea407fb2764750f0ea29f78abd4fb8/480/',28.3639429,34.7258056,'9P7G+H8F Magna البدع','','','','https://www.saudi-guide.com/tabuk-region/i/59782970/shaty-mkna',1,0,'شاطئ مقنا magna beach اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782944,'tabuk-region','جزيرة أم عسيلة','Umm Asila Island','gzyr-am-aasyl','["أماكن سياحية"]','["sights"]','جزيرة أم عسيلة قبالة ساحل ضباء في البحر الأحمر، من الجزر الساحلية في منطقة تبوك، وجهة لمحبي البحر والطبيعة والرحلات البحرية والاستمتاع بالشواطئ الهادئة.','<div class="texte" > <p>جزيرة أم عسيلة من الجزر الواقعة قبالة ساحل منطقة تبوك في البحر الأحمر، وتُعد وجهة لمحبي البحر والطبيعة الهادئة والرحلات البحرية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782944-44735021.jpg?v=1641164884"]','https://cmsphoto.ww-cdn.com/resizeapi/21992bb3368290da301b12a1ac0b1871ee2a7533/480/',28.0627313,35.0875281,'337Q+32R Gayal Duba','','','','https://www.saudi-guide.com/tabuk-region/i/59782944/gzyr-am-aasyl',1,0,'جزيره ام عسيله umm asila island اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782941,'tabuk-region','جبل اللوز','Jabal al-Lawz','jabal-al-lawz-gbl-alloz','["أماكن سياحية"]','["sights"]','جبل اللوز شمال غرب تبوك، من أعلى قمم منطقة حسمى بارتفاع 2549 مترًا، يشتهر بتساقط الثلوج شتاءً وبرسومه الصخرية القديمة ونقوشه التي تعود لآلاف السنين.','<div class="texte" > <p>جبال اللوز هو جبل يقع في شمال غرب المملكة العربية السعودية قرب الحدود الأردنية في منطقة تبوك على بعد حوالي 200 كم شمال غرب مدينة تبوك. ويبلغ ارتفاعة (2549) متر فوق سطح البحر ويعتبر من أعلى السلاسل الجبلية في منطقة حسمى التي تعد جبالها امتداداً لجبال السروات من غرب تبوك حتى وادي رم بالأردن، ويسمى بجبل اللوز لوجود شجر اللوز به قديما، وتنتشر بالمنطقة الرسوم الصخرية التي يرجع تاريخها حوالي 10.000 سنة قبل الميلاد، بالإضافة إلى النقوش القديمة والكتابات الإسلامية، وقد ازدهرت المنطقة تجارياً بسبب موقعها الجغرافي المتميز واشتراكها في النمو الحضاري خلال حقبة زمنية معينة وهي الفترة النبطية للقرنين الأول والثاني قبل الميلاد وربما بعده مما يؤيد الاستيطان العربي القديم في المنطقة. كما وتتساقط عليه الثلوج أحيانًا في فصل الشتاء وأحيانًا في فصل الربيع إذا حصل منخفض جوي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782941-44734998.jpg?v=1641164514"]','https://cmsphoto.ww-cdn.com/resizeapi/10f2180b6ab44b1ade6dbf733a48ee4ff8096174/480/',28.6460625,35.286253,'Jabal al-Lawz Tabuk Province SA','','','','https://www.saudi-guide.com/tabuk-region/i/59782941/jabal-al-lawz-gbl-alloz',1,0,'جبل لوز jabal al lawz اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782924,'hail','جبل محجة التاريخي','Mahajjah Mountain','mahajjah-mountain-gbl-mhg-altarykhy','["أماكن سياحية"]','["sights"]','جبل محجة تشكيل صخري تكوّن بفعل التعرية والتجوية غرب حائل، تحمل جدرانه رسوماً ونقوشاً من عصور تاريخية مختلفة بعضها بالخط الآرامي، ومقصد لهواة الآثار.','<div class="texte" > <p>محجة هي تشكيلة صخرية تكونت بفعل عوامل التعرية والتجوية غرب مدينة حائل شمال السعودية وشرق قرية الجهراء،&nbsp;يوجد على جدرانها بعض الرسومات والطلاسم وبعض من المخطوطات منقوشة في عصور تاريخية مختلفة بعضها بالخط الآرامي غيرها من اللغات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782924-44970321.jpg?v=1642947796"]','https://cmsphoto.ww-cdn.com/resizeapi/b3ac5c3f405ec305f73031afb7f1cead78f2c413/480/',27.0019542,39.5000865,'2G22+Q2P Qamra Tayma','','','','https://www.saudi-guide.com/hail/i/59782924/mahajjah-mountain-gbl-mhg-altarykhy',1,0,'جبل محجه تاريخي mahajjah mountain اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782836,'tabuk-region','حصاة النصلة في تيماء','Al Naslaa Rock','al-naslaa-rock-formation-hsa-alnsl-fy-tymaaa','["أماكن سياحية"]','["sights"]','صخرة النصلة في تيماء، كتلة صخرية بارتفاع ثمانية أمتار منشطرة إلى نصفين متساويين تقريبًا بشكل مذهل، وتحمل نقوشًا ثمودية ورسومًا صخرية قديمة.','<div class="texte" > <p>تقع صخرة النصلة في محافظة تيماء بمنطقة تبوك، وهي كتلة صخرية بارتفاع نحو ثمانية أمتار منشطرة إلى نصفين متساويين تقريبًا بشكل لافت، وتحمل نقوشًا ثمودية ورسومات صخرية قديمة، وقد جعلها شكلها الفريد من أشهر المعالم الطبيعية في المملكة ومقصدًا لهواة التصوير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782836-44735053.jpg?v=1641165970"]','https://cmsphoto.ww-cdn.com/resizeapi/ed56164478fef6b414ae657c3c1e252ff9e0331e/480/',27.2294006,38.5717237,'SA Tayma Tabuk Province','','','','https://www.saudi-guide.com/tabuk-region/i/59782836/al-naslaa-rock-formation-hsa-alnsl-fy-tymaaa',1,0,'حصاه نصله في تيماء al naslaa rock اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782830,'tabuk-region','منتزه الأمير فهد بن سلطان البحري بحقل','Prince Fahd bin Sultan Marine Park in Haql','mntzh-alamyr-fhd-bn-sltan-albhry-bhkl','["أماكن سياحية"]','["sights"]','منتزه الأمير فهد بن سلطان البحري في حقل، متنزه على ساحل خليج العقبة يطل على البحر والجبال، ووجهة للعائلات للتنزه والجلسات البحرية في منطقة تبوك.','<div class="texte" > <p>يقع منتزه الأمير فهد بن سلطان البحري على ساحل محافظة حقل المطل على خليج العقبة، ويقصده الأهالي والزوار للتنزه والجلسات البحرية والاستمتاع بإطلالة البحر والجبال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782830-44735054.jpg?v=1641165989"]','https://cmsphoto.ww-cdn.com/resizeapi/7cfd77a6c35454c205eae33ed7a2b24800cc1336/480/',29.3008459,34.9406862,'8W2R+87M Al Sabkhah Haql','','','','https://www.saudi-guide.com/tabuk-region/i/59782830/mntzh-alamyr-fhd-bn-sltan-albhry-bhkl',1,0,'منتزه امير فهد بن سلطان بحري بحقل prince fahd bin sultan marine park in haql اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782807,'tabuk-region','منتزه النخيل بحقل','Palm Park in Haql','mntzh-alnkhyl-bhkl-alsaaody','["أماكن سياحية"]','["sights"]','منتزه النخيل في محافظة حقل بمنطقة تبوك، متنزه عائلي بين أشجار النخيل قرب الساحل، يناسب التنزه والجلسات العائلية وقضاء الأوقات في الهواء الطلق.','<div class="texte" > <p>يقع منتزه النخيل على طريق الملك عبدالعزيز في محافظة حقل، وهو متنزه عائلي تظلله أشجار النخيل، ويناسب التنزه والجلسات العائلية وقضاء الأوقات في الهواء الطلق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782807-44735058.jpg?v=1641166008"]','https://cmsphoto.ww-cdn.com/resizeapi/8a240432c4df7ddc4ad1cd715c0f4b0817cbe0be/480/',29.2993419,34.9491164,'King Abdulaziz Rd Al Sabkhah Haql','','','','https://www.saudi-guide.com/tabuk-region/i/59782807/mntzh-alnkhyl-bhkl-alsaaody',1,0,'منتزه نخيل بحقل palm park in haql اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782804,'tabuk-region','كورنيش ضبا الجنوبي','Duba South Corniche','kornysh-dba-algnoby','["أماكن سياحية"]','["sights"]','كورنيش ضباء الجنوبي على ساحل البحر الأحمر، واجهة بحرية للعائلات والزوار للمشي والجلسات البحرية والاستمتاع بإطلالة البحر في محافظة ضباء بمنطقة تبوك.','<div class="texte" > <p>يقع كورنيش ضباء الجنوبي على ساحل البحر الأحمر في محافظة ضباء، ويُعد من الواجهات البحرية التي يقصدها الأهالي والزوار للتنزه والمشي والجلسات العائلية والاستمتاع بإطلالة البحر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782804-44735059.jpg?v=1641166027"]','https://cmsphoto.ww-cdn.com/resizeapi/ce2a6210464382ce1d260aef2414bbf610baa146/480/',27.3111213,35.747342,'كورنيش ضبا الجنوبي منطقة تبوك SA','','','','https://www.saudi-guide.com/tabuk-region/i/59782804/kornysh-dba-algnoby',1,0,'كورنيش ضبا جنوبي duba south corniche اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782803,'tabuk-region','كورنيش ضبا الشمالي','Duba North Corniche','kornysh-dba-alshmaly','["أماكن سياحية"]','["sights"]','كورنيش ضباء الشمالي على البحر الأحمر، متنفس بحري يقصده الأهالي والزوار للتنزه والمشي والاستمتاع بالمناظر الساحلية وغروب الشمس في محافظة ضباء.','<div class="texte" > <p>يقع كورنيش ضباء الشمالي على ساحل البحر الأحمر في محافظة ضباء، ويوفر واجهة بحرية مفتوحة للتنزه والمشي والجلسات العائلية، ويقصده الزوار للاستمتاع بهدوء البحر وغروب الشمس.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782803-44735060.jpg?v=1641166043"]','https://cmsphoto.ww-cdn.com/resizeapi/5f543de72079f1a043d424b345226f4e56a92bee/480/',27.3369759,35.7086059,'Duba Tabuk Province SA','','','','https://www.saudi-guide.com/tabuk-region/i/59782803/kornysh-dba-alshmaly',1,0,'كورنيش ضبا شمالي duba north corniche اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782781,'tabuk-region','عين الديسة','Ain Al Disah','aayn-aldys','["أماكن سياحية"]','["sights"]','عين الديسة في قرية الديسة جنوب غرب تبوك، من عيون المياه العذبة التي تغذي واحة الديسة ونخيلها، وسط جبال رملية شاهقة تشكّل مناظر طبيعية آسرة.','<div class="texte" > <p>تقع عين الديسة في وادي الديسة جنوب غرب مدينة تبوك، وهي من العيون الطبيعية التي تغذي الوادي وتمنحه جداوله وخضرته وأشجار النخيل المنتشرة فيه، ما يجعلها محطة مميزة لزوار الوادي ومحبي الطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782781-44735064.jpg?v=1641166058"]','https://cmsphoto.ww-cdn.com/resizeapi/11d3fb866ceffba990b0ccb68341ff6629de5735/480/',27.6336129,36.5209144,'JGMC+C9V Al-Disah Duba','','','','https://www.saudi-guide.com/tabuk-region/i/59782781/aayn-aldys',1,0,'عين ديسه ain al disah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59782776,'tabuk-region','وادي الديسة','Wadi Al Disah','oady-aldys','["أماكن سياحية"]','["sights"]','وادي الديسة جنوب غرب تبوك، وادٍ تحفه جبال على هيئة أعمدة وأبراج صخرية شاهقة، تجري فيه العيون وتنتشر فيه أشجار النخيل، ووجهة للمشي والتخييم والتصوير.','<div class="texte" > <p>يقع وادي الديسة على بُعد نحو 200 كيلومتر من مدينة تبوك، ويتميز بأعمدة وأبراج صخرية شاهقة يصل ارتفاع بعضها إلى نحو 250 مترًا، تتخللها عيون مائية وجداول وأشجار النخيل، ما يجعله من أجمل الوجهات الطبيعية في المملكة لمحبي المغامرة والتصوير والتخييم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59782776-44735067.jpg?v=1641166078"]','https://cmsphoto.ww-cdn.com/resizeapi/b90d07d74f94f179d7ffad1ea35551a578e8ba4b/480/',27.6021254,36.4310251,'JC2J+VC2 Al-Disah Duba','','','','https://www.saudi-guide.com/tabuk-region/i/59782776/oady-aldys',1,0,'وادي ديسه wadi al disah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59779472,'tabuk-region','جزيرة الظهرة بالوجه','Al Dhahra Island in Al Wajh','gzyr-althhr-balogh','["أماكن سياحية"]','["sights"]','جزيرة الظهرة الرملية في البحر الأحمر جنوب غرب محافظة الوجه، على بعد نحو 8 كيلومترات منها، وأقرب الجزر إليها جزيرة ريخة، ووجهة لمحبي البحر والطبيعة.','<div class="texte" > <p>جزيرة الظهرة&nbsp;هي إحدى الجزر الواقعة في&nbsp;البحر الأحمر، وتتبع&nbsp;منطقة تبوك&nbsp;شمال غرب&nbsp;السعودية، وهي عبارة عن&nbsp;<span>جزيرة رملية، تقع جنوب غرب&nbsp;محافظة الوجة&nbsp;وتبعد عنها 8 كم،</span>&nbsp;وأقرب جزيرة لها&nbsp;جزيرة ريخة&nbsp;التي تقع في شمال غرب جزيرة الظهرة.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59779472-44735071.jpg?v=1641166098"]','https://cmsphoto.ww-cdn.com/resizeapi/d1833ea66bd462e5fb13b07e607876d21e34d5f8/480/',26.1583146,36.4326576,'5C5M+83F Al Wajh SA','','','','https://www.saudi-guide.com/tabuk-region/i/59779472/gzyr-althhr-balogh',1,0,'جزيره ظهره بالوجه al dhahra island in al wajh اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59779311,'tabuk-region','شاطئ زاعم بالوجه','Zaem Beach in Al Wajh','shaty-zaaam-balogh','["أماكن سياحية"]','["sights"]','شاطئ زاعم في محافظة الوجه على ساحل البحر الأحمر، شاطئ هادئ بمياه صافية يقصده الأهالي والزوار للسباحة والتنزه والاستمتاع بالأجواء البحرية.','<div class="texte" > <p>يقع شاطئ زاعم على ساحل البحر الأحمر في محافظة الوجه، ويتميز بمياهه الصافية ورماله، ويقصده الزوار للسباحة والتنزه والاستمتاع بهدوء الطبيعة الساحلية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59779311-44735077.jpg?v=1641166188"]','https://cmsphoto.ww-cdn.com/resizeapi/ea2b99b86231abe9c9a7288446ae842397bababe/480/',26.2916659,36.4110269,'King Abdullah Rd Al Wajh Al Wajh','','','','https://www.saudi-guide.com/tabuk-region/i/59779311/shaty-zaaam-balogh',1,0,'شاطئ زاعم بالوجه zaem beach in al wajh اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59779303,'tabuk-region','شاطئ الوجه الصخرة','Al Wajh Rock Beach','shaty-alogh-alskhr','["أماكن سياحية"]','["sights"]','شاطئ الصخرة في الوجه على البحر الأحمر، شاطئ يتميز بتكويناته الصخرية ومياهه الصافية، ووجهة للتنزه والتصوير والاستمتاع بالطبيعة الساحلية في منطقة تبوك.','<div class="texte" > <p>يقع شاطئ الصخرة على ساحل البحر الأحمر في محافظة الوجه، ويتميز بتكويناته الصخرية المطلة على البحر، ويقصده الزوار للتنزه والتصوير والاستمتاع بالإطلالة البحرية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59779303-44735078.jpg?v=1641166208"]','https://cmsphoto.ww-cdn.com/resizeapi/aa8dab4c44949ab03e70a3216a1d9f123b6c536c/480/',26.243652,36.447739,'Al Wajh SA 48721','','','','https://www.saudi-guide.com/tabuk-region/i/59779303/shaty-alogh-alskhr',1,0,'شاطئ وجه صخره al wajh rock beach اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59779291,'tabuk-region','ستيشن 67','Station 67','station-67-styshn-67','["أماكن سياحية"]','["sights"]','ستيشن 67 على طريق الملك فيصل في تبوك، محطة سياحية عصرية مصممة بأسلوب حاويات الشحن، تضم مطاعم ومقاهي ومتاجر ومنطقة ألعاب للأطفال وفعاليات موسمية.','<div class="texte" > <p>ستيشن 67 وجهة ترفيهية على طريق الملك فيصل في مدينة تبوك، تمتد على مساحة نحو 10 آلاف متر مربع بتصميم مستوحى من حاويات الشحن، وتضم أكثر من 25 مطعمًا ومقهى إلى جانب منطقة للأطفال ومتاجر متنوعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59779291-47687447.jpg?v=1663547941"]','https://cmsphoto.ww-cdn.com/resizeapi/2ab1b421f3af4fad3a4bd05a60531abd9bd883a2/480/',28.4626738,36.515202,'King Faisal Rd Petromin Tabuk','','','','https://www.saudi-guide.com/tabuk-region/i/59779291/station-67-styshn-67',1,0,'ستيشن 67 station 67 اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59779286,'tabuk-region','بحيرة رايس','Rays Lake','rays-lake-bhyr-rays','["أماكن سياحية"]','["sights"]','بحيرة رايس في تبوك، بحيرة بمياه زرقاء هادئة تحيط بها الخضرة والجبال، وجهة للاسترخاء والتنزه والتخييم والتصوير بعيدًا عن صخب المدينة.','<div class="texte" > <p>تتميز بحيرة ريس في منطقة تبوك بمياهها الزرقاء الهادئة التي تحيط بها الخضرة والجبال، وتُعد وجهة طبيعية مناسبة للتخييم والتصوير والاستمتاع بالهدوء بعيدًا عن صخب المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59779286-44735081.jpg?v=1641166245"]','https://cmsphoto.ww-cdn.com/resizeapi/090a2f4003e1b22eff741c6a4edb4c1ee4591bbc/480/',28.3081555,36.5042857,'8G53+7P7 Tabuk Tabouk','','','','https://www.saudi-guide.com/tabuk-region/i/59779286/rays-lake-bhyr-rays',1,0,'بحيره رايس rays lake اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59779273,'tabuk-region','منتزه الأمير فهد بن سلطان','Prince Fahd bin Sultan Park','mntzh-alamyr-fhd-bn-sltan','["أماكن سياحية"]','["sights"]','منتزه الأمير فهد بن سلطان في مدينة تبوك، حديقة واسعة بمسطحات خضراء ومضمار للمشي والجري وألعاب للأطفال، ووجهة رئيسية للعائلات والرياضة والترفيه.','<div class="texte" > <p>منتزه الأمير فهد بن سلطان من المتنزهات العامة في مدينة تبوك، يضم مساحات خضراء واسعة ومسارًا للمشي، ويقصده الأهالي والزوار للتنزه والرياضة والجلسات العائلية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59779273-44735084.jpg?v=1641166259"]','https://cmsphoto.ww-cdn.com/resizeapi/63570c3b774ba9293a58f0ee46440d06528c5f0a/480/',28.4659679,36.5213576,'King Faisal Rd Petromin Tabuk','','','','https://www.saudi-guide.com/tabuk-region/i/59779273/mntzh-alamyr-fhd-bn-sltan',1,0,'منتزه امير فهد بن سلطان prince fahd bin sultan park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59779223,'tabuk-region','جادة الأمير فهد بن سلطان','Prince Fahd bin Sultan Walkway','gad-alamyr-fhd-bn-sltan','["أماكن سياحية"]','["sights"]','جادة الأمير فهد بن سلطان في قلب تبوك، أعرض شوارع المدينة التجارية وأعرقها، تمتد من قلعة تبوك شرقًا وتجاور عين السكر والمسجد الأثري، ومقصد للتسوق والمشي.','<div class="texte" > <p>جادة الأمير فهد بن سلطان ممشى للمشاة في وسط مدينة تبوك، يمتد بطول نحو 753 مترًا وعرض 20 مترًا من قلعة تبوك التاريخية شرقًا، وافتُتح عام 1992م، ويجاور عين السكر والمسجد القديم، ليشكل وجهة للتنزه في قلب المدينة التاريخي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59779223-44735085.jpg?v=1641166276"]','https://cmsphoto.ww-cdn.com/resizeapi/1a8729ac79db0a9ba3d978deba7afd406c9541e1/480/',28.3850374,36.5630969,'Tabuk Al''awayshah Tabouk','','','','https://www.saudi-guide.com/tabuk-region/i/59779223/gad-alamyr-fhd-bn-sltan',1,0,'جاده امير فهد بن سلطان prince fahd bin sultan walkway اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59747551,'medina','حصن كعب بن الأشرف','Fort Kaab Bin Ashraf','fort-kaab-bin-ashraf','["التراث والثقافة"]','["heritage"]','حصن كعب بن الأشرف بالمدينة المنورة، من أقدم الحصون التاريخية بني قبل 14 قرنًا، بمساحة تقارب 2000 متر مربع وذو 20 غرفة وثمانية أبراج مراقبة.','<div class="texte" > <p>حصن كعب بن الأشرف، من&nbsp;الحصون&nbsp;القديمة في&nbsp;المدينة المنورة، ويُعتبر من أهم وأبرز القلاع التاريخية فيها تم بناؤه قبل 14 قرنًا، وقدرت مساحته بحوالي 2000 متر مربع. وتتكون من 20 غرفة وثمانية أبراج مراقبة إلا أن جزءًا كبيرًا من القلعة تم تدميره واختفاءه على مر العصور، ولا يزال هناك بقايا هذا الحصن الذي يزوره العديد من السكان المحليين والسياح المهتمين&nbsp;بالآثار&nbsp;والتاريخ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59747551-44307028.jpg?v=1637903843"]','https://cmsphoto.ww-cdn.com/resizeapi/61e848af88a2b1738a311a2ea46e7da6c3ea5565/480/',24.4187347,39.6335975,'عبدالمحسن بن عبدالعزيز السد المدينة المنورة','','','','https://www.saudi-guide.com/medina/i/59747551/fort-kaab-bin-ashraf',1,0,'حصن كعب بن اشرف fort kaab bin ashraf تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59690100,'riyadh','موسم الرياض','Riyadh Season','riyadh-season-mosm-alryad','["أماكن سياحية"]','["sights"]','موسم الرياض من أكبر المواسم الترفيهية في المنطقة، يضم فعاليات متنوعة تشمل الحفلات والعروض المسرحية والمعارض والتجارب التفاعلية في مناطق متعددة بالرياض.','<div class="texte" > <p>موسم الرياض مهرجان ترفيهي وثقافي وسياحي سنوي تنظمه الهيئة العامة للترفيه في مدينة الرياض خلال أشهر الشتاء. يضم الموسم عدداً من المناطق الترفيهية مثل بوليفارد سيتي وبوليفارد وورلد وحديقة السويدي وحديقة حيوانات الرياض، إلى جانب الحفلات الغنائية والعروض المسرحية والبطولات الرياضية العالمية والمطاعم والمقاهي المتنوعة التي تناسب جميع أفراد العائلة.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59690100-43820475.jpg?v=1634805938", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59690100-43820474.jpg?v=1634805946"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/59690100-43820475.jpg?v=1634806210',24.7682111,46.6054909,'6871 سويد بن حارثة، Hittin','','','','https://www.saudi-guide.com/riyadh/i/59690100/riyadh-season-mosm-alryad',1,0,'موسم رياض riyadh season اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660193,'umluj','قصر الإمارة القديم بأملج','','ksr-alamar-alkdym-bamlg','["التراث والثقافة"]','["heritage"]','قصر الإمارة يقع وسط مدينة أملج القديمة، ويأخذ شكل القلعة الحصينة في تخطيطه، وكان مقرًا للإمارة لفترة طويلة، ويُعد من الأمثلة القليلة الباقية من المباني القديمة بمدينة أملج.','<div class="texte" > <p>قصر الإمارة&nbsp;يقع القصر وسط مدينة&nbsp;أملج&nbsp;القديمة، ويأخذ شكل القلعة الحصينة في تخطيطه٬ وكان مقرًا للإمارة لفترة طويلة٬ ويعد من الأمثلة القليلة الباقية من المباني القديمة&nbsp;بمدينة أملج.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59660193-44758369.jpg?v=1641325277"]','https://cmsphoto.ww-cdn.com/resizeapi/8067383df0510bf6fed94877032f97502b0de3dc/480/',25.0234615,37.2650617,'27F8+92M Al Balad Umluj','','','','https://www.saudi-guide.com/umluj/i/59660193/ksr-alamar-alkdym-bamlg',1,0,'قصر اماره قديم باملج تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660189,'umluj','متحف المناخة التراثي بأملج','','mthf-almnakh-altrathy-bamlg','["التراث والثقافة"]','["heritage"]','تم إنشاء متحف المناخة التراثي في أملج عام 2015 على يد الدكتور مساعد سلامة الفايدي، ويضم معرضًا على مساحة 8000 متر مربع يشمل آثارًا ومكتبة تاريخية وموروثًا شعبيًا وسيارات قديمة تعكس تاريخ أملج العريق.','<div class="texte" > <p>تم إنشاء متحف المناخة التراثي في عام 2015 على يد الدكتور مساعد سلامة الفايدي في مدينة أملج، ويضم معرضاً ممتداً على مساحة 8000 متر مربع، وتشمل مجموعته الدائمة آثاراً هامة ومكتبة تاريخية وملابس وموروث شعبي وسيارات قديمة وغيرها الكثير من المقتنيات التي تعكس تاريخ أملج العريق، وقد تمت تسمية المتحف بهذا الاسم لأن الإبل كانت "تنوخ" أي تجلس بجانب هذا الموقع نظراً لوجوده بجوار عين ماء أثرية قديماً.</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/uRMBsu2sqJw?si=UdgsX1oyCPAwtMm2&gbyoutube=uRMBsu2sqJw" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe> <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59660189-44758412.jpg?v=1641325669"]','https://cmsphoto.ww-cdn.com/resizeapi/32b35fb4cf00523c981dae07bee4038f2771cb10/480/',25.0594383,37.2758045,'375G+Q8F Umluj Umluj','','','','https://www.saudi-guide.com/umluj/i/59660189/mthf-almnakh-altrathy-bamlg',1,0,'متحف مناخه تراثي باملج تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660167,'umluj','جزيرة المقيطع بأملج','','gzyr-almkytaa-bamlg','["أماكن سياحية"]','["sights"]','جزيرة المقيطع إحدى الجزر الواقعة قبالة سواحل مدينة أملج بمنطقة تبوك، وتُعد وجهة طبيعية جاذبة لهواة الرحلات البحرية والغطس والاستمتاع بمياه البحر الأحمر الصافية.','<div class="texte" > <p>تقع جزيرة المقيطع قبالة سواحل محافظة أملج بمنطقة تبوك على البحر الأحمر، وتشتهر بمياهها الفيروزية الصافية وشعابها المرجانية المتنوعة، مما يجعلها وجهة مفضلة لهواة رحلات القوارب والغطس والغوص ومشاهدة الحياة البحرية.</p> </div>','[]','',24.7914279,37.1928056,'جزيرة المقيطع املج منطقة تبوك','','','','https://www.saudi-guide.com/umluj/i/59660167/gzyr-almkytaa-bamlg',1,0,'جزيره مقيطع باملج اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660166,'umluj','جزيرة جبل حسان - أملج','','gzyr-gbl-hsan-amlg','["أماكن سياحية"]','["sights"]','جزيرة جبل حسان تقع في الساحل الشمالي الغربي للمملكة بالبحر الأحمر، تتبع إداريًا لمحافظة أملج بمنطقة تبوك، وتبعد عن شاطئ أملج نحو 18 كم، وكانت ممرًا للسفن بين مصر والجزيرة العربية والأردن قديمًا.','<div class="texte" > <p>جزيرة جبل حسان&nbsp;هي&nbsp;جزيرة&nbsp;تقع في الساحل الشمالي الغربي&nbsp;للمملكة العربية السعودية&nbsp;في&nbsp;البحر الأحمر، تتبع إدارياً&nbsp;لمحافظة أملج&nbsp;الواقعة&nbsp;بمنطقة تبوك، وتبعد&nbsp;عن شاطئ مدينة أملج حوالي 18 كيلو متر، وسميت بجبل حسان نسبة لبطن الحساسنة من&nbsp;جهينة، وكانت ممر للسفن بين&nbsp;مصر&nbsp;والجزيرة العربية&nbsp;والأردن قديماً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59660166-44758404.jpg?v=1641325603"]','https://cmsphoto.ww-cdn.com/resizeapi/e41c4a5bf6880aed29ce290000dcd8cd09b73f4f/480/',24.9650571,37.0905898,'جزيرة جبل حسان املج منطقة تبوك','','','','https://www.saudi-guide.com/umluj/i/59660166/gzyr-gbl-hsan-amlg',1,0,'جزيره جبل حسان املج اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660160,'umluj','شاطئ املج','Umluj Beach','umluj-beach-shaty-amlg','["أماكن سياحية"]','["sights"]','شاطئ أملج من أبرز الشواطئ الرملية في مدينة أملج بمنطقة تبوك، يتميز برماله البيضاء ومياهه الفيروزية الهادئة، ويُعد وجهة مفضلة للعائلات للاستجمام والسباحة على ساحل البحر الأحمر.','<div class="texte" > <p>يقع شاطئ أملج في حي الروضة بمدينة أملج على ساحل البحر الأحمر، ويتميز برماله الناعمة ومياهه الهادئة الصافية ذات التدرجات اللونية الفيروزية، ما يجعله وجهة مفضلة للعائلات والزوار الراغبين في الاسترخاء والاستمتاع بالأجواء الساحلية الهادئة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59660160-44758426.jpg?v=1641325887"]','https://cmsphoto.ww-cdn.com/resizeapi/f862bc9b4ccaafa28715b86a85caee50c65ab6a7/480/',25.0408911,37.2523595,'Prince Abdul Majeed Ibn Abdulaziz Al Rawdhah Umluj','','','','https://www.saudi-guide.com/umluj/i/59660160/umluj-beach-shaty-amlg',1,0,'شاطئ املج umluj beach اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660159,'umluj','مرسى الحره','Marsa Umluj Alhurra','marsa-umluj-alhurra-mrs-alhrh','["أماكن سياحية"]','["sights"]','مرسى الحرة أحد المراسي الساحلية في مدينة أملج بمنطقة تبوك، يُستخدم كنقطة انطلاق للرحلات البحرية والغطس واستكشاف الجزر والشعاب المرجانية القريبة من ساحل البحر الأحمر.','<div class="texte" > <p>يقع مرسى الحرة بالقرب من مدينة أملج على ساحل البحر الأحمر، ويتميز بمياهه الهادئة المحمية التي تجعله مناسبًا لانطلاق رحلات القوارب والأنشطة البحرية والاستمتاع بمناظر الساحل الطبيعية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59660159-44758427.jpg?v=1641325906"]','https://cmsphoto.ww-cdn.com/resizeapi/3d143f40e2a632f04cb8ab8d219564df21cc9d11/480/',25.2015755,37.2234593,'مرسى الحره Umluj SA','','','','https://www.saudi-guide.com/umluj/i/59660159/marsa-umluj-alhurra-mrs-alhrh',1,0,'مرسي حره marsa umluj alhurra اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660157,'umluj','شاطئ الدقم للسباحة','','shaty-aldkm-llsbah','["أماكن سياحية"]','["sights"]','شاطئ الدقم من الشواطئ المخصصة للسباحة في مدينة أملج بمنطقة تبوك، يقع في حي المرجان، ويتميز بمياهه الهادئة الصالحة للسباحة والاستجمام العائلي على ساحل البحر الأحمر.','<div class="texte" > <p>يقع شاطئ الدقم للسباحة في حي المرجان بمحافظة أملج على ساحل البحر الأحمر، ويتميز بمياهه الصافية الهادئة ورماله الناعمة، ما يجعله من الشواطئ المناسبة للسباحة والاستجمام على مدار العام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59660157-44758429.jpg?v=1641325922"]','https://cmsphoto.ww-cdn.com/resizeapi/d49ef2d6072598ea57a334ce5bf79f65be44f601/480/',25.0856429,37.2605637,'37P6+764 المرجان، املج','','','','https://www.saudi-guide.com/umluj/i/59660157/shaty-aldkm-llsbah',1,0,'شاطئ دقم للسباحه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59660155,'umluj','كورنيش أملج','Umluj Corniche','umluj-corniche-kornysh-amlg','["أماكن سياحية"]','["sights"]','كورنيش أملج هو الواجهة البحرية لمدينة أملج بمنطقة تبوك، ويوفر مسارات للمشي وجلسات مطلة على البحر الأحمر، ما يجعله وجهة يومية مفضلة للأهالي والزوار للتنزه ومشاهدة الغروب.','<div class="texte" > <p>يمتد كورنيش أملج على طول ساحل مدينة أملج المطل على البحر الأحمر، ويضم ممشى بحريًا يتيح للزوار الاستمتاع بمناظر البحر الخلابة، ويُعد من أبرز الوجهات الترفيهية والمسائية المفضلة لدى السكان والزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59660155-44758432.jpg?v=1641325943"]','https://cmsphoto.ww-cdn.com/resizeapi/ed179f80a57926277885bf4287ad7ab59e4149c4/480/',25.0714534,37.2443732,'36CV+HPQ Umluj Umluj','','','','https://www.saudi-guide.com/umluj/i/59660155/umluj-corniche-kornysh-amlg',1,0,'كورنيش املج umluj corniche اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59653197,'yanbu','المسرح الروماني','Roman Theater','almsrh-alromany','["أماكن سياحية"]','["sights"]','المسرح الروماني في ينبع، معلم سياحي مستوحى من فكرة المسارح الرومانية المستديرة، تتوسطه حلبة عرض تحيط بها مقاعد متدرجة من الأسفل إلى الأعلى.','<div class="texte" > <p>المسرح الروماني هو بناء مستدير أو بيضاوي لعرض الألعاب المختلفة، تتوسطه&nbsp;حلبة&nbsp;العرض ومن حولها مقاعد النظارة تتدرج من أسفل إلى أعلى، وقد تم اقتباس هذه الفكرة لإنشاء المسرح الروماني في ينبع باعتباره مكاناً&nbsp;سياحياً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59653197-44171827.jpg?v=1637143390"]','https://cmsphoto.ww-cdn.com/resizeapi/e80ae9d8f997866391601f6d12dfae6600fa9589/480/',24.0281994,38.1364397,'24HP+7HG Al-Jaar Yanbu','','','','https://www.saudi-guide.com/yanbu/i/59653197/almsrh-alromany',1,0,'مسرح روماني roman theater اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59653195,'yanbu','جزيرة البريدي','Al Buraidi Island','gzyr-albrydy','["أماكن سياحية"]','["sights"]','جزيرة البريدي في ينبع، وجهة بحرية مفضلة بطبيعتها الخلابة ورمالها الناعمة ومياهها الصافية، تتيح للزوار السباحة والغوص وصيد الأسماك.','<div class="texte" > <p>تعد جزيرة البريدي وجهة سياحية بحرية مفضلة للسياح حيث أنها عُرفت بطبيعتها الخلابة ورمالها الناعمة ومياهها الصافية والنقية والتي تتيح للزوار ممارسة عدد من الأنشطة مثل السباحة والغوص وصيد الأسماك.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59653195-44371285.jpg?v=1638177693"]','https://cmsphoto.ww-cdn.com/resizeapi/6ff2bfdd9f0ab9c782fd6c102803b45b77a63cb8/480/',24.2514963,37.6643336,'Yanbu SA 46411','','','','https://www.saudi-guide.com/yanbu/i/59653195/gzyr-albrydy',1,0,'جزيره بريدي al buraidi island اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59653170,'yanbu','حديقة الصبح','Alsubh Park','alsubh-park-hdyk-alsbh','["أماكن سياحية"]','["sights"]','حديقة الصبح من أجمل حدائق ينبع، تجمع بين الطبيعة الخلابة والإطلالة الرائعة على البحر، وتضم مسارات للمشي ومناطق ألعاب للأطفال.','<div class="texte" > <p>تعتبر حديقة الصبح من أجمل حدائق ينبع بما تحتويه من طبيعة خلابة ذات جمال ساحر وإطلالة رائعة على البحر، بالإضافة إلى مسارات المشي ومناطق الألعاب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59653170-44371286.jpg?v=1638177716"]','https://cmsphoto.ww-cdn.com/resizeapi/6b901df5f9c4a90bbb478146553cf8d33351e603/480/',23.9898469,38.1920851,'X5QR+WRP Al Subh Yanbu','','','','https://www.saudi-guide.com/yanbu/i/59653170/alsubh-park-hdyk-alsbh',1,0,'حديقه صبح alsubh park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59653058,'yanbu','حديقة الفيروز','Al Fairouz Park','al-fairouz-park-hdyk-alfyroz','["أماكن سياحية"]','["sights"]','حديقة الفيروز في ينبع، حديقة واسعة بمسطحات خضراء وأشجار ونباتات متنوعة، تضم مجسمات جميلة وألعابًا للأطفال وتناسب النزهات العائلية.','<div class="texte" > <p>تتميز حديقة الفيروز باتساعها ومسطحاتها الخضراء وبتنوع الأشجار والنباتات فيها بالإضافة إلى وجود عدد من المجسمات الرائعة وألعاب الأطفال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59653058-44371288.jpg?v=1638177745"]','https://cmsphoto.ww-cdn.com/resizeapi/e289979b7b0eceb9c386d52a8e6d368719f6db40/480/',23.996687,38.2193403,'8248 King Saud Rd An Nawah','','','','https://www.saudi-guide.com/yanbu/i/59653058/al-fairouz-park-hdyk-alfyroz',1,0,'حديقه فيروز al fairouz park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59653013,'yanbu','مرسى الأحلام السياحي - مرسى للقوارب','Al Ahlam Tourist Marina','mtaam-mrs-alahlam-alsyahy-mrs-llkoarb','["أماكن سياحية"]','["sights"]','مرسى الأحلام السياحي في ينبع، مرسى للقوارب يتيح الرحلات البحرية ورحلات الغوص، ويضم مطعمًا ومقهى بإطلالة فريدة ومميزة على شرم ينبع.','<div class="texte" > <p>يتيح مرسى الأحلام السياحي للزائر فرصة الاستمتاع بالرحلات البحرية ورحلات الغوص، بالإضافة إلى وجود مطعم ومقهى يقدمان أشهى المأكولات وأفضل المشروبات بإطلالة فريدة ومميزة على شرم ينبع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59653013-44371659.jpg?v=1638179578"]','https://cmsphoto.ww-cdn.com/resizeapi/619270e3c6dc308c1cc3259273565ea49ac69091/480/',24.168108,37.964371,'Yanbu Al Bahr Yanbu Al Bahr Al Madinah Province','','','','https://www.saudi-guide.com/yanbu/i/59653013/mtaam-mrs-alahlam-alsyahy-mrs-llkoarb',1,0,'مرسي احلام سياحي مرسي للقوارب al ahlam tourist marina اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652247,'yanbu','جبل رضوى','Radwa Mount','radwa-mount-gbl-rdo','["أماكن سياحية"]','["sights"]','جبل رضوى في محافظة ينبع، من أشهر جبال الحجاز بارتفاع يبلغ 2170 مترًا، جبل وعر يصعب صعوده، ومن قمته تُرى مدينة ينبع كاملة.','<div class="texte" > <p>جبل رضوى&nbsp;هو جبل يقع في محافظة&nbsp;ينبع&nbsp;بمنطقة&nbsp;المدينة المنورة&nbsp;غرب&nbsp;المملكة العربي&nbsp;السعودية&nbsp;في ديار جهينة تحده من شمال الشرق قرية الفقعلي، ويحده من شمال الغرب قرية رخو هجرة قبيلة رفاعة وتحده من جنوب الغرب قرية تلعة نزا هجرة قبيلة نزاء ويبلغ ارتفاعه 2170 متراً.</p> <p>يتميز هذا الجبل بارتفاعه وجماله وشهرته على مر التاريخ وهو من الجبال الوعرة التي يصعب صعودها ومن قمته ترى مدينة ينبع كاملة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652247-44172198.jpg?v=1637144903"]','https://cmsphoto.ww-cdn.com/resizeapi/74a015306c510ebfd77cd93a7ed8ce33b29178ae/480/',24.5354871,38.3587174,'Radwa Mount Yanbu Al Bahr Al Madinah Province','','','','https://www.saudi-guide.com/yanbu/i/59652247/radwa-mount-gbl-rdo',1,0,'جبل رضوي radwa mount اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652244,'yanbu','سوق الجابرية التراثي','Jabriyah Heritage Market','jabriyah-heritage-market-sok-algabry-altrathy','["التراث والثقافة"]','["heritage"]','سوق الجابرية التراثي في قرية الجابرية بينبع النخل، سوق قديم من دكاكين متجاورة كانت تُباع فيه المواد الغذائية والمواشي والأعلاف والحطب.','<div class="texte" > <p>الجابرية&nbsp;قرية&nbsp;من قرى&nbsp;ينبع النخل&nbsp;في&nbsp;محافظة ينبع&nbsp;التابعة&nbsp;لمنطقة المدينة المنورة&nbsp;في&nbsp;السعودية، قديماً كان بها سوق الجابرية الشهير، وهو عبارة عن سوق مكون من عدة دكاكين كان في الماضي يباع فيها المواد الغذائية بأنواعها والمواشي والأعلاف والحطب وغيره، وبها أيضاً "الجلابين" أو "الحلة" وهي عبارة عن بيوت متجاورة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652244-44371304.jpg?v=1638177793"]','https://cmsphoto.ww-cdn.com/resizeapi/18954010fb9c2801400a4a533f1cb6b8a421bffb/480/',24.3185972,38.415087,'SA ينبع النخل ينبع البحر','','','','https://www.saudi-guide.com/yanbu/i/59652244/jabriyah-heritage-market-sok-algabry-altrathy',1,0,'سوق جابريه تراثي jabriyah heritage market تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652240,'yanbu','متحف رضوى التراثي','Radhwa Museum','mthf-rdo-lsahbh-salm-alhgory','["التراث والثقافة"]','["heritage"]','متحف رضوى التراثي في ينبع، من أكبر المتاحف التراثية في المملكة، حوّله سالم الحجوري من منزله إلى متحف يضم ست قاعات من المقتنيات التراثية النادرة.','<div class="texte" > <div data-original-size="14px"> <div data-habitat="C1" data-original-size="14px"> <section data-original-size="14px"> <div data-original-size="14px"> <div data-original-size="14px"> <div data-original-size="16px"> <p data-original-size="16px">يُعدُّ&nbsp;متحف رضوى&nbsp;واحدًا من أكبر المتاحف في السعودية، نشأ حين قرر سالم الحجوري؛ أحد المولعين بالتاريخ، تحويل منزله إلى متحف، وارثًا عن والده هذه الهواية الثمينة، كان يجمع في البداية الصحف والكتب والطوابع البريدية، ثم تطوَّر الأمر، واتسعت رغبته ليحتفظ بكل ما يعكس تاريخ المنطقة ويظهره كما يليق به، لتثمر هوايته أخيرًا عن تحفة سياحية.</p> </div> </div> </div> </section> </div> </div> <div data-original-size="14px"> <div data-habitat="C1" data-original-size="14px">فور دخولك لمتحف رضوى لن تصدق حجم المقتنيات التراثية الموجود في مكانٍ واحد، منها مجموعة من الأواني الخاصة بالقهوة والأسلحة والفوانيس، كما يحاكي تصميم المكان الدكاكين القديمة، وينقسم إلى ست قاعات، تستعرض القاعة الأولى منسوجات وملابس ومحنّطات، وتتزيّن القاعة الثانية بالفنون التشكيلية وقطع حربية تعود للعصور الإسلامية الأولى، مثل: سيوف، وبنادق، ودروع مطرزة بعبارات باللغة العربية، وستكون بانتظارك في القاعة الثالثة العديد من العملات الإسلامية والعربية النادرة، أما القاعة الرابعة فانفردت بمخطوطات وصحف وكتب قديمة، وتعرض القاعة الخامسة مجموعة من أواني الطهي المصنوعة من النحاس والفخار، وفي القاعة السادسة أدوات استخدمت في الصيد قديمًا، ومجموعة من الأسماك الكبيرة المحنَّطة التي تعكس تنوّع الحياة البحرية في ينبع.</div> </div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652240-44383556.jpg?v=1638242604", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652240-63567819.jpg?v=1753137107"]','https://cmsphoto.ww-cdn.com/resizeapi/a7407fd538104e928fb78cac205c8478b9361303/480/',24.0805625,38.0613125,'33j6+6g9 Al Sur Yanbu','','https://www.visitsaudi.com/ar/yanbu/attractions/radhwa-museum-in-yanbu','','https://www.saudi-guide.com/yanbu/i/59652240/mthf-rdo-lsahbh-salm-alhgory',1,0,'متحف رضوي تراثي radhwa museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652182,'yanbu','المنطقة التاريخية سوق الليل','Night market','night-market-almntk-altarykhy-sok-allyl','["التراث والثقافة"]','["heritage"]','منطقة ينبع التاريخية وسوق الليل، منطقة يقدّر عمرها بنحو 2500 عام، شهدت أحداثًا تاريخية بارزة وسكنتها شخصيات مهمة، وأصبحت اليوم متحفًا تراثيًا مفتوحًا.','<video controls controlsList="nodownload" poster="https://cmsphoto.ww-cdn.com/superstatic/images/2892882/video/2460709/player/player_preview.jpg?v=1638656950" width="100%" oncontextmenu="return false;"><source src="https://www.saudi-guide.com/apiv3/video/getIphoneSVideo/2460709/38053850.mp4/" type="video/mp4" /></video> <div class="texte" > <p>منطقة ينبع التاريخية&nbsp;هي منطقة يقدر عمرها بحوالي 2500 عام شهدت أحداث تاريخية ومن أهمها أحداث حرب&nbsp;بريطانيا&nbsp;ضد الاتراك وغزوة العشير التي بدأت في عهد الرسول صلى الله عليه وسلم، سكن في مدينة&nbsp;ينبع&nbsp;العديد من الشخصيات الهامة ومن اهمهم&nbsp;لورانس العرب و عبد&nbsp;الله بن الحسن بن الحسن بن علي بن أبي طالب و الصحابي أبو عبد&nbsp;الله حرملة المدلجي رضي الله عنه، حاليا أصبحت منطقة ينبع التاريخية كمتحف تراثي يأتي له العديد من السياح من كل مكان للنظر إلى التاريخ العريق لمدينة ينبع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652182-44446381.jpg?v=1638656870"]','https://cmsphoto.ww-cdn.com/resizeapi/adbe6ca7f7aa47c58b50685d539e5f163ef9fea4/480/',24.0795088,38.0607777,'4173 Al Sur Yanbu Al Bahr','','','','https://www.saudi-guide.com/yanbu/i/59652182/night-market-almntk-altarykhy-sok-allyl',1,0,'منطقه تاريخيه سوق ليل night market تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652179,'yanbu','عين الجابرية ينبع النخل','Al Jabriyah Water Spring','al-jabriyah-water-spring-aayn-algabry-ynbaa-alnkhl','["أماكن سياحية"]','["sights"]','عين الجابرية في ينبع النخل بمحافظة ينبع، من عيون الماء الطبيعية في قرى ينبع النخل، ومقصد لمحبي الطبيعة والمزارع والأجواء الريفية الهادئة.','<div class="texte" > <p>عين الجابرية من عيون الماء الطبيعية في قرى ينبع النخل بمحافظة ينبع التابعة لمنطقة المدينة المنورة، وتقع بالقرب من قرية الجابرية وسوقها التراثي، وتُعد مقصدًا لمحبي الطبيعة والمزارع والأجواء الريفية الهادئة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652179-44383649.jpg?v=1638243390"]','https://cmsphoto.ww-cdn.com/resizeapi/a52038ce10055f11b6d6876860cb90ed5df716b7/480/',24.3227377,38.4164415,'8CF8+3HW Yanbu Al Nakhal Yanbu Al Bahr','','','','https://www.saudi-guide.com/yanbu/i/59652179/al-jabriyah-water-spring-aayn-algabry-ynbaa-alnkhl',1,0,'عين جابريه ينبع نخل al jabriyah water spring اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652176,'yanbu','عين عجلان ينبع النخل','Ain Ajlan Spring','aayn-aaglan-ynbaa-alnkhl','["أماكن سياحية"]','["sights"]','عين عجلان في ينبع النخل، عين ماء وقرية قرب قرية السكوبية، جفّت نحو 30 سنة قبل أن تعود إلى الجريان مجددًا عام 1437هـ.','<div class="texte" > <p>عين عجلان هي&nbsp;عين ماء&nbsp;وقرية&nbsp;من قرى&nbsp;ينبع النخل&nbsp;في&nbsp;محافظة ينبع&nbsp;والتابعة&nbsp;لمنطقة المدينة المنورة&nbsp;في&nbsp;السعودية، وبالقرب منها تقع قرية&nbsp;السكوبية التي يسكنها عدد من&nbsp;قبائل جهينة، وقد جفت العين سابقاً ولمدة 30 سنة قبل أن تعود إلى الحياة مجدداً في عام 1437 هجري.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652176-44172123.jpg?v=1637144482"]','https://cmsphoto.ww-cdn.com/resizeapi/80d8e7c17272d1ed3e0b47c918c7dc66c5c8bea1/480/',24.3180293,38.4182065,'عين عجلان ينبع النخل ينبع البحر','','','','https://www.saudi-guide.com/yanbu/i/59652176/aayn-aaglan-ynbaa-alnkhl',1,0,'عين عجلان ينبع نخل ain ajlan spring اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652174,'yanbu','حديقة الأمير سعود بن ثنيان','Prince Saud bin Thunayan Park','hdyk-alamyr-saaod-bn-thnyan','["أماكن سياحية"]','["sights"]','منتزه الأمير سعود بن ثنيان الرياضي في ينبع، يضم مناطق ألعاب للأطفال والكبار ومسارات مخصصة للمشي ومطاعم متنوعة لخدمة الزوار.','<div class="texte" > <p>يوفر منتزه الأمير سعود بن ثنيان الرياضي العديد من الأنشطة الرياضية والترفيهية حيث يوجد به مناطق ألعاب مخصصة للأطفال وأخرى للكبار بالإضافة إلى المسارات المخصصة للمشي كما يوفر المنتزه عدد من المطاعم المتنوعة لتوفير الوجبات للزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652174-44383651.jpg?v=1638243416"]','https://cmsphoto.ww-cdn.com/resizeapi/772b40310ee5987bc29cff1525c7216092e3e7fc/480/',24.0227733,38.2184335,'Yanbu Al Bahr Al-Semairi Yanbu Al Bahr','','','','https://www.saudi-guide.com/yanbu/i/59652174/hdyk-alamyr-saaod-bn-thnyan',1,0,'حديقه امير سعود بن ثنيان prince saud bin thunayan park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652150,'yanbu','حديقة أشجار النيم الرياضية','Neem Trees Sports Park','hdyk-ashgar-alnym-alryad','["أماكن سياحية"]','["sights"]','حديقة أشجار النيم الرياضية في ينبع، تتميز بمسارات مجهزة لرياضة المشي وركوب الدراجات الهوائية، وتضم مناطق ألعاب للأطفال وجلسات للعائلات.','<div class="texte" > <p>حديقة تتميز بمساراتها المجهزة لممارسة رياضة المشي وركوب الدراجات الهوائية كما توفر الحديقة مناطق ألعاب للأطفال وجلسات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652150-44169580.jpg?v=1637136468"]','https://cmsphoto.ww-cdn.com/resizeapi/5bf89284e9672298a677b92c1cd51635357b46f7/480/',24.0423244,38.1794627,'Yanbu Al Bahr Al-Meshaireef Yanbu Al Bahr','','','','https://www.saudi-guide.com/yanbu/i/59652150/hdyk-ashgar-alnym-alryad',1,0,'حديقه اشجار نيم رياضيه neem trees sports park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652148,'yanbu','جزيرة المحار','Oyster Island','oyster-island-gzyr-almhar','["أماكن سياحية"]','["sights"]','جزيرة المحار في ينبع، وجهة بحرية مجهزة بجلسات مظللة ومناطق للشواء وشاطئ آمن للسباحة، مع إمكانية استئجار قارب لجولة بحرية مميزة.','<div class="texte" > <p>تتميز جزيرة المحار بينبع بكونها مجهزة بكل ما يحتاجه السياح للاستمتاع بالتجربة حيث أنها توفر جلسات مظللة ومناطق للشواء كما أن الشاطئ يُعد آمن للسباحة، ويمكن للسائح استئجار قارب وأخذ جولة بحرية مميزة أو الاكتفاء بالتأمل بجمال البحر البديع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652148-44383655.jpg?v=1638243443"]','https://cmsphoto.ww-cdn.com/resizeapi/f23188672affb0466c11f42786efbc65ae860f29/480/',23.9896424,38.1886582,'Oyster Island Yanbu Al Madinah Province','','','','https://www.saudi-guide.com/yanbu/i/59652148/oyster-island-gzyr-almhar',1,0,'جزيره محار oyster island اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652147,'yanbu','بحيرة ينبع الصناعية (حديقة الطيور)','Yanbu Lake Park','yanbu-lake-park-bhyr-ynbaa-alsnaaay-hdyk-altyor','["أماكن سياحية"]','["sights"]','بحيرة ينبع الصناعية أو حديقة الطيور، حدائق استوائية تحيط ببحيرة اصطناعية تلجأ إليها أسراب الطيور المهاجرة، مع مساحات لعب ومقهى للزوار.','<div class="texte" > <p>حدائق استوائية تحيط ببحيرة اصطناعية، مع مساحات لعب ومقهى للزوّار كما تلجأ إليها أسراب الطيور المهاجرة</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652147-44171925.jpg?v=1637143706"]','https://cmsphoto.ww-cdn.com/resizeapi/7a1401059426778f5f5a723628be35b7990f125e/480/',24.0082254,38.231207,'الميناء An Nawah Yanbu Al Bahr','','','','https://www.saudi-guide.com/yanbu/i/59652147/yanbu-lake-park-bhyr-ynbaa-alsnaaay-hdyk-altyor',1,0,'بحيره ينبع صناعيه (حديقه طيور) yanbu lake park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652104,'yanbu','حديقة سابك على البحر','SABIC Seaside Park','hdykh-sabk-aal-albhr','["أماكن سياحية"]','["sights"]','حديقة سابك على البحر في ينبع، حديقة ترفيهية بمسطحات خضراء واسعة وألعاب للأطفال وجلسات مظللة ومرافق خدمية متكاملة للزوار.','<div class="texte" > <p>حديقة سابك من حدائق ينبع التي تقع على البحر. وهي حديقة ترفيهية تتمتع بمساحات واسعة من المسطحات الخضراء والعديد من الألعاب المخصصة للأطفال بالإضافة إلى الجلسات المظللة، كذلك توفر الحديقة مرافق خدمية لتوفير&nbsp;ما&nbsp;يحتاجه الزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652104-44171935.jpg?v=1637143745"]','https://cmsphoto.ww-cdn.com/resizeapi/17b1186f83685effc9aee6cd397c6c7dd7d08142/480/',24.083743,38.019609,'Yanbu Al Bahr Al Shati Yanbu Al Bahr','','','','https://www.saudi-guide.com/yanbu/i/59652104/hdykh-sabk-aal-albhr',1,0,'حديقه سابك علي بحر sabic seaside park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652101,'yanbu','الكورنيش الشمالي','North Corniche','alkornysh-alshmaly','["أماكن سياحية"]','["sights"]','الكورنيش الشمالي في ينبع، إطلالة بحرية مميزة للاستمتاع بمشهد الغروب الساحر، مع أنشطة رياضية وترفيهية متنوعة مثل السباحة والمشي.','<div class="texte" > <p>تتيح&nbsp;الإطلالة البحرية التي يوفرها الكورنيش الشمالي بينبع فرصة الاستمتاع بمشهد الغروب الساحر بالإضافة إلى عدد من الأنشطة الرياضية والترفيهية مثل السباحة وغيرها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652101-44383661.jpg?v=1638243469"]','https://cmsphoto.ww-cdn.com/resizeapi/fd54ec9586906cfcb46c3a4b635d56caf3cecf2d/480/',24.0972922,38.0058091,'32W4+W87 Al Shati Yanbu','','','','https://www.saudi-guide.com/yanbu/i/59652101/alkornysh-alshmaly',1,0,'كورنيش شمالي north corniche اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652099,'yanbu','شاطئ العيقة للسباحة','SHATI Alaiqh Yanbu','shati-alaiqh-yanbu-shaty-alaayk-llsbah','["أماكن سياحية"]','["sights"]','شاطئ العيقة في ينبع، شاطئ بمياه كريستالية نظيفة وأجواء مثالية، يضم مناطق مخصصة للسباحة وركوب الخيل وإمكانية استئجار الدراجات الرباعية.','<div class="texte" > <p>يتميز شاطئ العيقة بمياهه الكريستالية النظيفة وأجواءه المثالية لقضاء أوقات ممتعة حيث يوجد مناطق مخصصة للسباحة وركوب الخيل كما يمكنك استئجار الدراجات النارية ذات الدفع الرباعي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652099-44383664.jpg?v=1638243491"]','https://cmsphoto.ww-cdn.com/resizeapi/5fd499a80e01848c921f27ba174452014c963296/480/',24.1548418,37.9557061,'5X34+W7P Yanbu SA','','','','https://www.saudi-guide.com/yanbu/i/59652099/shati-alaiqh-yanbu-shaty-alaayk-llsbah',1,0,'شاطئ عيقه للسباحه shati alaiqh yanbu اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59652048,'yanbu','الواجهة البحرية','Waterfront Industrial Yanbu','waterfront-industrial-yanbu-aloagh-albhry','["أماكن سياحية"]','["sights"]','الواجهة البحرية في ينبع الصناعية، أبرز معالم المحافظة السياحية بمسطحاتها الخضراء الواسعة وشاطئها الرملي النظيف ومرافقها الترفيهية والرياضية.','<div class="texte" > <p>تعد الواجهة البحرية المعلم السياحي الأبرز في محافظة ينبع بما تحتويه من مسطحات خضراء واسعة وشاطئ رملي نظيف ومرافق ترفيهية&nbsp;ورياضية بالإضافة إلى أنواع الخدمات المقدمة للزوار والتي تفي بكل احتياجاتهم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59652048-44171831.jpg?v=1637143854"]','https://cmsphoto.ww-cdn.com/resizeapi/aa3094f6a098b61a78640db479060b224c08a039/480/',24.0247271,38.1415828,'Waterfront Industrial Yanbu Al-Jaar Yanbu','','','','https://www.saudi-guide.com/yanbu/i/59652048/waterfront-industrial-yanbu-aloagh-albhry',1,0,'واجهه بحريه waterfront industrial yanbu اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59651987,'yanbu','جزيرة النورس','Al Nawras Island','gzyr-alnors','["أماكن سياحية"]','["sights"]','جزيرة النورس في الواجهة البحرية بينبع الصناعية، معلم بطابع عمراني وبيئي مميز على مساحة 23 هكتارًا، تضم متنزهات خضراء وشواطئ رملية ومناطق ترفيهية.','<div class="texte" > <p>تعد جزيرة النورس بالواجهة البحرية بمدينة&nbsp;ينبع الصناعية&nbsp;رافداً اقتصادياً مهماً ومعلماً مميزاً بطابع عمراني وبيئي يضاهي أجمل المناطق العالمية بجمالها وروعة تخطيطها الشاملة بكل المقاييس للمراحل التطورية لمشروع الواجهة البحرية، حيث تضم المراحل الإنشائية للجزيرة مرافق استثمارية متنوعة ومتنزهات خضراء وشواطئ رملية ومناطق تخييم ومنتجعات ومناطق ترفيهية ومطاعم.</p> <p>وتقع جزيرة النورس بمنطقة الواجهة البحرية بمدينة&nbsp;ينبع الصناعية&nbsp;وتبلغ مساحتها 23 هكتاراً وتتضمن مشاريع الجزيرة بعد انتهاء العمل بها على فندق سياحي ونادي ومدرسة للغوص ومحطة للتنقل المائي وألعاب مائية ومتحف بحري ورصيف زوارق ومواقف للسيارات وشاطئ ومتنزه عام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59651987-44171965.jpg?v=1637143865"]','https://cmsphoto.ww-cdn.com/resizeapi/6e0570ffdde7b60a2a4b37cb1f4fb9a9b95d7682/480/',24.0045024,38.1521595,'Yanbu Al-Jaar Yanbu Al Bahr','','','','https://www.saudi-guide.com/yanbu/i/59651987/gzyr-alnors',1,0,'جزيره نورس al nawras island اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480938,'jizan','بيت الجرمل بفرسان','','byt-algrml-bfrsan','["التراث والثقافة"]','["heritage"]','بيت الجرمل مبنى أثري على ساحل جزيرة قماح بجزر فرسان، شيّده الألمان مستودعًا لتخزين الفحم الحجري وقودًا للبواخر العابرة في البحر الأحمر.','<div class="texte" > <p>بيت الجرمل&nbsp;(تحريف لمسمى بيت الجيرمانgerman) هو مبنى أثري يقع على ساحل&nbsp;جزيرة قماح&nbsp;التابعة&nbsp;لجزر<a href="https://ar.wikipedia.org/wiki/%D8%AC%D8%B2%D8%B1_%D9%81%D8%B1%D8%B3%D8%A7%D9%86" title="جزر فرسان"> </a>فرسان&nbsp;في&nbsp;منطقة جازان&nbsp;جنوب&nbsp;المملكة العربية السعودية، وتعود قصة البيت إلى أن&nbsp;الألمان&nbsp;قاموا ببناء مستودع كبير لهم في جزيرة قماح لاستخدامه في تخزين&nbsp;الفحم الحجري&nbsp;المستخدم وقودا للبواخر العابرة إلى&nbsp;البحر الأحمر&nbsp;بين&nbsp;قناة السويس&nbsp;في الشمال الغربي للبحر الأحمر&nbsp;وباب المندب&nbsp;في الجنوب الشرقي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480938-43700883.jpg?v=1633983513"]','https://cmsphoto.ww-cdn.com/resizeapi/fbfa38b6aedd73ae1904c5bc003e2824df9e6a33/480/',16.6550154,42.0313962,'SA Jazan 88287','','','','https://www.saudi-guide.com/jizan/i/59480938/byt-algrml-bfrsan',1,0,'بيت جرمل بفرسان تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480886,'jizan','قرية القصار التراثية بفرسان','Heritage Village','heritage-village-kry-alksar-altarthy-bfrsan','["التراث والثقافة"]','["heritage"]','قرية القصار التراثية في جزيرة فرسان قرية قديمة تضم منازل مبنية من الحجارة وجريد النخل، ويعود تاريخها إلى العهد الروماني وفق المؤرخين.','<div class="texte" > <p>قرية القصار التراثية وتعرف اختصاراً باسم القصار هي قرية قديمة تقع في جزيرة فرسان التابعة لمنطقة جازان الواقعة جنوب غرب السعودية. تضم القرية حوالي 400 منزل مبنية من الحجارة وجريد النخل، ويعود تاريخها وفقاً للمؤرِّخين إلى العهد الروماني، كما تضم كتابات ورسومات تعود بعضها إلى العهد الحميري.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480886-44653015.jpg?v=1640264591"]','https://cmsphoto.ww-cdn.com/resizeapi/6a05a8f60e07b3fd021175465363d479e75e06a6/480/',16.6703799,42.1484417,'M4CX+594 Al Qessar Jazan','','','','https://www.saudi-guide.com/jizan/i/59480886/heritage-village-kry-alksar-altarthy-bfrsan',1,0,'قريه قصار تراثيه بفرسان heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480883,'jizan','مسجد النجدي التاريخي بفرسان','Najdi historic mosque','najdi-historic-mosque-msgd-alngdy-altarykhy-bfrsan','["التراث والثقافة"]','["heritage"]','مسجد النجدي من أبرز المواقع الأثرية في جزيرة فرسان، شيّده تاجر اللؤلؤ إبراهيم التميمي، ويتميز بنقوش وزخارف إسلامية تشبه زخارف قصر الحمراء.','<div class="texte" > <p>مسجد النجدي هو أحد المساجد القديمة الواقعة في جزيرة فرسان التابعة لمنطقة جازان غرب السعودية. ويعتبر المسجد أحد المواقع الأثرية والبارزة في الجزيرة. وقد شيده تاجر اللؤلؤ إبراهيم التميمي في عام 1347 هـ، وأهم ما يميز هذا المسجد هي النقوش والزخارف الإسلامية والتي تشبه إلى حد كبير تلك الموجودة في مسجد قصر الحمراء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480883-44653022.jpg?v=1640264609"]','https://cmsphoto.ww-cdn.com/resizeapi/7e229a10a9d4c79eaa2c3acbf2a07dbce6a0791f/480/',16.7029459,42.1164684,'P438+5HG Farasan Island Jazan','','','','https://www.saudi-guide.com/jizan/i/59480883/najdi-historic-mosque-msgd-alngdy-altarykhy-bfrsan',1,0,'مسجد نجدي تاريخي بفرسان najdi historic mosque تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480880,'jizan','متحف الزيلعي البحري بفرسان','Zayla''i Maritime Museum','zayla-i-maritime-museum-mthf-alzylaay-albhry-bfrsan','["التراث والثقافة"]','["heritage"]','متحف الزيلعي البحري في جزيرة فرسان يعرض مجموعة من القواقع والأسماك والسلاحف المحنطة وآثارًا بحرية تعكس بيئة البحر الأحمر.','<div class="texte" > <p>متحف بحري من القواقع والاسماك المحنطة والسلاحف وآثار البحرية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480880-44653033.jpg?v=1640264669"]','https://cmsphoto.ww-cdn.com/resizeapi/07e76bb2115f7284f4cc35b94a3dd82e4d770481/480/',16.7029254,42.1214694,'Farasan Island Jazan SA','','','','https://www.saudi-guide.com/jizan/i/59480880/zayla-i-maritime-museum-mthf-alzylaay-albhry-bfrsan',1,0,'متحف زيلعي بحري بفرسان zayla''i maritime museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480833,'jizan','بيت الرفاعي بجزيرة فرسان','House of Riffai''','house-riffai-byt-alrfaaay-bgzyr-frsan','["التراث والثقافة"]','["heritage"]','بيت الرفاعي من المواقع الأثرية بجزيرة فرسان، بناه تاجر اللؤلؤ أحمد الرفاعي، ويتميز بجمال تصميمه ونقوشه التي تعكس ازدهار تجارة اللؤلؤ قديمًا.','<div class="texte" > <p>بيت الرفاعي أو منزل الرفاعي هو أحد المواقع الأثرية بجزيرة فرسان التابعة لمنطقة جازان جنوب غرب السعودية، وشيد سنة 1341هـ. بنى المنزل تاجر اللؤلؤ أحمد المنور الرفاعي الذي كان أحد أهم و أكبر تجار الجزيرة قديماً، ويتميز المنزل بجمال تصميمه ونقوشه ويعد تحفة حقيقية في مجال الفن المعماري القديم حيث يعكس الثراء والترف بفرسان أيام ازدهار تجارة اللؤلؤ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480833-44653037.jpg?v=1640264691"]','https://cmsphoto.ww-cdn.com/resizeapi/db6613fa32de1ebbfd6bfd3d8b493d657987699f/480/',16.7051264,42.1223391,'Farasan Island Jazan SA','','','','https://www.saudi-guide.com/jizan/i/59480833/house-riffai-byt-alrfaaay-bgzyr-frsan',1,0,'بيت رفاعي بجزيره فرسان house of riffai'' تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480782,'jizan','مرسى الحسين بجزيرة فرسان','','mrs-alhsyn-bgzyr-frsan','["أماكن سياحية"]','["sights"]','مرسى الحسين في جزيرة فرسان يتميز بجمال شاطئه وصفاء مياهه، ويتيح للزوار صعود الجبل للاستمتاع بالمنظر والقيام بجولات بحرية ومشاهدة الغروب.','<div class="texte" > <p>الحسيّن هي قرية تابعة لجزيرة فرسان تتميز بجمال شاطئها وصفاوة مياهها، يمكنك الصعود لقمة الجبل هناك والاستمتاع بالمنظر أو استئجار أحد القوارب لأخذك في جولة بحرية مميزة أو الاكتفاء بالاستمتاع بمشهد الغروب الساحر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480782-44653041.jpg?v=1640264713"]','https://cmsphoto.ww-cdn.com/resizeapi/57a6be4141d9906bdc2e3b1b4c3df55f2a8e82ed/480/',16.7158073,41.9073912,'PW84+8XC جازان جازان','','','','https://www.saudi-guide.com/jizan/i/59480782/mrs-alhsyn-bgzyr-frsan',1,0,'مرسي حسين بجزيره فرسان اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480751,'jizan','مرسى الغدير بجزيرة فرسان','','mrs-alghdyr-bgzyr-frsan','["أماكن سياحية"]','["sights"]','مرسى الغدير في جزيرة فرسان مرسى صغير لمحبي القوارب والصيد، يتميز بكثرة أشجار المانجروف التي تشكل غابة وسط البحر.','<div class="texte" > <p>مرسى صغير وبسيط لمحبي القوارب والصيد خصوصاً، يتميز بكثرة أشجار المنقروف فيه والتي تشكل غابة في وسط البحر مما يزيد المنظر جماليةً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480751-44653048.jpg?v=1640264777"]','https://cmsphoto.ww-cdn.com/resizeapi/81da2cdc453e18aeed7d4d43e7c3f85a9aafa098/480/',16.682353,42.1082468,'M4J5+W7X جازان جازان','','','','https://www.saudi-guide.com/jizan/i/59480751/mrs-alghdyr-bgzyr-frsan',1,0,'مرسي غدير بجزيره فرسان اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480750,'jizan','شاطئ الحصيص بجزيرة فرسان','Beach Alhsas','beach-alhsas-shaty-alhsys-bgzyr-frsan','["أماكن سياحية"]','["sights"]','شاطئ الحصيص في جزيرة فرسان من أجمل شواطئ منطقة جازان، يضم كورنيشًا وجلسات مظللة للعائلات ويتيح للزوار الاستمتاع بالطبيعة الساحلية.','<div class="texte" > <p>يعد شاطئ الحصيص أجمل شواطئ منطقة جازان في نظر الكثيرين بما يوفره من طبيعة خلابة ومرافق عديدة تمنح الزوار مساحة كبيرة من الاستمتاع، يوجد في الشاطئ كورنيش مميز وجلسات مظللة للعوائل كما يمكن للزوار إقامة حفلات الشواء والمبيت في الشاطئ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480750-44657991.jpg?v=1640316237"]','https://cmsphoto.ww-cdn.com/resizeapi/79e6fcf7bae2651b1f77f2a5b77b889c64e4da16/480/',16.7486655,42.0737851,'Beach Alhsas Jazan SA','','','','https://www.saudi-guide.com/jizan/i/59480750/beach-alhsas-shaty-alhsys-bgzyr-frsan',1,0,'شاطئ حصيص بجزيره فرسان beach alhsas اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480703,'jizan','Qandal Forest غابة القندل جزيرة فرسان','','qandal-forest-ghab-alkndl-gzyr-frsan','["أماكن سياحية"]','["sights"]','غابة القندل شمال جزيرة فرسان موقع طبيعي خلاب وسط أشجار المانجروف والقندل تتخللها ممرات مائية، ويُنصح بزيارتها برفقة مرشد خبير بالطريق.','<div class="texte" > <p>تقع القندل&nbsp;في شمال جزيرة فرسان، والطريق إليها وعر قليلاً ويحتاج إلى مرشد خبير بالطريق، وهي تتميز بمواقع ذات طبيعة خلابة حيث تقع وسط غابة من أشجار المنغروف&nbsp;وأشجار القندل التي تتخللها الممرات المائية فتعطي تلك المنطقة المزيد من السحر والجمال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480703-44653046.jpg?v=1640264730"]','https://cmsphoto.ww-cdn.com/resizeapi/91b21689b36a2596242cb09c4749b1ae8309874e/480/',16.789085,42.0984238,'Q3QX+J9M جازان جازان','','','','https://www.saudi-guide.com/jizan/i/59480703/qandal-forest-ghab-alkndl-gzyr-frsan',1,0,'qandal forest غابه قندل جزيره فرسان اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480615,'jizan','منتزة الدفرة - فيفاء','Al Dhafra Park - Vivae','al-dhafra-park-vivae-mntz-aldfr-fyfaaa','["أماكن سياحية"]','["sights"]','منتزه الدفرة من أهم عوامل الجذب السياحي في فيفاء، يتميز بأجوائه المعتدلة صيفًا وإطلالته الجذابة، ويضم جلسات مظللة ووسائل ترفيهية.','<div class="texte" > <p>يعد منتزه الدفرة أحد أهم عوامل الجذب السياحي في محافظة فيفا خصوصاً في فصل الصيف حيث تكون الأجواء فيه معتدلة وغير حارة، يتميز المنتزه بإطلالته الجذابة ومرافقه الخدمية بالإضافة إلى الوسائل الترفيهية والجلسات المظللة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480615-44657990.jpg?v=1640316203"]','https://cmsphoto.ww-cdn.com/resizeapi/64f8fed02f82af3136dcee79dc0c7c921adf408b/480/',17.243409,43.1078206,'SA فيفاء فيفا','','','','https://www.saudi-guide.com/jizan/i/59480615/al-dhafra-park-vivae-mntz-aldfr-fyfaaa',1,0,'منتزه دفره فيفاء al dhafra park vivae اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480428,'jizan','قرية القرانعة الأثرية بالدائر','','kry-alkranaa-alathry-baldayr','["التراث والثقافة"]','["heritage"]','قرية القرانعة الأثرية في محافظة الداير بني مالك، من القرى الجبلية التاريخية التي تضم مباني وحصونًا حجرية بطراز معماري تقليدي وسط المدرجات الخضراء.','<div class="texte" > <p><strong>قرية القرانعة الأثرية</strong> واحدة من القرى التراثية المنتشرة في جبال محافظة الداير بني مالك، وتحتفظ بملامح البناء الحجري القديم الذي يميز قرى المنطقة، وتشكّل مع ما حولها من قرى وحصون جزءاً من الإرث التاريخي للمحافظة.</p> </div>  <div class="texte" > <p>تقع محافظة الداير بني مالك، شرق منطقة جازان بجنوب السعودية، وتتميز بالمرتفعات الشاهقة والمدرجات الخضراء والقلاع الأثرية المتناثرة أعالي القمم والمرتفعات التي تعانق الضباب، في صورة جمالية تسطر الماضي العريق لتلك القرى والمباني من طراز معماري وفن هندسي رائع، تقرأ في ملامحها الشوق والحنين للماضي، بعد أن طغت الحضارة على البشر، وتلتمس فيها قوة وبراعة التصميم.<br /> فلا يوجد وادٍ أو جبل إلا ويحوي عدداً من القرى والحصون الحجرية؛ ولهذا تحوي محافظة الداير بني مالك أكبر تجمع للحصون الحجرية في العالم؛ وذلك دليل على قِدَم الاستيطان البشري والكثافة السكانية، والتقدم الكبير في المجال العمراني والزراعي في تلك العصور.<br /> <br /> ومن دلائل قِدَم الحصون الأثرية في الداير وجبالها، عدمُ وجود المساجد والجوامع ودور العبادة في تصاميمها الأساسية؛ مما يعني أنها سابقة على عصر الإسلام، وكذلك وجود بعض التصاوير والرنوك تنتمي للعصر الحميري الأول والثاني؛ أيضاً ورودها في الأخبار القديمة، وتصل إلى الألف الأول قبل الميلاد في بعض النقوش الثمودية، واللحيانية والسبئية، ولها حضور فيما بعد الميلاد في حملة الرومان على جنوبي الجزيرة العربية وأخبار الملك الحميري "شمر يهرعش"؛ أما في العصور الإسلامية فأخبارها متعددة ومتناثرة خلال أحداث الدولة الزيدية والرسولية، والدول التي قامت في تهامة وصولاً إلى التاريخ المعاصر وأحداث الدولة الإدريسية والعهد السعودي الزاهر.<br /> <br /> وتتكون القلاع الأثرية والحصون التاريخية في الداير من الشكلين (الدائري والمربع)، ويقعان جنباً إلى جنب في أغلب القلاع والحصون؛ حيث تحوي محافظة الداير إرثاً تاريخياً زاخراً، يمتد عبر مئات السنين، تشكلت فيه مجموعة من الحضارات المتعاقبة الحافلة بالأحداث التاريخية المتعددة، يشهد على ذلك الكم الكبير من المواقع الأثرية المختلفة والمنتشرة في أماكن متعددة والنقوش التي عليها، وتعد أرضاً خصبة للدراسة التاريخية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480428-44657987.jpg?v=1640316158"]','https://cmsphoto.ww-cdn.com/resizeapi/08f107e37c307921e37df1abc6eebc0a6f24c54e/480/',17.3616423,43.1781379,'Addayer Al Dayer Jazan','','','','https://www.saudi-guide.com/jizan/i/59480428/kry-alkranaa-alathry-baldayr',1,0,'قريه قرانعه اثريه بالدائر تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480424,'jizan','قرية مثرارة التاريخيه بالدائر','','kry-mthrar-altarykhyh-baldayr','["التراث والثقافة"]','["heritage"]','قرية مثرارة التاريخية في محافظة الداير بني مالك شرق جازان، تعكس براعة العمارة الحجرية الجبلية القديمة وسط مرتفعات شاهقة تعانق الضباب.','<div class="texte" > <p><strong>قرية مثرارة التاريخية</strong> من القرى الجبلية الأثرية في محافظة الداير بني مالك، وتمثل نموذجاً للعمارة الحجرية التقليدية التي تشتهر بها جبال المحافظة، حيث بُنيت بيوتها من الحجر على السفوح المطلة على المدرجات الزراعية.</p> </div>  <div class="texte" > <p><span>تقع محافظة الداير بني مالك، شرق منطقة جازان بجنوب السعودية، وتتميز بالمرتفعات الشاهقة والمدرجات الخضراء والقلاع الأثرية المتناثرة أعالي القمم والمرتفعات التي تعانق الضباب، في صورة جمالية تسطر الماضي العريق لتلك القرى والمباني من طراز معماري وفن هندسي رائع، تقرأ في ملامحها الشوق والحنين للماضي، بعد أن طغت الحضارة على البشر، وتلتمس فيها قوة وبراعة التصميم.</span><br /> <span>فلا يوجد وادٍ أو جبل إلا ويحوي عدداً من القرى والحصون الحجرية؛ ولهذا تحوي محافظة الداير بني مالك أكبر تجمع للحصون الحجرية في العالم؛ وذلك دليل على قِدَم الاستيطان البشري والكثافة السكانية، والتقدم الكبير في المجال العمراني والزراعي في تلك العصور.</span><br /> <br /> <span>ومن دلائل قِدَم الحصون الأثرية في الداير وجبالها، عدمُ وجود المساجد والجوامع ودور العبادة في تصاميمها الأساسية؛ مما يعني أنها سابقة على عصر الإسلام، وكذلك وجود بعض التصاوير والرنوك تنتمي للعصر الحميري الأول والثاني؛ أيضاً ورودها في الأخبار القديمة، وتصل إلى الألف الأول قبل الميلاد في بعض النقوش الثمودية، واللحيانية والسبئية، ولها حضور فيما بعد الميلاد في حملة الرومان على جنوبي الجزيرة العربية وأخبار الملك الحميري "شمر يهرعش"؛ أما في العصور الإسلامية فأخبارها متعددة ومتناثرة خلال أحداث الدولة الزيدية والرسولية، والدول التي قامت في تهامة وصولاً إلى التاريخ المعاصر وأحداث الدولة الإدريسية والعهد السعودي الزاهر.</span><br /> <br /> <span>وتتكون القلاع الأثرية والحصون التاريخية في الداير من الشكلين (الدائري والمربع)، ويقعان جنباً إلى جنب في أغلب القلاع والحصون؛ حيث تحوي محافظة الداير إرثاً تاريخياً زاخراً، يمتد عبر مئات السنين، تشكلت فيه مجموعة من الحضارات المتعاقبة الحافلة بالأحداث التاريخية المتعددة، يشهد على ذلك الكم الكبير من المواقع الأثرية المختلفة والمنتشرة في أماكن متعددة والنقوش التي عليها، وتعد أرضاً خصبة للدراسة التاريخية.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480424-44657988.jpg?v=1640316172"]','https://cmsphoto.ww-cdn.com/resizeapi/1f50c3b88a7e0b0510c78166eb30afed74315ae5/480/',17.3614192,43.1863077,'956P+HG7 Habbes Al Dayer','','','','https://www.saudi-guide.com/jizan/i/59480424/kry-mthrar-altarykhyh-baldayr',1,0,'قريه مثراره تاريخيه بالدائر تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480405,'jizan','متحف منطقة جازان','Jizan Museum','jizan-museum-mthf-mntk-gazan','["التراث والثقافة"]','["heritage"]','متحف آثار جازان في مدينة صبيا بجوار موقع الأدارسة الأثري، يعرض خرائط المواقع الأثرية وأدوات العصر الحجري والفخار والعملات القديمة ومواد التراث الشعبي.','<div class="texte" > <p>متحف آثار جازان، هو متحف بمدينة صبيا الواقعة بمنطقة جازان، يقع بجوار موقع الأدارسة الأثري، ويشكل جزءاً من شبكة المتاحف التي أقامتها وكالة الآثار والمتاحف بوزارة المعارف، وتم بناء المتحف عام 1403 هـ الموافق 1983 م، وافتتح المتحف لاستقبال الزوار في 27 محرم 1412 هـ.</p> <p>يحتوي المتحف على لوحات لخرائط توضح المواقع الأثرية بمنطقة جازان وصور فوتوغرافية قديمة وأدوات العصر&nbsp;الحجري الأثرية مثل الفؤوس والمكاشط ورؤوس السهام ونماذج للأواني الفخارية وحلي والعملات القديمة، وكذلك لوحات خاصة بالكتابات والخطوط واللغات القديمة. وهناك لوحات وخزائن عرض خاصة بمواد التراث الشعبي مثل أواني الطهي والملابس والحلي وأدوات الزينة الخاصة بالمرأة والمصنوعات الجلدية ومصنوعات من جريد وسعف النخيل وغيرها، والحرف التي اشتهرت بها منطقة جازان. و يروي المتحف أيضا تاريخ جازان الحديث ودخولها تحت الحكم السعودي على يد الملك عبد العزيز آل سعود، كما يحتوي المتحف على أقسام مساندة منها المختبر والمكتبة، وقاعات للندوات والمحاضرات، وصُمم على أن يكون مركزاً للأبحاث والدراسات الأثرية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480405-44657989.jpg?v=1640316187"]','https://cmsphoto.ww-cdn.com/resizeapi/3cab42c8006def782de52064ff72ab22d822da92/480/',17.1633333,42.6475,'King Abdul Aziz Rd Al Nahdah Sabya','','','','https://www.saudi-guide.com/jizan/i/59480405/jizan-museum-mthf-mntk-gazan',1,0,'متحف منطقه جازان jizan museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480245,'jizan','مطل العارضة','','mtl-alaaard','["أماكن سياحية"]','["sights"]','مطل العارضة يقع على جبل شاهق في محافظة العارضة، ويعد من أبرز المطلات في منطقة جازان بجمال إطلالته، ويضم أماكن للجلوس وألعابًا للأطفال.','<div class="texte" > <p>يقع مطل العارضة في محافظة العارضة ويتميز بوقوعه على جبل شاهق الارتفاع مما يجعله أحد أبرز المطلات في<br /> منطقة جازان، ويتمتع المطل بجمال إطلالته وروعة مناظره، كذلك يوجد في المطل أماكن للجلوس والعديد من<br /> .الألعاب الترفيهية للأطفال</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480245-44664407.jpg?v=1640393419"]','https://cmsphoto.ww-cdn.com/resizeapi/4a53612052a91fd2e3f37a0ea8dcda533606df8c/480/',17.0313252,43.1231269,'1690 Al Aridhah Jazan','','','','https://www.saudi-guide.com/jizan/i/59480245/mtl-alaaard',1,0,'مطل عارضه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480204,'jizan','منتزه قرضة بفيفاء','','mntzh-krd-bfyfaaa','["أماكن سياحية"]','["sights"]','منتزه قرضة في فيفاء منتزه جبلي مرتب يتمتع بإطلالة رائعة، ويوفر جلسات مظللة وألعابًا للأطفال.','<div class="texte" > <p>منتزه جميل ومرتب يمتلك إطلالة رائعة ويوفر جلسات مظللة وألعاب للأطفال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480204-44676978.jpg?v=1640554520"]','https://cmsphoto.ww-cdn.com/resizeapi/89c85f80d148ed3677d5ccfc4db7ff9e8adfe65d/480/',17.2201853,43.1032526,'64C3+38C Fayfa Al Dayer','','','','https://www.saudi-guide.com/jizan/i/59480204/mntzh-krd-bfyfaaa',1,0,'منتزه قرضه بفيفاء اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480087,'jizan','ملعب محمد حربان ( ريع ) الملعب المنحوت بالحشر','','mlaab-mhmd-hrban-ryaa','["أماكن سياحية"]','["sights"]','ملعب محمد حربان في جبال الحشر ببني مالك تحفة رياضية فريدة، إذ نُحت ملعب كرة القدم في الصخر بجهود شخصية وسط الجبال الشاهقة.','<div class="texte" > <p>تشهد جبال الحشر في محافظة الداير بني مالك الواقعة شرق منطقة جازان تحفة رياضية فريدة، صنعها الرجال بعدما حفروا الأرض وطوّعوا الصخر لإنشاء ملعب لكرة القدم. وقد بدأ محمد حربان الحريصي هذا المشروع في عام 2003 بجهود شخصية، ليصبح الملعب المنحوت في الصخر من المعالم اللافتة في جبال الحشر.</p> <div>&nbsp;</div> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/1d-sZSJsw5A?gbyoutube=1d-sZSJsw5A" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe> <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480087-43700573.jpg?v=1633981684"]','https://cmsphoto.ww-cdn.com/resizeapi/1448fc4b43d759d3781a3a1ad0f6261321124386/480/',17.4105028,43.0672984,'C368+6W3 جازان الدائر','','','','https://www.saudi-guide.com/jizan/i/59480087/mlaab-mhmd-hrban-ryaa',1,0,'ملعب محمد حربان ( ريع ) ملعب منحوت بالحشر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480078,'jizan','بحيرة سد وادي قرى','Wadi Qura Dam''s Lake','wadi-qura-dam-s-lake-bhyr-sd-oady-kr','["أماكن سياحية"]','["sights"]','بحيرة سد وادي قرى في محافظة بيش بمنطقة جازان، مسطح مائي وسط طبيعة خلابة يقصده الزوار للاستمتاع بالهدوء والمناظر الطبيعية.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480078-44676977.jpg?v=1640554500"]','https://cmsphoto.ww-cdn.com/resizeapi/c235adaaefdb2ce9cff8321d46c62084006c9cac/480/',17.5135446,42.7305178,'Wadi Qura Dam''s Lake Baish Jazan','','','','https://www.saudi-guide.com/jizan/i/59480078/wadi-qura-dam-s-lake-bhyr-sd-oady-kr',1,0,'بحيره سد وادي قري wadi qura dam''s lake اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480076,'jizan','وادي بيش الفطيحة','','oady-bysh-alftyh','["أماكن سياحية"]','["sights"]','وادي الفطيحة في محافظة بيش بمنطقة جازان يتميز بجريان المياه طوال العام بفضل فائض سد وادي بيش، ما يمنحه خضرة دائمة ومراعي طبيعية واسعة.','<div class="texte" > <p>وادي الفطيحة أحد أودية منطقة جازان جنوب المملكة العربية السعودية، يقع الوادي في محافظة بيش، وبالتحديد شمال شرق محافظة بيش،&nbsp;ويمتاز الوادي بجريان المياه طوال العام، حيث يغذيه فائض سد وادي بيش مما يمنحه الخضرة الدائمة والمساحة الكبيرة في رقعة المراعي الطبيعية التي تستهوي الكثير من الزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480076-44653028.jpg?v=1640264651"]','https://cmsphoto.ww-cdn.com/resizeapi/0922e4a47a742789ef9b6024dbe8848c368661c7/480/',17.5834978,42.6182145,'SA Gazan Jazan','','','','https://www.saudi-guide.com/jizan/i/59480076/oady-bysh-alftyh',1,0,'وادي بيش فطيحه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480072,'jizan','الجبل الاسود بالريث','','algbl-alasod-balryth','["أماكن سياحية"]','["sights"]','الجبل الأسود أو جبل العزيين في محافظة الريث شرق جازان، سُمي بذلك لغطائه النباتي الكثيف الذي يمنحه لونًا داكنًا من بعيد.','<div class="texte" > <p>الجبل الأسود ويسمى جبل العزيين نسبة إلى قبيلة "العزيين" يقع في محافظة الريث شرق منطقة جازان الواقعة جنوب غرب السعودية.</p> <p>ترجح تسمية "الجبل الأسود" بهذا الاسم بسبب غطائه النباتي الكثيف الذي يضفي عليه اللون الأسود لناظره من بعيد، ويأخذ شكل قوس يبدأ من الشمال لينحني نحو الشرق عند أعلى قمة فيه،&nbsp;يحد الجبل من الشمال والشمال الغربي جبل القهر ووادي لجب الواقعة بمحافظة الريث، ومن الجنوب جبال منجد بمحافظة هروب،&nbsp;كما أن في المنطقة الواقعة جنوب الجبل توجد جبال الصهاليل.</p> <p>يبلغ طول الجبل حوالي 1800 م، ويسكنه أكثر من ألفي نسمة ويعمل معظمهم في الزراعة ورعي الماشية، ويتميزون كغيرهم من سكان جبال المنطقة بلباسهم التقليدي الذي يتكون من القميص والإزار بالإضافة إلى وضع بعض من أوراق النباتات العطرية على رؤوسهم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480072-44664406.jpg?v=1640393406"]','https://cmsphoto.ww-cdn.com/resizeapi/15310a2279b9c9bb324e372e92b696dd2e8e89d9/480/',17.6169984,42.8296643,'جبل الاسود، الريث Al Reeth','','','','https://www.saudi-guide.com/jizan/i/59480072/algbl-alasod-balryth',1,0,'جبل اسود بالريث اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480027,'jizan','وادي لجب بالريثWadi Lajb','','oady-lgb-balrythwadi-lajb','["أماكن سياحية"]','["sights"]','وادي لجب صدع في جبل القهر بمحافظة الريث، من أبرز المواقع السياحية في جازان، يشتهر بممراته الضيقة وشلالاته وبحيراته الطبيعية.','<div class="texte" > <p>وادي لجب هو صدع وانكسار في الجزء الشرقي من جبل القهر (زهوان) التابع لمحافظة الريث التي تقع على بعد 150 كيلومتراً إلى الشمال الشرقي من مدينة جيزان. يعتبر من أهم المواقع السياحية وأبرزها ومزاراً يؤمه الزائرون من أبناء المنطقة وغيرها من مناطق المملكة على مدار العام، ويشهد وادي لجب بمحافظة الريث كغيره من المواقع السياحية بمنطقة جازان إقبالاً متزايداً من قوافل الزوار من داخل المنطقة وخارجها.</p> <p>يمكن للزائر أن يستقل سيارته داخل الوادي مسافة 2 كيلو متر تقريباً من المدخل وسط الوادي ليضيق بعدها ممر الوادي، لتصبح مواصلة السير على الأقدام متعة متاحة للزائرين وسط رذاذ المياه المتطاير من الشلالات والبحيرات المتناثرة بامتداد الوادي و أشعة الشمس الذهبية التي لا تزور الوادي غير سويعات قليلة عندما تصل منتصف السماء وتتعامد أشعتها على الأرض،&nbsp;ويزيد المكان متعة وجمال حدائق الوادي المعلقة الواقعة على جانبي الوادي بكثافة من أشجار النخيل على ارتفاعات قد تصل إلى أكثر من 30 متراً تقريباً وسط أشجار معمّرة تشبثت بالحياة تمتدّ جذورها من منتصف حافتي الوادي تقريبا لتصل إلى مجرى المياه في الأسفل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480027-44664404.jpg?v=1640393391"]','https://cmsphoto.ww-cdn.com/resizeapi/d4060b8438af01389f52ce14e25a1fa3b8ccca83/480/',17.6048019,42.9301407,'Wadi lajab جيزان Al Reeth','','','','https://www.saudi-guide.com/jizan/i/59480027/oady-lgb-balrythwadi-lajb',1,0,'وادي لجب بالريثwadi lajb اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59480009,'jizan','منتزه العين الحارة بالعارضة','Al Aridhah Hot Spring Park','mntzh-alaayn-alhar-balaaard','["أماكن سياحية"]','["sights"]','العين الحارة في محافظة العارضة بجازان، ينابيع طبيعية تقارب حرارتها 50 درجة مئوية يقصدها الزوار للاستشفاء، وسط أشجار الدوم ضمن حوض سد وادي جازان.','<div class="texte" > <p>تقع العين الحارة في محافظة العارضة بمنطقة جازان، وهي مجموعة من الينابيع الطبيعية التي تخرج من باطن الأرض بدرجة حرارة مرتفعة تقارب 50 درجة مئوية، ويقصدها الزوار للاستشفاء والاستجمام. وتقع العين ضمن حوض سد وادي جازان وسط غابة من أشجار الدوم، ما يضفي على المكان جمالاً طبيعياً يجمع بين السياحة العلاجية والتنزه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59480009-44664400.jpg?v=1640393360"]','https://cmsphoto.ww-cdn.com/resizeapi/3c98de23036ec6db18ed7d30ed3ab2748af1dbd3/480/',17.0347389,42.9897799,'2XMQ+VWR العين الحارة العارضة','','','','https://www.saudi-guide.com/jizan/i/59480009/mntzh-alaayn-alhar-balaaard',1,0,'منتزه عين حاره بالعارضه al aridhah hot spring park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59479983,'jizan','بحيرة السد بالعارضة','','bhyr-alsd-balaaard','["أماكن سياحية"]','["sights"]','منتزه بحيرة السد بالعارضة في منطقة جازان يتميز بجمال طبيعته وروعة إطلالته، ويعد مقصدًا بارزًا لمحبي الاستمتاع بالطبيعة.','<div class="texte" > <p>يقع منتزه&nbsp;بحيرة السد بالعارضة في محافظة العارضة التابعة لمنطقة جازان، ويتميز المنتزه بجمال طبيعته وروعة إطلالته، وتعد البحيرة مقصداً سياحياً بارزاً لمحبي الاستمتاع بالطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59479983-44676975.jpg?v=1640554480"]','https://cmsphoto.ww-cdn.com/resizeapi/e077b8aa200f9037f94eb19026b2ed546eca7081/480/',17.0294839,42.9866858,'بحيرة السد العارضة جازان','','','','https://www.saudi-guide.com/jizan/i/59479983/bhyr-alsd-balaaard',1,0,'بحيره سد بالعارضه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59479561,'jeddah','مسجد الرحمة','Al Rahma Mosque','al-rahma-mosque-apung','["سياحة وترفيه"]','["sights"]','مسجد الرحمة أول مسجد في العالم يُبنى على سطح البحر مباشرة، ويستقبل أعداداً كبيرة من الحجاج والمعتمرين والزوار، ويُعد من أبرز المعالم المميزة في مدينة جدة.','<div class="texte" > <p>أول مسجد في العالم يبنى على سطح البحر، يستقبل&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%AD%D8%AC%D8%A7%D8%AC_(%D8%AA%D9%88%D8%B6%D9%8A%D8%AD)" title="حجاج (توضيح)">الحجاج</a>&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%B9%D9%85%D8%B1%D8%A9" title="عمرة">والمعتمرين</a>&nbsp;لزيارته ويعتبر من أهم المعالم في جدة، حيث وصل عدد زوار المسجد في عام&nbsp;<a href="https://ar.wikipedia.org/wiki/2009" title="2009">2009</a>&nbsp;إلى 20.000 زائر من&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%AD%D8%AC%D8%A7%D8%AC_(%D8%AA%D9%88%D8%B6%D9%8A%D8%AD)" title="حجاج (توضيح)">الحجاج</a>&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%B9%D9%85%D8%B1%D8%A9" title="عمرة">والمعتمرين</a>&nbsp;من جميع الجنسيات المختلفة.</p> <p>المسجد هو مزيج رائع للعمارة الحديثة والقديمة والفن&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%A5%D8%B3%D9%84%D8%A7%D9%85" title="إسلام">الإسلامي</a>&nbsp;ولقد بني بأحدث التقنيات والمعدات وبأنظمة صوت وإضاءة متطورة. يتكون من 52 قبة خارجية تحيط بالمسجد بالإضافة إلى القبة الرئيسية -الكبيرة- ذات القواعد الثمان التي تقع في المنتصف. وعدد 23 مظلة خارجية. مطرز من الخارج والداخل بآيات قرانية مخطوطة بعدة خطوط مختلفة كالنسخ والرقعة والديواني.</p> <p>تحتوي اطراف القبة الرئيسية على&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%B2%D8%AC%D8%A7%D8%AC_%D9%85%D8%B9%D8%B4%D9%82" title="زجاج معشق">زجاج معشق</a>&nbsp;يسمح بمرور&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%B6%D9%88%D8%A1" title="ضوء">الضوء</a>&nbsp;-اشعة&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%B4%D9%85%D8%B3" title="الشمس">الشمس</a>- داخل المسجد عبر 56 نافذة حول القبة المصممة على الطراز الإسلامي، بالإضافة إلى&nbsp;<a href="https://ar.wikipedia.org/wiki/%D8%B2%D8%AE%D8%B1%D9%81%D8%A9_%D8%B9%D8%B1%D8%A8%D9%8A%D8%A9" title="زخرفة عربية">أرابيسك</a>&nbsp;ونقوش الجدران والنوافذ الإسلامية، ومصلى نسائي خشبي -معلق- مرتفع في المنتصف الأخير من المسجد، يتسع لحوالي 500 مصلية. بالإضافة إلى المرافق الخدمية للمسجد حيث خصصت أماكن للوضوء ودورات المياه وقاعات مريحة للعبادة مجهزة بالكامل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59479561-43700349.jpg?v=1633979531"]','https://cmsphoto.ww-cdn.com/resizeapi/9365c8306348407f4d4951b3754f993602aac416/480/',21.6487534,39.1009249,'2420 6826 Corniche Rd','','https://ar.wikipedia.org/wiki/%D9%85%D8%B3%D8%AC%D8%AF_%D8%A7%D9%84%D8%B1%D8%AD%D9%85%D8%A9_(%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9)','','https://www.saudi-guide.com/jeddah/i/59479561/al-rahma-mosque-apung',1,0,'مسجد رحمه al rahma mosque سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59460430,'asir-region','شاطئ البرك','Beach ponds','beach-ponds','["أماكن سياحية"]','["sights"]','شاطئ البرك أو كما يسمى شاطئ المحاجي يقع شمال محافظة البرك، يتميز بنظافة تربته ويعتبر موقعًا محببًا لمحبي رياضة الغوص حيث توجد به شعب مرجانية.','<div class="texte" > <p>شاطئ البرك، المعروف أيضًا بشاطئ المحاجي، يقع شمال محافظة البرك في منطقة عسير، ويتميز بنظافة تربته الرملية. يُعد الشاطئ موقعًا محببًا لمحبي رياضة الغوص لاحتوائه على شعب مرجانية، كما يجذب هواة صيد الأسماك والباحثين عن أجواء ساحلية هادئة بعيدًا عن الازدحام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59460430-43690031.jpg?v=1633901852"]','https://cmsphoto.ww-cdn.com/resizeapi/e3876b54a60eec0a8632133107e7e7f006a1c36f/480/',18.2501814,41.4978028,'SA البرك منطقة عسير','','','','https://www.saudi-guide.com/asir-region/i/59460430/beach-ponds',1,0,'شاطئ برك beach ponds اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59460405,'asir-region','جزيرة جبل كدمبل','','jabal-kudumbul-island','["أماكن سياحية"]','["sights"]','جزيرة جبل كُدُمبل هي إحدى الجزر الواقعة في البحر الأحمر والتي تتبع مركز القحمة التابع لمنطقة عسير جنوب غرب السعودية، ويتطلب الوصول إليها نحو 30 دقيقة عبر قوارب الصيد. تتميز الجزيرة بوجود الجبل الذي يحتل مساحة كبيرة منها، ويقصدها بعض هواة صيد الأسماك، كما تشتهر بمرور الصقور المهاجرة أعلى الجبل.','<div class="texte" > <p>جزيرة جبل كُدُمبل هي إحدى الجزر الواقعة في البحر الأحمر والتي تتبع مركز القحمة الذي يتبع منطقة عسير جنوب غرب&nbsp;السعودية، يتطلب الوصول إلى الجزيرة&nbsp;30 دقيقة عبر قوارب الصيد، تتميز الجزيرة بوجود الجبل الذي يحتل مساحة كبيرة منها ويعتبر من الأماكن التي يقصدها البعض من هواة صيد الأسماك كما تتميز هذه الجزيرة أيضاً بمرور الصقور المهاجرة أعلى الجبل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59460405-44191180.jpg?v=1637246533"]','https://cmsphoto.ww-cdn.com/resizeapi/9b3e68001d99fbad6b919897c64690d5d990fce4/480/',17.8918461,41.6915609,'جزيرة جبل كدمبل SA ','','','','https://www.saudi-guide.com/asir-region/i/59460405/jabal-kudumbul-island',1,0,'جزيره جبل كدمبل اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59460404,'asir-region','بحيرة سد وادي ذهبان','','wadi-dahban-dam-lake','["أماكن سياحية"]','["sights"]','بحيرة سد وادي ذهبان من المسطحات المائية الطبيعية في منطقة عسير، وتشكل وجهة جميلة لعشاق الطبيعة والمناظر المائية الخلابة.','<div class="texte" > <p>تشكل بحيرة سد وادي ذهبان أحد المسطحات المائية الجميلة في منطقة عسير، حيث تتجمع خلفها مياه الأمطار وسط تضاريس جبلية خضراء تحيط بها من كل جانب. تُعد البحيرة وجهة محببة لعشاق الطبيعة والتصوير، إذ توفر أجواء هادئة بعيدة عن صخب المدن، وتزداد جمالًا في مواسم الأمطار حين ترتفع مناسيب المياه فيها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59460404-44191269.jpg?v=1637246772"]','https://cmsphoto.ww-cdn.com/resizeapi/f406756552a8a6b14495a3d2c8cdba27b54ffee0/480/',18.1383008,41.6454548,'بحيرة سد وادي ذهبان منطقة عسير SA','','','','https://www.saudi-guide.com/asir-region/i/59460404/wadi-dahban-dam-lake',1,0,'بحيره سد وادي ذهبان اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59460401,'asir-region','الواجهة البحرية بالحريضة','','al-hareedah-waterfront','["أماكن سياحية"]','["sights"]','يعتبر مشروع الواجهة البحرية بالحريضة والذي يقع غرب منطقة عسير معلمًا وطنيًا بيئيًا سياحيًا منظمًا وجميلًا بخدمات متكاملة توفر احتياجات جميع الزوار.','<div class="texte" > <p>يعتبر مشروع الواجهة البحرية بالحريضة، الواقع غرب منطقة عسير، معلمًا وطنيًا بيئيًا وسياحيًا منظمًا وجميلًا يوفر خدمات متكاملة تلبي احتياجات جميع الزوار. تمتد الواجهة على طول الساحل موفرة مسارات للمشي وجلسات مطلة على البحر، ما يجعلها وجهة مفضلة للعائلات لقضاء أوقات ترفيهية بعيدًا عن أجواء المدينة الجبلية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59460401-44192041.jpg?v=1637249066"]','https://cmsphoto.ww-cdn.com/resizeapi/1ca689850733b3089aace011ac67f3b4ab18e5a8/480/',17.7420125,41.9518955,'Al Shuqaiq Al Darb Jazan','','','','https://www.saudi-guide.com/asir-region/i/59460401/al-hareedah-waterfront',1,0,'واجهه بحريه بالحريضه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59460398,'asir-region','وادي عمق','Wadi Amaq','wadi-amaq','["أماكن سياحية"]','["sights"]','وادي عمق هو وادي كبير يمتد على طول المنطقة من أعالي جبال الحجاز ويمر بمدينة أبو راكة وينزل إلى عالية نجد، تكثر به النباتات بأنواعها وكذلك العدود القديمة والآبار.','<div class="texte" > <p>وادي عمق هو وادي كبير يمتد على طول المنطقة من أعالي جبال الحجاز ويمر بمدينة أبو راكة وينزل إلى عالية نجد مرورا بمطقة الرقيق إلى أن يصب في أكبر أودية الجزيرة العربية وادي تربة، تكثر به النباتات بأنواعها وكذلك العدود القديمة والآبار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59460398-44192348.jpg?v=1637249930"]','https://cmsphoto.ww-cdn.com/resizeapi/989e1c0e1de917f3bb5cdff2fd16364a8248d85c/480/',18.4773504,41.5362898,'Wadi Amaq Al Birk Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59460398/wadi-amaq',1,0,'وادي عمق wadi amaq اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59460395,'asir-region','متحف محمد بن عضوان الاحمري والقرية التراثية','The Mohammed Bin Adwhan Al Ahmari Museum','the-mohammed-bin-adwhan-al-ahmari-museum','["التراث والثقافة"]','["heritage"]','يقع متحف محمد بن عضوان الاحمري في جنوب المملكة العربية السعودية وتحديدًا في بلحمر، يحتوي المتحف 12 ركن بمقتنيات أثرية تاريخية تتجاوز 3 آلاف قطعة متوزعة على أربعة أدوار تنقل تاريخ ساكني المنطقة قديمًا.','<div class="texte" > <p>يقع متحف محمد بن عضوان الاحمري في جنوب المملكة العربية السعودية وتحديداً في بلحمر،&nbsp;تم انشاء المتحف في عام 2020&nbsp;كأحد المشاريع التراثية في المنطقة، يحتوي المتحف&nbsp;12 ركن بمقتنيات أثرية تاريخية تتجاوز 3 آلاف قطعة متوزعة&nbsp;على أربعة أدوار تنقل تاريخ ساكني المنطقة قديماً.</p> <p>تضم القرية التراثية مجالس للضيافة وقاعات للمناسبات ومطاعم شعبية تقدم للزوار أشهى المأكولات التراثية للمنطقة كما تضم القرية مزرعة للبر وأخرى للفراولة يمكن للزوار التجول فيها والقطف من ثمارها ويوجد أيضاً مقهى يشتهر بعصير الفراولة الطازجة والذي يُنتج من المزرعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59460395-44190673.jpg?v=1637245566"]','https://cmsphoto.ww-cdn.com/resizeapi/59f577df7d237b96eb591ff82a793f776f47610e/480/',18.6327265,42.2411593,'Bihan Abha Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59460395/the-mohammed-bin-adwhan-al-ahmari-museum',1,0,'متحف محمد بن عضوان احمري والقريه تراثيه the mohammed bin adwhan al ahmari museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59460394,'asir-region','عقبة الجعده بللحمر','','al-jadah-pass-billasmar','["أماكن سياحية"]','["sights"]','طريق عقبة الجعدة الموصلة إلى تهامة وعسير وصولًا إلى محافظة محايل، يختصر مسافة 170 كم للنزول إلى إقليم تهامة ليستغرق عبورها 15 دقيقة فقط من أعالي جبال الحجاز إلى سهول تهامة، وهي كذلك تُعد مكانًا مناسبًا للتنزه.','<div class="texte" > <p>طريق عقبة الجعدة الموصلة إلى تهامة وعسير وصولاً إلى محافظة محايل اختصر&nbsp;مسافة 170 كلم للنزول إلى إقليم تهامة ليستغرق عابرها الوقت إلى 15 دقيقة من أعالي جبال الحجاز إلى سهول تهامة، وهي كذلك تعد مكانأ مناسباً للتنزه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59460394-44205726.jpg?v=1637322292"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/59460394-44205726.jpg?v=1637322323',18.6553244,42.2263092,'2452 أبهــــا منطقة عسير','','','','https://www.saudi-guide.com/asir-region/i/59460394/al-jadah-pass-billasmar',1,0,'عقبه جعده بللحمر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59457563,'abha','سما أبها','Sama Abha','sama-abha-sma-abha','["أماكن سياحية"]','["sights"]','سما أبها مساحة خضراء تطل على مدينة أبها، تضم أحواض زهور مزخرفة وتعريشات على شكل قلب، وتعد مكاناً مناسباً للتنزه والتصوير والاستمتاع بالإطلالة.','<div class="texte" > <p>سما أبها مساحة خضراء صغيرة في مدينة أبها تُطلّ على المدينة من موقع مرتفع، وتضمّ أحواض زهور مزخرفة وتعريشات على شكل قلب، ما يجعلها مكاناً مناسباً للتنزه الهادئ والتقاط الصور والاستمتاع بالإطلالة وأجواء أبها المعتدلة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59457563-44064570.jpg?v=1636561389"]','https://cmsphoto.ww-cdn.com/resizeapi/d0a2db2b0cf48a90a5c5df8e567fef5e9edcf22c/480/',18.2601353,42.494907,'7F6V+3X3 Abha Abha','','','','https://www.saudi-guide.com/abha/i/59457563/sama-abha-sma-abha',1,0,'سما ابها sama abha اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440701,'asir-region','حصن تنومه للتراث دار دحدوح','Dar Dahdooh','dar-dahdooh-heritage-fort','["التراث والثقافة"]','["heritage"]','حصن تنومة من الحصون الأثرية الواقعة في تنومة التابعة لمنطقة عسير، يتكون الحصن من ثلاث طوابق، طابق للمصنوعات اليدوية والجلدية وطابق للأسلحة وطابق للحلي والملابس النسائية.','<div class="texte" > <p>حصن دار دحدوح من الحصون الأثرية الواقعة في تنومة التابعة لمنطقة عسير، ويتكون من ثلاثة طوابق تعرض ملامح الحياة التراثية في المنطقة: طابق مخصص للمصنوعات اليدوية والجلدية، وطابق للأسلحة التقليدية، وطابق للحلي والملابس النسائية القديمة. يمنح الحصن زواره جولة تعريفية بتاريخ تنومة وتراثها الأصيل عبر مقتنياته المتنوعة، ويحرص القائمون عليه على استقبال الزوار وتقديم التمر والزبدة الأصيلة والقهوة العربية بالطريقة التقليدية، ما يمنح التجربة طابعًا مضيافًا أصيلاً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440701-44205815.jpg?v=1637322631"]','https://cmsphoto.ww-cdn.com/resizeapi/fd0227ae53d7d0f6c2890ad58e662d7e6011a4c5/480/',18.9362255,42.1746851,'طريق الأربوعة، تنومة 61988','0505703145','','','https://www.saudi-guide.com/asir-region/i/59440701/dar-dahdooh-heritage-fort',1,0,'حصن تنومه للتراث دار دحدوح dar dahdooh تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440657,'asir-region','قرية القرية التراثية بتنومة','','al-qaryah-heritage-village-tanomah','["التراث والثقافة"]','["heritage"]','قرية أثرية بممرات جميلة وبناء أصيل، قرية متكاملة تحتوي على منازل وجسور صغيرة مبنية من حجر، كما يوجد بها بئر عميقة ومسجد عتيق.','<div class="texte" > <p>قرية القرية التراثية في تنومة هي قرية أثرية بممرات جميلة وبناء أصيل، تحتوي على منازل وجسور صغيرة مبنية من الحجر، إضافة إلى بئر عميقة ومسجد عتيق. تعكس القرية أسلوب العمارة الجبلية التقليدية في منطقة عسير، وتُعد وجهة مناسبة لمحبي التراث والتصوير الراغبين في استكشاف تفاصيل الحياة القديمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440657-44190984.jpg?v=1637246158"]','https://cmsphoto.ww-cdn.com/resizeapi/bfdd06d303361bad63648bb4d09e1b424479bc8d/480/',18.9039028,42.1864392,'Tanomah Tanomah Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59440657/al-qaryah-heritage-village-tanomah',1,0,'قريه قريه تراثيه بتنومه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440654,'asir-region','منتزه الحيفة بتنومه','Park Alheefah','park-alheefah','["أماكن سياحية"]','["sights"]','يقع منتزه الحيفة على بعد ستة كيلو مترات من الطريق العام مرورًا بمنتزه غدانة في الجهة الجنوبية الغربية، ويطل على تهامة، وقد اشتهر بأشجار الطلح والعتم وبعض التكوينات الصخرية.','<div class="texte" > <p>يقع منتزه الحيفة على بعد نحو ستة كيلومترات من الطريق العام، مرورًا بمنتزه غدانة في الجهة الجنوبية الغربية، ويطل على منطقة تهامة الساحلية. اشتهر المنتزه بأشجار الطلح والعتم والعرعر وبعض التكوينات الصخرية الطبيعية، ما يجعله وجهة مناسبة لمحبي التنزه ومشاهدة الطبيعة الجبلية المطلة على السهول الساحلية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440654-44205824.jpg?v=1637322693"]','https://cmsphoto.ww-cdn.com/resizeapi/77e0fb46f3c5775a75583da31c7bf4fb3c3df4b8/480/',18.8870556,42.164679,'Tanomah Tanomah Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59440654/park-alheefah',1,0,'منتزه حيفه بتنومه park alheefah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440652,'asir-region','منتزه الشرف بتنومه','Alsharaf Park','alsharaf-park','["أماكن سياحية"]','["sights"]','يتميز منتزه الشرف بتنومه بطبيعته الخلابة والتنوع النباتي الكبير الذي يحتويه وبعض الحيوانات المختلفة مثل البقر والماعز والجواميس التي تتغذى من الطبيعة.','<div class="texte" > <p>يتميز منتزه الشرف بتنومه بطبيعته الخلابة والتنوع النباتي الكبير الذي يحتويه، إضافة إلى وجود بعض الحيوانات مثل البقر والماعز والجواميس التي تتغذى في محيطه الطبيعي. يوفر المنتزه أجواء ريفية هادئة بعيدة عن صخب المدن، ما يجعله وجهة محببة لمحبي الطبيعة والراغبين في تجربة قريبة من الحياة الريفية في عسير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440652-44205946.jpg?v=1637323149"]','https://cmsphoto.ww-cdn.com/resizeapi/c27f289129b20770fc1330fe6be13de56620c8eb/480/',18.9485176,42.1498605,'W4XX+CW5 Tanomah Tanomah','','','','https://www.saudi-guide.com/asir-region/i/59440652/alsharaf-park',1,0,'منتزه شرف بتنومه alsharaf park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440651,'asir-region','منتزه المحفار بتنومه','','al-mahfar-park-tanomah','["أماكن سياحية"]','["sights"]','يقع منتزه المحفار في الجهة الغربية من مدينة تنومة الشهيرة بطبيعتها الخلابة، ويتميز المنتزه بمناخ رائع يعتدل طوال أيام العام في جميع الفصول الأربعة، ما يجعله وجهة مثالية للزوار في مختلف الفصول.','<div class="texte" > <p>يقع منتزه المحفار&nbsp;في الجهة الغربية من مدينة تنومة الشهيرة بطبيعتها الخلابة، يتميز المنتزه بمناخ رائع حيث أنه يعتدل طوال أيام العام في جميع الفصول الأربعة، ففي فصل الشتاء تقل البرودة ولكن&nbsp;ليست لدرجة&nbsp;مزعجة أو مثيرة للقلق بالإضافة إلى وجود بعض الضباب الكثيف والمنخفضة الذي&nbsp;يؤثر على الرؤية في بعض الأحيان.</p> <p>أما في فصل الصيف فيعتبر مناخه معتدل و مميز ليس قارص البرودة في الليل و لا حارق الحرارة في النهار حيث يمكن به قضاء العديد من الأوقات المختلفة والممتعة للسائحين، والسبب وراء عدم حدية المناخ ومحافظته على أن يكون معتدلًا طوال أيام العام هو بسبب انخفاض وادي تنومة الشهير والذي بدوره يوجد في قلب مجموعة من السلاسل الجبلية العملاقة التي تلتف حول الوادي وتختلف فيما بينها من حيث الطول والحجم والضخامة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440651-44205958.jpg?v=1637323173"]','https://cmsphoto.ww-cdn.com/resizeapi/f46a0f1d3615f71ef7b6de2dadd637d29d1430f0/480/',18.9654417,42.1362732,'Tanomah Tanomah Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59440651/al-mahfar-park-tanomah',1,0,'منتزه محفار بتنومه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440650,'asir-region','مرتفعات شعف بللسمر','','shaaf-heights-billasmar','["أماكن سياحية"]','["sights"]','تتميز مرتفعات شعف بللسمر بالمطل الذي يكشف جمال المنطقة من الجهة الجنوبية وبالمساحات الكبيرة التي تغطيها أشجار العرعر الكثيفة، كما تم تجهيزها بجلسات ومظلات ومناطق ألعاب لتصبح من أجمل المناطق السياحية في المنطقة.','<div class="texte" > <p>&nbsp;تتميز مرتفعات شعف بللسمر بالمطل الذي يكشف جمال المنطقة من الجهة الجنوبية وبالمساحات الكبيرة&nbsp;التي تغطيها أشجار العرعر الكثيفة، كما تم تجهيز المنتزه بجلسات ومظلات ومناطق ألعاب لتصبح من أجمل المناطق السياحية في المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440650-44205963.jpg?v=1637323198"]','https://cmsphoto.ww-cdn.com/resizeapi/f427839229dd33c530a54d8580968a75def8c5ba/480/',18.7792167,42.2234859,'Ashifa Billasmar Abha','','','','https://www.saudi-guide.com/asir-region/i/59440650/shaaf-heights-billasmar',1,0,'مرتفعات شعف بللسمر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59440627,'asir-region','سد الخلصة بللسمر','','al-khalsah-dam-billasmar','["أماكن سياحية"]','["sights"]','أنشئ سد الخلصة سنة 1431هـ من أجل استعاضة مياه الآبار الجوفية وتوفير مياه الشرب لسكان المنطقة، حاجزه من النوع الخرساني، يبلغ طول السد 60 مترًا بارتفاع 19 مترًا وبسعة تخزينية تفوق 240 ألف متر مكعب. يساهم السد أيضًا في السيطرة على الفيضانات ورفع منسوب المياه في الآبار السطحية والارتوازية التي يعتمد عليها المزارعون.','<div class="texte" > <p>أنشئ سد الخلصة سنة 1431 هــ من أجل استعاضة مياه الآبار الجوفية وتوفير مياه الشرب لسكان المنطقة والاستفادة من موارد المياه في المستجمع المائي، حاجزه من النوع الخرساني، يبلغ طول السد 60 مترًا بارتفاع&nbsp;19 مترًا وبسعة تخزينية تفوق 240&nbsp; ألف&nbsp;متر مكعب.</p> <p>يساهم السد أيضاً في السيطرة على الفيضانات ورفع منسوب المياه&nbsp;في الآبار السطحية والارتوازية التي يعتمد عليها المزارعون في ري مزارعهم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59440627-44205993.jpg?v=1637323308"]','https://cmsphoto.ww-cdn.com/resizeapi/5e9f6323ea6ccdbabe01325a2b4570fd63274557/480/',18.7670194,42.2607857,'سد الخلصة Zamzm Al Wurud','','','','https://www.saudi-guide.com/asir-region/i/59440627/al-khalsah-dam-billasmar',1,0,'سد خلصه بللسمر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070863,'jeddah','مطعم القلعة','IL Castello','il-castello-mtaam-alklaa','["مطاعم"]','["food"]','مطعم القلعة مطعم إيطالي عريق منذ 1976 يتميز بالبيتزا والأكلات الإيطالية الشهيرة بلمسة لبنانية، ويُعد أحد معالم جدة الراسخة.','<div class="texte" > <p>مطعم القلعة مطعم إيطالي عريق منذ 1976 يتميز بالبيتزا والأكلات الإيطالية الشهيرة بلمسة لبنانية، ويُعد أحد معالم جدة الراسخة. يتميز بديكور القلعة القديمة المزين بالدروع والسيوف الأثرية التي لم تتغير منذ افتتاحه قبل نحو 50 عامًا، ويحمل ذكريات طفولة لأجيال من سكان جدة. للتواصل: 0126606119، ومواعيد الدوام من 1:00 ظهرًا حتى 3:30 عصرًا ومن 6:00 مساءً حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070863-68544731.jpg?v=1791551285", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070863-68544732.jpg?v=1791551292"]','https://cmsphoto.ww-cdn.com/resizeapi/389ddc5f945b375120902f57efd459375f3009ba/480/',21.5220689,39.1850739,'أسعد الله، الشرفية، جدة 23218','0126606119','','','https://www.saudi-guide.com/jeddah/i/98070863/il-castello-mtaam-alklaa',1,0,'مطعم قلعه il castello مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070862,'jeddah','تاباس','Tapas','tapas-tabas','["مطاعم"]','["food"]','تاباس يتميز بتقديم شيمشوري ستيك لذيذ بجانب العديد من الأطباق الشهية وسط أجواء رائعة. يشتهر بحلوى التمر والبوراتا وسلطة البنجر.','<div class="texte" > <p>تاباس يتميز بتقديم شيمشوري ستيك لذيذ بجانب العديد من الأطباق الشهية وسط أجواء رائعة. يشتهر بحلوى التمر والبوراتا وسلطة البنجر، ويحظى بمساحات فاخرة تناسب المناسبات الخاصة رغم أسعاره المرتفعة نسبيًا مقارنة بحجم الحصص. للتواصل: 0563166593، ومواعيد الدوام من 12:30 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070862-68544755.jpg?v=1791551356", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070862-68544756.jpg?v=1791551363"]','https://cmsphoto.ww-cdn.com/resizeapi/c79c16640bc3ee0db72031e3251b42b1bad84c0b/480/',21.5727059,39.1350238,'طريق ساري، الزهراء، جدة 23424','0563166593','','','https://www.saudi-guide.com/jeddah/i/98070862/tapas-tabas',1,0,'تاباس tapas مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070861,'jeddah','شبابيك','Shababik','shababik-shbabyk','["مطاعم"]','["food"]','شبابيك مطعم لبناني مميز بالأجواء الجميلة والمأكولات اللبنانية الأصيلة، ويُعد من أفضل الوجهات اللبنانية في جدة.','<div class="texte" > <p>شبابيك مطعم لبناني مميز بالأجواء الجميلة والمأكولات اللبنانية الأصيلة، ويُعد من أفضل الوجهات اللبنانية في جدة. يشتهر بأطباق اللحم النيء وطبقًا يُعد الأفضل من نوعه، ويحظى بخدمة احترافية وأجواء راقية رغم أسعاره المرتفعة نسبيًا. للتواصل: 920003945، ومواعيد الدوام من 12:30 ظهرًا حتى 1:00 فجرًا (حتى 9:00 صباحًا يوم السبت).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070861-68544768.jpg?v=1791551413", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070861-68544772.jpg?v=1791551421"]','https://cmsphoto.ww-cdn.com/resizeapi/2f142e8d18fcdc2d195ab8e45ae3491dd31f7db1/480/',21.5516329,39.1437,'مجمع أنا سبيشل، طريق الأمير سلطان، الروضة، جدة 23431','920003945','','','https://www.saudi-guide.com/jeddah/i/98070861/shababik-shbabyk',1,0,'شبابيك shababik مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070860,'jeddah','وكامي','Wakame','wakame-okamy','["مطاعم"]','["food"]','وكامي مطعم ياباني تقليدي يقدم أشهى أنواع السوشي الأصلي. يشتهر بسلطة الكاني الحارة وعجينة الترافل بالروبيان.','<div class="texte" > <p>وكامي مطعم ياباني تقليدي يقدم أشهى أنواع السوشي الأصلي. يشتهر بسلطة الكاني الحارة وعجينة الترافل بالروبيان، ويحظى بتقييمات ممتازة جدًا لجودة الطعام وخدمة استثنائية من فريق متعدد الجنسيات. للتواصل: 920005036، ومواعيد الدوام من 12:00 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070860-68544784.jpg?v=1791551484", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070860-68544786.jpg?v=1791551491"]','https://cmsphoto.ww-cdn.com/resizeapi/9b92d02b06fda99ee44a0c5ff88a8f8987aa8d94/480/',21.5771653,39.1278123,'طريق الملك عبدالعزيز، الزهراء، جدة 23424','920005036','','','https://www.saudi-guide.com/jeddah/i/98070860/wakame-okamy',1,0,'وكامي wakame مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070859,'jeddah','آل دينتي','Al Dente','al-dente-al-dynty','["مطاعم"]','["food"]','آل دينتي مطعم إيطالي عريق يتميز بالمأكولات الإيطالية الأصلية بأجواء جبلية أنيقة تحاكي سقف الغابة. يشتهر بشوربة الطماطم الرائعة والباستا الغنية.','<div class="texte" > <p>آل دينتي مطعم إيطالي عريق يتميز بالمأكولات الإيطالية الأصلية بأجواء جبلية أنيقة تحاكي سقف الغابة. يشتهر بشوربة الطماطم الرائعة والباستا الغنية، ويحظى بتقييمات ممتازة كأحد أفضل المطاعم الإيطالية بديكوره الدافئ المريح. للتواصل: 0126970220، ومواعيد الدوام من 1:00 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070859-68544799.jpg?v=1791551564", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070859-68544805.jpg?v=1791551575"]','https://cmsphoto.ww-cdn.com/resizeapi/ea598b4c048a1145f89f5bb9b4c77af059bc0063/480/',21.5757626,39.14444,'طريق الأمير سلطان، السلامة، جدة 23436','0126970220','','','https://www.saudi-guide.com/jeddah/i/98070859/al-dente-al-dynty',1,0,'دينتي al dente مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070858,'jeddah','باكو','Baco','baco-bako','["مطاعم"]','["food"]','باكو مطعم يتميز بقائمة مميزة متنوعة مثل لحم البقر والباو والنودلز بأسلوب آسيوي عصري. يشتهر بأطباق البطاطس الآسيوية والمكسيكية والباو المحشو.','<div class="texte" > <p>باكو مطعم يتميز بقائمة مميزة متنوعة مثل لحم البقر والباو والنودلز بأسلوب آسيوي عصري. يشتهر بأطباق البطاطس الآسيوية والمكسيكية والباو المحشو، ويحظى بأجواء أنيقة ومريحة، رغم بعض الملاحظات على صغر حجم الحصص مقارنة بمطاعم أخرى مماثلة. للتواصل: 0500034378، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070858-68544820.jpg?v=1791551641", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070858-68544822.jpg?v=1791551656"]','https://cmsphoto.ww-cdn.com/resizeapi/ae2560b38fbd3ae94d45b24f9e0a4472706a2c16/480/',21.5692274,39.1245558,'بوليفارد، الشاطئ، جدة 23414','0500034378','','','https://www.saudi-guide.com/jeddah/i/98070858/baco-bako',1,0,'باكو baco مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070838,'jeddah','سكشن بي','Section B','section-b-skshn-by','["مطاعم"]','["food"]','سكشن بي طعم البرقر الأصلي قائمة منوعة من اللحم والدجاج المقرمش وغيرها من المقبلات. يُعد من أشهر مطاعم البرجر في جدة برأي كثير من الزوار.','<div class="texte" > <p>سكشن بي طعم البرقر الأصلي قائمة منوعة من اللحم والدجاج المقرمش وغيرها من المقبلات. يُعد من أشهر مطاعم البرجر في جدة برأي كثير من الزوار، ويحظى بتقييمات ممتازة لجودة اللحم والدجاج وحسن الضيافة من الفريق. مواعيد الدوام من 12:00 ظهرًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070838-68544845.jpg?v=1791551733"]','https://cmsphoto.ww-cdn.com/resizeapi/a33a5765b5bb5df1d4303c2a1137b49aa2a0a215/480/',21.6060577,39.1188028,'3362، شارع حراء، الشاطئ، جدة 23514','','','','https://www.saudi-guide.com/jeddah/i/98070838/section-b-skshn-by',1,0,'سكشن بي section b مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070837,'jeddah','منتزه النخيل','Al Nakheel Restaurant','al-nakheel-restaurant-mntzh-alnkhyl','["مطاعم"]','["food"]','منتزه النخيل قائمة أطباق متنوعة من المأكولات العربية مثل المطبق والمزة والمشاوي، ويُعد أحد أقدم وأشهر المطاعم في جدة منذ الثمانينيات.','<div class="texte" > <p>منتزه النخيل قائمة أطباق متنوعة من المأكولات العربية مثل المطبق والمزة والمشاوي، ويُعد أحد أقدم وأشهر المطاعم في جدة منذ الثمانينيات. يتميز بديكوره الكلاسيكي المستلهم من التراث السعودي وإطلالته على الكورنيش، ويُعد وجهة مثالية لمشاهدة الغروب مع الأصدقاء والعائلة. للتواصل: 0555442969، ومواعيد الدوام من 5:00 مساءً حتى 4:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070837-68544853.jpg?v=1791551810", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070837-68544858.jpg?v=1791551830"]','https://cmsphoto.ww-cdn.com/resizeapi/b07d023db5378978de338713acbf2b2b9d83dd7f/480/',21.5645709,39.1119218,'طريق الكرنيش الفرعي، الشاطئ، جدة 23413','0555442969','','','https://www.saudi-guide.com/jeddah/i/98070837/al-nakheel-restaurant-mntzh-alnkhyl',1,0,'منتزه نخيل al nakheel restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070836,'jeddah','زايكاكي','Zaikaki','zaikaki-zaykaky','["مطاعم"]','["food"]','زايكاكي مطعم هندي عريق يتميز بألذ الوصفات وتنوع قائمة المأكولات الهندية الأصيلة. يشتهر بدجاج البتر تشيكن وخبز الجبنة، ويحظى بولاء زبائن لأكثر من 12 عامًا.','<div class="texte" > <p>زايكاكي مطعم هندي عريق يتميز بألذ الوصفات وتنوع قائمة المأكولات الهندية الأصيلة. يشتهر بدجاج البتر تشيكن وخبز الجبنة، ويحظى بولاء زبائن لأكثر من 12 عامًا، ويُعد من أفضل المطاعم الهندية في جدة بشهادة روادها. للتواصل: 0536333746، ومواعيد الدوام من 2:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070836-68544883.jpg?v=1791551906", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070836-68544887.jpg?v=1791551924"]','https://cmsphoto.ww-cdn.com/resizeapi/8ce90008c062e6d886ff21dd58de8014b2805d4e/480/',21.5765057,39.1273377,'طريق الملك عبدالعزيز الفرعي، الزهراء، جدة 23433','0536333746','','','https://www.saudi-guide.com/jeddah/i/98070836/zaikaki-zaykaky',1,0,'زايكاكي zaikaki مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070835,'jeddah','ذا لاكي لاما','The Lucky Llama','the-lucky-llama-tha-laky-lama','["مطاعم"]','["food"]','ذا لاكي لاما مطعم ياباني يتميز باللحوم اللذيذة منها الواقيو والسوشي والساشيمي. يشتهر بغيوزا الروبيان المقرمشة وأرز البيف الكريمي.','<div class="texte" > <p>ذا لاكي لاما مطعم ياباني يتميز باللحوم اللذيذة منها الواقيو والسوشي والساشيمي. يشتهر بغيوزا الروبيان المقرمشة وأرز البيف الكريمي، ويحظى بديكور جميل وخدمة استثنائية تُذكر باسم النادل، مع لمسات شخصية كطبق رسالة مميزة للمناسبات. للتواصل: 0555070625، ومواعيد الدوام من 6:00 مساءً حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070835-68544896.jpg?v=1791552003", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070835-68544898.jpg?v=1791552022"]','https://cmsphoto.ww-cdn.com/resizeapi/8398787300607bbb75015e5b14b7e585a0deff18/480/',21.6474393,39.1160944,'4056 إبراهيم العنقري، المحمدية، جدة 23617','0555070625','','','https://www.saudi-guide.com/jeddah/i/98070835/the-lucky-llama-tha-laky-lama',1,0,'ذا لاكي لاما the lucky llama مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070834,'jeddah','توينا','Twina Seafood','twina-seafood-toyna','["مطاعم"]','["food"]','توينا قائمة محضرة من عدد من المأكولات البحرية الشهية، ويشتهر بجودة الأسماك الطازجة وسخاء الحصص. يحظى بتقييمات ممتازة لطابعه العائلي الدافئ.','<div class="texte" > <p>توينا قائمة محضرة من عدد من المأكولات البحرية الشهية، ويشتهر بجودة الأسماك الطازجة وسخاء الحصص. يحظى بتقييمات ممتازة لطابعه العائلي الدافئ، رغم بعض الملاحظات على بطء الخدمة أحيانًا عند قلة الزوار. للتواصل: 920028284، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070834-68544917.jpg?v=1791552124", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070834-68544919.jpg?v=1791552137"]','https://cmsphoto.ww-cdn.com/resizeapi/13418e268f79378a0ab6932562ce409980016782/480/',21.6632436,39.1225787,'طريق الأمير سلطان الفرعي، المحمدية، جدة 23625','920028284','','','https://www.saudi-guide.com/jeddah/i/98070834/twina-seafood-toyna',1,0,'توينا twina seafood مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070833,'jeddah','كراستيشين','Crustacean','crustacean-krastyshyn','["مطاعم"]','["food"]','كراستيشين من بيفرلي هيلز إلى قلب جدة يقدم قائمة واسعة من المأكولات الشهية المقدمة من الشيف آن، ويُعد المطعم الفيتنامي الوحيد في جدة.','<div class="texte" > <p>كراستيشين من بيفرلي هيلز إلى قلب جدة يقدم قائمة واسعة من المأكولات الشهية المقدمة من الشيف آن، ويُعد المطعم الفيتنامي الوحيد في جدة. يقع داخل نادي اليخوت بإطلالة غروب ساحرة، ويشتهر بنودلز آن الشهيرة والساتيه الفيتنامي، ويحظى بأجواء راقية عصرية تناسب المناسبات الخاصة. للتواصل: 0136637000، ومواعيد الدوام من 6:00 مساءً حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070833-68551933.jpg?v=1791635465", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070833-68551934.jpg?v=1791635478"]','https://cmsphoto.ww-cdn.com/resizeapi/fe22f317721f43ff945000fd5d326b464550cd8c/480/',21.6524072,39.1005153,'نادي اليخوت، طريق الكرنيش الفرعي، الشاطئ، جدة 23613','0136637000','','','https://www.saudi-guide.com/jeddah/i/98070833/crustacean-krastyshyn',1,0,'كراستيشين crustacean مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070832,'jeddah','فوغو دي تشاو','Fogo de Chão','fogo-de-ch-o-fogho-dy-tshao','["مطاعم"]','["food"]','فوغو دي تشاو من المطاعم المميزة والفاخرة بتقديم أشهى اللحوم البرازيلية بجانب العديد من الأطباق اللذيذة.','<div class="texte" > <p>فوغو دي تشاو من المطاعم المميزة والفاخرة بتقديم أشهى اللحوم البرازيلية بجانب العديد من الأطباق اللذيذة، ويشتهر بتقديمها المستمر (Rodizio) عبر نُدُل يتنقلون بين الطاولات. يضم بار سلطات غنيًا بالخيارات، ويحظى بخدمة استثنائية من الطاقم متعدد الجنسيات، ويُعد وجهة مثالية للاحتفالات والمناسبات. للتواصل: 920006815، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070832-68544931.jpg?v=1791552268", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070832-68544933.jpg?v=1791552282"]','https://cmsphoto.ww-cdn.com/resizeapi/c68a4934a30fe543923c4e3a777602c4f5232764/480/',21.5761491,39.1430558,'طريق الأمير سلطان، مجمع الصافية سكوير، الزهراء، جدة 23424','920006815','','','https://www.saudi-guide.com/jeddah/i/98070832/fogo-de-ch-o-fogho-dy-tshao',1,0,'فوغو دي تشاو fogo de chão مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070831,'jeddah','ذا وترفرونت كيتشن','The Waterfront Kitchen','the-waterfront-kitchen-tha-otrfront-kytshn','["مطاعم"]','["food"]','ذا وترفرونت كيتشن بإطلالة رائعة على البحر يقدم بوفيه متنوعًا بالمأكولات العالمية لتستمتعوا بجلسة إفطار أو غداء مميزة داخل فندق شانغريلا.','<div class="texte" > <p>ذا وترفرونت كيتشن بإطلالة رائعة على البحر يقدم بوفيه متنوعًا بالمأكولات العالمية لتستمتعوا بجلسة إفطار أو غداء مميزة داخل فندق شانغريلا. يشتهر ببوفيه الإفطار الغني بالمخبوزات الطازجة، ويحظى بخدمة استثنائية من الطاقم مع اهتمام خاص بتفاصيل الضيافة. للتواصل: 8004408888، ومواعيد الدوام من 7:00 صباحًا حتى 11:30 صباحًا ومن 1:00 ظهرًا حتى 4:00 عصرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070831-68544940.jpg?v=1791552357", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070831-68544941.jpg?v=1791552374"]','https://cmsphoto.ww-cdn.com/resizeapi/f6f41f55519b379fed6033c2727c5a30dfd52696/480/',21.6227073,39.1080017,'طريق الكورنيش، الطابق الثالث، الشاطئ، جدة 23611','8004408888','','','https://www.saudi-guide.com/jeddah/i/98070831/the-waterfront-kitchen-tha-otrfront-kytshn',1,0,'ذا وترفرونت كيتشن the waterfront kitchen مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070830,'jeddah','نيالي','Niyyali','niyyali-nyaly','["مطاعم"]','["food"]','نيالي تجربة لبنانية استثنائية من قلب جدة، متخصص بتقديم المأكولات اللبنانية الشهية في الطابق الثالث المطل على الكورنيش.','<div class="texte" > <p>نيالي تجربة لبنانية استثنائية من قلب جدة، متخصص بتقديم المأكولات اللبنانية الشهية في الطابق الثالث المطل على الكورنيش. يحظى بخدمة عملاء استثنائية تتعامل باحترافية مع أي ملاحظة، ويقدم أحيانًا حلوى مجانية كلفتة ضيافة، ما يجعله وجهة يُنصح بزيارتها مرارًا. للتواصل: 0126968888، ومواعيد الدوام من 4:00 عصرًا حتى 11:30 مساءً (حتى 12:30 فجرًا يومي الجمعة والسبت).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070830-68544952.jpg?v=1791552446", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070830-68544954.jpg?v=1791552461"]','https://cmsphoto.ww-cdn.com/resizeapi/d07d816aef64b4f00bb52a8861fa869d1ac3bf21/480/',21.622996,39.1081681,'طريق الكورنيش، الطابق الثالث، الشاطئ، جدة 23611','0126968888','','','https://www.saudi-guide.com/jeddah/i/98070830/niyyali-nyaly',1,0,'نيالي niyyali مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070829,'jeddah','توكي','Toki Restaurant','toki-restaurant-toky','["مطاعم"]','["food"]','توكي لعشاق الطعم الصيني يقدم لكم تجربة طعام استثنائية من المأكولات الصينية على يد أفضل الطهاة. يشتهر بالأضلاع المطهوة ببطء وسلة الديم سام المتنوعة.','<div class="texte" > <p>توكي لعشاق الطعم الصيني يقدم لكم تجربة طعام استثنائية من المأكولات الصينية على يد أفضل الطهاة. يشتهر بالأضلاع المطهوة ببطء وسلة الديم سام المتنوعة، ويُعد جزءًا من ذكريات المناسبات الخاصة لعملائه منذ سنوات طويلة بفضل ثبات جودته العالية. للتواصل: 0126060606، ومواعيد الدوام من 1:00 ظهرًا حتى 11:30 مساءً (حتى 12:30 فجرًا في نهاية الأسبوع).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070829-68544959.jpg?v=1791552523", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070829-68544962.jpg?v=1791552536"]','https://cmsphoto.ww-cdn.com/resizeapi/fd4151b636a1cf9cff77334c59e21ea722689bec/480/',21.5650829,39.1273139,'طريق الملك عبدالعزيز، الخالدية، جدة 23422','0126060606','','','https://www.saudi-guide.com/jeddah/i/98070829/toki-restaurant-toky',1,0,'توكي toki restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070828,'jeddah','مانكو','Manko','manko-manko','["مطاعم"]','["food"]','مانكو مطعم بيروفي فاخر يقدم أطباقًا متنوعة شهية وسط أجواء فاخرة أنيقة. يشتهر بالسيفيتشي والسوشي فيستا وكيك الفوندو.','<div class="texte" > <p>مانكو مطعم بيروفي فاخر يقدم أطباقًا متنوعة شهية وسط أجواء فاخرة أنيقة. يشتهر بالسيفيتشي والسوشي فيستا وكيك الفوندو، ويحظى بتقييمات ممتازة لجودة الطعام والخدمة المتميزة رغم أسعاره المرتفعة نسبيًا. للتواصل: 0535557594، ومواعيد الدوام من 5:00 مساءً حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070828-68544968.jpg?v=1791552594", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070828-68544972.jpg?v=1791552612"]','https://cmsphoto.ww-cdn.com/resizeapi/8efe118085779181f62d9d71048288c8cf1be706/480/',21.5485625,39.1383125,'الخالدية، جدة 23421','0535557594','','','https://www.saudi-guide.com/jeddah/i/98070828/manko-manko',1,0,'مانكو manko مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070827,'jeddah','قمر جدة','Amar Jeddah','amar-jeddah-kmr-gd','["مطاعم"]','["food"]','قمر جدة مطعم لبناني فاخر بأجواء دافئة يتميز بتقديم العديد من الأطباق العربية الشهية. يشتهر بالحمص مع اللحمة.','<div class="texte" > <p>قمر جدة مطعم لبناني فاخر بأجواء دافئة يتميز بتقديم العديد من الأطباق العربية الشهية. يشتهر بالحمص مع اللحمة، ويحظى بتقييمات استثنائية شبه إجماعية على جودة الطعام والخدمة الراقية، ويُعد من أشهر المطاعم اللبنانية في جدة. للتواصل: 0508055777، ومواعيد الدوام من 12:00 ظهرًا حتى 1:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070827-68544982.jpg?v=1791552684", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070827-68544986.jpg?v=1791552696"]','https://cmsphoto.ww-cdn.com/resizeapi/3f81a7646f4dcab5125863620a73c058a712a07a/480/',21.5485965,39.1383522,'3364، طريق الأمير محمد بن عبدالعزيز، الخالدية، جدة 23421','0508055777','','','https://www.saudi-guide.com/jeddah/i/98070827/amar-jeddah-kmr-gd',1,0,'قمر جده amar jeddah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070826,'jeddah','أليا','Alieia','alieia-alya','["مطاعم"]','["food"]','أليا استمتع بتجربة الطعام اليوناني البحري بجلسات وإطلالة مذهلة على البحر الأحمر خصوصًا وقت الغروب. يشتهر بسلطة البنجر ومعكرونة الخضار.','<div class="texte" > <p>أليا استمتع بتجربة الطعام اليوناني البحري بجلسات وإطلالة مذهلة على البحر الأحمر خصوصًا وقت الغروب. يشتهر بسلطة البنجر ومعكرونة الخضار، ويقدم قهوة فلات وايت وماكياتو رائعة، ويوصي الطاقم بتجربة آيس كريم المانجو المميز. للتواصل: 0125788230، ومواعيد الدوام من 2:30 عصرًا حتى 12:00 منتصف الليل (الأحد إجازة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070826-68545002.jpg?v=1791552760", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070826-68545003.jpg?v=1791552770"]','https://cmsphoto.ww-cdn.com/resizeapi/42291dd28127a9069245f5a45b17e0bbb198edb4/480/',21.5879828,39.1057407,'الشاطئ، جدة 23417','0125788230','','','https://www.saudi-guide.com/jeddah/i/98070826/alieia-alya',1,0,'يا alieia مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070824,'jeddah','روكا','ROKA Jeddah','roka-jeddah-roka','["مطاعم"]','["food"]','روكا يتميز بتنوع قائمة الأطباق العالمية المميزة، ويشتهر بالموسيقى الحية والأجواء الاحتفالية النابضة بالحياة.','<div class="texte" > <p>روكا يتميز بتنوع قائمة الأطباق العالمية المميزة، ويشتهر بالموسيقى الحية والأجواء الاحتفالية النابضة بالحياة. يشتهر بالباذنجان الدافئ مع زبدة الفول السوداني والأخطبوط المشوي، ويقدم قائمة موسمية للأطباق بأسعار تبدأ من 120 ريالًا تشمل مقبلات ومشروبًا وطبقًا رئيسيًا. للتواصل: 920017652، ومواعيد الدوام من 6:00 مساءً حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070824-68545015.jpg?v=1791552846"]','https://cmsphoto.ww-cdn.com/resizeapi/5b96ad4dc93a22d878df4d8de8a9a5dc326ee7b9/480/',21.548616,39.1384023,'طريق الأمير محمد بن عبدالعزيز، الخالدية، جدة 23421','920017652','','','https://www.saudi-guide.com/jeddah/i/98070824/roka-jeddah-roka',1,0,'روكا roka jeddah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070823,'jeddah','نوفيكوف','Novikov','novikov-nofykof','["مطاعم"]','["food"]','نوفيكوف استمتع بتجربة الطعام الياباني والإيطالي بالطعم الأصلي في آن واحد، ويُعد مطعمًا فاخرًا بديكور عصري أنيق.','<div class="texte" > <p>نوفيكوف استمتع بتجربة الطعام الياباني والإيطالي بالطعم الأصلي في آن واحد، ويُعد مطعمًا فاخرًا بديكور عصري أنيق. يشتهر بسلطة البط المقرمش ونيجيري بيض السمان بالواغيو، ويضم عرضًا للمأكولات البحرية الطازجة يختار منها الزائر مكوناته مباشرة. مواعيد الدوام من 2:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070823-68545039.jpg?v=1791552985", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070823-68545042.jpg?v=1791552993"]','https://cmsphoto.ww-cdn.com/resizeapi/5253e510d3eeb399f47bc67e5dc184c5631b3d23/480/',21.5692159,39.1251723,'علي أبو العلا، الشاطئ، جدة 23414','920005969','','','https://www.saudi-guide.com/jeddah/i/98070823/novikov-nofykof',1,0,'نوفيكوف novikov مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070822,'jeddah','كايزو','KAYZO by Myazu','kayzo-by-myazu-kayzo','["مطاعم"]','["food"]','كايزو الوجهة الأمثل لعشاق المأكولات اليابانية المعاصرة المحضرة ببراعة بنكهات مبتكرة، ويُعد النسخة السريعة من مطعم ميازو الشهير.','<div class="texte" > <p>كايزو الوجهة الأمثل لعشاق المأكولات اليابانية المعاصرة المحضرة ببراعة بنكهات مبتكرة، ويُعد النسخة السريعة من مطعم ميازو الشهير. يشتهر بسوشي "تشانسان" الذي يُفضّل تناوله في المطعم مباشرة لأفضل تجربة، ويوفر خيارًا اقتصاديًا لمحبي نكهات ميازو. للتواصل: 0530954870، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070822-68545053.jpg?v=1791553055", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070822-68545054.jpg?v=1791553066"]','https://cmsphoto.ww-cdn.com/resizeapi/0e4018b53ee23cb6afc7e3b74755b1e8eda530e1/480/',21.5508051,39.1529234,'عبدالرحمن الدخيل، الروضة، جدة 23431','0530954870','','','https://www.saudi-guide.com/jeddah/i/98070822/kayzo-by-myazu-kayzo',1,0,'كايزو kayzo by myazu مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070821,'jeddah','سان كارلو تشيكيتي','San Carlo Cicchetti','san-carlo-cicchetti-san-karlo-tshykyty','["مطاعم"]','["food"]','سان كارلو تشيكيتي مطعم إيطالي يتميز بالمأكولات الشهية والأجواء الجميلة، ويحظى بديكور فخم وأجواء حيوية.','<div class="texte" > <p>سان كارلو تشيكيتي مطعم إيطالي يتميز بالمأكولات الشهية والأجواء الجميلة، ويحظى بديكور فخم وأجواء حيوية. يشتهر بستيك الفلفل الأسود ومعكرونة البولونيز المطهوة بإتقان، ويقدم عرضًا ترفيهيًا مميزًا عند تقديم الجيلاتو بالشوكولاتة. للتواصل: 920004060، ومواعيد الدوام من 1:00 ظهرًا حتى 1:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070821-68545066.jpg?v=1791553124", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070821-68545067.jpg?v=1791553137"]','https://cmsphoto.ww-cdn.com/resizeapi/7422398306a1d1c5269865e7e1a751fb8acd15ca/480/',21.5505901,39.1541522,'طريق الأمير محمد بن عبدالعزيز، الروضة، جدة 23431','920004060','','','https://www.saudi-guide.com/jeddah/i/98070821/san-carlo-cicchetti-san-karlo-tshykyty',1,0,'سان كارلو تشيكيتي san carlo cicchetti مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070820,'jeddah','كورو','Kuuru Jeddah','kuuru-jeddah-koro','["مطاعم"]','["food"]','كورو مطعم ياباني فاخر يقدم أنواعًا مختلفة من السوشي والساشيمي بأجواء أنيقة غير رسمية. يشتهر بنيجيري الواغيو والكود الأسود بحبر السبيدج.','<div class="texte" > <p>كورو مطعم ياباني فاخر يقدم أنواعًا مختلفة من السوشي والساشيمي بأجواء أنيقة غير رسمية. يشتهر بنيجيري الواغيو والكود الأسود بحبر السبيدج، إلى جانب تشيز كيك يُعد من الأفضل تذوقًا على الإطلاق. للتواصل: 920035739، ومواعيد الدوام من 1:00 ظهرًا حتى 11:30 مساءً (حتى 12:30 فجرًا في نهاية الأسبوع).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070820-68545078.jpg?v=1791553205", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070820-68545082.jpg?v=1791553214"]','https://cmsphoto.ww-cdn.com/resizeapi/ff3170f714ddd75fee53624632eedfceee47aa57/480/',21.5649333,39.1269279,'طريق الملك، الخالدية، جدة 23422','920035739','','','https://www.saudi-guide.com/jeddah/i/98070820/kuuru-jeddah-koro',1,0,'كورو kuuru jeddah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070818,'jeddah','شانغ بالاس','Shang Palace','shang-palace-shangh-balas','["مطاعم"]','["food"]','شانغ بالاس مطعم آسيوي عصري يقدم قائمة أطباق صينية متنوعة يتميز بإطلالة على الكورنيش من الطابق الرابع لفندق شانغريلا.','<div class="texte" > <p>شانغ بالاس مطعم آسيوي عصري يقدم قائمة أطباق صينية متنوعة يتميز بإطلالة على الكورنيش من الطابق الرابع لفندق شانغريلا. يشتهر بالديم سام المطهو بعناية وبان باو الرائع، ويستضيف ليلة السيدات كل أربعاء، ويحظى بخدمة استثنائية من فريق متمرس. للتواصل: 8004408888، ومواعيد الدوام من 4:00 عصرًا حتى 11:30 مساءً (الأحد إجازة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070818-68545094.jpg?v=1791553276", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070818-68545097.jpg?v=1791553286"]','https://cmsphoto.ww-cdn.com/resizeapi/6f091c185b952a40ff6731c5a5f8e05f0e71be8e/480/',21.622886,39.1080209,'طريق الكورنيش، الطابق الرابع، الشاطئ، جدة 23611','8004408888','','','https://www.saudi-guide.com/jeddah/i/98070818/shang-palace-shangh-balas',1,0,'شانغ بالاس shang palace مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070816,'jeddah','سونيو','Sonyo','sonyo-sonyo','["مطاعم"]','["food"]','سونيو مطعم يقدم تجربة عالمية فاخرة لأطباق عالمية متنوعة داخل أتيليه لا في مول. يشتهر بعرض غداء يضم بيتزا كبيرة أو باستا مع سلطة ومشروب.','<div class="texte" > <p>سونيو مطعم يقدم تجربة عالمية فاخرة لأطباق عالمية متنوعة داخل أتيليه لا في مول. يشتهر بعرض غداء يضم بيتزا كبيرة أو باستا مع سلطة ومشروب، ويحظى بديكور جميل وأدوات مائدة مميزة، ويقدم شامبانيا سعودية ترحيبية للضيوف. للتواصل: 0539811880، ومواعيد الدوام من 1:00 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070816-68545168.jpg?v=1791553438", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070816-68545173.jpg?v=1791553453"]','https://cmsphoto.ww-cdn.com/resizeapi/a57a57aff962e022bdd6bca4e886d5040171f4e7/480/',21.6139992,39.1176789,'أتيليه لا في مول، طريق الأمير عبدالعزيز، الشاطئ، جدة 23514','0539811880','','','https://www.saudi-guide.com/jeddah/i/98070816/sonyo-sonyo',1,0,'سونيو sonyo مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070815,'jeddah','إلجبيانو','Il-Gabbiano','il-gabbiano-algbyano','["مطاعم"]','["food"]','إلجبيانو مطعم إيطالي عريق يتميز بقائمة طعام متنوعة ومميزة، ويقع في موقع مطل على البحر مباشرة. يشتهر بلا كاييماري المقلي والبوراتا الكبيرة.','<div class="texte" > <p>إلجبيانو مطعم إيطالي عريق يتميز بقائمة طعام متنوعة ومميزة، ويقع في موقع مطل على البحر مباشرة. يشتهر بلا كاييماري المقلي والبوراتا الكبيرة، ويحظى بولاء زبائن لأكثر من 20 عامًا رغم إغلاق بعض النوافذ لأسباب خصوصية. للتواصل: 0126587049، ويعمل من 1:00 ظهرًا حتى 11:30 مساءً (حتى 12:30 فجرًا في نهاية الأسبوع).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070815-68545193.jpg?v=1791553522", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070815-68545200.jpg?v=1791553535"]','https://cmsphoto.ww-cdn.com/resizeapi/90ef69821502ae7e380c7d35a08147555f8b670c/480/',21.5918835,39.1068179,'2174، طريق الكورنيش، الشاطئ، جدة 23511','0126587049','','','https://www.saudi-guide.com/jeddah/i/98070815/il-gabbiano-algbyano',1,0,'جبيانو il gabbiano مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069880,'jeddah','مطاعم الميدان','Almaidan Restaurant','almaidan-restaurant-mtaaam-almydan','["مطاعم"]','["food"]','مطاعم الميدان في جدة لعشاق المأكولات الشعبية، يقدم الأطباق السعودية بالطعم الأصلي ويشتهر بالزربيان والحصص الكبيرة والخدمة الودودة.','<div class="texte" > <p>مطاعم الميدان لعشاق المأكولات الشعبية يتميز بتقديم الأطباق السعودية بالطعم الأصلي. يشتهر بالزربيان وحصص كبيرة بأسعار مناسبة، مع خدمة ودودة من الطاقم رغم عدم توفر أدوات معدنية أو مشروبات ساخنة، ويقدم شوربة ترحيبية مجانية. للتواصل: 0552056655، ومواعيد الدوام من 11:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069880-68545215.jpg?v=1791553600", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069880-68545218.jpg?v=1791553611"]','https://cmsphoto.ww-cdn.com/resizeapi/907b507a3b2816014e2d2ed65e380e8a972dfd5b/480/',21.4946415,39.1808775,'حمزة شحاتة، البغدادية الغربية، جدة 22232','0552056655','','','https://www.saudi-guide.com/jeddah/i/98069880/almaidan-restaurant-mtaaam-almydan',1,0,'مطاعم ميدان almaidan restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069879,'jeddah','المراكبي للمأكولات البحرية','El Marakby Seafood','el-marakby-seafood-almrakby-llmakolat-albhry','["مطاعم"]','["food"]','المراكبي للمأكولات البحرية متخصص بتقديم المأكولات البحرية على الطريقة المصرية كما يتميز بتقديم أشهى أنواع الأسماك الطازجة.','<div class="texte" > <p>المراكبي للمأكولات البحرية متخصص بتقديم المأكولات البحرية على الطريقة المصرية كما يتميز بتقديم أشهى أنواع الأسماك الطازجة. يشتهر بالروبيان الديناميت وسمك الحريد المشوي، ويقدم عصيرًا وآيس كريم مجانيين بعد الوجبة، ويحظى بتقييمات ممتازة جدًا لجودة الطعام رغم أسعاره المرتفعة قليلًا. للتواصل: 0555291131، ومواعيد الدوام من 12:30 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069879-68545235.jpg?v=1791553679", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069879-68545237.jpg?v=1791553695"]','https://cmsphoto.ww-cdn.com/resizeapi/4279cca434800b62339cdf6591a72ecc61c2a6f5/480/',21.5575511,39.1714966,'مشرفة، طريق الأمير سعود الفيصل، التحلية، جدة 23432','0555291131','','','https://www.saudi-guide.com/jeddah/i/98069879/el-marakby-seafood-almrakby-llmakolat-albhry',1,0,'مراكبي للماكولات بحريه el marakby seafood مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069878,'jeddah','مدفون السدة','Madfoon Alsaddah','madfoon-alsaddah-mdfon-alsd','["مطاعم"]','["food"]','مدفون السدة في جدة مطعم ذبائح متخصص بطبخ المدفون والأطباق الشعبية السعودية، بصالات واسعة للتجمعات ويشتهر بالمندي واللحم.','<div class="texte" > <p>مدفون السدة مطعم ذبائح متخصص بطبخ المدفون كما يتميز بتقديم ألذ الأطباق الشعبية السعودية. يستقبل التجمعات الكبيرة بصالات واسعة تتسع لأكثر من 300 ضيف، ويشتهر بأطباق المندي واللحم مع تشكيلة من المقبلات والحلويات، رغم بعض الملاحظات على نظافة دورات المياه في أوقات الازدحام. للتواصل: 0506609977، ومواعيد الدوام من 6:00 صباحًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069878-68545260.jpg?v=1791553758"]','https://cmsphoto.ww-cdn.com/resizeapi/9433e5e3b25fcf3fbe3d14dcb20f8c8eec5331f7/480/',21.5578227,39.2237248,'أم القرى، الرحاب، جدة 23345','0506609977','','','https://www.saudi-guide.com/jeddah/i/98069878/madfoon-alsaddah-mdfon-alsd',1,0,'مدفون سده madfoon alsaddah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069877,'jeddah','مطعم هرمان','Herman Restaurant','herman-restaurant-mtaam-hrman','["مطاعم"]','["food"]','مطعم هرمان لتقديم الأطباق الشعبية السعودية بوصفات عالمية ونكهة مختصة. يشتهر بالكبسة والمندي والمظبي.','<div class="texte" > <p>مطعم هرمان لتقديم الأطباق الشعبية السعودية بوصفات عالمية ونكهة مختصة. يشتهر بالكبسة والمندي والمظبي، ويحظى بديكور يجمع بين الطابع التقليدي والراحة الحديثة مع جلسات علوية مضاءة بشكل جميل. للتواصل: 0536001963، ومواعيد الدوام من 11:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069877-68545270.jpg?v=1791553840", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069877-68545287.jpg?v=1791553851"]','https://cmsphoto.ww-cdn.com/resizeapi/fca6bcbb197439ea336a7f8ad5f3185756a39f32/480/',21.5786939,39.2357029,'حي السامر، الربيع، جدة 23461','0536001963','','','https://www.saudi-guide.com/jeddah/i/98069877/herman-restaurant-mtaam-hrman',1,0,'مطعم هرمان herman restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069876,'jeddah','مطاعم ابو زيد','Abu Zaid Restaurant','abu-zaid-restaurant-mtaaam-abo-zyd','["مطاعم"]','["food"]','مطاعم ابو زيد من أشهر مطاعم الإفطار في جدة لتقديم الوجبات الشعبية المتنوعة. يشتهر بالفول والتميس والمطبق.','<div class="texte" > <p>مطاعم ابو زيد من أشهر مطاعم الإفطار في جدة لتقديم الوجبات الشعبية المتنوعة. يشتهر بالفول والتميس والمطبق، ويحظى بشعبية كبيرة تجعله ممتلئًا دائمًا رغم بعض الملاحظات على جودة الخدمة والتغليف في أوقات الذروة. للتواصل: 0558291243، ومواعيد الدوام من 5:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069876-68545295.jpg?v=1791553911"]','https://cmsphoto.ww-cdn.com/resizeapi/4516714d8eb3836041d2d037ca32204c22d39043/480/',21.5340127,39.2008928,'فلسطين، مشرفة، جدة 23335','0558291243','','','https://www.saudi-guide.com/jeddah/i/98069876/abu-zaid-restaurant-mtaaam-abo-zyd',1,0,'مطاعم ابو زيد abu zaid restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069854,'jeddah','مطعم سرمد','Sarmad','sarmad-mtaam-srmd','["مطاعم"]','["food"]','مطعم سرمد مطعم شعبي يقدم مختلف أنواع المأكولات الشعبية والعربية بأسلوب يحاكي الأجواء القديمة، حيث تُقدَّم الوجبات في غرف خاصة على الأرض.','<div class="texte" > <p>مطعم سرمد مطعم شعبي يقدم مختلف أنواع المأكولات الشعبية والعربية بأسلوب يحاكي الأجواء القديمة، حيث تُقدَّم الوجبات في غرف خاصة على الأرض. يشتهر بالمندي والفاخر والمرسى، ويقدم شوربة ترحيبية مجانية، ويحظى بطابق مخصص للعائلات وأجواء واسعة نظيفة رغم صعوبة إيجاد موقف سيارات أحيانًا. للتواصل: 920035728، ومواعيد الدوام من 11:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069854-68545309.jpg?v=1791554019"]','https://cmsphoto.ww-cdn.com/resizeapi/ebd29e0731e2b08659835a533c9a112fc2437d95/480/',21.4928692,39.1889999,'محمد بن عبدالوهاب، البغدادية الشرقية، جدة 22235','920035728','','','https://www.saudi-guide.com/jeddah/i/98069854/sarmad-mtaam-srmd',1,0,'مطعم سرمد sarmad مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069853,'jeddah','فرن الشيخ','Forn Al Sheikh','forn-al-sheikh-frn-alshykh','["مطاعم"]','["food"]','فرن الشيخ يعتبر أحد معالم جدة التاريخية يقع على شارع الذهب ويشتهر بخبزه الأسمر الشهي الذي يخبز بنفس الطريقة منذ أجيال.','<div class="texte" > <p>فرن الشيخ يعتبر أحد معالم جدة التاريخية يقع على شارع الذهب ويشتهر بخبزه الأسمر الشهي الذي يخبز بنفس الطريقة منذ أجيال. تفوح رائحة الخبز الطازج من المكان فور الدخول، ويحظى بزيارات متكررة من أهل جدة القدامى حتى بعد انتقالهم خارج المملكة حنينًا لطعمه المميز. للتواصل: 0543008620، ومواعيد الدوام من 6:00 صباحًا حتى 11:08 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069853-68545325.jpg?v=1791554105"]','https://cmsphoto.ww-cdn.com/resizeapi/86924e7710355d35acb615476a4c77b9ae9479a6/480/',21.4875315,39.184746,'7200، شارع الذهب، حي البلد، جدة 22233','0543008620','','','https://www.saudi-guide.com/jeddah/i/98069853/forn-al-sheikh-frn-alshykh',1,0,'فرن شيخ forn al sheikh مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069852,'jeddah','سليق أمي','Saleeq Omi','saleeq-omi-slyk-amy','["مطاعم"]','["food"]','سليق أمي في جدة مطعم شعبي صغير يقدم طعم السليق الطائفي على الأصول بطلبات سريعة وجودة عالية، ويشتهر بالسمبوسة أيضاً.','<div class="texte" > <p>سليق أمي مأكولات شعبية وطعم السليق الطائفي على الأصول. مكان صغير يقدم طلبات سريعة بجودة عالية، ويشتهر بالسمبوسة أيضًا بسعر رمزي (1.5 ريال)، رغم صعوبة إيجاد موقف سيارات قريب أحيانًا. للتواصل: 0557690991، ومواعيد الدوام من 12:30 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069852-68545334.jpg?v=1791554189", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069852-68545338.jpg?v=1791554200"]','https://cmsphoto.ww-cdn.com/resizeapi/09a0c91d598e803e94030e938f36a2e4cc602e8f/480/',21.6068993,39.2113591,'المروة، جدة 23545','0557690991','','','https://www.saudi-guide.com/jeddah/i/98069852/saleeq-omi-slyk-amy',1,0,'سليق امي saleeq omi مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069850,'jeddah','تعتيمة جستنيه','Tatemat Jastaniah','tatemat-jastaniah-taatym-gstnyh','["مطاعم"]','["food"]','تعتيمة جستنيه يقدم تشكيلة واسعة من قائمة الإفطار والمأكولات الشعبية وسط أجواء وجلسات مميزة تحاكي البيت الحجازي التقليدي.','<div class="texte" > <p>تعتيمة جستنيه يقدم تشكيلة واسعة من قائمة الإفطار والمأكولات الشعبية وسط أجواء وجلسات مميزة تحاكي البيت الحجازي التقليدي. يشتهر بأطباق الجلابة ومخ الحمل، ويحظى بديكور أنيق يعكس أصالة المنطقة، ويُعد وجهة ثقافية غامرة للسياح والزوار. للتواصل: 0567076696، ومواعيد الدوام من 7:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069850-68545353.jpg?v=1791554260", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069850-68545354.jpg?v=1791554274"]','https://cmsphoto.ww-cdn.com/resizeapi/8b59c6dde2ed2b574afc6d40c7b81983d9e3f479/480/',21.580745,39.149835,'اليمامة، السلامة، جدة 23436','0567076696','','','https://www.saudi-guide.com/jeddah/i/98069850/tatemat-jastaniah-taatym-gstnyh',1,0,'تعتيمه جستنيه tatemat jastaniah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069848,'jeddah','مطعم باعشن للأسماك','Ba''eshen Seafood','baeshen-seafood-mtaam-baaashn-llasmak','["مطاعم"]','["food"]','مطعم باعشن للأسماك يقع في سوق الندى بمنطقة جدة التاريخية ويشتهر بتقديم مأكولات بحرية طازجة في أجواء تتسم بالبساطة وحسن الضيافة.','<div class="texte" > <p>مطعم باعشن للأسماك يقع في سوق الندى بمنطقة جدة التاريخية ويشتهر بتقديم مأكولات بحرية طازجة في أجواء تتسم بالبساطة وحسن الضيافة. يُعد رقم واحد لتجربة السمك في وسط جدة التاريخي القديم، مع أسعار معقولة وطاقم ودود، رغم مساحة جلوس ضيقة نسبيًا وعدم توفر خيار الشوي. للتواصل: 0503674710، ومواعيد الدوام من 12:15 ظهرًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069848-68545362.jpg?v=1791554335", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069848-68545364.jpg?v=1791554346"]','https://cmsphoto.ww-cdn.com/resizeapi/980820a2eb337e8cf90fdab364dd086f645621a9/480/',21.4870784,39.1840589,'جدة التاريخية، جدة 22233','0503674710','','','https://www.saudi-guide.com/jeddah/i/98069848/baeshen-seafood-mtaam-baaashn-llasmak',1,0,'مطعم باعشن للاسماك ba''eshen seafood مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069847,'jeddah','بيت التركستاني','Bait Al Turkistani','bait-al-turkistani-byt-altrkstany','["مطاعم"]','["food"]','بيت التركستاني في جدة يتميز بالمنتو والفرموزة وقائمة معجنات متنوعة على الطريقة الأفغانية، ويشتهر بمنتو اللحم والفرموزة الجبنية.','<div class="texte" > <p>بيت التركستاني يتميز المطعم بالمنتو والفرموزة وقائمة معجنات متنوعة على الطريقة الأفغانية. يشتهر بمنتو اللحم والفرموزة الجبنية المقدمة بحجم اقتصادي (3 قطع بريالين)، ويحظى بتقدير خاص لطعمها الأصيل رغم الأثر الجانبي المعتاد لأطباق المنتو من الانتفاخ. للتواصل: 0559217987، ومواعيد الدوام من 1:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069847-68545369.jpg?v=1791554409", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069847-68545370.jpg?v=1791554422"]','https://cmsphoto.ww-cdn.com/resizeapi/5bab70db8621017fac1b70a04a073da94dc3545c/480/',21.5368632,39.2123435,'شارع الصحافة، مشرفة، جدة 23341','0559217987','','','https://www.saudi-guide.com/jeddah/i/98069847/bait-al-turkistani-byt-altrkstany',1,0,'بيت تركستاني bait al turkistani مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069846,'jeddah','عسقلان للمقلوبة','Asqalan','asqalan-aasklan-llmklob','["مطاعم"]','["food"]','عسقلان للمقلوبة متخصص بتقديم المقلوبة بالنكهة الأصلية بجانب العديد من الأطباق الشهية. يشتهر بمقلوبة الدجاج واللحم والمكرونة والبرياني.','<div class="texte" > <p>عسقلان للمقلوبة متخصص بتقديم المقلوبة بالنكهة الأصلية بجانب العديد من الأطباق الشهية. يشتهر بمقلوبة الدجاج واللحم والمكرونة والبرياني، ويحظى بتقييمات ممتازة جدًا لجودة العرض والتقديم وتنوع القائمة رغم بساطتها. للتواصل: 0551383111، ومواعيد الدوام من 11:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069846-68545378.jpg?v=1791554489", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069846-68545379.jpg?v=1791554501"]','https://cmsphoto.ww-cdn.com/resizeapi/1929546e790d1faa8b06883ed81a1935669c35ad/480/',21.5585926,39.1528277,'طريق الأمير سعود الفيصل، الروضة، جدة 23432','0551383111','','','https://www.saudi-guide.com/jeddah/i/98069846/asqalan-aasklan-llmklob',1,0,'عسقلان للمقلوبه asqalan مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069845,'jeddah','السدة','Al Sadda','al-sadda-alsd','["مطاعم"]','["food"]','السدة مطعم شعبي في جدة يتميز بالأكلات السعودية الأصيلة في أجواء نظيفة ومريحة، ويحظى بتقييمات ممتازة لجودة الأرز واللحم.','<div class="texte" > <p>السدة مطعم شعبي يتميز بالأكلات الشعبية السعودية الأصيلة. يقدم أطباقًا تقليدية بأسعار مناسبة وأجواء نظيفة ومريحة، ويحظى بتقييمات ممتازة من الزوار لجودة الأرز واللحم وحسن استقبال الفريق. للتواصل: 0126677763، ومواعيد الدوام من 11:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069845-68545400.jpg?v=1791554563", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069845-68545402.jpg?v=1791554573"]','https://cmsphoto.ww-cdn.com/resizeapi/c918f79c07482f3e0fac4b43657f5d8258ca694f/480/',21.6314002,39.1334661,'طريق الأمير سلطان، النهضة، جدة 23615','0126677763','','','https://www.saudi-guide.com/jeddah/i/98069845/al-sadda-alsd',1,0,'سده al sadda مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069843,'jeddah','البصلي للأسماك','Albasali Seafood','albasali-seafood-albsly-llasmak','["مطاعم"]','["food"]','البصلي للأسماك مطعم أسماك ومأكولات شعبية يتميز بالأطباق المنوعة مثل السمك المقلي. يشتهر بالنجل المقلي والروبيان المقرمش وأرز السيادية.','<div class="texte" > <p>البصلي للأسماك مطعم أسماك ومأكولات شعبية يتميز بالأطباق المنوعة مثل السمك المقلي. يشتهر بالنجل المقلي والروبيان المقرمش وأرز السيادية، ويُعد من أشهر مطاعم الأسماك في جدة، رغم إقبال كثيف يستدعي انتظارًا يصل أحيانًا لـ50 دقيقة. للتواصل: 0504301163، ومواعيد الدوام من 1:00 ظهرًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069843-68545441.jpg?v=1791554634", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069843-68545454.jpg?v=1791554644"]','https://cmsphoto.ww-cdn.com/resizeapi/613b636b83471df9716e8e4a88871e59528f0e5d/480/',21.4860808,39.1902538,'خلف مدارس الفلاح، سوق باب مكة، جدة التاريخية، جدة 22236','0504301163','','','https://www.saudi-guide.com/jeddah/i/98069843/albasali-seafood-albsly-llasmak',1,0,'بصلي للاسماك albasali seafood مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069842,'jeddah','القرموشي','Al Qarmoshi','al-qarmoshi-alkrmoshy','["مطاعم"]','["food"]','القرموشي مطعم يقدم الأكلات الحجازية مثل المطبق الحالي والمالح والمعصوب. يشتهر بأطباق الفطور الحجازي الأصيل.','<div class="texte" > <p>القرموشي مطعم يقدم الأكلات الحجازية مثل المطبق الحالي والمالح والمعصوب. يشتهر بأطباق الفطور الحجازي الأصيل، ويحظى بإقبال كثيف خصوصًا صباحًا رغم بعض الملاحظات على سرعة الخدمة في أوقات الذروة. للتواصل: 0550893552، ومواعيد الدوام من 5:50 صباحًا حتى 11:25 صباحًا ومن 6:10 مساءً حتى 12:25 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069842-68545462.jpg?v=1791554710", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069842-68545465.jpg?v=1791554731"]','https://cmsphoto.ww-cdn.com/resizeapi/2d63b8472cc92f5682e4c917f31b36f3f7ce26f6/480/',21.7628421,39.2227283,'الصالحية، جدة 23672','0550893552','','','https://www.saudi-guide.com/jeddah/i/98069842/al-qarmoshi-alkrmoshy',1,0,'قرموشي al qarmoshi مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069841,'jeddah','مطعم ناجي الحربي للكباب','Naji Alharbi Kebab','naji-alharbi-kebab-mtaam-nagy-alhrby-llkbab','["مطاعم"]','["food"]','مطعم ناجي الحربي للكباب من أشهر وألذ مطاعم الكباب الشهيرة في مدينة جدة. يشتهر بأطباق الشواء واللحم المشوي بنكهة أصيلة، ويقدم صواني كبيرة تناسب المجموعات.','<div class="texte" > <p>مطعم ناجي الحربي للكباب من أشهر وألذ مطاعم الكباب الشهيرة في مدينة جدة. يشتهر بأطباق الشواء واللحم المشوي بنكهة أصيلة، ويقدم صواني كبيرة تناسب المجموعات، رغم عدم توفر كراسي أو جلسات في بعض الفروع فيُنصح بالطلب الخارجي. للتواصل: 0535400766، ومواعيد الدوام من 11:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069841-68545477.jpg?v=1791554811"]','https://cmsphoto.ww-cdn.com/resizeapi/43fb645e31600500a2b3a0e3959fa0a80dc5e9ee/480/',21.317094,39.2600216,'القرينية، جدة 22535','0535400766','','','https://www.saudi-guide.com/jeddah/i/98069841/naji-alharbi-kebab-mtaam-nagy-alhrby-llkbab',1,0,'مطعم ناجي حربي للكباب naji alharbi kebab مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069840,'jeddah','مطبخ همام','Matbakh Humam','matbakh-humam-mtbkh-hmam','["مطاعم"]','["food"]','مطبخ همام في جدة مطبخ شعبي يتميز بأطباق متنوعة مثل السليق الحجازي التقليدي، ويركز على الطلبات الخارجية والكميات الكبيرة.','<div class="texte" > <p>مطبخ همام مطبخ شعبي يتميز بأطباق متنوعة مثل طبق السليق الحجازي التقليدي. يُنصح بالاتصال المسبق للطلب لأن المطعم يعمل غالبًا للطلبات الخارجية دون صالة انتظار مكيّفة، ويُقدّم السليق بحد أدنى دجاجة كاملة، فيحتاج طلبات الكميات الكبيرة لحجز مسبق بساعات. للتواصل: 0126940945، ومواعيد الدوام من 10:00 صباحًا حتى 3:00 عصرًا ومن 5:00 عصرًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069840-68545491.jpg?v=1791554907", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069840-68545493.jpg?v=1791554920"]','https://cmsphoto.ww-cdn.com/resizeapi/e7f923d146aa6f8170c4381eadbd0c9ffdf57ccf/480/',21.611842,39.1239192,'التأمين، النهضة، جدة 23523','0126940945','','','https://www.saudi-guide.com/jeddah/i/98069840/matbakh-humam-mtbkh-hmam',1,0,'مطبخ همام matbakh humam مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069838,'jeddah','فلافل الخالدية','Falafel Al Khalidiyah','falafel-al-khalidiyah-flafl-alkhaldy','["مطاعم"]','["food"]','فلافل الخالدية يتميز المطعم بتقديم الفلافل المقرمشة والأطباق الشعبية، ويُعد جزءًا من أسطورة جدة القديمة بشهادة أهلها.','<div class="texte" > <p>فلافل الخالدية يتميز المطعم بتقديم الفلافل المقرمشة والأطباق الشعبية، ويُعد جزءًا من أسطورة جدة القديمة بشهادة أهلها. يشتهر بساندويتش الفلافل مع الحمص والصلصة الحارة المميزة، ويحظى بازدحام دائم خصوصًا في أوقات الفطور، مع خدمة طلبات خارجية فقط دون صالة جلوس. للتواصل: 0126306293، ومواعيد الدوام من 6:30 صباحًا حتى 12:00 ظهرًا ومن 5:00 عصرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069838-68545499.jpg?v=1791554984", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069838-68545503.jpg?v=1791554995"]','https://cmsphoto.ww-cdn.com/resizeapi/0146829e828951b1d1150f369f556fe6afffbf63/480/',21.5596009,39.1378315,'نور اليسر، الخالدية، جدة 23423','0126306293','','','https://www.saudi-guide.com/jeddah/i/98069838/falafel-al-khalidiyah-flafl-alkhaldy',1,0,'فلافل خالديه falafel al khalidiyah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069785,'jeddah','متحف المكتين','Al Maktain Museum','al-maktain-museum-mthf-almktyn','["التراث والثقافة"]','["heritage"]','متحف المكتين أول متحف من نوعه في المملكة العربية السعودية يضم قرابة 1000 قطعة نادرة موزعة على أربعة متاحف في مكان واحد: تاريخ الفن الإسلامي.','<div class="texte" > <p>متحف المكتين أول متحف من نوعه في المملكة العربية السعودية يضم قرابة 1000 قطعة نادرة موزعة على أربعة متاحف في مكان واحد: تاريخ الفن الإسلامي، تاريخ الطب الإسلامي، تصوير مكة والمدينة، ومحطات تاريخية بارزة. يتميز بلافتات إرشادية ممتازة بالعربية والإنجليزية ومقتنيات عالية المستوى، ويحظى بإشادة كبيرة من الزوار لثراء محتواه التعليمي. مواعيد الدوام من 10:00 صباحًا حتى 10:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069785-68545533.jpg?v=1791555067"]','https://cmsphoto.ww-cdn.com/resizeapi/e7f19f69579e355e947096f8dcba0eac7200dc84/480/',21.5565935,39.1849149,'العزيزية، شارع الأمير محمد بن عبدالعزيز، جدة 23334','','','','https://www.saudi-guide.com/jeddah/i/98069785/al-maktain-museum-mthf-almktyn',1,0,'متحف مكتين al maktain museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069783,'jeddah','مركز طارق عبدالحكيم','Tariq Abdulhakim Museum','tariq-abdulhakim-museum-mrkz-tark-aabdalhkym','["التراث والثقافة"]','["heritage"]','مركز طارق عبدالحكيم متحف يعرض مسيرة الفنان الكبير طارق عبدالحكيم في الفن والموسيقى، كما يضم صالة عزف آلات موسيقية تفاعلية يمكن للزوار تجربتها بأنفسهم.','<div class="texte" > <p>مركز طارق عبدالحكيم متحف يعرض مسيرة الفنان الكبير طارق عبدالحكيم في الفن والموسيقى، كما يضم صالة عزف آلات موسيقية تفاعلية يمكن للزوار تجربتها بأنفسهم. يقع في قلب جدة التاريخية (البلد)، ويقدم جولة إرشادية مجانية بلغة عربية وإنجليزية تستمر نحو 20 دقيقة، إذ فاز عبدالحكيم بجائزة اليونسكو الدولية للموسيقى عام 1981 كأول عربي ينالها. الدخول مجاني، ومواعيد الدوام من 9:00 صباحًا حتى 10:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069783-68545536.jpg?v=1791555135", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069783-68545538.jpg?v=1791555147"]','https://cmsphoto.ww-cdn.com/resizeapi/86e5bd0cac39a2e7d9dfe7440516ad88faddef80/480/',21.4829797,39.1874566,'3214، حي البلد، جدة 22236','','','','https://www.saudi-guide.com/jeddah/i/98069783/tariq-abdulhakim-museum-mrkz-tark-aabdalhkym',1,0,'مركز طارق عبدالحكيم tariq abdulhakim museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069756,'jeddah','كوكيان','Kokiyan Beach','kokiyan-beach-kokyan','["سياحة وترفيه"]','["sights"]','كوكيان شاطئ رملي للسباحة مناسب لجميع الفئات، يقدم العديد من الأنشطة والخدمات البحرية. يضم مناطق مخصصة للعائلات والأطفال بأجواء نظيفة ومياه صافية.','<div class="texte" > <p>كوكيان شاطئ رملي للسباحة مناسب لجميع الفئات، يقدم العديد من الأنشطة والخدمات البحرية. يضم مناطق مخصصة للعائلات والأطفال بأجواء نظيفة ومياه صافية، مع إمكانية تأجير الكراسي والطاولات وتوفر خيار الشيشة. مواعيد الدوام من 6:00 صباحًا حتى 10:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069756-68551945.jpg?v=1791635571"]','https://cmsphoto.ww-cdn.com/resizeapi/5e1f82ae885f5b2a1dbf11d8c8da58cdf731c54f/480/',21.7485872,39.1327662,'أبحر الجنوبية، جدة 23734','','','','https://www.saudi-guide.com/jeddah/i/98069756/kokiyan-beach-kokyan',1,0,'كوكيان kokiyan beach سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069754,'jeddah','شاطئ لابلايا','La Playa Beach','la-playa-beach-shaty-lablaya','["سياحة وترفيه"]','["sights"]','شاطئ لابلايا تجربة متكاملة، الاسترخاء على الشاطئ والاستمتاع بأشعة الشمس، مع مطعم مأكولات بحرية شهير يطل مباشرة على البحر.','<div class="texte" > <p>شاطئ لابلايا تجربة متكاملة، الاسترخاء على الشاطئ والاستمتاع بأشعة الشمس، مع مطعم مأكولات بحرية شهير يطل مباشرة على البحر. يشتهر بطبق الهامور ولا كاييماري الطازج، ويحظى بخدمة ضيافة استثنائية للإفطار والعشاء، مع حد أدنى للإنفاق يبلغ 300 ريال. للتواصل: 920002828، ومواعيد الدوام من 8:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069754-68545542.jpg?v=1791555258", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069754-68545543.jpg?v=1791555275"]','https://cmsphoto.ww-cdn.com/resizeapi/fe38c5273092e00b2fe6da8d41473454bb73564b/480/',21.723122,39.0804257,'شارع الأمير عبدالله الفيصل، أبحر الشمالية، جدة 23811','920002828','','','https://www.saudi-guide.com/jeddah/i/98069754/la-playa-beach-shaty-lablaya',1,0,'شاطئ لابلايا la playa beach سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069753,'jeddah','شاطئ البحيرات','Buhairat Beach','buhairat-beach-shaty-albhyrat','["سياحة وترفيه"]','["sights"]','شاطئ البحيرات من أهدأ شواطئ مدينة جدة لكونه يبعد عدة كيلومترات عن مركز المدينة ويعطي فرصة الاقتراب من الموج والتأمل في الآفاق.','<div class="texte" > <p>شاطئ البحيرات من أهدأ شواطئ مدينة جدة لكونه يبعد عدة كيلومترات عن مركز المدينة ويعطي فرصة الاقتراب من الموج والتأمل في الآفاق. يتميز بخصوصيته ونظافته العالية، ويحظى بإعجاب الزوار الباحثين عن تجربة شاطئية هادئة بعيدة عن صخب الشواطئ المزدحمة. للتواصل: 0566622849.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069753-68545556.jpg?v=1791555346", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069753-68545557.jpg?v=1791555363"]','https://cmsphoto.ww-cdn.com/resizeapi/689b2a4226765b800593cbec1c64f78ca9f7b43a/480/',21.8233249,39.0136967,'ذهبان، جدة 23843','0566622849','','','https://www.saudi-guide.com/jeddah/i/98069753/buhairat-beach-shaty-albhyrat',1,0,'شاطئ بحيرات buhairat beach سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069751,'jeddah','شاطئ أبحر','Obhur Beach','obhur-beach-shaty-abhr','["سياحة وترفيه"]','["sights"]','شاطئ أبحر هو من أجمل الشواطئ المطلة على مركز مدينة جدة بسبب تشكل الشاطئ على هيئة هلال. يتميز بمساحات مخصصة للأطفال مغطاة بالرمل، ومنطقتين للسباحة.','<div class="texte" > <p>شاطئ أبحر هو من أجمل الشواطئ المطلة على مركز مدينة جدة بسبب تشكل الشاطئ على هيئة هلال. يتميز بمساحات مخصصة للأطفال مغطاة بالرمل، ومنطقتين للسباحة، إلى جانب أجواء نظيفة ومنعشة تناسب الجلسات العائلية المسائية، ويُتوقع افتتاح محال آيس كريم وقهوة قريبًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069751-68545574.jpg?v=1791555432"]','https://cmsphoto.ww-cdn.com/resizeapi/26db0d30d9f1e23b001cbaa2ffe2c2a795bc115b/480/',21.7470004,39.1317857,'طريق الكرنيش، أبحر الجنوبية، جدة 23733','','','','https://www.saudi-guide.com/jeddah/i/98069751/obhur-beach-shaty-abhr',1,0,'شاطئ ابحر obhur beach سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069750,'jeddah','خليج الملك سلمان','King Salman Bay','king-salman-bay-khlyg-almlk-slman','["سياحة وترفيه"]','["sights"]','خليج الملك سلمان أحد المواقع البحرية القريبة من الشواطئ التي تسهل على الزائر التخييم أو الاستمتاع برحلة قارب سريعة.','<div class="texte" > <p>خليج الملك سلمان أحد المواقع البحرية القريبة من الشواطئ التي تسهل على الزائر التخييم أو الاستمتاع برحلة قارب سريعة. تتميز إطلالته الجميلة خصوصًا وقت شروق الشمس وأواخر النهار، ويحظى بإمكانيات كبيرة للتطور كوجهة سياحية بحرية في المستقبل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069750-68545592.jpg?v=1791555521", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069750-68545597.jpg?v=1791555542"]','https://cmsphoto.ww-cdn.com/resizeapi/b05b1e8e33c70bb9e2ed79e1825fa8c84373cdd0/480/',21.8926513,39.0044335,'مكة 23844','','','','https://www.saudi-guide.com/jeddah/i/98069750/king-salman-bay-khlyg-almlk-slman',1,0,'خليج ملك سلمان king salman bay سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069749,'jeddah','شاطئ الشيراتون','Sheraton Sahel Marina','sheraton-sahel-marina-shaty-alshyraton','["سياحة وترفيه"]','["sights"]','شاطئ الشيراتون يتيح لزواره فرصة الجلوس على الشاطئ والسباحة في مياه البحر الأحمر والتمتع بالفعاليات والأنشطة المقامة على الشاطئ.','<div class="texte" > <p>شاطئ الشيراتون يتيح لزواره فرصة الجلوس على الشاطئ والسباحة في مياه البحر الأحمر والتمتع بالفعاليات والأنشطة المقامة على الشاطئ. يقع في منتجع فلل بشمال أبحر، ويوفر أجواء مريحة للاسترخاء مع نسيم بحري منعش، رغم أن بعض الزوار يلاحظون حاجة الشاطئ لصيانة أكبر وتحسين نظافة المياه. للتواصل: 0122341871.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069749-68545630.jpg?v=1791555666"]','https://cmsphoto.ww-cdn.com/resizeapi/be481d9ad0dc555c0fe7f1c4a7f050a2f6fd16f0/480/',21.7722713,39.0551295,'شارع الأمير عبدالله الفيصل، اللؤلؤ، جدة 23821','0122341871','','','https://www.saudi-guide.com/jeddah/i/98069749/sheraton-sahel-marina-shaty-alshyraton',1,0,'شاطئ شيراتون sheraton sahel marina سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069748,'jeddah','جدة بروميناد','Jeddah Promenade','jeddah-promenade-gd-bromynad','["سياحة وترفيه"]','["sights"]','جدة بروميناد منطقة ترفيهية على الكورنيش تجمع مطاعم ومقاهي متنوعة ومسارات مشي بإطلالة على البحر الأحمر، ووجهة عائلية وقت الغروب.','<div class="texte" > <p>جدة بروميناد على بحر جدة منطقة ترفيهية متكاملة تجمع ما بين مطاعم متنوعة ومقاهي مميزة. يوفر مسارات مشي منظمة ومساحات مفتوحة وأعمالًا فنية عامة بإطلالة على البحر الأحمر، ويُعد وجهة عائلية مثالية خصوصًا في المساء وقت غروب الشمس، رغم ازدحام مواقف السيارات في عطلات نهاية الأسبوع. مواعيد الدوام من 4:00 عصرًا حتى 3:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069748-68545647.jpg?v=1791555752", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069748-68545650.jpg?v=1791555763"]','https://cmsphoto.ww-cdn.com/resizeapi/56cbe7a84d2b9844529ab6febb7bece206ad683f/480/',21.6389362,39.1032584,'8625، طريق الكورنيش، الشاطئ، جدة 23612','','','','https://www.saudi-guide.com/jeddah/i/98069748/jeddah-promenade-gd-bromynad',1,0,'جده بروميناد jeddah promenade سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069747,'jeddah','تروبيكال لاند','Tropical Land','tropical-land-trobykal-land','["سياحة وترفيه"]','["sights"]','تروبيكال لاند ستعيش تجربة الغابات الاستوائية في جدة، منطقة ترفيهية ممتعة تناسب جميع العائلة. يتيح للزوار التفاعل المباشر مع طيور استوائية ملونة.','<div class="texte" > <p>تروبيكال لاند ستعيش تجربة الغابات الاستوائية في جدة، منطقة ترفيهية ممتعة تناسب جميع العائلة. يتيح للزوار التفاعل المباشر مع طيور استوائية ملونة، بالإضافة لمشاهدة الفلامنجو والحيوانات الصغيرة كالإغوانا والثعابين، وسط أجواء مكيفة تحاكي الغابة الحقيقية. للتواصل: 920013725، ومواعيد الدوام من 12:00 ظهرًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069747-68545668.jpg?v=1791555941"]','https://cmsphoto.ww-cdn.com/resizeapi/dd8fcd02fe64e6da3549879da53fd7e5dcbeaf7d/480/',21.5556262,39.1830822,'العزيزية، جدة 23334','920013725','','','https://www.saudi-guide.com/jeddah/i/98069747/tropical-land-trobykal-land',1,0,'تروبيكال لاند tropical land سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069745,'jeddah','جدة بارك','Jeddah Park','jeddah-park-gd-bark','["سياحة وترفيه"]','["sights"]','جدة بارك أحد أحدث وأضخم مراكز التسوق في جدة، كما يشمل أبراجًا فندقية، ويضم متحفًا متخصصًا في الفن الإسلامي.','<div class="texte" > <p>جدة بارك أحد أحدث وأضخم مراكز التسوق في جدة، كما يشمل أبراجًا فندقية، ويضم متحفًا متخصصًا في الفن الإسلامي. يضم دار سينما وصالة ألعاب للأطفال بجانب علامات تجارية عالمية ومحلية بمختلف المستويات، إلى جانب ساحة طعام واسعة تلبي مختلف الأذواق. للتواصل: 920000262، ومواعيد الدوام من 9:30 صباحًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069745-68545675.jpg?v=1791556002", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069745-68545677.jpg?v=1791556013"]','https://cmsphoto.ww-cdn.com/resizeapi/626616e8a8a8372b1f2334e0a6c6fd05cf3325c3/480/',21.5561176,39.1853712,'العزيزية، جدة 23334','920000262','','','https://www.saudi-guide.com/jeddah/i/98069745/jeddah-park-gd-bark',1,0,'جده بارك jeddah park سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069723,'jeddah','حديقة بحيرة الأربعين','Lake Al-Arbaeen Park','lake-al-arbaeen-park-hdyk-bhyr-alarbaayn','["سياحة وترفيه"]','["sights"]','حديقة بحيرة الأربعين تتميز بموقعها على ضفاف بحيرة الأربعين، تضم مجسمات فنية عالمية تتوزع بين المسطحات الخضراء المنسقة.','<div class="texte" > <p>حديقة بحيرة الأربعين تتميز بموقعها على ضفاف بحيرة الأربعين، تضم مجسمات فنية عالمية تتوزع بين المسطحات الخضراء المنسقة. تجمع الحديقة بين المناظر الطبيعية والعمارة التاريخية والفعاليات الثقافية وعربات الطعام الشعبية، وتُعد جزءًا من رؤية السعودية 2030 لتطوير مسارات رياضية ومطاعم محلية تبرز تراث المدينة. مواعيد الدوام من 9:00 صباحًا حتى 11:40 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069723-68545690.jpg?v=1791556082", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069723-68545696.jpg?v=1791556100"]','https://cmsphoto.ww-cdn.com/resizeapi/8b981903fc4354bfd9d5165e61bdbfe0f527b7c0/480/',21.4904589,39.1851456,'الصناعير، جدة التاريخية، جدة 22233','','','','https://www.saudi-guide.com/jeddah/i/98069723/lake-al-arbaeen-park-hdyk-bhyr-alarbaayn',1,0,'حديقه بحيره اربعين lake al arbaeen park سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069722,'jeddah','الكوميدي كلوب','The Comedy Club','the-comedy-club-alkomydy-klob','["سياحة وترفيه"]','["sights"]','الكوميدي كلوب أحد أول المراكز الترفيهية المخصصة للعروض الكوميدية الحية، ويشمل عروض ستاند اب كوميدي وغيرها.','<div class="texte" > <p>الكوميدي كلوب أحد أول المراكز الترفيهية المخصصة للعروض الكوميدية الحية، ويشمل عروض ستاند اب كوميدي وغيرها. يوفر خدمة أمنية محكمة وأجواء دافئة، مع توفر الفشار والوجبات الخفيفة داخل القاعة، ويحظى بشعبية متزايدة تجعل حجز التذاكر أصعب مع كل موسم جديد. للتواصل: 0540902020، مواعيد الدوام من 8:00 مساءً حتى 11:30 مساءً (يغلق الاثنين والأربعاء).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069722-68545712.jpg?v=1791556164"]','https://cmsphoto.ww-cdn.com/resizeapi/625ad4c227bd11e3e60c9c96b15821601dd11b0c/480/',21.6317382,39.128733,'7520، الشاطئ، جدة 23413','0540902020','','','https://www.saudi-guide.com/jeddah/i/98069722/the-comedy-club-alkomydy-klob',1,0,'كوميدي كلوب the comedy club سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069609,'asir-region','نادي عسير للرياضات الجوية','Aseer Paragliding Club','aseer-paragliding-club-nady-aasyr-llryadat-algoy','["أماكن سياحية"]','["sights"]','نادي عسير للرياضات الجوية استمتع بتجربة الطيران الشراعي من أعلى قمة جبلية لتحظى برؤية رائعة لا تنسى للمدينة.','<div class="texte" > <p>نادي عسير للرياضات الجوية استمتع بتجربة الطيران الشراعي من أعلى قمة جبلية لتحظى برؤية رائعة لا تنسى للمدينة. يوفر الموقع مضمار إقلاع واسع وسطح أسفلتي مناسب، مع مواقف سيارات تتسع لأكثر من 20 سيارة، ويحظى بتقييم ممتاز من محترفي الطيران الشراعي لجودة التيارات الهوائية. للتواصل: 0552201335.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069609-68545730.jpg?v=1791556303"]','https://cmsphoto.ww-cdn.com/resizeapi/cb74c2b2dc11674df704d49f836edc95285f0ff4/480/',18.656339,42.125949,'آل سعيدان 63725','0552201335','','','https://www.saudi-guide.com/asir-region/i/98069609/aseer-paragliding-club-nady-aasyr-llryadat-algoy',1,0,'نادي عسير للرياضات جويه aseer paragliding club اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069608,'asir-region','وادي السهمين','Valley of the Two Arrows','valley-of-the-two-arrows-oady-alshmyn','["أماكن سياحية"]','["sights"]','من أجمل الأودية التي يمكنك الاستمتاع بطبيعتها، تتميز بجريان الوادي حول الأشجار وشلال منحدر على جانب الطريق.','<div class="texte" > <p>وادي السهمين من أجمل الأودية التي يمكنك الاستمتاع بطبيعتها، تتميز بجريان الوادي حول الأشجار وشلال منحدر على جانب الطريق. يتطلب الوصول لأجمل نقاطه بعض المشي والتسلق البسيط عبر مجرى الوادي، مع إمكانية السباحة في بعض البرك، ويُفضل ارتداء أحذية مناسبة والزيارة في الصباح الباكر.</p> </div>','[]','',18.6839255,41.9377193,'الجزيرة، بيشة 63697','','','','https://www.saudi-guide.com/asir-region/i/98069608/valley-of-the-two-arrows-oady-alshmyn',1,0,'وادي سهمين valley of the two arrows اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069606,'asir-region','محطة العربات المعلقة','Abha Cable Car','abha-cable-car-mht-alaarbat-almaalk','["أماكن سياحية"]','["sights"]','تأخذك العربة في نزهة قصيرة من سماء مدينة أبها تمر بها على معالم متعددة من المدينة وسط أجواء ضبابية متفردة.','<div class="texte" > <p>محطة العربات المعلقة (تلفريك أبها) تأخذك العربة في نزهة قصيرة من سماء مدينة أبها تمر بها على معالم متعددة من المدينة وسط أجواء ضبابية متفردة. تُعد تجربة رومانسية ممتعة خصوصًا وقت المساء حوالي الساعة 6، ويُنصح بالحجز في العطلات لتجنب وقت الانتظار الطويل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069606-68545745.jpg?v=1791556462"]','https://cmsphoto.ww-cdn.com/resizeapi/186a1262d15b41666e2b770ee4dec56b50536b87/480/',18.2101389,42.4849234,'أبها الجديدة، أبها 62512','','','','https://www.saudi-guide.com/asir-region/i/98069606/abha-cable-car-mht-alaarbat-almaalk',1,0,'محطه عربات معلقه abha cable car اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069604,'asir-region','شلالات عين الذيبة','Ain Al Dheebah Waterfalls','ain-al-dheebah-waterfalls-shlalat-aayn-althyb','["أماكن سياحية"]','["sights"]','شلالات عين الذيبة استمتع بمغامرة جبلية لا تنسى حيث التقاء جبلين وتدفق المياه من بينهما لتحظى بتجربة فريدة ومختلفة.','<div class="texte" > <p>شلالات عين الذيبة استمتع بمغامرة جبلية لا تنسى حيث التقاء جبلين وتدفق المياه من بينهما لتحظى بتجربة فريدة ومختلفة. تتطلب المسارات الصخرية بعض اللياقة البدنية، فتُناسب المجموعات الشابة النشيطة أكثر من كبار السن أو الأطفال، ويُنصح بجمع المخلفات والحفاظ على نظافة الموقع.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069604-68545763.jpg?v=1791556608"]','https://cmsphoto.ww-cdn.com/resizeapi/8c19378153f6275c661f3d63cf09ddf6f483ed0f/480/',18.2813826,42.3938078,'السودة، أبها 62535','','','','https://www.saudi-guide.com/asir-region/i/98069604/ain-al-dheebah-waterfalls-shlalat-aayn-althyb',1,0,'شلالات عين ذيبه ain al dheebah waterfalls اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069603,'asir-region','كوخ السرو','Tabab Cypress Cottage','tabab-cypress-cottage-kokh-alsro','["أماكن سياحية"]','["sights"]','كوخ السرو كوخ ريفي بطابع عصري للإقامة المؤقتة وسط مساحة خضراء في أجواء مرتفعات طبب. يتميز بنظافته وجماله وهدوء الموقع المحيط.','<div class="texte" > <p>كوخ السرو كوخ ريفي بطابع عصري للإقامة المؤقتة وسط مساحة خضراء في أجواء مرتفعات طبب. يتميز بنظافته وجماله وهدوء الموقع المحيط، ويُعد وجهة مثالية لكسر الروتين والاستمتاع بأجواء جبلية باردة. للتواصل: 0552723873.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069603-68545767.jpg?v=1791556673"]','https://cmsphoto.ww-cdn.com/resizeapi/49636213067b09f1d3af0804eae4b6a9c13f7095/480/',18.3764824,42.3747605,'طبب 62558','0552723873','','','https://www.saudi-guide.com/asir-region/i/98069603/tabab-cypress-cottage-kokh-alsro',1,0,'كوخ سرو tabab cypress cottage اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069587,'asir-region','مسار التسلق وممشى الدراجات بالسودة','Al Soudah Hiking & Cycling Trail','al-soudah-hiking-cycling-trail-msar-altslk-ommsha-aldragat-balsod','["أماكن سياحية"]','["sights"]','مسار التسلق (هايكنج) وممشى الدراجات بالسودة يتيح لك الاستمتاع بإطلالات ساحرة على تهامة حيث يتوفر مسار للمشي وركوب الدراجات.','<div class="texte" > <p>مسار التسلق (هايكنج) وممشى الدراجات بالسودة يتيح لك الاستمتاع بإطلالات ساحرة على تهامة حيث يتوفر مسار للمشي وركوب الدراجات. يناسب هواة الطبيعة والرياضة الباحثين عن أجواء منعشة، رغم بعض الملاحظات على الحاجة لتنظيم منطقة تخييم رسمية ولافتات إرشادية أوضح لغير المقيمين.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069587-68545790.jpg?v=1791556811"]','https://cmsphoto.ww-cdn.com/resizeapi/f945d5867f11a0e3d7433364cf050b5968f24024/480/',18.2011966,42.4144568,'العزيزة، السودة 62517','','','','https://www.saudi-guide.com/asir-region/i/98069587/al-soudah-hiking-cycling-trail-msar-altslk-ommsha-aldragat-balsod',1,0,'مسار تسلق وممشي دراجات بالسوده al soudah hiking & cycling trail اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069586,'asir-region','مطل العزيزة','Al Azizah Viewpoint','al-azizah-viewpoint-mtl-alaazyz','["أماكن سياحية"]','["sights"]','موقع يجعلك تشهد لحظات الغروب الساحرة من مرتفعات مطلة على القرى الريفية ومناظر تجمع الشجر بالجبل وسط الضباب.','<div class="texte" > <p>مطل العزيزة موقع يجعلك تشهد لحظات الغروب الساحرة من مرتفعات مطلة على القرى الريفية ومناظر تجمع الشجر بالجبل وسط الضباب. يوصى بأخذ الاحتياطات لتقلب الطقس الممطر أحيانًا، وتتوفر دورات مياه للزوار، ويُعد وجهة مثالية لعشاق التصوير الطبيعي.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069586-68545797.jpg?v=1791556881"]','https://cmsphoto.ww-cdn.com/resizeapi/3c42bd2f951f69b86ae52ac563ae14a1625ba68e/480/',18.2228042,42.4312581,'العزيزة، أبها 62518','','','','https://www.saudi-guide.com/asir-region/i/98069586/al-azizah-viewpoint-mtl-alaazyz',1,0,'مطل عزيزه al azizah viewpoint اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069585,'asir-region','عقبة حبو','Aqabat Habu','aqabat-habu-aakb-hbo','["أماكن سياحية"]','["sights"]','عقبة حبو في عسير موقع مثالي لمشاهدة الغروب من مرتفعات تعلو الغيوم، بإطلالات ساحرة على القرى الريفية المجاورة ومزارع الفراولة القريبة.','<div class="texte" > <p>عقبة حبو موقع يمكّنك من مشاهدة لحظات الغروب الساحرة من مرتفعات مطلة على القرى الريفية المجاورة. يُعد من أجمل المناظر الطبيعية في السعودية بإطلالة تعلو الغيوم، ويشتهر بتلفريك يوفر إطلالة رائعة (25 ريالًا للساعة)، وقربه من مزارع الفراولة يجعله محطة إضافية ممتعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069585-68545801.jpg?v=1791556951", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069585-68545802.jpg?v=1791556966"]','https://cmsphoto.ww-cdn.com/resizeapi/85b57f30203bbddec4521ecbadf9c3e9bbb70b5e/480/',18.1705622,42.4238273,'المحاج، أبها 62519','','','','https://www.saudi-guide.com/asir-region/i/98069585/aqabat-habu-aakb-hbo',1,0,'عقبه حبو aqabat habu اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069584,'asir-region','ممر السعادة','Al Saada Trail','al-saada-trail-mmr-alsaaad','["أماكن سياحية"]','["sights"]','ممر السعادة (المعروف أيضًا بعقبة فو القدم) مسار تاريخي ممتد لثمانية كيلومترات يربط بين منطقتين مختلفتين في التضاريس والمناخ، وهو خيار مناسب للهايكنج أو الجري.','<div class="texte" > <p>ممر السعادة (المعروف أيضًا بعقبة فو القدم) مسار تاريخي ممتد لثمانية كيلومترات يربط بين منطقتين مختلفتين في التضاريس والمناخ، وهو خيار مناسب للهايكنج أو الجري. تُعد الإطلالة على قمم الجبال والوديان من أجمل ما يمكن مشاهدته في المنطقة، خصوصًا في الأجواء الضبابية الباردة، رغم حاجة الموقع لتحسين في اللافتات الإرشادية والخدمات. للتواصل: 0502166240.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069584-68545806.jpg?v=1791557032", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069584-68545807.jpg?v=1791557051"]','https://cmsphoto.ww-cdn.com/resizeapi/7243db0215b59e062f6ad5c212c50648d7e8661d/480/',18.3342245,42.3190762,'بني غنمي، أبها 63439','0502166240','','','https://www.saudi-guide.com/asir-region/i/98069584/al-saada-trail-mmr-alsaaad',1,0,'ممر سعاده al saada trail اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069582,'asir-region','اوسان كافية','OSAN Cafe','osan-cafe','["مقاهي"]','["cafe"]','أول مقهى كوري بأسلوب عصري في أبها يقدم أنواعًا مختلفة من البوبا بجانب العديد من المشروبات بنكهات مبتكرة وفريدة.','<div class="texte" > <p>اوسان كافية أول مقهى كوري بأسلوب عصري في أبها يقدم أنواعًا مختلفة من البوبا بجانب العديد من المشروبات بنكهات مبتكرة وفريدة. يشتهر بمشروبات الماتشا بالبوبا وحلوى البينجسو الكورية النادرة في المدينة، ويحظى بأجواء آسيوية مميزة تنقلك لتجربة مختلفة تمامًا. للتواصل: 0595475775، ومواعيد الدوام من 4:00 عصرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069582-68545820.jpg?v=1791557143", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069582-68545825.jpg?v=1791557159"]','https://cmsphoto.ww-cdn.com/resizeapi/84ce0c2b29eebcc46578dced5db7f760d8a6be4d/480/',18.2308788,42.4936245,'طريق الملك عبدالعزيز، الوردتين، أبها 62521','0595475775','','','https://www.saudi-guide.com/asir-region/i/98069582/osan-cafe',1,0,'اوسان كافيه osan cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069579,'asir-region','سبوت','Spot Cafe','spot-cafe-sbot','["مقاهي"]','["cafe"]','سبوت يتفرد بتغير أجواءه في كل فصل من فصول السنة كما يقدم ألذ توست فرنسي في محايل. يقع داخل مجمع تجاري وسط المدينة، ويشتهر بالقهوة المفلترة وقهوة الأورينتال.','<div class="texte" > <p>سبوت يتفرد بتغير أجواءه في كل فصل من فصول السنة كما يقدم ألذ توست فرنسي في محايل. يقع داخل مجمع تجاري وسط المدينة، ويشتهر بالقهوة المفلترة وقهوة الأورينتال، ويناسب زوار محايل عسير الباحثين عن استراحة قهوة مريحة. للتواصل: 0531862013، ومواعيد الدوام من 6:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069579-68545830.jpg?v=1791557290", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069579-68545831.jpg?v=1791557304"]','https://cmsphoto.ww-cdn.com/resizeapi/83d1d848ed3221c02858e9e838e2fbf56b08ea07/480/',18.5435468,42.0377198,'طريق الملك فيصل، الخالدية، محايل عسير 63687','0531862013','','','https://www.saudi-guide.com/asir-region/i/98069579/spot-cafe-sbot',1,0,'سبوت spot cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069578,'asir-region','مقهى سذاب','Sthab Cafe','sthab-cafe-mkha-sthab','["مقاهي"]','["cafe"]','مقهى سذاب بأجواء دافئة ما بين الماضي والحاضر يقدم القهوة والحلويات لتستمتع بطعم فريد. اسمه مستوحى من نبتة السذاب العطرية المعروفة في جنوب السعودية.','<div class="texte" > <p>مقهى سذاب بأجواء دافئة ما بين الماضي والحاضر يقدم القهوة والحلويات لتستمتع بطعم فريد. اسمه مستوحى من نبتة السذاب العطرية المعروفة في جنوب السعودية، بديكور مستوحى من مقاهي الأجواء الكورية الهادئة. مواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069578-68545840.jpg?v=1791557404", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069578-68545842.jpg?v=1791557421"]','https://cmsphoto.ww-cdn.com/resizeapi/174b4756a84fd04daa57cfd8e47e0d735d8fe07d/480/',18.2002349,42.505129,'شارع بيض، الدباب، أبها 62522','','','','https://www.saudi-guide.com/asir-region/i/98069578/sthab-cafe-mkha-sthab',1,0,'مقهي سذاب sthab cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069577,'asir-region','محمصة ومقهى فلنت','Flint','flint-mhms-omkha-flnt','["مقاهي"]','["cafe"]','محمصة ومقهى فلنت مقهى ومحمصة يتميز بتقديم مشروبات صيفية شهية بالقهوة والآيس كريم بجانب العديد من الحلويات.','<div class="texte" > <p>محمصة ومقهى فلنت مقهى ومحمصة يتميز بتقديم مشروبات صيفية شهية بالقهوة والآيس كريم بجانب العديد من الحلويات. يشتهر بالكوكيز الطرية الدافئة واللاتيه الإسباني، ويحظى بأجواء دافئة وودودة من الطاقم داخل مجمع جاردن سكوير. للتواصل: 0532078781، ومواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069577-68545853.jpg?v=1791557521"]','https://cmsphoto.ww-cdn.com/resizeapi/f6d08c819af6d3f376110e903b99197094fb0476/480/',18.2314208,42.4981836,'مجمع جاردن سكوير، طريق الملك عبدالعزيز، الوردتين، أبها 62521','0532078781','','','https://www.saudi-guide.com/asir-region/i/98069577/flint-mhms-omkha-flnt',1,0,'محمصه ومقهي فلنت flint مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069576,'asir-region','اوكاف','Okaf','okaf-aokaf','["مقاهي"]','["cafe"]','اوكاف يتميز بتقديم الوافل بنكهات متعددة شهية كما يقدم القهوة بجميع أنواعها لتستمتع بمزيج رائع. يشتهر بالكافيه لاتيه وتمر السايس.','<div class="texte" > <p>اوكاف يتميز بتقديم الوافل بنكهات متعددة شهية كما يقدم القهوة بجميع أنواعها لتستمتع بمزيج رائع. يشتهر بالكافيه لاتيه وتمر السايس، ويحظى بأجواء هادئة داخلية وخارجية رغم صغر مساحته. مواعيد الدوام من 7:00 صباحًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069576-68545867.jpg?v=1791557614", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069576-68545869.jpg?v=1791557632"]','https://cmsphoto.ww-cdn.com/resizeapi/4239653cf9039977c40089073ff587cae57d37d6/480/',18.2304433,42.5482592,'طريق الملك فهد الفرعي، العارن، أبها 62528','','','','https://www.saudi-guide.com/asir-region/i/98069576/okaf-aokaf',1,0,'اوكاف okaf مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069575,'asir-region','مقهى كوف','Cove','cove-mkha-kof','["مقاهي"]','["cafe"]','مقهى كوف متعة الأجواء الجنوبية الدافئة مع أجود أنواع القهوة ويتميز بالبن اليمني. يشتهر بحلوى البيكان اللذيذة.','<div class="texte" > <p>مقهى كوف متعة الأجواء الجنوبية الدافئة مع أجود أنواع القهوة ويتميز بالبن اليمني. يشتهر بحلوى البيكان اللذيذة، ويحظى بخدمة راقية واهتمام بالتفاصيل رغم مساحته الصغيرة نسبيًا. للتواصل: 0556098865، ومواعيد الدوام من 7:00 مساءً حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069575-68545889.jpg?v=1791557706", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069575-68545891.jpg?v=1791557722"]','https://cmsphoto.ww-cdn.com/resizeapi/b58c45b4c93599f5d4141aa40d68a1719747caf9/480/',18.2405542,42.6426183,'الروضة، حي المطار، أبها 62437','0556098865','','','https://www.saudi-guide.com/asir-region/i/98069575/cove-mkha-kof',1,0,'مقهي كوف cove مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069574,'asir-region','ناش','Nash','nash-nash','["مقاهي"]','["cafe"]','ناش مقهى بطابع ريفي في عسير يقدم قهوة مختصة وأطباق إفطار، ويشتهر باللاتيه وكيك العسل وسط ديكور جذاب يناسب جلسات التصوير.','<div class="texte" > <p>ناش مقهى بطابع ريفي يقدم قهوة مختصة وأطباقًا خاصة بالإفطار والمكان معد لجلسات التصوير. يشتهر باللاتيه وكيك العسل، بديكور جذاب يجمع بين الطابع الريفي والحديث، ويُنصح بالحجز في أوقات الذروة الصيفية. للتواصل: 0550555343، ومواعيد الدوام من 7:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069574-68551987.jpg?v=1791636103", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069574-68551988.jpg?v=1791636113"]','https://cmsphoto.ww-cdn.com/resizeapi/22931e89b75a07ab15cc904c040ceb6e574ac3a4/480/',18.2387023,42.5820281,'طريق الملك فهد، المحالة، أبها 62561','0550555343','','','https://www.saudi-guide.com/asir-region/i/98069574/nash-nash',1,0,'ناش nash مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069573,'asir-region','دبليو','Doubleyou','doubleyou-dblyo','["مقاهي"]','["cafe"]','دبليو يتميز بجودة المشروبات وحبوب قهوة رائعة وكذلك بأسعار منافسة ويقدم فقط المخبوزات الفرنسية. يحظى بشعبية كبيرة وأجواء دافئة سعودية أصيلة.','<div class="texte" > <p>دبليو يتميز بجودة المشروبات وحبوب قهوة رائعة وكذلك بأسعار منافسة ويقدم فقط المخبوزات الفرنسية. يحظى بشعبية كبيرة وأجواء دافئة سعودية أصيلة، ويشتهر بالمشروبات المنعشة والخدمة الودودة من طاقم العمل. للتواصل: 0552021819، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069573-68545913.jpg?v=1791557861", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069573-68545918.jpg?v=1791557880"]','https://cmsphoto.ww-cdn.com/resizeapi/f9712eaa3ed1745917b99b491705999ba22715f6/480/',18.2651869,42.642852,'طريق الملك فهد، حجلة، خميس مشيط 62563','0552021819','','','https://www.saudi-guide.com/asir-region/i/98069573/doubleyou-dblyo',1,0,'دبليو doubleyou مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069568,'asir-region','لا دوز كافيه','La Dose Café','la-dose-cafe-la-doz-kafyh','["مقاهي"]','["cafe"]','لا دوز كافيه مقهى من ثلاثة طوابق بتراسات تطل على المدينة والمناظر الخضراء، يقدم أصنافًا منوعة من القهوة المختصة والحلويات.','<div class="texte" > <p>لا دوز كافيه أجواء وديكورات مميزة بإطلالة فاخرة يقدم أصنافًا منوعة من القهوة المختصة والحلويات. يتميز بتصميم من ثلاثة طوابق مع تراسات تطل على المدينة ومناظر خضراء جميلة، رغم صعوبة إيجاد موقف سيارات أحيانًا لقربه من الدوار الرئيسي. للتواصل: 0536663477.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069568-68545923.jpg?v=1791557940", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069568-68545925.jpg?v=1791557955"]','https://cmsphoto.ww-cdn.com/resizeapi/dfecf3e8d2a5a199d73cd534ad5018b348b75497/480/',18.2037802,42.4934062,'حزام، طريق الملك عبدالعزيز، الشفا، أبها 62521','0536663477','','','https://www.saudi-guide.com/asir-region/i/98069568/la-dose-cafe-la-doz-kafyh',1,0,'لا دوز كافيه la dose café مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069567,'asir-region','نمق كافيه','Namq','namq-nmk-kafyh','["مقاهي"]','["cafe"]','نمق كافيه مقهى مستوحى اسمه من الزينة والحسن، يتميز بديكوره التراثي الأنيق وطابعه الجذاب وخدمته الممتازة في منطقة عسير.','<div class="texte" > <p>نمق كافيه مستوحى اسمه من الزينة والحسن ويتميز بطابعه الجذاب. يشتهر بديكوره التراثي الأنيق ويحظى بخدمة ممتازة من الطاقم رغم الازدحام أحيانًا، ويعمل على مدار الساعة طوال أيام الأسبوع.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069567-68545938.jpg?v=1791558022"]','https://cmsphoto.ww-cdn.com/resizeapi/28a3f6c70111dc96d4ac13ec8257964a6a82a6df/480/',18.238233,42.6437914,'دوار، مول سفن، مطار، أبها 62586','0599649105','','','https://www.saudi-guide.com/asir-region/i/98069567/namq-nmk-kafyh',1,0,'نمق كافيه namq مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069566,'asir-region','وزاب كافيه','Wezzab Café','wezzab-cafe-ozab-kafyh','["مقاهي"]','["cafe"]','وزاب كافيه مستلهم من نبتة الوزاب العطرية التي تضاف إلى الشاي، بصمة مختلفة في مقاهي المنطقة. يشتهر بالشاي المميز وخبز القرص بالجبنة والشاورما الحلية.','<div class="texte" > <p>وزاب كافيه مستلهم من نبتة الوزاب العطرية التي تضاف إلى الشاي، بصمة مختلفة في مقاهي المنطقة. يشتهر بالشاي المميز وخبز القرص بالجبنة والشاورما الحلية، ويوفر خدمة ذاتية بأسعار معقولة جدًا. للتواصل: 0562414479، ومواعيد الدوام من 6:30 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069566-68545961.jpg?v=1791558085", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069566-68545964.jpg?v=1791558101"]','https://cmsphoto.ww-cdn.com/resizeapi/1f95ae44b236739fadfd080200d1ae923ed8c1e9/480/',18.2086772,42.6561118,'طريق المية، تقاطع المطار، أبها 62439','0562414479','','','https://www.saudi-guide.com/asir-region/i/98069566/wezzab-cafe-ozab-kafyh',1,0,'وزاب كافيه wezzab café مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069565,'asir-region','دكة شاي','Dakat Shay','dakat-shay-dk-shay','["مقاهي"]','["cafe"]','دكة شاي وجهة لمحبي الشاي وخبز التنور الجنوبي بأعشاب المنطقة العطرية، يشتهر بالسمبوسة والخبز الطازج في أجواء دافئة بسيطة.','<div class="texte" > <p>دكة شاي وجهة لمحبي الشاي وخبز التنور الجنوبي يجمع بين البساطة والحداثة بأعشاب المنطقة العطرية. يشتهر بالسمبوسة والخبز الطازج من التنور، ويعمل على مدار الساعة، ويحظى بأجواء دافئة تستحق الزيارة لعشاق الشاي التقليدي. للتواصل: 0530107086.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069565-68545968.jpg?v=1791558175", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069565-68545972.jpg?v=1791558195"]','https://cmsphoto.ww-cdn.com/resizeapi/95c291ae303db9bab8ea0c952b664df8fed96a03/480/',18.2097647,42.6576779,'طريق الأمير سعد بن عبدالرحمن الأول، أبها 62219','0530107086','','','https://www.saudi-guide.com/asir-region/i/98069565/dakat-shay-dk-shay',1,0,'دكه شاي dakat shay مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069564,'asir-region','ملء','mIL','mil-ml','["مقاهي"]','["cafe"]','ملء (mIL) مقهى بأجواء دافئة كالمنزل يقدم أصنافًا منوعة من القهوة وحلويات تُصنع يوميًا، مع شرفة علوية بإطلالة ساحرة على المدينة.','<div class="texte" > <p>ملء (mIL) أجواء دافئة وديكور مميز كمنزل بإطلالة فاخرة يقدم أصنافًا منوعة من القهوة ضمن جلسات مريحة. يشتهر بالشوكولاتة الساخنة والحلويات المصنوعة يوميًا في الموقع، مع شرفة علوية بإطلالة ساحرة على المدينة. مواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069564-68545978.jpg?v=1791558284", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069564-68545982.jpg?v=1791558306"]','https://cmsphoto.ww-cdn.com/resizeapi/52d6faaaa346292343eb3ddb17992b173b65af92/480/',18.219346,42.4800691,'خالد الفيصل، الخالدية، أبها 62541','','','','https://www.saudi-guide.com/asir-region/i/98069564/mil-ml',1,0,'ملء mil مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069563,'asir-region','خطوة جمل','Camel Step','camel-step-khto-gml','["مقاهي"]','["cafe"]','تلذذ بالقهوة بطعمها الأصلي، يضم محمصة لأصناف عالمية من القهوة في جلسات هادئة وديكورات مصممة بأناقة. مقهى.','<div class="texte" > <p>خطوة جمل (Camel Step) تلذذ بالقهوة بطعمها الأصلي، يضم محمصة لأصناف عالمية من القهوة في جلسات هادئة وديكورات مصممة بأناقة تستلهم من الطبيعة العسيرية. تصميمه الداخلي يجمع بين الحجر والخشب والروطان بمساحة 370 مترًا مربعًا، ويحظى بتقييمات ممتازة لجودة الإسبريسو رغم أسعاره المرتفعة قليلًا. للتواصل: 920000689، ومواعيد الدوام من 6:30 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069563-68545988.jpg?v=1791558403", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069563-68545991.jpg?v=1791558426"]','https://cmsphoto.ww-cdn.com/resizeapi/9a482e21211d0526c25f10500ef22c0e44817663/480/',18.2101783,42.4943449,'سعود بن عبدالعزيز، حي المفتاحة، أبها 62521','920000689','','','https://www.saudi-guide.com/asir-region/i/98069563/camel-step-khto-gml',1,0,'خطوه جمل camel step مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069561,'asir-region','سماري','Samari','samari-smary','["مقاهي"]','["cafe"]','مكان بطابع حضاري وكلاسيكي مستلهم من المباني العسيرية القديمة وهو مناسب لقضاء وقت ممتع بخيارات قائمتهم المتنوعة. مقهى.','<div class="texte" > <p>سماري مكان بطابع حضاري وكلاسيكي مستلهم من المباني العسيرية القديمة وهو مناسب لقضاء وقت ممتع بخيارات قائمتهم المتنوعة. يشتهر بالسمبوسة الدجاج والمنقوشة والشاي الجمر، ويحظى بأجواء وخدمة ممتازة تجعله وجهة محببة للجلوس الطويل. مواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069561-68546013.jpg?v=1791558562"]','https://cmsphoto.ww-cdn.com/resizeapi/1d055e65a2c6c840809ad0df8c67136e8e620d59/480/',18.2310724,42.49855,'طريق الملك عبدالعزيز، الوردتين، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98069561/samari-smary',1,0,'سماري samari مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069558,'asir-region','مقهى جيا','Gia','gia-mkha-gya','["مقاهي"]','["cafe"]','مقهى جيا مقهى أنيق يقدم القهوة المختصة ويتميز بتصميمه المميز. يشتهر بمشروب الفلات وايت والحلويات المصاحبة له كالكوكيز وفطيرة البيكان.','<div class="texte" > <p>مقهى جيا مقهى أنيق يقدم القهوة المختصة ويتميز بتصميمه المميز. يشتهر بمشروب الفلات وايت والحلويات المصاحبة له كالكوكيز وفطيرة البيكان، ويحظى بأجواء رائعة تناسب اللقاءات مع الأصدقاء أو العمل. للتواصل: 0537547567، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069558-68546031.jpg?v=1791558659", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069558-68546032.jpg?v=1791558671"]','https://cmsphoto.ww-cdn.com/resizeapi/edc235bf8a41286a24de3f4826d47bad10461165/480/',18.2261288,42.5084894,'شارع الرياض، أبها 62521','0537547567','','','https://www.saudi-guide.com/asir-region/i/98069558/gia-mkha-gya',1,0,'مقهي جيا gia مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069557,'asir-region','نواة','Nawah','nawah-noa','["مقاهي"]','["cafe"]','نواة مكان راقي يجمع بين الراحة والفعاليات الثقافية الموسمية التي ترضي كل الأذواق، ويوفر جلسات خارجية جميلة للاستمتاع بالهواء الطلق.','<div class="texte" > <p>نواة مكان راقي يجمع بين الراحة والفعاليات الثقافية الموسمية التي ترضي كل الأذواق، ويوفر جلسات خارجية جميلة للاستمتاع بالهواء الطلق. يستضيف فعاليات ثقافية وفنية دورية، ويعمل على مدار الساعة طوال أيام الأسبوع. للتواصل: 0542814044.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069557-68546050.jpg?v=1791558744"]','https://cmsphoto.ww-cdn.com/resizeapi/0d5636e5c45c5c6addeab33a69f46bc7e66b3df7/480/',18.2158372,42.5494938,'المروج، أبها 62527','0542814044','','','https://www.saudi-guide.com/asir-region/i/98069557/nawah-noa',1,0,'نواه nawah مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069556,'asir-region','خواطر','Khawater','khawater-khoatr','["مقاهي"]','["cafe"]','وجهة مناسبة لمحبي الفن التشكيلي، يعرض لوحات ويوفر خدمة الرسم للأطفال والكبار بجانب قائمة من الحلويات والقهوة المتنوعة. مقهى.','<div class="texte" > <p>خواطر وجهة مناسبة لمحبي الفن التشكيلي، يعرض لوحات ويوفر خدمة الرسم للأطفال والكبار بجانب قائمة من الحلويات والقهوة المتنوعة. يجمع بين المقهى ومساحة العرض الفني بأسلوب إبداعي فريد، ويُعد وجهة مميزة لعشاق الفن الباحثين عن تجربة مختلفة. للتواصل: 0500464228، ومواعيد الدوام من 4:00 عصرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069556-68546063.jpg?v=1791558832", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069556-68546067.jpg?v=1791558853"]','https://cmsphoto.ww-cdn.com/resizeapi/17175bdb8d7efb52a8e4ebb04263976cdc270c77/480/',18.2204663,42.5175681,'طريق الملك فهد، المنهل، أبها 62521','0500464228','','','https://www.saudi-guide.com/asir-region/i/98069556/khawater-khoatr',1,0,'خواطر khawater مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069555,'asir-region','بلومينق','Blooming','blooming-blomynk','["مقاهي"]','["cafe"]','بلومينق يوفر هذا المقهى تجربة إفطار فاخرة ضمن جلسات مطلة بخيارات مختلفة، بأجواء دافئة تناسب بداية اليوم بهدوء.','<div class="texte" > <p>بلومينق يوفر هذا المقهى تجربة إفطار فاخرة ضمن جلسات مطلة بخيارات مختلفة، بأجواء دافئة تناسب بداية اليوم بهدوء. يشتهر بأطباق الإفطار المتنوعة والقهوة المختصة، ويحظى بموقع سهل الوصول في السراوات. مواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069555-68546081.jpg?v=1791558952", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069555-68546084.jpg?v=1791558966"]','https://cmsphoto.ww-cdn.com/resizeapi/7bc99eeabc4a9825c13c1ab6328d3c3386f94d9a/480/',18.2049787,42.4920161,'طريق الملك عبدالعزيز، السراوات، أبها 62511','','','','https://www.saudi-guide.com/asir-region/i/98069555/blooming-blomynk',1,0,'بلومينق blooming مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069554,'asir-region','مقهى بكر','Bakr','bakr-mkha-bkr','["مقاهي"]','["cafe"]','مقهى بكر بتفاصيل أنيقة وبار مفتوح ونكهات جديدة وخيارات جلوس متنوعة، بأجواء راقية هادئة تناسب الاسترخاء مع قهوة لذيذة.','<div class="texte" > <p>مقهى بكر تفاصيل أنيقة تميز هذا المكان، بار مفتوح ونكهات جديدة وخيارات جلوس متنوعة. توسّع من مكان صغير في بداياته إلى مقهى أكبر مع الحفاظ على جودة القهوة اللذيذة نفسها، ويحظى بأجواء راقية هادئة تناسب التأمل والاسترخاء. للتواصل: 0503850687، ومواعيد الدوام من 6:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069554-68546094.jpg?v=1791559048", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069554-68546097.jpg?v=1791559071"]','https://cmsphoto.ww-cdn.com/resizeapi/ade15e985ca72ccb689bf8e22c779e9f09aab6f0/480/',18.212935,42.5208984,'طريق الملك عبدالعزيز، الأندلس، أبها 62521','0503850687','','','https://www.saudi-guide.com/asir-region/i/98069554/bakr-mkha-bkr',1,0,'مقهي بكر bakr مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069553,'asir-region','امبريللو','Umbrello','umbrello-ambryllo','["مقاهي"]','["cafe"]','امبريللو يتميز بمخبوزاته الطازجة وإطلالته وجلساته المرتفعة يقدم أصنافًا متنوعة من القهوة والحلويات. يشتهر بكيك الموز اللذيذ.','<div class="texte" > <p>امبريللو يتميز بمخبوزاته الطازجة وإطلالته وجلساته المرتفعة يقدم أصنافًا متنوعة من القهوة والحلويات. يشتهر بكيك الموز اللذيذ، ويحظى بأجواء هادئة وأنيقة تذكّر بمقاهي ملبورن الشهيرة، وهو خيار مثالي للاسترخاء وتنظيم الأفكار. للتواصل: 0561313751، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069553-68546106.jpg?v=1791559172"]','https://cmsphoto.ww-cdn.com/resizeapi/f1a6e8dd12e347f18e4bc6aeb281a594b0cf799d/480/',18.2049787,42.4920161,'طريق الملك عبدالعزيز، السراوات، أبها 62511','0561313751','','','https://www.saudi-guide.com/asir-region/i/98069553/umbrello-ambryllo',1,0,'امبريللو umbrello مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069552,'asir-region','فيفث افنيو','5th Avenue','5th-avenue-fyfth-afnyo','["مقاهي"]','["cafe"]','فيفث افنيو مقهى يتميز بتقديمه مختلف أنواع القهوة بأجود أنواع البن بالإضافة إلى أصناف الحلويات المتنوعة.','<div class="texte" > <p>فيفث افنيو مقهى يتميز بتقديمه مختلف أنواع القهوة بأجود أنواع البن بالإضافة إلى أصناف الحلويات المتنوعة. يشتهر بأجوائه الهادئة المناسبة للعمل والتركيز، ويحظى بتقييمات ممتازة لجودة القهوة وحسن الخدمة. مواعيد الدوام من 7:30 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069552-68546114.jpg?v=1791559247", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069552-68546118.jpg?v=1791559260"]','https://cmsphoto.ww-cdn.com/resizeapi/485546de7e4750acb1ec612da169c173d6792512/480/',18.231054,42.4984854,'طريق الملك عبدالعزيز، الوردتين، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98069552/5th-avenue-fyfth-afnyo',1,0,'فيفث افنيو 5th avenue مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069551,'asir-region','ايت اوز','8oz Coffee','8oz-coffee-ayt-aoz','["مقاهي"]','["cafe"]','مقهى من طابقين بجلسات هادئة وديكورات مصممة بعناية وعرض قائمة منوعة من خيارات القهوة والحلويات. مقهى.','<div class="texte" > <p>ايت اوز (8oz Coffee) مقهى من طابقين بجلسات هادئة وديكورات مصممة بعناية وعرض قائمة منوعة من خيارات القهوة والحلويات. يشتهر بمشروب الأوز لاتيه البارد، ويحظى بشعبية كبيرة لمشاهدة المباريات الرياضية بشاشات كبيرة، ويعمل على مدار الساعة. للتواصل: 0500676541.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069551-68546123.jpg?v=1791559333"]','https://cmsphoto.ww-cdn.com/resizeapi/df55877de85b694f840ec8ba302fbaec0f8959a5/480/',18.2426938,42.6113723,'طريق الملك فهد، سر الغالض، أبها 62521','0500676541','','','https://www.saudi-guide.com/asir-region/i/98069551/8oz-coffee-ayt-aoz',1,0,'ايت اوز 8oz coffee مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069547,'asir-region','طبق الفخار','Tabaq Al Fakhar','tabaq-al-fakhar','["مطاعم"]','["food"]','بطابع تراثي مميز يقدم أطباقًا واسعة ومتنوعة من الإفطار حتى العشاء كما يتميز بتقديم طبق المشاوي المثالي. يشتهر بالشاورما الطازجة وأطباق الإفطار الشعبي، ويوفر مواقف سيارات متاحة وقسمًا عائليًا مريحًا. مطعم مميز.','<div class="texte" > <p>طبق الفخار بطابع تراثي مميز يقدم أطباقًا واسعة ومتنوعة من الإفطار حتى العشاء كما يتميز بتقديم طبق المشاوي المثالي. يشتهر بالشاورما الطازجة وأطباق الإفطار الشعبي، ويوفر مواقف سيارات متاحة وقسمًا عائليًا مريحًا. للتواصل: 0581953536، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069547-68546136.jpg?v=1791559462", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069547-68546138.jpg?v=1791559483"]','https://cmsphoto.ww-cdn.com/resizeapi/96a0aa3a321df63012199d3722bf43490e6e2ce4/480/',18.2078305,42.5012028,'طريق الإمام عبدالرحمن بن فيصل بن تركي، الشفا، أبها 62521','0581953536','','','https://www.saudi-guide.com/asir-region/i/98069547/tabaq-al-fakhar',1,0,'طبق فخار tabaq al fakhar مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069546,'asir-region','جورنو','Giorno','giorno-gorno','["مطاعم"]','["food"]','جورنو يستمتع زواره بالأطباق الإيطالية بنكهتها الأصلية بإطلالة رائعة على شرفة جبل تهامة. يشتهر بشوربة الذرة الكريمية والفوتشيلي جورنو.','<div class="texte" > <p>جورنو يستمتع زواره بالأطباق الإيطالية بنكهتها الأصلية بإطلالة رائعة على شرفة جبل تهامة. يشتهر بشوربة الذرة الكريمية والفوتشيلي جورنو، ويحظى بخدمة استقبال ودودة ومساحات داخلية وخارجية تناسب الفطور والغداء والعشاء. للتواصل: 0552580280، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069546-68546155.jpg?v=1791559561", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069546-68546156.jpg?v=1791559579"]','https://cmsphoto.ww-cdn.com/resizeapi/63cebeefd0d7390a4a6eaa8f187731316a1a547d/480/',18.1984287,42.5074418,'شارع بيض، الدباب، أبها 62522','0552580280','','','https://www.saudi-guide.com/asir-region/i/98069546/giorno-gorno',1,0,'جورنو giorno مطاعم',strftime('%s','now'));
