INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069506,'asir-region','ريزو لافاندا','Rizzo Lavanda','rizzo-lavanda-ryzo-lafanda','["مطاعم"]','["food"]','ريزو لافاندا يأخذك نحو إيطاليا بأطباقها الشهيرة، البيتزا وأصناف متعددة من الباستا في جلسات بخصوصية عالية داخل مول لافندا بارك.','<div class="texte" > <p>ريزو لافاندا يأخذك نحو إيطاليا بأطباقها الشهيرة، البيتزا وأصناف متعددة من الباستا في جلسات بخصوصية عالية داخل مول لافندا بارك. يشتهر بالفيتوتشيني الألفريدو والبيتزا الهوائية، ويحظى بديكور أنيق دافئ يذكّر بأجواء إيطاليا الأصيلة. للتواصل: 0546360222، ومواعيد الدوام من 12:00 ظهرًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069506-68546213.jpg?v=1791559977"]','https://cmsphoto.ww-cdn.com/resizeapi/6ce302e22b2b40e2cf5230010a6ebbd449bd4920/480/',18.2405466,42.6045149,'لافندا بارك مول، المزوين، أبها 62583','0546360222','','','https://www.saudi-guide.com/asir-region/i/98069506/rizzo-lavanda-ryzo-lafanda',1,0,'ريزو لافاندا rizzo lavanda مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069505,'asir-region','ڤيردي','Verde','verde-vyrdy','["مطاعم"]','["food"]','يقدم أطباق متنوعة من المأكولات الفرنسية والإيطالية والأسبانية لتعيشوا تجربة رحلة حول دول البحر المتوسط. مطعم مميز.','<div class="texte" > <p>ڤيردي يقدم أطباقًا متنوعة من المأكولات الفرنسية والإيطالية والأسبانية لتعيشوا تجربة رحلة حول دول البحر المتوسط، ويشتهر بالبيتزا بلحم الضأن وسلطة الدجاج المشوي. يحظى بأجواء فاخرة تناسب أمسيات المواعدة، مع خدمة استقبال دافئة ومراعاة احتياجات النباتيين. للتواصل: 0535853000، ومواعيد الدوام من 12:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069505-68546228.jpg?v=1791560064", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069505-68546232.jpg?v=1791560092"]','https://cmsphoto.ww-cdn.com/resizeapi/a27f205cc9877917ad2d3e5e52ec813fa4df050a/480/',18.277725,42.7252039,'الشفا، خميس مشيط 62433','0535853000','','','https://www.saudi-guide.com/asir-region/i/98069505/verde-vyrdy',1,0,'ڤيردي verde مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069503,'asir-region','مطعم ريزو','Rizzo','rizzo-mtaam-ryzo','["مطاعم"]','["food"]','مطعم ريزو نحو إيطاليا بأطباقها الشهيرة، البيتزا وأصناف متعددة من الباستا في جلسات بخصوصية عالية داخل مجمع بارك فيو أبها.','<div class="texte" > <p>مطعم ريزو نحو إيطاليا بأطباقها الشهيرة، البيتزا وأصناف متعددة من الباستا في جلسات بخصوصية عالية داخل مجمع بارك فيو أبها. يشتهر ببيتزا المارغريتا وبيتزا الترافل، ويحظى بديكور أنيق وخصوصية عالية رغم أسعاره المرتفعة نسبيًا. للتواصل: 0172260222، ومواعيد الدوام من 12:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069503-68546253.jpg?v=1791560169", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069503-68546258.jpg?v=1791560184"]','https://cmsphoto.ww-cdn.com/resizeapi/a6715ef2df4cf89a1727994b090f7cf1da74c91c/480/',18.2281341,42.5441486,'طريق الملك فهد، العارن، أبها 62528','0172260222','','','https://www.saudi-guide.com/asir-region/i/98069503/rizzo-mtaam-ryzo',1,0,'مطعم ريزو rizzo مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069502,'asir-region','اكليل','Ekleel','ekleel-aklyl','["مطاعم"]','["food"]','اكليل نكهة الطعم اللبناني بين المقبلات والمحاشي والمشويات والمكونات ذات الجودة العالية. يشتهر بكباب الطاجن والخشخاش وسلطتي الروكا والبنجر.','<div class="texte" > <p>اكليل نكهة الطعم اللبناني بين المقبلات والمحاشي والمشويات والمكونات ذات الجودة العالية. يشتهر بكباب الطاجن والخشخاش وسلطتي الروكا والبنجر، ويحظى بموقع سهل الوصول ومواقف سيارات متوفرة رغم بعض الملاحظات على وقت الانتظار. للتواصل: 0500103431، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069502-68546268.jpg?v=1791560250", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069502-68546273.jpg?v=1791560263"]','https://cmsphoto.ww-cdn.com/resizeapi/71720f2ff0be2c20ad2a846b9d426d60dd6035af/480/',18.2174804,42.5219573,'حي الأندلس، طريق الملك عبدالعزيز، أبها 62521','0500103431','','','https://www.saudi-guide.com/asir-region/i/98069502/ekleel-aklyl',1,0,'اكليل ekleel مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069501,'asir-region','مهراني','Mahrani','mahrani-mhrany','["مطاعم"]','["food"]','مهراني تجربة شيقة يقدم المأكولات الهندية من البرياني والطواجن واللحوم بطريقة عصرية، ويشتهر بكباب الدجاج والضأن والمشروبات المنعشة.','<div class="texte" > <p>مهراني تجربة شيقة يقدم المأكولات الهندية من البرياني والطواجن واللحوم بطريقة عصرية، ويشتهر بكباب الدجاج والضأن والمشروبات المنعشة. يحظى بشعبية كبيرة وأجواء حيوية مع أقسام منفصلة للعائلات والأفراد، ويُعد من أفضل المطاعم الهندية في أبها. للتواصل: 0552576655، ومواعيد الدوام من 12:00 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069501-68546907.jpg?v=1791565812", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069501-68546909.jpg?v=1791565823"]','https://cmsphoto.ww-cdn.com/resizeapi/e7c3574c36c586ff67d05bcae155ac4f7ade86ec/480/',18.2174371,42.5225502,'حي الربوة، طريق الملك عبدالعزيز، أبها 62523','0552576655','','','https://www.saudi-guide.com/asir-region/i/98069501/mahrani-mhrany',1,0,'مهراني mahrani مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938436,'albaha','متحف ومقهى الأخوين','Al Akhawain Museum and Cafe','al-akhawain-museum-and-cafe-mthf-omkha-alakhoyn','["التراث والثقافة"]','["heritage"]','متحف ومقهى الأخوين في الباحة متحف مختص بتاريخ المنطقة وتراثها، يضم مقهى شعبياً واستوديو لالتقاط صور تذكارية بالأزياء التقليدية.','<div class="texte" > <p>يختص متحف الأخوين بمنطقة الباحة وتاريخها وفيه مقهى شعبي واستوديو تصوير ليتمكن أي زائر من الحصول على صورة تذكارية&nbsp;مرتدياً أزياء المنطقة&nbsp;في محاكاة للواقع القديم في منطقة الباحة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938436-44538133.jpg?v=1639324101"]','https://cmsphoto.ww-cdn.com/resizeapi/d40eadccce403a9fc9cf50af41669391e09e438c/480/',20.011868,41.4982751,'King Abdulaziz Rd Alrabwah Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59938436/al-akhawain-museum-and-cafe-mthf-omkha-alakhoyn',1,0,'متحف ومقهي اخوين al akhawain museum and cafe تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938435,'albaha','متحف الباحة الإقليمي','Al Baha Regional Museum','al-baha-regional-museum-mthf-albah-alaklymy','["التراث والثقافة"]','["heritage"]','متحف الباحة الإقليمي في غابة رغدان يعرض أحافير وقطعاً أثرية تعود للعصر الحجري وما قبل الميلاد، إلى جانب مخطوطات ومقتنيات تراثية.','<div class="texte" > <p>متحف الباحة، أحد متاحف منطقة الباحة، تأسس عام 1424 هـ، يعرض المتحف قطعا وأحافير وأدوات قديمة تعود للعهد الحجري، وإلى عهود ما قبل الميلاد بأكثر من 3500 سنة، إضافة إلى عرضه للعديد من القطع الأثرية للعصر الموستيري، وتصدرت نسخة المصحف الشريف التي أهداها نايف بن عبد العزيز لمتحف الباحة ويعود تاريخها للعام 1280 هـ ، وقد أُقيم المتحف في بداياته في مبنى مستأجر حتى تم إنشاء مقر دائم له من وكالة الآثار والمتحف حيث أختارت غابة رغدان موقعاً مناسباً له.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938435-44538135.jpg?v=1639323963"]','https://cmsphoto.ww-cdn.com/resizeapi/3446cc26fc1d252e820f2d72940917ab01f73590/480/',20.0247829,41.4439266,'الحزم الحازم الباحة','','','','https://www.saudi-guide.com/albaha/i/59938435/al-baha-regional-museum-mthf-albah-alaklymy',1,0,'متحف باحه اقليمي al baha regional museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938432,'albaha','قلعة الملد الأثرية','Al Malad Castle','al-malad-castle-klaa-almld-alathry','["التراث والثقافة"]','["heritage"]','قلعة الملد الأثرية في الباحة حصنان متجاوران بُنيا قديماً للمراقبة وتخزين الغذاء، على طريق التجارة القديم المتجه جنوباً نحو عسير.','<div class="texte" > <p>تعد قلعة الملد واحدة من أهم المعالم التاريخية في القرية وهي عبارة عن&nbsp;حِصنين متجاورين كانا لشقيقين قاما ببنائهما قديماً للمراقبة الحربية وجعلا منهما مستودعا للأغذية، ويجاور هذين البرجين مبنى كانت تُبرم فيه اتفاقيات الصلح بين القبائل وتعقد فيه الصفقات التجارية في قديم الزمان حيث يقعان على طريق التجارة القديم المؤدي لعسير جنوباً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938432-44538148.jpg?v=1639324131"]','https://cmsphoto.ww-cdn.com/resizeapi/7dc7603c5a5cdd4df529df7b9f96161ad0a21533/480/',20.01197,41.4985461,'7497 قرية الملد Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59938432/al-malad-castle-klaa-almld-alathry',1,0,'قلعه ملد اثريه al malad castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938430,'albaha','قرية ذي عين الأثرية','Thee Ain Heritage Village','thee-ain-heritage-village-kry-thy-aayn-alathry','["التراث والثقافة"]','["heritage"]','قرية ذي عين الأثرية في المخواة قرية حجرية على جبل أبيض يزيد عمرها على 400 عام، تحيط بها مزارع الموز والكادي وتُعد من أشهر معالم الباحة.','<div class="texte" > <p>قرية ذي عين هي قرية أثرية تقع في تهامة غرب المملكة العربية السعودية، وتبعد 20 كيلومتراً تقريباً عن محافظة المخواة و24 كيلو متراً عن الباحة، ونشأت في القرن العاشر الهجري وعمرها يزيد على 400 سنة، بنيت القرية على قمة جبل أبيض وتشتهر بزراعة الموز والليمون والفلفل والريحان والكادي، والصناعات اليدوية،&nbsp;تضم القرية العديد من البيوت والمكونة من طابقين إلى أربعة طوابق ومسجداً صغيراً والعديد من الحصون المستخدمة للدفاع عن القرية والمراقبة،&nbsp;القرية هي أيضاً ضمن عشر مواقع وافقت عليها الحكومة السعودية في نوفمبر 2014 لتطلب من اليونسكو ضمها إلى قائمة التراث العالمي في السنوات القادمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938430-44538151.jpg?v=1639324164"]','https://cmsphoto.ww-cdn.com/resizeapi/cb8590c30095b80fcd2a585562217f28dd62586c/480/',19.9299246,41.4420978,'246 Al Makhwah Al Bahah Province','','','','https://www.saudi-guide.com/albaha/i/59938430/thee-ain-heritage-village-kry-thy-aayn-alathry',1,0,'قريه ذي عين اثريه thee ain heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938382,'albaha','متنزه الفرشة','Al Farsha Park','al-farsha-park-mtnzh-alfrsh','["أماكن سياحية"]','["sights"]','متنزه الفرشة أسفل قمة جبل شدا الأعلى في تهامة الباحة، منتزه عائلي يضم جلسات خاصة وألعاب أطفال وممشى، وتُقام فيه فعاليات الربيع.','<div class="texte" > <p>منتزة الفرشة بمحافظة قلوة يقع اسفل قمة جبل شدا الاعلى، منتزه مناسب&nbsp;لتنزه العوائل أو الشباب، يوفر المنتزه جميع&nbsp; المرافق الخدمية&nbsp;كما يوجد به جلسات تتمتع بالخصوصية للعائلات&nbsp;بالإضافة إلى ملاهي اطفال وممشى وفعاليات مختلفة تقام ايام الربيع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938382-44420387.jpg?v=1638457535"]','https://cmsphoto.ww-cdn.com/resizeapi/9d8244b75711aa21d5086b61c841680d60d6a711/480/',19.8857388,41.3116843,'شدا المخواة منطقة الباحة','','','','https://www.saudi-guide.com/albaha/i/59938382/al-farsha-park-mtnzh-alfrsh',1,0,'متنزه فرشه al farsha park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938380,'albaha','جبل شدا الأعلى','Shada Al Ala Mountain','shada-al-ala-mountain-gbl-shda-alaaala','["أماكن سياحية"]','["sights"]','جبل شدا الأعلى أعلى جبال سهل تهامة بين قلوة والمخواة، بصخوره الملساء ومحميته الطبيعية التي تضم كائنات نادرة وطيوراً مهاجرة.','<div class="texte" > <p>جبل شدا الأعلى هو جبل صخري مرتفع، يُعدّ أعلى جبل في سهل تهامة، يقع تقريبًا بين مدينتي قلوة والمخواة جنوب غربي المملكة العربية السعودية. ويقدر ارتفاع قمة الجبل عن مستوى سطح البحر 2200 متر. تغلب على تضاريس الجبل الصخور الملساء، مما يعطي الجبل لونًا أزرق باهت،&nbsp;يوجد بالجبل مبنى للإمارة ومدرسة ومركز صحي، ويتوفر التيار الكهربائي أيضًا. كما تصل إلى الجبل طريق معبدة جيدة إلى حدٍ ما، تتفرع من طريق المخواة - قلوة. في 2001م انضم شدا الأعلى إلى قائمة المحميات الطبيعية في المملكة لكونه مسكنا لعدد من الكائنات الحية النادرة والطيور المهاجرة يعد أشهرها النمر العربي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938380-44420397.jpg?v=1638457552"]','https://cmsphoto.ww-cdn.com/resizeapi/7e494c17eb7c6892b4be66d67b46643eb2229b64/480/',19.8499523,41.3178221,'جبل شدا الأعلى شدا المخواة','','','','https://www.saudi-guide.com/albaha/i/59938380/shada-al-ala-mountain-gbl-shda-alaaala',1,0,'جبل شدا اعلي shada al ala mountain اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938335,'albaha','سوق الثلاثاء بالمخواة','Tuesday Market Al Makhwah','tuesday-market-al-makhwah-sok-althlatha-balmkhoa','["أماكن سياحية", "أسواق"]','["shopping", "sights"]','سوق الثلاثاء في المخواة من أكبر الأسواق الشعبية في الباحة، يعرض فيه أهالي تهامة التمور والعسل والمواشي والخضار والمنتجات المحلية.','<div class="texte" > <p>سوق الثلاثاء بالمخواة من أكبر الأسواق الشعبية في منطقة الباحة، ويقع شرق المخواة قرب الطريق المؤدي إلى مدينة الباحة. يعرض فيه الباعة، ومعظمهم من أهالي تهامة، التمور والعسل والخضار والفواكه والحبوب طوال الأسبوع، ويُخصَّص يوم الثلاثاء جزء من السوق لبيع المواشي والطيور والأدوات الزراعية، إلى جانب الملابس والعطور والأدوات التراثية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938335-44420408.jpg?v=1638457572"]','https://cmsphoto.ww-cdn.com/resizeapi/31922a670c8b5a03a49f2ef1c44bc1dc6ad8735c/480/',19.7831694,41.4396869,'246 Al Marwah Al Makhwah','','','','https://www.saudi-guide.com/albaha/i/59938335/tuesday-market-al-makhwah-sok-althlatha-balmkhoa',1,0,'سوق ثلاثاء بالمخواه tuesday market al makhwah اماكن سياحيه اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938312,'albaha','بحيرة سد وادي الأحسبة','Wadi Al Ahsabah Dam Lake','wadi-al-ahsabah-dam-lake-bhyr-sd-oady-alahsb','["أماكن سياحية"]','["sights"]','بحيرة سد وادي الأحسبة في غامد الزناد على أحد أطول أودية تهامة، وادٍ خصب بأشجاره الكثيفة ومياهه العذبة ومزارع الفواكه والخضروات.','<div class="texte" > <p>وادي الأحسبة&nbsp;هو من أطول&nbsp;الأودية&nbsp;في جنوب&nbsp;المملكة العربية السعودية، يقع الوادي في&nbsp;تهامة&nbsp;ويصب في&nbsp;البحر الأحمر&nbsp;ويتجه من الشرق إلى الغرب. يبلغ طوله 50 كم،&nbsp;تَصُب فيه عدة مصاب من أهمها بطاط وشدا، ويمر بالعديد من البلدات.</p> <p>يشتهر وادي الأحسبة بكثرة أشجاره وبخصوبة أرضه وعذوبة مائه وكثرة إنتاجه من الفواكه والخضروات وخاصة في الوقت الحاضر بعد تطور أدوات الزراعة.</p> <p>&nbsp;</p> <p>وادي الأحسبة</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938312-44420420.jpg?v=1638457598"]','https://cmsphoto.ww-cdn.com/resizeapi/e9c978dba252769082e9c860da227f599948525d/480/',19.7003674,41.395561,'بحيرة سد وادي الأحسبة غامد الزناد منطقة الباحة','','','','https://www.saudi-guide.com/albaha/i/59938312/wadi-al-ahsabah-dam-lake-bhyr-sd-oady-alahsb',1,0,'بحيره سد وادي احسبه wadi al ahsabah dam lake اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938311,'albaha','سد ناوان نيرا','Nawan Nira Dam','nawan-nira-dam-sd-naoan-nyra','["أماكن سياحية"]','["sights"]','سد ناوان في وادي نيرا شمال غرب المخواة، وادٍ تهامي يحيط به جبل شدا الأعلى شرقاً وجبل شدا الأسفل جنوباً وسط طبيعة جبلية خلابة.','<div class="texte" > <p>وادي نيرا&nbsp;أحد أودية قطاع&nbsp;تهامة&nbsp;بمنطقة&nbsp;الباحة&nbsp;يتبع لمحافظة المخواة، ويقع بالتحديد في شمال غرب محافظة&nbsp;المخواة، يحده من الشرق جبل&nbsp;شدا الأعلى&nbsp;ومن الجنوب جبل&nbsp;شدا الأسفل&nbsp;ومن الشمال والغرب عدد من الجبال الأخرى</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938311-44420423.jpg?v=1638457619"]','https://cmsphoto.ww-cdn.com/resizeapi/a7081165edc5a4547b670865331f999425b88668/480/',19.7589479,41.3340727,'Q85M+HJG قراما المخواة','','','','https://www.saudi-guide.com/albaha/i/59938311/nawan-nira-dam-sd-naoan-nyra',1,0,'سد ناوان نيرا nawan nira dam اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938309,'albaha','منتجع الكهوف بجبل شدا الأسفل','Caves Resort Shada Al Asfal','caves-resort-shada-al-asfal-mntgaa-alkhof-bgbl-shda-alasfl','["أماكن سياحية"]','["sights"]','منتجع الكهوف في جبل شدا الأسفل بالمخواة استراحات فريدة مصممة على شكل كهوف على ارتفاع يتجاوز 1400 متر، بإطلالات جبلية رائعة.','<div class="texte" > <p>يقع منتجع الكهوف على ارتفاع 1410 متر عن سطح البحر وهو عبارة عن مجموعة&nbsp;من الاستراحات على شكل كهوف، يتميز المنتجع بتصميمه الفريد وإطلالاته المميزة والرائعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938309-44420429.jpg?v=1638457638"]','https://cmsphoto.ww-cdn.com/resizeapi/fb07665916dbcf25a6203a0646dcb79ad15bb7f6/480/',19.7346687,41.3813202,'شدا المخواة منطقة الباحة','','','','https://www.saudi-guide.com/albaha/i/59938309/caves-resort-shada-al-asfal-mntgaa-alkhof-bgbl-shda-alasfl',1,0,'منتجع كهوف بجبل شدا اسفل caves resort shada al asfal اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938196,'albaha','منتزه الخلب بالمندق','Al Khulb Park and Restaurant','al-khulb-park-and-restaurant-mntzh-alkhlb-balmndk','["أماكن سياحية"]','["sights"]','منتزه الخلب في محافظة المندق منتزه عائلي يضم مطعماً ومقهى وجلسات خاصة وعامة ومسرحاً وساحة ألعاب للأطفال وسط طبيعة جميلة.','<div class="texte" > <p>منتزه الخلب في محافظة المندق وجهة عائلية تجمع بين جمال الطبيعة والخدمات المتكاملة، إذ يضم مطعماً ومقهى وجلسات خاصة وأخرى عامة، ومسرحاً وساحة ألعاب للأطفال، ويُعد من أجمل المزارات السياحية في المنطقة لقضاء يوم هادئ وسط الأجواء المعتدلة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938196-44420437.jpg?v=1638457660"]','https://cmsphoto.ww-cdn.com/resizeapi/26885b813faadeef566929c0d09c998ee799571a/480/',20.1803154,41.2647492,'Al Mandaq Al Bahah Province SA','','','','https://www.saudi-guide.com/albaha/i/59938196/al-khulb-park-and-restaurant-mntzh-alkhlb-balmndk',1,0,'منتزه خلب بالمندق al khulb park and restaurant اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938172,'albaha','حديقة الفراشة بالمندق','Butterfly Park','butterfly-park-hdyk-alfrash-balmndk','["أماكن سياحية"]','["sights"]','حديقة الفراشة في محافظة المندق حديقة عائلية تضم ساحة ألعاب للأطفال ومطلاً وجلسات وأكشاكاً للأطعمة وصالة ألعاب إلكترونية.','<div class="texte" > <p>واحدة من أجمل الحدائق العائلية في منطقة الباحة تحتوي على ساحة ألعاب للأطفال ومطل وجلسات غير أرضية بالإضافة إلى كشكات بيع الأطعمة والمشروبات كما تحتوي الحديقة على صالة ألعاب فيديو مناسبة لجميع الأعمار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938172-44420443.jpg?v=1638457681"]','https://cmsphoto.ww-cdn.com/resizeapi/6c939151870688fe4eeff71e997fb5ac4080a7e8/480/',20.1800596,41.2693799,'SA Al Mandaq Al Bahah Province','','','','https://www.saudi-guide.com/albaha/i/59938172/butterfly-park-hdyk-alfrash-balmndk',1,0,'حديقه فراشه بالمندق butterfly park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938148,'albaha','بحيرة وادي مشنية','Wadi Mashniyah Lake','wadi-mashniyah-lake-bhyr-oady-mshny','["أماكن سياحية", "الشلالات والأودية"]','["nature", "sights"]','بحيرة وادي مشنية في محافظة المندق بحيرة طبيعية بمياه متدفقة تحيط بها الأشجار الكثيفة، وجهة هادئة للنزهات العائلية وسط الطبيعة.','<div class="texte" > <p>بحيرة وادي مشنية بحيرة طبيعية في محافظة المندق بمنطقة الباحة، تتميز بمياهها المتدفقة وتحيط بها الأشجار الكثيفة من كل جانب، مما يجعلها وجهة هادئة للنزهات العائلية والاستمتاع بالطبيعة الخلابة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938148-44420462.jpg?v=1638457725"]','https://cmsphoto.ww-cdn.com/resizeapi/54bcbc34f57e96577c5df395ade866cac46a1da8/480/',20.176987,41.3164535,'بحيرة وادي مشنية المندق منطقة الباحة','','','','https://www.saudi-guide.com/albaha/i/59938148/wadi-mashniyah-lake-bhyr-oady-mshny',1,0,'بحيره وادي مشنيه wadi mashniyah lake اماكن سياحيه شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938067,'albaha','سد مدهاس','Madhas Dam','madhas-dam-sd-mdhas','["أماكن سياحية", "الشلالات والأودية"]','["nature", "sights"]','سد مدهاس في محافظة المندق موقع طبيعي تحيط به الجبال، وجهة محببة للتخييم والمبيت، ويبلغ أجمل حالاته حين تمتلئ بحيرته بعد الأمطار.','<div class="texte" > <p>سد مدهاس موقع طبيعي في محافظة المندق تحيط به الجبال من جهات عدة، ويُعد وجهة محببة للتخييم والمبيت في الأجواء المعتدلة. يتفاوت منسوب المياه في بحيرته حسب المواسم، ويبلغ أجمل حالاته في موسم الأمطار حين تمتلئ البحيرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938067-44443958.jpg?v=1638623119"]','https://cmsphoto.ww-cdn.com/resizeapi/dc0b3a79dafa0383175b37b777d3ba97cc4fafb0/480/',20.2221286,41.2742025,'SA Al Mandaq Al Bahah Province','','','','https://www.saudi-guide.com/albaha/i/59938067/madhas-dam-sd-mdhas',1,0,'سد مدهاس madhas dam اماكن سياحيه شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938066,'albaha','وادي الجنابين','Wadi Al Janabain','wadi-al-janabain-oady-algnabyn','["أماكن سياحية"]','["sights"]','وادي الجنابين في محافظة بلجرشي يضم منتزه سد الجنابين بمسارات مشي وجلسات مظللة ومساحات خضراء شاسعة ومناطق ألعاب للعائلات.','<div class="texte" > <p>منتزه سد الجنابين هو أحد أفضل المنتزهات في منطقة الباحة، ويقع في محافظة&nbsp;بلجرشي التابعة لمدينة الباحة، يحتوي المنتزه علي مسارات للمشاة وجلسات مظللة ومساحات خضراء شاسعة للاستمتاع بالهواء النقي بالإضافة للعديد من مناطق الألعاب.<br /> &nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938066-44443956.jpg?v=1638623098"]','https://cmsphoto.ww-cdn.com/resizeapi/b10e4787c844f48a43cb1c97a385fc8ae174c5db/480/',19.9074799,41.7071285,'وادي الجنابين بلجراشى منطقة الباحة','','','','https://www.saudi-guide.com/albaha/i/59938066/wadi-al-janabain-oady-algnabyn',1,0,'وادي جنابين wadi al janabain اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938063,'albaha','أبو الخير مول','Abu Alkhair Mall','abu-alkhair-mall-abo-alkhyr-mol','["أماكن سياحية", "أسواق"]','["shopping", "sights"]','أبو الخير مول في بلجرشي من أشهر المجمعات التجارية في المحافظة، يضم سوبر ماركت ومحلات متنوعة ومقاهي ومطاعم في مكان واحد.','<div class="texte" > <p>أبو الخير مول من أشهر المجمعات التجارية في محافظة بلجرشي، ووجهة تسوق متكاملة تضم سوبر ماركت للخضار والفواكه والمواد الغذائية، إلى جانب محلات تجارية متنوعة ومقاهٍ ومطاعم تلبي احتياجات الأهالي والزوار في مكان واحد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938063-44443955.jpg?v=1638623075"]','https://cmsphoto.ww-cdn.com/resizeapi/f1fb96c5cae529148e434b55fd791985abd22372/480/',19.8607417,41.5703767,'Al Mustashfa Baljurshi Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938063/abu-alkhair-mall-abo-alkhyr-mol',1,0,'ابو خير مول abu alkhair mall اماكن سياحيه اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938060,'albaha','منتزه أم غيث','Umm Ghaith Park','umm-ghaith-park-mntzh-am-ghyth','["أماكن سياحية"]','["sights"]','منتزه أم غيث في بلجرشي يكسوه الضباب أغلب أيام السنة، ويضم مطلات بمناظر خلابة ومسطحات خضراء واسعة وجلسات مهيأة للزوار.','<div class="texte" > <p>يشتهر&nbsp;منتزه أُم غيث باكتساء الضباب له في أغلب فترات السنة، يحتوي المنتزه عدة مطلات ذات مناظر خلابة بالإضافة إلى المسطحات الخضراء الواسعة والجلسات المهيئة للزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938060-44443953.jpg?v=1638623044"]','https://cmsphoto.ww-cdn.com/resizeapi/6ea58c5a06212c940506259e2d55aae982333234/480/',19.8670148,41.5357152,'SA Bani Obaid Baljurshi','','','','https://www.saudi-guide.com/albaha/i/59938060/umm-ghaith-park-mntzh-am-ghyth',1,0,'منتزه ام غيث umm ghaith park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938058,'albaha','منتزه شكران ببلجرشي','Shukran Park','shukran-park-mntzh-shkran-bblgrshy','["أماكن سياحية"]','["sights"]','منتزه شكران في بلجرشي جلسات مدرجة على جبل مرتفع من سفحه حتى قمته، يطل على المحافظة بالكامل ويضم مناطق لعب ويناسب المبيت.','<div class="texte" > <p>منتزة شكران هو عبارة عن جلسات مدرجة على جبل مرتفع من أسفله وحتى القمة، يمكنك من خلاله مشاهدة بلجرشي بالكامل، يحتوي المنتزه على العديد والعديد من الجلسات ومناطق اللعب وهو مناسب للمبيت أيضاً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938058-44443952.jpg?v=1638623021"]','https://cmsphoto.ww-cdn.com/resizeapi/8d03cb9a232f74df9f5311b85fbc28b2a3a32c1b/480/',19.8484022,41.5834431,'RHXM+998 Baljurashi Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938058/shukran-park-mntzh-shkran-bblgrshy',1,0,'منتزه شكران ببلجرشي shukran park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938057,'albaha','حديقة الجسر النباتية','Al Jisr Botanical Garden','al-jisr-botanical-garden-hdyk-algsr-alnbaty','["أماكن سياحية", "مزارع"]','["nature", "sights"]','حديقة الجسر النباتية في قرية القريع ببلجرشي مزرعة وحديقة بمئات الأشجار والأزهار، يميزها جسر خشبي معلق وجلسات بإطلالات متنوعة.','<div class="texte" > <p>تقع حديقة الجسر النباتية في قرية القريع بمحافظة بلجرشي، وهي مزرعة وحديقة تضم نحو 300 شجرة إلى جانب أنواع متعددة من الزهور، ويميزها جسر خشبي معلق بطول يقارب 100 متر يعبر فوق الحديقة. تتخللها قنوات مائية وممشى ومشتل للنباتات، وتضم جلسات بإطلالات متنوعة ومقهى ومسجداً ودورات مياه، كما تتيح للزوار قطف ما يحبون من ثمار أشجارها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938057-44443950.jpg?v=1638622920"]','https://cmsphoto.ww-cdn.com/resizeapi/05aa410bc8151f4f6a5ac7a31fd0304c145178a8/480/',19.8417101,41.5710512,'No name Al Bahah Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938057/al-jisr-botanical-garden-hdyk-algsr-alnbaty',1,0,'حديقه جسر نباتيه al jisr botanical garden اماكن سياحيه مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938013,'albaha','منتزه بلجرشي الوطني','Baljurashi National Park','baljurashi-national-park-mntzh-blgrshy-alotny','["أماكن سياحية"]','["sights"]','منتزه بلجرشي الوطني وجهة ترفيهية عائلية تضم ملاعب لكرة القدم والطائرة ومناطق ألعاب آمنة للأطفال ومطاعم وسط طبيعة جميلة.','<div class="texte" > <p>يتمتز منتزه&nbsp;بلجرشي الوطني بتوفيره كافة المرافق الترفيهية&nbsp;التي تضمن لك الإستمتاع بقضاء يوم جميل وسط طبيعة جميلة،&nbsp;يوجد بالمنتزه مجموعة من ملاعب كرة القدم، وملاعب كرة الطائرة، ومناطق متعددة لألعاب الأطفال الشيقة مع توافر عنصري السلامة والأمان، بالإضافة إلى ذلك يوجد بها مجموعة متنوعة من المطاعم الجيدة&nbsp;التي تُقدم أشهى المأكولات السريعة،&nbsp;كما يتمتع المنتزه بتصميم معماري فريد ومميز.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938013-44443946.jpg?v=1638622895"]','https://cmsphoto.ww-cdn.com/resizeapi/e96b0afc455da59ae41419e3685893d1de21225c/480/',19.8469319,41.5840181,'RHWM+QJC Baljurashi Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938013/baljurashi-national-park-mntzh-blgrshy-alotny',1,0,'منتزه بلجرشي وطني baljurashi national park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938011,'albaha','شلال جدر','Jidr Waterfall','jidr-waterfall-shlal-gdr','["أماكن سياحية"]','["sights"]','شلال جدر في منتزه غابة خيرة من أبرز معالم الجذب في الباحة، بأجواء رائعة ومناظر خلابة، ويُنصح بزيارته بعد الأمطار حين تغزر مياهه.','<div class="texte" > <p>يعد شلال جدر واحد من أكثر المناطق تميزاً في مدينة الباحة لما يتمتع به من أجواء رائعة ومناظر خلابة، يقع في منتزه غابة الخيرة ويعتبر من اكثر معالم الجذب السياحي في المنطقة، من الجدير بالذكر أن مياه الشلال تكون قليلة جداً في غير مواسم الأمطار لذلك ينصح بزيارة الشلال بعد نزول المطر للاستمتاع بالتجربة بشكل أكبر&nbsp;.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938011-44444473.jpg?v=1638630805"]','https://cmsphoto.ww-cdn.com/resizeapi/8c370a9e506e293104a825059172aa9fc163d4ea/480/',20.06275,41.3891197,'Kherah Forest Park St Al Mandaq Al Bahah Province','','','','https://www.saudi-guide.com/albaha/i/59938011/jidr-waterfall-shlal-gdr',1,0,'شلال جدر jidr waterfall اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938010,'albaha','حديقة الحسام (حديقة شهبة)','Al Hussam Park','al-hussam-park-hdyk-alhsam-hdyk-shhb','["أماكن سياحية"]','["sights"]','حديقة الحسام في حي شهبة بالباحة حديقة على سفح تل تطل على المدينة، تضم ملاعب كرة قدم صغيرة ونوافير وألعاباً وأكشاك طعام.','<div class="texte" > <p>تحتوي حديقة الحسام&nbsp;على ملاعب كرة قدم صغيرة وأكشاك طعام ومنتزه ألعاب في حدائق على سفح تل تضمّ نوافير وتوفّر إطلالات على المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938010-44444475.jpg?v=1638630827"]','https://cmsphoto.ww-cdn.com/resizeapi/1181506e568425aa9f87096ddd4dab0881504e49/480/',20.0222922,41.4623423,'Al Bahah Shuhbah Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59938010/al-hussam-park-hdyk-alhsam-hdyk-shhb',1,0,'حديقه حسام (حديقه شهبه) al hussam park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938008,'albaha','منتزه غابة شهبة','Shahba Forest Park','shahba-forest-park-mntzh-ghab-shhb','["أماكن سياحية"]','["sights"]','غابة شهبة شرق مدينة الباحة على قمة جبل يشرف على المنطقة، من أهم غابات الباحة بأشجار العرعر والزيتون البري والطلح.','<div class="texte" > <p>منتزه غابة شهبة هو منتزه مشابه لغابة رغدان و<span>غابة شهبة تقع شرق الباحة على قمة جبل يشرف على المنطقة، واشجارها من العرعر والزيتون البري والطلح، وتعتبر من أهم الغابات في المنطقة.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938008-44444477.jpg?v=1638630848"]','https://cmsphoto.ww-cdn.com/resizeapi/dac56f547ab2a6ef3323a1c8fa91164134f21c1f/480/',20.050882,41.4740586,'SA Shahbah Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59938008/shahba-forest-park-mntzh-ghab-shhb',1,0,'منتزه غابه شهبه shahba forest park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938007,'albaha','حديقة الأمير محمد بن سعود','Prince Mohammed bin Saud Park','prince-mohammed-bin-saud-park-hdyk-alamyr-mhmd-bn-saaod','["أماكن سياحية"]','["sights"]','حديقة الأمير محمد بن سعود من أجمل حدائق مدينة الباحة، تضم مساحات عشبية واسعة ومناطق لعب ومسارات مشي ومسجداً ودورات مياه.','<div class="texte" > <p>تعد حديقة&nbsp;الأمير محمد بن سعود واحدة من أجمل الحدائق في منطقة الباحة حيث أنها&nbsp;تتميز بتصميمها الفريد وتوفيرها لكل المرافق التي يحتاجها الزوار فتوجد بها مساحات عشبية كبيرة ومناطق للعب ومسارات مخصصة للمشي بالإضافة إلى دورات المياه والمسجد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938007-44444478.jpg?v=1638630874"]','https://cmsphoto.ww-cdn.com/resizeapi/e6020a1464fc69355d8b00738a3f1949cd72466b/480/',20.0189178,41.4427019,'2601 Al Bahah Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59938007/prince-mohammed-bin-saud-park-hdyk-alamyr-mhmd-bn-saaod',1,0,'حديقه امير محمد بن سعود prince mohammed bin saud park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938004,'albaha','منتزه الأمير حسام','Prince Hussam Park','prince-hussam-park-mntzh-alamyr-hsam','["أماكن سياحية"]','["sights"]','منتزه الأمير حسام في مدينة الباحة يضم مسارات مشي متعرجة ومسطحات عشبية ومناطق لعب، إلى جانب برك وشلال ونافورة راقصة.','<div class="texte" > <p>يعد منتزه الأمير حسام أحد أبرز الأماكن السياحية في منطقة الباحة، ويحتوي المنتزه على&nbsp;مسارات متعرّجة للمشي ومسطحات عشبية ومناطق&nbsp;للّعب، بالإضافة إلى برك وشلّال ونافورة راقصة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938004-44444479.jpg?v=1638630905"]','https://cmsphoto.ww-cdn.com/resizeapi/f0c2e8bd5b51159ed0d34a99c640281e875cbdda/480/',20.0115386,41.4502238,'Al Bahah Al Zarqa Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59938004/prince-hussam-park-mntzh-alamyr-hsam',1,0,'منتزه امير حسام prince hussam park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938002,'albaha','سد وادي الملد','Wadi Al Malad Dam','wadi-al-malad-dam-sd-oady-almld','["أماكن سياحية"]','["sights"]','سد وادي الملد قرب مدينة الباحة وقرية الملد التاريخية، يتميز بمياهه العذبة الجارية وأشجاره المتنوعة وقربه من المواقع الأثرية.','<div class="texte" > <p>يقع سد وادي الملد بالقرب من مدينة الباحة وقرية الملد التاريخية، ويمتاز الوادي بمياهه العذبة الجارية وأشجاره المتنوعة وقربه من المواقع الأثرية، مما يجعله مكاناً مناسباً للتنزه والاستمتاع بالطبيعة، خاصة بعد مواسم الأمطار حين تمتلئ بحيرته.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938002-44444490.jpg?v=1638630983"]','https://cmsphoto.ww-cdn.com/resizeapi/cd42779b0ca94e1a973a6c00f795e0e0e38c1810/480/',20.0128914,41.4865637,'King Abdulaziz Rd Aldhafir Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59938002/wadi-al-malad-dam-sd-oady-almld',1,0,'سد وادي ملد wadi al malad dam اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937953,'albaha','ممشى السحاب','Cloud Walk','cloud-walk-mmsha-alshab','["أماكن سياحية"]','["sights"]','ممشى السحاب في غابة رغدان بالباحة يضم جسراً معلقاً بين قمتين فوق وادٍ سحيق، يمشي فيه الزوار بين الضباب بإطلالات مذهلة على تهامة.','<div class="texte" > <p>يقع ممشى السحاب في غابة رغدان بمنطقة الباحة، ويضم جسراً معلقاً يمتد بين قمتين فوق وادٍ سحيق، حيث يمشي الزوار بين الضباب والسحب بإطلالات مذهلة على جبال السراة وأودية تهامة. يُعد تجربة مميزة لمحبي المغامرة، ويُنصح بزيارته نهاراً للاستمتاع بالمشي بين السحب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937953-44561663.jpg?v=1639489124"]','https://cmsphoto.ww-cdn.com/resizeapi/3bcb388a7f8506c9d8cf720b71b590b186b45b90/480/',20.0193284,41.434269,'SA Al Bahah Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59937953/cloud-walk-mmsha-alshab',1,0,'ممشي سحاب cloud walk اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937888,'albaha','مطل عقبة الملك فهد','King Fahd Pass Viewpoint','king-fahd-pass-viewpoint-mtl-aakb-almlk-fhd','["أماكن سياحية"]','["sights"]','مطل عقبة الملك فهد في غابة رغدان من أجمل مطلات الباحة، يشرف على منعطفات العقبة وأودية تهامة ويشتهر بضبابه الكثيف ومناظره.','<div class="texte" > <p>يقع مطل عقبة الملك فهد في غابة رغدان بمنطقة الباحة، ويُعد من أجمل المطلات في المنطقة، إذ يشرف على منعطفات عقبة الملك فهد التي تربط السراة بتهامة وعلى أوديتها العميقة، ويشتهر بكثافة ضبابه الذي يغمر المكان في كثير من الأوقات وبجمال مناظره عند الغروب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937888-44538703.jpg?v=1639324841"]','https://cmsphoto.ww-cdn.com/resizeapi/7842a4c6904235417e966163a2de2899c2ecc577/480/',20.0174161,41.4292687,'SA Al Bahah Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59937888/king-fahd-pass-viewpoint-mtl-aakb-almlk-fhd',1,0,'مطل عقبه ملك فهد king fahd pass viewpoint اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937829,'albaha','منتزه غابة خيرة','Khairah Forest Park','khairah-forest-park-mntzh-ghab-khyr','["أماكن سياحية"]','["sights"]','غابة خيرة في بني حسن من أشهر غابات الباحة، تكسوها الأمطار الغزيرة شتاءً وربيعاً وتكثر فيها الضباب والأجواء الباردة والنباتات.','<div class="texte" > <p>غابة خيرة هي غابة تقع في منطقة الباحة، بالمملكة العربية السعودية، تشتهر بالأمطار كثيفة الهطول في فصل الشتاء والربيع على منحدراتها وسفوحها، مما أكسبها ثروة فطرية ونباتية،&nbsp;كما أنها كثيرة الضباب والبرد خلال السنة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937829-44538706.jpg?v=1639324889"]','https://cmsphoto.ww-cdn.com/resizeapi/a7b720e24d11bd9bdbda3ec31c50f0ad54d500b3/480/',20.0522376,41.3977182,'SA بني حسن منطقة الباحة','','','','https://www.saudi-guide.com/albaha/i/59937829/khairah-forest-park-mntzh-ghab-khyr',1,0,'منتزه غابه خيره khairah forest park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937828,'albaha','قرية رغدان السياحية','Raghadan Village','raghadan-village-kry-rghdan-alsyahy','["أماكن سياحية"]','["sights"]','قرية رغدان شمال غرب مدينة الباحة على طريق الباحة الطائف، من أشهر قرى المنطقة بغابتها الشهيرة وسوق الأحد العريق الذي اشتهرت به.','<div class="texte" > <p>قرية رغدان من قرى منطقة الباحة، وتقع شمال غرب مدينة الباحة على بعد نحو 4 كم على الطريق العام بين الباحة والطائف، وتفصلها قرية الزرقاء عن المدينة. تُعد القرية وسيطة بين مجموعة من القرى، وتشتهر بغابتها التي تُعد من أجمل غابات المملكة وأكثرها شهرة، وهي مقر لمشيخة بني خثيم. اشتهرت رغدان قديماً بسوق الأحد العريق الذي يُقام أسبوعياً ويُعد من أشهر أسواق المنطقة ويتوافد إليه الناس من كل مكان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937828-44538717.jpg?v=1639324921"]','https://cmsphoto.ww-cdn.com/resizeapi/c5fcd7675071982f66e0f1e5c85eb3d67c4a82e0/480/',20.0218833,41.4408857,'طريق الملك عبدالله بن عبدالعزيز Alhazim Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59937828/raghadan-village-kry-rghdan-alsyahy',1,0,'قريه رغدان سياحيه raghadan village اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937826,'albaha','منتزه غابة رغدان','Raghadan Forest Park','raghadan-forest-park-mntzh-ghab-rghdan','["أماكن سياحية"]','["sights"]','غابة رغدان أشهر غابات الباحة بأشجار العرعر الكثيفة ومناخها المعتدل صيفاً، تطل على تهامة وعقبة الملك فهد ويغمرها الضباب.','<div class="texte" > <p>غابة رغدان هي الغابة التي تتميز بها الباحة والمنطقة الجنوبية، لكثافة أشجارها وخضرتها، مناخها معتدل طيلة أيام الصيف ولكونها تقع غرب منطقة الباحة، وتطل على إقليم تهامة وعقبة الملك فهد بالباحة والضباب الذي يتسلق أعالي جبال السراة إلى هذه الغابة، خصوصا في ساعات الصباح الباكر وساعات ما بعد الظهر وحتى ساعات متأخرة من الليل مما يجعل أجواء هذه الغابة صيفا بين المعتدلة والشتوية الممطرة ومما يزيد من جمال المتعة في هذه الغابة إلى جانب الارتفاع الشاهق كثرة مطلاتها على أعماق تهامة المنطقة وأوديتها السحيقة التي تغوص إليها عقبة الملك فهد كأحد الشرايين المهمة في المنطقة التي تربط بين سراة المنطقة وتهامتها كما أن كثافة الغطاء النباتي بعد آخر من أبعاد جمال هذه الغابة، حيث تواجد أشجار العرعر والطلح وبعض الشجيرات البسيطة، ظل في النهار، ونسيم عليل في الليل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937826-44538718.jpg?v=1639324944"]','https://cmsphoto.ww-cdn.com/resizeapi/167dcfae3832482d7f43b262aca77f7bb534b45c/480/',20.0206813,41.4327696,'4657 الحكم الزروقي Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59937826/raghadan-forest-park-mntzh-ghab-rghdan',1,0,'منتزه غابه رغدان raghadan forest park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937823,'albaha','منتزه القيم','Al Qeem Park','al-qeem-park-mntzh-alkym','["أماكن سياحية"]','["sights"]','منتزه القيم في مدينة الباحة يضم مسطحات خضراء بمدرجات وبحيرات وممشى، وزاوية ألعاب للأطفال وذوي الهمم وأكشاكاً للأسر المنتجة.','<div class="texte" > <p>منتزه القيم توجد به مسطحات خضراء متميزة بمدرجات وبحيرات وكذلك زاوية ألعاب&nbsp;للأطفال وذوي الهمم وممشى&nbsp;جميل، كما يوجد بالمنتزه عدة أكشاك لبيع أنواع الأطعمة والمشروبات بالإضافة إلى طاولات الأسر المنتجة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937823-44538723.jpg?v=1639324968"]','https://cmsphoto.ww-cdn.com/resizeapi/6b983d2df897b70a3e109c8a07c3a5c6fe73c9ac/480/',20.0096246,41.4511734,'6988 طريق القيم Al Bahah','','','','https://www.saudi-guide.com/albaha/i/59937823/al-qeem-park-mntzh-alkym',1,0,'منتزه قيم al qeem park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937759,'albaha','سد وادي العقيق','Wadi Al Aqiq Dam','wadi-al-aqiq-dam-sd-oady-alaakyk','["أماكن سياحية", "الشلالات والأودية"]','["nature", "sights"]','سد وادي العقيق جنوب محافظة العقيق أكبر سدود منطقة الباحة ومصدر مهم للمياه، يحيط به الشجر الكثيف ويقصده الزوار للتنزه.','<div class="texte" > <p>سد وادي العقيق يقع جنوب محافظة العقيق وهو أكبر سد&nbsp;بالمنطقة، يوجد به كميات كبيرة من مخزون المياه الذي&nbsp; يستخدمه&nbsp;أهالي منطقة الباحة،&nbsp;ويعتبر سد وادي العقيق محط أنظار السياح&nbsp;وذلك بسبب موقعه وسط الغابات والأشجار الكثيفة فيأتي الزوار للاستمتاع بأجوائه الرائعة ومناظر طبيعته الخلابة&nbsp;.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937759-44538731.jpg?v=1639325014"]','https://cmsphoto.ww-cdn.com/resizeapi/1970e457a512b13f051708cc31d3f8c1e2ce0b3d/480/',20.2369192,41.5708397,'SA Al Aqiq Al Bahah Province','','','','https://www.saudi-guide.com/albaha/i/59937759/wadi-al-aqiq-dam-sd-oady-alaakyk',1,0,'سد وادي عقيق wadi al aqiq dam اماكن سياحيه شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59937725,'albaha','بحيرة سد وادي ثراد','Wadi Tharad Dam Lake','wadi-tharad-dam-lake-bhyr-sd-oady-thrad','["أماكن سياحية"]','["sights"]','بحيرة سد وادي ثراد في محافظة العقيق تتجمع خلف السد الذي أُنشئ لدعم المنطقة بالمياه، وتُعد مكاناً هادئاً للتنزه وسط الطبيعة.','<div class="texte" > <p>سد وادي ثراد أحد السدود التابعة لمحافظة العقيق بمنطقة الباحة، أُنشئ لدعم المنطقة بالمياه، وتتجمع خلفه بحيرة تُضفي على المكان طابعاً طبيعياً هادئاً، مما يجعله مكاناً مناسباً للتنزه والاسترخاء وسط الطبيعة، خاصة بعد مواسم الأمطار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59937725-44538736.jpg?v=1639325033"]','https://cmsphoto.ww-cdn.com/resizeapi/9d1fad7fc4c61b87a2facfe601dbaa736e88d442/480/',20.1522673,41.717712,'Wadi Tharad Dam''s Lake Al Bahah Province SA','','','','https://www.saudi-guide.com/albaha/i/59937725/wadi-tharad-dam-lake-bhyr-sd-oady-thrad',1,0,'بحيره سد وادي ثراد wadi tharad dam lake اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896171,'riyadh-region','القرية التراثية بسدوس','','alkry-altrathy-bsdos','["التراث والثقافة"]','["heritage"]','تعد بلدة سدوس التراثية -شمال غرب مدينة الرياض- أحد المواقع التراثية المهمة في منطقة الرياض، والتي كان لها دور في تاريخ المملكة وملحمة توحيدها.','<div class="texte" > <p>تعد بلدة سدوس التراثية -شمال غرب مدينة الرياض- أحد المواقع التراثية المهمة في منطقة الرياض، والتي كان لها دور في تاريخ المملكة وملحمة توحيدها.&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896171-44380766.jpg?v=1638219817"]','https://cmsphoto.ww-cdn.com/resizeapi/2e7f3782edc996926a1c69365f6d22459f21793a/480/',24.9939068,46.2076566,'X6V5+H37 Sadus Diriyah','','','','https://www.saudi-guide.com/riyadh-region/i/59896171/alkry-altrathy-bsdos',1,0,'قريه تراثيه بسدوس تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896168,'riyadh-region','مقبرة شهداء اليمامة - جنوب','Al Yamamah Martyrs Cemetery - South','al-yamamah-martyrs-cemetery-south-mkbr-shhdaaa-alymam-gnob','["التراث والثقافة"]','["heritage"]','مقبرة شهداء اليمامة في الجبيلة بشمال الرياض دفن فيها بعض الصحابة بعد معركة ضد مسيلمة الكذاب في حرب المرتدين ومنهم زيد بن الخطاب والطفيل بن عمرو وأبو دجانة...','<div class="texte" > <p>مقبرة شهداء اليمامة في الجبيلة بشمال الرياض دفن فيها بعض الصحابة بعد معركة ضد مسيلمة الكذاب في حرب المرتدين ومنهم زيد بن الخطاب والطفيل بن عمرو وأبو دجانة وأبوحذيفة رضوان الله عليهم”.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896168-44380796.jpg?v=1638220188"]','https://cmsphoto.ww-cdn.com/resizeapi/28012a86b0a6137149fd83739bb7cdd007428130/480/',24.8937889,46.444386,'VCVV+GQ6 Al Jubaylah Diriyah','','','','https://www.saudi-guide.com/riyadh-region/i/59896168/al-yamamah-martyrs-cemetery-south-mkbr-shhdaaa-alymam-gnob',1,0,'مقبره شهداء يمامه جنوب al yamamah martyrs cemetery south تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896081,'riyadh-region','متحف السنين الماضية','','mthf-alsnyn-almady','["التراث والثقافة"]','["heritage"]','متحف السنين الماضية، ياخذك لرحلة عبر الزمن للماضي، ويعيشك أجواء تاريخية، ويطلعك على كل ماهو قديم عاصره الأجداد، ومن الأماكن اللي بتستمتع بزيارتها','<div class="texte" > <p>متحف السنين الماضية، ياخذك لرحلة عبر الزمن للماضي، ويعيشك أجواء تاريخية، ويطلعك على كل ماهو قديم عاصره الأجداد، ومن الأماكن اللي بتستمتع بزيارتها&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896081-44380861.jpg?v=1638220627"]','https://cmsphoto.ww-cdn.com/resizeapi/cf8af7a740e32cb2b21dcca11522252782954cfc/480/',24.7412328,46.5718307,'King Faisal Rd At Tarif Al Jadid Ad Diriyah','','','','https://www.saudi-guide.com/riyadh-region/i/59896081/mthf-alsnyn-almady',1,0,'متحف سنين ماضيه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896080,'riyadh-region','الدرعية التاريخية','','aldraay-altarykhy','["التراث والثقافة"]','["heritage"]','تقع الدرعية على أطراف الرياض وضفاف وادي حنيفة، وتمتاز بطرازها المعماريّ الأثريّ وجدرانها الطينية المقوسة، ليخلّدها التاريخ كأحد أهم محاضنِ الثقافة...','<div class="texte" > <p>تقع الدرعية على أطراف الرياض وضفاف وادي حنيفة، وتمتاز بطرازها المعماريّ الأثريّ وجدرانها الطينية المقوسة، ليخلّدها التاريخ كأحد أهم محاضنِ الثقافة والتجارة في المملكة. ومن أبرز معالمها حي الطريف والذي يحوي أهم قلاعها ومبانيها بالإضافة إلى كونه منطقة حكم الدولة السعودية الأولى&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896080-44380883.jpg?v=1638220857"]','https://cmsphoto.ww-cdn.com/resizeapi/1ea6f50174316edd5199accb505e4e67e7655cb5/480/',24.5561943,46.5929218,'Wadi Hanifah Alawali Ad Diriyah','','','','https://www.saudi-guide.com/riyadh-region/i/59896080/aldraay-altarykhy',1,0,'درعيه تاريخيه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896075,'riyadh-region','قرية علقة التراثية','','kry-aalk-altrathy','["التراث والثقافة"]','["heritage"]','قرية عْلِقَة التراثية" هي قرية تراثية قديمة العهد غرب مدينة الزلفي من جهة الشمال بالقرب من صحراء نفود الثويرات وجبل طويق.','<div class="texte" > <p dir="RTL">قرية عْلِقَة&nbsp;التراثية" هي قرية تراثية قديمة العهد غرب مدينة الزلفي من جهة الشمال بالقرب من صحراء نفود الثويرات وجبل طويق<span dir="LTR">.</span></p> <p dir="RTL"><span dir="LTR">&nbsp;</span>تُعد أسوار "مدينة&nbsp;عْلِقَة "&nbsp; وبلداتها العتيقة أحد أهم المعالم السياحية في الزلفي حيث بقايا الحصون والبيوت والمباني الطينية القديمة والمُزخرفة</p> <p>&nbsp;</p> <p>&nbsp;</p> <p dir="RTL">&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896075-44380897.jpg?v=1638220983"]','https://cmsphoto.ww-cdn.com/resizeapi/42a5b9e17d30a43ab5f595b8b46b83f4a9fc1e5b/480/',26.3363454,44.7781491,'5930 Az Zilfi Al Zulfi','','','','https://www.saudi-guide.com/riyadh-region/i/59896075/kry-aalk-altrathy',1,0,'قريه علقه تراثيه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896074,'riyadh-region','متحف عبدالرحمن بن حمود الضويحي','Abdulrahman bin Hamoud Alazaviha Museum','abdulrahman-bin-hamoud-alazaviha-museum-mthf-aabdalrhmn-bn-hmod-aldoyhy','["التراث والثقافة"]','["heritage"]','يضم متحف "الضويحي" بمحافظة الزلفى إحدى محافظات الرياض آلاف القطع الأثرية التي تروي تاريخ المنطقة، ما جعله من أهم المعالم السياحة هناك','<div class="texte" > <p>يضم متحف "الضويحي" بمحافظة الزلفى إحدى محافظات الرياض آلاف القطع الأثرية التي تروي تاريخ المنطقة، ما جعله من أهم المعالم السياحة هناك</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896074-44380943.jpg?v=1638221366"]','https://cmsphoto.ww-cdn.com/resizeapi/9268da5e5e34f8eee621cbb1231bb3c7f9517e8e/480/',26.3484046,44.7970418,'Al Khalil bin Ahmed Az Zilfi Al Zulfi','','','','https://www.saudi-guide.com/riyadh-region/i/59896074/abdulrahman-bin-hamoud-alazaviha-museum-mthf-aabdalrhmn-bn-hmod-aldoyhy',1,0,'متحف عبدالرحمن بن حمود ضويحي abdulrahman bin hamoud alazaviha museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896071,'riyadh-region','قرية السيح التراثية','As Sieh Museum','sieh-museum-kry-alsyh-altrathy','["التراث والثقافة"]','["heritage"]','هي عبارة عن قرية تراثية قديمة تشتهر بعيون الماء فيها، ومن أشهرها الراس وعين ام برج وعين ام هيب وعين مليحة، ولذلك اكتظت بالسكان على مر الأزمان.','<div class="texte" > <p>هي عبارة عن قرية تراثية قديمة تشتهر بعيون الماء فيها، ومن أشهرها الراس وعين ام برج وعين ام هيب وعين مليحة، ولذلك اكتظت بالسكان على مر الأزمان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896071-44380986.jpg?v=1638221577"]','https://cmsphoto.ww-cdn.com/resizeapi/4358992b7dbb5f3a45d5587f62053f25fc35f76b/480/',26.3236739,44.8084127,'Az Zilfi As Sieh Al Zulfi','','','','https://www.saudi-guide.com/riyadh-region/i/59896071/sieh-museum-kry-alsyh-altrathy',1,0,'قريه سيح تراثيه as sieh museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896061,'riyadh-region','مكتبة الرحمانية العامة','Al-Rahmania Public Library','al-rahmania-public-library-mktb-alrhmany-alaaam','["التراث والثقافة"]','["heritage"]','تقع دار الرحمانية وسط بستان العرنية وقد أخذ تصميمها في الاعتبار البيئة الريفية المحيطة بها في الغاط؛ فظهر بطابع نجدي، تتجلى فيه المباني الطينية والأقواس...','<div class="texte" > <p>تقع دار الرحمانية وسط بستان العرنية&nbsp;وقد أخذ تصميمها في الاعتبار البيئة الريفية المحيطة بها في الغاط؛ فظهر بطابع نجدي، تتجلى فيه المباني الطينية والأقواس النجدية، والمسجد ذي المصلى المفتوح على الفناء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896061-44381055.jpg?v=1638222126"]','https://cmsphoto.ww-cdn.com/resizeapi/d2c5684073a127e367e23c0501776cb16f39e4d3/480/',26.0208456,44.9630579,'King Abdulaziz Road Al Ghat Al-Ghat','','','','https://www.saudi-guide.com/riyadh-region/i/59896061/al-rahmania-public-library-mktb-alrhmany-alaaam',1,0,'مكتبه رحمانيه عامه al rahmania public library تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59896055,'riyadh-region','الديرة القديمة بالغاط','The old Deira','old-deira-aldyr-alkdym-balghat','["التراث والثقافة"]','["heritage"]','تحتوي القرية التراثية على قصر الإمارة الذي يعد تحفة معمارية اتخذت من الطراز الإسلامي في فن العمارة أسلوبا في البناء، وقلعة مغيران التاريخية، وعلى الضفة...','<div class="texte" > <p>&nbsp;تحتوي القرية التراثية على قصر الإمارة الذي يعد تحفة معمارية اتخذت من الطراز الإسلامي في فن العمارة أسلوبا في البناء، وقلعة مغيران التاريخية، وعلى الضفة الغربية من&nbsp;<a href="https://ar.wikipedia.org/wiki/%D9%88%D8%A7%D8%AF%D9%8A_%D9%85%D8%B1%D8%AE" title="وادي مرخ">وادي مرخ</a>&nbsp;هناك موضع يحوي العديد من النقوش والرسوم المنحوتة على صخور منفردة يرجع تاريخها للفترة ما بين 900 قبل الميلاد وعام 400 ميلادي</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59896055-44381070.jpg?v=1638222232"]','https://cmsphoto.ww-cdn.com/resizeapi/516765dbab42477694311bd8d605c5a04848eaf7/480/',26.0212771,45.0009629,'22C2+G98 Al Ghat Al-Ghat','','','','https://www.saudi-guide.com/riyadh-region/i/59896055/old-deira-aldyr-alkdym-balghat',1,0,'ديره قديمه بالغاط the old deira تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875672,'riyadh-region','قرية الفاو الأثرية','Qaryah Qaryat al Faw','qaryah-qaryat-al-faw-kry-alfao-alathry','["التراث والثقافة"]','["heritage"]','قرية الفاو الأثرية عاصمة مملكة كندة الأولى، ومن أهم المواقع الأثرية في الجزيرة العربية، وتجسد صورة متكاملة للمدينة العربية قبل الإسلام.','<div class="texte" > <p>قرية الفاو&nbsp;الأثرية عاصمة مملكة كندة&nbsp;الأولى أحد الممالك السبئية القديمة، ومن أهم المواقع الأثرية في شبه الجزيرة العربية؛ لأنها عبارة عن تجسيد متكامل للمدن العربية قبل الإسلام</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875672-44381103.jpg?v=1638222465"]','https://cmsphoto.ww-cdn.com/resizeapi/39a77278b0376ed70d192a83f914a000c08b99bd/480/',19.793501,45.139042,'Qaryah Qaryat al Faw Wadi ad-Dawasir As Sulayyil','','','','https://www.saudi-guide.com/riyadh-region/i/59875672/qaryah-qaryat-al-faw-kry-alfao-alathry',1,0,'قريه فاو اثريه qaryah qaryat al faw تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875669,'riyadh-region','منتزه ومتحف الصادرية','','mntzh-omthf-alsadry','["التراث والثقافة"]','["heritage"]','يعد متحف الصادرية أحد أشهر المعالم الأثرية في منطقة الرياض حيث أنه يضم أكثر من 30 ألف قطعة أثرية ومخطوطات قديمة من مُختلف العصور وبعضها يعود إلى ما قبل...','<div class="texte" > <p>يعد متحف الصادرية أحد أشهر المعالم الأثرية في منطقة الرياض حيث أنه يضم أكثر من 30 ألف قطعة أثرية ومخطوطات قديمة من مُختلف العصور وبعضها يعود إلى ما قبل 3000 عام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875669-44393145.jpg?v=1638287684"]','https://cmsphoto.ww-cdn.com/resizeapi/45ed014d33b9716407ef66aeabd4e5e2bd28d53f/480/',20.3701605,44.7593388,'شارع الحديدي Wadi ad-Dawasir Wadi Ad Dawasir','','','','https://www.saudi-guide.com/riyadh-region/i/59875669/mntzh-omthf-alsadry',1,0,'منتزه ومتحف صادريه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875665,'riyadh-region','قصر الملك عبدالعزيز بوادي الدواسر (اللدام)','Old Emirate Palace','old-emirate-palace-ksr-almlk-aabdalaazyz-boady-aldoasr-alldam','["التراث والثقافة"]','["heritage"]','يُعَدُّ قصر الملك عبد العزيز التاريخي بوادي الدواسر من أهم المعالم في المحافظة، ويعود تاريخ القصر إلى مرحلة مبكرة من مراحل تأسيس الدولة في عهد الملك...','<div class="texte" > <p>يُعَدُّ قصر الملك عبد العزيز التاريخي بوادي الدواسر من أهم المعالم في المحافظة، ويعود تاريخ القصر إلى مرحلة مبكرة من مراحل تأسيس الدولة في عهد الملك عبدالعزيز،&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875665-44393201.jpg?v=1638287953"]','https://cmsphoto.ww-cdn.com/resizeapi/e4210b3d0c068464c5e9a6688e20438600aca3ce/480/',20.4743518,44.7903823,'FQFR+P5R Wadi ad-Dawasir Wadi Ad Dawasir','','','','https://www.saudi-guide.com/riyadh-region/i/59875665/old-emirate-palace-ksr-almlk-aabdalaazyz-boady-aldoasr-alldam',1,0,'قصر ملك عبدالعزيز بوادي دواسر (اللدام) old emirate palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875652,'riyadh-region','قرية أشيقر التراثية','Ushaiqer Heritage Village','ushaiqer-heritage-village-kry-ashykr-altrathy','["التراث والثقافة"]','["heritage"]','تُعبر قرية أشيقر عن روح الأصالة والعراقة، حيث الفن المعماري الذي لم يتلاش أو يتقادم سحره مع مرور السنوات، إضافةً إلى أنها محاطة بجدرانٍ سميكة تظلّ أزقتها...','<div class="texte" > <p>تُعبر قرية أشيقر عن روح الأصالة والعراقة، حيث الفن المعماري الذي لم يتلاش أو يتقادم سحره مع مرور السنوات، إضافةً إلى أنها محاطة بجدرانٍ سميكة تظلُّ أزقتها المتعرِّجة، وممراتها الضيقة المؤطَّرة بالخشب، والتي تخترق بدورها مئات المنازل الطينية الأثرية المزيَّنة ببساتين النخيل، فترسم لوحةً عريقة للتصميم المعماري النجدي بنوافذها وأسطحها المثلَّثة وأبوابها الخشبيَّة، التي نُحت على بعضها أسماء العوائل التي سكنت فيها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875652-44393263.jpg?v=1638288177"]','https://cmsphoto.ww-cdn.com/resizeapi/a1ad80a753d07b6743775116db14ac7442c8fb1f/480/',25.3397513,45.1912354,'50 Ushaiqer Shuqrah','','','','https://www.saudi-guide.com/riyadh-region/i/59875652/ushaiqer-heritage-village-kry-ashykr-altrathy',1,0,'قريه اشيقر تراثيه ushaiqer heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875649,'riyadh','قصر السبيعي التاريخي','Subaie heritage house','subaie-heritage-house','["التراث والثقافة"]','["heritage"]','قصر السبيعي التاريخي بالرياض، منزل تراثي مرمم يعكس الطراز المعماري النجدي القديم.','<div class="texte" > <p data-original-size="16px">يعد قصر السبيعي واحداً من أبرز القصور التاريخية في السعودية، ويقع في محافظة شقراء بمنطقة الرياض. بُني القصر على الطراز الأندلسي الإسلامي، ويقع في الزاوية الجنوبية الغربية من البلدة القديمة، مطلاً على الأسواق التاريخية. كان الملك عبد العزيز رحمه الله يستريح في هذا القصر خلال سفره بين الرياض والمناطق الأخرى.</p> <p data-original-size="16px">يبلغ عمر قصر السبيعي أكثر من 80 عاماً، وتم ترميمه لأول مرة في عام 1411 هـ (1990م)، ثم تم ترميمه بشكل كامل في عام 1421 هـ (2000م). يعكس بيت السبيعي الزخارف التي كانت سائدة في منطقة وسط المملكة. ومن المقرر تحويل القصر إلى متحف تراثي، ليكون وجهة للزوار لاكتشاف تاريخ السعودية الغني وجمال معمارها العريق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875649-63387788.jpg?v=1751552166"]','https://cmsphoto.ww-cdn.com/resizeapi/0537123053e512fdca26ed874b526d405ffc2b4d/480/',25.2542154,45.253973,'النخيل Shaqra Shuqrah','','https://www.visitsaudi.com/ar/riyadh/attractions/al-subaie-palace','','https://www.saudi-guide.com/riyadh-region/i/59875649/subaie-heritage-house',1,0,'قصر سبيعي تاريخي subaie heritage house تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875646,'riyadh-region','بيت الحلوان التراثي','','byt-alhloan-altrathy','["التراث والثقافة"]','["heritage"]','بيت الحلوان التراثي أحد المنازل القديمة في الديرة التراثية بمحافظة مرات، يعكس طراز العمارة الطينية النجدية التقليدية.','<div class="texte" > <p>بيت الحلوان التراثي بيت طيني قديم في الديرة القديمة ببلدة أثيثية التابعة لمحافظة مرات في منطقة الرياض، ويعكس طراز العمارة النجدية التقليدية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875646-44393464.jpg?v=1638288758"]','https://cmsphoto.ww-cdn.com/resizeapi/0b7925649e6ddc9dc38ee64b0f28e67b5a597455/480/',25.1595069,45.3905717,'الديرة القديمة أثيثية مرات','','','','https://www.saudi-guide.com/riyadh-region/i/59875646/byt-alhloan-altrathy',1,0,'بيت حلوان تراثي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875623,'riyadh-region','قصر العناقر الأثري','Tharmida Oasis Fort','tharmida-oasis-fort-ksr-alaanakr-alathry','["التراث والثقافة"]','["heritage"]','ويقع قصر العناقر الذي أنشئ عام 1136هـ داخل بلدة ثرمداء القديمة وداخل السور القديم المسمى العقدة، يضم بين جنباته المزارع والآبار والمساجد والأسواق والبيوت،...','<div class="texte" > <p>ويقع قصر العناقر الذي أنشئ عام 1136هـ داخل بلدة ثرمداء القديمة وداخل السور القديم المسمى العقدة، يضم بين جنباته المزارع والآبار والمساجد والأسواق والبيوت، وتبلغ مساحة القصر الإجمالية 1800 متر مربع تقريبا.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875623-44393511.jpg?v=1638288901"]','https://cmsphoto.ww-cdn.com/resizeapi/87081c3dee4ed79297a13375ca022a8ee17bc30e/480/',25.1256722,45.4815471,'4FGJ+7J7 Tharmda Marat','','','','https://www.saudi-guide.com/riyadh-region/i/59875623/tharmida-oasis-fort-ksr-alaanakr-alathry',1,0,'قصر عناقر اثري tharmida oasis fort تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875553,'riyadh-region','بئر الوليدي(خالد بن الوليد رضي الله عنه)','Well','well-byr-alolydy-khald-bn-alolyd-rdy-allh-aanh','["التراث والثقافة"]','["heritage"]','بئر الوليدي هو بئر حفره الصحابي الجليل ((خالد بن الوليد)) أثناء مروره بمرات أيام حروب الردة وهو موجود إلى وقتنا الحاضر.','<div class="texte" > <p>بئر الوليدي هو بئر حفره الصحابي الجليل ((خالد بن الوليد)) أثناء مروره بمرات أيام حروب الردة وهو موجود إلى وقتنا الحاضر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875553-44450843.jpg?v=1638711422"]','https://cmsphoto.ww-cdn.com/resizeapi/77ca0eb549375af5435e54a180756231d7dfe140/480/',25.0697801,45.4729452,'3F9F+W58 Marat Marat','','','','https://www.saudi-guide.com/riyadh-region/i/59875553/well-byr-alolydy-khald-bn-alolyd-rdy-allh-aanh',1,0,'بئر وليدي(خالد بن وليد رضي له عنه) well تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875466,'riyadh-region','قرية العمار التراثية','','kry-alaamar-altrathy','["التراث والثقافة"]','["heritage"]','تعد قرية العمار التراثية وجهة مفضلة لمحبي التراث والبيوت الشعبية حيث تم ترميمها مؤخراً وتجهيزها لاستقبال الزوار.','<div class="texte" > <p>تعد&nbsp;قرية العمار التراثية وجهة مفضلة لمحبي التراث والبيوت الشعبية حيث تم ترميمها مؤخراً وتجهيزها لاستقبال الزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875466-44451005.jpg?v=1638712604"]','https://cmsphoto.ww-cdn.com/resizeapi/d15ecfe61cddbb77ac8f40ce730b6bf11a93cfc9/480/',22.2468528,46.7267092,'Al Amar Al-Aflaj Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59875466/kry-alaamar-altrathy',1,0,'قريه عمار تراثيه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875463,'riyadh-region','متحف الحزيمي التراثي','','mthf-alhzymy-altrathy','["التراث والثقافة"]','["heritage"]','متحف جذور وتراث أحد متاحف مدينة الرياض أسسه عبد العزيز عبد ربه الحازمي، يمتلك عبد العزيز الحازمي مجموعة من القطع التراثية الجيدة من حيث الكم ومن حيث...','<div class="texte" > <p>متحف جذور وتراث أحد متاحف مدينة الرياض أسسه عبد العزيز عبد ربه الحازمي، يمتلك عبد العزيز الحازمي مجموعة من القطع التراثية الجيدة من حيث الكم ومن حيث الحالة وقد دله تفكيره إلى بلورة ما بحوزته ومن خلال تلك المجموعة ووضعها في مكان واحد وبطريقة منظمة لتكون متحفا يحكي تاريخ جزءاً تاريخ المملكة العربية السعودية , وقد اشتملت المجموعة على جميع عناصر واستخدامات الإنسان في ذلك العصر ومن خلال مواد الصناعات المتوفرة من أخشاب وأصواف وجلود ومعادن وكذلك التربة ومن خلال الصناعات والأواني الفخارية، وهناك أواني الطبخ والمأكل والمشرب وكذلك أدوات القهوة والأدوات الزراعية والملابس للرجال والنساء وكذلك الحلي وأدوات الزينة للنساء والأسلحة وعدة الحرب وغير ذلك.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875463-44451008.jpg?v=1638712765"]','https://cmsphoto.ww-cdn.com/resizeapi/22a06d9cd6c7efdbd5bbcc541be1b691dbb1fd74/480/',22.292292,46.7331097,'7PRM+W69 Ghusaiba Layla','','','','https://www.saudi-guide.com/riyadh-region/i/59875463/mthf-alhzymy-altrathy',1,0,'متحف حزيمي تراثي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875461,'riyadh-region','بيت الطيبين التراثي','','byt-altybyn-altrathy','["التراث والثقافة"]','["heritage"]','بيت الطيبين التراثي أحد المباني التراثية في محافظة الليلى، يحافظ على ملامح العمارة الطينية النجدية القديمة في المنطقة.','<div class="texte" > <p>بيت الطيبين التراثي يقع في حي المبرز بمدينة ليلى، مقر محافظة الأفلاج جنوب منطقة الرياض، ويحافظ على طابع البيوت النجدية القديمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875461-44451013.jpg?v=1638712791"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/59875461-44451013.jpg?v=1638712811',22.2949776,46.7358848,'7PVP+X9R Almubarraz Layla','','','','https://www.saudi-guide.com/riyadh-region/i/59875461/byt-altybyn-altrathy',1,0,'بيت طيبين تراثي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59875458,'riyadh-region','جبل التوباد','Mount At Toobad','mount-toobad-gbl-altobad','["التراث والثقافة"]','["heritage"]','جبل التوباد، يقع في مدينة الأفلاج التي تقع بدورها إلى الجنوب الغربي من مدينة الرياض بالسعودية. ويقع جبار تحديداً بالقرب من قرية الغيل، بوسط...','<div class="texte" > <p>جبل التوباد، يقع في مدينة الأفلاج التي تقع بدورها إلى الجنوب الغربي من مدينة الرياض بالسعودية بمسافة 350كم. ويقع جبار تحديدًا بالقرب من قرية الغيل، بوسط وادي المغيال. شهد هذا الجبل قصة حب قيس بن الملوح وابنة عمه ليلى العامرية، وذلك عام خمس وستون من الهجرة في عهد الخليفة الأموي عبد الملك بن مروان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59875458-44451017.jpg?v=1638712849"]','https://cmsphoto.ww-cdn.com/resizeapi/12ce311551e03a885dbc09e7aa723496b9e10733/480/',22.5753534,46.5193353,'5040 Al Ghayl Al-Aflaj','','','','https://www.saudi-guide.com/riyadh-region/i/59875458/mount-toobad-gbl-altobad',1,0,'جبل توباد mount at toobad تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786383,'riyadh-region','سوق حليوة التراثي','Hlewa Heritage Market','hlewa-heritage-market-sok-hlyo-altrathy','["التراث والثقافة"]','["heritage"]','يعتبر سوق حليوة أحد أهم الأسواق التراثية في محافظة شقراء، ويطل عليه هذا الاسم نسبة إلى بستان مجاور للسوق يحمل اسم (حليوه).','<div class="texte" > <p>يعتبر سوق حليوة أحد أهم الأسواق التراثية في محافظة شقراء، ويطل عليه هذا الاسم نسبة إلى بستان مجاور للسوق يحمل اسم (حليوه).</p> <p>بني السوق في عام 1350هـ تقريباً. والسوق كبير وواسع زادت محلاته على المائة محل، تنوعت فيه التجارة الداخلية والخارجية، ويدل هذا السوق على مكانة شقراء التجارية التي كانت تتمتع بها في الجزيرة العربية عامة. لم يشتهر عند أهل شقراء فقط بل في كل الأقاليم، حتى لم يعد يقرن إسمه بكلمة السوق لبداهة ما يقصد وما يراد. وهذا السوق لشهرته غطى على الأسواق التي سبقته رغم حداثته نسبياً، ولا شك أن نشاط التجارة فيه جعلته في مقدمة الأسواق المشهورة في شقراء وسبب من أسباب اضمحلال نشاطها بوجوده، بل واختفائها بعد أن صار في المقدمة، ليس لأنه أكثر دكاكين منها ولا أوسع مساحة فقط، بل لأنه صاحب ظهوره هيمنة تجارة التجزئة وكثرة المنتجات المعروضة فيه، وتراجع تجارة الجملة التي كان تجار شقراء يملكون زمامها في أيام نشاط الأسواق السابقة والتي كانت تختص بالتجزئة البسيطة والمحلية فقط. وكانت تعرض فيه مستلزمات المنازل وأدواتها وأوانيها، وخضار وفواكه ومنتجات محلية وأغنام، بل إن الخدمات الأخرى تجاوره كطاحونة الدقيق وبيع المحاصيل والميزان العام ( القبان).</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786383-44451024.jpg?v=1638712885"]','https://cmsphoto.ww-cdn.com/resizeapi/804e028c70f7f4f73361866c446e4760576c2254/480/',25.2562691,45.2569358,'الديرة شقراء شقراء','','','','https://www.saudi-guide.com/riyadh-region/i/59786383/hlewa-heritage-market-sok-hlyo-altrathy',1,0,'سوق حليوه تراثي hlewa heritage market تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786348,'riyadh-region','الديره القديمه بشقراء','','aldyrh-alkdymh-bshkraaa','["التراث والثقافة"]','["heritage"]','الديرة القديمة بشقراء هي عبارة عن قرية تحتوي على العديد من بيوت الآباء والأجداد التي تم ترميمها وتجهيزها لاستضافة الزائرين.','<div class="texte" > <p>الديرة القديمة بشقراء هي عبارة عن قرية تحتوي على العديد من بيوت الآباء والأجداد التي تم ترميمها وتجهيزها لاستضافة الزائرين.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786348-44451028.jpg?v=1638712914"]','https://cmsphoto.ww-cdn.com/resizeapi/0cbfd748d7f035ee78bcd176c8701a0f83b3dc7e/480/',25.2555893,45.253794,'7743+6GM Shaqra Shuqrah','','','','https://www.saudi-guide.com/riyadh-region/i/59786348/aldyrh-alkdymh-bshkraaa',1,0,'ديره قديمه بشقراء تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786272,'riyadh-region','حرمة التاريخية','','hrm-altarykhy','["التراث والثقافة"]','["heritage"]','حَرْمَة بفتح الحاء، وإسكان الراء، وفتح الميم فتاء مربوطة. تقع شمال غرب مدينة الرياض على خط الطول 45.3406 شرقاً،...','<div class="texte" > <p>حَرْمَة بفتح الحاء، وإسكان الراء، وفتح الميم فتاء مربوطة. تقع على مسافة 195 كيلومتراً تقريباً, شمال غرب مدينة الرياض تقع على خط الطول 45.3406 شرقاً، ودائرة العرض 25.9233 شمالاً. يحتضنها وادي الباطن الذي يلتقي عنده كل من وادي الكَلْبِ ووادي المشقر حيث يلتقيان في بحيرة سد حرمة، وتشترك حرمة مع مدينة المجمعة بوادي الكلبي كما هو معروف لكنها تعتمد على سيل هذين الواديين إذ يجتمعان في هذا السد الكبير الذي يبلغ طوله حوالي 400 متر، شيده أهالي حرمه بالحجارة منذ مئات السنين، ثم دعمته وزارة الزراعة ونظمت تصريف سيوله عبر قنوات اصطناعية إلى مزارع حرمه فما زاد عن حاجة حرمه من سيل الواديين يذهب إلى الشرق عبر مجرى وادي الباطن إذ تقع بعض مزارع ونخيل حرمة جنوب هذا الوادي: وهي الظاهرية وسعة الله والوسطى وقلبان العود كما يقع جنوباً عن الوادي مريقب ابن دريس وظهرة مشرفة، ويفصل هذا الوادي مدينة حرمة عن مدينة المجمعة، وينحدر مع السيل حتى يصل إلى رياض صبحا والخفيسة ومطربة وغيرها مخترقاً ضلع المجزل من فتحة الكظيمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786272-44451032.jpg?v=1638712944"]','https://cmsphoto.ww-cdn.com/resizeapi/e8cd0b0cb808f41439da8e236cd8d55e7beda082/480/',25.9244588,45.3415477,'Harmah Al Majmaah Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59786272/hrm-altarykhy',1,0,'حرمه تاريخيه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786204,'riyadh-region','جلاجل القديمة','','glagl-alkdym','["التراث والثقافة"]','["heritage"]','تعد جلاجل من اقوى بلاد سدير في القرن الحادي عشر وقد سميت بهذا الاسم نسبة إلى جلجلة الماء وهو خرير الماء وتحركه بين صخور الأودية، تشتهر جلاجل بكثرة النخيل...','<div class="texte" > <p>تعد جلاجل من اقوى بلاد سدير في القرن الحادي عشر وقد سميت بهذا الاسم نسبة إلى&nbsp;جلجلة الماء وهو خرير الماء وتحركه بين صخور الأودية، تشتهر جلاجل&nbsp;<span>بكثرة النخيل وانتاج كميات كبيرة من التمور بالإضافة إلى احتواءها على بعض الأماكن التاريخية مثل المرقب والجامع القديم وقصرالأمارة وقصر وسويد بن علي.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786204-44451033.jpg?v=1638712969"]','https://cmsphoto.ww-cdn.com/resizeapi/2f3dce2de9c6e3de28da0dfc362b1dc84d08e054/480/',25.6761837,45.4683013,'MFG9+F8F Jalajil Al Majmaah','','','','https://www.saudi-guide.com/riyadh-region/i/59786204/glagl-alkdym',1,0,'جلاجل قديمه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786200,'riyadh-region','بيت الماجد التراثى','','byt-almagd-altrath','["التراث والثقافة"]','["heritage"]','بيت الماجد التراثي أحد المعالم القديمة في روضة سدير بمحافظة المجمعة، يعكس طابع العمارة الطينية النجدية الأصيلة.','<div class="texte" > <p>مزيج من الضيافة والتراث.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786200-44451037.jpg?v=1638712998"]','https://cmsphoto.ww-cdn.com/resizeapi/8db8ec168d53f19d8f11e3e49dea4b1d56d4e186/480/',25.612991,45.5522531,'JH72+5WR Raudat Sudair Al Majmaah','','','','https://www.saudi-guide.com/riyadh-region/i/59786200/byt-almagd-altrath',1,0,'بيت ماجد تراثي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786197,'riyadh-region','مقبلة سدير','Muqbilah Sudeir - Al Muhaideb‏ garh brown amber','muqbilah-sudeir-al-muhaideb-garh-brown-amber-mkbl-sdyr','["التراث والثقافة"]','["heritage"]','مقبلة سدير هي إحدى المراكز التابعة لمنطقة الرياض في السعودية، يوجد بالمركز بعض المعالم المعروفة ومنها وادي الفقي والذي يعتبر من أبرز معالمها، إضافة...','<div class="texte" > <p>مقبلة سدير هي إحدى المراكز التابعة لمنطقة الرياض في السعودية،&nbsp;<span>يوجد بالمركز&nbsp;بعض المعالم المعروفة ومنها وادي الفقي والذي يعتبر من أبرز معالمها، إضافة إلى قارة بني العنبر.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786197-44451038.jpg?v=1638713025"]','https://cmsphoto.ww-cdn.com/resizeapi/265fd8d5ff1e29c8cee89cc5ca765d75fd64230f/480/',25.58494,45.6257272,'King Abdulaziz Rd حوطة سدير المجمعة','','','','https://www.saudi-guide.com/riyadh-region/i/59786197/muqbilah-sudeir-al-muhaideb-garh-brown-amber-mkbl-sdyr',1,0,'مقبله سدير muqbilah sudeir al muhaideb‏ garh brown amber تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786195,'riyadh-region','متحف أبابطين التراثي','','mthf-ababtyn-altrathy','["التراث والثقافة"]','["heritage"]','متحف "عبد الله بن محمد أبابطين التراثي" هو متحف تراثي يقع في مزرعة عبد الله بن محمد أبابطين "العائذية" بروضة سدير، افتتح المتحف الأمير أحمد بن عبد العزيز...','<div class="texte" > <p>متحف "عبد الله بن محمد أبابطين التراثي" هو متحف تراثي يقع في مزرعة عبد الله بن محمد أبابطين "العائذية" بروضة سدير،&nbsp;افتتح المتحف الأمير أحمد بن عبد العزيز يوم 1436/02/13هـ، يضم المتحف أكثر من 5000 قطعة تراثية، تحكي واقع إقليم سدير قديماً من حيث طبيعة الأعمال المهنية والحرفية والزراعية، والمخطوطات والعملات والأسلحة التراثية والخرائط.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786195-44451039.jpg?v=1638713057"]','https://cmsphoto.ww-cdn.com/resizeapi/22275ce9cfa5bf9478f84710ff03dcd52d8bc60e/480/',25.6163498,45.5205793,'JG8C+G6P Raudat Sudair Al Majmaah','','','','https://www.saudi-guide.com/riyadh-region/i/59786195/mthf-ababtyn-altrathy',1,0,'متحف ابابطين تراثي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786192,'riyadh-region','بيت السويح التراثي','Al-Saweeh Heritage House','al-saweeh-heritage-house-byt-alsoyh-altrathy','["التراث والثقافة"]','["heritage"]','يعد بيت السويح التراثي نافذة للماضي حيث تم تأسيسه قبل 100 سنة تقريباً، يمكن للزائر استئجار البيت لمدة يوم كامل والاستمتاع بعبق الماضي...','<div class="texte" > <p>يعد بيت السويح التراثي نافذة للماضي حيث تم تأسيسه عام 1347 هـ أي قبل 100 سنة تقريباً، يمكن للزائر استئجار البيت لمدة يوم كامل والاستمتاع بعبق الماضي وتجربة العيش في بيت أثري كما يمكن شراء بعض المأكولات الشعبية من الأسر المنتجة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786192-44451041.jpg?v=1638713083"]','https://cmsphoto.ww-cdn.com/resizeapi/a7bf965f16911c9e4ce391040b94f0b2e4d5b3b2/480/',25.6128336,45.5608361,'الحزم روضة سدير المجمعة','','','','https://www.saudi-guide.com/riyadh-region/i/59786192/al-saweeh-heritage-house-byt-alsoyh-altrathy',1,0,'بيت سويح تراثي al saweeh heritage house تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59786144,'riyadh-region','القرية التراثية بعودة سدير','','alkry-altrathy-baaod-sdyr','["التراث والثقافة"]','["heritage"]','القرية التراثية بعودة سدير بمحافظة المجمعة، تشتهر بخصوبة أرضها ومزارع النخيل والقمح، وتحافظ على موروث أهل نجد كالعرضة النجدية والفنون الشعبية.','<div class="texte" > <p>تشتهر عودة سدير بخصوبة الأرض وتعدد الأودية، ما أدى بالنتيجة إلى ازدهار الزراعة واتساع المراعي، ويعتمد أهلها في المقام الأول على الزراعة حيث ينتج المزارعون أجود الأنواع من القمح والذرة والشعير، فضلاً عن اهتمامهم الكبير بالنخيل وإنتاج أنواع متعددة من التمور مثل الخضري والمقفزي والدخيني والحلوة والصقعي والمسكاني والسودي. وتعتمد في ذلك على السيول الجارية في وادي سدير المعروف عند أهل البلدة بالباطن، فإذا سال هذا الوادي امتلأت الآبار بالماء وارتوت النخيل، بالإضافة إلى عدة أودية مثل وادي الجوفاء ويسقي أعلى البلدة، ووادي الشعبة ويسقي أسفل البلدة، ووادي الداخلة ويسقي أسفل البلدة وصنع جنوب البلدة (المسيل الخاص) ويسقي مزارع وقصر أسرة العيسى.</p> <p>تعكس الحياة الاجتماعية في عودة سدير تقاليد ومأثورات أهل نجد، حيث تتوارث فيها ومنذ القدم العرضة النجدية والتي يحرص أهاليها على إقامتها في المناسبات السعيدة خاصة يوم العيد، ومن الفنون الشعبية لمحبي الشعر، غناء الحصاد ويؤديه المزارعون خاصة عند سنابل القمح، وفن الشعر المعروف بالرد والشعر الشعبي.</p> <p>وقد امتدت مظاهر النهضة والعمران إلى عودة سدير مثلها مثل مدن وقرى المملكة، حيث شيدت فيها المساكن الحديثة والمؤسسات التجارية والمنشآت التعليمية والصحية، وتم تزويدها بكافة المرافق والمنافع العامة.</p> <p>وهناك أيضا أماكن واثار عثر عليها هناك من قبل الهيئة العامة للسياحة والتراث الوطني السعودية وهناك مصادر ان هذه الاثار قبل الإسلام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59786144-44461829.jpg?v=1638799262"]','https://cmsphoto.ww-cdn.com/resizeapi/857dbef09e2b2b3d03dd62c0420caf39ca6660d9/480/',25.5471956,45.6793221,'Al Awdah Al Majmaah Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59786144/alkry-altrathy-baaod-sdyr',1,0,'قريه تراثيه بعوده سدير تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785976,'riyadh-region','قرية الشعراء التراثية','Ash Shu''ara heritage village','ash-shu-ara-heritage-village','["التراث والثقافة"]','["heritage"]','أعاد أهالي مركز الشعراء التابع لمحافظة الدوادمي إحياء تاريخ المساكن والمسجد والدكاكين القديمة من خلال ترميمها وتحويلها إلى قرية سياحية، وإنشاء بوابات من...','<div class="texte" > <p>أعاد أهالي مركز الشعراء التابع لمحافظة الدوادمي إحياء تاريخ المساكن والمسجد والدكاكين القديمة من خلال ترميمها وتحويلها إلى قرية سياحية، وإنشاء بوابات من جميع الجهات لما لها من أهمية تاريخية و<span>تمشياً مع سعي الهيئة العامة للسياحة والتراث الوطني لتنمية القرى التراثية، وقد</span>&nbsp;شهدت القرية&nbsp;أحداثاً تاريخية هامة، منها معركة أهل الشعراء مع الأشراف عام (1791م/1205هـ)، ومعركة سوفة في العام (1901م/1319 هـ)، ومؤتمر الشعراء الذي دعا إليه الملك عبد العزيز رحمه الله&nbsp;وعقد في يوم الخميس 1 / 5 / 1348هـ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785976-44461840.jpg?v=1638799286"]','https://cmsphoto.ww-cdn.com/resizeapi/fdd758f50d06a0b35d7e72f2f83ce3015a8b4f4d/480/',24.2635934,44.1821516,'565 Ash Shu''ara Dawadmi','','','','https://www.saudi-guide.com/riyadh-region/i/59785976/ash-shu-ara-heritage-village',1,0,'قريه شعراء تراثيه ash shu''ara heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785974,'riyadh-region','قصر الملك عبدالعزيز الآثري بالدوادمي','','ksr-almlk-aabdalaazyz-alathry-baldoadmy','["التراث والثقافة"]','["heritage"]','قصر الملك عبد العزيز هو قصر أثري تعود ملكيته للملك عبد العزيز بن عبد الرحمن آل سعود، وهو يقع في الجهة الغربية من محافظة الدوادمي على امتداد طريق الحجاز،...','<div class="texte" > <p>قصر الملك عبد العزيز هو قصر أثري تعود ملكيته للملك عبد العزيز بن عبد الرحمن آل سعود، وهو يقع في الجهة الغربية من محافظة الدوادمي على امتداد طريق الحجاز، يتميز بمبناه الجميل الذي يقع على مساحة كبيرة، حيث كانت بداية مراحل تأسيس القصر الأثري 1349هـ بصدور أمر الملك عبد العزيز إلى الشيخ عبد الرحمن أبو بكر آل غيهب يخبره بأن عليه أن يختار موقعاً مناسباً لبناء قصر للملك في الدوادمي.</p> <p>يتكون قصر الملك عبد العزيز في محافظة الدوادمي من عدد من المباني، أبرزها الجناح الملكي، الذي يتضمن السكن الملكي مع منافعه والروشن وهو المجلس الخاص بالملك وورش إصلاح السيارات الملكية بالإضافة إلى المشب الذي كان يستخدم لتحضير القهوة والشاي وغيرها من المنافع.</p> <p>شهد القصر اهتماما بالغا من وكالة وزارة التربية والتعليم للآثار والمتاحف (سابقا)، حيث تم تنفيذ مشروع وترميم هذا القصر الأثري، بإشراف من إدارة تعليم البنين في محافظة الدوادمي، ممثل في قسم المتاحف والآثار في الإدارة، وتمت ترسية مناقصة المشروع على شركة بوابة الجزيرة المتخصصة في ترميم الآثار والمتاحف بمبلغ 4.6 مليون ريال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785974-44461847.jpg?v=1638799315"]','https://cmsphoto.ww-cdn.com/resizeapi/d8369d43d0856af69086d256990729812737fa92/480/',24.4817378,44.3610444,'قصر الملك عبدالعزيز الآثري Al Duwadimi Dawadmi','','','','https://www.saudi-guide.com/riyadh-region/i/59785974/ksr-almlk-aabdalaazyz-alathry-baldoadmy',1,0,'قصر ملك عبدالعزيز اثري بالدوادمي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785934,'riyadh-region','أبراج الحمام في الدلم Pigeons Tower','','abrag-alhmam-fy-aldlm-pigeons-tower','["التراث والثقافة"]','["heritage"]','هي عبارة عن 14 برج كانت تستخدم لتربية الحمام في مشروع خفس دغره الزراعي وتم اهمالها لفتره طويله وعاد اليها الاهتمام بعد انتشار صور لمصور محترف...','<div class="texte" > <p>هي عبارة عن 14 برج كانت تستخدم لتربية الحمام في مشروع خفس دغره الزراعي وتم اهمالها لفترة طويله وعاد اليها الاهتمام بعد انتشار صور لمصور محترف وقامت لجنة التنمية السياحية باعادة تأهيل الابراج وفتحها للزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785934-44461856.jpg?v=1638799338"]','https://cmsphoto.ww-cdn.com/resizeapi/88ce3a1c9944803d90b9779a79b8481dfe36677b/480/',23.8458995,47.1938801,'الدلم الخرج منطقة الرياض','','','','https://www.saudi-guide.com/riyadh-region/i/59785934/abrag-alhmam-fy-aldlm-pigeons-tower',1,0,'ابراج حمام في دلم pigeons tower تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785933,'riyadh-region','قرية الدلم التراثية','','kry-aldlm-altrathy','["التراث والثقافة"]','["heritage"]','قرية الدلم هي قرية تراثية شعبيه ثقافية، تعد القرية أحد المشاريع السياحية الحديثة والمميزة في المحافظة حيث تقع وسط مزارع النخيل بالدلم، تضم عدة منازل قديمة...','<div class="texte" > <p>قرية الدلم هي قرية تراثية شعبيه ثقافية، تعد القرية أحد المشاريع السياحية الحديثة والمميزة في المحافظة حيث تقع وسط مزارع النخيل بالدلم، تضم عدة منازل قديمة تم تهيئتها للزوار وجلسات خارجيه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785933-44461861.jpg?v=1638799365"]','https://cmsphoto.ww-cdn.com/resizeapi/017e71cfae9c561adb39f96307467eafb606ddbc/480/',23.9729285,47.1463286,'شارع Al Ethar Ad Dilam','','','','https://www.saudi-guide.com/riyadh-region/i/59785933/kry-aldlm-altrathy',1,0,'قريه دلم تراثيه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785929,'riyadh-region','قصر الملك عبدالعزيز التاريخي','King AbdulAziz Palace','king-abdulaziz-palace-ksr-almlk-aabdalaazyz-altarykhy','["التراث والثقافة"]','["heritage"]','قصر الملك عبد العزيز، يعتبر من القصور التاريخية الأثرية في محافظة الخرج وتحديدا في مدينة السيح عاصمة الخرج قديما، ولا يزال القصر موجوداً إلى وقتنا...','<div class="texte" > <p>قصر الملك عبد العزيز، يعتبر من القصور التاريخية الأثرية في محافظة الخرج وتحديدا في مدينة السيح عاصمة الخرج قديما، ولا&nbsp;يزال القصر&nbsp;موجوداً إلى وقتنا الحاضر،&nbsp;تم بناء القصر عام 1359 هـ الموافق 1940م بأمر من الملك عبد العزيز آل سعود بغرض&nbsp;حماية الرياض&nbsp;وحماية حدودها الجنوبية من أي تمرد على الدولة، وتم بناء القصر تحديدا في الخرج لأنها هدف استراتيجي لكل من يريد السيطرة على اليمامة ونجد في تلك الحقبة، وتتميز الخرج بمواردها الطبيعية، وخصوبة أراضيها ووفرة عيونها المائية، كما تمتاز بالكثير من المواقع الأثرية المهمة التي يرجع تاريخ بعضها إلى&nbsp;500 سنة ق. م مثل المدافن الأثرية ومواقع (البنه) الأثرية باليمامة التي تمر عليها القوافل في رحلتها من الشام إلى اليمن والعكس، والمعروفة برحلة الشتاء والصيف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785929-44461866.jpg?v=1638799392"]','https://cmsphoto.ww-cdn.com/resizeapi/cf1f071d20c6a9e7f30067588e31a5082eb89b03/480/',24.1518933,47.2975695,'King Faisal Rd Al Aziziyyah Al-Kharj','','','','https://www.saudi-guide.com/riyadh-region/i/59785929/king-abdulaziz-palace-ksr-almlk-aabdalaazyz-altarykhy',1,0,'قصر ملك عبدالعزيز تاريخي king abdulaziz palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785926,'riyadh-region','مسجد قصر الشريعة الأثري','','msgd-ksr-alshryaa-alathry','["التراث والثقافة"]','["heritage"]','يعد مسجد قصر الشريعة الأثري من أبرز المباني الأثرية في منطقة الرياض حيث يتميز بطريقة بنائه المكونة من الطين والحجارة على الطراز النجدي.','<div class="texte" > <p>يعد&nbsp;مسجد قصر الشريعة الأثري من أبرز المباني الأثرية في منطقة الرياض حيث يتميز بطريقة بنائه المكونة من الطين والحجارة على الطراز النجدي،</p> <p>وبعيداً عن كون المسجد مكان للعبادة يعتبر أيضاً منارة ثقافية لتلقي العلم حيث تعقد فيه الكثير من الدروس والمحاضرات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785926-44461873.jpg?v=1638799413"]','https://cmsphoto.ww-cdn.com/resizeapi/059cdea92637709e85e12ee992bcd0e12e2e0aa8/480/',24.1537971,47.2543643,'Al Hayathem Al-Kharj Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59785926/msgd-ksr-alshryaa-alathry',1,0,'مسجد قصر شريعه اثري تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785924,'riyadh-region','متحف الموسى في بلدة السلميه','','mthf-almos-fy-bld-alslmyh','["التراث والثقافة"]','["heritage"]','متحف صالح بن إبراهيم الموسى أحد متاحف منطقة الرياض يقع في محافظة الخرج في بلدة السلمية، أسسه صالح بن إبراهيم الموسى.','<div class="texte" > <p>متحف صالح بن إبراهيم الموسى أحد متاحف منطقة الرياض يقع في محافظة الخرج في بلدة السلمية، أسسه صالح بن إبراهيم الموسى، يتكون المتحف من 5&nbsp;قاعات حيث تم عرض محتويات المتحف بعدة أساليب فمنها ما هو معروض داخل خزانات أو فاترينات ومنها ما هو معروض على أرفف وكذلك ما هو معروض بالتعليق الجداري وتأتي المعروضات داخل القاعات كالتالي :</p> <p>القاعة الأولى: وتضم الخوصيات والجلديات وبعض الأواني المعدنية .</p> <p>القاعة الثانية: وتضم مجموعة من الراديوهات القديمة والبكمات .</p> <p>القاعة الثالثة: وتضم معرضاً لصور سيارات قديمة .</p> <p>القاعة الرابعة: وهي عبارة عن صالة استقبال وجهاز عرض بروجوكتر .</p> <p>القاعة الخامسة: وهي القاعة الرئيسية وتشمل مجموعة كبيرة من المقتنيات التراثية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785924-44461877.jpg?v=1638799435"]','https://cmsphoto.ww-cdn.com/resizeapi/da223818929eae8119e205509cf7f0b9b07cb7c2/480/',24.2017867,47.2897039,'Al-Kharj Al-Kharj Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59785924/mthf-almos-fy-bld-alslmyh',1,0,'متحف موسي في بلده سلميه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785921,'riyadh-region','عريش الملك عبدالعزيز التاريخي','Arish King Abdulaziz','arish-king-abdulaziz-aarysh-almlk-aabdalaazyz-altarykhy','["التراث والثقافة"]','["heritage"]','يعد عريش الملك عبدالعزيز التاريخي في بلدة السلمية من أهم المعالم التاريخية، التي تشرف عليها الهيئة العامة للسياحة والتراث الوطني.','<div class="texte" > <p>يعد عريش الملك عبدالعزيز التاريخي في بلدة السلمية من أهم المعالم التاريخية، التي تشرف عليها الهيئة العامة للسياحة والتراث الوطني، والذي تم إدراجه مؤخرا ضمن مشروع المسارات السياحية بالمملكة، تعود الأهمية التاريخية للعريش لارتباطه بالمؤسس الملك عبد العزيز رحمه الله حيث كان يتخذ منه مجلسا له في زياراته لمحافظة الخرج.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785921-44461881.jpg?v=1638799453"]','https://cmsphoto.ww-cdn.com/resizeapi/33760d7aefb7b8d5e4fbc251d3dc157115c5d75e/480/',24.2011503,47.2860253,'672P+FC6 An Nasifah Al-Kharj','','','','https://www.saudi-guide.com/riyadh-region/i/59785921/arish-king-abdulaziz-aarysh-almlk-aabdalaazyz-altarykhy',1,0,'عريش ملك عبدالعزيز تاريخي arish king abdulaziz تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785867,'riyadh-region','مطل حافة العالم من طريق العيينة','Edge of the World','edge-world-mtl-haf-alaaalm-mn-tryk-alaayyn','["أماكن سياحية"]','["sights"]','حافة العالم هي مرتفعات صخرية شاهقة تطل على وادٍ سحيق، وهي معلم سياحي نادر صنعه الزمن، حيث يعود المطل ما قبل 50 مليون سنة؛ فقد كان عبارة عن قاع لبحر كبير...','<div class="texte" > <p>حافة العالم هي مرتفعات صخرية شاهقة تطل على وادي سحيق، وهي معلم سياحي نادر صنعه الزمن، حيث يعود المطل ما&nbsp;قبل 50 مليون سنة؛ فقد كان عبارة عن قاع لبحر كبير يغمر شبه الجزيرة العربية حتى بلاد الشام،&nbsp;تظهر بها آثار مجارٍ لأنهار، ومسارات قد جفت منذ زمن وتمتد لمئات الكيلومترات لترسم أشكالاً جمالية في سهولها الواسعة، إلى جانب أنواع مختلفة من الأحافير والمنحوتات والنقوش الرائعة التي كونتها عوامل الطبيعة على صخور الوادي والتي تحكي ما عاشت فيه المنطقة من ظروف وما تعاقب عليها من حقب زمنية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785867-44462073.jpg?v=1638800082"]','https://cmsphoto.ww-cdn.com/resizeapi/a2f15016ad25d387543b6f10145d7c6eab5ec30f/480/',24.9459637,45.9908543,'SA Dhurma Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59785867/edge-world-mtl-haf-alaaalm-mn-tryk-alaayyn',1,0,'مطل حافه عالم من طريق عيينه edge of the world اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785862,'riyadh-region','حدائق الفراولة المعلقة بالدرعية','Hanging Strawberry Gardens','hanging-strawberry-gardens-hdayk-alfraol-almaalk-baldraay','["أماكن سياحية"]','["sights"]','حدائق الفراولة المعلقة بالعمارية تقدم لزوارها فرصة فريدة للتعرف على نبات الفراولة وتجربة قطف ثمارها الطازجة اللذيذة بأيديهم ومشاهدة النحل الطنان وهو يلقح...','<div class="texte" > <p>حدائق الفراولة المعلقة بالعمارية تقدم لكم فرصة فريدة للتعرف على نبات الفراولة وتجربة قطف ثمارها الطازجة اللذيذة بأيديكم ومشاهدة النحل الطنان وهو يلقح الأزهار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785862-44462082.jpg?v=1638800107"]','https://cmsphoto.ww-cdn.com/resizeapi/2b9781a1c3c563e95a89ec8f9a876097f3489196/480/',24.8065803,46.4302665,'SA العمارية Diriyah','','','','https://www.saudi-guide.com/riyadh-region/i/59785862/hanging-strawberry-gardens-hdayk-alfraol-almaalk-baldraay',1,0,'حدائق فراوله معلقه بالدرعيه hanging strawberry gardens اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785823,'riyadh-region','مزرعة صوفي ورمضان الزهراني','','mzraa-sofy-ormdan-alzhrany','["أماكن سياحية"]','["sights"]','مزرعة بسيطه أجوائها ريفيه في قلب المدينه يتم فيها بيع الخضار يمكن شراء المنتجات والمحاصيل الزراعية ويمكن التجول فقط في المزرعة من خلال الممرات بين...','<div class="texte" > <p>مزرعة بسيطه أجوائها ريفيه في قلب المدينه يتم فيها بيع الخضار يمكن شراء المنتجات والمحاصيل الزراعية ويمكن التجول فقط في المزرعة من خلال الممرات بين المزروعات لايسمح بالافتراش والجلوس في المزرعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785823-44462088.jpg?v=1638800133"]','https://cmsphoto.ww-cdn.com/resizeapi/38cce70188c20289a85964a9a44a75bcb4846537/480/',24.7297223,46.5741631,'Wadi Hanifah Ad Diriyah Ar-Riyad','','','','https://www.saudi-guide.com/riyadh-region/i/59785823/mzraa-sofy-ormdan-alzhrany',1,0,'مزرعه صوفي ورمضان زهراني اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785816,'riyadh-region','ميدان سهام (اسهم و اقواس) بالدرعية','Archery Range (Bow and Arrow)','archery-range-bow-and-arrow-mydan-sham-ashm-o-akoas-baldraay','["أماكن سياحية"]','["sights"]','ميدان رماية بالقوس والسهم، بالإضافة لتجارب عديدة ممتعة.','<div class="texte" > <p>ميدان رماية بالقوس والسهم، بالإضافة لتجارب عديدة ممتعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785816-44462095.jpg?v=1638800157"]','https://cmsphoto.ww-cdn.com/resizeapi/96fbda38d7bcf9c52dfc5d03560546a50136a427/480/',24.7405023,46.584138,'Mohammed Al Faisaliyah Riyadh','','','','https://www.saudi-guide.com/riyadh-region/i/59785816/archery-range-bow-and-arrow-mydan-sham-ashm-o-akoas-baldraay',1,0,'ميدان سهام (اسهم و اقواس) بالدرعيه archery range (bow and arrow) اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785777,'riyadh-region','نفود ثرمداء','','nfod-thrmdaaa','["أماكن سياحية"]','["sights"]','نفود ثرمداء امتداد رملي في محافظة مرات، يجذب محبي التصوير والرحلات البرية بطبيعته الصحراوية الخلابة.','','[]','',25.163555,45.5041765,'5G73+CMF Tharmda Marat','','','','https://www.saudi-guide.com/riyadh-region/i/59785777/nfod-thrmdaaa',1,0,'نفود ثرمداء اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785769,'riyadh-region','ممالح القصب','Al Qasab Salt Flats','al-qasab-salt-flats-mmalh-alksb','["أماكن سياحية"]','["sights"]','ممالح القصب هي مكان استخراج الملح وفيها يمكن للسياح معرفة كيفية استخراج الملح وكذلك يمكنهم شراؤه.','<div class="texte" > <p>ممالح القصب هي مكان استخراج الملح وفيها يمكن للسياح معرفة كيفية استخراج الملح وكذلك يمكنهم شراؤه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785769-44462102.jpg?v=1638800193"]','https://cmsphoto.ww-cdn.com/resizeapi/78452b9f7243ae0b84a6860739641d16a6eb50dc/480/',25.2559883,45.5582201,'Al Qasab Salt Flats Riyadh Province SA','','','','https://www.saudi-guide.com/riyadh-region/i/59785769/al-qasab-salt-flats-mmalh-alksb',1,0,'ممالح قصب al qasab salt flats اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785768,'riyadh-region','بحيرة برودان','Lake Prodan','lake-prodan-bhyr-brodan','["أماكن سياحية"]','["sights"]','بحيرة برودان هي بحيرة مالحة في واحة في صحراء النفود، وتعد وجهة مميزة لعشاق البر.','<div class="texte" > <p>بحيرة برودان هي بحيرة مالحة في واحة في صحراء النفود، وتعد وجهة مميزة لعشاق البر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785768-44462119.jpg?v=1638800225"]','https://cmsphoto.ww-cdn.com/resizeapi/8d2c04286f19356f668dd214cac19634a057e90a/480/',25.189667,45.62025,'SA Marat Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59785768/lake-prodan-bhyr-brodan',1,0,'بحيره برودان lake prodan اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785762,'riyadh-region','وادي المشقر','','oady-almshkr','["أماكن سياحية"]','["sights"]','وادي المشقر في المجمعة من أكبر أودية سدير بطول يتجاوز 100 كم، يشتهر بأشجاره الكبيرة ونباتاته البرية ويكتسي بالخضرة بعد أمطار الربيع.','<div class="texte" > <p>وادي المشقر من أكبر أودية سدير، ويتجاوز طوله 100 كيلومتر، يبدأ من المرتفعات القريبة من المجمعة ويتجه شمال شرق مروراً بسد المجمعة ومزارع النخيل فيها، ويفصل بين حرمة والمجمعة. ويشتهر بأشجاره الكبيرة ونباتاته البرية المتنوعة خاصة في روضة المزيرعة أعلى الوادي، ويكتسي بالخضرة بعد أمطار الربيع.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785762-68552172.jpg?v=1791638431"]','https://cmsphoto.ww-cdn.com/resizeapi/672b5dff9ba273d2fd34923c42a356d1b397bf6e/480/',25.8804809,45.2990811,'FQJF+V4M Uraidh المجمعة','','','','https://www.saudi-guide.com/riyadh-region/i/59785762/oady-almshkr',1,0,'وادي مشقر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785760,'riyadh-region','منتزه الجزر','','mntzh-algzr','["أماكن سياحية"]','["sights"]','منتزه جميل يحتوي على منطقة ألعاب للأطفال وجلسات مفتوحة ومغلقة للشباب والعوائل.','<div class="texte" > <p>منتزه جميل يحتوي على منطقة ألعاب للأطفال وجلسات مفتوحة ومغلقة للشباب والعوائل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785760-44462138.jpg?v=1638800267"]','https://cmsphoto.ww-cdn.com/resizeapi/2201172b132070efbf227bed80c711d966c630b7/480/',25.6920136,45.447837,'MCRX+R44 Jalajil Al Majmaah','','','','https://www.saudi-guide.com/riyadh-region/i/59785760/mntzh-algzr',1,0,'منتزه جزر اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785688,'riyadh-region','محمية الراشد للطيور','','mhmy-alrashd-lltyor','["أماكن سياحية"]','["sights"]','محمية الراشد للطيور محمية طبيعية في محافظة المجمعة بمنطقة الرياض، تحتضن أنواعًا متعددة من الطيور البرية.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785688-44462147.jpg?v=1638800288"]','https://cmsphoto.ww-cdn.com/resizeapi/213ef68d44b7d74ca532f2463117393cb493ecc6/480/',25.5836482,45.6184527,'Al Janoubiyah Al Majmaah Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59785688/mhmy-alrashd-lltyor',1,0,'محميه راشد للطيور اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785685,'riyadh-region','محمية طيور الامازون','Amazon protected birds','amazon-protected-birds-mhmy-tyor-alamazon','["أماكن سياحية"]','["sights"]','تعتبر محمية طيور الامازون من أجمل المقاصد السياحية لسكان الجوف وزوارها، حيث تضم أنواعاً متعددة من طيور الزينة جمعت من مختلف دول العالم.','<div class="texte" > <p>تعتبر محمية طيور الامازون من أجمل المقاصد&nbsp;السياحية&nbsp;لسكان الجوف وزوارها حيث تضم المحمية 4000 طائر زينة من 39 نوع مختلِف تم جمعها من مختلَف دول العالم وتم خلق بيئة مناسبة تجمع كل الأنواع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785685-44463057.jpg?v=1638804273"]','https://cmsphoto.ww-cdn.com/resizeapi/0874bd5d06784cd8f5b72d4c369bb24a6fc3c0ce/480/',25.7154143,45.8559023,'أبوبكر الصديق King Faisal Tumair','','','','https://www.saudi-guide.com/riyadh-region/i/59785685/amazon-protected-birds-mhmy-tyor-alamazon',1,0,'محميه طيور امازون amazon protected birds اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785620,'riyadh-region','وادي ماوان','The Hidden Canyon','hidden-canyon-oady-maoan','["أماكن سياحية"]','["sights"]','وادي ماوان من أودية نجد يقع بالقرب من مدينة الدلم، يتميز بحوافه العالية وينحدر من جبال طويق حيث يقع مجراه الأعلى.','<div class="texte" > <p>وادي ماوان من أودية نجد&nbsp;يقع بالقرب من مدينة الدلم،&nbsp;يتميز الوادي بحوافه العالية وينحدر من جبال طويق حيث يقع مجراه الأعلى&nbsp;وينتهي غرب بلدة الرغيب إلى الجنوب من مدينة الدلم&nbsp;وبه مزارع وتجمعات لأشجار الطلح.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785620-44463063.jpg?v=1638804300"]','https://cmsphoto.ww-cdn.com/resizeapi/56156815b619376b05a25ad6dc12a10927479f70/480/',23.9100513,46.9419676,'SA Al-Kharj Riyadh Province','','','','https://www.saudi-guide.com/riyadh-region/i/59785620/hidden-canyon-oady-maoan',1,0,'وادي ماوان the hidden canyon اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785616,'riyadh-region','غار الامام تركي بن عبدالله ( غار الشيوخ )','','ghar-alamam-trky-bn-aabdallh-ghar-alshyokh','["أماكن سياحية"]','["sights"]','يقع غار الإمام تركي أو كما يسمى "غار الشيوخ" في هضبة العلية والتي تعد الهضبة الأكبر والأمنع في جبل اليمامة والأكثر أودية والأشد ارتفاعاً.','<div class="texte" > <p>يقع غار الإمام تركي أو كما يسمى "غار الشيوخ" في هضبة العلية والتي تعد الهضبة الأكبر والأمنع في جبل اليمامة والأكثر أودية والأشد ارتفاعاً، وقد سمي غار الإمام تركي بهذا الاسم نسبة إلى الإمام تركي بن عبد الله بن محمد آل سعود الذي اتخذه ملجأ يحتمي به من ظلم الأتراك الغزاة ولما سنحت له الفرصة طردهم من نجد، وقد تزوج الإمام تركي في هذا الغار أيضاً وأنجب ولدا أسماه جلوياً نسبة إلى جلوته في هذا الغار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785616-44463069.jpg?v=1638804324"]','https://cmsphoto.ww-cdn.com/resizeapi/105b2fa791710d3755c1444c29d9201c0c1f4e32/480/',23.9478,46.4288,'WCXH+4GF الجفير المزاحمية','','','','https://www.saudi-guide.com/riyadh-region/i/59785616/ghar-alamam-trky-bn-aabdallh-ghar-alshyokh',1,0,'غار امام تركي بن عبدالله ( غار شيوخ ) اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785612,'riyadh-region','برج الخرج','','brg-alkhrg','["أماكن سياحية"]','["sights"]','يعد البرج أحد أبرز معالم الخرج، يقع بمدخل المحافظة على طريق الرياض السريع. يبلغ ارتفاع برج الخرج 105 أمتار عن سطح الأرض.','<div class="texte" > <p>يُعد البرج أحد أبرز المعالم الخرج،&nbsp;يقع بمدخل المحافظة على طريق الرياض السريع. يبلغ ارتفاع برج الخرج 105 أمتار عن سطح الأرض.</p> <hr /> <p>يتكون البرج من خمسة أدوار على النحو التالي:</p> <p>دور القبو: ويحتوي على مكاتب الإدارة والفنيين والتحكم والمراقبة والمطبخ الرئيسي والمحطة الفرعية الكهربائية بالإضافة إلى الغرف الكهربائية والميكانيكية لوحدات التبريد والتكييف وقد تعرضت لأضرار بالغة نتيجة غمرها بالسيول أثناء مداهمة السيول لمحافظة الخرج عام 1424 هـ وخصوصاً الأنظمة الالكترونية وأنظمة المراقبة والتحكم وأنظمة الإنذار ومكافحة الحريق بالإضافة إلى وحدات خلط الهواء والمراوح الإرجاعية الموجودة بدور القبو.</p> <p>الدور الأول: يحتوي على صالات للتسوق وللمحاضرات وللاستقبال وكافتيريا للعوائل وصالة للمعارض الفنية.</p> <p>الدور الثاني: ويحتوي على مطاعم للعوائل والعزاب وكذلك المطل.</p> <p>الدور الثالث: وهو بالكامل عبارة عن مطعم دوار (بأرضية متحركة) بالإضافة إلى ملحق المطبخ العلوي مجهز بثلاجات تبريد ذات طاقة تخزينية عالية وهو يتسع لقرابة 320 شخصاً في وقت واحد ومجهز بالطاولات والكراسي.</p> <p>الدور الرابع: دور الميكانيكا ويحتوي على أجهزة التكييف المركزي والمبردات الرئيسية وغرف المصاعد ومحطة كهربائية فرعية ووحدات التبريد ومضخات الإمداد والتي تقدم الخدمات المساندة للبرج.</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785612-44463071.jpg?v=1638804345"]','https://cmsphoto.ww-cdn.com/resizeapi/05ec439b3215aa17b61a951b450b42621dc0f905/480/',24.1628282,47.2985043,'SA Al Burj Al-Kharj','','','','https://www.saudi-guide.com/riyadh-region/i/59785612/brg-alkhrg',1,0,'برج خرج اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59785584,'riyadh-region','مزرعة محمد بن سعد العبيدي بالخرج','','mzraa-mhmd-bn-saad-alaabydy-balkhrg','["أماكن سياحية"]','["sights"]','مزرعة محمد بن سعد العبيدي هي مزرعة متخصصة في زراعة الفراولة تتيح لزوارها فرصة الاستمتاع بالتجول بها وقطف ثمار الفراولة.','<div class="texte" > <p>مزرعة محمد بن سعد العبيدي هي مزرعة متخصصة في زراعة الفراولة تتيح لزوارها فرصة الاستمتاع بالتجول بها وقطف ثمار الفراولة&nbsp;كما تقدم المزرعة عصير الفراولة الطازج ومربى الفراولة اللذيذ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59785584-44463077.jpg?v=1638804371"]','https://cmsphoto.ww-cdn.com/resizeapi/03f845386e607015fb65661bd2d0157fab55314f/480/',24.1932278,47.3220917,'السيح Al-Kharj Al-Kharj','','','','https://www.saudi-guide.com/riyadh-region/i/59785584/mzraa-mhmd-bn-saad-alaabydy-balkhrg',1,0,'مزرعه محمد بن سعد عبيدي بالخرج اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783581,'tabuk-region','متحف مغاير النبي شعيب عليه السلام','Maghayir Shuaib','mthf-mghayr-alnby-shaayb-aalyh-alslam','["التراث والثقافة"]','["heritage"]','مغاير شعيب في البدع بمنطقة تبوك، مدينة مدين الأثرية ذات المقابر والواجهات المنحوتة في الصخر، الشبيهة بآثار الحجر، والمرتبطة بقصة النبي شعيب عليه السلام.','<div class="texte" > <p>مدائن شعيب، أو&nbsp;مغاير شعيب&nbsp;أو&nbsp;مدين&nbsp;هي مدينة أثرية تضم بيوت ومعابد أثرية منحوته في الصخر والجبال تقع في&nbsp;إقليم الحجاز&nbsp;غرب شبه الجزيرة العربية، وحاليًا في مدينة تسمى&nbsp;البدع&nbsp;في&nbsp;منطقة تبوك، وهي شبيهه بآثار مدينة الحجر (مدائن صالح) يرى بعض علماء الأثار أنها تعود إلى الألفية الثانية قبل الميلاد، وكان سكانها من قبيلة&nbsp;مدين.</p> <p>ذكرت&nbsp;مدين&nbsp;عدة مرات في النصوص التوراتية وذكرت في القرآن الكريم أن النبي موسى لجأ اليهم وصاهرهم وأن مساكن مدين قريبة من مساكن ثمود في الحجر وأن الله بعث في أهل مدين نبي منهم&nbsp;شعيب&nbsp;لكي يحضهم على المتاجرة الشريفة فرفضوا أن يسمعوا دعوته بأن يؤمنوا بالله ويتركوا المعاصي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783581-44703303.jpg?v=1640795366"]','https://cmsphoto.ww-cdn.com/resizeapi/0d5a5ec425b67a610749a20a27b5527a6e9d9c3d/480/',28.4878045,35.0033202,'SA البدع البدع','','','','https://www.saudi-guide.com/tabuk-region/i/59783581/mthf-mghayr-alnby-shaayb-aalyh-alslam',1,0,'متحف مغاير نبي شعيب عليه سلام maghayir shuaib تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783575,'tabuk-region','حطام الطائرة المائية كاتالينا','Catalina Seaplane Wreckage','catalina-seaplane-wreckage-katlyna-htam-altayrh-almayy','["التراث والثقافة"]','["heritage"]','حطام طائرة كاتالينا البرمائية على شاطئ خليج العقبة في منطقة تبوك، طائرة عسكرية أمريكية سقطت نحو عام 1960 وتحولت إلى معلم سياحي ومقصد للمصورين.','<div class="texte" > <p>يقع حطام طائرة كاتالينا على شاطئ خليج العقبة قرب رأس الشيخ حميد في منطقة تبوك، وهي طائرة برمائية عسكرية أمريكية سقطت في المنطقة نحو عام 1960، ولا يزال حطامها مستقرًا على الشاطئ حتى اليوم، لتتحول إلى معلم سياحي ومقصد لهواة التصوير والمغامرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783575-44704157.jpg?v=1640799723"]','https://cmsphoto.ww-cdn.com/resizeapi/0527dd87000da577a42e48a53bd073119841b649/480/',28.090771,34.608709,'3JR5+8F4 Ras Gasabah Al Bad','','','','https://www.saudi-guide.com/tabuk-region/i/59783575/catalina-seaplane-wreckage-katlyna-htam-altayrh-almayy',1,0,'حطام طائره مائيه كاتالينا catalina seaplane wreckage تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783526,'tabuk-region','قلعة المعظم','Al Muadham Castle','klaa-almaathm','["التراث والثقافة"]','["heritage"]','قلعة المعظم جنوب شرق مدينة تبوك، من أكبر القلاع العثمانية على طريق الحج الشامي، بُنيت عام 1031هـ لحماية الحجاج، وتضم بركة ونقوشًا تأسيسية على واجهتها.','<div class="texte" > <p>قلعة المعظم الأثرية&nbsp;هي قلعة تاريخية تعد من آثار العصور الإسلامية المتأخرة، وتقع جنوب شرق مدينة&nbsp;تبوك&nbsp;بمركز المعظم؛ أنشئت سنة&nbsp;1031 هـ&nbsp;الموافقة لسنة&nbsp;1622م&nbsp;في عهد السلطان العثماني&nbsp;عثمان الثاني، وهي من منازل الطريق الشامي، وتعد من أكبر القلاع العثمانية التي كانت تستخدم لمراقبة الحجيج وحمايتهم، وتشمل&nbsp;برّكة المعظم&nbsp;ومحطة سكة الحديد، حيث يوجد على واجهة هذه القلعة أربعة نقوش تأسيسية لبنائها.</p> <p>&nbsp;</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783526-44703304.jpg?v=1640795384"]','https://cmsphoto.ww-cdn.com/resizeapi/765a156082fa91508071c5784b277e2a9fda869e/480/',27.7408897,37.5087619,'SA Tabouk Tabuk Province','','','','https://www.saudi-guide.com/tabuk-region/i/59783526/klaa-almaathm',1,0,'قلعه معظم al muadham castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783521,'tabuk-region','قصر الرضم','Al Radm Palace','ksr-alrdm-arradam-palace','["التراث والثقافة"]','["heritage"]','قصر الرضم غرب تيماء، قصر أثري مستطيل تتوسطه بئر وتدعم جدرانه الحجرية دعامات في أركانها، ويعود بناؤه إلى العصر الحديدي في الألف الأول قبل الميلاد.','<div class="texte" > <p>يقع قصر الرضم في الجهة الغربية من&nbsp;تيماء، وهو عبارة عن قصر في منتصفه بئر، ويتخذ الشكل&nbsp;المستطيل&nbsp;حيث يبلغ طوله 34×25 م، وارتفاع جدرانه تصل إلى 3،5م، وقد يزيد السُمك إلى مترين، وقد دُعمت هذه الجدران بدعامات من حجارة في أركانها ووسطها وخارجها، ويعود بناء القصر إلى&nbsp;العصر الحديدي&nbsp;في النصف الأول من الألف&nbsp;قبل الميلاد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783521-44703311.jpg?v=1640795406"]','https://cmsphoto.ww-cdn.com/resizeapi/6cee6ebdedad81f30e1e8a7bdb5abab8937f8473/480/',27.6354019,38.5413577,'JGPR+5G9 Tayma Tayma','','','','https://www.saudi-guide.com/tabuk-region/i/59783521/ksr-alrdm-arradam-palace',1,0,'قصر رضم al radm palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783520,'tabuk-region','متحف تيماء','Taima Museum','taima-museum-mthf-tymaaa','["التراث والثقافة"]','["heritage"]','متحف تيماء للآثار، يعرض خرائط المواقع الأثرية في تيماء وقطعًا ونقوشًا صخرية قديمة من العصر الحجري حتى العصر الإسلامي، ومن أبرز مقتنياته مسلة تيماء.','<div class="texte" > <p>متحف تيماء، هو متحف للآثار يقع في مدينة&nbsp;تيماء&nbsp;بالسعودية،&nbsp;تم بناء المتحف سنة 1403هـ الموافق 1983م وافتتح لاستقبال الزوار عام 1407هـ الموافق 1987م.</p> <p>يحتوي المتحف على لوحات لخرائط المواقع الأثرية بتيماء وتعرض مجموعة من القطع الأثرية والكتابات والنقوش الصخرية القديمة المنتشرة في المنطقة، ومن أهمها&nbsp;مسلة تيماء&nbsp;والتي عرضت لفترة&nbsp;بمتحف اللوفر&nbsp;بباريس، ويضم المتحف مكتبة تحتوي على مجموعة من الكتب المتخصصة بالإضافة إلى بعض الدوريات والنشرات، ويحتوي المتحف أيضاً على قطعٍ مختارة من الحفريات الأثرية التي قامت بها وكالة&nbsp;الآثار&nbsp;في المنطقة حسب تسلسلها الزمني بدءاً من&nbsp;العصر الحجري&nbsp;حتى العصر الإسلامي، كما يتوفر بالمتحف تمثال قريب الشبه بالنمط اللحياني ويحمل رأس&nbsp;الأسد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783520-44703320.jpg?v=1640795452"]','https://cmsphoto.ww-cdn.com/resizeapi/a539fc30f29c307ef7604fc87092e31770f4dab0/480/',27.628145,38.5443782,'King Faisal Rd Tayma Tayma','','','','https://www.saudi-guide.com/tabuk-region/i/59783520/taima-museum-mthf-tymaaa',1,0,'متحف تيماء taima museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783518,'tabuk-region','بئر هداج','Haddaj Well','hadaj-well-byr-hdag','["التراث والثقافة"]','["heritage"]','بئر هداج في تيماء، من أشهر آبار الجزيرة العربية، بئر دائرية واسعة مطوية بالحجارة وسط البلدة القديمة يُعتقد أنها تعود إلى الألف الأول قبل الميلاد.','<div class="texte" > <p>بئر هداج، من أشهر الآبار في&nbsp;جزيرة العرب&nbsp;ويقع في شمال غرب&nbsp;المملكة العربية السعودية&nbsp;في مدينة&nbsp;تيماء&nbsp;وفيه عين من زاويته الجنوبية لا زالت ترفده إلى الآن وفوهة البئر واسعة يبلغ قطرها 15 مترا (50 قدماً) وعمقها 12 مترا (40 قدماً)، ذات شكل دائري غير منتظم، مطوية بالحجارة، ضرب بها المثل بالكرم فوصف الرجل المعطاء ب "هداج تيماء"،&nbsp;يقع البئر في وسط البلدة القديمة داخل إطار دائري من أشجار النخيل الباسقة،&nbsp;يعتقد أن البئر يعود إلى الألف الأول ق.م.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783518-44703323.jpg?v=1640795472"]','https://cmsphoto.ww-cdn.com/resizeapi/f9d3111b377d2b9714543ce25835aed2e3f3df27/480/',27.6348019,38.553434,'Tayma Tayma Tabuk Province','','','','https://www.saudi-guide.com/tabuk-region/i/59783518/hadaj-well-byr-hdag',1,0,'بئر هداج haddaj well تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783434,'tabuk-region','قصر الأمير عبدالكريم الرمان','Prince Abdulkarim Al Rumman Palace','karim-pomegranate-palace-ksr-alamyr-aabdalkrym-alrman','["التراث والثقافة"]','["heritage"]','قصر ابن رمان في تيماء بجوار بئر هداج، بُني من الحجارة واللبن بتعاون الأهالي، ويضم أبراجًا ومسجدين شتويًا وصيفيًا وفناءً كبيرًا، وظل مقرًا للإمارة لعقود.','<div class="texte" > <p>يقع قصر المذرعية أو قصر ابن رمان بجوار&nbsp;بئر هداج&nbsp;الأثري الشهير،&nbsp;أمر بتشييده وبنائه الأمير عبد&nbsp;الكريم بن علي الرمان، حاكم مدينة تيماء في ذلك الزمن، وبني خلال النصف الأول من القرن الهجري الماضي من الحجارة واللبن،&nbsp;وقد تعاون أهالي تيماء رجالًا ونساءً في بنا القصر، ما يؤكد على قدرة وتحمل الأهالي على البناء الرائع والجميل، حيث بنى الأهالي القصر من مواد الطبيعة المتاحة لديهم في البلدة، وانفرد بطراز عمراني ليعد نموذجًا واقعيًا ونادرًا لأسلوب البناء التقليدي. يتميز القصر بازدواجية الجدران الخارجية، بالإضافة إلى الأبراج كما يحتوي القصر على مسجدين، أحدهما شتوي والآخر صيفي، وفناء كبير داخل القصر، وعدد كبير من الغرف الداخلية،&nbsp;وقد ظل القصر مقرًا للإمارة حتى عام 1398هـ، ظل القصر صامدًا لأكثر من 100 عام، مقاومًا بجماله كل تغيرات الأجواء، ليشهد على فترة تاريخية هامة عاشتها محافظة تيماء بمنطقة تبوك شمال السعودية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783434-44703347.jpg?v=1640795537"]','https://cmsphoto.ww-cdn.com/resizeapi/bba660352cc3f1b1d5dc36258cb5c05344dbb539/480/',27.6343558,38.5560599,'الامام الشافعي Tayma Tayma','','','','https://www.saudi-guide.com/tabuk-region/i/59783434/karim-pomegranate-palace-ksr-alamyr-aabdalkrym-alrman',1,0,'قصر امير عبدالكريم رمان prince abdulkarim al rumman palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783411,'tabuk-region','سور تيماء الأثري','Tayma Ancient Wall','sor-tymaaa-alathry','["التراث والثقافة"]','["heritage"]','سور تيماء الأثري، من أطول أسوار الجزيرة العربية وأقدمها، يحيط بالمدينة القديمة من ثلاث جهات ويمتد لأكثر من 10 كيلومترات، ويعود بناؤه إلى آلاف السنين.','<div class="texte" > <p>سور تيماء&nbsp;أو سور&nbsp;تيماء&nbsp;القديم، هو سور يحيط بمدينة تيماء القديمة من الجهات الغربية والجنوبية والشرقية عدا الجهة الشمالية التي تشغلها الأرض الملحية المعروفة بالسبخة،&nbsp;يبلغ طول السور أكثر من 10 - 15 كيلومتر، وهو مشيد من&nbsp;الحجارة&nbsp;واللبن&nbsp;والطين، ويبلغ ارتفاعه حاليًا في بعض الأجزاء أكثر من عشرة أمتار، ويقل ارتفاعه في بعض الأجزاء حتى يصل إلى المتر الواحد تقريبًا،&nbsp;عرض السور يتراوح بين المتر والمترين، وهو أطول أسوار الجزيرة العربية، ومن أقدم الأسوار الأثرية في العالم؛ يعود تاريخ بنائه إلى الألفية الأولى قبل الميلاد، لكن الأبحاث العلمية الحديثة أظهرت أن تاريخ بنائه يعود إلى الألفية الثانية&nbsp;قبل الميلاد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783411-44703360.jpg?v=1640795559"]','https://cmsphoto.ww-cdn.com/resizeapi/7868d189b9eca4b1c85328cc0adc6b13dcfbd69b/480/',27.6173655,38.5533351,'JH83+W8W Tayma Tayma','','','','https://www.saudi-guide.com/tabuk-region/i/59783411/sor-tymaaa-alathry',1,0,'سور تيماء اثري tayma ancient wall تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783405,'tabuk-region','حطام سفينة جورجيوس جي في حقل','Georgios G Shipwreck','htam-sfyn-gorgyos-gy-fy-hkl','["التراث والثقافة"]','["heritage"]','حطام سفينة جورجيوس جي اليونانية على ساحل حقل، جنحت على الشعاب المرجانية عام 1978 وتُعرف بتايتانيك السعودية، ومن أشهر معالم التصوير في منطقة تبوك.','<div class="texte" > <p>يقع حطام سفينة جورجيوس جي على ساحل محافظة حقل في منطقة بئر الماشي، وهي سفينة يونانية بُنيت في إنجلترا عام 1949، وجنحت على الشعاب المرجانية في 4 أبريل 1978 أثناء نقلها شحنة من الدقيق. تُعرف السفينة بـ«تايتانيك السعودية»، وأصبحت من أشهر المعالم السياحية على ساحل حقل بخلفيتها من الجبال المرتفعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783405-44704174.jpg?v=1640799747"]','https://cmsphoto.ww-cdn.com/resizeapi/023810335af741faa33d4dd61a04ee6870cc6ca1/480/',28.8770555,34.8323464,'SA 49765 ','','','','https://www.saudi-guide.com/tabuk-region/i/59783405/htam-sfyn-gorgyos-gy-fy-hkl',1,0,'حطام سفينه جورجيوس جي في حقل georgios g shipwreck تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783402,'tabuk-region','قلعة المويلح العثمانية','Ottoman Castle Al Muwaileh','ottoman-castle-al-muwaileh-klaa-almoylh-alaathmany','["التراث والثقافة"]','["heritage"]','قلعة المويلح قرب ضباء، من كبرى قلاع طريق الحج الساحلي، بُنيت في عهد السلطان سليمان القانوني عام 968هـ، وتضم فناءً ومسجدًا وبئرًا وأبراجًا في أركانها.','<div class="texte" > <p>قلعة المويلح الأثرية&nbsp;هي قلعة تاريخية ضخمة تقع بالقرب من&nbsp;مركز المويلح&nbsp;التابع&nbsp;لمحافظة ضباء&nbsp;بمنطقة تبوك، كانت سابقاً إحدى المحطات الرئيسية لطريق الحج الساحلي وبوابة من بوابات الشمال في العصور الإسلامية المتأخرة وبنيت في عهد السلطان&nbsp;سليمان القانوني&nbsp;سنة&nbsp;968 هـ&nbsp;/&nbsp;1560م، وقد عمرت 400 عام ويعتبرها بعض المؤرخين من أكبر القلاع&nbsp;بالمملكة العربية السعودية، ومن كبرى القلاع القائمة على طريق الحج وبداخلها فناء ومسجد وبئر، ويحيط بالفناء من جميع الجهات وحدات أقيمت لخدمة الحجاج، كما أن للقلعة أبراج من مختلف الأركان الأربعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783402-44703668.jpg?v=1640796944"]','https://cmsphoto.ww-cdn.com/resizeapi/ae0bfef437d95e9d24181f221ac80675992acb3f/480/',27.6821286,35.4759953,'Al Muwaylih Duba Tabuk Province','','','','https://www.saudi-guide.com/tabuk-region/i/59783402/ottoman-castle-al-muwaileh-klaa-almoylh-alaathmany',1,0,'قلعه مويلح عثمانيه ottoman castle al muwaileh تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783396,'tabuk-region','قلعة الملك عبدالعزيز التاريخية في حقل','King Abdulaziz Castle in Haql','klaa-almlk-aabdalaazyz-altarykhy-fy-hkl','["التراث والثقافة"]','["heritage"]','قلعة الملك عبدالعزيز التاريخية في البلدة القديمة بمحافظة حقل، من القلاع التي بُنيت في عهد الملك عبدالعزيز إبان مرحلة تأسيس المملكة العربية السعودية.','<div class="texte" > <p>قلعة الملك عبد العزيز&nbsp;هي أحد القلاع التي بنيت في عهد&nbsp;الملك عبد العزيز&nbsp;إبان مرحلة تأسيس&nbsp;المملكة العربية السعودية، في منطقة تبوك&nbsp;بمحافظة حقل&nbsp;في حي البلدة القديم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783396-44703659.jpg?v=1640796872"]','https://cmsphoto.ww-cdn.com/resizeapi/103fdbb91586e4be3f1b01ed944786eefc5da668/480/',29.2967586,34.9464329,'Haql Al Sabkhah Haql','','','','https://www.saudi-guide.com/tabuk-region/i/59783396/klaa-almlk-aabdalaazyz-altarykhy-fy-hkl',1,0,'قلعه ملك عبدالعزيز تاريخيه في حقل king abdulaziz castle in haql تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783395,'tabuk-region','قلعة الملك عبدالعزيز في ضبا','King Abdulaziz Castle in Duba','klaa-almlk-aabdalaazyz-king-abdulaziz-fort','["التراث والثقافة"]','["heritage"]','قلعة الملك عبدالعزيز في ضباء، بُنيت عام 1352هـ من الحجر الجيري على تلة تشرف على السوق القديم لتكون مقرًا للإمارة، ومن أهم قلاع منطقة تبوك.','<div class="texte" > <p>بنيت قلعة الملك عبد&nbsp;العزيز في عام&nbsp;1352 هـ&nbsp;الموافق&nbsp;1933م، على تلّة مرتفعة تشرف على السوق من جهة الغرب لتكون مقراً للحكم السعودي في المنطقة،&nbsp;القلعة تعد من أهم القلاع في&nbsp;منطقة تبوك، تقع في&nbsp;محافظة ضباء&nbsp;التابعة&nbsp;لمنطقة تبوك&nbsp;شمال غرب&nbsp;المملكة العربية السعودية، بنيت القلعة على هضبة مرتفعة لجعلها مقراً لإمارة المنطقة، وقد بنيت من الحجر الجيري على نمط القلاع بالمنطقة وتم ترميمها لتكون مرفقاً سياحياً،&nbsp;وتبلغ مساحة القلعة 1000 متر مربع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783395-44703656.jpg?v=1640796806"]','https://cmsphoto.ww-cdn.com/resizeapi/9e1304b27ee52095e56a2e7d02652d8fb9bd53ee/480/',27.348411,35.6948645,'قلعة الملك عبدالعزيز King Abdulaziz fort Albalad Duba','','','','https://www.saudi-guide.com/tabuk-region/i/59783395/klaa-almlk-aabdalaazyz-king-abdulaziz-fort',1,0,'قلعه ملك عبدالعزيز في ضبا king abdulaziz castle in duba تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59783378,'tabuk-region','قلعة الأزلم في ضبا','Al Azlam Castle','alozlam-castle-klaa-alaznm-fy-dba','["التراث والثقافة"]','["heritage"]','قلعة الأزلم في وادي الأزنم جنوب ضباء، من محطات طريق الحج المصري في العصور الإسلامية المتأخرة، مبنية من الحجر الجيري وتضم فناءً كبيرًا وحجرات وديوانًا.','<div class="texte" > <p>تقع قلعة الأزلم&nbsp;في وادي الأزنم جنوب مدينة ضباء، وهي من محطات طريق الحج المصري خلال العصور الإسلامية المتأخرة،&nbsp;وتتكون من فناء كبير ووحدات داخلية وحجرات مستطيلة الشكل ونصف دائرية وديوان، القلعة مبنية من الحجر الجيري المنظم وفناء القلعة يفتح على جميع الوحدات الداخلية التي تضمها القلعة من حجرات، تبلغ مساحة القلعة 1500 متر مربع، وهي قريبة جد من الطريق العام الذي يربط ضباء بالوجه، وهي الآن محاطة بسور لحمايتها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59783378-44704181.jpg?v=1640799773"]','https://cmsphoto.ww-cdn.com/resizeapi/eb80bd9e6aa5708a2c3c2bc011ac06d11bb5ee9e/480/',27.0397536,36.0194992,'SA Duba Tabuk Province','','','','https://www.saudi-guide.com/tabuk-region/i/59783378/alozlam-castle-klaa-alaznm-fy-dba',1,0,'قلعه ازلم في ضبا al azlam castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049906,'riyadh','مطعم ليالي العراق','Layali Al Iraq','layali-al-iraq-mtaam-lyaly-alaarak','["مطاعم"]','["food"]','مطعم ليالي العراق مطعم عراقي عصري يتميز بتقديم أطباق متنوعة شهية داخل بوليفارد سيتي، ويشتهر بالدولمة والشوربة العدسية والخبز الساخن المقدم مباشرة من الفرن.','<div class="texte" > <p>مطعم ليالي العراق مطعم عراقي عصري يتميز بتقديم أطباق متنوعة شهية داخل بوليفارد سيتي، ويشتهر بالدولمة والشوربة العدسية والخبز الساخن المقدم مباشرة من الفرن. يقدم شايًا وتمرًا مجانيًا بعد الوجبة كلمسة ضيافة عراقية أصيلة، وسط أجواء فاخرة وأنيقة. للتواصل أو الحجز: 0553800033، ومواعيد الدوام من 4:00 عصرًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049906-68541974.jpg?v=1791538470", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049906-68541979.jpg?v=1791538490"]','https://cmsphoto.ww-cdn.com/resizeapi/3a9b82cf50caded346ce99f0131ce1ef6bcbed24/480/',24.7671713,46.604085,'بوليفارد سيتي، حطين، الرياض 23442','0553800033','','','https://www.saudi-guide.com/riyadh/i/98049906/layali-al-iraq-mtaam-lyaly-alaarak',1,0,'مطعم ليالي عراق layali al iraq مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049905,'riyadh','باكو','BACO','baco-bako','["مطاعم"]','["food"]','باكو مطعم مبتكر يقدم مزيجًا من المأكولات الآسيوية والأمريكية اللاتينية بأسلوب عصري وجذاب. يشتهر بسلطة الترافل والبطاطس المكسيكية وأطباق التاكو المتنوعة.','<div class="texte" > <p>باكو مطعم مبتكر يقدم مزيجًا من المأكولات الآسيوية والأمريكية اللاتينية بأسلوب عصري وجذاب. يشتهر بسلطة الترافل والبطاطس المكسيكية وأطباق التاكو المتنوعة، ويحظى بخدمة سريعة ومحترفة تجعله مناسبًا للتجمعات العائلية والأصدقاء. للتواصل أو الحجز: 0553034811، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049905-68551695.jpg?v=1791634630", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049905-68551698.jpg?v=1791634641"]','https://cmsphoto.ww-cdn.com/resizeapi/fc56dc8d2cc945ffc3b1f55322db86fafed17602/480/',24.7011651,46.7018534,'3824 العينة، السليمانية، الرياض 12223','0553034811','','','https://www.saudi-guide.com/riyadh/i/98049905/baco-bako',1,0,'باكو baco مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049903,'riyadh','توينا','Twina','twina-toyna','["مطاعم"]','["food"]','توينا يوفر لك تجربة فريدة في اختيار الأسماك وطهيها حسب ذوقك، حيث يمكن اختيار الأسماك والروبيان مباشرة بالكيلو لضمان أعلى درجات الطزاجة.','<div class="texte" > <p>توينا يوفر لك تجربة فريدة في اختيار الأسماك وطهيها حسب ذوقك، حيث يمكن اختيار الأسماك والروبيان مباشرة بالكيلو لضمان أعلى درجات الطزاجة. يشتهر بسمك الببغاء المشوي والروبيان المشوي على الفحم، ويُعد أول فروع سلسلة "توينا" الشهيرة خارج جدة. للتواصل أو الحجز: 920028284، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049903-68542018.jpg?v=1791538650", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049903-68542024.jpg?v=1791538670"]','https://cmsphoto.ww-cdn.com/resizeapi/f7318dede28ec5b21c02d37eede011e67ed3ee59/480/',24.7265706,46.6423605,'طريق الأمير تركي بن عبدالعزيز الأول، جامعة الملك سعود، الرياض 12371','920028284','','','https://www.saudi-guide.com/riyadh/i/98049903/twina-toyna',1,0,'توينا twina مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049902,'riyadh','موريني','Morini','morini-moryny','["مطاعم"]','["food"]','موريني لعشاق الطعم الإيطالي المميز يقدم مجموعة من الأطباق الإيطالية اللذيذة داخل فندق جريد بحطين، ويشتهر بعرض غداء يشمل مقبلات وطبقًا رئيسيًا وحلى بسعر مناسب.','<div class="texte" > <p>موريني لعشاق الطعم الإيطالي المميز يقدم مجموعة من الأطباق الإيطالية اللذيذة داخل فندق جريد بحطين، ويشتهر بعرض غداء يشمل مقبلات وطبقًا رئيسيًا وحلى بسعر مناسب. تتميز أجواؤه بالديكور الذي ينقلك إلى إيطاليا، ويحظى بإشادة كبيرة من الزوار خاصة عائلات الأطفال. للتواصل أو الحجز: 0112166176، ومواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049902-68551861.jpg?v=1791634987"]','https://cmsphoto.ww-cdn.com/resizeapi/4616dcc3fdb17b11664fa9914b3960f85dd00aca/480/',24.7503559,46.613269,'فندق جريد، طريق الأمير تركي بن عبدالعزيز، حطين، الرياض 11321','0112166176','','','https://www.saudi-guide.com/riyadh/i/98049902/morini-moryny',1,0,'موريني morini مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049896,'riyadh','يوميات باي دلال','Yawmiyat By Dalal','yawmiyat-by-dalal-yomyat-bay-dlal','["مطاعم"]','["food"]','يوميات باي دلال يشعرك بدفء المنزل ويقدم المأكولات اللبنانية الشهية في قائمة متغيرة باستمرار، بدءًا من المتبل بالدبس والفتوش وصولًا إلى المشاوي المتنوعة.','<div class="texte" > <p>يوميات باي دلال يشعرك بدفء المنزل ويقدم المأكولات اللبنانية الشهية في قائمة متغيرة باستمرار، بدءًا من المتبل بالدبس والفتوش وصولًا إلى المشاوي المتنوعة. تقدم زيتونًا ولبنة كطبق ترحيبي مجاني، وتحظى بتقدير خاص من نقاد الطعام لأصالة نكهاتها المنزلية. للتواصل أو الحجز: 0507111055، ومواعيد الدوام من 12:00 ظهرًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049896-68542129.jpg?v=1791538901", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049896-68542135.jpg?v=1791538918"]','https://cmsphoto.ww-cdn.com/resizeapi/d51abb6b2e8277bf272a571b088ccc24311f0ae8/480/',24.7223534,46.6732269,'شارع الأمير سلطان بن سلمان بن عبدالعزيز، الورود، الرياض 12251','0507111055','','','https://www.saudi-guide.com/riyadh/i/98049896/yawmiyat-by-dalal-yomyat-bay-dlal',1,0,'يوميات باي دلال yawmiyat by dalal مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049895,'riyadh','ميز','Meez','meez-myz','["مطاعم"]','["food"]','ميز يدمج الحداثة مع الأصالة من خلال تقديم أطباق محلية بلمسة عصرية، ويشتهر بالكبسة والمأكولات السعودية التقليدية المقدمة بطريقة عملية سريعة.','<div class="texte" > <p>ميز يدمج الحداثة مع الأصالة من خلال تقديم أطباق محلية بلمسة عصرية، ويشتهر بالكبسة والمأكولات السعودية التقليدية المقدمة بطريقة عملية سريعة. يتميز بأسعاره المناسبة وموقعه المتوسط في المدينة، ما يجعله خيارًا يوميًا مريحًا. للتواصل أو الحجز: 0550116755، ومواعيد الدوام من 8:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049895-68542186.jpg?v=1791539022"]','https://cmsphoto.ww-cdn.com/resizeapi/0201399f86760ca1532c1f97d94c9751bf84d998/480/',24.761991,46.7166065,'عثمان بن عفان، المغرزات، الرياض 12483','0550116755','','','https://www.saudi-guide.com/riyadh/i/98049895/meez-myz',1,0,'ميز meez مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049894,'riyadh','شبابيك','Shababik','shababik-shbabyk','["مطاعم"]','["food"]','شبابيك مطعم لبناني راقٍ يقدم مجموعة متنوعة من الأطباق الشهيرة كالكبة النية والمقبلات اللبنانية الأصيلة.','<div class="texte" > <p>شبابيك مطعم لبناني راقٍ يقدم مجموعة متنوعة من الأطباق الشهيرة كالكبة النية والمقبلات اللبنانية الأصيلة. يتميز بديكوره الأنيق والنابض بالحياة، ويُعد وجهة شهيرة لتناول الإفطار الجماعي والمناسبات العائلية. للتواصل أو الحجز: 920003945، ومواعيد الدوام من 9:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049894-68542239.jpg?v=1791539134", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049894-68542245.jpg?v=1791539157"]','https://cmsphoto.ww-cdn.com/resizeapi/e0ab3b71cdba0d1360a9e98a570eeede6bcf61e1/480/',24.7070797,46.7069246,'7178 شارع الأمير عبدالعزيز بن مساعد بن جلوي، السليمانية، الرياض 12243','920003945','','','https://www.saudi-guide.com/riyadh/i/98049894/shababik-shbabyk',1,0,'شبابيك shababik مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049893,'riyadh','بلكونة 99','Balcona','balcona-blkon-99','["مطاعم"]','["food"]','بلكونة 99 متخصص في المأكولات المصرية التقليدية في أجواء نابضة بالحياة، ويشتهر بأطباق الكنافة اللذيذة والمشاوي المصرية الأصيلة.','<div class="texte" > <p>بلكونة 99 متخصص في المأكولات المصرية التقليدية في أجواء نابضة بالحياة، ويشتهر بأطباق الكنافة اللذيذة والمشاوي المصرية الأصيلة. يحظى بإشادة كبيرة من الزوار لجودة طبخ الشيف وأجواء الضيافة المصرية الدافئة. للتواصل أو الحجز: 0547722266، ومواعيد الدوام من 9:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049893-68542278.jpg?v=1791539242", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049893-68542283.jpg?v=1791539261"]','https://cmsphoto.ww-cdn.com/resizeapi/23f0dfb13ac446a22db2a15b4d0115088f411ded/480/',24.7010405,46.6770389,'4354 طريق الملك فهد، العليا، الرياض 12331','0547722266','','','https://www.saudi-guide.com/riyadh/i/98049893/balcona-blkon-99',1,0,'بلكونه 99 balcona مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049892,'riyadh','سويس بتر','Swiss Butter','swiss-butter-soys-btr','["مطاعم"]','["food"]','سويس بتر مطعم متخصص في اللحوم الحمراء والبيضاء، يشتهر عالميًا بصلصته السرية المميزة (Swiss Butter Sauce) التي تُضفى على الستيك بعد الشوي مباشرة.','<div class="texte" > <p>سويس بتر مطعم متخصص في اللحوم الحمراء والبيضاء، يشتهر عالميًا بصلصته السرية المميزة (Swiss Butter Sauce) التي تُضفى على الستيك بعد الشوي مباشرة. يتميز بقائمة بسيطة وواضحة تركز على جودة اللحم، وأجواء مريحة تجمع بين الطابع الداخلي والخارجي المورق. للتواصل أو الحجز: 0533390630، ومواعيد الدوام من 12:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049892-68542334.jpg?v=1791539361", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049892-68542340.jpg?v=1791539382"]','https://cmsphoto.ww-cdn.com/resizeapi/3674b4e8fb4d3cc43a4de01142d17618b9acaf74/480/',24.7013125,46.6763125,'سنتشري كورنر، العليا، الرياض 12331','0533390630','','','https://www.saudi-guide.com/riyadh/i/98049892/swiss-butter-soys-btr',1,0,'سويس بتر swiss butter مطاعم',strftime('%s','now'));
