INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049889,'riyadh','انتروكوت','Entrecôte','entrecote-antrokot','["مطاعم"]','["food"]','انتروكوت (Entrecôte) مطعم سويسري يقدم قطع شرائح اللحم الفاخرة بإطلالة رائعة من داخل برج الفيصلية الشهير.','<div class="texte" > <p>انتروكوت (Entrecôte) مطعم سويسري يقدم قطع شرائح اللحم الفاخرة بإطلالة رائعة من داخل برج الفيصلية الشهير. يشتهر بستيك الواغيو المشوي بإتقان وحلوى الكريم بروليه، ويحظى بشعبية كبيرة كأحد أفضل مطاعم اللحوم في العليا. للتواصل أو الحجز: 920018998، ومواعيد الدوام من 1:00 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049889-68542448.jpg?v=1791539626", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049889-68542460.jpg?v=1791539647"]','https://cmsphoto.ww-cdn.com/resizeapi/c91b3b77dd93e0a97496648e6c2e1a95e0f7ff2d/480/',24.6900396,46.6848371,'برج الفيصلية، طريق الملك فهد الفرعي، العليا، الرياض 12212','920018998','','','https://www.saudi-guide.com/riyadh/i/98049889/entrecote-antrokot',1,0,'انتروكوت entrecôte مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049859,'riyadh','روباتا','Robata','robata-robata','["مطاعم"]','["food"]','روباتا لعشاق الأكل الياباني يقدم العديد من الأصناف اليابانية المتنوعة على يد أفضل الطهاة، ويشتهر بالأرز الياباني المقرمش والغيوزا والواغيو المشوي.','<div class="texte" > <p>روباتا لعشاق الأكل الياباني يقدم العديد من الأصناف اليابانية المتنوعة على يد أفضل الطهاة، ويشتهر بالأرز الياباني المقرمش والغيوزا والواغيو المشوي. يتميز بأجواء أنيقة ومريحة مع إضاءة طبيعية جميلة، ويحظى بتقييمات عالية لجودة الخدمة والتناغم الموسيقي. للتواصل أو الحجز: 920005613، ومواعيد الدوام من 1:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049859-68542513.jpg?v=1791539743", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049859-68542518.jpg?v=1791539760"]','https://cmsphoto.ww-cdn.com/resizeapi/7cc3669df923df518b318051e8caf2ec5bcd46c1/480/',24.7517757,46.6237525,'ذا كانوبي، حطين، الرياض 13512','920005613','','','https://www.saudi-guide.com/riyadh/i/98049859/robata-robata',1,0,'روباتا robata مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049858,'riyadh','نوزومي','Nozomi','nozomi-nozomy','["مطاعم"]','["food"]','نوزومي مطعم ياباني في الرياض يقدم السوشي والساشيمي والمأكولات البحرية الطازجة بجودة عالية وتقديم أنيق، ويناسب المناسبات الخاصة.','<div class="texte" > <p>نوزومي لعشاق المأكولات اليابانية يقدم مجموعة واسعة من السوشي والساشيمي بجودة عالية وتقديم أنيق، ويشتهر بأطباق المأكولات البحرية الطازجة وشوربة جوز الهند بالتوابل. يحظى بشعبية كبيرة لتنظيم الفطور الياباني في رمضان والمناسبات الخاصة كأعياد الميلاد والذكرى السنوية. للتواصل أو الحجز: 920011923، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049858-68542561.jpg?v=1791539865", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049858-68542565.jpg?v=1791539882"]','https://cmsphoto.ww-cdn.com/resizeapi/7a8a7c632383df9f4f0c0b0b0f769f8476db68f1/480/',24.7010494,46.6771162,'4255، 7448 طريق الملك فهد، العليا، الرياض 12331','920011923','','','https://www.saudi-guide.com/riyadh/i/98049858/nozomi-nozomy',1,0,'نوزومي nozomi مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049857,'riyadh','إل بي إم','La Petite Maison','la-petite-maison-al-by-am','["مطاعم"]','["food"]','إل بي إم (La Petite Maison) مطعم فرنسي فاخر يقدم مجموعة متنوعة من الأطباق الشهية وسط أجواء رائعة تجمع بين الأناقة الكلاسيكية والدفء.','<div class="texte" > <p>إل بي إم (La Petite Maison) مطعم فرنسي فاخر يقدم مجموعة متنوعة من الأطباق الشهية وسط أجواء رائعة تجمع بين الأناقة الكلاسيكية والدفء. يشتهر بالحلزون (escargots) وستيك الواغيو وطبق البوراتا، ويُعد من أرقى تجارب المطبخ الفرنسي في العليا. للتواصل أو الحجز: 920011794، ومواعيد الدوام من 12:30 ظهرًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049857-68542600.jpg?v=1791539965", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049857-68542607.jpg?v=1791539983"]','https://cmsphoto.ww-cdn.com/resizeapi/702ad919e26e18840181e1bfb06b2a18a3176e54/480/',24.6907541,46.6841285,'شارع المعتصم، العليا، الرياض 12212','920011794','','','https://www.saudi-guide.com/riyadh/i/98049857/la-petite-maison-al-by-am',1,0,'بي ام la petite maison مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049856,'riyadh','روكا','ROKA','roka-roka','["مطاعم"]','["food"]','روكا يقدم لفائف السوشي والمشويات اليابانية على الفحم (روباتا) بقائمة راقية وبأسلوب عصري فاخر، ويُعد أحد أشهر فروع سلسلة روكا العالمية.','<div class="texte" > <p>روكا يقدم لفائف السوشي والمشويات اليابانية على الفحم (روباتا) بقائمة راقية وبأسلوب عصري فاخر، ويُعد أحد أشهر فروع سلسلة روكا العالمية. يشتهر ببرنش نهاية الأسبوع المتكامل وأطباق السلطعون والتارتار، وسط أجواء أنيقة تناسب المناسبات الخاصة. للتواصل أو الحجز: 920012327، ومواعيد الدوام من 1:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049856-68542645.jpg?v=1791540077", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049856-68542653.jpg?v=1791540090"]','https://cmsphoto.ww-cdn.com/resizeapi/0f0d10fcf1a629eefa418adb276ff05b51a85c19/480/',24.7056353,46.7063975,'5140 طريق الأمير محمد بن عبدالعزيز، السليمانية، الرياض 12243','920012327','','','https://www.saudi-guide.com/riyadh/i/98049856/roka-roka',1,0,'روكا roka مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049854,'riyadh','رويا','Rüya','ruya-roya','["مطاعم"]','["food"]','رويا مطعم تركي عصري يتميز بقائمة أطباق حديثة ومميزة تمزج بين النكهات الأناضولية التقليدية والتقديم العصري، ويشتهر بالمقبلات والمشويات وخبز البوريك الطازج.','<div class="texte" > <p>رويا مطعم تركي عصري يتميز بقائمة أطباق حديثة ومميزة تمزج بين النكهات الأناضولية التقليدية والتقديم العصري، ويشتهر بالمقبلات والمشويات وخبز البوريك الطازج. تحيط بالمكان أجواء دافئة مستوحاة من إسطنبول، مع خيار الشيشة للجلسات الخارجية. للتواصل أو الحجز: 920010692، ومواعيد الدوام من 12:30 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049854-68551777.jpg?v=1791634785", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049854-68551778.jpg?v=1791634797"]','https://cmsphoto.ww-cdn.com/resizeapi/2c65571f03e13e310edda9f361171afb8ce9b185/480/',24.7059626,46.7065493,'1224 طريق الأمير محمد بن عبدالعزيز، السليمانية، الرياض 12243','920010692','','','https://www.saudi-guide.com/riyadh/i/98049854/ruya-roya',1,0,'رويا rüya مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049852,'riyadh','وايت روباتا','White Robata','white-robata-oayt-robata','["مطاعم"]','["food"]','وايت روباتا من أفضل المطاعم في تقديم الأصناف البحرية الشهية بلمسة يابانية آسيوية مبتكرة، ويشتهر بألذ غيوزا في الرياض إلى جانب أطباق السوشي واللوليزيانا كاراجي.','<div class="texte" > <p>White Robata من أفضل المطاعم في تقديم الأصناف البحرية الشهية بلمسة يابانية آسيوية مبتكرة، ويشتهر بألذ غيوزا في الرياض إلى جانب أطباق السوشي واللوليزيانا كاراجي. تتميز أجواؤه بالدفء والألوان الزاهية، ويُعد وجهة مفضلة لعشاق المطبخ الآسيوي الفريد. للتواصل أو الحجز: 8001220077، ومواعيد الدوام من 6:00 مساءً حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049852-68542706.jpg?v=1791540227"]','https://cmsphoto.ww-cdn.com/resizeapi/d979a2b3af8d71d843a6f1c1852badb8d773b690/480/',24.6934527,46.6323358,'2252 طريق العروبة الفرعي، أم الحمام الغربي، الرياض 12329','8001220077','','','https://www.saudi-guide.com/riyadh/i/98049852/white-robata-oayt-robata',1,0,'وايت روباتا white robata مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049850,'riyadh','سنيور ساسي','Signor Sassi','signor-sassi-snyor-sasy','["مطاعم"]','["food"]','سنيور ساسي (Signor Sassi) يقدم مأكولات إيطالية لذيذة وسط ديكورات رائعة وقائمة متنوعة من المأكولات الكلاسيكية.','<div class="texte" > <p>سنيور ساسي (Signor Sassi) يقدم مأكولات إيطالية لذيذة وسط ديكورات رائعة وقائمة متنوعة من المأكولات الكلاسيكية. يشتهر ببيتزا البوراتا والباستا الكريمية الحارة، ويحظى بسمعة راسخة كأحد أفضل المطاعم الإيطالية الفاخرة في الرياض. للتواصل أو الحجز: 920011877، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049850-68542742.jpg?v=1791540327", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049850-68542744.jpg?v=1791540342"]','https://cmsphoto.ww-cdn.com/resizeapi/eca1f4b969c75be01e1729cc4d26198f266db2f1/480/',24.6996837,46.7045731,'2605 شارع الأمير عبدالعزيز بن مساعد بن جلوي، السليمانية، الرياض 12234','920011877','','','https://www.saudi-guide.com/riyadh/i/98049850/signor-sassi-snyor-sasy',1,0,'سنيور ساسي signor sassi مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049849,'riyadh','إل باريتو','Il Baretto','il-baretto-al-baryto','["مطاعم"]','["food"]','إل باريتو (Il Baretto) يقدم قائمة رائعة من الطعام الإيطالي التقليدي في إطلالة جميلة وموقع متميز داخل مركز الملك عبدالله المالي (كافد).','<div class="texte" > <p>إل باريتو (Il Baretto) يقدم قائمة رائعة من الطعام الإيطالي التقليدي في إطلالة جميلة وموقع متميز داخل مركز الملك عبدالله المالي (كافد). يشتهر بالبيتزا وسلطة البنجر والباستا باللحم، مع موسيقى حية تضفي أجواءً دافئة على السهرة. للتواصل أو الحجز: 920012508، ومواعيد الدوام من 12:30 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049849-68542756.jpg?v=1791540420", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049849-68542762.jpg?v=1791540433"]','https://cmsphoto.ww-cdn.com/resizeapi/1982f4b8d79559f5434a1814aaa21cf5ec1f0eaf/480/',24.7626858,46.6385511,'كافد 5.08، العقيق، الرياض 13519','920012508','','','https://www.saudi-guide.com/riyadh/i/98049849/il-baretto-al-baryto',1,0,'باريتو il baretto مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049848,'riyadh','شيبرياني','Cipriani','cipriani-shybryany','["مطاعم"]','["food"]','شيبرياني (Cipriani) مطعم إيطالي عريق يحمل اسم عائلة تشيبرياني الشهيرة عالميًا، يقدم قائمة أصناف إيطالية كلاسيكية بأجواء هادئة وأنيقة.','<div class="texte" > <p>شيبرياني (Cipriani) مطعم إيطالي عريق يحمل اسم عائلة تشيبرياني الشهيرة عالميًا، يقدم قائمة أصناف إيطالية كلاسيكية بأجواء هادئة وأنيقة. يشتهر بالباستا الطازجة والآيس كريم الإيطالي، ويُعد وجهة موثوقة لمحبي المطبخ الإيطالي الأصيل في الرياض. للتواصل أو الحجز: 0112776700، ومواعيد الدوام من 1:00 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049848-68542778.jpg?v=1791540521", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049848-68542793.jpg?v=1791540555"]','https://cmsphoto.ww-cdn.com/resizeapi/bacbc0376735eee77d0fb00eec120beaf384fe60/480/',24.756809,46.607747,'6927 طريق الأمير تركي بن عبدالعزيز الأول، حطين، الرياض 13512','0112776700','','','https://www.saudi-guide.com/riyadh/i/98049848/cipriani-shybryany',1,0,'شيبرياني cipriani مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049725,'riyadh','لو ماشو','Le Maschou','le-maschou-lo-masho','["مطاعم"]','["food"]','لو ماشو مطعم فاخر يقع في الحي الدبلوماسي يقدم الأطباق الفرنسية الأصيلة بأجواء راقية وهادئة تناسب المناسبات الرومانسية والاحتفالات الخاصة.','<div class="texte" > <p>لو ماشو مطعم فاخر يقع في الحي الدبلوماسي يقدم الأطباق الفرنسية الأصيلة بأجواء راقية وهادئة تناسب المناسبات الرومانسية والاحتفالات الخاصة. يشتهر بسلطة التين والكالاماري ولحم الواغيو المشوي، إلى جانب طبق التيراميسو الذي يحظى بإشادة دائمة من الزوار. للتواصل أو الحجز: 920013005، ومواعيد الدوام من 2:00 عصرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049725-68542846.jpg?v=1791540679", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049725-68542849.jpg?v=1791540698"]','https://cmsphoto.ww-cdn.com/resizeapi/7ac365d4d5e8b401799c655fb5409a30b2182060/480/',24.6925155,46.6287842,'حي السفارات، شارع تيماء، الحي الدبلوماسي، الرياض 12513','920013005','','','https://www.saudi-guide.com/riyadh/i/98049725/le-maschou-lo-masho',1,0,'لو ماشو le maschou مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049724,'riyadh','ميازو','MYAZU','myazu-myazo','["مطاعم"]','["food"]','ميازو يجمع بين مطعم ياباني وصالة لاونج أنيقة، يقدم السوشي والواغيو المشوي وأطباقًا فاخرة، ويناسب المناسبات الخاصة والاحتفالات.','<div class="texte" > <p>ميازو يقدم مأكولات يابانية كلاسيكية مثل السوشي والواغيو وغيرها من الأطباق الفاخرة، ويجمع بين مطعم وصالة سهرات (لاونج) بأجواء أنيقة تناسب المناسبات الخاصة كأعياد الميلاد والتخرج. يشتهر برز الفطر ووجبات الواغيو المشوي، ويحظى بتقييمات عالية لجودة الخدمة والاحتفاء بالمناسبات. للتواصل أو الحجز: 920009686، ومواعيد الدوام من 1:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049724-68542886.jpg?v=1791540775", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049724-68542890.jpg?v=1791540786"]','https://cmsphoto.ww-cdn.com/resizeapi/edda6b82873ff36037dfaab2fea4f07aa3e4e23f/480/',24.6999984,46.7048876,'مساعد بن جلوي، السليمانية، الرياض 12244','920009686','','','https://www.saudi-guide.com/riyadh/i/98049724/myazu-myazo',1,0,'ميازو myazu مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049722,'riyadh','كورو','KUURU','kuuru-koro','["مطاعم"]','["food"]','كورو يقدم تجربة يابانية عصرية فاخرة من قلب العاصمة، بموقع مقابل مباشرة لمركز الملك عبدالله المالي (كافد).','<div class="texte" > <p>KUURU يقدم تجربة يابانية عصرية فاخرة من قلب العاصمة، بموقع مقابل مباشرة لمركز الملك عبدالله المالي (كافد). يشتهر بطبق "نيكو توموروكوشي" وتشكيلة السوشي الطازجة، إلى جانب حلوياته المميزة كالتشيز كيك. يتميز بديكور أنيق وخدمة راقية تجعله وجهة مفضلة للمناسبات الخاصة. للتواصل أو الحجز: 920035739، ومواعيد الدوام من 12:00 ظهرًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049722-68542913.jpg?v=1791540864", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049722-68542916.jpg?v=1791540876"]','https://cmsphoto.ww-cdn.com/resizeapi/2e16b6f1a2412e9539e71a00531a5e67327fdcce/480/',24.760361,46.6391496,'305، العقيق، الرياض 13519','920035739','','','https://www.saudi-guide.com/riyadh/i/98049722/kuuru-koro',1,0,'كورو kuuru مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049718,'riyadh','مامو ميكيلانجيلو','MAMO Michelangelo','mamo-michelangelo-mamo-mykylangylo','["مطاعم"]','["food"]','مامو ميكيلانجيلو تجربة فرنسية-إيطالية منعشة تحظى بشعبية عالمية على يد الشيف مامو، بديكور ملون مستوحى من الفخار الإيطالي التقليدي يمنح المكان طابعًا مبهجًا.','<div class="texte" > <p>مامو ميكيلانجيلو تجربة فرنسية-إيطالية منعشة تحظى بشعبية عالمية على يد الشيف مامو، بديكور ملون مستوحى من الفخار الإيطالي التقليدي يمنح المكان طابعًا مبهجًا. يشتهر بطبق البوراتا الطازج وكريم بروليه الفاخر، ويُعد من أكثر الأماكن جذبًا للتصوير في الرياض. للتواصل أو الحجز: 920000874، ومواعيد الدوام من 12:30 ظهرًا حتى 12:30 فجرًا (بفترتين: غداء ومساء).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049718-68542944.jpg?v=1791540946", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049718-68542952.jpg?v=1791540955"]','https://cmsphoto.ww-cdn.com/resizeapi/b6c92595e2981d4ada3343ac037226d9c085af03/480/',24.6897082,46.6849989,'طريق الملك فهد، العليا، الرياض 12212','920000874','','','https://www.saudi-guide.com/riyadh/i/98049718/mamo-michelangelo-mamo-mykylangylo',1,0,'مامو ميكيلانجيلو mamo michelangelo مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049703,'riyadh','كويا','COYA','coya-koya','["مطاعم"]','["food"]','كويا (COYA) يتميز بأطباق عالمية بالإضافة إلى أطباق فريدة مستوحاة من الطهي البيروفي والأمريكي اللاتيني.','<div class="texte" > <p>كويا (COYA) يتميز بأطباق عالمية بالإضافة إلى أطباق فريدة مستوحاة من الطهي البيروفي والأمريكي اللاتيني، بديكور مستلهم من حضارة الإنكا القديمة يمنح المكان طابعًا مميزًا. يشتهر بطبق لحم الخد المطهو ببطء وقائمة كوكتيلات مبتكرة، ويُعد وجهة رائجة للسهرات الفاخرة. للتواصل أو الحجز: 920010352، ومواعيد الدوام من 1:00 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049703-68542980.jpg?v=1791541027", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049703-68542987.jpg?v=1791541044"]','https://cmsphoto.ww-cdn.com/resizeapi/00a9e93a465b1efc65e6b3980c63b953bf3308a5/480/',24.7045336,46.7058862,'8710 شارع الأمير عبدالعزيز بن مساعد بن جلوي، السليمانية، الرياض 12223','920010352','','','https://www.saudi-guide.com/riyadh/i/98049703/coya-koya',1,0,'كويا coya مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049702,'riyadh','مستر تشاو','MR CHOW','mr-chow-mstr-tshao','["مطاعم"]','["food"]','مستر تشاو لعشاق الطعم الصيني الأصلي يتميز بتقديم أطباق صينية متنوعة وسط أجواء فاخرة، ويشتهر بطبق البط البكيني الأصيل والدمبلينغ المصنوع يدويًا.','<div class="texte" > <p>MR CHOW لعشاق الطعم الصيني الأصلي يتميز بتقديم أطباق صينية متنوعة وسط أجواء فاخرة، ويشتهر بطبق البط البكيني الأصيل والدمبلينغ المصنوع يدويًا. يوفر خدمة صالة (فاليه) مجانية وأجواء عصرية تمزج بين الطابع الشرقي والحديث، ما يجعله وجهة مفضلة للمناسبات وعشاء الأعمال. للتواصل أو الحجز: 920012658، ومواعيد الدوام من 12:00 ظهرًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049702-68543006.jpg?v=1791541116", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049702-68543008.jpg?v=1791541126"]','https://cmsphoto.ww-cdn.com/resizeapi/07b28bc7edb82b4e9c23335e12afac58c048f73f/480/',24.7656482,46.6400481,'مترو بوليفارد، العقيق، الرياض 13519','920012658','','','https://www.saudi-guide.com/riyadh/i/98049702/mr-chow-mstr-tshao',1,0,'مستر تشاو mr chow مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049698,'riyadh','تاو','TAO','tao-tao','["مطاعم"]','["food"]','تاو يقدم مجموعة متنوعة من الأطباق الشهية بأسلوب عالمي عصري، ويشتهر بحلوياته المميزة كالساديز السعودية وكعكة الشوكولاتة الفاخرة.','<div class="texte" > <p>تاو يقدم مجموعة متنوعة من الأطباق الشهية بأسلوب عالمي عصري، ويشتهر بحلوياته المميزة كالساديز السعودية وكعكة الشوكولاتة الفاخرة. يتميز بجلساته الداخلية والخارجية الأنيقة وأجوائه الفنية، ويُعد وجهة رائجة للمناسبات الخاصة والاحتفالات. للتواصل أو الحجز: 0114080808، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049698-68543048.jpg?v=1791541328", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049698-68543057.jpg?v=1791541344"]','https://cmsphoto.ww-cdn.com/resizeapi/ba7243e5e6bc081a76df43fe992ef0c316502a62/480/',24.751156,46.6130393,'حي حطين، طريق الأمير تركي بن عبدالعزيز الأول، الرياض 13513','0114080808','','','https://www.saudi-guide.com/riyadh/i/98049698/tao-tao',1,0,'تاو tao مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049684,'riyadh','وفرة الصفوة','Wafra Al Safwa','wafra-al-safwa-ofr-alsfo','["مطاعم"]','["food"]','وفرة الصفوة مطعم شعبي بأجواء منزلية دافئة يقدم نكهات المطبخ السعودي بلمسات لبنانية ومصرية وتركية، مع مكونات طازجة يوميًا.','<div class="texte" > <p>وفرة الصفوة من المطاعم الشعبية المميزة التي تقدم مأكولات شعبية تتميز بالمذاق الفريد، بأجواء منزلية دافئة تعكس نكهات المطبخ السعودي بلمسات لبنانية ومصرية وتركية في المقبلات والسلطات. يحرص المطعم على استخدام مكونات طازجة في كل أطباقه اليومية. للتواصل أو الحجز: 0555264432، ومواعيد الدوام من 8:30 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049684-68543074.jpg?v=1791541430", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049684-68543077.jpg?v=1791541450"]','https://cmsphoto.ww-cdn.com/resizeapi/d4364c3881bbe4759d4493fedc6b80e644223239/480/',24.786607,46.6872455,'شارع البحر الأحمر، الوادي، الرياض 12232','0555264432','','','https://www.saudi-guide.com/riyadh/i/98049684/wafra-al-safwa-ofr-alsfo',1,0,'وفره صفوه wafra al safwa مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049682,'riyadh','رزرز بخاري','RzRz Bukhari','rzrz-bukhari-rzrz-bkhary','["مطاعم"]','["food"]','رزرز بخاري متخصص في تقديم البخاري على الطريقة الأصلية، ويشتهر بالبولاو الأفغاني الذي يُعد من أبرز أطباقه إلى جانب البخاري بالدجاج واللحم.','<div class="texte" > <p>رزرز بخاري متخصص في تقديم البخاري على الطريقة الأصلية، ويشتهر بالبولاو الأفغاني الذي يُعد من أبرز أطباقه إلى جانب البخاري بالدجاج واللحم. يتميز بمساحته الواسعة القادرة على استيعاب أعداد كبيرة من الزوار، ما يجعله مناسبًا للتجمعات العائلية الكبيرة. للتواصل أو الحجز: 0535178224، ومواعيد الدوام من 11:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049682-68543103.jpg?v=1791541544", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049682-68543108.jpg?v=1791541556"]','https://cmsphoto.ww-cdn.com/resizeapi/624a88ebe675922e63b61d430460c27991fe767e/480/',24.5913974,46.8028086,'طريق الخرج، العزيزية، الرياض 14513','0535178224','','','https://www.saudi-guide.com/riyadh/i/98049682/rzrz-bukhari-rzrz-bkhary',1,0,'رزرز بخاري rzrz bukhari مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049680,'riyadh','مشخول','Mashkhool','mashkhool-mshkhol','["مطاعم"]','["food"]','مشخول يقدم قائمة من أشهى الأكلات الشعبية الأصيلة من القائمة المتنوعة، ويشتهر بشكل خاص برز الحساوي المطهو بطريقة تقليدية غنية بالنكهات.','<div class="texte" > <p>مشخول يقدم قائمة من أشهى الأكلات الشعبية الأصيلة من القائمة المتنوعة، ويشتهر بشكل خاص برز الحساوي المطهو بطريقة تقليدية غنية بالنكهات. تتميز أجواؤه بالبساطة والتركيز على جودة الطعم، ويحظى بتقدير الزوار لنظافة المكان وأسعاره المناسبة. للتواصل أو الحجز: 0112253131، ومواعيد الدوام من 10:30 صباحًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049680-68543151.jpg?v=1791541759", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049680-68543152.jpg?v=1791541769"]','https://cmsphoto.ww-cdn.com/resizeapi/e84dc7f44445d38982442e67bdb0b63eca666d71/480/',24.7554757,46.6823221,'8039 طريق الإمام سعود بن عبدالعزيز الفرعي، المرسلات، الرياض 12463','0112253131','','','https://www.saudi-guide.com/riyadh/i/98049680/mashkhool-mshkhol',1,0,'مشخول mashkhool مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049658,'riyadh','سواليف الديرة','Sawalef Al Direh','sawalef-al-direh-soalyf-aldyr','["مطاعم"]','["food"]','سواليف الديرة يقدم أشهى المأكولات الشعبية التقليدية بطابع عريق من الأطباق المحلية المتوارثة، وسط أجواء تحاكي الضيافة النجدية الأصيلة.','<div class="texte" > <p>سواليف الديرة يقدم أشهى المأكولات الشعبية التقليدية بطابع عريق من الأطباق المحلية المتوارثة، وسط أجواء تحاكي الضيافة النجدية الأصيلة. يُعد خيارًا مناسبًا لمن يبحث عن تجربة أكل شعبي أصيل بعيدًا عن الأجواء العصرية. للتواصل أو الحجز: 0505336690، ومواعيد الدوام من 12:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049658-68543165.jpg?v=1791541841", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049658-68543168.jpg?v=1791541855"]','https://cmsphoto.ww-cdn.com/resizeapi/c12744360c94e5b9ad7dfff224d79b7fc9a7c263/480/',24.8170621,46.5926634,'طريق الملك سلمان بن عبدالعزيز الفرعي، الملقا، الرياض 13525','0505336690','','','https://www.saudi-guide.com/riyadh/i/98049658/sawalef-al-direh-soalyf-aldyr',1,0,'سواليف ديره sawalef al direh مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049657,'riyadh','عسيب','Aseeb','aseeb-aasyb','["مطاعم"]','["food"]','مطعم عسيب يقدم الأكلات التراثية السعودية بطريقة عصرية، بديكور يعكس الهوية السعودية الأصيلة وأجواء عائلية دافئة وخدمة مميزة.','<div class="texte" > <p>مطعم عسيب يقدم الأكلات التراثية بطريقة عصرية لتعيش أجواء بين الحاضر والماضي، بديكور داخلي يعكس الهوية السعودية الأصيلة ويمنح الزوار تجربة بصرية مميزة إلى جانب الطعام. يحظى بتقييمات عالية من الزوار لجودة الخدمة والأجواء العائلية الدافئة. للتواصل أو الحجز: 920028226، ومواعيد الدوام من 6:30 صباحًا حتى 12:15 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049657-68543594.jpg?v=1791545092", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049657-68543597.jpg?v=1791545100"]','https://cmsphoto.ww-cdn.com/resizeapi/69d0d3a250a66b8e62084e19a2d0a78f265f0d6a/480/',24.8125975,46.6270043,'طريق أنس بن مالك، الياسمين، الرياض 13325','920028226','','','https://www.saudi-guide.com/riyadh/i/98049657/aseeb-aasyb',1,0,'عسيب aseeb مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049655,'riyadh','مندي ستيشن','Mandy Station','mandy-station-mndy-styshn','["مطاعم"]','["food"]','مندي ستيشن متخصص بتقديم المندي الأصلي بطريقة حديثة، مع عدة خيارات من اللحم والدجاج تُطهى على الطريقة اليمنية التقليدية.','<div class="texte" > <p>مندي ستيشن متخصص بتقديم المندي الأصلي بطريقة حديثة، مع عدة خيارات من اللحم والدجاج تُطهى على الطريقة اليمنية التقليدية. يتميز بأجواء عملية سريعة تناسب وجبات الغداء والعشاء الجماعية، وأسعار معقولة مقارنة بجودة الكمية المقدمة. للتواصل أو الحجز: 0500100932، ومواعيد الدوام من 12:30 ظهرًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049655-68543609.jpg?v=1791545192", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049655-68543615.jpg?v=1791545210"]','https://cmsphoto.ww-cdn.com/resizeapi/370e927a668a86d35b3b3dd1ba2bbbdb92bc2c86/480/',24.7898423,46.6220073,'العقيق، الرياض 13515','0500100932','','','https://www.saudi-guide.com/riyadh/i/98049655/mandy-station-mndy-styshn',1,0,'مندي ستيشن mandy station مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049654,'riyadh','سهيل','Suhail','suhail-shyl','["مطاعم"]','["food"]','مطعم سهيل يقدم أطباقًا من المأكولات السعودية التقليدية بلمسة عصرية، ويحظى بسمعة طيبة بفضل سرعة الخدمة وجودة الأطباق كالكبسة والشوربة والمقبلات المحلية.','<div class="texte" > <p>مطعم سهيل يقدم أطباقًا من المأكولات السعودية التقليدية بلمسة عصرية، ويحظى بسمعة طيبة بفضل سرعة الخدمة وجودة الأطباق كالكبسة والشوربة والمقبلات المحلية. تشتهر قائمته بسلطة الحبحب المنعشة إلى جانب أطباق الشرقية الأصيلة. للتواصل أو الحجز: 920002690، ومواعيد الدوام من 12:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049654-68551802.jpg?v=1791634881", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049654-68551809.jpg?v=1791634892"]','https://cmsphoto.ww-cdn.com/resizeapi/c130d1f0160d34c56c16f8e52083942f3351d8e0/480/',24.750147,46.6232781,'طريق الدائري الشمالي الفرعي، النخيل، الرياض 11564','920002690','','','https://www.saudi-guide.com/riyadh/i/98049654/suhail-shyl',1,0,'سهيل suhail مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049253,'riyadh','جيناكم مطبخ مديني','Jinakum Madani Cuisine','jinakum-madani-cuisine-gynakm-mtbkh-mdyny','["مطاعم"]','["food"]','جيناكم مطبخ مديني يقدم مختلف أنواع الأرز والذبائح المطبوخة بنكهات خاصة على الطراز المدني الأصيل، ويشتهر بالكبسة والمندي بمذاق يعكس تراث المدينة المنورة الغذائي.','<div class="texte" > <p>جيناكم مطبخ مديني يقدم مختلف أنواع الأرز والذبائح المطبوخة بنكهات خاصة على الطراز المدني الأصيل، ويشتهر بالكبسة والمندي بمذاق يعكس تراث المدينة المنورة الغذائي. يعمل المطعم بنظام الطلبات الخارجية فقط (بدون صالة جلوس)، ما يجعله مناسبًا لطلبات المناسبات والتجمعات العائلية. للتواصل أو الحجز: 0533010022، ومواعيد الدوام من 12:00 ظهرًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049253-68543629.jpg?v=1791545351", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049253-68543632.jpg?v=1791545363"]','https://cmsphoto.ww-cdn.com/resizeapi/9630f72a92b9d3d70b610efa53c7c60594703a2e/480/',24.8498305,46.6817567,'طريق الأمير فيصل بن بندر بن عبدالعزيز، النرجس، الرياض 13328','0533010022','','','https://www.saudi-guide.com/riyadh/i/98049253/jinakum-madani-cuisine-gynakm-mtbkh-mdyny',1,0,'جيناكم مطبخ مديني jinakum madani cuisine مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049251,'riyadh','المكي','Al Makki','al-makki-almky','["مطاعم"]','["food"]','المكي صاحب الريادة في تقديم المثلوثة وغيرها من الأكلات السعودية العريقة، ويُعد من المطاعم الشعبية التي حافظت على طابعها الأصيل لسنوات طويلة.','<div class="texte" > <p>المكي صاحب الريادة في تقديم المثلوثة وغيرها من الأكلات السعودية العريقة، ويُعد من المطاعم الشعبية التي حافظت على طابعها الأصيل لسنوات طويلة. يشتهر بأطباقه التقليدية المحضّرة على أصولها، ويحظى بقاعدة زبائن دائمة تقدّر جودة الطعم. للتواصل أو الحجز: 0114872277، ومواعيد الدوام من 10:30 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049251-68543647.jpg?v=1791545429", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049251-68543654.jpg?v=1791545449"]','https://cmsphoto.ww-cdn.com/resizeapi/20c3e6c63b04e3c6066325847bb835966fe2d446/480/',24.7872584,46.634606,'حي الصحافة، طريق الملك فهد، القرب من برج هيتال، الرياض 13321','0114872277','','','https://www.saudi-guide.com/riyadh/i/98049251/al-makki-almky',1,0,'مكي al makki مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049245,'riyadh','شواية الخليج','Shawaya Alkhaleej','shawaya-alkhaleej-shoay-alkhlyg','["مطاعم"]','["food"]','شواية الخليج الخيار الأمثل لتجربة شهية ولذيذة من الدجاج المشوي، حيث يشتهر بطريقة تحضيره المميزة وتتبيلته الخاصة التي تمنح اللحم نكهة غنية.','<div class="texte" > <p>شواية الخليج الخيار الأمثل لتجربة شهية ولذيذة من الدجاج المشوي، حيث يشتهر بطريقة تحضيره المميزة وتتبيلته الخاصة التي تمنح اللحم نكهة غنية. يقدم أطباق الدجاج مع الأرز والصلصات المرافقة بأسعار مناسبة وخدمة سريعة تلائم الوجبات العائلية. للتواصل أو الحجز: 920034443، ومواعيد الدوام من 10:30 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049245-68543662.jpg?v=1791545522", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049245-68543664.jpg?v=1791545538"]','https://cmsphoto.ww-cdn.com/resizeapi/752cc84378d6397a01d2a59f007bb712650c671f/480/',24.8204465,46.7519426,'الشيخ حسن بن حسين، المنصية، الرياض 13246','920034443','','','https://www.saudi-guide.com/riyadh/i/98049245/shawaya-alkhaleej-shoay-alkhlyg',1,0,'شوايه خليج shawaya alkhaleej مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049242,'riyadh','الرومانسية','Al Romansiah','al-romansiah-alromansy','["مطاعم"]','["food"]','الرومانسية إحدى أكثر سلاسل المطاعم شعبية في الرياض للطعم السعودي الأصيل، تشتهر بأطباق الكبسة والمضبي بالدجاج مع أرز الشعبي والصلصات المميزة.','<div class="texte" > <p>الرومانسية إحدى أكثر سلاسل المطاعم شعبية في الرياض للطعم السعودي الأصيل، تشتهر بأطباق الكبسة والمضبي بالدجاج مع أرز الشعبي والصلصات المميزة. تتوفر لها عدة فروع في المدينة بأجواء عائلية مريحة وخدمة سريعة تناسب أوقات الذروة. للتواصل أو الحجز: 920000144، ومواعيد الدوام من 10:30 صباحًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049242-68543714.jpg?v=1791545800", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049242-68543715.jpg?v=1791545819"]','https://cmsphoto.ww-cdn.com/resizeapi/d7ff1d2d105cfc270c85e0c38832bee9ab4bf159/480/',24.756439,46.675681,'طريق الملك عبدالعزيز الفرعي، المصيف، الرياض 12465','920000144','','','https://www.saudi-guide.com/riyadh/i/98049242/al-romansiah-alromansy',1,0,'رومانسيه al romansiah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049241,'riyadh','ديرتي','Derati','derati-dyrty','["مطاعم"]','["food"]','مطعم ديرتي مختص بتقديم الأكلات السعودية التقليدية بأشهى المذاق، ويقدم تشكيلة من الأطباق الشعبية كالكبسة والمطبق بأسلوب أصيل يعكس النكهة المحلية.','<div class="texte" > <p>مطعم ديرتي مختص بتقديم الأكلات السعودية التقليدية بأشهى المذاق، ويقدم تشكيلة من الأطباق الشعبية كالكبسة والمطبق بأسلوب أصيل يعكس النكهة المحلية. يتميز بأسعاره المناسبة وسرعة الخدمة، ما يجعله خيارًا عمليًا للوجبات اليومية. للتواصل أو الحجز: 920013111، ومواعيد الدوام من 10:30 صباحًا حتى 1:00 فجرًا تقريبًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049241-68543729.jpg?v=1791545903", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049241-68543730.jpg?v=1791545913"]','https://cmsphoto.ww-cdn.com/resizeapi/861430546dbc80482b544722e5ffd7fa802e95af/480/',24.5957403,46.772965,'العزيزية، الشارع العام - جوار العثيم، الرياض 14511','920013111','','','https://www.saudi-guide.com/riyadh/i/98049241/derati-dyrty',1,0,'ديرتي derati مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98049239,'riyadh','مقلوبة','Maqloba','maqloba-mklob','["مطاعم"]','["food"]','مطعم مقلوبة من المطاعم الشعبية المحببة في الرياض، يقدم أشهى المأكولات الخليجية بأجود المكونات الطازجة والبهارات المميزة.','<div class="texte" > <p>مطعم مقلوبة من المطاعم الشعبية المحببة في الرياض، يقدم أشهى المأكولات الخليجية بأجود المكونات الطازجة والبهارات المميزة، ويشتهر بأطباق الأرز المتنوعة كالمقلوبة والمجبوس ورز الروبيان بأحجام سخية. يوفر المطعم جلسات عائلية مريحة، ويُعد خيارًا مناسبًا للوجبات الجماعية. للتواصل أو الحجز: 920006836، ومواعيد الدوام من 11:00 صباحًا حتى 2:00 فجرًا يوميًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049239-68543804.jpg?v=1791545986", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98049239-68543815.jpg?v=1791545998"]','https://cmsphoto.ww-cdn.com/resizeapi/da2a86d072c6814644ab16294d99cce0a3c75b29/480/',24.7961651,46.7324036,'طريق الدمام، حي الشهداء، الرياض 13241','920006836','','','https://www.saudi-guide.com/riyadh/i/98049239/maqloba-mklob',1,0,'مقلوبه maqloba مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048691,'riyadh','بيت السينما','CineHouse','cinehouse-byt-alsynma','["ترفيه واستجمام"]','["fun"]','بيت السينما تجربة سينمائية راقية في حي الربيع بالرياض، تجمع بين مشاهدة أحدث الأفلام السعودية والعربية والعالمية وتجربة ضيافة مميزة داخل مطعم متصل بالصالة.','<div class="texte" > <p>بيت السينما تجربة سينمائية راقية في حي الربيع بالرياض، تجمع بين مشاهدة أحدث الأفلام السعودية والعربية والعالمية وتجربة ضيافة مميزة داخل مطعم متصل بالصالة. تتميز القاعات بتصميمها الصغير والحميمي مع مقاعد مريحة وجودة صوت وصورة عالية، ما يمنح الزوار أجواء مختلفة عن دور السينما التقليدية الكبيرة. يمكن طلب الطعام والمشروبات أثناء مشاهدة الفيلم، ويُعد المكان وجهة مثالية لمحبي السينما الباحثين عن تجربة أكثر خصوصية وراحة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048691-68543849.jpg?v=1791546069"]','https://cmsphoto.ww-cdn.com/resizeapi/924f5ccaa8d4727a201933e52998f63b9eb965d9/480/',24.7934431,46.6541116,'7773 أبي بن معاذ الأنصاري، الربيع، الرياض 13315','','','','https://www.saudi-guide.com/riyadh/i/98048691/cinehouse-byt-alsynma',1,0,'بيت سينما cinehouse ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048689,'riyadh','متحف الذهب الأسود','Black Gold Museum','black-gold-museum-mthf-althhb-alasod','["التراث والثقافة"]','["heritage"]','متحف الذهب الأسود يقع قرب مطار الملك خالد الدولي بالرياض، ويستعرض عبر أربعة طوابق العلاقة بين الإنسان والنفط بأسلوب فني احترافي.','<div class="texte" > <p>متحف الذهب الأسود يقع قرب مطار الملك خالد الدولي بالرياض، ويستعرض عبر أربعة طوابق العلاقة بين الإنسان والنفط بأسلوب فني احترافي، من تكوّن النفط واكتشافه إلى استخراجه واستخداماته عبر التاريخ في مختلف الصناعات. يعتمد المتحف على مجسمات فنية وتصاميم بصرية إبداعية تروي القصة الإيجابية والسلبية للنفط دون تحيز، مع جولة إرشادية مجانية تثري تجربة الزيارة. يلزم حجز التذاكر إلكترونيًا مسبقًا عبر منصة "webook" حيث الدخول مجاني لكن المواعيد محدودة، ورسوم الدخول للبعض نحو 20 ريالًا فقط.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048689-68543860.jpg?v=1791546150", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048689-68543862.jpg?v=1791546161"]','https://cmsphoto.ww-cdn.com/resizeapi/084d0a2e5dd439c143c9716fcd07890ed054e554/480/',24.8785625,46.7218125,'مطار الملك خالد الدولي، الرياض 13415','','','','https://www.saudi-guide.com/riyadh/i/98048689/black-gold-museum-mthf-althhb-alasod',1,0,'متحف ذهب اسود black gold museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048688,'riyadh','سوبر بارك','SuperPark Riyadh','superpark-riyadh-sobr-bark','["ترفيه واستجمام"]','["fun"]','سوبر بارك منتزه مغامرات وأنشطة داخلية عائلي يقع داخل حياة مول على طريق الملك عبدالله، ويضم مضمارًا للدراجات الرباعية، ومناطق تسلق.','<div class="texte" > <p>سوبر بارك منتزه مغامرات وأنشطة داخلية عائلي يقع داخل حياة مول على طريق الملك عبدالله، ويضم مضمارًا للدراجات الرباعية، ومناطق تسلق، وألعابًا حركية متنوعة تناسب الأطفال والكبار. يشتهر المكان باستضافة حفلات أعياد الميلاد بخدمة تنظيم متكاملة وفريق دعم متعاون، ويحظى بإقبال كبير من العائلات نظرًا لتنوع الأنشطة به. يُنصح بالحجز المسبق لحفلات الأعياد، والانتباه لتعليمات السلامة أثناء استخدام المضامير المخصصة للدراجات.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048688-68543868.jpg?v=1791546235", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048688-68543874.jpg?v=1791546246"]','https://cmsphoto.ww-cdn.com/resizeapi/a207e9a7636a2dd0b674292b84269ac0c9efe3b1/480/',24.7445613,46.6799916,'حياة مول، طريق الملك عبدالعزيز، الرياض 12272','','','','https://www.saudi-guide.com/riyadh/i/98048688/superpark-riyadh-sobr-bark',1,0,'سوبر بارك superpark riyadh ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048685,'riyadh','تويستد لابز','Twisted Labs','twisted-labs-toystd-labz','["ترفيه واستجمام"]','["fun"]','تويستد لابز مركز ترفيهي متكامل لعشاق الألعاب والرياضات الإلكترونية في منطقة الاستوديو ببوليفارد سيتي.','<div class="texte" > <p>تويستد لابز مركز ترفيهي متكامل لعشاق الألعاب والرياضات الإلكترونية في منطقة الاستوديو ببوليفارد سيتي، افتُتح في فبراير 2025 ليصبح أحد أبرز وجهات ثقافة الألعاب في السعودية. يضم المركز صالة تفاعلية للتحديات المهارية، ومركز ألعاب فيديو، ومضمار سباق داخلي، وغرفة هروب مليئة بالألغاز، إلى جانب منطقة مخصصة لمتابعة البطولات العالمية ومتجر لبيع منتجات الألعاب. تشمل التجربة تقنيات مبتكرة مثل قيادة السيارات بالتحكم الذهني، وتُعد وجهة مثالية لعشاق الرياضات الإلكترونية بأسعار تبدأ من 5 ريالات للساعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048685-68543884.jpg?v=1791546318"]','https://cmsphoto.ww-cdn.com/resizeapi/0c5ebb5984c3b609176dead59088df427c941ddd/480/',24.7693125,46.6065625,'QJ94+PJ3, حطين، الرياض 13516','','','','https://www.saudi-guide.com/riyadh/i/98048685/twisted-labs-toystd-labz',1,0,'تويستد لابز twisted labs ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048651,'umluj','شورى لينكس','Shura Links','shura-links-shora-lynks','["أماكن سياحية"]','["sights"]','وجهة جولف ساحلية فاخرة في جزيرة شورى تجمع بين الرياضة والطبيعة والأناقة، بتصميم يمتزج مع الكثبان الساحلية ومناظر البحر الأحمر.','<div class="texte" > <p>شورى لينكس ملعب جولف ساحلي فاخر مصمم على طراز ملاعب "اللينكس" التقليدية، ويمتد وسط الكثبان الرملية على جزيرة شورى بمشروع البحر الأحمر. يوفر الملعب تجربة لعب فريدة تجمع بين تحدي المسارات الرياضية وإطلالات مباشرة على المياه الفيروزية، إلى جانب نادٍ صحي (Clubhouse) يضم مطعمًا يقدم المأكولات البحرية والعالمية. يُعد وجهة مثالية لعشاق الجولف الباحثين عن تجربة راقية تمزج الرياضة بجمال الطبيعة الساحلية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048651-68543903.jpg?v=1791546401"]','https://cmsphoto.ww-cdn.com/resizeapi/15ecca9593ec2557981bf57181f9ebdbb3aee043/480/',25.50329,36.9543826,'Shura Links Golf Course, Shura Island, Red Sea Project, Hanak 48313','','','','https://www.saudi-guide.com/umluj/i/98048651/shura-links-shora-lynks',1,0,'شوري لينكس shura links اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048643,'alula','مطل الحرة','Harrat Viewpoint','harrat-viewpoint-mtl-alhr','["أماكن سياحية"]','["sights"]','نقطة إطلالة مرتفعة في العلا توفر مناظر بانورامية على الأودية العميقة والواحة الخضراء والتكوينات الصخرية البركانية، ويُفضّل زيارته عند الشروق أو الغروب.','<div class="texte" > <p>مطل الحرة نقطة إطلالة مرتفعة في العلا توفر مناظر بانورامية خلابة على الأودية العميقة والواحة الخضراء والتكوينات الصخرية البركانية الممتدة حتى الأفق. الدخول مجاني، ويُعد الموقع من أفضل الأماكن لمشاهدة الشروق أو الغروب، حيث ينصح بالوصول قبل الموعد بنحو 20 دقيقة لتجنب الازدحام والاستمتاع بالمنظر كاملًا. يحتوي الموقع على مطعم ومقهى بأسعار مرتفعة نسبيًا يفتحان من الساعة التاسعة صباحًا، لذا يُفضل إحضار المشروبات والوجبات الخفيفة الخاصة، مع العلم أن الطريق المؤدي للمطل جبلي ومتعرج لكنه بحالة جيدة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048643-68544335.jpg?v=1791548662"]','https://cmsphoto.ww-cdn.com/resizeapi/0f9cfb12d51e68378eb73dad06c7e412b2c33199/480/',26.6323815,37.8967098,'JVMW+6P، العلا 43562','','https://www.experiencealula.com/ar/places-to-go/harrat-viewpoint','','https://www.saudi-guide.com/alula/i/98048643/harrat-viewpoint-mtl-alhr',1,0,'مطل حره harrat viewpoint اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048641,'alula','سينما الجديدة','Cinema AlJadidah','cinema-aljadidah-synma-algdyd','["أماكن سياحية"]','["sights"]','تجربة سينما مفتوحة في الهواء الطلق داخل حي الجديدة بالعلا، تجمع بين أفلام الفن الراقي والأفلام العالمية الكبرى والسينما العربية في أجواء سحرية مميزة.','<div class="texte" > <p>سينما الجديدة تجربة سينمائية فريدة في الهواء الطلق داخل حي الجديدة بالعلا، حيث يتحول عرض الأفلام إلى مناسبة اجتماعية بأجواء ليلية ساحرة بعيدة عن قاعات السينما التقليدية. تعمل الشاشة بأحدث تقنيات العرض والصوت المحيطي، وتعرض مزيجًا من أفلام السينما العالمية والعربية وأفلام الفن الراقي وفق جدول أسبوعي، إذ تفتح أبوابها غالبًا من الخميس إلى السبت مساءً. يُنصح بالتحقق من برنامج العروض مسبقًا، مع العلم أن منطقة الوجبات الخفيفة تقع في موقع منفصل قليلًا عن صالة العرض.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048641-68544342.jpg?v=1791548748"]','https://cmsphoto.ww-cdn.com/resizeapi/f6d61367eb7219df136021adf9258e8374e7e482/480/',26.630803,37.9125349,'حي الجديدة، العلا 43523','','https://www.experiencealula.com/ar/places-to-go/cinema-aljadidah','','https://www.saudi-guide.com/alula/i/98048641/cinema-aljadidah-synma-algdyd',1,0,'سينما جديده cinema aljadidah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048613,'taif','سفاري الطائف','Taif Safari','taif-safari-sfary-altayf','["أماكن سياحية"]','["sights"]','سفاري الطائف حديقة مغامرات في أجواء جبلية باردة، تضم بحيرة للتجديف وألعاباً للأطفال ومنطقة سفاري تعرض بعض الحيوانات ومناطق للنزهات.','<div class="texte" > <p>سفاري الطائف أول حديقة مغامرات من نوعها في المنطقة الغربية، تقع في أجواء جبلية باردة ومحاطة بمناظر طبيعية خلابة على بعد مسافة قصيرة من مدينة الطائف. تضم الحديقة بحيرة صغيرة للتجديف بالقوارب، وألعابًا متنوعة للأطفال، ومنطقة سفاري بسيطة تعرض بعض الحيوانات، إلى جانب مناطق للنزهات ومحال لبيع الهدايا والأطعمة الخفيفة. تشهد الحديقة تفاوتًا في جودة الخدمة حسب الموسم، ويُنصح بالتحقق من حالة الأجواء الجوية قبل الزيارة نظرًا لطول الطريق المؤدي إليها.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048613-68544349.jpg?v=1791548812", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048613-68544350.jpg?v=1791548819"]','https://cmsphoto.ww-cdn.com/resizeapi/78ddf1710ed7a2b31dfec534bbf39618fb637ce6/480/',21.5536567,40.493337,'الطائف 26334','','','','https://www.saudi-guide.com/taif/i/98048613/taif-safari-sfary-altayf',1,0,'سفاري طائف taif safari اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048612,'taif','بيرد بارك','Bird Park','bird-park-byrd-bark','["أماكن سياحية"]','["sights"]','بيرد بارك في الهدا بالطائف وجهة لعشاق الطيور، تتيح تجربة تفاعلية مع الببغاوات والطيور المغردة وأقسام للأرانب وبعض الحيوانات الأليفة.','<div class="texte" > <p>بيرد بارك في الهدا بالطائف وجهة محببة لعشاق الطيور، حيث يتيح للزوار تجربة تفاعلية مباشرة مع أنواع متعددة من الطيور كالببغاوات والطيور المغردة، إلى جانب أقسام مخصصة للأرانب وخنازير غينيا وبعض الحيوانات النادرة الأليفة. تتميز الحديقة بنظافتها العالية وتنظيمها الجيد رغم كثرة الطيور فيها. تتوفر مرافق صلاة ودورات مياه، ما يجعلها وجهة مريحة لقضاء وقت ممتع مع العائلة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048612-68544360.jpg?v=1791548888", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048612-68544364.jpg?v=1791548895"]','https://cmsphoto.ww-cdn.com/resizeapi/e7b27e11cd6556dbb4d0197558dde5e207c7291d/480/',21.3409745,40.2920252,'شارع لامير نايف بن عبدالعزيز، الهدا، الطائف 26792','','','','https://www.saudi-guide.com/taif/i/98048612/bird-park-byrd-bark',1,0,'بيرد بارك bird park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048610,'taif','معمل الشيوخ للورد الطائفي','Al Shuyukh Taif Rose Factory','al-shuyukh-taif-rose-factory-maaml-alshyokh-llord-altayfy','["التراث والثقافة"]','["heritage"]','معمل الشيوخ للورد الطائفي قرب ميقات وادي محرم في الهدا، يعرّف الزوار بفن استخلاص دهن الورد وماء الورد، ويضم معرضاً للمنتجات ومقهى.','<div class="texte" > <p>معمل الشيوخ للورد الطائفي وجهة عريقة قرب ميقات وادي محرم في الهدا، تُعرّف الزوار بفن استخلاص زيت الورد وماء الورد الطائفي الأصيل عبر جولة تفصيلية في خطوات التصنيع. يضم المعمل معرضًا للمنتجات يشمل العطور ومستحضرات التجميل المصنوعة من الورد، إلى جانب مقهى داخلي بتصميم أنيق يقدم مشروبات ووجبات إفطار عربية تقليدية. تزهر حدائق الورد المحيطة بالمعمل في شهر مارس من كل عام، ما يجعل هذا الموسم الأنسب للزيارة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048610-68544379.jpg?v=1791548959", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048610-68544380.jpg?v=1791548967"]','https://cmsphoto.ww-cdn.com/resizeapi/d4f890c6d1a486c17acd167b8af8b70b3102ee2b/480/',21.3478867,40.3250183,'بجوار ميقات وادي محرم، الهدا، الطائف 26581','','','','https://www.saudi-guide.com/taif/i/98048610/al-shuyukh-taif-rose-factory-maaml-alshyokh-llord-altayfy',1,0,'معمل شيوخ للورد طائفي al shuyukh taif rose factory تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048609,'taif','بوابة المغامرات','Adventure Gate','adventure-gate-boab-almghamrat','["أماكن سياحية"]','["sights"]','بوابة المغامرات مدينة ترفيهية داخلية في حي الجال بالطائف، تضم ألعاباً حديثة للمغامرة والحركة تناسب مختلف الأعمار من الأطفال إلى الكبار.','<div class="texte" > <p>بوابة المغامرات مدينة ترفيهية داخلية في حي الجال بالطائف، تضم مجموعة واسعة من الألعاب الحديثة المصممة لتناسب مختلف الفئات العمرية من الأطفال الصغار وحتى المراهقين والكبار. تُصنَّف الألعاب حسب الطول ضمن باقات متعددة تشمل ألعاب المغامرة والحركة، ويُعد المكان من أفضل الوجهات الترفيهية المغطاة في المدينة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048609-68544384.jpg?v=1791549028", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048609-68544386.jpg?v=1791549035"]','https://cmsphoto.ww-cdn.com/resizeapi/1695d9392b4fce2ea24b9d6d4da6db324d04ad34/480/',21.2794067,40.4432313,'شارع 50، الجال، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98048609/adventure-gate-boab-almghamrat',1,0,'بوابه مغامرات adventure gate اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048589,'taif','مزرعة الفراولة','Strawberries Farm','strawberries-farm-mzraa-alfraol','["أماكن سياحية"]','["sights"]','مزرعة الفراولة في الهدا بالطائف وجهة عائلية بحدائق جميلة وأكشاك للفراولة الطازجة ومنتجاتها، مع حديقة طيور صغيرة ومنطقة ألعاب للأطفال.','<div class="texte" > <p>مزرعة الفراولة في الهدا بالطائف وجهة عائلية شهيرة، تتيح للزوار التجول بين حدائقها الجميلة واستنشاق الهواء المنعش. تضم المزرعة أكشاكاً لبيع الفراولة الطازجة ومنتجاتها كالعصائر والبان كيك والآيس كريم، إلى جانب حديقة طيور صغيرة ومنطقة ألعاب بطابع القراصنة للأطفال. رسوم الدخول نحو 35 ريالًا للشخص، وتُغلق المزرعة مؤقتًا خلال أوقات الصلاة يوم الجمعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048589-68544396.jpg?v=1791549096", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048589-68544397.jpg?v=1791549103"]','https://cmsphoto.ww-cdn.com/resizeapi/6412fccca465882901a4a32d0ef85b94ead6155d/480/',21.3553954,40.2714694,'الهدا، الطائف 26794','','','','https://www.saudi-guide.com/taif/i/98048589/strawberries-farm-mzraa-alfraol',1,0,'مزرعه فراوله strawberries farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048588,'taif','قيمز سكوير','Game Square','game-square-kymz-skoyr','["أماكن سياحية"]','["sights"]','قيمز سكوير في تيرا مول بالطائف وجهة ترفيهية داخلية تجمع البولينج ومحاكيات السباق وألعاب الرماية وتجارب الواقع الافتراضي لمختلف الأعمار.','<div class="texte" > <p>قيمز سكوير في تيرا مول بالطائف وجهة ترفيهية داخلية تجمع بين البولينج، وطاولات الألعاب المتنوعة، ومحاكيات السباق، وألعاب الرماية، وتجارب الواقع الافتراضي التي تناسب مختلف الأعمار. يوفر المكان أجواءً موسيقية حيوية ومقهى داخليًا لتناول المشروبات أثناء اللعب، ويُعد خيارًا مناسبًا لقضاء أمسية ترفيهية مع الأصدقاء أو العائلة بعيدًا عن حرارة الطقس الخارجي.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048588-68544405.jpg?v=1791549167"]','https://cmsphoto.ww-cdn.com/resizeapi/6e275a81bd88acad183190c81b4b5498fc70c186/480/',21.2792902,40.4421489,'حي الجال، تيرا مول، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98048588/game-square-kymz-skoyr',1,0,'قيمز سكوير game square اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048586,'taif','سيتي ووك الطائف','Taif City Walk','taif-city-walk-syty-ook-altayf','["أماكن سياحية"]','["sights"]','سيتي ووك الطائف ممشى عصري مفتوح في حي الجال يضم مطاعم ومقاهي ومحال تجارية ومساحات لأنشطة الأطفال، وجهة مثالية للنزهات المسائية.','<div class="texte" > <p>سيتي ووك الطائف ممشى عصري مفتوح يقع في حي الجال، ويُعد من أكثر الوجهات الترفيهية حيوية في المدينة، خاصة خلال ساعات المساء. يضم الممشى مجموعة متنوعة من المطاعم والمقاهي العالمية والمحلية، ومحال تجارية، ومساحات مخصصة لأنشطة الأطفال وفعاليات موسمية تقام على مدار العام. تحيط بالممشى أشجار وزهور عطرة تضفي أجواءً منعشة، ويُعد وجهة مثالية للنزهات المسائية وقضاء وقت ممتع مع العائلة والأصدقاء.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048586-68544416.jpg?v=1791549243", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048586-68544418.jpg?v=1791549249"]','https://cmsphoto.ww-cdn.com/resizeapi/2ac45d315a9abe2a87bc96a72b47ee84adaa7a26/480/',21.2906637,40.433829,'8004، حي الجال، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98048586/taif-city-walk-syty-ook-altayf',1,0,'سيتي ووك طائف taif city walk اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048582,'taif','حديقة مسرة','Masarrah Park','masarrah-park-hdyk-msr','["أماكن سياحية"]','["sights"]','حديقة مسرة من الحدائق الشهيرة في الطائف، تتميز بنظافتها ومساحاتها العشبية ومناطقها المظللة وألعاب الأطفال، وخيار مناسب لأمسية عائلية هادئة.','<div class="texte" > <p>حديقة مسرة من الحدائق الشهيرة في الطائف، ورغم مساحتها المتوسطة إلا أنها تتميز بنظافتها وجودة مرافقها. تضم الحديقة مساحات عشبية واسعة ومناطق مظللة، وألعابًا للأطفال، ودورات مياه نظيفة متوفرة على مدار اليوم. يمارس الزوار فيها أنشطة الشواء رغم القيود المعتادة على ذلك في الحدائق العامة، وتتوفر بالقرب منها مطاعم بيتزا ومحال تسوق صغيرة، ما يجعلها خيارًا مناسبًا لقضاء أمسية عائلية هادئة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048582-68544423.jpg?v=1791549316"]','https://cmsphoto.ww-cdn.com/resizeapi/b10854a39a6701c54f8151998882ecd4ff5de07a/480/',21.2998424,40.3875162,'4068 طريق المؤتمرات، مسرة، الطائف 26528','','','','https://www.saudi-guide.com/taif/i/98048582/masarrah-park-hdyk-msr',1,0,'حديقه مسره masarrah park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048580,'taif','قصر الكعكي','Kaki Palace','kaki-palace-ksr-alkaaky','["التراث والثقافة"]','["heritage"]','قصر الكعكي معلم معماري في المنطقة التاريخية بالطائف، يمزج بين الطراز الروماني والزخارف الحجازية ويشتهر بخشب العرعر والزجاج الملون.','<div class="texte" > <p>قصر الكعكي معلم معماري بارز في المنطقة التاريخية بالطائف، شُيّد بطراز فريد يمزج بين العمارة الرومانية والزخارف الحجازية التقليدية. استُخدم في بنائه خشب العرعر والجرانيت والزجاج الملون، ما يمنحه طابعاً جمالياً مميزاً يعكس ذوق تلك الحقبة، ويظل منظره الخارجي جذاباً للزوار والمصورين المهتمين بالعمارة القديمة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048580-68544428.jpg?v=1791549377"]','https://cmsphoto.ww-cdn.com/resizeapi/f88a8ca96b119660d1971afabf1bb6adba83d9d9/480/',21.269807,40.4054967,'7C94+W5H, السلامة، الطائف 26522','','','','https://www.saudi-guide.com/taif/i/98048580/kaki-palace-ksr-alkaaky',1,0,'قصر كعكي kaki palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048578,'taif','وادي قرن','Wadi Qarn','wadi-qarn-oady-krn','["أماكن سياحية"]','["sights"]','وادي قرن في الطائف واد تاريخي ورد ذكره في الشعر العربي القديم، يتميز بمناخه المعتدل ومناظره الخضراء ونباتاته العطرية وسد أثري قديم.','<div class="texte" > <p>وادي قرن واد تاريخي يعود اسمه إلى العصر الجاهلي، ويُذكر في الشعر العربي القديم ضمن قصص قبيلة بني فهم. يتميز الوادي بمناخه المعتدل ومناظره الخضراء المنعشة، وتنتشر فيه نباتات عطرية برية تضفي عليه جمالًا خاصًا، إلى جانب سد أثري قديم يقع في أعلى الوادي. يُعد وجهة مفضلة لهواة المشي والاستكشاف الطبيعي، لكن يُنصح بالحفاظ على نظافة الموقع نظرًا لتراكم بعض المخلفات في بعض المناطق.</p> </div>','[]','',21.468974,40.4073294,'وادي قرن، الطائف','','','','https://www.saudi-guide.com/taif/i/98048578/wadi-qarn-oady-krn',1,0,'وادي قرن wadi qarn اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048577,'taif','مزرعة بن سلمان','Bin Salman Farm','bin-salman-farm-mzraa-bn-slman','["أماكن سياحية"]','["sights"]','مزرعة بن سلمان في الطائف تحتفي بتراث زراعة الورد واللوز، وتضم مقاهي وجلسات بين حقول الورد ومعملاً صغيراً لصناعة العطور والصابون.','<div class="texte" > <p>مزرعة بن سلمان في الطائف وجهة فريدة تحتفي بتراث زراعة الورد واللوز في المنطقة، وتتحول في موسم الربيع إلى حديقة وردية عطرة تفوح فيها رائحة الورد الطائفي الأصيل. توفر المزرعة مقاهٍ ومساحات جلوس خارجية بين حقول الورد وسلسلة جبال السروات، إلى جانب معمل صغير لصناعة العطور والصابون من الورد. تشتهر بكعكة الورد اللذيذة وقهوتها المميزة، لكن يُنصح بالحجز أو الزيارة في أوقات الصباح الباكر لتفادي الازدحام ومحدودية مواقف السيارات.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048577-68539283.jpg?v=1791527790", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048577-68539284.jpg?v=1791527801"]','https://cmsphoto.ww-cdn.com/resizeapi/f8e64d0c7747e09cf6997e391a8b976912a1e39a/480/',21.3847852,40.3454588,'بلاد طويرق، الطائف 26583','','','','https://www.saudi-guide.com/taif/i/98048577/bin-salman-farm-mzraa-bn-slman',1,0,'مزرعه بن سلمان bin salman farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048576,'taif','أكبر شجرة معمرة في السعودية','Oldest Tree in Saudi Arabia','oldest-tree-in-saudi-arabia-akbr-shgr-maamr-fy-alsaaody','["التراث والثقافة"]','["heritage"]','شجرة معمرة على طريق الوهط والوهيط السياحي بالطائف، تحيط بها مناظر طبيعية خلابة ومساحات للتخييم وبقايا نخيل قديمة تعكس تاريخ الوادي.','<div class="texte" > <p>تقع هذه الشجرة المعمرة على طريق الوهط والوهيط السياحي بالطائف، وتُعد من أشهر الأشجار المعمرة في المملكة وشاهدة حية على تاريخ المنطقة الطويل. تحيط بالشجرة مناظر طبيعية خلابة ومساحات مخصصة للتخييم والرحلات العائلية، وتنتشر حولها بقايا نخيل قديمة تعكس تاريخ الزراعة في الوادي، ويقصدها الزوار للتأمل والتصوير.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048576-68539285.jpg?v=1791527860", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048576-68539289.jpg?v=1791527870"]','https://cmsphoto.ww-cdn.com/resizeapi/b0e3fa05af8119636a9e8f0c597a31ec3aa73a72/480/',21.1927259,40.3442256,'طريق الوهط والوهيط السياحي، الطائف 26781','','','','https://www.saudi-guide.com/taif/i/98048576/oldest-tree-in-saudi-arabia-akbr-shgr-maamr-fy-alsaaody',1,0,'اكبر شجره معمره في سعوديه oldest tree in saudi arabia تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048575,'taif','جبل دكا','Mount Daka','mount-daka-gbl-dka','["أماكن سياحية"]','["sights"]','جبل دكا في الطائف يكسوه غطاء كثيف من أشجار العرعر المعمرة، ويوفر مسارات للتنزه وإطلالات بانورامية على الوديان وأجواء جبلية باردة نسبياً.','<div class="texte" > <p>جبل دكا في الطائف يتميز بغطاء كثيف من أشجار العرعر المعمرة، وتنخفض درجات الحرارة تدريجيًا كلما ارتفع الزائر نحو القمة، ما يجعله ملاذًا منعشًا هربًا من حرارة الصيف. يوفر الجبل مسارات طبيعية للتنزه بين الأشجار، وإطلالات بانورامية واسعة على الوديان والسهول المحيطة به. يُعد وجهة هادئة بعيدة عن الازدحام السياحي، ومناسبة لهواة التخييم والتصوير الطبيعي في أجواء جبلية باردة نسبيًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048575-68539290.jpg?v=1791527927"]','https://cmsphoto.ww-cdn.com/resizeapi/0227439b0dbcc8fa096891698dbb6fc3c803d7d2/480/',21.0929679,40.2935452,'جبل دكا، الطائف','','','','https://www.saudi-guide.com/taif/i/98048575/mount-daka-gbl-dka',1,0,'جبل دكا mount daka اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048574,'taif','مصنع القرشي','Rashed Al Qurashi Factory','rashed-al-qurashi-factory-msnaa-alkrshy','["التراث والثقافة"]','["heritage"]','مصنع القرشي من أعرق مصانع دهن وماء الورد في الطائف، يتيح مشاهدة عملية التقطير التقليدية للورد الطائفي مع فيلم وثائقي عن تاريخ الصناعة.','<div class="texte" > <p>مصنع القرشي (Rashed Al Qurashi) من أعرق مصانع دهن وماء الورد في الطائف، يقدم للزوار تجربة مشاهدة عملية التقطير التقليدية للورد الطائفي الشهير، إلى جانب فيلم وثائقي قصير يشرح تاريخ هذه الصناعة العريقة. يضم المصنع متجرًا واسعًا لمنتجات العطور الفاخرة ودهن الورد وماء الورد بأسعار متفاوتة، ومقهى هادئًا يطل على أجواء جبلية باردة. رسوم الدخول رمزية لا تتجاوز 5 ريالات، ويُنصح بالزيارة خلال موسم قطف الورد في فصل الربيع لمشاهدة الحقول المزهرة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048574-68539293.jpg?v=1791527986", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048574-68539294.jpg?v=1791527995"]','https://cmsphoto.ww-cdn.com/resizeapi/b2aa31a7cc6da10d185e87fb597e308dca0749ad/480/',21.3369119,40.283463,'شارع الأمير نايف، الطائف 26792','','','','https://www.saudi-guide.com/taif/i/98048574/rashed-al-qurashi-factory-msnaa-alkrshy',1,0,'مصنع قرشي rashed al qurashi factory تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048439,'asir-region','تجربة كوخ العسل','Bees Tower Honey Refinery','bees-tower-honey-refinery-tgrb-kokh-alaasl','["التراث والثقافة"]','["heritage"]','اكتشف تراث تربية النحل في منطقة عسير، واستمتع بتذوق أنواع العسل الطبيعي المتنوعة، وتسوق من المتجر المخصص وسط أجواء تراثية.','<div class="texte" > <p>تجربة كوخ العسل (Bees Tower Honey Refinery) وجهة تراثية فريدة تُعرّف الزوار بتاريخ عائلة محلية عريقة اشتهرت بتربية النحل وإنتاج العسل عبر الأجيال. يضم الموقع مبنى مصمم على شكل أبراج تشبه خلايا النحل، وقاعة تذوق تعرض أكثر من 40 نوعًا مختلفًا من العسل الطبيعي كالسدر والحبة السوداء واللوز، إلى جانب متجر لبيع المنتجات ومقهى ومطعم. يشهد المكان إقبالًا كبيرًا خصوصًا في المناسبات والأعياد، وقد ترتفع الأسعار وتطول أوقات الانتظار في تلك الفترات.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048439-68539296.jpg?v=1791528053", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048439-68539297.jpg?v=1791528066"]','https://cmsphoto.ww-cdn.com/resizeapi/1872e1b9242de3c4f212d8e466624d545f5b20d1/480/',18.2016259,42.2851703,'Al Batilah 63455','','','','https://www.saudi-guide.com/asir-region/i/98048439/bees-tower-honey-refinery-tgrb-kokh-alaasl',1,0,'تجربه كوخ عسل bees tower honey refinery تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048437,'asir-region','القصر التراثي بقرية آل قزع','Al Qazaa Heritage Palace','al-qazaa-heritage-palace-alksr-altrathy-bkry-al-kzaa','["التراث والثقافة"]','["heritage"]','القصر التراثي بقرية آل قزع في عسير يُجسّد العمارة الجنوبية القديمة، ويُعد معلمًا ثقافيًا يعكس التراث المحلي للمنطقة.','<div class="texte" > <p>القصر التراثي بقرية آل قزع معلم أثري في منطقة عسير، استغرق بناؤه نحو 140 عامًا، ويُجسد تفاصيل العمارة الجنوبية القديمة بحجارتها المصقولة ونقوشها التقليدية. رُمم القصر مؤخرًا على يد أحد الفنانين المحليين للحفاظ على طابعه الأصيل، ويملكه اليوم أحد أحفاد الأسرة المؤسسة الذي يستقبل الزوار شخصيًا ويروي لهم قصة القصر وتاريخ العائلة. يقدّم المكان مشروبات ساخنة وباردة معدة محليًا وسط أجواء تراثية أصيلة، وتُعد الزيارة تجربة ثقافية غنية أكثر من كونها مجرد جولة سياحية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048437-68539301.jpg?v=1791528133", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048437-68539303.jpg?v=1791528148"]','https://cmsphoto.ww-cdn.com/resizeapi/92a9d8c93868987a3eacc6ab9e5b29e6bf11061f/480/',18.0296045,42.7540904,'AGPD8186, 3655 Al Faraa, Al Qazaa, Al Shaaf 62269','','','','https://www.saudi-guide.com/asir-region/i/98048437/al-qazaa-heritage-palace-alksr-altrathy-bkry-al-kzaa',1,0,'قصر تراثي بقريه قزع al qazaa heritage palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048434,'asir-region','فابي لاند','Fabyland','fabyland-faby-land','["أماكن سياحية"]','["sights"]','استمتع بتجربة فابي لاند، المركز الترفيهي الداخلي في الراشد مول بأبها، المليء بالألعاب والأنشطة المتنوعة لجميع الأعمار.','<div class="texte" > <p>فابي لاند مركز ترفيهي داخلي كبير يقع داخل الراشد مول بأبها، ويُعد من أبرز الوجهات الترفيهية المغطاة في المدينة خصوصًا في أيام الحر أو المطر. يضم المركز مجموعة واسعة من الألعاب الإلكترونية التقليدية والحديثة، إلى جانب عروض خاصة للأطفال ذوي الإعاقة تتيح لهم تجربة ترفيهية مناسبة. تعمل بعض الألعاب المتنقلة في أوقات مسائية محددة فقط، ويُنصح بالتحقق من مواعيد التشغيل مسبقًا، مع الأخذ بالحسبان الازدحام في أوقات العطلات.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048434-68539308.jpg?v=1791528204", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048434-68539309.jpg?v=1791528217"]','https://cmsphoto.ww-cdn.com/resizeapi/b3c16af21fd2f8fec41c04114a2517f3400a78de/480/',18.2376383,42.5807251,'6HPJ+V3, Al Badea, Abha 62581','','','','https://www.saudi-guide.com/asir-region/i/98048434/fabyland-faby-land',1,0,'فابي لاند fabyland اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048432,'asir-region','داينو بارك','Dino Park','dino-park-dayno-bark','["أماكن سياحية"]','["sights"]','استكشف داينو بارك أبها، الوجهة الترفيهية التعليمية التي تضم مجسمات ديناصورات بالحجم الطبيعي وتجارب تفاعلية للأطفال وسط أجواء مشوقة.','<div class="texte" > <p>داينو بارك أبها وجهة ترفيهية تعليمية مخصصة للأطفال، تضم مجسمات ديناصورات بالحجم الطبيعي موزعة في أرجاء الحديقة، إلى جانب ألعاب كهربائية متنوعة وزحاليق تناسب الأعمار الصغيرة. تعمل الحديقة ببطاقات مسبقة الدفع تتيح للأطفال ركوب عدد من الألعاب أو دخول قسم الديناصورات بشكل منفصل، مع توفر مصلى ودورات مياه نظيفة. يُعد المكان مناسبًا لقضاء أمسية عائلية بأسعار معقولة، وينصح بزيارته مساءً بعيدًا عن حرارة النهار.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048432-68539311.jpg?v=1791528290"]','https://cmsphoto.ww-cdn.com/resizeapi/8de2753ccbdb075a40ed1d97f61d4f1ec1c2e6c3/480/',18.2142817,42.6598947,'6M75+PX6, Abha 62439','','','','https://www.saudi-guide.com/asir-region/i/98048432/dino-park-dayno-bark',1,0,'داينو بارك dino park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048430,'asir-region','مزرعة روح','Rooh Farm','rooh-farm-mzraa-roh','["أماكن سياحية"]','["sights"]','استمتع بتجربة مزرعة ريفية متكاملة في جبال أبها، توفر الإقامة والأنشطة المتنوعة، بعيدًا عن صخب المدينة وسط أجواء هادئة وضبابية.','<div class="texte" > <p>مزرعة روح تجربة ريفية متكاملة تقع في جبال أبها، وتوفر إقامة هادئة بعيدة عن صخب المدينة وسط أجواء طبيعية وضبابية على مدار العام تقريبًا. تضم المزرعة أشجار فاكهة متنوعة ومساحات مفتوحة للتجول، إلى جانب وحدات سكنية تتسع لمجموعات تصل إلى تسعة أشخاص، ما يجعلها مناسبة للعائلات الكبيرة أو مجموعات الأصدقاء. يُنصح باستخدام سيارة مناسبة للطرق الجبلية الوعرة عند التوجه إليها، والتواصل المسبق مع المالك لتأكيد الحجز.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048430-68539312.jpg?v=1791528348", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048430-68539313.jpg?v=1791528359"]','https://cmsphoto.ww-cdn.com/resizeapi/3e7c00861063a63f715a09b270730057381c2ef1/480/',18.1709322,42.4047279,'5CC3+9VH, Abha 62519','','','','https://www.saudi-guide.com/asir-region/i/98048430/rooh-farm-mzraa-roh',1,0,'مزرعه روح rooh farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048428,'asir-region','منتجع الوادي','Valley Resort','valley-resort-mntgaa-aloady','["أماكن سياحية"]','["sights"]','منتجع به العديد من الخيارات للسكن والمأكولات والمشروبات وأيضًا الفعاليات، ويضم أكبر نافورة راقصة في السعودية ونموذجًا لقرية جنوبية تراثية.','<div class="texte" > <p>منتجع الوادي يقع في وادي ابن هشبل بمنطقة عسير، ويُعد من أكبر المنتجعات العائلية في المنطقة بمساحته الواسعة ومرافقه المتعددة. يضم المنتجع أكبر نافورة راقصة في السعودية، ونموذجًا مصغرًا لقرية جنوبية تراثية، إلى جانب مزرعة تضم أشجار الفاكهة والنخيل ومناطق للتجول سيرًا أو باستخدام عربات جولف وباصات مزدوجة الطوابق. توفر خيارات إقامة متنوعة ومطاعم ومقاهٍ، ويُنصح بتخصيص يوم كامل للاستمتاع بجميع مرافقه.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048428-68539316.jpg?v=1791528422", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048428-68539318.jpg?v=1791528439"]','https://cmsphoto.ww-cdn.com/resizeapi/7a7ec13b036bd82d3d86ca9a9d2b99495a813db9/480/',18.604311,42.7178361,'Wadi Ibn Hashbal 62918','','','','https://www.saudi-guide.com/asir-region/i/98048428/valley-resort-mntgaa-aloady',1,0,'منتجع وادي valley resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048427,'asir-region','شلال المحطبة','Al Mohatibah Waterfall','al-mohatibah-waterfall-shlal-almhtb','["أماكن سياحية"]','["sights"]','شلال المحطبة موقع طبيعي شديد الانحدار في أبها، يضم شلالًا موسميًا يتدفق بغزارة عقب هطول الأمطار وسط بيئة جبلية وعرة ذات مناظر خلابة.','<div class="texte" > <p>شلال المحطبة موقع طبيعي شديد الانحدار في أبها، يضم شلالًا موسميًا يتدفق بغزارة عقب هطول الأمطار وسط بيئة جبلية وعرة ذات مناظر خلابة. يتطلب الوصول إلى الموقع الالتزام بالحذر التام نظرًا لوعورة الطريق وانحداره الشديد، لذا لا يُنصح بزيارته للعائلات التي بصحبتها أطفال أو كبار السن. يُعد وجهة مفضلة لهواة المغامرة والتصوير الطبيعي، ويفضل تفقد حالة الطقس ومستوى المياه قبل التوجه إليه.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048427-68539321.jpg?v=1791528503"]','https://cmsphoto.ww-cdn.com/resizeapi/6abe38ae5f33082d761583e6f76e9d1291eb95a4/480/',18.2062686,42.457817,'62683, Abha 62514','','','','https://www.saudi-guide.com/asir-region/i/98048427/al-mohatibah-waterfall-shlal-almhtb',1,0,'شلال محطبه al mohatibah waterfall اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048425,'asir-region','منتزه الريف','Al Reef Park','al-reef-park-mntzh-alryf','["أماكن سياحية"]','["sights"]','وجهة طبيعية هادئة في قرى بني مازن، تتميز بجلسات عائلية وإطلالات على المدرجات الزراعية، وتُعد مكانًا مثاليًا للتنزه وسط الطبيعة الريفية العسيرية.','<div class="texte" > <p>منتزه الريف وجهة طبيعية هادئة في قرى بني مازن، تتميز بجلساتها العائلية المطلة على المدرجات الزراعية الخضراء المنتشرة على سفوح الجبال. يوفر الموقع مقهى ومطعمًا يقدمان أطباقًا محلية بخدمة مميزة، إلى جانب أجواء هادئة بعيدة عن صخب المدينة تناسب من يبحث عن استراحة قصيرة وسط الطبيعة الريفية العسيرية. يُعد مكانًا مثاليًا لتناول وجبة مع إطلالة خلابة خصوصًا في الأيام الضبابية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048425-68539324.jpg?v=1791528553", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048425-68539325.jpg?v=1791528572"]','https://cmsphoto.ww-cdn.com/resizeapi/9ec84529b70c7d98219c19d4e46d773de58aa461/480/',18.1783548,42.4559107,'Bani Mazin 62322','','','','https://www.saudi-guide.com/asir-region/i/98048425/al-reef-park-mntzh-alryf',1,0,'منتزه ريف al reef park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048424,'asir-region','منتزه السحاب','Al Sahab Park','al-sahab-park-mntzh-alshab','["أماكن سياحية"]','["sights"]','يقع على قمة جبل في السودة، ويُعرف بإطلالاته الخلابة وأجوائه الضبابية الدائمة، ويضم جلسات عائلية ومسارات للمشي بين الغيوم. منتزه.','<div class="texte" > <p>منتزه السحاب يقع على قمة أحد جبال السودة الشاهقة، ويُعد من أعلى النقاط السياحية في المملكة، حيث يمكن للزوار لمس الغيوم فعليًا عند مرورها عبر الموقع. يوفر المنتزه أكواخًا خشبية ومجالس للإيجار بالساعة، مع تقديم وجبات محلية كالأرز والدجاج ضمن باقات مناسبة الأسعار. يشهد الموقع إقبالًا كبيرًا خصوصًا في فصل الصيف هربًا من الحر، وينصح بالحجز المسبق للمجالس وارتداء ملابس دافئة نظرًا لبرودة الطقس في الأعلى.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048424-68539329.jpg?v=1791528634", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048424-68539330.jpg?v=1791528642"]','https://cmsphoto.ww-cdn.com/resizeapi/0876f6e141fde6dd34a67f0c33de2e8e594d2f48/480/',18.2184625,42.3965781,'Al Soudah 63479','','','','https://www.saudi-guide.com/asir-region/i/98048424/al-sahab-park-mntzh-alshab',1,0,'منتزه سحاب al sahab park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048419,'asir-region','منتزه قمم تمنية','Tamniah Peaks Park','tamniah-peaks-park-mntzh-kmm-tmny','["أماكن سياحية"]','["sights"]','منتزه قمم تمنية موقع جبلي مرتفع في بلدة تمنية بمنطقة عسير، يشتهر بإطلالاته الخلابة التي تمتد على الجبال الخضراء والوديان المحيطة على طول الطريق المؤدي إليه.','<div class="texte" > <p>منتزه قمم تمنية موقع جبلي مرتفع في بلدة تمنية بمنطقة عسير، يشتهر بإطلالاته الخلابة التي تمتد على الجبال الخضراء والوديان المحيطة على طول الطريق المؤدي إليه. يمر الطريق بقرى تراثية جميلة ذات عمارة عسيرية تقليدية، وتتميز المنطقة بأجواء ضبابية ساحرة تتيح مشاهدة السحب من قمة الجبل. يفتقر الموقع حاليًا لبعض الخدمات كدورات المياه، لذا يُنصح بالتحضير المسبق قبل الزيارة والتحلي بالمسؤولية البيئية للحفاظ على نظافة الطبيعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048419-68539346.jpg?v=1791528787"]','https://cmsphoto.ww-cdn.com/resizeapi/3b426607f16f78666ea5926931875eff63693683/480/',17.9838871,42.7701619,'Tareeq 13, Tamniah 62269','','','','https://www.saudi-guide.com/asir-region/i/98048419/tamniah-peaks-park-mntzh-kmm-tmny',1,0,'منتزه قمم تمنيه tamniah peaks park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048417,'asir-region','سماء بارك','Sama Park','sama-park-sma-bark','["أماكن سياحية"]','["sights"]','سماء بارك منتزه ترفيهي يقع على طريق الأمير سلطان بأبها، ويجمع بين الجلسات العائلية والألعاب الترفيهية المتنوعة.','<div class="texte" > <p>سماء بارك منتزه ترفيهي يقع على طريق الأمير سلطان بأبها، ويجمع بين الجلسات العائلية والألعاب الترفيهية المتنوعة. يضم المنتزه زحاليق مائية وألعابًا للأطفال، إلى جانب مساحات جلوس مفتوحة تناسب التجمعات العائلية والأصدقاء. يتميز الموقع بإطلالاته الجميلة على محيطه الطبيعي، ويُعد وجهة اقتصادية مناسبة لقضاء أمسية ترفيهية بأسعار معقولة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048417-68539349.jpg?v=1791528850", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048417-68539350.jpg?v=1791528867"]','https://cmsphoto.ww-cdn.com/resizeapi/6caf1c2b120fb08817c9f8d13afa9d63a432f40f/480/',18.2135626,42.6604892,'Tareeq Al Amir Sultan, Abha 62439','','','','https://www.saudi-guide.com/asir-region/i/98048417/sama-park-sma-bark',1,0,'سماء بارك sama park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048394,'asir-region','منتزه رجال','Rijal Alma Park','rijal-alma-park-mntzh-rgal','["أماكن سياحية"]','["sights"]','منتزه رجال منتزه طبيعي في محافظة رجال ألمع قرب القرية التراثية، بمساحات خضراء وأشجار ظليلة تناسب الاستراحة العائلية.','<div class="texte" > <p>منتزه رجال منتزه طبيعي يقع في محافظة رجال ألمع، على مقربة من القرية التراثية الشهيرة. يتميز بمساحاته الخضراء الواسعة وأشجاره الظليلة الكثيفة التي تمنح زواره أجواء منعشة طوال أيام السنة تقريبًا. يُعد محطة مثالية للراحة والاستراحة العائلية قبل أو بعد جولة استكشاف قرية رجال ألمع التراثية القريبة، ويوفر مساحات مناسبة للجلوس والتنزه بين الأشجار.</p> </div>','[]','',18.2150724,42.2777101,'678H+23G, Rijal Alma'' 63455','','','','https://www.saudi-guide.com/asir-region/i/98048394/rijal-alma-park-mntzh-rgal',1,0,'منتزه رجال rijal alma park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048392,'asir-region','منتزه المربع','Al Murabba Park','al-murabba-park-mntzh-almrbaa','["أماكن سياحية"]','["sights"]','منتزه المربع مساحة خضراء واسعة تقع في منطقة المربع بمحافظة أحد رفيدة، وتُعد متنفسًا طبيعيًا شهيرًا للعائلات القادمة من أبها ومحيطها.','<div class="texte" > <p>منتزه المربع مساحة خضراء واسعة تقع في منطقة المربع بمحافظة أحد رفيدة، وتُعد متنفسًا طبيعيًا شهيرًا للعائلات القادمة من أبها ومحيطها. يتميز المنتزه بمساحاته الواسعة الملائمة للتخييم وإقامة الرحلات الجماعية، إلى جانب مناطق مظللة ومرافق بسيطة تخدم الزوار. يشهد إقبالًا كبيرًا خلال عطلات نهاية الأسبوع، وينصح بالحفاظ على نظافة الموقع أثناء الزيارة نظرًا لكثرة الزوار.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048392-68539366.jpg?v=1791528973", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048392-68539369.jpg?v=1791528988"]','https://cmsphoto.ww-cdn.com/resizeapi/3f2725e5d0967338f3248f0b28a42be7af62a30b/480/',18.1062905,42.8686604,'4V49+GF7, Al Qarha'' 62277','','','','https://www.saudi-guide.com/asir-region/i/98048392/al-murabba-park-mntzh-almrbaa',1,0,'منتزه مربع al murabba park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048390,'asir-region','منتزه العقالة','Al Oqalah Park','al-oqalah-park-mntzh-alaakal','["أماكن سياحية"]','["sights"]','منتزه العقالة وجهة طبيعية تقع في بلدة الوديين بمحافظة أحد رفيدة، على بعد نحو 40 كيلومترًا من مدينة أبها.','<div class="texte" > <p>منتزه العقالة وجهة طبيعية تقع في بلدة الوديين بمحافظة أحد رفيدة، على بعد نحو 40 كيلومترًا من مدينة أبها. يتميز الموقع بموقعه الجغرافي المرتفع الذي يتيح للزوار الاستمتاع بمناظر طبيعية بكر وهواء منعش بعيدًا عن صخب المدن. يقصده السكان المحليون بشكل خاص لرعي الأغنام والتنزه العائلي البسيط، ويُعد خيارًا مناسبًا لمن يبحث عن تجربة هادئة بعيدة عن الازدحام السياحي.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048390-68539385.jpg?v=1791529046"]','https://cmsphoto.ww-cdn.com/resizeapi/1ecd3925452b9fdd74d34728a786c63f047b0769/480/',18.0638487,42.7634856,'AGPB7967, 7967, 2623 Abi Tahir, Al Wadiain 62266','','','','https://www.saudi-guide.com/asir-region/i/98048390/al-oqalah-park-mntzh-alaakal',1,0,'منتزه عقاله al oqalah park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048385,'asir-region','منتزه الحبلة','Al Habala Park','al-habala-park-mntzh-alhbl','["أماكن سياحية"]','["sights"]','منتزه الحبلة من أكثر الوجهات إثارة في منطقة عسير، إذ يقع على حافة جبل شاهقة الارتفاع تطل على سلسلة جبال السروات بمنظر بانورامي مذهل يشبه المشي فوق السحاب.','<div class="texte" > <p>منتزه الحبلة من أكثر الوجهات إثارة في منطقة عسير، إذ يقع على حافة جبل شاهقة الارتفاع تطل على سلسلة جبال السروات بمنظر بانورامي مذهل يشبه المشي فوق السحاب. يشتهر الموقع بتلفريكه المطل على الوادي، رغم أن تشغيله يتوقف أحيانًا لأعمال الصيانة، إلى جانب أكواخ ومظلات للجلوس العائلي ومطاعم تقدم المأكولات الشعبية. يحتاج الموقع لوقت طويل نسبيًا للاستمتاع الكامل بمرافقه، ويُنصح بإحضار وجبة خفيفة والاستعداد لأجواء باردة حتى في الصيف.</p> </div>    <div class="texte" > <p>مصدر الصور: ويكيميديا كومنز — تصوير Wajahatmr و Aiman titi (CC BY-SA 3.0)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048385-68537711.jpg?v=1791497859", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048385-68537715.jpg?v=1791497871"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98048385-68537711.jpg?v=1791497860',18.0324739,42.8525222,'2VJ3+X2J, Al Habala 62264','','','','https://www.saudi-guide.com/asir-region/i/98048385/al-habala-park-mntzh-alhbl',1,0,'منتزه حبله al habala park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048379,'asir-region','متحف فاطمة','Al-Qatt Al-Aseeri Museum','al-qatt-al-aseeri-museum-mthf-fatm','["التراث والثقافة"]','["heritage"]','استكشف فن القط العسيري في متحفه المخصص، واستمتع بالنقوش الزاهية التي تحكي قصص التراث، وشارك في ورش تعليمية تحتفي بهذا الفن المدرج في قائمة اليونسكو.','<div class="texte" > <p>متحف فاطمة (متحف القط العسيري) مخصص لفن القط العسيري النسائي، وهو فن الزخرفة الجداري الذي أدرجته اليونسكو ضمن قائمة التراث الثقافي غير المادي للإنسانية. يعرض المتحف نماذج أصلية للنقوش الملونة الزاهية التي كانت النساء العسيريات يزيّن بها جدران وسقوف بيوتهن، إلى جانب شرح تفصيلي لتاريخ هذا الفن ورمزيته. يقدم المتحف ورشًا تفاعلية يتعلم فيها الزوار أساسيات هذا الفن بأنفسهم تحت إشراف فنانات متخصصات، وينصح بالحجز المسبق نظرًا للإقبال الكبير عليه.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048379-68539410.jpg?v=1791529163"]','https://cmsphoto.ww-cdn.com/resizeapi/1d69ceac6393ab1ee9351ce2f2b227c4f297d2e6/480/',18.190758,42.5446941,'King Abdullah Rd, Abha 62523','','','','https://www.saudi-guide.com/asir-region/i/98048379/al-qatt-al-aseeri-museum-mthf-fatm',1,0,'متحف فاطمه al qatt al aseeri museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048375,'asir-region','سكي لين','Ski Line','ski-line-sky-lyn','["أماكن سياحية"]','["sights"]','سكي لين منتزه ترفيهي عائلي يقع في أبها، ويقدم مجموعة متنوعة من الألعاب والأنشطة التي تناسب مختلف الأعمار.','<div class="texte" > <p>سكي لين منتزه ترفيهي عائلي يقع في أبها، ويقدم مجموعة متنوعة من الألعاب والأنشطة التي تناسب مختلف الأعمار. يضم المنتزه سيارات الكارتينج، وألعاب البينتبول، وألعاب الفيديو والواقع الافتراضي، إلى جانب رحلات رافتنج وزحاليق مائية موسمية. يتوفر نظام بطاقات مسبقة الدفع لتسهيل استخدام الألعاب، ويُنصح بزيارته في المساء لتجنب حرارة النهار والاستمتاع بالأجواء المضاءة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048375-68539421.jpg?v=1791529286", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048375-68539425.jpg?v=1791529298"]','https://cmsphoto.ww-cdn.com/resizeapi/b8ca96d066d64ede54644158141eadb8d514c004/480/',18.2385178,42.6834462,'3742, 6426, Abha 62439','','','','https://www.saudi-guide.com/asir-region/i/98048375/ski-line-sky-lyn',1,0,'سكي لين ski line اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98048369,'asir-region','استوديو محي','Muhi Studio','muhi-studio-astodyo-mhy','["التراث والثقافة"]','["heritage"]','استكشف استوديو فنيًا نابضًا بالإبداع، يعرض أعمالًا فنية معاصرة، ويضم متجرًا للتذكارات ومتجرًا لمستلزمات الفن ومراسم فنية ومقهى.','<div class="texte" > <p>استوديو محي مساحة فنية نابضة بالإبداع في أبها، يجمع بين المرسم الفني والمعرض التجاري، حيث يعرض الفنان أعماله التشكيلية المعاصرة المستوحاة من طبيعة عسير وتراثها. يضم الاستوديو متجرًا للتذكارات الفنية ومتجرًا آخر لمستلزمات الرسم والفنون، إضافة إلى ركن مقهى يتيح للزوار الجلوس والاستمتاع بالأجواء الفنية أثناء التجول بين اللوحات. يستقبل الاستوديو الزوار الراغبين في اقتناء قطعة فنية أصيلة أو التعرف على تجربة فنان محلي عن قرب.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048369-68539443.jpg?v=1791529428", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98048369-68539447.jpg?v=1791529441"]','https://cmsphoto.ww-cdn.com/resizeapi/7e0276ae98755d2a3459975d363564e39bdd16fc/480/',18.2217248,42.591662,'Al-Mozvin, Abha 00000','','','','https://www.saudi-guide.com/asir-region/i/98048369/muhi-studio-astodyo-mhy',1,0,'استوديو محي muhi studio تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039894,'asir-region','قصور أبو سراح','Abu Sarrah Palaces','abu-sarrah-palaces-ksor-abo-srah','["التراث والثقافة"]','["heritage"]','مجموعة من القصور التاريخية في أبها، وتعد من أبرز المعالم المعمارية في المنطقة، بُنيت بالحجر الطبيعي وتضم ممرات ومجالس قديمة.','<div class="texte" > <p>قصور أبو سراح واحدة من أبرز المعالم المعمارية التاريخية في أبها، وتتكون من ثلاثة قصور رئيسية بناها الشيخ أبو سراح الذي عُرف بثرائه ونفوذه في المنطقة، ويُروى أنه كان له أكثر من 45 زوجة، ويظهر ذلك في تعدد الأجنحة والغرف داخل القصور. بُنيت القصور بالحجر الطبيعي والطين على الطراز العسيري التقليدي، وتضم اليوم متاحف داخلية تعرض الأزياء والأدوات القديمة، إلى جانب محال لبيع التذكارات والحرف اليدوية. يقدم مرشدون محليون جولات تعريفية تشرح تفاصيل حياة تلك الحقبة وقصص القصر.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039894-68539454.jpg?v=1791529503", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039894-68539456.jpg?v=1791529512"]','https://cmsphoto.ww-cdn.com/resizeapi/28c673a412050858fef985fff02df0e4a88467d4/480/',18.2206039,42.427699,'Al Soudah Rd, Al Azizah, Abha 62517','','','','https://www.saudi-guide.com/asir-region/i/98039894/abu-sarrah-palaces-ksor-abo-srah',1,0,'قصور ابو سراح abu sarrah palaces تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039892,'asir-region','منتزه الأمير سلطان','Prince Sultan Park','prince-sultan-park-mntzh-alamyr-sltan','["أماكن سياحية"]','["sights"]','منتزه واسع ومتنفس طبيعي للعائلات، يضم مساحات خضراء وملاعب ومسارات مشي وجلسات مظللة، ويُعد من أبرز وجهات التنزه في خميس مشيط.','<div class="texte" > <p>منتزه الأمير سلطان في خميس مشيط من أبرز الوجهات العائلية في محافظة خميس مشيط، ويوفر مساحات خضراء واسعة تحيط بها الأشجار الظليلة. يضم المنتزه ملاعب أطفال ومسارات مخصصة للمشي والجري، إضافة إلى جلسات مظللة مجهزة تناسب التجمعات العائلية الكبيرة. يشهد المنتزه إقبالًا كبيرًا في المساء وأيام العطلات، ويُعد خيارًا مثاليًا للنزهات الأسبوعية وممارسة الرياضة في أجواء عسير المعتدلة.</p> </div>','[]','',18.2681965,42.806296,'Khamis Mushait 62442','','','','https://www.saudi-guide.com/asir-region/i/98039892/prince-sultan-park-mntzh-alamyr-sltan',1,0,'منتزه امير سلطان prince sultan park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039891,'asir-region','مسار القرون','Aqabat Al Quroon Trail','aqabat-al-quroon-trail-msar-alkron','["أماكن سياحية"]','["sights"]','تجربة مغامرة تبدأ من السودة وتنتهي في رجال ألمع عبر مسار القرون، حيث ستأخذ الزائر للإطلالات الساحرة واستكشاف الطبيعة الخلابة لهذا المسار الجبلي.','<div class="texte" > <p>مسار القرون (عقبة القرون) هو طريق تجاري قديم يربط بين منطقة السودة وقرية رجال ألمع التراثية، ويُعد من أشهر مسارات المشي الجبلي في عسير. يتميز المسار بصعوبته النسبية في بدايته، حيث تنحدر الطريق بشكل حاد وسط الصخور، قبل أن تتحول تدريجيًا إلى سهولة أكبر، وتظهر على طول الطريق آثار مبانٍ حجرية قديمة تعود لأزمنة التجارة القديمة. تستغرق الرحلة الكاملة نحو ساعتين إلى ثلاث ساعات مشيًا، وتنتهي عند قرية رجال ألمع التاريخية، ما يجعلها تجربة تجمع بين المغامرة والتاريخ.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039891-68539471.jpg?v=1791529649", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039891-68539473.jpg?v=1791529659"]','https://cmsphoto.ww-cdn.com/resizeapi/de9ecaad04c5999f6a4f15faf1943066b9f0068b/480/',18.2598614,42.365827,'Al Soudah, Abha 62533','','','','https://www.saudi-guide.com/asir-region/i/98039891/aqabat-al-quroon-trail-msar-alkron',1,0,'مسار قرون aqabat al quroon trail اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039889,'asir-region','جبل منعاء','Jabal Manaa','jabal-manaa-gbl-mnaaa','["أماكن سياحية"]','["sights"]','جبل منعاء أحد أبرز المرتفعات الجبلية في محافظة تنومة بمنطقة عسير، ويشتهر بتضاريسه الوعرة وقممه الصخرية الفريدة.','<div class="texte" > <p>جبل منعاء أحد أبرز المرتفعات الجبلية في محافظة تنومة بمنطقة عسير، ويشتهر بتضاريسه الوعرة وقممه الصخرية الفريدة. يوفر الجبل إطلالات بانورامية ساحرة على الوديان والقرى المحيطة، خصوصًا عند الغروب أو في أوقات تشكّل الضباب. يُعد وجهة مفضلة لهواة التصوير والتخييم والمشي لمسافات طويلة، وينصح بارتداء أحذية مناسبة للتنقل بين الصخور نظرًا لوعورة بعض المسارات.</p> </div>','[]','',18.9608441,42.1730241,'Tanomah, Saudi Arabia','','','','https://www.saudi-guide.com/asir-region/i/98039889/jabal-manaa-gbl-mnaaa',1,0,'جبل منعاء jabal manaa اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039888,'asir-region','مركز هوساك للمغامرات','Husaak Adventures','husaak-adventures-mrkz-hosak-llmghamrat','["أماكن سياحية"]','["sights"]','مركز مغامرات في جبال طبب بتنومة يقدم تجارب متنوعة تشمل الباغي والهايكنج وركوب الخيل والدراجات الجبلية والتخييم والجرافيتي كارت وسط طبيعة عسير الخلابة.','<div class="texte" > <p>يقع مركز هوساك للمغامرات في قلب جبال طبب بمحافظة تنومة، ويُعد من أبرز وجهات السياحة المغامرة في منطقة عسير. يقدم المركز باقة متكاملة من التجارب تشمل ركوب عربات الباغي على التضاريس الوعرة، ومسارات الهايكنج والدراجات الجبلية، وركوب الخيل، والتخييم الليلي وسط الطبيعة، إضافة إلى مضمار الجرافيتي كارت المليء بالإثارة. يوفر المركز أكواخًا مستقلة للإقامة، ومطعمًا وكافيه يقدمان وجبات مميزة، ويحرص مرشدون محترفون على سلامة الزوار في جميع الأنشطة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039888-68539484.jpg?v=1791529763", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039888-68539488.jpg?v=1791529779"]','https://cmsphoto.ww-cdn.com/resizeapi/7a1cdd31f42200cf9d462b53269b1fd450515490/480/',18.8973971,42.1727974,'Tanomah 62796','','','','https://www.saudi-guide.com/asir-region/i/98039888/husaak-adventures-mrkz-hosak-llmghamrat',1,0,'مركز هوساك للمغامرات husaak adventures اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039887,'asir-region','مزرعة أعناب','The Vineyard','the-vineyard-mzraa-aaanab','["أماكن سياحية"]','["sights"]','فعالية ريفية تفاعلية تتيح للزوار زراعة الشتلات وقطف الفواكه وتذوق العصائر وإعداد خبز التنور والتصوير بالزي التراثي.','<div class="texte" > <p>تقع مزرعة أعناب (The Vineyard) على طريق أبها التاريخي، وتُعد من أشهر الوجهات الزراعية السياحية في عسير. تضم المزرعة بساتين متنوعة من العنب والرمان والتوت، إلى جانب حديقة صغيرة للحيوانات تشمل الخيول، ما يجعلها مناسبة للعائلات والأطفال. يمكن للزوار قطف الفواكه الطازجة وتذوق العصائر الطبيعية، والاستمتاع بمقاهٍ ومطاعم داخل المزرعة بأجواء ريفية هادئة. رسوم الدخول رمزية، وأفضل وقت للزيارة هو فترة الصباح أو المساء تجنبًا للازدحام.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039887-68539501.jpg?v=1791529838", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039887-68539505.jpg?v=1791529857"]','https://cmsphoto.ww-cdn.com/resizeapi/ef4a484857d6d1d2ddcefd54891e30134b2ff3e6/480/',18.3576189,42.4994094,'ABWA6659, Shouhet 62598','','','','https://www.saudi-guide.com/asir-region/i/98039887/the-vineyard-mzraa-aaanab',1,0,'مزرعه اعناب the vineyard اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039730,'jeddah','باتل كارت','Battle Kart Jeddah','battle-kart-jeddah-batl-kart','["سياحة وترفيه"]','["sights"]','باتل كارت جدة تمزج بين الكارتينج الكهربائي والواقع المعزز لتحول السباق إلى تجربة ألعاب تفاعلية وغامرة.','<div class="texte" > <p>باتل كارت جدة تمزج بين الكارتينج الكهربائي والواقع المعزز، لتحول السباق التقليدي إلى تجربة ألعاب تفاعلية وغامرة تجمع بين السرعة والتحدي الرقمي.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039730-68551499.jpg?v=1791633448", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039730-68551500.jpg?v=1791633460"]','https://cmsphoto.ww-cdn.com/resizeapi/8087a99bdfdf484ed29545982d739b7da1e6ecb4/480/',21.5069888,39.2182101,'St, Prince Majid Rd, Al Fayha, Jeddah 22245','','','','https://www.saudi-guide.com/jeddah/i/98039730/battle-kart-jeddah-batl-kart',1,0,'باتل كارت battle kart jeddah سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039728,'jeddah','جولات السيارات المائية في مرسى اللؤلؤة','Pearl Marina Jet Ski Tours','pearl-marina-jet-ski-tours-golat-alsyarat-almayy-fy-mrsa-allolo','["سياحة وترفيه"]','["sights"]','جولات السيارات المائية في مرسى اللؤلؤة (بيرل مارينا) تقدم مرحًا غير محدود على مياه البحر الأحمر شمال جدة.','<div class="texte" > <p>جولات السيارات المائية في مرسى اللؤلؤة (بيرل مارينا) تقدم مرحًا غير محدود على مياه البحر الأحمر شمال جدة، وتُعد إحدى أبرز الأنشطة البحرية للمغامرين الباحثين عن الإثارة والسرعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039728-68540389.jpg?v=1791533485", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039728-68540407.jpg?v=1791533493"]','https://cmsphoto.ww-cdn.com/resizeapi/ef861e9f1efc3c072d699a93727299adf217a312/480/',21.7329907,39.1178154,'Abhur Al Junoobiyah, Jeddah 23813','','','','https://www.saudi-guide.com/jeddah/i/98039728/pearl-marina-jet-ski-tours-golat-alsyarat-almayy-fy-mrsa-allolo',1,0,'جولات سيارات مائيه في مرسي لؤلؤه pearl marina jet ski tours سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039727,'jeddah','شاطئ شيدز','Shades Beach','shades-beach-shaty-shydz','["سياحة وترفيه"]','["sights"]','شاطئ شيدز وجهتك الفاخرة للاسترخاء داخل درة العروس بجدة، يوفر مياهً هادئة وأجواء بحرية خلابة تناسب من يبحثون عن يوم هروب هادئ من صخب المدينة.','<div class="texte" > <p>شاطئ شيدز وجهتك الفاخرة للاسترخاء داخل درة العروس بجدة، يوفر مياهً هادئة وأجواء بحرية خلابة تناسب من يبحثون عن يوم هروب هادئ من صخب المدينة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039727-68539524.jpg?v=1791530024", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039727-68539526.jpg?v=1791530031"]','https://cmsphoto.ww-cdn.com/resizeapi/134d237369143933d594c8130789d3d5b5b91e2a/480/',21.9398389,38.9544395,'Durrat Alarous, Jeddah 23851','','','','https://www.saudi-guide.com/jeddah/i/98039727/shades-beach-shaty-shydz',1,0,'شاطئ شيدز shades beach سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039726,'jeddah','درة العروس','Durrat Al Arous','durrat-al-arous-dr-alaaros','["سياحة وترفيه"]','["sights"]','درة العروس منتجع شاطئي متكامل شمال جدة، يضم فللاً خاصة وشواطئ شبه خاصة وأنشطة بحرية متنوعة، ووجهة مفضلة للعائلات قرب البحر الأحمر.','<div class="texte" > <p>درة العروس منتجع شاطئي متكامل شمال جدة، يضم فللًا خاصة وشواطئ شبه خاصة وأنشطة بحرية متنوعة، ويُعد وجهة مفضلة للعائلات الراغبة في قضاء إجازة قصيرة قرب البحر الأحمر.</p> </div>','[]','',21.940729,38.9555196,'Durrat Al Arous, Dahaban 21441','','','','https://www.saudi-guide.com/jeddah/i/98039726/durrat-al-arous-dr-alaaros',1,0,'دره عروس durrat al arous سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039725,'jeddah','نادي كونا للرياضات البحرية','Kona Watersports Club','kona-watersports-club-nady-kona-llryadat-albhry','["سياحة وترفيه"]','["sights"]','نادي كونا للرياضات البحرية على شاطئ الدرة شمال جدة، يُعد الوجهة المثالية لعشاق المغامرات الساحلية والرياضات المائية.','<div class="texte" > <p>نادي كونا للرياضات البحرية على شاطئ الدرة شمال جدة، يُعد الوجهة المثالية لعشاق المغامرات الساحلية والرياضات المائية، ويوفر أجواء منظمة ونظيفة تناسب أيام السيدات المخصصة وزيارات العائلات.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039725-68539540.jpg?v=1791530129", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039725-68539542.jpg?v=1791530140"]','https://cmsphoto.ww-cdn.com/resizeapi/3791d6c52c3db7b6d78dc29c76518241a64dbec0/480/',21.9649385,38.9623883,'Al Laqoun, Jeddah 12341','','','','https://www.saudi-guide.com/jeddah/i/98039725/kona-watersports-club-nady-kona-llryadat-albhry',1,0,'نادي كونا للرياضات بحريه kona watersports club سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039724,'jeddah','أميزون','Amazon Beach','amazon-beach-amyzon','["سياحة وترفيه"]','["sights"]','أميزون شاطئ نسائي خاص شمال جدة، يقدم موقعًا فاخرًا وفعاليات حصرية وتجارب استرخاء مميزة، في أجواء هادئة توفر خصوصية كاملة للزائرات.','<div class="texte" > <p>أميزون شاطئ نسائي خاص شمال جدة، يقدم موقعًا فاخرًا وفعاليات حصرية وتجارب استرخاء مميزة، في أجواء هادئة توفر خصوصية كاملة للزائرات.</p> </div>','[]','',21.7572852,39.0555146,'Prince Abdullah AlFaisal Rd, Al Lulu, Jeddah 23821','','','','https://www.saudi-guide.com/jeddah/i/98039724/amazon-beach-amyzon',1,0,'اميزون amazon beach سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039723,'jeddah','منتجع نارسيس أبحر','Narcissus Resort Obhur','narcissus-resort-obhur-mntgaa-narsys-abhr','["سياحة وترفيه"]','["sights"]','منتجع نارسيس أبحر منتجع شاطئي فاخر شمال جدة، يوفر شاطئًا نسائيًا خاصًا ومنطقة للأطفال وشاطئًا مختلطًا منفصلًا.','<div class="texte" > <p>منتجع نارسيس أبحر منتجع شاطئي فاخر شمال جدة، يوفر شاطئًا نسائيًا خاصًا ومنطقة للأطفال وشاطئًا مختلطًا منفصلًا، مع اهتمام كبير بخصوصية الضيوف ومطاعم متنوعة تقدم تجربة طعام مميزة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039723-68539568.jpg?v=1791530245", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039723-68539572.jpg?v=1791530262"]','https://cmsphoto.ww-cdn.com/resizeapi/acb1794a85fbdc3aa407b5d4249aaf77ff3b32d8/480/',21.7225523,39.0805927,'Prince Abdullah AlFiasal St, Obhur Al-Shamaliyah, Jeddah 23811','','','','https://www.saudi-guide.com/jeddah/i/98039723/narcissus-resort-obhur-mntgaa-narsys-abhr',1,0,'منتجع نارسيس ابحر narcissus resort obhur سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039722,'jeddah','منتجع سيلفر ساندز بيتش','Silver Sands Beach Resort','silver-sands-beach-resort-mntgaa-sylfr-sandz-bytsh','["سياحة وترفيه"]','["sights"]','منتجع سيلفر ساندز بيتش يقع شمال جدة، ويوفر مياهً صافية وشاطئًا خاصًا وأنشطة بحرية متنوعة، مع تنظيم يحدّ من أعداد الزوار للحفاظ على أجواء هادئة.','<div class="texte" > <p>منتجع سيلفر ساندز بيتش يقع شمال جدة، ويوفر مياهً صافية وشاطئًا خاصًا وأنشطة بحرية متنوعة، مع تنظيم يحدّ من أعداد الزوار للحفاظ على أجواء هادئة، إضافة إلى وجبات معدّة بعناية للاستمتاع بيوم شاطئي متكامل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039722-68539591.jpg?v=1791530317", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039722-68539596.jpg?v=1791530329"]','https://cmsphoto.ww-cdn.com/resizeapi/fdda376688244ba158a868ebb37a83b03629d550/480/',21.7736195,39.0542329,'Prince Abdullah AlFiasal St, Al Lulu, Jeddah 23821','','','','https://www.saudi-guide.com/jeddah/i/98039722/silver-sands-beach-resort-mntgaa-sylfr-sandz-bytsh',1,0,'منتجع سيلفر ساندز بيتش silver sands beach resort سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039721,'jeddah','مغامرات 17SIXTY البحر الأحمر','17SIXTY Red Sea Adventures','17sixty-red-sea-adventures-mghamrat-17sixty-albhr-alahmr','["سياحة وترفيه"]','["sights"]','17SIXTY وجهة مغامرات بحرية متكاملة في جدة، تقدم رحلات غوص وغطس وجولات جت سكي وباراسيلينج وتجربة قفص القرش وركوب القوارب المطاطية على امتداد ساحل البحر الأحمر.','<div class="texte" > <p>17SIXTY وجهة مغامرات بحرية متكاملة في جدة، تقدم رحلات غوص وغطس وجولات جت سكي وباراسيلينج وتجربة قفص القرش وركوب القوارب المطاطية على امتداد ساحل البحر الأحمر، مع مدربين محترفين يناسبون المبتدئين والمحترفين.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039721-68540586.jpg?v=1791533639"]','https://cmsphoto.ww-cdn.com/resizeapi/613b3b4588ff7d18ef5fde0f3e76c349b03e2fbb/480/',21.941041,38.9501754,'Durrat Alarous, Jeddah 23851','','','','https://www.saudi-guide.com/jeddah/i/98039721/17sixty-red-sea-adventures-mghamrat-17sixty-albhr-alahmr',1,0,'مغامرات 17sixty بحر احمر 17sixty red sea adventures سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039702,'jeddah','جوفالي','Guvali','guvali-gofaly','["سياحة وترفيه"]','["sights"]','يقدم جوفالي تجربة ترفيهية فاخرة تجمع الموسيقى الحية والعروض البصرية والأجواء الراقية والتواصل الاجتماعي في موقع مميز.','<div class="texte" > <p>جوفالي قاعة فعاليات وترفيه ليلي في جدة، تقدم تجربة موسيقية متنوعة وعروضًا بصرية ضمن أجواء اجتماعية راقية، وتستضيف فعاليات خاصة ومناسبات كبرى على مدار العام.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039702-68539614.jpg?v=1791530451"]','https://cmsphoto.ww-cdn.com/resizeapi/93dc216486c9458040f126331c9d918d5655f881/480/',21.9303066,39.2599149,'Al Ghulah, Jeddah 23887','','','','https://www.saudi-guide.com/jeddah/i/98039702/guvali-gofaly',1,0,'جوفالي guvali سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039701,'jeddah','غرف الهروب ذا إسكيب هوتيل','The Escape Hotel','the-escape-hotel-ghrf-alhrob-tha-askyb-hotyl','["سياحة وترفيه"]','["sights"]','ذا إسكيب هوتيل في جدة وجهة غرف هروب مرعبة تضم عدة غرف بموضوعات مختلفة مثل فرانكنشتاين والمومياء والزومبي.','<div class="texte" > <p>The Escape Hotel وجهة غرف هروب مرعبة في جدة، تضم عدة غرف بموضوعات مختلفة مثل فرانكنشتاين والمومياء والزومبي، تتطلب حل ألغاز إبداعية للخروج قبل انتهاء الوقت المحدد، ضمن أجواء تمثيلية غامرة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039701-68539627.jpg?v=1791530507", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039701-68539629.jpg?v=1791530518"]','https://cmsphoto.ww-cdn.com/resizeapi/6623e98fb53b18bc71fa7cd02437a8af6a368b96/480/',21.6406241,39.1327875,'Safia Bint Abdulmutalib St, Al Mohammadiyyah, Jeddah 23621','','','','https://www.saudi-guide.com/jeddah/i/98039701/the-escape-hotel-ghrf-alhrob-tha-askyb-hotyl',1,0,'غرف هروب ذا اسكيب هوتيل the escape hotel سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039700,'jeddah','كارتينج JCC','JCC Karting','jcc-karting-kartyng-jcc','["سياحة وترفيه"]','["sights"]','مضمار JCC للكارتينج في جدة يتيح لعشاق السباقات منافسات على مضمار مخصص لسيارات الكارت، ويسجل زمن كل لفة ويعرضه على شاشة كبيرة.','<div class="texte" > <p>مضمار JCC للكارتينج في جدة يتيح لعشاق السباقات الاستمتاع بمنافسات على مضمار مخصص لسيارات الكارت، وهو المضمار الوحيد في جدة الذي يسجل زمن كل لفة ويعرضها على شاشة كبيرة لمتابعة الأداء.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039700-68539637.jpg?v=1791530572", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039700-68539642.jpg?v=1791530581"]','https://cmsphoto.ww-cdn.com/resizeapi/dc732729a61eb6ac17be821a4be66f717a394d0c/480/',21.6207695,39.1152677,'King Abdulaziz Rd, Al Shatie District, Jeddah 23611','','','','https://www.saudi-guide.com/jeddah/i/98039700/jcc-karting-kartyng-jcc',1,0,'كارتينج jcc jcc karting سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039681,'jeddah','بوست ألعاب الترفيه والأركيد','Boost','boost-bost-alaaab-altrfyh-oalarkyd','["سياحة وترفيه"]','["sights"]','بوست من أكبر مراكز الترفيه في جدة، يضم أكثر من 100 لعبة تشمل الواقع الافتراضي والألعاب الإلكترونية الكلاسيكية والمحاكاة.','<div class="texte" > <p>بوست أحد أكبر مراكز الترفيه في جدة، يضم أكثر من 100 لعبة تشمل الواقع الافتراضي والألعاب الإلكترونية الكلاسيكية والمحاكاة، إضافة إلى صالة سينما وأنشطة ليزر تاغ تناسب جميع الأعمار.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039681-68539653.jpg?v=1791530634", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039681-68539656.jpg?v=1791530647"]','https://cmsphoto.ww-cdn.com/resizeapi/911add1d32dfee8a54fe4a66111da1392d975621/480/',21.5844361,39.1293152,'Ahmad Al Attas, Jeddah 23425','','','','https://www.saudi-guide.com/jeddah/i/98039681/boost-bost-alaaab-altrfyh-oalarkyd',1,0,'بوست عاب ترفيه والاركيد boost سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98039679,'jeddah','كيدزانيا','KidZania Jeddah','kidzania-jeddah-kydzanya','["سياحة وترفيه"]','["sights"]','كيدزانيا جدة مركز ترفيهي وتعليمي عالمي للأطفال داخل مول العرب، يتيح لهم تجربة تمثيل أدوار في مهن متنوعة كالطب والطيران والإطفاء.','<div class="texte" > <p>كيدزانيا جدة مركز ترفيهي وتعليمي عالمي للأطفال داخل مول العرب، يتيح لهم تجربة تمثيل أدوار في مهن متنوعة كالطب والطيران والإطفاء، بهدف تعزيز التعلم والإبداع من خلال اللعب التفاعلي في بيئة آمنة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039679-68539680.jpg?v=1791530741", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98039679-68539688.jpg?v=1791530760"]','https://cmsphoto.ww-cdn.com/resizeapi/441db033cbb6d29ea7a52a7f968fd438e24fc665/480/',21.633206,39.157372,'Nuzhah District, Mall of Arabia, Jeddah 23532','','','','https://www.saudi-guide.com/jeddah/i/98039679/kidzania-jeddah-kydzanya',1,0,'كيدزانيا kidzania jeddah سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073218,'albaha','شلال الغدير','Al Ghadeer Waterfall','al-ghadeer-waterfall-shlal-alghdyr','["الشلالات والأودية"]','["nature"]','شلال الغدير من أجمل شلالات منطقة الباحة، يقع في منطقة نائية خضراء ويُصل إليه عبر طريق ترابي، ويناسب محبي المغامرة من الشباب.','<div class="texte" > <p>يوصف شلال الغدير بأنه من أجمل الشلالات في منطقة الباحة، ويقع في منطقة نائية وسط أجواء خضراء ساحرة. يستلزم الوصول إليه قيادة لمسافة طويلة نسبياً على طريق ترابي، ويناسب زيارته الشباب المحبين للمغامرة أكثر من العائلات نظراً لبعد الموقع وقلة الخدمات المتوفرة فيه.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073218-68538074.jpg?v=1791503191"]','https://cmsphoto.ww-cdn.com/resizeapi/6ab15f2fd93047a079f18534d6786cc66f4c1039/480/',20.1239725,41.4827777,'مدينة الباحة 65726','','https://baha.gov.sa/ar/Albums/ImageDetails/475','','https://www.saudi-guide.com/albaha/i/98073218/al-ghadeer-waterfall-shlal-alghdyr',1,0,'شلال غدير al ghadeer waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073217,'albaha','شلال الحمده','Al Hamdah Waterfall','al-hamdah-waterfall-shlal-alhmdh','["الشلالات والأودية"]','["nature"]','شلال الحمده في الباحة شلال صغير يحيط به اخضرار كثيف وجدول مياه هادئ، بمساحات واسعة للجلوس العائلي ومناظر قروية جميلة.','<div class="texte" > <p>يُعد شلال الحمده من المشاهد النادرة في المملكة بما يحيطه من اخضرار كثيف وشلاله الصغير، إذ يبعث صوت المياه المتدفقة عبر الجدول وإلى الوادي شعوراً بالهدوء. يتميز المكان بجمال منظره وتوفر مساحات واسعة للجلوس وقضاء وقت ممتع مع العائلة، ويمكن للأطفال اللعب بالماء ومشاهدة مناظر القرية الجميلة بما فيها من بط وصغاره تسبح عبر الجدول.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073217-68299691.jpg?v=1789816460"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073217-68299691.jpg?v=1789816461',20.0241089,41.4943867,'النزهة، مدينة الباحة 65711','','https://baha.gov.sa/ar/Albums/ImageDetails/404','','https://www.saudi-guide.com/albaha/i/98073217/al-hamdah-waterfall-shlal-alhmdh',1,0,'شلال حمده al hamdah waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073216,'albaha','وادي تربة زهران','Wadi Turabah Zahran','wadi-turabah-zahran-oady-trb-zhran','["الشلالات والأودية"]','["nature"]','وادي تربة زهران في محافظة المندق من أكبر أودية الجزيرة العربية بطول يتجاوز 330 كم، معلم جغرافي بارز يجذب محبي الطبيعة.','<div class="texte" > <p>يعتبر وادي تربة زهران أحد أكبر أودية الجزيرة العربية، إذ يبلغ طوله أكثر من 330 كم، ما يجعله معلماً جغرافياً بارزاً في محافظة المندق يجذب محبي الطبيعة والمساحات الشاسعة.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073216-68299711.jpg?v=1789816641"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073216-68299711.jpg?v=1789816642',20.2067307,41.2836832,'المندق 65756','','https://baha.gov.sa/ar/Albums/ImageDetails/415','','https://www.saudi-guide.com/albaha/i/98073216/wadi-turabah-zahran-oady-trb-zhran',1,0,'وادي تربه زهران wadi turabah zahran شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073215,'albaha','وادي القدحة بمسير','Wadi Al Qadhah','wadi-al-qadhah-oady-alkdh-bmsyr','["الشلالات والأودية"]','["nature"]','وادي القدحة في المندق من أشهر أودية الباحة، تحيط به بساتين الرمان وتجري مياهه معظم العام حتى سد مذحج، وجهة مثالية للتنزه.','<div class="texte" > <p>من أشهر وديان منطقة الباحة في محافظة المندق، بالإضافة إلى موقعه المتميز. يحيط بالوادي بساتين من أشجار الرمان الشهيرة بزراعتها في المنطقة، ويتميز بمياهه المتدفقة على مدار العام حتى تصل إلى سد مذحج الشهير، ويُعد من أفضل الأماكن لقضاء أوقات ممتعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073215-68538080.jpg?v=1791503256"]','https://cmsphoto.ww-cdn.com/resizeapi/20bab51e815b80c22e89bf96c0065c88c9b51839/480/',20.2089622,41.2775636,'دوس، محافظة المندق 65757','+966506560252','https://baha.gov.sa/ar/Albums/ImageDetails/474','','https://www.saudi-guide.com/albaha/i/98073215/wadi-al-qadhah-oady-alkdh-bmsyr',1,0,'وادي قدحه بمسير wadi al qadhah شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073214,'albaha','وادي ثراد','Wadi Tharad','wadi-tharad-oady-thrad','["الشلالات والأودية"]','["nature"]','وادي ثراد من أشهر أودية محافظة العقيق بمنطقة الباحة، تتدفق مياهه في فصل الربيع وسط أجواء طبيعية خلابة تجذب محبي المناظر.','<div class="texte" > <p>من أشهر وديان منطقة الباحة في محافظة العقيق، بالإضافة إلى موقعه الجاذب. يتميز الوادي بمياهه المتدفقة في فصل الربيع وسط أجواء طبيعية خلابة، ما يجعله وجهة محببة لمحبي المناظر الطبيعية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073214-68538081.jpg?v=1791503285"]','https://cmsphoto.ww-cdn.com/resizeapi/cc91497a14c939289cfac5480dbecb0b74eb37ec/480/',20.2175812,41.7995218,'وادي ثراد، محافظة العقيق','','https://baha.gov.sa/ar/Albums/ImageDetails/452','','https://www.saudi-guide.com/albaha/i/98073214/wadi-tharad-oady-thrad',1,0,'وادي ثراد wadi tharad شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073211,'albaha','منتزه الشلال','Al Shallal Park','al-shallal-park-mntzh-alshlal','["أماكن سياحية"]','["sights"]','منتزه الشلال في محافظة بني حسن بين أحضان الطبيعة، يضم جلسات مظللة وممرات مشاة وألعاب أطفال وشلالات وبحيرات تنبع من أعلى الجبل.','<div class="texte" > <p>يتوسط المنتزه موقعاً متميزاً وسط جمال الطبيعة في محافظة بني حسن، ويضم مجموعة من الخدمات والمرافق اللازمة لخدمة الزوار، كما يحتوي على جلسات مظللة وممرات للمشاة وألعاب أطفال وأكشاك تموينات، ويتميز بشلالات وبحيرات مائية طبيعية واصطناعية تنبع من أعلى الجبل. يعمل يومياً من 7 صباحاً حتى 2 فجراً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073211-68538083.jpg?v=1791503353"]','https://cmsphoto.ww-cdn.com/resizeapi/018b6cf0b6b3ab78ea1c968a000ae5332f50e3b0/480/',20.0607394,41.3900213,'قرية خيرة، الباحة 65735','','','','https://www.saudi-guide.com/albaha/i/98073211/al-shallal-park-mntzh-alshlal',1,0,'منتزه شلال al shallal park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073210,'albaha','غابة خيرة','','ghab-khyr','["أماكن سياحية"]','["sights"]','غابة خيرة من أجمل المناطق السياحية في الباحة، تضم غطاءً نباتياً كثيفاً وشلالات وبرك مياه بين تشكيلات صخرية ومناطق للتخييم.','<div class="texte" > <p>واحدة من أجمل المناطق السياحية في منطقة الباحة ودائماً ما تفتح أبوابها لعشاق الطبيعة والمناظر الخلابة لما تحتويه من غطاء نباتي وأشجار كثيفة وشلالات متدفقة وبرك مياه محاطة بتشكيلات صخرية خلابة، بالإضافة إلى مناطق تخييم وتجمع بين جمال الأشجار المعمرة كالعرعر والزيتون. تعمل طوال اليوم، وتضم أكشاك تموينات.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073210-68538084.jpg?v=1791503396"]','https://cmsphoto.ww-cdn.com/resizeapi/f73349501293528ca6b5c6487068ccd7989e86ed/480/',20.0689767,41.3854937,'طريق غابة خيرة، الباحة 65735','','','','https://www.saudi-guide.com/albaha/i/98073210/ghab-khyr',1,0,'غابه خيره اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073209,'albaha','منتزه الخلب','','mntzh-alkhlb','["أماكن سياحية"]','["sights"]','منتزه الخلب وجهة طبيعية بمنطقة الباحة، توفر أجواء استراحة ومرافق ترفيهية للزوار.','<div class="texte" > <p>يقع منتزه الخلب على ربوة عالية بإطلالات واسعة على محافظة المندق والأودية والجبال المجاورة، كما يحتوي على تقسيمات من المسطحات الخضراء بالإضافة إلى ممرات للمشي وشلالات ومجرى للمياه بمنتصف المنتزه ويضم كهوفاً، مما يضفي جمالية ساحرة وتجربة فريدة. يعمل طوال اليوم، وتضم مقاهي ومطعم البرج.</p> </div>','[]','',20.179832,41.2646203,'محافظة المندق 65585','','','','https://www.saudi-guide.com/albaha/i/98073209/mntzh-alkhlb',1,0,'منتزه خلب اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073202,'albaha','حديقة الأمير سلطان بن سلمان','Prince Sultan bin Salman Park','prince-sultan-bin-salman-park-hdyk-alamyr-sltan-bn-slman','["أماكن سياحية"]','["sights"]','حديقة الأمير سلطان بن سلمان في الباحة من أفضل منتزهات المنطقة بتصميم فريد ومرافق متنوعة، وإطلالة رائعة لمشاهدة شروق الشمس.','<div class="texte" > <p>تعد حديقة الأمير سلطان بن سلمان من أفضل المنتزهات في الباحة، وتتميز بتصميم فريد ومرافق وخدمات متنوعة وأنشطة مختلفة تتيح قضاء وقت ممتع برفقة العائلة، مع إطلالة رائعة تجعلها من أفضل الأماكن لمشاهدة شروق الشمس، وتضم أكشاك تموينات للزوار.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073202-68538085.jpg?v=1791503476"]','https://cmsphoto.ww-cdn.com/resizeapi/d3982af776e80b7443d79ed0a7dbe421852917ef/480/',19.9810111,41.4657008,'الروضة، الباحة 65531','','https://baha.gov.sa/ar/Albums/ImageDetails/457','','https://www.saudi-guide.com/albaha/i/98073202/prince-sultan-bin-salman-park-hdyk-alamyr-sltan-bn-slman',1,0,'حديقه امير سلطان بن سلمان prince sultan bin salman park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073107,'taif','مقهى بولس','Paul Cafe','paul-cafe-mkha-bols','["مقاهي"]','["cafe"]','مقهى بولس داخل ذا بارك مول بالطائف يقدم قهوة مختصة وحلويات شهية بأجواء هادئة، ويشتهر بأطباقه المقدمة بعناية وخدمته الودودة.','<div class="texte" > <p>مقهى بولس كافيه مقهى يقدم قهوة مختصة بأجواء هادئة، بجانب حلويات شهية داخل ذا بارك مول. يشتهر بأطباقه المقدَّمة بعناية وتقديم أنيق، ويحظى بخدمة ودودة من الطاقم يشيد بها الزوار. يعمل يوميًا تقريبًا من 8 صباحًا حتى منتصف الليل، وللتواصل: 0127442088.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073107-68551420.jpg?v=1791632714"]','https://cmsphoto.ww-cdn.com/resizeapi/0c650c79729430979538e0baa920d79b77fa06d3/480/',21.4293205,40.4991869,'ذا بارك مول، الجوهرة، الطائف 26575','','','','https://www.saudi-guide.com/taif/i/98073107/paul-cafe-mkha-bols',1,0,'مقهي بولس paul cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073082,'taif','استون كوفي','Aston Coffee','aston-coffee-aston-kofy','["مقاهي"]','["cafe"]','استون كوفي في الطائف مقهى عصري داخل حديقة تراثية بمبانٍ حجرية قديمة، يقدم القهوة المختصة ويضم ألعاباً للأطفال واسطبلاً للخيول.','<div class="texte" > <p>مقهى استون كوفي يجمع هذا المقهى العصري بين القهوة المختصة والأجواء المستوحاة من روح المدينة، ويقع داخل حديقة تراثية ذات مبانٍ حجرية قديمة تمنح المكان طابعًا يشبه العودة بالزمن للوراء. يضم إلى جانب المقهى بعض الألعاب للأطفال واسطبلًا للخيول، ما يجعله وجهة عائلية ممتعة تجمع بين التاريخ والطبيعة. يعمل يوميًا تقريبًا من 4 عصرًا حتى منتصف الليل أو 12:30 فجرًا (ويوم الجمعة على مدار 24 ساعة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073082-68538090.jpg?v=1791503628", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073082-68538091.jpg?v=1791503641"]','https://cmsphoto.ww-cdn.com/resizeapi/597a5137b32c347c422217f0805aa2e38c8ce700/480/',21.1153125,40.3655625,'الطائف 26762','','','','https://www.saudi-guide.com/taif/i/98073082/aston-coffee-aston-kofy',1,0,'استون كوفي aston coffee مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073079,'taif','كويف الأكواخ السبعة','Seven Huts Cafe','seven-huts-cafe-koyf-alakoakh-alsbaa','["مقاهي"]','["cafe"]','كويف الأكواخ السبعة في الشفا مقهى بطابع ريفي وجلسات مستوحاة من الأكواخ الخشبية، وسط مناظر خضراء ونخيل ونوافير تضفي أجواءً هادئة.','<div class="texte" > <p>مقهى كويف الأكواخ السبعة مقهى بطابع ريفي مميز، يقدم قهوة مختصة وسط أجواء دافئة وجلسات مستوحاة من تصميم الأكواخ الخشبية في منطقة الشفا. يتميز بمناظره الطبيعية الخضراء ونخيله ونوافيره التي تضفي أجواءً هادئة وأنيقة، ويقدم القهوة السعودية إلى جانب الحلويات مثل كيك سيباستيان. يعمل يوميًا تقريبًا من 6 صباحًا حتى 2 فجرًا (ويومي الخميس والجمعة حتى 4 فجرًا).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073079-68538092.jpg?v=1791503679"]','https://cmsphoto.ww-cdn.com/resizeapi/fb5b62eb34b6ac9bc9c219951a0de48cffea8770/480/',21.0714489,40.3085439,'الشفا 26766','','','','https://www.saudi-guide.com/taif/i/98073079/seven-huts-cafe-koyf-alakoakh-alsbaa',1,0,'كويف اكواخ سبعه seven huts cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073078,'taif','بريزس كافيه','Breezes Cafe','breezes-cafe-bryzs-kafyh','["مقاهي"]','["cafe"]','بريزس كافيه في الشفا مقهى بإطلالات جبلية خلابة، يقدم القهوة والحلويات ويوفر أجواءً مميزة للتصوير مع مراجيح الزهور والجسر الزجاجي المعلق.','<div class="texte" > <p>مقهى بريزس كافيه مقهى بإطلالات خلابة على الجبال، يقدم تشكيلة من القهوة، والمشروبات، والحلويات المميزة كتشيز كيك التوت الأزرق. يوفر أجواءً مميزة للتصوير مع مراجيح زهور وجسر زجاجي معلق ومقاعد قرب موقد دافئ، ما يجعله وجهة رومانسية محببة للأزواج. يعمل على مدار 24 ساعة يوميًا، وللتواصل: 0556135202.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073078-68538094.jpg?v=1791503761", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073078-68538095.jpg?v=1791503773"]','https://cmsphoto.ww-cdn.com/resizeapi/2396bafeea6cb34466304e71387548f4d850999f/480/',21.0673426,40.309021,'طريق الشفا الدائري، الشفا 26766','+966556135202','','','https://www.saudi-guide.com/taif/i/98073078/breezes-cafe-bryzs-kafyh',1,0,'بريزس كافيه breezes cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073076,'taif','مقهى باز','Baz Cafe','baz-cafe-mkha-baz','["مقاهي"]','["cafe"]','مقهى باز في الشفا يقدم القهوة المختصة بجلسات داخلية وخارجية وإطلالات بانورامية على الجبال، ويضم منطقة ألعاب للأطفال وخط زيبلاين.','<div class="texte" > <p>مقهى باز يقدم قهوة مختصة في أجواء مميزة، مع جلسات داخلية وخارجية، وإطلالات بانورامية على جبال الشفا. الوصول إليه عبر طرق متعرجة ترتفع نحو أجواء الشفا الباردة، ويضم منطقة ألعاب للأطفال وخط زيبلاين، ما يجعله وجهة مثالية للعائلات. يعمل يوميًا من 3 عصرًا حتى منتصف الليل تقريبًا، وللتواصل: 0536974441.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073076-68538096.jpg?v=1791503803", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073076-68538097.jpg?v=1791503819"]','https://cmsphoto.ww-cdn.com/resizeapi/4881d5b6e7eceed09806d9c6085adb371c3095ec/480/',21.1309543,40.3009931,'مفرق خماس، الشفا، الطائف 26775','+966536974441','','','https://www.saudi-guide.com/taif/i/98073076/baz-cafe-mkha-baz',1,0,'مقهي باز baz cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073075,'taif','ضي كافيه','Dhai Cafe','dhai-cafe-dy-kafyh','["مقاهي"]','["cafe"]','ضي كافيه في منطقة الشفا بالطائف مقهى عصري يقدم القهوة المختصة والحلويات بأجواء هادئة، ويشتهر بمشروب الكركديه وعصا الوافل.','<div class="texte" > <p>ضي كافيه مقهى عصري يقدم القهوة المختصة وحلويات شهية في أجواء هادئة بمنطقة الشفا. يشتهر بمشروب الكركديه المنعش وعصا الوافل، ويتميز بكونه صديقاً للحيوانات الأليفة. يعمل يوميًا من 2 ظهرًا حتى 2 فجرًا تقريبًا، وللتواصل: 0569452846.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073075-68538099.jpg?v=1791503909", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073075-68538100.jpg?v=1791503919"]','https://cmsphoto.ww-cdn.com/resizeapi/312cae988f792261e3580553b09d3f047cb88b17/480/',21.0742571,40.3086615,'الشفا 26766','+966569452846','','','https://www.saudi-guide.com/taif/i/98073075/dhai-cafe-dy-kafyh',1,0,'ضي كافيه dhai cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073074,'taif','ترف شوكلت كافيه','Taraf Chocolate Cafe','taraf-chocolate-cafe-trf-shoklt-kafyh','["مقاهي"]','["cafe"]','ترف شوكلت كافيه داخل منتزه الردف بالطائف مقهى راقٍ يقدم تشكيلة من المشروبات والقهوة والشوكولاتة، بجلسات داخلية وخارجية وحلويات مميزة.','<div class="texte" > <p>مقهى ترف شوكلت كافيه يقدم تشكيلة متنوعة من المشروبات، والقهوة، والشوكولاتة، بجلسات داخلية وخارجية داخل منتزه الردف. يتميز بحلوياته المميزة رغم بساطة القائمة نسبيًا، ويحتوي المكان أيضًا على مطعم مجاور. يعمل يوميًا تقريبًا من 4 عصرًا حتى 1:45 فجرًا، وللتواصل: 0566247972.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073074-68538101.jpg?v=1791503957", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073074-68538102.jpg?v=1791503968"]','https://cmsphoto.ww-cdn.com/resizeapi/6e48c4c79293c385fabfe33be8f27b477796018c/480/',21.2298696,40.4225441,'الردف، الطائف 26514','+966566247972','','','https://www.saudi-guide.com/taif/i/98073074/taraf-chocolate-cafe-trf-shoklt-kafyh',1,0,'ترف شوكلت كافيه taraf chocolate cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073073,'taif','بن فاضل فيو','BFV Coffee','bfv-coffee-bn-fadl-fyo','["مقاهي"]','["cafe"]','بن فاضل فيو مقهى راقٍ داخل منتجع بن فاضل في الشفا، بإطلالة بانورامية خلابة على الطائف وديكور عصري أنيق وقائمة حلويات متنوعة.','<div class="texte" > <p>مقهى بن فاضل فيو (BFV) مقهى راقٍ بإطلالة بانورامية خلابة على مدينة الطائف، يقع داخل منتجع بن فاضل بمنطقة الشفا. يتميز بديكوره العصري الأنيق وقائمة حلويات متنوعة، مع مقاعد أمامية مطلة على المنظر وموقد للتدفئة، ما يجعله مثالياً لالتقاط الصور خصوصاً في الأجواء الضبابية. يعمل يوميًا تقريبًا من 6 صباحًا حتى منتصف الليل (ويومي الخميس والجمعة حتى الواحدة فجرًا).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073073-68538105.jpg?v=1791504046", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073073-68538106.jpg?v=1791504055"]','https://cmsphoto.ww-cdn.com/resizeapi/b96a93f8f50ff2bb78eff98ee2db93d12fbeecb0/480/',21.0681821,40.3078732,'الشفا، الطائف 43702','','','','https://www.saudi-guide.com/taif/i/98073073/bfv-coffee-bn-fadl-fyo',1,0,'بن فاضل فيو bfv coffee مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073072,'taif','ميلتز كافيه','Melt''s Cafe','melts-cafe-myltz-kafyh','["مقاهي"]','["cafe"]','ميلتز كافيه في حي الجال بالطائف يقدم تشكيلة من الحلويات والمخبوزات الطازجة، ويشتهر بقهوة الآيس دريب والفلات وايت بأجواء هادئة ومريحة.','<div class="texte" > <p>مقهى ميلتز وجهتك للتمتع بالنكهات الشهية مع تشكيلة لذيذة من الحلويات والمخبوزات الطازجة. يشتهر بقهوة الآيس دريب اليمنية والفلات وايت الغنية بالطعم دون مرارة، بأجواء هادئة ومريحة تناسب اللقاءات وجلسات العمل. يعمل على مدار 24 ساعة يوميًا (ويوم الجمعة من 12 ظهرًا حتى منتصف الليل).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073072-68538107.jpg?v=1791504088", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073072-68538108.jpg?v=1791504103"]','https://cmsphoto.ww-cdn.com/resizeapi/ca1726daac5b970fbd1438d2bc4b8e3c55aed7dc/480/',21.2751824,40.44053,'حسين بن مروان، الجال، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98073072/melts-cafe-myltz-kafyh',1,0,'ميلتز كافيه melt''s cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073071,'taif','نورث كافيه','North Cafe','north-cafe-north-kafyh','["مقاهي"]','["cafe"]','نورث كافيه داخل تيرا مول بالطائف مقهى مختص بتصميم داخلي أنيق، يشتهر باللاتيه الإسباني وتشكيلة الحلويات ويضم شرفة خارجية حيوية.','<div class="texte" > <p>نورث كافيه وجهة مختصة تجمع بين نكهات القهوة المميزة وأجواء هادئة تلهم الزوار في كل زيارة، ويقع داخل مجمع تيرا مول بتصميم داخلي أنيق. يشتهر باللاتيه الإسباني وتشكيلة الحلويات مثل تشيز كيك التوت، ويضم شرفة خارجية تنشط مساء يوم الجمعة بأجواء حيوية. يعمل على مدار 24 ساعة يوميًا، وللتواصل: 0560243439.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073071-68538109.jpg?v=1791504169", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073071-68538110.jpg?v=1791504179"]','https://cmsphoto.ww-cdn.com/resizeapi/ad900ede347f9ec7881b260ab93c904297cf45e7/480/',21.2785707,40.4431306,'شارع الخمسين، الجال، الطائف 26561','+966560243439','','','https://www.saudi-guide.com/taif/i/98073071/north-cafe-north-kafyh',1,0,'نورث كافيه north cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073070,'taif','دوبامين كافيه','Dopeamine Cafe','dopeamine-cafe-dobamyn-kafyh','["مقاهي"]','["cafe"]','دوبامين كافيه من أبرز المقاهي داخل ذا بارك مول بالطائف، يقدم أنواعاً من البن الفاخر بتصميم جذاب، ويشتهر بالأمريكانو مع التيراميسو.','<div class="texte" > <p>مقهى دوبامين يقدم أنواعًا من البن الفاخر في أجواء تمنح لحظات من السعادة، ويُعد من أبرز المقاهي داخل ذا بارك مول بتصميمه الجذاب. يشتهر بالأمريكانو المقدَّم مع التيراميسو، وتشكيلة واسعة من الكيك والمخبوزات الطازجة. يعمل على مدار 24 ساعة يوميًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073070-68538111.jpg?v=1791504239", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073070-68538112.jpg?v=1791504253"]','https://cmsphoto.ww-cdn.com/resizeapi/8ef05404c9384c9a41c616a942bdcb7736a71547/480/',21.429132,40.499007,'ذا بارك مول، الجوهرة، الطائف 26575','','','','https://www.saudi-guide.com/taif/i/98073070/dopeamine-cafe-dobamyn-kafyh',1,0,'دوبامين كافيه dopeamine cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073068,'taif','فيلوتشي','Veloce Cafe','veloce-cafe-fylotshy','["مقاهي"]','["cafe"]','فيلوتشي مقهى عصري داخل تيرا مول بالطائف يجمع بين سرعة الخدمة والقهوة المختصة، ويشتهر باللاتيه الإسباني وقهوة V60 مع خيارات من الحلويات.','<div class="texte" > <p>مقهى فيلوتشي يجمع بين سرعة الخدمة ولذة القهوة المختصة، مع خيارات متعددة من الحلويات التي تكمل التجربة. يقع داخل مجمع تيرا مول ويشتهر بقهوة اللاتيه الإسباني وقهوة V60 الكولومبية والإثيوبية، مع طاقم عمل ودود يترك انطباعًا جيدًا لدى الزوار. يعمل على مدار 24 ساعة يوميًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073068-68538113.jpg?v=1791504313", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073068-68538114.jpg?v=1791504326"]','https://cmsphoto.ww-cdn.com/resizeapi/f575105a4b25afb5bf771c133de3d67deb405400/480/',21.2795246,40.4420529,'تيرا مول، شارع الخمسين، الجال، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98073068/veloce-cafe-fylotshy',1,0,'فيلوتشي veloce cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073067,'taif','مقهى بويس','POISE Cafe','poise-cafe-mkha-boys','["مقاهي"]','["cafe"]','مقهى بويس في الطائف يقدم مشروبات وحلويات مختصة بتصميم عصري وأجواء هادئة، ويشتهر برولات القرفة ومشروبات الماتشا والكركديه.','<div class="texte" > <p>مقهى بويس (POISE) يقدم مجموعة متنوعة من المشروبات والحلويات المختصة، ويتميز بتصميم عصري وأجواء هادئة تناسب الجلسات الطويلة. من أبرز ما يشتهر به رولات القرفة والمشروبات على أساس الماتشا والكركديه المبخر، وقد حظي بإشادة واسعة من الزوار لجودة تجربته الشاملة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073067-68538115.jpg?v=1791504382", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073067-68538116.jpg?v=1791504394"]','https://cmsphoto.ww-cdn.com/resizeapi/f7a162a2cae4f3f7fa503b31b11ccb2d911751b2/480/',21.2998485,40.433593,'طريق وادي وج، جبرة، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98073067/poise-cafe-mkha-boys',1,0,'مقهي بويس poise cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073066,'taif','شاهي حكيم','Shahi Hakeem','shahi-hakeem-shahy-hkym','["مقاهي"]','["cafe"]','شاهي حكيم في الطائف محل شاي صغير يقدم أنواعاً متعددة من الشاي المختص مثل الكركديه، إلى جانب الكرواسون وفطائر الجوز والوجبات الخفيفة.','<div class="texte" > <p>شاهي حكيم يجمع بين نكهات الشاي المختصة وخيارات من الحلويات الشهية في أجواء تنبض بالحياة، وهو محل شاي صغير يقدم الكرواسون وفطائر الجوز والوجبات الخفيفة إلى جانب أنواع متعددة من الشاي مثل الكركديه. يقع داخل حي سكني وله جلسات محدودة لشخصين فقط، لكنه نظيف ومرتب. يعمل يوميًا من 2:30 ظهرًا حتى 2:30 فجرًا تقريبًا (ويوم الجمعة من 4:30 عصرًا)، وللتواصل: 0500654711.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073066-68538119.jpg?v=1791504448", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073066-68538121.jpg?v=1791504463"]','https://cmsphoto.ww-cdn.com/resizeapi/ddadd8928387548a87769925cae8d71d4e560186/480/',21.2625825,40.4114571,'الشهداء الجنوبية، الطائف 26513','+966500654711','','','https://www.saudi-guide.com/taif/i/98073066/shahi-hakeem-shahy-hkym',1,0,'شاهي حكيم shahi hakeem مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073065,'taif','ريشيو','RATIO Speciality Coffee','ratio-speciality-coffee-ryshyo','["مقاهي"]','["cafe"]','ريشيو علامة سعودية للقهوة المختصة في حي الجال بالطائف، تتميز بجودة حبوب البن وديكور عصري نظيف وأجواء هادئة مناسبة للعمل أو الدراسة.','<div class="texte" > <p>مقهى ريشيو (RATIO) قهوة مختصة بموازين دقيقة ونكهات تُلهم الذائقة، وهو علامة سعودية معروفة بحرصها على جودة حبوب البن. يتميز بديكوره العصري النظيف وأجوائه الهادئة المناسبة للعمل أو الدراسة، ويقدم في بعض الأمسيات جلسات حول نار صغيرة على الطاولات. يعمل على مدار 24 ساعة يوميًا، وللتواصل: 0566373727.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073065-68538123.jpg?v=1791504524", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073065-68538124.jpg?v=1791504539"]','https://cmsphoto.ww-cdn.com/resizeapi/b96e07c24f3d1e894b67fba7ab4c06316d220059/480/',21.2782342,40.4421541,'شارع الخمسين، الجال، الطائف 21985','+966566373727','','','https://www.saudi-guide.com/taif/i/98073065/ratio-speciality-coffee-ryshyo',1,0,'ريشيو ratio speciality coffee مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073064,'taif','روزا كافيه','Rosa Cafe','rosa-cafe-roza-kafyh','["مقاهي"]','["cafe"]','روزا كافيه في حي المعاشي بالطائف يقدم القهوة المختصة والحلويات الفاخرة والكرواسون، بديكور أنيق وجلسات داخلية وخارجية مناسبة للتصوير.','<div class="texte" > <p>روزا كافيه عالم من القهوة المختصة والحلويات الفاخرة بأجواء جميلة وديكور أنيق يجذب الزوار للتصوير. يقدم تشكيلة من الكرواسون والكعك، مع أجواء داخلية وخارجية رغم صغر مساحته نسبيًا. يعمل يوميًا تقريبًا من 7 صباحًا حتى 1:30 فجرًا (ويوم الجمعة من 3 عصرًا)، وللتواصل: 0564386232.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073064-68538126.jpg?v=1791504600", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073064-68538157.jpg?v=1791504613"]','https://cmsphoto.ww-cdn.com/resizeapi/b4b759f5640b0c39a15fd4d976bc6c08c9838698/480/',21.2802423,40.3998775,'المعاشي، الطائف 26522','+966564386232','','','https://www.saudi-guide.com/taif/i/98073064/rosa-cafe-roza-kafyh',1,0,'روزا كافيه rosa cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071153,'taif','هانزو كافيه','Hanzo Cafe','hanzo-cafe-hanzo-kafyh','["مقاهي"]','["cafe"]','هانزو كافيه في حي الجال بالطائف مقهى صغير ومريح يقدم القهوة المختصة بأجواء مستوحاة من روح المدينة، مع جلسات داخلية وخارجية محدودة.','<div class="texte" > <p>مقهى هانزو يجمع بين القهوة المختصة والأجواء المستوحاة من روح المدينة، بمكان صغير ومريح يناسب أهل الحي والبيوت القريبة. يوفر جلسات داخلية وخارجية محدودة العدد لكنها مناسبة للمكان، ويحظى بتقييمات عالية لجودة قهوته. يعمل على مدار 24 ساعة يوميًا. للتواصل: 0535005309.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071153-68538191.jpg?v=1791504670", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071153-68538192.jpg?v=1791504683"]','https://cmsphoto.ww-cdn.com/resizeapi/69f87e93c72081893e28b5ea0b92e140dc8a5bea/480/',21.2800215,40.4312113,'الجال، القمرية، الطائف 26311','+966535005309','','','https://www.saudi-guide.com/taif/i/98071153/hanzo-cafe-hanzo-kafyh',1,0,'هانزو كافيه hanzo cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071152,'taif','محفور السعودي - مبشور الطائف','','mhfor-alsaaody-mbshor-altayf','["مطاعم"]','["food"]','مطعم شعبي عريق في الطائف يشتهر بأطباق المبشور من الدجاج واللحم مع مقبلات متنوعة، ويحظى بشعبية كبيرة رغم بساطة قائمته.','<div class="texte" > <p>مطعم محفور السعودي (مبشور الطائف) مطعم شعبي عريق يمتد لسنوات طويلة في المدينة، تتجسد فيه أصالة المذاق السعودي في أطباق تحاكي روح الضيافة والنكهة التقليدية بكل تفاصيلها. يشتهر بأطباق المبشور من دجاج ولحم مع مجموعة من المقبلات المتنوعة، ويحظى بشعبية كبيرة رغم بساطة قائمته. يعمل يوميًا من 5:30 صباحًا حتى 2 فجرًا تقريبًا، وللتواصل: 0127377776.</p> </div>','[]','',21.287325,40.4230628,'طريق المطار، الريان، الطائف 26523','+966127377776','','','https://www.saudi-guide.com/taif/i/98071152/mhfor-alsaaody-mbshor-altayf',1,0,'محفور سعودي مبشور طائف مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071151,'taif','بيتنا القديم','','bytna-alkdym','["مطاعم"]','["food"]','مطعم شعبي في الطائف يقدم أطباقًا سعودية أصيلة داخل بيت تراثي من ثلاثة طوابق مليء بالأثاث العتيق والمقتنيات التي تحكي قصص الماضي.','<div class="texte" > <p>مطعم بيتنا القديم مطعم شعبي يقدم أشهى الأطباق بطابع سعودي أصيل، داخل بيت تراثي قديم من ثلاثة طوابق مليء بالأثاث العتيق والمقتنيات التي تحكي قصص الماضي. يمنح الزوار تجربة فريدة بين جدران عبقة بعبق التاريخ وشاشات تلفاز قديمة وأدوات تراثية، وسط أجواء تراثية أصيلة. يعمل يوميًا من 5 عصرًا حتى 2 فجرًا تقريبًا، وللتواصل: 0509080009.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071151-68538194.jpg?v=1791504783", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071151-68538195.jpg?v=1791504793"]','https://cmsphoto.ww-cdn.com/resizeapi/113093718486df0b67bad5d20535da2391b5a24f/480/',21.2736831,40.397716,'أسامة بن زيد، قروى، الطائف 26521','+966509080009','','','https://www.saudi-guide.com/taif/i/98071151/bytna-alkdym',1,0,'بيتنا قديم مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071150,'taif','مطعم مّله','Mallah','mtaam-m-lh-mallah','["مطاعم"]','["food"]','مطعم مّله في الطائف يقدم المأكولات السعودية الشعبية بأجواء عصرية راقية، مع جلسات داخلية وخارجية وكبائن عائلية وأطباق خليجية تقليدية.','<div class="texte" > <p>مطعم مّله يقدم تجربة مميزة للمأكولات السعودية الشعبية بأجواء عصرية راقية، مع جلسات داخلية وخارجية وصالات وكبائن عائلية متعددة. يشتهر بأطباقه التقليدية الخليجية مثل الأم علي، ويُقدَّم عند البداية خبز طازج مع الجبن والتمر كعناية إضافية بالضيوف. يعمل يوميًا من الواحدة ظهرًا حتى الواحدة صباحًا تقريبًا، وللتواصل: 0127444012.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071150-68538197.jpg?v=1791504859", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071150-68538198.jpg?v=1791504871"]','https://cmsphoto.ww-cdn.com/resizeapi/33b4391e74b79d5e2c3e68358cfd96268d99b600/480/',21.2814113,40.4465433,'طريق الملك خالد، السرور، الطائف 26311','+966127444012','','','https://www.saudi-guide.com/taif/i/98071150/mtaam-m-lh-mallah',1,0,'مطعم مله mallah مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071120,'taif','سيڤان','Sivan','sy-sivan','["مطاعم"]','["food"]','مطعم سيڤان في الطائف يجمع بين المأكولات اللبنانية والأرمينية والإيطالية، مع جلسات داخلية وخارجية أنيقة ومخصصة للعائلات.','<div class="texte" > <p>مطعم سيڤان يقدم تجربة راقية تجمع بين المأكولات اللبنانية والأرمينية والإيطالية، مع جلسات داخلية وخارجية أنيقة ومخصصة للعائلات. يشتهر بأطباق المشاوي المختلطة وقائمة مقبلات غنية، وقد قدّم بوفيه إفطار خلال رمضان إلى جانب قائمته المعتادة. يعمل يوميًا من الواحدة ظهرًا حتى 2 فجرًا تقريبًا، وللتواصل: 0503831831.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071120-68538204.jpg?v=1791504927", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071120-68538205.jpg?v=1791504941"]','https://cmsphoto.ww-cdn.com/resizeapi/5cd53c7ef974cebe3278ba9b649c909ebb9078ba/480/',21.3528592,40.4280288,'شارع الشيخ سليمان الراجحي، القيام الأعلى، الطائف 26526','+966503831831','','','https://www.saudi-guide.com/taif/i/98071120/sy-sivan',1,0,'سيڤان sivan مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071117,'taif','مطعم بوهو','Bohoo','mtaam-boho-bohoo','["مطاعم"]','["food"]','مطعم بوهو في الطائف يقدم أطباقًا متنوعة بأجواء بوهيمية مميزة، ويُعد من أشهر وجهات الفطور في المدينة بتنوع طعامه وجودة خدمته.','<div class="texte" > <p>مطعم بوهو يتيح لزواره تذوق أطباق متنوعة بأجواء بوهيمية مميزة، ويُعد من أشهر وجهات الفطور في الطائف بتنوع طعامه وجودة خدمته. يقع داخل أحد المجمعات التجارية، ويوفر مواقف سيارات كافية ودورات مياه مع مغاسل داخل المطعم. لا توجد أوقات دوام ثابتة معلنة رسميًا، لذا يُفضّل التأكد قبل الزيارة، وهو من الوجهات التي يُنصح بها بشدة لتجربة فطور مميزة في المدينة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071117-68538209.jpg?v=1791504995", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071117-68538212.jpg?v=1791505015"]','https://cmsphoto.ww-cdn.com/resizeapi/888b37fc404b4de63491fe0ecafbfdcf61209bb7/480/',21.2461062,40.4155399,'السداد، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98071117/mtaam-boho-bohoo',1,0,'مطعم بوهو bohoo مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071116,'taif','مطعم أغابي','Agape','mtaam-aghaby-agape','["مطاعم"]','["food"]','مطعم أغابي في الطائف يقدم الباستا والبرغر والسلطات المميزة في أجواء راقية ودافئة وديكور أنيق، مع خدمة سريعة واحترافية.','<div class="texte" > <p>مطعم أغابي وجهة تجمع بين الأجواء الراقية والمذاقات المتنوعة في تجربة تعكس روح الضيافة، بقائمة تشمل الباستا والبرغر والسلطات المميزة. يتميز بديكور أنيق وأجواء دافئة، وخدمة سريعة واحترافية أشاد بها الكثير من زواره. يعمل يوميًا تقريبًا من 4 عصرًا حتى منتصف الليل أو الواحدة صباحًا، وللتواصل: 0557480341.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071116-68538214.jpg?v=1791505072", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071116-68538215.jpg?v=1791505082"]','https://cmsphoto.ww-cdn.com/resizeapi/91b46ad5c38abb472336d7eb5ec21e878fa9578d/480/',21.2809692,40.445608,'طريق الملك خالد، الجال، الطائف 26523','+966557480341','','','https://www.saudi-guide.com/taif/i/98071116/mtaam-aghaby-agape',1,0,'مطعم اغابي agape مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071115,'taif','زولو','Zulu','zolo-zulu','["مطاعم"]','["food"]','مطعم زولو في حي شهار بالطائف يقدم أطباقاً عالمية متنوعة بتجربة عصرية، مع جلسات مريحة وخدمة مميزة وأطباق طازجة بتقديم أنيق.','<div class="texte" > <p>مطعم زولو يقدم تجربة عصرية تجمع بين الأطباق العالمية المتنوعة، مع جلسات مريحة وخدمة مميزة في حي شهار. يشتهر بأطباقه الطازجة المطهوة بإتقان والمقدمة بتقديم أنيق، ويحظى بتقييمات عالية لجودة الطعام والخدمة معًا. يعمل يوميًا تقريبًا من 7 صباحًا حتى 2 فجرًا، وللتواصل: 0563346583.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071115-68538216.jpg?v=1791505141", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071115-68538217.jpg?v=1791505153"]','https://cmsphoto.ww-cdn.com/resizeapi/ee9ca5264e986ba8d6e4ec47789368a019d27685/480/',21.2473438,40.4152365,'شهار، الطائف 26513','+966563346583','','','https://www.saudi-guide.com/taif/i/98071115/zolo-zulu',1,0,'زولو zulu مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071114,'taif','والونج ياز','YAZ Cafe & Lounge','oalong-yaz-yaz-cafe-lounge','["مطاعم"]','["food"]','مطعم ولاونج ياز في الطائف يقدم أجواءً راقية وإطلالة جبلية خلابة على المدينة، مع سطح مفتوح لمشاهدة غروب الشمس وقائمة متنوعة.','<div class="texte" > <p>مطعم والونج ياز يقدم تجربة فريدة تجمع بين الأجواء الراقية والإطلالة الجبلية الخلابة على مدينة الطائف، مع قائمة متنوعة من الأطباق والمشروبات والشيشة. يتميز بسطح مفتوح رائع لمشاهدة غروب الشمس، وأجواء تزداد برودة مساءً فيُنصح بارتداء ملابس دافئة (تتوفر بطانيات لمن يحتاجها). يعمل يوميًا تقريبًا من 4 عصرًا حتى 4 فجرًا، وللتواصل: 0552373888.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071114-68538220.jpg?v=1791505210", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071114-68538223.jpg?v=1791505226"]','https://cmsphoto.ww-cdn.com/resizeapi/87e0119ae0b1d440016252267d5a7423617436ba/480/',21.2708451,40.4577308,'طريق الملك خالد، النسيم، الطائف 26524','+966552373888','','','https://www.saudi-guide.com/taif/i/98071114/oalong-yaz-yaz-cafe-lounge',1,0,'والونج ياز yaz cafe & lounge مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071113,'taif','كابانا - الكوخ اللبناني','','kabana-alkokh-allbnany','["مطاعم"]','["food"]','مطعم ومقهى لبناني في الطائف يقدم قائمة متنوعة من المشاوي والمقبلات، مع جلسات داخلية وخارجية وسطح مفتوح بإطلالة جميلة على طريق وادي وج.','<div class="texte" > <p>مطعم و مقهى كابانا (الكوخ اللبناني) يقدم تجربة لبنانية أصيلة مع قائمة متنوعة من المشاوي والمقبلات في أجواء أنيقة، وجلسات داخلية وخارجية مريحة تشمل سطحًا مفتوحًا بإطلالة جميلة. يقع في مجمع يضم عدة مطاعم ومقاهي على طريق وادي وج، ويُعد خيارًا مفضلًا لوجبة الفطور المفتوحة في بعض الأوقات إلى جانب قائمته المعتادة. يعمل بدون أوقات دوام ثابتة معلنة، وللتواصل: 0547018954.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071113-68551445.jpg?v=1791632905"]','https://cmsphoto.ww-cdn.com/resizeapi/f8bf29acc6ac55dfab189e7c5cb5aa5b85072c9a/480/',21.3001259,40.4339195,'جبرة، الطائف 26523','+966547018954','','','https://www.saudi-guide.com/taif/i/98071113/kabana-alkokh-allbnany',1,0,'كابانا كوخ لبناني مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071112,'taif','مطعم جست','Just Restaurant','mtaam-gst-just-restaurant','["مطاعم"]','["food"]','مطعم جست الإيطالي في الطائف يقدم البيتزا والباستا المصنوعة بعناية في أجواء عصرية ومريحة ضمن فيلات واحة ميرال بالردف.','<div class="texte" > <p>مطعم جست إيطالي يقدم أطباقًا شهية بنكهات مميزة في أجواء عصرية ومريحة، وتشتهر قائمته بالبيتزا والباستا المصنوعة بعناية. يقع ضمن فيلات واحة ميرال بمنطقة الردف، ويُعد من الوجهات المفضلة لعشاق المطبخ الإيطالي الأصيل في الطائف. يعمل المطعم يوميًا من الواحدة ظهرًا حتى منتصف الليل تقريبًا، وللتواصل: 0506097222.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071112-68538225.jpg?v=1791505344", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071112-68538226.jpg?v=1791505354"]','https://cmsphoto.ww-cdn.com/resizeapi/d9a8b046d389d9b968382b9ae5f45e91902378ca/480/',21.2176879,40.4137882,'فيلات واحة ميرال، الردف، الطائف 26515','+966506097222','','','https://www.saudi-guide.com/taif/i/98071112/mtaam-gst-just-restaurant',1,0,'مطعم جست just restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071109,'taif','أيكون بيكري','Icon Bakery','icon-bakery-aykon-bykry','["مطاعم"]','["food"]','أيكون بيكري في حي الجال بالطائف مخبز ومقهى يجمع القهوة المختصة والمخبوزات الطازجة، ويشتهر بكرواسون الحلوم والفلات وايت بتصميم أنيق.','<div class="texte" > <p>أيكون بيكري مخبز ومقهى يجمع بين القهوة المختصة والمخبوزات الطازجة في أجواء مميزة ودافئة. يشتهر بكرواسون الحلوم والفلات وايت، والمعجنات المخبوزة طازجة يوميًا برائحة تملأ المكان، والمقهى صغير لكنه أنيق التصميم. يعمل يوميًا تقريبًا من 6 صباحًا حتى 3 عصرًا (ويغلق يوم الجمعة)، وللتواصل: 0537070647.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071109-68538232.jpg?v=1791505453", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071109-68538233.jpg?v=1791505467"]','https://cmsphoto.ww-cdn.com/resizeapi/89ccce9d9deb3a7d5d43b45d52a40e56daa076ba/480/',21.2785093,40.4374224,'ابن الهيثم، الجال، الطائف 26523','+966537070647','','','https://www.saudi-guide.com/taif/i/98071109/icon-bakery-aykon-bykry',1,0,'ايكون بيكري icon bakery مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071108,'taif','تميس 09','Tamees 09','tamees-09-tmys-09','["مطاعم"]','["food"]','مطعم تميس 09 في الطائف يقدم الفطور بأسلوب عصري يشمل خبز التميس بنكهات مبتكرة، وأطباقاً مميزة مثل المقلقل والقلابة في أجواء عائلية.','<div class="texte" > <p>مطعم تميس 09 يقدم الفطور بأسلوب عصري يشمل خبز التميس بنكهات مبتكرة، وأطباقًا صباحية متنوعة في أجواء مريحة تمزج بين الطابع الشعبي والحديث. من أطباقه المميزة المقلقل والقلابة اللذيذة، ويحرص المطعم على تجربة استقبال دافئة للعائلات. يعمل يوميًا تقريبًا من 5 صباحًا حتى منتصف الليل (ويوم الجمعة يفتح على فترتين)، وللتواصل: 0534040959.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071108-68538234.jpg?v=1791505525", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071108-68538235.jpg?v=1791505539"]','https://cmsphoto.ww-cdn.com/resizeapi/d17e147f52bbf82eed4b8fcb22c250b3edeba750/480/',21.2400163,40.3739331,'القرهين، الطائف 26511','+966534040959','','','https://www.saudi-guide.com/taif/i/98071108/tamees-09-tmys-09',1,0,'تميس 09 tamees 09 مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071107,'taif','مطعم بوستن','Boston Restaurant','boston-restaurant-mtaam-bostn','["مطاعم"]','["food"]','مطعم بوستن في حي المعاشي بالطائف يقدم أطباق فطور محلية وعالمية بأجواء عصرية، مع جلسات خارجية مميزة ويشتهر بالأطباق التركية والبان كيك.','<div class="texte" > <p>مطعم بوستن يقدم أطباق فطور تجمع بين النكهات المحلية والعالمية في أجواء عصرية مريحة، مع جلسات خارجية مميزة خصوصًا في موسم الورد. يشتهر بأطباقه التركية والشرقية، ومن أبرز الأطباق المحببة لدى الزوار البان كيك. يعمل المطعم يوميًا تقريبًا من 6 صباحًا حتى منتصف الليل (مع إغلاق قصير بعد الظهر بعض الأيام)، وللتواصل والاستفسار: 0127252150.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071107-68538238.jpg?v=1791505592", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071107-68538239.jpg?v=1791505603"]','https://cmsphoto.ww-cdn.com/resizeapi/8bf307ca2b9a2335ed0b09e584956ee0e3397a9a/480/',21.2792886,40.4026331,'شارع الجيش، المعاشي، الطائف 26522','+966127252150','','','https://www.saudi-guide.com/taif/i/98071107/boston-restaurant-mtaam-bostn',1,0,'مطعم بوستن boston restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071106,'taif','بوب كارت منتزه الحدبان','Pop Kart Al Hadban','pop-kart-al-hadban-bob-kart-mntzh-alhdban','["أماكن سياحية"]','["sights"]','بوب كارت منتزه الحدبان في الشفا تجربة مثيرة لعشاق السرعة، تتيح سباق سيارات صغيرة على مسار مخصص وسط الأجواء الجبلية الباردة.','<div class="texte" > <p>لعبة البوب كارت في منتزه الحدبان بمنطقة الشفا تجربة مثيرة لعشاق السرعة، حيث تسمح بسباق سيارات صغيرة على مسار مخصص وسط أجواء جبلية باردة تميز الشفا. الجولة الواحدة قصيرة لكنها ممتعة، ويُنصح بالزيارة في الأوقات المتأخرة من المساء لتفادي الازدحام في موسم الذروة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071106-68538240.jpg?v=1791505661", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071106-68538241.jpg?v=1791505678"]','https://cmsphoto.ww-cdn.com/resizeapi/c4f1c0c79748b67b66cf2755b7b73e27601f6d0f/480/',21.1255633,40.3696013,'طريق الشفا، منتزه الحدبان الترفيهي، الشفا 26762','','','','https://www.saudi-guide.com/taif/i/98071106/pop-kart-al-hadban-bob-kart-mntzh-alhdban',1,0,'بوب كارت منتزه حدبان pop kart al hadban اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071105,'taif','مزرعة ورد الطائف','Taif Rose Farm','taif-rose-farm-mzraa-ord-altayf','["أماكن سياحية"]','["sights"]','مزرعة ورد الطائف وجهة طبيعية ساحرة بحقول الورد الطائفي التي تزهر في الربيع، مع فرصة مشاهدة المزارعين أثناء الحصاد وتجربة الإفطار الريفي.','<div class="texte" > <p>مزرعة ورد الطائف وجهة طبيعية ساحرة تقدّم أجمل حقول الورد الطائفي في أجواء هادئة وتجربة فريدة، حيث يزهر الورد في فصل الربيع من كل عام. يمكن للزوار مشاهدة مزارعي الورد أثناء عملهم وحصادهم للأزهار، إلى جانب تجربة الإفطار الريفي بمكونات طازجة من المزرعة نفسها، مع لمحة عن أصالة الطائف وشهرتها بمنتجاتها الزراعية. تعمل المزرعة يوميًا تقريبًا من 6:30 صباحًا حتى 10:30 مساءً، ويُنصح بالزيارة في الصباح الباكر لتفادي الازدحام والاستمتاع بالمكان في أفضل حالاته.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071105-68538243.jpg?v=1791505770", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071105-68538244.jpg?v=1791505786"]','https://cmsphoto.ww-cdn.com/resizeapi/d24c8735eb4e5c7ad217e49c86d0f99aa88f0c08/480/',21.3826179,40.3476055,'ملح، الطائف 26583','','','','https://www.saudi-guide.com/taif/i/98071105/taif-rose-farm-mzraa-ord-altayf',1,0,'مزرعه ورد طائف taif rose farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071104,'taif','ذا بارك مول','The Park Mall','the-park-mall-tha-bark-mol','["أماكن سياحية"]','["sights"]','ذا بارك مول وجهة تسوق بطابع فرنسي فاخر في الطائف مقابل جامعة الطائف، بمساحات خضراء منسقة ومجموعة من المتاجر والمطاعم والمقاهي.','<div class="texte" > <p>ذا بارك مول وجهة تسوق بطابع فرنسي فاخر، وهو أول مول من نوعه في الطائف بموقع استراتيجي مقابل جامعة الطائف وقرب المطار. يتميز بمساحاته الخضراء المنسقة التي تضفي أجواءً هادئة وسط صخب التسوق، إلى جانب مجموعة من المتاجر والمطاعم والمقاهي. يعمل المول يوميًا من التاسعة صباحًا حتى الحادية عشرة مساءً تقريبًا (ويفتح الجمعة من الواحدة ظهرًا)، ويُنصح بزيارته مساءً في الصيف للاستمتاع بأجواء أكثر اعتدالًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071104-68538247.jpg?v=1791505845", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071104-68538251.jpg?v=1791505858"]','https://cmsphoto.ww-cdn.com/resizeapi/94e1e7132fe5d86d6475a40920a2634942910aa8/480/',21.4297412,40.4990112,'طريق المطار، الجوهرة، الطائف 26575','+966920009467','','','https://www.saudi-guide.com/taif/i/98071104/the-park-mall-tha-bark-mol',1,0,'ذا بارك مول the park mall اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071103,'taif','جوري مول','Jouri Mall','jouri-mall-gory-mol','["أماكن سياحية"]','["sights"]','جوري مول من أكبر مراكز التسوق في الطائف مساحةً وتنوعاً، يضم علامات تجارية عالمية ومحلية ومطاعم ومقاهي متعددة وحياة ليلية نشطة.','<div class="texte" > <p>جوري مول من أكبر مراكز التسوق في الطائف من حيث المساحة والتنوع، ويضم مجموعة واسعة من العلامات التجارية العالمية والمحلية، إلى جانب مطاعم ومقاهي متعددة وحياة ليلية نشطة خصوصًا في عطلة نهاية الأسبوع. يتميز بمواقف سيارات مظللة وواسعة، ويُعد خيارًا مثاليًا لمن يبحث عن تجربة تسوق شاملة في مكان واحد. يستقبل زواره يوميًا من العاشرة صباحًا حتى الحادية عشرة مساءً تقريبًا (ويفتح الجمعة من الثانية ظهرًا).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071103-68538252.jpg?v=1791505915", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071103-68538255.jpg?v=1791505926"]','https://cmsphoto.ww-cdn.com/resizeapi/b2453b8ec8292b6e4ac7cec753c0d421c5abdfa6/480/',21.277086,40.444686,'طريق خالد بن الوليد، الجال، الطائف 26523','+966122270118','','','https://www.saudi-guide.com/taif/i/98071103/jouri-mall-gory-mol',1,0,'جوري مول jouri mall اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98071101,'taif','تيرا مول','Tera Mall','tera-mall-tyra-mol','["أماكن سياحية"]','["sights"]','تيرا مول من أبرز وجهات التسوق في الطائف بتصميم معماري فرنسي أنيق، يجمع المتاجر العالمية والمحلية والمطاعم والمقاهي وواجهة مميزة للتصوير.','<div class="texte" > <p>تيرا مول من أبرز وجهات التسوق في الطائف، بتصميم معماري فرنسي أنيق يجمع بين المتاجر العالمية والمحلية، والمطاعم، والمقاهي المتنوعة. يتميز المول بواجهته الخارجية المميزة وبرجه الصغير الذي يذكّر بمعالم أوروبية، ما يجعله وجهة محببة للتصوير. يضم المول قسمين رئيسيين ومنطقة واسعة للمطاعم والمقاهي، ويعمل يوميًا من الساعة 8:30 صباحًا حتى الواحدة صباحًا تقريبًا، وهو مكان مناسب لقضاء أمسية عائلية بين التسوق وتناول الطعام.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071101-68538256.jpg?v=1791505979", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98071101-68538257.jpg?v=1791505988"]','https://cmsphoto.ww-cdn.com/resizeapi/c719cbae671b9e7d7c672a19c09fcf70a3ca287f/480/',21.2789693,40.4446421,'شارع الخمسين، القطبية، الطائف 26523','','','','https://www.saudi-guide.com/taif/i/98071101/tera-mall-tyra-mol',1,0,'تيرا مول tera mall اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070988,'jeddah','مدينة الملك عبدالله الرياضية','King Abdullah Sports City','king-abdullah-sports-city-mdyn-almlk-aabdallh-alryady','["سياحة وترفيه"]','["sights"]','مدينة الملك عبدالله الرياضية استاد رياضي ضخم يستضيف أهم المباريات والفعاليات الرياضية، ويُعد وجهة مميزة لعشاق كرة القدم لمشاهدة نجوم عالميين.','<div class="texte" > <p>مدينة الملك عبدالله الرياضية استاد رياضي ضخم يستضيف أهم المباريات والفعاليات الرياضية، ويُعد وجهة مميزة لعشاق كرة القدم لمشاهدة نجوم عالميين. يوفر أكشاكًا للوجبات الخفيفة والمشروبات داخل المدرجات، ودورات مياه متعددة ومحطات لتعبئة المياه، ويحظى بتقييمات ممتازة لجودة المرافق وسهولة إجراءات الدخول. مواعيد الدوام من 9:00 صباحًا حتى 6:00 مساءً (حتى 5:00 عصرًا في نهاية الأسبوع).</p> </div>  <div class="texte" > <p>مصدر الصورة: ويكيميديا كومنز — تصوير saudipics (CC BY-SA 4.0)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070988-68537710.jpg?v=1791497858"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98070988-68537710.jpg?v=1791497858',21.7635443,39.1641378,'طريق الأمير طلال بن منصور، مطار الملك عبدالعزيز الدولي، جدة 23737','','','','https://www.saudi-guide.com/jeddah/i/98070988/king-abdullah-sports-city-mdyn-almlk-aabdallh-alryady',1,0,'مدينه ملك عبدالله رياضيه king abdullah sports city سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070987,'jeddah','منتزه الكورنيش الأوسط','Middle Corniche Park','middle-corniche-park-mntzh-alkornysh-alaost','["سياحة وترفيه"]','["sights"]','منتزه الكورنيش الأوسط يتميز بإطلالة على أطول نافورة في العالم كما يضم جلسات وألعاب للأطفال بالإضافة إلى أكشاك لبيع المرطبات والمأكولات.','<div class="texte" > <p>منتزه الكورنيش الأوسط يتميز بإطلالة على أطول نافورة في العالم كما يضم جلسات وألعاب للأطفال بالإضافة إلى أكشاك لبيع المرطبات والمأكولات. يُنصح بزيارته صباحًا للاستمتاع بمشاهدة الطيور والأسماك، مع توفر مسجد ودورات مياه ومقاعد جلوس مريحة، ويعمل على مدار الساعة طوال أيام الأسبوع.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070987-68538259.jpg?v=1791506042", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070987-68538260.jpg?v=1791506053"]','https://cmsphoto.ww-cdn.com/resizeapi/650bf95c8ce1bbf54a7f98b4aadef19411325da2/480/',21.5284328,39.1553081,'2403، طريق الكرنيش الفرعي، الحمراء، جدة 23321','','','','https://www.saudi-guide.com/jeddah/i/98070987/middle-corniche-park-mntzh-alkornysh-alaost',1,0,'منتزه كورنيش اوسط middle corniche park سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070986,'jeddah','نافورة الملك فهد','King Fahd''s Fountain','king-fahds-fountain-nafor-almlk-fhd','["سياحة وترفيه"]','["sights"]','نافورة الملك فهد حصلت على لقب أطول نافورة في العالم من موسوعة جينيس العالمية، بارتفاع يقارب 260 مترًا يجعلها معلمًا مرئيًا من مسافات بعيدة.','<div class="texte" > <p>نافورة الملك فهد حصلت على لقب أطول نافورة في العالم من موسوعة جينيس العالمية، بارتفاع يقارب 260 مترًا يجعلها معلمًا مرئيًا من مسافات بعيدة. يبدأ عرض النافورة عادة الساعة 5:30 مساءً، وتُعد تجربة ساحرة خصوصًا عند الغروب مع إضاءتها الليلية الملونة، ويُنصح بالوصول مبكرًا لاختيار مكان جلوس مناسب على طول الكورنيش.</p> </div>    <div class="texte" > <p>مصدر الصور: ويكيميديا كومنز — تصوير Tahir mq (CC BY-SA 4.0) و Basheer Olakara (CC BY 2.0)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070986-68537709.jpg?v=1791497856", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070986-68537714.jpg?v=1791497869"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98070986-68537709.jpg?v=1791497857',21.5156556,39.1450512,'الأندلس، جدة 23311','','','','https://www.saudi-guide.com/jeddah/i/98070986/king-fahds-fountain-nafor-almlk-fhd',1,0,'نافوره ملك فهد king fahd''s fountain سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070977,'jeddah','ستارز أفينيو','Stars Avenue','starz-afynyo-stars-avenue','["أسواق"]','["shopping"]','يضم مجموعة كبيرة من المحال التجارية المميزة والمطاعم بالإضافة إلى صالة ألعاب للأطفال. مجمع تجاري.','<div class="texte" > <p>ستارز أفينيو يضم مجموعة كبيرة من المحال التجارية المميزة والمطاعم بالإضافة إلى صالة ألعاب للأطفال. يتميز بموقعه القريب من البحر وسينما AMC ونادي رياضي، ويقدم مأكولات متنوعة من إنجليزية وعربية وإيطالية. للتواصل: 0122754562، ومواعيد الدوام من 10:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070977-68538265.jpg?v=1791506127"]','https://cmsphoto.ww-cdn.com/resizeapi/84336d1de91c4f3130eda5e946d3fb867e2cef92/480/',21.5727255,39.1285135,'طريق الملك عبدالعزيز، الزهراء، جدة 23424','0122754562','','','https://www.saudi-guide.com/jeddah/i/98070977/starz-afynyo-stars-avenue',1,0,'ستارز افينيو stars avenue اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070976,'jeddah','المروة سنتر','Al Marwah Plaza','al-marwah-plaza-almro-sntr','["أسواق"]','["shopping"]','المروة سنتر يضم مجموعة معارض متنوعة ومطاعم مميزة يقع في حي المروة. يضم ستاربكس ومطعم فارس للإفطار وكوستا كوفي وماكدونالدز وألباك.','<div class="texte" > <p>المروة سنتر يضم مجموعة معارض متنوعة ومطاعم مميزة يقع في حي المروة. يضم ستاربكس ومطعم فارس للإفطار وكوستا كوفي وماكدونالدز وألباك، مع تصميم يسمح بالتجول السهل رغم بعض الملاحظات على تعقيد المخارج أحيانًا. مواعيد الدوام من 6:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070976-68538272.jpg?v=1791506188"]','https://cmsphoto.ww-cdn.com/resizeapi/68b3ba92f2cfa3715d7a1c8c4d86d0d0b67e20c0/480/',21.6147562,39.1882539,'الأمير ماجد، المروة، جدة 23541','','','','https://www.saudi-guide.com/jeddah/i/98070976/al-marwah-plaza-almro-sntr',1,0,'مروه سنتر al marwah plaza اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070974,'jeddah','سكاي ووك','Skywalk','skywalk-skay-ook','["أسواق"]','["shopping"]','سكاي ووك يضم مجموعة مميزة من المطاعم والكافيهات بأسلوب مفعم بالحياة العصرية. يشتهر بمطعم قود هود وعروض الفطور المبكر.','<div class="texte" > <p>سكاي ووك يضم مجموعة مميزة من المطاعم والكافيهات بأسلوب مفعم بالحياة العصرية. يشتهر بمطعم قود هود وعروض الفطور المبكر، ويحظى بشعبية كبيرة في حي الروضة كوجهة يومية للقاء الأصدقاء وتناول الطعام.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070974-68538277.jpg?v=1791506248", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070974-68538278.jpg?v=1791506260"]','https://cmsphoto.ww-cdn.com/resizeapi/d4c4eda672dde64f64b72d8349ff785f797bdf8d/480/',21.5745167,39.1479443,'8895، عبدالمقصود خوجة، الروضة، جدة 23435','','','','https://www.saudi-guide.com/jeddah/i/98070974/skywalk-skay-ook',1,0,'سكاي ووك skywalk اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070972,'jeddah','تاون سكوير','Town Square','town-square-taon-skoyr','["أسواق"]','["shopping"]','تاون سكوير وجهة متكاملة تضم كل وسائل الترفيه والتسلية من مراكز التسوق إلى السينما والمطاعم والكافيهات.','<div class="texte" > <p>تاون سكوير وجهة متكاملة تضم كل وسائل الترفيه والتسلية من مراكز التسوق إلى السينما والمطاعم والكافيهات. يضم مكتبة جرير وسوبرماركت لولو إكسبرس وسينما فوكس، ويُعد وجهة مفضلة لإنجاز عدة مهام تسوق في زيارة واحدة. مواعيد الدوام من 8:00 صباحًا حتى 5:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070972-68538279.jpg?v=1791506350"]','https://cmsphoto.ww-cdn.com/resizeapi/7b3df50efb7a15c16b4a992eafe0d666777a7d78/480/',21.4829466,39.2381812,'الثغر، جدة 22338','','','','https://www.saudi-guide.com/jeddah/i/98070972/town-square-taon-skoyr',1,0,'تاون سكوير town square اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070971,'jeddah','الاندلس مول','Al Andalus Mall','al-andalus-mall-alandls-mol','["أسواق"]','["shopping"]','الاندلس مول مركز تسوق كبير ومعاصر يضم الكثير من متاجر التجزئة الشهيرة وسوبر ماركت وقاعة طعام. يضم سينما وصالات ألعاب.','<div class="texte" > <p>الاندلس مول مركز تسوق كبير ومعاصر يضم الكثير من متاجر التجزئة الشهيرة وسوبر ماركت وقاعة طعام. يضم سينما وصالات ألعاب، ويحظى بشعبية كبيرة كوجهة عائلية شاملة تلبي احتياجات التسوق والترفيه في آن واحد. للتواصل: 8001111771، ومواعيد الدوام من 9:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070971-68538285.jpg?v=1791506449", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070971-68538289.jpg?v=1791506459"]','https://cmsphoto.ww-cdn.com/resizeapi/c1bf43279c768c9fc15e11704d33e27135e6f66f/480/',21.5071076,39.2178928,'طريق الأمير ماجد، الفيحاء، جدة 22245','8001111771','','','https://www.saudi-guide.com/jeddah/i/98070971/al-andalus-mall-alandls-mol',1,0,'اندلس مول al andalus mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070970,'jeddah','السلام مول','Al Salaam Mall','al-salaam-mall-alslam-mol','["أسواق"]','["shopping"]','السلام مول يتميز بموقع حيوي هام كما يتميز بتشكيلة متنوعة من الماركات العالمية المميزة. يوفر تجربة تسوق شاملة تجمع الملابس والإلكترونيات والبقالة.','<div class="texte" > <p>السلام مول يتميز بموقع حيوي هام كما يتميز بتشكيلة متنوعة من الماركات العالمية المميزة. يوفر تجربة تسوق شاملة تجمع الملابس والإلكترونيات والبقالة، بجانب مرافق ترفيهية كصالة ألعاب للأطفال ونادٍ رياضي وسينما. للتواصل: 920000262، ومواعيد الدوام من 10:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070970-68538291.jpg?v=1791506516", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070970-68538292.jpg?v=1791506530"]','https://cmsphoto.ww-cdn.com/resizeapi/b0845915488048b426c3cfdf0c250b6a08b36900/480/',21.507193,39.2237106,'طريق الملك عبدالله، حي السليمانية، جدة 22251','920000262','','','https://www.saudi-guide.com/jeddah/i/98070970/al-salaam-mall-alslam-mol',1,0,'سلام مول al salaam mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070969,'jeddah','ذا فيلج مول','The Village Mall','the-village-mall-tha-fylg-mol','["أسواق"]','["shopping"]','ذا فيلج مول يتألق بتصاميمه الحديثة ويعتبر مركزًا تجاريًا شاملاً ومتنوعًا ووجهة متكاملة لجميع أفراد العائلة.','<div class="texte" > <p>ذا فيلج مول يتألق بتصاميمه الحديثة ويعتبر مركزًا تجاريًا شاملاً ومتنوعًا ووجهة متكاملة لجميع أفراد العائلة. يتميز بدمجه الأنيق بين البوليفارد الخارجي والمحال الداخلية، ونافورة راقصة مسائية، ومقاهٍ كإل آند إن وبارنز. للتواصل: 920009467، ومواعيد الدوام من 9:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070969-68538294.jpg?v=1791506603", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070969-68538295.jpg?v=1791506615"]','https://cmsphoto.ww-cdn.com/resizeapi/c3ffb4444368948e9acd23ce6cbec326918acc61/480/',21.7739847,39.1702953,'5342، طريق الأمير طلال بن منصور، الأصالة، جدة 23738','920009467','','','https://www.saudi-guide.com/jeddah/i/98070969/the-village-mall-tha-fylg-mol',1,0,'ذا فيلج مول the village mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070968,'jeddah','أتيليه لافي','Atelier La Vie','atelier-la-vie-atylyh-lafy','["أسواق"]','["shopping"]','أتيليه لافي في جدة مجمع مطاعم وكافيهات حديثة ومتنوعة بجلسات مميزة، كما يضم سينما فاخرة ووجهة مثالية للسهرات.','<div class="texte" > <p>أتيليه لافي مركز أتيليه اليف جدة مجمع مطاعم وكافيهات حديثة ومتنوعة بجلسات مميزة كما يضم سينما فاخرة. يضم مطاعم مرموقة كأوليف جاردن وبرو 92 وإل آند إن، مع مواقف مجانية، ويُعد وجهة راقية للمناسبات الخاصة والسهرات. مواعيد الدوام من 7:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070968-68538296.jpg?v=1791506682", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070968-68538297.jpg?v=1791506702"]','https://cmsphoto.ww-cdn.com/resizeapi/8ab6a2ad30b50f5deb57a9574890c7650f782e93/480/',21.6130625,39.1180625,'الشاطئ، جدة 23514','','','','https://www.saudi-guide.com/jeddah/i/98070968/atelier-la-vie-atylyh-lafy',1,0,'اتيليه لافي atelier la vie اسواق',strftime('%s','now'));
