INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070964,'jeddah','أبحر مول','Obhour Mall','obhour-mall-abhr-mol','["أسواق"]','["shopping"]','أبحر مول يوفر مجموعة متنوعة من المحال التجارية كما يضم مجموعة من المرافق الترفيهية المتنوعة. يشتهر بمطاعمه المميزة مثل تشيليز وشريمب زون.','<div class="texte" > <p>أبحر مول يوفر مجموعة متنوعة من المحال التجارية كما يضم مجموعة من المرافق الترفيهية المتنوعة. يشتهر بمطاعمه المميزة مثل تشيليز وشريمب زون، وسينما تُقيم عروضًا ترويجية أسبوعية وشهرية، رغم صغر حجمه نسبيًا مقارنة بمولات جدة الكبرى.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070964-68538326.jpg?v=1791506950"]','https://cmsphoto.ww-cdn.com/resizeapi/37c90ddf98f3eeff6f38388f8a512bfdf7dc547f/480/',21.7539003,39.1192524,'4283، أبحر الشمالية، جدة 23815','','','','https://www.saudi-guide.com/jeddah/i/98070964/obhour-mall-abhr-mol',1,0,'ابحر مول obhour mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070963,'jeddah','العرب مول','Mall of Arabia','mall-of-arabia-alaarb-mol','["أسواق"]','["shopping"]','العرب مول يعد مركز العرب التجاري أكبر المراكز التجارية في مدينة جدة ويضم مناطق مختلفة تناسب جميع أفراد العائلة.','<div class="texte" > <p>العرب مول يعد مركز العرب التجاري أكبر المراكز التجارية في مدينة جدة ويضم مناطق مختلفة تناسب جميع أفراد العائلة. يضم علامات عالمية كسيفورا وديكاثلون وساحة طعام واسعة، ويحظى بتصميم معماري جذاب مع ممرات واسعة تسهّل التنقل. للتواصل: 920000262، ومواعيد الدوام من 10:00 صباحًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070963-68538332.jpg?v=1791507014", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070963-68538333.jpg?v=1791507025"]','https://cmsphoto.ww-cdn.com/resizeapi/9059e8c91ecd1bf5ef14c729ec6bcf777235a91c/480/',21.632517,39.156161,'طريق المدينة المنورة، النزهة، جدة 23532','920000262','','','https://www.saudi-guide.com/jeddah/i/98070963/mall-of-arabia-alaarb-mol',1,0,'عرب مول mall of arabia اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070961,'jeddah','ردسي مول','Red Sea Mall','red-sea-mall-rdsy-mol','["أسواق"]','["shopping"]','ردسي مول يضم تحت سقفه العديد من المتاجر المحلية والعالمية ومناطق ألعاب، كما يحتوي على إحدى أكبر صالات السينما في جدة.','<div class="texte" > <p>ردسي مول يضم تحت سقفه العديد من المتاجر المحلية والعالمية ومناطق ألعاب، كما يحتوي على إحدى أكبر صالات السينما في جدة. يوفر موقعًا استراتيجيًا مع فندق ضمن نفس المبنى، ويضم خيارات واسعة من المطاعم والمقاهي، ويُعد من أكثر المولات شعبية في المدينة. للتواصل: 0122151551، ومواعيد الدوام من 9:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070961-68538335.jpg?v=1791507081", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070961-68538336.jpg?v=1791507092"]','https://cmsphoto.ww-cdn.com/resizeapi/196d149e20cda4f539137c86c219a75287550422/480/',21.6286568,39.1118495,'طريق الملك عبدالعزيز، الشاطئ، جدة 21146','0122151551','','','https://www.saudi-guide.com/jeddah/i/98070961/red-sea-mall-rdsy-mol',1,0,'ردسي مول red sea mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070960,'jeddah','هيفاء مول','Haifa Mall','haifa-mall-hyfa-mol','["أسواق"]','["shopping"]','هيفاء مول يحتوي المركز على مناطق مخصصة للأطفال بمختلف الأعمار ومحال تجارية عالمية ومنطقة طعام متفردة.','<div class="texte" > <p>هيفاء مول يحتوي المركز على مناطق مخصصة للأطفال بمختلف الأعمار ومحال تجارية عالمية ومنطقة طعام متفردة. يتميز بهدوئه النسبي مقارنة بالمولات الأكثر ازدحامًا، ويناسب الزوار الباحثين عن تسوق مريح بعيدًا عن الصخب. مواعيد الدوام من 9:00 صباحًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070960-68538339.jpg?v=1791507148"]','https://cmsphoto.ww-cdn.com/resizeapi/914136680527991a613f6669c3a13a16d40c3554/480/',21.5275222,39.1774566,'8349، فلسطين، حي الروضة، جدة 23215','','','','https://www.saudi-guide.com/jeddah/i/98070960/haifa-mall-hyfa-mol',1,0,'هيفاء مول haifa mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070941,'jeddah','مقهى دياب','Diyab Cafe','mkh-dyab-diyab-cafe','["مقاهي ومخبوزات"]','["cafe"]','هو الأقدم في جدة التاريخية والوجهة المفضلة لمحبي قهوة اللوز الأصيلة المعدة بوصفة خاصة من ابتكار مالك المقهى. مقهى.','<div class="texte" > <p>مقهى دياب هو الأقدم في جدة التاريخية والوجهة المفضلة لمحبي قهوة اللوز الأصيلة المعدة بوصفة خاصة من ابتكار مالك المقهى وليد دياب. يقدم القهوة العربية مع التمر مجانًا، ويحتضنك بأجواء صحراوية دافئة وسط قصة تراثية حية تعكس أصالة جدة القديمة. للتواصل: 0535256858، ومواعيد الدوام من 8:00 صباحًا حتى 11:00 مساءً (من 4:00 عصرًا يوم الجمعة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070941-68538344.jpg?v=1791507217", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070941-68538345.jpg?v=1791507238"]','https://cmsphoto.ww-cdn.com/resizeapi/473a0b6703eb635831437887a3ab2dd9de37faa4/480/',21.4846271,39.1875363,'80، جدة التاريخية، جدة 22249','0535256858','','','https://www.saudi-guide.com/jeddah/i/98070941/mkh-dyab-diyab-cafe',1,0,'مقهي دياب diyab cafe مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070939,'jeddah','ستار مقز','Star Mugs Coffee Shop','star-mugs-coffee-shop-star-mkz','["مقاهي ومخبوزات"]','["cafe"]','ستار مقز يتميز بتقديم القهوة التركية على الرمل بالطريقة الأصلية بجانب العديد من المشروبات والحلويات الشهية.','<div class="texte" > <p>ستار مقز يتميز بتقديم القهوة التركية على الرمل بالطريقة الأصلية بجانب العديد من المشروبات والحلويات الشهية. يقدم قهوة يومية طازجة وخدمة جيدة رغم بساطة المكان، ويحظى بتقدير الزوار على تجربة يومية موثوقة. مواعيد الدوام من 6:30 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070939-68538352.jpg?v=1791507382"]','https://cmsphoto.ww-cdn.com/resizeapi/90900b2cb64036fd14e4827864ab5784c0fc89ff/480/',21.59549,39.2048692,'طريق الأمير متعب بن عبدالعزيز، الصفا، جدة 23456','','','','https://www.saudi-guide.com/jeddah/i/98070939/star-mugs-coffee-shop-star-mkz',1,0,'ستار مقز star mugs coffee shop مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070938,'jeddah','ميراكي','Meraki Artisan','meraki-artisan-myraky','["مقاهي ومخبوزات"]','["cafe"]','ميراكي محمصة قهوة مختصة تتميز بتقديم القهوة بجودة عالية والمخبوزات الطازجة. يشتهر بالأمريكانو الخفيف عديم الحموضة والكرواسان بالجبن التركي مع الزيتون.','<div class="texte" > <p>ميراكي محمصة قهوة مختصة تتميز بتقديم القهوة بجودة عالية والمخبوزات الطازجة. يشتهر بالأمريكانو الخفيف عديم الحموضة والكرواسان بالجبن التركي مع الزيتون، ويعتمد نظام طلب عبر رمز QR يجلب الطلب مباشرة للطاولة. للتواصل: 0551101862، ومواعيد الدوام من 7:00 صباحًا حتى 11:00 مساءً (حتى منتصف الليل الخميس).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070938-68538355.jpg?v=1791507438", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070938-68538356.jpg?v=1791507447"]','https://cmsphoto.ww-cdn.com/resizeapi/b41ba5d20a2dd4c7803719a4ac341fb71098799d/480/',21.5729577,39.1486149,'سيتي يارد، 2628 عبدالمقصود خوجة، الروضة، جدة 23435','0551101862','','','https://www.saudi-guide.com/jeddah/i/98070938/meraki-artisan-myraky',1,0,'ميراكي meraki artisan مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070937,'jeddah','برو 92','Brew 92','brew-92-bro-92','["مقاهي ومخبوزات"]','["cafe"]','برو 92 يقدم مجموعة واسعة من القهوة المختصة المقدمة بجودة عالية. يشتهر بمشروب الماتشا بحليب جوز الهند والعسل وسلطة القيصر.','<div class="texte" > <p>برو 92 يقدم مجموعة واسعة من القهوة المختصة المقدمة بجودة عالية. يشتهر بمشروب الماتشا بحليب جوز الهند والعسل وسلطة القيصر، ويوفر مساحة عمل هادئة في الطابق العلوي، ويحظى بشعبية كبيرة كوجهة يومية للقاءات والدراسة. للتواصل: 0564843439، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل (حتى 2:00 فجرًا في منتصف الأسبوع ونهايته).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070937-68538357.jpg?v=1791507500", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070937-68538358.jpg?v=1791507512"]','https://cmsphoto.ww-cdn.com/resizeapi/2e4256cd7629befc2cf846582809feb86b57b1d4/480/',21.6145304,39.1176649,'طريق الملك عبدالعزيز الفرعي، الشاطئ، جدة 23514','0564843439','','','https://www.saudi-guide.com/jeddah/i/98070937/brew-92-bro-92',1,0,'برو 92 brew 92 مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070936,'jeddah','كافيين لاب','Caffeine Lab','caffeine-lab-kafyyn-lab','["مقاهي ومخبوزات"]','["cafe"]','كافيين لاب في جدة يقدم تجربة قهوة استثنائية ترضي جميع الأذواق، ويشتهر ببسكويت النوتيلا وساندويتش فيرفاكس بأجواء عصرية مريحة.','<div class="texte" > <p>كافيين لاب يقدم تجربة قهوة استثنائية ترضي جميع الأذواق. يشتهر ببسكويت النوتيلا وساندويتش فيرفاكس، ويقدم حبوب قهوة مختارة من حول العالم بأجواء عصرية مريحة تناسب العمل أو اللقاءات الاجتماعية. للتواصل: 0556009987، ومواعيد الدوام من 6:30 صباحًا حتى 11:00 مساءً (حتى منتصف الليل الخميس والجمعة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070936-68538365.jpg?v=1791507574", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070936-68538366.jpg?v=1791507589"]','https://cmsphoto.ww-cdn.com/resizeapi/a083ea43b6fcbc842350f18a5cc9e0bd9985ca9d/480/',21.5474238,39.1493869,'عبدالله المطري، الأندلس، جدة 23322','0556009987','','','https://www.saudi-guide.com/jeddah/i/98070936/caffeine-lab-kafyyn-lab',1,0,'كافيين لاب caffeine lab مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070935,'jeddah','ذا بوبا بار','The Boba Bar','the-boba-bar-tha-boba-bar','["مقاهي ومخبوزات"]','["cafe"]','ذا بوبا بار يقدم مشروبات البوبا والماتشا المنعشة بالإضافة إلى العديد من الخيارات المميزة. يشتهر ببوبا السكر البني والتارو.','<div class="texte" > <p>ذا بوبا بار يقدم مشروبات البوبا والماتشا المنعشة بالإضافة إلى العديد من الخيارات المميزة. يشتهر ببوبا السكر البني والتارو، ويقدم آيس كريم التارو مجانيًا كلمسة ترحيبية، ويُعد من أشهر محال البوبا في جدة بشهادة زبائنه. للتواصل: 0546090031، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070935-68538370.jpg?v=1791507648", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070935-68538372.jpg?v=1791507661"]','https://cmsphoto.ww-cdn.com/resizeapi/7774b7f5dda8a3cef7076db4b09fe4659e21b9d4/480/',21.5987095,39.1252353,'الزهراء، جدة 23523','0546090031','','','https://www.saudi-guide.com/jeddah/i/98070935/the-boba-bar-tha-boba-bar',1,0,'ذا بوبا بار the boba bar مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070934,'jeddah','عمار كافيه','Ammar''s Cafe','ammars-cafe-aamar-kafyh','["مقاهي ومخبوزات"]','["cafe"]','عمار كافيه يقدم القهوة المختصة المصنوعة يدويًا كما يتميز بتصميم داخلي أنيق. يشتهر بكيك التمر والوافل، ويحظى بموسيقى هادئة تسمح بمحادثات مريحة.','<div class="texte" > <p>عمار كافيه يقدم القهوة المختصة المصنوعة يدويًا كما يتميز بتصميم داخلي أنيق. يشتهر بكيك التمر والوافل، ويحظى بموسيقى هادئة تسمح بمحادثات مريحة، ويعمل على مدار الساعة طوال أيام الأسبوع بخدمة تتحدث الإنجليزية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070934-68538376.jpg?v=1791507718", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070934-68538379.jpg?v=1791507729"]','https://cmsphoto.ww-cdn.com/resizeapi/4018eb6bef027484eb4b0f9ac74a0f25bb36b2b0/480/',21.5970022,39.1426771,'4515، الباطرجي، الزهراء، جدة 23521','','','','https://www.saudi-guide.com/jeddah/i/98070934/ammars-cafe-aamar-kafyh',1,0,'عمار كافيه ammar''s cafe مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070898,'jeddah','قهوة زهر','Qahwet Zahr','qahwet-zahr-kho-zhr','["مقاهي ومخبوزات"]','["cafe"]','قهوة زهر مقهى بأجواء مصرية يقدم القهوة والحلويات اللذيذة، ويشتهر بمشروبات الشاي والقهوة الساخنة والباردة والعصائر الطازجة.','<div class="texte" > <p>قهوة زهر مقهى بأجواء مصرية يقدم القهوة والحلويات اللذيذة، ويشتهر بمشروبات الشاي والقهوة الساخنة والباردة والعصائر الطازجة. يتميز بموسيقى مسائية جميلة تبدأ عادة من الساعة العاشرة مساءً، ويُنصح بحجز مسبق في المناسبات الخاصة. للتواصل: 0555840270، ويعمل على مدار الساعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070898-68538381.jpg?v=1791507782", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070898-68538383.jpg?v=1791507791"]','https://cmsphoto.ww-cdn.com/resizeapi/782abcd425b85c6867caa5f01619f6d14ad087c3/480/',21.6441052,39.1415031,'صفياء، عائكة بنت عبدالمطلب، الصفا، جدة 23454','0555840270','','','https://www.saudi-guide.com/jeddah/i/98070898/qahwet-zahr-kho-zhr',1,0,'قهوه زهر qahwet zahr مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070897,'jeddah','هيمي كوفي','Hemi Coffee','hemi-coffee-hymy-kofy','["مقاهي ومخبوزات"]','["cafe"]','هيمي كوفي في جدة مقهى ومحمصة يقدم أنواعاً متعددة من البن بجودة عالية، ويشتهر بكيك الموز وحلوى تريس ليتشيس بالمانجو.','<div class="texte" > <p>Hemi Coffee مقهى ومحمصة يقدم أنواعًا متعددة من البن بجودة عالية يناسب جميع الأذواق. يشتهر بكيك الموز وحلوى تريس ليتشيس بالمانجو، ويتميز برائحة القهوة المحمصة الطازجة صباحًا في منطقة التحميص المفتوحة، مع أجواء هادئة تناسب العمل والدراسة. للتواصل: 0552121165، ومواعيد الدوام من 6:30 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070897-68538387.jpg?v=1791507842", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070897-68538388.jpg?v=1791507852"]','https://cmsphoto.ww-cdn.com/resizeapi/6ce87a73f031761492090af505c2edf07e416ee5/480/',21.6026094,39.1424143,'مجمع سبا، طريق الأمير سلطان، الزهراء، جدة 23522','0552121165','','','https://www.saudi-guide.com/jeddah/i/98070897/hemi-coffee-hymy-kofy',1,0,'هيمي كوفي hemi coffee مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070896,'jeddah','مقهى ميناء','Minaa Cafe','minaa-cafe-mkha-myna','["مقاهي ومخبوزات"]','["cafe"]','مقهى ميناء يقع على بعد خطوات من بيت نصيف في جدة التاريخية ويشتهر بتحضير مختلف أنواع القهوة. يشتهر بقهوة V60 والوافل.','<div class="texte" > <p>مقهى ميناء يقع على بعد خطوات من بيت نصيف في جدة التاريخية ويشتهر بتحضير مختلف أنواع القهوة. يشتهر بقهوة V60 والوافل، ويتميز بديكور كلاسيكي يعكس عبق التاريخ منسجمًا مع أجواء البلد، وطاقم ودود يشعرك بالانتماء للمكان. مواعيد الدوام من 8:00 صباحًا حتى 11:30 مساءً (من 4:00 عصرًا يوم الجمعة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070896-68538394.jpg?v=1791507909", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070896-68538397.jpg?v=1791507925"]','https://cmsphoto.ww-cdn.com/resizeapi/9d9c9900f1d6f8ea866daa03a8f3fc047b1fbd3e/480/',21.4841075,39.1879739,'جدة التاريخية، جدة 22236','','','','https://www.saudi-guide.com/jeddah/i/98070896/minaa-cafe-mkha-myna',1,0,'مقهي ميناء minaa cafe مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070895,'jeddah','سكلبتشر','Sculpture Café','sculpture-caf-sklbtshr','["مقاهي ومخبوزات"]','["cafe"]','سكلبتشر متخصص في تقديم القهوة كما يحتوي على متجر يقدم منتجات مختارة بعناية. يشتهر بقهوة V60 وأطباق الفطور الفاخرة.','<div class="texte" > <p>سكلبتشر متخصص في تقديم القهوة كما يحتوي على متجر يقدم منتجات مختارة بعناية. يشتهر بقهوة V60 وأطباق الفطور الفاخرة، ويقدم حبوب قهوة مستوردة من اليمن وكولومبيا وأوغندا وإثيوبيا ونيكاراجوا، ويُعد فائزًا بجوائز عدة كأفضل مقهى في جدة. للتواصل: 0542408734، ومواعيد الدوام من 8:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070895-68538403.jpg?v=1791507981", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070895-68538406.jpg?v=1791507998"]','https://cmsphoto.ww-cdn.com/resizeapi/4047acba1b5c1d55ee3df290fc6af030814e8b3e/480/',21.5472604,39.1495057,'شارع التحلية، 6631 عبدالله المطري، الأندلس، جدة 23322','0542408734','','','https://www.saudi-guide.com/jeddah/i/98070895/sculpture-caf-sklbtshr',1,0,'سكلبتشر sculpture café مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070894,'jeddah','تايني هاوس','Tiny House','tiny-house-tayny-haos','["مقاهي ومخبوزات"]','["cafe"]','تايني هاوس يقدم عددًا من الأصناف اللذيذة من الحلويات بالإضافة إلى القهوة. يتميز بمساحة صغيرة بسيطة لكن أنيقة تتماشى مع اسمه.','<div class="texte" > <p>تايني هاوس يقدم عددًا من الأصناف اللذيذة من الحلويات بالإضافة إلى القهوة. يتميز بمساحة صغيرة بسيطة لكن أنيقة تتماشى مع اسمه، ويحظى بخدمة ودودة عالية المعايير من الطاقم، ويُنصح بالطلب الخارجي نظرًا لمحدودية أماكن الجلوس. للتواصل: 0562569471، ومواعيد الدوام من 2:00 ظهرًا حتى 3:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070894-68538409.jpg?v=1791508063", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070894-68538413.jpg?v=1791508081"]','https://cmsphoto.ww-cdn.com/resizeapi/8db2e67e34cff51384685fb4dfb20fbdc701004f/480/',21.5895356,39.1293633,'2505، شارع الأمير نايف فرعي، الزهراء، جدة 23425','0562569471','','','https://www.saudi-guide.com/jeddah/i/98070894/tiny-house-tayny-haos',1,0,'تايني هاوس tiny house مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070893,'jeddah','دوتس','DOTS Doughnut','dots-doughnut-dots','["مقاهي ومخبوزات"]','["cafe"]','دوتس يقدم القهوة وتشكيلة متنوعة من الدونات بطريقة مميزة وجديدة. يشتهر بدونات الجلاس والتشيز كيك، ويحظى بخدمة سريعة ولطيفة من الفريق.','<div class="texte" > <p>دوتس يقدم القهوة وتشكيلة متنوعة من الدونات بطريقة مميزة وجديدة. يشتهر بدونات الجلاس والتشيز كيك، ويحظى بخدمة سريعة ولطيفة من الفريق، ويُعد من أفضل محال الدونات في جدة بشهادة الزوار. مواعيد الدوام من 8:00 صباحًا حتى 1:00 فجرًا (حتى 2:00 فجرًا نهاية الأسبوع).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070893-68538419.jpg?v=1791508141", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070893-68538422.jpg?v=1791508153"]','https://cmsphoto.ww-cdn.com/resizeapi/141d19eec73a72c213df242a1758c45735c1446e/480/',21.5700269,39.1249562,'بوليفارد، الشاطئ، جدة 23414','','','','https://www.saudi-guide.com/jeddah/i/98070893/dots-doughnut-dots',1,0,'دوتس dots doughnut مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070892,'jeddah','عدني بار','Adani Bar','adani-bar-aadny-bar','["مقاهي ومخبوزات"]','["cafe"]','عدني بار يقدم مشروب الشاي العدني بالإضافة إلى أصناف مختلفة من المأكولات الخفيفة. يشتهر بساندويتش التونة الشهير وشاي الجعلة الحار والبارد.','<div class="texte" > <p>عدني بار يقدم مشروب الشاي العدني بالإضافة إلى أصناف مختلفة من المأكولات الخفيفة. يشتهر بساندويتش التونة الشهير وشاي الجعلة الحار والبارد، ويقدم أطباق الفلافل والكباب أيضًا في أجواء دافئة تشعرك وكأنك في المنزل. للتواصل: 0542826054، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070892-68540913.jpg?v=1791533916", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070892-68540927.jpg?v=1791533926"]','https://cmsphoto.ww-cdn.com/resizeapi/f1cbf782c2975732d6eb3d9484f214ba06ca61d8/480/',21.5993721,39.1184883,'7033، الخنساء، حي الشاطئ، جدة 23513','0542826054','','','https://www.saudi-guide.com/jeddah/i/98070892/adani-bar-aadny-bar',1,0,'عدني بار adani bar مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070891,'jeddah','قود هود','GOODHOOD','goodhood-kod-hod','["مقاهي ومخبوزات"]','["cafe"]','قود هود يتميز بألعاب الطاولة والقهوة والمأكولات الخفيفة، ويشتهر بالشوكولاتة الساخنة بنكهة المارشميلو وقهوة السحابة.','<div class="texte" > <p>قود هود يتميز بألعاب الطاولة والقهوة والمأكولات الخفيفة، ويشتهر بالشوكولاتة الساخنة بنكهة المارشميلو وقهوة السحابة. يوفر إنترنت مجاني للعمل أو الدراسة، ويتميز بديكور جذاب متنوع الألوان والمقاعد يجعله مثاليًا للتصوير. للتواصل: 0550835166، ومواعيد الدوام من 8:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070891-68539246.jpg?v=1791527429", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070891-68539249.jpg?v=1791527443"]','https://cmsphoto.ww-cdn.com/resizeapi/ff079bc6fd19e817428a6f9cc1c2ef46cce6b9af/480/',21.5742276,39.148464,'عبدالمقصود خوجه، الروضة، جدة 23615','0550835166','','','https://www.saudi-guide.com/jeddah/i/98070891/goodhood-kod-hod',1,0,'قود هود goodhood مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070890,'jeddah','آيتش','H Cafe','h-cafe-aytsh','["مقاهي ومخبوزات"]','["cafe"]','آيتش مقهى يقدم القهوة وأصنافًا من الحلويات المعدة بعناية. يحظى بأجواء هادئة وخدمة ودودة من الفريق، ويشيد الزوار خصوصًا بحسن الاستقبال والمعاملة الطيبة.','<div class="texte" > <p>آيتش مقهى يقدم القهوة وأصنافًا من الحلويات المعدة بعناية، ويعمل على مدار الساعة طوال أيام الأسبوع. يحظى بأجواء هادئة وخدمة ودودة من الفريق، ويشيد الزوار خصوصًا بحسن الاستقبال والمعاملة الطيبة. للتواصل: 0502466697.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070890-68539260.jpg?v=1791527523", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070890-68539261.jpg?v=1791527539"]','https://cmsphoto.ww-cdn.com/resizeapi/b2865302becd093398b0ce6e757b8f2f9a60c585/480/',21.4788246,39.2662466,'4976، جنوب ابن لادن، الروابي، جدة 22345','0502466697','','','https://www.saudi-guide.com/jeddah/i/98070890/h-cafe-aytsh',1,0,'ايتش h cafe مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070889,'jeddah','أفران الحطب','Al Hatab Bakery','al-hatab-bakery-afran-alhtb','["مقاهي ومخبوزات"]','["cafe"]','أفران الحطب يشتهر بتقديم المخبوزات والمعجنات الطازجة المحضرة يوميًا في مخابزهم بجانب العديد من الأجبان والألبان الشهية.','<div class="texte" > <p>أفران الحطب يشتهر بتقديم المخبوزات والمعجنات الطازجة المحضرة يوميًا في مخابزهم بجانب العديد من الأجبان والألبان الشهية. يشتهر بالعصائر الطازجة والأطعمة الصحية، ويوفر متنوعة من التوابل المعبأة إضافة للمخبوزات الأساسية. للتواصل: 920002281، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070889-68539266.jpg?v=1791527590", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070889-68539267.jpg?v=1791527604"]','https://cmsphoto.ww-cdn.com/resizeapi/40a3eb1e7794c50cbdd7c2c2d7f5b53f03e1338a/480/',21.6138389,39.156513,'شارع حراء، البوادي، جدة 23531','920002281','','','https://www.saudi-guide.com/jeddah/i/98070889/al-hatab-bakery-afran-alhtb',1,0,'افران حطب al hatab bakery مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070888,'jeddah','لا كريم','La Crème Bakery','la-cr-me-bakery-la-krym','["مقاهي ومخبوزات"]','["cafe"]','لا كريم في جدة مخبز يقدم تشكيلة واسعة من الحلويات المحضرة بالكريمة بنكهات مبتكرة، ويشتهر بالكرواسان باللوز والجبنة المدخنة.','<div class="texte" > <p>لا كريم يقدم مجموعة واسعة من الحلويات المحضرة بالكريمة بحشوات مختلفة ونكهات مبتكرة لذيذة. يشتهر بالكرواسان باللوز والجبنة المدخنة اللذين يُنصح بهما لفطور لا يُنسى، ويحظى بأسعار جيدة وطعم رائع في مكان صغير ولطيف. للتواصل: 0564469291، ومواعيد الدوام من 7:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070888-68539270.jpg?v=1791527663", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070888-68539275.jpg?v=1791527676"]','https://cmsphoto.ww-cdn.com/resizeapi/858a02824a9d5c4f326b2342db9893f95478723f/480/',21.612459,39.2095044,'عامر بن أبي ربيعة، المروة، جدة 23535','0564469291','','','https://www.saudi-guide.com/jeddah/i/98070888/la-cr-me-bakery-la-krym',1,0,'لا كريم la crème bakery مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070887,'jeddah','بلو جام','Blu Jam','blu-jam-blo-gam','["مقاهي ومخبوزات"]','["cafe"]','بلو جام من أفضل المخابز في جدة يقدم تشكيلة واسعة من المخبوزات المبتكرة ومجموعة متنوعة من الكيك بنكهات فريدة.','<div class="texte" > <p>بلو جام من أفضل المخابز في جدة يقدم تشكيلة واسعة من المخبوزات المبتكرة ومجموعة متنوعة من الكيك بنكهات فريدة. يشتهر بالكرواسان الذي لم يجد له مثيلًا في جدة برأي كثير من الزوار، ورائحة الخبز الطازج تفوح كل صباح منذ الساعة السابعة. للتواصل: 0561555999، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070887-68539279.jpg?v=1791527727", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070887-68539280.jpg?v=1791527737"]','https://cmsphoto.ww-cdn.com/resizeapi/1cd5a5407a7bd9757f069e37467b0e4573efb1f2/480/',21.5137511,39.1611478,'شارع المعادي، بجانب مطعم بيتزا لينو، الحمراء، جدة 23212','0561555999','','','https://www.saudi-guide.com/jeddah/i/98070887/blu-jam-blo-gam',1,0,'بلو جام blu jam مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070886,'jeddah','نعمة','Neamah Bakery','neamah-bakery-naam','["مقاهي ومخبوزات"]','["cafe"]','نعمة مخبز يتميز بتقديم المعجنات والحلويات منذ عام 1985 بتشكيلة واسعة ومتنوعة شهية. يُعد من أعرق المخابز في جدة بخبرة تمتد لعقود.','<div class="texte" > <p>نعمة مخبز يتميز بتقديم المعجنات والحلويات منذ عام 1985 بتشكيلة واسعة ومتنوعة شهية. يُعد من أعرق المخابز في جدة بخبرة تمتد لعقود، ويحظى بمنتجات طازجة تُصنع يوميًا، وإن كانت بعض الملاحظات تشير لضرورة تحسين مستوى خدمة العملاء. للتواصل: 920000679، ومواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070886-68544535.jpg?v=1791550092", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070886-68544536.jpg?v=1791550099"]','https://cmsphoto.ww-cdn.com/resizeapi/6af490b6e549423bc565a53799bbea7fadb600eb/480/',21.7320141,39.1947468,'الكوثر، جدة 23743','920000679','','','https://www.saudi-guide.com/jeddah/i/98070886/neamah-bakery-naam',1,0,'نعمه neamah bakery مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070885,'jeddah','كريبري دي ماربيا','Creperie De Marbella','creperie-de-marbella-krybry-dy-marbya','["مقاهي ومخبوزات"]','["cafe"]','كريبري دي ماربيا لعشاق الكريب يتميز بتقديم الكريب بنكهات متعددة ومبتكرة لتستمتع بمذاق رائع. يشتهر بكريب النوتيلا والكريب الحار بصلصة البيستو.','<div class="texte" > <p>كريبري دي ماربيا لعشاق الكريب يتميز بتقديم الكريب بنكهات متعددة ومبتكرة لتستمتع بمذاق رائع. يشتهر بكريب النوتيلا والكريب الحار بصلصة البيستو، ويقدم جلسات داخلية أنيقة وخارجية مريحة، إلى جانب مشروبات باردة منعشة كالكركديه. للتواصل: 0502077676، ومواعيد الدوام من 10:30 صباحًا حتى 3:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070885-68544541.jpg?v=1791550156", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070885-68544542.jpg?v=1791550163"]','https://cmsphoto.ww-cdn.com/resizeapi/6e4141e26526ad19574c3f6094142b8dbfa58d76/480/',21.5742592,39.1271774,'طريق الملك عبدالعزيز، الزهراء، جدة 23424','0502077676','','','https://www.saudi-guide.com/jeddah/i/98070885/creperie-de-marbella-krybry-dy-marbya',1,0,'كريبري دي ماربيا creperie de marbella مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070884,'jeddah','سيبلنقز','Siblings','siblings-syblnkz','["مقاهي ومخبوزات"]','["cafe"]','سيبلنقز في جدة يشتهر بتقديم البان كيك والتوست الفرنسي بطريقة مميزة، إلى جانب العديد من الحلويات والمخبوزات الشهية.','<div class="texte" > <p>Siblings يشتهر بتقديم ألذ بان كيك في جدة، كما يقدم التوست الفرنسي بطريقة مميزة شهية والعديد من الحلويات والمخبوزات. يشتهر ببان كيك السوفليه المميز الذي يحظى بإشادة كبيرة من الزوار، ويقدم لعبة صغيرة تفوز فيها بسوربيه مجاني كلمسة ممتعة. للتواصل: 0559181286، ومواعيد الدوام من 7:00 صباحًا حتى 11:00 مساءً (حتى منتصف الليل الخميس والجمعة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070884-68544546.jpg?v=1791550214", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070884-68544547.jpg?v=1791550221"]','https://cmsphoto.ww-cdn.com/resizeapi/53d5f5ce60272d4505306b4b28378bf6b620f6b1/480/',21.5705514,39.1484895,'2603، الإمام مالك، الروضة، جدة 23435','0559181286','','','https://www.saudi-guide.com/jeddah/i/98070884/siblings-syblnkz',1,0,'سيبلنقز siblings مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070883,'jeddah','بريد أهيد البيكري والمدرسة','Bread Ahead','bread-ahead-bryd-ahyd-albykry-oalmdrs','["مقاهي ومخبوزات"]','["cafe"]','بريد أهيد البيكري والمدرسة يقدم تجربة صنع المخبوزات لتعيش دور الخباز بالإضافة إلى الاستمتاع بالقهوة والمعجنات اللذيذة.','<div class="texte" > <p>بريد أهيد البيكري والمدرسة يقدم تجربة صنع المخبوزات لتعيش دور الخباز بالإضافة إلى الاستمتاع بالقهوة والمعجنات اللذيذة. يشتهر بساندويتش الديك الرومي البيغل وشكشوكة الجبن، ويقدم ورش خبز حقيقية بإشراف طهاة محترفين لمن يريد تعلم الحرفة. للتواصل: 0538434670، ومواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070883-68544551.jpg?v=1791550276", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070883-68544552.jpg?v=1791550283"]','https://cmsphoto.ww-cdn.com/resizeapi/0f19fc97bf85e7c44da676b77708bc011e8c00a3/480/',21.576657,39.1273143,'طريق الملك عبدالعزيز، الزهراء، جدة 23424','0538434670','','','https://www.saudi-guide.com/jeddah/i/98070883/bread-ahead-bryd-ahyd-albykry-oalmdrs',1,0,'بريد اهيد بيكري والمدرسه bread ahead مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070882,'jeddah','جاناش','Ganache','ganache-ganash','["مقاهي ومخبوزات"]','["cafe"]','جاناش متخصص بتقديم قائمة واسعة من الكيك والحلويات المصنوعة يوميًا بالإضافة إلى القهوة. يشتهر بكيك المانجو السحابي وكيك الشوكولاتة الغني.','<div class="texte" > <p>جاناش متخصص بتقديم قائمة واسعة من الكيك والحلويات المصنوعة يوميًا بالإضافة إلى القهوة. يشتهر بكيك المانجو السحابي وكيك الشوكولاتة الغني، ويُعد علامة سعودية فاخرة محلية معروفة بجودة منتجاتها العالية وخدمتها الاستثنائية. للتواصل: 920019960، ومواعيد الدوام من 9:00 صباحًا حتى 1:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070882-68544554.jpg?v=1791550339", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070882-68544556.jpg?v=1791550346"]','https://cmsphoto.ww-cdn.com/resizeapi/c05b89d6ce76843c4049dea6fa67c4defc4f3e13/480/',21.5610802,39.1598614,'طريق الأمير سعود الفيصل، الروضة، جدة 23432','920019960','','','https://www.saudi-guide.com/jeddah/i/98070882/ganache-ganash',1,0,'جاناش ganache مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070881,'jeddah','سكر الندى','Sucre de Nada','sucre-de-nada-skr-alnda','["مقاهي ومخبوزات"]','["cafe"]','سكر الندى استمتع برائحة القهوة وسط أجواء دافئة بجانب قائمة واسعة ومتنوعة من الحلويات الشهية. يشتهر بفطيرة التفاح الشهيرة وكريم كراميل.','<div class="texte" > <p>سكر الندى استمتع برائحة القهوة وسط أجواء دافئة بجانب قائمة واسعة ومتنوعة من الحلويات الشهية. يشتهر بفطيرة التفاح الشهيرة وكريم كراميل، ويحظى بتقييمات ممتازة جدًا لجودة الكيك، خصوصًا كيك جوز الهند والشوكولاتة، رغم بعض الملاحظات على مستوى الخدمة أحيانًا. للتواصل: 0505286861، ومواعيد الدوام من 10:00 صباحًا حتى 11:00 مساءً (حتى منتصف الليل في نهاية الأسبوع).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070881-68544560.jpg?v=1791550402", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070881-68544561.jpg?v=1791550409"]','https://cmsphoto.ww-cdn.com/resizeapi/7a87e149002ee6336071f6489712110c395a3de7/480/',21.5617794,39.1595217,'درويش كيال، الروضة، جدة 23433','0505286861','','','https://www.saudi-guide.com/jeddah/i/98070881/sucre-de-nada-skr-alnda',1,0,'سكر ندي sucre de nada مقاهي ومخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070879,'jeddah','مطعم طوكيو','Tokyo Al Malik Road','mtaam-tokyo-tokyo-al-malik-road','["مطاعم"]','["food"]','من أشهر المطاعم في تقديم الأطباق اليابانية يتميز بتقديم قائمة واسعة من السوشي اللذيذ. مطعم مميز.','<div class="texte" > <p>مطعم طوكيو من أشهر المطاعم في تقديم الأطباق اليابانية يتميز بتقديم قائمة واسعة من السوشي اللذيذ. يشتهر بتونة سمك أمبرجاك الترافل وأرز طوكيو الخاص وشرائح لحم الواغيو الياباني، ويحظى بخدمة استثنائية وقائمة تتجدد حسب الموسم. للتواصل: 920009662، ومواعيد الدوام من 1:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070879-68544570.jpg?v=1791550464", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070879-68544571.jpg?v=1791550471"]','https://cmsphoto.ww-cdn.com/resizeapi/afbd9d416f4e0ba5e01fb5618a3f0d0de6fcdead/480/',21.6445645,39.112059,'3605، طريق الملك عبدالعزيز، المحمدية، جدة 23617','920009662','','','https://www.saudi-guide.com/jeddah/i/98070879/mtaam-tokyo-tokyo-al-malik-road',1,0,'مطعم طوكيو tokyo al malik road مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070877,'jeddah','مطعم وكافيه اغايف','Agave','agave-mtaam-okafyh-aghayf','["مطاعم"]','["food"]','مطعم وكافيه اغايف مطعم مميز يقدم أجود الأطباق العالمية في مكان واحد ويوفر أيضًا القهوة والحلويات اللذيذة.','<div class="texte" > <p>مطعم وكافيه اغايف مطعم مميز يقدم أجود الأطباق العالمية في مكان واحد ويوفر أيضًا القهوة والحلويات اللذيذة. يتميز بإطلالة ساحرة على مدينة جدة من السطح، وأجواء موسيقية حية، ويُعد مكانًا رائعًا لالتقاط الصور خصوصًا وقت الغروب. للتواصل: 0552361616، ومواعيد الدوام من 1:00 ظهرًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070877-68544584.jpg?v=1791550539", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070877-68544588.jpg?v=1791550546"]','https://cmsphoto.ww-cdn.com/resizeapi/139028acf1499b29c7c2327edd78ad0086ff98cd/480/',21.7652858,39.1419539,'طريق الملك عبدالعزيز الفرعي، أبحر الجنوبية، جدة 23734','0552361616','','','https://www.saudi-guide.com/jeddah/i/98070877/agave-mtaam-okafyh-aghayf',1,0,'مطعم وكافيه اغايف agave مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070875,'jeddah','مطعم أوليف جاردن','Olive Garden','olive-garden-mtaam-aolyf-gardn','["مطاعم"]','["food"]','مطعم أوليف جاردن المكان الأمثل لعشاق النكهات الإيطالية الأصلية متخصص بتقديم العديد من الأطباق الإيطالية الشهية.','<div class="texte" > <p>مطعم أوليف جاردن المكان الأمثل لعشاق النكهات الإيطالية الأصلية متخصص بتقديم العديد من الأطباق الإيطالية الشهية. يشتهر بالخبز والشوربة والباستا المتنوعة، ويحظى بتقييمات ممتازة جدًا لجودة الخدمة والأجواء العائلية الودودة. للتواصل: 0597485555، ومواعيد الدوام من 12:00 ظهرًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070875-68544598.jpg?v=1791550600", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070875-68544601.jpg?v=1791550607"]','https://cmsphoto.ww-cdn.com/resizeapi/b4472211cc3896ea63540f26ae8e2386098aaa64/480/',21.6134841,39.1179079,'أتيليه لا في، طريق الملك عبدالعزيز، الشاطئ، جدة 23514','0597485555','','','https://www.saudi-guide.com/jeddah/i/98070875/olive-garden-mtaam-aolyf-gardn',1,0,'مطعم اوليف جاردن olive garden مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070874,'jeddah','لو فيزوفيو','Le Vesuvio','le-vesuvio-lo-fyzofyo','["مطاعم"]','["food"]','لو فيزوفيو من المطاعم المميزة الفاخرة يأتيكم من فرنسا ليقدم ألذ الأطباق الشهية بجلسات رائعة على البحر.','<div class="texte" > <p>لو فيزوفيو من المطاعم المميزة الفاخرة يأتيكم من فرنسا ليقدم ألذ الأطباق الشهية بجلسات رائعة على البحر. يشتهر ببيتزا الترافل الأصيلة ولازانيا البارميجيانو، ويستضيف موسيقى حية كل خميس، ويحظى بإطلالة رائعة على غروب الشمس. مواعيد الدوام من 5:00 مساءً حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070874-68544611.jpg?v=1791550659", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070874-68544613.jpg?v=1791550666"]','https://cmsphoto.ww-cdn.com/resizeapi/3e1281070cf79e6499cdbf47b5d5c3e438e4251f/480/',21.6530855,39.1024697,'7190، طريق الكورنيش الفرعي، الشاطئ، جدة 23613','','','','https://www.saudi-guide.com/jeddah/i/98070874/le-vesuvio-lo-fyzofyo',1,0,'لو فيزوفيو le vesuvio مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070873,'jeddah','5 ريفرز','5 Rivers','5-rivers-5-ryfrz','["مطاعم"]','["food"]','5 ريفرز من أفضل المطاعم الهندية بتقديم خبز النان اللذيذ بجانب العديد من الأطباق الشهية. يشتهر بأضلاع اللحم وشوربة اللوز بالدجاج.','<div class="texte" > <p>5 ريفرز من أفضل المطاعم الهندية بتقديم خبز النان اللذيذ بجانب العديد من الأطباق الشهية. يشتهر بأضلاع اللحم وشوربة اللوز بالدجاج، ويحظى بديكور راقٍ يضم زراعة نباتية داخلية، رغم بعض الملاحظات على صغر الحصص مقارنة بالأسعار. للتواصل: 0508265666، ومواعيد الدوام من 12:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070873-68544629.jpg?v=1791550719"]','https://cmsphoto.ww-cdn.com/resizeapi/3daf3aee600d9711806a1ab277ff5864c190d7ce/480/',21.5725028,39.1325702,'2858، طريق ساري، الزهراء، جدة 23424','0508265666','','','https://www.saudi-guide.com/jeddah/i/98070873/5-rivers-5-ryfrz',1,0,'5 ريفرز 5 rivers مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070872,'jeddah','خيال','Khayal Restaurant','khayal-restaurant-khyal','["مطاعم"]','["food"]','خيال مطعم تركي يقدم أشهى المأكولات التركية والعربية بنكهات أصلية، ويقدم خبزًا ومقبلات وزيتونًا وصلصة ترحيبية مجانية مع كل وجبة.','<div class="texte" > <p>خيال مطعم تركي يقدم أشهى المأكولات التركية والعربية بنكهات أصلية، ويقدم خبزًا ومقبلات وزيتونًا وصلصة ترحيبية مجانية مع كل وجبة. يشتهر بشوربة العدس المريحة وأطباق الشواء الطازجة، ويُعد من أكثر المطاعم شعبية وازدحامًا في جدة. للتواصل: 920002223، ومواعيد الدوام من 6:00 صباحًا حتى 3:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070872-68544647.jpg?v=1791550786", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070872-68544649.jpg?v=1791550793"]','https://cmsphoto.ww-cdn.com/resizeapi/f97dda11fe137f2f226d5971718afb0bb7e2c79c/480/',21.6095822,39.1410604,'طريق الأمير سلطان، الزهراء، جدة 23522','920002223','','','https://www.saudi-guide.com/jeddah/i/98070872/khayal-restaurant-khyal',1,0,'خيال khayal restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070871,'jeddah','سومو سايز','Somosays Pizza','somosays-pizza-somo-sayz','["مطاعم"]','["food"]','سومو سايز مطعم متخصص بتقديم البيتزا على الطريقة الأصلية بنكهات فريدة بجانب مجموعة واسعة من الصلصات المبتكرة.','<div class="texte" > <p>سومو سايز مطعم متخصص بتقديم البيتزا على الطريقة الأصلية بنكهات فريدة بجانب مجموعة واسعة من الصلصات المبتكرة. يشتهر ببيتزا البافلو الشهية وصندوق المقبلات السخي، ويحظى بأجواء دافئة وإضاءة جذابة تجعله وجهة محببة للتكرار. للتواصل: 0555664725، ومواعيد الدوام من 12:00 ظهرًا حتى 4:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070871-68544660.jpg?v=1791550844", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070871-68544662.jpg?v=1791550851"]','https://cmsphoto.ww-cdn.com/resizeapi/5a9c26965f7fc458a80e0e6c1430b0d6401bf1df/480/',21.598438,39.1251349,'بوكس بارك سنتر، الباطرجي، الزهراء، جدة 23522','0555664725','','','https://www.saudi-guide.com/jeddah/i/98070871/somosays-pizza-somo-sayz',1,0,'سومو سايز somosays pizza مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070869,'jeddah','كيكن','Keiken','keiken-kykn','["مطاعم"]','["food"]','كيكن في جدة مطعم ياباني يتميز بسير السوشي وتشكيلة من الكابوريا والتونة والسلمون والروبيان، مع إمكانية مشاهدة الطهاة أثناء التحضير.','<div class="texte" > <p>كيكن لعشاق الطعم الياباني الأصلي يتميز بتقديم سير السوشي بجانب العديد من الأطباق المتنوعة الشهية. يقدم عرض سوشي مفتوح بسعر ثابت (129 ريالًا) يشمل أنواعًا متعددة من الكابوريا والتونة والسلمون والروبيان، ويتيح للزوار مشاهدة الطهاة أثناء التحضير مباشرة. للتواصل: 0555041624، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070869-68544675.jpg?v=1791550928"]','https://cmsphoto.ww-cdn.com/resizeapi/76c11c6198c470163feec82f8672f9c7f4de7bda/480/',21.5755248,39.1426659,'6370، طريق الأمير سلطان، الزهراء، جدة 23424','0555041624','','','https://www.saudi-guide.com/jeddah/i/98070869/keiken-kykn',1,0,'كيكن keiken مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070868,'jeddah','شاي معلوم','Chai Maloom','chai-maloom-shay-maalom','["مطاعم"]','["food"]','شاي معلوم في جدة يقدم التوابل الهندية الشهية بجانب العديد من الأصناف العربية، ويشتهر بمشروب الشاي المميز الذي يحمل اسمه.','<div class="texte" > <p>شاي معلوم يقدم لكم استمتاعًا بالتوابل الهندية الشهية بجانب العديد من الأصناف العربية. يفتح أبوابه باكرًا جدًا من الفجر، ويشتهر بمشروب الشاي المميز الذي يحمل اسمه، ويحظى بشعبية بين عشاق المذاق الهندي الممزوج بالطابع الشعبي. للتواصل: 0553382166، ومواعيد الدوام من 4:30 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070868-68544684.jpg?v=1791550995", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070868-68544686.jpg?v=1791551002"]','https://cmsphoto.ww-cdn.com/resizeapi/753faec10b8e522bfd6e256b11b010205388ec76/480/',21.6541835,39.11213,'المحمدية، جدة 23617','0553382166','','','https://www.saudi-guide.com/jeddah/i/98070868/chai-maloom-shay-maalom',1,0,'شاي معلوم chai maloom مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070867,'jeddah','دا باو','Da Bao','da-bao-da-bao','["مطاعم"]','["food"]','دا باو في حي الروضة بجدة وجهة لعشاق الطعم الآسيوي، يقدم أطباقاً آسيوية متنوعة بطريقة مبتكرة وشهية في برج روفان.','<div class="texte" > <p>دا باو في حي الروضة بجدة وجهة لعشاق الطعم الآسيوي، يقدم أطباقاً آسيوية متنوعة بطريقة مبتكرة وشهية، ويقع في برج روفان على طريق الأمير سعود الفيصل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070867-68544690.jpg?v=1791551055", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070867-68544691.jpg?v=1791551064"]','https://cmsphoto.ww-cdn.com/resizeapi/f1de2a768b3d5e7e39dabf08fa46bbe2bc4807bb/480/',21.5620506,39.161459,'برج روفان، طريق الأمير سعود الفيصل، الروضة، جدة 23433','0565161760','','','https://www.saudi-guide.com/jeddah/i/98070867/da-bao-da-bao',1,0,'دا باو da bao مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070866,'jeddah','جو','Jaw','jaw-go','["مطاعم"]','["food"]','جو مطعم ومقهى يقدم أطباق عربية شهية بأجواء دافئة يملؤها الطابع المنزلي. يشتهر بالتيراميسو اللذيذ والكرك المميز، ويحظى بأمسيات موسيقية حية مع مطرب.','<div class="texte" > <p>جو مطعم ومقهى يقدم أطباق عربية شهية بأجواء دافئة يملؤها الطابع المنزلي. يشتهر بالتيراميسو اللذيذ والكرك المميز، ويحظى بأمسيات موسيقية حية مع مطرب، ويتطلب حجزًا مسبقًا بحد أدنى للطلب. للتواصل: 0562101019، ومواعيد الدوام من 8:00 مساءً حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070866-68544701.jpg?v=1791551117", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070866-68544703.jpg?v=1791551124"]','https://cmsphoto.ww-cdn.com/resizeapi/cdf65691ccb9b8ca2affb9738fd246181ca8dfd9/480/',21.5470653,39.1383153,'طريق الأمير محمد بن عبدالعزيز، الأندلس، جدة 23322','0562101019','','','https://www.saudi-guide.com/jeddah/i/98070866/jaw-go',1,0,'جو jaw مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070865,'jeddah','لا كايي','La Calle','la-calle-la-kayy','["مطاعم"]','["food"]','لا كايي يقدم قائمة واسعة ومتنوعة من الأطباق الشهية لأصحاب الذوق المختلف وسط أجواء رائعة. يشتهر بالباييلا بالمأكولات البحرية والروبيان بالواسابي وقطع اللوبستر.','<div class="texte" > <p>لا كايي يقدم قائمة واسعة ومتنوعة من الأطباق الشهية لأصحاب الذوق المختلف وسط أجواء رائعة. يشتهر بالباييلا بالمأكولات البحرية والروبيان بالواسابي وقطع اللوبستر، ويحظى بتقييمات ممتازة جدًا كواحد من أفضل المطاعم الإسبانية في جدة. للتواصل: 0562861562، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 ظهرًا ومن 2:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070865-68551906.jpg?v=1791635350"]','https://cmsphoto.ww-cdn.com/resizeapi/603942e1586d564ce75ac679472fd04348d93a12/480/',21.5537993,39.1431247,'طريق الأمير سلطان، مبنى لينك بي، الطابق الأول، الروضة، جدة 23431','0562861562','','','https://www.saudi-guide.com/jeddah/i/98070865/la-calle-la-kayy',1,0,'لا كايي la calle مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98070864,'jeddah','بلو اوشن','Blue Ocean','blue-ocean-blo-aoshn','["مطاعم"]','["food"]','بلو اوشن مطعم يتميز بإطلالة باهرة على البحر يتنوع بقائمة مأكولات متنوعة تشمل المأكولات الأمريكية والبحرية. يشتهر بلفافة الفطور وأومليت فاهيتا الستيك.','<div class="texte" > <p>بلو اوشن مطعم يتميز بإطلالة باهرة على البحر يتنوع بقائمة مأكولات متنوعة تشمل المأكولات الأمريكية والبحرية. يشتهر بلفافة الفطور وأومليت فاهيتا الستيك، ويحظى بخدمة ودودة وأسعار معقولة بالنظر للموقع والجودة. للتواصل: 0533056605، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070864-68544719.jpg?v=1791551223", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98070864-68544720.jpg?v=1791551228"]','https://cmsphoto.ww-cdn.com/resizeapi/2f6b9546ffa0d4e331647ce35f34e5171baacd1a/480/',21.5722175,39.109369,'طريق الكرنيش الفرعي، الشاطئ، جدة 23413','0533056605','','','https://www.saudi-guide.com/jeddah/i/98070864/blue-ocean-blo-aoshn',1,0,'بلو اوشن blue ocean مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069500,'asir-region','شندل','Shandal','shandal-shndl','["مطاعم"]','["food"]','شندل أصالة الأكل الحجازي والخليجي بتقديم عصري يعود بك نحو المنازل الحجازية القديمة، بإطلالة رائعة على مساحة خضراء تشبه المزرعة.','<div class="texte" > <p>شندل أصالة الأكل الحجازي والخليجي بتقديم عصري يعود بك نحو المنازل الحجازية القديمة، بإطلالة رائعة على مساحة خضراء تشبه المزرعة. يشتهر بالحلوم والحمص وأطباق الكباب المميزة، ويحظى بتقييمات ممتازة لأسعاره المناسبة وجودة الطعام. للتواصل: 0530309988، ومواعيد الدوام من 5:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069500-68546917.jpg?v=1791565910", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069500-68546918.jpg?v=1791565920"]','https://cmsphoto.ww-cdn.com/resizeapi/08fba292c3f2020300c8d328e0e54b37c117764e/480/',18.2310601,42.4984036,'حي الوردتين، أبها 62521','0530309988','','','https://www.saudi-guide.com/asir-region/i/98069500/shandal-shndl',1,0,'شندل shandal مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98069499,'asir-region','كريفنج كلوب','Craving Club','craving-club-kryfng-klob','["مطاعم"]','["food"]','لمحبي المأكولات الأمريكية، يتميز بأطباق اللحوم المتنوعة وسط أجواء وإطلالة مميزة على المدينة. مطعم مميز.','<div class="texte" > <p>كريفنج كلوب لمحبي المأكولات الأمريكية، يتميز بأطباق اللحوم المتنوعة وسط أجواء وإطلالة مميزة على المدينة. يشتهر بالستيك المطهو بإتقان وأطباق البرجر الفاخرة، ويحظى بتقييمات ممتازة جدًا لجودة الطعام والخدمة الاحترافية. للتواصل: 0541660256، ومواعيد الدوام من 11:00 صباحًا حتى 3:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069499-68546922.jpg?v=1791565994", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98069499-68546924.jpg?v=1791566015"]','https://cmsphoto.ww-cdn.com/resizeapi/319109cac6b0c57512948067a66c5bed9a02b73b/480/',18.2908305,42.6808486,'طريق الملك فهد، خميس مشيط 62432','0541660256','','','https://www.saudi-guide.com/asir-region/i/98069499/craving-club-kryfng-klob',1,0,'كريفنج كلوب craving club مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060957,'asir-region','تونير','Tonir','tonir-tonyr','["مطاعم"]','["food"]','تونير أصل المذاق الأرميني يقدم قائمة واسعة من الأطباق الأرمينية الأصيلة كالكباب المتبل والباذنجان باللحم.','<div class="texte" > <p>تونير أصل المذاق الأرميني يقدم قائمة واسعة من الأطباق الأرمينية الأصيلة كالكباب المتبل والباذنجان باللحم. يحظى بتقييمات عالية جدًا لجودة الطعام وأجوائه الأنيقة، ويُعد كنزًا مخفيًا يستحق الزيارة رغم بعده النسبي عن وسط المدينة. للتواصل: 0537703732، ومواعيد الدوام من 1:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060957-68546934.jpg?v=1791566076", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060957-68546935.jpg?v=1791566095"]','https://cmsphoto.ww-cdn.com/resizeapi/f0266ecbfa7bc98f3f8d8be0288d786034d0c14b/480/',18.2549086,42.6306833,'طريق الملك فهد، أبها 62437','0537703732','','','https://www.saudi-guide.com/asir-region/i/98060957/tonir-tonyr',1,0,'تونير tonir مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060956,'asir-region','مطعم دوما بالاس','Duma Palace','duma-palace-mtaam-doma-balas','["مطاعم"]','["food"]','مطعم دوما بالاس استمتع بقائمة متنوعة من أشهى المأكولات وسط أجواء ساحرة حيث تمتزج الفخامة بالذوق في خميس مشيط.','<div class="texte" > <p>مطعم دوما بالاس استمتع بقائمة متنوعة من أشهى المأكولات وسط أجواء ساحرة حيث تمتزج الفخامة بالذوق في خميس مشيط. يحظى بخدمة ضيافة استثنائية من الموظفين، ويُعد وجهة موثوقة للمناسبات العائلية بفضل جودة الطعام وحسن الاستقبال. للتواصل: 0537044004، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060956-68546938.jpg?v=1791566176", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060956-68546940.jpg?v=1791566194"]','https://cmsphoto.ww-cdn.com/resizeapi/184e170fbea2e7ace4ca10e0ad25ea711d6b2de1/480/',18.295653,42.7028013,'الإمام محمد بن سعود، خميس مشيط 62432','0537044004','','','https://www.saudi-guide.com/asir-region/i/98060956/duma-palace-mtaam-doma-balas',1,0,'مطعم دوما بالاس duma palace مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060955,'asir-region','مطعم والونج سرايا خيال','Walwang Saraya Khayal','walwang-saraya-khayal-mtaam-oalong-sraya-khyal','["مطاعم"]','["food"]','يتميز بتقديم المأكولات العربية بجانب قائمة واسعة من المأكولات الشهية المتنوعة لترضي ذائقتك. مطعم فاخر.','<div class="texte" > <p>مطعم والونج سرايا خيال يتميز بتقديم المأكولات العربية بجانب قائمة واسعة من المأكولات الشهية المتنوعة لترضي ذائقتك. يشتهر بلحمه الطري المتبل بإتقان وسلطة الفتوش المنعشة، بأسعار معقولة وخدمة ودودة من الطاقم. للتواصل: 0532425000، ومواعيد الدوام من 11:30 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060955-68546942.jpg?v=1791566261", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060955-68546945.jpg?v=1791566276"]','https://cmsphoto.ww-cdn.com/resizeapi/1f9d8f04a3d5029cf8b65d76a42d5bfe0ab78e17/480/',18.2309097,42.5495683,'طريق الملك فهد الفرعي، العارن، أبها 62528','0532425000','','','https://www.saudi-guide.com/asir-region/i/98060955/walwang-saraya-khayal-mtaam-oalong-sraya-khyal',1,0,'مطعم والونج سرايا خيال walwang saraya khayal مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060954,'asir-region','زورنا','Zurna','zurna-zorna','["مطاعم"]','["food"]','زورنا مطعم عصري يمزج بين الأطباق التركية واللبنانية والأرمينية لتحظى بتجربة مميزة، يقع في الطابق الثالث من فندق سيتادين.','<div class="texte" > <p>زورنا مطعم عصري يمزج بين الأطباق التركية واللبنانية والأرمينية لتحظى بتجربة مميزة، يقع في الطابق الثالث من فندق سيتادين. يشتهر بشوربة الكريمة والحمص وطاووق الدجاج، مع شوت ليمون ترحيبي مجاني، وجلسات خارجية مريحة للمدخنين وغيرهم. للتواصل: 0543779024، ومواعيد الدوام من 6:30 صباحًا حتى 10:30 صباحًا ومن 12:00 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060954-68546951.jpg?v=1791566341", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060954-68546952.jpg?v=1791566366"]','https://cmsphoto.ww-cdn.com/resizeapi/3aed1359c7f6335218d4226331220d926f9445f2/480/',18.2407228,42.6070088,'طريق الملك فهد، المزوين، أبها 62583','0543779024','','','https://www.saudi-guide.com/asir-region/i/98060954/zurna-zorna',1,0,'زورنا zurna مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060953,'asir-region','لا سين','La Scene','la-scene-la-syn','["مطاعم"]','["food"]','لا سين تجربة مميزة تتذوق من خلالها أشهى الأطباق المتنوعة والحلويات والمخبوزات الطازجة ضمن مجمع الجوري إيليت.','<div class="texte" > <p>لا سين تجربة مميزة تتذوق من خلالها أشهى الأطباق المتنوعة والحلويات والمخبوزات الطازجة ضمن مجمع الجوري إيليت. يقدم أطباقًا عالمية متنوعة بأجواء أنيقة، ويُعد الخيار الثالث ضمن المجمع لمن يبحث عن تنوع أكبر في نفس الموقع. للتواصل: 0542773280، ومواعيد الدوام من 9:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060953-68546955.jpg?v=1791566446", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060953-68546956.jpg?v=1791566465"]','https://cmsphoto.ww-cdn.com/resizeapi/e5ad378399aa4b229aa6da4865ca0e3ca5f80a39/480/',18.2002538,42.4992173,'طريق الملك عبدالعزيز، الشفا، أبها 65251','0542773280','','','https://www.saudi-guide.com/asir-region/i/98060953/la-scene-la-syn',1,0,'لا سين la scene مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060950,'asir-region','لوفوياج','Le Voyage','le-voyage-lofoyag','["مطاعم"]','["food"]','لوفوياج تجربة مميزة لعشاق الأجواء الفاخرة يتميز بتقديم قائمة واسعة من الأطباق الشهية المبتكرة كالريزوتو والمقبلات الباردة المتنوعة.','<div class="texte" > <p>لوفوياج تجربة مميزة لعشاق الأجواء الفاخرة يتميز بتقديم قائمة واسعة من الأطباق الشهية المبتكرة كالريزوتو والمقبلات الباردة المتنوعة. يشتهر بأجواء هادئة ومريحة وخدمة استقبال راقية، ويحظى بتقييمات ممتازة كأحد أفضل المطاعم الفاخرة رغم أسعاره المرتفعة نسبيًا. للتواصل: 0500332559، ومواعيد الدوام من 1:00 ظهرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060950-68546958.jpg?v=1791566525", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060950-68546959.jpg?v=1791566535"]','https://cmsphoto.ww-cdn.com/resizeapi/df1cd484b677f3c1f97b16844bb55d8eaffb6298/480/',18.2149107,42.6032091,'طريق الملك فهد، المزوين، أبها 62582','0500332559','','','https://www.saudi-guide.com/asir-region/i/98060950/le-voyage-lofoyag',1,0,'لوفوياج le voyage مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060949,'asir-region','جوي فينيو','Joy Venue','joy-venue-goy-fynyo','["مطاعم"]','["food"]','جوي فينيو مطعم بجلسات مشرفة على منحدرات تهامة وإطلالة خلابة، يقدم وجبات متنوعة ومميزة ويُعد خيارًا رائعًا للاحتفالات العائلية.','<div class="texte" > <p>جوي فينيو (Joy Venue) يقدم العديد من الوجبات المتنوعة والمميزة في جلسات مشرفة على منحدرات تهامة بإطلالة خلابة. يوفر بطانيات للجلسات الخارجية الباردة، ويحظى بخدمة استثنائية وطعام لذيذ يجعله من أفضل الأماكن للاحتفالات العائلية. للتواصل: 0551956675، ومواعيد الدوام من 8:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060949-68546964.jpg?v=1791566644", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060949-68546965.jpg?v=1791566658"]','https://cmsphoto.ww-cdn.com/resizeapi/2c597dd8d2887647cf721943fe2c82d16e60879c/480/',18.1969238,42.5075898,'شارع بيض، الدباب، أبها 62522','0551956675','','','https://www.saudi-guide.com/asir-region/i/98060949/joy-venue-goy-fynyo',1,0,'جوي فينيو joy venue مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060948,'asir-region','على بالي كافيه','Aala Bali','aala-bali-aala-baly-kafyh','["مطاعم"]','["food"]','على بالي كافيه مطعم يتميز بتنوع أطباقه التي تقدم أشهى المأكولات اللبنانية بطابعها الفريد، ويقع ضمن مجمع الجوري إيليت بإطلالة على حديقة جميلة.','<div class="texte" > <p>على بالي كافيه مطعم يتميز بتنوع أطباقه التي تقدم أشهى المأكولات اللبنانية بطابعها الفريد، ويقع ضمن مجمع الجوري إيليت بإطلالة على حديقة جميلة. يشتهر بموظفيه الودودين خصوصًا الفريق الفلبيني، ويُعد وجهة مفضلة لمحبي المطبخ اللبناني الأصيل. للتواصل: 0542773278، ومواعيد الدوام من 7:00 صباحًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060948-68546968.jpg?v=1791566733", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060948-68546969.jpg?v=1791566747"]','https://cmsphoto.ww-cdn.com/resizeapi/3364f9fc528ab9b08ea2b089ef143fcf9d852bb9/480/',18.2002538,42.4992173,'طريق الملك عبدالعزيز، الشفا، أبها 65251','0542773278','','','https://www.saudi-guide.com/asir-region/i/98060948/aala-bali-aala-baly-kafyh',1,0,'علي بالي كافيه aala bali مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060946,'asir-region','الجوري ايليت','Jorry Elite','jorry-elite-algory-aylyt','["مطاعم"]','["food"]','الجوري ايليت يقدم أصنافًا متعددة من الأطباق العالمية المليئة باللذة وسط مساحات خضراء وضباب كثيف بإطلالة مرتفعة ساحرة.','<div class="texte" > <p>الجوري ايليت يقدم أصنافًا متعددة من الأطباق العالمية المليئة باللذة وسط مساحات خضراء وضباب كثيف بإطلالة مرتفعة ساحرة. يشتهر بديكوره الأنيق وموظفيه المحترفين، ويحظى بتقييمات ممتازة كأحد أفضل المطاعم في أبها منذ سنوات طويلة، رغم أسعاره المرتفعة نسبيًا. للتواصل: 0542773279، ومواعيد الدوام من 7:00 صباحًا حتى 11:00 صباحًا ومن 12:30 ظهرًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060946-68552007.jpg?v=1791636312", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060946-68552008.jpg?v=1791636325"]','https://cmsphoto.ww-cdn.com/resizeapi/2f6c54b795c04c8d07ea3e82c705192a87fddd74/480/',18.2002538,42.4992173,'طريق الملك عبدالعزيز، الشفا، أبها 65251','0542773279','','','https://www.saudi-guide.com/asir-region/i/98060946/jorry-elite-algory-aylyt',1,0,'جوري ايليت jorry elite مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060939,'asir-region','سدف','Sadaf','sadaf-sdf','["مطاعم"]','["food"]','سدف تجربة الأطباق التراثية المحلية بنكهة عصرية مميزة، يجمع بين الطابع القديم واللمسة العصرية بأجواء أنيقة ومريحة.','<div class="texte" > <p>سدف تجربة الأطباق التراثية المحلية بنكهة عصرية مميزة، يجمع بين الطابع القديم واللمسة العصرية بأجواء أنيقة ومريحة. يشتهر بتنوع أطباقه وقهوته الجيدة، ويحظى بشعبية كبيرة تستدعي الحجز المسبق لتفادي الانتظار. يعمل على مدار الساعة معظم أيام الأسبوع.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060939-68546974.jpg?v=1791566911", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060939-68546976.jpg?v=1791566923"]','https://cmsphoto.ww-cdn.com/resizeapi/29f0e1d59bb7ca27bf673634db58382ee8a6576c/480/',18.2337427,42.5062125,'طريق الملك عبدالعزيز، الشرفية، أبها 62542','','','','https://www.saudi-guide.com/asir-region/i/98060939/sadaf-sdf',1,0,'سدف sadaf مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060937,'asir-region','حصن أبها التراثي','Abha Fort Heritage Restaurant','abha-fort-heritage-restaurant-hsn-abha-altrathy','["مطاعم"]','["food"]','حصن أبها التراثي يعود بك إلى حقبة زمنية قديمة للتراث السعودي الأصيل ليقدم أطباقًا شعبية شهية، ويقع بجانب قلعة أبها التاريخية والجسر العثماني القديم.','<div class="texte" > <p>حصن أبها التراثي يعود بك إلى حقبة زمنية قديمة للتراث السعودي الأصيل ليقدم أطباقًا شعبية شهية، ويقع بجانب قلعة أبها التاريخية والجسر العثماني القديم. يشتهر بحساء اللحم ولبن الريف، ويشهد ازدحامًا كبيرًا في موسم السياحة يصل أحيانًا لساعتين انتظار، فيُنصح بزيارته في أوقات أقل ازدحامًا. للتواصل: 0543470968، ومواعيد الدوام من 7:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060937-68546983.jpg?v=1791566997", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060937-68546984.jpg?v=1791567008"]','https://cmsphoto.ww-cdn.com/resizeapi/735231f640bff4a379fb1972a737d94f4aaeac1b/480/',18.2197014,42.4978857,'وسط المدينة، أبها 62521','0543470968','','','https://www.saudi-guide.com/asir-region/i/98060937/abha-fort-heritage-restaurant-hsn-abha-altrathy',1,0,'حصن ابها تراثي abha fort heritage restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060934,'asir-region','مطعم علي رمزي','Ali Ramzi Restaurant','ali-ramzi-restaurant-mtaam-aaly-rmzy','["مطاعم"]','["food"]','مطعم علي رمزي متعة الأكل الجنوبي بكل أبعاده حيث الحنيذ والمندي والمظبي والأطباق المختلفة من اللحوم والأرز.','<div class="texte" > <p>مطعم علي رمزي متعة الأكل الجنوبي بكل أبعاده حيث الحنيذ والمندي والمظبي والأطباق المختلفة من اللحوم والأرز. يشتهر بحنيذ اللحم الطري بنكهته الأصيلة، ويحظى بشعبية جيدة رغم بعض الملاحظات على ضرورة تحسين تنظيم صف الانتظار. للتواصل: 0556603335، ومواعيد الدوام من 12:00 ظهرًا حتى 10:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060934-68546990.jpg?v=1791567125", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060934-68546991.jpg?v=1791567142"]','https://cmsphoto.ww-cdn.com/resizeapi/037edda07da1cf22a69a64672b103d9d95c499b6/480/',18.2118792,42.4979281,'شارع الملك سعود، غرب البنك الأهلي، المفتاحة، أبها 62521','0556603335','','','https://www.saudi-guide.com/asir-region/i/98060934/ali-ramzi-restaurant-mtaam-aaly-rmzy',1,0,'مطعم علي رمزي ali ramzi restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060933,'asir-region','العريش','Al Areesh','al-areesh-alaarysh','["مطاعم"]','["food"]','العريش وجهة لمحبي أطباق الإفطار الشعبية بالطرق التقليدية بطابع تراثي، ويُعد من المطاعم القليلة المفتوحة صباحًا في المنطقة.','<div class="texte" > <p>العريش وجهة لمحبي أطباق الإفطار الشعبية بالطرق التقليدية بطابع تراثي، ويُعد من المطاعم القليلة المفتوحة صباحًا في المنطقة. يشتهر بالفول والشكشوكة العدنية والكبسة، وتقدم وجبات إفطار رمضانية غنية خلال الشهر الفضيل. مواعيد الدوام من 6:00 صباحًا حتى 3:00 عصرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060933-68551999.jpg?v=1791636200", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060933-68552000.jpg?v=1791636209"]','https://cmsphoto.ww-cdn.com/resizeapi/da0e55227632f7425c7909b5b46d0cf1a02bafc5/480/',18.208992,42.4909858,'طريق الملك عبدالعزيز، المفتاحة، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98060933/al-areesh-alaarysh',1,0,'عريش al areesh مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060932,'asir-region','المجلس الخليجي','Al Majlis Al Khaleeji','al-majlis-al-khaleeji-almgls-alkhlygy','["مطاعم"]','["food"]','المجلس الخليجي مطعم بطراز تراثي مفعم بعبق الماضي، يقدم أطباقًا خليجية شعبية أصيلة كالمقلوبة والمجبوس بديكور يعكس الضيافة.','<div class="texte" > <p>المجلس الخليجي تجربة تراثية ما بين الأطباق الشعبية الغنية والمتنوعة بطراز مفعم بعبق الماضي. يقدم أطباقًا خليجية أصيلة كالمقلوبة والمجبوس بديكور يعكس الضيافة التقليدية. للتواصل: 920009533، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060932-68546999.jpg?v=1791567266"]','https://cmsphoto.ww-cdn.com/resizeapi/18c27afcb08a136ed1c0dc466afbdfc3c871fdde/480/',18.2230626,42.5788892,'حي الصفا، أبها 62581','920009533','','','https://www.saudi-guide.com/asir-region/i/98060932/al-majlis-al-khaleeji-almgls-alkhlygy',1,0,'مجلس خليجي al majlis al khaleeji مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060930,'asir-region','حنيذ ملة','Haneeth Mala','haneeth-mala-hnyth-ml','["مطاعم"]','["food"]','حنيذ ملة مطعم يقدم الحنيذ والمظبي والمضغوط مع أرز البشاور والإيدامات الشهية والمقبلات، ويشتهر بحنيذ اللحم والدجاج.','<div class="texte" > <p>حنيذ ملة مطعم متنوع من الحنيذ والمظبي والمضغوط وأنواع الايدامات الشهية والمقبلات المتنوعة. يشتهر بحنيذ اللحم والدجاج المقدم مع أرز البشاور والسلطات المتنوعة، ويعمل بنظام الطلبات الخارجية بشكل أساسي. للتواصل: 0535513666، ومواعيد الدوام من 12:30 ظهرًا حتى 12:30 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060930-68547004.jpg?v=1791567343", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060930-68547009.jpg?v=1791567369"]','https://cmsphoto.ww-cdn.com/resizeapi/eb99972448f87fac0b6ff54f463570da1d417eab/480/',18.2777142,42.5930959,'المحالة، أبها 62564','0535513666','','','https://www.saudi-guide.com/asir-region/i/98060930/haneeth-mala-hnyth-ml',1,0,'حنيذ مله haneeth mala مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060929,'asir-region','باب التراث','Bab Al Turath','bab-al-turath-bab-altrath','["مطاعم"]','["food"]','باب التراث المطبخ السعودي الأصيل من المثلوثة والجريش إلى المرقوق والمقلوبة، بديكور تراثي يضم كبائن جلوس أرضية تقليدية.','<div class="texte" > <p>باب التراث المطبخ السعودي الأصيل من المثلوثة والجريش إلى المرقوق والمقلوبة، بديكور تراثي يضم كبائن جلوس أرضية تقليدية. يشتهر بأطباق الأرز السخية الكمية والجودة، ويحظى بخدمة سريعة تجعله وجهة موثوقة لتجربة المطبخ السعودي الأصيل. للتواصل: 0552281500، ومواعيد الدوام من 11:30 صباحًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060929-68547017.jpg?v=1791567438", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060929-68547018.jpg?v=1791567450"]','https://cmsphoto.ww-cdn.com/resizeapi/d5c0d97640f20a5d755c4db171d2cfbee005dfcd/480/',18.208706,42.4909158,'طريق الملك عبدالعزيز، المفتاحة، أبها 62521','0552281500','','','https://www.saudi-guide.com/asir-region/i/98060929/bab-al-turath-bab-altrath',1,0,'باب تراث bab al turath مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060898,'asir-region','مجمع شرفة بوليفارد','Shurfa Boulevard','shurfa-boulevard-mgmaa-shrf-bolyfard','["أماكن سياحية"]','["sights"]','إطلالة هادئة تشرف بك على طريق الحزام الدائري لمدينة أبها متضمنًا خيارات من المقاهي والمطاعم. مجمع مطاعم ومقاهي.','<div class="texte" > <p>مجمع شرفة بوليفارد إطلالة هادئة تشرف بك على طريق الحزام الدائري لمدينة أبها متضمنًا خيارات من المقاهي والمطاعم. يُعد مكانًا لطيفًا للقاء الأصدقاء وتناول القهوة، رغم حاجة بعض المحال لتحسينات كإضافة غرف قياس، وهو خيار بسيط ومريح للاستراحة أثناء التجول في المدينة.</p> </div>','[]','',18.2099175,42.4900132,'طريق الملك عبدالعزيز، أبها الجديدة، أبها 62512','','','','https://www.saudi-guide.com/asir-region/i/98060898/shurfa-boulevard-mgmaa-shrf-bolyfard',1,0,'مجمع شرفه بوليفارد shurfa boulevard اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060895,'asir-region','جاردن سكوير','Abha Garden Square','abha-garden-square-gardn-skoyr','["أماكن سياحية"]','["sights"]','ستحظى بلحظة تسوق جميلة مع أفراد أسرتك لتستمتع بالعديد من خيارات المطاعم والمقاهي والمخبوزات الطازجة. مجمع مطاعم ومقاهي.','<div class="texte" > <p>جاردن سكوير ستحظى بلحظة تسوق جميلة مع أفراد أسرتك لتستمتع بالعديد من خيارات المطاعم والمقاهي والمخبوزات الطازجة. يقع على طريق الحزام الدائري ويجمع مساحات صغيرة أنيقة للمطاعم، رغم بعض الملاحظات على مواقف السيارات المحدودة وارتفاع الأسعار في بعض المحال. مواعيد الدوام من 6:00 صباحًا حتى 12:30 فجرًا.</p> </div>','[]','',18.2312257,42.4984777,'الحزام الدائري، الورداتين، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98060895/abha-garden-square-gardn-skoyr',1,0,'جاردن سكوير abha garden square اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060894,'asir-region','رفالا بلازا','Rafala Plaza','rafala-plaza-rfala-blaza','["أماكن سياحية"]','["sights"]','يضم العديد من المقاهي المختلفة والمطاعم المميزة بجانب سوبرماركت وبعض العلامات التجارية ليكون وجهتك المثالية. مجمع مطاعم ومقاهي.','<div class="texte" > <p>رفالا بلازا يضم العديد من المقاهي المختلفة والمطاعم المميزة بجانب سوبرماركت وبعض العلامات التجارية ليكون وجهتك المثالية. يتوفر فيه دانوب وصالة جيمز جولد للياقة إلى جانب مطاعم متنوعة كأصل البرجر وبسكن روبنز. للتواصل: 0554930949، ومواعيد الدوام من 7:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060894-68547039.jpg?v=1791567761"]','https://cmsphoto.ww-cdn.com/resizeapi/ffafa14474105065c957ca204f928beb15076197/480/',18.2285614,42.5441156,'طريق الملك فهد، العارن، أبها 62528','0554930949','','','https://www.saudi-guide.com/asir-region/i/98060894/rafala-plaza-rfala-blaza',1,0,'رفالا بلازا rafala plaza اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060892,'asir-region','الغنيم سكوير','Al Ghoneim Square','al-ghoneim-square-alghnym-skoyr','["أماكن سياحية"]','["sights"]','ستحظى بلحظة تسوق جميلة مع أفراد أسرتك لتستمتع بالعديد من خيارات التسوق والمطاعم الخليجية. مجمع مطاعم ومقاهي.','<div class="texte" > <p>الغنيم سكوير ستحظى بلحظة تسوق جميلة مع أفراد أسرتك لتستمتع بالعديد من خيارات التسوق والمطاعم الخليجية. يضم محال متنوعة كأديداس وسوبرماركت طازج يوميًا، ويتميز بأسعار معقولة وطاقم استقبال ودود، ما يجعله وجهة عملية للتسوق اليومي في خميس مشيط. مواعيد الدوام من 8:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060892-68547048.jpg?v=1791567861"]','https://cmsphoto.ww-cdn.com/resizeapi/c5a5aca0386ec5700b1d43ddd499e382bb60074b/480/',18.2776385,42.7247828,'الشفا، خميس مشيط 62433','','','','https://www.saudi-guide.com/asir-region/i/98060892/al-ghoneim-square-alghnym-skoyr',1,0,'غنيم سكوير al ghoneim square اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060891,'asir-region','أرض القهوة','Abha Coffee Land','abha-coffee-land-ard-alkho','["أماكن سياحية"]','["sights"]','ستقابلك رائحة القهوة التي تطغى على المكان ضمن مجمع يحوي أشهر علامات القهوة التجارية العالمية. مجمع مطاعم ومقاهي.','<div class="texte" > <p>أرض القهوة ستقابلك رائحة القهوة التي تطغى على المكان ضمن مجمع يحوي أشهر علامات القهوة التجارية العالمية كستاربكس ودانكن دونتس بجانب مقاهي محلية. يتميز بمساحات جلوس خارجية جميلة (تراس) لكل مقهى، ويشهد إقبالًا مسائيًا كبيرًا يجعل مواقفه مزدحمة أحيانًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060891-68547054.jpg?v=1791567950"]','https://cmsphoto.ww-cdn.com/resizeapi/62b1c1ac4bf45b8e74b27c98ac17ddb995a9d7a6/480/',18.2312168,42.4928091,'القرى، أبها 62541','','','','https://www.saudi-guide.com/asir-region/i/98060891/abha-coffee-land-ard-alkho',1,0,'ارض قهوه abha coffee land اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060889,'asir-region','أبها بارك','Abha Park','abha-park-abha-bark','["أماكن سياحية"]','["sights"]','مبانٍ عصرية تحاكي أحدث التصاميم حيث يتوفر بها عدة مطاعم بأيدٍ سعودية ومقاهي متنوعة. مجمع مطاعم ومقاهي.','<div class="texte" > <p>أبها بارك مبانٍ عصرية تحاكي أحدث التصاميم حيث يتوفر بها عدة مطاعم بأيدي سعودية ومقاهي متنوعة كمخبز باتر الشهير. يزيّن المكان نافورة راقصة تتحرك على أنغام الموسيقى، مع منطقة ألعاب داخلية للأطفال، ويحظى بأجواء رائعة تجمع العائلات والأصدقاء. للتواصل: 0598068684، ويعمل على مدار الساعة.</p> </div>','[]','',18.2130848,42.6556776,'طريق الميه، أبها 62561','0598068684','','','https://www.saudi-guide.com/asir-region/i/98060889/abha-park-abha-bark',1,0,'ابها بارك abha park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060888,'asir-region','أبها فيو','Abha View','abha-view-abha-fyo','["أماكن سياحية"]','["sights"]','موقع مميز مطل على الطريق الرابط بين أبها وخميس مشيط يضم العديد من المطاعم والمقاهي ومحلات للحيوانات الأليفة. مجمع مطاعم ومقاهي.','<div class="texte" > <p>أبها فيو موقع مميز مطل على الطريق الرابط بين أبها وخميس مشيط، يضم العديد من المطاعم والمقاهي ومحلات للحيوانات الأليفة. يُعد وجهة صيفية شهيرة يقصدها الزوار للاستمتاع بالمناظر والأجواء الباردة، ويحظى بشعبية كبيرة كأحد أفضل الأماكن الترفيهية في المنطقة. مواعيد الدوام من 7:00 صباحًا حتى 2:00 فجرًا.</p> </div>','[]','',18.2389243,42.5815567,'6407 طريق الملك فهد الفرعي، المحالة، أبها 62561','','','','https://www.saudi-guide.com/asir-region/i/98060888/abha-view-abha-fyo',1,0,'ابها فيو abha view اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060854,'asir-region','سوق العقبة','','souq-al-aqabah','["أسواق"]','["shopping"]','سوق شعبي قديم يحوي العديد من المحال التجارية لبيع المفروشات كما يضم العديد من الخزفيات والفخار. تناقص عدد محاله المفتوحة مع مرور الوقت، لكنه لا يزال يحتفظ بطابعه الشعبي وبعض المحال التي تقدم أسعارًا مناسبة لمستلزمات المنزل.','<div class="texte" > <p>سوق العقبة سوق شعبي قديم يحوي العديد من المحال التجارية لبيع المفروشات كما يضم العديد من الخزفيات والفخار. تناقص عدد محاله المفتوحة مع مرور الوقت، لكنه لا يزال يحتفظ بطابعه الشعبي وبعض المحال التي تقدم أسعارًا مناسبة لمستلزمات المنزل. للتواصل: 0534963800.</p> </div>','[]','',18.2046217,42.5140231,'المدينة المنورة، الثيرة، أبها 62521','0534963800','','','https://www.saudi-guide.com/asir-region/i/98060854/souq-al-aqabah',1,0,'سوق عقبه اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060853,'asir-region','سوق محايل الشعبي','Mahayil Popular Market','mahayil-popular-market-sok-mhayl-alshaaby','["أسواق"]','["shopping"]','سوق محايل الشعبي يحافظ على النمط القديم للسوق الشعبي محتضنًا خيارات واسعة من منتجات الحرف اليدوية والمنتجات الزراعية.','<div class="texte" > <p>سوق محايل الشعبي يحافظ على النمط القديم للسوق الشعبي محتضنًا خيارات واسعة من منتجات الحرف اليدوية والمنتجات الزراعية. يقع في مدينة صغيرة بمناخ لطيف شتاءً وحار صيفًا، ويُعد وجهة موثوقة لأسعار مناسبة للمنتجات المحلية. للتواصل: 0559667486، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060853-68547083.jpg?v=1791568299"]','https://cmsphoto.ww-cdn.com/resizeapi/2883c2aed043ef6c432ce62ffbd1e64339735c1b/480/',18.5467067,42.0481918,'البلد، محايل عسير 63711','0559667486','','','https://www.saudi-guide.com/asir-region/i/98060853/mahayil-popular-market-sok-mhayl-alshaaby',1,0,'سوق محايل شعبي mahayil popular market اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060852,'asir-region','سوق الجمعة','Al Jumaa Market','al-jumaa-market-sok-algmaa','["أسواق"]','["shopping"]','سوق الجمعة في أحد الأحياء القديمة لمحافظة الوادين يعرض خيارات واسعة من الملابس الشعبية والألعاب والمشغولات اليدوية.','<div class="texte" > <p>سوق الجمعة في أحد الأحياء القديمة لمحافظة الوادين يعرض خيارات واسعة من الملابس الشعبية والألعاب والمشغولات اليدوية. يشتهر ببيع الخضار والفواكه الطازجة مباشرة من المزارعين خصوصًا يوم الجمعة، ما يجعله وجهة مفضلة لعشاق المنتجات المحلية الطازجة. للتواصل: 0533794157، ومواعيد الدوام من 8:00 صباحًا حتى 7:55 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060852-68547093.jpg?v=1791568393"]','https://cmsphoto.ww-cdn.com/resizeapi/9b4a95d0bb5fcc65cbfaff623655593c277f046c/480/',18.0945078,42.8049718,'الوادين 62237','0533794157','','','https://www.saudi-guide.com/asir-region/i/98060852/al-jumaa-market-sok-algmaa',1,0,'سوق جمعه al jumaa market اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060851,'asir-region','بسطة القابل','Bastat Al Qabil','bastat-al-qabil-bst-alkabl','["أسواق"]','["shopping"]','بسطة القابل كنز تاريخي في قلب أبها يظهر جمال المنطقة لتجد نفسك محاطًا بأصالة عسير وتراثها وتستمتع بتجربة تاريخية ثرية بعمرانها الشامخ.','<div class="texte" > <p>بسطة القابل كنز تاريخي في قلب أبها يظهر جمال المنطقة لتجد نفسك محاطًا بأصالة عسير وتراثها وتستمتع بتجربة تاريخية ثرية بعمرانها الشامخ. يضم مقاهي ومطاعم ومحال تحف ومتجر حيوانات، برسوم دخول رمزية للبالغين ومجانية للأطفال، مع أزقة ضيقة تعكس العمارة التراثية الأصيلة. يُفضّل زيارته مساءً لتفادي الازدحام والحر.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060851-68547099.jpg?v=1791568459"]','https://cmsphoto.ww-cdn.com/resizeapi/e9aca54eab1ca2f5783da634e5724c8846dfac5a/480/',18.2201113,42.4981199,'الكورنيش، وسط المدينة، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98060851/bastat-al-qabil-bst-alkabl',1,0,'بسطه قابل bastat al qabil اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060850,'asir-region','سوق الخميس','Al Khamis Market','al-khamis-market-sok-alkhmys','["أسواق"]','["shopping"]','سوق الخميس في أحد الأحياء القديمة لمحافظة خميس مشيط يعرض خيارات واسعة من الخناجر والجنابي والأسلحة القديمة والمشغولات اليدوية.','<div class="texte" > <p>سوق الخميس في أحد الأحياء القديمة لمحافظة خميس مشيط يعرض خيارات واسعة من الخناجر والجنابي والأسلحة القديمة والمشغولات اليدوية. سوق متخصص وصغير جذب هواة اقتناء التحف التراثية، وتتوفر فيه محال بأسعار جيدة خصوصًا من البائعين الباكستانيين والبنغاليين. مواعيد الدوام من 8:00 صباحًا حتى 11:00 مساءً.</p> </div>','[]','',18.3081837,42.7313722,'العرق الشمالي، خميس مشيط 62461','','','','https://www.saudi-guide.com/asir-region/i/98060850/al-khamis-market-sok-alkhmys',1,0,'سوق خميس al khamis market اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060849,'asir-region','سوق البلد','Al Balad Market','al-balad-market-sok-albld','["أسواق"]','["shopping"]','سوق البلد يوفر مساحة للتسوق المتنوع لكل ما تحتاج إليه من المنتجات المحلية والمستوردة، ويُعد من أقدم الأسواق في وسط مدينة أبها.','<div class="texte" > <p>سوق البلد يوفر مساحة للتسوق المتنوع لكل ما تحتاج إليه من المنتجات المحلية والمستوردة، ويُعد من أقدم الأسواق في وسط مدينة أبها. يشتهر بتنوع خياراته وأسعاره المناسبة، ويجذب الزوار الباحثين عن تجربة تسوق شعبية أصيلة. مواعيد الدوام من 9:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>','[]','',18.2171437,42.502409,'وسط المدينة، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98060849/al-balad-market-sok-albld',1,0,'سوق بلد al balad market اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060848,'asir-region','لافاندا بارك','Lavanda Park Mall','lavanda-park-mall-lafanda-bark','["أسواق"]','["shopping"]','من أفضل المراكز التجارية في أبها يضم العديد من العلامات التجارية العالمية والمقاهي كما يتميز بساحات واسعة مزينة بالنوافير. مركز تجاري.','<div class="texte" > <p>لافاندا بارك من أفضل المراكز التجارية في أبها يضم العديد من العلامات التجارية العالمية والمقاهي كما يتميز بساحات واسعة مزينة بالنوافير. يقع في موقع استراتيجي بين أبها وخميس مشيط قرب المطار، ويضم هايبرماركت إكسترا ومحال أزياء متنوعة، ما يجعله وجهة أنيقة راسخة في ذاكرة زواره. للتواصل: 0920009467، ومواعيد الدوام من 9:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060848-68552070.jpg?v=1791636854"]','https://cmsphoto.ww-cdn.com/resizeapi/ba7b6224fe26e1657eaefb82d18f90a18bf1feb3/480/',18.2397786,42.6035307,'طريق الملك فهد، المزوين، أبها 62583','0920009467','','','https://www.saudi-guide.com/asir-region/i/98060848/lavanda-park-mall-lafanda-bark',1,0,'لافاندا بارك lavanda park mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060847,'asir-region','بوليفارد خميس مشيط','KM Boulevard','km-boulevard-bolyfard-khmys-mshyt','["أسواق"]','["shopping"]','بتصميم عصري كمدينة مختلفة يتوسطها نافورة راقصة وأماكن للجلوس والتسوق بالإضافة إلى مطاعم ومقاهي. مركز تجاري.','<div class="texte" > <p>بوليفارد خميس مشيط بتصميم عصري كمدينة مختلفة يتوسطها نافورة راقصة وأماكن للجلوس والتسوق بالإضافة إلى مطاعم ومقاهي متنوعة. يجمع بين الجمال والترفيه والاستجمام في مساحات عصرية واسعة، ويستضيف فعاليات وأنشطة موسمية للعائلات والأفراد. مواعيد الدوام من 7:30 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060847-68547128.jpg?v=1791568759", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060847-68547131.jpg?v=1791568774"]','https://cmsphoto.ww-cdn.com/resizeapi/471c75c51a8733b54f5f2126afc89a80b24c552f/480/',18.2747926,42.7194669,'الشفا، خميس مشيط 62433','','','','https://www.saudi-guide.com/asir-region/i/98060847/km-boulevard-bolyfard-khmys-mshyt',1,0,'بوليفارد خميس مشيط km boulevard اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060846,'asir-region','الواحة مول','Oasis Centre','oasis-centre-aloah-mol','["أسواق"]','["shopping"]','من المراكز التجارية المميزة في المنطقة يضم العديد من العلامات التجارية وصالة ألعاب للأطفال بالإضافة إلى مطعم هندي رائع. مركز تجاري.','<div class="texte" > <p>الواحة مول من المراكز التجارية المميزة في المنطقة يضم العديد من العلامات التجارية كسنتربوينت وماكس وأوثايم بالإضافة إلى مطعم هندي رائع. يوفر منطقة ألعاب للأطفال وصالة صلاة واستراحة، ومواقف سيارات منظمة وواسعة، ما يجعله خيارًا عمليًا للتسوق اليومي. للتواصل: 0583192370، ومواعيد الدوام من 9:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060846-68547146.jpg?v=1791568844"]','https://cmsphoto.ww-cdn.com/resizeapi/fa366dae301303e305c7ac878f3a9eb7ba512626/480/',18.2796657,42.6727121,'طريق الملك فهد، المنهل، أبها 62521','0583192370','','','https://www.saudi-guide.com/asir-region/i/98060846/oasis-centre-aloah-mol',1,0,'واحه مول oasis centre اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060844,'asir-region','أصداف مول','Asdaf Mall','asdaf-mall-asdaf-mol','["أسواق"]','["shopping"]','أصداف مول من المراكز التجارية المميزة للعائلة لكونه يحوي العديد من العلامات التجارية والمقاهي العالمية وصالة ألعاب للأطفال في الطابق الثاني.','<div class="texte" > <p>أصداف مول من المراكز التجارية المميزة للعائلة لكونه يحوي العديد من العلامات التجارية والمقاهي العالمية وصالة ألعاب للأطفال في الطابق الثاني. يضم منطقة طعام مجهزة جيدًا، وإن كانت بعض الأقسام تحتاج تنشيطًا أكبر لجذب زوار أكثر خصوصًا في الطوابق العلوية.</p> </div>','[]','',18.3060326,42.7319648,'العرق الجنوبي، خميس مشيط 62461','','','','https://www.saudi-guide.com/asir-region/i/98060844/asdaf-mall-asdaf-mol',1,0,'اصداف مول asdaf mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060843,'asir-region','موجان بارك','Mujan Park','mujan-park-mogan-bark','["أسواق"]','["shopping"]','من أحدث المراكز التجارية في المنطقة حيث يضم خيارات متعددة للتسوق والألعاب والسينما وهو من المراكز المتجددة. مركز تجاري.','<div class="texte" > <p>موجان بارك من أحدث المراكز التجارية في المنطقة حيث يضم خيارات متعددة للتسوق والألعاب والسينما وهو من المراكز المتجددة باستمرار بعلامات جديدة. يشتهر بتوفير كل الاحتياجات تحت سقف واحد بأجواء أنيقة، رغم بعض الملاحظات على ضيق مواقف السيارات في أوقات الذروة. للتواصل: 0920035121، ومواعيد الدوام من 8:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060843-68547152.jpg?v=1791568992"]','https://cmsphoto.ww-cdn.com/resizeapi/f66989205c51b570d98f3701c7e9fb0111e23c29/480/',18.2851198,42.7400044,'النزهة، خميس مشيط 62465','0920035121','','','https://www.saudi-guide.com/asir-region/i/98060843/mujan-park-mogan-bark',1,0,'موجان بارك mujan park اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060841,'asir-region','الخميس آفينيو','Al Khamis Avenue','al-khamis-avenue-alkhmys-afynyo','["أسواق"]','["shopping"]','من المراكز التجارية المميزة في المنطقة يتضمن علامات عالمية وخيارات للتسوق وألعاب للأطفال ومطاعم ومقاهي. مركز تجاري.','<div class="texte" > <p>الخميس آفينيو من المراكز التجارية المميزة في خميس مشيط، يتضمن علامات عالمية مثل H&amp;M وMothercare وMAC وخيارات متعددة للتسوق وألعاب للأطفال ومطاعم ومقاهي متنوعة. يتميز بمساحته الواسعة ومواقفه الجيدة، ويُعد وجهة مسائية شهيرة لعشاق التسوق في المحافظة. مواعيد الدوام من 9:30 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060841-68547156.jpg?v=1791569079", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060841-68547157.jpg?v=1791569089"]','https://cmsphoto.ww-cdn.com/resizeapi/dbcf599f616b6e9aa7aff3c9a7109a75ed2d74e2/480/',18.2466704,42.7652596,'طريق الملك خالد، الظلالة، خميس مشيط 62411','','','','https://www.saudi-guide.com/asir-region/i/98060841/al-khamis-avenue-alkhmys-afynyo',1,0,'خميس افينيو al khamis avenue اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060840,'asir-region','الراشد مول','Al Rashid Mall','al-rashid-mall-alrashd-mol','["أسواق"]','["shopping"]','أحد الوجهات العائلية يضم تشكيلة من العلامات التجارية الكبرى والمطاعم والمقاهي وصالة السينما ومنطقة ألعاب الأطفال. مركز تجاري.','<div class="texte" > <p>الراشد مول أحد الوجهات العائلية الرائدة في أبها، يضم تشكيلة واسعة من العلامات التجارية الكبرى كزارا وH&amp;M والمطاعم والمقاهي وصالة سينما ومنطقة ألعاب أطفال كبيرة. يتميز بتنظيمه الجيد وموقفه المتعدد الطوابق، ويُعد من أكثر الوجهات موثوقية للتسوق والترفيه العائلي في المنطقة. للتواصل: 0530246140، ومواعيد الدوام من 9:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060840-68547161.jpg?v=1791569173"]','https://cmsphoto.ww-cdn.com/resizeapi/92a361db0635148d3d7ffc0a576580f742652e50/480/',18.2367023,42.579298,'طريق الملك فهد، البديع، أبها 62581','0530246140','','','https://www.saudi-guide.com/asir-region/i/98060840/al-rashid-mall-alrashd-mol',1,0,'راشد مول al rashid mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060794,'asir-region','مزرعة غصن الريفية','Ghusn Rural Farm','ghusn-rural-farm-mzraa-ghsn-alryfy','["أماكن سياحية"]','["sights"]','مزرعة غصن الريفية تتميز بوجود العديد من أنواع الزهور والورود كما تضم محمية للطيور حيث يمكنك الاستمتاع بأجواء ريفية هادئة.','<div class="texte" > <p>مزرعة غصن الريفية تتميز بوجود العديد من أنواع الزهور والورود كما تضم محمية للطيور حيث يمكنك الاستمتاع بأجواء ريفية هادئة. مكان واسع يجمع بين مطعم وبوفيه ومقهى، ما يتيح قضاء وقت طويل دون ملل، وسط أجواء ريفية مريحة ترفع المعنويات. للتواصل: 0562654481، ومواعيد الدوام من 6:00 صباحًا حتى 10:00 مساءً.</p> </div>','[]','',19.1437823,41.9011278,'المجاردة 63941','0562654481','','','https://www.saudi-guide.com/asir-region/i/98060794/ghusn-rural-farm-mzraa-ghsn-alryfy',1,0,'مزرعه غصن ريفيه ghusn rural farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060793,'asir-region','مزرعة التركي للفراولة','AlTurki Farm','alturki-farm-mzraa-altrky-llfraol','["أماكن سياحية"]','["sights"]','يمكنك الاستمتاع برؤية مراحل زراعة الفراولة حتى نضجها، كما تتميز ببيع بعض المنتجات المصنوعة من الفراولة. مزرعة.','<div class="texte" > <p>مزرعة التركي للفراولة تتيح لك الاستمتاع برؤية مراحل زراعة الفراولة حتى نضجها، كما تتميز ببيع بعض المنتجات المصنوعة من الفراولة كالتين المجفف. تجربة رائعة للأطفال يستمتعون فيها بقطف الفراولة وتذوقها طازجة مع الشوكولاتة، بأسعار معقولة وأجواء ودودة. للتواصل: 0552548800، ومواعيد الدوام من 9:00 صباحًا حتى 10:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060793-68547177.jpg?v=1791569345"]','https://cmsphoto.ww-cdn.com/resizeapi/16814d41b7c37b8c9ea596b287e3e6a57ed12d94/480/',18.2318333,42.6095833,'سر الغالض، أبها 62583','0552548800','','','https://www.saudi-guide.com/asir-region/i/98060793/alturki-farm-mzraa-altrky-llfraol',1,0,'مزرعه تركي للفراوله alturki farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060792,'asir-region','مزرعة العاذرية','Al Athiriyah Farm','al-athiriyah-farm-mzraa-alaaathry','["أماكن سياحية"]','["sights"]','مزرعة العاذرية من أفضل المزارع تتميز بمساحاتها الخضراء وتنوع الأزهار حولها وتضم جلسات متنوعة بالإضافة إلى أكشاك لبيع الطعام والمرطبات.','<div class="texte" > <p>مزرعة العاذرية من أفضل المزارع تتميز بمساحاتها الخضراء وتنوع الأزهار حولها وتضم جلسات متنوعة بالإضافة إلى أكشاك لبيع الطعام والمرطبات. تقع في بيشة، ورسوم الدخول رمزية (15 ريالًا للفرد)، مع أجواء هادئة تناسب الاسترخاء أكثر من الأنشطة الترفيهية للأطفال. للتواصل: 0558268572، ومواعيد الدوام من 6:00 صباحًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060792-68547181.jpg?v=1791569440"]','https://cmsphoto.ww-cdn.com/resizeapi/486a234f65ec8be21ce03c341e0c082d600ac9bc/480/',20.0254836,42.6066746,'النخيل، بيشة 67716','0558268572','','','https://www.saudi-guide.com/asir-region/i/98060792/al-athiriyah-farm-mzraa-alaaathry',1,0,'مزرعه عاذريه al athiriyah farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060791,'asir-region','مزرعة الثمرات للورد الطائفي','Al Thamarat Taifi Rose Farm','al-thamarat-taifi-rose-farm-mzraa-althmrat-llord-altayfy','["أماكن سياحية"]','["sights"]','مزرعة الثمرات للورد الطائفي تتيح لك الاستمتاع برائحة الورد الطائفي الطبيعي وبشكله الجمالي وسط بيئة ريفية جميلة.','<div class="texte" > <p>مزرعة الثمرات للورد الطائفي تتيح لك الاستمتاع برائحة الورد الطائفي الطبيعي وبشكله الجمالي وسط بيئة ريفية جميلة. تُعد وجهة مصغرة عن حقول الورد الشهيرة في الطائف، ومناسبة لعشاق التصوير والباحثين عن أجواء ريفية عطرة. للتواصل: 0500550884.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060791-68547189.jpg?v=1791569516"]','https://cmsphoto.ww-cdn.com/resizeapi/9de61f03c7916f3b22332dfcc0e35efad75e479d/480/',18.3819189,42.6011925,'بني مالك 62475','0500550884','','','https://www.saudi-guide.com/asir-region/i/98060791/al-thamarat-taifi-rose-farm-mzraa-althmrat-llord-altayfy',1,0,'مزرعه ثمرات للورد طائفي al thamarat taifi rose farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060790,'asir-region','مزرعة مناحل الألمعي','Al Almaei Apiaries Farm','al-almaei-apiaries-farm-mzraa-mnahl-alalmaay','["أماكن سياحية"]','["sights"]','مزرعة مناحل الألمعي متخصصة في صنع العسل حيث يمكنك الاستمتاع برؤية مراحل صنع العسل وأنواعه كما تتميز ببيع أجود أنواع العسل الطبيعي.','<div class="texte" > <p>مزرعة مناحل الألمعي متخصصة في صنع العسل حيث يمكنك الاستمتاع برؤية مراحل صنع العسل وأنواعه كما تتميز ببيع أجود أنواع العسل الطبيعي. يوفر المكان شحنًا لمنتجات العسل لجميع مناطق المملكة، وتحظى منتجاته بتقييمات ممتازة لنقاء الطعم وجودته. للتواصل: 0532980597، ومواعيد الدوام من 8:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060790-68547192.jpg?v=1791569580"]','https://cmsphoto.ww-cdn.com/resizeapi/351250e947c108a8f4c56f50b3856b702338c53b/480/',18.2273623,42.4039496,'سوقة، السودة 63479','0532980597','','','https://www.saudi-guide.com/asir-region/i/98060790/al-almaei-apiaries-farm-mzraa-mnahl-alalmaay',1,0,'مزرعه مناحل المعي al almaei apiaries farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060788,'asir-region','مزرعة سحاب السقا للفراولة','Sahab Al Saqa Strawberry Farm','sahab-al-saqa-strawberry-farm-mzraa-shab-alska-llfraol','["أماكن سياحية"]','["sights"]','مزرعة سحاب السقا للفراولة تجربة مميزة من القطف المباشر لثمار الفراولة أو الاستمتاع بعصيرها وبعض الأطباق المصنوعة منها.','<div class="texte" > <p>مزرعة سحاب السقا للفراولة تجربة مميزة من القطف المباشر لثمار الفراولة أو الاستمتاع بعصيرها وبعض الأطباق المصنوعة منها. تحظى بتقييمات ممتازة من العائلات لجودة الفراولة الطازجة وودّية الطاقم، وتُعد وجهة مرحة يستمتع فيها الأطفال بقطف ثمارهم بأنفسهم. للتواصل: 0551752209، ومواعيد الدوام من 9:30 صباحًا حتى 6:30 مساءً.</p> </div>','[]','',18.2162561,42.407008,'السقا، السودة، أبها 62518','0551752209','','','https://www.saudi-guide.com/asir-region/i/98060788/sahab-al-saqa-strawberry-farm-mzraa-shab-alska-llfraol',1,0,'مزرعه سحاب سقا للفراوله sahab al saqa strawberry farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060786,'asir-region','مزرعة السحاب للفراولة','The Strawberry Farm','the-strawberry-farm-mzraa-alshab-llfraol','["أماكن سياحية"]','["sights"]','مزرعة السحاب للفراولة في عسير تتيح لك تجربة قطف الفراولة بنفسك وشرائها أو تذوق عصيرها الطازج وسط أجواء ريفية ممتعة.','<div class="texte" > <p>مزرعة السحاب للفراولة تتيح لك الاستمتاع بتجربة القطف والشراء أو تناول عصير من الفراولة الطازجة. تفتح أبوابها للزوار حوالي الساعة 10 صباحًا لمشاهدة المزرعة، ثم للقطف الفعلي من الساعة 1 ظهرًا، والدخول مجاني بالكامل. للتواصل: 0551900766، ومواعيد الدوام من 1:00 ظهرًا حتى 7:30 مساءً.</p> </div>','[]','',18.1801649,42.4152061,'قرية شعف آل ويمن، أبها 62518','0551900766','','','https://www.saudi-guide.com/asir-region/i/98060786/the-strawberry-farm-mzraa-alshab-llfraol',1,0,'مزرعه سحاب للفراوله the strawberry farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060784,'asir-region','حديقة الروضة','Alrawda Park','alrawda-park-hdyk-alrod','["أماكن سياحية"]','["sights"]','من مسارات المشي الهادئة والمناسبة لممارسة أنواع مختلفة من الرياضة، يوفر أماكن للجلوس وغيرها من الفعاليات. حديقة.','<div class="texte" > <p>حديقة الروضة من مسارات المشي الهادئة والمناسبة لممارسة أنواع مختلفة من الرياضة، يوفر أماكن للجلوس وغيرها من الفعاليات. تضم محال ومنتجات محلية تشمل الحلاوة الطحينية وأكواب الفراولة وخبز الميفا، وتفتح من الساعة 4 عصرًا حتى 2 فجرًا، ما يجعلها وجهة مسائية هادئة ومنظمة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060784-68547203.jpg?v=1791569840"]','https://cmsphoto.ww-cdn.com/resizeapi/32f4eff5150e62a363c68a6b1ae90764b7a5e7ae/480/',18.2421057,42.6370278,'قرى آل غليظ، سر الغالض، أبها 62586','','','','https://www.saudi-guide.com/asir-region/i/98060784/alrawda-park-hdyk-alrod',1,0,'حديقه روضه alrawda park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060783,'asir-region','حديقة وادي لعصان','Lasan Valley Park','lasan-valley-park-hdyk-oady-laasan','["أماكن سياحية"]','["sights"]','يقع في حي الموظفين ويتضمن مسارًا للمشي وملاعب وممرًا للدراجات بجانب مسطحات خضراء للجلوس والاستمتاع. حديقة.','<div class="texte" > <p>حديقة وادي لعصان تقع في حي الموظفين وتضم مسارًا للمشي وملاعب وممرًا للدراجات بجانب مسطحات خضراء للجلوس والاستمتاع. تتميز بمسارها المستقيم الخالي من المرتفعات المتعبة، مع انتشار عربات الطعام على طول الممشى ومصلى ودورات مياه، ما يجعلها من أفضل حدائق أبها.</p> </div>','[]','',18.2316381,42.589364,'حي الموظفين، الموزفين، أبها 62583','0559323935','','','https://www.saudi-guide.com/asir-region/i/98060783/lasan-valley-park-hdyk-oady-laasan',1,0,'حديقه وادي لعصان lasan valley park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060781,'asir-region','حديقة الأندلس','Andalus Park','andalus-park-hdyk-alandls','["أماكن سياحية"]','["sights"]','حديقة الأندلس من أقدم الحدائق في المنطقة، مكان مميز للعائلة لقربه من خيارات متعددة من المطاعم. تشتهر بأشجار الجاكاراندا الجميلة وجدار فني ملون بالخلفية.','<div class="texte" > <p>حديقة الأندلس من أقدم الحدائق في المنطقة، مكان مميز للعائلة لقربه من خيارات متعددة من المطاعم. تشتهر بأشجار الجاكاراندا الجميلة وجدار فني ملون بالخلفية، وتغطيها الضباب أحيانًا ما يمنحها طابعًا ساحرًا، رغم إزعاج بسيط من بائعي أكاليل الزهور المتجولين أحيانًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060781-68547214.jpg?v=1791569984"]','https://cmsphoto.ww-cdn.com/resizeapi/66e0937d2eef53819b7fb50dc34f76ca2e541b20/480/',18.2120574,42.5150943,'الأمير سلطان، النزهة، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98060781/andalus-park-hdyk-alandls',1,0,'حديقه اندلس andalus park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060780,'asir-region','حديقة المليون','Million''s Park','millions-park-hdyk-almlyon','["أماكن سياحية"]','["sights"]','إحدى الحدائق الكبيرة في المنطقة تضم ممشى وحديقة للجلوس وأماكن لبيع القهوة والمأكولات وألعاب للأطفال. حديقة.','<div class="texte" > <p>حديقة المليون إحدى الحدائق الكبيرة في المنطقة تضم ممشى وحديقة للجلوس وأماكن لبيع القهوة والمأكولات وألعاب للأطفال. تشتهر برحلة القطار الصغير الممتعة للأطفال (10 ريالات للركوب)، إلى جانب محال متنوعة للألعاب والآيس كريم والعطور، ما يجعلها وجهة مفضلة في أمسيات الصيف الباردة.</p> </div>','[]','',18.3098997,42.629754,'طريق المحالة، أبها 62569','','','','https://www.saudi-guide.com/asir-region/i/98060780/millions-park-hdyk-almlyon',1,0,'حديقه مليون million''s park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060758,'asir-region','حديقة المشهد','Almashhad Park','almashhad-park-hdyk-almshhd','["أماكن سياحية"]','["sights"]','مسارات متعددة للمشي على اتساع كبير توفر جلسات للأسر وألعاب للأطفال وملاعب لكرة القدم والطائرة. حديقة.','<div class="texte" > <p>حديقة المشهد تضم مسارات متعددة للمشي على اتساع كبير توفر جلسات للأسر وألعاب للأطفال وملاعب لكرة القدم والطائرة. تُعد من أفضل الحدائق المجتمعية في أبها لطول مسار المشي فيها، وتناسب النزهات الطويلة رغم ازدحامها أحيانًا في المساء.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060758-68547227.jpg?v=1791570246", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060758-68547228.jpg?v=1791570264"]','https://cmsphoto.ww-cdn.com/resizeapi/b1b77c1d185a52082da337778b43b021cb3d30fe/480/',18.2412829,42.4789029,'القرى، أبها 62541','','','','https://www.saudi-guide.com/asir-region/i/98060758/almashhad-park-hdyk-almshhd',1,0,'حديقه مشهد almashhad park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060756,'asir-region','حديقة الوطن','Alwatan Park','alwatan-park-hdyk-alotn','["أماكن سياحية"]','["sights"]','حديقة الوطن جسر مشاة بإضاءات خافتة قريب من مطار أبها ويوفر خيارات متنوعة لكافة أفراد الأسرة. تشتهر بمروجها الخضراء الواسعة.','<div class="texte" > <p>حديقة الوطن جسر مشاة بإضاءات خافتة قريب من مطار أبها ويوفر خيارات متنوعة لكافة أفراد الأسرة. تشتهر بمروجها الخضراء الواسعة، رغم بعض الملاحظات على نظافتها وضرورة الحذر من منحنى خطير عند المدخل والمخرج. تتوفر دورات مياه للجنسين، وتُعد وجهة هادئة لمشاهدة غروب الشمس.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060756-68547240.jpg?v=1791570400", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060756-68547241.jpg?v=1791570408"]','https://cmsphoto.ww-cdn.com/resizeapi/c714d71b1ef5231c5133cb17f3c21c6adb9502a9/480/',18.2469072,42.6332811,'قرى آل غليظ، أبها 62586','','','','https://www.saudi-guide.com/asir-region/i/98060756/alwatan-park-hdyk-alotn',1,0,'حديقه وطن alwatan park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060754,'asir-region','منتزه سما أبها','Sama Abha Park','sama-abha-park-mntzh-sma-abha','["أماكن سياحية"]','["sights"]','قريبة من مدينة أبها على ارتفاع مشرف على جزء كبير من المدينة، تقام بها فعاليات موسمية وتضم مسارات للمشي والجلوس. منتزه.','<div class="texte" > <p>منتزه سما أبها قريب من مدينة أبها على ارتفاع مشرف على جزء كبير من المدينة، تقام به فعاليات موسمية وتضم مسارات للمشي والجلوس. يشتهر بألوان الأزهار الجميلة خصوصًا في يونيو ويوليو، وأفضل وقت لزيارته بين الساعة 5 و7 مساءً لمشاهدة مناظر خلابة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060754-68547248.jpg?v=1791570477"]','https://cmsphoto.ww-cdn.com/resizeapi/39c8e41c0cd4a07e12fcf0b52596dbc05add465d/480/',18.2415214,42.4837476,'القرى، أبها 62541','','','','https://www.saudi-guide.com/asir-region/i/98060754/sama-abha-park-mntzh-sma-abha',1,0,'منتزه سما ابها sama abha park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060749,'asir-region','منتزه المسقي','Al Masqi Park','al-masqi-park-mntzh-almsky','["أماكن سياحية"]','["sights"]','منتزه المسقي وجهة مناسبة للاسترخاء حيث الإطلالات المشرفة على مناظر متسعة من الطبيعة، ويشتهر بمناظره الفريدة وإمكانية مشاهدة القرود البرية أثناء التجول.','<div class="texte" > <p>منتزه المسقي وجهة مناسبة للاسترخاء حيث الإطلالات المشرفة على مناظر متسعة من الطبيعة، ويشتهر بمناظره الفريدة وإمكانية مشاهدة القرود البرية أثناء التجول. يناسب رحلات المجموعات الكبيرة والتخييم والطبخ في الهواء الطلق، مع نصيحة مهمة بعدم إطعام القرود للحفاظ على سلامة الزوار. يعمل على مدار الساعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060749-68547261.jpg?v=1791570613", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060749-68547262.jpg?v=1791570624"]','https://cmsphoto.ww-cdn.com/resizeapi/646e84a56198e318ba2eb46299273b95b6e50abc/480/',18.0312448,42.7221997,'منتزه الأمير سلطان، المسقي 62352','','','','https://www.saudi-guide.com/asir-region/i/98060749/al-masqi-park-mntzh-almsky',1,0,'منتزه مسقي al masqi park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060605,'asir-region','قلعة شمسان التاريخية','Shamsan Castle','shamsan-castle-klaa-shmsan-altarykhy','["التراث والثقافة"]','["heritage"]','تقع على إحدى القمم المشرفة على أبها، بنيت على يد الأتراك لحماية جنودهم حتى أصبحت الآن مطلًّا للاستمتاع برؤية المدينة. قلعة تاريخية.','<div class="texte" > <p>قلعة شمسان التاريخية تقع على إحدى القمم المشرفة على أبها، بنيت على يد الأتراك في العهد العثماني لحماية جنودهم، حتى أصبحت الآن مطلًا للاستمتاع برؤية المدينة. رغم إغلاق الداخل أمام الزوار حاليًا، إلا أن التجول حول أسوارها الحجرية والاستمتاع بالإطلالة الخارجية يبقى تجربة تستحق زيارة قصيرة، خصوصًا عند الغروب. تعمل على مدار الساعة، مع مسارات مشي ومقاعد جلوس حول الموقع.</p> </div>  <div class="texte" > <p>مصدر الصورة: ويكيميديا كومنز — هيئة التراث (CC BY-SA 4.0)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060605-68537713.jpg?v=1791497864"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98060605-68537713.jpg?v=1791497864',18.2252866,42.503598,'شمسان، أبها 62521','','','','https://www.saudi-guide.com/asir-region/i/98060605/shamsan-castle-klaa-shmsan-altarykhy',1,0,'قلعه شمسان تاريخيه shamsan castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060603,'asir-region','متحف تهلل','Tahlal Museum','tahlal-museum-mthf-thll','["التراث والثقافة"]','["heritage"]','متحف تهلل يحمل عبق الماضي وأصالته في عرض التحف والأدوات المستخدمة قديمًا كما يضم جلسات مميزة مطلة على الجبال في قرية الشط على طريق السودة.','<div class="texte" > <p>متحف تهلل يحمل عبق الماضي وأصالته في عرض التحف والأدوات المستخدمة قديمًا كما يضم جلسات مميزة مطلة على الجبال في قرية الشط على طريق السودة. ينقسم إلى استوديو للوحات تراثية بأصباغ طبيعية محلية، ومتحف يضم قطعًا أثرية عمرها ثلاثة قرون، ومقهى ومطعم مريح، وتشتهر مالكته "أم حليمة" بكرمها وضيافتها الدافئة. مواعيد الدوام من 9:00 صباحًا حتى 7:30 مساءً، برسوم دخول رمزية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060603-68547266.jpg?v=1791570699"]','https://cmsphoto.ww-cdn.com/resizeapi/a1a4d05b52ac1029d63b43fb0e693e41ed83e177/480/',18.2928013,42.4104412,'الطالع، قرية الشط، طريق السودة، أبها 62534','','','','https://www.saudi-guide.com/asir-region/i/98060603/tahlal-museum-mthf-thll',1,0,'متحف تهلل tahlal museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060602,'asir-region','متحف قصر مالك','Malik Palace Museum','malik-palace-museum-mthf-ksr-malk','["التراث والثقافة"]','["heritage"]','متحف قصر مالك يجسد حقبة من عبق التاريخ ووجهة مميزة لعشاق المتعة البصرية والفنون المعمارية في إحدى قرى بني مالك بمنطقة عسير.','<div class="texte" > <p>متحف قصر مالك يجسد حقبة من عبق التاريخ ووجهة مميزة لعشاق المتعة البصرية والفنون المعمارية في إحدى قرى بني مالك بمنطقة عسير. يقع وسط طبيعة خلابة تظهر فيها القرود البرية أحيانًا، ويحظى بإشادة كبيرة من الزوار رغم بعده النسبي عن الطرق الرئيسية. للتواصل: 0504782302، ويعمل على مدار الساعة.</p> </div>','[]','',18.0240205,42.2709903,'حبيل 63496','0504782302','','','https://www.saudi-guide.com/asir-region/i/98060602/malik-palace-museum-mthf-ksr-malk',1,0,'متحف قصر مالك malik palace museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060597,'asir-region','قصور العسابلة','Asabilah Palaces','asabilah-palaces-ksor-alaasabl','["التراث والثقافة"]','["heritage"]','قرية تاريخية يعود عمرها إلى أكثر من 300 عام، تضم تحف أثرية وعروضًا شعبية والعديد من الأنشطة الممتعة. قرية تراثية.','<div class="texte" > <p>قصور العسابلة قرية تاريخية يعود عمرها إلى أكثر من 300 عام، تضم أربعة قصور رئيسية وتحفًا أثرية وعروضًا شعبية والعديد من الأنشطة الممتعة. تحولت اليوم إلى وجهة مسائية تضم محال ومقاهي ومطاعم، مع فعاليات موسيقية حية أحيانًا، ورسوم دخول تبلغ حوالي 20-25 ريالًا للفرد. للتواصل: 0503681375، ومواعيد الدوام من 4:00 عصرًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: Heritage Commission (هيئة التراث) عبر Wikimedia Commons (CC BY-SA 4.0)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060597-68554867.jpg?v=1791697339"]','https://cmsphoto.ww-cdn.com/resizeapi/4d161a80b2d02350f1057ec20f751e8b4a7cb774/480/',19.1203755,42.1308174,'حي الصديق، النماص 67387','0503681375','','','https://www.saudi-guide.com/asir-region/i/98060597/asabilah-palaces-ksor-alaasabl',1,0,'قصور عسابله asabilah palaces تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060592,'asir-region','قرية المسقي التراثية','Al Masqi Heritage Village','al-masqi-heritage-village-kry-almsky-altrathy','["التراث والثقافة"]','["heritage"]','قرية المسقي التراثية من القرى العسيرية الأصيلة التي تعود لمئات السنين، وتُعد من "القرى الظاهرة" التي وردت في القرآن الكريم لقدمها التاريخي الكبير.','<div class="texte" > <p>قرية المسقي التراثية من القرى العسيرية الأصيلة التي تعود لمئات السنين، وتُعد من "القرى الظاهرة" التي وردت في القرآن الكريم لقدمها التاريخي الكبير. تشتهر بمسجدها التراثي الذي يزيد عمره عن 850 عامًا، وممراتها الحجرية المسقوفة التي لا تزال قائمة رغم أعمال الترميم المستمرة. تُعد وجهة مثالية لعشاق التصوير والتاريخ رغم قلة الخدمات المتوفرة حاليًا في الموقع.</p> </div>','[]','',18.0417365,42.7459396,'الفرعاء، المسقي 62268','','','','https://www.saudi-guide.com/asir-region/i/98060592/al-masqi-heritage-village-kry-almsky-altrathy',1,0,'قريه مسقي تراثيه al masqi heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060347,'riyadh','المدينة الرقمية','Digital City','digital-city-almdyn-alrkmy','["أماكن سياحية"]','["sights"]','المدينة الرقمية في الرياض مجمع حديث متعدد الاستخدامات بأبراج ذهبية لامعة تتحول ليلًا إلى لوحة إضاءة ساحرة، ويستضيف فعاليات فنية.','<div class="texte" > <p>المدينة الرقمية مجمع حديث متعدد الاستخدامات يشمل محالًا تجارية وسكنية، ويشتهر بأبراجه الأربعة الذهبية اللامعة التي تخلق مشهدًا معماريًا مذهلاً خصوصًا عند الوقوف في منتصفها. تتحول الأبراج ليلًا إلى لوحة إضاءة متحركة ساحرة، ويستضيف المكان فعاليات فنية كمهرجان "نور الرياض"، مع موسيقى حية ونافورة مياه جميلة، رغم قلة خيارات المطاعم نسبيًا في محيطه.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060347-68547299.jpg?v=1791571206", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060347-68547300.jpg?v=1791571219"]','https://cmsphoto.ww-cdn.com/resizeapi/75e382fd414029385b5f4242968b47f9c68994b0/480/',24.740393,46.6354193,'Prince Turki Bin Abdulaziz Al Awal Rd, An Nakheel, Riyadh 12382','0112059911','','','https://www.saudi-guide.com/riyadh/i/98060347/digital-city-almdyn-alrkmy',1,0,'مدينه رقميه digital city اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060335,'riyadh','معهد مسك للفنون','Misk Art Institute','misk-art-institute-maahd-msk-llfnon','["التراث والثقافة"]','["heritage"]','معهد مسك للفنون يقدم عالم الفن والثقافة من منظور الفن المعاصر، ويحوي معارض فنية دورية وورش عمل تعليمية للمواهب الناشئة والمحترفين.','<div class="texte" > <p>معهد مسك للفنون يقدم عالم الفن والثقافة من منظور الفن المعاصر، ويحوي معارض فنية دورية وورش عمل تعليمية للمواهب الناشئة والمحترفين. تجمع مساحاته بين الأساليب الفنية التقليدية والحديثة بتنسيق متقن، ويحظى بأجواء هادئة ملهمة يشيد بها الزوار، إلى جانب طاقم عمل متعاون ومطلع. مواعيد الدوام من 4:00 عصرًا حتى 10:00 مساءً (الجمعة إجازة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060335-68547306.jpg?v=1791571306"]','https://cmsphoto.ww-cdn.com/resizeapi/1e7e0175b967d2cd8fc3ea98137438b721a55ff0/480/',24.6638592,46.6903968,'النموذجية، الرياض 12731','','','','https://www.saudi-guide.com/riyadh/i/98060335/misk-art-institute-maahd-msk-llfnon',1,0,'معهد مسك للفنون misk art institute تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060334,'riyadh','صالة تجريد للفنون','Abstract Art Gallery','abstract-art-gallery-sal-tgryd-llfnon','["التراث والثقافة"]','["heritage"]','صالة تجريد للفنون تضم لوحات نادرة متنوعة لأكثر من فنان لتكون في متناولكم للاقتناء، وتشتهر بعرض أعمال فنانين خليجيين وشمال أفريقيين وشرق أوسطيين.','<div class="texte" > <p>صالة تجريد للفنون تضم لوحات نادرة متنوعة لأكثر من فنان لتكون في متناولكم للاقتناء، وتشتهر بعرض أعمال فنانين خليجيين وشمال أفريقيين وشرق أوسطيين، صاعدين ومشهورين على حد سواء. تتوفر أعمال بمختلف الميزانيات، ويحظى المكان بإشادة الزوار لحسن اختيار المعروضات رغم صغر مساحته نسبيًا. للتواصل: 0503009936، ومواعيد الدوام من 9:30 صباحًا حتى 11:30 صباحًا ومن 4:30 عصرًا حتى 9:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060334-68547311.jpg?v=1791571400"]','https://cmsphoto.ww-cdn.com/resizeapi/50ad0bddccac7c53538128408061d8e18d31aec7/480/',24.7473325,46.6160778,'طريق الدائري الشمالي، النخيل، الرياض 12391','0503009936','','','https://www.saudi-guide.com/riyadh/i/98060334/abstract-art-gallery-sal-tgryd-llfnon',1,0,'صاله تجريد للفنون abstract art gallery تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060333,'riyadh','ليفت آرت جاليري','Lift Art Gallery','lift-art-gallery-lyft-art-galyry','["التراث والثقافة"]','["heritage"]','ليفت آرت جاليري تأسس ليصبح معرضًا فنيًا معاصرًا، ومنصة تجمع الفنون المعاصرة للفنانين المحليين والعالميين داخل حي البجيري بالدرعية الجديدة.','<div class="texte" > <p>Lift Art Gallery تأسس ليصبح معرضًا فنيًا معاصرًا، ومنصة تجمع الفنون المعاصرة للفنانين المحليين والعالميين داخل حي البجيري بالدرعية الجديدة. يتيح للزوار شراء أي قطعة معروضة، أو حتى رسم لوحاتهم الخاصة بالأدوات المتوفرة في المكان، ويستضيف ورش عمل فنية يُعلن عنها عبر حساباته على مواقع التواصل. للتواصل: 0552858800، ومواعيد الدوام من 11:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060333-68547314.jpg?v=1791571495"]','https://cmsphoto.ww-cdn.com/resizeapi/4df3561bb6aacfe4f667385ec8979220eed8dfbf/480/',24.7449004,46.5378468,'ابن جوير الطبري، الدرعية الجديدة، الدرعية 13732','0552858800','','','https://www.saudi-guide.com/riyadh/i/98060333/lift-art-gallery-lyft-art-galyry',1,0,'ليفت ارت جاليري lift art gallery تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060331,'riyadh','إرم آرت جاليري','Errm Art Gallery','errm-art-gallery-arm-art-galyry','["التراث والثقافة"]','["heritage"]','إرم آرت جاليري يقدم أعمالًا تشكيلية عربية واستشارات فنية وبناء مجموعات فنية، ويشتهر بعرض أعمال فنانين معاصرين من مختلف دول الشرق الأوسط.','<div class="texte" > <p>إرم آرت جاليري يقدم أعمالًا تشكيلية عربية واستشارات فنية وبناء مجموعات فنية، ويشتهر بعرض أعمال فنانين معاصرين من مختلف دول الشرق الأوسط. يديره مالك معروف بلطفه ومعرفته الواسعة بالفن، والدخول مجاني للجميع، ما يجعله وجهة مثالية لعشاق الفن والفنانين الباحثين عن فرصة عرض أعمالهم. للتواصل: 0500593400، ومواعيد الدوام من 10:00 صباحًا حتى 10:00 مساءً (الجمعة إجازة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060331-68547318.jpg?v=1791571573"]','https://cmsphoto.ww-cdn.com/resizeapi/b16c63a7f7a191cb0e8e6c617540d1d2a85ee6ab/480/',24.6862798,46.6891956,'العليا، الرياض 12221','0500593400','','','https://www.saudi-guide.com/riyadh/i/98060331/errm-art-gallery-arm-art-galyry',1,0,'ارم ارت جاليري errm art gallery تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060330,'riyadh','لكم آرت سبيس','Lakum Artspace','lakum-artspace-lkm-art-sbys','["التراث والثقافة"]','["heritage"]','لكم آرت سبيس معرض فني معاصر متعدد الوظائف في الرياض، يقدم تجربة تفاعلية للزوار ويضم متجر هدايا ومقهى صغيرًا للاسترخاء.','<div class="texte" > <p>Lakum Artspace معرض معاصر متعدد الوظائف، وهو أكثر من مجرد مساحة فنية تفاعلية للزوار. استضاف معرض "الأجساد المؤدية" الذي استكشف علاقة النسيج بالفقد والحداد والولادة الجديدة، ويضم متجر هدايا ومقهى صغيرًا لطيفًا للاسترخاء بين جولات المشاهدة. للتواصل: 920012083، ومواعيد الدوام من 10:00 صباحًا حتى 10:00 مساءً (الجمعة إجازة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060330-68547331.jpg?v=1791571659", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060330-68547332.jpg?v=1791571671"]','https://cmsphoto.ww-cdn.com/resizeapi/7ca85307e469d8411a65b4bbce50428de246a080/480/',24.7007377,46.6463564,'طريق العروبة الفرعي، أم الحمام الغربي، الرياض 12328','920012083','','','https://www.saudi-guide.com/riyadh/i/98060330/lakum-artspace-lkm-art-sbys',1,0,'لكم ارت سبيس lakum artspace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060329,'riyadh','صالة الأمير فيصل بن فهد للفنون','Prince Faisal Bin Fahd Arts Hall','prince-faisal-bin-fahd-arts-hall-sal-alamyr-fysl-bn-fhd-llfnon','["التراث والثقافة"]','["heritage"]','صالة الأمير فيصل بن فهد للفنون تضم أشكالًا متنوعة للفن، ليشكل كل منفذ من الفن تجسيدًا فريدًا للنظرة المعاصرة، داخل مبنى بطراز معماري قديم أُعيد تأهيله.','<div class="texte" > <p>صالة الأمير فيصل بن فهد للفنون تضم أشكالًا متنوعة للفن، ليشكل كل منفذ من الفن تجسيدًا فريدًا للنظرة المعاصرة، داخل مبنى بطراز معماري قديم أُعيد تأهيله. تضم استوديوهات إقامة فنية للفنانين ومساحة "مساحة" للورش وورش رسم حية مجانية أسبوعية، إلى جانب مقهى صغير وغرف اجتماعات. للتواصل: 0566740917، ومواعيد الدوام من 4:00 عصرًا حتى 10:00 مساءً (الجمعة إجازة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060329-68547333.jpg?v=1791571739", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060329-68547334.jpg?v=1791571752"]','https://cmsphoto.ww-cdn.com/resizeapi/f578f3355de02d4a045aac09b19eb2c0c5c76b1e/480/',24.6638274,46.6901833,'طريق الملك سعود، النموذجية، الرياض 12731','0566740917','','','https://www.saudi-guide.com/riyadh/i/98060329/prince-faisal-bin-fahd-arts-hall-sal-alamyr-fysl-bn-fhd-llfnon',1,0,'صاله امير فيصل بن فهد للفنون prince faisal bin fahd arts hall تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060327,'riyadh','أحلام جاليري','Ahlam Gallery','ahlam-gallery-ahlam-galyry','["التراث والثقافة"]','["heritage"]','أحلام جاليري متجر يجعل الفن السعودي والمحلي في متناولكم للاقتناء والاستثمار، كما يقدم أعمالًا فنية متنوعة داخل مركز الموسى بشارع العليا.','<div class="texte" > <p>أحلام جاليري متجر يجعل الفن السعودي والمحلي في متناولكم للاقتناء والاستثمار، كما يقدم أعمالًا فنية متنوعة داخل مركز الموسى بشارع العليا. يستضيف معارض دورية لفنانين سعوديين موهوبين، ويتميز بأجواء ترحيبية دافئة تشجع الزوار الجدد على استكشاف عالم الفن. للتواصل: 0559144488، ومواعيد الدوام من 9:00 صباحًا حتى 10:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060327-68547338.jpg?v=1791571824", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060327-68547340.jpg?v=1791571838"]','https://cmsphoto.ww-cdn.com/resizeapi/9440ddd991f38af391ff6e9209136b19e3223073/480/',24.6862132,46.6893266,'مركز الموسى، شارع العليا، الرياض 12221','0559144488','','','https://www.saudi-guide.com/riyadh/i/98060327/ahlam-gallery-ahlam-galyry',1,0,'احلام جاليري ahlam gallery تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060314,'riyadh','ممشى واحة نجد','Najd Oasis Walkway','najd-oasis-walkway-mmsha-oah-ngd','["ترفيه واستجمام"]','["fun"]','ممشى واحة نجد يتميز بموقع مثالي في وسط المدينة بين طريقي العليا والملك فهد، ويضم العديد من عربات الطعام بالإضافة إلى جمال طبيعته المليئة بالأشجار الظليلة.','<div class="texte" > <p>ممشى واحة نجد يتميز بموقع مثالي في وسط المدينة بين طريقي العليا والملك فهد، ويضم العديد من عربات الطعام بالإضافة إلى جمال طبيعته المليئة بالأشجار الظليلة. يخضع أحيانًا لأعمال صيانة جزئية، لكنه يبقى من أنظف وأهدأ الممرات في الرياض، ويديره أمانة منطقة الرياض بعناية مستمرة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060314-68547347.jpg?v=1791571902", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060314-68547349.jpg?v=1791571917"]','https://cmsphoto.ww-cdn.com/resizeapi/a15f43649e9d8a4b6821b9592bfd4916e2367645/480/',24.7290743,46.664645,'طريق الملك فهد، الرياض 12261','','','','https://www.saudi-guide.com/riyadh/i/98060314/najd-oasis-walkway-mmsha-oah-ngd',1,0,'ممشي واحه نجد najd oasis walkway ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060311,'riyadh','منتزه السويدي','Al Suwaidi Park','al-suwaidi-park-mntzh-alsoydy','["ترفيه واستجمام", "موسم الرياض"]','["fun"]','منتزه السويدي يتميز بتفاصيل هندسية رائعة ومساحات خضراء واسعة بالإضافة للعديد من الخدمات والمرافق، ويُعد وجهة أساسية لفعاليات موسم الرياض السنوية.','<div class="texte" > <p>منتزه السويدي يتميز بتفاصيل هندسية رائعة ومساحات خضراء واسعة بالإضافة للعديد من الخدمات والمرافق، ويُعد وجهة أساسية لفعاليات موسم الرياض السنوية. يستضيف مهرجانات ثقافية أسبوعية بموسيقى ورقص وأسواق شعبية، مع دخول مجاني، رغم أن مواقف السيارات ودورات المياه قد تحتاج لتحسين في أوقات الازدحام.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060311-68547352.jpg?v=1791571985"]','https://cmsphoto.ww-cdn.com/resizeapi/903b87ccbb4a0983c74ee5b031e52c7dd1cb3e69/480/',24.5970372,46.6950887,'السويدي، الرياض 12791','','','','https://www.saudi-guide.com/riyadh/i/98060311/al-suwaidi-park-mntzh-alsoydy',1,0,'منتزه سويدي al suwaidi park ترفيه واستجمام موسم رياض',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060310,'riyadh','منتزه الواحة','Oasis Garden','oasis-garden-mntzh-aloah','["ترفيه واستجمام"]','["fun"]','منتزه الواحة يتميز بشكله الطولي ليكون المكان المثالي للرياضة، ويضم الكثير من مرافق اللعب للأطفال بالإضافة إلى استئجار الدراجات والألعاب ذات العجلات.','<div class="texte" > <p>منتزه الواحة يتميز بشكله الطولي ليكون المكان المثالي للرياضة، ويضم الكثير من مرافق اللعب للأطفال بالإضافة إلى استئجار الدراجات والألعاب ذات العجلات. تنتشر فيه إضاءات جميلة تمنحه أجواءً رومانسية مسائية، ويحظى بشعبية كبيرة للمشي والجري وركوب الدراجات في حي الملك سلمان.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060310-68547358.jpg?v=1791572085"]','https://cmsphoto.ww-cdn.com/resizeapi/b6e6651af43527628cb0fdee3354f3152c613fe5/480/',24.7363165,46.720294,'حي الملك سلمان، الرياض 12442','','','','https://www.saudi-guide.com/riyadh/i/98060310/oasis-garden-mntzh-aloah',1,0,'منتزه واحه oasis garden ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060309,'riyadh','منتزه حي النفل','An Nafal Park','an-nafal-park-mntzh-hy-alnfl','["ترفيه واستجمام"]','["fun"]','منتزه حي النفل يقع وسط حي سكني ويتميز بوجود ألعاب للأطفال ومرافق وخدمات لقضاء وقت ممتع مع العائلة والأصدقاء.','<div class="texte" > <p>منتزه حي النفل يقع وسط حي سكني ويتميز بوجود ألعاب للأطفال ومرافق وخدمات لقضاء وقت ممتع مع العائلة والأصدقاء. يتميز بمساحاته الخضراء الوفيرة ودورات مياه نظيفة، ويُعد وجهة صغيرة ومريحة مناسبة للنزهات المسائية السريعة داخل الحي.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060309-68547365.jpg?v=1791572173"]','https://cmsphoto.ww-cdn.com/resizeapi/7c64ddb59a58a59c18d449cbfaf4c6b8215b5975/480/',24.7785703,46.6696496,'النفل، الرياض 13312','','','','https://www.saudi-guide.com/riyadh/i/98060309/an-nafal-park-mntzh-hy-alnfl',1,0,'منتزه حي نفل an nafal park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060308,'riyadh','منتزه الحزام','Hizam Park','hizam-park-mntzh-alhzam','["ترفيه واستجمام"]','["fun"]','منتزه الحزام يضم ساحات واسعة للعب ومساحات خضراء رائعة ومرافق وخدمات لنزهة ممتعة، ويحتوي على معدات رياضية حديثة نسبيًا.','<div class="texte" > <p>منتزه الحزام يضم ساحات واسعة للعب ومساحات خضراء رائعة ومرافق وخدمات لنزهة ممتعة، ويحتوي على معدات رياضية حديثة نسبيًا. يشهد إقبالًا كبيرًا في عطلات نهاية الأسبوع، رغم أن بعض المناطق تحتاج لعناية أكبر بقص العشب، ويوصى بإحضار كل ما يلزم من مستلزمات نظرًا لعدم وجود بقالة قريبة. للتواصل: 0114354991، ومواعيد الدوام من 9:00 صباحًا حتى 6:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060308-68547378.jpg?v=1791572300"]','https://cmsphoto.ww-cdn.com/resizeapi/37c9516eb247c884b1b6c60c112fad9da4429349/480/',24.6353279,46.6730593,'شارع الأمير سطام، الرفيعة، الرياض 12753','0114354991','','','https://www.saudi-guide.com/riyadh/i/98060308/hizam-park-mntzh-alhzam',1,0,'منتزه حزام hizam park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060307,'riyadh','منتزه تلال','Riyadh Hills Park','riyadh-hills-park-mntzh-tlal','["ترفيه واستجمام"]','["fun"]','منتزه تلال يمكنك الاستمتاع فيه بالخضرة والأشجار والاسترخاء وسط الطبيعة الرائعة، ويضم بحيرة صغيرة وممرًا خشبيًا يلتف حول غابة من أشجار الصنوبر.','<div class="texte" > <p>منتزه تلال يمكنك الاستمتاع فيه بالخضرة والأشجار والاسترخاء وسط الطبيعة الرائعة، ويضم بحيرة صغيرة وممرًا خشبيًا يلتف حول غابة من أشجار الصنوبر. يتميز بنظافته العالية وتنظيمه الجيد، ويوفر مساحات مظللة ودورات مياه نظيفة ومناطق آمنة للعائلات، ما يجعله من أكثر المنتزهات المفضلة في شمال الرياض.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060307-68547395.jpg?v=1791572443"]','https://cmsphoto.ww-cdn.com/resizeapi/f9bb1b8c34c422cbffc9220e395b7d011ad84760/480/',24.7994302,46.6127593,'الملقا، الرياض 13521','','','','https://www.saudi-guide.com/riyadh/i/98060307/riyadh-hills-park-mntzh-tlal',1,0,'منتزه تلال riyadh hills park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060306,'riyadh','منتزه الزهور','Flower Path','flower-path-mntzh-alzhor','["ترفيه واستجمام"]','["fun"]','منتزه الزهور يتميز بجماله الخلاب، وينتشر فيه العديد من الأزهار والورود المختلفة الألوان بشكل منسق وجميل على طول الممشى.','<div class="texte" > <p>منتزه الزهور يتميز بجماله الخلاب، وينتشر فيه العديد من الأزهار والورود المختلفة الألوان بشكل منسق وجميل على طول الممشى. يُعد أفضل مسار للمشي في الرياض خصوصًا في فصل الشتاء، ويضم معدات رياضية بسيطة لتمارين وزن الجسم، إلى جانب مراوح ضباب للتخفيف من الحر صيفًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060306-68547405.jpg?v=1791572505"]','https://cmsphoto.ww-cdn.com/resizeapi/7e59617910f5dbefef95856a9a74d6c61b0f45cc/480/',24.7389692,46.7035638,'حي الملك سلمان، الرياض 12435','','','','https://www.saudi-guide.com/riyadh/i/98060306/flower-path-mntzh-alzhor',1,0,'منتزه زهور flower path ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060305,'riyadh','منتزه النخيل','Annakheel Park','annakheel-park-mntzh-alnkhyl','["ترفيه واستجمام"]','["fun"]','منتزه النخيل واحد من أشهر الحدائق مليء بالعديد من المرافق والخدمات التي توفر نزهة مميزة للعائلة والأفراد.','<div class="texte" > <p>منتزه النخيل واحد من أشهر الحدائق مليء بالعديد من المرافق والخدمات التي توفر نزهة مميزة للعائلة والأفراد، ويضم مضمارًا مخصصًا للتزلج ومسارًا طويلًا للمشي ومسارًا منفصلًا لركوب الدراجات، إلى جانب ملاعب كرة قدم وسلة. يشهد إقبالًا كثيفًا في عطلات نهاية الأسبوع، ويُعد من أكبر المتنزهات الحديثة في حي النخيل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060305-68547417.jpg?v=1791572570"]','https://cmsphoto.ww-cdn.com/resizeapi/8e3e516cc7032358cc5c4cf9bdd558a9e0fea706/480/',24.7401626,46.6020727,'النخيل، الرياض 12394','','','','https://www.saudi-guide.com/riyadh/i/98060305/annakheel-park-mntzh-alnkhyl',1,0,'منتزه نخيل annakheel park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060303,'riyadh','منتزه الحمراء','Al Hamra Park','al-hamra-park-mntzh-alhmra','["ترفيه واستجمام"]','["fun"]','يتميز بمساحته الواسعة ومساحاته الخضراء ووجود حراس أمن وطاقم نظافة، بالإضافة إلى قطط ودودة تجوب أرجاءه، ما يجعله مناسبًا للمشي وممارسة الرياضة الخفيفة.','<div class="texte" > <p>منتزه الحمراء يعتبر من أفضل المتنزهات التي يمكن قضاء أجمل الأوقات فيها للعائلة والأفراد، وهو محاط بسور يمنحه أمانًا إضافيًا. يتميز بمساحته الواسعة ومساحاته الخضراء ووجود حراس أمن وطاقم نظافة، بالإضافة إلى قطط ودودة تجوب أرجاءه، ما يجعله مناسبًا للمشي وممارسة الرياضة الخفيفة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060303-68547443.jpg?v=1791572719"]','https://cmsphoto.ww-cdn.com/resizeapi/bf3388701701a32ac15434313b9bdda8621ef2f0/480/',24.7710015,46.7431741,'الحمراء، الرياض 13216','','','','https://www.saudi-guide.com/riyadh/i/98060303/al-hamra-park-mntzh-alhmra',1,0,'منتزه حمراء al hamra park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060302,'riyadh','منتزه الملك فهد','King Fahad Road Park','king-fahad-road-park-mntzh-almlk-fhd','["ترفيه واستجمام"]','["fun"]','منتزه الملك فهد بالرياض، ممشى ومنتزه يمتد على أحد أشهر شوارع الرياض مع أجواء خضراء ومساحات خصصت للرياضة والمشي.','<div class="texte" > <p>منتزه الملك فهد يعد ملاذًا للعوائل والأفراد، يوفر لزواره جوًا من الهدوء والسكينة وفرصة للاستمتاع بالأنشطة وسط مساحات خضراء واسعة على طريق الملك فهد. تتميز الحديقة بمساحة مركزية مخصصة للجلوس تستقطب حشدًا حيويًا مساءً، وممرات مشي منظمة تحيط بالحديقة بأكملها، ما يجعلها وجهة مناسبة أكثر للتنزه المسائي منها للنزهات العائلية.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060302-68547450.jpg?v=1791572826"]','https://cmsphoto.ww-cdn.com/resizeapi/1bc6a7b58ad7d932de4f7cf54b8293185aa5d315/480/',24.6300319,46.7049545,'الدرعية، الرياض 12651','','','','https://www.saudi-guide.com/riyadh/i/98060302/king-fahad-road-park-mntzh-almlk-fhd',1,0,'منتزه ملك فهد king fahad road park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060301,'riyadh','منتزه الخزامى','Khuzama Park','khuzama-park-mntzh-alkhzama','["ترفيه واستجمام"]','["fun"]','منتزه الخزامى واحة خضراء مخفية داخل الحي الدبلوماسي، يضم أشجارًا ونخيلًا وارفًا وممرات متعرجة تشبه المتاهة.','<div class="texte" > <p>منتزه الخزامى واحة خضراء مخفية داخل الحي الدبلوماسي، يضم أشجارًا ونخيلًا وارفًا وممرات متعرجة تشبه المتاهة، بالإضافة إلى نوافير مياه جميلة وصخور طبيعية على الأطراف. يوفر إطلالة رائعة على وادي حنيفة، ويتصل بمسار مشي طويل يمتد على طول الوادي، ما يجعله وجهة هادئة مثالية للتأمل والمشي المسائي.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060301-68547455.jpg?v=1791572901"]','https://cmsphoto.ww-cdn.com/resizeapi/43379b736afd5a17be70fc8a8590a3cac51ed966/480/',24.686497,46.621927,'شارع الخوابي، الصفارات، الرياض 12513','','','','https://www.saudi-guide.com/riyadh/i/98060301/khuzama-park-mntzh-alkhzama',1,0,'منتزه خزامي khuzama park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060290,'riyadh','السمحانية','Samhaniya','samhaniya-alsmhany','["أماكن سياحية"]','["sights"]','مجمع السمحانية يتميز بطابعه الشعبي الحديث ويضم مجموعة مطاعم ومقاهي شعبية لتجربة مختلفة متميزة في قلب الدرعية التاريخية.','<div class="texte" > <p>مجمع السمحانية يتميز بطابعه الشعبي الحديث ويضم مجموعة مطاعم ومقاهي شعبية لتجربة مختلفة متميزة في قلب الدرعية التاريخية. يضم أيضًا محال لبيع القطع النادرة والمقتنيات القديمة (قراشيع)، ويُعد وجهة رائعة لقضاء أمسية شتوية دافئة حول المواقد. مواعيد الدوام حتى ساعات متأخرة من الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060290-68547462.jpg?v=1791572982"]','https://cmsphoto.ww-cdn.com/resizeapi/cb60f5cc2cc0204179f78f1941f0d4ce59f6f446/480/',24.7413125,46.5715625,'Samhan, Diriyah 13712','','','','https://www.saudi-guide.com/riyadh/i/98060290/samhaniya-alsmhany',1,0,'سمحانيه samhaniya اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060288,'riyadh','المملكة سوشيال داينينغ','Al Mamlaka Social Dining','al-mamlaka-social-dining-almmlk-soshyal-daynyngh','["أماكن سياحية"]','["sights"]','المملكة سوشيال داينينغ يتميز بإطلالات مطاعمه الفاخرة و21 تجربة طعام فريدة عالمية ومحلية داخل مركز المملكة الشهير.','<div class="texte" > <p>المملكة سوشيال داينينغ يتميز بإطلالات مطاعمه الفاخرة و21 تجربة طعام فريدة عالمية ومحلية داخل مركز المملكة الشهير. تُدفع رسوم دخول رمزية (حوالي 29 ريالًا) تتيح التجول بين المطاعم المختلفة واختيار الأطباق من أي منها، ويحظى بشعبية كبيرة كوجهة اجتماعية تجمع الغرباء وتحوّلهم لأصدقاء. مواعيد الدوام من 8:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060288-68547470.jpg?v=1791573063", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060288-68547471.jpg?v=1791573080"]','https://cmsphoto.ww-cdn.com/resizeapi/1b05f127908762ffc7ccf2e8a27fc06eafb17c45/480/',24.7114797,46.6744736,'Kingdom Centre, Olaya St, Al Olaya, Riyadh 12271','','','','https://www.saudi-guide.com/riyadh/i/98060288/al-mamlaka-social-dining-almmlk-soshyal-daynyngh',1,0,'مملكه سوشيال داينينغ al mamlaka social dining اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060287,'riyadh','لوميير','Lumiere Centre','lumiere-centre-lomyyr','["أماكن سياحية"]','["sights"]','لوميير يجمع أفضل المطاعم والمقاهي المحلية والعالمية المتنوعة بما يرضي جميع الأذواق، من المأكولات البحرية إلى اللبنانية والإيطالية والبرجر.','<div class="texte" > <p>لوميير يجمع أفضل المطاعم والمقاهي المحلية والعالمية المتنوعة بما يرضي جميع الأذواق، من المأكولات البحرية إلى اللبنانية والإيطالية والبرجر. يتميز بتصميم مضيء وشرفات علوية بإطلالات جميلة، ومجاري مائية صغيرة تضفي أجواءً هادئة على المكان. مواعيد الدوام 24 ساعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060287-68547475.jpg?v=1791573160", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060287-68547476.jpg?v=1791573173"]','https://cmsphoto.ww-cdn.com/resizeapi/ad76d8b585bdaa2979736af63099de549da23534/480/',24.7598419,46.6036753,'Turki Bin Abdulaziz Al Awwal, Hittin, Riyadh 13513','','','','https://www.saudi-guide.com/riyadh/i/98060287/lumiere-centre-lomyyr',1,0,'لوميير lumiere centre اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060285,'riyadh','ليتل الرياض','Little Riyadh','little-riyadh-lytl-alryad','["أماكن سياحية"]','["sights"]','ليتل الرياض يجمع أفضل المقاهي والمطاعم المحلية والعالمية، ويتميز بموقعه القريب من السفارات في حي السفارات.','<div class="texte" > <p>ليتل الرياض يجمع أفضل المقاهي والمطاعم المحلية والعالمية، ويتميز بموقعه القريب من السفارات في حي السفارات. يضم فروعًا لسلاسل عالمية كـ"جو آند ذا جوس"، ويشتهر بأطباق الباستا والستيك الشهية بديكور عصري أنيق يستقطب الزوار خصوصًا في المساء. للتواصل: 920024788، ومواعيد الدوام من 8:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060285-68547479.jpg?v=1791573250"]','https://cmsphoto.ww-cdn.com/resizeapi/bd96114a01e04d26a53ab984fd3530d4c348517d/480/',24.6862776,46.6229063,'Al Safarat, Riyadh 12513','','','','https://www.saudi-guide.com/riyadh/i/98060285/little-riyadh-lytl-alryad',1,0,'ليتل رياض little riyadh اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060283,'riyadh','ذا اسبلاند','The Esplanade','the-esplanade-tha-asbland','["أماكن سياحية"]','["sights"]','ذا اسبلاند وجهة ساحرة تجمع بين العلامات التجارية والمطاعم وصالات السينما بأسلوب حديث، وتُعد مركزًا ترفيهيًا متكاملًا سهل التنقل داخله.','<div class="texte" > <p>ذا اسبلاند وجهة ساحرة تجمع بين العلامات التجارية والمطاعم وصالات السينما بأسلوب حديث، وتُعد مركزًا ترفيهيًا متكاملًا سهل التنقل داخله. يتميز بمناظر ليلية جميلة ومواقف سيارات مريحة، ويحظى بشعبية كبيرة كوجهة عائلية للخروجات المسائية بعد الفيلم أو قبله. مواعيد الدوام من 7:00 صباحًا حتى 2:00 فجرًا.</p> </div>','[]','',24.726102,46.6427444,'Prince Turki Bin Abdulaziz Al Awal Rd, King Saud University, Riyadh 12371','','','','https://www.saudi-guide.com/riyadh/i/98060283/the-esplanade-tha-asbland',1,0,'ذا اسبلاند the esplanade اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060263,'riyadh','وصل كافيه','Wasl Cafe','osl-kafyh-wasl-cafe','["كافيهات"]','["cafe"]','وصل كافيه في حي الملقا بالرياض، يتميز بتقديم مجموعة متنوعة من الكروفل والحلويات، ويشتهر بالوافل الطازج والشوكولاتة الساخنة والمشروبات المبتكرة.','<div class="texte" > <p>وصل كافيه يتميز بتقديم مجموعة متنوعة من الكروفل بجانب حلويات أخرى شهية، ويشتهر بالوافل الطازج والشوكولاتة الساخنة المميزة. يقدم مشروبات مبتكرة تناسب الأجواء الباردة، ويحظى بتقييمات جيدة رغم بعض الأعمال الإنشائية المحيطة بالموقع أحيانًا. مواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل (الاثنين-الأربعاء إجازة).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060263-68547502.jpg?v=1791573616", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060263-68547503.jpg?v=1791573641"]','https://cmsphoto.ww-cdn.com/resizeapi/e879af35d906833225960471c06260fb5f14b549/480/',24.780592,46.5777822,'Prince Yazid Ibn Abdullah Ibn Abdulrahman, Al Malqa, Riyadh 23567','','','','https://www.saudi-guide.com/riyadh/i/98060263/osl-kafyh-wasl-cafe',1,0,'وصل كافيه wasl cafe كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060262,'riyadh','عدنية','Adanya','adanya-aadny','["كافيهات"]','["cafe"]','عدنية متخصص بتقديم العدني الساخن والبارد بالإضافة إلى الساندويتشات الشهية، ويشتهر بالتونة الحارة وحلومي السحوق.','<div class="texte" > <p>عدنية متخصص بتقديم العدني الساخن والبارد بالإضافة إلى الساندويتشات الشهية، ويشتهر بالتونة الحارة وحلومي السحوق. يوفر تغليفًا إبداعيًا وخدمة سريعة، ويطل على بوليفارد سيتي ما يجعله وجهة عملية للاستراحة قبل أو بعد استكشاف المنطقة. للتواصل: 0555639986، ومواعيد الدوام من 6:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060262-68547518.jpg?v=1791573736"]','https://cmsphoto.ww-cdn.com/resizeapi/fc0225e66c7cd26a40499a052bbcfb9118bf47db/480/',24.7692918,46.6094134,'Wadi Al Ain, Hittin, Riyadh 13516','0555639986','','','https://www.saudi-guide.com/riyadh/i/98060262/adanya-aadny',1,0,'عدنيه adanya كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060261,'riyadh','كوزفن','Cosefan','cosefan-kozfn','["كافيهات"]','["cafe"]','كوزفن لمحبي الفن والقهوة، يقدم القهوة والمخبوزات اللذيذة بالإضافة إلى الأنشطة الفنية كورش الفخار والرسم.','<div class="texte" > <p>كوزفن لمحبي الفن والقهوة، يقدم القهوة والمخبوزات اللذيذة بالإضافة إلى الأنشطة الفنية كورش الفخار والرسم. يتميز بأجواء نباتية خضراء وإضاءة طبيعية دافئة، ويُعد وجهة مثالية لقضاء وقت إبداعي مع الأصدقاء بعيدًا عن المقاهي التقليدية. للتواصل: 0596200360، ومواعيد الدوام من 12:00 ظهرًا حتى 2:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060261-68547528.jpg?v=1791573840", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060261-68547530.jpg?v=1791573851"]','https://cmsphoto.ww-cdn.com/resizeapi/4866376e2d8b1f07a4aa7a5e1c82d086a8aa3122/480/',24.7549674,46.5495762,'Prince Abdullah Abdul Rahman, Al Diriyah Al Jadidah, Diriyah 13732','0596200360','','','https://www.saudi-guide.com/riyadh/i/98060261/cosefan-kozfn',1,0,'كوزفن cosefan كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060260,'riyadh','جازين','Jazean','jazean-gazyn','["كافيهات"]','["cafe"]','جازين يشتهر بتقديم أفضل بن من موطن أرابيكا لعشاق القهوة بالطعم الأصلي، ويقع في موقع مميز داخل الحي الدبلوماسي.','<div class="texte" > <p>جازين يشتهر بتقديم أفضل بن من موطن أرابيكا لعشاق القهوة بالطعم الأصلي، ويقع في موقع مميز داخل الحي الدبلوماسي. يشتهر بالساندويتش الحار والحلومي بالسحوق، ويحظى بتقدير خاص للمنتجات المحلية والهدايا المعبأة بعناية فائقة تعكس الضيافة السعودية. للتواصل: 920012063، ومواعيد الدوام من 8:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060260-68547534.jpg?v=1791573931", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060260-68547535.jpg?v=1791573943"]','https://cmsphoto.ww-cdn.com/resizeapi/d276f42432b59605c0e74f12b23b0f88f78acfeb/480/',24.6858552,46.628366,'Diplomatic Quarter, Riyadh 12512','920012063','','','https://www.saudi-guide.com/riyadh/i/98060260/jazean-gazyn',1,0,'جازين jazean كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060256,'riyadh','ميت أب كافيه آند باستري','Meetup Cafe & Pastry','meetup-cafe-pastry-myt-ab-kafyh-and-bastry','["كافيهات"]','["cafe"]','ميت أب كافيه آند باستري يقدم مجموعة واسعة من المخبوزات الشهية بجانب القهوة بأجواء مناسبة للعمل والدراسة، ويشتهر بالقهوة الإثيوبية والقطايف بالكريمة الحلوة.','<div class="texte" > <p>Meetup Cafe &amp; Pastry يقدم مجموعة واسعة من المخبوزات الشهية بجانب القهوة بأجواء مناسبة للعمل والدراسة، ويشتهر بالقهوة الإثيوبية والقطايف بالكريمة الحلوة. يوفر خصمًا خاصًا للطلاب وأشعة شمس طبيعية جميلة تمنح المكان أجواءً هادئة ومريحة. للتواصل: 0502947716، ومواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060256-68547550.jpg?v=1791574150"]','https://cmsphoto.ww-cdn.com/resizeapi/14141000106ecfd177c2a688cfd8b5176b74b519/480/',24.8088604,46.6273281,'Olaya St, As Sahafah, Riyadh 13321','0502947716','','','https://www.saudi-guide.com/riyadh/i/98060256/meetup-cafe-pastry-myt-ab-kafyh-and-bastry',1,0,'ميت اب كافيه اند باستري meetup cafe & pastry كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060255,'riyadh','تريستي','Trieste','trieste-trysty','["كافيهات"]','["cafe"]','تريستي يتميز بتقديم مجموعة واسعة متنوعة من الحلويات الشهية بإطلالة جلسات رائعة على طابقين، ويشتهر بالكوكيز المحشو بالشوكولاتة السائلة.','<div class="texte" > <p>تريستي يتميز بتقديم مجموعة واسعة متنوعة من الحلويات الشهية بإطلالة جلسات رائعة على طابقين، ويشتهر بالكوكيز المحشو بالشوكولاتة السائلة. يعمل على مدار الساعة طوال أيام الأسبوع، ويحظى بتقييمات متفاوتة حول جودة القهوة رغم إجماع على تميز الحلويات. مواعيد الدوام: 24 ساعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060255-68547565.jpg?v=1791574243", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060255-68547566.jpg?v=1791574253"]','https://cmsphoto.ww-cdn.com/resizeapi/6bfaab6f9f33f948bd9b3c32c697f9586c7b3af6/480/',24.7415816,46.6453797,'Al Takhassousi, An Nakheel, Riyadh 12382','','','','https://www.saudi-guide.com/riyadh/i/98060255/trieste-trysty',1,0,'تريستي trieste كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060252,'riyadh','كويارد','Coyard','coyard-koyard','["كافيهات"]','["cafe"]','كويارد مقهى هادئ يقدم القهوة الرائعة ويوفر أجواء مثالية للعمل والدراسة، ويشتهر بمشروب البينا كولادا والماتشا بطعم أصيل غير محلى بشكل مصطنع.','<div class="texte" > <p>كويارد مقهى هادئ يقدم القهوة الرائعة ويوفر أجواء مثالية للعمل والدراسة، ويشتهر بمشروب البينا كولادا والماتشا بطعم أصيل غير محلى بشكل مصطنع. يحظى بخدمة ودودة من الباريستا ويوضح تفاصيل المنتجات بصبر للزوار الجدد. للتواصل: 0552645213، ومواعيد الدوام من 7:00 صباحًا حتى 11:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060252-68547570.jpg?v=1791574326"]','https://cmsphoto.ww-cdn.com/resizeapi/910d9d07c34d60d612c89e4567a0fcccc8a462f3/480/',24.7460993,46.724544,'King Abdullah Dt., Riyadh 12445','0552645213','','','https://www.saudi-guide.com/riyadh/i/98060252/coyard-koyard',1,0,'كويارد coyard كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060251,'riyadh','مقهى كارف','Carve Coffee Bar','carve-coffee-bar-mkha-karf','["كافيهات"]','["cafe"]','مقهى كارف لأصحاب الأذواق المختلفة يشتهر بتقديم ألذ قهوة والشوكولاتة الساخنة في أجواء هادئة، ويتميز بتقديم كوبين إما ورقي أو سيراميك حسب الرغبة.','<div class="texte" > <p>مقهى كارف لأصحاب الأذواق المختلفة يشتهر بتقديم ألذ قهوة والشوكولاتة الساخنة في أجواء هادئة، ويتميز بتقديم كوبين إما ورقي أو سيراميك حسب الرغبة. يشتهر بتشيز كيك التوت المشكل والفلات وايت المتقن، رغم بعض الملاحظات على صعوبة إيجاد موقف سيارات. للتواصل: 0505745780، ومواعيد الدوام من 6:00 صباحًا حتى 1:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060251-68547576.jpg?v=1791574425", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060251-68547581.jpg?v=1791574443"]','https://cmsphoto.ww-cdn.com/resizeapi/bd4dfde051c2168e04a8f680ca9e7343bf21c6eb/480/',24.7143718,46.6767119,'Al Urubah Rd, Taqhat, Riyadh 12251','0505745780','','','https://www.saudi-guide.com/riyadh/i/98060251/carve-coffee-bar-mkha-karf',1,0,'مقهي كارف carve coffee bar كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060250,'riyadh','محمصة كيل','Kail Roastery','kail-roastery-mhms-kyl','["كافيهات"]','["cafe"]','محمصة كيل مخبز حديث ومبهج يقدم تشكيلة واسعة من المخبوزات النباتية بجانب القهوة المختصة المحمصة في الموقع نفسه.','<div class="texte" > <p>محمصة كيل مخبز حديث ومبهج يقدم تشكيلة واسعة من المخبوزات النباتية بجانب القهوة المختصة المحمصة في الموقع نفسه. يتميز بتصميم داخلي مضيء ونوافذ غير تقليدية الشكل، مع إطلالة ليلية جميلة على برج المملكة من الجلسات الخارجية. للتواصل: 0530668391، ومواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060250-68547599.jpg?v=1791574526"]','https://cmsphoto.ww-cdn.com/resizeapi/f76c49ee7b42a4c5b7c9a0dca6ccdd597ef03f7a/480/',24.7254863,46.6781633,'Prince Sultan Bin Abdulaziz Al Amar St, Al Worood, Riyadh 12253','0530668391','','','https://www.saudi-guide.com/riyadh/i/98060250/kail-roastery-mhms-kyl',1,0,'محمصه كيل kail roastery كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060249,'riyadh','صحبه','Sohba Coffee','sohba-coffee-shbh','["كافيهات"]','["cafe"]','صحبه مقهى يقدم المشروبات المتنوعة والمخبوزات الطازجة في مساحة ممتعة ولطيفة، ويشتهر بكعكة العسل والكيك المجرة إلى جانب اللاتيه المتقن.','<div class="texte" > <p>صحبه مقهى يقدم المشروبات المتنوعة والمخبوزات الطازجة في مساحة ممتعة ولطيفة، ويشتهر بكعكة العسل والكيك المجرة إلى جانب اللاتيه المتقن. يُعد من أفضل تجارب القهوة المختصة في الرياض بفضل ديكوره المريح المناسب للعمل والدراسة. مواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060249-68547621.jpg?v=1791574604"]','https://cmsphoto.ww-cdn.com/resizeapi/417380080d36026845ab6a8b8ee65e5f2e34093f/480/',24.8116775,46.604024,'Wadi Hajr St, Al Malqa, Riyadh 13252','','','','https://www.saudi-guide.com/riyadh/i/98060249/sohba-coffee-shbh',1,0,'صحبه sohba coffee كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060248,'riyadh','1/2 مليون','Half Million','half-million-1-2-mlyon','["كافيهات"]','["cafe"]','يشتهر بالماتشا لاتيه وأكواب التذكارات القابلة للتحصيل التي تجذب أعدادًا كبيرة من الزوار عند إصدار كل تصميم جديد.','<div class="texte" > <p>1/2 مليون مقهى محلي مستوحى من المقاهي الحديثة مع فروع متعددة لخدمة السيارات (درايف ثرو)، ويعمل على مدار الساعة طوال أيام الأسبوع. يشتهر بالماتشا لاتيه وأكواب التذكارات القابلة للتحصيل التي تجذب أعدادًا كبيرة من الزوار عند إصدار كل تصميم جديد. للتواصل: 920014022، ويعمل 24 ساعة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060248-68547639.jpg?v=1791574756", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060248-68547640.jpg?v=1791574770"]','https://cmsphoto.ww-cdn.com/resizeapi/76741e6707f29d4d6e7d1155d4ec38c0dc2aa076/480/',24.775925,46.618437,'Prince Muhammad Ibn Saad Ibn Abdulaziz Rd, Al Aqiq, Riyadh 13515','920014022','','','https://www.saudi-guide.com/riyadh/i/98060248/half-million-1-2-mlyon',1,0,'1/2 مليون half million كافيهات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060242,'riyadh','هوم بيكري','Home Bakery','hom-bykry-home-bakery','["مخبوزات"]','["cafe"]','هوم بيكري في حي الملقا بالرياض مخبز وكافيه بأجواء منزلية دافئة، يقدم إفطارًا شهيًا وحلويات مميزة، ويشتهر بالسيميت التركي وكيك الزبدة.','<div class="texte" > <p>هوم بيكري (Home Bakery) مخبز وكافيه بأجواء منزلية دافئة يقدم إفطارًا شهيًا وحلويات مميزة، ويشتهر بالسيميت التركي وكيك الزبدة والمانجو فلوب. يتميز بديكور جميل ونوافذ زجاجية كبيرة تمنحه إحساسًا بالفخامة، ويحظى بخدمة سريعة وودودة حتى في أوقات الازدحام. للتواصل: 0533055568، ومواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060242-68547644.jpg?v=1791574857"]','https://cmsphoto.ww-cdn.com/resizeapi/8beb511935c7236f8adcae997be82d779fc02205/480/',24.806835,46.613574,'Anas Ibn Malik, Al Malqa, Riyadh 13524','0533055568','','','https://www.saudi-guide.com/riyadh/i/98060242/hom-bykry-home-bakery',1,0,'هوم بيكري home bakery مخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060241,'riyadh','تي إف بيكري','TF Bakery','tf-bakery-ty-af-bykry','["مخبوزات"]','["cafe"]','تي إف بيكري مخبز يقدم ساندويشات إفطار طازجة ومعجنات مميزة بأجواء بسيطة وأنيقة، ويشتهر بأومليت الأعشاب على خبز السوردو والكرواسان بالتوت.','<div class="texte" > <p>TF Bakery مخبز يقدم ساندويشات إفطار طازجة ومعجنات مميزة بأجواء بسيطة وأنيقة، ويشتهر بأومليت الأعشاب الفرنسية على خبز السوردو والكرواسان بالتوت الأزرق والكريمة. تُعد قهوته اليومية ممتازة، ورغم صغر مساحة الجلوس الداخلية إلا أن جودة الطعام تعوّض عن ذلك تمامًا. مواعيد الدوام من 6:00 صباحًا حتى 9:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060241-68547653.jpg?v=1791574952", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060241-68547655.jpg?v=1791574964"]','https://cmsphoto.ww-cdn.com/resizeapi/4147e08d6ef45887ddb3064c0c17b3497e09a272/480/',24.7971473,46.6265851,'Al Oumra, Al Malqa, Riyadh 13521','','','','https://www.saudi-guide.com/riyadh/i/98060241/tf-bakery-ty-af-bykry',1,0,'تي اف بيكري tf bakery مخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060239,'riyadh','نوفلز بيكري','House of Novels','house-of-novels-noflz-bykry','["مخبوزات"]','["cafe"]','نوفلز بيكري (House of Novels) مخبز صغير يقدم مخبوزات وحلويات عالية الجودة بخدمة منزلية دافئة، ويحظى بتقييمات استثنائية شبه كاملة من زواره.','<div class="texte" > <p>نوفلز بيكري (House of Novels) مخبز صغير يقدم مخبوزات وحلويات عالية الجودة بخدمة منزلية دافئة، ويحظى بتقييمات استثنائية شبه كاملة من زواره. يشتهر بأسعاره المعقولة وجودة تحضير كل قطعة بعناية فائقة، ويُعد كنزًا مخفيًا يستحق الاكتشاف لعشاق الحلويات الفاخرة. للتواصل: 0511048069، ومواعيد الدوام من 9:00 صباحًا حتى 9:00 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060239-68547659.jpg?v=1791575046", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060239-68547660.jpg?v=1791575059"]','https://cmsphoto.ww-cdn.com/resizeapi/5dcde1559e0d4ea1331f7c61170e8546cdfea8c1/480/',24.7813887,46.7220804,'Al Abbas Bin Abdul Muttalib, Al Izdihar, Riyadh 12486','0511048069','','','https://www.saudi-guide.com/riyadh/i/98060239/house-of-novels-noflz-bykry',1,0,'نوفلز بيكري house of novels مخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060238,'riyadh','لوس بريموس بيكري وكافيه','Los Primos Bakery & Cafe','los-primos-bakery-cafe-los-brymos-bykry-okafyh','["مخبوزات"]','["cafe"]','لوس بريموس بيكري وكافيه مخبز وكافيه يقدم قائمة إفطار شهية بجانب المعجنات والكرواسان الطازج، ويشتهر بساندويش الكلوب والكرواسان بالحلوم.','<div class="texte" > <p>لوس بريموس بيكري وكافيه مخبز وكافيه يقدم قائمة إفطار شهية بجانب المعجنات والكرواسان الطازج، ويشتهر بساندويش الكلوب والكرواسان بالحلوم. يجمع بين تناسق الكافيه والمخبز في مكان واحد بأجواء هادئة، ويحظى بخدمة راقية ومريحة من الموظفين. للتواصل: 0554576000، ومواعيد الدوام من 7:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060238-68547663.jpg?v=1791575167", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060238-68547664.jpg?v=1791575181"]','https://cmsphoto.ww-cdn.com/resizeapi/5b04ab72880661db8a07aab545efaeb49031f575/480/',24.7764732,46.6590397,'Muhammad Al Muqaddami St, Al Ghadir, Riyadh 13311','0554576000','','','https://www.saudi-guide.com/riyadh/i/98060238/los-primos-bakery-cafe-los-brymos-bykry-okafyh',1,0,'لوس بريموس بيكري وكافيه los primos bakery & cafe مخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060237,'riyadh','بارت بيكري','Part Bakery','part-bakery-bart-bykry','["مخبوزات"]','["cafe"]','بارت بيكري (Part Bakery) مخبز يقدم أجواء رائعة مع قهوة ومعجنات لذيذة، ويتميز بأجواء حيوية مناسبة للدراسة والجلوس الطويل.','<div class="texte" > <p>بارت بيكري (Part Bakery) مخبز يقدم أجواء رائعة مع قهوة ومعجنات لذيذة، ويتميز بأجواء حيوية مناسبة للدراسة والجلوس الطويل. يحظى بتقييمات جيدة لجودة القهوة والحلويات الخفيفة، مع ديكور جداري إبداعي يضيف لمسة فنية مميزة للمكان. مواعيد الدوام من 6:00 صباحًا حتى 12:00 منتصف الليل.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060237-68547667.jpg?v=1791575269", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060237-68547669.jpg?v=1791575288"]','https://cmsphoto.ww-cdn.com/resizeapi/7b4c3803048b6d215727965216d832fdcf62b63b/480/',24.7409217,46.6078656,'Salim Ibn Maqil, An Nakheel, Riyadh 12392','','','','https://www.saudi-guide.com/riyadh/i/98060237/part-bakery-bart-bykry',1,0,'بارت بيكري part bakery مخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060236,'riyadh','بسترينا بيكري','Pistrina Bakery','pistrina-bakery-bstryna-bykry','["مخبوزات"]','["cafe"]','بسترينا بيكري (Pistrina Bakery) مخبز يقدم قائمة شهية من المخبوزات والقهوة المميزة بديكور فني جذاب يضم أدوات خبز تراثية وأقمشة متموجة على السقف.','<div class="texte" > <p>بسترينا بيكري (Pistrina Bakery) مخبز يقدم قائمة شهية من المخبوزات والقهوة المميزة بديكور فني جذاب يضم أدوات خبز تراثية وأقمشة متموجة على السقف. يشتهر بعجلة البيكان وعجلة الجبن بالعسل الخفيفة والمقرمشة، ويحظى بتقييمات ممتازة لتفرد نكهة قهوته. للتواصل: 0534554148، ومواعيد الدوام من 7:00 صباحًا حتى 4:00 فجرًا.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060236-68547676.jpg?v=1791575367", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060236-68547677.jpg?v=1791575378"]','https://cmsphoto.ww-cdn.com/resizeapi/95bc20e36ef4a0a6c78dbb6f031153a5a149bdec/480/',24.8333024,46.6576151,'Abi Bakr As Siddiq Rd, Al Yasmeen, Riyadh 13315','0534554148','','','https://www.saudi-guide.com/riyadh/i/98060236/pistrina-bakery-bstryna-bykry',1,0,'بسترينا بيكري pistrina bakery مخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98060235,'riyadh','مخابز الحطب','Wooden Bakery','wooden-bakery-mkhabz-alhtb','["مخبوزات"]','["cafe"]','مخابز الحطب (Wooden Bakery) مخبز لبناني شهير يقدم تشكيلة واسعة من الخبز والمعجنات والكيك بجودة عالية، ويشتهر بالكرواسان والأجبان واللحوم الباردة والزيتون.','<div class="texte" > <p>مخابز الحطب (Wooden Bakery) مخبز لبناني شهير يقدم تشكيلة واسعة من الخبز والمعجنات والكيك بجودة عالية، ويشتهر بالكرواسان والأجبان واللحوم الباردة والزيتون. يتميز بنظافته العالية وتنوع منتجاته الصحية، ويُعد من أكثر المخابز موثوقية وانتشارًا في الرياض بعدة فروع. للتواصل: 0501338321، ومواعيد الدوام من 7:00 صباحًا حتى 11:30 مساءً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98060235-68547682.jpg?v=1791575454"]','https://cmsphoto.ww-cdn.com/resizeapi/ade7321ed1ce5a9f8540a9970bd8f9b58f7f7e92/480/',24.6941192,46.7226815,'Salah Ad Din Al Ayyubi Rd, As Sulimaniyah, Riyadh 12233','0501338321','','','https://www.saudi-guide.com/riyadh/i/98060235/wooden-bakery-mkhabz-alhtb',1,0,'مخابز حطب wooden bakery مخبوزات',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080249,'hail','مدينة الفيرا الترفيهية','Lafira Land','lafira-land-mdyn-alfyra-altrfyhy','["أماكن سياحية"]','["sights"]','مدينة الفيرا الترفيهية في حائل وجهة متكاملة تضم عجلة عملاقة وألعاباً متنوعة للأطفال والعائلات، إلى جانب مطاعم وعربات طعام ومقاهٍ.','<div class="texte" > <p>اكتشف مدينة ترفيهية تكاملية تجمع بين الألعاب المشوقة والفعاليات المميزة بمدينة حائل، إذ تضم عجلة عملاقة ومجموعة متنوعة من الألعاب المناسبة للأطفال والعائلات، بالإضافة إلى مطاعم وعربات طعام ومقاهي متنوعة. رسوم الدخول 11 ريالاً، وللتواصل: 0539355433.</p> </div>','[]','',27.4858004,41.700806,'الفرزدق، البحيرة، حائل 55422','+966539355433','','','https://www.saudi-guide.com/hail/i/98080249/lafira-land-mdyn-alfyra-altrfyhy',1,0,'مدينه فيرا ترفيهيه lafira land اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080248,'hail','جامبولين','Jumpoline','jumpoline-gambolyn','["أماكن سياحية"]','["sights"]','جامبولين في مدينة حائل مركز ترامبولين يوفر مساحات واسعة للقفز والحركة، وتجربة مليئة بالطاقة والمرح تناسب الأطفال والشباب.','<div class="texte" > <p>أطلق العنان للمرح والمتعة في تجربة مليئة بالقفز والطاقة بمدينة حائل، حيث توفر منطقة الترامبولين مساحات واسعة للقفز والحركة تناسب الأطفال والشباب. تعمل يومياً من 3 عصراً حتى منتصف الليل، وللتواصل: 0556540110.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080248-68548591.jpg?v=1791584008"]','https://cmsphoto.ww-cdn.com/resizeapi/2dac72dc9f2563e4841cc44c81c183b8aa6c1929/480/',27.5543125,41.6814375,'حي أجا، حائل 55427','+966556540110','','','https://www.saudi-guide.com/hail/i/98080248/jumpoline-gambolyn',1,0,'جامبولين jumpoline اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080247,'hail','يلو للترفيه','Yello Entertainment','yello-entertainment-ylo-lltrfyh','["أماكن سياحية"]','["sights"]','يلو للترفيه في مدينة حائل مركز ألعاب حركية للأطفال يضم ألعاباً آمنة ومنظمة، إلى جانب ركن لرسم الوجه واشتراكات مخصصة للأطفال.','<div class="texte" > <p>استمتع بتجربة لعب حركية لألعاب الأطفال مليئة بالمتعة والمرح بمدينة حائل، ويضم المركز مجموعة متنوعة من الألعاب الآمنة والمنظمة، بالإضافة إلى ركن لرسم الوجه واشتراكات للأطفال. يعمل يومياً من 4 عصراً حتى منتصف الليل، وللتواصل: 0549097755.</p> </div>','[]','',27.4415513,41.6122176,'الأمير سعود بن عبدالمحسن، الرصف، حائل 55439','+966549097755','','','https://www.saudi-guide.com/hail/i/98080247/yello-entertainment-ylo-lltrfyh',1,0,'يلو للترفيه yello entertainment اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080244,'qassim-region','جمار','Jammar','jammar-gmar','["أماكن سياحية"]','["sights"]','جمار مزرعة عصرية في مدينة عنيزة تضم مقاهي ومطاعم متنوعة، وتتميز بتراس هادئ وتصميم مريح غني بالتفاصيل التراثية الدافئة.','<div class="texte" > <p>مزرعة عصرية بمدينة عنيزة تضم العديد من المقاهي والمطاعم المتنوعة بأجواء مميزة، وتتميز بتراس جميل هادئ وتصميم مريح غني بالتفاصيل التراثية التي تمنح المكان شعوراً بالدفء والترحيب.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080244-68548603.jpg?v=1791584138", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080244-68548606.jpg?v=1791584144"]','https://cmsphoto.ww-cdn.com/resizeapi/b31875d95b8d8985e1e8b4944932480851f58c30/480/',26.1021427,43.9828235,'أبي البقاء العمري، الشريميّة، عنيزة 56219','','','','https://www.saudi-guide.com/qassim-region/i/98080244/jammar-gmar',1,0,'جمار jammar اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080243,'qassim-region','غضراء','Ghadraa','ghadraa-ghdra','["أماكن سياحية"]','["sights"]','غضراء في مدينة عنيزة موقع أنيق بجلسات خارجية وسط أشجار النخيل، وأجواء هادئة تناسب شرب القهوة والشاي بين أحضان الطبيعة.','<div class="texte" > <p>غضراء بمدينة عنيزة موقع أنيق يتميز بجلساته الخارجية وسط أشجار النخيل، ويوفر لحظات استثنائية وتجربة لا تُنسى بين أحضان الطبيعة، مع أجواء هادئة تناسب شرب القهوة والشاي.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080243-68548619.jpg?v=1791584200"]','https://cmsphoto.ww-cdn.com/resizeapi/d3a435b82c45d81ff9b4b9269234421cd5a17310/480/',26.0164599,43.9361813,'ربوة الحاجب، عنيزة 56275','','','','https://www.saudi-guide.com/qassim-region/i/98080243/ghadraa-ghdra',1,0,'غضراء ghadraa اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080242,'qassim-region','جادة عسيب','Jadat Aseeb','jadat-aseeb-gad-aasyb','["أماكن سياحية"]','["sights"]','جادة عسيب في مدينة بريدة وجهة نابضة بالحياة تجمع المقاهي والمحلات المتنوعة، وتشتهر بمقاهيها التراثية وقهوتها المختصة وحلوياتها.','<div class="texte" > <p>جادة عسيب بمدينة بريدة وجهة نابضة بالحياة تجمع بين المقاهي والمحلات المتنوعة التي تناسب كل الأذواق، وتشتهر بمقاهيها التراثية التي تقدم قهوة مختصة وحلويات مميزة وسط أجواء تراثية أصيلة تحاكي عبق الماضي. تعمل يومياً من 2 ظهراً حتى 3 فجراً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080242-68548630.jpg?v=1791584256"]','https://cmsphoto.ww-cdn.com/resizeapi/26b88410fda28e69ac0e8f5df772d0ace0390e18/480/',26.3169514,43.9721147,'حي الجنوب، عسيب، بريدة 52354','','','','https://www.saudi-guide.com/qassim-region/i/98080242/jadat-aseeb-gad-aasyb',1,0,'جاده عسيب jadat aseeb اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080241,'qassim-region','مزرعة ريفا','Reva Farm','reva-farm-mzraa-ryfa','["أماكن سياحية"]','["sights"]','مزرعة ريفا في عنيزة تقدم فطوراً ريفياً ومنتجات طازجة، مع تجربة إطعام الماعز وركوب الحيوانات، ما يجعلها وجهة مثالية للعائلات.','<div class="texte" > <p>مزرعة ريفا بمدينة عنيزة تقدم فطوراً لذيذاً ومنتجات طازجة وسط الأجواء الريفية، ويمكنك خلالها عيش تجربة فعالية إطعام الماعز والاستمتاع بركوب الحيوانات، ما يجعلها وجهة مثالية للعائلات. تعمل يومياً من 4 حتى 9 صباحاً، وللتواصل: 0541607799.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080241-68548649.jpg?v=1791584322"]','https://cmsphoto.ww-cdn.com/resizeapi/fa2b836943dd462177272261f0448b96c5b073a3/480/',26.01709,43.9291957,'ربوة الحاجب، عنيزة 51911','+966541607799','','','https://www.saudi-guide.com/qassim-region/i/98080241/reva-farm-mzraa-ryfa',1,0,'مزرعه ريفا reva farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080240,'qassim-region','سوق المسوكف الشعبي','Al Musawkaf Market','al-musawkaf-market-sok-almsokf-alshaaby','["أماكن سياحية"]','["sights"]','سوق المسوكف الشعبي في عنيزة قطعة من إرث القصيم العمراني، يستحضر أجواء الماضي بمناداة الدلالين والقطع الأثرية والأكلات الشعبية.','<div class="texte" > <p>سوق المسوكف الشعبي في عنيزة يمثل قطعة عزيزة من إرث القصيم العمراني، حيث يمكنك التجول في سوق تقليدي ينبض بالحياة ويستحضر أجواء الماضي بمناداة الدلالين وبيع القطع الأثرية النادرة، مع معرض تراثي وغرف متنوعة تعكس جوانب من التاريخ والثقافة، ومحلات تبيع المنتجات المحلية والأكلات الشعبية الدافئة. يعمل يومياً من 4 حتى 9:30 مساءً، وللتواصل: 0559829449.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080240-68548663.jpg?v=1791584392"]','https://cmsphoto.ww-cdn.com/resizeapi/af311380a490e7eb612537d1606f2c46d6c9b45e/480/',26.0889335,43.9669143,'طريق الوهلان، الدليعة، عنيزة 56219','+966559829449','','','https://www.saudi-guide.com/qassim-region/i/98080240/al-musawkaf-market-sok-almsokf-alshaaby',1,0,'سوق مسوكف شعبي al musawkaf market اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080239,'qassim-region','جادة النخيل','Jadat Al Nakheel','jadat-al-nakheel-gad-alnkhyl','["أماكن سياحية"]','["sights"]','جادة النخيل في مدينة عنيزة ممشى خلاب يمتد بين مزرعة نخيل كبيرة، تحيط به المقاهي المتنوعة وسط أجواء طبيعية نقية وهواء منعش.','<div class="texte" > <p>جادة النخيل بمدينة عنيزة موقع خلاب يمتد بين مزرعة نخيل كبيرة، تحيط به المقاهي المتنوعة حيث يمكنك الجلوس والاسترخاء مع كوب قهوة وسط أجواء طبيعية نقية وهواء منعش. تعمل يومياً من 5:30 مساءً حتى 5:30 فجراً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080239-68548673.jpg?v=1791584468"]','https://cmsphoto.ww-cdn.com/resizeapi/f91702e6b513b2c3bcc46638da2d70ffe601c4e1/480/',26.0964606,43.9686837,'حي مربيدة، عنيزة 56219','','','','https://www.saudi-guide.com/qassim-region/i/98080239/jadat-al-nakheel-gad-alnkhyl',1,0,'جاده نخيل jadat al nakheel اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080238,'qassim-region','متحف الشماسية التراثي','Al Shamasiyah Heritage Museum','al-shamasiyah-heritage-museum-mthf-alshmasy-altrathy','["التراث والثقافة"]','["heritage"]','متحف الشماسية التراثي يعرض مقتنيات تاريخية ومخطوطات نادرة وأشجار أنساب لعائلات الشماسية، أسسه الأستاذ عبدالله البراك بترخيص رسمي.','<div class="texte" > <p>متحف الشماسية التراثي بوابة إلى عالم الماضي، يعرض تشكيلة متنوعة من المقتنيات التاريخية النادرة والمخطوطات النادرة، بالإضافة إلى أشجار الأنساب لعدة عائلات في الشماسية، أسسه الأستاذ عبدالله البراك ومرخص من الهيئة العامة للسياحة. يعمل يومياً من 8 صباحاً حتى 11:30 مساءً، وللتواصل: 0503982006.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080238-68548697.jpg?v=1791584580"]','https://cmsphoto.ww-cdn.com/resizeapi/1efdbabf1f76c59f9d9978c20dff553a631b3478/480/',26.3275252,44.2532348,'المتحف، الشماسية 52426','+966503982006','','','https://www.saudi-guide.com/qassim-region/i/98080238/al-shamasiyah-heritage-museum-mthf-alshmasy-altrathy',1,0,'متحف شماسيه تراثي al shamasiyah heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080237,'qassim-region','منتزه البحيرة','Lake Park','lake-park-mntzh-albhyr','["أماكن سياحية"]','["sights"]','منتزه البحيرة في محافظة المذنب حديقة خلابة بتصميم فريد تضم بحيرة وشلالات، مع مقاهٍ وعربات طعام متنوعة توفر أجواء مثالية للاسترخاء.','<div class="texte" > <p>منتزه البحيرة بمحافظة المذنب حديقة خلابة بتصميم فريد، تضم بحيرة وشلالات تزين المكان، بالإضافة إلى مقاهي وعربات طعام متنوعة توفر أجواء مثالية للاسترخاء، ومسجد قريب منها. يعمل على مدار الساعة يومياً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080237-68548709.jpg?v=1791584642"]','https://cmsphoto.ww-cdn.com/resizeapi/b6abc4da0e3a6e89acdf8c75e45f745759cdf339/480/',25.8791917,44.205863,'طريق الملك عبدالعزيز، الروضة، المذنب 56643','','','','https://www.saudi-guide.com/qassim-region/i/98080237/lake-park-mntzh-albhyr',1,0,'منتزه بحيره lake park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080234,'qassim-region','محمية الأوسية','Al Awsaiyah Reserve','al-awsaiyah-reserve-mhmy-alaosy','["أماكن سياحية"]','["sights"]','محمية الأوسية في مدينة عنيزة رحلة ساحرة بين ألوان الطيور وأصواتها المميزة، يلتقي فيها سحر الطبيعة بعبق التاريخ مع مقهى جميل.','<div class="texte" > <p>محمية الأوسية بمدينة عنيزة رحلة ساحرة بين ألوان الطيور وأصواتها المميزة، حيث يلتقي سحر الطبيعة بعبق التاريخ، وتضم مقهى جميلاً وسط أجواء الطيور. تعمل يومياً من 5 حتى 9 صباحاً ومن 3 عصراً حتى منتصف الليل، وللتواصل: 0545779476.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080234-68548716.jpg?v=1791584695", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080234-68548719.jpg?v=1791584702"]','https://cmsphoto.ww-cdn.com/resizeapi/d13a446bd0347662f97ce570a0501311f93063f7/480/',26.0939208,43.9689389,'الدائري الداخلي، عنيزة 56219','+966545779476','','','https://www.saudi-guide.com/qassim-region/i/98080234/al-awsaiyah-reserve-mhmy-alaosy',1,0,'محميه اوسيه al awsaiyah reserve اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080205,'albaha','بلجرشي مول','Baljurashi Mall','baljurashi-mall-blgrshy-mol','["أسواق"]','["shopping"]','بلجرشي مول من المراكز التجارية الرئيسية في محافظة بلجرشي بمنطقة الباحة، يضم محلات متنوعة تخدم الأهالي والزوار في مكان واحد.','<div class="texte" > <p>بلجرشي مول أحد المراكز التجارية الرئيسية بمحافظة بلجرشي، يضم مجموعة من المحلات التجارية المتنوعة التي تخدم أهالي المحافظة والزوار على حد سواء.</p> </div>','[]','',19.8839772,41.5676407,'المحمدية، بلجرشي 65627','','','','https://www.saudi-guide.com/albaha/i/98080205/baljurashi-mall-blgrshy-mol',1,0,'بلجرشي مول baljurashi mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080204,'albaha','العطية مول','Al Atiyah Mall','al-atiyah-mall-alaaty-mol','["أسواق"]','["shopping"]','العطية مول في محافظة بلجرشي وجهة تسوق تضم سوبر ماركت كبيراً ومحلات للملابس والإكسسوارات ومنطقة ترامبولين ترفيهية للأطفال.','<div class="texte" > <p>العطية مول من الوجهات التسوقية بمحافظة بلجرشي، يضم سوبر ماركت كبيراً ومحلات متنوعة للإكسسوارات والملابس، بالإضافة إلى منطقة ترامبولين ترفيهية للأطفال. يعمل يومياً من 8 صباحاً حتى منتصف الليل تقريباً، وللتواصل: 0555774449.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080204-68548757.jpg?v=1791584830"]','https://cmsphoto.ww-cdn.com/resizeapi/8b246d1886f8a249956ba20925c5f5cdee1f52fd/480/',19.8415603,41.5911591,'15، بلجرشي 65637','+966555774449','','','https://www.saudi-guide.com/albaha/i/98080204/al-atiyah-mall-alaaty-mol',1,0,'عطيه مول al atiyah mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080203,'albaha','الغنيم مول','Al Ghunaim Mall','al-ghunaim-mall-alghnym-mol','["أسواق"]','["shopping"]','الغنيم مول من أقدم وأكبر المولات في قلب مدينة الباحة، يضم محلات للملابس والإكسسوارات وسوبر ماركت، ويطل على الجبال المحيطة.','<div class="texte" > <p>يُعد الغنيم مول من أكبر وأقدم المولات في مدينة الباحة، ويقع في قلب المدينة، ويتميز بإطلالة رائعة على الجبال المحيطة من الجهة الخلفية للمول. يضم مجموعة متنوعة من المحلات التجارية للملابس والإكسسوارات، بالإضافة إلى سوبر ماركت كبير. يعمل يومياً من 8:30 صباحاً حتى منتصف الليل تقريباً (ويوم الجمعة من 4:30 عصراً).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080203-68548787.jpg?v=1791584972"]','https://cmsphoto.ww-cdn.com/resizeapi/d59eb809b1b7d06b3e4952e445f64604307daa9f/480/',20.007072,41.4516393,'طريق الجنوب، وسط المدينة، الباحة 65522','','','','https://www.saudi-guide.com/albaha/i/98080203/al-ghunaim-mall-alghnym-mol',1,0,'غنيم مول al ghunaim mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080202,'albaha','الباحة مول','Al Baha Mall','al-baha-mall-albah-mol','["أسواق"]','["shopping"]','الباحة مول من أحدث وجهات التسوق في مدينة الباحة، يضم علامات تجارية محلية وعالمية ومطاعم ومقاهي وأنشطة ترفيهية للأطفال.','<div class="texte" > <p>الباحة مول من أحدث الوجهات التسوقية بمدينة الباحة، يضم مجموعة واسعة من العلامات التجارية المحلية والعالمية، بالإضافة إلى مطاعم ومقاهي متنوعة وسط ممرات واسعة ومرافق نظيفة، ويوفر أنشطة ترفيهية للأطفال. يعمل يومياً من 8 صباحاً حتى منتصف الليل (ويوم الجمعة من 4 عصراً).</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080202-68548799.jpg?v=1791585025", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080202-68548800.jpg?v=1791585033"]','https://cmsphoto.ww-cdn.com/resizeapi/f274ff34cca84220700bb973f202298816a4d263/480/',20.072541,41.528153,'الشروق، الباحة 65715','','','','https://www.saudi-guide.com/albaha/i/98080202/al-baha-mall-albah-mol',1,0,'باحه مول al baha mall اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080198,'albaha','حديقة نشمة','Nashmah Park','nashmah-park-hdyk-nshm','["أماكن سياحية"]','["sights"]','حديقة نشمة في محافظة غامد الزناد بتصميم جميل ومسارات مخصصة للدراجات وألعاب للأطفال، وجهة عائلية مثالية في أمسيات الباحة المنعشة.','<div class="texte" > <p>حديقة نشمة بمحافظة غامد الزناد تتميز بتصميمها الجميل ومساراتها المخصصة للدراجات وألعاب الأطفال، وتُعد وجهة مثالية للعائلات لقضاء أوقات ممتعة، خاصة في ساعات المساء بأجواء هادئة ومنعشة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080198-68548801.jpg?v=1791585085"]','https://cmsphoto.ww-cdn.com/resizeapi/7a1f4f807eb53fb488c2998648c324c6ad2c353e/480/',19.7217844,41.4820649,'غامد الزناد 65443','','https://baha.gov.sa/ar/Albums/ImageDetails/473','','https://www.saudi-guide.com/albaha/i/98080198/nashmah-park-hdyk-nshm',1,0,'حديقه نشمه nashmah park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080194,'albaha','منتزه شائقة','Shaiqah Park','shaiqah-park-mntzh-shayk','["أماكن سياحية"]','["sights"]','منتزه وحديقة شائقة في منطقة الباحة بمساحات خضراء واسعة ومرافق ترفيهية، تقابله مجموعة من المطاعم ليكون وجهة مفضلة للعائلات والأصدقاء.','<div class="texte" > <p>منتزه وحديقة شائقة بمحافظة العقيق يتميز بمساحاته الخضراء الواسعة ومرافقه الترفيهية، ويقابله مجموعة من المطاعم، ما يجعله وجهة مفضلة لقضاء أوقات ممتعة مع العائلة أو الأصدقاء.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080194-68548802.jpg?v=1791585140", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080194-68548803.jpg?v=1791585147"]','https://cmsphoto.ww-cdn.com/resizeapi/7511949d1de6ba9118e41617ab6d7d143032e24a/480/',20.2664987,41.6510047,'العقيق 65912','','https://baha.gov.sa/ar/Albums/ImageDetails/468','','https://www.saudi-guide.com/albaha/i/98080194/shaiqah-park-mntzh-shayk',1,0,'منتزه شائقه shaiqah park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080189,'albaha','حديقة السلام','Al Salam Park','al-salam-park-hdyk-alslam','["أماكن سياحية"]','["sights"]','حديقة السلام في محافظة بلجرشي وجهة عائلية بأجواء منعشة ومناخ لطيف، تضم مساحات لعب للأطفال ومقاعد مريحة للجلوس وقضاء وقت هادئ.','<div class="texte" > <p>حديقة السلام بمحافظة بلجرشي وجهة عائلية جميلة بأجواء منعشة ومناخ لطيف، تضم مساحات لعب للأطفال ومقاعد مريحة للجلوس والاستمتاع بوقت هادئ مع العائلة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080189-68548806.jpg?v=1791585208"]','https://cmsphoto.ww-cdn.com/resizeapi/f66f500e19eb8fe887a337be353c613d5a05df43/480/',19.8337632,41.6255765,'بلجرشي 65656','','https://baha.gov.sa/ar/Albums/ImageDetails/456','','https://www.saudi-guide.com/albaha/i/98080189/al-salam-park-hdyk-alslam',1,0,'حديقه سلام al salam park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080139,'albaha','مزرعة الحصن الريفية','Al Hisn Rural Farm','al-hisn-rural-farm-mzraa-alhsn-alryfy','["مزارع"]','["nature"]','مزرعة الحصن الريفية في بني حسن مزرعة أنيقة يقطف فيها الزوار الخوخ، وتضم متحفاً تراثياً وممرات مشي ومقهى وخيولاً للأطفال.','<div class="texte" > <p>مزرعة الحصن الريفية بمحافظة بني حسن مزرعة صغيرة أنيقة ومرتبة بعناية، يسمح صاحبها للزوار بقطف الخوخ مباشرة من الأشجار، وتضم متحفاً تراثياً جميلاً وممرات مشي ومطعماً ومقهى يقدم الكيك والبسبوسة والشاي، بالإضافة إلى طيور وخيول للركوب مناسبة للأطفال، وإطلالة رائعة على الوادي. تعمل يومياً من 4 حتى 11:30 مساءً، وللتواصل: 0555519464.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080139-68548819.jpg?v=1791585261"]','https://cmsphoto.ww-cdn.com/resizeapi/442ab377919f14915289671e7161ec4626d7bbd0/480/',20.137933,41.3413482,'وادي الصدر، بني حسن 65743','+966555519464','https://baha.gov.sa/ar/Albums/ImageDetails/491','','https://www.saudi-guide.com/albaha/i/98080139/al-hisn-rural-farm-mzraa-alhsn-alryfy',1,0,'مزرعه حصن ريفيه al hisn rural farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080138,'albaha','مزرعة حسن الشنتير','Al Shantir Farm','al-shantir-farm-mzraa-hsn-alshntyr','["مزارع"]','["nature"]','مزرعة الشنتير في محافظة القرى وجهة ريفية هادئة تشتهر بالتوت الأسود الطازج، وتضم مقهى وجلسات تطل على المزرعة والنوافير.','<div class="texte" > <p>مزرعة الشنتير بمحافظة القرى من أفضل الوجهات السياحية في الباحة، تجمع بين الجمال الطبيعي الآسر والأجواء الهادئة، وتشتهر بمنتجها الطازج من التوت الأسود، بالإضافة إلى مقهى يقدم تشكيلة متنوعة من المشروبات وجلسات خاصة بإطلالة على المزرعة والنافورات. تعمل يومياً من 5 صباحاً حتى منتصف الليل تقريباً، وللتواصل: 0558697074.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080138-68299823.jpg?v=1789817416"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080138-68299823.jpg?v=1789817417',20.1903214,41.3346829,'الحكمان، القرى 65796','+966558697074','https://baha.gov.sa/ar/Albums/ImageDetails/424','','https://www.saudi-guide.com/albaha/i/98080138/al-shantir-farm-mzraa-hsn-alshntyr',1,0,'مزرعه حسن شنتير al shantir farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080137,'albaha','مزرعة وأكواخ ريف الأزهر','Reef Al Azhar Farm and Cabins','reef-al-azhar-farm-and-cabins-mzraa-oakoakh-ryf-alazhr','["مزارع"]','["nature"]','ريف الأزهر في محافظة القرى منتجع ريفي بمساحات خضراء واسعة، يضم كبائن إقامة ومقهى ومنطقة ألعاب للأطفال وطيوراً متنوعة.','<div class="texte" > <p>منتجع ريف الأزهر بمحافظة القرى وجهة فاخرة تجمع بين المساحات الخضراء الواسعة وأجواء الاسترخاء التام، ويضم مقهى مميزاً ومنطقة ألعاب للأطفال وطيوراً تضفي لمسة جمالية، بالإضافة إلى كبائن إقامة أنيقة ونظيفة. للتواصل: 0501277400.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080137-68299819.jpg?v=1789817402"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080137-68299819.jpg?v=1789817402',20.3158796,41.3522266,'محمد سعيد حسن كمال، القرى 65942','+966501277400','https://baha.gov.sa/ar/Albums/ImageDetails/489','','https://www.saudi-guide.com/albaha/i/98080137/reef-al-azhar-farm-and-cabins-mzraa-oakoakh-ryf-alazhr',1,0,'مزرعه واكواخ ريف ازهر reef al azhar farm and cabins مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080117,'albaha','مزرعة لاتين بارك','Lateen Park Farm','lateen-park-farm-mzraa-latyn-bark','["مزارع"]','["nature"]','لاتين بارك في محافظة العقيق منتجع ريفي يضم أكواخاً للإقامة ومطعماً ومقهى وقسماً للحيوانات والطيور ومنطقة ألعاب للأطفال.','<div class="texte" > <p>منتجع لاتين بارك بمحافظة العقيق يضم أكواخاً للإقامة ومطعماً ومقهى، بالإضافة إلى قسم للحيوانات والطيور ومنطقة ألعاب للأطفال وشاشة عرض كبيرة لمشاهدة المباريات. يعمل يومياً من 3 حتى 11:30 مساءً، والدخول 10 ريالات للفرد، وللتواصل: 0573700836.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080117-68548822.jpg?v=1791585319", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080117-68548823.jpg?v=1791585327"]','https://cmsphoto.ww-cdn.com/resizeapi/f7505b5f55d4bbb3b014c29f7e0224ebb2d8bd23/480/',20.2480311,41.5791338,'العقيق 65923','+966573700836','https://baha.gov.sa/ar/Albums/ImageDetails/490','','https://www.saudi-guide.com/albaha/i/98080117/lateen-park-farm-mzraa-latyn-bark',1,0,'مزرعه لاتين بارك lateen park farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080115,'albaha','مزرعة عقيق النخل الريفية','Aqiq Al Nakhl Rural Farm','aqiq-al-nakhl-rural-farm-mzraa-aakyk-alnkhl-alryfy','["مزارع"]','["nature"]','مزرعة عقيق النخل في محافظة العقيق مزرعة ريفية كبيرة تضم خيمة بدوية تقليدية ومطعماً وقسماً للحيوانات يضم الأرانب والبط والخيول.','<div class="texte" > <p>مزرعة عقيق النخل للسياحة الريفية بمحافظة العقيق مزرعة كبيرة تضم خدمات متنوعة وخيمة بدوية تقليدية، ويشتهر مطعمها بأطباقه الشهية، بالإضافة إلى قسم للحيوانات يضم الأرانب والبط والخيول. تعمل يومياً من 4:30 عصراً حتى منتصف الليل تقريباً، وللتواصل: 0500009261.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080115-68299807.jpg?v=1789817348"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080115-68299807.jpg?v=1789817349',20.2955402,41.6995157,'خالد بن قيس بن النعمان، العقيق 65811','+966500009261','https://baha.gov.sa/ar/Albums/ImageDetails/437','','https://www.saudi-guide.com/albaha/i/98080115/aqiq-al-nakhl-rural-farm-mzraa-aakyk-alnkhl-alryfy',1,0,'مزرعه عقيق نخل ريفيه aqiq al nakhl rural farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080113,'albaha','مزرعة أرياف السياحية','Aryaf Tourist Farm','aryaf-tourist-farm-mzraa-aryaf-alsyahy','["مزارع"]','["nature"]','مزرعة أرياف السياحية في المخواة منتزه عائلي يضم ألعاب أطفال وجلسات ومقهى ومطعماً وحديقة طيور وأراجيح عملاقة وسط خرير المياه.','<div class="texte" > <p>مزرعة ارياف السياحية بمحافظة المخواة منتزه منظم يجمع مناطق لعب الأطفال وجلسات مريحة ومقهى ومطعماً يقدم الأطباق التقليدية، وحديقة طيور وأراجيح عملاقة وتراموبولين وسكوترات للأطفال، وسط خرير المياه وأصوات الطيور. تعمل يومياً من 4 حتى 11 مساءً، والدخول 20 ريالاً للعائلة، وللتواصل: 0502380759.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080113-68548837.jpg?v=1791585380"]','https://cmsphoto.ww-cdn.com/resizeapi/e1c32e7af0530143240335c0f8a8d9e6f442137d/480/',19.7545,41.4582626,'شارع تحلية مياه، المروة، المخواة 65616','+966502380759','https://baha.gov.sa/ar/Albums/ImageDetails/492','','https://www.saudi-guide.com/albaha/i/98080113/aryaf-tourist-farm-mzraa-aryaf-alsyahy',1,0,'مزرعه ارياف سياحيه aryaf tourist farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080111,'albaha','مزرعة وأكواخ الحازم','Al Hazem Farm and Cabins','al-hazem-farm-and-cabins-mzraa-oakoakh-alhazm','["مزارع"]','["nature"]','مزرعة وأكواخ الحازم في محافظة المندق تجمع بين الأشجار الكثيفة والطبيعة الخضراء ومقهى يقدم القهوة والوجبات الخفيفة للعائلات.','<div class="texte" > <p>مزرعة وأكواخ الحازم الريفية بمحافظة المندق تجمع بين الطبيعة الخضراء والمقهى المميز، وتضم أشجاراً كثيفة ومقهى يقدم قهوة لذيذة ووجبات خفيفة، بموقع جميل يناسب الجلسات العائلية. تعمل يومياً من 7 صباحاً حتى 11 مساءً، وللتواصل: 0558681438.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080111-68299797.jpg?v=1789817311"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080111-68299797.jpg?v=1789817311',20.1980528,41.2532127,'عمضان، المندق 65758','+966558681438','https://baha.gov.sa/ar/Albums/ImageDetails/409','','https://www.saudi-guide.com/albaha/i/98080111/al-hazem-farm-and-cabins-mzraa-oakoakh-alhazm',1,0,'مزرعه واكواخ حازم al hazem farm and cabins مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080109,'albaha','مزرعة الوالدين','Al Walidain Farm','al-walidain-farm-mzraa-aloaldyn','["مزارع"]','["nature"]','مزرعة الوالدين في محافظة بلجرشي مزرعة عائلية أوقفها صاحبها براً بوالديه، وتتميز بأجوائها المحافظة المخصصة للعائلات.','<div class="texte" > <p>مزرعة الوالدين بمحافظة بلجرشي مزرعة عائلية أوقفها صاحبها إحساناً لوالديه، وتتميز بأجواء محافظة إذ لا تسمح بدخول الأفراد بمفردهم. تعمل يومياً من 5 حتى 7 مساءً تقريباً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080109-68548842.jpg?v=1791585447"]','https://cmsphoto.ww-cdn.com/resizeapi/85d124e347632ac6d7d500da456f1d28925030ba/480/',19.8584548,41.5485613,'المدان، بلجرشي 65628','','https://baha.gov.sa/ar/Albums/ImageDetails/247','','https://www.saudi-guide.com/albaha/i/98080109/al-walidain-farm-mzraa-aloaldyn',1,0,'مزرعه والدين al walidain farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080107,'albaha','مزرعة الوادي الريفية','Al Wadi Rural Farm','al-wadi-rural-farm-mzraa-aloady-alryfy','["مزارع"]','["nature"]','مزرعة الوادي الريفية في بلجرشي تضم شاليه واحداً فاخراً مفروشاً يتسع لعائلة كاملة، بخصوصية تامة وسط طبيعة ريفية ساحرة.','<div class="texte" > <p>مزرعة الوادي الريفية بمحافظة بلجرشي تتميز بتصميمها الفاخر وخصوصيتها التامة، حيث تضم شاليه واحداً مفروشاً بأرقى الأثاث يتسع لعائلة كاملة، وسط طبيعة ساحرة تشبه أجواء الريف. للتواصل: 0553117077.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080107-68548857.jpg?v=1791585506"]','https://cmsphoto.ww-cdn.com/resizeapi/a4ea12b10d50820b15991be562117a773b27076c/480/',19.8591891,41.601255,'التلقية، بلجرشي 65627','+966553117077','https://baha.gov.sa/ar/Albums/ImageDetails/458','','https://www.saudi-guide.com/albaha/i/98080107/al-wadi-rural-farm-mzraa-aloady-alryfy',1,0,'مزرعه وادي ريفيه al wadi rural farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080106,'albaha','مزرعة الخازم','Al Khazem Farm','al-khazem-farm-mzraa-alkhazm','["مزارع"]','["nature"]','مزرعة الخازم في محافظة بلجرشي مزرعة واسعة تضم أشجار العنب والتين ومساحات مظللة كبيرة وحيوانات يستمتع بها الأطفال والعائلة.','<div class="texte" > <p>مزرعة الخازم بمحافظة بلجرشي مزرعة واسعة تجمع بين الطبيعة والخضرة، وتضم أشجار العنب والتين، بالإضافة إلى مساحات مظللة كبيرة وحيوانات تسعد الأطفال والعائلة. تعمل يومياً من 8 صباحاً حتى 9 مساءً (ويوم الجمعة من 2 عصراً)، وللتواصل: 0500656557.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080106-68299790.jpg?v=1789817259"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080106-68299790.jpg?v=1789817260',19.8544859,41.602385,'الأشتيبة، بلجرشي 65653','+966500656557','https://baha.gov.sa/ar/Albums/ImageDetails/430','','https://www.saudi-guide.com/albaha/i/98080106/al-khazem-farm-mzraa-alkhazm',1,0,'مزرعه خازم al khazem farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080105,'albaha','مزرعة برشومي السراة','Barshomi Al Sarah Farm','barshomi-al-sarah-farm-mzraa-brshomy-alsra','["مزارع"]','["nature"]','مزرعة برشومي السراة في الباحة متخصصة في التين الشوكي، وتشتهر بآيس كريم الصبار ومنتجاته، مع كرفانات إقامة تطل على المزرعة.','<div class="texte" > <p>مزرعة برشومي السراة بمدينة الباحة متخصصة في زراعة التين الشوكي (الصبار)، وتشتهر بتقديم آيس كريم الصبار الطازج ومنتجاته المميزة، بالإضافة إلى كرفانات للإقامة تطل على حديقة التين الشوكي والتوت. تعمل من 4 حتى 7:30 مساءً تقريباً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080105-68548860.jpg?v=1791585560", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080105-68548861.jpg?v=1791585566"]','https://cmsphoto.ww-cdn.com/resizeapi/7d36b5ce14bf6c71a9bee3f61c426d8b716ab6c7/480/',20.0431221,41.4504975,'طريق الملك عبدالعزيز، شهبة، الباحة 65721','','https://baha.gov.sa/ar/Albums/ImageDetails/488','','https://www.saudi-guide.com/albaha/i/98080105/barshomi-al-sarah-farm-mzraa-brshomy-alsra',1,0,'مزرعه برشومي سراه barshomi al sarah farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080104,'albaha','مزرعة الخميس النموذجية','Al Khamis Model Farm','al-khamis-model-farm-mzraa-alkhmys-alnmothgy','["مزارع"]','["nature"]','مزرعة الخميس في مدينة الباحة تشتهر بالعنب والفراولة الطازجة التي تُشترى مباشرة من المزرعة، وتضم قسماً للحيوانات والطيور.','<div class="texte" > <p>مزرعة الخميس للعنب بمدينة الباحة تشتهر بزراعة العنب والفراولة الطازجة التي يمكن شراؤها مباشرة من المزرعة، بالإضافة إلى قسم للحيوانات والطيور والزيتون. تعمل يومياً من 6 صباحاً حتى 6:30 مساءً، وللتواصل: 0504426039.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080104-68548871.jpg?v=1791585624"]','https://cmsphoto.ww-cdn.com/resizeapi/29e541591b4ca4d25e1c02d5cea8fa1eb03b5c25/480/',20.039807,41.5120247,'طريق الملك عبدالعزيز، النزهة، الباحة 65712','+966504426039','https://baha.gov.sa/ar/Albums/ImageDetails/487','','https://www.saudi-guide.com/albaha/i/98080104/al-khamis-model-farm-mzraa-alkhmys-alnmothgy',1,0,'مزرعه خميس نموذجيه al khamis model farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080103,'albaha','مزرعة العمر الريفية','Al Omar Rural Farm','al-omar-rural-farm-mzraa-alaamr-alryfy','["مزارع"]','["nature"]','مزرعة العمر الريفية في المندق موقع واسع بأشجار الرمان والخوخ، يضم مطعماً شعبياً وألعاباً للأطفال وقسماً للخيول والنعام والغزلان.','<div class="texte" > <p>مزرعة ومنتزه العمر الريفية بمحافظة المندق موقع طبيعي واسع، يضم أشجار الرمان والخوخ المثمرة، بالإضافة إلى مطعم يقدم الأطباق السعودية التقليدية ووجبات خفيفة للأطفال، وألعاباً مجانية وأخرى نفخية، وقسماً للحيوانات يضم الخيول والنعام والغزلان والأرانب يستمتع به الأطفال والكبار. تعمل يومياً من 8 صباحاً حتى 10:30 مساءً، وللتواصل: 0550056665.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080103-68299788.jpg?v=1789817233"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080103-68299788.jpg?v=1789817234',20.2308934,41.264624,'المغثة، المندق 65758','+966550056665','https://baha.gov.sa/ar/Albums/ImageDetails/408','','https://www.saudi-guide.com/albaha/i/98080103/al-omar-rural-farm-mzraa-alaamr-alryfy',1,0,'مزرعه عمر ريفيه al omar rural farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080099,'albaha','وادي لومة','Wadi Lawmah','wadi-lawmah-oady-lom','["الشلالات والأودية"]','["nature"]','وادي لومة في محافظة غامد الزناد وادٍ طبيعي بكر في أقصى جنوب منطقة الباحة، بعيد عن صخب المدن ويستهوي محبي الاستكشاف والهدوء.','<div class="texte" > <p>وادي لومة العريق بمحافظة غامد الزناد، من الأودية الطبيعية ذات الطابع البكر البعيد عن صخب المدن، ويتميز بموقعه في أقصى جنوب منطقة الباحة، ما يمنحه طبيعة متفردة تستهوي محبي الاستكشاف والهدوء.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080099-68299733.jpg?v=1789816834"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080099-68299733.jpg?v=1789816835',19.5403828,41.4107447,'غامد الزناد 65482','','https://baha.gov.sa/ar/Albums/ImageDetails/425','','https://www.saudi-guide.com/albaha/i/98080099/wadi-lawmah-oady-lom',1,0,'وادي لومه wadi lawmah شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080098,'albaha','وادي دوقة','Wadi Dawqah','wadi-dawqah-oady-dok','["الشلالات والأودية"]','["nature"]','وادي دوقة في محافظة قلوة عروس تهامة، وادٍ طبيعي بتضاريس جبلية ومناخ معتدل يستقطب محبي الرحلات البرية والمناظر الطبيعية.','<div class="texte" > <p>وادي دوقة بمحافظة قلوة "عروس تهامة"، من الأودية الطبيعية التي تتميز بطبيعتها الجبلية ومناخها المعتدل، وتستقطب محبي الرحلات البرية والاستمتاع بجمال المناظر الطبيعية في هذه المحافظة الساحرة.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080098-68299712.jpg?v=1789816672"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080098-68299712.jpg?v=1789816672',19.9377244,41.2542327,'قلوة 65573','','https://baha.gov.sa/ar/Albums/ImageDetails/418','','https://www.saudi-guide.com/albaha/i/98080098/wadi-dawqah-oady-dok',1,0,'وادي دوقه wadi dawqah شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080096,'albaha','وادي بيدة','Wadi Bidah','wadi-bidah-oady-byd','["الشلالات والأودية"]','["nature"]','وادي بيدة في محافظة معشوقة بأراضي زهران يضم سد معشوقة، وتحيط به جبال خلابة وطيور مثل مالك الحزين، والوصول إليه عبر طرق ترابية.','<div class="texte" > <p>يضم وادي بيدة بمحافظة معشوقة سد معشوقة، وهو رابع سد في هذا الوادي الواقع بأراضي قبيلة زهران، ويحيط به منظر جبلي خلاب يمكن مشاهدته من أعلى الجبل المجاور مع طيور مثل مالك الحزين. يصعب الوصول إلى منطقة السد وتتطلب قيادة على طرق ترابية وعرة، وللتواصل: 0556867078.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080096-68299731.jpg?v=1789816819"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080096-68299731.jpg?v=1789816819',20.3636408,41.4115718,'وادي بيدة، معشوقة 65789','+966556867078','https://baha.gov.sa/ar/Albums/ImageDetails/431','','https://www.saudi-guide.com/albaha/i/98080096/wadi-bidah-oady-byd',1,0,'وادي بيده wadi bidah شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080095,'albaha','شلال صفا ميعان','Safa Maean Waterfall','safa-maean-waterfall-shlal-sfa-myaaan','["الشلالات والأودية"]','["nature"]','شلال صفا ميعان في بني كبير موقع طبيعي بمسبح صخري تتجمع فيه المياه، يصله محبو المغامرة بسيارات الدفع الرباعي عبر طريق جبلي وعر.','<div class="texte" > <p>شلال صفا ميعان بمحافظة بني كبير موقع طبيعي يقدم تجربة قيادة مثيرة نوعاً ما عبر طريق جبلي وعر ضيق في بعض المقاطع، وتحتوي بدايته على مسبح طبيعي يشبه السد الصخري تتجمع فيه المياه. تتطلب زيارته سيارة دفع رباعي ومهارة في القيادة، وتستغرق الرحلة أكثر من ساعتين ذهاباً وإياباً، لكنها تستحق العناء لمحبي المغامرة.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080095-68299723.jpg?v=1789816799"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080095-68299723.jpg?v=1789816800',19.9952304,41.6087353,'بني كبير 65718','','https://baha.gov.sa/ar/Albums/ImageDetails/423','','https://www.saudi-guide.com/albaha/i/98080095/safa-maean-waterfall-shlal-sfa-myaaan',1,0,'شلال صفا ميعان safa maean waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080094,'albaha','شلال المرزوق','Al Marzouq Waterfall','al-marzouq-waterfall-shlal-almrzok','["الشلالات والأودية"]','["nature"]','شلال المرزوق من أجمل شلالات بني كبير، بقسم سفلي قرب الشلال لمحبي المغامرة وقسم علوي بمجرى مياه هادئ يناسب العائلات.','<div class="texte" > <p>شلال المرزوق من أجمل الشلالات بمحافظة بني كبير، ويتكون من قسمين: قسم سفلي قريب من الشلال يصعب الوصول إليه على العائلات والأطفال، وقسم علوي بمجرى مياه هادئ يناسب الجميع. تصل السيارات إلى الموقع مباشرة، ويُنصح باصطحاب الشباب والمغامرين للاستمتاع بجماله الكامل مع أخذ الحيطة من الصخور المحيطة.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080094-68299719.jpg?v=1789816779"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080094-68299719.jpg?v=1789816779',19.933147,41.6323347,'بني كبير 65663','','https://baha.gov.sa/ar/Albums/ImageDetails/422','','https://www.saudi-guide.com/albaha/i/98080094/al-marzouq-waterfall-shlal-almrzok',1,0,'شلال مرزوق al marzouq waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080093,'albaha','وادي يحر','Wadi Yahar','wadi-yahar-oady-yhr','["الشلالات والأودية"]','["nature"]','وادي يحر في محافظة قلوة وادٍ طبيعي نائي بطابع بكر وتضاريس جبلية، وجهة مثالية لعشاق المغامرة والاستكشاف والهدوء بعيداً عن المدن.','<div class="texte" > <p>وادي يحر بمحافظة قلوة من الأودية الطبيعية النائية التي تناسب عشاق المغامرة والاستكشاف، ويتميز بطابعه البكر البعيد عن صخب المدينة، ما يجعله وجهة مثالية لمحبي الهدوء والطبيعة الجبلية.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080093-68299716.jpg?v=1789816745"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080093-68299716.jpg?v=1789816746',19.9213042,41.2823457,'طريق وادي يحر، قلوة 65559','','https://baha.gov.sa/ar/Albums/ImageDetails/421','','https://www.saudi-guide.com/albaha/i/98080093/wadi-yahar-oady-yhr',1,0,'وادي يحر wadi yahar شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080092,'albaha','وادي محلا','Wadi Mahla','wadi-mahla-oady-mhla','["الشلالات والأودية"]','["nature"]','وادي محلا في محافظة قلوة موقع طبيعي هادئ بتضاريس جبلية متنوعة، يناسب محبي الرحلات البرية والتخييم وهواة التصوير في تهامة.','<div class="texte" > <p>وادي محلا بمحافظة قلوة موقع طبيعي هادئ يناسب محبي الرحلات البرية والاستكشاف، ويتميز بطبيعته الجبلية والتضاريس المتنوعة التي تستهوي هواة التصوير والتخييم.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080092-68299715.jpg?v=1789816716"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080092-68299715.jpg?v=1789816717',19.9878891,41.233924,'طريق وادي محلا، قلوة 65573','','https://baha.gov.sa/ar/Albums/ImageDetails/420','','https://www.saudi-guide.com/albaha/i/98080092/wadi-mahla-oady-mhla',1,0,'وادي محلا wadi mahla شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080091,'albaha','وادي سبة','Wadi Sabah','wadi-sabah-oady-sb','["الشلالات والأودية"]','["nature"]','وادي سبة في محافظة قلوة من الأودية الجبلية الخلابة التي تستقطب محبي الرحلات والتخييم، ويبلغ أجمل حالاته في موسم الأمطار.','<div class="texte" > <p>وادي سبة بمحافظة قلوة من الأودية الطبيعية التي تستقطب محبي الرحلات والتخييم، ويتميز بطبيعته الجبلية الخلابة. يُفضل زيارته خلال موسم الأمطار للاستمتاع بأجمل مناظره الطبيعية.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080091-68299713.jpg?v=1789816686"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080091-68299713.jpg?v=1789816687',20.0151652,41.2792373,'القرين، قلوة 65573','','https://baha.gov.sa/ar/Albums/ImageDetails/419','','https://www.saudi-guide.com/albaha/i/98080091/wadi-sabah-oady-sb',1,0,'وادي سبه wadi sabah شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080087,'albaha','وادي برحرح','Wadi Barahrah','wadi-barahrah-oady-brhrh','["الشلالات والأودية"]','["nature"]','وادي برحرح من أجمل أودية المندق بمناظره الخلابة ومساره الرملي الوعر الذي يحتاج سيارة دفع رباعي، ويزدهر جماله مع أمطار الموسم.','<div class="texte" > <p>وادي برحرح من أجمل الأودية الطبيعية بمحافظة المندق، يتميز بمنظره الخلاب ومساره الرملي الوعر الذي يستدعي استخدام سيارة دفع رباعي للوصول إلى مناطقه الأعمق. يشتد جمال الوادي بغزارة مياهه في موسم الأمطار، ويُنصح بأخذ الاحتياطات اللازمة عند زيارته.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080087-68299710.jpg?v=1789816624"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080087-68299710.jpg?v=1789816625',20.3434097,41.214491,'دوس، المندق 26872','','https://baha.gov.sa/ar/Albums/ImageDetails/411','','https://www.saudi-guide.com/albaha/i/98080087/wadi-barahrah-oady-brhrh',1,0,'وادي برحرح wadi barahrah شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080086,'albaha','وادي ضرك','Wadi Dharak','wadi-dharak-oady-drk','["الشلالات والأودية"]','["nature"]','وادي ضرك في محافظة المندق من أشهر أودية الجنوب، يضم سداً وبحيرة ومياهاً جارية معظم العام، مع جلسات مظللة للشواء والتخييم.','<div class="texte" > <p>وادي ضرك من الأودية المعروفة جنوب منطقة الباحة بمحافظة المندق، وتجري مياهه على مدار العام، ويضم سداً وبحيرة مائية بإطلالة جميلة، مع جلسات مظللة قريبة من البحيرة مناسبة للشواء والتخييم، ويبقى وجهة طبيعية محببة لعشاق الهدوء.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080086-68299708.jpg?v=1789816607"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080086-68299708.jpg?v=1789816607',20.1849247,41.2867177,'طريق سد وادي ضرك، المندق 65756','','https://baha.gov.sa/ar/Albums/ImageDetails/410','','https://www.saudi-guide.com/albaha/i/98080086/wadi-dharak-oady-drk',1,0,'وادي ضرك wadi dharak شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080085,'albaha','وادي الخيطان','Wadi Al Khaitan','wadi-al-khaitan-oady-alkhytan','["الشلالات والأودية"]','["nature"]','وادي الخيطان في بلجرشي من أجمل الأودية المتدفقة، بأشجار متنوعة وجبال شاهقة ومياه عذبة تعيش فيها الأسماك، ويقصده محبو الطبيعة.','<div class="texte" > <p>وادي الخيطان من أجمل الأودية المتدفقة بمحافظة بلجرشي، يتميز بتنوع أشجاره وتربته الرملية وجباله الشاهقة، ويحتوي على مياه عذبة نادرة تعيش فيها أسماك يجب الحفاظ عليها وعدم الإضرار بها. يستقطب الموقع محبي الطبيعة على مدار العام تقريباً.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080085-68299705.jpg?v=1789816593"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080085-68299705.jpg?v=1789816594',19.7405625,41.6540469,'وادي الخيطان، بلجرشي 65426','','https://baha.gov.sa/ar/Albums/ImageDetails/428','','https://www.saudi-guide.com/albaha/i/98080085/wadi-al-khaitan-oady-alkhytan',1,0,'وادي خيطان wadi al khaitan شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080084,'albaha','شلال اثرب','Athrab Waterfall','athrab-waterfall-shlal-athrb','["الشلالات والأودية"]','["nature"]','شلال اثرب في بني حسن بجوار غابة خيرة، يتميز بجسر مشاة معلق بأرضية زجاجية يطل على الشلال، ويبلغ ذروة تدفقه في موسم الأمطار.','<div class="texte" > <p>شلال اثرب موقع طبيعي خلاب بمحافظة بني حسن، بالقرب من غابة خيرة، يتميز بجسر مشاة معلق وأرضية زجاجية توفر إطلالة مثيرة على الشلال من الأعلى. يشتهر الموقع خلال موسم الأمطار بغزارة تدفق مياهه، بينما يقل تدفقها صيفاً.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080084-68299702.jpg?v=1789816492"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080084-68299702.jpg?v=1789816493',20.0614865,41.3889048,'محافظة بني حسن 65735','','https://baha.gov.sa/ar/Albums/ImageDetails/427','','https://www.saudi-guide.com/albaha/i/98080084/athrab-waterfall-shlal-athrb',1,0,'شلال اثرب athrab waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98080083,'albaha','وادي مذود','Wadi Mathood','wadi-mathood-oady-mthod','["الشلالات والأودية"]','["nature"]','وادي مذود في محافظة بلجرشي موقع طبيعي بكر بمجرى مياه هادئ وبحيرة صغيرة فيها أسماك، ويكون تدفقه أقوى في فصل الشتاء.','<div class="texte" > <p>وادي مذود موقع طبيعي بكر بمحافظة بلجرشي، يتميز بمجرى مياه هادئ وسط طبيعة خلابة، ويحتوي على بحيرة صغيرة بها أسماك. يفتقر الموقع للخدمات الأساسية وتنعدم فيه تغطية الاتصالات، ويُفضل زيارته في فصل الشتاء حين يكون تدفق المياه أقوى.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080083-68299696.jpg?v=1789816477"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080083-68299696.jpg?v=1789816477',19.8708942,41.751643,'الأزاهرة، بلجرشي 65698','','https://baha.gov.sa/ar/Albums/ImageDetails/426','','https://www.saudi-guide.com/albaha/i/98080083/wadi-mathood-oady-mthod',1,0,'وادي مذود wadi mathood شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073598,'albaha','سد القمع','Al Qima Dam','al-qima-dam-sd-alkmaa','["الشلالات والأودية"]','["nature"]','سد القمع في بلجرشي من أكبر متنزهات منطقة الباحة، موقع طبيعي بكر بأشجار العرعر والسنط والأثل ومساحات خضراء وجلسات مظللة للعائلات.','<div class="texte" > <p>يُعد سد القمع (الڨمّة) من أكبر وأهم وأشهر متنزهات المنطقة بمحافظة بلجرشي، يقع على بعد نحو 45 كم من الباحة، ويتميز بموقع طبيعي بكر يضم أشجاراً معمرة كالعرعر والسنط والأثل. يوفر مرافق ومساحات خضراء واسعة وأماكن جلوس مظللة عديدة، بالإضافة إلى منطقة مخصصة لتأجير الخيام، ما يجعله وجهة مثالية للعائلات والأفراد.</p> </div>','[]','',19.8073132,41.7139319,'بلجرشي 65675','','https://baha.gov.sa/ar/Albums/ImageDetails/454','','https://www.saudi-guide.com/albaha/i/98073598/al-qima-dam-sd-alkmaa',1,0,'سد قمع al qima dam شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073596,'albaha','شلال وادي الملد','Wadi Al Malad Waterfall','wadi-al-malad-waterfall-shlal-oady-almld','["الشلالات والأودية"]','["nature"]','شلال وادي الملد بجوار قرية الملد في مدينة الباحة، موقع طبيعي بمياه متدفقة يستهوي العائلات، ويكون في أجمل حالاته بعد الأمطار.','<div class="texte" > <p>شلال وادي الملد بجوار قرية الملد بمدينة الباحة، موقع طبيعي جميل بمياه متدفقة يستهوي العائلات لقضاء وقت ممتع، رغم افتقاره لخدمات كبيرة. يُنصح بزيارته بعد هطول الأمطار للاستمتاع بأفضل مناظره، مع الحرص على الحذر بالقرب من مجرى المياه للأطفال.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073596-68299681.jpg?v=1789816410"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073596-68299681.jpg?v=1789816411',20.0130064,41.4910785,'قرية الملد، الظفير، الباحة 65529','','https://baha.gov.sa/ar/Albums/ImageDetails/406','','https://www.saudi-guide.com/albaha/i/98073596/wadi-al-malad-waterfall-shlal-oady-almld',1,0,'شلال وادي ملد wadi al malad waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073595,'albaha','شلال خيرة','Khairah Waterfall','khairah-waterfall-shlal-khyr','["الشلالات والأودية"]','["nature"]','شلال خيرة في بني حسن قرب غابة خيرة، شلال صغير ساحر تتدفق مياهه من الجبال بين تشكيلات صخرية خلابة، ويُزار بعد هطول الأمطار.','<div class="texte" > <p>شلال خيرة موقع طبيعي جميل بمحافظة بني حسن، يتميز بمياهه المتدفقة من الجبال وسط تشكيلات صخرية خلابة، ويقع بالقرب من غابة خيرة. يُعد صغيراً لكنه ساحر، وينصح بزيارته بعد هطول الأمطار مباشرة للاستمتاع بأجمل مناظره.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073595-68299672.jpg?v=1789816382"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073595-68299672.jpg?v=1789816383',20.0619507,41.3891938,'محافظة بني حسن 65735','','https://baha.gov.sa/ar/Albums/ImageDetails/412','','https://www.saudi-guide.com/albaha/i/98073595/khairah-waterfall-shlal-khyr',1,0,'شلال خيره khairah waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073530,'albaha','متحف سعد بن ناصر فرحة','Saad Nasser Farhah Museum','saad-nasser-farhah-museum-mthf-saad-bn-nasr-frh','["التراث والثقافة"]','["heritage"]','متحف سعد ناصر فرحة في محافظة العقيق متحف تراثي منظم بعناية يضم مقتنيات متنوعة، ويشتهر مالكه بحبه للتراث وترحيبه بأسئلة الزوار.','<div class="texte" > <p>متحف الأستاذ سعد ناصر فرحة بمحافظة العقيق متحف تراثي متنوع ومنظم بعناية، حيث توضع كل قطعة في موضعها المناسب. يشتهر مالكه بحبه للتراث ومعرفته الواسعة به، ويجيب على أسئلة الزوار بلطف. يعمل يومياً من 4 حتى 10 مساءً، وللتواصل: 0508866123.</p> </div>','[]','',20.2820724,41.683116,'حي خدعة، محافظة العقيق 65915','+966508866123','','','https://www.saudi-guide.com/albaha/i/98073530/saad-nasser-farhah-museum-mthf-saad-bn-nasr-frh',1,0,'متحف سعد بن ناصر فرحه saad nasser farhah museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073529,'albaha','متحف الديرة','Deerah Museum','mthf-aldyr-deerah-museum','["التراث والثقافة"]','["heritage"]','متحف الديرة بمحافظة المندق يحتضن مجموعة نادرة من القطع الأثرية التي تعكس هوية قبيلة زهران، مع مزرعة ملحقة يستمتع الزوار بالتجول فيها.','<div class="texte" > <p>متحف الديرة بمحافظة المندق يحتضن مجموعة نادرة من القطع الأثرية التي تعكس هوية قبيلة زهران، مع شرح واضح لأسماء التحف والمقتنيات، بالإضافة إلى مزرعة ملحقة به يستمتع الزوار بالتجول فيها. يعمل يومياً من 6 صباحاً حتى 10 مساءً، وللتواصل: 0533568851.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073529-68548925.jpg?v=1791585774", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073529-68548928.jpg?v=1791585781"]','https://cmsphoto.ww-cdn.com/resizeapi/ca926a5fec0c7b5eb51cef291161a386306ad459/480/',20.0931796,41.3088251,'بلخزمر، المندق 65747','+966533568851','','','https://www.saudi-guide.com/albaha/i/98073529/mthf-aldyr-deerah-museum',1,0,'متحف ديره deerah museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073528,'albaha','متحف آل دغسان','Al Daghsan Museum','al-daghsan-museum-mthf-al-dghsan','["التراث والثقافة"]','["heritage"]','متحف آل دغسان في محافظة بلجرشي يقع داخل مزرعة هادئة بعيداً عن صخب المدينة، ويجمع بين جمال الطبيعة والمقتنيات التراثية القديمة.','<div class="texte" > <p>متحف آل دغسان يقع ضمن مزرعة هادئة بمحافظة بلجرشي بعيداً عن صخب المدينة، ويجمع بين جمال الطبيعة والذكريات التراثية القديمة. يعمل يومياً من 4:30 عصراً حتى 3 فجراً تقريباً، ويُفضل الاتصال قبل الزيارة للتأكد من توفر حجز.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073528-68548943.jpg?v=1791585840"]','https://cmsphoto.ww-cdn.com/resizeapi/cacee5acca41849c67a481c081735f74541777f3/480/',19.8608227,41.5984441,'العطاشين، بلجرشي 65651','','','','https://www.saudi-guide.com/albaha/i/98073528/al-daghsan-museum-mthf-al-dghsan',1,0,'متحف دغسان al daghsan museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073527,'albaha','متحف بني جرة التراثي','Bani Jarrah Heritage Museum','bani-jarrah-heritage-museum-mthf-bny-gr-altrathy','["التراث والثقافة"]','["heritage"]','متحف بني جرة التراثي في بلجرشي بتصميم إبداعي ومقتنيات متنوعة وحديقة أنيقة، ويقابله نموذج مصغر دقيق للقرى التاريخية صنعه مالك المتحف.','<div class="texte" > <p>متحف بني جرة التراثي بمحافظة بلجرشي يتميز بتصميمه الإبداعي وعرضه المتنوع للمقتنيات التراثية، مع مقاعد جميلة وحديقة أنيقة. يضم في الشارع المقابل له نموذجاً مصغراً بالتفصيل الدقيق للقرى التاريخية القديمة صنعه مالك المتحف بنفسه. يعمل من السبت حتى الخميس من 8 صباحاً حتى 12 ظهراً ومن 4 حتى 9 مساءً (ويغلق يوم الجمعة)، وللتواصل: 0505880233.</p> </div>','[]','',19.905376,41.5595721,'بني جرة، بلجرشي 65627','+966505880233','','','https://www.saudi-guide.com/albaha/i/98073527/bani-jarrah-heritage-museum-mthf-bny-gr-altrathy',1,0,'متحف بني جره تراثي bani jarrah heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073526,'albaha','المتحف الأبنوي','Al Abnawi Museum','al-abnawi-museum-almthf-alabnoy','["التراث والثقافة"]','["heritage"]','المتحف الأبنوي في محافظة بلجرشي متحف تراثي يستحق الزيارة، يضم مجموعة من القطع القديمة بتفاصيلها الدقيقة ويتميز بحسن استقبال مالكه للزوار.','<div class="texte" > <p>المتحف الأبنوي بمحافظة بلجرشي متحف جميل يستحق الزيارة، يتميز بأناقة مالكه وحسن استقباله للزوار، ويضم مجموعة من القطع التراثية التي تجمع الماضي بتفاصيله الدقيقة. يعمل يومياً تقريباً من 2 ظهراً حتى منتصف الليل، وللتواصل: 0554992844.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073526-68548960.jpg?v=1791585970"]','https://cmsphoto.ww-cdn.com/resizeapi/3116168e20fdd9e085bfd1fc034ce9a454cd5c16/480/',19.8201044,41.6111074,'بلجرشي 65639','+966554992844','','','https://www.saudi-guide.com/albaha/i/98073526/al-abnawi-museum-almthf-alabnoy',1,0,'متحف ابنوي al abnawi museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073525,'albaha','متحف العمدة','Al Omda Museum','al-omda-museum-mthf-alaamd','["التراث والثقافة"]','["heritage"]','متحف العمدة في وسط مدينة الباحة يضم مجموعة متنوعة من المقتنيات والتحف التراثية القديمة، ووجهة محببة لهواة القطع الأثرية والتراثية.','<div class="texte" > <p>متحف العمدة يقع في وسط مدينة الباحة، ويضم مجموعة متنوعة من المقتنيات والتحف التراثية القديمة، ويُعد وجهة محببة لهواة اقتناء القطع الأثرية والتراثية. يعمل يومياً من 7:30 صباحاً حتى 1:30 ظهراً، ومن 4 حتى 9:30 مساءً (ويوم الجمعة من 12:30 ظهراً)، وللتواصل: 0508834697.</p> </div>','[]','',20.0108465,41.4596169,'الأمير فيصل بن محمد بن سعود، وسط المدينة، الباحة 65522','+966508834697','','','https://www.saudi-guide.com/albaha/i/98073525/al-omda-museum-mthf-alaamd',1,0,'متحف عمده al omda museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073522,'albaha','متحف بدر آل موالا','Badr Al Mawala Museum','badr-al-mawala-museum-mthf-bdr-al-moala','["التراث والثقافة"]','["heritage"]','متحف بدر آل موالا على طريق الملك فهد في محافظة المخواة، يحتفظ بمقتنيات وأدوات تراثية تعكس تاريخ تهامة الباحة وحياة أهلها قديماً.','<div class="texte" > <p>متحف بدر آل موالا يقع على طريق الملك فهد بمحافظة المخواة، ويحتفظ بمجموعة من المقتنيات والأدوات التراثية التي تعكس تاريخ المنطقة وحياة أهلها في الماضي. يعمل يومياً من 8:30 صباحاً حتى 11 مساءً تقريباً (ويوم الجمعة من 4 عصراً)، وللتواصل: 0535536617.</p> </div>','[]','',19.8893913,41.4467865,'الجوة، طريق الملك فهد، محافظة المخواة 83246','+966535536617','','','https://www.saudi-guide.com/albaha/i/98073522/badr-al-mawala-museum-mthf-bdr-al-moala',1,0,'متحف بدر موالا badr al mawala museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073520,'albaha','متحف الشملاني','Al Shamlani Museum','al-shamlani-museum-mthf-alshmlany','["التراث والثقافة"]','["heritage"]','متحف الشملاني في قرية الأطاولة التراثية بمحافظة القرى، أسسه الشيخ عبدالعزيز الشملاني في منزل العائلة ليحفظ تراث المنطقة وتاريخها.','<div class="texte" > <p>يقع متحف الشملاني في قرية الأطاولة التراثية بمحافظة القرى، على بعد نحو 29 كم من مدينة الباحة. أسسه الشيخ عبدالعزيز الشملاني في منزل العائلة ليكون إرثاً تاريخياً يحافظ على تراث المنطقة، ويشرف عليه حالياً عبدالعزيز بن سعيد الشملاني. يعمل يومياً من 10 صباحاً حتى 8:30 مساءً تقريباً (ويوم الجمعة من 2 ظهراً)، وللتواصل: 0555775219.</p> </div>','[]','',20.2498753,41.3599775,'الأطاولة، القرى 65798','+966555775219','','','https://www.saudi-guide.com/albaha/i/98073520/al-shamlani-museum-mthf-alshmlany',1,0,'متحف شملاني al shamlani museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073445,'albaha','بيور كافيه','Pure Cafe','pure-cafe-byor-kafyh','["مقاهي"]','["cafe"]','بيور كافيه مقهى قهوة مختصة وسط الطبيعة قرب غابة رغدان في الباحة، يقدم مشروبات مميزة وحلويات في أجواء هادئة بعيداً عن صخب المدينة.','<div class="texte" > <p>قهوة مختصة وسط الغابة، يقدم بيور كافيه مشروبات مميزة وحلويات شهية في أجواء طبيعية هادئة بالقرب من غابة رغدان، ما يجعله ملاذاً مثالياً للاسترخاء بعيداً عن صخب المدينة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073445-68548992.jpg?v=1791586248", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073445-68548999.jpg?v=1791586255"]','https://cmsphoto.ww-cdn.com/resizeapi/d964c7a69a158802c47b1e2a3d7fa2497ec96700/480/',20.0207422,41.4338565,'حديقة سانديا، الباحة 65541','','','','https://www.saudi-guide.com/albaha/i/98073445/pure-cafe-byor-kafyh',1,0,'بيور كافيه pure cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073444,'albaha','أوروبيا كافيه','Orobia Cafe','orobia-cafe-aorobya-kafyh','["مقاهي"]','["cafe"]','أوروبيا كافيه في الباحة مقهى بتصميم فريد داخل مشتل نباتات هادئ، يقدم القهوة الباردة والحارة والحلويات ويشتهر بشاي الكركديه.','<div class="texte" > <p>يتميز أوروبيا كافيه بتصميمه الفريد ضمن مشتل نباتات هادئ، كما يقدم القهوة الباردة والحارة بالإضافة إلى الحلويات، ويشتهر بشاي الكركديه اللذيذ. يعمل يومياً من 3 عصراً حتى 11 مساءً، وللتواصل: 0563112763.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073444-68549019.jpg?v=1791586310", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073444-68549021.jpg?v=1791586317"]','https://cmsphoto.ww-cdn.com/resizeapi/1d17643aeaed112e5205d18a5b332c0fcd47c0a9/480/',20.0028044,41.4559391,'طريق الملك فيصل، وسط المدينة، الباحة 65525','+966563112763','','','https://www.saudi-guide.com/albaha/i/98073444/orobia-cafe-aorobya-kafyh',1,0,'اوروبيا كافيه orobia cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073442,'albaha','مقهى هافين','Haven Cafe','haven-cafe-mkha-hafyn','["مقاهي"]','["cafe"]','مقهى هافين في مدينة الباحة يقدم القهوة الإثيوبية المميزة وتشكيلة من الحلويات، ويشتهر بتشيز كيك سان سيباستيان وإطلالة مقاعده العلوية.','<div class="texte" > <p>تمتع بقهوة إثيوبية مميزة، والعديد من الحلويات اللذيذة في مقهى هافين، ويشتهر بحلوى سان سيباستيان الكريمية وإطلالة جميلة من المقاعد العلوية. يعمل على مدار 24 ساعة يومياً، وللتواصل: 0535883130.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073442-68549048.jpg?v=1791586382"]','https://cmsphoto.ww-cdn.com/resizeapi/1912b934d02a121f28755c07d55b7e63438082c8/480/',20.0080984,41.4511857,'طريق الملك فيصل، حي البوليفارد، الباحة 65522','+966535883130','','','https://www.saudi-guide.com/albaha/i/98073442/haven-cafe-mkha-hafyn',1,0,'مقهي هافين haven cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073429,'albaha','شورت ستوب','Short Stop','short-stop-short-stob','["مقاهي"]','["cafe"]','شورت ستوب في الباحة مقهى ومخبز يقدم قائمة واسعة من المخبوزات وأنواع القهوة، ويشتهر بالفلات وايت والتشيز كيك البارد بخدمة سريعة.','<div class="texte" > <p>مقهى ومخبز يقدم قائمة واسعة من المخبوزات بجانب مختلف أنواع القهوة، ويشتهر بالفلات وايت وتشيز كيك بارد لذيذ، بخدمة سريعة وأجواء ودودة. يعمل يومياً من 6 صباحاً حتى 2 فجراً، وللتواصل: 0535385544.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073429-68549086.jpg?v=1791586490", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073429-68549089.jpg?v=1791586496"]','https://cmsphoto.ww-cdn.com/resizeapi/4ab695de6a275980a5040b1c2e7356d85e0f2ecc/480/',20.0240204,41.4769245,'النزهة، الباحة 65711','+966535385544','','','https://www.saudi-guide.com/albaha/i/98073429/short-stop-short-stob',1,0,'شورت ستوب short stop مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073428,'albaha','كولد محمصة ومقهى','Cold Roastery and Coffee','cold-roastery-and-coffee-kold-mhms-omkha','["مقاهي"]','["cafe"]','كولد محمصة ومقهى في محافظة بلجرشي يقدم القهوة المختصة ويشتهر بالتوست الفرنسي الكلاسيكي، بديكور عصري أنيق وتصميم داخلي مريح.','<div class="texte" > <p>يقدم ألذ قهوة مختصة، كما يشتهر كولد محمصة ومقهى بتقديم ألذ توست فرنسي كلاسيكي بمحافظة بلجرشي، ضمن ديكور عصري أنيق وتصميم داخلي مريح. يعمل يومياً من 6:30 صباحاً حتى 2:15 فجراً تقريباً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073428-68549097.jpg?v=1791586555", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073428-68549101.jpg?v=1791586562"]','https://cmsphoto.ww-cdn.com/resizeapi/919c04c831a142ad091d10c0bc3b6e999e97c63c/480/',19.8753054,41.5734189,'المحمدية، بلجرشي 65651','','','','https://www.saudi-guide.com/albaha/i/98073428/cold-roastery-and-coffee-kold-mhms-omkha',1,0,'كولد محمصه ومقهي cold roastery and coffee مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073426,'albaha','الفاخر كافيه','Al Fakher Cafe','al-fakher-cafe-alfakhr-kafyh','["مقاهي"]','["cafe"]','الفاخر كافيه في مدينة الباحة مقهى بجلسات في الطابق التاسع تطل على المدينة، يقدم أنواع القهوة والحلويات المميزة مثل كيك الزعفران.','<div class="texte" > <p>يتميز الفاخر كافيه بجلسات مميزة بإطلالة رائعة على المدينة من الطابق التاسع، ويقدم مجموعة متنوعة من القهوة بجانب الحلويات المميزة مثل كيك الزعفران. يعمل يومياً من 6 صباحاً حتى منتصف الليل تقريباً، وللتواصل: 0554005996.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073426-68550665.jpg?v=1791627244", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073426-68550668.jpg?v=1791627251"]','https://cmsphoto.ww-cdn.com/resizeapi/092cff045e57b3e23be5bb95bf50a169ca5022ff/480/',20.0145479,41.4692412,'طريق الملك فهد، الرايب، الباحة 65528','+966554005996','','','https://www.saudi-guide.com/albaha/i/98073426/al-fakher-cafe-alfakhr-kafyh',1,0,'فاخر كافيه al fakher cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073425,'albaha','مطعم التينو','Latino Restaurant','latino-restaurant-mtaam-altyno','["مطاعم"]','["food"]','مطعم التينو في مدينة الباحة يقدم المطبخ المكسيكي بقائمة متنوعة، ويشتهر بالتاكو المقرمش وأطباق الشيبوتلي والكيساديا الطازجة.','<div class="texte" > <p>يقدم مطعم التينو قائمة واسعة ومتنوعة مصممة خصيصاً لمحبي النكهة المكسيكية، ويشتهر بالتاكو المقرمش وأطباق الشيبوتلي والكيساديا الطازجة. يعمل يومياً من 1 ظهراً حتى 12:30 فجراً (ويوم الجمعة من 2 ظهراً)، وللتواصل: 0562688455.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073425-68550674.jpg?v=1791627317", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073425-68550675.jpg?v=1791627326"]','https://cmsphoto.ww-cdn.com/resizeapi/e36bb08650b07cded02c3a9beef429555b96fcd2/480/',20.018644,41.4656126,'معالي الشيخ ابراهيم الابراهيم، شهبة، الباحة 65525','+966562688455','','','https://www.saudi-guide.com/albaha/i/98073425/latino-restaurant-mtaam-altyno',1,0,'مطعم تينو latino restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073423,'albaha','مطعم مشراق','Mashraq Restaurant','mashraq-restaurant-mtaam-mshrak','["مطاعم"]','["food"]','مطعم مشراق في مدينة الباحة وجهة للفطور الشرقي الأصيل، يقدم الفول والعريكة وأطباقاً تقليدية متنوعة ويشتهر بطبق فطور مشراق المتكامل.','<div class="texte" > <p>تجربة فطور شرقية أصيلة، يقدم مطعم مشراق مجموعة متنوعة من الأطباق التقليدية مثل الفول والعريكة بنكهات مميزة، ويشتهر بطبق فطور مشراق المتكامل والفرنش توست. يعمل يومياً من 5 صباحاً حتى 1 ظهراً ومن 6:30 حتى منتصف الليل، وللتواصل: 0539790880.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073423-68550681.jpg?v=1791627392", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073423-68550684.jpg?v=1791627397"]','https://cmsphoto.ww-cdn.com/resizeapi/2b6fbe4ddadc11de84623ff5b2751501aeb047a2/480/',20.0077954,41.4513892,'طريق الملك فيصل، الباحة 65522','+966539790880','','','https://www.saudi-guide.com/albaha/i/98073423/mashraq-restaurant-mtaam-mshrak',1,0,'مطعم مشراق mashraq restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073422,'albaha','مطعم طلوب المندي','Teluob Mandi Restaurant','teluob-mandi-restaurant-mtaam-tlob-almndy','["مطاعم"]','["food"]','مطعم طلوب المندي في محافظة المندق متخصص في المندي فقط، يحضّر الأرز واللحم بالطريقة التقليدية بنكهات أصيلة ويتطلب الطلب حجزاً مسبقاً.','<div class="texte" > <p>وجهة متخصصة في تقديم المندي فقط بمحافظة المندق، حيث يُحضر الأرز واللحم بأسلوب تقليدي مميز ونكهات أصيلة، ويحتاج الطلب لحجز مسبق يوم واحد على الأقل. يعمل يومياً من 1:30 حتى 10 مساءً (ويوم الجمعة حتى 11 مساءً)، وللتواصل: 0507770636.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073422-68550687.jpg?v=1791627461"]','https://cmsphoto.ww-cdn.com/resizeapi/c39b8cf44a16e971865ff4dc8e4293d07770f59a/480/',20.1489961,41.3196411,'المندق 65744','+966507770636','','','https://www.saudi-guide.com/albaha/i/98073422/teluob-mandi-restaurant-mtaam-tlob-almndy',1,0,'مطعم طلوب مندي teluob mandi restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073420,'albaha','مطعم مذاق ماضينا','Mathaq Madhina Restaurant','mathaq-madhina-restaurant-mtaam-mthak-madyna','["مطاعم"]','["food"]','مطعم مذاق ماضينا في الباحة تجربة تعيدك لأجواء التراث السعودي، يقدم المضغوط والبرياني والإدامات والأطباق الشعبية التقليدية.','<div class="texte" > <p>تجربة أصيلة تعيدك لأجواء التراث السعودي، يقدم مطعم مذاق ماضينا أطباقاً تقليدية مثل المضغوط والإدامات المتنوعة، ويشتهر بالبرياني والمضغوط الشهي. يعمل يومياً من 7 صباحاً حتى 1 فجراً، وللتواصل: 0555946705.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073420-68550726.jpg?v=1791627655", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073420-68550727.jpg?v=1791627666"]','https://cmsphoto.ww-cdn.com/resizeapi/fb2bedb28347e1bdc1188007e51cba49bd477b72/480/',20.0607926,41.4412693,'مدخل مستشفى الملك فهد، الأزهر، الباحة 65732','+966555946705','','','https://www.saudi-guide.com/albaha/i/98073420/mathaq-madhina-restaurant-mtaam-mthak-madyna',1,0,'مطعم مذاق ماضينا mathaq madhina restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073419,'albaha','مطعم روح ديرتي','Roh Dirty Restaurant','roh-dirty-restaurant-mtaam-roh-dyrty','["مطاعم"]','["food"]','مطعم روح ديرتي في الباحة وجهة شعبية تقدم المندي والحنيذ والمضغوط بأجواء سعودية أصيلة، مع جلسات أرضية واسعة تناسب العائلات.','<div class="texte" > <p>وجهة شعبية يتميز مطعم روح ديرتي بتقديم المندي والحنيذ والمضغوط بأجواء سعودية أصيلة، وله جلسات أرضية واسعة تناسب العائلات. يعمل يومياً من 7 صباحاً حتى 2 فجراً تقريباً (ويوم الجمعة من 12:30 ظهراً)، وللتواصل: 0553202255.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073419-68550736.jpg?v=1791627750"]','https://cmsphoto.ww-cdn.com/resizeapi/92ab0f7c6ce3f388b9ebcfa4a95d0e456714815a/480/',20.0101418,41.4721104,'طريق الملك عبدالعزيز، الرايب، الباحة 65528','+966553202255','','','https://www.saudi-guide.com/albaha/i/98073419/roh-dirty-restaurant-mtaam-roh-dyrty',1,0,'مطعم روح ديرتي roh dirty restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073417,'albaha','مطعم إيتان الهندي','Etan Indian Restaurant','etan-indian-restaurant-mtaam-aytan-alhndy','["مطاعم"]','["food"]','مطعم إيتان الهندي في الباحة يقدم أطباقاً هندية غنية مثل البرياني والماسالا وخبز النان، داخل مبنى واسع من ثلاثة طوابق.','<div class="texte" > <p>لمحبي النكهات الهندية الأصيلة، يتميز مطعم إيتان بتقديم أطباق هندية غنية ومتنوعة مثل البرياني والماسالا بجانب خبز النان الشهير، ضمن مبنى واسع من ثلاثة طوابق. يعمل يومياً من 12 ظهراً حتى منتصف الليل تقريباً (ويومي الخميس والجمعة حتى 1 فجراً)، وللتواصل: 0559395933.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073417-68550750.jpg?v=1791627824", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073417-68550751.jpg?v=1791627836"]','https://cmsphoto.ww-cdn.com/resizeapi/d4c2d2f4732f73f974ee3aa7c0f144585bbf8172/480/',20.0029192,41.4583234,'طريق الملك فيصل، حي الشفاء، الباحة 65522','+966559395933','','','https://www.saudi-guide.com/albaha/i/98073417/etan-indian-restaurant-mtaam-aytan-alhndy',1,0,'مطعم ايتان هندي etan indian restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073415,'albaha','مطعم أسماك النورس','Al Nawras Seafood','al-nawras-seafood-mtaam-asmak-alnors','["مطاعم"]','["food"]','مطعم أسماك النورس في الباحة متخصص في المأكولات البحرية، يقدم أنواع الأسماك المشوية والمقلية والكاليماري والجمبري بتشكيلة واسعة.','<div class="texte" > <p>متخصص بالمأكولات البحرية، يقدم مطعم أسماك النورس مجموعة واسعة من أشهى الأطباق ومختلف أنواع الأسماك، مثل صحن الكاليماري والجمبري المقلي والسمك المشوي الطازج. يعمل يومياً من 12 ظهراً حتى منتصف الليل، وللتواصل: 0565380005.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073415-68550765.jpg?v=1791627964", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073415-68550768.jpg?v=1791627977"]','https://cmsphoto.ww-cdn.com/resizeapi/874cb368b69d48a71793e8c9763399b8bb36638a/480/',20.0087544,41.4578313,'طريق الملك سعود، وسط المدينة، الباحة 65522','+966565380005','','','https://www.saudi-guide.com/albaha/i/98073415/al-nawras-seafood-mtaam-asmak-alnors',1,0,'مطعم اسماك نورس al nawras seafood مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073414,'albaha','مطعم سيكستي برجر','Sixty Burger','sixty-burger-mtaam-syksty-brgr','["مطاعم"]','["food"]','مطعم سيكستي برجر في مدينة الباحة مطعم عصري يقدم البرجر والبطاطس المقرمشة، ويشتهر ببرجر اللحم والبريسكت الطازج الغني بالنكهة.','<div class="texte" > <p>مطعم عصري يقدم ألذ برجر بجانب البطاطس المقرمشة، ويشتهر ببرجر اللحم والبريسكت الطازج الغني بالنكهة. يعمل يومياً من 10 صباحاً حتى 2 فجراً تقريباً (ويوم الجمعة من 4 عصراً حتى 3 فجراً)، وللتواصل: 0558660065.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073414-68550777.jpg?v=1791628047", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073414-68550780.jpg?v=1791628059"]','https://cmsphoto.ww-cdn.com/resizeapi/63b3c5daf30a7531e275fecfa71459b1946cbb67/480/',20.0080429,41.452668,'طريق الملك فيصل، الباحة 65522','+966558660065','','','https://www.saudi-guide.com/albaha/i/98073414/sixty-burger-mtaam-syksty-brgr',1,0,'مطعم سيكستي برجر sixty burger مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073413,'albaha','مطعم البرج','Al Burj Restaurant','al-burj-restaurant-mtaam-albrg','["مطاعم"]','["food"]','مطعم البرج في محافظة المندق بتصميم فريد على حافة جبل، يقدم قائمة واسعة من المأكولات المشوية بإطلالة مميزة على جبال السروات.','<div class="texte" > <p>بتصميمه الفريد على حافة جبل بمحافظة المندق، يقدم مطعم البرج قائمة واسعة من المأكولات المشوية بإطلالة مميزة على الجبال. يعمل يومياً من 7 صباحاً حتى منتصف الليل تقريباً (ويوم الجمعة من 1 ظهراً)، وللتواصل: 0535700735.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073413-68550809.jpg?v=1791628203", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073413-68550811.jpg?v=1791628213"]','https://cmsphoto.ww-cdn.com/resizeapi/90365e2bb8c9c3ed560683b548c0a5c4fd75f6db/480/',20.1733766,41.2713781,'المندق 65583','+966535700735','','','https://www.saudi-guide.com/albaha/i/98073413/al-burj-restaurant-mtaam-albrg',1,0,'مطعم برج al burj restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073411,'albaha','بوليفارد الباحة','Al Baha Boulevard','al-baha-boulevard-bolyfard-albah','["أماكن سياحية"]','["sights"]','بوليفارد الباحة في وسط المدينة وجهة سياحية تضم مطاعم ومقاهي محلية وعالمية، ويحتضن الفعاليات والأمسيات ويُعد مكاناً مثالياً للتصوير.','<div class="texte" > <p>بتصميمه المميز يضم بوليفارد الباحة مجموعة واسعة من المطاعم والمقاهي المحلية والعالمية، ويُعد مكاناً محبباً لإقامة الفعاليات والأمسيات، ما يجعله وجهة سياحية بارزة ومكاناً مثالياً لالتقاط الصور في وسط مدينة الباحة. يعمل على مدار 24 ساعة يومياً.</p> </div>','[]','',20.0078883,41.4511746,'وسط المدينة، الباحة 65522','','','','https://www.saudi-guide.com/albaha/i/98073411/al-baha-boulevard-bolyfard-albah',1,0,'بوليفارد باحه al baha boulevard اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073409,'albaha','دار عوضة','Dar Awdah','dar-awdah-dar-aaod','["التراث والثقافة"]','["heritage"]','دار عوضة في محافظة القرى مبنى تراثي يجسد تاريخ الباحة وكرم الضيافة، بديكور تراثي وأشجار مرتبة ومقهى يقدم القهوة والحلويات.','<div class="texte" > <p>مبنى يجسد تراث وتاريخ منطقة الباحة في أجواء أصيلة ودفء الضيافة السعودية بمحافظة القرى، ويتميز بديكوره التراثي وتنظيمه الجميل وأشجاره المرتبة، ويضم مقهى يقدم القهوة والحلويات بأسعار مناسبة. يعمل يومياً من 4 عصراً حتى 11 مساءً، وللتواصل: 0557102946.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073409-68550852.jpg?v=1791628407"]','https://cmsphoto.ww-cdn.com/resizeapi/7795cc7b5801cadeddd9a7a12d780e75a22391d3/480/',20.2385856,41.3619319,'الأخوة، القرى 65791','+966557102946','','','https://www.saudi-guide.com/albaha/i/98073409/dar-awdah-dar-aaod',1,0,'دار عوضه dar awdah تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073406,'albaha','منتزه سيدة السحاب','Lady of the Clouds Park','lady-of-the-clouds-park-mntzh-syd-alshab','["أماكن سياحية"]','["sights"]','منتزه سيدة السحاب في الباحة بإطلالة تلامس السحاب ومرافق سياحية متنوعة، يضم مطعماً ومقهى وسط أجواء باردة منعشة طوال فصل الصيف.','<div class="texte" > <p>منتزه بإطلالة مميزة تلامس السحاب، ومرافق سياحية متنوعة متميزة بمحافظة المندق، ويضم مطعماً ومقهى يخدم الزوار وسط أجواء باردة منعشة طوال فصل الصيف. يعمل يومياً من 12 ظهراً حتى منتصف الليل تقريباً، وللتواصل: 0502227978.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073406-68550859.jpg?v=1791628481", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073406-68550862.jpg?v=1791628490"]','https://cmsphoto.ww-cdn.com/resizeapi/ee3c3567ff0d788eb69e4eeb475c575acc3a2b4b/480/',20.1763525,41.2650742,'عويرة، المندق 65585','+966502227978','','','https://www.saudi-guide.com/albaha/i/98073406/lady-of-the-clouds-park-mntzh-syd-alshab',1,0,'منتزه سيده سحاب lady of the clouds park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073405,'albaha','مركز فال العز للفروسية','Fal Al Ezz Equestrian Center','fal-al-ezz-equestrian-center-mrkz-fal-alaaz-llfrosy','["أماكن سياحية"]','["sights"]','مركز فال العز للفروسية في محافظة العقيق لتعليم ركوب الخيل وقفز الحواجز، يضم مرافق ترفيهية وطيوراً وغزلاناً ونخيلاً وسط الطبيعة.','<div class="texte" > <p>مركز متخصص في تعليم ركوب الخيل وقفز الحواجز، يضم مرافق ترفيهية متكاملة وسط أجواء الطبيعة بمحافظة العقيق، بالإضافة إلى وجود طيور وغزلان ونخيل يستمتع بها الزوار. يعمل يومياً من 4 عصراً حتى 8 مساءً، وللتواصل: 0556815556.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073405-68550898.jpg?v=1791628751"]','https://cmsphoto.ww-cdn.com/resizeapi/f0e00bbb1e0bd3292b91f7b44e93dd7ec3881753/480/',20.2541852,41.6086089,'محافظة العقيق 65819','+966556815556','','','https://www.saudi-guide.com/albaha/i/98073405/fal-al-ezz-equestrian-center-mrkz-fal-alaaz-llfrosy',1,0,'مركز فال عز للفروسيه fal al ezz equestrian center اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073402,'albaha','قرية الأطلال التراثية','Al Atlal Heritage Village','al-atlal-heritage-village-kry-alatlal-altrathy','["التراث والثقافة"]','["heritage"]','قرية الأطلال التراثية بجانب وادي العقب في الباحة، تضم جلسات وخياماً ومطعماً يقدم المأكولات التراثية والمشاوي في أجواء عائلية.','<div class="texte" > <p>تشتهر قرية الأطلال بموقع مميز بجانب وادي العقب، كما تضم جلسات وخياماً، بالإضافة لمطعم يقدم أشهى المأكولات التراثية والمشاوي بأجواء عائلية مريحة. تعمل يومياً من 6 صباحاً حتى 11 مساءً تقريباً (ويوم الجمعة من 12 ظهراً)، وللتواصل: 0537466589.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073402-68550915.jpg?v=1791628885"]','https://cmsphoto.ww-cdn.com/resizeapi/67a72e6deff6c3d85afab86d464811aa97d78f44/480/',20.1322436,41.2980875,'المصيف، المندق 65748','+966537466589','','','https://www.saudi-guide.com/albaha/i/98073402/al-atlal-heritage-village-kry-alatlal-altrathy',1,0,'قريه اطلال تراثيه al atlal heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073401,'albaha','مزرعة البروقي','Al Bruqi Farm','al-bruqi-farm-mzraa-albroky','["مزارع"]','["nature"]','مزرعة البروقي في محافظة المندق وجهة عائلية بمسطحات خضراء وجلسات مميزة، تشتهر بالفراولة الطازجة والعسل ومطعم للأكلات الشعبية.','<div class="texte" > <p>وجهة مثالية للعائلة تضم مسطحات خضراء وجلسات مميزة، بالإضافة إلى الفراولة الطازجة والعسل، ومطعم يقدم أكلات شعبية مميزة بمحافظة المندق. يعمل من الخميس حتى السبت من 2 عصراً حتى 10 مساءً، وللتواصل: 0501319444.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073401-68299795.jpg?v=1789817297"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073401-68299795.jpg?v=1789817298',20.13413,41.3186664,'المندق 65748','+966501319444','https://baha.gov.sa/ar/Albums/ImageDetails/407','','https://www.saudi-guide.com/albaha/i/98073401/al-bruqi-farm-mzraa-albroky',1,0,'مزرعه بروقي al bruqi farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073279,'albaha','سوق الإثنين بقلوة','Monday Market Qilwah','monday-market-qilwah-sok-alathnyn-bklo','["أسواق"]','["shopping"]','سوق الإثنين في محافظة قلوة سوق شعبي أسبوعي يُقام كل يوم إثنين، يعرض فيه أهالي تهامة منتجاتهم الزراعية والحرفية المحلية.','<div class="texte" > <p>سوق الإثنين أحد الأسواق الشعبية الأسبوعية بمحافظة قلوة، المعروفة بـ"عروس تهامة" لجمال مدرجاتها ومناخها المعتدل. يعقد كل يوم إثنين ويعرض فيه الأهالي المنتجات الزراعية والحرفية المحلية، ويُعد وجهة تراثية محببة لأهالي المحافظة والزوار.</p> </div>','[]','',19.9293495,41.2643785,'قلوة، حي العزيزية 65335','','','','https://www.saudi-guide.com/albaha/i/98073279/monday-market-qilwah-sok-alathnyn-bklo',1,0,'سوق اثنين بقلوه monday market qilwah اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073276,'albaha','سوق السبت بغامد الزناد','Saturday Market Ghamid Al Zinad','saturday-market-ghamid-al-zinad-sok-alsbt-bghamd-alznad','["أسواق"]','["shopping"]','سوق السبت في محافظة غامد الزناد سوق شعبي أسبوعي يُقام كل سبت، يعرض فيه الأهالي منتجاتهم الزراعية والمحلية في أجواء تراثية أصيلة.','<div class="texte" > <p>سوق السبت أحد الأسواق الشعبية الأسبوعية بمحافظة غامد الزناد، يعقد كل يوم سبت ويعرض فيه أهالي المحافظة منتجاتهم الزراعية والمحلية، ويُعد وجهة تراثية محببة لأهالي المنطقة والزوار الباحثين عن أجواء الأسواق الشعبية الأصيلة.</p> </div>','[]','',19.6033213,41.4812771,'غامد الزناد','','','','https://www.saudi-guide.com/albaha/i/98073276/saturday-market-ghamid-al-zinad-sok-alsbt-bghamd-alznad',1,0,'سوق سبت بغامد زناد saturday market ghamid al zinad اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073274,'albaha','سوق الأحد بالحجرة','Sunday Market Al Hajrah','sunday-market-al-hajrah-sok-alahd-balhgr','["أسواق"]','["shopping"]','سوق الأحد في محافظة الحجرة سوق شعبي أسبوعي يُقام كل أحد، ويشتهر ببيع الأغنام والمواشي إلى جانب المنتجات المحلية والحرفية.','<div class="texte" > <p>سوق الأحد أحد الأسواق الشعبية الأسبوعية بمحافظة الحجرة، يعقد كل يوم أحد ويشتهر بسوق الأغنام والمواشي إلى جانب بيع المنتجات المحلية والحرفية، ويُعد وجهة تقليدية لأهالي المحافظة والزوار من محبي الأسواق الشعبية.</p> </div>','[]','',20.201003,41.0757542,'محافظة الحجرة 28695','','','','https://www.saudi-guide.com/albaha/i/98073274/sunday-market-al-hajrah-sok-alahd-balhgr',1,0,'سوق احد بالحجره sunday market al hajrah اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073273,'albaha','سوق العقيق الأسبوعي','Al Aqiq Weekly Markets','al-aqiq-weekly-markets-sok-alaakyk-alasboaay','["أسواق"]','["shopping"]','أسواق العقيق الشعبية تُقام أربعة أيام في الأسبوع، يعرض فيها الأهالي منتجاتهم الزراعية والحرفية في أجواء الأسواق الشعبية الأصيلة.','<div class="texte" > <p>تشهد محافظة العقيق نشاطاً تجارياً شعبياً على مدار الأسبوع، حيث تعقد أسواق شعبية أربعة أيام متتالية: السبت والإثنين والثلاثاء والأربعاء، يعرض فيها الأهالي منتجاتهم الزراعية والحرفية المحلية، وتُعد من الوجهات التي يحرص الزوار على التسوق فيها لتجربة أجواء الأسواق الشعبية الأصيلة.</p> </div>','[]','',20.2705338,41.6576719,'محافظة العقيق 65923','','','','https://www.saudi-guide.com/albaha/i/98073273/al-aqiq-weekly-markets-sok-alaakyk-alasboaay',1,0,'سوق عقيق اسبوعي al aqiq weekly markets اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073272,'albaha','سوق الخميس بالباحة','Thursday Market Al Baha','thursday-market-al-baha-sok-alkhmys-balbah','["أسواق"]','["shopping"]','سوق الخميس في مدينة الباحة سوق شعبي أسبوعي يعرض الخضار والفواكه والعسل والحرف اليدوية، ويستقطب محبي التسوق التقليدي.','<div class="texte" > <p>سوق الخميس أحد الأسواق الشعبية الأسبوعية في مدينة الباحة، يعقد كل خميس ويعرض فيه الباعة منتجات محلية متنوعة من الخضار والفواكه والعسل والحرف اليدوية، ويستقطب الأهالي والزوار من محبي التسوق التقليدي.</p> </div>','[]','',20.0109443,41.4619369,'مدينة الباحة','','','','https://www.saudi-guide.com/albaha/i/98073272/thursday-market-al-baha-sok-alkhmys-balbah',1,0,'سوق خميس بالباحه thursday market al baha اسواق',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073263,'albaha','8OZ كافيه','8OZ Cafe','8oz-cafe-8oz-kafyh','["مقاهي"]','["cafe"]','8OZ كافيه في الباحة مقهى بتصميم حديث وإطلالة على الطبيعة، يقدم المشروبات الباردة والساخنة والحلويات ويشتهر بالفرنش توست والشوكولاتة.','<div class="texte" > <p>يتميز 8OZ كافيه بتصميمه الحديث، ويقدم قائمة متنوعة من المشروبات الباردة والساخنة والحلويات الغربية، مع إطلالة جميلة على الطبيعة المحيطة. يشتهر بالفرنش توست وقطع الشوكولاتة الفاخرة، ويعمل على مدار 24 ساعة يومياً.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073263-68551017.jpg?v=1791629264", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073263-68551022.jpg?v=1791629273"]','https://cmsphoto.ww-cdn.com/resizeapi/5ad9788f4afdfb8d2fdedc93df52f27d73aa000b/480/',20.0165322,41.4715394,'شارع الملك فهد، الرايب، الباحة 65528','','','','https://www.saudi-guide.com/albaha/i/98073263/8oz-cafe-8oz-kafyh',1,0,'8oz كافيه 8oz cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073260,'albaha','ريشيو كافيه','Ratio Cafe','ratio-cafe-ryshyo-kafyh','["مقاهي"]','["cafe"]','ريشيو كافيه في مدينة الباحة بأجواء جميلة وديكور حديث، يقدم المشروبات والحلويات ويشتهر بقهوة V60 الإثيوبية والفرنش توست بالشوكولاتة.','<div class="texte" > <p>يمتاز ريشيو كافيه بالأجواء الجميلة والديكورات الحديثة، ويوفر مجموعة من المشروبات الباردة والساخنة والحلويات اللذيذة، ويشتهر بقهوة V60 الإثيوبية والفرنش توست بالشوكولاتة. يعمل على مدار 24 ساعة يومياً، وللتواصل: 0534697836.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073260-68551059.jpg?v=1791629440"]','https://cmsphoto.ww-cdn.com/resizeapi/9020a26cb88b31976531a293853abb6b72c50798/480/',20.007622,41.4513745,'طريق الملك فيصل، الباحة 65421','+966534697836','','','https://www.saudi-guide.com/albaha/i/98073260/ratio-cafe-ryshyo-kafyh',1,0,'ريشيو كافيه ratio cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073259,'albaha','مقهى سينين','Seneen Cafe','seneen-cafe-mkha-synyn','["مقاهي"]','["cafe"]','مقهى سينين في الباحة مقهى راقٍ وهادئ بجلسات داخلية وخارجية، يشتهر بالدونات المحشوة والفرنش توست بالشوكولاتة البيضاء وقهوة V60.','<div class="texte" > <p>مقهى سينين مقهى راقٍ وهادئ، ويتميز بجلسات داخلية وخارجية. يشتهر بالدونات المحشوة بالنوتيلا والتوت والليمون والفستق، والفرنش توست بالشوكولاتة البيضاء، إلى جانب قهوة V60 المميزة، ويوفر مياهاً مجانية للزوار. للتواصل: 0555644769.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073259-68551070.jpg?v=1791629530", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073259-68551074.jpg?v=1791629538"]','https://cmsphoto.ww-cdn.com/resizeapi/90bd4bc64549b0d1e382f1746ea5b4c1ddaa8943/480/',20.0263994,41.4762102,'طريق الملك فهد، الباهر، الباحة 65721','+966555644769','','','https://www.saudi-guide.com/albaha/i/98073259/seneen-cafe-mkha-synyn',1,0,'مقهي سينين seneen cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073256,'albaha','كافيه بوكا دي','Boca D Cafe','boca-d-cafe-kafyh-boka-dy','["مقاهي"]','["cafe"]','كافيه بوكا دي مقابل الممشى السياحي في الباحة من دورين بجلسات داخلية وخارجية، يقدم القهوة والحلويات والشوكولاتة البلجيكية والفطور الأمريكي.','<div class="texte" > <p>يتكون كافيه بوكا دي من دورين بجلسات داخلية وخارجية، ويقدم العديد من أنواع القهوة والحلويات، إلى جانب مشروبات الشوكولاتة البلجيكية الفاخرة وفطور أمريكي. يقع مقابل الممشى السياحي بموقع مميز، ويعمل يومياً من 6 صباحاً حتى منتصف الليل تقريباً (ويوم الجمعة من 2 ظهراً)، وللتواصل: 0552071139.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073256-68551097.jpg?v=1791629614", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073256-68551101.jpg?v=1791629625"]','https://cmsphoto.ww-cdn.com/resizeapi/83e56982be2f672d438432879102102195daf0d2/480/',20.0225573,41.4719223,'7228 الباهر، الباحة 65525','+966552071139','','','https://www.saudi-guide.com/albaha/i/98073256/boca-d-cafe-kafyh-boka-dy',1,0,'كافيه بوكا دي boca d cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073253,'albaha','كالما كافيه','Calma Cafe','calma-cafe-kalma-kafyh','["مقاهي"]','["cafe"]','كالما كافيه في الباحة مقهى بديكور جميل وجلسات داخلية وخارجية وعلوية، يقدم أنواع القهوة والحلويات المميزة ويشتهر بالكوكيز بان.','<div class="texte" > <p>يقدم كالما كافيه العديد من أنواع القهوة وأصناف الحلويات، ويحتوي على جلسات داخلية وخارجية وجلسات في الطابق العلوي. يتميز بديكوره الجميل وحلوياته المميزة، ويقدم أيضاً كوكيز بان محبباً لدى الزوار. يعمل يومياً من 7 صباحاً حتى منتصف الليل تقريباً (ويوم الجمعة من 12:45 ظهراً)، وللتواصل: 0536695155.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073253-68551127.jpg?v=1791629696"]','https://cmsphoto.ww-cdn.com/resizeapi/f7fb645bd065bf83e674fb030b30eff1233b6cd2/480/',20.0355537,41.4860683,'النزهة، طريق الملك فهد، الباحة 65711','+966536695155','','','https://www.saudi-guide.com/albaha/i/98073253/calma-cafe-kalma-kafyh',1,0,'كالما كافيه calma cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073250,'albaha','باورو كافيه','Bauro Cafe','bauro-cafe-baoro-kafyh','["مقاهي"]','["cafe"]','باورو كافيه قرب غابة رغدان في الباحة مقهى عصري بموقع هادئ وجلسات داخلية وخارجية، يقدم المشروبات الساخنة والباردة وأصناف الحلويات.','<div class="texte" > <p>مقهى ذو طابع عصري يقدم العديد من أصناف المشروبات الساخنة والباردة وأصنافاً متنوعة من الحلويات، ويحتوي على جلسات داخلية وخارجية. يقع بالقرب من غابة رغدان بموقع هادئ يناسب الجلسات الطويلة. يعمل يومياً من الواحدة ظهراً حتى منتصف الليل، وللتواصل: 0501410436.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073250-68538023.jpg?v=1791501560"]','https://cmsphoto.ww-cdn.com/resizeapi/601fe40ea55eb896e7f5b6d0f34dc26a9b6f9a12/480/',20.0220561,41.4321731,'غابة رغدان، الباحة 65541','+966501410436','','','https://www.saudi-guide.com/albaha/i/98073250/bauro-cafe-baoro-kafyh',1,0,'باورو كافيه bauro cafe مقاهي',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073248,'albaha','مطعم فيفث سيزون','Fifth Season Restaurant','fifth-season-restaurant-mtaam-fyfth-syzon','["مطاعم"]','["food"]','مطعم فيفث سيزون في الباحة يقدم أشهى المأكولات اللبنانية والتركية من مقبلات ومشاوي، مع جلسات خارجية مريحة في أجواء الباحة المعتدلة.','<div class="texte" > <p>مطعم فيفث سيزون وجهة مميزة لمحبي تذوق أشهى أصناف الطعام العربية، حيث يهدف إلى تقديم تجربة طعام فريدة ومريحة لزواره. يشتهر بالمأكولات اللبنانية والتركية كالمقبلات الباردة وأطباق المشاوي، ويوفر جلسات خارجية مريحة في الطقس الجميل. يعمل يومياً من 12 ظهراً حتى منتصف الليل تقريباً (ويومي الخميس والجمعة حتى الواحدة فجراً)، وللتواصل: 0534896665.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073248-68538018.jpg?v=1791501205"]','https://cmsphoto.ww-cdn.com/resizeapi/a7eab6f664a9dd9ae85a2e118cce017638c0da93/480/',20.0072116,41.4618932,'طريق الملك سعود، وسط المدينة، الباحة 65522','+966534896665','','','https://www.saudi-guide.com/albaha/i/98073248/fifth-season-restaurant-mtaam-fyfth-syzon',1,0,'مطعم فيفث سيزون fifth season restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073247,'albaha','مطعم البستان','Al Bustan Restaurant','al-bustan-restaurant-mtaam-albstan','["مطاعم"]','["food"]','مطعم البستان من أشهر مطاعم المأكولات اللبنانية في الباحة، يقدم تشكيلة واسعة من الأطباق في مبنى أنيق من طابقين بأجواء دافئة.','<div class="texte" > <p>مطعم البستان من أفضل المطاعم التي تقدم المأكولات اللبنانية في الباحة، ويتميز بتقديم تشكيلة واسعة ومتنوعة من الأطباق اللبنانية الشهية، بتصميم أنيق مكون من طابقين وأجواء دافئة مناسبة للطقس البارد. يعمل يومياً من 12 ظهراً حتى 12:30 فجراً، وللتواصل: 0177241007.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073247-68538050.jpg?v=1791502492", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073247-68538051.jpg?v=1791502511"]','https://cmsphoto.ww-cdn.com/resizeapi/b39d6abbf16434ac2aab0a5a5449b88e18c0124a/480/',20.0440394,41.4474529,'راغدان، الباحة 65731','+966177241007','','','https://www.saudi-guide.com/albaha/i/98073247/al-bustan-restaurant-mtaam-albstan',1,0,'مطعم بستان al bustan restaurant مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073245,'albaha','مطعم وكافيه سول','Sol Restaurant and Cafe','sol-restaurant-and-cafe-mtaam-okafyh-sol','["مطاعم"]','["food"]','مطعم وكافيه سول في الباحة بتصميم مستوحى من التراث الأندلسي من طابقين، يشتهر بالأطباق الإيطالية كالبيتزا والريزوتو ويقدم حلويات متنوعة.','<div class="texte" > <p>يتميز مطعم وكافيه سول بتصميم مستوحى من التراث الأندلسي، ويتكون من طابقين بجلسات داخلية وخارجية مع مواقف سيارات، كما يقدم المقهى قائمة متنوعة من الحلويات. يشتهر بأطباقه الإيطالية كالبيتزا والريزوتو، ويضم أيضاً محل زهور ضمن المجمع. يعمل يومياً من 7 صباحاً حتى منتصف الليل تقريباً (ويوم الجمعة من 12:30 ظهراً)، وللتواصل: 0508800004.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google (صور المالك)</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073245-68538059.jpg?v=1791502828", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073245-68538060.jpg?v=1791502843"]','https://cmsphoto.ww-cdn.com/resizeapi/82496f786dcbdd32c0c164f39e046a167e16ef82/480/',20.0045625,41.4604375,'وسط المدينة، الباحة 65522','+966508800004','','','https://www.saudi-guide.com/albaha/i/98073245/sol-restaurant-and-cafe-mtaam-okafyh-sol',1,0,'مطعم وكافيه سول sol restaurant and cafe مطاعم',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073242,'albaha','مزرعة الدوسية','Al Dawsiyah Farm','al-dawsiyah-farm-mzraa-aldosy','["مزارع"]','["nature"]','مزرعة الدوسية في وادي سيال بمحافظة الحجرة من أكبر مزارع النباتات العطرية والطبية في المملكة، وتنتج المورينقا ومحاصيل عضوية متنوعة.','<div class="texte" > <p>تعد مزرعة الدوسية أكبر مزرعة للنباتات العطرية على مستوى المملكة، وتُعد أول مزرعة متخصصة في إنتاج النباتات الطبية والعطرية في المملكة. تتميز بإنتاج النباتات الطبية والعطرية والمنتجات العضوية ومنتجات المورينقا (العربية والهندية)، كما تحتوي على العديد من الأصناف الأخرى مثل المانجو والليمون والسمسم والتفاح وغيرها، وجميع منتجاتها عضوية من النبتة وحتى المحصول الزراعي. تعمل يومياً من 6 صباحاً حتى 7 مساءً، وللتواصل: 0555702987.</p> </div>','[]','',20.0709582,40.8704624,'وادي سيال، محافظة الحجرة 28791','+966555702987','https://baha.gov.sa/ar/Albums/ImageDetails/486','','https://www.saudi-guide.com/albaha/i/98073242/al-dawsiyah-farm-mzraa-aldosy',1,0,'مزرعه دوسيه al dawsiyah farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073240,'albaha','مزرعة وأكواخ بساتين اللوز','Basateen Al Loz Farm and Cabins','basateen-al-loz-farm-and-cabins-mzraa-oakoakh-bsatyn-alloz','["مزارع"]','["nature"]','بساتين اللوز في الباحة مزرعة ريفية بأشجار اللوز والتين والعنب، تضم أكواخاً خشبية للإقامة ومقهى وحديقة طيور وحيوانات صغيرة.','<div class="texte" > <p>تمثل مزرعة وأكواخ "بساتين اللوز" البيئة الريفية البكر لمنطقة الباحة، حيث يمكن التجول في المزرعة ومشاهدة أشجارها ومنتجاتها من اللوز والتين والعنب وغيرها، كما تضم المزرعة أكواخاً خشبية يحتوي كل كوخ منها على غرفتين بكامل ملحقاتها، بالإضافة إلى مقهى مجهز لخدمة زوار المزرعة يقدم فطوراً تقليدياً وبيتزا ومشروبات، وأحواض ماء بنافورات، وحديقة طيور وحيوانات صغيرة. تشمل الأنشطة التجول في المزرعة والإقامة في الأكواخ، وتضم مصلى ودورات مياه وكوخاً للطيور ومقهى وجلسات. تعمل يومياً من 6 صباحاً حتى 10:30 صباحاً ومن 3 حتى 9 مساءً، وللتواصل: 0550785152.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073240-68538063.jpg?v=1791502934", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073240-68538066.jpg?v=1791502943"]','https://cmsphoto.ww-cdn.com/resizeapi/50bc43c9f8c50b03c3648ddef8e0e71a5e70c669/480/',19.9947093,41.5187656,'بني ظبيان، قرية الخويتم، الروضة، الباحة 65515','+966550785152','https://baha.gov.sa/ar/Albums/ImageDetails/246','','https://www.saudi-guide.com/albaha/i/98073240/basateen-al-loz-farm-and-cabins-mzraa-oakoakh-bsatyn-alloz',1,0,'مزرعه واكواخ بساتين لوز basateen al loz farm and cabins مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073239,'albaha','مزرعة الزيتونة','Al Zaytuna Farm','al-zaytuna-farm-mzraa-alzyton','["مزارع"]','["nature"]','مزرعة الزيتونة في الباحة أول مزرعة سياحية معتمدة في المملكة، تضم معاصر زيتون وحديقة طيور وفراشات ومزرعة فراولة وركوب خيل.','<div class="texte" > <p>أول مزرعة سياحية معتمدة من وزارة السياحة على مستوى المملكة. تتيح المزرعة المجال أمام الزوار للتنزه في أرجائها والتمتع بمشاهدة المدرجات الطبيعية والمحاصيل الزراعية والمرافق الترفيهية في أجواء عائلية وضيافة ترحيبية متميزة، وهي بذلك إحدى أهم الوجهات السياحية الأفضل في المنطقة الجنوبية ومدينة الباحة خاصة. تشمل الأنشطة معاصر الزيتون، وحديقة الطيور، وحديقة الفراشات، ومزرعة الفراولة، وإفطار، ومتاجر الزيتونة، وكهف الزيتونة، وركوب الخيل، والرمي بالسهام، بالإضافة إلى مسجد ودورات مياه ووحدات سكنية. تعمل الخميس والجمعة والسبت، وللتواصل: 0552732870.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073239-68299804.jpg?v=1789817334"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073239-68299804.jpg?v=1789817334',20.0763061,41.5692638,'طريق الملك فهد، الباحة 65717','+966552732870','https://baha.gov.sa/ar/Albums/ImageDetails/245','','https://www.saudi-guide.com/albaha/i/98073239/al-zaytuna-farm-mzraa-alzyton',1,0,'مزرعه زيتونه al zaytuna farm مزارع',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073234,'albaha','نزل العائد التراثي','Al Aed Heritage Lodge','al-aed-heritage-lodge-nzl-alaaayd-altrathy','["التراث والثقافة"]','["heritage"]','نزل العائد التراثي في محافظة بني كبير يعرض القطع الأثرية وأدوات الأجداد، ويقدم الضيافة والفطور الشعبي والعروض الفلكلورية للزوار.','<div class="texte" > <p>يعكس نزل العائد تراث المنطقة وتاريخها ومظاهر الكرم والضيافة، كما يعرض مجموعة من أهم القطع الأثرية والأدوات القديمة بمحافظة بني كبير. تشمل الأنشطة جولة في النزل مع التعريف بتراث الأجداد وتاريخ المنطقة وتقديم الضيافة والوجبات الشعبية وعروض الفرقة الشعبية، ويشتهر بتقديم فطور سعودي محلي أصيل وإمكانية حجز تجربة عشاء منزلية الصنع مسبقاً. للتواصل: 0544752231.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073234-68538068.jpg?v=1791502981", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073234-68538069.jpg?v=1791502995"]','https://cmsphoto.ww-cdn.com/resizeapi/3be30216212e6e7d603a6411d920d78384081bcf/480/',19.9441875,41.5650625,'الدهامشة، بني كبير 65642','+966544752231','','','https://www.saudi-guide.com/albaha/i/98073234/al-aed-heritage-lodge-nzl-alaaayd-altrathy',1,0,'نزل عائد تراثي al aed heritage lodge تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073224,'albaha','شلال الشولة','Al Shawlah Waterfall','al-shawlah-waterfall-shlal-alshol','["الشلالات والأودية"]','["nature"]','شلال الشولة في بني حسن موقع طبيعي بكر لعشاق المغامرة، من أكبر مصادر تدفق المياه في الباحة، ويصله الزوار بسيارات الدفع الرباعي.','<div class="texte" > <p>شلال الشولة موقع طبيعي بكر بمحافظة بني حسن يستهوي عشاق المغامرة، إذ يتطلب الوصول إليه سيارة دفع رباعي ومسافة مشي معتدلة الصعوبة. يُعد من أكبر مصادر تدفق المياه في منطقة الباحة، ويستقطب هواة التخييم لعدة أيام بجانب مجرى مياهه الهادئ والمنعش.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073224-68538070.jpg?v=1791503066"]','https://cmsphoto.ww-cdn.com/resizeapi/31e8d8f20f6d81b3101475ddbc808a780f8aaf32/480/',20.1064172,41.3966339,'محافظة بني حسن 65737','','https://baha.gov.sa/ar/Albums/ImageDetails/476','','https://www.saudi-guide.com/albaha/i/98073224/al-shawlah-waterfall-shlal-alshol',1,0,'شلال شوله al shawlah waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073222,'albaha','شلال عين الجمل','Ain Al Jamal Waterfall','ain-al-jamal-waterfall-shlal-aayn-algml','["الشلالات والأودية"]','["nature"]','شلال عين الجمل في محافظة بني حسن موقع طبيعي جميل ونظيف بأجواء هادئة ومناظر خلابة، ويُفضل الوصول إليه بسيارة دفع رباعي.','<div class="texte" > <p>شلال عين الجمل موقع طبيعي جميل ونظيف بمحافظة بني حسن، يُنصح باستخدام سيارة دفع رباعي للوصول إليه بسهولة، وهو من الوجهات التي يستمتع زوارها بأجوائها الهادئة ومناظرها الطبيعية الخلابة.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073222-68299717.jpg?v=1789816764"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073222-68299717.jpg?v=1789816765',20.1087782,41.3934609,'محافظة بني حسن 65737','','https://baha.gov.sa/ar/Albums/ImageDetails/405','','https://www.saudi-guide.com/albaha/i/98073222/ain-al-jamal-waterfall-shlal-aayn-algml',1,0,'شلال عين جمل ain al jamal waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073221,'albaha','شلال الشراشير','Al Sharashir Waterfall','al-sharashir-waterfall-shlal-alshrashyr','["الشلالات والأودية"]','["nature"]','شلال الشراشير من أكبر شلالات منطقة الباحة بمنحدرين يصنعان مشهداً مميزاً، ويُفضل الوصول إليه بسيارة مرتفعة أو سيراً على الأقدام.','<div class="texte" > <p>يُعد شلال الشراشير من أكبر الشلالات في منطقة الباحة، وله منحدران يجعلانه مشهداً مميزاً. يُفضل استخدام سيارة دفع رباعي أو مرتفعة قليلاً عن الأرض للاقتراب منه، أو يمكن ركن السيارة والمشي إليه، مع العلم أنه لا توجد خدمات متوفرة في الموقع.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073221-68299674.jpg?v=1789816395"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98073221-68299674.jpg?v=1789816396',20.1030625,41.4719375,'محافظة بني حسن 65726','','https://baha.gov.sa/ar/Albums/ImageDetails/403','','https://www.saudi-guide.com/albaha/i/98073221/al-sharashir-waterfall-shlal-alshrashyr',1,0,'شلال شراشير al sharashir waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073220,'albaha','شلال صفا البراق','Safa Al Buraq Waterfall','safa-al-buraq-waterfall-shlal-sfa-albrak','["الشلالات والأودية"]','["nature"]','شلال صفا البراق في مدينة الباحة مجرى مائي طويل يمتد وسط الطبيعة، تتفاوت غزارته بحسب الموسم ويكون في أجمل حالاته بعد الأمطار.','<div class="texte" > <p>شلال صفا البراق موقع طبيعي طويل يشبه المجرى المائي، يمتد وسط الطبيعة بمدينة الباحة. تختلف غزارة مياهه بحسب الموسم، ويُنصح بزيارته بعد هطول الأمطار مباشرة للاستمتاع بأجمل مناظره، مع الحرص على الحفاظ على نظافة الموقع.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073220-68538071.jpg?v=1791503093"]','https://cmsphoto.ww-cdn.com/resizeapi/418642b090b332441e41afa759564adaa8b44dac/480/',20.0476442,41.5642646,'مدينة الباحة 65714','','','','https://www.saudi-guide.com/albaha/i/98073220/safa-al-buraq-waterfall-shlal-sfa-albrak',1,0,'شلال صفا براق safa al buraq waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (98073219,'albaha','شلال أم الدقيق','Umm Al Daqiq Waterfall','umm-al-daqiq-waterfall-shlal-am-aldkyk','["الشلالات والأودية"]','["nature"]','شلال أم الدقيق في مدينة الباحة موقع طبيعي ساحر تحيط به الأشجار الكثيفة، يزداد جمالاً بعد الأمطار ويستحق عناء الطريق للوصول.','<div class="texte" > <p>شلال أم الدقيق موقع طبيعي ساحر يتميز بجمال مناظره خصوصاً بعد هطول الأمطار، وتحيط به الأشجار الكثيفة. يتطلب الوصول إليه بعض الجهد نظراً لطبيعة الطريق، لكن جمال المكان وسحر الطبيعة المحيطة به يستحق الزيارة، ويُنصح بالحفاظ على نظافة الموقع لصون جماله لمن يأتي بعدك.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98073219-68538072.jpg?v=1791503158"]','https://cmsphoto.ww-cdn.com/resizeapi/41ec9bcfff70a7dab4245f1a0ea5f74725045839/480/',20.029137,41.4854365,'النزهة، مدينة الباحة 65711','+966573229729','https://baha.gov.sa/ar/Albums/ImageDetails/451','','https://www.saudi-guide.com/albaha/i/98073219/umm-al-daqiq-waterfall-shlal-am-aldkyk',1,0,'شلال ام دقيق umm al daqiq waterfall شلالات والاوديه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328599,'taif','منتزه الشلال','Alshalal Park','alshalal-park-mntzh-alshlal','["أماكن سياحية"]','["sights"]','مدينة ألعاب متكاملة ومناسبة لكل الأعمار.','<div class="texte" > <p>مدينة ألعاب متكاملة ومناسبة لكل الأعمار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328599-44161375.jpg?v=1637070608"]','https://cmsphoto.ww-cdn.com/resizeapi/28d75e11c61aeda1a70ee1f196f96da2548a3f37/480/',21.2894343,40.3875446,'Al Amir Sultan الخالدية الطائف','','','','https://www.saudi-guide.com/taif/i/59328599/alshalal-park-mntzh-alshlal',1,0,'منتزه شلال alshalal park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328596,'taif','ملاهي حديقة الحيوان','','mlahy-hdyk-alhyoan','["أماكن سياحية"]','["sights"]','حديقة واسعة وكبيرة جداً تحتوي على العديد من الحيوانات المختلفة بالإضافة إلى منطقة مخصصة للألعاب الكهربائية كما تحتوي الحديقة على مسطحات خضراء واسعة','<div class="texte" > <p>حديقة واسعة وكبيرة جداً تحتوي على العديد من الحيوانات المختلفة بالإضافة إلى منطقة مخصصة للألعاب الكهربائية كما تحتوي الحديقة على مسطحات خضراء واسعة، وكشكات لبيع الأطعمة والمشروبات، ومناطق للجلوس.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328596-44124340.jpg?v=1636991026"]','https://cmsphoto.ww-cdn.com/resizeapi/9d55b874aab5eb9b7e3b908096b0be5ba9152da4/480/',21.2299113,40.4287781,'At Taif Alhadaek At-Taif','','','','https://www.saudi-guide.com/taif/i/59328596/mlahy-hdyk-alhyoan',1,0,'ملاهي حديقه حيوان اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328574,'taif','منتزه الملك عبدالله','King Abdullah Park Taif','king-abdullah-park-taif-mntzh-almlk-aabdallh','["أماكن سياحية"]','["sights"]','متنزّه شاسع يضم مساحة للّعب ونوافير وحدائق زهور، بالإضافة إلى ملاعب كرة سلة وكرة طائرة.','<div class="texte" > <p>متنزّه شاسع يضم مساحة للّعب ونوافير وحدائق زهور، بالإضافة إلى ملاعب كرة سلة وكرة طائرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328574-44161434.jpg?v=1637070845"]','https://cmsphoto.ww-cdn.com/resizeapi/a8132902b1e891a47cee009bf1755107c7d05b40/480/',21.2704725,40.4540693,'3032 طريق الملك خالد، النسيم، الطائف 26524 6938 King Khalid Rd Alnaseem','','','','https://www.saudi-guide.com/taif/i/59328574/king-abdullah-park-taif-mntzh-almlk-aabdallh',1,0,'منتزه ملك عبدالله king abdullah park taif اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328573,'taif','منتزه سيسيد الوطني','Saiysad National park','saiysad-national-park-mntzh-sysyd-alotny','["أماكن سياحية"]','["sights"]','منتزه واسع وكبير جدا يضم عدة مناطق لعب للأطفال وجلسات مظللة وأماكن للتنزه حول السد الصغير، بالإضافة إلى جداول المياه الموسمية.','<div class="texte" > <p>منتزه واسع وكبير جدا&nbsp;يضم عدة مناطق&nbsp;لعب للأطفال <span>وجلسات مظللة&nbsp;</span>وأماكن&nbsp;للتنزه&nbsp;حول السد الصغير، بالإضافة إلى جداول المياه الموسمية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328573-44122580.jpg?v=1636984750"]','https://cmsphoto.ww-cdn.com/resizeapi/b44645552494ff7fc328a81998e064e8bd00e58e/480/',21.2932561,40.4941168,'7FVV+8J5 Taif At-Taif','','','','https://www.saudi-guide.com/taif/i/59328573/saiysad-national-park-mntzh-sysyd-alotny',1,0,'منتزه سيسيد وطني saiysad national park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59328563,'taif','منتزه الردف','Arruddaf Park','arruddaf-park-mntzh-alrdf','["أماكن سياحية"]','["sights"]','متنزه واسع مناسب للعائلات يحتوي على عروض النافورة المائية وعدة مناطق للتنزّه بالإضافة إلى فعاليات ثقافية متنوعة.','<div class="texte" > <p>متنزه&nbsp;واسع مناسب للعائلات يحتوي على&nbsp;عروض النافورة المائية وعدة مناطق للتنزّه بالإضافة إلى فعاليات ثقافية متنوعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59328563-44124233.jpg?v=1636990624"]','https://cmsphoto.ww-cdn.com/resizeapi/12783d6e761ebcf30957c994927bd24390b9a932/480/',21.2291806,40.4252563,'Abu Talib Al Ruddaf At Taif','','','','https://www.saudi-guide.com/taif/i/59328563/arruddaf-park-mntzh-alrdf',1,0,'منتزه ردف arruddaf park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59323943,'riyadh','نبض الرياض','Nabd Al Riyadh','nabd-al-riyadh','["أماكن سياحية"]','["sights"]','نبض الرياض في قصر المصمك، فعالية ثقافية تعرض الموروث الشعبي لمناطق المملكة المختلفة في مكان واحد.','<div class="texte" > <p>يقام مهرجان نبض الرياض في قصر المصمك حيث يأخذ الزوار جولة بين لوحات فنية تبين الموروث الشعبي لمناطق المملكة ، فمن الطبيعة الخلابة في المنطقة الجنوبية إلى الشواهد التاريخية في المملكة ومن فنون الحجاز في الغربية إلى سواحل الشرقية لتجتمع كلها في المنطقة الوسطى وفي قصر المصمك تحديداً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59323943-43622242.jpg?v=1633379966"]','https://cmsphoto.ww-cdn.com/resizeapi/2be2541676ab8dc4b2286f86f799e72bbfc601ea/480/',24.6308337,46.7117965,'الديرة الرياض الرياض','','','','https://www.saudi-guide.com/riyadh/i/59323943/nabd-al-riyadh',1,0,'نبض رياض nabd al riyadh اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305875,'jeddah','حديقة الشلال الترفيهية','','hdyk-alshlal-altrfyhy','["سياحة وترفيه"]','["sights"]','تُعد حديقة الشلال الترفيهية واحدة من أكثر المتنزهات شعبية في جدة، وذلك لموقعها المتميز على شاطئ البحر الأحمر وما فيها من وسائل ترفيه.','<div class="texte" > <p>تُعد حديقة الشلال الترفيهية واحدة من أكثر المتنزهات شعبية في&nbsp;جدة، حيث يزورها ما يقرب من مليون زائر سنويا لموقعها المتميز على شاطئ&nbsp;البحر الأحمر&nbsp;وما فيها من وسائل ترفيه متعددة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305875-44001912.jpg?v=1636081734"]','https://cmsphoto.ww-cdn.com/resizeapi/238b0821edd5dd58bb837985a42b66ae8ebccc73/480/',21.567957,39.111062,'طريق الكورنيش، Ash Shati Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305875/hdyk-alshlal-altrfyhy',1,0,'حديقه شلال ترفيهيه سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305851,'jeddah','فن تايم','Fun Time','fun-time-fn-taym','["سياحة وترفيه"]','["sights"]','مركز ترفيهي داخلي يحتوي على ألعاب كلاسيكية وألعاب ركوب وسينما بتقنية 4D، بالإضافة إلى مطاعم متنوعة.','<div class="texte" > <p>مركز ترفيهي داخلي يحتوي على ألعاب كلاسيكية وألعاب ركوب وسينما بتقنية 4D، بالإضافة إلى مطاعم متنوعة.</p> <p>يجمع المركز بين الألعاب التقليدية وألعاب الركوب الحديثة وتجربة السينما التفاعلية، إلى جانب خيارات متنوعة من المطاعم، ما يجعله وجهة مناسبة لقضاء وقت ممتع مع العائلة والأصدقاء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305851-44001924.jpg?v=1636081994"]','https://cmsphoto.ww-cdn.com/resizeapi/85fd18f307112bd26acff252ff01da7db72296d5/480/',21.593133,39.106782,'H4V4+6P طريق الكورنيش، Ash Shati','','','','https://www.saudi-guide.com/jeddah/i/59305851/fun-time-fn-taym',1,0,'فن تايم fun time سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305848,'jeddah','منتزه عطالله الارض السعيدة','Atallah Happy Land Park','atallah-happy-land-park-mntzh-aatallh-alard-alsaayd','["سياحة وترفيه"]','["sights"]','الأرض السعيدة هي مدينة ملاهي عريقة تضم ألعاب ركوب داخلية وخارجية، بالإضافة إلى حلبة للتزلّج على الجليد وقاعة طعام.','<div class="texte" > <p>الأرض السعيدة هي مدينة ملاهي عريقة تضم ألعاب ركوب داخلية وخارجية، بالإضافة إلى حلبة للتزلّج على الجليد وقاعة طعام.</p> <p>تجمع الأرض السعيدة بين أجواء مدينة الملاهي التقليدية والألعاب المتنوعة، وتضيف حلبة التزلج على الجليد تجربة مختلفة ضمن المكان نفسه، بالإضافة إلى قاعة الطعام التي تتيح للزوار الاستراحة بين الجولات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305848-44001930.jpg?v=1636082116"]','https://cmsphoto.ww-cdn.com/resizeapi/19ede56b1c011b23b43c9d7ea6165df58582bcd4/480/',21.6178999,39.1085014,'Jiddah Ash Shati Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305848/atallah-happy-land-park-mntzh-aatallh-alard-alsaayd',1,0,'منتزه عطالله ارض سعيده atallah happy land park سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305807,'jeddah','سماء الغربية للطيران','Western Sky Aviation','western-sky-aviation-smaaa-alghrby-lltyran','["سياحة وترفيه"]','["sights"]','يقدم نادي سماء الغربية للطيران تجربة طيران فريدة من نوعها باحترافية ومستوى أمان عالي.','<div class="texte" > <p>يقدم نادي سماء الغربية للطيران تجربة طيران فريدة من نوعها باحترافية ومستوى أمان عالٍ.</p> <p>يتيح النادي لعشاق الطيران خوض تجربة تحليق تحت إشراف طيارين محترفين ووفق معايير سلامة عالية، ما يجعله وجهة مميزة لهواة المغامرات الجوية في جدة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305807-44001938.jpg?v=1636082311"]','https://cmsphoto.ww-cdn.com/resizeapi/0a085e056bcdf39014abf99a22d66f2c5c346e72/480/',21.629858,39.115161,'King Abdul Aziz Rd Al Mohammadiyyah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305807/western-sky-aviation-smaaa-alghrby-lltyran',1,0,'سماء غربيه للطيران western sky aviation سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305784,'jeddah','حديقة الارادة لذوي الاحتياجات الخاصة','','hdyk-alarad-lthoy-alahtyagat-alkhas','["سياحة وترفيه"]','["sights"]','حديقة الإرادة تعد أول حديقة مجهزة لذوي الاحتياجات الخاصة في المملكة العربية السعودية، تضم الحديقة ممشى وعدة ملاعب ومناطق ألعاب بالإضافة إلى جلسات ومظلات ومساحات خضراء.','<div class="texte" > <p>حديقة الإرادة تعد أول حديقة مجهزة لذوي الاحتياجات الخاصة في المملكة العربية السعودية، تضم الحديقة ممشى وعدة ملاعب ومناطق ألعاب بالإضافة إلى جلسات ومظلات ومساحات خضراء مزودة بالعديد من الأشجار والنخيل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305784-44001945.jpg?v=1636082475"]','https://cmsphoto.ww-cdn.com/resizeapi/2a9b06fc364bdc482de07f3476452a34210918da/480/',21.6000722,39.1442278,'SA As Salamah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305784/hdyk-alarad-lthoy-alahtyagat-alkhas',1,0,'حديقه اراده لذوي احتياجات خاصه سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305775,'jeddah','ايس لاند','Ice Land','ice-land-ays-land','["سياحة وترفيه"]','["sights"]','آيس لاند هو مركز ترفيهي يمنح زائريه متعة خاصة بين الثلوج، يحتوي المركز على ساحة للتزلج وصالة بولينج وطاولات بلياردو وألعاب الفيديو وغيرها الكثير بالإضافة إلى أكشاك.','<div class="texte" > <p>آيس لاند هو مركز ترفيهي يمنح زائريه متعة خاصة بين الثلوج، يحتوي المركز على ساحة للتزلج وصالة بولينج وطاولات بلياردو وألعاب الفيديو وغيرها الكثير بالإضافة إلى أكشاك الوجبات السريعة المفضلة لدى الزوار غالباً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305775-44001946.jpg?v=1636082674"]','https://cmsphoto.ww-cdn.com/resizeapi/0f61f16ed4c214c3ef7a3e2173a993a10da298a9/480/',21.5988806,39.1449835,'Jeddah As Salamah Jiddah','','','','https://www.saudi-guide.com/jeddah/i/59305775/ice-land-ays-land',1,0,'ايس لاند ice land سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305739,'jeddah','IN10SO ان تن سو','','in10so-tn-so','["سياحة وترفيه"]','["sights"]','مركز ترفيهي فريد ومميز للعائلات يضم العديد من الرياضات مثل البولينغ والرماية والبلياردو وغيرها كما يحتوي أيضا على ألعاب الفيديو.','<div class="texte" > <p>مركز ترفيهي فريد ومميز للعائلات يضم العديد من الرياضات مثل البولينغ والرماية والبلياردو وغيرها كما يحتوي أيضًا على ألعاب الفيديو.</p> <p>يجمع المركز أنشطة متعددة في مكان واحد تناسب مختلف الأعمار، من البولينغ والرماية إلى البلياردو وألعاب الفيديو، ما يجعله وجهة مناسبة للعائلات والمجموعات الباحثة عن تجربة ترفيهية متنوعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305739-44001956.jpg?v=1636083205"]','https://cmsphoto.ww-cdn.com/resizeapi/bfcc70ba9e4ad09bad84b4ffbdcdb02b3d69929f/480/',21.5607335,39.1842282,'جدة الفيصلية جدة','','','','https://www.saudi-guide.com/jeddah/i/59305739/in10so-tn-so',1,0,'in10so ان تن سو سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305703,'jeddah','مون تون','Moon Toon','moon-toon-mon-ton','["سياحة وترفيه"]','["sights"]','مدينة ملاهي تحتوي على ألعاب كهربائية وإلكترونية متنوعة ومناسبة لجميع الأعمار.','<div class="texte" > <p>مدينة ملاهي تحتوي على ألعاب كهربائية وإلكترونية متنوعة ومناسبة لجميع الأعمار.</p> <p>تضم المدينة مجموعة متنوعة من الألعاب الكهربائية والإلكترونية المناسبة لمختلف الأعمار، ما يجعلها وجهة مناسبة لقضاء وقت ممتع مع الأطفال والعائلة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305703-44001964.jpg?v=1636083320"]','https://cmsphoto.ww-cdn.com/resizeapi/b827c73063aea6831a85430d1749c3abd0a22247/480/',21.5608944,39.1862566,'Hassan Ad Dabi Al Faisaliyyah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305703/moon-toon-mon-ton',1,0,'مون تون moon toon سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305700,'jeddah','اوكتو','Octo!','octo-aokto','["سياحة وترفيه"]','["sights"]','مدينة ملاهي مخصصة للأطفال ومجهزة بأنوار ومجسمات لشخصيات كرتونية تجعل تجربة اللعب أكثر متعة وحماس.','<div class="texte" > <p>مدينة ملاهي مخصصة للأطفال ومجهزة بأنوار ومجسمات لشخصيات كرتونية تجعل تجربة اللعب أكثر متعة وحماسًا.</p> <p>تتميز المدينة بأجوائها الملونة ومجسمات الشخصيات الكرتونية المنتشرة في أرجائها، ما يضفي طابعًا مرحًا على تجربة اللعب ويجعلها وجهة محببة لدى الأطفال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305700-44001967.jpg?v=1636083527"]','https://cmsphoto.ww-cdn.com/resizeapi/8178e8da721b8195641af451698c99a7b2b37369/480/',21.595196,39.229232,'جدة المنار جدة','','','','https://www.saudi-guide.com/jeddah/i/59305700/octo-aokto',1,0,'اوكتو octo! سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305661,'jeddah','منتزه الامواج الترفيهي','','mntzh-alamoag-altrfyhy','["سياحة وترفيه"]','["sights"]','منتزه الأمواج الترفيهي يعتبر من أكثر الأماكن الترفيهية المميزة للعائلات بجدة حيث يحتوي على العديد من الألعاب الكهربائية المتنوعة والمسلية لكل الأعمار.','<div class="texte" > <p>منتزه&nbsp;الأمواج الترفيهي يعتبر من أكثر الأماكن الترفيهية المميزة&nbsp;للعائلات بجدة حيث&nbsp;يحتوي&nbsp;على العديد من الألعاب الكهربائية المتنوعة والمسلية لكل الأعمار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305661-44001972.jpg?v=1636083715"]','https://cmsphoto.ww-cdn.com/resizeapi/75fb7b9c8cf86ff1b6b9892dda140300a0db5c23/480/',21.5992976,39.2862801,'محاذي جدة جدة','','','','https://www.saudi-guide.com/jeddah/i/59305661/mntzh-alamoag-altrfyhy',1,0,'منتزه امواج ترفيهي سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305653,'jeddah','القرية المائية','Water Village','water-village-alkry-almayy','["سياحة وترفيه"]','["sights"]','مركز ترفيهي مناسب للعائلات فيه مسابح وقنوات مائية وزحاليق أنبوبية، بالإضافة إلى مطعم بوفيه ومطاعم في الفناء.','<div class="texte" > <p>مركز ترفيهي مناسب للعائلات فيه مسابح وقنوات مائية وزحاليق&nbsp;أنبوبية، بالإضافة إلى مطعم بوفيه ومطاعم في الفناء، تعد القرية متنفساً للسياح وأهالي المنطقة حيث يقضون فيها وقت مليء بالمتعة والتسلية</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305653-44001974.jpg?v=1636083836"]','https://cmsphoto.ww-cdn.com/resizeapi/4bfc8b99653e39d4d569f5c560602ea4f0b9f165/480/',21.5893158,39.1854559,'Al Makarunah Rd Ar Rabwah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305653/water-village-alkry-almayy',1,0,'قريه مائيه water village سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305494,'jeddah','عالم سماش','Smash World','aaalm-smash','["سياحة وترفيه"]','["sights"]','عالم سماش هو عالم ألعاب ترفيهي ومتنوع مناسب لجميع الأعمار، يحتوي على العديد من الألعاب الاكترونية والرياضات الممتعة.','<div class="texte" > <p>عالم سماش هو مركز ألعاب ترفيهي متنوع مناسب لجميع الأعمار، يحتوي على العديد من الألعاب الإلكترونية والأنشطة الرياضية الممتعة.</p> <p>يوفر المكان بيئة مليئة بالحيوية تجمع بين الألعاب الإلكترونية والأنشطة الرياضية الخفيفة، ما يجعله وجهة مناسبة لقضاء وقت ترفيهي مع الأصدقاء والعائلة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305494-44001987.jpg?v=1636084022"]','https://cmsphoto.ww-cdn.com/resizeapi/431d898f193e10b248552f2ed6e976604da10a53/480/',21.5844524,39.1292875,'SA Al Zahra Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305494/aaalm-smash',1,0,'عالم سماش smash world سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305375,'jeddah','متحف الفنون المنزلية','Museum of Home Art','museum-home-art-mthf-alfnon-almnzly','["التراث والثقافة"]','["heritage"]','متحف يعرض تاريخ وتراث منطقة جدة وعادات وتقاليد أهلها من ملابس وأثاث وغيرها، ويشرح عن البيئة القديمة لها.','<div class="texte" > <p>متحف الفنون المنزلية هو متحف يعرض تاريخ وتراث منطقة جدة وعادات وتقاليد أهلها من ملابس وأثاث وغيرها، ويشرح عن البيئة القديمة لها، ويعتبر من اهم الأماكن السياحية في جدة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305375-44022696.jpg?v=1636292779"]','https://cmsphoto.ww-cdn.com/resizeapi/7b4890d913e4d43c424cb08ad3bfb4bf858e0dd5/480/',21.5209207,39.1550775,'الكلاء الحمراء Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305375/museum-home-art-mthf-alfnon-almnzly',1,0,'متحف فنون منزليه museum of home art تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305374,'jeddah','متحف درويش سلامة','Darwish Salamah Museum','darwish-salamah-museum-mthf-droysh-slam','["التراث والثقافة"]','["heritage"]','يقع متحف درويش سلامة في منزل العقيد الطيار درويش سلامة الذي حوّل منزله إلى مزار تراثي مميز.','<div class="texte" > <p>يقع متحف درويش سلامة في منزل العقيد الطيار درويش سلامة الذي تقاعد بعد&nbsp;تحطم&nbsp;طائرته بسبب الظروف الجوية السيئة وهو&nbsp;ما شجعه على الإبداع وتحويل منزله إلى مزار تراثي لا يمكن تفويته، فقد قام بصنع&nbsp;مجموعة كبيرة تزيد عن الألف قطعة&nbsp;من مجسمات البيوت التراثية يدوياً وباستخدام الإسمنت والحديد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305374-44022803.jpg?v=1636294975"]','https://cmsphoto.ww-cdn.com/resizeapi/75b40440e6f105fc486c76373c9f450a38437d59/480/',21.527099,39.1596019,'3029 Ar Rubu Al Arabiyyah Al Hamra District','','','','https://www.saudi-guide.com/jeddah/i/59305374/darwish-salamah-museum-mthf-droysh-slam',1,0,'متحف درويش سلامه darwish salamah museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305351,'jeddah','جدة التاريخية','Historic Jeddah','historic-jeddah-gd-altarykhy','["التراث والثقافة"]','["heritage"]','جدة التاريخية، وتعرف محليًا باسم جدة البلد، تقع في وسط مدينة جدة وتعد من أقدم الأحياء المأهولة في المنطقة.','<div class="texte" > <p>جدة التاريخية، وتعرف محلياً بإسم&nbsp;جدة البلد، تقع في وسط مدينة جدة، ويعود تاريخها -حسب بعض المصادر- إلى عصور ما قبل الإسلام، وأن نقطة التحول في تاريخها كانت في عهد الخليفة الراشد عثمان بن عفان رضي الله عنه&nbsp;عندما اتخذها ميناءً لمكة المكرمة&nbsp;في عام 26هـ</p> <p>&nbsp;تضم جدة التاريخية عدداً من المعالم والمباني الأثرية والتراثية، مثل آثار سور جدة وحاراتها التاريخية: حارة المظلوم، وحارة الشام، وحارة اليمن، وحارة البحر، كما يوجد بها عدد من المساجد التاريخية أبرزها: مسجد عثمان بن عفان، ومسجد الشافعي، ومسجد الباشا، ومسجد عكاش، ومسجد المعمار، وجامع الحنفي، إضافة إلى الأسواق التاريخية، وفي 21 يونيو 2014&nbsp;أُدرجت ضمن مواقع التراث العالمي،&nbsp;وأمر الملك سلمان بن عبد العزيز&nbsp;في يونيو 2018&nbsp;بإنشاء إدارة باسم إدارة مشروع جدة التاريخية ترتبط بوزارة الثقافة، مع تخصيص ميزانية مستقلة لها، وذلك بناء على ما عرضه ولي العهد الأمير محمد بن سلمان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305351-44023052.jpg?v=1636298901"]','https://cmsphoto.ww-cdn.com/resizeapi/0d560cd2770fed23dfdaef8780f9bcb6157c5404/480/',21.4888583,39.1857913,'SA Al-Balad Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305351/historic-jeddah-gd-altarykhy',1,0,'جده تاريخيه historic jeddah تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305316,'jeddah','متحف عبدالرؤوف حسن خليل','','mthf-aabdalroof-hsn-khlyl','["التراث والثقافة"]','["heritage"]','متحف لعرض المقتنيات الأثرية، يضم مجموعة متنوعة تعود لتاريخ شبه الجزيرة العربية والثقافة السعودية.','<div class="texte" > <p>متحف عبد&nbsp;الرؤوف خليل هو عبارة عن متحف&nbsp;لعرض المقتنات الأثرية، ويتميز بأنه يضم العديد من الآثار المتنوعة التي تعود لتاريخ منطقة شبة الجزيرة العربية والثقافة السعودية والحضارة الاسلامية العثمانية. بالإضافة إلى ذلك فإنه يتميز بتأثره بالحضارة الصينية والحضارات الأخرى كالحضارة الأوروبية.</p> <p>يعد متحف عبد الرؤوف خليل من أهم وأجمل المتاحف والمعالم السياحية في المملكة العربية السعودية؛ لأهميته الحضارية والأثرية،&nbsp;زار المتحف العديد من السياسيين والآمراء و من أبرزهم&nbsp;الأمير تشارلز والأميرة ديانا</p> <p>&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305316-44023087.jpg?v=1636299141"]','https://cmsphoto.ww-cdn.com/resizeapi/60680619fb0a21acec6158f1b33807e3d7866984/480/',21.5806637,39.1765387,'SA Al Faisaliyyah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59305316/mthf-aabdalroof-hsn-khlyl',1,0,'متحف عبدالرؤوف حسن خليل تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305290,'jeddah','مدينة الطيبات للعلوم والمعرفة','Al Tayebat International City','al-tayebat-international-city-mdyn-altybat-llaalom-oalmaarf','["التراث والثقافة"]','["heritage"]','مدينة متكاملة تمثل طرز العمارة التقليدية في بلاد الحجاز وتحتوي على متحف تتجسد فيه كل أنواع الحضارات من قبل التاريخ وحتى العصر الحديث.','<div class="texte" > <p>مدينة متكاملة تمثل طرز العمارة التقليدية في بلاد الحجاز وتحتوي على متحف تتجسد فيه كل أنواع الحضارات من قبل التاريخ وحتى العصر الحديث.</p> <p>يمزج الموقع بين العمارة التراثية والمحتوى المتحفي، إذ يضم مجموعة واسعة من المقتنيات التي تعكس تنوع الحضارات عبر العصور، ما يجعله وجهة مهمة لعشاق التاريخ والتراث في جدة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305290-44023196.jpg?v=1636300283"]','https://cmsphoto.ww-cdn.com/resizeapi/5896583765bcbf5be7b696240b78662038e29a60/480/',21.5812175,39.1769051,'ريحانة الجزيرة حي الفيصلية جدة','','','','https://www.saudi-guide.com/jeddah/i/59305290/al-tayebat-international-city-mdyn-altybat-llaalom-oalmaarf',1,0,'مدينه طيبات للعلوم والمعرفه al tayebat international city تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59305285,'jeddah','متحف أبرق الرغامة','','mthf-abrk-alrgham','["التراث والثقافة"]','["heritage"]','أبرق الرغامة موقع أثري يقع شرق مدينة جدة في المملكة العربية السعودية، كان ممرًا تاريخيًا لطرق القوافل المتجهة من جدة إلى مكة المكرمة.','<div class="texte" > <p>أبرق الرغامة&nbsp;موقع أثري يقع شرق مدينة جدة&nbsp;في المملكة العربية السعودية، كان ممراً تاريخياً لطرق القوافل المتجهة من جدة إلى مكة المكرمة،&nbsp;اكتسب الموقع شهرته من كونه آخر نقطة عَسكَرَ فيها الملك عبد العزيز بن عبد الرحمن آل سعود&nbsp;بجيشه أثناء توحيد البلاد&nbsp;للدخول إلى جدة في 25 من ديسمبر من عام 1925م.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59305285-44023218.jpg?v=1636300554"]','https://cmsphoto.ww-cdn.com/resizeapi/a2d7523212a14b39c2a692dfa98844a1a30de0da/480/',21.5126172,39.2603684,'G776+24X ابرق الرغامة، جدة','','','','https://www.saudi-guide.com/jeddah/i/59305285/mthf-abrk-alrgham',1,0,'متحف ابرق رغامه تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300873,'jeddah','ممشى التحليه','Tahlia Walkway','tahlia-walkway-mmsh-althlyh','["سياحة وترفيه"]','["sights"]','ممشى بطول 2.2 كم يتميز بتوفير مسارات خاصة للمكفوفين وذوي الإعاقة يمكنهم التنزه وممارسة رياضة المشي فيها.','<div class="texte" > <p>ممشى بطول 2.2 كم يتميز بتوفير مسارات خاصة للمكفوفين وذوي الإعاقة يمكنهم التنزه وممارسة رياضة المشي فيها.</p> <p>يوفر الممشى بيئة مريحة لممارسة رياضة المشي على مدار اليوم، مع مسارات مخصصة تراعي ذوي الإعاقة والمكفوفين، ما يجعله وجهة شاملة تناسب مختلف أفراد المجتمع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300873-44001997.jpg?v=1636084138"]','https://cmsphoto.ww-cdn.com/resizeapi/9f1b2c94bbd013cd45e19c7f47d3764805d313c9/480/',21.554991,39.1612337,'Tahliya Walk Ar Rawdah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300873/tahlia-walkway-mmsh-althlyh',1,0,'ممشي تحليه tahlia walkway سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300808,'jeddah','فقيه اكواريوم','Fakieh Aquarium','fakieh-aquarium-fkyh-akoaryom','["سياحة وترفيه"]','["sights"]','معرض أحياء مائية يحتوي على العديد من أنواع أسماك البحر الأحمر، بالإضافة إلى عروض الدلافين وقاعة وناد رياضي مع مسبح.','<div class="texte" > <p>معرض أحياء مائية يحتوي على العديد من أنواع أسماك البحر الأحمر، بالإضافة إلى عروض الدلافين وقاعة وناد رياضي مع مسبح.</p> <p>يمنح المعرض الزوار فرصة التعرف عن قرب على الحياة البحرية في البحر الأحمر، فيما تضيف عروض الدلافين والمرافق الرياضية المصاحبة بعدًا ترفيهيًا يناسب الزيارات العائلية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300808-44002000.jpg?v=1636084258"]','https://cmsphoto.ww-cdn.com/resizeapi/f9ddc861653d946441f54c9501be5d258d50db68/480/',21.5722338,39.109632,'Next to Al Kurnaysh Rd Al Nawras','','','','https://www.saudi-guide.com/jeddah/i/59300808/fakieh-aquarium-fkyh-akoaryom',1,0,'فقيه اكواريوم fakieh aquarium سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300804,'jeddah','ممشى الأمير فيصل بن فهد','The Walk Of Prince Faisal Bin Fahad','walk-prince-faisal-bin-fahad-mmsh-alamyr-fysl-bn-fhd','["سياحة وترفيه"]','["sights"]','ممشى بمساحة كبيرة جداً مناسبة لممارسة رياضة المشي وركوب الدراجات الهوائية.','<div class="texte" > <p>ممشى بمساحة كبيرة جداً مناسبة للممارسة رياضة المشي وركوب الدراجات الهوائية.</p> <p>يستقطب الممشى محبي رياضة المشي وركوب الدراجات على مدار اليوم، بفضل مساحته الواسعة وأجوائه المفتوحة المناسبة للنشاط البدني والاسترخاء على حد سواء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300804-44002017.jpg?v=1636084454"]','https://cmsphoto.ww-cdn.com/resizeapi/8bd70da3342f5ca6a8f9e298de451ab33b5ac4a4/480/',21.5945067,39.1092972,'Prince Faisal Bin Fahd Street الشاطئ Jazan','','','','https://www.saudi-guide.com/jeddah/i/59300804/walk-prince-faisal-bin-fahad-mmsh-alamyr-fysl-bn-fhd',1,0,'ممشي امير فيصل بن فهد the walk of prince faisal bin fahad سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300766,'jeddah','كورنيش جدة الجديد','JW Corniche','jw-corniche-kornysh-gd-algdyd','["سياحة وترفيه"]','["sights"]','يعد مشروع الكورنيش الجديد في الواجهة البحرية بجدة من أهم عوامل الجذب للزوار والسياح.','<div class="texte" > <p>يعد مشروع الكورنيش الجديد في الواجهة البحرية بجدة من أهم عوامل الجذب للزوار والسياح حيث توجد به خدمات تم إضافتها لأول مرة على مستوى الواجهات البحرية بجدة ، الكورنيش مجهز بكل الخدمات المناسبة لجميع الفئات والأعمار من ألعاب وغيرها من وسائل الترفيه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300766-44002021.jpg?v=1636084587"]','https://cmsphoto.ww-cdn.com/resizeapi/43df96a42ffb0ddc382a12a9eb400a9e41d69142/480/',21.6041714,39.1073564,'SA Ash Shati Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300766/jw-corniche-kornysh-gd-algdyd',1,0,'كورنيش جده جديد jw corniche سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300723,'jeddah','الواجهة البحرية','Jeddah Water Front','jeddah-water-front-aloagh-albhry','["سياحة وترفيه"]','["sights"]','تتميّز الواجهة البحريّة بكونها وجهةً مفضلةً لنزهة العائلات حيث تحتوي على مساحات كبيرة ومفتوحة من المناطق المخصصة لألعاب الأطفال.','<div class="texte" > <p>تتميّز الواجهة البحريَّة بكونها وجهةً مفضلةً لنزهة العائلات حيث تحتوي على مساحات كبيرة ومفتوحة من المناطق المخصصة لألعاب الأطفال،&nbsp;ويمكن للبالغين الاشتراك في مجموعة&nbsp;من الرياضات المائية على الشاطئ أو استئجار الدراجات الهوائيَّة وركوبها على طول الكورنيش البالغ 4.2 كم، أو التنزه على&nbsp;الرصيف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300723-44002028.jpg?v=1636084917"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/59300723-44002028.jpg?v=1636084952',21.5927844,39.1056194,'الشاطئ، جدة جدة','','','','https://www.saudi-guide.com/jeddah/i/59300723/jeddah-water-front-aloagh-albhry',1,0,'واجهه بحريه jeddah water front سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300631,'jeddah','ممشى شارع فلسطين','Palestine Street Walk','palestine-street-walk-mmsh-sharaa-flstyn','["سياحة وترفيه"]','["sights"]','ممشى بطول 1200 متر ، يوجد على امتداده عدة مقاهي ومطاعم.','<div class="texte" > <p>ممشى بطول 1200 متر، يوجد على امتداده عدة مقاهي ومطاعم.</p> <p>يتيح الممشى للزوار الجمع بين رياضة المشي وتجربة المقاهي والمطاعم المنتشرة على امتداده، ما يجعله وجهة نابضة بالحياة خصوصًا في ساعات المساء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300631-44002032.jpg?v=1636085095"]','https://cmsphoto.ww-cdn.com/resizeapi/d34d539f6a0ef092611b441358139625f2c4872f/480/',21.5201597,39.1565916,'Falastin الحمراء Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300631/palestine-street-walk-mmsh-sharaa-flstyn',1,0,'ممشي شارع فلسطين palestine street walk سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300626,'jeddah','جزيرة الشراع','Sail Island','sail-island-gzyr-alshraaa','["سياحة وترفيه"]','["sights"]','جزيرة الشراع من أهم المنتزهات والأماكن السياحة في مدينة جدة تقع على الكورنيش البحري لمدينة جدة وتتميز بأنها مركز هام للترفيه يقصده الزوار من الداكل والخارور.','<div class="texte" > <p>جزيرة الشراع من أهم المنتزهات والأماكن السياحة في مدينة جدة تقع على الكورنيش البحري لمدينة جدة و تتميز بأنها مركز&nbsp;هام للترفيه يقصده الزوار من الداخل والخارج ، تضم صالة خاصة لفنون الرسم والتلوين تقام فيها انشطة تعليمية وترفيهية للأطفال بالاضافة الى المسابح والحديقة المائية .</p> <p>يقدم هذا المنتزه العديد من الفعاليات للأطفال و العائلة ويوفر المنتزه برك سباحة مناسبة للأطفال بالإضافة إلى الحديقة المائية و عدد من المطاعم، يبلغ سعر التذكرة 50 ريال للفرد شامل وجبات الطعام ، ويمكن للعائلات استئجار شاليهات خاصة لإقامة الحفلات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300626-44002035.jpg?v=1636085210"]','https://cmsphoto.ww-cdn.com/resizeapi/074b3bede0dcd15c58c67b623350fdb553f47644/480/',21.6252935,39.1044821,'طريق الكورنيش،، Ash Shati Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300626/sail-island-gzyr-alshraaa',1,0,'جزيره شراع sail island سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300558,'jeddah','المتحف المفتوح','','almthf-almftoh','["سياحة وترفيه"]','["sights"]','الفكرة من المتحف المفتوح هي أن التحف تكون معروضة في الهواء الطلق خارج المباني على مدار اليوم، يحتوي المتحف على 20 مجسم وعمل فني لأكبر الفنانين التشكيليين في العالم.','<div class="texte" > <p>الفكرة من المتحف المفتوح هي أن التحف تكون معروضة في الهواء الطلق خارج المباني على مدار 24 ساعة ، يحتوي المتحف على 20 مجسم وعمل فني لأكبر الفنانين التشكيليين في العالم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300558-44002036.jpg?v=1636085347"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/59300558-44002036.jpg?v=1636085382',21.5334615,39.1575469,'SA Al-Hamra''a Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300558/almthf-almftoh',1,0,'متحف مفتوح سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300532,'jeddah','اعمار سكوير','','aaamar-skoyr','["سياحة وترفيه"]','["sights"]','اعمار سكوار يتألف من 3 مباني مكتبية بتصاميم داخلية فاخرة وأنيقة، وإطلالة جميلة على الساحة ونافورة المياه التفاعلية والمتاجر الفاخرة.','<div class="texte" > <p>اعمار سكوير يتألف من ٣ مباني مكتبية بتصاميم داخلية فاخرة وأنيقة، وإطلالة جميلة&nbsp;على الساحة ونافورة المياه التفاعلية والمتاجر الفاخرة، إضافة إلى توفير عدة مطاعم ومقاهي .متنوعة ومميزة</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300532-44002040.jpg?v=1636085482"]','https://cmsphoto.ww-cdn.com/resizeapi/6f7f9540bb7639ca9685cd413278b1cd023b9582/480/',21.5092179,39.2034107,'Jeddah Al Fayha''a Jiddah','','','','https://www.saudi-guide.com/jeddah/i/59300532/aaamar-skoyr',1,0,'اعمار سكوير سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300529,'jeddah','كنز ابحر','KANZ OBHUR','kanz-obhur-knz-abhr','["سياحة وترفيه"]','["sights"]','مطعم فاخر للمأكولات البسيطة والنرجيلة في محيط مريح ومطلّ على المياه مع فناء كبير.','<div class="texte" > <p>مطعم فاخر للمأكولات البسيطة والنرجيلة في محيط مريح ومطلّ على المياه مع فناء كبير.</p> <p>يوفر المكان أجواءً هادئة تجمع بين المأكولات الخفيفة والنرجيلة في محيط مطل على المياه، مع فناء واسع يناسب التجمعات العائلية والجلسات المسائية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300529-44002054.jpg?v=1636085589"]','https://cmsphoto.ww-cdn.com/resizeapi/c2aa78f5c8dbe33e5736a6c1f4189bec9beeaec0/480/',21.7319403,39.1173972,'Alkurnaysh Road Abhur Al Junoobiyah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300529/kanz-obhur-knz-abhr',1,0,'كنز ابحر kanz obhur سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300525,'jeddah','مرسى الاحلام السياحي','Modo Cafe','modo-cafe-mrs-alahlam-alsyahy','["سياحة وترفيه"]','["sights"]','مرسى الأحلام السياحي هو مرسى قوارب يحتوي على مجموعة من المطاعم والمقاهي والتي تمنح الزوار إطلالة مميزة وفريدة على البحر الأحمر مما يعكن للزوار أخذ جولة بحرية في أحد.','<div class="texte" > <p>مرسى الاحلام السياحي&nbsp;هو مرسى قوارب يحتوي على مجموعة من المطاعم والمقاهي&nbsp;والتي تمنح الزوار إطلالة مميزة وفريدة&nbsp;على البحر الأحمر كما يمكن للزوار أخذ جولة بحرية في أحد القوارب أو الدبابات البحرية وقضاء وقت ممتع وسط البحر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300525-44002055.jpg?v=1636085678"]','https://cmsphoto.ww-cdn.com/resizeapi/a411d460ec72303d0507daa053dbfdb28cf843ae/480/',21.736824,39.122902,'Alkurnaysh Road Abhur Al Junoobiyah Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300525/modo-cafe-mrs-alahlam-alsyahy',1,0,'مرسي احلام سياحي modo cafe سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59300503,'jeddah','منتجع بلاجيو','Belajio Resort','belajio-resort-mntgaa-blagyo','["سياحة وترفيه"]','["sights"]','منتجع بلاجيو هو عبارة عن مجموعة من المطاعم والمقاهي الراقية والمزودة بجلسات مطلة على البحر.','<div class="texte" > <p>منتجع بلاجيو هو عباره عن مجموعة من المطاعم والمقاهي الراقية والمزودة بجلسات مطلة على البحر، يتميز المنتجع بأجواءه الهادئة&nbsp;وإطلالته المميزة على البحر كما يحتوي المنتجع على صالة افراح&nbsp;للمناسبات الخاصة ومنطقة صغيرة لألعاب الأطفال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59300503-44001898.jpg?v=1636081539"]','https://cmsphoto.ww-cdn.com/resizeapi/795c2aa335d528490fc83e2d86613133e7c24d1f/480/',21.627351,39.105127,'Corniche Rd Ash Shati Jeddah','','','','https://www.saudi-guide.com/jeddah/i/59300503/belajio-resort-mntgaa-blagyo',1,0,'منتجع بلاجيو belajio resort سياحه وترفيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59238266,'abha','متحف الراقدي','Al Raqdi Museum','al-raqdi-museum-mthf-alrakdy','["التراث والثقافة"]','["heritage"]','متحف الراقدي في أبها أسسه محمد بن علي الراقدي، ويضم أقساماً للنحاسيات والملابس والفضيات والمطبخ القديم والمجلس العسيري والجلسة التهامية والعمارة الحجرية.','<div class="texte" > <p>متحف الراقدي أحد متاحف منطقة عسير في أبها , أسسه محمد بن علي الراقدي، تكون المتحف من تسعة أقسام قسم النحاسيات وقسم الملابس والفضيات التراثية النسائية وقسم المطبخ القديم وحرف يدوية وأدوات زراعية وقسم المجلس العسيري القديم وقسم الجلسة التهامية وقسم القرية العسيرية وفن العمارة البناء بالحجر وقسم أعمال صاحب المتحف وقسم الجلسة الساحلية وقسم بيع القطع والمنتوجات التراثية والشعبية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59238266-44065969.jpg?v=1636569972"]','https://cmsphoto.ww-cdn.com/resizeapi/1935597c90eba78e26ca85f78807a7548d258c92/480/',18.2043752,42.5051285,'طريق الإمام عبدالرحمن بن فيصل بن تركي Thirah Abha','0504780817','','','https://www.saudi-guide.com/asir-region/i/59238266/al-raqdi-museum-mthf-alrakdy',1,0,'متحف راقدي al raqdi museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59238031,'abha','متحف عسير الإقليمي','Asir Regional Museum','asir-regional-museum-mthf-aasyr-alaklymy','["التراث والثقافة"]','["heritage"]','متحف عسير الإقليمي في وسط أبها قرب قصر شدا، يضم قاعات لعصور ما قبل التاريخ وما قبل الإسلام والعصور الإسلامية والدولة السعودية والتراث الشعبي لمنطقة عسير.','<div class="texte" > <p>متحف عسير الإقليمي من أكبر متاحف منطقة عسير، ويقع في وسط مدينة أبها على شارع الملك خالد بالقرب من قصر شدا التاريخي، على مساحة تتجاوز 7 آلاف متر مربع.</p> <p>يضم المتحف ثماني قاعات متخصصة تأخذ الزائر في رحلة عبر تاريخ المنطقة، تشمل عصور ما قبل التاريخ، وفترة ما قبل الإسلام، والعصور الإسلامية، وتاريخ الدولة السعودية بأدوارها الثلاثة، والتراث الشعبي المحلي، إلى جانب قاعة للعروض المؤقتة، ويحتوي على مجموعة من القطع الأثرية النادرة التي توثق الحياة في عسير عبر العصور.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59238031-44065978.jpg?v=1636570074"]','https://cmsphoto.ww-cdn.com/resizeapi/4da61f37e3c00010252dfa42133d23c6e0bcf0f9/480/',18.2164239,42.499212,'King Khalid Bin Abdul Aziz St Town Center Abha','','','','https://www.saudi-guide.com/abha/i/59238031/asir-regional-museum-mthf-aasyr-alaklymy',1,0,'متحف عسير اقليمي asir regional museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237983,'abha','قصر شدا التاريخي','Shada Palace','shada-palace-ksr-shda-altarykhy','["التراث والثقافة"]','["heritage"]','قصر شدا في وسط أبها بُني عام 1348هـ بأمر الملك عبدالعزيز من أربعة أدوار بالحجارة والجص، وكان مقراً لإمارة عسير ثم تحول عام 1408هـ إلى متحف للموروث الشعبي.','<div class="texte" > <p>قصر شدا أو «القصر الأبيض» من أهم المعالم التاريخية في وسط مدينة أبها، بُني عام 1348هـ / 1929م بتوجيه من الملك عبدالعزيز، ويتكون من أربعة أدوار شُيدت بالحجارة وكُسيت جدرانها بطبقة من الجص من الداخل والخارج، واستُخدمت الأخشاب في أبوابه ونوافذه وأسقفه.</p> <p>كان القصر مقراً لإمارة منطقة عسير فترة من الزمن، ثم رُمم عام 1407هـ وافتُتح عام 1408هـ / 1988م متحفاً للموروثات الشعبية، ويقع على مقربة من سوق الثلاثاء الشعبي ومتحف عسير الإقليمي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237983-44065980.jpg?v=1636570105"]','https://cmsphoto.ww-cdn.com/resizeapi/ff3b41b34e998036e226764176ae413d638f517d/480/',18.216653,42.5009272,'King Khalid Bin Abdul Aziz St Town Center Abha','','','','https://www.saudi-guide.com/abha/i/59237983/shada-palace-ksr-shda-altarykhy',1,0,'قصر شدا تاريخي shada palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237898,'abha','متحف الجحل','Al Jahl Museum','al-jahl-museum-mthf-alghl','["التراث والثقافة"]','["heritage"]','متحف الجحل في أبها يضم صوراً للأسرة المالكة وعملات قديمة وحلياً وفضيات وأدوات حرب وهواتف قديمة وملابس تراثية وأدوات زراعة ومطبخ ونحاسيات ومصنوعات جلدية.','<div class="texte" > <p>يحتوي متحف الجحل على بعض الصور الخاصة بالأسرة السعـوديـة المـالكـة، والعملات القديمة والحلي والفضيات بالإضافة إلى أدوات الحرب بأنواعها والهواتف القديمة والملابس التراثية، أدوات الزراعة والمطبخ، المكاييل والموازين كذلك، وبعض&nbsp;النحاسيات والمصنوعات الجلدية المختلفة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237898-44065982.jpg?v=1636570136"]','https://cmsphoto.ww-cdn.com/resizeapi/df0dff959884b6df98b16910a226af40f2e93023/480/',18.3546073,42.3287887,'طريق قرية مزمة Abha Aseer Province','0501736336','','','https://www.saudi-guide.com/asir-region/i/59237898/al-jahl-museum-mthf-alghl',1,0,'متحف جحل al jahl museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237896,'abha','قرية طبب التراثية','Tabab Heritage Village','tabab-heritage-village-kry-tbb-altrathy','["التراث والثقافة"]','["heritage"]','قرية طبب التراثية شمال غرب أبها كانت عاصمة عسير في عهد الدولة السعودية الأولى، وتضم مسجد طبب التاريخي المبني عام 1221هـ وقصور أمراء آل أبو نقطة المتحمي.','<div class="texte" > <p>طبب هي قرية سعودية في منطقة عسير، تقع في الشمال الغربي من مدينة أبها على بعد 25 كم. بنيت في عهد الدولة السعودية الأولى وكانت العاصمة السياسية والثقافية والاقتصادية الأولى لمنطقة عسير أثناء حكم الدولة السعودية الأولى للفترة (1215 - 1234 هـ) خلال إمارة آل أبو نقطة المتحمي، تضم عدة مواقع تاريخية وتراثية هامة، أبرزها مسجد طبب والذي أسسه الأمير عبد الوهاب بن عامر أبو نقطة المتحمي عام 1221 هـ في عهد الإمام سعود بن عبد العزيز، كما تشمل قرية طبب قصور أمراء آل أبو نقطة المتحمي. وهي في الوقت الحالي مقر أسرتهم ومشيخة قبائل ربيعة ورفيدة وبني ثوعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237896-44065988.jpg?v=1636570176"]','https://cmsphoto.ww-cdn.com/resizeapi/e5fd4482b7f32fd6f82931303885b68cbd62f623/480/',18.3673198,42.3701232,'Tabab Abha Aseer Province','','','','https://www.saudi-guide.com/abha/i/59237896/tabab-heritage-village-kry-tbb-altrathy',1,0,'قريه طبب تراثيه tabab heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237887,'abha','متحف الأجيال التراثي','Al Ajyal Heritage Museum','al-ajyal-heritage-museum-mthf-alagyal-altrathy','["التراث والثقافة"]','["heritage"]','متحف الأجيال التراثي في أبها يضم مخطوطات ووثائق وعملات وحلياً وفضيات وأسلحة وملابس تراثية وأدوات زراعة ومطبخ ومكاييل وموازين ونحاسيات ومصنوعات جلدية.','<div class="texte" > <p>يتكون متحف الأجيال التراثي من مبنى مستقل به قاعتين رئيسيتين الأولى مساحتها 108 متر مربع والثانية مساحتها 48 متر مربع،&nbsp;ويتنوع أسلوب العرض بالمتحف باستخدام خزائن العرض الزجاجية والاستاندات بأسلوب جيد، ويحتوي المتحف على المخطوطات القديمة والوثائق والعملات والحلي والفضيات إضافة إلى الأسلحة وأدوات الحرب بأنواعها والهواتف القديمة والملابس التراثية وأدوات الزراعة والمطبخ والمكاييل والموازين والخوصيات والنحاسيات والمصنوعات الجلدية المختلفة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237887-44065991.jpg?v=1636570203"]','https://cmsphoto.ww-cdn.com/resizeapi/94c526218b7e9cfda45d38816ff5761a357ec967/480/',18.3144932,42.5404888,'شارع بني مالك Abha Abha','0545794554','','','https://www.saudi-guide.com/asir-region/i/59237887/al-ajyal-heritage-museum-mthf-alagyal-altrathy',1,0,'متحف اجيال تراثي al ajyal heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237744,'abha','مطل العقبة','Al Aqaba Viewpoint','al-aqaba-viewpoint-mtl-alaakb','["أماكن سياحية"]','["sights"]','مطل العقبة في أبها من أجمل المطلات في المدينة، يكشف العقبة والجبال والأودية المجاورة، ويزداد جماله في أوقات الأمطار والضباب، ومقصد لهواة التصوير والتأمل.','<div class="texte" > <p>يطل مطل العقبة على العقبة والمخواة والجبال والأودية المجاورة، ويعد من أجمل الأماكن في مدينة أبها، خاصة في أوقات الأمطار حين يكسو الضباب القمم ويمنح المكان مشهداً ساحراً، ما يجعله مقصداً لهواة التصوير ومحبي الطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237744-44064577.jpg?v=1636561422"]','https://cmsphoto.ww-cdn.com/resizeapi/58feb2bb58bb7df1222ed007ae5fb57a0e8098ba/480/',18.1823779,42.507223,'Abha Abha Aseer Province','','','','https://www.saudi-guide.com/abha/i/59237744/al-aqaba-viewpoint-mtl-alaakb',1,0,'مطل عقبه al aqaba viewpoint اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237701,'abha','السودة','Al Soudah','al-soudah-alsod','["أماكن سياحية"]','["sights"]','السودة وجهة جبلية على بعد نحو 20 كم من أبها وعلى ارتفاع يقارب 3000 متر، تكسوها غابات العرعر وتطل على سهول تهامة، وترتبط بقرية رجال ألمع بالتلفريك.','<div class="texte" > <p>السودة وجهة سياحية جبلية في منطقة عسير تبعد عن مدينة أبها نحو 20 كيلومتراً، وتقع على ارتفاع يقارب 3000 متر عن سطح البحر، وتكسو جبالها أشجار العرعر الكثيفة مكونة غابات طبيعية خلابة.</p> <p>تطل السودة على إقليم تهامة، ولذلك ثُبتت مناظير مكبرة في بعض أجزائها كمطلات لمشاهدة الأغوار والأودية والقرى المجاورة في سهول تهامة، وتتميز بأجوائها المعتدلة صيفاً والباردة شتاءً قياساً بالمناطق المحيطة، وتضم قرية السودة السياحية بخدماتها المتنوعة، وترتبط بقرية رجال ألمع في تهامة عبر العربات المعلقة «التلفريك».</p> <p>وعلى مقربة من السودة تقع قرى باحة ربيعة التي تضم منتزه المحتطبة المعروف بشلالاته الطبيعية وبحيراته التي تكونت من جريان المياه وهطول الأمطار، كما يقع منتزه الملك عبدالعزيز شمال السودة بمناظره الطبيعية وخدماته المتنوعة للزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237701-44064580.jpg?v=1636561456"]','https://cmsphoto.ww-cdn.com/resizeapi/935b5c10238ea95dde38d7824ec24a756b787254/480/',18.2350528,42.4288123,'Al Azizah Al Azizah Abha','','','','https://www.saudi-guide.com/abha/i/59237701/al-soudah-alsod',1,0,'سوده al soudah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237698,'abha','قرية السودة السياحية','Al Soudah Tourist Village','al-soudah-tourist-village-kry-alsod-alsyahy','["أماكن سياحية"]','["sights"]','قرية السودة السياحية قرب أبها تضم منتزهات أبرزها منتزه عسير السياحي ومنتزه الملك عبدالعزيز، وفنادق بإطلالات جبلية، وترتبط بقرية رجال ألمع بالتلفريك.','<div class="texte" > <p>تعتبر قرية السودة ضمن مدينة أبها التابعة لمنطقة عسير،&nbsp;تضم القرية&nbsp;<span>منت</span><span>زهات عدة أبرزها</span>&nbsp;منتزه عسير السياحي&nbsp;ومتنزه الملك عبدالعزيز آل سعود،&nbsp;كما يوجد بها بعض الفنادق التي تقدم إطلالات&nbsp;جبلية رائعة&nbsp;كما تحتوي القرية على مرافق متعددة توفر مختلف الخدمات التي يحتاج إليها الزوار، والتي تشرف عليها أمانة منطقة عسير.</p> <p><span>ترتبط&nbsp; القرية من خلال تلفريك بقرية رجال ألمع، وعلى مقربة منها هناك عدد من القرى منها قرى باحة ربيعة.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237698-44065885.jpg?v=1636569102"]','https://cmsphoto.ww-cdn.com/resizeapi/73e662122ff1f0167d6549e8c6a4c00e564e430b/480/',18.2610717,42.3772023,'طريق السودة، Al Soudah Abha','','','','https://www.saudi-guide.com/abha/i/59237698/al-soudah-tourist-village-kry-alsod-alsyahy',1,0,'قريه سوده سياحيه al soudah tourist village اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237693,'abha','المدينة العالية','The High City','the-high-city-almdyn-alaaaly','["أماكن سياحية"]','["sights"]','المدينة العالية في أبها تطل على تهامة ومدينة أبها، وتضم منتجعات وفنادق وفللاً سكنية ومقاهي ومطاعم متنوعة، وتعد وجهة للإقامة والاستمتاع بالإطلالات الجبلية.','<div class="texte" > <p>تتميز المدينة العالية بإطلالتها الجميلة على&nbsp;تهامة من الجهة الجنوبية الشرقية وعلى مدينة أبها من الجهة الشمالية الغربية وتبلغ مساحة المدينة حوالي 26 ألف متر مربع وتضم العديد من المنتجعات والفنادق والفلل السكنية التي تلبي احتياجات الزوار كما تضم العديد من المقاهي والمطاعم الراقية والمتنوعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237693-44064595.jpg?v=1636561504"]','https://cmsphoto.ww-cdn.com/resizeapi/ad6676c09510a578250c79333048cbe8eb38c27f/480/',18.2004275,42.4960277,'4820 8993 King Abdul Aziz Rd','','','','https://www.saudi-guide.com/asir-region/i/59237693/the-high-city-almdyn-alaaaly',1,0,'مدينه عاليه the high city اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237692,'abha','منتزه أبو خيال','Abu Khayal Park','abu-khayal-park-mntzh-abo-khyal','["أماكن سياحية"]','["sights"]','منتزه أبو خيال متنزه على تلة يطل على أبها بإطلالة بانورامية، يضم مساحات خضراء ومدرجات وملاعب للأطفال، وسُمي بذلك لانتشار الضباب فيه شتاءً كالخيالات.','<div class="texte" > <p>متنزه هادئ في أعلى تلّة يضمّ ملعبًا للأطفال ومقاعد وإطلالات واسعة على المدينة، تطل الحديقة على مدينة ابها من أعلى بإطلالة بانورامية، وتضم مساحات خضراء شاسعة وأشجار متنوعة،&nbsp;أفضل وقت لزيارتها في فصل الشتاء لمشاهدة الضباب يتخلل الحديقة، يوفر المنتزه العديد من مقاعد الجلوس التي يمكنك الاستعانة بها من أجل الاستراحة والجلوس للاستمتاع،&nbsp;و تحتوي الحديقة على عدد من المدرجات الخضراء.</p> <p>سميت حديقة أبو خيال بهذا الاسم لأنه في فصل الشتاء ينتشر الضباب في الحديقة بشكل كبير حيث يراها من بها وكأنها خيالات في مناظر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237692-44064601.jpg?v=1636561532"]','https://cmsphoto.ww-cdn.com/resizeapi/dc72f2d3273696fad4944eb2b22df509e2eafdfb/480/',18.1998646,42.499623,'Al Shifa Abha Abha','','','','https://www.saudi-guide.com/asir-region/i/59237692/abu-khayal-park-mntzh-abo-khyal',1,0,'منتزه ابو خيال abu khayal park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237621,'abha','ممشى الضباب','Al Dabab Walkway','al-dabab-walkway-mmsha-aldbab','["أماكن سياحية"]','["sights"]','ممشى الضباب في أبها ممشى معلق يمتد نحو سبعة كيلومترات على قمم الجبال مطلاً على عقبة ضلع وتهامة، ويمنح زواره شعور التجول بين السحاب وسط الشلالات والجلسات.','<div class="texte" > <p>يعد ممشى الضباب من أجمل الوجهات السياحية في أبها، إذ يمنح زواره شعوراً وكأنهم يتجولون بين السحاب. يقع في حي الضباب على قمم الجبال مطلاً على عقبة ضلع وسهول تهامة، ويمتد ممشاه المعلق لمسافة تقارب سبعة كيلومترات بعرض يصل إلى 14 متراً.</p> <p>يضم الممشى جلسات مظللة ومساحات خضراء وألعاباً للأطفال وشلالات صناعية تضفي على المكان أجواء ساحرة في المساء، إلى جانب المطاعم ودورات المياه والمصليات ومواقف السيارات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237621-44064615.jpg?v=1636561588"]','https://cmsphoto.ww-cdn.com/resizeapi/722a844d80ef765d3601a0f5152d7d6be59016fc/480/',18.1970296,42.5074584,'ِAlsahab Walk Al Dabab Abha','','','','https://www.saudi-guide.com/asir-region/i/59237621/al-dabab-walkway-mmsha-aldbab',1,0,'ممشي ضباب al dabab walkway اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237597,'abha','منتزهات بحيرة سد أبها','Abha Dam Lake Parks','abha-dam-lake-parks-mntzhat-bhyr-sd-abha','["أماكن سياحية"]','["sights"]','منتزهات بحيرة سد أبها غرب المدينة، تحيط بالبحيرة التي كونها سد أبها المفتتح عام 1394هـ، وتضم مساحات خضراء واسعة للتنزه والجلسات العائلية وسط الطبيعة.','<div class="texte" > <p>تقع منتزهات بحيرة سد أبها غرب المدينة على ضفاف البحيرة التي كوّنها سد أبها، وتضم مساحات خضراء واسعة تناسب النزهات والجلسات العائلية وسط الطبيعة.</p> <p>أُعيد بناء سد أبها في عهد الملك فيصل وافتُتح عام 1394هـ / 1974م لحفظ مياه السيول النازلة من الجبال، ويبلغ طوله نحو 350 متراً وارتفاعه 30 متراً، وتتسع بحيرته لأكثر من مليوني متر مكعب من المياه، ما جعلها من أبرز المعالم الطبيعية في أبها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237597-44065685.jpg?v=1636567625"]','https://cmsphoto.ww-cdn.com/resizeapi/8981b9df6a3670b11f50a9df621a2f4cebd91b7a/480/',18.2116134,42.4867258,'Abha Dam Abha Al Jadidah Abha','','','','https://www.saudi-guide.com/abha/i/59237597/abha-dam-lake-parks-mntzhat-bhyr-sd-abha',1,0,'منتزهات بحيره سد ابها abha dam lake parks اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237593,'abha','حديقة ملهمتي','Mulhimati Art Park','mulhimati-art-park-hdyk-mlhmty','["أماكن سياحية"]','["sights"]','حديقة ملهمتي في أبها أنشأها شباب لترويج الإبداع الفني السعودي وإيصال رسائل هادفة كالمحافظة على البيئة وإعادة التدوير، وتضم أعمالاً فنية ومناطق ألعاب.','<div class="texte" > <p>تم إنشاء حديقة ملهمتي من قبل مجموعة من الشباب بهدف الترويج للأعمال الفنية والقدرات الإبداعية لدى الشباب السعودي كما اهتمت الحديقة بإيصال الرسائل الهادفة عن طريق الفنون مثل أهمية المحافظة على البيئة وإعادة التدوير، تحتوي الحديقة على مناطق للألعاب ومنذ افتتاحها وهي تعد عامل جذب كبير للزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237593-44087355.jpg?v=1636717756"]','https://cmsphoto.ww-cdn.com/resizeapi/4f8629521bcd69c580fb7355cb5554346424b1fb/480/',18.2132036,42.4902356,'7667 King Abdul Aziz Rd As Sadd','','','','https://www.saudi-guide.com/abha/i/59237593/mulhimati-art-park-hdyk-mlhmty',1,0,'حديقه ملهمتي mulhimati art park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237592,'abha','الجبل الأخضر','Green Mountain','green-mountain-algbl-alakhdr','["أماكن سياحية"]','["sights"]','الجبل الأخضر من أبرز معالم أبها، سُمي بذلك لأضوائه الخضراء، ويطل على المدينة كلها وسهول تهامة، ويمكن الوصول إلى قمته بالتلفريك وسط مرافق وخدمات للزوار.','<div class="texte" > <p><span>سمي&nbsp;الجبل الأخضر بهذا الاسم بسبب الأضواء الخضراء التي تزينه،&nbsp;</span>يعتبر الجبل الأخضر واحد&nbsp;من أهم وأبرز الوجهات السياحيّة في مدينة أبها؛ وذلك بسبب ارتفاعه وإطلالته الرائعة التي تكشف كل&nbsp;معالم أبها&nbsp;بالإضافة إلى إمكانية مشاهدة سهول&nbsp;تهامة من أعلى الجبل،&nbsp;يمكن الوصول إلى قمة الجبل الأخضر عن طريق التلفريك، وقد تم إنشاء&nbsp; العديد من المرافق التي توفر جميع الخدمات التي يحتاجها الزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237592-44065707.jpg?v=1636567672"]','https://cmsphoto.ww-cdn.com/resizeapi/4dbe3a9499594c48baf42ef8b14b5cd5f75aef62/480/',18.2046855,42.5062038,'Green Mountain Thirah Abha','','','','https://www.saudi-guide.com/abha/i/59237592/green-mountain-algbl-alakhdr',1,0,'جبل اخضر green mountain اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237558,'abha','قرية المفتاحة','Al Muftaha Village','al-muftaha-village-kry-almftah','["التراث والثقافة"]','["heritage"]','قرية المفتاحة في أبها قرية تراثية مبنية على طراز عمارة عسير بمبانٍ متلاصقة وحوائط سميكة وفتحات صغيرة ورقف تحمي الجدران الطينية، وتعد مركزاً للفنون.','<div class="texte" > <p>قرية المفتاحة&nbsp;هي واحدة من القرى السياحية بالواقعة في&nbsp;مدينة أبها&nbsp;جنوب&nbsp;المملكة العربية السعودية. القرية مقامة على طرز معماري مستمد من تراث وحضارة&nbsp;منطقة عسير. وهي عبارة عن مجموعة من المباني المتلاصقة على امتداد الممرات الداخلية والخارجية والتي تم بناؤها بالأساليب التقليدية للبناء في مدينة أبها حيث الفتحات الصغيرة والحوائط السميكة واستخدام (الرقف) لحماية الحوائط الطينية من الأمطار وتوفير الظلال على واجهة المبنى.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237558-63482365.jpg?v=1752360418", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237558-63482366.jpg?v=1752360429", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237558-44065786.jpg?v=1636568477"]','https://cmsphoto.ww-cdn.com/resizeapi/56c9fbb840f11fa3a3a31dd9e533d9282966d081/480/',18.2127325,42.4933704,'Al Muftaha Abha Abha','','https://www.visitsaudi.com/ar/destinations/aseer/attractions/almuftaha-village','','https://www.saudi-guide.com/asir-region/i/59237558/al-muftaha-village-kry-almftah',1,0,'قريه مفتاحه al muftaha village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237504,'abha','شارع الفن','Art Street','art-street-sharaa-alfn','["أماكن سياحية"]','["sights"]','شارع الفن في قلب أبها يمتد نحو 200 متر بين صفين من أشجار الجاكرندا، يضم صالات عرض ومسرحاً ومطاعم ومقاهي وأعمالاً فنية لفناني المنطقة ومظلات ملونة.','<div class="texte" > <p>شارع الفن، يقع في قلب أبها بمنطقة عسير جنوب غرب المملكة العربية السعودية، ويمتد حوالي 200 متر، ويعتبر الشارع من أهم المزارات السياحية في المنطقة، وتعتبر نقطة لقاء لعشاق الفن من الفنانين والمهتمين من جميع انحاء المملكة العربية السعودية، يتضمن الشارع 10 صالات عرض ومسرح لإقامة الحفلات والعديد من المطاعم والمقاهي المحلية والعالمية، وعلى مد النظر الشارع مزيين بأعمال فنية متنوعة بأيدي فناني المنطقة، حيث تنتشر المظلات الملونة وكأنه مهرجان كرنفالي متألق بين صفين من أشجار الجاكرندا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237504-44065791.jpg?v=1636568511"]','https://cmsphoto.ww-cdn.com/resizeapi/6869bce53bdec69e8ddd43bd27e7442f9516c3b4/480/',18.2147279,42.4936054,'King Khalid Rd Al Muftaha Abha','','','','https://www.saudi-guide.com/asir-region/i/59237504/art-street-sharaa-alfn',1,0,'شارع فن art street اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237500,'abha','منتزه الحبلة السياحي','Al Habala Tourist Park','al-habala-tourist-park-mntzh-alhbl-alsyahy','["أماكن سياحية"]','["sights"]','منتزه الحبلة في عسير حول القرية المعلقة على جرف صخري شاهق كان الوصول إليها بالحبال، ويضم تلفريكاً ووحدات سكنية ومطعماً يطل على القرية القديمة.','<div class="texte" > <p>تقع قرية الحبلة في منطقة عسير على بعد نحو 57 كيلومتراً من مدينة أبها، وهي قرية معلقة بُنيت بيوتها الحجرية على حافة جرف صخري شاهق في جبال السروات، وسُميت بالحبلة لأن الحبال كانت الوسيلة الوحيدة للوصول إليها ونقل المؤن إلى سكانها قديماً.</p> </div>  <div class="texte" > <p>ما أن علم الملك فيصل بن عبدالعزيز آل سعود بمعاناة سكان الحبلة حتى أمر ببناء قرية حديثة لهم عُرفت بقرية الملك فيصل الخيرية، وقد أُقيمت في مكان منبسط وانتقل إليها كافة سكان الحبلة، وأصبح المكان القديم مكاناً سياحياً حيث نجحت الشركة السياحية بتحويله إلى منتجع سياحي عن طريق إقامة عدد من المشروعات السياحية مثل: إنشاء بعض الوحدات السكنية الحديثة المزودة بالخدمات ووسائل الترفيه كالسباحة والألعاب الأخرى، وفي أعلى المطل الذي يشرف على القرية القديمة أُقيم مطعم يقدم الوجبات المتعددة للزوار، وأُقيمت أيضاً العربات المتحركة "التلفريك"، كما ساهمت وسائل المواصلات الحديثة في اعتناء بعض المواطنين بمزارعهم القديمة حيث&nbsp;خُصصت لاستقبال الزوار وتناول المشروبات وأصناف المأكولات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237500-44065795.jpg?v=1636568540"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/59237500-44065795.jpg?v=1636568584',18.0383171,42.871581,'Al Habala Ahad Rafidah Aseer Province','','','','https://www.saudi-guide.com/abha/i/59237500/al-habala-tourist-park-mntzh-alhbl-alsyahy',1,0,'منتزه حبله سياحي al habala tourist park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237471,'abha','مطعم حصن أبها التراثي','Hisn Abha Heritage Restaurant','hisn-abha-heritage-restaurant-mtaam-hsn-abha-altrathy','["أماكن سياحية"]','["sights"]','مطعم حصن أبها التراثي في مدينة أبها بتصميم شعبي مستوحى من عمارة عسير، يقدم الأكلات الشعبية الجنوبية في أجواء تراثية تناسب العائلات والزوار.','<div class="texte" > <p>مطعم حصن أبها التراثي مطعم في مدينة أبها بتصميم شعبي أنيق يستحضر الطابع التراثي لمنطقة عسير، ويقدم الأكلات الشعبية الجنوبية في أجواء تراثية تناسب العائلات والزوار الراغبين في تذوق المطبخ المحلي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237471-44065809.jpg?v=1636568616"]','https://cmsphoto.ww-cdn.com/resizeapi/9721116e7251e301408b12147f50e7d08323daa5/480/',18.219177,42.4984531,'Al Qabil Abha Abha','','','','https://www.saudi-guide.com/abha/i/59237471/hisn-abha-heritage-restaurant-mtaam-hsn-abha-altrathy',1,0,'مطعم حصن ابها تراثي hisn abha heritage restaurant اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237447,'abha','سد وادي عشران','Wadi Ashran Dam','wadi-ashran-dam-sd-oady-aashran','["أماكن سياحية"]','["sights"]','سد وادي عشران قرب أبها سد خرساني أُنشئ عام 1985 لتعويض مياه الآبار الجوفية وتوفير مياه الشرب والاستفادة من موارد المياه في وادي قرى آل عاصم.','<div class="texte" > <p>أنشئ سد عشران سنة 1985 حاجزه خرساني&nbsp;النوع من أجل استعاضة مياه الآبار الجوفية وتوفير مياه الشرب لسكان المنطقة والاستفادة من موارد المياه في وادي قرى آل عاصم</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237447-44065813.jpg?v=1636568746"]','https://cmsphoto.ww-cdn.com/resizeapi/19e98ed3cd9a25a36a7717369b11a74ec0a4a860/480/',18.2681706,42.4353121,'سد وادي عشران أبهــــا منطقة عسير','','','','https://www.saudi-guide.com/abha/i/59237447/wadi-ashran-dam-sd-oady-aashran',1,0,'سد وادي عشران wadi ashran dam اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237404,'abha','حديقة الشلال','Waterfall Park','waterfall-park-hdyk-alshlal','["أماكن سياحية"]','["sights"]','حديقة الشلال في أبها حديقة عائلية تضم مسطحات خضراء وأشجاراً كبيرة وجلسات مظللة ومناطق لألعاب الأطفال وعربات للطعام، وتناسب النزهات العائلية.','<div class="texte" > <p>حديقة عائلية تحتوي على مسطحات خضراء وأشجار كبيرة في غاية الجمال&nbsp;كما تحتوي الحديقة على جلسات مظللة ومناطق&nbsp;لألعاب الأطفال بالإضافة إلى عربات الطعام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237404-44065828.jpg?v=1636568781"]','https://cmsphoto.ww-cdn.com/resizeapi/37e386bbd487384b163e7953ee6d906d0b2c5fb1/480/',18.2315793,42.5005299,'9424 King Faisal Rd Al Wardatain','','','','https://www.saudi-guide.com/abha/i/59237404/waterfall-park-hdyk-alshlal',1,0,'حديقه شلال waterfall park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237360,'abha','سد ضبوعي','Dabouei Dam','dabouei-dam-sd-dboaay','["أماكن سياحية"]','["sights"]','سد ضبوعي قرب مركز طبب شمال غرب أبها، كوّن بحيرة جميلة أصبحت متنفساً للأهالي والزوار للتنزه على ضفافها والاستمتاع بروعة المنظر وبرودة الجو.','<div class="texte" > <p>تعتبر البحيرة التي صنعها سد ضبوعي الواقع قرب مركز طبب متنفسا للمواطنين ولأهالي المنطقة للتنزه على ضفافه ومنطقة سياحية تجذب الجميع والذين يزورون بحيرة السد أسبوعيا، حيث يتميز هذا السد بجمال وروعة المنظر وبرودة الجو.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237360-44065836.jpg?v=1636568819"]','https://cmsphoto.ww-cdn.com/resizeapi/87e8786744eef18013816af95ddad6a49f4ffe87/480/',18.3674642,42.3617427,'SA أبهــــا منطقة عسير','','','','https://www.saudi-guide.com/abha/i/59237360/dabouei-dam-sd-dboaay',1,0,'سد ضبوعي dabouei dam اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237337,'abha','منتزه مطار أبها','Abha Airport Park','abha-airport-park-mntzh-mtar-abha','["أماكن سياحية"]','["sights"]','منتزه مطار أبها من أكبر حدائق عسير، يضم مسطحات خضراء واسعة وألعاب أطفال ونافورة ومسارات مشي ومجرى مائي تعبره جسور خشبية، ويناسب النزهات العائلية.','<div class="texte" > <p>تُعد حديقة مطار أبها من أكبر حدائق&nbsp;منطقة عسير فهي تمتد على مساحة تزيد عن 125.000 متر مربع، تشتمل الحديقة على مجموعة من المسطحات الخضراء الواسعة ومناطق ألعاب للأطفال ونافورة تتوسط الحديقة بالإضافة إلى عدة&nbsp;مسارات للمشي ومقاعد للجلوس، أبرز ما يميز الحديقة هو المجرى المائي الذي يصل طوله إلى 260 متر وتتوزع عليه ثلاثة جسور خشبية بتصاميم رائعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237337-44065842.jpg?v=1636568849"]','https://cmsphoto.ww-cdn.com/resizeapi/dd4d9ab8463ce4351f7dd47d35b0cde873f4f6f7/480/',18.2405604,42.6453852,'Abha Abha Aseer Province','','','','https://www.saudi-guide.com/asir-region/i/59237337/abha-airport-park-mntzh-mtar-abha',1,0,'منتزه مطار ابها abha airport park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59237246,'abha','حديقة وملاهي السلام','Al Salam Park','al-salam-park-hdyk-omlahy-alslam','["أماكن سياحية"]','["sights"]','حديقة وملاهي السلام في أبها مساحة خضراء عائلية تضم أحواض زهور ومسجداً وألعاباً تقليدية وكهربائية للأطفال، وتعد وجهة مناسبة للنزهات العائلية.','<div class="texte" > <p>حديقة وملاهي السلام مساحة خضراء حضرية في حي النسيم بمدينة أبها، تشمل أحواض زهور ومسجداً وألعاباً تقليدية للأطفال بالإضافة إلى الألعاب الكهربائية، وتعد وجهة مناسبة للعائلات لقضاء أوقات ممتعة في الهواء الطلق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59237246-44065847.jpg?v=1636568885"]','https://cmsphoto.ww-cdn.com/resizeapi/de0e1c5edb8e7d4c6de150042a6aefca3872c9b4/480/',18.2118904,42.5432384,'SA النسيم أبها','','','','https://www.saudi-guide.com/asir-region/i/59237246/al-salam-park-hdyk-omlahy-alslam',1,0,'حديقه وملاهي سلام al salam park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59233342,'alula','طنطورة','Al Ula Tantura','al-ula-tantura-tntor','["أماكن سياحية"]','["sights"]','اسم مستوحى من مزولة شمسية استخدمها أهالي العلا القديمة لمعرفة دخول موسم الزراعة وتغير الفصول، تضم اليوم مهرجانات ترفيهية وثقافية ورياضية متنوعة.','<div class="texte" > <p>اسم&nbsp;"طنطورة" مستوحى من مزولة تقع في بلدة العلا القديمة، والتي كانت تستخدم من قبل السكان المحليين كعلامة لتغيير الفصول حيث كان أهالي المنطقة يعتمدون عليها في&nbsp;<span>في معرفة وقت دخول موسم الزراعة وتغير فصول السنة.</span></p> <p><font color="#202122" face="arial"><span>تضم طنطورة عدة مهرجانات&nbsp;</span></font><span>ترفيهية وثقافية ورياضية وتوفر زيارات ميدانية للمواقع الأثرية في المنطقة.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59233342-44049436.jpg?v=1636483055"]','https://cmsphoto.ww-cdn.com/resizeapi/614b3f6e188dc5b7d764be7f0bc9324bfc3c35e2/480/',26.6245252,37.9162934,'AlUla AlUla Al Madinah Province','','','','https://www.saudi-guide.com/alula/i/59233342/al-ula-tantura-tntor',1,0,'طنطوره al ula tantura اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59233341,'alula','المنتزه الشتوي','Winter park','winter-park','["أماكن سياحية"]','["sights"]','منتزه رائع يوفر كل الخدمات التي يحتاجها الزوار من كدورات مياه وعربات طعام وقهوة، يعتبر المركز الحيوي لمدينة العلا والوجهة المفضلة لسكانها خاصة في أوقات الشتاء.','<div class="texte" > <p>منتزه رائع ومنظم يوفر كل الخدمات التي يحتاجها الزوار كدورات المياه وعربات الطعام والقهوة، يعتبر المنتزه المركز الحيوي لمدينة العلا كما انه نقطة الانطلاق للعديد من الفعاليات المشوقة والمناسبة، كما يعد المنتزه الوجهة المفضلة لسكان العلا خاصة في أوقات الشتاء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59233341-44035120.jpg?v=1636386198"]','https://cmsphoto.ww-cdn.com/resizeapi/dd5a840638c1c6b085bb031c8308a60e150aa33d/480/',26.663606,37.9034288,'AlUla AlUla Al Madinah Province','','','','https://www.saudi-guide.com/alula/i/59233341/winter-park',1,0,'منتزه شتوي winter park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59233334,'alula','متحف العُلا','Al Ula Museum','al-ula-museum','["أماكن سياحية"]','["sights"]','متحف للحضارة والتاريخ الخاصة بمنطقة العلا، يحتوي على العديد من القطع الأثرية والمعلومات التاريخية عن المنطقة وأهلها قديماً وحديثًا.','<div class="texte" > <p>متحف العلا&nbsp;هو متحف للحضارة والتاريخ الخاصة بمنطقة العلا يحتوي على العديد من القطع الأثرية والمعلومات التاريخية عن المنطقة وأهالي المنطقة قديماً كما يحتوي على بعض المعلومات التاريخية من مختلف العصور.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59233334-44035142.jpg?v=1636386295"]','https://cmsphoto.ww-cdn.com/resizeapi/d626b94cd760147293ef630b36669761526e4837/480/',26.6086648,37.9232758,'AlUla Al Sukhayrat AlUla','','','','https://www.saudi-guide.com/alula/i/59233334/al-ula-museum',1,0,'متحف علا al ula museum اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59233263,'alula','جبل العكمة (عكمة) الأثري','Ekmah Heritage Mountain','ekmah-heritage-mountain','["التراث والثقافة"]','["heritage"]','منطقة جبلية ينحدر منها وادي ضيق، تضم أكبر تجمّع للنقوش والكتابات اللحيانية، وتوثق تاريخ مملكة لحيان وحضارتها، بالقرب من موقع الخريبة.','<div class="texte" > <p>عكمة هو عبارة عن منطقة جبلية ينحدر منها وادي ضيق، وهو ذو لون داكن يميل للون الأحمر، وشاهق الارتفاع، يضم العديد من الكتابات اللحيانية على الواجهات الصخرية في الموقع، وتوثق هذه النقوش والكتابات تاريخ مملكة لحيان وحضارتها وتفاعلاتها المجتمعية وعلاقاتها الخارجية وتنظيماتها وقوانينها الداخلية، وهي قريبة من موقع الخريبة&nbsp;الذي عاشت فيه دولة لحيان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59233263-44049723.jpg?v=1636485381"]','https://cmsphoto.ww-cdn.com/resizeapi/371528ec85347cd3844f68b0161cd6ea778289b2/480/',26.6886973,37.9041326,'الشراعبة العذيب العلا','','https://www.experiencealula.com/ar/places-to-go/jabal-ikmah','','https://www.saudi-guide.com/alula/i/59233263/ekmah-heritage-mountain',1,0,'جبل عكمه (عكمه) اثري ekmah heritage mountain تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231766,'alula','دادان Dadan - مقابر الاسود','','dadan-lion-tombs','["التراث والثقافة"]','["heritage"]','فجوات منحوتة بتصميم مستطيل، سميت مقابر الأسود لنحت رسم الأسد على واجهاتها رمزاً للقوة، ويعود تاريخها لمملكة دادان قبل الميلاد بأكثر من أربعة قرون.','<div class="texte" > <p>هي عبارة عن فجوات منحوتة بتصميم مستطيل الشكل تتباين ألوانها بين الأحمر والأبيض، وتبلغ أبعادها الأربع 80 سم وعمقها مترين، سميت مقابر الأسود بهذا الاسم نتيجة لنحت الأسد الذي يعلو واجهات مقابرها، ويذكر الباحثون أن اختيار رسم الأسد على واجهات هذه المقابر كان بسبب ما يمثله الأسد من رمز للقوة والمنعة في ثقافات العالم القديم،&nbsp;يعود تاريخ المقابر&nbsp;إلى القرن الخامس قبل الميلاد أي في الفترة الأولى من مملكة دادان&nbsp;التي كانت تحكم المنطقة في تلك الفترة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231766-44049742.jpg?v=1636485538"]','https://cmsphoto.ww-cdn.com/resizeapi/dc60bb772e97c3ac24e80110e9eb9c6d55798844/480/',26.6470934,37.9160763,'طريق Al Ula AlUla','','https://www.experiencealula.com/ar/places-to-go/dadan','','https://www.saudi-guide.com/alula/i/59231766/dadan-lion-tombs',1,0,'دادان dadan مقابر اسود تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231645,'alula','الحجر (مدائن صالح)','Saleh cites','hegra-madain-saleh','["التراث والثقافة"]','["heritage"]','أول موقع سعودي مسجّل في قائمة اليونسكو للتراث العالمي، عاصمة مملكة لحيان الجنوبية بعد الأنباط، يضم 153 واجهة صخرية منحوتة ومدافن نبطية تعود لألفي عام.','<div class="texte" > <p>مدائن صالح كانت تعرف قديماً بمدينة الحِجْر، هي موقع أثري يقع في إقليم الحجاز في شبه الجزيرة العربية، شمال غرب المملكة العربية السعودية وتحديداً في محافظة العُلا التابعة لمنطقة المدينة المنورة، يحتل المكان موقعاً إستراتيجياً على الطريق الذي يربط جنوب شبه الجزيرة العربية ببلاد الرافدين وبلاد الشام ومصر، كما أن للمكان شهرته التاريخية التي استمدّها من موقعه على طريق التجارة القديم الذي يربط جنوب شبه الجزيرة العربية والشام.</p> <p>والحجر اسم ديار ثمود بوادي القرى بين المدينة المنورة وتبوك، ورد ذكر الحجر في القرآن على أنها موطن قوم ثمود، الذين استجابوا لدعوة نبي الله صالح، ثم ارتدُّوا عن دينهم وعقروا الناقة التي أرسلها الله لهم آية فأهلكهم بالصيحة.</p> <p>تعد مدائن صالح من أهم حواضر الأنباط بعد عاصمتهم البتراء، إذ تحتوي على أكبر مستوطنة جنوبية لمملكة الأنباط بعد البتراء في الأردن، والتي تفصلها عنها مسافة 500 كم، ويعود أبرز أدوارها الحضارية إلى القرنين الأول قبل الميلاد والأول الميلادي، وذلك خلال فترة ازدهار الدولة النبطية وقبل سقوطها على يد الإمبراطورية الرومانية عام 106م، ويُعتقد أن الحِجْر استمرت في حضارتها حتى القرن الرابع الميلادي، وكانت عاصمة مملكة لحيان في شمال شبه الجزيرة العربية.</p> <p>تضم آثار مدائن صالح 153 واجهة صخرية منحوتة، كما تضم عدداً من الآثار الإسلامية والتي تتمثل في عدد من القلاع وبقايا خط سكة حديد الحجاز والتي تمتد لمسافة 13 كم وكذلك المحطة والقاطرات، في سنة 2008م تم تسجيل الموقع ضمن قائمة مواقع التراث العالمي، ليصبح بذلك أول موقع يتم تسجيله في السعودية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231645-44049763.jpg?v=1636485752"]','https://cmsphoto.ww-cdn.com/resizeapi/22347525e8d9d6b63ea90d48dd26d75db7d1c587/480/',26.8040118,37.9572703,'RX34+JW2 Hegra AlUla','','https://www.experiencealula.com/ar/places-to-go/hegra','','https://www.saudi-guide.com/alula/i/59231645/hegra-madain-saleh',1,0,'حجر (مدائن صالح) saleh cites تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231603,'alula','بلدة العلا القديمة AlUla Old Town','','alula-old-town','["التراث والثقافة"]','["heritage"]','بلدة تراثية محصّنة بالكامل تضم نحو 870 وحدة سكنية متلاصقة يعود تاريخها لنحو 7 قرون، تنقسم إلى حارة الشقيق وحارة الحف، وتبعد 22 كيلو متراً عن مدائن صالح.','<iframe width="560" height="315" src="https://www.youtube.com/embed/8PVtQkGc5pw?si=2My-y4JoRG8fQjog&gbyoutube=8PVtQkGc5pw" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe> <div class="texte" > <p>البلدة القديمة هي بلدة مهجورة بالكامل، تقع غرب المملكة العربية السعودية في محافظة العلا،&nbsp;تسمى بالديرة ويوجد بها مباني تراثية قديمة ومساجد وأسواق يعود تاريخها إلى نحو 7 قرون وتبعد عن مدائن صالح 22 كيلو متر.</p> <p>تظهر البلدة التراثية وكأنها مبنى واحد لتقارب وحداتها السكنية التي تقدر بـ 870 وحدة سكنية، تتخللها أزقة ضيقة ومتعرجة، وتنقسم إلى قسمين حارة الشقيق في الشمال وحارة الحف في الجنوب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231603-63526123.jpg?v=1752741547"]','https://cmsphoto.ww-cdn.com/resizeapi/5c68fea1ffed09980fa94be35ccc17d5b0b65cfb/480/',26.6250587,37.9150404,'375 Al Ula AlUla','','https://www.visitsaudi.com/ar/alula/attractions/alula-old-town','','https://www.saudi-guide.com/alula/i/59231603/alula-old-town',1,0,'بلده علا قديمه alula old town تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231533,'alula','جبال الغراميل','Magnificient Rocks of Buraikah','magnificient-rocks-buraikah','["أماكن سياحية"]','["sights"]','تكوينات صخرية حمراء عجيبة بأشكال مختلفة ومتفاوتة الحجم تشكل لوحة أيقونية فريدة ذات منظر صحراوي ساحر وجميل.','<div class="texte" > <p>جبال الغراميل (Magnificient Rocks of Buraikah) تكوينات صخرية حمراء عجيبة اتخذت أشكالاً مختلفة ومتفاوتة الحجم بفعل عوامل التعرية الطبيعية عبر آلاف السنين، لتشكل لوحة أيقونية فريدة ذات منظر صحراوي ساحر وجميل، وتُعد من أبرز المعالم الطبيعية التي تعكس التنوع الجيولوجي لمنطقة العلا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231533-43570537.jpg?v=1633006176"]','https://cmsphoto.ww-cdn.com/resizeapi/3bb607227d1f3ada82fef17c4aa21cd135b9e560/480/',27.3582244,37.8103354,'SA AlUla Al Madinah Province','','','','https://www.saudi-guide.com/alula/i/59231533/magnificient-rocks-buraikah',1,0,'جبال غراميل magnificient rocks of buraikah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231507,'alula','جبل القوس','Rainbow Rock','rainbow-rock','["أماكن سياحية"]','["sights"]','يعد جبل القوس أو نقرة الدبوس واحدًا من أجمل التكوينات الصخرية في العلا، يمتاز بشكله الغريب الذي يشبه قوس المطر وأشكال الأحجار المتعددة الألوان.','<div class="texte" > <p>يعد جبل القوس أو "نقرة الدبوس" واحد من أجمل التكوينات الصخرية في العلا والذي يمتاز بشكله الغريب والمميز الذي يشبه قوس المطر، الجبل محاط بأشكال من الأحجار الجميلة متعددة الألوان والتي يمكن رؤيتها مدمجة في الصخرة نفسها أو على&nbsp;الأرض من حولها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231507-44035153.jpg?v=1636386342"]','https://cmsphoto.ww-cdn.com/resizeapi/bede6cac285c84e34c39ed81a5d9f1b2454ebc16/480/',27.0493536,37.7661245,'SA AlUla Al Madinah Province','','','','https://www.saudi-guide.com/alula/i/59231507/rainbow-rock',1,0,'جبل قوس rainbow rock اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231502,'alula','منتجع الشلال الزراعي','Waterfall Tourist Resort','waterfall-tourist-resort','["أماكن سياحية"]','["sights"]','منتجع جميل تحيط به أشكال الطبيعة الخلابة من جبال وكثبان ومزارع نخيل، يضم شاليهات مفروشة ومسابح أطفال ومقهى طبيعي رائع يستحق الزيارة.','<div class="texte" > <p>منتجع جميل تحيط به أشكال الطبيعة الخلابة مثل الجبال والكثبان الرملية ومزارع النخيل والحمضيات والزيتون، يكمن لسكان الشاليهات التجول في المزرعة والأكل من ثمارها، يضم المنتجع شاليهات مفروشة ومسابح اطفال كما يحتوي المنتجع على مقهى طبيعي رائع يستحق الزيارة بصراحة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231502-44035181.jpg?v=1636386511"]','https://cmsphoto.ww-cdn.com/resizeapi/65be174d3ef74adabdf18bca90a1fd03c10f8ed4/480/',26.8283217,37.8537154,'SA AlUla Al Madinah Province','','','','https://www.saudi-guide.com/alula/i/59231502/waterfall-tourist-resort',1,0,'منتجع شلال زراعي waterfall tourist resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231372,'alula','منتزة الملك عبدالعزيز','King Abdulaziz Park','king-abdulaziz-park','["أماكن سياحية"]','["sights"]','منتزه عائلي في محافظة العلا يضم ألعاباً للأطفال وعربات لبيع الأطعمة والمشروبات، مكان مناسب لقضاء أوقات ممتعة مع العائلة في أجواء مفتوحة.','<div class="texte" > <p>منتزة الملك عبدالعزيز هو منتزه عائلي مُجهّز يقع في محافظة العلا، ويُعد من الوجهات المحببة للعائلات الباحثة عن مكان مفتوح لقضاء أوقات ممتعة بعيداً عن صخب المدينة.</p> <p>يضم المنتزه مساحات خضراء وألعاباً متنوعة للأطفال، إضافة إلى عربات ومحال لبيع الأطعمة والمشروبات الخفيفة، ما يجعله وجهة مناسبة للنزهات العائلية المسائية.</p> <p>يتميز الموقع بسهولة الوصول إليه وأجوائه الهادئة، ويُقصد بشكل خاص في المساء وعطلات نهاية الأسبوع من قِبل سكان وزوار العلا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231372-44035206.jpg?v=1636386683"]','https://cmsphoto.ww-cdn.com/resizeapi/c00d3b0484b7e16e905ac3037b0651ca93162a78/480/',26.6339686,37.8943292,'375 AlUla Al Madinah Province','','','','https://www.saudi-guide.com/alula/i/59231372/king-abdulaziz-park',1,0,'منتزه ملك عبدالعزيز king abdulaziz park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231366,'alula','مقهى ومنتزه المحكر Almahker Cafe and Park','','almahker-cafe-and-park','["أماكن سياحية"]','["sights"]','مقهى ومنتزه يقدم أنواع القهوة المختصة والعربية والشاي تحت أشجار النخيل، مع فقرات وليالي فنية يقدمها نخبة من أبناء العلا.','<div class="texte" > <p>مقهى ومنتزه المحكر مكان يقدم أنواع القهوة المختصة&nbsp;والقهوة العربية والشاي بالإضافة الى انواع الكيك وكل ذلك بمكان واحد تحت اشجار النخيل وبجلسات مفتوحه صممت خصيصا للموقع بالاضافة الى وجود فقرات وليالي فنية يقدمها نخبة&nbsp;من أبناء العلا وكذلك فقرة الراوي التي تضيف للموقع رونقا خاصا بنكهة الماضي وعبق المستقبل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231366-44035222.jpg?v=1636386729"]','https://cmsphoto.ww-cdn.com/resizeapi/483649967ff0488dc975efeaa7623fb17b075b40/480/',26.6285157,37.9168823,'375 Al Ula AlUla','','','','https://www.saudi-guide.com/alula/i/59231366/almahker-cafe-and-park',1,0,'مقهي ومنتزه محكر almahker cafe and park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231361,'alula','Nakhil Brzan Countryside Resort and Restaurant- منتجع نخيل برزان الريفي','','nakhil-brzan-countryside-resort','["أماكن سياحية"]','["sights"]','منتجع جميل يتميز بجلساته المتنوعة حسب ذائقة الزوار، يقدم الضيافة العربية ووجبات الغداء والعشاء بأكلات شعبية لذيذة ومقهى للزوار.','<div class="texte" > <p>منتجع نخيل برزان الريفي منتجع جميل بمحاذاة سكة حديد الحجاز يتميز بجلساته المتنوعة حسب ذائقة الزوار، ويقدم الضيافة العربية ووجبات الغداء والعشاء بأكلات شعبية لذيذة، إلى جانب مقهى للزوار وبوفيه مفتوح بنظام الحجز المسبق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231361-44035227.jpg?v=1636386823"]','https://cmsphoto.ww-cdn.com/resizeapi/a3d32aaff366e90487a8ff1f7917a38467d85211/480/',26.6292373,37.9232542,'Hejaz Railway Station Al Ula AlUla','','','','https://www.saudi-guide.com/alula/i/59231361/nakhil-brzan-countryside-resort',1,0,'nakhil brzan countryside resort and restaurant منتجع نخيل برزان ريفي اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231334,'alula','منتزه الحدائق للترفيه','Heritage Leisure Parks','heritage-leisure-parks','["أماكن سياحية"]','["sights"]','منتزه الحدائق للترفيه هو وجهة عائلية في العلا تجمع بين المساحات الخضراء وأجواء الاسترخاء، ويضم مطعمًا ومقهى إلى جانب جلسات خارجية مخصصة للعائلات.','<div class="texte" > <p>منتزه الحدائق للترفيه هو وجهة عائلية في العلا تجمع بين المساحات الخضراء وأجواء الاسترخاء، حيث يضم مطعمًا ومقهى إلى جانب جلسات خارجية مخصصة للعائلات، مما يجعله مكانًا مناسبًا لقضاء وقت ممتع في أجواء طبيعية هادئة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231334-44035241.jpg?v=1636386871"]','https://cmsphoto.ww-cdn.com/resizeapi/8ba9327d6b859f8ebd01101d5fe9c691015ae298/480/',26.6145961,37.9225986,'AlUla Al Sukhayrat AlUla','','','','https://www.saudi-guide.com/alula/i/59231334/heritage-leisure-parks',1,0,'منتزه حدائق للترفيه heritage leisure parks اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59231322,'alula','جبل الفيل','Elephant Rock','elephant-rock','[]','[]','جبل الفيل هو صخرة ضخمة يبلغ ارتفاعها عن الأرض 52 مترًا، وتتميز بشكلها الفريد الذي يشبه الفيل، وتقع في منطقة متسعة تكسوها الرمال الذهبية على بعد 7 كم إلى جهة الشرق من محافظة العلا التابعة لمنطقة المدينة المنورة.','<div class="texte" > <p>جبل الفيل هو عبارة عن صخرة ضخمة يبلغ ارتفاعها عن الأرض 52 متر وتتميز بشكلها الفريد الذي يشبه الفيل ومنه اكتسب هذا المسمى وتحيط بالصخرة مجموعة من الجبال ذات الألوان الفاتحة ويقع في منطقة متسعة تكسوها الرمال الذهبية على بعد 7 كم إلى جهة الشرق من محافظة العلا التابعة لمنطقة المدينة المنورة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59231322-54494579.jpg?v=1698911522"]','https://cmsphoto.ww-cdn.com/resizeapi/908c0525b2f83d414e6602d3d4f641a91749e752/480/',26.6893459,37.9816139,'AlUla AlUla Al Madinah Province','','https://www.experiencealula.com/ar/places-to-go/elephant-rock','','https://www.saudi-guide.com/alula/i/59231322/elephant-rock',1,0,'جبل فيل elephant rock',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59092180,'riyadh','متحف جارالله العضيب التراثي','','jarallah-al-adhib-heritage-museum','["التراث والثقافة"]','["heritage"]','متحف جارالله العضيب التراثي بالرياض، يضم مقتنيات وأدوات شعبية تعكس تراث المنطقة.','<div class="texte" > <p>يعد متحف جار الله من أبرز&nbsp;المتاحف الشخصية في الرياض&nbsp;وقد أنشأه صاحبه في مزرعته بحي الرمال ، يحتوي المعرض على عدة سيارات قديمة وقطع أثرية وأجهزة الكترونية قديمة بالإضافة إلى عدة صحف ومجلات قديمة وغيرها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59092180-43941083.jpg?v=1635676822"]','https://cmsphoto.ww-cdn.com/resizeapi/e73755f662cb8f56cb99bc53f1f0b1f2aa424d10/480/',24.9135395,46.8276437,'Ar Rimal Riyadh Ar-Riyad','','','','https://www.saudi-guide.com/riyadh/i/59092180/jarallah-al-adhib-heritage-museum',1,0,'متحف جارالله عضيب تراثي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59092134,'riyadh','متحف قصر المصمك','Al Masmak Palace Museum','al-masmak-palace-museum','["التراث والثقافة"]','["heritage"]','متحف قصر المصمك بالرياض، معلم تاريخي بني 1865، شاهد على فتح الملك عبدالعزيز للرياض عام 1902 وتأسيس المملكة.','<video controls controlsList="nodownload" poster="https://cmsphoto.ww-cdn.com/superstatic/images/2892882/video/3441158/player/player_preview.jpg?v=1754751398" width="100%" oncontextmenu="return false;"><source src="https://www.saudi-guide.com/apiv3/video/getIphoneSVideo/3441158/49957769.mp4/" type="video/mp4" /></video> <div class="texte" > <p>يُعد حصن المصمك من المعالم التاريخية البارزة في حي الديرة وسط الرياض، وهو من المباني القليلة التي لا تزال قائمة منذ تأسيس المدينة. شُيّد عام 1282هـ (1865م) في عهد الإمام عبد الله بن فيصل بن تركي لحماية المدينة، فتميّز بجدرانه المتينة وفتحات صغيرة مخصصة لفوهات البنادق، مع مدخلين رئيسيين فقط.<br /> <br /> في عام 1319هـ (1902م)، استعاد الملك عبد العزيز آل سعود الحصن خلال معركة فتح الرياض، ليُستخدم لاحقًا كمخزنٍ للذخيرة، ثم سجن، قبل تحويله إلى متحف يوثّق قصة استرداد الرياض ومسيرة توحيد المملكة. افتُتح المتحف رسميًا في 11 يونيو 1995م ليعرض مراحل تأسيس المملكة على يد الملك المؤسس - طيّب الله ثراه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59092134-63761339.jpg?v=1754751264"]','https://cmsphoto.ww-cdn.com/resizeapi/d4de57816dc209549b6d06ae52b9aa541fd1a8c9/480/',24.6312313,46.713417,'6937 Al Thumairi St Ad Dirah','9668001189999','https://museums.moc.gov.sa/museums/museums-detail?id=0B441465C74A4D46AB9875E1B4757E35','','https://www.saudi-guide.com/riyadh/i/59092134/al-masmak-palace-museum',1,0,'متحف قصر مصمك al masmak palace museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59092109,'riyadh','مركز الملك عبدالعزيز التاريخي','','king-abdulaziz-historical-center','["التراث والثقافة"]','["heritage"]','مركز الملك عبدالعزيز التاريخي بالرياض، معلم وطني يعكس تاريخ جزيرة العرب ورسالة الإسلام وأسس المملكة العربية السعودية.','<div class="texte" > <p>أنشئ مركز الملك عبد العزيز&nbsp;التاريخي ليكون معلما وطنيا على مستوى المملكة العربية السعودية، وليكون مركزا ثقافيا وواجهة حضارية مشرقة تعكس تاريخ جزيرة العرب، ورسالة الإسلام&nbsp;الخالدة، وتعرف بتاريخ المملكة العربية السعودية، والأسس التي قامت عليها، والجهود التي بذلت لبنائها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59092109-43941447.jpg?v=1635680501"]','https://cmsphoto.ww-cdn.com/resizeapi/2e6ffe56d7d7c734ee70f27b4badab2019fbf794/480/',24.6479311,46.7100446,'Ar-Riyad Al Murabba Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59092109/king-abdulaziz-historical-center',1,0,'مركز ملك عبدالعزيز تاريخي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59092105,'riyadh','مكتبة الملك فهد الوطنية','king Fahad National Library','king-fahad-national-library','["التراث والثقافة"]','["heritage"]','مكتبة الملك فهد الوطنية بالرياض، أكبر صرح ثقافي في المملكة يضم ملايين الكتب والمخطوطات النادرة.','<div class="texte" > <p>تعد المكتبة معلماً تذكارياً شُيّد على نفقة المواطنين؛ ليكون تحفة معمارية بالتعاون مع هيئة تطوير مدينة الرياض التي قدمت الأرض والإشراف الفني والمعماري والإداري، وقد صُمّم المبنى ليكون مكتبة معمارية، ثم حُوّلت إلى مكتبة وطنية للمملكة العربية السعودية، بناءً على اقتراح خادم الحرمين الشريفين الملك سلمان بن عبد العزيز، الذي كانت له اليد الطولى في إنشاء المكتبة وتجهيزها، حيث كان رئيس اللجنة الاستشارية في مرحلة الإنشاء، فكسبت البلاد مكتبة وطنية بعد طول انتظار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59092105-43941491.jpg?v=1635681072"]','https://cmsphoto.ww-cdn.com/resizeapi/2e57479f4747d9f42f4b02b7bfedea838db630c8/480/',24.6855614,46.6865207,'6757 King Fahd Rd Al Olaya','','','','https://www.saudi-guide.com/riyadh/i/59092105/king-fahad-national-library',1,0,'مكتبه ملك فهد وطنيه king fahad national library تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59092097,'riyadh','متحف الفيصل للفن الإسلامي','Al Faisal Arabic and Islamic Arts Museum','al-faisal-islamic-arts-museum','["التراث والثقافة"]','["heritage"]','متحف الفيصل للفن الإسلامي والعربي بالرياض، يضم مجموعة من القطع الفنية الإسلامية النادرة.','<div class="texte" > <p>يعد&nbsp;متحف الفيصل للفن الإسلامي من أهم المتاحف التي تعرض عدد من المخطوطات النادرة الأصلية من مصاحف الأمصار بالإضافة إلى العديد من القطع الأثرية القديمة من مختلف العصور الإسلامية وغيرها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59092097-43941709.jpg?v=1635683541"]','https://cmsphoto.ww-cdn.com/resizeapi/feb55f4a32c4b8eed55a6aac5c1424718958707b/480/',24.6915538,46.684607,'3314 رقم 38 الرياض 12212 No. 38 Al Olaya','','','','https://www.saudi-guide.com/riyadh/i/59092097/al-faisal-islamic-arts-museum',1,0,'متحف فيصل للفن اسلامي al faisal arabic and islamic arts museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59092091,'riyadh','King Salman Science Oasis واحة الملك سلمان للعلوم','','king-salman-science-oasis','["التراث والثقافة"]','["heritage"]','واحة الملك سلمان للعلوم بالرياض، مركز علمي تفاعلي يقدم تجارب ممتعة للأطفال والعائلات.','<div class="texte" > <p>واحة الملك سلمان للعلوم هي بيئة تعليمية ترفيهية تستعرض مجموعة من العلوم والتجارب بصورة تعليمية مشوقة وممتعة للمقيمين والزائرين.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59092091-43943752.jpg?v=1635695219"]','https://cmsphoto.ww-cdn.com/resizeapi/144cf662459be4a92706e01f92345ffdd6923699/480/',24.7161658,46.638416,'طريق الملك عبدالله، Al Raed Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59092091/king-salman-science-oasis',1,0,'king salman science oasis واحه ملك سلمان للعلوم تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091998,'riyadh','متحف الحمدان للتراث الشعبي','Al Hmdan Heritage Museum','al-hmdan-heritage-museum','["التراث والثقافة"]','["heritage"]','متحف الحمدان للتراث الشعبي بالرياض، يضم مقتنيات وأدوات تراثية تعكس الحياة الشعبية القديمة.','<div class="texte" > <p>متحف الحمدان للتراث الشعبي هو الوجهة الأفضل لمحبي التراث الشعبي ولمن يريد استرجاع الذكريات القديمة .</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091998-43943845.jpg?v=1635695443"]','https://cmsphoto.ww-cdn.com/resizeapi/d9ea35d26e2212414d258d1dc9efe003e5d3f968/480/',24.7841228,46.8233931,'الطرفاوي، الخليج Al Khaleej Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091998/al-hmdan-heritage-museum',1,0,'متحف حمدان للتراث شعبي al hmdan heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091990,'riyadh','مكتبة الملك عبدالعزيز العامة','King Abdulaziz Public Library','king-abdulaziz-public-library','["التراث والثقافة"]','["heritage"]','مكتبة الملك عبدالعزيز العامة بالرياض، صرح ثقافي ومعرفي يقدم خدمات مكتبية وثقافية متنوعة للزوار.','<div class="texte" > <p>توفر مكتبة الملك عبد العزيز&nbsp;مصادر المعرفة البشرية وتنظمها وتيسر استخدامها وجعلها في متناول الباحثين والدارسين.</p> <p>وللمكتبة اهتمام مميز بتوثيق تاريخ المملكة العربية السعودية&nbsp;وتاريخ الملك عبد العزيز على وجه الخصوص بوصف المكتبة تتشرف بحمل اسمه. كما تبذل قصارى جهدها لرصد التراث العربي والإسلامي والإسهام في إحيائه وإخراجه بما يلائم روح العصر، كما تسهم في خدمة المجتمع من خلال إقامة الندوات والمحاضرات والمعارض والمشاركة في المناسبات الدينية والوطنية والاجتماعية، ودعم حركة البحث العلمي والتأليف والترجمة والنشر، وتنمية ثقافة الطفل، وتوفير خدمات المعلومات للمرأة، وتبادل الخبرات مع مؤسسات المعلومات على مختلف المستويات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091990-43943898.jpg?v=1635695909"]','https://cmsphoto.ww-cdn.com/resizeapi/e54e684a52b16351061fb2d32ac1ec8795a8805e/480/',24.7104254,46.7533898,'4170 Makkah Al Mukarramah Rd King Abdullah Dt.','','','','https://www.saudi-guide.com/riyadh/i/59091990/king-abdulaziz-public-library',1,0,'مكتبه ملك عبدالعزيز عامه king abdulaziz public library تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091970,'riyadh','متحف المشوح للتراث الشعبي','','al-mashwah-heritage-museum','["التراث والثقافة"]','["heritage"]','متحف المشوح للتراث الشعبي بالرياض، موقع يعرض مقتنيات وأدوات قديمة تروي ذاكرة الماضي.','<div class="texte" > <p>مؤسس متحف المشوح هو مشوح عبد الرحمن المشوح وقد عرض به&nbsp;الكثير من القطع منها أدوات الحرب السلاح القديم وأدوات الطهي ومواد البقالة القديمة وأدوات&nbsp;الترحال والسقيا والمكاييل وأجهزة سمعية وأدوات القهوة العربية&nbsp; ومجلس عربي متكامل ومطبوعات قديمة وقاعدة مدفع تاريخه وغيرها من القطع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091970-43944141.jpg?v=1635697080"]','https://cmsphoto.ww-cdn.com/resizeapi/faf3c51130abeef077a1f2cd80e73953f5a9bdee/480/',24.7509277,46.7830462,'8280 Ibn Al Halawi Al Andalus','','','','https://www.saudi-guide.com/riyadh/i/59091970/al-mashwah-heritage-museum',1,0,'متحف مشوح للتراث شعبي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091931,'riyadh','Saqer-Aljazirah Royal Saudi Air Force Aviation Museum (Riyadh)- متحف صقر الجزيرة للطيران','','saqer-aljazirah-aviation-museum','["التراث والثقافة"]','["heritage"]','متحف صقر الجزيرة للطيران بالرياض، يوثق تاريخ قوات الدفاع الجوي الملكي السعودي ويضم طائرات تاريخية.','<div class="texte" > <p>متحف صقر الجزيرة للطيران هو متحف جوي يسرد التطور التاريخي للقوات الجوية الملكية السعودية منذ نشأتها علي يدي الملك عبد العزيز إلى ما وصلت إليه في هذا العصر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091931-43944070.jpg?v=1635696777"]','https://cmsphoto.ww-cdn.com/resizeapi/66328133039750c6a7328fac30ed2d68c00f014d/480/',24.7540196,46.7391089,'مخرج 10 Eastern Ring Rd King Abdullah Dt.','','','','https://www.saudi-guide.com/riyadh/i/59091931/saqer-aljazirah-aviation-museum',1,0,'saqer aljazirah royal saudi air force aviation museum (riyadh) متحف صقر جزيره للطيران تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091829,'riyadh','جبال طويق','Towaiq Mountains','towaiq-mountains','["ترفيه واستجمام"]','["fun"]','جبال طويق بالرياض، سلسلة جبلية طبيعية ممتدة محاذية للمدينة، مقصد مفضل للمغامرة ورياضة التسلق.','<div class="texte" > <p><span>جبل طويق&nbsp;أحد أهم المعالم الجغرافية في الجزيرة العربية</span><span>، وأحد أبرز المعالم الطوبوغرافية التي يمكن رؤيتها من الفضاء الخارجي</span><span>&nbsp;وهو قلب إقليم ال</span>يمامة<span>&nbsp;التاريخي وإقليم نجد</span><span>. </span></p> <p><span>اسم الجبل طويق تصغير لكلمه طوق وتصغير الأسماء لتمليحها عادة قديمة عند العرب. طويق من أقدم الآثار في نجد التي عرفوها شعوب الجزيرة العربية منذ زمنٍ طويل فالحفريات الأثرية العالمية الجارية اليوم تحت إشراف الهيئة العامة للسياحة والتراث الوطني تغوص عميقًا حتى ما قبل التاريخ، لتكشف عن الكثير من التفاصيل المثيرة التي تتعلق بالهجرات الإنسانية القديمة، وتؤكد وجود قرى قديمة على امتداد جبال طويق.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091829-43871436.jpg?v=1635156628"]','https://cmsphoto.ww-cdn.com/resizeapi/07d8e97c0fe68cbf291d02dee1f27e21273fd11a/480/',21.7434999,45.6763443,'Towaiq Mountains Riyadh Province SA','','','','https://www.saudi-guide.com/riyadh/i/59091829/towaiq-mountains',1,0,'جبال طويق towaiq mountains ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091826,'riyadh','منتزه بحيرة الحائر','Al-Haeer Park Lake','al-haeer-park-lake','["ترفيه واستجمام"]','["fun"]','منتزه بحيرة الحائر بالرياض، موقع طبيعي يضم بحيرة ماء ومساحات استراحة جنوب الرياض.','<div class="texte" > <p>يشكل منتزه بحيرات الحاير في الرياض مجمع ترفيهي مُتكامل يضم فنادق ومراكز تسوق ومدن ألعاب مائية، بالإضافة إلى&nbsp;ساحات ممتدة من المُسطحات الخضراء مُتنوعة العناصر النباتية ومجموعة من البحيرات الطبيعية وما يلحق بها من مكونات اصطناعية كالقنوات والأنهار والبرك <span>&nbsp;والممرات المائية</span>، وكذلك المرافق الخدمية، وعليه قد لا يكفي يومًا واحدًا للتمكن من اغتراف السعادة وحيازة المُتعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091826-43871554.jpg?v=1635158530"]','https://cmsphoto.ww-cdn.com/resizeapi/b4cbe5347ed03380cd155f89c37e5839f808f016/480/',24.3900954,46.8812327,'9VRJ+2FQ Riyadh Ar-Riyad','','','','https://www.saudi-guide.com/riyadh/i/59091826/al-haeer-park-lake',1,0,'منتزه بحيره حائر al haeer park lake ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091801,'riyadh','منتزه الثمامه البري','Thumamah National Park','thumamah-national-park','["ترفيه واستجمام"]','["fun"]','منتزه الثمامة البري بالرياض، محمية طبيعية صحراوية مفتوحة لمحبي التخييم والطبيعة البرية.','<div class="texte" > <p>يتميز منتزه الثمامة البري بكثرة المخيمات المجهزة للتأجير وفرصة الاستمتاع بالهواء الطلق بعيدا عن أجواء المدينة مما يدفع الأسر للتوجه إليه وقضاء أجمل الأوقات وأمتعها خصوصا في أيام نهاية الأسبوع والعطلات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091801-43872010.jpg?v=1635160105"]','https://cmsphoto.ww-cdn.com/resizeapi/cfdcc588100e1e924741826e8691eb52b14809a9/480/',25.1226414,46.6706917,'الرياض منطقة الرياض SA','','','','https://www.saudi-guide.com/riyadh/i/59091801/thumamah-national-park',1,0,'منتزه ثمامه بري thumamah national park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091744,'riyadh','منتزه وادي حنيفة','Wadi Hanifa Park','wadi-hanifa-park','["ترفيه واستجمام"]','["fun"]','منتزه وادي حنيفة بالرياض، أطول وادي في الجزيرة العربية بعد إعادة تأهيله ليضم مساحات خضراء وبحيرات.','<div class="texte" > <p>يعد منتزه وادي حنيفة واحد من أهم منتزهات الرياض، يضم الوادي العديد من الإطلالات الجميلة&nbsp;على المساحات الخضراء والعديد من&nbsp;المتنزهات&nbsp;الرائعة بالإضافة إلى البحيرة، أيضا يضم المنتزه العديد من المطاعم&nbsp;والمقاهي، كما يضم ممرات مشاه مميزة، ملاعب كرة، مرافق خدمية ومصليات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091744-43871920.jpg?v=1635159391"]','https://cmsphoto.ww-cdn.com/resizeapi/b0559c25fe2d419ce5e6a977fa5fbfbd03fedadc/480/',24.5522524,46.7406021,'4848 Al-Masani'' Riyadh','','https://www.diriyah.sa/ar/wadi-hanifah','','https://www.saudi-guide.com/riyadh/i/59091744/wadi-hanifa-park',1,0,'منتزه وادي حنيفه wadi hanifa park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091687,'riyadh','منتزه سد وادي نمار','','wadi-namar-dam-park','["ترفيه واستجمام"]','["fun"]','منتزه سد وادي نمار بالرياض، موقع طبيعي جميل يضم سدًا ومساحات طبيعية مفتوحة.','<div class="texte" > <p>منتزه سد وادي نمار&nbsp;هو منتزة مفتوح يقع جنوب الرياض، يعد من المعالم السياحية الأشهر والأكثر جذبا لزوار وسياح العاصمة، ويكتض هذا الموقع السياحي البيئي في عطلة نهاية الأسبوع بالزوار الذين يستمتعون بالجلوس حول البحيرة الصناعية في المنتزه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091687-43872191.jpg?v=1635161174"]','https://cmsphoto.ww-cdn.com/resizeapi/604766acef719d3ba630f14211cb960bbc04d7e6/480/',24.5714739,46.6795882,'Ahmad Al Aquli Namar Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091687/wadi-namar-dam-park',1,0,'منتزه سد وادي نمار ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091679,'riyadh','منتزه السد الحجري','','al-sad-al-hajari-park','["ترفيه واستجمام"]','["fun"]','منتزه السد الحجري بالرياض، موقع طبيعي يضم سدًا ومساحات خضراء مفتوحة.','<div class="texte" > <p>يشتمل منتزه سد الحجري على بحيرة كبيرة تبلغ مساحتها 10 كلم مربع كما يحتوي على ممرات مشاة بطول 4,5 كلم وعدد كبير من الشجيرات والأشجار الصحراوية وأشجار النخيل</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091679-43872395.jpg?v=1635161915"]','https://cmsphoto.ww-cdn.com/resizeapi/156a7b561c7f4085faa122e05adc35f2ba437f3b/480/',24.5706898,46.7233733,'Badr Riyadh Ar-Riyad','','','','https://www.saudi-guide.com/riyadh/i/59091679/al-sad-al-hajari-park',1,0,'منتزه سد حجري ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091646,'riyadh','كهف عين هيت','Ayn Hayt','ayn-hayt-cave','["ترفيه واستجمام"]','["fun"]','كهف عين هيت بالرياض، تكوين جيولوجي طبيعي فريد من النوع يجذب محبي المغامرة والاستكشاف.','<div class="texte" > <p>كهف هيت هو تجويف صخري يعود عمره لآلاف السنين كما يمتد عمقه ل390 متر،&nbsp;يحتوي الكهف على عين هيت المليئة بالمياه النقية ويعد الكهف وجهة مفضلة لعشاق المغامرات والاستكشاف</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091646-43872519.jpg?v=1635162686"]','https://cmsphoto.ww-cdn.com/resizeapi/4ca4be1bc7b4c5560cc358414257673d1287a9f7/480/',24.6729039,46.7426946,'Ayn Hayt Al Malaz Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091646/ayn-hayt-cave',1,0,'كهف عين هيت ayn hayt ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091368,'riyadh','ميدان ديراب','DIRAB Park','dirab-park','["ترفيه واستجمام"]','["fun"]','ميدان ديراب بالرياض، مركز مخصص لرياضة الفروسية والأنشطة الصحراوية جنوب المدينة.','<div class="texte" > <p>يحتضن ميدان ديراب سنويا العديد من الفعاليات الترفيهية والرياضية الكبيرة كما ينظم الميدان العديد من البطولات والمسابقات الخاصة بقيادة السيارات والدرجات النارية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091368-43872684.jpg?v=1635163412"]','https://cmsphoto.ww-cdn.com/resizeapi/ddb4e074a6537efbddd89297f5f14405bc20cbd6/480/',24.461645,46.5824174,'Jabal Ajyad Rd Dahiat Namar Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091368/dirab-park',1,0,'ميدان ديراب dirab park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091362,'riyadh','منتزه الملك سلمان البري','','king-salman-park-riyadh','["ترفيه واستجمام"]','["fun"]','منتزه الملك سلمان البري بالرياض، محمية طبيعية واسعة تجمع بين الحياة الفطرية ومسارات المغامرة.','<div class="texte" > <p>يعد&nbsp;منتزه الملك سلمان البري وجهة مميزة للسياح حيث يوفر الحدائق الطبيعية والبرية والتي تحتوي على تنوع نباتي كبير كما يضم المنتزه منطقة السفاري التي تضم حيوانات مختلفة من جميع أنحاء العالم، ويمكن للزوار أن يشاهدوا هذه الحيوانات عن قرب من خلال سيارات خاصة يوفرها المنتزه.</p> <p>كما يوفر المنتزه منطقة خاصة بالعائلات والتي تتميز بوجود مناطق خاصة للتخييم ومزودة بالخدمات المناسبة وتحتوي أيضا على منطقة للألعاب المناسبة لكل الأعمار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091362-43872782.jpg?v=1635164590"]','https://cmsphoto.ww-cdn.com/resizeapi/35fae9a92f5e15af6499f8a7dc07b643aaacb11e/480/',25.0056571,46.6005703,'Ar-Riyad Riyadh Riyadh Province','','','','https://www.saudi-guide.com/riyadh/i/59091362/king-salman-park-riyadh',1,0,'منتزه ملك سلمان بري ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091317,'riyadh','نادي الفارسة للسيدات','','al-farisa-ladies-club','["ترفيه واستجمام"]','["fun"]','نادي الفارسة للسيدات بالرياض، مركز رياضي مخصص للفروسية ورياضة الخيول للسيدات.','<div class="texte" > <p>&nbsp;نادي الفارسة للسيدات هو نادي لتعليم <span>الفروسية ل</span>لسيدات&nbsp;وتقديم عدة برامج لهم تتعلق في كيفية التعامل مع الخيول .مثل&nbsp;الطريقة الصحيحة لركوب الخيل وتوجيهها وكيفية العناية بها</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091317-43873003.jpg?v=1635165260"]','https://cmsphoto.ww-cdn.com/resizeapi/4b1f0072d494b9b23edca6b5727214c637a8e3ca/480/',24.9219152,46.8349486,'Riyadh Ash Sharq Rumah','','','','https://www.saudi-guide.com/riyadh/i/59091317/al-farisa-ladies-club',1,0,'نادي فارسه للسيدات ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091311,'riyadh','المركز العالمي للبولينغ','Universal Bowling Center','universal-bowling-center','["ترفيه واستجمام"]','["fun"]','المركز العالمي للبولينغ بالرياض، صالة بولينج متطورة تقدم أجواء ترفيهية ممزوجة للعائلات والأصدقاء.','<div class="texte" > <p>المركز العالمي للبولينج هو أكبر صالة بولينج في المملكة العربية السعودية، ويقع في العاصمة الرياض، تضم الصالة 30 مسار بولينج ومركز إنترنت وألعاباً إلكترونية وطاولات للبلياردو وألعاب الفيديو، وهي مصممة ومخصصة للبطولات الدولية.</p> <p>كذلك تضم الصالة عدة طاولات تنس وبلياردو وبعض الرياضات الأخرى.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091311-43884796.jpg?v=1635245219"]','https://cmsphoto.ww-cdn.com/resizeapi/e9b7981242b187b3b758271fd39bde903d00fbf9/480/',24.6488187,46.6518522,'Prince Faisal Bin Fahd Bin Abdulaziz Rd Ar Rafiah Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091311/universal-bowling-center',1,0,'مركز عالمي للبولينغ universal bowling center ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091302,'riyadh','الحكير تايم (الملقا)','ALHOKAIR TIME','alhokair-time-al-malqa','["ترفيه واستجمام"]','["fun"]','الحكير تايم بالملقا، مدينة ألعاب وترفيه داخلي تضم ألعاباً متنوعة للأطفال والعائلات.','<div class="texte" > <p>ملاهي الحكير تايم هي مدينة ألعاب تتميز&nbsp;بتنوع الألعاب فيها والتي تناسب جميع الأعمار كما توفر المدينة مجموعة من المطاعم والمقاهي وتعتبر الحكير تايم وجهة مفضلة للزوار لقضاء أوقات ممتعة ومسلية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091302-43884834.jpg?v=1635246156"]','https://cmsphoto.ww-cdn.com/resizeapi/932d72412535601baa37b955e2a9386c30622d80/480/',24.820712,46.6015066,'RJC2+8M King Salman Rd Al Malqa','','','','https://www.saudi-guide.com/riyadh/i/59091302/alhokair-time-al-malqa',1,0,'حكير تايم (الملقا) alhokair time ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091284,'riyadh','حديقة اليمامة','Al Yamamah Park','al-yamamah-park','["ترفيه واستجمام"]','["fun"]','حديقة اليمامة بالرياض، حديقة عامة توفر أجواء خضراء ومساحات مناسبة للمشي والرياضة.','<div class="texte" > <p>حديقة اليمامة هي إحدى&nbsp;الحدائق التابعة&nbsp;لمركز الملك عبدالعزيز التاريخي ، من أهم ما يميز الحديقة هي الطبيعة الخلابة والهواء النقي بالإضافة إلى المسطحات الخضراء الواسعة والجميلة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091284-43885357.jpg?v=1635248362"]','https://cmsphoto.ww-cdn.com/resizeapi/e4f598de6ab3fe8b2d571bcab3ca1085f52f363f/480/',24.6444281,46.7088461,'King Saud Rd Al Futah Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091284/al-yamamah-park',1,0,'حديقه يمامه al yamamah park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091133,'riyadh','منتزه الملك عبدالله بالملز','King Abdullah Park','king-abdullah-park-almalaz','["ترفيه واستجمام"]','["fun"]','منتزه الملك عبدالله بالملز بالرياض، من أكبر المتنزهات العامة يضم أجواء خضراء ومساحات مميزة.','<div class="texte" > <p>تُعد حديقة الملك عبد الله&nbsp;من أجمل حدائق الرياض وواحدة من أهم الأماكن السياحية فيها&nbsp;وأكثرها زيارة لعدة أسباب من بينها سهولة الوصول اليها حيث تقع في وسط مدينة الرياض.</p> <div dir="rtl">تم تزويد الحديقة بكل التجهيزات و الامكانات التي تتوفر عليها أشهر المنتزهات العالمية من مساحات ضخراء ، أماكن جلوس مظللة ، مناطق لعب للاطفال ، سجاد من الورود الطبيعية ، نافورة مياه راقصة استثنائية تقذف الماء بارتفاع 110م اضافة الى مرافق متعددة مثل المطاعم و المقاهي و المصليات و مناطق ترفيهية للشباب.</div> <div>&nbsp;</div> <div>&nbsp;</div> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091133-43886580.jpg?v=1635250349"]','https://cmsphoto.ww-cdn.com/resizeapi/b13f07b86a260f88aaa2077edc8756ba383599d0/480/',24.666626,46.7370781,'Al Ameen Abdullah Al Ali Al Naeem St Al Malaz Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091133/king-abdullah-park-almalaz',1,0,'منتزه ملك عبدالله بالملز king abdullah park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59091127,'riyadh','حديقة العليا','Olaya Park','olaya-park','["ترفيه واستجمام"]','["fun"]','حديقة العليا بالرياض، حديقة عامة توفر أجواء خضراء ومساحات مناسبة للمشي وسط المدينة.','<div class="texte" > <p>تعد المسطحات الخضراء والأشجار الكثيفة بالإضافة إلى البحيرة الصناعية من أهم عوامل جذب السياح لحديقة&nbsp;العليا&nbsp;كما توفر الحديقة&nbsp;منطقة خاصة بالألعاب بالإضافة إلى ملعب كرة قدم صغير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59091127-43886695.jpg?v=1635251475"]','https://cmsphoto.ww-cdn.com/resizeapi/d6203e4b8dc9183b4e1ccd9a5339afdcf454ce05/480/',24.6806073,46.6828041,'ابي بكر الباقلاني ,العليا Al Olaya Riyadh','','','','https://www.saudi-guide.com/riyadh/i/59091127/olaya-park',1,0,'حديقه عليا olaya park ترفيه واستجمام',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121494,'eastern-region','شاطئ طيبة','Taiba Beach','taiba-beach-shaty-tyb','["أماكن سياحية"]','["sights"]','شاطئ طيبة أحد الشواطئ بالمنطقة الشرقية، يوفر للزوار أجواءً ساحلية هادئة على مياه الخليج العربي.','<div class="texte" > <p>شاطئ طيبة شاطئ عام في حي جلمودة بمدينة الجبيل الصناعية على ساحل الخليج العربي، ويقصده الأهالي والزوار للتنزه والجلسات العائلية والاستمتاع بالأجواء البحرية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121494-45096049.jpg?v=1643852735"]','https://cmsphoto.ww-cdn.com/resizeapi/38cc66a9cc73f57ced93a1658ae23a67b897efc0/480/',27.1691435,49.5497094,'Jalmudah Al Jubail Jubail','','','','https://www.saudi-guide.com/eastern-region/i/60121494/taiba-beach-shaty-tyb',1,0,'شاطئ طيبه taiba beach اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121493,'eastern-region','متنزه نجد','Najd Park','najd-park-mtnzh-ngd','["أماكن سياحية"]','["sights"]','متنزه نجد من المتنزهات العامة بالمنطقة الشرقية، ويتيح للزوار أجواءً خضراء مناسبة للنزهات العائلية.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121493-45096052.jpg?v=1643852752"]','https://cmsphoto.ww-cdn.com/resizeapi/cefe8f958988884d3abee81d5e072c4375e14bd4/480/',27.1479876,49.5389826,'3606 نجد 2 Fanateer','','','','https://www.saudi-guide.com/eastern-region/i/60121493/najd-park-mtnzh-ngd',1,0,'متنزه نجد najd park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121492,'eastern-region','متنزه الأندلس','Andalus Park','andalus-park-mtnzh-alandls','["أماكن سياحية"]','["sights"]','متنزه الأندلس أحد المتنزهات العامة بالمنطقة الشرقية، ويوفر مساحات خضراء وممرات للمشي مناسبة لجميع أفراد الأسرة.','<div class="texte" > <p>متنزه الأندلس من المتنزهات العامة في حي الدفي بمدينة الجبيل الصناعية، ويوفر مساحات خضراء مفتوحة للتنزه والجلسات العائلية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121492-45096055.jpg?v=1643852767"]','https://cmsphoto.ww-cdn.com/resizeapi/38758b3aab437d57b96850d581073c772836998e/480/',27.1397433,49.5398617,'4GQQ+VWX Deffi Al Jubail','','','','https://www.saudi-guide.com/eastern-region/i/60121492/andalus-park-mtnzh-alandls',1,0,'متنزه اندلس andalus park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121490,'eastern-region','متنزه القناة المائية للترفيه','Aqua Park','aqua-park-mtnzh-alkna-almayy-lltrfyh','["أماكن سياحية"]','["sights"]','متنزه القناة المائية للترفيه وجهة ترفيهية مائية بالمنطقة الشرقية، تجمع بين الألعاب المائية وأجواء الاستجمام العائلي.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121490-45096057.jpg?v=1643852781"]','https://cmsphoto.ww-cdn.com/resizeapi/684898e5f20c80822d7faeba45db3ea1c2b75865/480/',27.1143241,49.5617371,'Al Huwailat Al Jubayl Jubail','','','','https://www.saudi-guide.com/eastern-region/i/60121490/aqua-park-mtnzh-alkna-almayy-lltrfyh',1,0,'متنزه قناه مائيه للترفيه aqua park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121485,'eastern-region','كورنيش الفناتير','Corniche Fanateer','corniche-fanateer-kornysh-alfnatyr','["أماكن سياحية"]','["sights"]','يعد شاطئ الفناتير في الجبيل من أفضل شواطئ مدينة الجبيل وأحدثها، فهو يتميز بالديكورات والتصميمات المتطورة الحديثة، كما يتميز بأنه من الشواطئ العائلية...','<div class="texte" > <p>يعد شاطئ الفناتير في الجبيل من أفضل شواطئ مدينة الجبيل وأحدثها، فهو يتميز بالديكورات والتصميمات المتطورة الحديثة، كما يتميز بأنه من الشواطئ العائلية التي يمكنك اصطحاب عائلتك للتمتع بيوم ترفيهي مميز،&nbsp;يقع شاطئ الفناتير في مدينة الجبيل الصناعية بالقرب من طريق “فهد”،&nbsp;ويشغل شاطئ الفناتير مع الشواطئ المحيطة به مسافة 45 كم من مدينة الجبيل، ويعتبر ذلك الشاطئ من أهم الشواطئ الجاذبة للسكّان المحليين بالمدينة وأيضًا للسيّاح الخارجيين، ويعتبر ايضاً من اهم اماكن السياحة في الجبيل .</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121485-45137781.jpg?v=1644232103"]','https://cmsphoto.ww-cdn.com/resizeapi/4c3eaf0d892b51055e8b803d324cbecac46c5946/480/',27.1546064,49.5693479,'Fanateer Al Jubail Jubail','','','','https://www.saudi-guide.com/eastern-region/i/60121485/corniche-fanateer-kornysh-alfnatyr',1,0,'كورنيش فناتير corniche fanateer اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121483,'eastern-region','شاطئ دارين','','shaty-daryn','["أماكن سياحية"]','["sights"]','شاطئ دارين يُعتبر من أجمل شواطئ الجبيل الصناعية وهو عبارة عن شبه جزيرة رائعة، ذات مساحة كبيرة جدًا تبلغ ما يزيد عن 250 هكتار.','<div class="texte" > <p>شاطئ دارين يُعتبر من أجمل شواطئ الجبيل الصناعية وهو عبارة عن شبه جزيرة رائعة، ذات مساحة كبيرة جدًا تبلغ ما يزيد عن 250 هكتار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121483-45096044.jpg?v=1643852675"]','https://cmsphoto.ww-cdn.com/resizeapi/3c6e87506c712fbabd4127f05f70eda12567e102/480/',27.1670529,49.5643033,'5H87+RPF Fanateer Al Jubail','','','','https://www.saudi-guide.com/eastern-region/i/60121483/shaty-daryn',1,0,'شاطئ دارين اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121481,'eastern-region','كورنيش الجبيل','Corniche Jubail','corniche-jubail-kornysh-algbyl','["أماكن سياحية"]','["sights"]','كورنيش هادئ وجميل ومناسب للاستجمام  وتمضية أوقات الراحة أو ممارسة الرياضة بالهواء الطلق، يوفر الكورنيش جلسات عائلية بجانب البحر او على العشب، يرتاد...','<div class="texte" > <p>كورنيش هادئ وجميل ومناسب&nbsp;<span>للاستجمام&nbsp;</span>&nbsp;وتمضية أوقات الراحة أو ممارسة الرياضة&nbsp;بالهواء الطلق، يوفر الكورنيش جلسات عائلية بجانب البحر او على العشب،&nbsp;يرتاد الكورنيش&nbsp;الكثير من الزوار للجبيل وخاصة في أيام&nbsp; .نهاية الاسبوع</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121481-45137838.jpg?v=1644232369"]','https://cmsphoto.ww-cdn.com/resizeapi/4850a27449ac569a0e635abf63311eee675cde57/480/',27.0362075,49.6372392,'2JPP+FVQ King Fahd Industrial Port Al Jubail','','','','https://www.saudi-guide.com/eastern-region/i/60121481/corniche-jubail-kornysh-algbyl',1,0,'كورنيش جبيل corniche jubail اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121480,'eastern-region','متنزه الدفي','Deffi Park','deffi-park-mtnzh-aldfy','["أماكن سياحية"]','["sights"]','متنزّه يحتوي على ألعاب ومسارات للمشي والهرولة ومرافق رياضية، بالإضافة إلى أماكن للشواء مظلّلة بأشجار النخيل.','<div class="texte" > <p>متنزّه يحتوي على&nbsp;ألعاب ومسارات للمشي والهرولة ومرافق رياضية، بالإضافة إلى أماكن للشواء مظلّلة بأشجار النخيل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121480-45096042.jpg?v=1643852656"]','https://cmsphoto.ww-cdn.com/resizeapi/5a8f4176abac354466bb16ada1ebb7a601a586d2/480/',27.1432308,49.5342479,'Al Andalus Deffi Al Jubayl','','','','https://www.saudi-guide.com/eastern-region/i/60121480/deffi-park-mtnzh-aldfy',1,0,'متنزه دفي deffi park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121479,'eastern-region','شاطئ النخيل','Al Nakheel Beach','al-nakheel-beach-shaty-alnkhyl','["أماكن سياحية"]','["sights"]','شاطئ النخيل هو منتجع يقع بالقرب من الشاطئ ويحتوي على شاليه ومسبح وصالة رياضية وغيرها من الخدمات.','<div class="texte" > <p>&nbsp;شاطئ النخيل هو منتجع يقع بالقرب من الشاطئ ويحتوي على شاليه ومسبح وصالة رياضية وغيرها من الخدمات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121479-45137842.jpg?v=1644232390"]','https://cmsphoto.ww-cdn.com/resizeapi/8a5f32a335427802526c41838f7950cb9d9b90f1/480/',27.1176508,49.5722442,'4208 Rd 101 Al Jubayl','','','','https://www.saudi-guide.com/eastern-region/i/60121479/al-nakheel-beach-shaty-alnkhyl',1,0,'شاطئ نخيل al nakheel beach اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121439,'eastern-region','القرية الشعبية','Heritage Village','heritage-village-alkry-alshaaby','["التراث والثقافة"]','["heritage"]','قرية ثقافية فيها مخطوطات يدوية وتحف أثرية وسيارات قديمة، وتضم مطعمًا سعوديًا تقليديًا.','<div class="texte" > <p>قرية ثقافية فيها مخطوطات يدوية وتحف أثرية وسيارات قديمة، وتضم مطعمًا سعوديًا تقليديًا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121439-45095822.jpg?v=1643851763"]','https://cmsphoto.ww-cdn.com/resizeapi/144e106cffee30e499b02b2dc09f9663e2400e2c/480/',26.4919881,50.1205838,'Corniche Walk Way Ash Shati Al Gharbi Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121439/heritage-village-alkry-alshaaby',1,0,'قريه شعبيه heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121437,'eastern-region','متحف الفلوة والجوهرة للتراث','Alfelwah and Aljowharah Museum','alfelwah-and-aljowharah-museum-mthf-alflo-oalgohr-lltrath','["التراث والثقافة"]','["heritage"]','يعد متحف الفلوة والجوهرة للتراث أهم متاحف المنطقة الشرقية حيث أنه يحتوي على أكثر من 500 قطعة أثرية نادرة موزعة على طابقين بمساحة 5000 متر مربع، ينقسم...','<div class="texte" > <p>&nbsp;يعد متحف الفلوة والجوهرة للتراث أهم متاحف المنطقة الشرقية حيث أنه يحتوي على أكثر من 500 قطعة أثرية نادرة موزعة على طابقين بمساحة 5000 متر مربع، ينقسم المتحف إلى 10 أقسام ما بين السيارات الكلاسيكية والتراث الإسلامي والعملات النقدية&nbsp;والمهن الحرفية ومقتنيات الأسر الحاكمة وغيرها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121437-45137824.jpg?v=1644232293"]','https://cmsphoto.ww-cdn.com/resizeapi/d948f397a91054cd1a79768d811039748fb20c81/480/',26.4000345,50.1111109,'8061 8 Al Nuzha','','https://www.visitsaudi.com/ar/eastern-province/attractions/alfelwah-and-aljowharah-museum','','https://www.saudi-guide.com/eastern-region/i/60121437/alfelwah-and-aljowharah-museum-mthf-alflo-oalgohr-lltrath',1,0,'متحف فلوه والجوهره للتراث alfelwah and aljowharah museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121435,'eastern-region','متحف الدمام الاقليمي','','mthf-aldmam-alaklymy','["التراث والثقافة"]','["heritage"]','متحف الدمام الإقليمي يعرض آثار المنطقة الشرقية وتراثها في ست قاعات، من العصور الحجرية حتى تراث الآباء والأجداد، ويضم قاعة أمير المنطقة الشرقية.','<div class="texte" > <p><span>متحف الدمام الإقليمي يُعد واحداً من ضمن سلسلة المتاحف التي قامت وزارة المعارف بإنشائها تحت إشراف وكالة الآثار والمتاحف وبرعاية الأمير محمد بن فهد بن عبد الله آل سعود تم افتتاح المتحف في 24 /7 /1405هـ في مبناه المؤقت بالمكتبة العامة بالدمام - الدور الرابع،&nbsp;يَضم المتحف ست قاعات آثارية وتراثية وطبيعية بالإضافة إلى قاعة أمير المنطقة الشرقية التي افتتحت لاحقاً عام 1421هـ. وحسب ما أثبتته المكتشفات والحفريات التي أجريت في المنطقة فإن هناك أكثر من 400 موقع أثري مهم في مختلف أرجاء المنطقة الشرقية كالظهران وتاروت والقطيف والجبيل والأحساء والخبر والدمام وثاج ويبرين وبقيق وغيرها، ويُمكن رؤية هذه الآثار داخل قاعات المتحف الست موزعة داخل خزائن «فاترينات» عرض خاصة ومتسلسلة حسب الفترات الزمنية بالتدرج منذ العصور الحجرية إلى تراث الآباء والأجداد.</span></p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121435-45096039.jpg?v=1643852638"]','https://cmsphoto.ww-cdn.com/resizeapi/7a7b49a7f6327dde45a01e3e057213bb360a1f67/480/',26.4843462,50.1178124,'F4M9+P4M Ash Shati Al Gharbi Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121435/mthf-aldmam-alaklymy',1,0,'متحف دمام اقليمي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121434,'eastern-region','قلعة قصر محمد بن عبد الوهاب','','klaa-ksr-mhmd-bn-aabd-alohab','["التراث والثقافة"]','["heritage"]','قصر محمد بن عبد الوهاب الفيحاني أو قصر الفيحاني هو قصر أثري تجاوره قلعة تُعرف بقلعة دارين يقع في قرية دارين بجزيرة تاروت في محافظة القطيف شرق السعودية...','<div class="texte" > <p>قصر محمد بن عبد الوهاب الفيحاني أو قصر الفيحاني هو قصر أثري تجاوره قلعة تُعرف بقلعة دارين يقع في قرية دارين بجزيرة تاروت في محافظة القطيف شرق السعودية، رُمِّمت القلعة من قبل محمد بن عبد الوهاب الفيحاني ما بين عامي 1884م و1885م فصارت تُعرَف باسمه.</p> <p>القصر بملحقاته قائمٌ على منتصف قوس ساحل جنوب دارين، ويضّم مرافقَ وملحقاتٍ عدّة تتضمنُ: مجموعةَ غُرَفٍ، مخازنَ، مجالسَ وفناءً خلفيًّا؛ جدرانُه تحتوي على مجموعةِ من الأقواس المصممة على الطراز الإسلامي العباسي،&nbsp;وتبلغ مساحته الإجمالية مع ملحقاته نحو 8,000 مترًا مربّعًا.</p> <p>يتوسّطُ القصرُ بملحقاتِه قريةَ دارين على مرتفعٍ كبيرٍ قربَ سطح البحر، ويقع بين الحوطة والحي الشرقي. يحدُّ القصر بملحقاته من الجنوب مسجد صغير بمرتفع صخري ينخفض تدريجيًّا حتّى يتّصل بالبحر مباشرة حيث ميناء دارين، ومن الشرق مجموعة منازل سكنيّة ثم جامع دارين الكبير، ومن الشمال ساحة مفتوحة وغربه منزل مهجورة، يُمثّل التّل الواقعة عليه القلعة طبقات رسوبية مُتراكمة، تشكل كل واحدة منها حقبة زمنية مختلفة.</p> <p>أخذت قلعة دارين قيمة تاريخية كبيرة خلال قيام الدّولة السعودية الأولى والثّانية وكذلك في عهد الدولة العثمانية إلا أنّها تحوّلت بملحقات القصر لأنقاض وأكوام حجارة نتيجة تهاوي الجدران وتساقطها على بعضها، ولم يبقَ منها سوى أساساتها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121434-45095818.jpg?v=1643851741"]','https://cmsphoto.ww-cdn.com/resizeapi/8f8ad0088fdb807f811dd7a187c3f319e353e165/480/',26.5433929,50.0776611,'Darin Tarut Al-Qatif','','','','https://www.saudi-guide.com/eastern-region/i/60121434/klaa-ksr-mhmd-bn-aabd-alohab',1,0,'قلعه قصر محمد بن عبد وهاب تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121431,'eastern-region','شاطئ الامواج','Amwaj Beach','amwaj-beach-shaty-alamoag','["أماكن سياحية"]','["sights"]','منتجع ومطعم ومقهى شاطئ امواج هو منتجع سياحي وترفيهي مطل على البحر يوفر جميع الخدمات التي يحتاجها الزوار لقضاء وقت ممتع.','<div class="texte" > <p>منتجع ومطعم ومقهى شاطئ امواج هو منتجع سياحي وترفيهي مطل على البحر يوفر جميع&nbsp;الخدمات التي يحتاجها الزوار لقضاء وقت ممتع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121431-45095814.jpg?v=1643851722"]','https://cmsphoto.ww-cdn.com/resizeapi/b7c81406f7c998848d46e11dfe348774baab4ff9/480/',26.1418185,50.0017519,'Amwaj Beach Dhahran Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121431/amwaj-beach-shaty-alamoag',1,0,'شاطئ امواج amwaj beach اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121425,'eastern-region','متنزه الملك عبدالله - الواجهة البحرية','King Abdullah Park, Sea front','king-abdullah-park-sea-front-mtnzh-almlk-aabdallh-aloagh-albhry','["أماكن سياحية"]','["sights"]','متنزه الملك عبدالله على الواجهة البحرية من المتنزهات الساحلية بالمنطقة الشرقية، ويجمع بين المساحات الخضراء وإطلالات البحر.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121425-45137808.jpg?v=1644232237"]','https://cmsphoto.ww-cdn.com/resizeapi/50ba19f4c4d0866366c81ac473053d744695aea0/480/',26.4874107,50.1192138,'F4P9+XM8 Ash Shati Al Gharbi Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121425/king-abdullah-park-sea-front-mtnzh-almlk-aabdallh-aloagh-albhry',1,0,'متنزه ملك عبدالله واجهه بحريه king abdullah park sea front اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121423,'eastern-region','ملاهي سبلاش المائية','Splash Island','splash-island-mlahy-sblash-almayy','["أماكن سياحية"]','["sights"]','ملاهي سبلاش المائية الدمام هي واحدة من أفضل الوجهات المائية في مدينة الدمام، والتي تضمن لك ولعائلتك يوماً مليئاً بالمرح واللعب.','<div class="texte" > <p>ملاهي سبلاش المائية الدمام هي واحدة من أفضل الوجهات المائية في مدينة الدمام، والتي تضمن لك ولعائلتك يوماً مليئاً بالمرح واللعب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121423-45137815.jpg?v=1644232268"]','https://cmsphoto.ww-cdn.com/resizeapi/9d2efc10c4f6cba8141d6eac6ef5aa83df5dca2c/480/',26.3991879,50.1176038,'94X9+M2H Al Shifa Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121423/splash-island-mlahy-sblash-almayy',1,0,'ملاهي سبلاش مائيه splash island اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121420,'eastern-region','عالم المغامرات','Adventure World','adventure-world-aaalm-almghamrat','["أماكن سياحية"]','["sights"]','مركز ترفيهي مخصّص للأطفال الصغار يضمّ ألعاب ركوب ومناطق للعب وخيارات متعدّدة من المطاعم المريحة.','<div class="texte" > <p>مركز ترفيهي مخصّص للأطفال الصغار يضمّ ألعاب ركوب ومناطق للعب وخيارات متعدّدة من المطاعم المريحة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121420-45095810.jpg?v=1643851704"]','https://cmsphoto.ww-cdn.com/resizeapi/faf50e04ed417249f2f5d735b22545493a9a18f7/480/',26.4319043,50.1140726,'حي 5233 الامير منصور','','','','https://www.saudi-guide.com/eastern-region/i/60121420/adventure-world-aaalm-almghamrat',1,0,'عالم مغامرات adventure world اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121418,'eastern-region','شاطئ الصدف','Sadaf Beach Half Moon','sadaf-beach-half-moon-shaty-alsdf','["أماكن سياحية"]','["sights"]','شاطئ هادئ ونظيف يتميز بتوفيره لكل الخدمات التي يحتاجها الزوار والسائحين مثل دورات المياه ومحطة البنزين ومحال التموين وغيرها.','<div class="texte" > <p>شاطئ هادئ ونظيف يتميز بتوفيره لكل الخدمات التي يحتاجها الزوار والسائحين مثل دورات المياه ومحطة البنزين ومحال التموين وغيرها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121418-45137796.jpg?v=1644232214"]','https://cmsphoto.ww-cdn.com/resizeapi/f107145abce83b9eabd704bfa9d7f034e556f4e0/480/',26.200042,50.0284043,'Sadaf Beach Half Moon Dhahran Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121418/sadaf-beach-half-moon-shaty-alsdf',1,0,'شاطئ صدف sadaf beach half moon اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121415,'eastern-region','منتزه جبل المريكبات','Muraikabat Mountain Park','muraikabat-mountain-park-mntzh-gbl-almrykbat','["أماكن سياحية"]','["sights"]','يشكل جبل المريكبات بعداً تاريخياً وبيئياً داخل مدينة الدمام، لذا تم تطوير منتزه عليه مع الاحتفاظ بوضعه الطبيعي دون تغيير، ويحتوي المنتزه على أشجار ومسارات للمشي.','<div class="texte" > <p>يشكل جبل المريكبات بعداً تاريخياً وبيئياً داخل مدينة الدمام، لذا تم تطوير منتزه عليه مع الاحتفاظ بوضعه الطبيعي دون تغيير، يحتوي المنتزه على أشجار وشجيرات متلائمة مع ظروف الموقع ومسطحات خضراء في الأماكن المنخفضة، وكراسي للجلوس ومظلات وملاعب للأطفال، ومضمار للمشي حول الجبل بطول كيلو مترين، يتخلله ممرات داخل المنتزه.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121415-45095809.jpg?v=1643851684"]','https://cmsphoto.ww-cdn.com/resizeapi/8f210d24dcaf43fc4c61d5cb9f088bd952baefcc/480/',26.4170579,50.1056111,'Albairuni St Al Muraikabat Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121415/muraikabat-mountain-park-mntzh-gbl-almrykbat',1,0,'منتزه جبل مريكبات muraikabat mountain park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121411,'eastern-region','مدينة الكوبرا الترفيهية','Cobra Amusement Park','cobra-amusement-park-mdyn-alkobra-altrfyhy','["أماكن سياحية"]','["sights"]','مدينة الكوبرا الترفيهية من الوجهات الترفيهية بالمنطقة الشرقية، وتضم ألعابًا متنوعة تناسب مختلف أفراد الأسرة.','<div class="texte" > <p>مدينة الكوبرا الترفيهية مدينة ألعاب في حي البساتين بمدينة الدمام، وتضم ألعاباً متنوعة للكبار والصغار، من أبرزها أفعوانية «كوبرا» المثيرة وأفعوانية «دراغون» العائلية. وقد خضعت المدينة لأعمال تجديد في السنوات الأخيرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121411-45137794.jpg?v=1644232189"]','https://cmsphoto.ww-cdn.com/resizeapi/b55af1195935af18b0d25959850518663cf88c76/480/',26.3870735,50.1248664,'cobra amusement park Al Basatin Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121411/cobra-amusement-park-mdyn-alkobra-altrfyhy',1,0,'مدينه كوبرا ترفيهيه cobra amusement park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121408,'eastern-region','حديقة الحيوان','Zoo','zoo-hdyk-alhyoan','["أماكن سياحية"]','["sights"]','تقع حديقة حيوانات عبد الحميد على طريق الظهران الجبيل السريع، وهي من أبرز حدائق الحيوان في المنطقة الشرقية، ففيها العديد من الحيوانات والطيور.','<div class="texte" > <p>تقع حديقة حيوانات عبد الحميد على طريق الظهران الجبيل السريع، وهي من أبرز حدائق الحيوان في المنطقة الشرقية، ففيها العديد من الحيوانات والطيور وبعض الألعاب البسيطة التي تُناسب الأطفال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121408-45137790.jpg?v=1644232170"]','https://cmsphoto.ww-cdn.com/resizeapi/29b726dc92103bfc431a7e44af320433c32102eb/480/',26.4834742,50.003324,'Dhahran Jubail Expy Saihat Al-Qatif','','','','https://www.saudi-guide.com/eastern-region/i/60121408/zoo-hdyk-alhyoan',1,0,'حديقه حيوان zoo اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121394,'eastern-region','شاطئ الرملة البيضاء','Ramlet Al-Bayda Beach','ramlet-al-bayda-beach-shaty-alrml-albydaaa','["أماكن سياحية"]','["sights"]','شاطئ الرملة البيضاء أو شاطئ الرفيعة هو ساحل بحري يطل على خليج تاروت، غرب الخليج العربي، يمتد الشاطئ من نهاية بلدة دارين إلى بداية بحر سنابس.','<div class="texte" > <p>شاطئ الرملة البيضاء أو شاطئ الرفيعة هو ساحل بحري يطل على خليج تاروت، غرب الخليج العربي،&nbsp;يمتد الشاطئ من نهاية بلدة دارين&nbsp;إلى بداية بحر سنابس،&nbsp;يصل طول الشاطئ إلى كيلومتر واحد،&nbsp;تمتاز أرض الشاطئ بالصلابة والشدة والانبساط نتيجة تشبع تربتها الرملية بالماء، وهي تتصف بخلوها من الصخور والموانع الطبيعية ما جعلها سابقاً مهبطاً للطائرات والمروحيات القادمة إلى مطار دارين الذي يبعد عن الشاطئ حوالي 600 متراً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121394-45095808.jpg?v=1643851660"]','https://cmsphoto.ww-cdn.com/resizeapi/60dbf9b25280a2ff0c32268ccf8685ab1203c137/480/',26.5594578,50.0851371,'Ramlet Al-Bayda Beach Al Andalus Tarut','','','','https://www.saudi-guide.com/eastern-region/i/60121394/ramlet-al-bayda-beach-shaty-alrml-albydaaa',1,0,'شاطئ رمله بيضاء ramlet al bayda beach اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121392,'eastern-region','(لايف بارك) منتزه الملك فهد بالدمام','King Fahd Park (Life Park)','king-fahd-park-life-park-layf-bark-mntzh-almlk-fhd-baldmam','["أماكن سياحية"]','["sights"]','مساحة خضراء شاسعة تحتوي على مسارات للمشي ومنتزه للتزلّج وحدائق، بالإضافة إلى مدينة ملاهي.','<div class="texte" > <p>مساحة خضراء شاسعة تحتوي على&nbsp;مسارات للمشي ومنتزه للتزلّج وحدائق، بالإضافة إلى مدينة ملاهي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121392-45095807.jpg?v=1643851634"]','https://cmsphoto.ww-cdn.com/resizeapi/e0dbd48a4fe9e3423cc5ee2ea0f48b5c1f27a385/480/',26.3924832,50.1273835,'Al Basatin Dammam Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121392/king-fahd-park-life-park-layf-bark-mntzh-almlk-fhd-baldmam',1,0,'(لايف بارك) منتزه ملك فهد بالدمام king fahd park (life park) اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121345,'eastern-region','كورنيش الدمام','Dammam Corniche','dammam-corniche-kornysh-aldmam','["أماكن سياحية"]','["sights"]','كورنيش الدمام هو منتزه للهرولة وصيد السمك، يقع بمحاذاة الماء وتصطف على جانبيه مساحات خضراء، يضم مساحات لعب وألعاب أطفال وعربات طعام.','<div class="texte" > <p>كورنيش الدمام هو منتزه للهرولة وصيد السمك، يقع بمحاذاة الماء وتصطف على جانبَيه مساحات خضراء، يضم مساحات لعب وألعاب أطفال&nbsp;وعربات طعام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121345-45095805.jpg?v=1643851611"]','https://cmsphoto.ww-cdn.com/resizeapi/ac53808aaa6831b61aacc02ab2d0e8b61c30a444/480/',26.4575889,50.1017626,'Dammam As Salam Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121345/dammam-corniche-kornysh-aldmam',1,0,'كورنيش دمام dammam corniche اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121322,'eastern-region','قرية الدولفين الترفيهية','Dolphin Village Dammam','dolphin-village-dammam-kry-aldolfyn-altrfyhy','["أماكن سياحية"]','["sights"]','مدينة ملاهي تتميّز بعروض الدلافين وأسود البحر بالإضافة إلى ألعاب للأطفال ومسابح تضمّ منزلقات.','<div class="texte" > <p>مدينة ملاهي تتميّز بعروض الدلافين وأسود البحر بالإضافة إلى ألعاب للأطفال ومسابح تضمّ منزلقات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121322-45095803.jpg?v=1643851591"]','https://cmsphoto.ww-cdn.com/resizeapi/d6088cd84dbc72f98096bd4540449c15fee33dd5/480/',26.4791299,50.097549,'Cornish Rd Al-Hamra''a Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121322/dolphin-village-dammam-kry-aldolfyn-altrfyhy',1,0,'قريه دولفين ترفيهيه dolphin village dammam اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121320,'eastern-region','بحيرة سيهات','Saihat Lake','saihat-lake-bhyr-syhat','["أماكن سياحية"]','["sights"]','بحيرة سيهات إحدى البحيرات الطبيعية بمحافظة سيهات، وتشكل وجهة هادئة لمحبي الطبيعة والتصوير.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121320-45137782.jpg?v=1644232145"]','https://cmsphoto.ww-cdn.com/resizeapi/e69fadd9ee73773a0ce01a45dba3b07e2cec32d0/480/',26.4673479,50.0669084,'Saihat Lake Eastern Province SA','','','','https://www.saudi-guide.com/eastern-region/i/60121320/saihat-lake-bhyr-syhat',1,0,'بحيره سيهات saihat lake اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121319,'eastern-region','جزيرة المرجان','Murjan Island','murjan-island-gzyr-almrgan','["أماكن سياحية"]','["sights"]','جزيرة المرجان هي جزيرة سياحية في مدينة الدمام شرق المملكة العربية السعودية، وهي أول جزيرة اصطناعية بالمملكة.','<div class="texte" > <p>جزيرة المرجان هي جزيرة سياحية في مدينة الدمام شرق المملكة العربية السعودية، وهي أول جزيرة اصطناعية بالمملكة،&nbsp;بُنيت الجزيرة بواسطة شركة أرامكو سنة 1991م&nbsp;في عهد الملك فهد بن عبد العزيز،&nbsp;تبعد جزيرة المرجان عن كورنيش الدمام حوالي 1800 م، كما أنها تتصل بجسر ممهد يربطها بالكورنيش،&nbsp;تبلغ مساحتها 7000 متر مربع، ويتوسطها برج "الملوية" بتصميمه الفريد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121319-45095802.jpg?v=1643851569"]','https://cmsphoto.ww-cdn.com/resizeapi/1ad2a885471e50b63c1502addc3db4e47bc2b113/480/',26.4838331,50.1059144,'Cornish Rd Al-Hamra''a Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60121319/murjan-island-gzyr-almrgan',1,0,'جزيره مرجان murjan island اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121317,'eastern-region','حديقة الملك فهد','King Fahad Park','king-fahad-park-hdyk-almlk-fhd','["أماكن سياحية"]','["sights"]','حديقة الملك فهد من الحدائق العامة بالمنطقة الشرقية، وتوفر مساحات خضراء مناسبة للنزهات العائلية.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121317-45137692.jpg?v=1644231298"]','https://cmsphoto.ww-cdn.com/resizeapi/bc93c61184914112b1e4eea397910ebc39faba76/480/',26.4198554,50.1204473,'3059 طريق الملك فهد بن عبد العزيز Al Shifa','','','','https://www.saudi-guide.com/eastern-region/i/60121317/king-fahad-park-hdyk-almlk-fhd',1,0,'حديقه ملك فهد king fahad park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121245,'eastern-region','ميناء العقير الأثري','Old Al Uqayr Seaport','old-al-uqayr-seaport-mynaaa-alaakyr-alathry','["التراث والثقافة"]','["heritage"]','ميناء العقير هو ميناء بحري أثري يقع في محافظة الأحساء، في المنطقة الشرقية من المملكة العربية السعودية.','<div class="texte" > <p>ميناء العقير هو ميناء بحري أثري يقع في محافظة الأحساء، في المنطقة الشرقية من المملكة العربية السعودية. يبعد الميناء 65 كيلومتراً عن مدينة الهفوف ويقع غرب الخليج العربي. ميناء العقير هو أقدم ميناء بحري في المملكة العربية السعودية، حيث اتُخِذَ الميناءُ بوابةً بحريةً لمنطقة نجد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121245-45095663.jpg?v=1643850620"]','https://cmsphoto.ww-cdn.com/resizeapi/e0439699917298a4427b13a28fa5348fdeb2b4c6/480/',25.6434173,50.2155662,'Uqair Rd الأحساء المنطقة الشرقية','','','','https://www.saudi-guide.com/eastern-region/i/60121245/old-al-uqayr-seaport-mynaaa-alaakyr-alathry',1,0,'ميناء عقير اثري old al uqayr seaport تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121244,'eastern-region','مسجد جواثا التاريخي','Jawatha Mosque','jawatha-mosque-msgd-goatha-altarykhy','["التراث والثقافة"]','["heritage"]','مسجد جواثى أو جوثا أو جواثا، يقع في محافظة الأحساء شرق المملكة العربية السعودية، ويبعد المسجد الذي يقع ضمن متنزه يعرف بالاسم نفسه.','<div class="texte" > <p>مسجد جواثى أو جوثا أو جواثا، يقع في محافظة الأحساء شرق المملكة العربية السعودية، ويبعد المسجد الذي يقع ضمن متنزه يعرف بالاسم نفسه، نحو 17 كيلومتراً شمال شرق مدينة الهفوف. بني هذا المسجد في عهد النبي محمد عليه السلام وتشرف ببنائه سكان بلاد إقليم البحرين بنو عبد قيس وهم الذين بادروا بإسلامهم طوعاً لا كرهاً وقد مدح النبي أهل هذه الديار بقوله (أكرموا أخوانكم فإنهم أشبه الناس بكم أسلموا طوعاً لا كرهاً)، ولا تزال قواعد هذا المسجد قائمة إلى وقتنا الحالي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121244-45095643.jpg?v=1643850598"]','https://cmsphoto.ww-cdn.com/resizeapi/6e4650ba151ff3dd2bd2d78c5a39814ef22a62e9/480/',25.4698414,49.6785138,'Juatha Al Kulabiyah Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121244/jawatha-mosque-msgd-goatha-altarykhy',1,0,'مسجد جواثا تاريخي jawatha mosque تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121241,'eastern-region','متحف دار التراث','Dar Alturath Museum','mthf-dar-altrath-dar-alturath-museum','["التراث والثقافة"]','["heritage"]','متحف دار التراث هو متحف يقع في محافظة الأحساء التابعة لمنطقة الشرقية في المملكة العربية السعودية، ويضم مجموعة من القطع الأثرية والتراثية المتنوعة.','<div class="texte" > <p>متحف دار التراث هو متحف يقع في محافظة الأحساء التابعة لمنطقة الشرقية في المملكة العربية السعودية،&nbsp;يحتوي المتحف 18 ركنًا تشمل حوالي ثلاثة آلاف قطعة أثرية، تمثل الحرف وأنواع المقتنيات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121241-45095642.jpg?v=1643850580"]','https://cmsphoto.ww-cdn.com/resizeapi/80d048f8aa0c05626ca93485abe78578314cca35/480/',25.3972019,49.6810777,'المبرز المنصورة الأحساء','','','','https://www.saudi-guide.com/eastern-region/i/60121241/mthf-dar-altrath-dar-alturath-museum',1,0,'متحف دار تراث dar alturath museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121239,'eastern-region','متحف القهوة / المملكة العربية السعودية','Coffee Museum brother','coffee-museum-brother-mthf-alkho-almmlk-alaarby-alsaaody','["التراث والثقافة"]','["heritage"]','متحف القهوة متحف نوعي جميل يضم مقهى ومتجراً وأكاديمية للقهوة، كما أنه يُدون تاريخ القهوة في المملكة العربية السعودية ويعرض أدواتها والطرق المستخدمة.','<div class="texte" > <p>متحف القهوة متحف نوعي جميل يضم مقهى ومتجراً وأكاديمية القهوة، كما أنه يُدون تاريخ القهوة في المملكة العربية السعودية ويعرض أدواتها والطرق المستخدمة لزرعها وطحنها وتحميصها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121239-45095639.jpg?v=1643850546"]','https://cmsphoto.ww-cdn.com/resizeapi/43356d3b828b46b9b48d22ffcaad57c5e88a7d6e/480/',25.495657,49.578743,'SA Al-Ahsa Eastern Province','','','','https://www.saudi-guide.com/eastern-region/i/60121239/coffee-museum-brother-mthf-alkho-almmlk-alaarby-alsaaody',1,0,'متحف قهوه / مملكه عربيه سعوديه coffee museum brother تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121235,'eastern-region','حديقة قصر محيرس','Mehaires Palace','mehaires-palace-hdyk-ksr-mhyrs','["التراث والثقافة"]','["heritage"]','قصر محيرس هو قصر يقع في محافظة الاحساء، شرق المملكة العربية السعودية.','<div class="texte" > <p>قصر محيرس هو قصر يقع في محافظة الاحساء، شرق المملكة العربية السعودية. شيد القصر على يد الإمام سعود بن عبد العزيز على أعلى قمّة تلّ في عام 1208هـ لأغراض عسكرية،&nbsp;وهو عبارة عن&nbsp;قلعة حربية صغيرة مكونة من أبراج دائريّة بها عدد من الغرف، خُزنت بها الأسلحة والمؤن والذخائر،&nbsp;وشهدت القلعة معركة بين قوات الإمام وبين قوات زيد بن عريعر، وطردهم من شمال المبرز ومن القرى الشمالية بالأحساء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121235-45095635.jpg?v=1643850497"]','https://cmsphoto.ww-cdn.com/resizeapi/c914bedf71caf8bdd24362ef225510d669158c00/480/',25.4482602,49.5825542,'الملك فيصل Al Rashdiyah Al Mubarraz','','','','https://www.saudi-guide.com/eastern-region/i/60121235/mehaires-palace-hdyk-ksr-mhyrs',1,0,'حديقه قصر محيرس mehaires palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121233,'eastern-region','قلعة صاهود','Sahood Fort','sahood-fort-klaa-sahod','["التراث والثقافة"]','["heritage"]','قصر صاهود، قلعة تقع خارج الأسوار الغربية لمدينة المبرز، ويواجه مدخله ضاحية الحزم، وقد اُعيد بناؤه بشكل جيد ويستخدم كثكنات للجيش العربي السعودي.','<div class="texte" > <p>قصر صاهود، قلعة تقع خارج الأسوار الغربية لمدينة المبرز، ويواجه مدخله ضاحية الحزم، وقد اُعيد بناؤه بشكل جيد ويستخدم كثكنات للجيش العربي السعودي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121233-45095632.jpg?v=1643850453"]','https://cmsphoto.ww-cdn.com/resizeapi/1b145723d3173b703d6c4d2040aecbd5b777a735/480/',25.4140119,49.583231,'المبرز حي العتبان الأحساء','','','','https://www.saudi-guide.com/eastern-region/i/60121233/sahood-fort-klaa-sahod',1,0,'قلعه صاهود sahood fort تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121231,'eastern-region','قصر إبراهيم العفيصان الأثري','Ibrahim Palace','ibrahim-palace-ksr-abrahym-alaafysan-alathry','["التراث والثقافة"]','["heritage"]','قصر إبراهيم هو قصرٌ تاريخي وأحد آثار الأحساء بالمنطقة الشرقية في السعودية، يقع شمال حي الكوت حيث كان المقر الرئيس لحامية الدولة العثمانية في محافظة...','<div class="texte" > <p>قصر إبراهيم هو قصرٌ تاريخي وأحد آثار الأحساء بالمنطقة الشرقية في السعودية،&nbsp;يقع شمال حي الكوت حيث كان المقر الرئيس لحامية الدولة العثمانية في محافظة الأحساء في الهفوف التابعة للبصرة آنذاك،&nbsp;سيطر عليه الملك عبد العزيز آل سعود ليلة الخامس من جمادى الأولى 1331 هـ المُوافق 13 إبريل، 1913م أثناء ضمه للأحساء.</p> <p>بدأ بناء القصر مع مسجد القُبَّة عام 963هـ المُوَافق 1555م، وخلال القرن التالي توسع ليضم القلعة، وسجنًا، وحمامات عُثمانية،&nbsp;في مارس 2019 أعلنت الهيئة العامة للسياحة والتراث الوطني انتهاء مراحل الترميم في جميع أجزاء ومرافق القصر، والتي شملت إعادة بناء الأجزاء المتساقطة، إضافة إلى الأعمال الجصية لمرافق القصر، مع دهن المباني حسب المواصفات المناسبة للموقع التاريخي، وتسوية الساحة المقابلة للقصر وتأهيلها لتكون مقراً لإقامة الفعاليات والمهرجانات السياحية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121231-45095631.jpg?v=1643850406"]','https://cmsphoto.ww-cdn.com/resizeapi/b32e5620ad1eab4d05f84a6549824edd8eced18c/480/',25.3788664,49.5868937,'Al Rafaa North Al Hofuf Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121231/ibrahim-palace-ksr-abrahym-alaafysan-alathry',1,0,'قصر ابراهيم عفيصان اثري ibrahim palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121230,'eastern-region','المدرسة الأميرية','Princes School','princes-school-almdrs-alamyry','["التراث والثقافة"]','["heritage"]','مدرسة الهفوف الأولى أو المدرسة الأميرية أو بيت الثقافة، هي مدرسة حكومية سعودية تقع بمحافظة الأحساء في الهفوف.','<div class="texte" > <p>مدرسة الهفوف الأولى أو المدرسة الأميرية أو بيت الثقافة، هي مدرسة حكومية سعودية تقع بـمحافظة الأحساء في الهفوف، بدأ بناؤها عام 1937م وافتتحت رسمياً في فبراير، 1941م تحت رعاية سعود بن جلوي أمير الأحساء وقتها. المدرسة الأميرية هي أقدم مدرسة حكومية في السعودية وقد ارتبطت بتاريخ الملك عبد العزيز آل سعود وإنجازاته، فأسس المدرسة لتكون نقطة انطلاق التعليم في المنطقة الشرقية، تعلم في المدرسة العديد من المسؤولين من بينهم خالد الفيصل أمير مكة المكرمة الذي درس القرآن الكريم والسنتين الأولى والثانية الابتدائيتين في الأحساء، ووزير البترول علي النعيمي، ووزير العمل السابق غازي القصيبي.</p> <p>يُذكر أنّ مدرسة الأميرية تخرّج منها أول دفعة بلغ عددها 70 طالباً سنة 1943م، ويغلب على تصميمها الطراز الإسلامي حيث شُيّد مدخل المدرسة الشرقي وفقًا لفن العمارة العربي الإسلامي، وهي ضمن المواقع السياحية والأثرية المدرجة في قائمة الهيئة العامة للسياحة والتراث الوطني بالأحساء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121230-45095627.jpg?v=1643850385"]','https://cmsphoto.ww-cdn.com/resizeapi/21d59b58fbd56ba635bb17941de9cd4a17c1aab9/480/',25.374103,49.5874626,'9HFP+JXW Al Rifaa South Al Hofuf','','','','https://www.saudi-guide.com/eastern-region/i/60121230/princes-school-almdrs-alamyry',1,0,'مدرسه اميريه princes school تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121217,'eastern-region','فندق الكوت التراثي','Al Koot Heritage Hotel','fndk-alkot-altrathy-al-koot-heritage-hotel','["التراث والثقافة"]','["heritage"]','يقع فندق الكوت التراثي في مبنى تراثي مرمم قرب قصر أحمد التاريخي في الأحساء، وتتميز غرفه بديكورات تقليدية من الشرق الأوسط، ويضم مطعمًا ومقهى بأجواء تعكس طابع المنطقة.','<div class="texte" > <p>قع فندق الكوت الساحر في مبنى تراثي مرمّم على بُعد 5 دقائق سيرًا على الأقدام من قصر أحمد الذي يعود إلى القرن السادس عشر، ويبعُد مسافة 4 كم عن متحف الأحساء الوطني و 20 كم عن مطار الأحساء،&nbsp;تتميّز الغرف المريحة بمنسوجات وأثاث وديكورات تقليدية من الشرق الأوسط ، وتضم أجهزة تلفزيون بشاشات مسطّحة وثلّاجات صغيرة وخدمة Wi-Fi مجانية فضلاً عن آلات لتحضير القهوة والشاي،&nbsp;وتتميّز الغرف التي تتمّ ترقيتها بمساحات منفصلة للمعيشة في حين تضمّ الشقق التي تضمّ غرفتين نوم مطابخ، وتضم الفناء المقوّس المزدوج الارتفاع مطعمًا مريحًا يقدّم مأكولات من الشرق الأوسط والغربية،&nbsp;ويضمّ الفندق أيضًا مقهًى هادئًا ، وتتوفّر مواقف للسيارات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121217-45095626.jpg?v=1643850362"]','https://cmsphoto.ww-cdn.com/resizeapi/fe0921df64bf04b917248a5c9fe2654a51009b6c/480/',25.3779653,49.5853573,'SA Al Koot Al Naathil Al Hofuf','','','','https://www.saudi-guide.com/eastern-region/i/60121217/fndk-alkot-altrathy-al-koot-heritage-hotel',1,0,'فندق كوت تراثي al koot heritage hotel تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121215,'eastern-region','جامع الجبري التراثي','','gamaa-algbry-altrathy','["التراث والثقافة"]','["heritage"]','جامع الجبري هُو مسجد ومنطقة أثرية تاريخية يقع في حي الكوت في مدينة الهفوف في محافظة الأحساء شرق المملكة العربية السعودية.','<div class="texte" > <p>جامع الجبري هُو مسجد ومنطقة أثرية تاريخية يقع في حي الكوت في مدينة الهفوف في محافظة الأحساء شرق المملكة العربية السعودية. تعود فترة بناء المسجد إلى القرن التاسع الهجري وبالضبط سنة 880 هـ، حيث بناه سيف بن زامل بن حسين الجبري أمير الإمارة الجبرية في الأحساء آنذاك.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121215-45095624.jpg?v=1643850337"]','https://cmsphoto.ww-cdn.com/resizeapi/c7d96a49036f1796451f03711acec04a3869fe43/480/',25.3786336,49.5836291,'Al Koot Al Naathil Al Hofuf Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121215/gamaa-algbry-altrathy',1,0,'جامع جبري تراثي تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121190,'eastern-region','قصر خزام الاثري','Khuzam Palace','khuzam-palace-ksr-khzam-alathry','["التراث والثقافة"]','["heritage"]','قصر خزام أحد قصور منطقة الأحساء شرقي السعودية.','<div class="texte" > <p>قصر خزام أحد قصور منطقة الأحساء شرقي السعودية. بني هذا القصر في المدخل الجنوبي الغربي للهفوف بحي النعاثل عام 1207 هـ - 1210 هـ في عصر الإمام سعود بن عبد العزيز الكبير،&nbsp;وتُعدّ فكرة بناءه في ذلك الموقع كحماية عسكرية من مخيمات البادية التي تستقر في ذلك الموقع في مواسم محددة من كل عام، إذ يحضر البدو الرحل إلى الأحساء لشراء مستلزماتهم. يُعتبر أصغر من قصر إبراهيم في الكوت إذ تقدر أطوال أسواره بـ 70 متر في 80 متر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121190-45130839.jpg?v=1644156694"]','https://cmsphoto.ww-cdn.com/resizeapi/1bdac70252dd45ba20fcfc9cf4ec32efb4eb4ba9/480/',25.3680422,49.5768616,'Abu Bakr As Siddiq Rd Almuallimeen Al Hofuf','','','','https://www.saudi-guide.com/eastern-region/i/60121190/khuzam-palace-ksr-khzam-alathry',1,0,'قصر خزام اثري khuzam palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121167,'eastern-region','بحيرة الاصفر بالاحساء','','bhyr-alasfr-balahsaaa','["أماكن سياحية"]','["sights"]','بحيرة الأصفر هي بحيرة تقع في العمران شرق الأحساء بالسعودية، وتعتبر أكبر تجمع مائي في منطقة الخليج، وهي الوحيدة في المملكة من نوعها والتي تعيش فيها حياة...','<div class="texte" > <p>بحيرة الأصفر هي بحيرة تقع في العمران شرق الأحساء بالسعودية، وتعتبر أكبر تجمع مائي في منطقة الخليج، وهي الوحيدة في المملكة من نوعها والتي تعيش فيها حياة فطرية متكاملة،&nbsp;كانت البحيرة تسمى سابقاً ببحيرة هجر،&nbsp;للبحيرة أهمية كبيرة فهي تستوعب المياه الزائدة من الأمطار الغزيرة وتحمي المنطقة من المستنقعات عبر المصارف المفتوحة، كما أنها مصدر رزق للأهالي ومصدراً للحشائش التي تستخدم أعلافاً للمواشي وكذلك للأسماك الصغيرة، وبعض النباتات التي تستخدم في عمليات التصنيع كنبات الأسل، إلى جانب ذلك إنها كانت تعتبر بيئة طبيعية حاضنة لكثير من الحيوانات والطيور المقيمة والمهاجرة، وتعتبر بحيرة الأصفر بواحة الأحساء البحيرة الوحيدة في المملكة التي تعيش فيها حياة فطرية متكاملة، في فبراير 2019، أعلنت وزارة البيئة السعودية عن تحويل البحيرة إلى محمية طبيعية. ويأتي تحويلها بغرض تأهيلها للدخول في قائمة التراث العالمي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121167-45130838.jpg?v=1644156671"]','https://cmsphoto.ww-cdn.com/resizeapi/78ba6ca8465079f4a9fdfb76ac12c512e41df799/480/',25.5665192,49.8332965,'العمران الأحساء المنطقة الشرقية','','','','https://www.saudi-guide.com/eastern-region/i/60121167/bhyr-alasfr-balahsaaa',1,0,'بحيره اصفر بالاحساء اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121165,'eastern-region','مدينة الملك عبدالله للتمور - الأحساء','King Abdullah City for dates','king-abdullah-city-dates-mdyn-almlk-aabdallh-lltmor-alahsaaa','["أماكن سياحية"]','["sights"]','مدينة الملك عبدالله للتمور بالأحساء صرح متخصص في صناعة وتسويق التمور، ويعكس مكانة الأحساء كأكبر واحة نخيل في العالم.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121165-45137689.jpg?v=1644231280"]','https://cmsphoto.ww-cdn.com/resizeapi/709040d5a740b4873a65861e7f2944b189aecbb0/480/',25.3767948,49.777894,'SA Al-Ahsa Eastern Province','','','','https://www.saudi-guide.com/eastern-region/i/60121165/king-abdullah-city-dates-mdyn-almlk-aabdallh-lltmor-alahsaaa',1,0,'مدينه ملك عبدالله للتمور احساء king abdullah city for dates اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121164,'eastern-region','حديقة الطرف النموذجية','Al-Taraf Model Zoo','al-taraf-model-zoo-hdyk-altrf-alnmothgy','["أماكن سياحية"]','["sights"]','حديقة الطرف النموذجية أو حديقة الحيوان بالأحساء هي حديقة، تشمل العديد من الحيوانات مثل الحيونات المفترسة كالأسد، والنمر، والأليفة مثل الزرافة، والماعز...','<div class="texte" > <p>حديقة الطرف النموذجية أو حديقة الحيوان بالأحساء هي حديقة، تشمل&nbsp;العديد من الحيوانات مثل الحيونات المفترسة كالأسد، والنمر، والأليفة مثل الزرافة، والماعز الجبلي، والغزلان، والطيور الجارحة مثل الصقر، والنسر، والداجنة مثل البجع، والحمام، والبط، كما يوجد بيت للزواحف، ويعيش في الحديقة التمساح والثعابين،&nbsp;وتضم الحديقة بعض ألعاب الأطفال، كما تضم العديد من النوافير والشلالات الاصطناعية في وسط أشجار النخيل، والمساحات الخضراء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121164-45130825.jpg?v=1644156450"]','https://cmsphoto.ww-cdn.com/resizeapi/6ebb22525ccb61910fba009219704aff337ca162/480/',25.3666349,49.7224829,'SA Al Tarf Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121164/al-taraf-model-zoo-hdyk-altrf-alnmothgy',1,0,'حديقه طرف نموذجيه al taraf model zoo اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121163,'eastern-region','مدينة جواثا السياحية بالأحساء','Jawatha Park','jawatha-park-mdyn-goatha-alsyahy-balahsaaa','["أماكن سياحية"]','["sights"]','مدينة جواثا السياحية بالأحساء هي مدينة ترفيهية بالقرب من مسجد جواثا التاريخي وتحتوي المدينة على العديد من الانشطة الترفيهية المتنوعة.','<div class="texte" > <p>مدينة جواثا السياحية بالأحساء هي مدينة ترفيهيه بالقرب من مسجد جواثا التاريخي والذي صليت فيه ثاني جمعة بالإسلام وتحتوي المدينة على العديد من الانشطة الترفيهيه للصغار والكبار مثل مدينة الألعاب نادي الطيران الشراعي ونادي الكارتنيج ونادي البينتبول وبحرة وقوارب، وتحتوي مدينة جواثا السياحية علي سوق (هجر التراثي)، ومساحات لاقامة الفعاليات الحية والتراثية والثقافية بالإضافة لمساحات للتخييم الشتوي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121163-45130822.jpg?v=1644156429"]','https://cmsphoto.ww-cdn.com/resizeapi/2d026f71dc96548d10672dcb6e5ec0021ea671f0/480/',25.4700081,49.6785522,'Juatha Al Kulabiyah Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121163/jawatha-park-mdyn-goatha-alsyahy-balahsaaa',1,0,'مدينه جواثا سياحيه بالاحساء jawatha park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121161,'eastern-region','جبل القارة','Al-Qara Hill','al-qara-hill-gbl-alkar','["أماكن سياحية"]','["sights"]','جبل القارة ويُعرَف أيضاً بجبل الشبعان يقع بين قرية التويثير وقرية القارة بمحافظة الأحساء، في المنطقة الشرقية من المملكة العربية السعودية.','<div class="texte" > <p>جبل القارة ويُعرَف أيضاً بجبل الشبعان يقع بين قرية التويثير وقرية القارة بمحافظة الأحساء، في المنطقة الشرقية من المملكة العربية السعودية،&nbsp;يُعد الجبل من أبرز المعالم السياحية الطبيعية في الأحساء وقد سُجل في لائحة التراث العالمي عام 2018م بعد ضم واحة الأحساء إلى اللائحة،&nbsp;يبعد الجبل مسافة 15 كيلومتراً شرق مدينة الهفوف،&nbsp;ويحتوي على كهوفٍ أو ما يسمى بالمغاراتِ بين أهالي الأحساء،&nbsp;تتميز بعض مغاراته مثل مغارة النشاب بأن لها درجة حرارة معتدلة شبه ثابتة طوال العام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121161-45130819.jpg?v=1644156393"]','https://cmsphoto.ww-cdn.com/resizeapi/2053c6382198695ecac09da4774ffdc950ca989a/480/',25.4114832,49.6928144,'Al-Qara Hill Alqourhah Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121161/al-qara-hill-gbl-alkar',1,0,'جبل قاره al qara hill اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121103,'eastern-region','مصنع الفخار ( دوغة الغراش )','Pottery Shop','pottery-shop-msnaa-alfkhar-dogh-alghrash','["أماكن سياحية"]','["sights"]','يتميز دوغة الغراش بطبعه المعماري القديم، حيث يقع المنزل بين النخيل، والجبل، والماء، حيث يحتوي صناعة الفخار بأنوعها المختلفه.','<div class="texte" > <p>يتميز دوغة الغراش بطبعه المعماري القديم، حيث يقع المنزل بين النخيل، والجبل، والماء، حيث يحتوي صناعة الفخار بأنوعها المختلفه، وتتم صناعة المقتنيات يدويًا،&nbsp;تعتبر دوغة الغراش معمل يتم فيه صناعة الأواني الفخارية يدوياً من الطين، ويتم فيه حرق الخزف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121103-45130818.jpg?v=1644156370"]','https://cmsphoto.ww-cdn.com/resizeapi/e846a130cf078b6f81354ff75e95b721b36e1066/480/',25.4120218,49.6836004,'CM6M+RC5 Alqourhah Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121103/pottery-shop-msnaa-alfkhar-dogh-alghrash',1,0,'مصنع فخار ( دوغه غراش ) pottery shop اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121100,'eastern-region','حديقة الأسود الافريقية بالحليلة','','hdyk-alasod-alafryky-balhlyl','["أماكن سياحية"]','["sights"]','حديقة الأسود الأفريقية بالحليلة حديقة حيوانات تتيح للزوار مشاهدة الأسود الأفريقية عن قرب ضمن أجواء طبيعية مفتوحة.','<div class="texte" > <p>حديقة حيوان.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121100-45137686.jpg?v=1644231261"]','https://cmsphoto.ww-cdn.com/resizeapi/e0e2795c0a77f359d6b924626ba5e6afc2efd890/480/',25.4235804,49.6685663,'SA الأحساء المنطقة الشرقية','','','','https://www.saudi-guide.com/eastern-region/i/60121100/hdyk-alasod-alafryky-balhlyl',1,0,'حديقه اسود افريقيه بالحليله اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121099,'eastern-region','مطعم زمان لوّل السياحي','','mtaam-zman-lo-l-alsyahy','["أماكن سياحية"]','["sights"]','مطعم وسط نخيل الاحساء الجميلة يتميز بجمال تصميمه ويقدم الاكل الشعبي الأحسائي وكذلك المشويات والمقبلات بجلسات خارجية مفتوحة وجلسات مغلقة لمزيد من الخصوصية.','<div class="texte" > <p>مطعم وسط نخيل الاحساء الجميلة&nbsp;يتميز بجمال تصميمه ويقدم الاكل الشعبي الأحسائي وكذلك المشويات والمقبلات بجلسات خارجية&nbsp;مفتوحة وجلسات مغلقة&nbsp;لمزيد من الخصوصيه كما يوفر المطعم جلسات كبيرة وواسعة للولائم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121099-45137680.jpg?v=1644231227"]','https://cmsphoto.ww-cdn.com/resizeapi/b2fc9068eb369255e0f5393322c14477dfe72d58/480/',25.3872089,49.6249491,'عين اللويمي طريق ترابي Banimaan','','','','https://www.saudi-guide.com/eastern-region/i/60121099/mtaam-zman-lo-l-alsyahy',1,0,'مطعم زمان لول سياحي اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121094,'eastern-region','عين أم سبعة','','aayn-am-sbaa','["أماكن سياحية"]','["sights"]','عين أم سبعة أو عين مُحلّم نبع مائي عذب، تقع في شمال مدينة المبرز بالقرب من قرية القرين بمحافظة الأحساء شرق المملكة العربية السعودية.','<div class="texte" > <p>عين أم سبعة أو عين مُحلّم نبع مائي عذب، يقدر دفقها بعشرين الف جالون في الدقيقة، تقع في شمال مدينة المبرز بالقرب من قرية القرين بمحافظة الأحساء شرق السعودية،&nbsp;وهي أحد المواقع التي يقصدها السكان والزوار من الخليج العربي في محافظة الأحساء للأغراض السياحية والعلاجية، ومن أهم مصادر المياه فيها،&nbsp;تصل مساحة العين إلى 1200 م3، وتبلغ حرارة مياهها في الوسط 104 درجة مئوية، وعند الأطراف تصل إلى 101 درجة مئوية.</p> <p>تعتبر عين أم سبعة المكان الأمثل للسياحة الترفيهية والسياحة العلاجية، حيث طبيعة المكان والمناخ الجيد واتساع واحات النخيل حولها والهواء النقي والحدائق الخضراء،&nbsp;مما جعلها قبلة سياحية على خريطة السياحة الأحسائية من داخل السعودية ومن دول الخليج العربي كافة، وتبلغ درجة حرارة المياه في أطراف بحيرة عين أم سبعة 101 درجة مئوية، في حين تبلغ حرارة مياهها وسط البحيرة 104 درجة مئوية. تمتاز مياه البحيرة بالدفء، حيث يقصدها الكثير من الزوار في فصل الشتاء للاستماع بطبيعة مياهها الحارة وقضاء أوقات الاستجمام في الطبيعة وبين مزارع النخيل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121094-45130816.jpg?v=1644156346"]','https://cmsphoto.ww-cdn.com/resizeapi/ac923e259add36d4536ba5750f2a414be4e9a23b/480/',25.4676787,49.5816784,'عين أم سبعة الأحساء المنطقة الشرقية','','','','https://www.saudi-guide.com/eastern-region/i/60121094/aayn-am-sbaa',1,0,'عين ام سبعه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121092,'eastern-region','عين الحارة','Ain Al-Harrah','ain-al-harrah-aayn-alhar','["أماكن سياحية"]','["sights"]','عين الحارة هي أحد عيون محافظة الأحساء السعودية، تقع في مدينة المبرز وهي نبع متوسط الحجم، سميت بذلك لسخونة الماء الذي يخرج منها.','<div class="texte" > <p>عين الحارة هي أحد عيون محافظة الأحساء السعودية، تقع في مدينة المبرز وهي نبع متوسط الحجم، سميت بذلك لسخونة الماء الذي يخرج منها. والعين قريبة من مقبرة المبرز. يذكر ان ماءها يقدر بعشرين ألف جالون في الدقيقة، ويصل ماؤها إلى سطح الأرض عبر 3 فوهات مكونا بحيرة كبيرة، أقامت عليها هيئة الري والصرف مضخات كبيرة بعد أن قل ماؤها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121092-45116844.jpg?v=1643991629"]','https://cmsphoto.ww-cdn.com/resizeapi/4fee0efdbe871fae1ac4ac3c3786c8a53629b7e1/480/',25.4219974,49.5870927,'Ain Al-Harrah Madinatal Mubarraz Al Mubarraz','','','','https://www.saudi-guide.com/eastern-region/i/60121092/ain-al-harrah-aayn-alhar',1,0,'عين حاره ain al harrah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121090,'eastern-region','سوق القيصرية الإحساء','','sok-alkysry-alahsaaa','["أماكن سياحية"]','["sights"]','سوق القيصرية هو سوق تاريخي يقع في الأحساء شرق السعودية، ويقع وسط مدينة الهفوف في الجهة الغربية لحي الرفعة الأوسط.','<div class="texte" > <p>سوق القيصرية هو سوق تاريخي يقع في الأحساء شرق السعودية، ويقع سوق القيصرية وسط مدينة الهفوف، في الجهة الغربية لحي الرفعة الأوسط، ويُفتح مباشرة على شارع واسع يخترق وسط المدينة من الشمال للجنوب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121090-45116842.jpg?v=1643991611"]','https://cmsphoto.ww-cdn.com/resizeapi/887f9f0bf2620bb7904cd17dce15f6a22b423322/480/',25.3759045,49.5890805,'Al Rafaa North Al Hofuf Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121090/sok-alkysry-alahsaaa',1,0,'سوق قيصريه احساء اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121087,'eastern-region','مركز الابداع الحرفي','Creative Handicrafts Center','creative-handicrafts-center-mrkz-alabdaaa-alhrfy','["أماكن سياحية"]','["sights"]','مركز الإبداع الحرفي وجهة تراثية تعرّف الزوار بالحرف اليدوية التقليدية في المنطقة الشرقية.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121087-45137669.jpg?v=1644231204"]','https://cmsphoto.ww-cdn.com/resizeapi/2425bd86c282337f3f12c07b0ad6801abfef560e/480/',25.3882848,49.5567643,'9HQ4+8P6 Government Departments Complex 1st Al Mubarraz','','','','https://www.saudi-guide.com/eastern-region/i/60121087/creative-handicrafts-center-mrkz-alabdaaa-alhrfy',1,0,'مركز ابداع حرفي creative handicrafts center اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121084,'eastern-region','أسواق القرية الشعبية','','asoak-alkry-alshaaby','["أماكن سياحية"]','["sights"]','يشمل هذا المجمّع متاجر للملابس والأثاث والأدوات المنزلية بالإضافة لقاعة طعام خارجية في فناء.','<div class="texte" > <p>يشمل هذا المجمّع متاجر للملابس والأثاث والأدوات المنزلية بالإضافة لقاعة طعام خارجية في فناء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121084-45116841.jpg?v=1643991594"]','https://cmsphoto.ww-cdn.com/resizeapi/018295837cf4ba2b500edf6b1ecc23c828c4397b/480/',25.3885291,49.5475275,'Aynnajm Al Mubarraz Al-Ahsa','','','','https://www.saudi-guide.com/eastern-region/i/60121084/asoak-alkry-alshaaby',1,0,'اسواق قريه شعبيه اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121062,'eastern-region','منتزه الملك عبدالله البيئي','King Abdullah Environmental Park','king-abdullah-environmental-park-mntzh-almlk-aabdallh-albyyy','["أماكن سياحية"]','["sights"]','ملاعب كرة قدم وطريق بتصميم متاهة ومقاهٍ في حدائق تتوسطها بحيرة مع عروض ليزر ضوئية في المساء.','<div class="texte" > <p>ملاعب كرة قدم وطريق بتصميم متاهة ومقاهٍ في حدائق تتوسطها بحيرة مع عروض ليزر ضوئية في الليل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121062-45116831.jpg?v=1643991553"]','https://cmsphoto.ww-cdn.com/resizeapi/d52e465a22b507aa206ee40a282cbe652a431283/480/',25.3214566,49.5583559,'8HC5+H8Q Al Hofuf South Al Hofuf','','','','https://www.saudi-guide.com/eastern-region/i/60121062/king-abdullah-environmental-park-mntzh-almlk-aabdallh-albyyy',1,0,'منتزه ملك عبدالله بيئي king abdullah environmental park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121058,'makkah-region','الحكير تايم','ALHOKAIR TIME','alhokair-time-alhkyr-taym','["أماكن سياحية"]','["sights"]','الحكير تايم مدينة ألعاب متكاملة في حي الزاهر بمكة المكرمة، تقدم أنشطة ترفيهية متنوعة تناسب مختلف أفراد الأسرة.','<div class="texte" > <p>مدينة ألعاب متكاملة</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121058-44887565.jpg?v=1642351702"]','https://cmsphoto.ww-cdn.com/resizeapi/8523d07e4e35e122629ca827e780e54721ab8e43/480/',21.4475657,39.8076851,'Al Madinah Al Munawarah Rd Az Zahir Makkah','','','','https://www.saudi-guide.com/makkah-region/i/60121058/alhokair-time-alhkyr-taym',1,0,'حكير تايم alhokair time اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120970,'makkah-region','جامع الراجحي','Aisha Al Rajhi Mosque','aisha-al-rajhi-mosque-gamaa-alraghy','["معالم إسلامية"]','["islamic"]','جامع عائشة الراجحي من المساجد الكبيرة في مكة المكرمة، يتميز بعمارته ذات الطراز المملوكي وزخارفه البديعة، ويقع على طريق إبراهيم الخليل.','<div class="texte" > <p>جامع عائشة الراجحي&nbsp;بمكة&nbsp;هو&nbsp;مسجد&nbsp;كبير تمتلكه شركة سليمان بن عبد العزيز الراجحي الوقفية التابعة لشركة أوقاف سليمان الراجحي القابضة تم افتتاحه في&nbsp;22 شعبان،&nbsp;1434 هـ&nbsp;بحضور أمير&nbsp;منطقة مكة المكرمة&nbsp;الأمير خالد الفيصل.</p> <p>يتميز بناء الجامع بعمارة مملوكية الطراز، تزينت جدرانه بزخارف مملوكية بديعة كما يتميز الجامع باستخدام نظم تقنية التحكم الإلكتروني الشامل لجميع الوحدات المركزية والتشغيلية والمجهّزة بمراقبة كل مرافق الجامع .والمحافظة عليها</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120970-44887400.jpg?v=1642349918"]','https://cmsphoto.ww-cdn.com/resizeapi/33b44dfc43d5458719b4a6f1898d6c0fe0618963/480/',21.3817017,39.8739757,'طريق ابراهيم الخليل، An Naseem Makkah','','','','https://www.saudi-guide.com/makkah-region/i/60120970/aisha-al-rajhi-mosque-gamaa-alraghy',1,0,'جامع راجحي aisha al rajhi mosque معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120807,'makkah-region','متحف العمودي','Alamoudi Museum','alamoudi-museum-mthf-alaamody','["التراث والثقافة"]','["heritage"]','متحف العمودي من المتاحف في مكة المكرمة، يقع على طريق مكة – جدة السريع، ويمثل محطة ثقافية للزوار المهتمين بالتاريخ والتراث.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120807-44887561.jpg?v=1642351674"]','https://cmsphoto.ww-cdn.com/resizeapi/a3eff1f9915194baeaeae8e77db48a5e3ef13bbb/480/',21.3531099,39.6284985,'Makkah - Jeddah Hwy Al Hamra Umm Al Jud Makkah','','','','https://www.saudi-guide.com/makkah-region/i/60120807/alamoudi-museum-mthf-alaamody',1,0,'متحف عمودي alamoudi museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120806,'makkah-region','معرض عمارة الحرمين الشريفين','Exhibition Of The Two Holy Mosques Architecture','exhibition-two-holy-mosques-architecture-maard-aamar-alhrmyn-alshryfyn','["التراث والثقافة"]','["heritage"]','معرض عمارة الحرمين الشريفين بمكة المكرمة يوثق تطور عمارة المسجد الحرام والمسجد النبوي عبر العصور، ويضم مجسمات ومخطوطات وقطعًا أثرية وصورًا نادرة.','<div class="texte" > <p>متحف الحرمين الشريفين&nbsp;أحد متاحف&nbsp;منطقة مكة المكرمة، ويتبع&nbsp;الرئاسة العامة لشؤون المسجد الحرام والمسجد النبوي،&nbsp;تأسس في عام&nbsp;1999، وهو معرض يعنى&nbsp;بالحرمين الشريفين&nbsp;والتطور الذي شهدته عمارتهما على مدى العصور، ويتكون المعرض من سبع قاعات تشتمل على مجسمين للحرمين الشريفين وعدد من المقتنيات المختلفة من مخطوطات ونقوش كتابية وقطع أثرية ثمينة ومجسمات معمارية وصور فوتوغرافية نادرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120806-44899837.jpg?v=1642438281"]','https://cmsphoto.ww-cdn.com/resizeapi/962cca08419e4b641ee98b5204347495dc8a9dfb/480/',21.433782,39.754361,'Old Makkah Jeddah Rd Al Hamra Umm Al Jud Makkah','','','','https://www.saudi-guide.com/makkah-region/i/60120806/exhibition-two-holy-mosques-architecture-maard-aamar-alhrmyn-alshryfyn',1,0,'معرض عماره حرمين شريفين exhibition of the two holy mosques architecture تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120763,'makkah-region','متحف مكة للتراث والآثار','Mecca Museum','mecca-museum-mthf-mk-lltrath-oalathar','["التراث والثقافة"]','["heritage"]','متحف مكة للتراث والآثار في قصر الزاهر التاريخي الذي شُيّد بأمر من الملك عبدالعزيز، ويعرض جوانب من تاريخ مكة المكرمة وتراثها بعد ترميمه ترميمًا شاملًا.','<div class="texte" > <p>متحف مكة&nbsp;(متحف قصر الزاهر)، أحد متاحف&nbsp;منطقة مكة المكرمة&nbsp;بدأ العمل في تشييد هذا قصر متحف مكة عام&nbsp;1365 هـ&nbsp;1946&nbsp;بأمر من&nbsp;الملك عبد العزيز، واستغرق بناء القصر سبع سنوات حيث فرغ العمل منه عام&nbsp;1372 هـ&nbsp;1952، واستخدم مدة من الزمن قصراً للضيافة ثم منح عام&nbsp;1378 هـ&nbsp;لوزارة المعارف آنذاك التي حولته ليكون مقرا لمدرسة الزاهر المتوسطة، وأعادت توظيف غرفه وصالاته إلى فصول دراسية، واستمر استخدامه حتى عام&nbsp;1398 هـ، ثم سلم المبنى لوكالة الآثار والمتاحف حيث تولت الوكالة ترميمه ترميماً شاملاً وإعادته إلى الحالة المعمارية التي كان عليها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120763-44900098.jpg?v=1642439402"]','https://cmsphoto.ww-cdn.com/resizeapi/d7107dcddd94101df9fbcc91340e43aaaa5c1009/480/',21.4461466,39.807936,'Makkah Al Madinah Munawawrah Rd Az Zahir Makkah','','','','https://www.saudi-guide.com/makkah-region/i/60120763/mecca-museum-mthf-mk-lltrath-oalathar',1,0,'متحف مكه للتراث والاثار mecca museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120762,'makkah-region','متحف برج الساعة','Clock Tower Museum','clock-tower-museum-mthf-brg-alsaaa','["التراث والثقافة"]','["heritage"]','متحف برج الساعة متحف فلكي في برج الساعة بمكة المكرمة، يتكون من أربعة أدوار وشرفة تطل على المسجد الحرام.','<div class="texte" > <p>متحف برج الساعة&nbsp;هو متحف&nbsp;فلكي&nbsp;يقع في شرفة&nbsp;برج الساعة&nbsp;بمكة المكرمة، يتكون المتحف من أربعة أدوار&nbsp;بالإضافة إلى الشرفة التي تطل على&nbsp;المسجد الحرام، وتقوم على تشغيله&nbsp;مؤسسة محمد بن سلمان بن عبدالعزيز&nbsp;"مسك الخيرية"، افتتح في&nbsp;رمضان&nbsp;1440هـ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120762-44900129.jpg?v=1642439563"]','https://cmsphoto.ww-cdn.com/resizeapi/1be552983f91b0a22e343c45c8bcc57ec8701c71/480/',21.4182719,39.8254191,'King Abd Al Aziz وقف Makkah','','','','https://www.saudi-guide.com/makkah-region/i/60120762/clock-tower-museum-mthf-brg-alsaaa',1,0,'متحف برج ساعه clock tower museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120760,'makkah-region','متحف التراث الإنساني','Museum of Human Heritage','museum-human-heritage-mthf-altrath-alansany','["التراث والثقافة"]','["heritage"]','متحف التراث الإنساني في مكة المكرمة يجسد أحداث تاريخ الإنسان وتفاصيل حياته، ويضم قطعًا أثرية وتحفًا نادرة ونقودًا وأدوات من الحياة اليومية قديمًا.','<div class="texte" > <p>يلعب متحف التراث الإنساني دوراً هاماً في بناء المشهد التاريخي وتجسيد أحداث تاريخ الإنسان وتفاصيل حياته منذ قديم الزمان، ويضم العديد من القطع الأثرية القديمة من تحف نادرة ونقود وكذلك أدوات كانت تستخدم في الحياة اليومية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120760-44900152.jpg?v=1642439717"]','https://cmsphoto.ww-cdn.com/resizeapi/dc0921d7cadc4ccb0d993f29cb0dff9c6365b6f6/480/',21.404524,39.8789894,'CV3H+RH5 Al Mursalat Mecca','','','','https://www.saudi-guide.com/makkah-region/i/60120760/museum-human-heritage-mthf-altrath-alansany',1,0,'متحف تراث انساني museum of human heritage تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120637,'makkah-region','قصر بن سليمان التاريخي','Qasr Bin Sulaiman historical','qasr-bin-sulaiman-historical-ksr-bn-slyman-altarykhy','["معالم إسلامية"]','["islamic"]','قصر بن سليمان التاريخي من المباني التاريخية في حي جرول بمكة المكرمة، ويعكس طابع العمارة التقليدية في المدينة.','<div class="texte" > <p>قصر بن سليمان التاريخي يقع في حي جرول بمكة المكرمة، وهو قصر الشيخ عبدالله بن سليمان الحمدان أول وزير للمالية في عهد الملك عبدالعزيز. ويُعد من المباني التاريخية المرتبطة بمرحلة تأسيس الدولة السعودية الحديثة في مكة المكرمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120637-44900238.jpg?v=1642440407"]','https://cmsphoto.ww-cdn.com/resizeapi/0b895b54a83c2b65e5883956c4b060d2c7d7c66f/480/',21.4295324,39.8159669,'8091 Beir Tawa Jarwal','','','','https://www.saudi-guide.com/makkah-region/i/60120637/qasr-bin-sulaiman-historical-ksr-bn-slyman-altarykhy',1,0,'قصر بن سليمان تاريخي qasr bin sulaiman historical معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120635,'makkah-region','غار ثور','Ghar Thowr','ghar-thowr-ghar-thor','["معالم إسلامية"]','["islamic"]','غار ثور في جبل ثور جنوب مكة المكرمة، هو الغار الذي أوى إليه النبي محمد ﷺ وأبو بكر الصديق في طريقهما إلى المدينة المنورة خلال رحلة الهجرة.','<div class="texte" > <p>غار ثور&nbsp;يقع في الجهة الشمالية من&nbsp;جبل ثور&nbsp;جنوب&nbsp;مكة المكرمة، وعلى بعد نحو أربعة كيلو مترات في الجهة الجنوبية من&nbsp;المسجد الحرام، وهو الغار الذي أوى إليه النبي&nbsp;محمد&nbsp;ﷺ&nbsp;وأبو بكر الصديق&nbsp;وهما في طريقهما إلى&nbsp;المدينة المنورة&nbsp;في رحلة&nbsp;الهجرة النبوية، يبلغ ارتفاعه 760 متراً عن سطح البحر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120635-44901707.jpg?v=1642450729"]','https://cmsphoto.ww-cdn.com/resizeapi/d5d08b32f1838718152d87a4218a657e040fdce1/480/',21.377189,39.8497564,'Al Hijrah Mecca Makkah Al-Mukarramah','','','','https://www.saudi-guide.com/makkah-region/i/60120635/ghar-thowr-ghar-thor',1,0,'غار ثور ghar thowr معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120633,'makkah-region','مسجد عائشة','Masjid Ayesha','masjid-ayesha-msgd-aaaysh','["معالم إسلامية"]','["islamic"]','مسجد عائشة أو مسجد التنعيم من مساجد مكة المكرمة، ومنه يحرم أهل مكة للعمرة، وقد بُني في الموضع الذي أحرمت منه أم المؤمنين عائشة رضي الله عنها.','<div class="texte" > <p>مسجد التنعيم&nbsp;أو&nbsp;مسجد السيدة عائشة&nbsp;أحد مساجد&nbsp;مكة المكرمة، يقع في الجزء الغربي من مكة المكرمة على مسافة 7 كم عن الحرم المكي الشريف، ومنه يحرم أهالي مكة للحج والعمرة، اكتسب شهرته من كونه بُني في الموضع الذي أحرمت منه&nbsp;أم المؤمنين عائشة بنت أبي بكر&nbsp;بالعمرة في&nbsp;حجة الوداع&nbsp;سنة 9 للهجرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120633-44901797.jpg?v=1642451047"]','https://cmsphoto.ww-cdn.com/resizeapi/2bbaf7f5cc86496a136b9629a6572ba8360ccb7e/480/',21.4676053,39.8012731,'Mecca At Taniem Makkah Al-Mukarramah','','','','https://www.saudi-guide.com/makkah-region/i/60120633/masjid-ayesha-msgd-aaaysh',1,0,'مسجد عائشه masjid ayesha معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120631,'makkah-region','مسجد الجن','Jinn Mosque','jinn-mosque-msgd-algn','["معالم إسلامية"]','["islamic"]','مسجد الجن، ويُعرف أيضًا بمسجد الحرس، مسجد تاريخي قرب المسجد الحرام بمكة المكرمة، ويرتبط بقصة استماع الجن للنبي ﷺ.','<div class="texte" > <p>مسجد الجن وكان يطلق عليه مسجد الحرس هو مسجدٌ تاريخيٌّ يقع في&nbsp;مكة المكرمة، في حي الغزة بالقرب من&nbsp;المسجد الحرام، سمي بهذا الاسم لأن العسس يجتمعون عنده ليلاً، ويقال الموضع الذي خطه&nbsp;الرسول&nbsp;صلى الله عليه وسلم لابن مسعود ليلة استمع إليه الجن، وأن&nbsp;الجن&nbsp;بايعوا الرسول صلى الله عليه وسلم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120631-44901872.jpg?v=1642451536"]','https://cmsphoto.ww-cdn.com/resizeapi/17ed0d01f27cd6da870b99dfaee135daef4a10bf/480/',21.4334258,39.8289381,'8464 Al Masjid Al Haram Rd As Sulaymaniyyah','','','','https://www.saudi-guide.com/makkah-region/i/60120631/jinn-mosque-msgd-algn',1,0,'مسجد جن jinn mosque معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120607,'makkah-region','قصر السقاف التاريخي','Al Sakkaf Palace','al-sakkaf-palace-ksr-alskaf-altarykhy','["معالم إسلامية"]','["islamic"]','قصر السقاف التاريخي في مكة المكرمة كان مقرًا للحكم في عهد الملك عبدالعزيز والملك سعود، ويتميز بطابع معماري إسلامي وزخارف فنية مميزة.','<div class="texte" > <p>قصر السقاف&nbsp;هو قصر تاريخي يقع في&nbsp;مكة المكرمة&nbsp;غرب&nbsp;المملكة العربية السعودية، وقد كان مقراً للدولة ومركزاً للحكم في عهد&nbsp;الملك عبدالعزيز&nbsp;والملك سعود بن عبدالعزيز،&nbsp;قصر السقاف من المباني القديمة بمكة حاملاً طابعاً إسلامياً في المعمار لاحتوائه على الكثير من العناصر الفنية والزخرفات الإسلامية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120607-44901902.jpg?v=1642451650"]','https://cmsphoto.ww-cdn.com/resizeapi/90a1610ae520e01b5a5bd88c8cb22555dec91d22/480/',21.4399521,39.8386332,'CRQQ+XFJ Al Jummayzah Mecca','','','','https://www.saudi-guide.com/makkah-region/i/60120607/al-sakkaf-palace-ksr-alskaf-altarykhy',1,0,'قصر سقاف تاريخي al sakkaf palace معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120605,'makkah-region','مسجد بيعة العقبة','Mezquita de Bay''ah','mezquita-de-bay-ah-msgd-byaa-alaakb','["معالم إسلامية"]','["islamic"]','مسجد البيعة أو مسجد العقبة بمكة المكرمة، بناه أبو جعفر المنصور في الموضع الذي بايع فيه الأنصار النبي محمد ﷺ بيعة العقبة.','<div class="texte" > <p>مسجد البيعة&nbsp;ويطلق عليه مسجد العقبة، وهو&nbsp;مسجد&nbsp;بناه&nbsp;أبو جعفر المنصور&nbsp;سنة&nbsp;144هـ&nbsp;في المكان الذي اجتمع فيه النبي&nbsp;محمد&nbsp;مع&nbsp;الأنصار&nbsp;حيث بايعوه&nbsp;بيعة العقبة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120605-44902054.jpg?v=1642452407"]','https://cmsphoto.ww-cdn.com/resizeapi/86f24616d3322d5be0a217cfc7f9382a8eb52abc/480/',21.424687,39.8674858,'CVF8+VXH Al Mashair Mecca','','','','https://www.saudi-guide.com/makkah-region/i/60120605/mezquita-de-bay-ah-msgd-byaa-alaakb',1,0,'مسجد بيعه عقبه mezquita de bay''ah معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120604,'makkah-region','مسجد نمره','Masjid-e-Nimrah','masjid-e-nimrah-msgd-nmrh','["معالم إسلامية"]','["islamic"]','مسجد نمرة من أهم معالم مشعر عرفات، يصلي فيه الحجاج الظهر والعصر جمعًا وقصرًا يوم عرفة اقتداءً بالنبي محمد ﷺ.','<div class="texte" > <p>مسجد نمرة&nbsp;بفتح النون وكسر الميم وسكونها، هو مسجد وواحد من أهم المعالم في مشعر&nbsp;عرفات، وبه يصلي عشرات الآلاف من ضيوف الرحمن حجاج&nbsp;البيت الحرام&nbsp;صلاة الظهر&nbsp;وصلاة العصر&nbsp;في&nbsp;يوم عرفة&nbsp;جمعا وقصرا اقتداء&nbsp;بالنبي محمد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120604-44902067.jpg?v=1642452502"]','https://cmsphoto.ww-cdn.com/resizeapi/61d67a2463123406df0c076b225cfcd2db573e55/480/',21.3528786,39.96675,'9X38+5M5 Al Mashair Mecca','','','','https://www.saudi-guide.com/makkah-region/i/60120604/masjid-e-nimrah-msgd-nmrh',1,0,'مسجد نمره masjid e nimrah معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120601,'makkah-region','المسجد الحرام','Masjid al-Haram','masjid-al-haram-almsgd-alhram','["معالم إسلامية"]','["islamic"]','المسجد الحرام في قلب مكة المكرمة أعظم مساجد الإسلام وأقدسها، تتوسطه الكعبة المشرفة قبلة المسلمين في صلاتهم، وإليه يحجون ويعتمرون.','<div class="texte" > <p>المسجد الحرام&nbsp;هو أعظم مسجد في&nbsp;الإسلام&nbsp;ويقع في قلب مدينة&nbsp;مكة&nbsp;غرب&nbsp;المملكة العربية السعودية، تتوسطه&nbsp;الكعبة&nbsp;المشرفة التي هي أول بيت وضع للناس على وجه الأرض ليعبدوا الله فيه تبعاً للعقيدة الإسلامية، وهذه هي أعظم وأقدس بقعة على وجه الأرض عند&nbsp;المسلمين، والمسجد الحرام هو&nbsp;قبلة&nbsp;المسلمين&nbsp;في صلاتهم، وإليه يحجون، سمي بالمسجد الحرام لحرمة القتال فيه منذ دخول&nbsp;النبي محمد&nbsp;إلى&nbsp;مكة المكرمة&nbsp;منتصراً، ويؤمن&nbsp;المسلمون&nbsp;أن الصلاة فيه تعادل مئة ألف صلاة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120601-44902106.jpg?v=1642452705"]','https://cmsphoto.ww-cdn.com/resizeapi/339da34e7cf99de515288f9a89eb0ce167a1c4d6/480/',21.4228714,39.8257347,'Mecca Al Haram Makkah Al-Mukarramah','','','','https://www.saudi-guide.com/makkah-region/i/60120601/masjid-al-haram-almsgd-alhram',1,0,'مسجد حرام masjid al haram معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60120599,'makkah-region','عين زبيدة','Zubaida Canal','zubaida-canal-aayn-zbyd','["معالم إسلامية"]','["islamic"]','عين زبيدة من روائع أوقاف المسلمين في مكة المكرمة، أمرت بإنشائها زبيدة زوجة الخليفة هارون الرشيد لسقيا أهل مكة والحجاج.','<div class="texte" > <p>عين زبيدة&nbsp;هي عين عذبة الماء غزيرة وإحدى روائع&nbsp;أوقاف&nbsp;المسلمين، أمرت بإنشائها الأميرة&nbsp;زبيدة&nbsp;بنت&nbsp;أبي الفضل جعفر&nbsp;بن&nbsp;أبي جعفر المنصور&nbsp;العباسية الهاشمية، زوجة&nbsp;هارون الرشيد&nbsp;وغلب عليها لقبها زبيدة وهي تتبع الهيئة العامة للأوقاف في&nbsp;السعودية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60120599-44902079.jpg?v=1642452614"]','https://cmsphoto.ww-cdn.com/resizeapi/ad48726f14b3776eec5a1fd00c901f7cb66f14df/480/',21.38807,39.9142504,'Al Mashair Makkah Makkah Al-Mukarramah','','','','https://www.saudi-guide.com/makkah-region/i/60120599/zubaida-canal-aayn-zbyd',1,0,'عين زبيده zubaida canal معالم اسلاميه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075317,'eastern-region','مجمع روفز التجاري ROOFS MALL','','mgmaa-rofz-altgary-roofs-mall','["أماكن سياحية"]','["sights"]','مجمع تجاري يضم عدة مطاعم ومقاهي راقية وذات تصميم جميل.','<div class="texte" > <p>مجمع تجاري يضم عدة مطاعم ومقاهي راقية وذات تصميم جميل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075317-45137665.jpg?v=1644231174"]','https://cmsphoto.ww-cdn.com/resizeapi/863ace5aea1d5c28af847edf3f7702d992e0b0d6/480/',26.3203421,50.2226864,'Al Khobar Alkurnaish Al-Khobar','','','','https://www.saudi-guide.com/eastern-region/i/60075317/mgmaa-rofz-altgary-roofs-mall',1,0,'مجمع روفز تجاري roofs mall اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075279,'eastern-region','قرية القصيبي','Gosaibi Village','gosaibi-village-kry-alksyby','["أماكن سياحية"]','["sights"]','تشمل هذه الساحة الخارجية متاجر لبيع الملابس والهدايا، فضلاً عن مقاهٍ وأماكن بيع آيس كريم وصالون.','<div class="texte" > <p>تشمل هذه الساحة الخارجية متاجر لبيع الملابس والهدايا، فضلاً عن مقاهٍ وأماكن بيع آيس كريم وصالون.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075279-45116837.jpg?v=1643991575"]','https://cmsphoto.ww-cdn.com/resizeapi/5ac4d493a83bbab82092aeba3f3c54d7bffc1555/480/',26.3029069,50.2222922,'Prince Turkey Street Al Yarmouk Al Khobar','','','','https://www.saudi-guide.com/eastern-region/i/60075279/gosaibi-village-kry-alksyby',1,0,'قريه قصيبي gosaibi village اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075214,'eastern-region','مركز سلطان بن عبدالعزيز للعلوم والتقنية (سايتك)','Scitech','scitech-mrkz-sltan-bn-aabdalaazyz-llaalom-oaltkny-saytk','["أماكن سياحية"]','["sights"]','مركز سلطان بن عبد العزيز للعلوم والتقنية (سايتك) هو أحد مشاريع مؤسسة الأمير سلطان بن عبد العزيز آل سعود الخيرية، ويعد من أبرز مراكز العلوم التفاعلية في المنطقة الشرقية.','<div class="texte" > <p>مركز سلطان بن عبد العزيز للعلوم والتقنية (سايتك) هو أحد مشاريع مؤسسة الأمير سلطان بن عبد العزيز آل سعود الخيرية ولقد جاءت فكرة إنشاء المركز عام 2000م حيث أمر الأمير سلطان بن عبد العزيز (رحمه الله) بإنشاء مركز علمي على غرار أحدث المراكز العلمية في العالم ليخدم فئة الطلبة والباحثين في مجالات العلوم والتقنية وجميع فئات المجتمع. نظراً لنظرة الأمير سلطان بن عبد العزيز (رحمه الله) في إهداء المركز إلى جهة تعنى بالأمور العلمية والتقنية فقد أمر بإهداءه إلى جامعة الملك فهد للبترول والمعادن في عام 2006م ، ليصبح بذلك أحد المراكز الفاعله في خدمة وتوعية المجتمع , وفي عام 2022م تم انتقال المركز إلى هيئة تطوير المنطقة الشرقية ليكمل مشروع النهضة العملية والاجتماعية والثقافية. يقع المركز على كورنيش مدينة الخبر على أرض مساحتها 21.700متر مربع و مساحة المبنى 14.100متر مربع صمم و نفذ على غرار أحدث المراكز العالمية ويشتمل على ( 4 ) قاعات عرض رئيسية تتناول مختلف المجالات العلمية والثقافيه ، و القبة العلمية " IMAX "، المرصد الفلكي، قاعة المؤتمرات (المسرح)، قاعات معارض متعددة الاستخدامات، مرافق إدارية وخدمات. يهدف المركز بصورة أساسية إلى تثقيف أفراد المجتمع-خاصة الناشئة - من خلال أسلوب تفاعلي شيق يعتمد على التعليم بالترفيه/ التعليم بالتجربة و المشاهدة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075214-65348679.jpg?v=1767551790"]','https://cmsphoto.ww-cdn.com/resizeapi/bc971dae03bac8798409aec406f24d85af57f5d7/480/',26.319249,50.2279355,'Corniche Alkurnaish Al Khobar','','https://www.visitsaudi.com/ar/eastern-province/attractions/science-and-play-collide-at-scitech','','https://www.saudi-guide.com/eastern-region/i/60075214/scitech-mrkz-sltan-bn-aabdalaazyz-llaalom-oaltkny-saytk',1,0,'مركز سلطان بن عبدالعزيز للعلوم والتقنيه (سايتك) scitech اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075182,'eastern-region','مركز الملك عبدالعزيز الثقافي العالمي - إثراء','King Abdulaziz Center for World Culture - Ithra','king-abdulaziz-center-world-culture-ithra-mrkz-almlk-aabdalaazyz-althkafy-alaaalmy-athraaa','["أماكن سياحية"]','["sights"]','مركز الملك عبد العزيز الثقافي العالمي أو إثراء هو مركز ثقافي تملكه أرامكو السعودية، ويقع بالقرب من أول موقع اكتشاف للنفط في المملكة في الظهران.','<div class="texte" > <p>مركز الملك عبد العزيز الثقافي العالمي أو إثراء هو مركز ثقافي تملكه أرامكو السعودية، ويقع على نفس الموقع الذي اكتشف فيه بئر الخير أول ينبوع للنفط في المملكة العربية السعودية بمدينة الظهران، ويأتي تصميم مركز الملك عبد العزيز الثقافي العالمي على شكل مجموعة من الحجارة المتراصة التي تضم بين جنباتها مكتبة عصرية، ومركزاً للابتكار، وواحة للصغار تشكل أول متحف من نوعه للطفل في العالم العربي، ومتحف التاريخ الطبيعي، وقاعات للفنون، ومركز الأرشيف، ويتعالى في وسطه برج المعرفة الذي يقدم البرامج التعليمية للرواد من كل الأعمار، عام 2018 تم اختياره من قبل مجلة "تايم" الأمريكية بصفته أحد أعظم 100 مكان في العالم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075182-65348648.jpg?v=1767551518"]','https://cmsphoto.ww-cdn.com/resizeapi/82f49c414e54fefe2a183e43e772cb6cb661effa/480/',26.3354262,50.1209593,'8386 Ring Rd Gharb Al Dhahran','','https://www.ithra.com/ar','','https://www.saudi-guide.com/eastern-region/i/60075182/king-abdulaziz-center-world-culture-ithra-mrkz-almlk-aabdalaazyz-althkafy-alaaalmy-athraaa',1,0,'مركز ملك عبدالعزيز ثقافي عالمي اثراء king abdulaziz center for world culture ithra اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075179,'eastern-region','معرض الطاقة بالظهران','Energy Exhibit','energy-exhibit-maard-altak-balthhran','["أماكن سياحية"]','["sights"]','معرض الطاقة بالظهران يعرض إنجازات قطاع الطاقة في المملكة عبر الماضي والحاضر، ويسلط الضوء على التحديات والفرص المستقبلية في هذا القطاع.','<div class="texte" > <p>“معرض الطاقة يعرض إنجازات الماضي والحاضر، وتحديات المستقبل”</p> <p>يعمل معرض الطاقة -معرض أرامكو السعودية للزيت سابقاً- على جذب الزّوار باستخدام التقنية الحديثة والوسائط المتنوعة، إذ يتمحور حول النفط والعلوم والطاقة والتكنولوجيا، وسيتمكن زوّاره&nbsp;من التمتع برحلة تأخذهم عبر بدايات البترول وتكونات الصخور تحت الأرض وعمليات الحفر في الصحراء، مروًرا بمصانع التكرير وحلول الطاقة البديلة للمملكة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075179-45137661.jpg?v=1644231154"]','https://cmsphoto.ww-cdn.com/resizeapi/f2db2e0484fb9de1acf5ecdf425b1132095bbed1/480/',26.3344383,50.1225929,'Saudi Aramco Dhahran Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60075179/energy-exhibit-maard-altak-balthhran',1,0,'معرض طاقه بالظهران energy exhibit اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075095,'eastern-region','الحكير تايم','Alhokair Time','alhokair-time-alhkyr-taym','["أماكن سياحية"]','["sights"]','الحكير تايم مركز ترفيهي عائلي بالمنطقة الشرقية، يضم مجموعة من الألعاب والأنشطة الترفيهية.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075095-45137656.jpg?v=1644231125"]','https://cmsphoto.ww-cdn.com/resizeapi/5a59da17464854f4ef41d1c2ec3ac41166cfca65/480/',26.2939768,50.2204176,'Al Khobar Al Shamalia Al Khobar Al-Khobar','','','','https://www.saudi-guide.com/eastern-region/i/60075095/alhokair-time-alhkyr-taym',1,0,'حكير تايم alhokair time اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075024,'eastern-region','التركي بزنس بارك','Alturki Business Park','alturki-business-park-altrky-bzns-bark','["أماكن سياحية"]','["sights"]','التركي بزنس بارك مجمع مكاتب إدارية على طريق الدمام – الظهران، يتوسطه برج من 14 طابقاً ضمن مجمع مسوّر منسّق.','<div class="texte" > <p>التركي بزنس بارك مجمع مكاتب إدارية تابع لشركة التركي القابضة على طريق الدمام – الظهران في حي الدوحة الجنوبية، ويتوسطه برج من 14 طابقاً تحيط به مبانٍ مكتبية أصغر ضمن مجمع مسوّر ومنسّق. وقد حصل المشروع على جائزة أفضل تطوير مكتبي ضمن جوائز العقارات العربية عام 2011.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075024-45131273.jpg?v=1644160834"]','https://cmsphoto.ww-cdn.com/resizeapi/c6d2d0fd88e4fbe92ca5a6e2dcdc01239a73d12a/480/',26.3091667,50.1755556,'7244 King Saud Bin Abdulaziz Rd Al Dawhah Al Janubiyah','','','','https://www.saudi-guide.com/eastern-region/i/60075024/alturki-business-park-altrky-bzns-bark',1,0,'تركي بزنس بارك alturki business park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075002,'eastern-region','حديقة الأمير سعود بن جلوي','Prince Ibn Jalawy Park','prince-ibn-jalawy-park-hdyk-alamyr-saaod-bn-gloy','["أماكن سياحية"]','["sights"]','حديقة الأمير سعود بن جلوي من الحدائق العامة بالمنطقة الشرقية، وتوفر مساحات خضراء للنزهة والاسترخاء.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075002-45131259.jpg?v=1644160712"]','https://cmsphoto.ww-cdn.com/resizeapi/9d2692610e60015f8112e7734ca6dd5649c01f21/480/',26.2835084,50.2054528,'Custodian of The Two Holy Mosques Rd Al Khobar Al Shamalia Al Khobar','','','','https://www.saudi-guide.com/eastern-region/i/60075002/prince-ibn-jalawy-park-hdyk-alamyr-saaod-bn-gloy',1,0,'حديقه امير سعود بن جلوي prince ibn jalawy park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60075001,'eastern-region','حديقة اسكان الخبر','','hdyk-askan-alkhbr','["أماكن سياحية"]','["sights"]','حديقة إسكان الخبر من الحدائق العامة بمدينة الخبر، وتتيح للزوار أجواءً خضراء هادئة.','<div class="texte" > <p>حديقة إسكان الخبر حديقة عامة تقع على طريق الملك فهد في حي الإسكان بمدينة الخبر، وتوفر مساحات خضراء وأجواء هادئة لسكان الحي والزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60075001-45131276.jpg?v=1644160867"]','https://cmsphoto.ww-cdn.com/resizeapi/a9cba4a787eedd00c800a18c06506b0b92ee2556/480/',26.2637423,50.2100351,'3879 King Fahd Road Iskan','','','','https://www.saudi-guide.com/eastern-region/i/60075001/hdyk-askan-alkhbr',1,0,'حديقه اسكان خبر اماكن سياحيه',strftime('%s','now'));
