INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60074910,'eastern-region','اجدان ووك','Ajdan Walk','ajdan-walk-agdan-ook','["أماكن سياحية"]','["sights"]','اجدان ووك عبارة عن ساحة للمأكولات تحتوي قاعة طعام عصرية واسعة تشمل باقة من خيارات تناول الطعام في محيط خلاب.','<div class="texte" > <p>اجدان ووك عبارة عن ساحة للمأكولات تحتوي على قاعة طعام عصرية وواسعة تشمل باقة من خيارات تناول الطعام في محيط خلاب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60074910-65348619.jpg?v=1767551449"]','https://cmsphoto.ww-cdn.com/resizeapi/28ce83dd2d2c1079d60ca8f928ff662b04c1d5dc/480/',26.2833438,50.219878,'Prince Turkey Street Alkurnaish Al Khobar','','','','https://www.saudi-guide.com/eastern-region/i/60074910/ajdan-walk-agdan-ook',1,0,'اجدان ووك ajdan walk اماكن سياحيه',strftime('%s','now'));
