INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60074888,'eastern-region','واحة الخبر','alkhobar oasis','alkhobar-oasis-oah-alkhbr','["أماكن سياحية"]','["sights"]','واحة الخبر من المساحات الخضراء بمدينة الخبر، وتوفر أجواءً طبيعية هادئة وسط المدينة.','<div class="texte" > <p>واحة الخبر مساحة خضراء على طريق خادم الحرمين الشريفين في حي الخبر الجنوبية بمدينة الخبر، وتوفر للزوار أجواء هادئة للتنزه وسط المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60074888-45131244.jpg?v=1644160657"]','https://cmsphoto.ww-cdn.com/resizeapi/1b3dcbd6bfb1a0e579848851a1deaa388effb5de/480/',26.2817847,50.201791,'Custodian of The Two Holy Mosques Rd Custodian of The Two Holy Mosques Rd Al Khobar Al Janubiyah','','','','https://www.saudi-guide.com/eastern-region/i/60074888/alkhobar-oasis-oah-alkhbr',1,0,'واحه خبر alkhobar oasis اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60074759,'eastern-region','برج المياه بالخبر','Khobar Water Tower','khobar-water-tower-brg-almyah-balkhbr','["أماكن سياحية"]','["sights"]','برج المياه بالخبر من المعالم المميزة بمدينة الخبر، ويعد نقطة استدلال بارزة في أفق المدينة.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60074759-45131231.jpg?v=1644160609"]','https://cmsphoto.ww-cdn.com/resizeapi/2414407269a986ba81fd2509241db0564cf77cd4/480/',26.3076133,50.2317096,'865J+2MW Alkurnaish Al Khobar','','','','https://www.saudi-guide.com/eastern-region/i/60074759/khobar-water-tower-brg-almyah-balkhbr',1,0,'برج مياه بالخبر khobar water tower اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60074737,'eastern-region','كورنيش الخبر الجديد','','kornysh-alkhbr-algdyd','["أماكن سياحية"]','["sights"]','كورنيش الخبر الجديد واجهة بحرية حديثة بمدينة الخبر، تضم مسارات للمشي وإطلالات على الخليج العربي.','<div class="texte" > <p>كورنيش الخبر الجديد جزء من الواجهة البحرية لمدينة الخبر المطلة على الخليج العربي، ويضم مسطحات خضراء وجلسات عائلية مطلة على البحر وملاعب للأطفال ومسارات للمشي والدراجات، إلى جانب عدد من المطاعم والمقاهي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60074737-45131228.jpg?v=1644160574"]','https://cmsphoto.ww-cdn.com/resizeapi/b28fc6a0f4d672e2fa07d7adf79cf527faa8e585/480/',26.313351,50.22929,'867H+8PV الكورنيش، الخبر','','','','https://www.saudi-guide.com/eastern-region/i/60074737/kornysh-alkhbr-algdyd',1,0,'كورنيش خبر جديد اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60074710,'eastern-region','الواجهة البحرية بالخبر','Khobar Sea Front','khobar-sea-front-aloagh-albhry-balkhbr','["أماكن سياحية"]','["sights"]','الواجهة البحرية بالخبر من أبرز الوجهات الساحلية بمدينة الخبر، وتوفر مسارات للمشي وإطلالات بحرية.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60074710-45131214.jpg?v=1644160495"]','https://cmsphoto.ww-cdn.com/resizeapi/8e0006177f702bc8b95db65a998a4c84d65c047a/480/',26.2936317,50.2254964,'Al Khobar Alkurnaish Al-Khobar','','','','https://www.saudi-guide.com/eastern-region/i/60074710/khobar-sea-front-aloagh-albhry-balkhbr',1,0,'واجهه بحريه بالخبر khobar sea front اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60074615,'eastern-region','بحيرة مدن','Modon Lake','modon-lake-bhyr-mdn','["أماكن سياحية"]','["sights"]','بحيرة مدن تُعد أكبر بحيرة صناعية مطورة في المملكة العربية السعودية، وهي بحيرة صديقة للبيئة أنشأتها الهيئة السعودية للمدن الصناعية ومناطق التقنية (مدن) بالدمام.','<div class="texte" > <p>بحيرة مدن أكبر بحيرة صناعية مطورة في المملكة العربية السعودية، وهي بحيرة صديقة للبيئة، بلغت تكلفة إنشائها نحو 129 مليون ريال، وتبلغ المساحة الاجمالية للمشروع 400 ألف متر مربع، فيما تبلغ مساحة البحيرة 210 آلاف متر مربع، أي بما يزيد عن 52% من المساحة الاجمالية للمشروع، أنشأت البحيرة من قبل الهيئة السعودية للمدن الصناعية ومناطق التقنية مدن في المنطقة الصناعية الثانية بالدمام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60074615-44017835.jpg?v=1636222772"]','https://cmsphoto.ww-cdn.com/resizeapi/dc33b0f34e97fd7ce11af6c222a50090d2d8f281/480/',26.2262584,49.9745076,'Modon Lake Dammam Dammam','','','','https://www.saudi-guide.com/eastern-region/i/60074615/modon-lake-bhyr-mdn',1,0,'بحيره مدن modon lake اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60074552,'eastern-region','شاطئ نصف القمر','Half Moon Bay','half-moon-bay-shaty-nsf-alkmr','["أماكن سياحية"]','["sights"]','يُعتبر شاطئ نصف القمر أحد أجمل الوجهات السياحية في المنطقة الشرقية بالمملكة العربية السعودية.','<div class="texte" > <h2>يُعتبر شاطئ نصف القمر أحد أجمل الوجهات السياحية في المنطقة الشرقية بالمملكة العربية السعودية. يتميز هذا الشاطئ بمياهه الصافية ورماله الذهبية، مما يجعله مكانًا مثاليًا للزوار للاستمتاع بأوقاتهم على البحر.</h2> <h3>موقع الشاطئ</h3> <p>يقع شاطئ نصف القمر بالقرب من مدينة الخبر، ويبعد حوالي 30 كيلومترًا عن العاصمة الإدارية للمنطقة، الدمام. يُمكن الوصول إليه بسهولة بواسطة السيارة، مما يجعله وجهة مفضلة للعديد من العائلات والسياح.</p> <h3>الأنشطة المتاحة</h3> <p>يوفر شاطئ نصف القمر مجموعة متنوعة من الأنشطة الممتعة، بما في ذلك:</p> <ul> <li>السباحة والاستمتاع بالشمس.</li> <li>ممارسة الرياضات المائية مثل ركوب الأمواج والتزلج على الماء.</li> <li>تنظيم رحلات بحرية قصيرة.</li> <li>التخييم والاستمتاع بالأجواء الطبيعية.</li> </ul> <h3>المرافق والخدمات</h3> <p>يحتوي شاطئ نصف القمر على عدد من المرافق والخدمات التي تسهم في تحسين تجربة الزوار، مثل:</p> <ul> <li>مطاعم وكافيهات تقدم مختلف أنواع المأكولات والمشروبات.</li> <li>مناطق مخصصة للشواء.</li> <li>أماكن للإيجار مثل المظلات والكراسي.</li> </ul> <p>باختصار، يُعتبر شاطئ نصف القمر وجهة مثالية لمن يرغب في الاستمتاع بأجواء البحر والاسترخاء في المناطق الطبيعية الجميلة. لا تفوتوا فرصة زيارة هذا الشاطئ الرائع عند زيارتكم للمنطقة الشرقية!</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60074552-65348548.jpg?v=1767550748"]','https://cmsphoto.ww-cdn.com/resizeapi/42fa14a53fb928f098671f0fadb9ee848ad7a099/480/',26.0786143,50.0393017,'Half Moon Bay SA ','','','','https://www.saudi-guide.com/eastern-region/i/60074552/half-moon-bay-shaty-nsf-alkmr',1,0,'شاطئ نصف قمر half moon bay اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60030102,'yanbu','قلعة واسط الأثرية','Wasit Castle archaeological','wasit-castle-archaeological-klaa-oast-alathry','["التراث والثقافة"]','["heritage"]','قلعة واسط الأثرية بين ينبع النخل ومحافظة بدر، قلعة عثمانية على طريق الحج القديم بجوارها بئر السلطاني، كانت ملتقى طريقي الحاج الشامي والمصري.','<div class="texte" > <p>القلعه التركيه الجميله وهى تقع على طريق الحج ابان حكم الاتراك ( الدوله العثمانيه ) وتقع بين ينبع النخل ومحافظة بدر وبجوارها بئر تسمى بئر السلطاني ومنهم من يطلق عليها بئر السلطني وتتضح اشجار الاثل في الصوره وهى من زراعة الاتراك وللمعلوميه هذه القلعه في احدى الحقب الزمنيه كانت نقطة التقا طريق الحاج الشامى بالحاج المصرى&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60030102-43997446.jpg?v=1636041025", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60030102-43997571.jpg?v=1636041512"]','https://cmsphoto.ww-cdn.com/resizeapi/9e021a13b3c91863b879a008342660982761f3ea/480/',24.009229,38.712429,'SA Badr Al Madinah Province','','','','https://www.saudi-guide.com/yanbu/i/60030102/wasit-castle-archaeological-klaa-oast-alathry',1,0,'قلعه واسط اثريه wasit castle archaeological تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60029892,'yanbu','شاطئ الشباب ينبع الصناعية','Youth Beach Yanbu Industrial','youth-beach-yanbu-industrial-shaty-alshbab-ynbaa-alsnaaay','["أماكن سياحية"]','["sights"]','شاطئ الشباب في ينبع الصناعية، شاطئ نظيف بمياه كريستالية ورمال ناعمة وأجواء منعشة، تتوفر فيه المرافق الخدمية ويناسب ممارسة الرياضة والهوايات.','<div class="texte" > <p>يتمتع شاطئ الشباب بينبع الصناعية بأجوائه&nbsp;المنعشة وشواطئه النظيفة ذات المياه الكريستالية&nbsp;والرمال الناعمة، كما تتوفّر فيه المرافق الخدمية التي توفر كل وسائل الراحة للزائر بالإضافة إلى كونه مكاناً مناسباً لممارسة الرياضة وبعض الهوايات الأخرى.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60029892-44371280.jpg?v=1638177652"]','https://cmsphoto.ww-cdn.com/resizeapi/5962b8fe7a59bfd11dfc133b6f37697ade9d46b3/480/',23.9849005,38.1934668,'X5MV+X98 Al-Nahdah Yanbu','','','','https://www.saudi-guide.com/yanbu/i/60029892/youth-beach-yanbu-industrial-shaty-alshbab-ynbaa-alsnaaay',1,0,'شاطئ شباب ينبع صناعيه youth beach yanbu industrial اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938588,'albaha','قرية الخلف والخليف الأثرية','Al Khalaf and Al Khulaif Village','al-khalaf-and-al-khulaif-village-kry-alkhlf-oalkhlyf-alathry','["التراث والثقافة"]','["heritage"]','قريتا الخلف والخليف الأثريتان في قلوة تضمان بقايا أحياء سكنية ومسجد الخلف المحصّن ونقوشاً بالخط الكوفي من القرون الهجرية الأولى.','<div class="texte" > <p>الخلف والخليف هما موقعان لقريتين متجاورتين تفصل بينهما مسافة كيلو مترين فقط، عثر فيهما على بقايا أحياء سكنية مختلفة وكذلك بقايا مسجد الخلف المربع الشكل الذي تبلغ مساحته 324 متر مربع، ويظهر فيه الطابع التحصيني من حيث ارتفاع جدرانه وسماكتها ومتانة البناء، أما مسجد الخليف فقد أندثر ولم يبق منه شيء، ويحتوي الموقعان على العديد من المقابر فيهما، وكذلك النقوش الخطية التي عثر منها على 27 نقشا تغطي فترة زمنية متقدمة من القرون الهجري الأولى، وجميعها منقوشة بالخط الكوفي المتدرج من البسيط إلى المورق ثم المزهر، تقع القريتان في محافظة قلوة التابعة لمنطقة الباحة في تهامة جنوب غرب المملكة العربية السعودية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938588-44538066.jpg?v=1639322943"]','https://cmsphoto.ww-cdn.com/resizeapi/e16c7a7f5da7cdd86b3b28bc1a095516fbfbd958/480/',19.968923,41.2263612,'X69G+HG9 Qilwah Qilwah','','','','https://www.saudi-guide.com/albaha/i/59938588/al-khalaf-and-al-khulaif-village-kry-alkhlf-oalkhlyf-alathry',1,0,'قريه خلف والخليف اثريه al khalaf and al khulaif village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938571,'albaha','متحف عاصفة الحزم','Asifat Al Hazm Museum','asifat-al-hazm-museum-mthf-aaasf-alhzm','["التراث والثقافة"]','["heritage"]','متحف عاصفة الحزم في قرية الصفح بمحافظة المندق من متاحف منطقة الباحة، ويُعد محطة لمحبي التراث والتاريخ المحلي خلال جولتهم في المندق.','<div class="texte" > <p>متحف عاصفة الحزم متحف خاص يقع في قرية الصفح بمحافظة المندق بمنطقة الباحة، ويُعنى بعرض مقتنيات تراثية تعكس جوانب من تاريخ المنطقة وحياة أهلها، ويُنصح بالتواصل مع القائمين عليه قبل الزيارة للتأكد من إتاحته للزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938571-44538074.jpg?v=1639322999"]','https://cmsphoto.ww-cdn.com/resizeapi/0ab3ef2b09e9e0bb37cc677eb3208276812e4343/480/',20.0932037,41.308751,'38V5+7GJ الصفح المندق','','','','https://www.saudi-guide.com/albaha/i/59938571/asifat-al-hazm-museum-mthf-aaasf-alhzm',1,0,'متحف عاصفه حزم asifat al hazm museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938569,'albaha','قلعة بخروش بن علاس','Bakhroush bin Allas Castle','bakhroush-bin-allas-castle-klaa-bkhrosh-bn-aalas','["التراث والثقافة"]','["heritage"]','قلعة بخروش بن علاس في محافظة القرى قرية حصون تاريخية للقائد الزهراني بخروش بن علاس، بحصون دائرية من الحجارة البركانية شمال الأطاولة.','<div class="texte" > <p>بخروش بن علاس القرشي الزهراني (1170هـ-1230هـ) كان فارسا من قبيلة زهران في الحجاز وقائدًا من قادة الدولة السعودية الأولى، قتل واحتز رأسه بعد عدة وقائع على يد الجيوش العثمانية الغازية بقيادة محمد علي باشا الوالي العثماني لمصر، وقلعته هذه تعد من أهم معالم التاريخ القديم للسعودية حيث أنها تحكي روايات الحروب والأحداث التاريخية. تُعرف رسميًا باسم "قرية حصون بخروش بن علاس"، وتقع شمال الأطاولة بمسافة نحو 5 كم، وعلى بعد 37 كم من مدينة الباحة. تضم القرية عدة حصون دائرية الشكل صممت خصيصًا للتخفيف من آثار قذائف المدفعية، أبرزها حصن بخروش الذي يتميز بمساحته الواسعة وأبراجه الدائرية رغم تهدم جزء منه. بُنيت الجدران بالحجارة البركانية المتراصة بأحجام وألوان متفاوتة، وطُليت من الداخل بطبقة سميكة من الطين، فيما بُنيت الأسقف من جذوع الأشجار وأغصانها ثم غُطيت بالطين. تضم القرية أيضًا أربع مقابر جماعية جنوب شرق القلعة لجنود أتراك سقطوا في معركة وادي قريش عام 1229هـ.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938569-44538077.jpg?v=1639323027"]','https://cmsphoto.ww-cdn.com/resizeapi/7ccddcca6a62e616fdd24a8d64c498edce5b5bdb/480/',20.2944762,41.3592686,'SA القرى منطقة الباحة','','','','https://www.saudi-guide.com/albaha/i/59938569/bakhroush-bin-allas-castle-klaa-bkhrosh-bn-aalas',1,0,'قلعه بخروش بن علاس bakhroush bin allas castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938524,'albaha','قرية القهاد الأثرية','Al Qahad Heritage Village','al-qahad-heritage-village-kry-alkhad-alathry','["التراث والثقافة"]','["heritage"]','قرية القهاد الأثرية في محافظة القرى من قرى زهران التاريخية، تتميز بدقة تخطيطها وتصميمها المعماري وتُعد من رموز التراث في المنطقة.','<div class="texte" > <p>قرية القهاد الأثرية هي قرية من قرى زهران بمنطقة الحجاز الشهيرة تتميز بروعة التخطيط ، والدقة في التصميم، والتنفيذ وتعد من الرموز التاريخية المهمة في المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938524-44538079.jpg?v=1639323061"]','https://cmsphoto.ww-cdn.com/resizeapi/8410c659aa45948cedd3fc78e2d94f63612e47c8/480/',20.272,41.3596416,'15 Al Atawilah Al Qara','','','','https://www.saudi-guide.com/albaha/i/59938524/al-qahad-heritage-village-kry-alkhad-alathry',1,0,'قريه قهاد اثريه al qahad heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938523,'albaha','القرية الأثرية بالأطاولة','Al Atawilah Heritage Village','al-atawilah-heritage-village-alkry-alathry-balataol','["التراث والثقافة"]','["heritage"]','قرية الأطاولة التراثية في محافظة القرى تطل على طريق الطائف الباحة، وتضم حصني العثمان ودماس ومسجدها القديم وسوق ربوع قريش التاريخي.','<div class="texte" > <p>تتميز قرية الاطاولة التراثية بموقعها المرتفع واطلالتها المتميزة على طريق الطائف الباحة الإقليمي والمناطق المحيطة بها من جميع الجهات حيث تبعد ما يقرب من 33 كم عن مدينة الباحة عاصمة المنطقة (مقر الامارة) وتعتبر مدينة الأطاولة بشكل عام هي الأكبر مساحة في محافظة القرى، وهي مقر الدوائر الحكومية، وتضم القرية سوق ربوع قريش والذي كان يقام يوم الخميس من كل اسبوع ثم تحول إلى يوم الأربعاء، والذي ساهم في تأكيد المكانة التاريخية للقرية، حيث كانت تتوافد سكان المنطقة من القرى المحيطة للبيع والشراء والتجارة في السوق والذي كانت تحكمه القوانين والاعراف المتوارثة والتي كانت بمثابة مواثيق تحكم عمليات التجارة والمعاملات بين الناس في المنطقة، وقد تميزت قرية الاطاولة بوجود حصنين للحماية كانا مرتبطين بسور للقرية هما حصن العثمان وحصن دماس وهي مباني ذات تصميم فريد من الحجر وتتكون من عدة أدوار، وقد كان يتوسط القرية المسجد الذي مازال باقيا حتى الان بأنظمة المياه الفريدة التي كانت تستخدم في الوضوء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938523-44538083.jpg?v=1639323157"]','https://cmsphoto.ww-cdn.com/resizeapi/62924bd82776f814af30e469ca5875480326d3eb/480/',20.250294,41.359724,'7925+4V9 Al Atawilah Al Qara','','','','https://www.saudi-guide.com/albaha/i/59938523/al-atawilah-heritage-village-alkry-alathry-balataol',1,0,'قريه اثريه بالاطاوله al atawilah heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938522,'albaha','متحف دوس','Daws Museum','daws-museum-mthf-dos','["التراث والثقافة"]','["heritage"]','متحف دوس التراثي في محافظة المندق متحف خاص يضم مئات القطع التراثية من الفضيات والأسلحة القديمة وأدوات الزراعة والطبخ والملابس.','<div class="texte" > <p>متحف دوس متحف خاص بالتراث المحلي يقع في قرية برحرحة بمحافظة المندق، أسسه بشير الزهراني، ويضم نحو 800 قطعة تراثية وأثرية تشمل المشغولات الفضية والأسلحة القديمة وأدوات الزراعة والمطبخ والملابس التقليدية والمصنوعات من سعف النخيل والعملات القديمة، وهو مرخّص من هيئة السياحة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938522-44538086.jpg?v=1639323140"]','https://cmsphoto.ww-cdn.com/resizeapi/310482fba0dab83c73c68e43c44b6b1448ff1b5e/480/',20.338139,41.197222,'Doos Al Mandaq Al Bahah Province','','','','https://www.saudi-guide.com/albaha/i/59938522/daws-museum-mthf-dos',1,0,'متحف دوس daws museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938521,'albaha','متحف الفيان بالأطاولة','Al Fayyan Museum','al-fayyan-museum-mthf-alfyan-balataol','["التراث والثقافة"]','["heritage"]','متحف ناصر الفيان في الأطاولة متحف تراثي خاص يضم آلاف القطع التي جُمعت على مدى سنوات، ويضم مقهى وجلسات عائلية بإطلالة جميلة.','<div class="texte" > <p>متحف ناصر الفيان - الاطاولة بالباحه بدأ في جمع القطع التراثية منذ عام 1414 في منزله الخاص وواصل إهتمامه بالتراث حتى خصص له مبنى عام 1438 جمع فيه آلاف القطع وفي عام 1442 تم تحويل المتحف للعامه حيث يضم ايضا مقهى وجلسات للعوائل وأخرى للشباب ويتمتع بإطلالة جميله.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938521-44538121.jpg?v=1639323809"]','https://cmsphoto.ww-cdn.com/resizeapi/e9d948d3250907df05b910aff03968f877600eee/480/',20.2428266,41.3549331,'Al Qara Al Bahah Province SA','','','','https://www.saudi-guide.com/albaha/i/59938521/al-fayyan-museum-mthf-alfyan-balataol',1,0,'متحف فيان بالاطاوله al fayyan museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938519,'albaha','مسجد الصفا التاريخي','Al Safa Historic Mosque','al-safa-historic-mosque-msgd-alsfa-altarykhy','["التراث والثقافة"]','["heritage"]','مسجد الصفا التاريخي في بلجرشي من أقدم مساجد المملكة، يُنسب بناؤه للصحابي سفيان بن عوف، وطُوّر ضمن مشروع الأمير محمد بن سلمان للمساجد التاريخية.','<div class="texte" > <p>يقع مسجد الصفا التاريخي وسط محافظة بلجرشي على بعد نحو 27 كم من مدينة الباحة، ويُعد من أقدم مساجد المنطقة إذ يتجاوز عمره 1350 عاماً، ويحمل بابه تاريخ عام 46 هـ، ويُنسب بناؤه إلى الصحابي سفيان بن عوف رضي الله عنه. شُيّد المسجد بالحجر الجرانيتي المحلي وأعمدة من خشب العرعر، وقد شمله مشروع الأمير محمد بن سلمان لتطوير المساجد التاريخية للحفاظ على طابعه المعماري الأصيل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938519-44538122.jpg?v=1639323831"]','https://cmsphoto.ww-cdn.com/resizeapi/493db8f3a408efb834970e9ad42489506c62aaab/480/',19.8599682,41.559278,'VH55+XPJ Baljurashi Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938519/al-safa-historic-mosque-msgd-alsfa-altarykhy',1,0,'مسجد صفا تاريخي al safa historic mosque تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938518,'albaha','القرية التاريخية ببلجرشي','Baljurashi Historic Village','baljurashi-historic-village-alkry-altarykhy-bblgrshy','["التراث والثقافة"]','["heritage"]','القرية التاريخية ببلجرشي تشتهر بحصونها الشامخة على قمة الجبل وبيوتها القديمة، وبساتين اللوز والعنب والتين، ومناخها المعتدل صيفاً.','<div class="texte" > <p>تشتهر القرية التاريخية ببلجرشي أو كما تسمى "الملد" باللوز&nbsp;والعنب&nbsp;والحماط&nbsp;والتين، كما تشتهر بحصونها المرتفعة والشامخة في قمة جبل تحيطها البيوت القديمة،&nbsp;مناخها ممطر وبارد في&nbsp;الشتاء&nbsp;ومعتدل في&nbsp;الصيف، يعد برجا الملد&nbsp;أشهر معالمها التاريخية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938518-44538124.jpg?v=1639323856"]','https://cmsphoto.ww-cdn.com/resizeapi/98e698518d64a65a4dc87ce85debfec0b0eaee38/480/',19.8601958,41.5595607,'VH65+3RF Baljurashi Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938518/baljurashi-historic-village-alkry-altarykhy-bblgrshy',1,0,'قريه تاريخيه ببلجرشي baljurashi historic village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938515,'albaha','عقبة حميدة الأثرية','Humaida Stairs','humaida-stairs-aakb-hmyd-alathry','["التراث والثقافة"]','["heritage"]','عقبة حميدة الأثرية في بلجرشي طريق تاريخي مدرّج ومرصوف كانت تسلكه القوافل بين السراة وتهامة، وأهم طريق تجاري يربط بلجرشي بالمخواة والقنفذة.','<div class="texte" > <p>عقبة حميده هي عقبة تاريخية مدرجة ومرصوفه وكانت تستخدم قديماً&nbsp;لسير القوافل وتحميل البضائع النازلة من&nbsp;الحجاز&nbsp;إلى&nbsp;تهامة&nbsp;والصاعدة منها وكانت أهم طريق تجاري يربط بلجرشى&nbsp;بالمخواة&nbsp;والقنفذة&nbsp;على ساحل&nbsp;البحر الأحمر&nbsp;وما والاها من المدن والبلدان في الساحل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938515-44538127.jpg?v=1639323884"]','https://cmsphoto.ww-cdn.com/resizeapi/69a66ca9a2ebdbe47e40c318d1f1a59fa2b7dbb5/480/',19.8562411,41.5367722,'VG4P+FPR Baljurashi Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938515/humaida-stairs-aakb-hmyd-alathry',1,0,'عقبه حميده اثريه humaida stairs تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (59938438,'albaha','متحف محمد بن مصبح ببلجرشي','Bin Musbeh Museum','bin-musbeh-museum-mthf-mhmd-bn-msbh-bblgrshy','["التراث والثقافة"]','["heritage"]','متحف محمد بن مصبح في بلجرشي متحف تراثي يضم عملات وحلياً وأسلحة وملابس تقليدية وأدوات زراعة ومطبخ ومجسمات للحياة القديمة.','<div class="texte" > <p>يتكون&nbsp;متحف محمد بن مصبح من مبنى مستقل متكوّن من قاعتين رئيستين مساحة كلاً منها 120 متر مربع وثلاث غرف مساحة الواحدة 48 متر مربع، يتنوع أسلوب العرض بالمتحف باستخدام خزائن العرض الزجاجية والاستاندات بأسلوب جيد . يحتوي المتحف على مكتبة لصور الأسرة السعودية المالكة والعملات والحلي والفضيات إضافة إلى الأسلحة وأدوات الحرب بأنواعها والهواتف القديمة والملابس التراثية وأدوات الزراعة والمطبخ والمكاييل والموازين والخوصيات والنحاسيات، كما يوجد مجسمات لمعمل القطران والدياسة والبئر وأدواته والأبواب القديمة والرحي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/59938438-44538129.jpg?v=1639323911"]','https://cmsphoto.ww-cdn.com/resizeapi/db8c961b7849e59beb6afb32d5404c6a48549113/480/',19.8421482,41.5764418,'قرية الجلحية Baljurshi Baljurashi','','','','https://www.saudi-guide.com/albaha/i/59938438/bin-musbeh-museum-mthf-mhmd-bn-msbh-bblgrshy',1,0,'متحف محمد بن مصبح ببلجرشي bin musbeh museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169739,'najran','قرية مدماك التراثية ومتحف الرمال','Madmak Heritage Village','madmak-heritage-village-kry-mdmak-altrathy-omthf-alrmal','["أماكن سياحية"]','["sights"]','قرية مدماك التراثية ومتحف الرمال على طريق الملك عبدالله في نجران، وجهة تراثية تعكس طراز العمارة النجرانية وتعرض مقتنيات تروي حياة الأجداد في المنطقة.','<div class="texte" > <p>قرية مدماك التراثية ومتحف الرمال وجهة تراثية على طريق الملك عبدالله في مدينة نجران، تستلهم طراز العمارة الطينية النجرانية، وتعرض مقتنيات تراثية تروي ملامح حياة الأجداد في المنطقة، ويقصدها المهتمون بالتراث والزوار الراغبون في التعرف على موروث نجران.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169739-45042092.jpg?v=1643479537"]','https://cmsphoto.ww-cdn.com/resizeapi/acf70103d2d5eaf6b2d31a0613cc54b0ec8ad310/480/',17.5416473,44.279293,'King Abdullah Rd Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169739/madmak-heritage-village-kry-mdmak-altrathy-omthf-alrmal',1,0,'قريه مدماك تراثيه ومتحف رمال madmak heritage village اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169735,'najran','مدينة الأرض السعيدة الترفيهية','Happy Land Najran','happy-land-najran-mdyn-alard-alsaayd-altrfyhy','["أماكن سياحية"]','["sights"]','مدينة الأرض السعيدة الترفيهية في نجران وجهة عائلية تضم ألعاباً ترفيهية متنوعة للأطفال والكبار، وتعد من الأماكن المفضلة لقضاء أوقات ممتعة في المدينة.','<div class="texte" > <p>مدينة الأرض السعيدة الترفيهية وجهة ترفيهية عائلية في مدينة نجران، تضم ألعاباً متنوعة تناسب الأطفال والكبار، وتعد من الأماكن التي تقصدها العائلات لقضاء أوقات ممتعة في أجواء مرحة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169735-45042141.jpg?v=1643479973"]','https://cmsphoto.ww-cdn.com/resizeapi/6f2dd72b33491067f78ff0c5ac5d4573407031d1/480/',17.6194185,44.2264456,'Najran Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169735/happy-land-najran-mdyn-alard-alsaayd-altrfyhy',1,0,'مدينه ارض سعيده ترفيهيه happy land najran اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169703,'najran','محمية عروق بني معارض','Uruq Bani Maarid Reserve','uruq-bani-maarid-reserve-mhmy-aarok-bny-maaard','["أماكن سياحية"]','["sights"]','محمية عروق بني معارض على الطرف الغربي من الربع الخالي، موقع تراث عالمي لليونسكو يضم كثباناً رملية شاهقة وهضاباً جيرية، وأُعيد إليها المها العربي والغزلان.','<div class="texte" > <p>محمية عروق بني معارض محمية طبيعية تقع في جنوب المملكة العربية السعودية، تحت إشراف المركز الوطني لتنمية الحياة الفطرية، على الطرف الغربي من صحراء الربع الخالي، أكبر صحراء رملية في العالم في منطقة نجران،&nbsp;وتُعتبر آخر المناطق التي شوهد فيها المها العربي قبل انقراضه عام 1970، وتضم المحمية عدداً من التشكيلات الأرضية والمواطن الفطرية الطبيعية الهامة منها الكثبان الرملية المرتفعة وهضبة جيرية متقطعة وتنقسم المحمية إلى ثلاثة مناطق؛ المنطقة الرئيسية للمحمية والمنطقة التي يُسمح فيها بالرعي الخاضع للرقابة ومنطقة الصيد.</p> <p>تقع عروق بني معارض في منطقة كانت موطناً للمها العربي قبل انقراضه من البرية. وقد اختير المتبقي منه لإعادة إدخال المها التي ترعرت ضمن برنامج تربية الأسر،&nbsp;وقد وقع اختياره أيضاً باعتباره مناسباً لإستعادة قطعان غزال الريم العربي وغزال الجبل والنعام وجميعها كانت تسكن المنطقة تاريخياً.</p> </div>  <div class="texte" > <p>وفي عام 2023م أُدرجت محمية عروق بني معارض في قائمة التراث العالمي لمنظمة اليونسكو، لتكون أول موقع طبيعي في المملكة يُسجل في القائمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169703-45042089.jpg?v=1643479512"]','https://cmsphoto.ww-cdn.com/resizeapi/2595def5c6511c09d2101262556c1b879a49ce14/480/',19.3369381,45.9039661,'SA  ','','','','https://www.saudi-guide.com/najran/i/60169703/uruq-bani-maarid-reserve-mhmy-aarok-bny-maaard',1,0,'محميه عروق بني معارض uruq bani maarid reserve اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169702,'najran','النافورة الراقصة','Najran Dancing Fountain','najran-dancing-fountain-alnafor-alraks','["أماكن سياحية"]','["sights"]','النافورة الراقصة في نجران معلم ترفيهي بعروض مائية ملونة مصحوبة بالموسيقى، تحيط بها مساحات للتنزه والمشي ومقاهٍ، وتعد من أبرز وجهات الأمسيات في المدينة.','<div class="texte" > <p>النافورة الراقصة من أبرز المعالم الترفيهية في مدينة نجران، وتقع داخل حديقة الملك سعود في حي الفهد، وتتكون من حلقات مائية تتوسطها حلقة رئيسية ترتفع منها المياه عالياً في عروض ملونة مصحوبة بالموسيقى.</p> <p>ويحيط بالنافورة منتزه يضم مساحات للتنزه والمشي وألعاباً ترفيهية ومقاهي، ما يجعلها وجهة مفضلة للعائلات والزوار في الأمسيات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169702-45042145.jpg?v=1643479994"]','https://cmsphoto.ww-cdn.com/resizeapi/64a1755b1b3c0dece307e728adad57b5635f9a8b/480/',17.5614235,44.2279221,'SA Najran Najran','','','','https://www.saudi-guide.com/najran/i/60169702/najran-dancing-fountain-alnafor-alraks',1,0,'نافوره راقصه najran dancing fountain اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169690,'northern-border','متحف للماضي أثر التراثي','Lil Madi Athar Heritage Museum','lil-madi-athar-heritage-museum-mthf-llmady-athr-altrathy','["التراث والثقافة"]','["heritage"]','متحف للماضي أثر في رفحاء متحف خاص أسسه صياح الشمري، يضم آلاف القطع من أسلحة وعملات وأزياء وأوانٍ وسيارات قديمة.','<div class="texte" > <p>متحف "للماضي أثر" متحف تراثي خاص في محافظة رفحاء بمنطقة الحدود الشمالية، أسسه المواطن صياح قاسم الشمري بعد سنوات طويلة من جمع القطع النادرة منذ صغره، ويستقبل الزوار من الأهالي والسياح.</p><p>يضم المتحف آلاف القطع المتنوعة، منها الأسلحة القديمة والسيوف والدروع، والأواني الفخارية والمشغولات اليدوية، والعملات النقدية والأزياء التقليدية، إضافة إلى سيارات وأجهزة قديمة ومعروضات توثق تطور الحياة في المملكة، و"العمارية" التي كانت تُحمل على ظهور الإبل. ويعكس المتحف تراث الحدود الشمالية خاصة والجزيرة العربية عامة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169690-44915918.jpg?v=1642535640"]','https://cmsphoto.ww-cdn.com/resizeapi/e3f3f0903c083b6d072393fd248d7c7d01e4aea3/480/',29.6287539,43.5222453,'Rafha Al Muhammadiyah Rafha','','','','https://www.saudi-guide.com/northern-border/i/60169690/lil-madi-athar-heritage-museum-mthf-llmady-athr-altrathy',1,0,'متحف للماضي اثر تراثي lil madi athar heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169687,'northern-border','بركة الجميمة','Al-Jumaimah Pool','al-jumaimah-pool-brk-algmym','["التراث والثقافة"]','["heritage"]','بركة الجميمة إحدى محطات درب زبيدة في الحدود الشمالية قرب رفحاء، تضم بركة مياه تاريخية وأطلال قصر بصف من الدكاكين.','<div class="texte" > <p>الجميمة&nbsp;إحدى منازل&nbsp;درب زبيدة، وتقع حالياً في&nbsp;السعودية&nbsp;وتحديداً في&nbsp;منطقة الحدود الشمالية&nbsp;بالقرب من الحدود&nbsp;العراقية، يضم الموقع بركة تسمى بركة الجريسي أو بركة الجميمة، كما يوجد بالموقع أطلال لقصر به صف دكاكين ومبنى آخر.&nbsp;</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169687-44915934.jpg?v=1642535833"]','https://cmsphoto.ww-cdn.com/resizeapi/e2af2ded96fc62346b7f39f7c5833d35df1fcadb/480/',29.6055239,43.6036837,'SA Rafha Northern Borders Province','','','','https://www.saudi-guide.com/northern-border/i/60169687/al-jumaimah-pool-brk-algmym',1,0,'بركه جميمه al jumaimah pool تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169620,'northern-border','قرية زبالا','Zubala Village','zubala-village-kry-zbala','["التراث والثقافة"]','["heritage"]','قرية زبالا جنوب رفحاء من أشهر منازل درب زبيدة، تضم آثاراً وبركاً وآباراً قديمة كانت محطة للحجاج والمسافرين.','<div class="texte" > <p>زُبالة&nbsp;أو&nbsp;"زُبَالا"&nbsp;هي قرية تقع في محافظة&nbsp;رفحاء&nbsp;الواقعة&nbsp;بمنطقة الحدود الشمالية&nbsp;في&nbsp;السعودية،&nbsp;تضم القرية موقعاً تاريخياً، وتشتهر كونها إحدى منازل&nbsp;درب زبيدة، تقع في جنوب مدينة&nbsp;رفحاء، وتبعد عنها 25 كم وتقع على طريق الحجاج القديم، ويوجد بها آثار قديمة وبرك وآبار تتجمع فيها مياه وادي المناشبي وأبا الرمم وأم عصافير،&nbsp;وكانت محطة للحجاج والمسافرين قديماً والآن هي موطن لعشيرة السليط من اليحيا من قبيلة شمر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169620-44915970.jpg?v=1642536078"]','https://cmsphoto.ww-cdn.com/resizeapi/fca85a3b0c2c5bb79ee26412fdd9799db1ccb422/480/',29.3931937,43.5582915,'زبالا رفحاء منطقة الحدود الشمالية','','','','https://www.saudi-guide.com/northern-border/i/60169620/zubala-village-kry-zbala',1,0,'قريه زبالا zubala village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169575,'northern-border','سوق لينة التاريخي','Linah Historic Souq','linah-historic-souq-sok-lyn-altarykhy','["التراث والثقافة"]','["heritage"]','سوق لينة التاريخي في رفحاء سوق المشاهدة القديم في قرية لينة المشهورة بآبارها، وبقربه قصر الملك عبدالعزيز التاريخي.','<div class="texte" > <p>لينة، هي قرية شمال&nbsp;نجد&nbsp;في&nbsp;المملكة العربية السعودية، تعد من أقدم مستوطنات الجزيرة العربية، وأحد منازل&nbsp;درب زبيدة&nbsp;الذي كان يسلكه الحاج العراقي. تشتهر لينة منذ القدم بعذوبة مياهها وآبارها الكثيرة التي تبلغ نحو 300 بئر، وفيها معالم تاريخية مثل&nbsp;قصر الملك عبد&nbsp;العزيز&nbsp;الذي أنشئ عام 1354هـ والسوق القديم سوق "المشاهدة" نسبة إلى تجار العراق المشاهدة الذين كانوا يأتون لهذا السوق للتبادل التجاري مع أهل نجد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169575-44916000.jpg?v=1642536247"]','https://cmsphoto.ww-cdn.com/resizeapi/3c0e7b645ebf43cccc705217e975842be854523e/480/',28.7601404,43.7392937,'QP6Q+3P3 Linah Rafha','','','','https://www.saudi-guide.com/northern-border/i/60169575/linah-historic-souq-sok-lyn-altarykhy',1,0,'سوق لينه تاريخي linah historic souq تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169570,'northern-border','متنزه عرعر الوطني','Arar National Park','arar-national-park-mtnzh-aaraar-alotny','["أماكن سياحية"]','["sights"]','متنزه عرعر الوطني متنفس للعائلات على أطراف عرعر، يضم مساحات خضراء ومسارات للمشي والدراجات وجلسات للنزهة في الهواء الطلق.','<div class="texte" > <p>متنزه عرعر الوطني من أهم المتنفسات الطبيعية للعائلات في مدينة عرعر، يقع على أطراف المدينة ويوفر مساحات واسعة للتنزه بعيداً عن زحام الأحياء.</p><p>يضم المتنزه مسطحات خضراء وحدائق وممرات للمشي ومسارات للدراجات، إلى جانب مساحات لممارسة الرياضة وجلسات للعائلات، ويقصده الأهالي خاصة في أيام الربيع واعتدال الأجواء للاستمتاع بالهواء الطلق وقضاء أوقات عائلية.</p> </div>','[]','',30.9201319,41.0904208,'Arar Al Dahiyah Arar','','','','https://www.saudi-guide.com/northern-border/i/60169570/arar-national-park-mtnzh-aaraar-alotny',1,0,'متنزه عرعر وطني arar national park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169507,'northern-border','متحف بسام المفلح الشخصي','Bassam Al-Mefleh Museum','bassam-al-mefleh-museum-mthf-bsam-almflh-alshkhsy','["التراث والثقافة"]','["heritage"]','متحف بسام المفلح الشخصي في عرعر من المتاحف الخاصة بالحدود الشمالية، يعرض مقتنيات تراثية توثق حياة الأجداد في المنطقة.','<div class="texte" > <p>متحف بسام المفلح الشخصي أحد المتاحف الخاصة في مدينة عرعر، ويندرج ضمن مجموعة من المتاحف الأهلية في منطقة الحدود الشمالية التي أسسها هواة جمع التراث لتوثيق تاريخ المنطقة وربط الأجيال الجديدة بحياة الآباء والأجداد.</p><p>يعرض المتحف مقتنيات تراثية جمعها صاحبه تعكس ملامح الحياة التقليدية في شمال المملكة، ويمثل محطة مناسبة لمحبي التراث والتاريخ المحلي خلال زيارتهم لعرعر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169507-44916049.jpg?v=1642536611"]','https://cmsphoto.ww-cdn.com/resizeapi/4a63b6fae6d322efde62459058210c8bc1ad57f5/480/',30.9765636,41.0598591,'SA Naseem Arar','','','','https://www.saudi-guide.com/northern-border/i/60169507/bassam-al-mefleh-museum-mthf-bsam-almflh-alshkhsy',1,0,'متحف بسام مفلح شخصي bassam al mefleh museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169505,'northern-border','جبل أقرن','Agran Mountain','agran-mountain-gbl-akrn','["أماكن سياحية"]','["sights"]','جبل أقرن قرب دوقرة شمال غرب طريف موقع أثري في الحدود الشمالية، تعود أطلاله إلى أواخر العصر الروماني أو بدايات العصر الإسلامي.','<div class="texte" > <p>جبل أقرن يقع بالقرب من منطقة دوقرة وهي عبارة عن&nbsp;موقع أثري&nbsp;يقع على بعد 40 كم شمال غرب&nbsp;محافظة طريف&nbsp;التابعة&nbsp;لمنطقة الحدود الشمالية،&nbsp;يعود تاريخ الموقع إلى&nbsp;الفترة الرومانية&nbsp;المتأخرة أو إلى&nbsp;الفترة الإسلامية&nbsp;المبكرة، ويعتقد بعض الباحثين أن أطلال المباني في دوقرة تعود إلى&nbsp;العصر الأموي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169505-44916318.jpg?v=1642537978"]','https://cmsphoto.ww-cdn.com/resizeapi/01fcacd7c473b88bc955f6e06e6cb43c973b652a/480/',31.5342539,38.3033967,'Agran Mountain Turaif Northern Borders Province','','','','https://www.saudi-guide.com/northern-border/i/60169505/agran-mountain-gbl-akrn',1,0,'جبل اقرن agran mountain اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169501,'northern-border','بوليفارد مول عرعر','Boulevard Mall Arar','boulevard-mall-arar-bolyfard-mol-aaraar','["أماكن سياحية"]','["sights"]','بوليفارد مول عرعر وجهة تسوق وترفيه في عرعر، يضم متاجر أزياء وأحذية وإكسسوارات ومطاعم ومقاهي في مكان واحد للعائلات.','<div class="texte" > <p>بوليفارد مول من وجهات التسوق والترفيه في مدينة عرعر، يجمع تحت سقف واحد تشكيلة من المتاجر المتخصصة في الأزياء الرجالية والنسائية وملابس الأطفال، والأحذية والحقائب، والإكسسوارات والهدايا، إلى جانب عدد من العلامات التجارية المعروفة.</p><p>يضم المول أيضاً مطاعم ومقاهي متنوعة، وخدمات مثل مواقف السيارات وأجهزة الصراف الآلي، ما يجعله خياراً مناسباً للعائلات لقضاء وقت ممتع بين التسوق وتناول الطعام.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169501-44916329.jpg?v=1642538041"]','https://cmsphoto.ww-cdn.com/resizeapi/13b30a3ac101df7bcc68163e7a01767609e85ade/480/',30.977777,41.0087325,'Ar Ar Alkhalidiyah Arar','','','','https://www.saudi-guide.com/northern-border/i/60169501/boulevard-mall-arar-bolyfard-mol-aaraar',1,0,'بوليفارد مول عرعر boulevard mall arar اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169483,'northern-border','متنزه وممشى المساعدية','Al-Musaidiyah Park and Walkway','al-musaidiyah-park-and-walkway-mtnzh-ommsha-almsaaady','["أماكن سياحية"]','["sights"]','متنزه وممشى المساعدية في عرعر وجهة خضراء للعائلات، تضم مسارات للمشي بين النخيل والمسطحات الخضراء ومساحات مفتوحة للتنزه.','<div class="texte" > <p>متنزه وممشى المساعدية من أبرز الوجهات الخضراء في مدينة عرعر، يقع في الجهة الشرقية من المدينة ويجمع الأهالي والعائلات للمشي والتنزه.</p><p>تشكّل أشجار النخيل هوية المكان، وتمتد مسارات المشي بين المسطحات الخضراء والمساحات المفتوحة، ما يجعله مكاناً مناسباً لممارسة رياضة المشي والاسترخاء وقضاء أوقات عائلية في الهواء الطلق، خاصة في الأمسيات المعتدلة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169483-44916331.jpg?v=1642538085"]','https://cmsphoto.ww-cdn.com/resizeapi/a49d4184e9c5cd75f95215cdac364dd73f60fcc6/480/',30.9690437,41.0193648,'X299+JP9 Almusaidiyah Ash Sharqiyyah Arar','','','','https://www.saudi-guide.com/northern-border/i/60169483/al-musaidiyah-park-and-walkway-mtnzh-ommsha-almsaaady',1,0,'متنزه وممشي مساعديه al musaidiyah park and walkway اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169391,'aljawf-region','حي الدرع الأثري','Al-Dir'' Heritage Quarter','al-dir-heritage-quarter-hy-aldraa-alathry','["التراث والثقافة"]','["heritage"]','حي الدرع في دومة الجندل أطلال حي قديم ببيوت حجرية متلاصقة وأزقة مسقوفة بالأقواس، يجاور مسجد عمر بن الخطاب وقلعة مارد.','<div class="texte" > <p>حي الدرع هو عبارة عن أطلال حي في وسط دومة الجندل ضمن المنطقة الأثرية بجوار مسجد عمر بن الخطاب، يقع في محافظة الجوف شمال المملكة العربية السعودية .</p> <p>حي الدرع يتكون من بيوت حجرية متلاصقة، وأزقته متصلة ببعضها البعض، وبعضها مغطى بأقواس، وتم رصف هذه الأزقة بالحجارة عام 1413 هـ، وبعض البيوت يتألف من دورين ومسقوف بالأثل وسعف النخيل، والحركة داخل الموقع خطرة لأن معظم بيوته آيلة للسقوط، يعتبر حي الدرع أحد الآثار الباقية من مدينة دومة الجندل القديمة والتي سلمت من معاول الهدم التي طالت سوق دومة الجندل، يعود تاريخ إنشاء الحي إلى العصر الإسلامي الوسيط، لكنها تقوم على طبقات أثرية وأساسات تعود إلى منتصف الألف الأول قبل الميلاد، ويتميز الحي بعقوده الحجرية ومبانيه الحجرية وأزقته ووقوعه بين البساتين ومسارب الماء التي كانت تؤمن الحياة لساكني الحي من العيون القريبة، كما أن الحي قائم على انقاض أحياء سابقة العهد، يتضح ذلك من خلال تعدد الطبقات وكذلك ظهور الطريق القديم للحي تحت المباني القائمة حاليا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169391-44999896.jpg?v=1643137092"]','https://cmsphoto.ww-cdn.com/resizeapi/2907c02358ec39843fe4ed10ad5aeece2018930a/480/',29.8126041,39.8669126,'حي الدرع الأثري دومة الجندل دومة الجندل','','','','https://www.saudi-guide.com/aljawf-region/i/60169391/al-dir-heritage-quarter-hy-aldraa-alathry',1,0,'حي درع اثري al dir'' heritage quarter تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169384,'aljawf-region','قرية كاف التراثية','Kaf Heritage Village','kaf-heritage-village-kry-kaf-altrathy','["التراث والثقافة"]','["heritage"]','قرية كاف التراثية في القريات بيوت طينية ومسجد ومدرسة حجرية بين النخيل والعيون الكبريتية، قرب قصر كاف وجبل الصعيدي.','<div class="texte" > <p>قرية كاف التراثية هي قرية قديمة تقع بالقرب من قصر كاف على بعد 27 كم من التجمع السكاني، وتتألف من بيوت طينية متلاصقة، تنتشر فيها مزارع النخيل ويتوسطها مسجد قديم مبني من الحجارة، وتضم مدرسة مبنية من الحجارة أيضاً بالطراز المعماري الإسلامي القديم، وتوجد في القرية منطقة سبخه إضافة إلى العديد من العيون الكبريتية الجارية التي تستخدم في ري مزارع النخيل، ويرتادها في الوقت الحاضر الكثير من الزوار للعلاج بالمياه الكبريتية من الأمراض الجلدية، وقد تم اختيار الموقع سياحيا لأهميته التراثية والعلاجية ولتكامله السياحي مع مواقع سياحية مجاورة مثل قصر كاف وقلعة الصعيدي، وبطرفها الشمالي جبل الصعيدي، وفي أعلاه قلعة تعود للعصر النبطي، ولقد أُستخدمت فيما بعد كحامية لطريق الحجاج، وكانت المادة المصنوعة منها الحجارة البركانية، أما الطريق الموصل لها فهو متعرج رُصفت جوانبه بالحجارة، ويوجد في الجهة الشمالية الشرقية من جبل الصعيدي قصر كبير يُنسب بنائهُ إلى الشيخ نوري الشعلان، وقد بُني من الحجر الرملي الكبير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169384-44999893.jpg?v=1643137072"]','https://cmsphoto.ww-cdn.com/resizeapi/6a650fc9b9b5bba5cbc9e6e5448b3d174c7a66e1/480/',31.3932906,37.4994325,'SA Kaf Al Qurayyat','','','','https://www.saudi-guide.com/aljawf-region/i/60169384/kaf-heritage-village-kry-kaf-altrathy',1,0,'قريه كاف تراثيه kaf heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169373,'aljawf-region','حي الضلع التاريخي','Al-Dhil'' Historic Quarter','al-dhil-historic-quarter-hy-aldlaa-altarykhy','["التراث والثقافة"]','["heritage"]','حي الضلع في سكاكا حي تاريخي على سفح التل تحت قلعة زعبل، ببيوت من الطين والحجر وأزقة مسقوفة بسعف النخيل والأثل.','<div class="texte" > <p>حي الضلع من أقدم الأحياء التاريخية في مدينة سكاكا، يقع على سفح التل الذي تعلوه قلعة زعبل في الطرف الشمالي الغربي من المدينة، ويشكّل معها ومع بئر سيسرا المجاورة نسيجاً تراثياً متكاملاً.</p><p>يتميز الحي ببيوته المتلاصقة المبنية من الطين والحجارة على الطراز المعماري الذي كان سائداً في منطقة الجوف قديماً، وبعض مبانيه من طابقين، وتتخلله أزقة متعددة سُقف بعضها بسعف النخيل وأغصان الأثل. وقد أُعيدت تهيئة الحي ليكون من الوجهات التراثية في المنطقة، ويُنصح بزيارته مع قلعة زعبل للاستمتاع بالإطلالة على سكاكا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169373-44999904.jpg?v=1643137116"]','https://cmsphoto.ww-cdn.com/resizeapi/725522d2af82d6ca0b6f01f1cff7d96cb2462cc9/480/',29.9925714,40.2024689,'X6V2+2X Sakakah Sakaka','','','','https://www.saudi-guide.com/aljawf-region/i/60169373/al-dhil-historic-quarter-hy-aldlaa-altarykhy',1,0,'حي ضلع تاريخي al dhil'' historic quarter تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169356,'aljawf-region','بئر سيسرا الأثري','Sisra Archaeological Well','sisra-archaeological-well-byr-sysra-alathry','["التراث والثقافة"]','["heritage"]','بئر سيسرا في سكاكا بئر أثرية منحوتة في الصخر غرب قلعة زعبل، لها درج صخري وفتحات سفلية كانت تغذيها مياه العيون القديمة.','<div class="texte" > <p>بئر سيسرا، هي من الآبار الأثرية في منطقة الجوف الواقعة في السعودية،&nbsp;وهي بئر منحوتة في الصخرغرب حصن زعبل، شُيّد على أحد جوانبها درج منحوت في الصخر وفي أسفلها توجد فتحة مستطيلة تتلوها فتحة أكبر، مما يؤكد أن هذه البئر كانت مصدراً لمياه العيون القديمة بالمنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169356-44999891.jpg?v=1643137051"]','https://cmsphoto.ww-cdn.com/resizeapi/b8baa84976ed737cbae9cebac8d0de781e38b0ea/480/',29.99191,40.198315,'X5RX+Q88 Aldil'' Sakaka','','','','https://www.saudi-guide.com/aljawf-region/i/60169356/sisra-archaeological-well-byr-sysra-alathry',1,0,'بئر سيسرا اثري sisra archaeological well تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169325,'aljawf-region','متحف النويصر','Al-Nuwaiser Museum','al-nuwaiser-museum-mthf-alnoysr','["التراث والثقافة"]','["heritage"]','متحف النويصر للتراث في دومة الجندل متحف خاص بجوار قلعة مارد، يعرض عملات ومصاحف وحلياً وأسلحة وأدوات الحياة التقليدية.','<div class="texte" > <p>متحف النويصر للتراث أحد متاحف منطقة الجوف شمال المملكة العربية السعودية، يقع المتحف في دومة الجندل , أسسه علي بن نويصر الحسن، يشغل المتحف مبنى الامارة القديم بجانب قلعة مارد، ويحتوي على صالتين وخيمة تراثية وثلاث غرف وسوق شعبي لبيع التراث من سبع غرف،&nbsp;الصالتين عرض بها العمـلات والمسكوكات القديمة والمصاحف والحلي والسيوف والبنادق والدروع والسـجاد وأدوات الحياكة وأدوات الضيافة والقهوة العربية وأدوات الزراعة، بالإضافة إلى خيمة تراثية متكاملة وثلاث غرف بها محنطات ومتحجرات، والسوق الشعبي عرضت به الطوابع والعملات وقطع تراثية وشعبية متنوعة.</p> </div>','[]','',29.8203988,39.8506147,'RVC2+565 Al Tahkim Dumah Al Jandal','','','','https://www.saudi-guide.com/aljawf-region/i/60169325/al-nuwaiser-museum-mthf-alnoysr',1,0,'متحف نويصر al nuwaiser museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169305,'aljawf-region','مدينة الجوف الترفيهية','Al-Jouf Amusement City','al-jouf-amusement-city-mdyn-algof-altrfyhy','["التراث والثقافة"]','["heritage"]','مدينة الجوف الترفيهية في سكاكا وجهة عائلية تضم ألعاباً للأطفال ومساحات خضراء ومطاعم ومقاهي، مناسبة للنزهة والترفيه.','<div class="texte" > <p>مدينة الجوف الترفيهية وجهة عائلية في حي السليمانية بمدينة سكاكا، تجمع بين الألعاب الترفيهية للأطفال من مختلف الأعمار والمساحات الخضراء المفتوحة.</p><p>تضم المدينة حدائق وجلسات للعائلات إلى جانب مطاعم ومقاهي ومتاجر، وتستضيف فعاليات ترفيهية في المواسم والإجازات، وتعد خياراً مناسباً لقضاء أمسية ممتعة خاصة في فصلي الخريف والشتاء حين تعتدل الأجواء في الجوف.</p> </div>','[]','',29.9831148,40.1731025,'السليمانية سكاكا سكاكا','','','','https://www.saudi-guide.com/aljawf-region/i/60169305/al-jouf-amusement-city-mdyn-algof-altrfyhy',1,0,'مدينه جوف ترفيهيه al jouf amusement city تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169304,'aljawf-region','متحف الجوف الإقليمي','Al-Jouf Regional Museum','al-jouf-regional-museum-mthf-algof-alaklymy','["التراث والثقافة"]','["heritage"]','متحف الجوف الإقليمي للآثار والتراث في دومة الجندل قرب قلعة مارد، يعرض تاريخ المنطقة عبر العصور ومقتنياتها الأثرية.','<div class="texte" > <p>متحف الجوف الإقليمي للآثار والتراث الشعبي أحد أبرز المتاحف في شمال المملكة، يقع في محافظة دومة الجندل على مقربة من قلعة مارد ومسجد عمر بن الخطاب وحي الدرع، ضمن المنطقة التاريخية للبلدة القديمة.</p><p>تضم صالة العرض لوحات توضيحية تسرد تاريخ منطقة الجوف وفق تسلسلها الزمني، إلى جانب مقتنيات أثرية من المنطقة ومعروضات من التراث الشعبي تعكس حياة الأهالي قديماً. ويعد المتحف محطة مثالية لبدء جولة في معالم دومة الجندل التاريخية وفهم قصتها قبل زيارتها.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169304-44999887.jpg?v=1643137028"]','https://cmsphoto.ww-cdn.com/resizeapi/8b1d647a103087f6884f046b9cc148a6bcb1a0fa/480/',29.8099172,39.8670331,'RV68+2R Alkhaldiyah Dumah Al Jandal','','','','https://www.saudi-guide.com/aljawf-region/i/60169304/al-jouf-regional-museum-mthf-algof-alaklymy',1,0,'متحف جوف اقليمي al jouf regional museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169302,'aljawf-region','قلعة زعبل','Zaabal Castle','zaabal-castle-klaa-zaabl','["التراث والثقافة"]','["heritage"]','قلعة زعبل حصن تاريخي على قمة جبل شمال غرب سكاكا، بسور من الحجر والطين وأربعة أبراج، ويطل على حي الضلع وبئر سيسرا.','<div class="texte" > <p>قلعة زعبل هي قلعة أثرية تقع في مدينة سكاكا في منطقة الجوف وتقع على رأس جبل في الطرف الشمالي الغربي للمدينة&nbsp;وهي عبارة عن سور مبني من الحجر والطين وله أربعة أبراج في زواياه ويتم الوصول إلى القلعة بواسطة طريق وحيد ومتعرج وقد وقفت القلعة حامية للمدينة فترة طويلة من الزمن بسبب قوة تحصيناتها وصعوبة الوصول إليها، ويتداول الأهالي قصصاً أسطورية عن هذه القلعة ووقوفها صامدة في وجه الغزاة الذين أرادوا هدمها لأهميتها الاستراتيجية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169302-44999884.jpg?v=1643137005"]','https://cmsphoto.ww-cdn.com/resizeapi/83d8fd04f2bbc110bfd011f155c1636e5ac7c19c/480/',29.9930637,40.2019113,'الضلع، Sakakah Sakaka','','','','https://www.saudi-guide.com/aljawf-region/i/60169302/zaabal-castle-klaa-zaabl',1,0,'قلعه زعبل zaabal castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169301,'aljawf-region','قلعة مارد الأثرية','Marid Castle','marid-castle-klaa-mard-alathry','["التراث والثقافة"]','["heritage"]','قلعة مارد في دومة الجندل من أقدم القلاع في الجزيرة العربية، تعود إلى القرن الأول الميلادي وتطل على البلدة القديمة.','<div class="texte" > <p>قلعة مارد هي قلعة تاريخية حربية تقع بمدينة دومة الجندل بمنطقة الجوف، وتبعد عن مدينة سكاكا حوالي 50 كم، ويعود تاريخها إلى القرن الأول الميلادي، وأقدم ذكر لها يعود للقرن الثالث الميلادي حيث ذكرتها الملكة الزباء (240 - 274) حينما غزت دومة الجندل وتيماء ولم تستطع اقتحام القلعة فقالت: "تمرد مارد وعز الأبلق".</p> <p>تقع القلعة على ربوة ارتفاعها 620 م تقريباً فوق سطح البحر، وتطل على مدينة دومة الجندل التابعة لمنطقة الجوف من الجهة الغربية، وهو ما ساهم في قوة تحصينها حيث يستطيع المطل من القلعة أن يشرف على جميع أجزاء البلدة ويرى القادم إليها من مسافات بعيدة،&nbsp;سميت قلعة مارد بهذا الاسم لتمردها واستعصائها على من يحاول اقتحامها كما ذكر ياقوت الحموي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169301-44999879.jpg?v=1643136987"]','https://cmsphoto.ww-cdn.com/resizeapi/f871fdb35ac67c1252e035fe9f31026a663fcf90/480/',29.8113826,39.8673275,'طريق الملك سعود Alkhaldiyah Dumah Al Jandal','','','','https://www.saudi-guide.com/aljawf-region/i/60169301/marid-castle-klaa-mard-alathry',1,0,'قلعه مارد اثريه marid castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169300,'aljawf-region','أعمدة الرجاجيل','Rajajil Columns','rajajil-columns-aaamd-alrgagyl','["التراث والثقافة"]','["heritage"]','أعمدة الرجاجيل جنوب سكاكا من أقدم المواقع الأثرية في الجوف، مجموعات من الأعمدة الحجرية المنتصبة تشبه الرجال من بعيد.','<div class="texte" > <p>أعمدة الرجاجيل، موقع أثري يعد أقدم المواقع الأثرية في منطقة الجوف في السعودية، يقع في ضاحية قارة جنوب سكاكا، ويتكون من 50 مجموعة من الأعمدة الحجرية المنتصبة والمسماة بالرجاجيل، وتتكون من عدد من الأعمدة الحجرية المنحوتة من الحجر الرملي، ويتراوح عددها من ثلاثة إلى سبعة أعمدة، ويصل ارتفاع بعض الأعمدة القائمة إلى أعلى من ثلاثة أمتار، فيما تبلغ سماكتها نحو 60 سنتيمترا،&nbsp;سميت بالرجاجيل لكونها تشبه الرجل في هيئته إذا ما شوهدت من مسافة بعيدة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169300-44999871.jpg?v=1643136940"]','https://cmsphoto.ww-cdn.com/resizeapi/8300e85275ae47ea7919c7ace68c221435870896/480/',29.8128876,40.2196684,'Sakaka Sakaka Al Jowf','','','','https://www.saudi-guide.com/aljawf-region/i/60169300/rajajil-columns-aaamd-alrgagyl',1,0,'اعمده رجاجيل rajajil columns تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169248,'aljawf-region','محمية واحة الأمازون','Amazon Oasis Reserve','amazon-oasis-reserve-mhmy-oah-alamazon','["أماكن سياحية"]','["sights"]','محمية واحة الأمازون في دومة الجندل مزرعة ومحمية خاصة تضم أعداداً كبيرة من طيور الزينة والحيوانات بين النخيل والخضرة.','<div class="texte" > <p>محمية واحة الأمازون وجهة سياحية خاصة في محافظة دومة الجندل، اشتهرت باحتضانها أعداداً كبيرة من طيور الزينة المتنوعة، إلى جانب حيوانات أليفة ومساحات زراعية خضراء بين أشجار النخيل.</p><p>تستقطب المحمية العائلات والأطفال ومحبي الطيور والتصوير، وتمنح الزائر تجربة مختلفة في قلب واحة دومة الجندل، ويمكن الجمع بين زيارتها وزيارة المعالم التاريخية القريبة مثل قلعة مارد ومسجد عمر بن الخطاب وبحيرة دومة الجندل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169248-44999877.jpg?v=1643136965"]','https://cmsphoto.ww-cdn.com/resizeapi/be04c9cd82b13bf3a1625525f32f088f75c3bd37/480/',29.843138,39.8519397,'Dumah Al Jandal Al Safah Al Shimali Dumat Al-Jandal','','','','https://www.saudi-guide.com/aljawf-region/i/60169248/amazon-oasis-reserve-mhmy-oah-alamazon',1,0,'محميه واحه امازون amazon oasis reserve اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60169246,'aljawf-region','منتزه بحيرة دومة الجندل','Dumat Al-Jandal Lake Park','dumat-al-jandal-lake-park-mntzh-bhyr-dom-algndl','["أماكن سياحية"]','["sights"]','بحيرة دومة الجندل بحيرة صناعية واسعة تحيط بها الكثبان والنخيل، ومنتزه مفتوح للتنزه وقضاء الوقت على ضفافها في الجوف.','<div class="texte" > <p>بحيرة دومة الجندل هي بحيرة ليست طبيعية بل إصطناعية ونشأت في دومة الجندل التابعة لمنطقة الجوف شمال المملكة العربية السعودية،&nbsp;وتعد البحيرة الصناعية&nbsp;الأكبر في الجزيرة العربية بصفة عامة.</p> </div>  <div class="texte" > <p>تقع البحيرة شرق مدينة دومة الجندل وتحيط بها الكثبان الرملية ومزارع النخيل، ما يمنحها مشهداً فريداً يجمع بين الماء والصحراء. ويقصدها الأهالي والزوار للتنزه والجلسات العائلية والتصوير، خاصة وقت الغروب، وتعد من أبرز المعالم الطبيعية في منطقة الجوف إلى جانب معالمها التاريخية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60169246-44999864.jpg?v=1643136920"]','https://cmsphoto.ww-cdn.com/resizeapi/ae586bf916743c538c3d4bc6ddc4c21fc5815dcc/480/',29.8074738,39.908042,'RW45+X6M Dumah Al Jandal Dumat Al-Jandal','','','','https://www.saudi-guide.com/aljawf-region/i/60169246/dumat-al-jandal-lake-park-mntzh-bhyr-dom-algndl',1,0,'منتزه بحيره دومه جندل dumat al jandal lake park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60149028,'hail','جبل أم سنمان','Umm Sinman Mountain','umm-sinman-mountain-gbl-am-snman','["التراث والثقافة"]','["heritage"]','جبل أم سنمان غرب جبة في حائل، يضم نقوشاً ورسوماً صخرية لإنسان ما قبل التاريخ، وهو جزء من موقع الفنون الصخرية في حائل المسجل في قائمة التراث العالمي لليونسكو.','<div class="texte" > <p>جبل أم سنمان أحد جبال منطقة حائل شمال المملكة العربية السعودية، يقع غرب مدينة جبة التي تبعد نحو 100 كيلومتر شمال غرب حائل وسط صحراء النفود. وتُعد جبة من أهم المواقع الأثرية في المملكة، إذ تنتشر النقوش والرسوم الصخرية في جبل أم سنمان والجبال القريبة منه، وتعود إلى فترات زمنية مختلفة.</p> <p>والمنطقة في الأصل أرض بحيرة قديمة تحيط بها كثبان النفود الكبير، وتعلوها من الغرب والجنوب جبال رسوبية أبرزها أم سنمان وغوطا وشويحط وعنيزة. وفي عام 2015م سُجل موقع «الفنون الصخرية في منطقة حائل» الذي يضم جبل أم سنمان في جبة وجبلي المنجور وراط في الشويمس ضمن قائمة التراث العالمي لمنظمة اليونسكو.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60149028-44970443.jpg?v=1642949009"]','https://cmsphoto.ww-cdn.com/resizeapi/56a7d4e0b4c5a5395fd9d9ca99b85f66885059c6/480/',28.0129468,40.914825,'2W77+5WG Jubbah Hail','','','','https://www.saudi-guide.com/hail/i/60149028/umm-sinman-mountain-gbl-am-snman',1,0,'جبل ام سنمان umm sinman mountain تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60149024,'hail','متحف العيادة التراثي','Al Eyadah Heritage Museum','al-eyadah-heritage-museum-mthf-alaayad-altrathy','["التراث والثقافة"]','["heritage"]','متحف العيادة التراثي في محافظة جبة بمنطقة حائل، يعرض مقتنيات وأدوات تراثية تعكس تاريخ المنطقة وحياة الأجداد، ويقصده المهتمون بالتراث المحلي.','<div class="texte" > <p>متحف العيادة التراثي بمحافظة جبة يعرض مجموعة من المقتنيات والأدوات التراثية التي تعكس تاريخ المنطقة وحياة الأجداد، ويُعد أحد أهم متاحف منطقة حائل التي تجذب الزوار والمهتمين بالتراث المحلي.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60149024-44970447.jpg?v=1642949025"]','https://cmsphoto.ww-cdn.com/resizeapi/fcc034024f0db6ec105df2cc775caf0e9618df89/480/',28.0282304,40.9361727,'2WHP+7FV Jubbah Hail','','','','https://www.saudi-guide.com/hail/i/60149024/al-eyadah-heritage-museum-mthf-alaayad-altrathy',1,0,'متحف عياده تراثي al eyadah heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60149022,'hail','متحف قصر النايف التراثي','Al Naif Palace Museum','al-naif-palace-museum-mthf-ksr-alnayf-altrathy','["التراث والثقافة"]','["heritage"]','متحف قصر النايف في جبة أسسه سعود بن نايف الرمالي الشمري، ويضم نحو 2165 قطعة تشمل أدوات القهوة والحلي والملابس والنحاسيات والأسلحة والمصنوعات الجلدية.','<div class="texte" > <p>متحف قصر النايف الأثري، أحد متاحف منطقة حائل، أسسه سعود بن نايف بن عتيق الرمالي الشمري، المتحف عبارة عن دور أرضي واسع مقسم إلى سبعة أجزاء مختلفة المساحات يضم ما يقارب 2165 قطعة تقريبا،&nbsp;وتشمل المقتنيات أدوات القهوة، وبعض الملابس والحلي وأدوات الزينة النسائية القديمة وكذلك أدوات الخياطة والمصنوعات الجلدية كالقرب والنطع والعديد من الأدوات النحاسية المتمثلة في دلال القهوة والسحال والصفاري لحفظ ماء الشرب، كما يشمل مجموعة من الاسلحة وأدوات الحرب،&nbsp;يتنوع أسلوب العرض بالمتحف باستخدام خزائن العرض الزجاجية والإستاندات والأرفف والدواليب فيما تم عرض القطع الثقيلة على الأرض حيث يتم عرض وتوزيع القطع حسب الوظيفة والمادة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60149022-44970460.jpg?v=1642949156"]','https://cmsphoto.ww-cdn.com/resizeapi/3176d2a36fe3650501430eb1eb0844c2c4f2b7a9/480/',28.0309493,40.9400851,'SA جبــــة حائل','','','','https://www.saudi-guide.com/hail/i/60149022/al-naif-palace-museum-mthf-ksr-alnayf-altrathy',1,0,'متحف قصر نايف تراثي al naif palace museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60149017,'hail','قصر العفنان التاريخي','Al Afnan Historic Palace','al-afnan-historic-palace-ksr-alaafnan-altarykhy','["التراث والثقافة"]','["heritage"]','قصر العفنان التاريخي في محافظة السبعان بمنطقة حائل، من المعالم الأثرية التي تعكس طراز العمارة الطينية التقليدية وتروي جانباً من تاريخ المنطقة.','<div class="texte" > <p>قصر العفنان التاريخي بمحافظة السبعان يعد من المعالم الأثرية القديمة بمنطقة حائل، ويعكس طراز العمارة التقليدية للمنطقة، ويستحضر بجدرانه الطينية قصصاً من تاريخ حائل العريق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60149017-44970451.jpg?v=1642949051"]','https://cmsphoto.ww-cdn.com/resizeapi/f305ea9c4620e93e54b5ac44f20963773a2d0efa/480/',27.0398675,41.974602,'2XQF+WRX السبعان الشنان','','','','https://www.saudi-guide.com/hail/i/60149017/al-afnan-historic-palace-ksr-alaafnan-altarykhy',1,0,'قصر عفنان تاريخي al afnan historic palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60149006,'hail','متحف فيد الجديد','New Fayd Museum','new-fayd-museum-mthf-fyd-algdyd','["التراث والثقافة"]','["heritage"]','متحف فيد الجديد قرب مدينة فيد الأثرية في حائل، يضم قطعاً أثرية مكتشفة في محيط المدينة التي كانت محطة رئيسية على درب زبيدة بين الكوفة ومكة المكرمة.','<div class="texte" > <p>متحف فيد الجديد يقع بالقرب من مدينة فيد الأثرية بمنطقة حائل، ويضم مجموعة من القطع الأثرية المكتشفة في محيط المدينة التاريخية التي كانت محطة رئيسية في منتصف درب زبيدة، طريق الحج بين الكوفة ومكة المكرمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60149006-44970459.jpg?v=1642949135"]','https://cmsphoto.ww-cdn.com/resizeapi/a28300e73831df3f81fa40dde2402da316e7157d/480/',27.1204649,42.5244877,'Fayd Al Shinan Hail Province','','','','https://www.saudi-guide.com/hail/i/60149006/new-fayd-museum-mthf-fyd-algdyd',1,0,'متحف فيد جديد new fayd museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60149004,'hail','مدينة فيد الأثرية','Fayd Historic City','fayd-historic-city-mdyn-fyd-alathry','["التراث والثقافة"]','["heritage"]','مدينة فيد الأثرية جنوب شرق حائل محطة رئيسية على درب زبيدة، تضم قصر خراش وبرك زبيدة والآبار والقنوات المائية ونقوشاً تعود لعصور ما قبل التاريخ.','<div class="texte" > <p>فيد هي مدينة تاريخية تقع إلى الجنوب الشرقي من منطقة حائل، وتعتبر أحد الأمكنة الأثرية التاريخية للمنطقة إذ تختزن جبالها نقوشاً تاريخية تعود إلى عصور ما قبل التاريخ، فضلا عن كونها محطة رئيسية في درب زبيدة حيث تقع في منتصف الطريق بين مكة وبغداد، وكانت مسجلة ضمن ولايات الخلافة العباسية، وهي غنية بالآثار الإسلامية، ولها أهمية ومكانة تاريخية،&nbsp;تبعد مدينة فيد عن حائل 92 كم على الطريق السريع الذي يربط حائل بالقصيم، كما تبعد 160 كم عن القصيم. من أهم آثار مدينة فيد، قصر خراش، وبرك زبيدة، والمدينة السكنية، والسراديب، ومنطقة التلال، وفسقية القصر، والرحى العملاق لطحن الحبوب، والآبار حيث فيها ما يقارب 45 بئراً، والقنوات المائية،&nbsp;يرجع تاريخ المدينة إلى العصور الإسلامية الأولى. كما أعلن مؤخراً عن تطوير مدينة فيد التاريخية سياحياً.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60149004-44970434.jpg?v=1642948955"]','https://cmsphoto.ww-cdn.com/resizeapi/09ce49ae1fb33c4026f0f3a9f0aa530f639f78cc/480/',27.1136271,42.5264409,'4G7G+FH4 Fayd Al Shinan','','','','https://www.saudi-guide.com/hail/i/60149004/fayd-historic-city-mdyn-fyd-alathry',1,0,'مدينه فيد اثريه fayd historic city تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148988,'hail','نقوش راط والمنجور','Rat and Al Manjor Rock Art','rat-and-al-manjor-rock-art-nkosh-rat-oalmngor','["التراث والثقافة"]','["heritage"]','راط والمنجور موقعان للفنون الصخرية غرب الشويمس جنوب حائل، يضمان رسوماً صخرية قديمة يُعتقد أن عمرها يصل إلى آلاف السنين، ضمن موقع مسجل في اليونسكو.','<div class="texte" > <p>راط والمنجور هما موقعان أثريان يقعان في الجنوب من مدينة حائل على بعد حوالي 320 كم منها، وإلى الغرب من قرية الشويمس التابعة لمدينة الحائط بحوالي 35 كم منها، ويعد الموقعان من الاكتشافات الجديدة في ساحة الآثار في حائل، وهذا ما استدل به الخبراء الدوليون بعد جهد كبير من الدراسات التحليلية من الرسومات المكتشفة في الشويمس، التي قد يعود عمرها إلى 14.000 عام مضت.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148988-44970431.jpg?v=1642948941"]','https://cmsphoto.ww-cdn.com/resizeapi/a1160aacde7303837ad6451af5ffcc072e31a680/480/',26.1275633,39.9190777,'SA Al Hait Hail Province','','','','https://www.saudi-guide.com/hail/i/60148988/rat-and-al-manjor-rock-art-nkosh-rat-oalmngor',1,0,'نقوش راط والمنجور rat and al manjor rock art تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148937,'hail','قرية فدك التراثية','Fadak Heritage Village','fadak-heritage-village-kry-fdk-altrathy','["التراث والثقافة"]','["heritage"]','قرية فدك التراثية في محافظة الحائط جنوب غرب حائل، واحة تاريخية عريقة بمياهها ونخيلها، تضم حصوناً مبنية بالحجارة البركانية ونقوشاً للملك البابلي نابونيد.','<div class="texte" > <p>فدك واحة تاريخية عريقة تقع في محافظة الحائط جنوب غرب مدينة حائل على بعد نحو 250 كيلومتراً، وكانت منذ القدم واحة زراعية مهمة لوفرة مياهها وخصوبة تربتها، واشتهرت بزراعة النخيل والحبوب، ولا تزال عيونها ونخيلها شاهدة على ذلك.</p> <p>شهدت فدك أحداثاً تاريخية بارزة، فقد وصلها الملك البابلي نابونيد في حملته على شمال غرب الجزيرة العربية في القرن السادس قبل الميلاد، وعُثر فيها على نقوش تعود إليه. وفي العهد النبوي صالح أهلُها المسلمين بعد فتح خيبر. وتضم المنطقة قلاعاً وحصوناً قديمة مبنية بالحجارة البركانية السوداء، إلى جانب نقوش ثمودية وإسلامية مبكرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148937-44970427.jpg?v=1642948924"]','https://cmsphoto.ww-cdn.com/resizeapi/4ccdf4f28f108525cf05e786805a9277faddb9e8/480/',25.9784488,40.4701248,'Al Hayit Al Hait Hail Province','','','','https://www.saudi-guide.com/hail/i/60148937/fadak-heritage-village-kry-fdk-altrathy',1,0,'قريه فدك تراثيه fadak heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148934,'hail','سوق الحائط الشعبي','Al Hait Traditional Market','al-hait-traditional-market-sok-alhayt-alshaaby','["التراث والثقافة"]','["heritage"]','سوق الحائط الشعبي سوق تقليدي في محافظة الحائط بمنطقة حائل، يضم محلات للمنتجات المحلية والحرف اليدوية، ويعكس الطابع التراثي وعادات أهل المنطقة.','<div class="texte" > <p>سوق الحايط الشعبي بمحافظة الحائط سوق تقليدي يعكس الطابع التراثي للمنطقة، ويضم محلات تعرض المنتجات المحلية والحرف اليدوية، ويُعد وجهة محببة لمحبي التسوق التقليدي والتعرف على عادات أهل المنطقة.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148934-68541188.jpg?v=1791534182"]','https://cmsphoto.ww-cdn.com/resizeapi/70d5d3e65d388f4995c283b9e1c463462a5f36c4/480/',25.9972534,40.4621184,'XFW6+WR5 Al Hait Al Hait','','','','https://www.saudi-guide.com/hail/i/60148934/al-hait-traditional-market-sok-alhayt-alshaaby',1,0,'سوق حائط شعبي al hait traditional market تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148890,'hail','متحف الضويلي التراثي','Al Dowaili Heritage Museum','al-dowaili-heritage-museum-mthf-aldoyly-altrathy','["التراث والثقافة"]','["heritage"]','متحف الضويلي التراثي في حائل أسسه مصعب حامد الغفيلي الشمري، ويقع في مبنى من دورين بمساحة 500 متر مربع يضم صالة للقطع النادرة وأقساماً بأسقف مقببة.','<div class="texte" > <p>متحف الضويلي، أحد متاحف منطقة حائل، أسسه مصعب حامد الغفيلي الشمري، يقع المتحف داخل بناء حديث يتكون من دورين مجموع مساحتهما 500 متر مربع تضم ضمن تقسيماتها صالة عرض للقطع النادرة والثمينة وكذلك عدة أقسام ذات أسقف مقببه حيث يتم عرض جميع المقتنيات تحت تلك القباب.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148890-44970345.jpg?v=1642947952"]','https://cmsphoto.ww-cdn.com/resizeapi/8ea2ef07a7e41d6ac9105c9811984b0e595d25db/480/',27.5525775,41.6734669,'HM3F+29P Al Muntazah Al Gharbi Hail','','','','https://www.saudi-guide.com/hail/i/60148890/al-dowaili-heritage-museum-mthf-aldoyly-altrathy',1,0,'متحف ضويلي تراثي al dowaili heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148888,'hail','مقهى ومتحف أجا وسلمى','Aja and Salma Cafe and Museum','aja-and-salma-cafe-and-museum-mkha-omthf-aga-oslma','["التراث والثقافة"]','["heritage"]','متحف أجا وسلمى للتراث في حائل أسسه فهد المحمد الطوب، يضم أسلحة وعملات قديمة وأدوات ضيافة ومبنى تراثياً على طراز حائل ومجموعة من السيارات القديمة.','<div class="texte" > <p>متحف أجا وسلمى للتراث، أحد متاحف منطقة حائل، أسسه فهد المحمد الطوب، يقع المتحف ضمن منطقة خصصها المالك للأنشطة الاجتماعية بمدينة حائل. ويحتل المتحف مساحة 4500 متر مربع، ويتكون من: قاعة رئيسية مساحتها 480 متر، وتضم العديد من الأسلحة القديمة التي كانت تستخدم قديمًا في الحروب، والعملات القديمة، والأدوات المستخدمة في الضيافة العربية بكميات كبيرة، ومبنى تراثي به مجموعة من الغرف مبنية على طراز العمارة القديم بمنطقة حائل، ومعروض بها “جلديات ـ ابواب خشبية ـ أدوات السقيا و الترحال ـ ملابس ـ صوفيات ـ نموذج لدار المصخن بالتجهيزات – غرفة لجلسة عائلية”، ومجموعة من السيارات القديمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148888-44970344.jpg?v=1642947937"]','https://cmsphoto.ww-cdn.com/resizeapi/5eee5f9fd3e3252c5585dc7fd9c43c5c2b9c0d52/480/',27.4860853,41.6656736,'Hail An Nuqrah Hail','','','','https://www.saudi-guide.com/hail/i/60148888/aja-and-salma-cafe-and-museum-mkha-omthf-aga-oslma',1,0,'مقهي ومتحف اجا وسلمي aja and salma cafe and museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148885,'hail','المطعم التراثي','Al Turathi Restaurant','al-turathi-restaurant-almtaam-altrathy','["التراث والثقافة"]','["heritage"]','المطعم التراثي في وسط حائل مطعم ومتحف في مبنى طيني قديم من دورين وسقف من خشب الأثل، يقدم الأكلات الشعبية ويعرض مقتنيات تراثية وأسلحة ودلال قهوة.','<div class="texte" > <p>المطعم التراثي في وسط مدينة حائل تجربة تجمع بين المطعم والمتحف، أسسه عيد الحربي في مبنى طيني قديم يزيد عمره على مئة عام، سقفه من خشب الأثل، ويتكون من دورين يضمان نحو 35 غرفة على مساحة تقارب 1200 متر مربع، مع جلسات على السطح تطل على معالم حائل.</p> <p>يقدم المطعم الأكلات الشعبية الحائلية، ويتجول زواره بين غرفه الطينية التي تعرض مقتنيات تراثية متنوعة من أسلحة وأوانٍ منزلية ودلال قهوة وأباريق شاي قديمة وحلي وقطع سجاد.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148885-44970456.jpg?v=1642949109"]','https://cmsphoto.ww-cdn.com/resizeapi/e5c70d95b93c8eff83926d242fde012a7049ecfa/480/',27.5218204,41.6957095,'Al Mahattah Hail Hail','','','','https://www.saudi-guide.com/hail/i/60148885/al-turathi-restaurant-almtaam-altrathy',1,0,'مطعم تراثي al turathi restaurant تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148837,'hail','قصر القشلة التاريخي','Al Qishlah Historic Palace','al-qishlah-historic-palace-ksr-alkshl-altarykhy','["التراث والثقافة"]','["heritage"]','قصر القشلة في حائل بُني عام 1360هـ في عهد الملك عبدالعزيز على الطراز النجدي بزخارف جصية حائلية، ويمتد على مساحة تقارب 20 ألف متر مربع.','<div class="texte" > <p>قصر القشلة هو قصر تاريخي بني في عهد الملك عبد العزيز آل سعود في سنة 1360 للهجرة / 1941 للميلاد في مدينة حائل،&nbsp;استمر بناء القصر سنةً ونصف، ثم أضيف إليه المسجد ومبنى السجن وبعض الملحقات الأخرى والتي انتهى بناؤها في 1362 للهجرة،&nbsp;القصر بني على أسلوب أسلوب المدرسة النجدية في البناء ولكن زخارفه الجصية سمة من سمات العمارة التقليدية في حائل، وهذه الزخارف من الجص الزين بالعناصر الهندسية والنباتية،&nbsp;تبلغ مساحة المبنى 19,932 متراً مربعاً،&nbsp;بعض هذه الزخارف تشمل كتابات منها "يعيش مولانا الملك المعظم عبد العزيز بن عبد الرحمن آل سعود".</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148837-44970343.jpg?v=1642947919"]','https://cmsphoto.ww-cdn.com/resizeapi/d0410738f3c3b6d24d130e753976a4d14c0b001a/480/',27.5190979,41.6943175,'5668 نجد، Al Mahattah','','','','https://www.saudi-guide.com/hail/i/60148837/al-qishlah-historic-palace-ksr-alkshl-altarykhy',1,0,'قصر قشله تاريخي al qishlah historic palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148834,'hail','متحف لقيت للماضي أثر','Laqeet Lilmadi Athar Museum','laqeet-lilmadi-athar-museum-mthf-lkyt-llmady-athr','["التراث والثقافة"]','["heritage"]','متحف لقيت للماضي أثر في حي لبدة بمدينة حائل قرب قلعة أعيرف، متحف تراثي يعرض مقتنيات قديمة تروي ملامح الحياة الماضية في منطقة حائل.','<div class="texte" > <p>متحف «لقيت للماضي أثر» من المتاحف التراثية في مدينة حائل، ويقع في حي لبدة على مقربة من قلعة أعيرف التاريخية، ويعرض مجموعة من المقتنيات القديمة التي تروي ملامح الحياة اليومية في منطقة حائل قديماً، ويقصده المهتمون بالتراث والزوار الراغبون في التعرف على ماضي المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148834-44986522.jpg?v=1643066459"]','https://cmsphoto.ww-cdn.com/resizeapi/2cac662e258a08c2eb0858e2537d08b211bf35c7/480/',27.5160904,41.7026873,'GP83+C3M Labdah Hail','','','','https://www.saudi-guide.com/hail/i/60148834/laqeet-lilmadi-athar-museum-mthf-lkyt-llmady-athr',1,0,'متحف لقيت للماضي اثر laqeet lilmadi athar museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148832,'hail','قلعة أعيرف','Aarif Fort','aarif-fort-klaa-aaayrf','["التراث والثقافة"]','["heritage"]','قلعة أعيرف التاريخية فوق جبل يشرف على قلب مدينة حائل، يُعتقد أنها بُنيت نحو عام 1840م، وتعد من أبرز معالم حائل التراثية ويمكن رؤيتها من أنحاء المدينة.','<div class="texte" > <p>قلعة عيرف أو أعيرف قلعة قديمة تقع في منطقة حائل شمال المملكة العربية السعودية، تقع قلعة عيرف التاريخية في قلب مدينة حائل فوق قمة جبل يشرف على المدينة، والذي تنسب إليه تسميه القلعة بهذا الاسم. يُعتقد أن القلعة قد بنيت في عام 1840،&nbsp;وتعتبر أحد معالم حائل التراثية، وتمتاز بموقعها الذي يسهل رؤيتها من كافة أنحاء المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148832-44970342.jpg?v=1642947902"]','https://cmsphoto.ww-cdn.com/resizeapi/9be0141763c9ea3f0607c242180e83186c09a9fd/480/',27.5170707,41.7034705,'Ar Riyadh Labdah Hail','','','','https://www.saudi-guide.com/hail/i/60148832/aarif-fort-klaa-aaayrf',1,0,'قلعه اعيرف aarif fort تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148830,'hail','متحف حائل الإقليمي','Hail Regional Museum','hail-regional-museum-mthf-hayl-alaklymy','["التراث والثقافة"]','["heritage"]','متحف حائل الإقليمي بجوار مركز الأمير سلطان الحضاري، يروي تاريخ المنطقة منذ ما قبل التاريخ مروراً بالعصر الإسلامي، ويضم كنوزاً أثرية ومقتنيات ومخطوطات.','<div class="texte" > <p>متحف حائل الإقليمي، هو متحف ترفيهي سياحي مملوك لهيئة المتاحف السعودية، ويعد متحف حائل أحد أهم المتاحف في مدينة حائل، ويجذب اليه الكثير من الزوار وقد تم بناءه لتوعية وتثقيف المجتمع.</p> <p>متحف حائل يروي لزواره تاريخ حقبة زمنية مرت بها الجزيرة العربية بشكل عام و«عروس الشمال» على وجه الخصوص منذ ما قبل التاريخ، مروراً ببدايات الإسلام وصولاً إلى المرحلة الحالية، وهو ما جعله واحداً من أهم المشاريع الثقافية على مستوى المنطقة،&nbsp;يقع المتحف في مدينة حائل مجاور لمركز الأمير سلطان الحضاري بحائل، على مساحة إجمالية تقدر 11.000 متر مربع،&nbsp;تم افتتاح المتحف في عام 2004م بعد عمليات التجديد،&nbsp;صُمم المتحف بشكل فريد مستوحى من عمارة حائل؛ حيث أن أن المتحف الإقليمي يشكل إضافة بالغة الأهمية للمشهد الثقافي والفني في المنطقة بما يحتويه من كنوز أثرية ومقتنيات تراثية ومخطوطات قديمة تتيح لجميع زوارها فرصة حقيقية للتجول بين الأزمنة والتعرف على التراث الحضاري للمملكة العربية السعودية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148830-44970339.jpg?v=1642947880"]','https://cmsphoto.ww-cdn.com/resizeapi/12eb29f01165378362c18d36db377ff5dc026460/480/',27.4773092,41.6978507,'FMGX+W4H Albuhayrah Hail','','','','https://www.saudi-guide.com/hail/i/60148830/hail-regional-museum-mthf-hayl-alaklymy',1,0,'متحف حائل اقليمي hail regional museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148826,'hail','منازل حاتم الطائي','Hatim Al Tai Houses','hatim-al-tai-houses-mnazl-hatm-altayy','["التراث والثقافة"]','["heritage"]','منازل حاتم الطائي في وادي توارن بجبل أجا شمال غرب حائل، تضم بقايا قصر توارن وقبر حاتم الطائي رمز الكرم العربي وموضع النار التي كان يوقدها للضيوف.','<div class="texte" > <p>يقع قصر توارن على بعد 65 كم شمال غرب مدينة حائل، في وادي توارن التاريخي والبيئي بجبل أجا، حيث يمكن لزائر الموقع يمكن مشاهدة بقايا قصر توارن، الأثر الوحيد المتبقي من قرية توارن الأثرية. القصر يعد من أهم المواقع الثقافية نظراً لارتباط اسمه بسيرة حاتم الطائي وبقبيلة طيء التي عاشت في هذا المكان، بالإضافة إلى ذلك يمكن لزائر الموقع مشاهدة قبر حاتم الطائي وقبر ابنته التي يعتقد أنها أدركت الإسلام بجانب القصر، ويمكن مشاهدة مكان موقد النار الذي كان حاتم الطائي يضيئه ليلاً لإرشاد الضيوف إلى بيته لاستضافتهم وإكرامهم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148826-44970337.jpg?v=1642947861"]','https://cmsphoto.ww-cdn.com/resizeapi/2ee7e40303930ae883375310fe090bb37c78cc52/480/',27.5862915,41.4443843,'SA Mawqaq Hail Province','','','','https://www.saudi-guide.com/hail/i/60148826/hatim-al-tai-houses-mnazl-hatm-altayy',1,0,'منازل حاتم طائي hatim al tai houses تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148820,'hail','حرة بني رشيد البركانية','Black and White Volcanoes','black-and-white-volcanoes-hr-bny-rshyd-albrkany','["أماكن سياحية"]','["sights"]','حرة بني رشيد جزء من حرة خيبر جنوب غرب حائل، تضم براكين نادرة أبرزها جبل الأبيض بصخوره البيضاء وفوهته الواسعة وجبل القدر بحممه البازلتية السوداء.','<div class="texte" > <p>حرة بني رشيد جزء من حرة خيبر الواقعة جنوب غرب منطقة حائل قرب حدودها مع منطقة المدينة المنورة، وهي حقل بركاني شاسع تبلغ مساحته نحو 14 ألف كيلومتر مربع، تكوّن بفعل ثورانات بركانية امتدت عبر ملايين السنين، وتغطيه الحمم والصخور البركانية السوداء.</p> <p>تشتهر الحرة ببراكينها النادرة، وأبرزها جبل الأبيض (البيضاء) الذي يتميز بصخوره البيضاء النادرة وفوهته الواسعة التي يقارب قطرها 1500 متر، وبجواره جبل القدر ذو الحمم البازلتية الداكنة، ما جعل الموقع يُعرف بالبراكين البيضاء والسوداء، ومقصداً لمحبي المغامرة والجيولوجيا والتصوير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148820-44970330.jpg?v=1642947844"]','https://cmsphoto.ww-cdn.com/resizeapi/9ebe844769d708825147affbe75489c5be50be34/480/',25.668954,39.9465604,'SA Al Hait Hail Province','','','','https://www.saudi-guide.com/hail/i/60148820/black-and-white-volcanoes-hr-bny-rshyd-albrkany',1,0,'حره بني رشيد بركانيه black and white volcanoes اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148817,'hail','أبو الهول في حائل','Abu Al Hol in Hail','abu-al-hol-in-hail-abo-alhol-fy-hayl','["أماكن سياحية"]','["sights"]','جبل أبو الهول في قرية أبا الحيران بسلسلة جبال أجا غرب حائل، تكوين صخري طبيعي نحتته عوامل التعرية فصار يشبه رأس إنسان كتمثال أبي الهول في مصر.','<div class="texte" > <p>جبل أبو الهول تكوين صخري طبيعي فريد يقع في قرية أبا الحيران ضمن سلسلة جبال أجا غرب مدينة حائل، ونحتته عوامل التعرية والتجوية عبر الزمن حتى صار يشبه رأس إنسان، ولذلك سُمي بأبي الهول لتشابهه مع التمثال الشهير في مصر.</p> <p>ويُعد الجبل من المعالم الطبيعية اللافتة في منطقة حائل، ويقصده الزوار وهواة التصوير للاستمتاع بالتشكيلات الصخرية المتنوعة التي تزخر بها جبال أجا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148817-44970328.jpg?v=1642947829"]','https://cmsphoto.ww-cdn.com/resizeapi/390a5799baa93b72398214706a05046a979e9a9a/480/',27.0562693,40.9852719,'3X4P+G42 ابا الحيران موقق','','','','https://www.saudi-guide.com/hail/i/60148817/abu-al-hol-in-hail-abo-alhol-fy-hayl',1,0,'ابو هول في حائل abu al hol in hail اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148815,'hail','جبال أجا','Aja Mountains','aja-mountains-gbal-aga','["أماكن سياحية"]','["sights"]','جبال أجا وسلمى أو جبال طيء العلامة المميزة لحائل، يقع أجا شمال غرب المدينة وسلمى جنوب شرقها ويفصل بينهما سهل البطين، وترتبط بهما أسطورة عربية قديمة.','<div class="texte" > <p>هما الجبلان أجا وسلمى أو جبال طيء، العلامة المميزة لمنطقة حائل، وتقع سلسلة جبال أجا في الجهة الشمالية الغربية من المدينة، بينما تقع سلسلة جبال سلمى في الجهة الشرقية الجنوبية، وأكبرهما جبل أجا ويفصل بينهما سهل البطين.</p> <p>يعود سبب تسميتهما بهذا الاسم لأسطورة قديمة تقول أن أجا كان رجلاً من إحدى قبائل العماليق التي تسكن تلك الناحية من الجزيرة العربية، وسلمى هو اسم فتاة كان يعشقها أجا، وهي تعشقه إلى حد الجنون ولكن رفض أهلهما تزويجهما بسبب بعض الأعراف القبلية،&nbsp;وفي يوم من الأيام هربت سلمى مع رفيقها أجا، ومعهما خادمتها واسمها العوجاء، فطاردهما القوم حتى أمسكوا بهما بين جبلي أجا وسلمى وهناك قتلوهما وصلبوهما، أجا على الجبل الغربي وسلمى على الجبل الشرقي، فحملا هذا الاسم حتى الآن.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148815-44970327.jpg?v=1642947815"]','https://cmsphoto.ww-cdn.com/resizeapi/380a0ace10e30cc7c9fdde28b75ef9b53d6f8c0a/480/',27.4731167,41.401196,'Ajaa Mountains Hail Province SA','','','','https://www.saudi-guide.com/hail/i/60148815/aja-mountains-gbal-aga',1,0,'جبال اجا aja mountains اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148811,'hail','متنزه مشار الوطني','Mishar National Park','mishar-national-park-mtnzh-mshar-alotny','["أماكن سياحية"]','["sights"]','متنزه مشار الوطني في حائل يوفر مساحات خضراء واسعة ومرافق ترفيهية تناسب العائلات، ويعد وجهة محببة للاستمتاع بالطبيعة بعيداً عن صخب المدينة.','<div class="texte" > <p>منتزه مشار الوطني بمدينة حائل يوفر مساحات خضراء واسعة ومرافق ترفيهية تناسب العائلات، ويُعد وجهة محببة لقضاء أوقات هادئة والاستمتاع بالطبيعة بعيداً عن صخب المدينة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148811-44986536.jpg?v=1643066478"]','https://cmsphoto.ww-cdn.com/resizeapi/13a655dbbdfcf7bce74219969e250f9d3298c1e2/480/',27.5749361,41.6327374,'طريق مشار Mishar Hail','','','','https://www.saudi-guide.com/hail/i/60148811/mishar-national-park-mtnzh-mshar-alotny',1,0,'متنزه مشار وطني mishar national park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148751,'hail','منتزه المغواة الترفيهي للاحتفالات','Al Mughwah Events Park','al-mughwah-events-park-mntzh-almghoa-altrfyhy-llahtfalat','["أماكن سياحية"]','["sights"]','منتزه المغواة الترفيهي في حائل موقع مخصص لإقامة الفعاليات والاحتفالات، ويضم مساحات واسعة تتيح تنظيم المناسبات العائلية والجماعية في أجواء مفتوحة.','<div class="texte" > <p>منتزه المغواة الترفيهي للاحتفالات بمدينة حائل موقع مخصص لإقامة الفعاليات والاحتفالات المختلفة، ويضم مساحات واسعة تتيح تنظيم المناسبات العائلية والجماعية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148751-44986539.jpg?v=1643066501"]','https://cmsphoto.ww-cdn.com/resizeapi/6ff49a91459839145119548fa25853c8e9e4d845/480/',27.5533568,41.6504411,'HM32+85W Hail Hail','','','','https://www.saudi-guide.com/hail/i/60148751/al-mughwah-events-park-mntzh-almghoa-altrfyhy-llahtfalat',1,0,'منتزه مغواه ترفيهي للاحتفالات al mughwah events park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148749,'hail','منتزه أجا بارك','Aja Park','aja-park-mntzh-aga-bark','["أماكن سياحية"]','["sights"]','منتزه أجا بارك في حائل وجهة عائلية تضم مدينة ألعاب مفتوحة وشاليهات ومخيمات وأماكن لركوب الخيل ومسرحاً للفعاليات ومنطقة تسوق ومطاعم ومقاهي.','<div class="texte" > <div> <div> <div data-habitat="C1"> <section> <section> <div> <p>يتمتع منتزه أجا بارك في حائل بمرافق عديدة تلائم كل فرد في عائلتك؛ حيث تجد الشاليهات، و تنتظرك في الداخل أكبر مدينة ألعاب على مساحة مفتوحة في حائل، وأماكن لركوب الخيل وتعلمه، إلى جانب منطقة تسوق ومطاعم ومقاهٍ تلبي ذائقتك وتؤنس رحلتك.</p> <p>&nbsp;</p> </div> </section> </section> </div> </div> </div> </div>    <div class="texte" > <p>عند دخولك منتزه أجا بارك تستقبلك منطقة تسوق يمكنك أن تباشر منها زيارتك، وفي مساحتها الداخلية ستجد مدينة ألعاب كبيرة، حيث يمكنك الاستمتاع بالعديد من الألعاب الكهربائية والهوائية، وتتراءى لك حين تطير عاليًا بألعابها جبال حائل الشامخة.</p> <p>كما يتضمن المنتزه مسرحًا تُقام فيه الفعاليات، إلى جانب أكواخ ومخيمات وشاليهات للإيجار بجلسات فريدة متنوعة وأحجام مختلفة؛ إذ تتوافر جلسات تحمل الطابع اليوناني الذي يتميز باللون الأزرق الطاغي الباعث على الهدوء، وشاليهات بتصميم ريفي، إلى جانب شاليهات بطابع شعبي، وجلسات أرضية تتسم بالبساطة وتعطي شعورًا بالأريحية.</p> </div>  <div class="texte" > <p>يرحب بك أجا بارك وبكل الزوار يوميًا من الساعة 1:30 ظهرًا حتى 2 فجرًا صيفًا، ومن 3 عصرًا حتى 1 فجرًا شتاءً.</p> </div>    <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148749-59708945.jpg?v=1728483660", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148749-59708963.jpg?v=1728483871", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148749-59709014.jpg?v=1728483878"]','https://cmsphoto.ww-cdn.com/resizeapi/32837471130464106ad3916612c8da1d9681de3e/480/',27.579805,41.6472701,'Mishar Hail Hail Principality','','','','https://www.saudi-guide.com/hail/i/60148749/aja-park-mntzh-aga-bark',1,0,'منتزه اجا بارك aja park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148746,'hail','بوليفارد حائل','Hail Boulevard','hail-boulevard-bolyfard-hayl','["أماكن سياحية"]','["sights"]','بوليفارد حائل وجهة ترفيهية حديثة تجمع المطاعم والمقاهي والمحلات التجارية في أجواء عصرية مضيئة، ويقصدها الأهالي والزوار لقضاء أمسياتهم في حائل.','<div class="texte" > <p>بوليفارد حائل وجهة ترفيهية حديثة تجمع بين المطاعم والمقاهي والمحلات التجارية في أجواء عصرية مضيئة، ويُعد من أبرز الأماكن التي يقصدها الأهالي والزوار لقضاء أمسياتهم بمدينة حائل.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148746-44986542.jpg?v=1643066536"]','https://cmsphoto.ww-cdn.com/resizeapi/2cfcc179ac7402c12dd1b4fe7f94e9f86f3ee151/480/',27.4632929,41.6561946,'An Nuqrah Hail Hail','','','','https://www.saudi-guide.com/hail/i/60148746/hail-boulevard-bolyfard-hayl',1,0,'بوليفارد حائل hail boulevard اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148743,'hail','جلسات منتزه السمراء العائلية','Al Samra Family Park','al-samra-family-park-glsat-mntzh-alsmra-alaaayly','["أماكن سياحية"]','["sights"]','منتزه السمراء على جبل السمراء المطل على مدينة حائل، وجهة لمشاهدة الغروب تضم مقاهي ومطاعم، ويرتبط الجبل بحاتم الطائي الذي كان يوقد عليه النار للمسافرين.','<div class="texte" > <p>منتزه السمراء وجهة غروب ساحرة تجمع بين المقاهي والمطاعم المتنوعة بإطلالة رائعة على مدينة حائل، ويقع على جبل السمراء الذي ارتبط اسمه بحاتم الطائي رمز الكرم، إذ يُروى أنه كان يوقد النار على الجبل لإرشاد المسافرين إلى بيته.</p> </div>  <div class="texte" > <p>رسوم دخول السيارة 20-25 ريالًا تقريبًا.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148743-44986543.jpg?v=1643066550"]','https://cmsphoto.ww-cdn.com/resizeapi/c5984b41e2103d63d2c7b9880a0040f99d55b591/480/',27.5221691,41.7204416,'6312 طريق الديعجان، مغيضة حائل 55428 4426 Ad Dayajan Rd Mughaydah','','','','https://www.saudi-guide.com/hail/i/60148743/al-samra-family-park-glsat-mntzh-alsmra-alaaayly',1,0,'جلسات منتزه سمراء عائليه al samra family park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148433,'qassim-region','بقايا قصر عنترة','Antarah Palace Ruins','bkaya-ksr-aantr','["التراث والثقافة"]','["heritage"]','بقايا قصر عنترة في منطقة القصيم، أطلال أثرية مرتبطة بسيرة الشاعر عنترة بن شداد، ضمن مواقع التراث الأدبي التي تشتهر بها منطقة القصيم.','<div class="texte" > <p>تقع بقايا قصر عنترة على قمة هضبة صخرية تُعرف بجال قصيباء قرب بلدة القوارة في منطقة القصيم، وتضم أطلالًا وأبراجًا حجرية يُعتقد أنها استُخدمت للحراسة ومراقبة عيون الماء وبساتين النخيل. ويرتبط الموقع بسيرة الشاعر الجاهلي عنترة بن شداد، وعُثر في محيطه على نقوش ثمودية ورسوم صخرية تصوّر الوعول والجمال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148433-44773589.jpg?v=1641422657"]','https://cmsphoto.ww-cdn.com/resizeapi/9c0ea57e8d6d55f830c0204267a4bff5794587d7/480/',26.8734721,43.563605,'VHF7+9CQ Al-KSejbe Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148433/bkaya-ksr-aantr',1,0,'بقايا قصر عنتره antarah palace ruins تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148369,'qassim-region','قصر المشقوق','Mashqouq Palace','mashqouq-palace-ksr-almshkok','["التراث والثقافة"]','["heritage"]','قصر المشقوق في منطقة القصيم، أحد المباني التراثية الطينية في المنطقة، يعكس طراز العمارة النجدية القديمة ويقصده المهتمون بالتاريخ والتراث المحلي.','<div class="texte" > <p>يقع قصر المشقوق، المعروف أيضًا بقصر الراضي، في مركز قصيباء شمال مدينة بريدة، وبدأ إنشاؤه عام 1250هـ. بُني القصر من الطين والحجارة وسُقف بخشب الأثل وجريد النخل، ويبلغ ارتفاع جدرانه نحو 15 مترًا ويحيط به سور، ويضم مجالس ومسجدًا وغرفًا. وسُمّي بالمشقوق لأنه أقيم على مجرى عين ماء شُقّت تحت الأرض لإيصال المياه إلى بئر القصر.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148369-44773591.jpg?v=1641422674"]','https://cmsphoto.ww-cdn.com/resizeapi/703754badde75f76ef6e1cf052b5e84676c2f861/480/',26.8998182,43.5877445,'6280 Buraydah Al Qassim','','','','https://www.saudi-guide.com/qassim-region/i/60148369/mashqouq-palace-ksr-almshkok',1,0,'قصر مشقوق mashqouq palace تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148366,'qassim-region','بلدة الخبراء القديمة','Al Khabra Old Town','bld-alkhbraaa-alkdym','["التراث والثقافة"]','["heritage"]','بلدة الخبراء القديمة في القصيم، بلدة طينية عمرها أكثر من 200 عام تضم أكثر من 400 منزل بُنيت بشكل دائري حول السوق والمسجد على مساحة 120 ألف متر مربع.','<div class="texte" > <p>بلدة الخبراء القديمة بنيت البلدة قبل أكثر من 200 عام من الطين الحر، ما جعلها قوية في وجه الزمن وعوامل التعرية، وتضم أكثر من 400 منزل، بُنيت بالشكل الدائري وهي تشبه بناء بغداد في العصر العباسي، حيث بقيت متماسكة، وتحيط القرية بسوق المجلس والمسجد بشكل دائري، وبهذا تكون أماكن البيع والشراء في منتصف البلدة. تقع البلدة القديمة وسط منطقة القصيم في المملكة العربية السعودية، على مساحة 120 ألف متر مربع، بُنيت في حقبة زمنية تاريخية ترجع إلى العام 1115 هـ، ووصفت بأنها حصن حصين صمدت أمام الغزوات والحملات العسكرية، وترجع تسميتها بالخبراء لأنها كانت مكاناً تتجمع في مياه الأمطار والمياه الفائضة من وادي الرمة قديماً، الذي يعدّ أكبر وادي في الجزيرة العربية وكذلك سميت بخبراء العفالق نسبة لال العفالق أول من سكانها في الألف الأول الهجري.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148366-68551574.jpg?v=1791634058"]','https://cmsphoto.ww-cdn.com/resizeapi/209faae8142d595b50207bdc93fd2381a4a3103f/480/',26.0635971,43.6513254,'بلدة الخبراء القديمة بريدة القصيم','','','','https://www.saudi-guide.com/qassim-region/i/60148366/bld-alkhbraaa-alkdym',1,0,'بلده خبراء قديمه al khabra old town تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148364,'qassim-region','متحف العبري','Al Abri Museum','mthf-alaabry','["التراث والثقافة"]','["heritage"]','متحف العبري للتراث والسيارات القديمة في رياض الخبراء بالقصيم، يضم أسلحة وعملات ووثائق وأدوات ضيافة وأدوات زراعية وسيارات قديمة تحكي تاريخ المنطقة.','<div class="texte" > <p>متحف العبري للتراث والسيارات القديمة، أحد متاحف منطقة القصيم يقع في محافظة رياض الخبراء، أسسه عبد الرحمن بن ناصر العبري، يتكون المتحف من قاعة رئيسية ووحدتين وسواني متكاملة وساحة كبيرة، ويشمل العرض مجموعة من المقتنيات التراثية كالأسلحة والعملات والوثائق وأدوات الضيافة والقهوة العربية وأدوات الإضاءة القديمة والأدوات الزراعية والأجهزة السمعية القديمة والمصنوعات الخشبية والجلدية والخوصيات وبعض الحيوانات المحنطة، كما يوجد المطبخ القديم وغرفة النوم ومحتوياتها قديما، اما الفناء فيحتوي على السواني وحسو وجصة ومجموعة من السيارات القديمة ومضخات الوقود قديما.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148364-44773587.jpg?v=1641422639"]','https://cmsphoto.ww-cdn.com/resizeapi/d68c1458f09133c25b63dd6e170e6e80fcbd146c/480/',26.0362885,43.5097992,'2GP5+GW7 Riyadh Al Khabra Riyadh Al Khabra','','','','https://www.saudi-guide.com/qassim-region/i/60148364/mthf-alaabry',1,0,'متحف عبري al abri museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148363,'qassim-region','قرية الخبراء التراثية','Al Khabra Heritage Village','kry-alkhbraaa-altrathy','["التراث والثقافة"]','["heritage"]','قرية الخبراء التراثية في منطقة القصيم، قرية قديمة ببيوت طينية وأزقة ضيقة تعكس نمط الحياة النجدية التقليدية، ووجهة لمحبي التراث والتصوير.','<div class="texte" > <p>قرية الخبراء التراثية من أبرز البلدات الطينية في منطقة القصيم، ويعود تاريخها إلى عام 1115هـ، وتضم مئات المنازل الطينية المبنية من طابق أو طابقين حول ساحة مركزية يتوسطها سوق المجلس والمسجد، وكانت في الماضي بلدة زراعية مهمة في المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148363-44773595.jpg?v=1641422690"]','https://cmsphoto.ww-cdn.com/resizeapi/37bc66c029e75b064fc803f6cf1a4cefb63bcae3/480/',26.0635971,43.6513254,'3M72+CGP Al Silah قرية الخبراء التراثية','','','','https://www.saudi-guide.com/qassim-region/i/60148363/kry-alkhbraaa-altrathy',1,0,'قريه خبراء تراثيه al khabra heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148335,'qassim-region','صخرة عنترة بن شداد (حصاة النصلة) في غاف الجواء','Antarah Ibn Shaddad Rock','antarah-ibn-shaddad-rock-skhr-aantr-bn-shdad-hsa-alnsl-fy-ghaf-algoaaa','["التراث والثقافة"]','["heritage"]','صخرة عنترة أو حصاة النصلة في عيون الجواء بالقصيم، صخرة حمراء ترتبط بقصة عنترة بن شداد وعبلة، وأبرز محطات مسار التراث الأدبي في المنطقة.','<div class="texte" > <p>حصاة النصلة أو حصاة عنترة هي صخرة حمراء اللون تقع في منطقة القصيم وسط المملكة العربية السعودية. تُعد حصاة النصلة إحدى الشواهد التي تُشير إلى تاريخ عنترة بن شداد وابنة عمه عبلة، والتي دارت فصولها بين صخرتين عرفا بعد ذلك بصخرة عنتر. وتعتبر الصخرة من أبرز المواقع على المسار السياحي المعتمد في منطقة القصيم وهو مسار متخصص ضمن مسارات التراث الأدبي التي تحتضنها المنطقة، وعملت الهيئة العامة للسياحة بالتعاون مع الشركاء على عدد من البرامج والأنشطة التعريفية في الموقع من قصيباء شمال شرق حتى موقع الصخرة في الجواء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148335-44773586.jpg?v=1641422623"]','https://cmsphoto.ww-cdn.com/resizeapi/6b26937886c7a8363bb00cb80f33189dea7596a3/480/',26.5509357,43.5952883,'HH2W+94F gaf Al Jawa Uyun AlJiwa','','','','https://www.saudi-guide.com/qassim-region/i/60148335/antarah-ibn-shaddad-rock-skhr-aantr-bn-shdad-hsa-alnsl-fy-ghaf-algoaaa',1,0,'صخره عنتره بن شداد (حصاه نصله) في غاف جواء antarah ibn shaddad rock تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148327,'qassim-region','القرية التراثية في عيون الجواء','Heritage Village','heritage-village-alkry-altrathy-fy-aayon-algoaaa','["التراث والثقافة"]','["heritage"]','القرية التراثية في عيون الجواء بمنطقة القصيم، تضم مباني طينية تقليدية تعكس طابع الحياة القديمة في الجواء، وتجمع بين التاريخ والطبيعة الريفية.','<div class="texte" > <p>تقع القرية التراثية في محافظة عيون الجواء بمنطقة القصيم، وتحتفي بالموروث المحلي وتقدّم لزوارها تجربة تعرّفهم على نمط الحياة القديمة في المنطقة، في محافظة ترتبط بسيرة الشاعر عنترة بن شداد وتضم عددًا من المواقع التاريخية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148327-44773596.jpg?v=1641422712"]','https://cmsphoto.ww-cdn.com/resizeapi/432dcdd51f0fe85e68fa8aeea4e06b330f60a5b4/480/',26.5051839,43.6265578,'GJ4G+3JF Uyun Al Jawa Uyun AlJiwa','','','','https://www.saudi-guide.com/qassim-region/i/60148327/heritage-village-alkry-altrathy-fy-aayon-algoaaa',1,0,'قريه تراثيه في عيون جواء heritage village تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148320,'qassim-region','متحف ومحمية عبدالرحمن الراجحي','Abdulrahman Al Rajhi Museum and Reserve','mthf-omhmy-aabdalrhmn-alraghy','["التراث والثقافة"]','["heritage"]','متحف ومحمية عبدالرحمن الراجحي في البكيرية بالقصيم، وجهة تجمع بين المقتنيات التراثية ومساحات المحمية الطبيعية، وتناسب محبي التراث والعائلات.','<div class="texte" > <p>يقع متحف ومحمية عبدالرحمن الراجحي في محافظة البكيرية بمنطقة القصيم، ويجمع بين متحف يعرض مقتنيات تراثية ومساحة محمية، ليكون وجهة لمحبي التراث والطبيعة من العائلات والزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148320-44773597.jpg?v=1641422726"]','https://cmsphoto.ww-cdn.com/resizeapi/b7e9ec08380dbf01fc1ea372788ad04d2aac5931/480/',26.1794873,43.6635615,'Al Bukayriyah Al Pakyria Al Qassim','','','','https://www.saudi-guide.com/qassim-region/i/60148320/mthf-omhmy-aabdalrhmn-alraghy',1,0,'متحف ومحميه عبدالرحمن راجحي abdulrahman al rajhi museum and reserve تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148318,'qassim-region','مقصورة السويلم','Maqsorat Alswailem','maqsorat-alswailem-mksor-alsoylm','["التراث والثقافة"]','["heritage"]','مقصورة السويلم في البكيرية، قصر أثري بُني مطلع القرن الثالث عشر الهجري وكان مقرًا للإمارة، واستقبل الإمام فيصل بن تركي والملك عبدالعزيز عام 1325هـ.','<div class="texte" > <p>مقصورة السويلم هي&nbsp;عبارة عن قصر أثري كبير يتضمن ملاحق بنيت مطلع القرن الثالث عشر الهجري، في عهد أمير البكيرية عبد الله بن سويلم بن عثمان آل سويلم عقب إنشاء محافظة البكيرية، وكانت مقصورة السويلم مقراً للإمارة فترة من الزمن، حيث استُقبل فيها عدد من الملوك والشخصيات البارزة مثل الإمام فيصل بن تركي والملك عبد العزيز حين قدم إلى البكيرية عام 1325 هـ، وتعد المقصورة أحد أهم المعالم التراثية بمحافظة البكيرية التابعة لمنطقة القصيم وسط المملكة العربية السعودية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148318-44773585.jpg?v=1641422606"]','https://cmsphoto.ww-cdn.com/resizeapi/ae41cc9bd18dee599f826d1d3e5ec1a3fb85776a/480/',26.1522517,43.6655137,'5M28+W62 Al Bukayriyah Al Pakyria','','','','https://www.saudi-guide.com/qassim-region/i/60148318/maqsorat-alswailem-mksor-alsoylm',1,0,'مقصوره سويلم maqsorat alswailem تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148316,'qassim-region','متحف عبدالله بن علي الدخيل التراثي','Abdullah bin Ali Al Dakhil Heritage Museum','mthf-aabdallh-bn-aaly-aldkhyl-altrathy','["التراث والثقافة"]','["heritage"]','متحف عبدالله بن علي الدخيل التراثي في البلد القديم بالبكيرية، متحف خاص يعرض مقتنيات تراثية تحكي تاريخ الحياة اليومية القديمة في منطقة القصيم.','<div class="texte" > <p>يقع متحف عبدالله بن علي الدخيل التراثي في البلد القديم بمحافظة البكيرية، وهو متحف خاص يعرض مقتنيات تراثية تعكس جوانب من الحياة اليومية القديمة في منطقة القصيم.</p> </div>  <div class="texte" > <p>مصدر الصور: صفحة المكان على خرائط Google</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148316-68541314.jpg?v=1791534326"]','https://cmsphoto.ww-cdn.com/resizeapi/a5f8a378e0996a087c5f4f0229f387b186b6eadc/480/',26.1482909,43.6660248,'4MX8+8C6 Al Balad Al Qadim Al Bukayriyah','','','','https://www.saudi-guide.com/qassim-region/i/60148316/mthf-aabdallh-bn-aaly-aldkhyl-altrathy',1,0,'متحف عبدالله بن علي دخيل تراثي abdullah bin ali al dakhil heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148315,'qassim-region','مقصورة الراجحي','Maqsorat Alrajhi','maqsorat-alrajhi-mksor-alraghy','["التراث والثقافة"]','["heritage"]','مقصورة الراجحي في قلب البكيرية، معلم تراثي بُني نحو عام 1190هـ بعد انتقال ناصر الراجحي من الهلالية، ويجري تطويره ليبقى شاهدًا على تاريخ المحافظة.','<div class="texte" > <p>بعد استقرار ناصر الراجحي في البكيرية بعد محطات عديدة كانت المقصورة هي الآثر المادي الباقي الذي يسجد مسيرته، فكان واجب الحفاظ عليه والعناية به ليبقى معلماً بارزاً في قلب البيكيرية، وقد مرت المقصورة بمراحل عديدة تعاقبت عليها وتفاوت تأثيرها منذ نشاتها وحتى اليوم، حيث يجري تطويرها وتنشيطها لتأخذ شكلها وحجمها الملائمين في التركيبة التراثية والتاريخية.</p> <p>&nbsp;بنيت المقصورة عام 1190هـ تقريباً بعد انتقال ناصر الراجحي من الهلالية، ثم تلتها فترات متباينة بني فيها باقي مرافق المنزل الرئيسية وهي المسجد والبئر والقهوة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148315-44807408.jpg?v=1641726224"]','https://cmsphoto.ww-cdn.com/resizeapi/96d1f71b5ecd211871f73e5b3392333db36b4a02/480/',26.1489266,43.6703606,'4MXC+H4H Al Bukayriyah Al Pakyria','','','','https://www.saudi-guide.com/qassim-region/i/60148315/maqsorat-alrajhi-mksor-alraghy',1,0,'مقصوره راجحي maqsorat alrajhi تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148314,'qassim-region','مسجد الشيخ محمد بن عبدالوهاب','Sheikh Mohammed bin Abdul Wahab Mosque','sheikh-mohammed-bin-abdul-wahab-mosque-msgd-alshykh-mhmd-bn-aabdalohab','["التراث والثقافة"]','["heritage"]','مسجد الشيخ محمد بن عبدالوهاب في محافظة البكيرية بمنطقة القصيم، من المساجد المعروفة في المحافظة ومعلم ديني يقصده المصلون والزوار.','<div class="texte" > <p>يقع مسجد الشيخ محمد بن عبدالوهاب في محافظة البكيرية بمنطقة القصيم، وهو من مساجد المحافظة المعروفة التي يقصدها المصلون والزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148314-44817058.jpg?v=1641811025"]','https://cmsphoto.ww-cdn.com/resizeapi/6eea76ed2b48ea8457e6e858d8cf14e616462d8d/480/',26.1180463,43.6778238,'SA Al Bukayriyah Al Pakyria','','','','https://www.saudi-guide.com/qassim-region/i/60148314/sheikh-mohammed-bin-abdul-wahab-mosque-msgd-alshykh-mhmd-bn-aabdalohab',1,0,'مسجد شيخ محمد بن عبدالوهاب sheikh mohammed bin abdul wahab mosque تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148311,'qassim-region','دار الحسياني للتراث','Al Hussayani Heritage House','al-hussayani-heritage-house-dar-alhsyany-lltrath','["التراث والثقافة"]','["heritage"]','دار الحسياني للتراث في المذنب، متحف مبني على الطراز القديم يضم أسلحة وأدوات قهوة وضيافة وأدوات زراعية وصالة لعرض السيارات القديمة.','<div class="texte" > <p>متحف الحسيّاني، أحد متاحف منطقة القصيم يقع في محافظة المذنب، أسسه محمد بن عثمان بن سعود الحسيّاني الناصري التميمي، المتحف مبنى مستقل مبني على الطراز القديم التراثي وهو عبارة عن ساحة كبيرة يوجد بها مجموعة من الغرف بالإضافة إلى صالة لعرض السيارات القديمة تنوعت بها طرق العرض تضم مجموعة من مواد العرض المتحفي وتقسم إلى عدة مجموعات كالتالي مجموعة لأسلحة كالبنادق والسيوف، مجموعة أدوات القهوة والضيافة العربية كالأواني والدلال، مجموعة الأدوات الزراعية والمحاريث، مجموعة للعملات المعدنية والورقية، مجموعة للصور والوثائق القديمة، مجموعة من الأجهزة الكهربائية القديمة مثل الرادو وآلات الباكم، مجموعة متنوعة من السيارات القديمة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148311-44807427.jpg?v=1641726319"]','https://cmsphoto.ww-cdn.com/resizeapi/e329fa338729683f4268b194c24bdeafbcec1cef/480/',25.8688855,44.210317,'V696+H44 Al Khaldiyah Al Mithnab','','','','https://www.saudi-guide.com/qassim-region/i/60148311/al-hussayani-heritage-house-dar-alhsyany-lltrath',1,0,'دار حسياني للتراث al hussayani heritage house تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148306,'qassim-region','بلدة المذنب التراثية','Al Mithnab Traditional Town','al-mithnab-traditional-town-bld-almthnb-altrathy','["التراث والثقافة"]','["heritage"]','بلدة المذنب التراثية في القصيم، قرية قديمة يعود تاريخها إلى نحو 700 عام، أعيد تأهيلها لتصبح وجهة سياحية تحكي العمق التاريخي للمحافظة.','<div class="texte" > <p>قرية المذنب هي قرية تراثية قديمة، يعود تاريخ إنشائها إلى 700 سنة، أعيد تأهيلها حديثاً وأصبحت إحدى المناطق السياحية، تقع القرية التراثية في محافظة المذنب وسط المملكة العربية السعودية.</p> <p>يعود تاريخ عمارة المذنب واستيطانها كما ورد في الكتب التاريخية إلى منتصف القرن السادس الهجري وما تزال هنالك آثار قديمة تؤكد العمق التاريخي لهذه المدينة حيث يوجد على ضفاف الاودية القريبة من المذنب آثار حجارة صينية تعود إلى قرون ماضية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148306-44807424.jpg?v=1641726304"]','https://cmsphoto.ww-cdn.com/resizeapi/762d672c725149f3efa646b72a1a6d9731b9f31d/480/',25.8683691,44.2274627,'V69G+8XW Al Deerah Al Mithnab','','','','https://www.saudi-guide.com/qassim-region/i/60148306/al-mithnab-traditional-town-bld-almthnb-altrathy',1,0,'بلده مذنب تراثيه al mithnab traditional town تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148302,'qassim-region','متحف الطيور بالمذنب','Al Mithnab Birds Museum','mthf-altyor-balmthnb','["التراث والثقافة"]','["heritage"]','متحف الطيور في محافظة المذنب بمنطقة القصيم، وجهة تعليمية وترفيهية للتعرف على أنواع الطيور، وتناسب العائلات والأطفال ومحبي الطبيعة.','<div class="texte" > <p>يقع متحف الطيور في محافظة المذنب بمنطقة القصيم، ويتيح للزوار التعرف على أنواع مختلفة من الطيور، ما يجعله محطة تعليمية وترفيهية مناسبة للعائلات والأطفال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148302-44817068.jpg?v=1641811048"]','https://cmsphoto.ww-cdn.com/resizeapi/5c2579dace45ca09df1be6ca39e1aa8afa42b61c/480/',25.8624738,44.2289618,'Al Mithnab Al Judaydah Al Mithnab','','','','https://www.saudi-guide.com/qassim-region/i/60148302/mthf-altyor-balmthnb',1,0,'متحف طيور بالمذنب al mithnab birds museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148299,'qassim-region','محمية ومتحف الفوزان','Fawzan Museum','fawzan-museum-mhmy-omthf-alfozan','["التراث والثقافة"]','["heritage"]','محمية ومتحف الفوزان في محافظة المذنب بالقصيم، وجهة تجمع بين المقتنيات التراثية ومساحات المحمية، ومناسبة للعائلات ومحبي التراث والطبيعة.','<div class="texte" > <p>تقع محمية ومتحف الفوزان في محافظة المذنب بمنطقة القصيم، وتجمع بين متحف لعرض المقتنيات التراثية ومساحة محمية، لتقدّم للزوار تجربة تجمع بين التراث والطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148299-44817074.jpg?v=1641811073"]','https://cmsphoto.ww-cdn.com/resizeapi/56a91234f71f0a2ca77d120ff3955e3240ab3b16/480/',25.8550834,44.2397522,'V64Q+2WJ العدان، المذنب','','','','https://www.saudi-guide.com/qassim-region/i/60148299/fawzan-museum-mhmy-omthf-alfozan',1,0,'محميه ومتحف فوزان fawzan museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148293,'qassim-region','برج الشنانة','Al Shinanah Historical Tower','al-shinanah-historical-tower-brg-alshnan','["التراث والثقافة"]','["heritage"]','برج الشنانة في الرس، صرح أثري يحكي بطولة أهل الرس في الدفاع عن بلدتهم، وشاهد على معارك عديدة منذ الدولة السعودية الأولى حتى عهد الملك عبدالعزيز.','<div class="texte" > <p>برج الشنانة هو الصرح الأثري الذي يحكي قصة البطولة التي أبداها أهل الرس وقوة بأسهم في التصدي للعدوان وكان شاهدا على شجاعتهم وتضحيتهم بنفوسهم في الدفاع عن بلدتهم يحدوهم الأمل في العيش الرغيد والحياة الهانئة، فلقد كان شاهداً على كثير من المعارك التي حدثت حوله في جميع مراحل الدولة السعودية من الأولى إلى عهد الملك عبد العزيز.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148293-44807420.jpg?v=1641726283"]','https://cmsphoto.ww-cdn.com/resizeapi/fc7216f5e5df36a871756cd292ca11f747cd9262/480/',25.8340878,43.4398704,'RCMQ+JWQ Al Sina''iyah Ar Rass','','','','https://www.saudi-guide.com/qassim-region/i/60148293/al-shinanah-historical-tower-brg-alshnan',1,0,'برج شنانه al shinanah historical tower تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148290,'qassim-region','متحف راشد بن صالح الغفيلي','Rashid bin Saleh Al Ghufaili Museum','mthf-rashd-bn-salh-alghfyly','["التراث والثقافة"]','["heritage"]','متحف راشد بن صالح الغفيلي في محافظة الرس بالقصيم، متحف خاص يعرض مقتنيات تراثية تعكس تاريخ الحياة القديمة في المنطقة وموروثها الشعبي.','<div class="texte" > <p>متحف راشد بن صالح الغفيلي من المتاحف الخاصة في محافظة الرس بمنطقة القصيم، ويعرض مجموعة من المقتنيات التراثية التي تعكس الموروث الشعبي وأنماط الحياة القديمة في المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148290-44817076.jpg?v=1641811092"]','https://cmsphoto.ww-cdn.com/resizeapi/f6c76f3d1f9e53d3408cb9c54a39b2bc4bad4f9f/480/',25.8800924,43.5008084,'VGJ2+28M Airport Ar Rass','','','','https://www.saudi-guide.com/qassim-region/i/60148290/mthf-rashd-bn-salh-alghfyly',1,0,'متحف راشد بن صالح غفيلي rashid bin saleh al ghufaili museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148285,'qassim-region','متحف دار الأجداد','Dar Al Ajdad Museum','mthf-dar-alagdad','["التراث والثقافة"]','["heritage"]','متحف دار الأجداد في الرس، يقع داخل منزل شعبي كبير ويعرض أدوات القهوة كالدلال والمحاميس والنجر، وأدوات الطبخ والأواني التراثية القديمة.','<div class="texte" > <p>متحف دار الأجداد، أحد متاحف منطقة القصيم يقع في محافظة الرس، أسسه ضيف الله عبد الله محمد الغفيلي، يقع المتحف داخل منزل شعبي كبير يحتوي على قاعات كبيرة وردهات وغرف وقد تم عرض محتويات المتحف التراثية داخل تلك الأماكن، وتتكون محتويات المتحف التراثية من أدوات القهوة كالدلال المتنوعة من حيث الصناعة وكذلك من حيث الحجم، والأباريق ومحاميس القهوة والنجر الهاون وطواحين القهوة وغيرها وكذلك أدوات وأواني الطبخ كالقدور والصياني والتباسي والصحاف وغيرها من الأدوات الزراعية من المحاحيل والمحراث والرشا وكذلك الرحى لطحن وجرش الحبوب، كما يضم بعض أدوات الحرب كالبنادق والسيوف والرماح وغيرها، ويضم المتحف مجموعة من الملابس والحلي وأدوات الزينة الخاصة بالنساء، ويضم المتحف أيضا عدد من السيارات القديمة تم عرضها خارج المتحف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148285-44807417.jpg?v=1641726265"]','https://cmsphoto.ww-cdn.com/resizeapi/e45a52735379ab63edfa62a567d3824c1bc9274c/480/',25.8639418,43.5064096,'VG74+HHF King Fahd Ar Rass','','','','https://www.saudi-guide.com/qassim-region/i/60148285/mthf-dar-alagdad',1,0,'متحف دار اجداد dar al ajdad museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148263,'qassim-region','قلعة جدعية التراثية','Jadaia Heritage Castle','klaa-gdaay-altrathy','["التراث والثقافة"]','["heritage"]','قلعة جدعية التراثية في الرس، متحف على شكل قلعة يضم مباني وغرفًا قديمة وبيت الجدة ومسجدًا، وأكثر من سبعة آلاف قطعة تراثية قيمة ونادرة.','<div class="texte" > <p>متحف جدعية، أحد متاحف منطقة القصيم يقع في محافظة الرس، أسسه خالد بن محمد الجدعي، وهو&nbsp;عبارة عن قلعة تحتوي على مجموعة من المباني والغرف القديمة وبيت الجدة الشهير ومسجد، وعلى أكثر من سبعة آلاف قطعة تراثية قيمة ونادرة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148263-44807412.jpg?v=1641726245"]','https://cmsphoto.ww-cdn.com/resizeapi/209f1aa3900f6b35321a38ec5a3f063a8ab99413/480/',25.7915308,43.508846,'طريق الملك فهد Ar Rass Ar Rass','','','','https://www.saudi-guide.com/qassim-region/i/60148263/klaa-gdaay-altrathy',1,0,'قلعه جدعيه تراثيه jadaia heritage castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148260,'qassim-region','قلعة الربيعي التراثية','Al Rubaie Heritage Castle','klaa-alrbyaay-altrathy','["التراث والثقافة"]','["heritage"]','قلعة الربيعي التراثية في محافظة عنيزة بمنطقة القصيم، مبنى تراثي بطابع القلاع القديمة يعكس العمارة النجدية، ووجهة لمحبي التاريخ والتراث.','<div class="texte" > <p>تقع قلعة الربيعي التراثية في محافظة عنيزة بمنطقة القصيم، وهي مبنى تراثي بطابع القلاع القديمة يعكس ملامح العمارة النجدية، ويقصدها محبو التاريخ والتراث والتصوير.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148260-44817083.jpg?v=1641811112"]','https://cmsphoto.ww-cdn.com/resizeapi/8bf95e562b6cf8865a06e7f740b61633911a1e40/480/',26.1009573,43.837452,'8360 Al Shuaib Unayzah','','','','https://www.saudi-guide.com/qassim-region/i/60148260/klaa-alrbyaay-altrathy',1,0,'قلعه ربيعي تراثيه al rubaie heritage castle تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148257,'qassim-region','متحف الحمدان التراثي','Al Hamdan Heritage Museum','mthf-alhmdan-altrathy','["التراث والثقافة"]','["heritage"]','متحف الحمدان التراثي في عنيزة، مزرعة كبيرة بمبانٍ طينية مسقوفة بخشب الأثل، تعرض ملابس رجالية ونسائية وأدوات وقطعًا تراثية بأسلوب عرض منسق.','<div class="texte" > <p>متحف الحمدان أحد متاحف منطقة القصيم يقع في محافظة عنيزة، أسسه إبراهيم بن صالح بن حمد الحمدان، المتخف عبارة عن مزرعة كبيرة بها عدد كبير من المباني التراثية والمبنية من الطين واللبن ومسقوفة بخشب الأثل، وقد تم عرض مقتنيات ذلك المتحف داخل غرف تلك المباني وفي الممرات التي بينها وذلك بأسلوب عرض منسق وقد تم العرض من خلال التعليق على الحائط أو من خلال فاترينات ألمنيوم وستاندات خشبية أو من خلال عرضها على أرفف.</p> <p>ومن محتويات المتحف الملابس الرجالية والنسائية وكذلك أواني الطهي والطعام والشراب وكذلك أواني القهوة وأدوات الإضاءة والمباخر ومجموعة من أدوات الحرب والأسلحة من بنادق وسيوف وخناجر ورماح وأدوات الزراعة والري وبعض الأدوات المدرسية والكتب والمخطوطات إضافة إلى بعض العملات وقد أستخدم العرض في بعض الأحيان في تمثيل بعض المهن والعادات الأسرية القديمة كما أن المزرعة إضافة إلى المتحف تضم حديقة حيوانات تشمل الكثير من أنواع الحيوانات الداجنة والبرية الأنيسة منها والمفترسة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148257-44816926.jpg?v=1641810483"]','https://cmsphoto.ww-cdn.com/resizeapi/cf01dd1ff60c52c46e8932798934c5643064e4a9/480/',26.1424581,43.9684992,'حي الروغاني عنيزة عنيزة','','','','https://www.saudi-guide.com/qassim-region/i/60148257/mthf-alhmdan-altrathy',1,0,'متحف حمدان تراثي al hamdan heritage museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148254,'qassim-region','متحف الصالحي','Al Salhi Museum','mthf-alsalhy','["التراث والثقافة"]','["heritage"]','متحف الصالحي في عنيزة، منزل طيني من ثلاثة أدوار حوّله فهد الصالحي إلى متحف يضم المجلس الشعبي والقبة والمقلط وغرفًا بأثاث البيت النجدي القديم.','<div class="texte" > <p>متحف الصالحي أحد متاحف منطقة القصيم يقع في محافظة عنيزة، أسسه فهد العلي الصالحي، وهو عبارة عن منزل طيني متهالك يعود تاريخه إلى أكثر من ستين عامًا، حيث اشتراه الصالحي في مزاد علني ثم خوله إلى متحف خلال خمسة أشهر وتم تجهيزه للزوار والمهتمين، ويتكون المتحف من ثلاثة ادوار مقامة على مساحة 300م يحتوي الدور الأول على المجلس الشعبي والقبة والمقلط والحوش، فيما يضم الدور الثاني خمس غرف ورواشن تحتوي جميعها على اثاث المنزل النجدي القديم، يضم المتحف العديد من المقتنيات والأدوات التراثية التي تشمل معظم أدوات المنزل القديم إضافة إلى بعض الأدوات التي تستخدم في الزراعة والأسواق وخلافها، كما يضم المتحف سيارات قديمة وعملات معدنية وكتب تراثية.</p> </div>','[]','',26.0833976,43.9627492,'Unayzah Al Mazadah Unaizah','','','','https://www.saudi-guide.com/qassim-region/i/60148254/mthf-alsalhy',1,0,'متحف صالحي al salhi museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148253,'qassim-region','بيت البسام التراثي','Albassam Heritage House','albassam-heritage-house-byt-albsam-altrathy','["التراث والثقافة"]','["heritage"]','بيت البسام في عنيزة بالقصيم، منزل تراثي طيني بسقوف عالية يضم مجلسين صيفي وربيعي ومقهى قديمًا وقسمًا للعائلة، ومن أبرز معالم المحافظة التراثية.','<div class="texte" > <p>بيت البسام، هو أحد المنازل التراثية في عنيزة، وهو عبارة عن قصر طيني يمثل طراز العمارة القديمة فيها، بأسقف من شجر الأثل وجريد النخل، ويقع بجوار سوق المسوكف الشعبي. يعد البيت أحد المعالم البارزة بمنطقة القصيم، ويقع في الجهة الغربية من محافظة عنيزة،&nbsp;يتميّز البيت بالارتفاع العالي للسقوف. كما أنه يضم أقساماً عدّة، فهناك قسم للرجال يحتوي على مجلسين أحدهما صيفي والآخر ربيعي بالإضافة إلى مقهى قديم، وكذلك هناك قسم خاص للسكن العائلي وأقسام أخرى للضيوف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148253-44816919.jpg?v=1641810467"]','https://cmsphoto.ww-cdn.com/resizeapi/456ab67d215c2c55294f376261bf296869d0e7d3/480/',26.089394,43.967419,'3XQ8+QX3 Ad Dulayah Unayzah','','','','https://www.saudi-guide.com/qassim-region/i/60148253/albassam-heritage-house-byt-albsam-altrathy',1,0,'بيت بسام تراثي albassam heritage house تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148252,'qassim-region','متحف النعيم في عنيزة','Al Naim Museum in Unaizah','mthf-alnaaym-fy-aanyzh','["التراث والثقافة"]','["heritage"]','متحف النعيم في عنيزة، بيت شعبي يضم قطعًا تراثية كثيرة من أدوات القهوة والطبخ والأسلحة والملابس والحلي والفخاريات تحكي تفاصيل الحياة قديمًا.','<div class="texte" > <p>متحف محمد النعيم، أحد متاحف منطقة القصيم يقع في محافظة عنيزة، أسسه محمد إبراهيم سليمان النعيم، المتحف عبارة عن بيت شعبي مسقوف بالخرسانة يتكون من 4 غرف وصالة عرض ويشمل جميع أنشطة الحياة واحتياجات الإنسان في ذلك الزمان، ويحتوي المتحف على مجموعة كبيرة من القطع التراثية تضم أدوات القهوة والضيافة وكذلك أدوات الطبخ والمأكل والمشرب والأسلحة وأدوات الحرب والملابس الرجالية والنسائية وأدوات الزينة والحلي، وأدوات الزراعة وأدوات الإنارة والفخاريات والجلديات ويوجد في منتصف المتحف صالتان مصباحان بالمسمى التراثي عرض بهما أيضا مجموعة من القطع التراثية الثقيلة وزنا والكبيرة حجما كأبواب المنازل والأدوات الحجرية كأدوات الطحن والهرس وبعض الأدوات الزراعية كالدراج والمحالة والمحراث.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148252-44816908.jpg?v=1641810449"]','https://cmsphoto.ww-cdn.com/resizeapi/3c34f8b32314267ad2da42c76463382851b056de/480/',26.079975,43.9950611,'Ash Shifa District عنيزة عنيزة','','','','https://www.saudi-guide.com/qassim-region/i/60148252/mthf-alnaaym-fy-aanyzh',1,0,'متحف نعيم في عنيزه al naim museum in unaizah تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148249,'qassim-region','متحف بريدة','Buraidah Museum','buraidah-museum-mthf-bryd','["التراث والثقافة"]','["heritage"]','متحف بريدة في القصيم، يعرض تراث المنطقة في قاعات تاريخية وثقافية، ويضم جناحًا لرجال العقيلات وجناحًا للملك عبدالعزيز فيه سيارته الخاصة ومكتبة.','<div class="texte" > <p>متحف بريدة، هو متحف في مدينة بريدة بمنطقة القصيم في السعودية، يعرض جانب من تراث المنطقة ويحوي العديد من المقتنيات ويضم قاعات تاريخية وعلمية وثقافية وجناح لرجال العقيلات، وكما أن هناك جناح خاص بالملك عبد العزيز بن عبد الرحمن آل سعود يضم سيارته الخاصة، وقاعة للتراث الشعبي، وقاعة لأرامكو السعودية، ويمكن للزائر أن يطلع على عدد من المؤلفات المنشورة عن مدينة بريدة ومنطقة القصيم من خلال مكتبة المتحف.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148249-44816901.jpg?v=1641810430"]','https://cmsphoto.ww-cdn.com/resizeapi/e815cd373b4c7234f395d07bfc2b2793bc79e61f/480/',26.3502571,43.9576072,'6165 3144 King Abdulaziz Rd','','','','https://www.saudi-guide.com/qassim-region/i/60148249/buraidah-museum-mthf-bryd',1,0,'متحف بريده buraidah museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148247,'qassim-region','متحف العقيلات','Aloqilat Museum','aloqilat-museum-mthf-alaakylat','["التراث والثقافة"]','["heritage"]','متحف العقيلات في بريدة، متحف خاص يروي تاريخ العقيلات ورحلاتهم التجارية بالإبل والخيول، ويضم قطعًا تراثية وسيارات قديمة من تاريخ القصيم.','<div class="texte" > <p>يطلق اسم "العقيلي" أو "العقيلات" على القبائل والأسر التي تاجرت بالإبل والخيول والأغنام والأغذية، ويحفظ متحف العقيلات قطعًا تراثية تروي التاريخ الذي مرّت به منطقة القصيم منذ ما يقارب 100 عام، وهو من المتاحف الخاصة التي يهتم أصحابها بالموروث الشعبي، ويحرصون على جمع واقتناء القطع المميزة من التراث والسيارات القديمة من مبدأ صون التراث وحفظ التاريخ للأجيال القادمة.</p> <p>ويسلّط المتحف الضوء على تنقلات العقيلات التجارية التي كانت تنطلق من القصيم وتمتدّ إلى العراق والشام ومصر والهند والصين، كما يكشف مساهمة العقيلات -من خلال رحلاتهم عبر التاريخ- في نقل الثقافة السعودية إلى البلدان التي قصدوها للتجارة.</p> <p>وفي مبنى رائع يحاكي الطراز العمراني القديم، يضمّ المتحف خريطة للطريق الذي سلكه "العقيلات" في تنقّلهم إلى الدول من حولهم، بالإضافة إلى لوحات يقدّر عددها بأكثر من 100 لوحة توثّق تاريخهم، والعديد من المخطوطات والمراسلات التي دارت بين الملك المؤسس -رحمه الله- والعقيلات في تلك الفترة.</p> </div>  <div class="texte" > <p>أوقات الزيارة: يستقبل المتحف زواره من الساعة 8:30 صباحًا إلى 12:00 ظهرًا، ومن الساعة 4:00 عصرًا إلى 6:30 مساءً.</p> </div>  <div class="texte" > <p>يقوم المتحف على جهود عبد اللطيف الوهيبي، الذي قام بتوثيق تاريخ العقيلات أحد أشهر الرحلات التجارية الحديثة والتي كانت تنطلق من منطقة القصيم،&nbsp;يحتوي المتحف على توثيق التاريخ بالصور عبر متحف العقيلات الذي أنشأه عبد اللطيف الوهيبي بمبادرة فردية وفتح المتحف أمام الزوار والباحثين، حيث ضم المتحف أكثر من 10 آلاف وثيقة تاريخية تختص بالعقيلات وكذلك الأدوات وخريطة المسارات التجارية لهم،&nbsp;المتحف يضم معظم الشخصيات الشهيرة في تجارة العقيلات والوثائق التي استخدموها،&nbsp;العقيلات هي حركة تجارية تنطلق من نجد وخصوصًا القصيم نحو البلاد المتاخمة للجزيرة العربية، يبلغ تاريخها قبل نحو 300 عام وانتهت بترسيم الحدود.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148247-60624460.jpg?v=1734214532", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148247-44816881.jpg?v=1641810393"]','https://cmsphoto.ww-cdn.com/resizeapi/fe9692714b6f8253f503ea575979c12ce228be24/480/',26.2987029,43.9945498,'418 Al Shifa'' Buraydah','','https://www.visitsaudi.com/ar/qassim/attractions/al-oqilat-museum-in-qassim','','https://www.saudi-guide.com/qassim-region/i/60148247/aloqilat-museum-mthf-alaakylat',1,0,'متحف عقيلات aloqilat museum تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148246,'qassim-region','متحف المجحدي لنوادر التراث والسيارات الكلاسيكية','Al Mujahdi Museum of Heritage and Classic Cars','almjehda-museum-anecdotes-heritage-and-classic-cars-mthf-almghdy-lnoadr-altrath-oalsyarat-alklasyky','["التراث والثقافة"]','["heritage"]','متحف المجحدي في بريدة، يضم نخبة من السيارات الكلاسيكية إلى جانب نوادر التراث والقطع الأثرية المميزة، ووجهة لعشاق السيارات القديمة والتراث.','<div class="texte" > <p>متحف المجحدي لنوادر التراث والسيارات الكلاسيكية يضم النخبه والعديد من السيارات الكلاسيكية ايضا نوادر التراث والقطع الاثرية المميزة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148246-44816874.jpg?v=1641810371"]','https://cmsphoto.ww-cdn.com/resizeapi/9385e5ac6f567a8ca32faeb616374f6feb0bf8ab/480/',26.2628483,43.9989807,'Buraydah Khub Al Qasba Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148246/almjehda-museum-anecdotes-heritage-and-classic-cars-mthf-almghdy-lnoadr-altrath-oalsyarat-alklasyky',1,0,'متحف مجحدي لنوادر تراث والسيارات كلاسيكيه al mujahdi museum of heritage and classic cars تراث والثقافه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148244,'qassim-region','جامع ومجمع الملك فهد رحمه الله الثقافي والاجتماعي','King Fahd Mosque and Cultural Complex','king-fahad-grand-mosque-gamaa-o-mgmaa-almlk-fhd-rhmh-allh-althkafy-o-alagtmaaay','["أماكن سياحية"]','["sights"]','جامع ومجمع الملك فهد الثقافي والاجتماعي في عيون الجواء بالقصيم، معلم ديني ومركز يخدم الأهالي والزوار بأنشطته الثقافية والاجتماعية.','<div class="texte" > <p>يقع جامع ومجمع الملك فهد الثقافي والاجتماعي في محافظة عيون الجواء بمنطقة القصيم، ويضم جامعًا ومجمعًا يخدم أهالي المحافظة وزوارها في الجوانب الدينية والثقافية والاجتماعية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148244-44817088.jpg?v=1641811129"]','https://cmsphoto.ww-cdn.com/resizeapi/b1b20601b9d415bf68587aa8dec2fab16b030190/480/',26.4915992,43.6349019,'FJRM+JXJ Uyun Al Jawa Uyun AlJiwa','','','','https://www.saudi-guide.com/qassim-region/i/60148244/king-fahad-grand-mosque-gamaa-o-mgmaa-almlk-fhd-rhmh-allh-althkafy-o-alagtmaaay',1,0,'جامع ومجمع ملك فهد رحمه له ثقافي والاجتماعي king fahd mosque and cultural complex اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148242,'qassim-region','منتزه شبه الجزيرة في عيون الجواء','Peninsula Park in Uyun Al Jiwa','mntz-shbh-algzyr-fy-aayn-algoaaa','["أماكن سياحية"]','["sights"]','منتزه شبه الجزيرة في عيون الجواء بمنطقة القصيم، مساحة ترفيهية مفتوحة للعائلات والزوار للتنزه والاستمتاع بالأجواء الخارجية.','<div class="texte" > <p>يقع منتزه شبه الجزيرة في محافظة عيون الجواء بمنطقة القصيم، وهو مساحة ترفيهية مفتوحة يقصدها الأهالي والزوار للتنزه وقضاء الأوقات في الهواء الطلق.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148242-44817091.jpg?v=1641811146"]','https://cmsphoto.ww-cdn.com/resizeapi/34115c9a314cea0f0b1dc43eabf62c9541da71f6/480/',26.4845295,43.6414078,'7679 عبدالله بن عباس Uyun Al Jawa','','','','https://www.saudi-guide.com/qassim-region/i/60148242/mntz-shbh-algzyr-fy-aayn-algoaaa',1,0,'منتزه شبه جزيره في عيون جواء peninsula park in uyun al jiwa اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148239,'qassim-region','محمية الفوزان للغزلان والمها العربي والنعام','Deer Farm Buraydah','deer-farm-buraydah-mhmy-alfozan-llghzlan-oalmha-alaarby-oalnaaam','["أماكن سياحية"]','["sights"]','محمية الفوزان في بريدة، وجهة عائلية لمشاهدة الغزلان والمها العربي والنعام عن قرب، وتجمع بين الطبيعة والتعرف على الحياة الفطرية.','<div class="texte" > <p>تقع محمية الفوزان قرب مدينة بريدة بمنطقة القصيم، وتضم الغزلان والمها العربي والنعام، ما يتيح للزوار فرصة مشاهدة هذه الحيوانات عن قرب والتعرف على الحياة الفطرية في بيئة طبيعية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148239-44872333.jpg?v=1642162686"]','https://cmsphoto.ww-cdn.com/resizeapi/ff899a002e6f670cfef1d542887819479aed65c7/480/',26.44327,43.689232,'SA Buraydah Al Qassim','','','','https://www.saudi-guide.com/qassim-region/i/60148239/deer-farm-buraydah-mhmy-alfozan-llghzlan-oalmha-alaarby-oalnaaam',1,0,'محميه فوزان للغزلان والمها عربي والنعام deer farm buraydah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148238,'qassim-region','مزرعة الحبردي السياحية بالبدائع','Al Habardi Tourist Farm in Al Badayea','mzraa-alhbrdy-alsyahy-balbdayaa','["أماكن سياحية"]','["sights"]','مزرعة الحبردي السياحية في البدائع بالقصيم، وجهة ريفية للعائلات تجمع بين أجواء المزارع والطبيعة الهادئة، وتناسب النزهات والرحلات القصيرة.','<div class="texte" > <p>تقع مزرعة الحبردي السياحية في محافظة البدائع بمنطقة القصيم، وهي وجهة ريفية تتيح للعائلات قضاء أوقات هادئة وسط أجواء المزارع والطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148238-44872339.jpg?v=1642162713"]','https://cmsphoto.ww-cdn.com/resizeapi/7886421f56573b5e75bc33c9f1642b88107e3ae2/480/',26.0554675,43.7841452,'Eastern Ring Rd Al Badayea Unaizah','','','','https://www.saudi-guide.com/qassim-region/i/60148238/mzraa-alhbrdy-alsyahy-balbdayaa',1,0,'مزرعه حبردي سياحيه بالبدائع al habardi tourist farm in al badayea اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148212,'qassim-region','منتزه المملكة بالبدائع','Kingdom Garden','kingdom-garden-mntzh-almmlk-balbdayaa','["أماكن سياحية"]','["sights"]','منتزه المملكة في محافظة البدائع بمنطقة القصيم، مساحة ترفيهية مفتوحة للعائلات تناسب التنزه وقضاء الأوقات الممتعة في الهواء الطلق.','<div class="texte" > <p>يقع منتزه المملكة في محافظة البدائع بمنطقة القصيم، وهو متنزه مفتوح للعائلات والزوار يناسب التنزه والجلسات الخارجية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148212-44872341.jpg?v=1642162737"]','https://cmsphoto.ww-cdn.com/resizeapi/73bf8ad4f8551f4ddc8dd31b0f79fc2ceb9c9332/480/',25.9472411,43.7390768,'WPWQ+VJW Al Badayea Al Badayea','','','','https://www.saudi-guide.com/qassim-region/i/60148212/kingdom-garden-mntzh-almmlk-balbdayaa',1,0,'منتزه مملكه بالبدائع kingdom garden اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148202,'qassim-region','عالم الرماية لعبة البنتبول','Shooting World Paintball','shooting-world-paintball-aaalm-alrmay-laab-albntbol','["أماكن سياحية"]','["sights"]','عالم الرماية في عنيزة، وجهة ترفيهية لمحبي لعبة البنتبول والرماية، تناسب الشباب والمجموعات لقضاء أوقات مليئة بالحماس والمغامرة.','<div class="texte" > <p>يقع عالم الرماية في محافظة عنيزة بمنطقة القصيم، ويقدّم أنشطة الرماية ولعبة البنتبول لمحبي المغامرة والحماس من الشباب والمجموعات.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148202-44872345.jpg?v=1642162756"]','https://cmsphoto.ww-cdn.com/resizeapi/bf0ba9f2787fafa2c3482fd9c198881b973a75dd/480/',26.1390275,43.9862638,'King Abdulaziz Rd Ar Rawghani Unayzah','','','','https://www.saudi-guide.com/qassim-region/i/60148202/shooting-world-paintball-aaalm-alrmay-laab-albntbol',1,0,'عالم رمايه لعبه بنتبول shooting world paintball اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148199,'qassim-region','حايط الحركان التراثي','Al Harkan Heritage Farm','hayt-alhrkan-altrathy','["أماكن سياحية"]','["sights"]','حايط الحركان التراثي في عنيزة بمنطقة القصيم، موقع تراثي يعكس طابع البناء والحياة القديمة في المحافظة، ووجهة لمحبي التراث والتصوير.','<div class="texte" > <p>يقع حايط الحركان التراثي في حي مريبدة بمحافظة عنيزة، و"الحايط" في اللهجة المحلية هو البستان أو المزرعة المسوّرة، ويعكس الموقع طابع المزارع والحياة القديمة في عنيزة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148199-44872351.jpg?v=1642162775"]','https://cmsphoto.ww-cdn.com/resizeapi/55b12f1cf83701a6e5a159a185f3c8382a020b07/480/',26.0902924,43.9716253,'6563 حي مريبدة Ad Dulayah','','','','https://www.saudi-guide.com/qassim-region/i/60148199/hayt-alhrkan-altrathy',1,0,'حايط حركان تراثي al harkan heritage farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148195,'qassim-region','منتجع الفلايح','Al Falayeh Resort','mntgaa-alflayh','["أماكن سياحية"]','["sights"]','منتجع الفلايح في عنيزة بمنطقة القصيم، وجهة ريفية للاسترخاء والتنزه وسط أجواء المزارع، ومناسبة للعائلات ومحبي الطبيعة الهادئة.','<div class="texte" > <p>يقع منتجع الفلايح في محافظة عنيزة بمنطقة القصيم، وهو وجهة ريفية للاسترخاء والتنزه وسط أجواء المزارع، مناسبة للعائلات ومحبي الطبيعة الهادئة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148195-44872354.jpg?v=1642162790"]','https://cmsphoto.ww-cdn.com/resizeapi/ef8680ebafcdeef464e869059a33a31866d5554c/480/',26.0896532,43.9718577,'3XQC+VP9 Ad Dulayah Unayzah','','','','https://www.saudi-guide.com/qassim-region/i/60148195/mntgaa-alflayh',1,0,'منتجع فلايح al falayeh resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148178,'qassim-region','مزرعة العبيد للكراث والخضار والورقيات','Al Obaid Farm for Leeks and Vegetables','mzraa-alaabyd-llkrath-oalkhdar-oalorkyat','["أماكن سياحية"]','["sights"]','مزرعة العبيد في عنيزة، مزرعة متخصصة في الكراث والخضار والورقيات، وتجربة ريفية للتعرف على الزراعة المحلية في منطقة القصيم.','<div class="texte" > <p>تقع مزرعة العبيد في محافظة عنيزة بمنطقة القصيم، وهي مزرعة متخصصة في زراعة الكراث والخضار والورقيات، وتقدّم للزوار لمحة عن الزراعة المحلية في المنطقة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148178-44872363.jpg?v=1642162823"]','https://cmsphoto.ww-cdn.com/resizeapi/1ea5ef36b1fcaf9ddecfcab8ce26da1b7257e2dc/480/',26.0850128,43.9757518,'شارع الريان Al Rayan Unayzah','','','','https://www.saudi-guide.com/qassim-region/i/60148178/mzraa-alaabyd-llkrath-oalkhdar-oalorkyat',1,0,'مزرعه عبيد للكراث والخضار والورقيات al obaid farm for leeks and vegetables اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148153,'qassim-region','عنيزة بوليفارد','The Boulevard Unayzah','boulevard-unayzah-aanyz-bolyfard','["أماكن سياحية"]','["sights"]','عنيزة بوليفارد في القصيم، وجهة ترفيهية حديثة للعائلات والشباب تجمع بين الممشى والمطاعم والمقاهي والأنشطة الترفيهية في أجواء حيوية.','<div class="texte" > <p>عنيزة بوليفارد وجهة حديثة في محافظة عنيزة بمنطقة القصيم، تضم مجموعة من المطاعم والمقاهي، ويقصدها الأهالي والزوار للتنزه وقضاء أوقات ممتعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148153-44872409.jpg?v=1642163193"]','https://cmsphoto.ww-cdn.com/resizeapi/17362b2beb0f89bbc395290f8d5622795890c8e0/480/',26.0725788,44.0124166,'32F6+2XM Al Wafaa Unayzah','','','','https://www.saudi-guide.com/qassim-region/i/60148153/boulevard-unayzah-aanyz-bolyfard',1,0,'عنيزه بوليفارد the boulevard unayzah اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148149,'qassim-region','منتزه الأمير فيصل بن مشعل بن سعود (البصر)','Prince Faisal bin Mishaal Park (Al Basr)','mntzh-alamyr-fysl-bn-mshaal-bn-saaod-albsr','["أماكن سياحية"]','["sights"]','منتزه الأمير فيصل بن مشعل بن سعود في البصر ببريدة، مساحة خضراء ومتنزه عائلي يناسب التنزه وقضاء أوقات ممتعة في الهواء الطلق.','<div class="texte" > <p>يقع منتزه الأمير فيصل بن مشعل بن سعود في منطقة البصر غرب مدينة بريدة، ويُعد من المتنزهات المعروفة في المدينة، ويستضيف فعاليات موسمية ترفيهية وتراثية يقصدها الأهالي والزوار.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148149-44872415.jpg?v=1642163218"]','https://cmsphoto.ww-cdn.com/resizeapi/a14b99b877669ffb405e2de3be014911e621a4bb/480/',26.3023815,43.8369124,'SA Buraydah Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148149/mntzh-alamyr-fysl-bn-mshaal-bn-saaod-albsr',1,0,'منتزه امير فيصل بن مشعل بن سعود (البصر) prince faisal bin mishaal park (al basr) اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148139,'qassim-region','البخاري بوليفارد','Al Bukhari Boulevard','albkhary-bolyard','["أماكن سياحية"]','["sights"]','البخاري بوليفارد في بريدة، ممشى ووجهة حضرية للعائلات والشباب تجمع بين أجواء المشي والجلسات الخارجية والمقاهي في المدينة.','<div class="texte" > <p>يقع البخاري بوليفارد على شارع البخاري في حي الريان بمدينة بريدة، وهو وجهة حضرية يقصدها الأهالي والزوار للمشي وقضاء الأوقات.</p> </div>','[]','',26.3995395,43.9167911,'شارع البخاري Al Rayyan Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148139/albkhary-bolyard',1,0,'بخاري بوليفارد al bukhari boulevard اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148116,'qassim-region','مزرعة السليم السياحية','Al Salim Tourist Farm','mzraa-alslym-alsyahy','["أماكن سياحية"]','["sights"]','مزرعة السليم السياحية في بريدة بمنطقة القصيم، وجهة ريفية للعائلات تجمع بين أجواء المزارع والطبيعة، ومناسبة للنزهات والرحلات القصيرة.','<div class="texte" > <p>تقع مزرعة السليم السياحية على طريق الملك فهد غرب مدينة بريدة، وهي وجهة ريفية تتيح للعائلات الاستمتاع بأجواء المزارع والطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148116-44872419.jpg?v=1642163241"]','https://cmsphoto.ww-cdn.com/resizeapi/67d4afcab92c0bb3433547be65e3af95fa4f652c/480/',26.3281914,43.9112914,'King Fahd Rd غرب Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148116/mzraa-alslym-alsyahy',1,0,'مزرعه سليم سياحيه al salim tourist farm اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148083,'qassim-region','برج بريدة','Buraidah Tower','buraidah-tower-brg-bryd','["أماكن سياحية"]','["sights"]','برج بريدة أو برج مياه بريدة، معلم بارز شمال المدينة افتُتح عام 1406هـ على مساحة 45 ألف متر مربع، ومن أشهر رموز مدينة بريدة ومنطقة القصيم.','<div class="texte" > <p>برج مياه بريدة أو برج بريدة هو برج مياه يقع في شمال مدينة بريدة في منطقة القصيم. تم افتتاحة عام 1406هـ على بعد 5 كم من محطة التنقية بمساحة مقدارها 45000 م2،&nbsp;أشرفت على تنفيذه شركة «كمهو» الكورية بتكلفة تقدر بـ 69 مليون ريال.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148083-44872464.jpg?v=1642163540"]','https://cmsphoto.ww-cdn.com/resizeapi/9dae2938db6e0bc0c202fa3555109f30810bf942/480/',26.3535785,43.9558526,'6593 King Abdulaziz Rd Al Safra''','','','','https://www.saudi-guide.com/qassim-region/i/60148083/buraidah-tower-brg-bryd',1,0,'برج بريده buraidah tower اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148060,'qassim-region','حديقة الملك خالد','King Khalid Park','king-khalid-park-hdyk-almlk-khald','["أماكن سياحية"]','["sights"]','حديقة الملك خالد في حي الصفراء ببريدة، حديقة عامة ومتنفس للعائلات بمساحات خضراء، تناسب التنزه والمشي وقضاء الأوقات في الهواء الطلق.','<div class="texte" > <p>تقع حديقة الملك خالد في حي الصفراء بمدينة بريدة، وتتميز بمسطحاتها الخضراء الواسعة وأشجارها الظليلة ومضمار للمشي، ما يجعلها مكانًا مناسبًا لتجمع العائلات والأصدقاء.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148060-44872421.jpg?v=1642163260"]','https://cmsphoto.ww-cdn.com/resizeapi/44e39e2e1ef076e4366a20444a23db4d49a43426/480/',26.3524066,43.9588761,'SA Al Safra'' Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148060/king-khalid-park-hdyk-almlk-khald',1,0,'حديقه ملك خالد king khalid park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148058,'qassim-region','مزارع الصباخ السياحية','Al Sabakh Tourist Farms','mzaraa-alsbakh-alsyahy','["أماكن سياحية"]','["sights"]','مزارع الصباخ السياحية جنوب بريدة، وجهة ريفية تجمع بين مزارع النخيل والطبيعة، ومناسبة للعائلات ومحبي الأجواء الزراعية الهادئة.','<div class="texte" > <p>تقع مزارع الصباخ جنوب مدينة بريدة، وهي منطقة زراعية تنتشر فيها مزارع النخيل، ويقصدها الزوار للاستمتاع بالأجواء الريفية الهادئة.</p> </div>','[]','',26.3592309,43.981812,'جنوب، بريدة بريدة','','','','https://www.saudi-guide.com/qassim-region/i/60148058/mzaraa-alsbakh-alsyahy',1,0,'مزارع صباخ سياحيه al sabakh tourist farms اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148056,'qassim-region','منتزه الملك عبدالله الوطني','King Abdullah National Park','king-abdullah-national-park-mntzh-almlk-aabdallh-alotny','["أماكن سياحية"]','["sights"]','منتزه الملك عبدالله الوطني في بريدة، منتزه يجمع بين الطابع البري والحضري على مساحة تتجاوز 1.6 مليون متر مربع، بإطلالة خلابة على المدينة.','<div class="texte" > <p>منتزه الملك عبد الله الوطني هو منتزه وحديقة عامة في مدينة بريدة ذو تصميم يجمع بين المنتزه البري والحضري وتبلغ مساحته أكثر من 1.6 مليون مربع ، وهو أحد برامج التوازن والإصحاح البيئي لزيادة مساحة الرقعة الخضراء بمدينة بريدة،&nbsp;يطل المتنزه على مدينة بريدة وذلك لتماشيه مع طبوغرافية الأرض الطبيعية، حيث يقع المنتزه على طريق الملك فهد عند تقاطعه مع الطريق الدائري الشرقي، ليتمتع زائر المنتزه في منطقة ذات اطلالة خلابة على المدينة وقد نفذت دكات للجلوس مطلة على المدينة تمكن زائر المنتزه من رؤية مشهد بانورامي للمدينة من «نافورة البلازا».</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148056-44872460.jpg?v=1642163524"]','https://cmsphoto.ww-cdn.com/resizeapi/bdda29cb013b7f8a14a6744f9ab209181d5243dd/480/',26.3883589,44.0166685,'الرمز البريدي :، Al Nafl Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148056/king-abdullah-national-park-mntzh-almlk-aabdallh-alotny',1,0,'منتزه ملك عبدالله وطني king abdullah national park اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148055,'qassim-region','منتجع ديرتي الريفي','Derity Farm Resort','derity-farm-resort-mntgaa-dyrty-alryfy','["أماكن سياحية"]','["sights"]','منتجع ديرتي الريفي في بريدة بمنطقة القصيم، وجهة للاستجمام وسط أجواء ريفية هادئة، ومناسبة للعائلات ومحبي الطبيعة والمزارع.','<div class="texte" > <p>يقع منتجع ديرتي الريفي في مدينة بريدة بمنطقة القصيم، ويقدّم لزواره أجواء ريفية هادئة للاستجمام، مناسبة للعائلات ومحبي الطبيعة والمزارع.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148055-44872422.jpg?v=1642163278"]','https://cmsphoto.ww-cdn.com/resizeapi/c860549df0f3157d9cf709f87ce4dec09f8bf039/480/',26.3178189,43.9737761,'شارع المياه حي الجنوب Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148055/derity-farm-resort-mntgaa-dyrty-alryfy',1,0,'منتجع ديرتي ريفي derity farm resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148054,'qassim-region','مدينة التمور ببريدة','Dates City','dates-city-mdyn-altmor-bbrydh','["أماكن سياحية"]','["sights"]','مدينة التمور في بريدة، من أشهر وجهات تسويق التمور في منطقة القصيم، تعكس مكانة القصيم الزراعية وتنوع أصناف التمور التي تشتهر بها.','<div class="texte" > <p>تقع مدينة التمور في حي الصباخ بمدينة بريدة، وتُعد من أكبر أسواق التمور في المملكة، وتحتضن موسميًا مهرجان تمور بريدة الذي تُعرض فيه أصناف التمور التي تشتهر بها منطقة القصيم.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148054-44872425.jpg?v=1642163296"]','https://cmsphoto.ww-cdn.com/resizeapi/1d6fc4f1822c6f72677ce6f9d05ae0ebc316cf90/480/',26.3132315,43.9814713,'As Sabbakh Buraydah Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148054/dates-city-mdyn-altmor-bbrydh',1,0,'مدينه تمور ببريده dates city اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60148032,'qassim-region','منتجع جاردن تلنتس','Talents Garden Protected Birds','talents-garden-protected-birds-mntgaa-gardn-tlnts','["أماكن سياحية"]','["sights"]','منتجع جاردن تلنتس في خب القصبة ببريدة، وجهة ريفية تضم طيورًا محمية ومساحات خضراء، ومناسبة للعائلات ومحبي الطبيعة والهدوء.','<div class="texte" > <p>يقع منتجع جاردن تلنتس في خب القصبة بمدينة بريدة، وهو وجهة ريفية تضم مجموعة من الطيور المحمية ومساحات خضراء، مناسبة للعائلات ومحبي الطبيعة.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60148032-44872428.jpg?v=1642163313"]','https://cmsphoto.ww-cdn.com/resizeapi/d8c8dd0bb40f9fc524879d1dd5aaec27995697ab/480/',26.2621144,43.9954457,'الوجيعان Khub Al Qasba Buraydah','','','','https://www.saudi-guide.com/qassim-region/i/60148032/talents-garden-protected-birds-mntgaa-gardn-tlnts',1,0,'منتجع جاردن تلنتس talents garden protected birds اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121541,'eastern-region','برج الطوية الأثري','Crease Archaeological Tower','crease-archaeological-tower-brg-altoy-alathry','["أماكن سياحية"]','["sights"]','برج الطوية أو حصن الطوية أو برج حصن الطوية هو برج تحصيني يقع وسط محافظة الجبيل في السعودية وهو المعلم الأثري التراثي الرمزي الوحيد في محافظة الجبيل...','<div class="texte" > <p>برج الطوية أو حصن الطوية أو برج حصن الطوية هو برج تحصيني يقع وسط محافظة الجبيل في السعودية وهو المعلم الأثري التراثي الرمزي الوحيد في محافظة الجبيل وأحد الشواهد على حقبة بدايات نشأة الجبيل لأنه يرتبط بعهد الملك عبد العزيز آل سعود. بني الحصن عام 1928م ويعتقد أنه قد بُني لحماية بئر الطوية.</p> </div>  <div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121541-45096046.jpg?v=1643852695"]','https://cmsphoto.ww-cdn.com/resizeapi/29d6d5d92c86695d1f56f2a59a9598601530db7a/480/',27.012727,49.6369493,'Abu Ali Rd King Fahd Industrial Port Al Jubayl','','','','https://www.saudi-guide.com/eastern-region/i/60121541/crease-archaeological-tower-brg-altoy-alathry',1,0,'برج طويه اثري crease archaeological tower اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO places (id,city,title,title_en,slug,cats,kinds,summary,body,images,thumb,lat,lng,address,phone,website,email,url,comments,premium,search,updated) VALUES (60121519,'eastern-region','منتزه بو عينين الخلاب','Al buainain Farm and resort','al-buainain-farm-and-resort-mntzh-bo-aaynyn-alkhlab','["أماكن سياحية"]','["sights"]','منتزه بو عينين الخلاب وجهة ترفيهية وطبيعية بالمنطقة الشرقية، يجمع بين المساحات الخضراء وأجواء الاستجمام العائلي.','<div class="texte" > <p>الصور لأغراض تعريفية، وتعود حقوقها لأصحابها.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/60121519-45096048.jpg?v=1643852716"]','https://cmsphoto.ww-cdn.com/resizeapi/fd07b2292ff092bbc8976ae2abac7042b70bfc56/480/',26.8932427,49.4800008,'VFVJ+72R Al Jubail Jubail','','','','https://www.saudi-guide.com/eastern-region/i/60121519/al-buainain-farm-and-resort-mntzh-bo-aaynyn-alkhlab',1,0,'منتزه بو عينين خلاب al buainain farm and resort اماكن سياحيه',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98314628,'حفل فضل شاكر "ليلة عودة الغايب" - الليلة الثانية','ليلة ثانية لحفل فضل شاكر ليلة عودة الغايب على مسرح أبو بكر سالم في موسم الرياض يوم الجمعة 23 أكتوبر 2026 بعد نفاد تذاكر الليلة الأولى.','<div class="texte" > <p>بعد نفاد تذاكر الليلة الأولى، أُضيفت ليلة ثانية لحفل الفنان فضل شاكر "ليلة عودة الغايب" ضمن حفلات موسم الرياض 2026–2027 على مسرح أبو بكر سالم في بوليفارد رياض سيتي، بتنظيم شركة بنش مارك، يقدم فيها أشهر أغانيه لجمهوره.</p> <p><strong>الموعد:</strong> الجمعة 23 أكتوبر 2026، وتُفتح الأبواب الساعة 7:00 مساءً.</p> <p><strong>المكان:</strong> مسرح أبو بكر سالم، بوليفارد رياض سيتي، الرياض.</p> <p><strong>أسعار التذاكر (شاملة الضريبة):</strong> فئة C ‏475 ريال، فئة B ‏695 ريال، فئة A ‏950 ريال، VIP ‏2,875 ريال، VVIP ‏3,450 ريال. وتظهر التذاكر حالياً على ويبوك بحالة "نفدت التذاكر"، ويمكن متابعة تذاكر إعادة البيع المضمونة من ويبوك.</p> <p><strong>تنبيهات مهمة:</strong> الدخول من عمر 15 سنة فأكبر، وتذكرة لكل شخص، والتذاكر غير مستردة ويُمنع إعادة بيعها خارج المنصة، ولا يُسمح بالعودة بعد مغادرة المبنى، مع الالتزام بقواعد الذوق العام واللبس المحتشم.</p> <p><strong>المصدر:</strong> <a href="https://webook.com/ar/sa/ruh/music-events/events/the-return-night-2-tickets-rs27-873737" target="_blank">ويبوك (Webook)</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98314628-68537949.jpg?v=1791499572", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98314628-68537953.jpg?v=1791499591"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98314628-68537949.jpg?v=1791499573','2026-10-23T16:00:00.000Z','2026-10-23T20:30:00.000Z',0,'["موسم الرياض", "غنائية ومسرحية"]','riyadh',24.773693,46.605288,'مسرح أبو بكر سالم، بوليفارد رياض سيتي، حي حطين، الرياض','https://webook.com/ar/sa/ruh/music-events/events/the-return-night-2-tickets-rs27-873737','','https://www.saudi-guide.com/events/i/98314628/fadel-shaker-awdat-alghayeb-night-2-riyadh-season',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98314627,'حفل فضل شاكر "ليلة عودة الغايب" - موسم الرياض','فضل شاكر يفتتح حفلات موسم الرياض 2026–2027 بحفل ليلة عودة الغايب على مسرح أبو بكر سالم يوم 22 أكتوبر، والتذاكر تبدأ من 475 ريال عبر ويبوك.','<div class="texte" > <p>بعد طول انتظار، يعود الفنان فضل شاكر للقاء جمهوره في حفل "ليلة عودة الغايب"، الذي يفتتح حفلات موسم الرياض 2026–2027 على مسرح أبو بكر سالم في بوليفارد رياض سيتي، بتنظيم شركة بنش مارك. أمسية تعود فيها الأغاني التي أحبها الجمهور والذكريات التي ارتبطت بصوته على مدى السنين.</p> <p><strong>الموعد:</strong> الخميس 22 أكتوبر 2026، وتُفتح الأبواب الساعة 7:00 مساءً.</p> <p><strong>المكان:</strong> مسرح أبو بكر سالم، بوليفارد رياض سيتي، الرياض.</p> <p><strong>أسعار التذاكر (شاملة الضريبة):</strong> فئة C ‏475 ريال، فئة B ‏695 ريال، فئة A ‏950 ريال، Gold ‏1,500 ريال، VIP ‏2,875 ريال، VVIP ‏3,450 ريال، Royal ‏3,750 ريال.</p> <p><strong>تنبيهات مهمة:</strong> الدخول من عمر 15 سنة فأكبر، وتذكرة لكل شخص، والتذاكر غير مستردة ويُمنع إعادة بيعها، ولا يُسمح بالعودة بعد مغادرة المبنى، مع الالتزام بقواعد الذوق العام واللبس المحتشم.</p> <p><strong>المصدر:</strong> <a href="https://webook.com/ar/sa/ruh/music-events/events/the-return-night-concert-rs27-tickets-784736" target="_blank">ويبوك (Webook)</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98314627-68537948.jpg?v=1791499570", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98314627-68537952.jpg?v=1791499589"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98314627-68537948.jpg?v=1791499571','2026-10-22T16:00:00.000Z','2026-10-22T20:30:00.000Z',0,'["موسم الرياض", "غنائية ومسرحية"]','riyadh',24.773693,46.605288,'مسرح أبو بكر سالم، بوليفارد رياض سيتي، حي حطين، الرياض','https://webook.com/ar/sa/ruh/music-events/events/the-return-night-concert-rs27-tickets-784736','','https://www.saudi-guide.com/events/i/98314627/fadel-shaker-awdat-alghayeb-riyadh-season',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98276255,'بطولة Six Kings Slam 2026 للتنس','بطولة Six Kings Slam 2026 في الرياض أيام 21 و22 و24 أكتوبر بمشاركة سينر وألكاراز وديوكوفيتش وزفيريف ودي مينور وفريتز، ضمن موسم الرياض.','<div class="texte" > <p>تعود بطولة التنس الاستعراضية "Six Kings Slam" في نسختها الثالثة ضمن فعاليات موسم الرياض، وتجمع ستة من أبرز نجوم التنس في العالم على أرض "ذا فينيو" (ANB Arena) بحي حطين في الرياض، بجوار بوليفارد سيتي.</p> <p><strong>النجوم المشاركون:</strong> الإيطالي يانيك سينر، والإسباني كارلوس ألكاراز، والصربي نوفاك ديوكوفيتش، والألماني ألكسندر زفيريف، والأسترالي أليكس دي مينور، والأمريكي تايلور فريتز.</p> <p><strong>جدول البطولة:</strong> الأربعاء 21 أكتوبر ربع النهائي، والخميس 22 أكتوبر نصف النهائي، والسبت 24 أكتوبر المباراة النهائية ومباراة المركز الثالث. وتقام المنافسات بنظام خروج المغلوب، بدون مباريات يوم الجمعة 23 أكتوبر.</p> <p><strong>التذاكر:</strong> عبر منصة Webook الرسمية، والدخول للأطفال من عمر 5 سنوات مع مرافق بتذكرة مستقلة. وتُنقل المباريات مباشرة على منصة Netflix لمن يتابع من خارج الرياض.</p> <p><strong>المصدر:</strong> <a href="https://www.spa.gov.sa/en/N2690978" target="_blank">وكالة الأنباء السعودية (واس)</a>، <a href="https://sabq.org/article/rwmr5od" target="_blank">صحيفة سبق</a>، <a href="https://webook.com/en/zones/the-venue-rs25" target="_blank">ويبوك (Webook)</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98276255-68537923.jpg?v=1791499294"]','https://cmsphoto.ww-cdn.com/resizeapi/cbc366476b1c2797b6772c4d208522a30c89c378/480/','2026-10-21T13:00:00.000Z','2026-10-24T20:59:00.000Z',0,'["موسم الرياض", "رياضية"]','riyadh',24.7764783,46.6066881,'ذا فينيو (ANB Arena)، حي حطين، الرياض','https://webook.com/en/zones/the-venue-rs25','','https://www.saudi-guide.com/events/i/98276255/six-kings-slam-2026-riyadh',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98083103,'مهرجان سماء العلا','احتفِ بسماء العلا الصافية من 6 إلى 15 نوفمبر 2026 مع رحلات المناطيد الهوائية، عروض ضوئية، سينما تحت القمر، ومغامرات رصد النجوم في أول محمية سماء مظلمة بالخليج.','<div class="texte" > <p>احتفِ بسماء العلا مع رحلات المناطيد الهوائية فوق الأودية والتضاريس الخلابة نهارًا، ومع حلول الليل استمتع بعروض المناطيد المثبتة على أنغام الموسيقى، والسينما تحت ضوء القمر، ومغامرات رصد النجوم. تُعد العلا أول محمية سماء مظلمة معتمدة في الخليج، بسماء صافية خالية من التلوث الضوئي.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98083103-68299196.jpg?v=1789807897"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98083103-68299196.jpg?v=1789807898','2026-11-06T11:00:00.000Z','2026-11-15T11:00:00.000Z',1,'["لحظات العلا", "المهرجانات"]','alula',26.6242728,37.9144594,'العلا','','https://www.experiencealula.com/ar/whats-on/festivals/alula-skies-festival','https://www.saudi-guide.com/events/i/98083103/alula-skies-festival',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98080590,'تجربة شاطئ قالو','يوم هادئ على شاطئ جدة، استمتع بأجواء نادي شاطئ قالو الأنيقة وسط إطلالة رائعة على البحر الأحمر ومرافق مخصصة للاسترخاء. يستقبل النادي الزوار يوميًا من 10:00 صباحًا حتى 5:00 مساءً، وسعر الدخول 100 ريال ل','<div class="texte" > <p>يوم هادئ على شاطئ جدة، استمتع بأجواء نادي شاطئ قالو الأنيقة وسط إطلالة رائعة على البحر الأحمر ومرافق مخصصة للاسترخاء. يستقبل النادي الزوار يوميًا من 10:00 صباحًا حتى 5:00 مساءً، وسعر الدخول 100 ريال للشخص الواحد.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080590-68297606.jpg?v=1789770939"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080590-68297606.jpg?v=1789770940','2026-08-25T07:00:00.000Z','2026-10-31T14:00:00.000Z',0,'["موسم جدة", "تجارب ومغامرات"]','jeddah',21.8454068,38.9985298,'شاطئ قالو، جدة','https://jeddah.platinumlist.net/ar/event-tickets/107853/galu-beach','https://www.visitsaudi.com/ar/destinations/jeddah/events/galu-beach-experience','https://www.saudi-guide.com/events/i/98080590/tgrb-shaty-kalo',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98080580,'«استمرارية 26» برنامج الفنانين الناشئين بمركز الدرعية لفنون المستقبل','النسخة الثانية من سلسلة المعارض السنوية التي تحتفي بمخرجات 16 فنانًا ناشئًا في فنون الوسائط الجديدة، بعد مسار تطوير امتد عامًا كاملًا، وتتنوع الأعمال بين التركيبات الغامرة والواقع الافتراضي والذكاء ال','<div class="texte" > <p>النسخة الثانية من سلسلة المعارض السنوية التي تحتفي بمخرجات 16 فنانًا ناشئًا في فنون الوسائط الجديدة، بعد مسار تطوير امتد عامًا كاملًا، وتتنوع الأعمال بين التركيبات الغامرة والواقع الافتراضي والذكاء الاصطناعي وأعمال الضوء والصوت. يُقام بمركز الدرعية لفنون المستقبل، يوميًا من 2:00 ظهرًا حتى منتصف الليل، والتذاكر من 50 ريالاً.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080580-68297584.jpg?v=1789770743"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080580-68297584.jpg?v=1789770744','2026-09-03T11:00:00.000Z','2026-11-07T20:59:00.000Z',0,'["موسم الدرعية", "معارض ومؤتمرات"]','riyadh',24.7398349,46.5728451,'الدرعية، الرياض','https://webook.com/ar/sa/ruh/activities-adventures/events/continuum-26-moc876-diriyah-art-futures','https://www.visitsaudi.com/ar/destinations/diriyah/events/continuum-26-diriyah-art-futures','https://www.saudi-guide.com/events/i/98080580/astmrary-26-brnamg-alfnanyn-alnashyyn-bmrkz-aldraay-lfnon-almstkbl',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98080446,'معرض اللغة العربية للطفل','معرض يعيش الطفل فيه تجربة لا تُنسى مع اللغة العربية، ينتقل فيها بين محطاتٍ تفاعلية تمزج بين اللعب والمعرفة، من قصص تتحدث، وشاشات تتفاعل، وتجارب تفتح أبواب الإبداع. يقع في مجمع الملك سلمان العالمي للغة','<div class="texte" > <p>معرض يعيش الطفل فيه تجربة لا تُنسى مع اللغة العربية، ينتقل فيها بين محطاتٍ تفاعلية تمزج بين اللعب والمعرفة، من قصص تتحدث، وشاشات تتفاعل، وتجارب تفتح أبواب الإبداع. يقع في مجمع الملك سلمان العالمي للغة العربية، ويعمل من السبت إلى الأربعاء من 8:00 صباحًا حتى 4:00 مساءً، وللتواصل: 0115207777.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080446-68297546.jpg?v=1789770314"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080446-68297546.jpg?v=1789770315','2026-01-01T05:00:00.000Z','2026-12-31T13:00:00.000Z',0,'["معارض ومؤتمرات"]','riyadh',24.7208204,46.6717366,'مجمع الملك سلمان العالمي للغة العربية، الورود، الرياض','https://www.visitsaudi.com/ar/destinations/riyadh/events/arabic-language-exhibition-for-kids','https://alx.ksaa.gov.sa/','https://www.saudi-guide.com/events/i/98080446/maard-allgh-alaarby-lltfl',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98080445,'معرض اللغة العربية 28','في مجمع الملك سلمان العالمي للغة العربية بقلب الرياض، معرض لغوي تفاعلي يجمع بين الأصالة والابتكار؛ رحلة يعيشها الزائر بين أروقةٍ تنبض بتاريخ العربية وجمالها، وتقنيات حديثة تجسّد كيف يمكن للّغة أن تتحو','<div class="texte" > <p>في مجمع الملك سلمان العالمي للغة العربية بقلب الرياض، معرض لغوي تفاعلي يجمع بين الأصالة والابتكار؛ رحلة يعيشها الزائر بين أروقةٍ تنبض بتاريخ العربية وجمالها، وتقنيات حديثة تجسّد كيف يمكن للّغة أن تتحول إلى تجربة حيّة تُرى وتُسمع وتُلمس. يعمل من السبت إلى الأربعاء من 8:00 صباحًا حتى 4:00 مساءً (ويغلق يومي الخميس والجمعة)، وللتواصل: 0115207777.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080445-68297542.jpg?v=1789770293"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080445-68297542.jpg?v=1789770293','2026-01-01T05:00:00.000Z','2026-12-31T13:00:00.000Z',0,'["معارض ومؤتمرات"]','riyadh',24.7208204,46.6717366,'مجمع الملك سلمان العالمي للغة العربية، الورود، الرياض','https://www.visitsaudi.com/ar/destinations/riyadh/events/arabic-language-exhibition','https://alx.ksaa.gov.sa/','https://www.saudi-guide.com/events/i/98080445/maard-allgh-alaarby-28',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (98080415,'كرنفال بريدة الدولي للتمور','اكتشف كرنفال بريدة الدولي للتمور، أحد أبرز مهرجانات التمور في السعودية، يُقام في مدينة التمور ببريدة ويجمع بين المزادات اليومية للتمور والتجارب الثقافية والتراثية. يضم مركز النخلة، وساحة المزادات والأ','<div class="texte" > <p>اكتشف كرنفال بريدة الدولي للتمور، أحد أبرز مهرجانات التمور في السعودية، يُقام في مدينة التمور ببريدة ويجمع بين المزادات اليومية للتمور والتجارب الثقافية والتراثية. يضم مركز النخلة، وساحة المزادات والأسواق، ومتحف النخلة، والحرف التقليدية، وعربات الفود ترك. تُقام المزادات صباحًا من 4:30 حتى 9:00 صباحًا، وتستقبل الفعاليات المسائية الزوار يوميًا من 4:30 حتى 9:00 مساءً، والدخول مجاني لجميع الزوار.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98080415-68297524.jpg?v=1789770178"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98080415-68297524.jpg?v=1789770179','2026-08-01T13:30:00.000Z','2026-10-15T18:00:00.000Z',0,'["المهرجانات"]','qassim-region',26.3592309,43.981812,'بريدة، القصيم','','https://www.buraydahcarnival.com/ar','https://www.saudi-guide.com/events/i/98080415/krnfal-bryd-aldoly-lltmor',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (97902963,'Six Flags Qiddiya City -  مدينة القدية','افتتاح مدينة ملاهي Six Flags مدينة القدية – أكبر وجهة ترفيهية في السعودية','<div class="texte" > <p>افتتاح مدينة ملاهي Six Flags مدينة القدية – أكبر وجهة ترفيهية في السعودية</p> <p>استعدوا لحدث عالمي ينتظره عشاق الترفيه والمغامرات! في 31 ديسمبر 2025، تفتتح Six Flags مدينة القدية أبوابها لتصبح أضخم مدينة ملاهي في المملكة العربية السعودية وواحدة من أبرز الوجهات الترفيهية في العالم، بمساحة تفوق 320,000 متر مربع على سفوح جبال طويق الساحرة بالقرب من العاصمة الرياض. ستأخذكم المدينة في تجربة غير مسبوقة عبر 6 مناطق ترفيهية مبهرة:</p> <ul> <li> <p>القلعة (The Citadel): قلب المنتزه مع مطاعم عالمية ومتاجر فاخرة.</p> </li> <li> <p>مدينة التشويق (City of Thrills): تضم رحلة الصقر – أطول وأسرع وأعلى أفعوانية بالعالم، وبرج سيروكو – أعلى برج هبوط حر.</p> </li> <li> <p>ينابيع الاستكشاف (Discovery Springs): مغامرات مائية وسط أجواء صحراوية خلابة.</p> </li> <li> <p>مدينة البخار (Steam Town): تجارب صناعية مثيرة وأفعوانية Iron Rattler الفريدة.</p> </li> <li> <p>وادي الثروات (Valley of Fortune): مغامرات البحث عن الكنوز وسط أطلال قديمة.</p> </li> <li> <p>المعرض الكبير (Grand Exposition): تقنيات حديثة وألعاب مبتكرة في أجواء عالمية.</p> </li> </ul> <p>أبرز الحقائق والأرقام: ✅ 28 مرفق ترفيهي متنوعة بين ألعاب التشويق والألعاب العائلية. ✅ 5 ألعاب حصدت أرقامًا قياسية عالمية. ✅ 27 مطعمًا عالميًا و24 متجرًا فاخرًا للتسوق. ✅ عمليات تشغيل صديقة للبيئة مع إعادة تدوير 80% من النفايات.</p> <p>🎟 احجز التذاكر الرسمية أونلاين webook.com هو بائع معتمد لتذاكر سيكس فلاجز القدية سيتي الرسمية، مع حجز آمن، وتسليم رقمي فوري، وباقات مختارة بعناية للعائلات والأصدقاء والمجموعات. اختر بين تذاكر البالغين (+12) أو الأطفال (4–11)، واستمتع بدخول ليوم كامل إلى جميع الألعاب والمرافق الترفيهية.</p> <p>لماذا يجب أن تتصدر Six Flags, Qiddiya City خطّة رحلتك في الرياض:</p> <p>تقع هذه المدينة الترفيهية الضخمة بالقرب من العاصمة السعودية، وتُعد وجهة مثالية لعطلات نهاية الأسبوع، والرحلات العائلية اليومية، والخروجات الجماعية، ومغامرات الباحثين عن الإثارة.</p> <p>📍 الموقع: القدية سيتي، بالقرب من الرياض، المملكة العربية السعودية</p> <p>💡 خطّط لزيارتك اليوم!</p> <p>سواء كنت تبحث عن ألعاب الأدرينالين أو تجارب الترفيه العائلي، فإن Six Flags مدينة القدية هي الوجهة المثالية لعطلة نهاية الأسبوع، ورحلات العائلات، ومغامرات الأصدقاء.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97902963-68159246.jpg?v=1788399544"]','https://cmsphoto.ww-cdn.com/resizeapi/449a1f2ea2712fc60bfe22d42ed699fb5bd818c8/480/','2025-12-31T12:00:00.000Z','2026-12-30T22:00:00.000Z',0,'["ترفيه واستجمام"]','riyadh',24.586783,46.3311103,'H8PJ+PC Al Moqbel Palaces Al-Muzahmiyya','https://webook.com/ar/SA/RUH/experience/events/six-flags-new-2026','https://sixflagsqiddiyacity.com/ar/tickets-passes','https://www.saudi-guide.com/events/i/97902963/six-flags-qiddiya-city-mdyn-alkdy',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (97902910,'Aquarabia Qiddiya City - اكواريبيا - مدينه القديه','أكوارابيا – مدينة القدية: أكبر مغامرة مائية في السعودية','<div class="texte" > <p>أكوارابيا – مدينة القدية: أكبر مغامرة مائية في السعودية</p> <p>استعدوا لافتتاح أكوارابيا مدينة القدية في 23 أبريل الساعة 12:00 ظهراً، الوجهة المائية الاستثنائية التي ستغير مفهوم الترفيه في المملكة. يقع المنتزه في قلب مدينة القدية ويمتد على مساحة 250,000 متر مربع مليئة بالإثارة والمتعة لكل أفراد الأسرة.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/97902910-68159237.jpg?v=1788399315"]','https://cmsphoto.ww-cdn.com/resizeapi/94f22e523bdc4f0ea6f3200a2278aa2a4949a566/480/','2026-04-23T13:00:00.000Z','2026-12-30T21:00:00.000Z',0,'["ترفيه واستجمام"]','riyadh',24.584896,46.3250892,'Qiddiya City Al-Muzahmiyya Riyadh Province','https://webook.com/ar/sa/ruh/activities-adventures/events/aquarabia-qiddiya-tickets','https://aquarabiaqiddiyacity.com/ar','https://www.saudi-guide.com/events/i/97902910/aquarabia-qiddiya-city-akoarybya-mdynh-alkdyh',strftime('%s','now'));
INSERT OR REPLACE INTO events (id,title,summary,body,images,thumb,start,"end",all_day,cats,city,lat,lng,address,tickets,link,url,updated) VALUES (69412409,'تذكرة دخول الدرعية - العامة','اكتشف الطريف، مهد انطلاقة الدولة السعودية الأولى وأحد مواقع التراث العالمي لليونسكو، واستمتع بتجارب الطعام الراقية والفاخرة في مطل البجيري','<div class="texte" > <p>اكتشف الطريف، مهد انطلاقة الدولة السعودية الأولى وأحد مواقع التراث العالمي لليونسكو، واستمتع بتجارب الطعام الراقية والفاخرة في مطل البجيري</p> <p>مطل البجيري</p> <p>أيام الأسبوع:<br /> من الساعة 9:00 صباحاً حتى 12:00 صباحاً<br /> <br /> نهاية الأسبوع:<br /> من الساعة 9:00 صباحاً مساءً حتى 1:00 صباحاً<br /> <br /> &nbsp;</p> <p>الطريف</p> <p>يومياً:<br /> من الساعة 5:00 مساءً حتى 12:00 صباحاً<br /> <br data-end="206" data-start="203" /> (آخر دخول الساعة 11:00 مساءً)</p> </div> <div class="texte" > <p>ساعات العمل</p> <div> <p>سيفتح مطل البجيري أبوابه للضيوف 7 أيام في الأسبوع:</p> <p>من السبت إلى الأربعاء<br /> من 10:00 صباحا - 12:00 صباحا</p> <p>يوم الخميس<br /> من 10:00 صباحا - 1:00 صباحا</p> <p>أيام الجمعة وإجازات نهاية الأسبوع<br /> من 2:00 م - 2:00 ص</p> <p>* قد تختلف ساعات عمل المطاعم.</p> </div> </div> <div class="texte" > <blockquote class="twitter-tweet"> <p dir="rtl" lang="ar"><a href="https://twitter.com/hashtag/%D9%85%D8%B7%D9%84_%D8%A7%D9%84%D8%A8%D8%AC%D9%8A%D8%B1%D9%8A?src=hash&amp;ref_src=twsrc%5Etfw">#مطل_البجيري</a> يفتتح أبوابه للزوار!<br /> <br /> اكتشف تجربة تذوق غير مسبوقة عبر أكثر من 20 مطعم ومقهى بإطلالة استثنائية على حي <a href="https://twitter.com/hashtag/%D8%A7%D9%84%D8%B7%D8%B1%D9%8A%D9%81?src=hash&amp;ref_src=twsrc%5Etfw">#الطريف</a> التاريخي.<br /> <br /> احجز تجربتك عبر: <a href="https://t.co/kRqRaCcymw">https://t.co/kRqRaCcymw</a></p> — Visit Diriyah (@VisitDiriyah) <a href="https://twitter.com/VisitDiriyah/status/1599804367514882050?ref_src=twsrc%5Etfw">December 5, 2022</a></blockquote> <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/69412409-48547541.jpg?v=1670297354"]','https://cmsphoto.ww-cdn.com/resizeapi/f5063060869ca69f8a1a1161c73b3757a2a3e758/480/','2022-12-10T06:28:00.000Z','2026-12-30T21:00:00.000Z',0,'["ترفيه واستجمام", "تراثي ثقافي"]','riyadh',24.7367155,46.574677,'Riyadh Province Al Bujairi Ad Diriyah','https://tickets.bujairi.sa/ar/d/3552/diriyah-access','https://www.diriyah.sa/ar/','https://www.saudi-guide.com/events/i/69412409/tthkr-dkhol-aldraay-alaaam',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (98275491,'موسم الرياض 2026 ينطلق في 21 أكتوبر بنسخته السابعة تحت شعار "Big Time"','وكالة الأنباء السعودية','2026-10-05T09:00:00.000Z','تركي آل الشيخ يعلن انطلاق موسم الرياض 2026 في 21 أكتوبر بنسخته السابعة لمدة عشرة أسابيع، بنزالات عالمية وبطولة Six Kings Slam وعودة بوليفارد وورلد.','<div class="texte" > <p>أعلن رئيس مجلس إدارة الهيئة العامة للترفيه المستشار تركي بن عبدالمحسن آل الشيخ، يوم 26 سبتمبر 2026، موعد انطلاق فعاليات موسم الرياض 2026 يوم الأربعاء 21 أكتوبر، في نسخته السابعة التي تمتد على مدى عشرة أسابيع، وتضم برنامجًا متنوعًا من الفعاليات والبطولات والعروض والتجارب الترفيهية.</p> <p>وجاء الإعلان عبر مقطع مرئي تشويقي استعرض جانبًا من ملامح الموسم، الذي يتضمن نزالات عالمية في الملاكمة والمصارعة وبطولات UFC، إلى جانب بطولة التنس "Six Kings Slam"، والحفلات الموسيقية والعروض المسرحية والكوميدية، وفعاليات وتجارب مخصصة للأطفال والعائلات.</p> <p>وتعود "بوليفارد وورلد" ضمن مناطق الموسم بثقافاتها ووجهاتها العالمية، فيما تستقبل "بوليفارد سيتي" زوارها بفعاليات ومحتوى متجدد، إلى جانب "وندر جاردن" بألعابها وأنشطتها الترفيهية. كما تشمل مناطق الموسم "ذا جروفز" و"سوق المزارعين"، ومعرض "أنا عربية" في منطقة "فيا رياض".</p> <p>ويواصل موسم الرياض تقديم فعالياته تحت شعار "Big Time"، عبر برنامج يجمع الرياضة والترفيه والفنون والتجارب العائلية، مستقطبًا الزوار من داخل المملكة وخارجها.</p> <p><strong>المصدر:</strong> <a href="https://www.spa.gov.sa/N2686610" target="_blank">وكالة الأنباء السعودية (واس)</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98275491-68500749.jpg?v=1791225217"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98275491-68500749.jpg?v=1791225217','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/98275491/riyadh-season-2026-starts-october-21',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (98150965,'افتتاح "مستشفى البحر الأحمر" بالشراكة مع مجموعة الدكتور سليمان الحبيب','البحر الأحمر الدولية','2026-09-25T12:14:00.000Z','البحر الأحمر الدولية ومجموعة الدكتور سليمان الحبيب تفتتحان مستشفى البحر الأحمر لخدمة سكان الوجهة وموظفيها وزوارها بخدمات طوارئ وعيادات تخصصية.','<div class="texte" > <p>دشّنت "البحر الأحمر الدولية" بالشراكة مع مجموعة الدكتور سليمان الحبيب للخدمات الطبية "مستشفى البحر الأحمر" في 17 سبتمبر 2026، ليقدّم الرعاية الصحية لموظفي الوجهة وسكانها والمجتمعات المحلية المحيطة وزوارها.</p> <p>ويقدّم المستشفى، الذي تشغّله مجموعة الدكتور سليمان الحبيب، خدمات الطوارئ والتنويم والعيادات الخارجية والتخصصية والعمليات الجراحية، إلى جانب خدمات الصحة الرقمية. والمستشفى مرخّص بالكامل من وزارة الصحة، مع خطط لإنشاء ست صيدليات ومنظومة مخصصة للاستجابة للطوارئ الطبية.</p> <p>وأكد جون باغانو، الرئيس التنفيذي لمجموعة البحر الأحمر الدولية، أن المستشفى خطوة مهمة نحو بناء وجهات متكاملة يستطيع الناس زيارتها والعيش والعمل فيها بثقة. فيما أشار فيصل النصار، الرئيس التنفيذي لمجموعة الحبيب، إلى أن الشراكة تعكس طموحًا مشتركًا لتقديم نموذج رعاية صحية يليق بوجهة عالمية. كما أشاد وزير الصحة فهد الجلاجل بنمو قطاع السياحة في المملكة، واصفًا البحر الأحمر بأنه نموذج مميز لهذا التحول.</p> <p><strong>المصدر:</strong> <a href="https://sabq.org/article/cs7zo9c" target="_blank">صحيفة سبق</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98150965-68359046.jpg?v=1790353512"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98150965-68359046.jpg?v=1790353513','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/98150965/red-sea-hospital-opens-dr-sulaiman-al-habib',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (98150963,'"ديزرت روك" أول فندق في السعودية يحصل على ثلاثة مفاتيح ميشلان','البحر الأحمر الدولية','2026-09-25T12:14:00.000Z','منتجع ديزرت روك في وجهة البحر الأحمر يحصل على ثلاثة مفاتيح ميشلان وجائزة ميشلان للعمارة والتصميم 2026، ليكون أول فندق سعودي ينال هذا التصنيف.','<div class="texte" > <p>حصل منتجع "ديزرت روك" في وجهة البحر الأحمر على ثلاثة مفاتيح ميشلان، وهو أعلى تصنيف في دليل ميشلان للفنادق، ليصبح أول فندق في المملكة يحقق هذا الإنجاز، وفق ما أعلنته "البحر الأحمر الدولية" في 21 سبتمبر 2026. كما فاز المنتجع بجائزة ميشلان للعمارة والتصميم لعام 2026.</p> <p>وينضم "ديزرت روك" بهذا التصنيف إلى 155 فندقًا حول العالم حصلت على ثلاثة مفاتيح هذا العام، وهو واحد من فندقين فقط في دول الخليج ينالان هذه الدرجة. وفي الوجهة نفسها، احتفظ منتجع "شيبارة" بمفتاحي ميشلان.</p> <p>وتضم وجهة البحر الأحمر حاليًا 11 فندقًا مفتوحًا، مع ستة منتجعات إضافية تستعد للافتتاح في جزيرة شورى، في إطار تطوير واحدة من أبرز الوجهات السياحية ضمن رؤية السعودية 2030.</p> <p>ووصف جون باغانو، الرئيس التنفيذي لمجموعة البحر الأحمر الدولية، الحصول على المفاتيح الثلاثة والفوز بجائزة العمارة والتصميم بأنه لحظة فخر كبيرة للمنتجع وللمملكة.</p> <p><strong>المصدر:</strong> <a href="https://www.akhbaar24.com/%D9%85%D9%86%D9%88%D8%B9%D8%A7%D8%AA/%D8%AF%D9%8A%D8%B2%D8%B1%D8%AA-%D8%B1%D9%88%D9%83-%D8%A3%D9%88%D9%84-%D9%85%D9%86%D8%AA%D8%AC%D8%B9-%D8%B3%D8%B9%D9%88%D8%AF%D9%8A-%D9%8A%D9%86%D8%A7%D9%84-3-%D9%85%D9%81%D8%A7%D8%AA%D9%8A%D8%AD-%D9%85%D9%8A%D8%B4%D9%84%D8%A7%D9%86-770398" target="_blank">أخبار 24</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98150963-68359045.jpg?v=1790353510"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98150963-68359045.jpg?v=1790353511','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/98150963/desert-rock-first-saudi-hotel-three-michelin-keys',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (98150962,'"البحر الأحمر الدولية" تطلق "Yachting Network" لتوحيد مراسي اليخوت على ساحل البحر الأحمر','البحر الأحمر الدولية','2026-09-25T12:14:00.000Z','البحر الأحمر الدولية تطلق Yachting Network لتشغيل مرسيي أمالا وجزيرة شورى بإجمالي 278 رصيفًا لليخوت حتى 120 مترًا، ويبدأ التشغيل شتاء 2026.','<div class="texte" > <p>أعلنت "البحر الأحمر الدولية" في 23 سبتمبر 2026 إطلاق "Yachting Network"، وهي جهة تشغيل موحّدة للمراسي ونوادي اليخوت، تجمع الخدمات البحرية تحت إدارة واحدة لخدمة مجتمع اليخوت الدولي على ساحل البحر الأحمر السعودي.</p> <p>وتضم الشبكة في مرحلتها الأولى مرسى "أمالا" بـ119 رصيفًا، ومرسى "جزيرة شورى" بـ159 رصيفًا، بإجمالي 278 رصيفًا تستقبل يخوتًا يصل طولها إلى 120 مترًا. ومن المقرر أن يبدأ التشغيل في شتاء 2026، على أن تنضم مراسٍ ومواقع رسو إضافية في عام 2027.</p> <p>وتتيح الشبكة لأصحاب اليخوت عقد رسو واحدًا، وخدمات بحرية منسّقة، ووصولًا موحدًا بين الوجهات، مع الالتزام بمدونة الهيئة السعودية للبحر الأحمر ومعايير حماية البيئة البحرية بالتعاون مع معهد "كوراليوم" للأحياء البحرية. ويبعد ساحل البحر الأحمر السعودي نحو 1,300 ميل بحري عن موناكو عبر قناة السويس، ما يجعله محطة جذابة لليخوت القادمة من البحر المتوسط.</p> <p>وأوضح جون باغانو، الرئيس التنفيذي لمجموعة البحر الأحمر الدولية، أن الإطلاق يمثل محطة مهمة في ترسيخ مكانة البحر الأحمر وجهةً لمجتمع اليخوت العالمي.</p> <p><strong>المصدر:</strong> <a href="https://www.akhbaar24.com/%D8%A7%D9%82%D8%AA%D8%B5%D8%A7%D8%AF/%D8%A5%D8%B7%D9%84%D8%A7%D9%82-%D8%B4%D8%A8%D9%83%D8%A9-%D8%A7%D9%84%D9%8A%D8%AE%D9%88%D8%AA-%D9%84%D8%B1%D8%A8%D8%B7-%D9%88%D8%AC%D9%87%D8%AA%D9%8A-%D8%A3%D9%85%D8%A7%D9%84%D8%A7-%D9%88%D8%A7%D9%84%D8%A8%D8%AD%D8%B1-%D8%A7%D9%84%D8%A3%D8%AD%D9%85%D8%B1-770668" target="_blank">أخبار 24</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98150962-68357217.jpg?v=1790339426", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98150962-68357220.jpg?v=1790339446"]','https://cmsphoto.ww-cdn.com/resizeapi/c43722a9aee3768f722be60fc328442d2136324d/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/98150962/red-sea-global-launches-yachting-network',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (98150961,'ولي العهد يطلق "إكسوبوت".. أول سيارة كهربائية من علامة "سير" السعودية','وكالة الأنباء السعودية','2026-09-25T12:14:00.000Z','إطلاق إكسوبوت أول سيارة كهربائية من علامة سير السعودية بنسختي سيدان ودفع رباعي، تُصنع في مدينة الملك عبدالله الاقتصادية ضمن رؤية 2030.','<div class="texte" > <p>أطلق صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز، ولي العهد رئيس مجلس الوزراء، يوم 21 سبتمبر 2026 أول مركبة من إنتاج شركة "سير" (CEER)، أول علامة سعودية لصناعة السيارات الكهربائية. وتحمل المركبة اسم "إكسوبوت" (EXOBOT)، وتأتي بنسختين: سيدان، ومركبة رياضية متعددة الاستخدامات بدفع رباعي.</p> <p>وتُعد "إكسوبوت" الأولى ضمن سبعة طرازات تخطط الشركة لطرحها خلال السنوات الخمس المقبلة. وقد طُوّر تصميمها محليًا مستلهمًا من ثقافة المملكة وطبيعتها وفق أعلى المعايير الدولية، وتُصنَّع في المجمع الصناعي للشركة بمدينة الملك عبدالله الاقتصادية.</p> <p>ويُتوقع أن يسهم المشروع بنحو 30 مليار ريال في الناتج المحلي الإجمالي، وأن يحسّن الميزان التجاري للمملكة بنحو 80 مليار ريال بحلول عام 2034، إلى جانب توفير فرص عمل مباشرة وغير مباشرة، في خطوة تدعم مستهدفات رؤية السعودية 2030 لتوطين الصناعة وتنويع الاقتصاد.</p> <p>وأكد سمو ولي العهد أن هذا الإطلاق يعزز مساعي المملكة لبناء منظومة صناعية مستدامة ومزدهرة، وترسيخ مكانتها مركزًا عالميًا رائدًا لصناعة السيارات.</p> <p><strong>المصدر:</strong> <a href="https://www.spa.gov.sa/ar/N2681718" target="_blank">وكالة الأنباء السعودية (واس)</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/98150961-68357006.jpg?v=1790338473"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/98150961-68357006.jpg?v=1790338474','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/98150961/ceer-exobot-first-saudi-electric-car-launch',strftime('%s','now'));
