INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (89036149,'عيد الأضحى في المدينة المنورة','روح المدينة','2025-06-04T14:39:00.000Z','اكتشف فعاليات عيد الأضحى في المدينة المنورة عبر الإصدار الثاني من مجلة روح المدينة، ويضم أبرز الأنشطة والمناسبات خلال أيام العيد.','<div class="texte" > <blockquote class="twitter-tweet"> <p dir="rtl" lang="ar">مجلة <a href="https://twitter.com/hashtag/%D8%B1%D9%88%D8%AD_%D8%A7%D9%84%D9%85%D8%AF%D9%8A%D9%86%D8%A9?src=hash&amp;ref_src=twsrc%5Etfw">#روح_المدينة</a> – الإصدار الثاني بين يديك الآن<br /> عبر الرابط التالي✨<a href="https://t.co/8EgxKpeWR2">https://t.co/8EgxKpeWR2</a><br /> يسلط هذا العدد الضوء على أبرز الفعاليات السياحية لشهر مايو 2025، وتعرّف على مقترحات ملهمة للتجول في أرجاء المدينة المنورة خلال يونيو 2025، عبر إصدارنا الجديد.<br /> __<br /> روح المدينة لتكتشف… <a href="https://t.co/HDEI6Can85">pic.twitter.com/HDEI6Can85</a></p> — Visit Madinah | روح المدينة (@visitmadinahsa) <a href="https://twitter.com/visitmadinahsa/status/1929981282383212847?ref_src=twsrc%5Etfw">June 3, 2025</a></blockquote> <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script> </div>  <div class="texte" > <p><a href="https://t.co/8EgxKpeWR2">https://t.co/8EgxKpeWR2</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89036149-63010636.jpg?v=1749048075"]','https://cmsphoto.ww-cdn.com/resizeapi/7343e94fe287b3f2d03a72b0d8ae62c67c9f536a/480/','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/89036149/eid-al-adha-madinah-guide',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (89031808,'لوّن صيفك - حمل دليل فعاليات الصيف الأن','روح السعودية','2025-06-04T14:12:00.000Z','اكتشف تجارب صيفية استثنائية في السعودية، من أجواء الجبال المنعشة إلى الشواطئ الخلابة والمهرجانات الثقافية النابضة بالحياة في مختلف المناطق.','<div class="texte" > <div data-original-size="14px"> <div data-original-size="14px"> <div data-original-size="14px"> <div data-original-size="14px"> <div data-original-size="14px"> <div data-habitat="C1" data-original-size="14px"> <section data-original-size="14px" id="AboutSectionWrapperId"> <section data-original-size="14px"> <div data-original-size="16px"> <div data-original-size="16px"> <p data-original-size="16px">أجواء الجبال المنعشة بدرجات حرارة تصل إلى 24 درجة مئوية، إلى الشواطئ الخلابة والمهرجانات الثقافية النابضة بالحياة، تنتظرك في السعودية تجارب صيفية استثنائية تناسب جميع احتياجاتك. اكتشف الأجواء المعتدلة وأماكن الإقامة الفاخرة والمغامرات التي لا تُنسى في مختلف أنحاء المملكة هذا الصيف.</p> <div>&nbsp;</div> </div> </div> </section> </section> </div> </div> </div> </div> </div> </div> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/dqRcWlXvm5c?si=1EN6A0Synni82SJF&gbyoutube=dqRcWlXvm5c" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>  <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="saudi-calendar-ar" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2752130/"> saudi-calendar-ar </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/89031808-63001141.jpg?v=1749047180"]','https://cmsphoto.ww-cdn.com/resizeapi/511d311b274a1022b5adaad791b8ac1c1a445ab4/480/','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/89031808/saudi-summer-events-guide',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (88635077,'الأحلام تحت التنفيذ أبريل 2025','مشاريع السعودية','2025-05-18T16:20:00.000Z','','<iframe width="560" height="315" src="https://www.youtube.com/embed/lYuWMz3b4PA?si=-2yrt7GQ7JYGK7DV&gbyoutube=lYuWMz3b4PA" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>  <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="الأحلام تحت التنفيذ أبريل 2025" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2745113/"> الأحلام تحت التنفيذ أبريل 2025 </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88635077-62753652.jpg?v=1747585229"]','https://cmsphoto.ww-cdn.com/resizeapi/eb10e5b7189774cd09f3049217fdfc7365aae615/480/','[]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/88635077/alahlam-tht-altnfyth-abryl-2025',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (88155363,'الأحلام تحت التنفيذ مارس 2025','مشاريع السعودية','2025-04-26T09:07:00.000Z','نيوم تواصل تسارع أعمال التطوير في مناطقها المختلفة، ووجهة البحر الأحمر تطلق مشاريعها السكنية، وحديقة الملك سلمان تبدأ تنفيذ أولى مناطقها الاستثمارية، والدرعية تكشف عن تطورات جديدة','<div class="texte" > <p>نيوم تواصل تسارع أعمال التطوير في مناطقها المختلفة، ووجهة البحر الأحمر تطلق مشاريعها السكنية، وحديقة الملك سلمان تبدأ تنفيذ أولى مناطقها الاستثمارية، والدرعية تكشف عن تطورات جديدة</p> <div>&nbsp;</div> <div>&nbsp;</div> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/iPsjbx68eKc?si=g4kitwH4fMb--J21&gbyoutube=iPsjbx68eKc" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>  <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="تقرير الأحلام شهر مارس" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2736316/"> تقرير الأحلام شهر مارس </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88155363-62436843.jpg?v=1745658534"]','https://cmsphoto.ww-cdn.com/resizeapi/35c73fb6986d0d62675053c731027e24f59e0006/480/','[]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/88155363/alahlam-tht-altnfyth-mars-2025',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (88148499,'التقرير السنوي لرؤية السعودية 2030 لعام 2024م','رؤية السعودية  2030','2025-04-25T21:45:00.000Z','التقرير السنوي لرؤية السعودية 2030 لعام 2024 يستعرض أبرز الإنجازات في عامها التاسع، مع تسارع التنفيذ وتحقيق الأهداف الاستراتيجية في مختلف القطاعات، مستندة إلى مكامن القوة التي تتميز بها المملكة.','<div class="texte" > <p>تقترب رؤية السعودية 2030 في عامها التاسع منذ إطلاقها وهي تقترب من الوصول إلى أهدافها الاستراتيجية، أكثر من أي وقت مضى؛ حيث يزدهر الاقتصاد ويتنوع، في مجتمع حيوي، ووطن طموحه عنان السماء. ‎وقد استندت الرؤية في رحلتها على مكامن القوة التي تتميز بها المملكة؛ إذ أنها قلب العالمين العربي والإسلامي، وتمتلك قوة استثمارية واقتصادية فاعلة، وموقعاً جغرافياً استراتيجياً يُعد محوراً لوجستياً وتجارياً عالمياً. وقد استثمرت المملكة هذه الأركان الثلاثة بحكمة؛ لاستكمال مسيرتها التنموية التي تمتد لعقود، ولتواصل طريقها في خدمة ضيوف الرحمن بقيم أصيلة، وتحقيق تنمية شاملة توفر فرص العمل والاستثمار، مع استغلال موقعها الاستراتيجي لتصبح مركزاً عالمياً للفرص والازدهار.</p> </div>   <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="annual-report-2025" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2736241/"> annual-report-2025 </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88148499-62430697.jpg?v=1745617563", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88148499-62430698.jpg?v=1745617575"]','https://cmsphoto.ww-cdn.com/superstatic/2892882/art/large_16_9/88148499-62430697.jpg?v=1745617680','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/88148499/vision2030-annual-report-2024',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (88100285,'"ناموس" يختار وجهة "أمالا" في السعودية لافتتاح أول منتجع له خارج اليونان','البحر الأحمر الدولية','2025-04-23T19:13:00.000Z','أعلنت البحر الأحمر الدولية عن افتتاح منتجع ناموس أمالا خلال عام 2025، ليكون أول مشروع فندقي لمجموعة ناموس اليونانية خارج بلادها، ومعيارًا جديدًا للفخامة في وجهة البحر الأحمر.','<div class="texte" > <p><span>الرياض، 23 أبريل 2025:&nbsp;</span>أعلنت "البحر الأحمر الدولية"، الشركة الرائدة في تطوير أحد أكثر المشاريع السياحية المتجددة طموحًا في العالم، عن افتتاح منتجع "ناموس أمالا" خلال هذا العام، والذي يمثل معيارًا جديدًا للفخامة في منطقة البحر الأحمر. وتمثل هذه الشراكة أول مشروع فندقي لمجموعة فنادق ومنتجعات "ناموس" خارج اليونان، حيث تعكس تصاميمها الأنيقة وضيافتها العالمية، لتقدِّم تجربة فريدة من نوعها في السعودية.</p> <p>ويقع منتجع "ناموس أمالا" في منطقة "تربل باي" بوجهة "أمالا"، ويقدم للضيوف إطلالات ساحرة على البحر الأحمر وخليج الحجاز. ومن المتوقع أن يستقبل المنتجع أول زواره خلال هذا العام، حيث يعد بتجربة استثنائية تمتاز بالتصميم الراقي، والمرافق الفاخرة، والمزيج المتناغم بين التصاميم المستوحاة من ميكونوس ومنطقة غرب السعودية.</p> <p>ويُعد منتجع "ناموس أمالا" المنتجع الثاني ضمن محفظة فنادق ومنتجعات "ناموس"، وهو جزء من "أدمو لايف ستايل"، المشروع المشترك بين مجموعة” ألفا ظبي القابضة" و"منتروك إنترناشونال". ويستمر التوسع العالمي للعلامة التجارية الشهيرة "ناموس"، بما يتماشى تمامًا مع رؤية "أدمو" في إعادة تعريف حدود تجارب الطهي الفاخرة وأنماط الحياة الاستثنائية.</p> </div>  <div class="texte" > <blockquote>"يمثل منتجع "ناموس أمالا" علامة فارقة لكل من "البحر الأحمر الدولية" و"أدمو لايف ستايل القابضة"، حيث يجسد هذا التعاون تناغمًا بين التصميم العصري والفخامة العالمية. ونحن فخورون بتقديم هذا المنتجع الاستثنائي كأحد المنتجعات الثمانية التي ستُفتتح في المرحلة الأولى من "أمالا" خلال الأشهر القادمة." جون باغانو، الرئيس التنفيذي لـ"البحر الأحمر الدولية"</blockquote> </div>    <div class="texte" > <p>وقال سانجي ناندي، الرئيس التنفيذي لشركة "أدمو لايف ستايل القابضة": "يعد منتجع "ناموس أمالا" نقطة فارقة في توسع "أدمو" العالمي في قطاع الفنادق. كعلامة تجارية ترتبط بالفخامة النابضة بالحياة والتجارب الاستثنائية، فإن افتتاح المنتجع في واحدة من أكثر وجهات الحياة الفاخرة في العالم يتناسب تمامًا مع علامة "ناموس" ويعزز التزام "أدمو" بتوسيع محفظتها الدولية في قطاع الضيافة الفاخرة".</p> <p><br /> بدوره، قال بيتروس ستاثيس، رئيس مجلس إدارة "ناموس وورلد" ونائب رئيس مجلس إدارة "أدمو لايف ستايل القابضة"، قائلاً:<br /> "يمثل افتتاح منتجع "ناموس أمالا" محطة فارقة في مسيرة علامة "ناموس"، إذ نقدم تجربة منتجع متكاملة وشاملة في واحدة من أكثر الوجهات السياحية الفاخرة ترقباً على مستوى العالم. لدينا ثقة كاملة في الرؤية الطموحة لقيادة السعودية، التي تشاركنا الالتزام بالتميّز وتعيد رسم ملامح قطاع الضيافة العالمي للعقود قادمة. نشعر بالفخر لكوننا جزءاً من هذه الرحلة الاستثنائية، ونتطلع إلى ما ينتظرنا في البحر الأحمر"</p> </div>    <div class="texte" > <p>ويتميز المنتجع الفاخر بـ 110 غرفة مطلة على البحر، إضافة إلى 20 وحدة سكنية تحمل علامة "ناموس" تتمتع هذه الوحدات بإطلالات خلابة على مارينا "أمالا" و"كوراليوم" مركز الحياة البحرية. كما يضم المنتجع سبا فاخر يقدم تجربة استرخاء متجددة، وصالة رياضية مجهزة بأحدث التقنيات لمحبي اللياقة البدنية والاستشفاء، وناديًا للأطفال يقدم تجارب مثالية للعائلات. ويتضمن المنتجع أيضًا 4 مطاعم استثنائية؛ من بينها بار "هورايزون" الذي يقدم إطلالات ساحرة على غروب الشمس في البحر الأحمر، ومطعم "ناموس" الشهير، ومطعم "نالو" الذي يقدم مزيجًا فريدًا من النكهات اللاتينية والآسيوية في تجربة طعام طوال اليوم، بالإضافة إلى أحواض سباحة متدرجة تنساب نحو الشاطئ الرئيسي للمنتجع. كما يضم المنتجع مطعم أمنية، وهو مطعم عالمي يقدم قائمة طعام متجددة تحت إشراف طهاة وعلامات عالمية بارزة.</p> <p>وصُمم المنتجع بعناية ليجمع بين الجماليات اليونانية والسعودية، حيث إن تصميم الواجهة الخارجية، المصممة من قِبل شركة "فوستر وشركاه،" مستوحى من العمارة الحجازية التقليدية، في حين تعكس التصاميم الداخلية، التي أبدعها المصمم "لازارو روزا فيولان ستوديو" الإسباني وشركة "إيلاستيك أركيتكتس" اليونانية، أناقة الطراز السيكلاديكي في ميكونوس. وتشمل التفاصيل المميزة الأرضيات التيرازو، والجدران المزخرفة، والأقواس التقليدية، بينما تتناغم لوحة الألوان التي تجمع بين الأزرق الفاتح، الأبيض، والذهبي، مما يخلق أجواء البحر الأبيض المتوسط العصرية.</p> </div>    <div class="texte" > <p>ولطالما اشتهرت مطاعم "ناموس" باختيارها لأروع المواقع على الشواطئ، حيث تمتزج الفخامة بالجمال الطبيعي. في "أمالا"، لم يكن الأمر مختلفًا، إذ يقع مطعم "ناموس" في قلب جزيرة الحجاز الخاصة على سواحل المنتجع، ليكون جزءًا من هذا التناغم الفريد بين البحر الأحمر والسماء. يقدم المطعم إطلالات استثنائية على غروب شمس البحر الأحمر، ويضمن للزوار خصوصية تامة من خلال أكواخه المريحة. يمكن الوصول إليه عبر القارب من مرسى "أمالا"، مما يضيف لمسة من الحصرية والتميز، إذ يقتصر دخوله على ضيوف منتجعات "أمالا" فقط. من أبرز معالمه المسبح البانورامي الذي يبدو وكأنه يطفو على البحر الأحمر، ليمنح الزوار مشهدًا ساحرًا للغروب لا مثيل له.</p> </div>    <div class="texte" > <p>ولطالما اشتهرت مطاعم "ناموس" باختيارها لأروع المواقع على الشواطئ، حيث تمتزج الفخامة بالجمال الطبيعي. في "أمالا"، لم يكن الأمر مختلفًا، إذ يقع مطعم "ناموس" في قلب جزيرة الحجاز الخاصة على سواحل المنتجع، ليكون جزءًا من هذا التناغم الفريد بين البحر الأحمر والسماء. يقدم المطعم إطلالات استثنائية على غروب شمس البحر الأحمر، ويضمن للزوار خصوصية تامة من خلال أكواخه المريحة. يمكن الوصول إليه عبر القارب من مرسى "أمالا"، مما يضيف لمسة من الحصرية والتميز، إذ يقتصر دخوله على ضيوف منتجعات "أمالا" فقط. من أبرز معالمه المسبح البانورامي الذي يبدو وكأنه يطفو على البحر الأحمر، ليمنح الزوار مشهدًا ساحرًا للغروب لا مثيل له.<br /> &nbsp;<br /> يستمر العمل في المخطط الرئيسي الأول لوجهة "أمالا،" التي تركز على تطوير "تربل باي،" ومن المتوقع أن يستقبل المنتجع أول ضيوفه في 2025 عبر 1,400 غرفة موزعة على 8 منتجعات. وفي المستقبل، سيضم "تربل باي" 12 منتجعًا و3 مجمعات سكنية.<br /> &nbsp;<br /> وبمجرد اكتمالها، ستضم "أمالا" نحو 4,000 غرفة فندقية في 30 فندقًا، وحوالي 1,200 فيلا سكنية وشقق ووحدات عقارية فاخرة، كما ستشمل وجهة "أمالا" مارينا حيوية تخدم مجتمع اليخوت العالمي، بالإضافة إلى مجموعة واسعة من متاجر التجزئة الراقية والمطاعم الفاخرة ومراكز الاستجمام والمرافق الترفيهية.</p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88100285-62398628.jpg?v=1745435781", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88100285-62398622.jpg?v=1745435714", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88100285-62398632.jpg?v=1745435818", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88100285-62398636.jpg?v=1745435878", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/88100285-62398643.jpg?v=1745435933"]','https://cmsphoto.ww-cdn.com/resizeapi/79e31cd2c3f3ad6a0647d9e254113a5c65dc66e2/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/88100285/namos-resorts-amaala-first-location-outside-greece',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (87954462,'"البحر الأحمر الدولية" تكشف عن "لاحق".. أول جزيرة سكنية خاصة للعيش برفاهية في السعودية','البحر الأحمر الدولية','2025-04-16T14:21:00.000Z','أعلنت البحر الأحمر الدولية عن إطلاق جزيرة لاحق، أول جزيرة سكنية خاصة ضمن وجهة البحر الأحمر، لتقدّم تجربة فريدة لنمط الحياة الفاخر على الجزر في السعودية.','<div class="texte" > <p>الرياض، 15 أبريل 2025:&nbsp;أعلنت شركة "البحر الأحمر الدولية"، الرائدة في تطوير أبرز المشاريع السياحية المتجددة في العالم، عن إطلاق جزيرة "لاحق"، أول جزيرة سكنية خاصة ضمن وجهة "البحر الأحمر"، تقدم تجربة فريدة لنمط الحياة الفاخر على الجزر في السعودية.</p> <p>وتمثل جزيرة "لاحق" أول مشروع سكني يتم الكشف عنه بعد اكتمال المرحلة الأولى من وجهة "البحر الأحمر"، والتي استقبلت أول ضيوفها في عام 2023، وشهدت افتتاح 5 منتجعات. ويجري حالياً استكمال بناء 11 منتجعًا إضافيًا على جزيرة "شورى"، إلى جانب تشغيل مطار "البحر الأحمر الدولي" برحلات داخلية ودولية منتظمة.</p> <p>ومن المقرر افتتاح جزيرة "لاحق" في عام 2028، لتكون أول مشروع في الوجهة يُركز على تملّك الوحدات السكنية، ويعزز التجربة بمرافق ضيافة وخدمات استثنائية، تواكب أعلى معايير الفخامة والخصوصية.</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/ovdCqSsVbYk?si=e9FvsxMpeAKdksKJ&gbyoutube=ovdCqSsVbYk" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe> <div class="texte" > <blockquote>سيحظى سكان جزيرة "لاحق"، سواء من الزوّار أو المقيمين الذين اختاروا امتلاك منازلهم في وجهة "البحر الأحمر"، بأسلوب حياة راقٍ في جزيرة خاصة، ضمن مجتمع نابض يعزز الروابط الإنسانية ويجمع الأفراد على المدى الطويل". جون باغانو، الرئيس التنفيذي لشركة "البحر الأحمر الدولية"</blockquote> </div>  <div class="texte" > <p>وأضاف باغانو: "لقد أثبتنا مكانتنا كمطور رائد للوجهات الفاخرة والمتجددة، لكن طموحاتنا تمتد لما هو أبعد. فنحن في "البحر الأحمر الدولية" نعد مطورًا ومشغّلًا عقاريًا متكاملًا، ونعمل على تطوير مجتمعات سكنية خاصة تُسهم في تحقيق رؤية السعودية 2030 بجعل السعودية وجهة عالمية للعيش والعمل والسفر، ودعم التنوع الاقتصادي وخلق فرص وظيفية نوعية".</p> <p>وتقع جزيرة "لاحق" ضمن أرخبيل يضم 92 جزيرة بكر على الساحل الغربي للمملكة، محاط بأحد أكبر الحيود المرجانية في العالم، والذي يُعد موطنًا لأكثر من 2000 نوع من الأسماك النادرة والفريدة، التي يصعب العثور على نظير لها في بحار ومحيطات أخرى.</p> <p>وقد وقع اختيار "البحر الأحمر الدولية" على جزيرة "لاحق" بوصفها جوهرة الأرخبيل، لتكون نموذجًا لمجتمع فاخر على جزيرة خاصة، تمتد على مساحة 400 هكتار (4,000,000 متر مربع)، وتحتضن شواطئ رملية بيضاء، وشعبًا مرجانية نابضة بالحياة، ومياهًا فيروزية صافية تُعد من الأجمل في العالم.</p> </div>    <div class="texte" > <p>فرص جديدة للتملّك في وجهة "البحر الأحمر"</p> <p>تستلهم الوحدات السكنية الخاصة في جزيرة "لاحق" تصميمها من تناغم الطبيعة المحيطة، من الأرض والبحر والسماء والنباتات المحلية. ويُستخدم الخشب الطبيعي في بناء المظلات وتزيين الشرفات والحدائق وساحات الفناء الخارجية الأنيقة، ليعكس روح الجزيرة ويعزز الشعور بالانسجام مع البيئة.</p> <p>وتقدّم جزيرة "لاحق" مجموعة متنوعة من المرافق الترفيهية والأنشطة الحيوية التي تلبي احتياجات المقيمين والزوار على حد سواء. ويضم المرسى 115 رصيفًا لليخوت، إلى جانب مراكز تعليم الإبحار والرياضات المائية. كما تشمل الجزيرة ناديًا للتنس، ومركزًا للياقة البدنية، وملاعب رياضية، وملعب جولف خلاب مكوّن من 18 حفرة، إضافةً إلى منتزه مصمم بعناية لعشاق الأنشطة البرية.</p> <p>ويشكّل السوق في الجزيرة تجربة نابضة بالحياة، تمتزج فيها الأصوات والمشاهد والروائح العبقة، ويقدّم باقة مختارة بعناية من المنتجات والمستلزمات التي تلائم أسلوب الحياة الفاخر.</p> <p>كما يمكن للمقيمين والضيوف الاستمتاع بمجموعة من النوادي الشاطئية وتجارب تناول الطعام المتنوعة، التي تتراوح بين الأجواء الهادئة والبسيطة إلى الأماكن الراقية، مع التركيز على المكونات الطازجة وأعلى معايير الطهي المحلي والعالمي.</p> <p>وتضم الجزيرة منتجعين فاخرين، يُعنى أحدهما بتقديم تجارب الاستشفاء والاستجمام، بينما يوفر الآخر أسلوب حياة نشطًا وحيويًا، يستهدف المسافرين ذوي روح المغامرة والاكتشاف.</p> </div>    <div class="texte" > <p>تصميم مستدام</p> <p>تولت شركة "فوستر وشركاه"، إحدى أبرز شركات العمارة في العالم، تصميم جزيرة "لاحق" ضمن مفهوم "فور إيفر غاردن"، الذي يركّز على استخدام الغطاء النباتي والمساحات الخضراء بشكل وافر لخلق بيئة حيوية ومستدامة.</p> <p>ويُعد "ذا رينغ" العنصر المعماري الأيقوني في التصميم، وهو هيكل دائري بقطر 800 متر، يضم شققًا ومنتجعات فاخرة ومرافق للتجزئة، ويحيط به شاطئ رملي أبيض يطل على بحيرة الجزيرة.</p> <p>وقد علّق نورمان فوستر، المؤسس والرئيس التنفيذي لشركة "فوستر وشركاه"، قائلًا: "تنطلق رؤيتنا من تقدير عميق للجمال الطبيعي الخلاب لجزيرة "لاحق". حيث نستقبل المقيمين والضيوف في بيئة مفعمة بالهدوء وتُغني الحواس، وتوفر إطلالات بانورامية خلابة على الطبيعة المحيطة".</p> </div>    <div class="texte" > <p>السياحة المتجددة</p> <p>أصبح بإمكان الزوار والمقيمين في وجهة "البحر الأحمر" استكشاف روعة طبيعتها الفريدة بفضل التزام "البحر الأحمر الدولية" الراسخ بمفهوم السياحة المتجددة، وهو مصطلح صاغته الشركة لوصف الوجهات التي لا تكتفي بالحفاظ على بيئتها، بل تعمل أيضًا على تحسينها وتعزيزها.</p> <p>وقد التزمت "البحر الأحمر الدولية" بزراعة 50 مليون شجرة مانغروف، وتحسين جودة موائلها، إلى جانب حماية وتجديد شُعب البحر الأحمر المرجانية وما يتصل بها من نظم بيئية بحرية.</p> <p>وعند اكتمال وجهة "البحر الأحمر"، ستكون أكبر وجهة في العالم تعمل بالكهرباء المتجددة بنسبة 100%، بما يشمل جميع مرافقها ومنتجعاتها، بما فيها جزيرة "لاحق".</p> <p>وتسير أعمال تطوير الوجهة بخطى متسارعة، حيث من المتوقع الانتهاء من تشغيل جميع منتجعات المرحلة الأولى البالغ عددها 16 منتجعًا خلال عام 2025. وبحلول عام 2030، ستضم وجهة "البحر الأحمر" 50 منتجعًا توفر ما يصل إلى 8,000 غرفة فندقية، وأكثر من 1,000 وحدة سكنية موزعة على 22 جزيرة و6 مواقع داخلية. كما سيكون مطار "البحر الأحمر الدولي" البوابة الرئيسية للمقيمين والزوار، حيث يوفر نقطة وصول سريعة ومريحة إلى منازلهم.</p> <p>تمثل "لاحق" مشروعا أساسيًا في محفظة "البحر الأحمر الدولية"، بإدارة شركة "البحر الأحمر ريزيدنسز". للحصول على المزيد من المعلومات حول جميع المشاريع التي تطورها "البحر الأحمر ريزيدنسز"، أو لتسجيل اهتمامكم، يرجى زيارة الموقع الإلكتروني:&nbsp;<a href="https://www.redseaglobal.com/ar/the-residences">https://www.redseaglobal.com/ar/the-residences</a></p> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87954462-62322405.jpg?v=1744813374", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87954462-62322438.jpg?v=1744813444", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87954462-62322448.jpg?v=1744813484", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87954462-62322461.jpg?v=1744813541"]','https://cmsphoto.ww-cdn.com/resizeapi/ed832fb3e86932a07ced8d6a8adaf49d87415c59/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/87954462/red-sea-international-reveals-laheq-private-residential-island',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (87585575,'‫الأحلام تحت التنفيذ‬ | يناير -  فبراير 2025','مشاريع السعودية','2025-03-31T21:05:00.000Z','تفاصيل أكثر من 40 إنجازًا لمشاريع رؤية السعودية 2030 الكبرى خلال شهري يناير وفبراير 2025 ضمن تقرير الأحلام تحت التنفيذ الشهري لمتابعة تقدم المشاريع العملاقة.','<iframe width="560" height="315" src="https://www.youtube.com/embed/8B2z4f6hVqo?si=HZi18ThJKfMipit7&gbyoutube=8B2z4f6hVqo" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe> <iframe width="560" height="315" src="https://www.youtube.com/embed/ITgv1AQJb20?si=_f73T9UYi26MEv8i&gbyoutube=ITgv1AQJb20" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe> <div class="texte" > <p>تفاصيل أكثر من 40 منجز للمشاريع الكبرى 🏗️<br /> ‏- جديد الوجهات والمشاريع المكتملة📌<br /> ‏- تطورات الصناعات الوطنية الرائدة 🏭<br /> <br /> ‏ومنجزات أكثر حققتها السعودية خلال شهر فبراير الماضي، نرصدها لكم في تقرير ⁧‫الأحلام تحت التنفيذ‬⁩ 🇸🇦<br /> <br /> ‏تصفح التقرير الآن:</p> </div>   <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="تقرير الاحلام تحت التنفيذ" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2724309/"> تقرير الاحلام تحت التنفيذ </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/87585575-62113021.jpg?v=1743455482"]','https://cmsphoto.ww-cdn.com/resizeapi/85221e55c72177e5b508e5c9ad0bcbb93564d1e6/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/87585575/vision2030-monthly-progress-report-january-february-2025',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (85916809,'الأحلام تحت التنفيذ‬ | ديسمبر 2024','مشاريع السعودية','2025-01-26T16:16:00.000Z','تقرير الأحلام تحت التنفيذ الشهري يرصد أبرز إنجازات مشاريع رؤية السعودية 2030 الكبرى خلال شهر ديسمبر 2024، ومستجدات المشاريع العملاقة في مختلف مناطق المملكة.','<iframe width="560" height="315" src="https://www.youtube.com/embed/Nnm0kSWO9uw?si=Br0_JTANs1PU3L-H&gbyoutube=Nnm0kSWO9uw" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>  <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="الأحلام تحت التنفيذ | شهر ديسمبر" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2692375/"> الأحلام تحت التنفيذ | شهر ديسمبر </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/85916809-61172094.jpg?v=1737908496"]','https://cmsphoto.ww-cdn.com/resizeapi/75df425a12f71e5ad2fbbd53859100050b231547/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/85916809/vision2030-monthly-progress-report-december-2024',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (85055699,'الأحلام تحت التنفيذ نوفمبر ٢٠٢٤','مشاريع السعودية','2024-12-19T20:22:00.000Z','تدشين قطار الرياض، وسلسلة تدشينات وافتتاحات لمشاريع في الدرعية، وتقدم كبير في تنفيذ جزيرة شورى بوجهة البحر الأحمر، وتعيين 3 شركاء عالميين لتطوير مشروع ذا لاين ضمن تقرير الأحلام تحت التنفيذ الشهري.','<div class="texte" > <p>تدشين قطار الرياض، والكشف عن سلسلة تدشينات وافتتاحات لمشاريع في الدرعية، وقطع شوط كبير من أعمال تنفيذ جزيرة شورى في وجهة البحر الأحمر، وتعيين 3 شركاء عالميين لتطوير مشروع ذا لاين</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/t2zcaHaTEoc?si=xMKz-lAdIQpuG71q&gbyoutube=t2zcaHaTEoc" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>  <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="الأحلام تحت التنفيذ نوفمبر ٢٠٢٤" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2680388/"> الأحلام تحت التنفيذ نوفمبر ٢٠٢٤ </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/85055699-60688303.jpg?v=1734644540"]','https://cmsphoto.ww-cdn.com/resizeapi/fa678223d2499573ed6bc42bd8c9f7bb91d4f2b2/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/85055699/vision2030-monthly-progress-report-november-2024',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84882180,'الدليل الإرشادي لمعرض جدة للكتاب ٢٠٢٤','وزارة الثقافة','2024-12-11T12:59:00.000Z','استكشف أبرز فعاليات البرنامج الثقافي وجميع دور النشر المشاركة في معرض جدة للكتاب 2024 من خلال هذا الدليل الإرشادي الشامل.','<div class="texte" > <blockquote class="twitter-tweet"> <p dir="rtl" lang="ar">استكشف أبرز فعاليات البرنامج الثقافي، وجميع دُور النشر المشاركة في <a href="https://twitter.com/hashtag/%D9%85%D8%B9%D8%B1%D8%B6_%D8%AC%D8%AF%D8%A9_%D9%84%D9%84%D9%83%D8%AA%D8%A7%D8%A8_2024?src=hash&amp;ref_src=twsrc%5Etfw">#معرض_جدة_للكتاب_2024</a> 👇<br /> <br /> تجربة ثقافية لا تٌفوّت!<a href="https://twitter.com/hashtag/%D8%AC%D8%AF%D8%A9_%D8%AA%D9%82%D8%B1%D8%A3?src=hash&amp;ref_src=twsrc%5Etfw">#جدة_تقرأ</a><a href="https://twitter.com/hashtag/%D9%87%D9%8A%D8%A6%D8%A9_%D8%A7%D9%84%D8%A3%D8%AF%D8%A8_%D9%88%D8%A7%D9%84%D9%86%D8%B4%D8%B1_%D9%88%D8%A7%D9%84%D8%AA%D8%B1%D8%AC%D9%85%D8%A9?src=hash&amp;ref_src=twsrc%5Etfw">#هيئة_الأدب_والنشر_والترجمة</a></p> — معارض الكتاب في السعودية (@SaudiBookFairs) <a href="https://twitter.com/SaudiBookFairs/status/1866777442813349953?ref_src=twsrc%5Etfw">December 11, 2024</a></blockquote> <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script> </div>  <div class="texte" > <blockquote class="twitter-tweet" data-media-max-width="560"> <p dir="rtl" lang="ar">لوصول أسرع إلى <a href="https://twitter.com/hashtag/%D9%85%D8%B9%D8%B1%D8%B6_%D8%AC%D8%AF%D8%A9_%D9%84%D9%84%D9%83%D8%AA%D8%A7%D8%A8_2024?src=hash&amp;ref_src=twsrc%5Etfw">#معرض_جدة_للكتاب_2024</a>، اطّلع على إرشادات الموقع.<br /> <br /> نتطلع لزيارتكم في جدة سوبر دوم 📍<br /> من 12 إلى 21 ديسمبر 🗓️<br /> <br /> احجز تذكرتك الآن مجاناً 👇:<a href="https://t.co/c5F35Cosof">https://t.co/c5F35Cosof</a><a href="https://twitter.com/hashtag/%D8%AC%D8%AF%D8%A9_%D8%AA%D9%82%D8%B1%D8%A3?src=hash&amp;ref_src=twsrc%5Etfw">#جدة_تقرأ</a><a href="https://twitter.com/hashtag/%D9%87%D9%8A%D8%A6%D8%A9_%D8%A7%D9%84%D8%A3%D8%AF%D8%A8_%D9%88%D8%A7%D9%84%D9%86%D8%B4%D8%B1_%D9%88%D8%A7%D9%84%D8%AA%D8%B1%D8%AC%D9%85%D8%A9?src=hash&amp;ref_src=twsrc%5Etfw">#هيئة_الأدب_والنشر_والترجمة</a> <a href="https://t.co/bxNcN5Ys30">pic.twitter.com/bxNcN5Ys30</a></p> — معارض الكتاب في السعودية (@SaudiBookFairs) <a href="https://twitter.com/SaudiBookFairs/status/1866571315966251241?ref_src=twsrc%5Etfw">December 10, 2024</a></blockquote> <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script> </div>   <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="الدليل الارشادي لمعرض جدة للكتاب 2024" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2676859/"> الدليل الارشادي لمعرض جدة للكتاب 2024 </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84882180-60581178.jpg?v=1733923196"]','https://cmsphoto.ww-cdn.com/resizeapi/fc234fee8fee528d80b0fe27c3defdce3e8edda5/480/','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/84882180/jeddah-book-fair-2024-guide',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84858347,'"ديزرت روك" يفتح أبوابه.. تحفة معمارية بين الجبال من "البحر الأحمر الدولية"','البحر الأحمر الدولية','2024-12-10T13:01:00.000Z','أعلنت البحر الأحمر الدولية عن افتتاح منتجع ديزرت روك الجبلي في وجهة البحر الأحمر، وهو ثالث منشآتها الفندقية التي تديرها الشركة بنفسها، ويجمع بين الطراز المعماري الفريد والطبيعة الجبلية الخلابة.','<iframe width="560" height="315" src="https://www.youtube.com/embed/JTB5_TQSYkI?si=-hlQddT-GxYrF7Sr&gbyoutube=JTB5_TQSYkI" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe> <div class="texte" > <p>الرياض – 10 ديسمبر:&nbsp;أعلنت "البحر الأحمر الدولية"، المطوّرة لأكثر المشاريع السياحية المتجددة طموحاً في العالم، عن افتتاح منتجع "ديزرت روك" الجبلي في وجهة "البحر الأحمر"، والذي يُعد ثالث منشآتها الفندقية التي تُديرها الشركة بنفسها.</p> <p>ويقع "ديزرت روك" في قلب الصحراء، حيث تلتقي الجبال بالرمال في مشهد يخطف الأنفاس. ويمتد المنتجع على مساحة 30,000 متر مربع، ويتميز بتصميم معماري فريد يندمج بسلاسة مع التكوينات الصخرية التي تميِّز المنطقة. ويبعد 20 دقيقة فقط عن مطار "البحر الأحمر الدولي"، مما يوفر للزوار سهولة الوصول وراحة البال. ويوفر "ديزرت روك" للضيوف ملاذًا مثاليًا يجمع بين المغامرة والهدوء، مع خيارات إقامة متنوعة تشمل فللًا مزودة بمسابح خاصة، وأجنحة فاخرة، ومرافق حصرية، تضمن تجربة استثنائية لكل زائر.</p> </div>  <div class="texte" > <blockquote>"يسرنا أن نرحب بالزوار في "ديزرت روك"، الذي يُعد إضافة فريدة إلى محفظتنا الفندقية. تم تصميم هذا المنتجع ليوفر تجربة غامرة تجمع بين الفخامة والطبيعة، مما يجعله وجهة لا تُنسى". وأضاف باغانو: "سواء كنت ترغب في استكشاف الصحراء والجبال مع فريق المغامرات "أكون"، أو الاسترخاء في خصوصية تامة، أو الاستمتاع بتجارب طعام عالمية المستوى، فإن "ديزرت روك" يقدم تجربة فريدة تناسب كل ضيف". جون باغانو، الرئيس التنفيذي لشركة "البحر الأحمر الدولية".</blockquote> </div>    <div class="texte" > <p>ويوفر "ديزرت روك" خيارات إقامة متنوعة تناسب جميع الأذواق، بدءًا من فلل الوادي الواسعة المثالية للعائلات، والتي تتميز بتصميمها المستوحى من الصحراء ومسابحها الخاصة، إلى الفلل المعلقة على الحافة الصخرية التي توفر إطلالات بانورامية خلابة، وأجنحة الكهف الجبلي المُدمجة في الصخور والتي توفر الخصوصية التامة، والفلل المحفورة في الجبل بموقعها الفريد وإطلالاتها الساحرة، وصولًا إلى الفيلا الملكية الفاخرة المكونة من ثلاث غرف نوم والمثالية للمناسبات الخاصة.</p> </div>    <div class="texte" > <p>ويُقدم "ديزرت روك" تجارب طعام استثنائية تناسب جميع الأذواق، من "نيرا" الذي يقدم أشهى المأكولات المطهوة على الحطب بقيادة الشيف الشهير عثمان سيزين الذي حازت مطاعمه على نجوم ميشلان عام 2024، إلى "ميكا" البار العصري الذي يقدم كوكتيلات غير كحولية وأطباقًا صغيرة في أجواء هادئة، وبازلت" الذي يقدم وجبات إفطار وأطباقًا هندية حديثة مع عروض ترفيهية، و"وادي" البار الذي يقع بجانب المسبح ويقدم مأكولات مستوحاة من المطبخ البيروفي مع عروض دي جي، و"ذا أوبزرفاتوري" اللاونج الراقي الذي يوفر إطلالات على النجوم مع كوكتيلات غير كحولية وحلويات. كما يتميز منتجع "ديزرت روك" بتجربة استجمام متكاملة مع غرف علاجية، وحمام تقليدي، ومرافق علاجية بالمياه، ومساحة علاجية خارجية، وجلسات يوغا.</p> </div>    <div class="texte" > <p>ويجسد "ديزرت روك" التزام "البحر الأحمر الدولية" الراسخ بمبادئ الاستدامة والمحافظة على البيئة، حيث تم تصميمه بحرص شديد لضمان الحد الأدنى من الأثر على البيئة المحيطة. يُعدّ المنتجع نموذجًا يحتذى به في مجال السياحة المستدامة، فهو يعمل بالكامل بالطاقة الشمسية، ويعتمد على ممارسات صديقة للبيئة في جميع عملياته، مثل إعادة تدوير المياه والمخلفات، والحد من استخدام البلاستيك، والتعاون مع أهالي منطقة البحر الأحمر للحفاظ على الموارد الطبيعية. كما يُولي المنتجع اهتمامًا خاصًا بحماية الكائنات الحية والنظم البيئية في المنطقة، من خلال مبادرات مُتعددة تهدف إلى إعادة تأهيل الموائل الطبيعية وتعزيز التنوع الحيوي.</p> </div>    <div class="texte" > <p>يمكنكم الآن حجز إقامتكم في منتجع "ديزرت روك" والاستفادة من عرض الافتتاح: احجز ليلتين واحصل على الليلة الثالثة مجانًا. كما يتوفر خصم 20% للحجوزات قبل 45 يومًا من موعد الإقامة.&nbsp;</p> <p>للحجز والاستفسار يمكنكم زيارة&nbsp;<a href="https://www.visitredsea.com/ar/where-to-stay/desert-rock-resort">الموقع الالكتروني للمنتجع</a></p> </div>  <div class="texte" > <blockquote class="twitter-tweet"> <p dir="rtl" lang="ar">يسرنا الإعلان عن افتتاح منتجعنا الجديد <a href="https://twitter.com/hashtag/%D8%AF%D9%8A%D8%B2%D8%B1%D8%AA_%D8%B1%D9%88%D9%83?src=hash&amp;ref_src=twsrc%5Etfw">#ديزرت_روك</a> في <a href="https://twitter.com/hashtag/%D9%88%D8%AC%D9%87%D8%A9_%D8%A7%D9%84%D8%A8%D8%AD%D8%B1_%D8%A7%D9%84%D8%A3%D8%AD%D9%85%D8%B1?src=hash&amp;ref_src=twsrc%5Etfw">#وجهة_البحر_الأحمر</a>، الذي أصبح جاهزًا لاستقبال الحجوزات! 🏞️<br /> <br /> يقع المنتجع بين جبال البحر الأحمر الساحرة، ويضم أجنحة مطلة على المنحدرات، وفلل مستقلة بخدمات شخصية وإطلالات لا تضاهى. ملاذ فاخر يحتفي بالتناغم بين الإنسان والطبيعة. 🌟… <a href="https://t.co/Ru6YkCIRpk">pic.twitter.com/Ru6YkCIRpk</a></p> — البحر الأحمر الدولية (@RedSeaGlobalAR) <a href="https://twitter.com/RedSeaGlobalAR/status/1866418101874463115?ref_src=twsrc%5Etfw">December 10, 2024</a></blockquote> <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script> </div>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84858347-60565733.jpg?v=1733835743", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84858347-60565745.jpg?v=1733835854", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84858347-60565764.jpg?v=1733835923", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84858347-60565780.jpg?v=1733836004", "https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84858347-60565796.jpg?v=1733836147"]','https://cmsphoto.ww-cdn.com/resizeapi/d480f3871d428312ea790794f64eb1af11ed2939/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/84858347/desert-rock-resort-opens-red-sea-international',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84635465,'دليل التخييم والكرفانات ٢٠٢٤ -٢٠٢٥','المركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر','2024-12-01T11:06:00.000Z','','<p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="دليل التخييم والكرفانات" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2673456/"> دليل التخييم والكرفانات </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84635465-60416420.jpg?v=1733051250"]','https://cmsphoto.ww-cdn.com/resizeapi/ff15df81c1ff44cea1af5e415d35c35483509ac6/480/','[]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/84635465/dlyl-altkhyym-oalkrfanat-2024',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84575409,'الأحلام_تحت_التنفيذ | أكتوبر 2024','مشاريع السعودية','2024-11-28T11:01:00.000Z','نيوم تبني مجمعًا صناعيًا لإنتاج الخرسانة لمشروع ذا لاين، وجزيرة سندالة تستقبل زوارها رسميًا، وبرج جدة الأطول في العالم يواصل التنفيذ، والأعمال متواصلة في القدية والمربع الجديد.','<div class="texte" > <p>نيوم تبني مجمع صناعي لإنتاج الخرسانة لمشروع ذا لاين، وجزيرة سندالة تستقبل زوارها رسميًا، وبرج جدة الأطول في العالم أصبح تحت التنفيذ مجددًا، والأعمال في القدية والمربع الجديد على قدمٍ وساق</p> </div>  <iframe width="560" height="315" src="https://www.youtube.com/embed/ODaCYaiRvTI?si=nhrxA4tn9H2bSqTX&gbyoutube=ODaCYaiRvTI" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>  <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="الأحلام تحت التنفيذ | أكتوبر" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2672196/"> الأحلام تحت التنفيذ | أكتوبر </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84575409-60383417.jpg?v=1732792670"]','https://cmsphoto.ww-cdn.com/resizeapi/1b743a7ae8544db6d3f9da64ab76d3bd88e9ef0d/480/','["أخبار المشاريع"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/84575409/vision2030-monthly-progress-report-october-2024',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84510950,'حمل دليل شتاء حائل','روح السعودية','2024-11-25T12:28:00.000Z','استكشف دليل شتاء حائل واستمتع بأبرز الفعاليات والتجارب المميزة التي تقدمها المنطقة خلال موسم الشتاء.','<div class="texte" > <p>استكشف دليل شتاء حائل واستمتع بالفعاليات والتجارب المميزة&nbsp;</p> </div>   <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="دليل شتاء حائل" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2670430/"> دليل شتاء حائل </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84510950-60344537.jpg?v=1732537882"]','https://cmsphoto.ww-cdn.com/resizeapi/44a8f26588b07a3e331979a27f29a733e76f54be/480/','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/84510950/hail-winter-guide',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84510864,'حمل دليل شتاء العلا','روح السعودية','2024-11-25T12:16:00.000Z','اكتشف شتاء العلا الساحر واستمتع بتجارب متنوعة بين المعالم الأثرية والطبيعة الخلابة التي تجعل من العلا وجهة شتوية استثنائية.','<div class="texte" > <p>اكتشف شتاء العلا الساحر ، واستمتع بتجارب متنوعة</p> </div>   <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="  " class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2670423/">    </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84510864-60344406.jpg?v=1732537231"]','https://cmsphoto.ww-cdn.com/resizeapi/58cba54ace942d67ed69a1eb668d8794a1ebe991/480/','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/84510864/alula-winter-guide',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84405487,'دليل شتاء السعودية - Saudi Winter Guide','روح السعودية','2024-11-20T21:09:00.000Z','اكتشف شتاء السعودية الساحر، من أجواء الرياض النابضة بالحياة إلى لحظات العلا المهيبة وتاريخ الدرعية، وحيوية جدة وشواطئ البحر الأحمر.','<div class="texte" > <div> <div data-habitat="C1"> <section> <div> <div> <div> <p>اكتشف شتاء السعودية الساحر! استمتع بأجواء الرياض النابضة بالحياة، لحظات العلا المهيبة، وتاريخ الدرعية. اكتشف حيوية جدة وشواطئ البحر الأحمر الخلابة. شتاء السعودية يقدم رحلة تجمع بين الترفيه، الفخامة، والمغامرة. ابدأ رحلتك الآن!</p> </div> </div> </div> </section> </div> </div> <div> <div data-habitat="C1"> <section id="PromotionalBannerWrapperId"> <div id="promotionalBanner"> <div> <div> <div> <div> <div> <div id="picture">&nbsp;</div> </div> </div> </div> </div> </div> </div> </section> </div> </div> <source media="(max-width: 420px)" srcset="https://scth.scene7.com/is/image/scth/mdlbeast-winter-banner:crop-460x620?defaultImage=mdlbeast-winter-banner&amp;wid=460&amp;hei=620 460w" /><source srcset="https://scth.scene7.com/is/image/scth/mdlbeast-winter-banner:crop-1920x768?defaultImage=mdlbeast-winter-banner&amp;wid=1920&amp;hei=768 1920w" /> </div>   <p class="pj"> <img src="https://www.saudi-guide.com/assets/img/icon-pdf.png" alt="دليل شتاء السعودية" class="image" /> <a class="pj" target="_blank" href="https://www.saudi-guide.com/apiv3/attachment/download/2668230/"> دليل شتاء السعودية </a>  <br />  </p>','["https://cmsphoto.ww-cdn.com/superstatic/2892882/art/default/84405487-60281238.jpg?v=1732137219"]','https://cmsphoto.ww-cdn.com/resizeapi/c4164889ffe321224e68807c86b5f1627704d87a/480/','["سياحة وفعاليات"]','استكشف السعودية','https://www.saudi-guide.com/visit-saudi/i/84405487/saudi-winter-guide',strftime('%s','now'));
INSERT OR REPLACE INTO articles (id,title,author,date,summary,body,images,thumb,cats,section,url,updated) VALUES (84404433,'شركة الدرعية تضع حجر الأساس لـ 7 فنادق عالمية ضمن حدث بشاير_الدرعية','مشاريع السعودية','2024-11-20T20:20:00.000Z','أعلنت شركة الدرعية عن وضع حجر الأساس لـ 7 فنادق عالمية ضمن مشروع الدرعية، توفر ما مجموعه 877 غرفة فندقية، وذلك ضمن فعاليات حدث بشائر_الدرعية.','<div class="texte" > <blockquote class="twitter-tweet"> <p dir="rtl" lang="ar">🔴 عاجل<a href="https://twitter.com/hashtag/%D8%B4%D8%B1%D9%83%D8%A9_%D8%A7%D9%84%D8%AF%D8%B1%D8%B9%D9%8A%D8%A9?src=hash&amp;ref_src=twsrc%5Etfw">#شركة_الدرعية</a> تعلن عن وضع حجر الأساس لـ 7 فنادق عالمية في مشروع الدرعية توفر 877 غرفة فندقية<br /> <br /> - رافلز<br /> - أرماني<br /> - أورينت إكسبريس<br /> - باكارا<br /> - كورينثيا<br /> - روزوود<br /> - وفوشون لهوتيل <a href="https://t.co/3Bxu46x5FF">pic.twitter.com/3Bxu46x5FF</a></p> — مشاريع السعودية (@SaudiProject) <a href="https://twitter.com/SaudiProject/status/1859242035728863339?ref_src=twsrc%5Etfw">November 20, 2024</a></blockquote> <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script> </div>  <div class="texte" > <blockquote class="twitter-tweet"> <p dir="rtl" lang="ar">تصاميم الفندق الأول:<br /> <br /> فندق <a href="https://twitter.com/hashtag/%D8%B1%D8%A7%D9%81%D9%84%D8%B2_%D8%A7%D9%84%D8%AF%D8%B1%D8%B9%D9%8A%D8%A9?src=hash&amp;ref_src=twsrc%5Etfw">#رافلز_الدرعية</a> بواقع 202 وحدة <a href="https://t.co/VdnOIa9wEf">pic.twitter.com/VdnOIa9wEf</a></p> — مشاريع السعودية (@SaudiProject) <a href="https://twitter.com/SaudiProject/status/1859263733412893134?ref_src=twsrc%5Etfw">November 20, 2024</a></blockquote> <script async src="https://platform.twitter.com/widgets.js" charset="utf-8"></script> </div>  <div class="texte" > <blockquote class="twitter-tweet"> <p dir="rtl" lang="ar">تصاميم الفندق الثاني:<br /> <br /> فندق <a href="https://twitter.com/hashtag/%D8%B1%D9%88%D8%B2%D9%88%D8%B1%D8%AF_%D8%A7%D9%84%D8%AF%D8%B1%D8%B9%D9%